-- Basis aus 341 Migrationen bis 20261224100000 (ROADMAP 7.16, Aufräumen Schritt 2).
-- Erzeugt von scripts/basis-migration.mjs, nicht von Hand ändern; neue Migrationen kommen dahinter.

set check_function_bodies = false;

create extension if not exists btree_gist with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pgcrypto with schema extensions;

CREATE SCHEMA app;

CREATE TYPE app.timerange AS RANGE (
    subtype = time without time zone,
    multirange_type_name = app.timemultirange
);

COMMENT ON TYPE app.timerange IS 'Bereich ueber Ortszeiten. Grundlage der Ueberschneidungs- und Abdeckungspruefung von Arbeitszeiten (CAL-005).';

CREATE FUNCTION app.account_display_name(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select nullif(btrim(concat_ws(' ', p.given_name, p.family_name)), '')
  from public.user_profiles up
  join public.persons p on p.id = up.person_id
  where up.id = p_user_id
$$;

CREATE FUNCTION app.active_service_catalog_version(p_organization_id uuid, p_on date) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select v.id
  from public.service_catalog_versions v
  where v.organization_id = p_organization_id
    and v.published_at is not null
    and v.valid_from <= p_on
  order by v.valid_from desc
  limit 1
$$;

COMMENT ON FUNCTION app.active_service_catalog_version(p_organization_id uuid, p_on date) IS 'Die am Stichtag gueltige veroeffentlichte Preisliste (ABR-001): die mit dem groessten Beginn bis zu diesem Tag. null heisst, dass es fuer diesen Tag keine gibt - dann kann auch keine Leistung erfasst werden.';

CREATE FUNCTION app.add_workdays(p_from date, p_days integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_tag    date := p_from;
  v_zaehle integer := 0;
begin
  while v_zaehle < greatest(coalesce(p_days, 0), 0) loop
    v_tag := v_tag + 1;
    if extract(isodow from v_tag) < 6 then
      v_zaehle := v_zaehle + 1;
    end if;
  end loop;
  return v_tag;
end;
$$;

COMMENT ON FUNCTION app.add_workdays(p_from date, p_days integer) IS 'KOM-001 (ANN-309): der n-te Werktag (Montag bis Freitag) nach einem Tag. Eine Frage vom Samstag mit zwei Werktagen ist am Dienstag faellig.';

CREATE FUNCTION app.aftercare_cancellation_end(p_starts_on date, p_day date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- ANN-270: zum Ende des laufenden Abo-Monats; vor dem Beginn endet das Abo,
  -- bevor ein Monat entsteht.
  select case
    when p_day < p_starts_on then p_starts_on - 1
    else app.aftercare_month_end(p_starts_on, app.aftercare_month_index(p_starts_on, p_day))
  end
$$;

COMMENT ON FUNCTION app.aftercare_cancellation_end(p_starts_on date, p_day date) IS 'ANG-003 (ANN-270): letzter Tag des Abos nach einer Kuendigung an diesem Tag - das Ende des laufenden Abo-Monats, vor dem Beginn der Vortag des Beginns.';

CREATE FUNCTION app.aftercare_earliest_start(p_patient_id uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- ANN-268: der Abschluss der Versorgung ist das Ende der Behandlung; ein
  -- Abo wird hoechstens 14 Tage rueckwirkend angelegt, sonst entstuenden
  -- faellige Monate fuer eine Zeit, in der niemand die Nachsorge nutzte.
  select greatest(p.care_concluded_on, app.training_today(p.organization_id) - 14)
  from public.patients p
  where p.id = p_patient_id and p.care_concluded_on is not null
$$;

COMMENT ON FUNCTION app.aftercare_earliest_start(p_patient_id uuid) IS 'ANG-001 (ANN-268): fruehester Beginn eines Nachsorge-Abos - der Abschluss der Versorgung, hoechstens 14 Tage zurueck. null, solange die Behandlung laeuft.';

CREATE FUNCTION app.aftercare_month_blocker(p_subscription_id uuid, p_month_start date) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_abo    public.aftercare_subscriptions%rowtype;
  v_heute  date;
  v_index  integer;
begin
  select * into v_abo from public.aftercare_subscriptions s where s.id = p_subscription_id;
  if not found then
    return 'not_a_month';
  end if;
  v_index := app.aftercare_month_index(v_abo.starts_on, p_month_start);
  if v_index < 0 or app.aftercare_month_start(v_abo.starts_on, v_index) <> p_month_start then
    return 'not_a_month';
  end if;
  if v_abo.ends_on is not null and p_month_start > v_abo.ends_on then
    return 'after_end';
  end if;
  v_heute := app.training_today(v_abo.organization_id);
  if p_month_start > v_heute then
    return 'not_due';
  end if;
  -- ANN-271: Laeuft die Behandlung wieder, wird kein Abo-Monat berechnet -
  -- waehrend der Behandlung ist die Plattform Teil der Heilbehandlung (4.6).
  -- Die Praxis beendet das Abo oder erfasst, sobald die Versorgung wieder
  -- abgeschlossen ist.
  if app.aftercare_earliest_start(v_abo.patient_id) is null then
    return 'care_open';
  end if;
  -- Zweitreview: Auch nach dem naechsten Abschluss bleibt ein Monat frei,
  -- in dem behandelt wurde - jeder Behandlungstermin, der nicht abgesagt ist.
  if exists (
    select 1
    from public.appointments a
    join public.organizations o on o.id = a.organization_id
    where a.patient_id = v_abo.patient_id
      and a.kind = 'therapy'
      and a.status <> 'cancelled'
      and (a.starts_at at time zone o.time_zone)::date
          between p_month_start and app.aftercare_month_end(v_abo.starts_on, v_index)
  ) then
    return 'care_during_month';
  end if;
  if not exists (select 1 from app.aftercare_month_price(v_abo.organization_id, p_month_start)) then
    return 'no_price';
  end if;
  return null;
end;
$$;

COMMENT ON FUNCTION app.aftercare_month_blocker(p_subscription_id uuid, p_month_start date) IS 'ANG-002: warum ein Abo-Monat nicht erfasst werden kann (not_a_month, after_end, not_due, care_open, care_during_month, no_price) oder null. Zu Beginn faellig (ANN-270), nicht waehrend und nicht fuer die Zeit einer neuen Behandlung (ANN-271).';

CREATE FUNCTION app.aftercare_month_end(p_starts_on date, p_index integer) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    -- Paragraf 188 Abs. 3 BGB: Der entsprechende Tag fehlt im Monat, die
    -- Rechnung landet auf dessen letztem Tag - der ist das Ende.
    when extract(day from (p_starts_on + make_interval(months => p_index + 1)))
         < extract(day from p_starts_on)
      then (p_starts_on + make_interval(months => p_index + 1))::date
    else (p_starts_on + make_interval(months => p_index + 1))::date - 1
  end
$$;

CREATE FUNCTION app.aftercare_month_index(p_starts_on date, p_day date) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_n integer;
begin
  if p_day < p_starts_on then
    return -1;
  end if;
  v_n := (extract(year from p_day)::integer - extract(year from p_starts_on)::integer) * 12
         + extract(month from p_day)::integer - extract(month from p_starts_on)::integer;
  if app.aftercare_month_start(p_starts_on, v_n) > p_day then
    v_n := v_n - 1;
  end if;
  return v_n;
end;
$$;

COMMENT ON FUNCTION app.aftercare_month_index(p_starts_on date, p_day date) IS 'ANG-001 (ANN-270): der Abo-Monat (ab 0), in dem ein Tag liegt; -1 vor dem Beginn. Monate werden vom Beginn aus gerechnet.';

CREATE FUNCTION app.aftercare_month_price(p_organization_id uuid, p_month_start date) RETURNS TABLE(catalog_item_id uuid, unit_price_cents integer, currency text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.id, c.unit_price_cents, c.currency
  from public.service_catalog_items c
  where c.catalog_version_id = app.active_service_catalog_version(p_organization_id, p_month_start)
    and c.item_kind = 'aftercare_month'
$$;

CREATE FUNCTION app.aftercare_month_start(p_starts_on date, p_index integer) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_index <= 0 then p_starts_on
              else app.aftercare_month_end(p_starts_on, p_index - 1) + 1 end
$$;

CREATE FUNCTION app.aftercare_tax_allowed(p_tax_treatment text, p_tax_rate_permille smallint) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_tax_treatment = 'taxable' and p_tax_rate_permille = 190
$$;

COMMENT ON FUNCTION app.aftercare_tax_allowed(p_tax_treatment text, p_tax_rate_permille smallint) IS 'ANG-002 (ANN-269): das Steuerkennzeichen, das ein Abo-Monat tragen darf - bis zur Antwort der Steuerberatung (B4) steuerpflichtig zum Regelsatz. Die eine Stelle fuer die Annahme.';

CREATE FUNCTION app.apply_leave(p_org uuid, p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_antrag record;
begin
  select r.staff_member_id, r.starts_on, r.ends_on into v_antrag
  from public.staff_leave_requests r
  where r.id = p_request_id and r.organization_id = p_org;

  perform 1 from public.staff_members sm where sm.id = v_antrag.staff_member_id for no key update;

  if exists (
    select 1 from public.staff_working_hour_exceptions e
    where e.organization_id = p_org
      and e.staff_member_id = v_antrag.staff_member_id
      and (e.kind = 'block' or e.time_account_entry_id is not null)
      and e.on_date between v_antrag.starts_on and v_antrag.ends_on
  ) then
    raise exception 'working hours exception in period' using errcode = '55000';
  end if;

  insert into public.staff_working_hour_exceptions
    (organization_id, staff_member_id, on_date, kind, created_by, leave_request_id)
  select p_org, v_antrag.staff_member_id, d::date, 'unavailable', null, p_request_id
  from generate_series(v_antrag.starts_on, v_antrag.ends_on, interval '1 day') as d
  where not exists (
    select 1 from public.staff_working_hour_exceptions e
    where e.organization_id = p_org
      and e.staff_member_id = v_antrag.staff_member_id
      and e.on_date = d::date
  );
end;
$$;

CREATE FUNCTION app.apply_working_time_change(p_org uuid, p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_antrag record;
  v_tag    integer;
begin
  select r.staff_member_id, r.kind, r.on_date, r.blocks into v_antrag
  from public.staff_working_time_requests r
  where r.id = p_request_id and r.organization_id = p_org;

  perform 1 from public.staff_members sm where sm.id = v_antrag.staff_member_id for no key update;

  if v_antrag.kind = 'once' then
    if exists (
      select 1 from public.staff_leave_requests l
      where l.organization_id = p_org and l.staff_member_id = v_antrag.staff_member_id
        and l.kind = 'leave' and l.status = 'approved'
        and v_antrag.on_date between l.starts_on and l.ends_on
    ) then
      raise exception 'day is part of approved leave' using errcode = '55000';
    end if;
    delete from public.staff_working_hour_exceptions e
     where e.organization_id = p_org and e.staff_member_id = v_antrag.staff_member_id
       and e.on_date = v_antrag.on_date;
    insert into public.staff_working_hour_exceptions
      (organization_id, staff_member_id, on_date, kind, starts_at, ends_at, created_by,
       working_time_request_id)
    select p_org, v_antrag.staff_member_id, v_antrag.on_date, 'block',
           (b ->> 'von')::time, (b ->> 'bis')::time, auth.uid(), p_request_id
    from jsonb_array_elements(v_antrag.blocks) as b;
    return;
  end if;

  if exists (
    select 1 from public.staff_working_hours h
    where h.organization_id = p_org and h.staff_member_id = v_antrag.staff_member_id
      and h.valid_from > v_antrag.on_date
  ) then
    raise exception 'later working plan exists' using errcode = '55000';
  end if;
  delete from public.staff_working_hours h
   where h.organization_id = p_org and h.staff_member_id = v_antrag.staff_member_id
     and h.valid_from = v_antrag.on_date;
  update public.staff_working_hours h
     set valid_until = v_antrag.on_date - 1
   where h.organization_id = p_org and h.staff_member_id = v_antrag.staff_member_id
     and daterange(h.valid_from, h.valid_until, '[]') @> v_antrag.on_date;
  for v_tag in 1 .. 7 loop
    insert into public.staff_working_hours
      (organization_id, staff_member_id, weekday, starts_at, ends_at, created_by, valid_from)
    select p_org, v_antrag.staff_member_id, v_tag, (b ->> 'von')::time, (b ->> 'bis')::time,
           auth.uid(), v_antrag.on_date
    from jsonb_array_elements(v_antrag.blocks -> v_tag::text) as b;
  end loop;
end;
$$;

CREATE FUNCTION app.appointment_basis_position(p_appointment_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    -- Abgesagt oder nicht angetroffen: verbraucht nichts, hat keine Position.
    when a.status in ('cancelled', 'no_show') then null
    else (
      select count(*)::integer
      from public.appointments frueher
      where frueher.treatment_basis_id  = a.treatment_basis_id
        and frueher.organization_id     = a.organization_id
        and frueher.status not in ('cancelled', 'no_show')
        and (frueher.starts_at, frueher.id) <= (a.starts_at, a.id)
    )
  end
  from public.appointments a
  where a.id = p_appointment_id
    and a.treatment_basis_id is not null
$$;

COMMENT ON FUNCTION app.appointment_basis_position(p_appointment_id uuid) IS 'PRX-008: der wievielte Termin seiner Grundlage dieser ist, geordnet nach Beginn und Kennung; abgesagte und nicht angetroffene Termine zaehlen nicht (ABN-001, ANN-067). null ohne Grundlage, bei Absage und bei Nichtantreffen. Einzige Stelle der Reihenfolge; app.appointment_is_covered fragt sie.';

CREATE FUNCTION app.appointment_days_in_leave(p_org uuid, p_staff_member_id uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('on_date', t.tag, 'appointments', t.anzahl)
                            order by t.tag), '[]'::jsonb)
  from (
    select (a.starts_at at time zone o.time_zone)::date as tag, count(*)::integer as anzahl
    from public.appointments a
    join public.organizations o on o.id = a.organization_id
    where a.organization_id = p_org
      and a.staff_member_id = p_staff_member_id
      and a.status = 'confirmed'
      and a.starts_at >= (p_from::timestamp at time zone o.time_zone)
      and a.starts_at < ((p_to + 1)::timestamp at time zone o.time_zone)
    group by 1
  ) t
$$;

CREATE FUNCTION app.appointment_is_billable(p_kind text, p_status text, p_fee_basis text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_kind
           when 'therapy'  then p_status = 'documented' or p_fee_basis is not null
           when 'training' then p_status in ('completed', 'documented')
           -- ERN-011: die Beratung aus dem abgehakten Termin (app.billing_kind).
           when 'nutrition_counselling' then p_status = 'completed'
           else false
         end
$$;

COMMENT ON FUNCTION app.appointment_is_billable(p_kind text, p_status text, p_fee_basis text) IS 'Ob an einem Termin eine Leistung entstehen darf (PROJECT_PRINCIPLES.md 19): Behandlung aus "dokumentiert" oder einem Gebuehrenanlass, ohne Override (ANN-072); Training aus dem durchgefuehrten Termin (ANN-181); die Ernaehrungsberatung (p_kind aus app.billing_kind) aus dem abgehakten Termin (ERN-011); ein interner Termin nie.';

CREATE FUNCTION app.appointment_is_checked(p_kind text, p_status text, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Training: wie bisher setzt das Protokoll den Abschluss mit (ANN-036).
  select p_kind <> 'therapy' or p_status = 'invoiced' or p_completed_at is not null
$$;

COMMENT ON FUNCTION app.appointment_is_checked(p_kind text, p_status text, p_completed_at timestamp with time zone) IS 'B4/B7 (ANN-512, ANN-513): Ist ein Behandlungstermin abgehakt? Der Haken (completed_at) steht neben dem Zustand; ein abgerechneter Termin gilt als abgehakt. Fuer andere Terminarten immer wahr.';

CREATE FUNCTION app.appointment_is_covered(p_appointment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.appointment_basis_position(a.id) <= b.appointment_count
  from public.appointments a
  -- Ohne Grundlage keine Deckung: kein Join-Treffer, Ergebnis null. Eine
  -- Absage hat keine Position und damit ebenfalls null.
  join public.treatment_bases b on b.id = a.treatment_basis_id
  where a.id = p_appointment_id
$$;

COMMENT ON FUNCTION app.appointment_is_covered(p_appointment_id uuid) IS 'Deckt die Behandlungsgrundlage diesen Termin? (CAL-022, ANN-067) Gedeckt ist, wessen Position in der Grundlage (app.appointment_basis_position) hoechstens die Terminzahl ist. null heisst: keine Grundlage, abgesagt oder nicht angetroffen - dann gibt es keine Aussage.';

CREATE FUNCTION app.appointment_notification_channels(p_appointment_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(distinct n.channel order by n.channel), array[]::text[])
  from public.appointment_notifications n
  join public.appointments a on a.id = n.appointment_id
  where n.appointment_id = p_appointment_id
    and n.notified_at >= a.patient_relevant_changed_at
$$;

COMMENT ON FUNCTION app.appointment_notification_channels(p_appointment_id uuid) IS 'Die seit der letzten fuer die Patient:in relevanten Terminaenderung vermerkten Mitteilungswege (CAL-012, ABN-003). Nur fuer die serverseitigen Lese- und Schreibpfade.';

CREATE FUNCTION app.appointment_performed_on(p_appointment_id uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (a.starts_at at time zone o.time_zone)::date
  from public.appointments a
  join public.organizations o on o.id = a.organization_id
  where a.id = p_appointment_id
$$;

COMMENT ON FUNCTION app.appointment_performed_on(p_appointment_id uuid) IS 'Leistungstag eines Termins in der Zeitzone der Organisation (ABR-002). Er entscheidet ueber die geltende Preisliste.';

CREATE FUNCTION app.appointment_series_limit() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 30
$$;

COMMENT ON FUNCTION app.appointment_series_limit() IS 'Hoechstzahl der Termine, die ein Serienvorgang anlegt (CAL-007, ANN-038).';

CREATE FUNCTION app.appointment_session_fee_stays_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'session fee is immutable' using errcode = '23514';
end;
$$;

CREATE FUNCTION app.appointment_window_minutes() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 60
$$;

COMMENT ON FUNCTION app.appointment_window_minutes() IS 'VORBELEGUNG der Laenge eines angebotenen Terminfensters in Minuten (PROJECT_PRINCIPLES.md 8.1, CAL-010a, CAL-020). Die Terminserie plant damit; der einzelne Termin darf davon abweichen.';

-- ANN-049
CREATE FUNCTION app.appointment_window_options() RETURNS integer[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array[60, 45]
$$;

COMMENT ON FUNCTION app.appointment_window_options() IS 'REGELLAENGEN eines Behandlungstermins in Minuten (PROJECT_PRINCIPLES.md 0.11 Abschnitt 8.1, CAL-020). Keine Schranke mehr: Eine andere Laenge wird angenommen und in der Terminanzeige als abweichend gekennzeichnet. Die erste ist die Vorbelegung.';

CREATE FUNCTION app.appointments_basis_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.treatment_basis_id is not null and app.treatment_basis_locked(new.treatment_basis_id) then
      raise exception 'treatment basis is in billing' using errcode = '55000';
    end if;
    return new;
  end if;

  -- Erst die Spalten, dann die Sperre (Zweitreview A, Nachtrag): Eine
  -- Aenderung, die die Abrechnung nicht beruehrt - Zusammenfuehren, Titel -,
  -- sperrt die Grundlage nicht und wartet auf keine Freigabe.
  if new.starts_at          is not distinct from old.starts_at
     and new.ends_at            is not distinct from old.ends_at
     and new.status             is not distinct from old.status
     and new.completed_at       is not distinct from old.completed_at
     and new.treatment_basis_id is not distinct from old.treatment_basis_id
     and new.staff_member_id    is not distinct from old.staff_member_id then
    return new;
  end if;

  if (old.treatment_basis_id is not null and app.treatment_basis_locked(old.treatment_basis_id))
     or (new.treatment_basis_id is not null
         and new.treatment_basis_id is distinct from old.treatment_basis_id
         and app.treatment_basis_locked(new.treatment_basis_id)) then
    raise exception 'treatment basis is in billing' using errcode = '55000';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.appointments_in_leave(p_org uuid, p_staff_member_id uuid, p_from date, p_to date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*)::integer
  from public.appointments a
  join public.organizations o on o.id = a.organization_id
  where a.organization_id = p_org
    and a.staff_member_id = p_staff_member_id
    and a.status = 'confirmed'
    and a.starts_at >= (p_from::timestamp at time zone o.time_zone)
    and a.starts_at < ((p_to + 1)::timestamp at time zone o.time_zone)
$$;

CREATE FUNCTION app.appointments_mark_patient_relevant_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.starts_at          is distinct from old.starts_at
     or new.ends_at         is distinct from old.ends_at
     or new.appointment_type is distinct from old.appointment_type
     or new.location_id     is distinct from old.location_id
     or new.staff_member_id is distinct from old.staff_member_id
     or new.visit_street    is distinct from old.visit_street
     or new.visit_house_number is distinct from old.visit_house_number
     or new.visit_postal_code  is distinct from old.visit_postal_code
     or new.visit_city      is distinct from old.visit_city
     or (new.status = 'cancelled' and old.status <> 'cancelled')
  then
    new.patient_relevant_changed_at := now();
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.appointments_mark_patient_relevant_change() IS 'Setzt appointments.patient_relevant_changed_at bei Aenderungen an Beginn, Ende, Terminart, Ort, Adresse, Person oder bei der Absage (ABN-003, ANN-040). Einzige Stelle der Regel; die Mitteilungswege vergleichen damit.';

CREATE FUNCTION app.appointments_outside_working_time(p_org uuid, p_staff_member_id uuid, p_kind text, p_on_date date, p_blocks jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with termine as (
    select (a.starts_at at time zone o.time_zone)::date as tag,
           (a.starts_at at time zone o.time_zone)::time as von,
           case when (a.ends_at at time zone o.time_zone)::date > (a.starts_at at time zone o.time_zone)::date
                then time '24:00' else (a.ends_at at time zone o.time_zone)::time end as bis
    from public.appointments a
    join public.organizations o on o.id = a.organization_id
    where a.organization_id = p_org
      and a.staff_member_id = p_staff_member_id
      and a.status = 'confirmed'
      and a.starts_at >= (p_on_date::timestamp at time zone o.time_zone)
      and a.starts_at < ((case when p_kind = 'once' then p_on_date + 1 else p_on_date + 366 end)::timestamp
                         at time zone o.time_zone)
  ),
  betroffen as (
    select t.tag
    from termine t
    where t.bis > t.von
      and (p_kind = 'once' or not exists (
        select 1 from public.staff_working_hour_exceptions e
        where e.organization_id = p_org and e.staff_member_id = p_staff_member_id and e.on_date = t.tag))
      and not coalesce((
        select range_agg(app.timerange((b ->> 'von')::time, (b ->> 'bis')::time, '[)'))
        from jsonb_array_elements(
          case when p_kind = 'once' then p_blocks else p_blocks -> extract(isodow from t.tag)::text end
        ) as b
      ) @> app.timerange(t.von, t.bis, '[)'), false)
  )
  select coalesce(jsonb_agg(jsonb_build_object('on_date', x.tag, 'appointments', x.anzahl) order by x.tag),
                  '[]'::jsonb)
  from (select b.tag, count(*)::integer as anzahl from betroffen b group by b.tag) x
$$;

CREATE FUNCTION app.appointments_record_default_services() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app.record_default_services(new.id);
  return null;
end;
$$;

