CREATE FUNCTION app.assert_appointment_count(p_appointment_count integer) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_appointment_count is null then
    raise exception 'appointment count is required' using errcode = '22023';
  end if;

  if p_appointment_count < 1 or p_appointment_count > 500 then
    raise exception 'appointment count out of range' using errcode = '22023';
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_appointment_count(p_appointment_count integer) IS 'Prueft die Anzahl moeglicher Termine einer Behandlungsgrundlage: Pflicht, zwischen 1 und 500 (VER-EPIC-002, ANN-064).';

CREATE FUNCTION app.assert_appointment_staff_active() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform 1
  from public.staff_members sm
  where sm.id = new.staff_member_id
    and sm.organization_id = new.organization_id
    and sm.employment_status = 'active'
  for share;

  if not found then
    raise exception 'staff member is not active' using errcode = '22023';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.assert_appointment_staff_active() IS 'Verhindert Terminzuweisungen an inaktive Mitarbeitende - konkurrenzsicher ueber eine Zeilensperre (STAFF-001).';

CREATE FUNCTION app.assert_electricity_month(p_org uuid, p_month date) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_laufend date;
begin
  select date_trunc('month', now() at time zone o.time_zone)::date into v_laufend
  from public.organizations o where o.id = p_org;
  if p_month is null or p_month <> date_trunc('month', p_month)::date
     or p_month >= v_laufend or p_month < (v_laufend - interval '12 months')::date then
    raise exception 'month not allowed' using errcode = '22023';
  end if;
end;
$$;

CREATE FUNCTION app.assert_geocode_result(p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_lat is null or p_lon is null
     or p_lat not between -90 and 90 or p_lon not between -180 and 180 then
    raise exception 'coordinate out of range' using errcode = '22023';
  end if;
  if p_precision is null or p_precision not in ('address', 'street', 'locality', 'unknown') then
    raise exception 'unknown geocode precision' using errcode = '22023';
  end if;
  -- ANN-016: unterhalb der Hausnummer bestaetigt die erfassende Person den
  -- Treffer, sonst bleibt die Adresse ohne Koordinate.
  if p_precision <> 'address' and coalesce(p_confirmed, false) is false then
    raise exception 'geocode result below address precision must be confirmed' using errcode = '22023';
  end if;
end;
$$;

CREATE FUNCTION app.assert_invoice_items_match_basis(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_basis   uuid;
  v_bereich text;
begin
  select i.treatment_basis_id, i.service_area into v_basis, v_bereich
  from public.invoices i where i.id = p_invoice_id;

  if v_bereich <> 'therapy' then
    return;
  end if;

  if exists (
    select 1
    from public.invoice_items it
    join public.billable_services b on b.id = it.billable_service_id
    -- ANG-002: ein Abo-Monat ohne Termin gehoert nie zu einer Grundlage.
    left join public.appointments a on a.id = b.appointment_id
    where it.invoice_id = p_invoice_id
      and a.treatment_basis_id is distinct from v_basis
  ) then
    raise exception 'invoice items do not belong to the treatment basis of the invoice'
      using errcode = '23514';
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_invoice_items_match_basis(p_invoice_id uuid) IS 'Weist das Ausstellen ab, wenn eine Zeile nicht (mehr) zur Behandlungsgrundlage der Rechnung gehoert (ABR-032). Aufgerufen aus issue_invoice.';

CREATE FUNCTION app.assert_invoice_recipient_address(p_recipient jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_fehlt text[] := '{}';
begin
  if nullif(btrim(p_recipient ->> 'street'), '') is null then v_fehlt := array_append(v_fehlt, 'street'); end if;
  if nullif(btrim(p_recipient ->> 'house_number'), '') is null then v_fehlt := array_append(v_fehlt, 'house_number'); end if;
  if nullif(btrim(p_recipient ->> 'postal_code'), '') is null then v_fehlt := array_append(v_fehlt, 'postal_code'); end if;
  if nullif(btrim(p_recipient ->> 'city'), '') is null then v_fehlt := array_append(v_fehlt, 'city'); end if;
  if cardinality(v_fehlt) > 0 then
    raise exception 'invoice recipient address incomplete'
      using errcode = '22023', detail = array_to_string(v_fehlt, ',');
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_invoice_recipient_address(p_recipient jsonb) IS 'Keine Rechnung ohne vollstaendige Empfaengeranschrift: Strasse, Hausnummer, PLZ, Ort (ABN-020, BEF-111). DETAIL nennt die fehlenden Felder.';

CREATE FUNCTION app.assert_invoice_tax_lawful(p_document jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_klein    boolean := coalesce((p_document -> 'issuer' ->> 'small_business')::boolean, false);
  v_zeile    jsonb;
  v_gruppe   jsonb;
  v_kennung  text;
  v_steuer   integer;
  v_summe    integer := 0;
  v_gesamt   integer := coalesce((p_document -> 'totals' ->> 'tax_total_cents')::integer, 0);
begin
  -- Nicht an der Zeile.
  for v_zeile in
    select jsonb_array_elements(coalesce(p_document -> 'items', '[]'::jsonb))
  loop
    v_kennung := coalesce(v_zeile ->> 'tax_treatment', '');
    v_steuer  := coalesce((v_zeile ->> 'tax_cents')::integer, 0);

    if v_kennung <> 'taxable'
       and coalesce((v_zeile ->> 'tax_rate_permille')::integer, 0) <> 0 then
      raise exception 'tax rate on an exempt or non-taxable line (Par. 14c UStG)'
        using errcode = '23514';
    end if;

    if v_steuer <> 0 and (v_klein or v_kennung <> 'taxable') then
      raise exception 'tax shown on an exempt or non-taxable line (Par. 14c UStG)'
        using errcode = '23514';
    end if;
  end loop;

  -- Nicht an der Steuergruppe - und der Grund steht da.
  for v_gruppe in
    select jsonb_array_elements(coalesce(p_document -> 'tax_groups', '[]'::jsonb))
  loop
    v_kennung := coalesce(v_gruppe ->> 'tax_treatment', '');
    v_steuer  := coalesce((v_gruppe ->> 'tax_cents')::integer, 0);
    v_summe   := v_summe + v_steuer;

    if v_steuer <> 0 and v_kennung <> 'taxable' then
      raise exception 'tax shown on an exempt or non-taxable tax group (Par. 14c UStG)'
        using errcode = '23514';
    end if;

    if v_steuer <> 0 and v_klein then
      raise exception 'tax shown under the small business scheme (Par. 19 UStG)'
        using errcode = '23514';
    end if;

    if v_kennung in ('exempt_healthcare', 'not_taxable')
       and coalesce(btrim(v_gruppe ->> 'exemption_reason'), '') = '' then
      raise exception 'exemption reason missing (Par. 14 Abs. 4 Nr. 8 UStG)'
        using errcode = '23514';
    end if;
  end loop;

  -- Nicht in der Summe.
  if v_gesamt <> v_summe then
    raise exception 'tax total does not match the tax groups (Par. 14c UStG)'
      using errcode = '23514';
  end if;

  if v_klein and v_gesamt <> 0 then
    raise exception 'tax shown under the small business scheme (Par. 19 UStG)'
      using errcode = '23514';
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_invoice_tax_lawful(p_document jsonb) IS 'Der Par. 14c-Riegel (ABR-007, ADR-009 Punkt 18): kein Steuerbetrag an einem steuerfreien oder nicht steuerbaren Posten - nicht an der Zeile, nicht an der Steuergruppe, nicht in der Summe; unter Par. 19 UStG an der ganzen Rechnung. Verlangt zugleich den Grund der Steuerbefreiung als Pflichtangabe (Par. 14 Abs. 4 Nr. 8 UStG). Bricht mit 23514 ab; wird vor dem Ausstellen aufgerufen, nicht danach.';

CREATE FUNCTION app.assert_leave_period(p_org uuid, p_starts_on date, p_ends_on date) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_heute date;
begin
  if p_starts_on is null or p_ends_on is null or p_ends_on < p_starts_on
     or p_ends_on - p_starts_on > 92 then
    raise exception 'leave period is invalid' using errcode = '22023';
  end if;
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = p_org;
  if p_starts_on < v_heute then
    raise exception 'leave must not start in the past' using errcode = '22023';
  end if;
end;
$$;



CREATE TABLE public.platform_accesses (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    access_kind text DEFAULT 'self'::text NOT NULL,
    account_user_id uuid,
    status text DEFAULT 'invited'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    activated_at timestamp with time zone,
    locked_at timestamp with time zone,
    locked_by uuid,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    revoked_reason text,
    legal_basis text,
    representative_name text,
    proof_documents text[],
    health_scope boolean,
    proof_recorded_by uuid,
    proof_recorded_at timestamp with time zone,
    consent_text_version text,
    consent_recorded_by uuid,
    consent_recorded_at timestamp with time zone,
    consent_earlier_messages boolean,
    finance_scope boolean,
    companion_declined_at timestamp with time zone,
    companion_declined_by uuid,
    companion_declined_reason text,
    onboarding_finished_at timestamp with time zone,
    onboarding_skipped_at timestamp with time zone,
    onboarding_skipped_by uuid,
    CONSTRAINT platform_accesses_access_kind_check CHECK ((access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text, 'companion'::text]))),
    CONSTRAINT platform_accesses_account_by_status CHECK ((((status = 'invited'::text) AND (account_user_id IS NULL)) OR ((status = ANY (ARRAY['active'::text, 'locked'::text])) AND (account_user_id IS NOT NULL)) OR (status = 'revoked'::text))),
    CONSTRAINT platform_accesses_companion_declined_shape CHECK ((((companion_declined_at IS NULL) AND (companion_declined_by IS NULL) AND (companion_declined_reason IS NULL)) OR ((companion_declined_at IS NOT NULL) AND (companion_declined_by IS NOT NULL) AND (companion_declined_reason = 'capacity_doubt'::text) AND (access_kind = 'legal_representative'::text)))),
    CONSTRAINT platform_accesses_kind_fields CHECK (
CASE access_kind
    WHEN 'self'::text THEN ((legal_basis IS NULL) AND (representative_name IS NULL) AND (proof_documents IS NULL) AND (health_scope IS NULL) AND (finance_scope IS NULL) AND (proof_recorded_by IS NULL) AND (proof_recorded_at IS NULL) AND (consent_text_version IS NULL) AND (consent_recorded_by IS NULL) AND (consent_recorded_at IS NULL) AND (consent_earlier_messages IS NULL))
    WHEN 'legal_representative'::text THEN ((legal_basis IS NOT NULL) AND (representative_name IS NOT NULL) AND (proof_recorded_by IS NOT NULL) AND (proof_recorded_at IS NOT NULL) AND (proof_documents @> ARRAY['identity_document'::text]) AND (proof_documents @> ARRAY[
    CASE legal_basis
        WHEN 'custody'::text THEN 'custody_proof'::text
        WHEN 'guardianship'::text THEN 'guardianship_certificate'::text
        ELSE 'power_of_attorney'::text
    END]) AND ((legal_basis = 'custody'::text) = (health_scope IS NULL)) AND COALESCE(health_scope, true) AND (finance_scope IS NOT NULL) AND (consent_text_version IS NULL) AND (consent_recorded_by IS NULL) AND (consent_recorded_at IS NULL) AND (consent_earlier_messages IS NULL))
    WHEN 'companion'::text THEN ((legal_basis IS NULL) AND (health_scope IS NULL) AND (representative_name IS NOT NULL) AND (proof_recorded_by IS NOT NULL) AND (proof_recorded_at IS NOT NULL) AND (proof_documents = ARRAY['identity_document'::text]) AND (consent_text_version IS NOT NULL) AND (consent_recorded_by IS NOT NULL) AND (consent_recorded_at IS NOT NULL) AND (consent_earlier_messages IS NOT NULL) AND (finance_scope IS NOT NULL))
    ELSE false
END),
    CONSTRAINT platform_accesses_legal_basis_check CHECK ((legal_basis = ANY (ARRAY['custody'::text, 'guardianship'::text, 'power_of_attorney'::text]))),
    CONSTRAINT platform_accesses_live_has_relationship CHECK (((status = 'revoked'::text) OR (patient_id IS NOT NULL) OR (training_relationship_id IS NOT NULL))),
    CONSTRAINT platform_accesses_locked_stamp CHECK (((status = 'locked'::text) = (locked_at IS NOT NULL))),
    CONSTRAINT platform_accesses_onboarding_skip_stamp CHECK (((onboarding_skipped_at IS NULL) = (onboarding_skipped_by IS NULL))),
    CONSTRAINT platform_accesses_proof_documents_check CHECK (((proof_documents IS NULL) OR ((cardinality(proof_documents) BETWEEN 1 AND 4) AND (proof_documents <@ ARRAY['identity_document'::text, 'custody_proof'::text, 'guardianship_certificate'::text, 'power_of_attorney'::text])))),
    CONSTRAINT platform_accesses_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT platform_accesses_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND ((patient_id IS NULL) OR (patient_id = relationship_id))) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND ((training_relationship_id IS NULL) OR (training_relationship_id = relationship_id))))),
    CONSTRAINT platform_accesses_representative_name_check CHECK (((representative_name IS NULL) OR ((representative_name = btrim(representative_name)) AND (char_length(representative_name) BETWEEN 2 AND 120)))),
    CONSTRAINT platform_accesses_revoked_reason_check CHECK ((revoked_reason = ANY (ARRAY['practice'::text, 'relationship_deleted'::text, 'account_deleted'::text, 'consent_withdrawn'::text, 'scope_unproven'::text]))),
    CONSTRAINT platform_accesses_revoked_stamp CHECK (((status = 'revoked'::text) = ((revoked_at IS NOT NULL) AND (revoked_reason IS NOT NULL)))),
    CONSTRAINT platform_accesses_status_check CHECK ((status = ANY (ARRAY['invited'::text, 'active'::text, 'locked'::text, 'revoked'::text])))
);

COMMENT ON TABLE public.platform_accesses IS 'Plattformzugang (ADR-023 Punkt 3, POR-002): ein Konto zu einem Verhaeltnis, mit Zustand. Nachweis bis drei Jahre nach dem Ende (ANN-189). Datenklasse: Plattformzugang.';

COMMENT ON COLUMN public.platform_accesses.relationship_id IS 'Kennung des Verhaeltnisses (patients.id oder training_relationships.id). Ohne FK, damit der Nachweis das Verhaeltnis ueberdauert, ohne es festzuhalten.';

COMMENT ON COLUMN public.platform_accesses.account_user_id IS 'auth.users.id des Plattformkontos. Ohne FK: das Konto faellt 30 Tage nach dem Ende, der Nachweis erst nach drei Jahren (ADR-023 Punkt 5).';

COMMENT ON COLUMN public.platform_accesses.representative_name IS 'ANN-203: Name der vertretenden Person als Teil des Nachweises (ADR-023 Konsequenzen). Nie der Name der vertretenen Person.';

COMMENT ON COLUMN public.platform_accesses.proof_documents IS 'ANN-205: welche Art Dokument angesehen wurde (Ausweis, Sorgerechtsnachweis, Betreuerausweis, Vollmacht). Gespeichert wird nie das Dokument, nie eine Nummer.';

COMMENT ON COLUMN public.platform_accesses.health_scope IS 'Rechtliche Vertretung: Die Praxis hat gesehen, dass der Aufgabenkreis bzw. die Vollmacht die Gesundheitssorge umfasst (Betreuung, Vorsorgevollmacht; Pflicht). Beim Sorgerecht null - es umfasst sie. Bis ABN-010 guardianship_health_scope und nur fuer die Betreuung (ANN-205, BEF-119).';

COMMENT ON COLUMN public.platform_accesses.consent_text_version IS 'ANN-206: Fassung des Wortlauts, in die die Person zur Begleitung eingewilligt hat (src/lib/vertretung.ts).';

COMMENT ON COLUMN public.platform_accesses.finance_scope IS 'Rechnungen und Zahlungen: rechtliche Vertretung nur mit nachgewiesener Vermoegenssorge, Begleitung nur mit Einwilligung in diesen Bereich. Fuer den eigenen Zugang null - er sieht alles Eigene (ABN-010, BEF-119, BEF-116, ANN-216).';

COMMENT ON COLUMN public.platform_accesses.companion_declined_reason IS 'ADR-023 Punkt 13: keine Begleitung, weil die Praxis an der Einwilligungsfaehigkeit zweifelt. Fester Wert, kein Freitext, keine Diagnose (ANN-207).';

COMMENT ON COLUMN public.platform_accesses.onboarding_finished_at IS 'POR-019: wann die Person den Einstieg beendet hat (auch "spaeter"); null = noch nicht.';

COMMENT ON COLUMN public.platform_accesses.onboarding_skipped_at IS 'POR-019 (IDEA-LZK-005): wann die Praxis den Einstieg fuer die Person uebersprungen hat. Einwilligungen bleiben davon unberuehrt.';

COMMENT ON COLUMN public.platform_accesses.onboarding_skipped_by IS 'POR-019: wer den Einstieg uebersprungen hat (Praxiskonto mit dem Recht, den Zugang zu verwalten).';

CREATE FUNCTION app.assert_platform_exercise(p_access_id uuid) RETURNS public.platform_accesses
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'exercise')
     or not app.platform_access_writable(p_access_id) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  return v_zugang;
end;
$$;

CREATE FUNCTION app.assert_platform_message(p_access_id uuid) RETURNS public.platform_accesses
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'message')
     or not app.platform_access_writable(p_access_id) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  return v_zugang;
end;
$$;

CREATE FUNCTION app.assert_platform_representation(p_access_kind text, p_legal_basis text, p_date_of_birth date, p_time_zone text, p_name text, p_proof_documents text[], p_health_scope boolean, p_consent_version text, p_earlier_messages boolean, p_finance_scope boolean) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_minderjaehrig boolean;
begin
  if p_access_kind is null or p_access_kind not in ('legal_representative', 'companion') then
    raise exception 'unknown representation kind' using errcode = '22023';
  end if;
  if p_name is null or char_length(btrim(p_name)) < 2 or char_length(btrim(p_name)) > 120 then
    raise exception 'representative name required' using errcode = '22023';
  end if;
  -- ANN-208: ohne Geburtsdatum keine Vertretung - die Altersgrenze ist sonst
  -- nicht pruefbar (wie ANN-190).
  if p_date_of_birth is null then
    raise exception 'date of birth required' using errcode = '22023';
  end if;
  v_minderjaehrig := app.platform_is_minor(p_date_of_birth, p_time_zone);

  if p_proof_documents is null or not (p_proof_documents @> array['identity_document']::text[]) then
    raise exception 'identity document must be seen' using errcode = '22023';
  end if;

  -- ABN-010: Der Bereich Rechnungen ist immer eine ausdrueckliche Angabe -
  -- nachgewiesen oder eingewilligt, ja oder nein. Ohne Angabe gibt es keine
  -- Vertretung, statt still "alles" oder "nichts" anzunehmen.
  if p_finance_scope is null then
    raise exception 'finance scope must be stated' using errcode = '22023';
  end if;

  if p_access_kind = 'legal_representative' then
    if p_legal_basis is null or p_legal_basis not in ('custody', 'guardianship', 'power_of_attorney') then
      raise exception 'legal basis required' using errcode = '22023';
    end if;
    -- Punkt 15: unter 18 nur Sorgeberechtigte, ab 18 kein Sorgerecht.
    if v_minderjaehrig and p_legal_basis <> 'custody' then
      raise exception 'minor needs custody' using errcode = '22023';
    end if;
    if not v_minderjaehrig and p_legal_basis = 'custody' then
      raise exception 'custody ends at majority' using errcode = '22023';
    end if;
    if not (p_proof_documents @> array[case p_legal_basis
                                         when 'custody' then 'custody_proof'
                                         when 'guardianship' then 'guardianship_certificate'
                                         else 'power_of_attorney' end]::text[]) then
      raise exception 'authority document must be seen' using errcode = '22023';
    end if;
    -- ABN-010 (BEF-119): Betreuung UND Vorsorgevollmacht nur mit
    -- nachgewiesener Gesundheitssorge - die Plattform zeigt Gesundheitsdaten.
    if p_legal_basis = 'guardianship' and not coalesce(p_health_scope, false) then
      raise exception 'guardianship must cover health care' using errcode = '22023';
    end if;
    if p_legal_basis = 'power_of_attorney' and not coalesce(p_health_scope, false) then
      raise exception 'power of attorney must cover health care' using errcode = '22023';
    end if;
  else
    -- Punkt 15: Eine Begleitung gibt es fuer Minderjaehrige nicht.
    if v_minderjaehrig then
      raise exception 'minor needs custody' using errcode = '22023';
    end if;
    if p_consent_version is distinct from app.platform_companion_consent_version() then
      raise exception 'consent of the person required' using errcode = '22023';
    end if;
    if p_earlier_messages is null then
      raise exception 'consent scope required' using errcode = '22023';
    end if;
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_platform_representation(p_access_kind text, p_legal_basis text, p_date_of_birth date, p_time_zone text, p_name text, p_proof_documents text[], p_health_scope boolean, p_consent_version text, p_earlier_messages boolean, p_finance_scope boolean) IS 'Prueft die Angaben einer Vertretung: Art, Name, Alter, gesehene Dokumente, nachgewiesene bzw. eingewilligte Bereiche (Gesundheit, Rechnungen) und die Fassung der Einwilligung. Die eine Stelle des Nachweisverfahrens bis B2 (ADR-023 Punkt 13, ABN-010, BEF-116).';

CREATE FUNCTION app.assert_questionnaire_answers(p_answers jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_key text;
  v_val jsonb;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    raise exception 'answers must be an object' using errcode = '22023';
  end if;
  if octet_length(p_answers::text) > 65536 then
    raise exception 'answers too large' using errcode = '22023';
  end if;
  for v_key, v_val in select key, value from jsonb_each(p_answers) loop
    if v_key !~ '^[a-z][a-z0-9_]*$' or length(v_key) > 80 then
      raise exception 'answer key is not an identifier' using errcode = '22023';
    end if;
    if jsonb_typeof(v_val) <> 'object' then
      raise exception 'answer must be an object' using errcode = '22023';
    end if;
  end loop;
end;
$_$;

CREATE FUNCTION app.assert_questionnaire_answers(p_instrument_id text, p_version text, p_answers jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_definition jsonb;
  v_key        text;
  v_val        jsonb;
  v_item       jsonb;
  v_typ        text;
  v_ids        text[];
  v_frei       text[];
  v_exklusiv   text[];
  v_auswahl    text[];
  v_text       text;
  v_m          jsonb;
  v_zahl       numeric;
begin
  -- Die Form zuerst: Objekt, Kennungen, Groesse (ANN-105).
  perform app.assert_questionnaire_answers(p_answers);

  select d.definition into v_definition
  from public.questionnaire_definitions d
  where d.instrument_id = p_instrument_id and d.version = p_version;
  if v_definition is null then
    raise exception 'unknown questionnaire definition' using errcode = '22023';
  end if;

  for v_key, v_val in select key, value from jsonb_each(p_answers) loop
    v_item := null;
    select i into v_item
    from jsonb_array_elements(v_definition->'items') i
    where i->>'id' = v_key;
    if v_item is null then
      raise exception 'answer to an unknown item' using errcode = '22023';
    end if;
    v_typ := v_item->>'typ';

    -- Kennung einer Option: ihre id, sonst ihr Punktwert (ANN-102, optionKennung).
    select coalesce(array_agg(coalesce(o->>'id', (o->'wert')::text)), '{}'),
           coalesce(array_agg(coalesce(o->>'id', (o->'wert')::text))
                      filter (where (o->>'freitext')::boolean), '{}'),
           coalesce(array_agg(coalesce(o->>'id', (o->'wert')::text))
                      filter (where (o->>'exklusiv')::boolean), '{}')
      into v_ids, v_frei, v_exklusiv
    from jsonb_array_elements(coalesce(v_item->'optionen', '[]'::jsonb)) o;

    if v_typ in ('einzelauswahl', 'mehrfachauswahl') then
      if exists (select 1 from jsonb_object_keys(v_val) k where k not in ('auswahl', 'freitext')) then
        raise exception 'answer has unexpected fields' using errcode = '22023';
      end if;
      if v_typ = 'einzelauswahl' then
        if jsonb_typeof(v_val->'auswahl') is distinct from 'string' then
          raise exception 'answer is not a choice' using errcode = '22023';
        end if;
        v_auswahl := array[v_val->>'auswahl'];
      else
        if jsonb_typeof(v_val->'auswahl') is distinct from 'array'
           or jsonb_array_length(v_val->'auswahl') = 0
           or exists (select 1 from jsonb_array_elements(v_val->'auswahl') e
                      where jsonb_typeof(e) <> 'string') then
          raise exception 'answer is not a choice' using errcode = '22023';
        end if;
        select array_agg(e) into v_auswahl from jsonb_array_elements_text(v_val->'auswahl') e;
        if cardinality(v_auswahl) <> (select count(distinct e) from unnest(v_auswahl) e) then
          raise exception 'option chosen twice' using errcode = '22023';
        end if;
        -- "nein" steht allein.
        if v_auswahl && v_exklusiv and cardinality(v_auswahl) > 1 then
          raise exception 'exclusive option combined' using errcode = '22023';
        end if;
      end if;
      if not (v_auswahl <@ v_ids) then
        raise exception 'unknown option' using errcode = '22023';
      end if;
      if v_val ? 'freitext' then
        if jsonb_typeof(v_val->'freitext') <> 'string'
           or length(regexp_replace(v_val->>'freitext', '^\s+|\s+$', '', 'g')) not between 1 and 2000 then
          raise exception 'free text out of range' using errcode = '22023';
        end if;
        -- Eine eigene Angabe gehoert zu einer Option, die sie vorsieht.
        if not (v_auswahl && v_frei) then
          raise exception 'free text without matching option' using errcode = '22023';
        end if;
      end if;

    elsif v_typ in ('skala', 'zahl') then
      if exists (select 1 from jsonb_object_keys(v_val) k where k <> 'wert')
         or jsonb_typeof(v_val->'wert') is distinct from 'number' then
        raise exception 'answer is not a number' using errcode = '22023';
      end if;
      v_zahl := (v_val->>'wert')::numeric;
      -- Positiv formuliert: Fehlt ein Wert der Definition, ist NULL nicht
      -- "in Ordnung", sondern abgewiesen (Zweitreview H1).
      if v_typ = 'skala' and not coalesce(
           v_zahl = trunc(v_zahl)
           and v_zahl >= (v_item->'skala'->>'min')::numeric
           and v_zahl <= (v_item->'skala'->>'max')::numeric, false) then
        raise exception 'value out of range' using errcode = '22023';
      end if;

    elsif v_typ = 'freitext' then
      if exists (select 1 from jsonb_object_keys(v_val) k where k <> 'text')
         or jsonb_typeof(v_val->'text') is distinct from 'string' then
        raise exception 'answer is not a text' using errcode = '22023';
      end if;
      -- Jeder Leerraum wie Zods .trim(), nicht nur Leerzeichen (Zweitreview N1).
      v_text := regexp_replace(v_val->>'text', '^\s+|\s+$', '', 'g');
      if length(v_text) not between 1 and 2000 then
        raise exception 'free text out of range' using errcode = '22023';
      end if;

    elsif v_typ = 'koerperschema' then
      if exists (select 1 from jsonb_object_keys(v_val) k where k <> 'markierungen')
         or jsonb_typeof(v_val->'markierungen') is distinct from 'array'
         or jsonb_array_length(v_val->'markierungen') not between 1 and 30 then
        raise exception 'answer is not a body chart' using errcode = '22023';
      end if;
      for v_m in select e from jsonb_array_elements(v_val->'markierungen') e loop
        -- Schritt fuer Schritt und positiv: Erst die Form, dann die Werte -
        -- ein leeres Objekt oder ein fehlender Bereich ergibt nie NULL statt
        -- "abgewiesen" (Zweitreview H1).
        if jsonb_typeof(v_m) is distinct from 'object'
           or not coalesce(
                (select array_agg(k order by k) from jsonb_object_keys(v_m) k)
                  = array['bereich', 'x', 'y'], false)
           or jsonb_typeof(v_m->'x') is distinct from 'number'
           or jsonb_typeof(v_m->'y') is distinct from 'number'
           or jsonb_typeof(v_m->'bereich') is distinct from 'string' then
          raise exception 'body chart mark out of range' using errcode = '22023';
        end if;
        if not coalesce(
             (v_m->>'x')::numeric between 0 and 1
             and (v_m->>'y')::numeric between 0 and 1
             and (v_m->>'bereich') = any (app.questionnaire_body_regions()), false) then
          raise exception 'body chart mark out of range' using errcode = '22023';
        end if;
      end loop;

    else
      raise exception 'unknown item type' using errcode = '22023';
    end if;
  end loop;
end;
$_$;

COMMENT ON FUNCTION app.assert_questionnaire_answers(p_instrument_id text, p_version text, p_answers jsonb) IS 'Prueft Antworten gegen die Definition der genannten Fassung (ABN-014, BEF-101): Item, Form je Typ, Optionen, Skalenbereich, freie Angaben, exklusive Optionen, Koerperbereiche. Dieselben Regeln wie antwortSchema in src/features/assessments/antworten.ts.';

CREATE FUNCTION app.assert_staff_member_in_org(p_staff_member_id uuid, p_organization_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_staff_member_id is null then
    return;
  end if;

  if not exists (
    select 1
    from public.staff_members sm
    where sm.id = p_staff_member_id
      and sm.organization_id = p_organization_id
  ) then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_staff_member_in_org(p_staff_member_id uuid, p_organization_id uuid) IS 'Prueft, dass eine Mitarbeiter-ID zur uebergebenen Organisation gehoert. Eine fremde und eine unbekannte ID sind nicht zu unterscheiden (PROJECT_PRINCIPLES.md 13).';

CREATE FUNCTION app.assert_staff_role_keys(p_role_keys text[]) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_role_keys is null or cardinality(p_role_keys) = 0 then
    raise exception 'at least one role is required' using errcode = '22023';
  end if;

  if exists (
    select 1 from unnest(p_role_keys) as r(key)
    where r.key is null or r.key not in ('owner', 'therapist', 'team_lead', 'office', 'trainer')
  ) then
    raise exception 'unknown role' using errcode = '22023';
  end if;

  if cardinality(p_role_keys) <> (select count(distinct r.key) from unnest(p_role_keys) as r(key)) then
    raise exception 'duplicate role' using errcode = '22023';
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_staff_role_keys(p_role_keys text[]) IS 'Prueft eine Rollenliste fuer einen Praxiszugang: owner, therapist, team_lead, office und seit TRN-003 trainer. "patient" ist bewusst ausgeschlossen (PROJECT_PRINCIPLES.md 4.6).';

CREATE FUNCTION app.assert_text_snippet_input(p_title text, p_body text, p_staff_member_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_title is null or btrim(p_title) = '' then
    raise exception 'title must not be empty' using errcode = '22023';
  end if;
  if length(btrim(p_title)) > 80 then
    raise exception 'title is too long' using errcode = '22023';
  end if;
  if p_body is null or btrim(p_body, E' \t\r\n') = '' then
    raise exception 'snippet must not be empty' using errcode = '22023';
  end if;
  if length(btrim(p_body, E' \t\r\n')) > 2000 then
    raise exception 'snippet is too long' using errcode = '22023';
  end if;

  -- Praxisweit heisst: fuer alle sichtbar. Das darf nur owner.
  if p_staff_member_id is null and not app.can_manage_shared_text_snippets() then
    raise exception 'not allowed to manage shared text snippets' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION app.assert_treatment_basis_input(p_organization_id uuid, p_prescriber_id uuid, p_treatment_basis_kind text, p_issued_on date) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_treatment_basis_kind not in ('first', 'follow_up', 'self_pay') then
    raise exception 'unknown treatment basis kind' using errcode = '22023';
  end if;

  -- Pflicht fuer beide Bauarten: beim Rezept das Ausstellungsdatum, beim
  -- Selbstzahler der Tag der Vereinbarung (ADR-020 Punkt 3).
  if p_issued_on is null then
    raise exception 'issued_on is required' using errcode = '22023';
  end if;

  -- Ein Ausstellungsdatum in der Zukunft ist in der Praxis ein Tippfehler und
  -- keine Grundlage (PROJECT_PRINCIPLES.md 13).
  if p_issued_on > current_date then
    raise exception 'issued_on must not be in the future' using errcode = '22023';
  end if;

  -- ADR-020 Punkt 3: Was eine Verordnung braucht, verlangt die Datenbank weiter
  -- - aber nur von ihr. Ein Selbstzahler hat keine Verordner:in, und eine
  -- mitgeschickte ist keine Nachlaessigkeit, sondern ein Widerspruch: entweder
  -- der Aufrufer meint die falsche Bauart, oder er meint die falsche Person.
  if p_treatment_basis_kind = 'self_pay' then
    if p_prescriber_id is not null then
      raise exception 'self_pay must not carry a prescriber' using errcode = '22023';
    end if;
    return;
  end if;

  if p_prescriber_id is null then
    raise exception 'prescriber is required for a prescription' using errcode = '22023';
  end if;

  -- Verordner:in ausschliesslich in der eigenen Organisation suchen: eine
  -- fremde und eine unbekannte ID sind nicht zu unterscheiden.
  if not exists (
    select 1 from public.prescribers v
    where v.id = p_prescriber_id and v.organization_id = p_organization_id
  ) then
    raise exception 'prescriber not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION app.assert_treatment_basis_input(p_organization_id uuid, p_prescriber_id uuid, p_treatment_basis_kind text, p_issued_on date) IS 'Prueft Bauart, Ausstellungsdatum und Verordner:in einer Behandlungsgrundlage (VER-003, ADR-020 Punkt 3): Verordner:in Pflicht bei first und follow_up, ausgeschlossen bei self_pay.';

CREATE FUNCTION app.assert_valid_time_zone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- NULL bleibt der NOT-NULL-Constraint ueberlassen: sie meldet den fehlenden
  -- Wert deutlicher als eine Katalogpruefung, die ins Leere laeuft.
  if new.time_zone is not null and not exists (
    select 1 from pg_catalog.pg_timezone_names z where z.name = new.time_zone
  ) then
    raise exception 'unknown IANA time zone' using errcode = '22023';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.assert_valid_time_zone() IS 'Prueft organizations.time_zone gegen den IANA-Katalog der Datenbank (CAL-001).';

CREATE FUNCTION app.assert_working_time_change(p_org uuid, p_staff_member_id uuid, p_kind text, p_on_date date, p_blocks jsonb, p_errcode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_bisher   jsonb;
  v_minuten  integer;
  v_probleme text[];
begin
  v_bisher := app.working_time_baseline(p_org, p_staff_member_id, p_kind, p_on_date);
  if p_blocks = v_bisher -> 'blocks' then
    raise exception 'working time unchanged' using errcode = p_errcode;
  end if;
  -- ZK-001 (Zweitreview B4): Ein neuer Wochenplan ändert keinen Tag mit
  -- Freizeitausgleich ab seinem Datum still - der Eintrag rechnet mit den
  -- bisherigen Zeiten. Erst zurückweisen oder zurücknehmen (55000, ANN-595).
  if p_kind = 'permanent' and app.time_off_on_changed_weekdays(
    p_org, p_staff_member_id, p_on_date, p_blocks, v_bisher -> 'blocks'
  ) then
    raise exception 'day has time off in lieu' using errcode = '55000';
  end if;
  v_minuten := app.working_time_minutes(p_kind, p_blocks);
  if v_minuten < (v_bisher ->> 'minutes')::integer then
    raise exception 'working time would be reduced' using errcode = p_errcode;
  end if;
  v_probleme := app.working_time_problems(p_org, p_staff_member_id, p_kind, p_on_date, p_blocks);
  if cardinality(v_probleme) > 0 then
    raise exception 'working time rule: %', array_to_string(v_probleme, ', ') using errcode = p_errcode;
  end if;
  return v_bisher || jsonb_build_object('new_minutes', v_minuten);
end;
$$;

CREATE FUNCTION app.assert_working_time_date(p_org uuid, p_kind text, p_on_date date) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_heute date;
begin
  if p_kind is null or p_kind not in ('once', 'permanent') then
    raise exception 'kind must be once or permanent' using errcode = '22023';
  end if;
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = p_org;
  if p_on_date is null or p_on_date <= v_heute or p_on_date > v_heute + 400 then
    raise exception 'working time change date is invalid' using errcode = '22023';
  end if;
end;
$$;

CREATE FUNCTION app.audit_entry_held(p_organization_id uuid, p_subject_type text, p_subject_id uuid, p_context jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  with akte as (
    select case when p_subject_type = 'patient' then p_subject_id
                when p_context ->> 'patient_id' ~ '^[0-9a-f-]{36}$'
                  then (p_context ->> 'patient_id')::uuid
           end as id
  )
  select coalesce((
    select app.under_legal_hold(p_organization_id, 'patient', akte.id)
        or exists (
             select 1 from public.patient_merge_records m
             where m.organization_id = p_organization_id
               and m.source_patient_id = akte.id
               and app.under_legal_hold(p_organization_id, 'patient', m.target_patient_id))
    from akte
    where akte.id is not null
  ), false)
$_$;

CREATE FUNCTION app.audit_retention_class(p_action text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_action in (
      'patient_record.viewed', 'training_relationship.viewed', 'platform_representation.read',
      'access.denied',
      'account.password_changed', 'account.sessions_ended', 'account.mfa_enrolled',
      'account.mfa_removed',
      'staff_account.locked', 'staff_account.unlocked', 'staff_account.password_reset_requested'
    ) then 'auditlog_lesen_sicherheit'
    else 'auditlog'
  end
$$;

COMMENT ON FUNCTION app.audit_retention_class(p_action text) IS 'LOG-EPIC-001 (ADR-011 Punkt 4): Lese- und Sicherheitsereignisse zwoelf Monate, alle uebrigen Auditeintraege drei Jahre.';

CREATE FUNCTION app.auskunft_ohne_kennungen(p_zeile jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
  from jsonb_each(p_zeile) e
  where e.key not in ('organization_id', 'training_relationship_id', 'person_id')
    and e.key not like '%\_by'
    and e.key not like '%platform\_access\_id'
$$;

COMMENT ON FUNCTION app.auskunft_ohne_kennungen(p_zeile jsonb) IS 'BEF-182 (Zweitreview): entfernt aus einer Zeile der Auskunft Mandant, Verweise auf Verhaeltnis und Person und jede Kennung bearbeitender Konten oder Zugaenge nach Muster.';

CREATE FUNCTION app.auskunft_organisation(p_patient_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.has_any_role('owner') then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.patients p
    where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  return v_org;
end;
$$;

COMMENT ON FUNCTION app.auskunft_organisation(p_patient_id uuid) IS 'Prueft Anmeldung, owner-Rolle und Mandantengrenze fuer die Betroffenenrechte und liefert die Organisation (OPS-006, ADR-004).';

CREATE FUNCTION app.auskunft_organisation_training(p_training_relationship_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.has_any_role('owner') then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  -- Ob es das Verhältnis gibt, ist selbst eine Auskunft (ADR-003): dieselbe
  -- Abweisung wie ohne Recht.
  if not exists (
    select 1 from public.training_relationships t
    where t.id = p_training_relationship_id and t.organization_id = v_org
  ) then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  return v_org;
end;
$$;

COMMENT ON FUNCTION app.auskunft_organisation_training(p_training_relationship_id uuid) IS 'BEF-182: Prueft Anmeldung, owner-Rolle und Mandantengrenze fuer die Auskunft zu einem Trainingsverhaeltnis und liefert die Organisation (wie app.auskunft_organisation, ADR-004).';

CREATE FUNCTION app.billable_fee_basis(p_fee_basis text, p_fee_waived_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_fee_waived_at is null then p_fee_basis end
$$;

COMMENT ON FUNCTION app.billable_fee_basis(p_fee_basis text, p_fee_waived_at timestamp with time zone) IS 'Gebuehrenanlass, soweit er noch abrechenbar ist: null nach einem Verzicht (ABN-006, BEF-094).';

CREATE FUNCTION app.billable_service_amount(p_billable_service_id uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select l.line_cents
       from app.session_fee_lines(b.appointment_id) l
      where l.billable_service_id = b.id),
    b.quantity::bigint * c.unit_price_cents
  )
  from public.billable_services b
  join public.service_catalog_items c on c.id = b.catalog_item_id
  where b.id = p_billable_service_id
$$;

COMMENT ON FUNCTION app.billable_service_amount(p_billable_service_id uuid) IS 'Betrag einer erfassten Leistung in Cent (ABR-031): ihr Anteil am Terminhonorar, wenn der Termin eines traegt und die Position ein Heilmittel ist, sonst Menge mal Katalogpreis (Bestand, Ausfallhonorar, Positionen ohne Heilmittel, Training).';

CREATE FUNCTION app.billable_service_area_from_catalog() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_area text;
begin
  select c.service_area into v_area
  from public.service_catalog_items c
  where c.id = new.catalog_item_id;

  -- Eine Position, die es nicht gibt, weist der Fremdschluessel ab; hier
  -- bleibt nichts zu setzen.
  if v_area is null then
    return new;
  end if;

  if new.service_area is not null and new.service_area is distinct from v_area then
    raise exception 'service area % does not match the catalog item (%)', new.service_area, v_area
      using errcode = '23514';
  end if;

  new.service_area := v_area;
  return new;
end;
$$;

COMMENT ON FUNCTION app.billable_service_area_from_catalog() IS 'Setzt den Leistungsbereich einer erfassten Leistung aus ihrer Katalogposition (ABR-008, ADR-009 Punkt 16). Am Trigger, damit jeder Schreibweg ihn traegt; ein abweichend mitgegebener Bereich wird abgewiesen statt still ersetzt.';

CREATE FUNCTION app.billable_service_matches_appointment_context() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_kind     text;
  v_patient  uuid;
  v_training uuid;
  v_erwartet text;
  v_art      text;
  v_occasion text;
begin
  select c.item_kind into v_art
  from public.service_catalog_items c where c.id = new.catalog_item_id;

  if new.appointment_id is null then
    -- ANG-006: das Trainingspaket - Position, Verhaeltnis und Beginn sind die
    -- des Pakets.
    if new.training_package_id is not null then
      if v_art is distinct from 'training_package' or not exists (
        select 1 from public.training_packages k
        where k.id = new.training_package_id
          and k.training_relationship_id = new.training_relationship_id
          and k.organization_id = new.organization_id
          and k.catalog_item_id = new.catalog_item_id
          and k.starts_on = new.performed_on
      ) then
        raise exception 'billable service does not match its training package'
          using errcode = '23514';
      end if;
      return new;
    end if;
    if v_art is distinct from 'aftercare_month' then
      raise exception 'only an aftercare month or a training package can be billed without an appointment'
        using errcode = '23514';
    end if;
    if not exists (
      select 1 from public.aftercare_subscriptions s
      where s.id = new.aftercare_subscription_id
        and s.patient_id = new.patient_id
        and s.organization_id = new.organization_id
    ) then
      raise exception 'billable service does not belong to the patient of its aftercare subscription'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if v_art = 'aftercare_month' then
    raise exception 'an aftercare month is not billed at an appointment' using errcode = '23514';
  end if;
  -- ANG-006: ein Paket nie am Termin.
  if v_art = 'training_package' then
    raise exception 'a training package is not billed at an appointment' using errcode = '23514';
  end if;

  select a.kind, a.patient_id, a.training_relationship_id, a.occasion
    into v_kind, v_patient, v_training, v_occasion
  from public.appointments a
  where a.id = new.appointment_id;

  v_erwartet := app.service_area_of_appointment_kind(v_kind);

  if v_erwartet is null then
    raise exception 'an appointment of kind % cannot carry billable services', v_kind
      using errcode = '23514';
  end if;

  if new.service_area is distinct from v_erwartet then
    raise exception 'service area % does not match the appointment context % (expected %)',
      new.service_area, v_kind, v_erwartet
      using errcode = '23514';
  end if;

  -- TRN-007: dasselbe Verhaeltnis wie der Termin, in beiden Spalten.
  if new.patient_id is distinct from v_patient
     or new.training_relationship_id is distinct from v_training then
    raise exception 'billable service does not belong to the relationship of its appointment'
      using errcode = '23514';
  end if;

  -- ERN-011 (ANN-664): Am Beratungstermin steht nur die Position der
  -- Ernaehrungsberatung, und sie steht an keinem anderen Termin.
  if (v_occasion = 'nutrition_counselling') is distinct from (v_art = 'nutrition_counselling') then
    raise exception 'billable service does not match the appointment occasion' using errcode = '23514';
  end if;

  -- ANG-007 (ANN-279, BEF-114): Ein Trainingstermin im Zeitraum eines Pakets
  -- ist mit dem Paket bezahlt und traegt keine eigene Forderung. Die
  -- Ernaehrungsberatung ist nicht Teil des Pakets (ERN-011).
  if v_kind = 'training' and v_occasion = 'regular' then
    -- Zweitreview: unter Sperre des Verhaeltnisses. create_training_package
    -- haelt es FOR UPDATE; FOR SHARE wartet darauf, und die Abfrage danach
    -- sieht das neue Paket (READ COMMITTED, neuer Snapshot je Anweisung).
    -- Umgekehrt wartet die Paketanlage, bis diese Erfassung feststeht, und
    -- ihr Guard sieht sie. Sonst liefen beide an der Pruefung vorbei.
    perform 1 from public.training_relationships t where t.id = v_training for share;
    if app.training_package_covering(v_training, app.appointment_performed_on(new.appointment_id)) is not null then
      raise exception 'training appointment is covered by a training package' using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.billable_service_matches_appointment_context() IS 'Weist eine Leistung ab, deren Leistungsbereich dem Kontext ihres Termins widerspricht (ADR-009 Punkt 16, ADR-022 Punkt 2) oder die an einem anderen Verhaeltnis haengt als ihr Termin (TRN-007). Abweisen und nicht anpassen: Punkt 16 nennt den Widerspruch einen Erfassungsfehler und schliesst die stille Korrektur aus.';

CREATE FUNCTION app.billable_service_period_until(p_billable_service_id uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select app.aftercare_month_end(s.starts_on, app.aftercare_month_index(s.starts_on, b.performed_on))
       from public.aftercare_subscriptions s
      where s.id = b.aftercare_subscription_id),
    (select k.ends_on from public.training_packages k where k.id = b.training_package_id)
  )
  from public.billable_services b
  where b.id = p_billable_service_id
$$;

CREATE FUNCTION app.billable_services_require_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_termin record;
begin
  if new.appointment_id is null then
    return new;
  end if;
  -- Beim Aendern nur, wenn die Leistung an einen anderen Termin wandert.
  if tg_op = 'UPDATE' and new.appointment_id is not distinct from old.appointment_id then
    return new;
  end if;

  select a.kind, a.status, a.completed_at,
         app.billable_fee_basis(a.fee_basis, a.fee_waived_at) as anlass
    into v_termin
  from public.appointments a
  where a.id = new.appointment_id;

  if found
     and v_termin.anlass is null
     and not app.appointment_is_checked(v_termin.kind, v_termin.status, v_termin.completed_at) then
    raise exception 'appointment is not checked off' using errcode = '22023';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.billable_services_require_check() IS 'B4/B7 (ANN-513): Eine Leistung an einem Behandlungstermin entsteht nur mit dem Haken (oder aus einem Gebuehrenanlass) - auf jedem Weg, auch im Buero, und auch beim Umhaengen auf einen anderen Termin.';

CREATE FUNCTION app.billing_kind(p_kind text, p_occasion text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_occasion = 'nutrition_counselling' then 'nutrition_counselling' else p_kind end
$$;

CREATE FUNCTION app.billing_retention_due_at(p_patient_id uuid, p_time_zone text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select max(app.retention_due_at(
           (date_trunc('year', t.beleg_am) + interval '1 year' - interval '1 day')::date,
           app.retention_interval('abrechnungsdaten'),
           p_time_zone
         ))
  from (
    select i.issued_on as beleg_am
    from public.invoices i
    where i.patient_id = p_patient_id
      and i.status = 'issued'

    union all

    -- Die drei folgenden Belege haengen ausschliesslich an ausgestellten
    -- Rechnungen; ihr Datum wird trotzdem ohne Umweg ueber den
    -- Rechnungszustand gelesen. Was als Beleg in der Tabelle steht, zaehlt.
    select c.cancelled_on
    from public.invoice_cancellations c
    join public.invoices i on i.id = c.invoice_id
    where i.patient_id = p_patient_id

    union all

    select r.reminder_on
    from public.invoice_payment_reminders r
    join public.invoices i on i.id = r.invoice_id
    where i.patient_id = p_patient_id

    union all

    select p.paid_on
    from public.payments p
    join public.invoices i on i.id = p.invoice_id
    where i.patient_id = p_patient_id
  ) t
$$;

COMMENT ON FUNCTION app.billing_retention_due_at(p_patient_id uuid, p_time_zone text) IS 'Ablauf der steuerlichen Aufbewahrung ueber alle Abrechnungsbelege einer Patientin: ausgestellte Rechnungen, Stornodokumente, Zahlungserinnerungen und Zahlungen (ADR-008, Par. 147 AO, R3-003). null heisst: kein Beleg. Haelt die Akte im Loeschlauf zurueck, solange die laengste Frist laeuft.';

CREATE FUNCTION app.bootstrap_practice(p_owner_email text, p_organization_name text, p_time_zone text, p_location_name text, p_given_name text, p_family_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_email       text;
  v_org_name    text;
  v_time_zone   text;
  v_loc_name    text;
  v_given       text;
  v_family      text;
  v_user        uuid;
  v_confirmed   timestamptz;
  v_treffer     integer;
  v_org         uuid;
  v_location    uuid;
  v_person      uuid;
  v_staff       uuid;
begin
  -- Zweite Sperre neben dem fehlenden Grant: Ein angemeldeter
  -- Anwendungsnutzer richtet keine Praxis ein.
  if auth.uid() is not null then
    raise exception 'bootstrap not allowed for application users' using errcode = '42501';
  end if;

  -- Eine Sperre gegen den gleichzeitigen zweiten Aufruf; die Pruefung darunter
  -- saehe sonst zweimal eine leere Tabelle. Die Sperre traegt nur unter READ
  -- COMMITTED: Unter REPEATABLE READ oder SERIALIZABLE stammt der Schnappschuss
  -- aus der Zeit vor der Sperre, und ein paralleler zweiter Aufruf saehe die
  -- erste Organisation nicht. Deshalb wird jede andere Stufe abgewiesen, statt
  -- sich auf die Voreinstellung des SQL-Editors zu verlassen.
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'bootstrap requires read committed' using errcode = '25001';
  end if;

  lock table public.organizations in share row exclusive mode;

  if exists (select 1 from public.organizations) then
    raise exception 'already_bootstrapped' using errcode = '55000';
  end if;

  v_email     := lower(btrim(coalesce(p_owner_email, '')));
  v_org_name  := btrim(coalesce(p_organization_name, ''));
  v_time_zone := btrim(coalesce(p_time_zone, ''));
  v_loc_name  := btrim(coalesce(p_location_name, ''));
  v_given     := btrim(coalesce(p_given_name, ''));
  v_family    := btrim(coalesce(p_family_name, ''));

  if v_org_name = '' or v_loc_name = '' then
    raise exception 'organization name and location name are required' using errcode = '22023';
  end if;

  if v_given = '' or v_family = '' then
    raise exception 'given name and family name are required' using errcode = '22023';
  end if;

  -- Die Zeitzone legt fest, wie Kalendertage und Uhrzeiten gelesen werden
  -- (CAL-001). Ein Tippfehler faellt sonst erst beim ersten Termin auf.
  if not exists (select 1 from pg_catalog.pg_timezone_names t where t.name = v_time_zone) then
    raise exception 'unknown time zone' using errcode = '22023';
  end if;

  select count(*), min(u.id::text)::uuid, min(u.email_confirmed_at)
    into v_treffer, v_user, v_confirmed
  from auth.users u
  where lower(u.email) = v_email
    -- Ein geloeschtes, gesperrtes oder anonymes Konto wird nicht Inhaberin.
    -- Ueber to_jsonb, weil diese Spalten dem Anmeldedienst gehoeren und nicht
    -- in jeder Fassung von auth.users stehen.
    and to_jsonb(u) ->> 'deleted_at' is null
    and coalesce((to_jsonb(u) ->> 'banned_until')::timestamptz <= now(), true)
    and coalesce((to_jsonb(u) ->> 'is_anonymous')::boolean, false) = false;

  if v_treffer = 0 then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  if v_treffer > 1 then
    raise exception 'account ambiguous' using errcode = '22023';
  end if;

  -- Ohne bestaetigte Adresse scheitert die erste Anmeldung; besser hier.
  -- Ein schon gebundenes Konto braucht keine eigene Pruefung: Ein Profil setzt
  -- eine Organisation voraus, und die gibt es an dieser Stelle nicht.
  if v_confirmed is null then
    raise exception 'account not confirmed' using errcode = '22023';
  end if;

  insert into public.organizations (name, time_zone, created_by)
  values (v_org_name, v_time_zone, v_user)
  returning id into v_org;

  insert into public.locations (organization_id, name, created_by)
  values (v_org, v_loc_name, v_user)
  returning id into v_location;

  insert into public.persons (organization_id, given_name, family_name, created_by)
  values (v_org, v_given, v_family, v_user)
  returning id into v_person;

  insert into public.staff_members (
    organization_id, person_id, primary_location_id, employment_status, work_email, created_by
  )
  values (v_org, v_person, v_location, 'active', v_email, v_user)
  returning id into v_staff;

  -- Wie create_staff_member: Die Zeile der Privatangaben entsteht immer, leer.
  insert into public.staff_private_details (staff_member_id, organization_id, created_by)
  values (v_staff, v_org, v_user);

  insert into public.user_profiles (id, organization_id, person_id, display_name, created_by)
  values (v_user, v_org, v_person, v_given || ' ' || v_family, v_user);

  insert into public.user_roles (user_id, organization_id, role_key, created_by)
  values (v_user, v_org, 'owner', v_user);

  insert into public.audit_log (
    organization_id, actor_kind, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, 'system', null, 'organization.bootstrapped', 'organization', v_org, 'success',
    jsonb_build_object(
      'surface', 'sql',
      'purpose', 'bootstrap',
      'owner_user_id', v_user,
      'roles', jsonb_build_array('owner')
    )
  );

  return jsonb_build_object(
    'organization_id', v_org,
    'location_id', v_location,
    'staff_member_id', v_staff,
    'user_id', v_user
  );
end;
$$;

COMMENT ON FUNCTION app.bootstrap_practice(p_owner_email text, p_organization_name text, p_time_zone text, p_location_name text, p_given_name text, p_family_name text) IS 'Richtet die eine Organisation ein: Standort, Person, Mitarbeiterdatensatz, Profil und Rolle owner fuer ein vorhandenes, bestaetigtes Konto. Nur Eigentuemerrolle, nur solange keine Organisation existiert (OPS-007, ADR-003, ADR-010). Vorgehen: docs/betrieb/bootstrap.md.';

CREATE FUNCTION app.build_invoice_document(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_invoice   record;
  v_profile   record;
  v_items     jsonb;
  v_gruppen   jsonb;
  v_basen     jsonb;
  v_empfaenger jsonb;
  v_patient   jsonb;
  v_summe     integer;
  v_steuer    integer;
  v_waehrung  text;
  v_anzahl    integer;
begin
  select i.* into v_invoice from public.invoices i where i.id = p_invoice_id;
  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  select b.* into v_profile
  from public.practice_billing_profiles b
  where b.organization_id = v_invoice.organization_id;

  if not found then
    raise exception 'practice billing profile missing' using errcode = '22023';
  end if;

  -- Die Zeilen. Preis, Bezeichnung und Steuerkennzeichen kommen aus der
  -- Katalogposition - sie ist unveraenderlich, solange ihre Preisliste in
  -- Kraft ist (ABR-001).
  select jsonb_agg(z.zeile order by z.sort_order),
         sum(z.brutto)::integer,
         count(*)::integer,
         max(z.currency)
    into v_items, v_summe, v_anzahl, v_waehrung
  from (
    select it.sort_order,
           c.currency,
           -- ABR-031: Anteil am Terminhonorar oder Katalogpreis.
           app.billable_service_amount(b.id) as brutto,
           jsonb_build_object(
             'performed_on',      b.performed_on,
             'code',              c.code,
             'label',             c.label,
             'item_kind',         c.item_kind,
             'quantity',          b.quantity,
             'unit_price_cents',  app.billable_service_amount(b.id) / b.quantity,
             'line_total_cents',  app.billable_service_amount(b.id),
             'currency',          c.currency,
             'tax_treatment',     c.tax_treatment,
             'tax_rate_permille', c.tax_rate_permille,
             -- ABR-032 (schema_version 5): Anteil am Terminhonorar? Die
             -- Darstellung fasst gleiche Positionen mit ihren Tagen zusammen.
             'session_fee',       exists (
                                    select 1 from public.appointment_session_fees f
                                    where f.appointment_id = b.appointment_id
                                  ) and c.remedy is not null,
             -- ANG-002: Ein Abo-Monat nennt seinen Zeitraum, nicht nur den
             -- ersten Tag (Par. 14 Abs. 4 Nr. 6 UStG). Sonst null.
             'period_until',      app.billable_service_period_until(b.id)
           ) as zeile
    from public.invoice_items it
    join public.billable_services b     on b.id = it.billable_service_id
    join public.service_catalog_items c on c.id = b.catalog_item_id
    where it.invoice_id = p_invoice_id
  ) z;

  if v_anzahl is null or v_anzahl = 0 then
    raise exception 'invoice has no items' using errcode = '22023';
  end if;

  if (select count(distinct c.currency)
        from public.invoice_items it
        join public.billable_services b     on b.id = it.billable_service_id
        join public.service_catalog_items c on c.id = b.catalog_item_id
       where it.invoice_id = p_invoice_id) > 1 then
    raise exception 'an invoice cannot mix currencies' using errcode = '22023';
  end if;

  -- Steuergruppen: je Kennzeichen und Satz der Bruttobetrag, die darin
  -- enthaltene Steuer und der Nettobetrag. Unter der Kleinunternehmerregelung
  -- ist die enthaltene Steuer null - auch bei einer steuerpflichtigen
  -- Position (Par. 19 UStG). Der Grund der Befreiung steht an der Gruppe
  -- (ABR-006, ANN-082).
  select jsonb_agg(g.gruppe order by g.tax_treatment, g.tax_rate_permille),
         sum(g.steuer)::integer
    into v_gruppen, v_steuer
  from (
    select c.tax_treatment,
           c.tax_rate_permille,
           sum(app.billable_service_amount(b.id))::integer as brutto,
           case
             when v_profile.small_business or c.tax_treatment <> 'taxable' then 0
             else round(sum(app.billable_service_amount(b.id))::numeric
                        * c.tax_rate_permille / (1000 + c.tax_rate_permille))::integer
           end as steuer,
           jsonb_build_object(
             'tax_treatment',     c.tax_treatment,
             'tax_rate_permille', c.tax_rate_permille,
             'gross_cents',       sum(app.billable_service_amount(b.id))::integer,
             'tax_cents',
               case
                 when v_profile.small_business or c.tax_treatment <> 'taxable' then 0
                 else round(sum(app.billable_service_amount(b.id))::numeric
                            * c.tax_rate_permille / (1000 + c.tax_rate_permille))::integer
               end,
             'net_cents',
               sum(app.billable_service_amount(b.id))::integer
               - case
                   when v_profile.small_business or c.tax_treatment <> 'taxable' then 0
                   else round(sum(app.billable_service_amount(b.id))::numeric
                              * c.tax_rate_permille / (1000 + c.tax_rate_permille))::integer
                 end,
             'exemption_reason', app.tax_exemption_reason(c.tax_treatment)
           ) as gruppe
    from public.invoice_items it
    join public.billable_services b     on b.id = it.billable_service_id
    join public.service_catalog_items c on c.id = b.catalog_item_id
    where it.invoice_id = p_invoice_id
    group by c.tax_treatment, c.tax_rate_permille
  ) g;

  -- Verordnungsbezug: Bauart, Ausstellungsdatum, Verordner:in - und seit
  -- schema_version 4 die Diagnose der Verordnung, ICD-10 und Text (ANN-229).
  -- Private Kassen und Beihilfe erwarten sie auf der Rechnung. Ob sie
  -- draufsteht, entscheidet allein app.invoice_shows_diagnosis(). Therapieziel
  -- und Verordnerhinweis bleiben weg (Datensparsamkeit), am Selbstzahler gibt
  -- es keine Diagnose.
  select jsonb_agg(v.eintrag order by v.issued_on)
    into v_basen
  from (
    select distinct tb.issued_on,
           jsonb_build_object(
             'kind',       tb.treatment_basis_kind,
             'issued_on',  tb.issued_on,
             'prescriber',
               case when pr.id is null then null
                    else btrim(coalesce(pr.title || ' ', '') || pr.given_name || ' ' || pr.family_name)
               end,
             'diagnosis_icd10',
               case when app.invoice_shows_diagnosis() then tb.diagnosis_icd10 end,
             'diagnosis',
               case when app.invoice_shows_diagnosis() then nullif(btrim(tb.diagnosis), '') end
           ) as eintrag
    from public.invoice_items it
    join public.billable_services b on b.id = it.billable_service_id
    join public.appointments a      on a.id = b.appointment_id
    join public.treatment_bases tb  on tb.id = a.treatment_basis_id
    left join public.prescribers pr on pr.id = tb.prescriber_id
    where it.invoice_id = p_invoice_id
  ) v;

  -- Empfaenger: die hinterlegte Zeile oder, wenn keine gewaehlt ist, die
  -- Patientin selbst (ANN-076).
  --
  -- TRN-008 (ANN-182): Eine Trainingsrechnung geht an die Kund:in selbst, mit
  -- der Anschrift aus dem Trainingskontakt - nie aus der Akte, auch wenn
  -- dieselbe Person eine hat (ADR-021 Punkt 3). Seit ABN-020 (BEF-111) mit
  -- Strasse und Hausnummer in getrennten Feldern wie in der Akte.
  if v_invoice.training_relationship_id is not null then
    select jsonb_build_object(
             'kind',         'self',
             'name',         pe.given_name || ' ' || pe.family_name,
             'street',       tc.street,
             'house_number', tc.house_number,
             'postal_code',  tc.postal_code,
             'city',         tc.city,
             'reference',    null
           )
      into v_empfaenger
    from public.training_relationships t
    join public.persons pe on pe.id = t.person_id
    left join public.training_contact_details tc on tc.training_relationship_id = t.id
    where t.id = v_invoice.training_relationship_id;
  elsif v_invoice.recipient_id is null then
    select jsonb_build_object(
             'kind',         'self',
             'name',         pe.given_name || ' ' || pe.family_name,
             'street',       pc.street,
             'house_number', pc.house_number,
             'postal_code',  pc.postal_code,
             'city',         pc.city,
             'reference',    null
           )
      into v_empfaenger
    from public.patients p
    join public.persons pe on pe.id = p.person_id
    left join public.patient_contact_details pc on pc.patient_id = p.id
    where p.id = v_invoice.patient_id;
  else
    select jsonb_build_object(
             'kind',         r.recipient_kind,
             'name',         r.name,
             'street',       r.street,
             'house_number', r.house_number,
             'postal_code',  r.postal_code,
             'city',         r.city,
             'reference',    r.reference
           )
      into v_empfaenger
    from public.invoice_recipients r
    where r.id = v_invoice.recipient_id;
  end if;

  -- Die behandelte Person steht auch dann auf der Rechnung, wenn jemand
  -- anderes sie bezahlt - sonst liesse sich die Leistung nicht zuordnen.
  --
  -- TRN-008 (ANN-182): Im Training ist sie zugleich die Empfaengerin; das
  -- Geburtsdatum dient in der Behandlung der Zuordnung bei Beihilfe und
  -- Versicherung und bleibt im Training weg (Datenminimierung, Art. 5 Abs. 1
  -- lit. c DSGVO). Der Schluessel heisst im Snapshot weiter `patient`: Er
  -- nennt die Person, fuer die geleistet wurde; die Beschriftung waehlt die
  -- Darstellung am Bereich.
  if v_invoice.training_relationship_id is not null then
    select jsonb_build_object(
             'name',          pe.given_name || ' ' || pe.family_name,
             'date_of_birth', null
           )
      into v_patient
    from public.training_relationships t
    join public.persons pe on pe.id = t.person_id
    where t.id = v_invoice.training_relationship_id;
  else
    select jsonb_build_object(
             'name',          pe.given_name || ' ' || pe.family_name,
             'date_of_birth', pc.date_of_birth
           )
      into v_patient
    from public.patients p
    join public.persons pe on pe.id = p.person_id
    left join public.patient_contact_details pc on pc.patient_id = p.id
    where p.id = v_invoice.patient_id;
  end if;

  return jsonb_build_object(
    -- BEF-165 (schema_version 6): der Hinweis nach Par. 19 UStG im Dokument.
    'schema_version', 6,
    'period_month', v_invoice.period_month,
    -- ABR-032: der erste und der letzte Leistungstag der Rechnung.
    'service_period', (
      select jsonb_build_object(
               'from', min(b.performed_on),
               'to', max(coalesce(app.billable_service_period_until(b.id), b.performed_on)))
      from public.invoice_items it
      join public.billable_services b on b.id = it.billable_service_id
      where it.invoice_id = p_invoice_id
    ),
    'service_area', v_invoice.service_area,
    'currency', v_waehrung,
    'issuer', jsonb_build_object(
      'legal_name',        v_profile.legal_name,
      'street',            v_profile.street,
      'house_number',      v_profile.house_number,
      'postal_code',       v_profile.postal_code,
      'city',              v_profile.city,
      'phone',             v_profile.phone,
      'email',             v_profile.email,
      'tax_number',        v_profile.tax_number,
      'vat_id',            v_profile.vat_id,
      'small_business',    v_profile.small_business,
      -- BEF-165: der Wortlaut zum Zeitpunkt der Ausstellung, sonst null.
      'small_business_notice',
        case when v_profile.small_business then app.small_business_notice() end,
      'bank_name',         v_profile.bank_name,
      'account_holder',    v_profile.account_holder,
      'iban',              v_profile.iban,
      'bic',               v_profile.bic,
      'payment_term_days', v_profile.payment_term_days
    ),
    'recipient', v_empfaenger,
    'patient', v_patient,
    'treatment_bases', coalesce(v_basen, '[]'::jsonb),
    'items', v_items,
    'tax_groups', coalesce(v_gruppen, '[]'::jsonb),
    'totals', jsonb_build_object(
      'total_cents', v_summe,
      'tax_total_cents', coalesce(v_steuer, 0)
    )
  );
end;
$$;

COMMENT ON FUNCTION app.build_invoice_document(p_invoice_id uuid) IS 'Baut das Rechnungsdokument aus Stammdaten, Empfaenger, Leistungen und Steuergruppen (ABR-003, ADR-009 Punkt 10). Dieselbe Funktion liefert die Entwurfsansicht und den Snapshot beim Ausstellen. Seit ABR-006 mit dem Grund der Steuerbefreiung je Gruppe, seit ABR-010 mit dem Leistungsbereich, seit TRN-008 mit Empfaenger und Person aus dem Trainingsverhaeltnis (ANN-182), seit schema_version 4 mit der Diagnose der Verordnung (ANN-229, Schalter app.invoice_shows_diagnosis).';

