CREATE FUNCTION app.fleet_photo_sides() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array['left', 'front', 'right', 'back']::text[]
$$;

COMMENT ON FUNCTION app.fleet_photo_sides() IS 'FLT-007 (ANN-568): die vier Seiten des Rads fuer die Fotos im Check-Up. Gegenstueck SEITEN in src/features/fleet/checkupablauf.ts.';

CREATE TABLE public.fleet_photos (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bike_id uuid NOT NULL,
    spot_id uuid,
    checkup_id uuid,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    checksum_sha256 text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    confirmation_requested_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    verified_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    object_key text GENERATED ALWAYS AS ((((((organization_id)::text || '/'::text) || (COALESCE(spot_id, checkup_id))::text) || '/'::text) || (id)::text)) STORED NOT NULL,
    side text,
    CONSTRAINT fleet_photos_byte_size_check CHECK (((byte_size > 0) AND (byte_size <= 10485760))),
    CONSTRAINT fleet_photos_checksum_sha256_check CHECK ((checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT fleet_photos_mime_type_check CHECK ((mime_type = 'image/jpeg'::text)),
    CONSTRAINT fleet_photos_one_reference CHECK (((spot_id IS NULL) <> (checkup_id IS NULL))),
    CONSTRAINT fleet_photos_ready_confirmed CHECK (((status = 'ready'::text) = (confirmed_at IS NOT NULL))),
    CONSTRAINT fleet_photos_side_check CHECK ((side = ANY (app.fleet_photo_sides()))),
    CONSTRAINT fleet_photos_side_on_checkup CHECK (((side IS NULL) OR (checkup_id IS NOT NULL))),
    CONSTRAINT fleet_photos_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text])))
);

COMMENT ON TABLE public.fleet_photos IS 'FLT-002 (ANN-552): Foto an einer Stelle am Rad oder an einem Check-Up ("Weitere Fotos"). Nur Gegenstaende, nie Personen. Datenklasse radflotte_ereignis, faellt mit Stelle oder Check-Up (cascade) und hinterlaesst einen Loeschauftrag fuer das Objekt (ADR-017 Punkt 25). Kein Tabellenrecht.';

COMMENT ON COLUMN public.fleet_photos.checksum_sha256 IS 'SHA-256 der abgelegten Bytes, im Browser gerechnet; zum Nachweis des Servers erst mit verified_at (ADR-017 Punkte 9 und 49).';

COMMENT ON COLUMN public.fleet_photos.side IS 'FLT-007 (ANN-568): die Seite des Rads bei einem Seitenfoto im Check-Up (left, right, front, back); null bei einem weiteren Foto oder einem Foto an einer Stelle.';

CREATE FUNCTION app.can_delete_fleet_photo(p_photo public.fleet_photos) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.can_manage_fleet()
         or (p_photo.created_by = auth.uid()
             and (p_photo.created_at at time zone o.time_zone)::date
                 = (now() at time zone o.time_zone)::date)
  from public.organizations o
  where o.id = p_photo.organization_id
$$;

