CREATE FUNCTION app.can_write_patient_file(p_document_type text, p_treatment_basis_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    case
      -- ADR-017 Punkt 13: Der Scan folgt dem Schreibrecht an seinem
      -- Bezugsdatensatz, der Behandlungsgrundlage (PRX-010).
      when p_document_type = 'verordnungsscan'
        then app.can_write_treatment_bases()
      when app.patient_file_type_is_clinical(p_document_type)
        then app.can_write_clinical_patient_files()
      else app.can_write_organisational_patient_files()
    end,
    false
  )
  and (p_treatment_basis_id is null or app.can_write_treatment_bases())
$$;

COMMENT ON FUNCTION app.can_write_patient_file(p_document_type text, p_treatment_basis_id uuid) IS 'Schreibrecht an einer Datei nach ADR-017 Punkt 13: Dokumentart plus, bei einer Datei an der Behandlungsgrundlage, das Schreibrecht an Behandlungsgrundlagen. Der Verordnungsscan folgt allein dem Schreibrecht an Grundlagen (PRX-010, ANN-011).';

