CREATE FUNCTION app.cancel_aftercare(p_subscription_id uuid, p_via text, p_access_id uuid, p_access_kind text, p_representative text) RETURNS TABLE(ends_on date, cancelled_at timestamp with time zone, cancelled_on date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_abo   public.aftercare_subscriptions%rowtype;
  v_heute date;
  v_ende  date;
begin
  perform 1 from public.patients p
  join public.aftercare_subscriptions s on s.patient_id = p.id
  where s.id = p_subscription_id
  for update of p;

  select * into v_abo from public.aftercare_subscriptions s where s.id = p_subscription_id
  for update;
  if not found then
    raise exception 'aftercare subscription not found' using errcode = '42501';
  end if;
  if v_abo.ends_on is not null then
    raise exception 'aftercare subscription already cancelled' using errcode = '23514';
  end if;

  v_heute := app.training_today(v_abo.organization_id);
  v_ende := app.aftercare_cancellation_end(v_abo.starts_on, v_heute);

  update public.aftercare_subscriptions s
     set ends_on = v_ende,
         cancelled_at = now(),
         cancelled_by = auth.uid(),
         cancelled_on = v_heute,
         cancelled_via = p_via,
         cancelled_platform_access_id = p_access_id,
         cancelled_access_kind = p_access_kind,
         cancelled_representative_name = p_representative
   where s.id = p_subscription_id;

  return query select v_ende, now(), v_heute;
end;
$$;

CREATE FUNCTION app.cancellation_notice_period() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select interval '24 hours'
$$;

COMMENT ON FUNCTION app.cancellation_notice_period() IS 'Frist, unter der eine Patientenabsage eine Ausfallgebuehr ausloest (PROJECT_PRINCIPLES.md 8, ADR-018 Fassung 2 Punkt 8). Die eine Stelle, an der die 24 Stunden stehen.';

CREATE FUNCTION app.carry_over_time_account_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.staff_time_account_entries
    (organization_id, staff_member_id, kind, on_date, minutes, status, entered_by)
  values (old.organization_id, old.staff_member_id, 'carryover',
          make_date(extract(year from old.on_date)::integer, 12, 31), old.minutes, 'valid', null)
  on conflict (staff_member_id, on_date) where kind = 'carryover'
  do update set minutes = public.staff_time_account_entries.minutes + excluded.minutes;
  return old;
end;
$$;

