$$;

COMMENT ON FUNCTION app.chat_attachment_bucket() IS 'TEAM-003 (ADR-017 Punkt 73): Name des privaten Buckets der Anhänge im Teamchat - Klasse teamchat. Die einzige Stelle, an der er steht.';

CREATE FUNCTION app.check_working_plan_versions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.staff_working_hours h
    where h.staff_member_id = new.staff_member_id
      and h.id <> new.id
      and daterange(h.valid_from, h.valid_until, '[]') && daterange(new.valid_from, new.valid_until, '[]')
      and (h.valid_from is distinct from new.valid_from or h.valid_until is distinct from new.valid_until)
  ) then
    raise exception 'working plan versions overlap' using errcode = '23P01';
  end if;
  return null;
end;
$$;

CREATE FUNCTION app.checkin_keys_valid(p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(cardinality(p_keys), 0) > 0
     and (select count(distinct k) from unnest(p_keys) k) = cardinality(p_keys)
     and not exists (
       select 1 from unnest(p_keys) k
       where not exists (
         select 1 from app.tracking_parameters() t
         where t.parameter_key = k and t.cadence = 'checkin'
       )
     )
     and (
       select count(*) from unnest(p_keys) k
       join app.tracking_parameters() t on t.parameter_key = k and t.cadence = 'checkin'
       where t.role = 'question'
     ) between 1 and 5
$$;

COMMENT ON FUNCTION app.checkin_keys_valid(p_keys text[]) IS 'TRK-002, TRK-005: Fragen eines Check-ins - eine bis fuenf verschiedene Fragen des Takts checkin (ANN-349), dazu beliebig die Angaben zum Zusammenhang (ANN-355).';

CREATE TABLE public.checkin_schedules (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    interval_days smallint NOT NULL,
    parameter_keys text[] NOT NULL,
    starts_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT checkin_schedules_interval_days_check CHECK ((interval_days BETWEEN 1 AND 28)),
    CONSTRAINT checkin_schedules_parameter_keys_check CHECK (app.checkin_keys_valid(parameter_keys)),
    CONSTRAINT checkin_schedules_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT checkin_schedules_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND (patient_id = relationship_id)) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id = relationship_id))))
);

COMMENT ON TABLE public.checkin_schedules IS 'TRK-002: Takt und Fragen des Check-ins eines Verhaeltnisses (IDEA-TRK-004, ANN-349, ANN-350). Datenklasse des Verhaeltnisses; faellt mit ihm. Geschrieben nur ueber set_checkin_schedule und end_checkin_schedule. Kein Tabellenrecht (ADR-004).';

CREATE FUNCTION app.checkin_due_on(p_schedule public.checkin_schedules) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when l.zuletzt is null or l.zuletzt < p_schedule.starts_on then p_schedule.starts_on
    else l.zuletzt + p_schedule.interval_days
  end
  from (
    select max(c.answered_on) as zuletzt
    from public.checkins c
    where c.relationship_kind = p_schedule.relationship_kind
      and c.relationship_id = p_schedule.relationship_id
  ) l
$$;

COMMENT ON FUNCTION app.checkin_due_on(p_schedule public.checkin_schedules) IS 'TRK-002 (ANN-350): der Tag, ab dem der naechste Check-in faellig ist - der Tag der Einstellung, sonst interval_days nach dem letzten. Verpasstes wird nicht nachgeholt (IDEA-TRK-004).';

CREATE FUNCTION app.checkin_relationship(p_kind text, p_relationship_id uuid, p_organization_id uuid) RETURNS TABLE(area text, is_open boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'therapy', p.care_concluded_on is null
  from public.patients p
  where p_kind = 'treatment' and p.id = p_relationship_id and p.organization_id = p_organization_id
  union all
  select 'training', t.contract_ended_on is null
  from public.training_relationships t
  where p_kind = 'training' and t.id = p_relationship_id and t.organization_id = p_organization_id
$$;

CREATE FUNCTION app.checkin_sessions_json(p_kind text, p_relationship_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'performed_on', s.performed_on,
    'finished_at', s.finished_at,
    'plan_title', p.title,
    'recorded_by_kind', s.finished_access_kind,
    'values', (select jsonb_object_agg(v.parameter_key, v.value)
               from public.exercise_plan_session_values v where v.session_id = s.id)
  ) order by s.performed_on desc, s.finished_at desc), '[]'::jsonb)
  from public.exercise_plan_sessions s
  join public.exercise_plans p on p.id = s.plan_id
  where s.finished_at is not null
    and exists (select 1 from public.exercise_plan_session_values v where v.session_id = s.id)
    and (
      (p_kind = 'treatment' and p.service_area = 'therapy' and p.patient_id = p_relationship_id)
      or (p_kind = 'training' and p.service_area = 'training'
          and p.training_relationship_id = p_relationship_id)
    )
$$;

COMMENT ON FUNCTION app.checkin_sessions_json(p_kind text, p_relationship_id uuid) IS 'TRK-006: die beendeten Einheiten eines Verhaeltnisses mit ihren Angaben (Anstrengung, Schmerz, Bewegungssicherheit), Tag, Ende, Plan und wer beendet hat - unveraendert. Ohne Rechtepruefung: nur aus get_checkins.';

CREATE FUNCTION app.checkins_json(p_kind text, p_relationship_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'answered_on', c.answered_on,
    'recorded_at', c.recorded_at,
    'recorded_by_kind', c.platform_access_kind,
    'values', (select coalesce(jsonb_object_agg(v.parameter_key, v.value), '{}'::jsonb)
               from public.checkin_values v where v.checkin_id = c.id)
  ) order by c.answered_on desc, c.recorded_at desc), '[]'::jsonb)
  from public.checkins c
  where c.relationship_kind = p_kind and c.relationship_id = p_relationship_id
$$;

COMMENT ON FUNCTION app.checkins_json(p_kind text, p_relationship_id uuid) IS 'TRK-002: die Check-ins eines Verhaeltnisses - Tag, Zeitpunkt, wer erfasst hat (Person oder rechtliche Vertretung) und die Angaben unveraendert. Ohne Rechtepruefung: nur aus get_checkins und der Auskunft.';

CREATE FUNCTION app.clear_icd10_for_self_pay() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.treatment_basis_kind = 'self_pay' then
    new.diagnosis_icd10 := null;
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.close_waitlist_entry(p_org uuid, p_actor uuid, p_entry_id uuid, p_outcome text, p_appointment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eintrag public.waitlist_entries;
begin
  select * into v_eintrag
  from public.waitlist_entries w
  where w.id = p_entry_id and w.organization_id = p_org
  for update;
  if not found then
    raise exception 'waitlist entry not found' using errcode = 'P0002';
  end if;
  if v_eintrag.status <> 'open' then
    raise exception 'waitlist entry closed' using errcode = '22023';
  end if;

  if p_outcome = 'placed' then
    if p_appointment_id is null or not exists (
      select 1 from public.appointments a
      where a.id = p_appointment_id
        and a.organization_id = p_org
        and a.patient_id = v_eintrag.patient_id
        and a.kind = 'therapy'
        and a.status <> 'cancelled'
    ) then
      raise exception 'appointment not found' using errcode = 'P0002';
    end if;
  elsif p_outcome = 'withdrawn' then
    if p_appointment_id is not null then
      raise exception 'withdrawn entry takes no appointment' using errcode = '22023';
    end if;
  else
    raise exception 'invalid outcome' using errcode = '22023';
  end if;

  update public.waitlist_entries w
     set status                = p_outcome,
         placed_appointment_id = p_appointment_id,
         closed_at             = clock_timestamp(),
         closed_by             = p_actor,
         updated_at            = clock_timestamp(),
         updated_by            = p_actor
   where w.id = p_entry_id;

end;
$$;

CREATE FUNCTION app.closing_talk_due(p_appointment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select a.kind = 'therapy'
       and a.status not in ('cancelled', 'no_show')
       and b.appointment_count is not null
       and app.appointment_basis_position(a.id) >= b.appointment_count - 1
       and pa.care_concluded_on is null
       and not exists (
         select 1 from public.treatment_bases neu
         where neu.patient_id = b.patient_id
           and neu.organization_id = b.organization_id
           and (neu.issued_on, neu.created_at) > (b.issued_on, b.created_at)
       )
       and not exists (
         select 1 from public.training_offers o
         where o.patient_id = a.patient_id
           and o.organization_id = a.organization_id
           and o.withdrawn_at is null
           and o.created_at >= b.created_at
       )
    from public.appointments a
    join public.treatment_bases b on b.id = a.treatment_basis_id and b.organization_id = a.organization_id
    join public.patients pa on pa.id = a.patient_id and pa.organization_id = a.organization_id
    where a.id = p_appointment_id
  ), false)
$$;

COMMENT ON FUNCTION app.closing_talk_due(p_appointment_id uuid) IS 'KND-001 (ANN-286): Ist dieser Behandlungstermin einer der letzten zwei seiner Grundlage, bei offener Versorgung, ohne juengere Grundlage und ohne Trainingsangebot seit Beginn der Grundlage? Fragt nur die Akte, nie das Training (4.8).';

CREATE FUNCTION app.copy_visit_coordinate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lat       double precision;
  v_lon       double precision;
  v_precision text;
begin
  if tg_op = 'UPDATE'
     and app.patient_merge_active()
     and app.only_patient_id_changed(to_jsonb(new), to_jsonb(old)) then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.visit_street       is not distinct from old.visit_street
     and new.visit_house_number is not distinct from old.visit_house_number
     and new.visit_postal_code  is not distinct from old.visit_postal_code
     and new.visit_city         is not distinct from old.visit_city
     and new.patient_id         is not distinct from old.patient_id then
    return new;
  end if;

  new.visit_lat := null;
  new.visit_lon := null;
  new.visit_geocode_precision := null;

  if new.visit_street is null or new.patient_id is null then
    return new;
  end if;

  select c.lat, c.lon, c.geocode_precision
    into v_lat, v_lon, v_precision
  from public.patient_contact_details c
  where c.patient_id = new.patient_id
    and c.organization_id = new.organization_id
    and c.street       is not distinct from new.visit_street
    and c.house_number is not distinct from new.visit_house_number
    and c.postal_code  is not distinct from new.visit_postal_code
    and c.city         is not distinct from new.visit_city
    and c.lat is not null;

  if found then
    new.visit_lat := v_lat;
    new.visit_lon := v_lon;
    new.visit_geocode_precision := v_precision;
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.copy_visit_coordinate() IS 'MAP-006a, ANN-016: uebernimmt die Koordinate der Patientenadresse in den Hausbesuchs-Snapshot, wenn die Adressen uebereinstimmen.';

CREATE FUNCTION app.correction_draft_services(p_invoice_id uuid) RETURNS TABLE(billable_service_id uuid, sort_order smallint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select z.id, z.nummer
  from (
    select b.id,
           row_number() over (order by b.performed_on, c.code, b.id)::smallint as nummer
    from public.invoices v_alt
    join public.billable_services b     on b.organization_id = v_alt.organization_id
    join public.service_catalog_items c on c.id = b.catalog_item_id
    -- ANG-002: Ein Abo-Monat hat keinen Termin und damit keine Grundlage.
    left join public.appointments a     on a.id = b.appointment_id
    where v_alt.id = p_invoice_id
      and b.patient_id is not distinct from v_alt.patient_id
      and b.training_relationship_id is not distinct from v_alt.training_relationship_id
      and b.status = 'billable'
      and b.service_area = v_alt.service_area
      -- ABR-032: dieselbe Klammer wie die stornierte Rechnung - die Grundlage,
      -- ohne sie der Monat, und dann nur Leistungen ohne Grundlage (die
      -- gehoeren auf die Rechnung ihrer Verordnung).
      and (
        (v_alt.treatment_basis_id is not null and a.treatment_basis_id = v_alt.treatment_basis_id)
        or (v_alt.treatment_basis_id is null
            and a.treatment_basis_id is null
            and date_trunc('month', b.performed_on)::date = v_alt.period_month)
      )
      and not exists (
        select 1 from public.invoice_items it
        where it.billable_service_id = b.id and it.released_at is null
      )
      -- UX-008b: Leistungen, die eine andere offene Stornierung derselben
      -- Klammer haelt, gehoeren auf deren eigene Korrektur (ANN-321).
      and app.open_cancellation_holding_service(
            b.id, v_alt.patient_id, v_alt.training_relationship_id, v_alt.service_area,
            v_alt.treatment_basis_id, v_alt.period_month, p_invoice_id) is null
  ) z
$$;

COMMENT ON FUNCTION app.correction_draft_services(p_invoice_id uuid) IS 'BEF-143: die Leistungen, die die Korrektur dieser stornierten Rechnung aufnimmt, mit ihrer Reihenfolge (ANN-077, ABR-032, ANN-321). Die eine Stelle fuer create_correction_draft und correction_pending in get_invoice.';

CREATE FUNCTION app.count_staff_future_appointments(p_staff_member_id uuid, p_organization_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
