  from public.appointments a
  where a.staff_member_id = p_staff_member_id
    and a.organization_id = p_organization_id
    and a.status = 'confirmed'
    and a.ends_at > now()
$$;

COMMENT ON FUNCTION app.count_staff_future_appointments(p_staff_member_id uuid, p_organization_id uuid) IS 'Anzahl noch offener geplanter Termine einer Person. Nur fuer serverseitige Pfade (STAFF-001).';

