CREATE FUNCTION app.custom_food_input(p_food jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_name text := nullif(btrim(p_food ->> 'name'), '');
begin
  if jsonb_typeof(p_food) is distinct from 'object' or v_name is null then
    raise exception 'name is required' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_food) k
    where k not in ('name', 'brand', 'base_unit', 'energy_kcal', 'protein_g', 'fat_g',
                    'carbohydrate_g', 'sugar_g', 'fibre_g', 'saturated_fat_g', 'salt_g',
                    'portions')) then
    raise exception 'unknown field' using errcode = '22023';
  end if;
  if (p_food ->> 'energy_kcal') is null or (p_food ->> 'protein_g') is null
     or (p_food ->> 'fat_g') is null or (p_food ->> 'carbohydrate_g') is null then
    raise exception 'energy and macros are required' using errcode = '22023';
  end if;
  return p_food;
end;
$$;

CREATE FUNCTION app.food_portions_valid(p_portions jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select jsonb_typeof(p_portions) = 'array'
     and jsonb_array_length(p_portions) <= 12
     and not exists (
       select 1 from jsonb_array_elements(p_portions) e
       where jsonb_typeof(e) <> 'object'
          or jsonb_typeof(e -> 'label') is distinct from 'string'
          or length(btrim(e ->> 'label')) not between 1 and 60
          or jsonb_typeof(e -> 'amount') is distinct from 'number'
          or (e ->> 'amount')::numeric <= 0
          or (e ->> 'amount')::numeric > 5000
          or (select count(*) from jsonb_object_keys(e)) <> 2)
$$;

CREATE FUNCTION app.food_search_key(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select btrim(regexp_replace(regexp_replace(
    replace(lower(translate(coalesce(p_text, ''),
      'ÄÖÜäöüÀÁÂÃÅàáâãåÈÉÊËèéêëÌÍÎÏìíîïÒÓÔÕòóôõÙÚÛùúûÇçÑñ',
      'aouaouaaaaaaaaaaeeeeeeeeiiiiiiiioooooooouuuuuuccnn')), 'ß', 'ss'),
    '([aou])e', '\1', 'g'),
    '[^a-z0-9]+', ' ', 'g'))
$$;

COMMENT ON FUNCTION app.food_search_key(p_text text) IS 'ERN-004: die eine Normalisierung für Suchbegriff und Suchschlüssel - Kleinbuchstaben, Umlaute ohne Punkte und ae/oe/ue wie der Umlaut (Käse = Kaese = kase), ß als ss, Satzzeichen als Leerzeichen.';

CREATE TABLE public.custom_foods (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    owner_kind text NOT NULL,
    profile_id uuid,
    name text NOT NULL,
    brand text,
    base_unit text DEFAULT 'g'::text NOT NULL,
    energy_kcal numeric(5,1) NOT NULL,
    protein_g numeric(5,2) NOT NULL,
    fat_g numeric(5,2) NOT NULL,
    carbohydrate_g numeric(5,2) NOT NULL,
    sugar_g numeric(5,2),
    fibre_g numeric(5,2),
    saturated_fat_g numeric(5,2),
    salt_g numeric(6,3),
    portions jsonb DEFAULT '[]'::jsonb NOT NULL,
    name_key text GENERATED ALWAYS AS (app.food_search_key(name)) STORED,
    search_key text GENERATED ALWAYS AS (app.food_search_key((name || COALESCE((' '::text || brand), ''::text)))) STORED,
    platform_access_id uuid,
    platform_access_kind text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    archived_at timestamp with time zone,
    CONSTRAINT custom_foods_base_unit_check CHECK ((base_unit = ANY (ARRAY['g'::text, 'ml'::text]))),
    CONSTRAINT custom_foods_brand_check CHECK (((brand IS NULL) OR ((length(btrim(brand)) >= 1) AND (length(btrim(brand)) <= 80)))),
    CONSTRAINT custom_foods_carbohydrate_g_check CHECK ((carbohydrate_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT custom_foods_energy_kcal_check CHECK ((energy_kcal BETWEEN (0)::numeric AND (950)::numeric)),
    CONSTRAINT custom_foods_fat_g_check CHECK ((fat_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT custom_foods_fibre_g_check CHECK (((fibre_g IS NULL) OR (fibre_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT custom_foods_macros_fit CHECK ((((protein_g + fat_g) + carbohydrate_g) <= (105)::numeric)),
    CONSTRAINT custom_foods_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT custom_foods_owner_kind_check CHECK ((owner_kind = ANY (ARRAY['practice'::text, 'person'::text]))),
    CONSTRAINT custom_foods_owner_shape CHECK ((((owner_kind = 'practice'::text) AND (profile_id IS NULL) AND (platform_access_id IS NULL) AND (platform_access_kind IS NULL)) OR ((owner_kind = 'person'::text) AND (profile_id IS NOT NULL) AND (archived_at IS NULL) AND ((platform_access_id IS NULL) = (platform_access_kind IS NULL))))),
    CONSTRAINT custom_foods_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT custom_foods_portions_check CHECK (app.food_portions_valid(portions)),
    CONSTRAINT custom_foods_protein_g_check CHECK ((protein_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT custom_foods_salt_g_check CHECK (((salt_g IS NULL) OR (salt_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT custom_foods_saturated_fat_g_check CHECK (((saturated_fat_g IS NULL) OR (saturated_fat_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT custom_foods_sugar_g_check CHECK (((sugar_g IS NULL) OR (sugar_g BETWEEN (0)::numeric AND (100)::numeric)))
);

COMMENT ON TABLE public.custom_foods IS 'ERN-005 (ADR-027 Punkt 9): eigene Lebensmittel mit Nährwerten von der Verpackung - der Praxis (Inhalt, von der Beratung gepflegt, in jeder Suche der Organisation) oder einer Person an ihrem Ernährungsprofil (von ihr oder ihrer rechtlichen Vertretung, nur mit Einwilligung). Datenklassen: Betriebsdaten bzw. Ernährungsberatung (fällt mit dem Profil). Kein Tabellenrecht zum Schreiben; lesen nur mit der Fähigkeit.';

CREATE FUNCTION app.custom_food_json(p_food public.custom_foods) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'kind', p_food.owner_kind,
    'id', p_food.id,
    'source', p_food.owner_kind,
    'source_code', null,
    'name', p_food.name,
    'brand', p_food.brand,
    'base_unit', p_food.base_unit,
    'per_100', jsonb_build_object(
      'energy_kcal', p_food.energy_kcal, 'protein_g', p_food.protein_g, 'fat_g', p_food.fat_g,
      'carbohydrate_g', p_food.carbohydrate_g, 'sugar_g', p_food.sugar_g,
      'fibre_g', p_food.fibre_g, 'saturated_fat_g', p_food.saturated_fat_g,
      'salt_g', p_food.salt_g),
    'portions', p_food.portions,
    'updated_at', p_food.updated_at
  )
$$;

CREATE FUNCTION app.day_with_plan(p_org uuid, p_staff_member_id uuid, p_date date, p_on_date date, p_week jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tag jsonb := app.effective_day(p_org, p_staff_member_id, p_date);
begin
  if v_tag ->> 'kind' = 'plan' and p_date >= p_on_date then
    return coalesce(p_week -> extract(isodow from p_date)::text, '[]'::jsonb);
  end if;
  return coalesce(v_tag -> 'blocks', '[]'::jsonb);
end;
$$;

CREATE FUNCTION app.delete_due_fleet_records(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Schluessel: 30 Tage nach der Rueckgabe; offene nie.
  with faellig as (
    select k.id, k.organization_id,
           app.retention_due_at(
             (k.returned_at at time zone p_time_zone)::date,
             app.retention_interval('schluesselverlauf'),
             p_time_zone
           ) as due_at
    from public.fleet_key_handovers k
    where k.organization_id = p_org and k.returned_at is not null
  ),
  geloescht as (
    delete from public.fleet_key_handovers k
    using faellig f
    where k.id = f.id and f.due_at <= now()
    returning k.id, k.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'fleet_key_handovers', g.id, 'schluesselverlauf', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Sperren: drei Jahre ab Ende des Kalenderjahres der Freigabe; offene nie.
  with faellig as (
    select b.id, b.organization_id,
           app.retention_due_at(
             (date_trunc('year', b.released_at at time zone p_time_zone)
               + interval '1 year' - interval '1 day')::date,
             app.retention_interval('radflotte_ereignis'),
             p_time_zone
           ) as due_at
    from public.fleet_blocks b
    where b.organization_id = p_org and b.released_at is not null
  ),
  geloescht as (
    delete from public.fleet_blocks b
    using faellig f
    where b.id = f.id and f.due_at <= now()
    returning b.id, b.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'fleet_blocks', g.id, 'radflotte_ereignis', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Check-Ups: drei Jahre ab Ende des Kalenderjahres der Pruefung, nicht
  -- solange eine ihrer Stellen offen ist.
  with faellig as (
    select c.id, c.organization_id,
           app.retention_due_at(
             (date_trunc('year', c.checked_at at time zone p_time_zone)
               + interval '1 year' - interval '1 day')::date,
             app.retention_interval('radflotte_ereignis'),
             p_time_zone
           ) as due_at
    from public.fleet_checkups c
    where c.organization_id = p_org
      and not exists (
        select 1 from public.fleet_spots s where s.checkup_id = c.id and s.resolved_at is null
      )
  ),
  geloescht as (
    delete from public.fleet_checkups c
    using faellig f
    where c.id = f.id and f.due_at <= now()
    returning c.id, c.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'fleet_checkups', g.id, 'radflotte_ereignis', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Pannen: drei Jahre ab Ende des Kalenderjahres der Meldung, nicht solange
  -- eine Stelle oder eine Sperre aus ihr offen ist.
  with faellig as (
    select d.id, d.organization_id,
           app.retention_due_at(
             (date_trunc('year', d.reported_at at time zone p_time_zone)
               + interval '1 year' - interval '1 day')::date,
             app.retention_interval('radflotte_ereignis'),
             p_time_zone
           ) as due_at
    from public.fleet_breakdowns d
    where d.organization_id = p_org
      and not exists (
        select 1 from public.fleet_spots s where s.breakdown_id = d.id and s.resolved_at is null
      )
      and not exists (
        select 1 from public.fleet_blocks b where b.breakdown_id = d.id and b.released_at is null
      )
  ),
  geloescht as (
    delete from public.fleet_breakdowns d
    using faellig f
    where d.id = f.id and f.due_at <= now()
    returning d.id, d.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'fleet_breakdowns', g.id, 'radflotte_ereignis', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Ausgemusterte Raeder (ANN-557): Ist ihr Verlauf nach seinen Fristen
  -- gefallen, faellt auch das Rad - ausgemustert heisst nicht dauerhaft
  -- ausgeblendet (ADR-008 Punkt 10). Ein Rad in der Flotte bleibt, bis die
  -- Praxis es entfernt.
  with geloescht as (
    delete from public.fleet_bikes r
    where r.organization_id = p_org
      and r.archived_at is not null
      and not exists (select 1 from public.fleet_checkups c where c.bike_id = r.id)
      and not exists (select 1 from public.fleet_breakdowns d where d.bike_id = r.id)
      and not exists (select 1 from public.fleet_blocks b where b.bike_id = r.id)
      and not exists (select 1 from public.fleet_key_handovers k where k.bike_id = r.id)
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'fleet_bikes', g.id, 'betriebsdaten', now()
  from geloescht g;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_fleet_records(p_org uuid, p_time_zone text, p_run uuid) IS 'FLT-001 (ANN-551): Loeschlauf der Radflotte - Schluessel 30 Tage nach der Rueckgabe, Sperren, Check-Ups und Pannen drei Jahre ab Ende des Kalenderjahres; offene nie. Danach ausgemusterte Raeder ohne Verlauf (ANN-557). Schreibt das Loeschjournal. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_due_nutrition_profiles(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  with faellig as (
    select p.id, p.organization_id,
           app.retention_due_at(
             p.ended_on, app.retention_interval('ernaehrungsberatung'), p_time_zone
           ) as due_at
    from public.nutrition_profiles p
    where p.organization_id = p_org
      and p.ended_on is not null
      -- ANN-619: ein Legal Hold an der Akte hält auch die Beratung.
      and (p.patient_id is null or not app.under_legal_hold(p_org, 'patient', p.patient_id))
  ),
  geloescht as (
    delete from public.nutrition_profiles p
    using faellig f
    where p.id = f.id and f.due_at <= now()
    returning p.id, p.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'nutrition_profiles', g.id, 'ernaehrungsberatung', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_nutrition_profiles(p_org uuid, p_time_zone text, p_run uuid) IS 'ERN-001 (ADR-008 Fassung 6, ANN-619): löscht Ernährungsprofile drei Jahre nach ihrem Ende endgültig, mit Einwilligung und Gewicht und mit Eintrag im Löschjournal. Ein Legal Hold an der Akte hält. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_due_patient_photos(p_organization_id uuid, p_patient_id uuid, p_run_id uuid, p_actor uuid, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  -- Ein Befehl mit datenveraendernden Teilausdruecken: Auswahl, Sperre,
  -- Loeschen und Journal sehen dieselbe Menge. Der Trigger an
  -- patient_files schreibt je Zeile den Loeschauftrag fuer das Objekt.
  --
  -- Auch Zeilen im Zustand pending: Ein Widerruf trifft ein Foto, dessen
  -- Upload noch laeuft (Aufnahme = created_at). Ohne SKIP LOCKED: Ein Foto,
  -- das gerade bestaetigt wird, wird nicht uebergangen, sondern nach der
  -- Bestaetigung geloescht.
  with kandidaten as (
    select f.id,
           f.patient_id,
           f.photo_locked_at,
           app.patient_photo_due_at(f.patient_id, f.created_at, f.photo_locked_at) as due_at,
           app.under_legal_hold(p_organization_id, 'patient', f.patient_id) as gehalten
    from public.patient_files f
    where f.organization_id = p_organization_id
      and f.document_type = 'patientenfoto'
      and (p_patient_id is null or f.patient_id = p_patient_id)
    for update of f
  ),
  faellig as (
    select k.id, k.patient_id, k.photo_locked_at, k.due_at, k.gehalten
    from kandidaten k
    where k.due_at <= now()
  ),
  -- Einmal faellig bleibt faellig: Der Hold haelt die Loeschung an, nicht die
  -- Sperre.
  gesperrt as (
    update public.patient_files f
       set photo_locked_at = x.due_at
      from faellig x
     where f.id = x.id
       and x.gehalten
       and x.photo_locked_at is null
    returning f.id
  ),
  zu_loeschen as (
    select x.id, x.patient_id, x.due_at from faellig x where not x.gehalten
  ),
  geloescht as (
    delete from public.patient_files f
    using zu_loeschen x
    where f.id = x.id
    returning f.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_organization_id, p_run_id, 'patient_files', g.id, 'patientenfoto', x.due_at
  from geloescht g
  join zu_loeschen x on x.id = g.id;
  get diagnostics v_anzahl = row_count;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_patient_photos(p_organization_id uuid, p_patient_id uuid, p_run_id uuid, p_actor uuid, p_reason text) IS 'Loescht faellige Patientenfotos einer Organisation (optional einer Patient:in), auch laufende Uploads, mit Loeschjournal und - bei handelnder Person - Auditeintrag je Foto; unter Legal Hold haelt sie die Sperre in photo_locked_at fest (ADR-017 Punkt 36 und 38). Nur fuer record_patient_privacy_entry, release_legal_hold, reopen_patient_care und apply_retention.';

CREATE FUNCTION app.delete_due_platform_accesses(p_org uuid, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  with faellig as (
    select a.id, a.organization_id,
           app.platform_access_ended_at(a.id) + app.retention_interval('plattformzugang') as due_at,
           -- LOG-EPIC-001: Ein Zugang mit Zweifel-Vermerk (ADR-023 Punkt 13)
           -- bleibt so lange wie die Akte bzw. das Verhaeltnis; deren
           -- Loeschung setzt die Verweise auf null.
           a.companion_declined_at is null
             or (a.patient_id is null and a.training_relationship_id is null) as frei
    from public.platform_accesses a
    where a.organization_id = p_org
  ),
  geloescht as (
    delete from public.platform_accesses a
    using faellig f
    where a.id = f.id
      and f.due_at is not null
      and f.due_at <= now()
      and f.frei
      -- LOG-EPIC-001: Ein Legal Hold an der Akte haelt auch ihre Zugaenge.
      and not app.under_legal_hold(p_org, 'patient', a.patient_id)
    returning a.id, a.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'platform_accesses', g.id, 'plattformzugang', f.due_at
  from geloescht g
  join faellig f on f.id = g.id;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

CREATE FUNCTION app.delete_due_platform_accounts(p_org uuid, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_konto  record;
  v_anzahl integer := 0;
begin
  for v_konto in
    select a.account_user_id as id,
           max(app.platform_access_ended_at(a.id)) as ended_at
    from public.platform_accesses a
    where a.organization_id = p_org
      and a.account_user_id is not null
      and exists (select 1 from auth.users u where u.id = a.account_user_id)
      and not exists (select 1 from public.user_profiles up where up.id = a.account_user_id)
      -- Zweitreview B2: Ein Konto mit offenem Auftrag zaehlt nicht bei jedem
      -- Lauf neu.
      and not exists (
        select 1 from public.platform_account_deletions d where d.account_user_id = a.account_user_id
      )
    group by a.account_user_id
    -- Jeder Zugang des Kontos ist beendet, auch in anderen Organisationen.
    having bool_and(app.platform_access_ended_at(a.id) is not null)
       and not exists (
         select 1 from public.platform_accesses b
         where b.account_user_id = a.account_user_id
           and b.organization_id <> p_org
           and app.platform_access_ended_at(b.id) is null
       )
       and max(app.platform_access_ended_at(a.id)) + app.platform_read_period() <= now()
  loop
    -- Den Entzug zaehlt retention.applied (LOG-EPIC-001).
    update public.platform_accesses a
       set status = 'revoked',
           revoked_at = app.platform_access_ended_at(a.id),
           revoked_by = null,
           revoked_reason = 'account_deleted',
           locked_at = null,
           locked_by = null
     where a.account_user_id = v_konto.id and a.status <> 'revoked';

    -- ABN-011 (BEF-115): Geloescht wird ueber die Admin-API des
    -- Anmeldedienstes, nicht per SQL. Der Lauf gibt den Auftrag; der
    -- Zugangsdienst fuehrt ihn aus und bestaetigt, erst dann steht das Konto
    -- im Loeschjournal.
    perform app.order_platform_account_deletion(
      v_konto.id, p_org, p_run, v_konto.ended_at + app.platform_read_period(), 'retention');
    v_anzahl := v_anzahl + 1;
  end loop;

  -- Zweitreview: Ein Konto, das der Zugangsdienst angelegt hat und das nie
  -- gebunden wurde (Einloesen abgebrochen, Aufraeumen gescheitert), traegt
  -- die Marke `platform_account` in den Metadaten des Anmeldedienstes und
  -- faellt 30 Tage nach dem Anlegen. Praxiskonten tragen sie nie. Der Lauf
  -- einer Organisation raeumt nur, wenn er der erste ist: Das Konto gehoert
  -- keiner Organisation, jede Organisation saehe es gleich.
  if p_org = (select min(o.id::text)::uuid from public.organizations o) then
    for v_konto in
      select u.id, u.created_at
      from auth.users u
      where coalesce(u.raw_app_meta_data ->> 'platform_account', '') = 'true'
        and u.created_at + app.platform_read_period() <= now()
        and not exists (select 1 from public.user_profiles up where up.id = u.id)
        and not exists (select 1 from public.platform_accesses a where a.account_user_id = u.id)
        and not exists (select 1 from public.platform_account_deletions d where d.account_user_id = u.id)
    loop
      perform app.order_platform_account_deletion(
        v_konto.id, p_org, p_run, v_konto.created_at + app.platform_read_period(), 'unbound');
      v_anzahl := v_anzahl + 1;
    end loop;
  end if;
  return v_anzahl;
end;
$$;

CREATE FUNCTION app.delete_due_reimbursements(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Ausgezahlt: acht Jahre ab Ende des Jahres der Auszahlung (Par. 147 AO).
  -- Die Belege fallen mit (cascade), ihre Objekte über den Löschauftrag.
  with faellig as (
    select r.id, r.organization_id,
           app.retention_due_at(
             make_date(extract(year from (r.paid_at at time zone p_time_zone))::integer, 12, 31),
             app.retention_interval('erstattung'),
             p_time_zone
           ) as due_at
    from public.staff_reimbursements r
    where r.organization_id = p_org and r.status = 'paid'
      and not app.under_legal_hold(p_org, 'staff_member', r.staff_member_id)
  ),
  geloescht as (
    -- Erneut geprüft wie beim Zeitkonto: nur, was noch ausgezahlt ist.
    delete from public.staff_reimbursements r
    using faellig f
    where r.id = f.id and f.due_at <= now() and r.status = 'paid'
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_reimbursements', g.id, 'erstattung', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Abgelehnt und zurückgezogen: ein Jahr nach ihrem Ende.
  with faellig as (
    select r.id, r.organization_id,
           app.retention_due_at(
             (coalesce(r.decided_at, r.withdrawn_at) at time zone p_time_zone)::date,
             app.retention_interval('erstattung_kurz'),
             p_time_zone
           ) as due_at
    from public.staff_reimbursements r
    where r.organization_id = p_org and r.status in ('rejected', 'withdrawn')
      and not app.under_legal_hold(p_org, 'staff_member', r.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_reimbursements r
    using faellig f
    where r.id = f.id and f.due_at <= now() and r.status in ('rejected', 'withdrawn')
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_reimbursements', g.id, 'erstattung_kurz', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_reimbursements(p_org uuid, p_time_zone text, p_run uuid) IS 'ERS-001 (ANN-602): löscht ausgezahlte Erstattungen mit ihren Belegen acht Jahre ab Ende des Jahres der Auszahlung, abgelehnte und zurückgezogene ein Jahr nach ihrem Ende - mit Eintrag im Löschjournal. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_due_staff_feedback(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Rückmeldungen: zwölf Monate ab Ende des Monats der Abgabe, endgültig.
  with faellig as (
    select f.id, f.organization_id,
           app.retention_due_at(
             (f.month + interval '1 month' - interval '1 day')::date,
             app.retention_interval('rueckmeldung'),
             p_time_zone
           ) as due_at
    from public.staff_feedback f
    where f.organization_id = p_org
  ),
  geloescht as (
    delete from public.staff_feedback f
    using faellig x
    where f.id = x.id and x.due_at <= now()
    returning f.id, f.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_feedback', g.id, 'rueckmeldung', x.due_at
  from geloescht g join faellig x on x.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Teilnahme: fällt nach ihrem Monat. Ohne Journal - sonst stünde die Zahl
  -- der Teilnehmenden je Monat im Nachweis des Laufs; die Regel hängt am
  -- Monat allein und greift nach einem Restore im nächsten Lauf ebenso.
  delete from public.staff_feedback_participations p
  where p.organization_id = p_org
    and app.retention_due_at(
          (p.month + interval '1 month' - interval '1 day')::date,
          app.retention_interval('rueckmeldung_teilnahme'),
          p_time_zone
        ) <= now();
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Anonyme Antworten abgeschlossener Monate neu schreiben (Zweitreview,
  -- Befund 1): in zufälliger Reihenfolge, mit neuer Kennung, in dieser einen
  -- Transaktion. Danach teilen sie keine Transaktionsnummer (`xmin`) und keine
  -- Lage (`ctid`) mehr mit der Teilnahmemarke ihrer Abgabe und tragen keine
  -- Spur ihres Zeitpunkts. Bis dahin - im laufenden Monat - bliebe die
  -- Verknüpfung nur mit Zugriff an den Rechten der Anwendung vorbei möglich
  -- (ANN-607). Zählt nicht als Löschung.
  with alt as (
    delete from public.staff_feedback f
    where f.organization_id = p_org and f.staff_member_id is null
      and f.month < app.staff_feedback_month(p_org)
    returning f.organization_id, f.kind, f.month, f.mood, f.tours, f.team,
              f.easier_text, f.more_text, f.message_text
  )
  insert into public.staff_feedback
    (organization_id, kind, month, mood, tours, team, easier_text, more_text, message_text)
  select a.organization_id, a.kind, a.month, a.mood, a.tours, a.team,
         a.easier_text, a.more_text, a.message_text
  from alt a
  order by random();

  -- Blöcke, die ganz vor der Frist liegen, fallen mit (kein Personenbezug).
  delete from public.staff_feedback_blocks b
  where b.organization_id = p_org
    and app.retention_due_at(
          (b.to_month + interval '1 month' - interval '1 day')::date,
          app.retention_interval('rueckmeldung'),
          p_time_zone
        ) <= now();

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_staff_feedback(p_org uuid, p_time_zone text, p_run uuid) IS 'ORG-006 (ANN-607): löscht Rückmeldungen von Beschäftigten zwölf Monate ab Ende ihres Monats endgültig (mit Eintrag im Löschjournal) und Teilnahmemarken nach ihrem Monat (ohne Journal). Aufgerufen aus public.apply_retention(); ohne Eintrag in dessen Auditzusammenfassung.';

CREATE FUNCTION app.delete_due_staff_leave(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Genehmigt und storniert: drei Jahre ab Ende des Kalenderjahres, in dem
  -- der Urlaub endet. Ein Storno faellt mit seinem Urlaub (cascade).
  with faellig as (
    select r.id, r.organization_id,
           app.retention_due_at(
             make_date(extract(year from r.ends_on)::integer, 12, 31),
             app.retention_interval('urlaub'),
             p_time_zone
           ) as due_at
    from public.staff_leave_requests r
    where r.organization_id = p_org and r.kind = 'leave' and r.status in ('approved', 'cancelled')
      and not exists (
        select 1 from public.staff_leave_requests c
        where c.refers_to = r.id and c.status = 'requested'
      )
      and not app.under_legal_hold(p_org, 'staff_member', r.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_leave_requests r
    using faellig f
    where r.id = f.id and f.due_at <= now()
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_leave_requests', g.id, 'urlaub', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Abgelehnt und zurueckgezogen - auch ein abgelehnter oder
  -- zurueckgezogener Storno: ein Jahr nach ihrem Ende.
  with faellig as (
    select r.id, r.organization_id,
           app.retention_due_at(
             (coalesce(r.decided_at, r.withdrawn_at) at time zone p_time_zone)::date,
             app.retention_interval('urlaub_kurz'),
             p_time_zone
           ) as due_at
    from public.staff_leave_requests r
    where r.organization_id = p_org and r.status in ('rejected', 'withdrawn')
      and not app.under_legal_hold(p_org, 'staff_member', r.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_leave_requests r
    using faellig f
    where r.id = f.id and f.due_at <= now()
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_leave_requests', g.id, 'urlaub_kurz', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Ansprueche: drei Jahre ab Ende ihres Jahres.
  with faellig as (
    select e.id, e.organization_id,
           app.retention_due_at(
             make_date(e.year, 12, 31),
             app.retention_interval('urlaub'),
             p_time_zone
           ) as due_at
    from public.staff_leave_entitlements e
    where e.organization_id = p_org
      and not app.under_legal_hold(p_org, 'staff_member', e.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_leave_entitlements e
    using faellig f
    where e.id = f.id and f.due_at <= now()
    returning e.id, e.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_leave_entitlements', g.id, 'urlaub', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_staff_leave(p_org uuid, p_time_zone text, p_run uuid) IS 'URL-001 (ANN-579): loescht faellige Urlaubsantraege und -ansprueche mit Eintrag im Loeschjournal. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_due_team_messages(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Antworten: zwölf Monate ab ihrem Tag.
  with faellig as (
    select m.id,
           app.retention_due_at((m.created_at at time zone p_time_zone)::date,
                                app.retention_interval('teamchat'), p_time_zone) as due_at
    from public.team_messages m
    where m.organization_id = p_org and m.parent_id is not null
  ),
  geloescht as (
    delete from public.team_messages m
    using faellig x
    where m.id = x.id and x.due_at <= now()
    returning m.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_org, p_run, 'team_messages', g.id, 'teamchat', x.due_at
  from geloescht g join faellig x on x.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Ausgangsnachrichten erst sperren, dann prüfen (Zweitreview TEAM-001, N3).
  perform 1 from public.team_messages m
  where m.organization_id = p_org and m.parent_id is null
  for update;

  -- Ausgangsnachrichten, an denen keine Antwort mehr hängt (auch Anker).
  with faellig as (
    select m.id,
           app.retention_due_at((m.created_at at time zone p_time_zone)::date,
                                app.retention_interval('teamchat'), p_time_zone) as due_at
    from public.team_messages m
    where m.organization_id = p_org and m.parent_id is null
      and not exists (select 1 from public.team_messages r where r.parent_id = m.id)
  ),
  geloescht as (
    delete from public.team_messages m
    using faellig x
    where m.id = x.id and x.due_at <= now()
    returning m.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_org, p_run, 'team_messages', g.id, 'teamchat', x.due_at
  from geloescht g join faellig x on x.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Anker ohne Inhalt, an denen keine Antwort mehr hängt (ANN-610); nicht der
  -- Anker einer Entfernung durch owner - er ist der Nachweis (ADR-010 Punkt 15).
  with geloescht as (
    delete from public.team_messages m
    where m.organization_id = p_org and m.parent_id is null and m.removed_at is not null
      and m.removed_kind is distinct from 'owner'
      and not exists (select 1 from public.team_messages r where r.parent_id = m.id)
    returning m.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_org, p_run, 'team_messages', g.id, 'teamchat', now()
  from geloescht g;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Der eigene Stand Ausgeschiedener: Lesestand (ANN-609), Stand an Threads
  -- (ANN-640), „Für später“ (ANN-646) und Einstellungen (ANN-647). Er dient
  -- nur der Person selbst und fällt mit dem Ausscheiden. Ohne Journal - die
  -- Regel greift nach einem Restore im nächsten Lauf ebenso. Nachrichten und
  -- Reaktionen bleiben bis zu ihrer Frist; sie gehören dem Gespräch.
  delete from public.team_read_states rs
  using public.staff_members sm
  where rs.organization_id = p_org and sm.id = rs.staff_member_id
    and sm.employment_status <> 'active';
  delete from public.team_thread_states ts
  using public.staff_members sm
  where ts.organization_id = p_org and sm.id = ts.staff_member_id
    and sm.employment_status <> 'active';
  delete from public.team_saved_messages s
  using public.staff_members sm
  where s.organization_id = p_org and sm.id = s.staff_member_id
    and sm.employment_status <> 'active';
  delete from public.team_channel_settings cs
  using public.staff_members sm
  where cs.organization_id = p_org and sm.id = cs.staff_member_id
    and sm.employment_status <> 'active';
  -- Noch nicht Gesendetes erscheint nicht mehr, wenn die Verfasser:in nicht
  -- mehr teilnimmt (Ausscheiden, gesperrtes Konto, entzogene Rolle) oder das
  -- Gespräch nicht mehr liest (die Radflotte nach einem Rollenwechsel) -
  -- Zweitreview TEAM-002, Befund 1 beider Runden. Mit Journal unter diesem
  -- Lauf. Verlassen, Herausnehmen und Archivieren wirken sofort
  -- (`app.team_drop_scheduled`); was zwischen Sperre und Lauf fällig wird,
  -- erscheint (ANN-643).
  with geloescht as (
    delete from public.team_messages m
    where m.organization_id = p_org and m.created_at > now()
      and (m.author_staff_member_id is null
           or not app.teamchat_participant(p_org, m.author_staff_member_id)
           or not app.team_channel_readable(m.channel_id, p_org, m.author_staff_member_id)
           -- Archiviert: auch, was ein Rennen mit dem Archivieren überstand.
           or exists (select 1 from public.team_channels c
                      where c.id = m.channel_id and c.archived_at is not null))
    returning m.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_org, p_run, 'team_messages', g.id, 'teamchat', now()
  from geloescht g;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Fällige Ausgangsnachrichten mit laufenden Antworten werden Anker.
  perform app.strip_due_team_anchors(p_org, p_time_zone);

  -- Direkt- und Gruppennachrichten ohne jede Nachricht, zwölf Monate nach
  -- ihrem Beginn; private Kanäle ohne aktives Mitglied sofort - sie liest
  -- niemand mehr, auch owner nicht (Befund 3 des Zweitreviews).
  with faellig as (
    select c.id,
           case when c.kind = 'private' then now()
                else app.retention_due_at((c.created_at at time zone p_time_zone)::date,
                                          app.retention_interval('teamchat'), p_time_zone)
           end as due_at
    from public.team_channels c
    where c.organization_id = p_org
      and ((c.kind in ('direct', 'group')
            and not exists (select 1 from public.team_messages m where m.channel_id = c.id))
           or (c.kind = 'private'
               and not exists (select 1 from public.team_channel_members m
                               join public.staff_members sm on sm.id = m.staff_member_id
                               where m.channel_id = c.id and sm.employment_status = 'active')))
  ),
  geloescht as (
    delete from public.team_channels c
    using faellig x
    where c.id = x.id and x.due_at <= now()
    returning c.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_org, p_run, 'team_channels', g.id, 'teamchat', x.due_at
  from geloescht g join faellig x on x.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_team_messages(p_org uuid, p_time_zone text, p_run uuid) IS 'TEAM-001 (ANN-610): löscht Nachrichten des Teamchats zwölf Monate ab ihrem Tag endgültig (mit Eintrag im Löschjournal); fällige Ausgangsnachrichten mit laufenden Antworten bleiben ohne Inhalt als Anker; leere Direktnachrichten fallen zwölf Monate nach Beginn. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_due_time_account_entries(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Gültige: drei Jahre ab Ende des Jahres ihres Datums. Ihr Saldo bleibt als
  -- Übertrag des Jahres stehen (app.carry_over_time_account_entry); ihre
  -- Abweichung fällt mit (cascade). Überträge bleiben (ANN-030).
  with faellig as (
    select e.id, e.organization_id,
           app.retention_due_at(
             make_date(extract(year from e.on_date)::integer, 12, 31),
             app.retention_interval('zeitkonto'),
             p_time_zone
           ) as due_at
    from public.staff_time_account_entries e
    where e.organization_id = p_org and e.status = 'valid' and e.kind <> 'carryover'
      and not app.under_legal_hold(p_org, 'staff_member', e.staff_member_id)
  ),
  geloescht as (
    -- Erneut geprüft: Wird ein Eintrag während des Laufs zurückgewiesen
    -- oder zurückgenommen, fällt er hier nicht als gültiger (Zweitreview
    -- Runde 2).
    delete from public.staff_time_account_entries e
    using faellig f
    where e.id = f.id and f.due_at <= now() and e.status = 'valid'
    returning e.id, e.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_time_account_entries', g.id, 'zeitkonto', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Zurückgewiesen und zurückgenommen: ein Jahr nach ihrem Ende.
  with faellig as (
    select e.id, e.organization_id,
           app.retention_due_at(
             (coalesce(e.rejected_at, e.withdrawn_at) at time zone p_time_zone)::date,
             app.retention_interval('zeitkonto_kurz'),
             p_time_zone
           ) as due_at
    from public.staff_time_account_entries e
    where e.organization_id = p_org and e.status in ('rejected', 'withdrawn')
      and not app.under_legal_hold(p_org, 'staff_member', e.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_time_account_entries e
    using faellig f
    where e.id = f.id and f.due_at <= now()
    returning e.id, e.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_time_account_entries', g.id, 'zeitkonto_kurz', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_time_account_entries(p_org uuid, p_time_zone text, p_run uuid) IS 'ZK-001 (ANN-597): löscht gültige Einträge im Zeitkonto drei Jahre ab Ende ihres Jahres (ihr Saldo bleibt als Übertrag), zurückgewiesene und zurückgenommene ein Jahr nach ihrem Ende - mit Eintrag im Löschjournal. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_due_working_time_requests(p_org uuid, p_time_zone text, p_run uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer := 0;
  v_teil   integer;
begin
  -- Genehmigt: drei Jahre ab Ende des Kalenderjahres, in dem die Aenderung wirkt.
  with faellig as (
    select r.id, r.organization_id,
           app.retention_due_at(
             make_date(extract(year from r.on_date)::integer, 12, 31),
             app.retention_interval('arbeitszeit'),
             p_time_zone
           ) as due_at
    from public.staff_working_time_requests r
    where r.organization_id = p_org and r.status = 'approved'
      and not app.under_legal_hold(p_org, 'staff_member', r.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_working_time_requests r
    using faellig f
    where r.id = f.id and f.due_at <= now()
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_working_time_requests', g.id, 'arbeitszeit', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  -- Abgelehnt und zurueckgezogen: ein Jahr nach ihrem Ende.
  with faellig as (
    select r.id, r.organization_id,
           app.retention_due_at(
             (coalesce(r.decided_at, r.withdrawn_at) at time zone p_time_zone)::date,
             app.retention_interval('arbeitszeit_kurz'),
             p_time_zone
           ) as due_at
    from public.staff_working_time_requests r
    where r.organization_id = p_org and r.status in ('rejected', 'withdrawn')
      and not app.under_legal_hold(p_org, 'staff_member', r.staff_member_id)
  ),
  geloescht as (
    delete from public.staff_working_time_requests r
    using faellig f
    where r.id = f.id and f.due_at <= now()
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run, 'staff_working_time_requests', g.id, 'arbeitszeit_kurz', f.due_at
  from geloescht g join faellig f on f.id = g.id;
  get diagnostics v_teil = row_count;
  v_anzahl := v_anzahl + v_teil;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.delete_due_working_time_requests(p_org uuid, p_time_zone text, p_run uuid) IS 'AZ-001 (ANN-591): loescht faellige Antraege auf Aenderung der Arbeitszeit mit Eintrag im Loeschjournal. Aufgerufen aus public.apply_retention().';

CREATE FUNCTION app.delete_patient_record(p_patient_id uuid, p_run_id uuid, p_due_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_person uuid;
  v_count  integer := 0;
  v_n      integer;
begin
  select p.organization_id, p.person_id
    into v_org, v_person
  from public.patients p
  where p.id = p_patient_id;

  if not found then
    return 0;
  end if;

  -- Neu mit ABR-003d: Zahlungserinnerungen zuerst. Auch sie zeigen mit
  -- RESTRICT auf die Rechnung.
  with geloescht as (
    delete from public.invoice_payment_reminders r
     where r.invoice_id in (
       select i.id from public.invoices i where i.patient_id = p_patient_id
     )
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_payment_reminders', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Mit ABR-003c: Stornodokumente vor den Rechnungen. Sie zeigen mit RESTRICT auf
  -- die Rechnung; faellt eines still mit ihr, fehlt seine Zeile im Journal.
  with geloescht as (
    delete from public.invoice_cancellations c
     where c.invoice_id in (
       select i.id from public.invoices i where i.patient_id = p_patient_id
     )
    returning c.id, c.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_cancellations', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Mit ABR-004: Zahlungen vor den Rechnungen. Sie zeigen mit RESTRICT auf die
  -- Rechnung, und ihre steuerliche Frist ist dieselbe - der Lauf haette die
  -- Akte sonst zurueckgehalten (ADR-008 Punkt 2).
  with geloescht as (
    delete from public.payments z
     where z.invoice_id in (
       select i.id from public.invoices i where i.patient_id = p_patient_id
     )
    returning z.id, z.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'payments', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Rechnungszeilen: Sie zeigen mit RESTRICT auf die Leistung.
  with geloescht as (
    delete from public.invoice_items it
     where it.invoice_id in (
       select i.id from public.invoices i where i.patient_id = p_patient_id
     )
    returning it.id, it.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_items', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.invoices i
     where i.patient_id = p_patient_id
    returning i.id, i.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoices', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.invoice_recipients r
     where r.patient_id = p_patient_id
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_recipients', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Leistungen fallen vor Termin und Patientenzeile, weil sie mit RESTRICT
  -- auf beide zeigen, und ihre steuerliche Frist ist nie laenger als die zehn
  -- Jahre der Akte (ADR-008, ABR-002).
  with geloescht as (
    delete from public.billable_services b
     where b.patient_id = p_patient_id
    returning b.id, b.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'billable_services', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.treatment_notes t
     where t.appointment_id in (
       select a.id from public.appointments a where a.patient_id = p_patient_id
     )
    returning t.id, t.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'treatment_notes', g.id, 'patientenakte', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.treatment_bases pr
     where pr.patient_id = p_patient_id
    returning pr.id, pr.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'treatment_bases', g.id, 'patientenakte', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.appointments a
     where a.patient_id = p_patient_id
    returning a.id, a.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'appointments', g.id, 'patientenakte', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.legal_holds h
     where h.subject_type = 'patient'
       and h.subject_id = p_patient_id
    returning h.id, h.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'legal_holds', g.id, 'patientenakte', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.patients p
     where p.id = p_patient_id
    returning p.id, p.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'patients', g.id, 'patientenakte', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Die vierte Pruefung (LEI-001, ADR-021 Konsequenzen): Wer noch
  -- trainiert, behaelt seine Stammdaten. Ohne sie braeche der Lauf am
  -- Fremdschluessel ab - oder er naehme einer laufenden Trainingsbetreuung
  -- die Person unter den Fuessen weg. Das Ende des einen Verhaeltnisses
  -- beendet das andere nicht.
  with geloescht as (
    delete from public.persons pe
     where pe.id = v_person
       and not exists (select 1 from public.patients x      where x.person_id = pe.id)
       and not exists (select 1 from public.staff_members x where x.person_id = pe.id)
       and not exists (select 1 from public.user_profiles x where x.person_id = pe.id)
       and not exists (select 1 from public.training_relationships x where x.person_id = pe.id)
    returning pe.id, pe.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'persons', g.id, 'personenstammdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  return v_count;
end;
$$;

COMMENT ON FUNCTION app.delete_patient_record(p_patient_id uuid, p_run_id uuid, p_due_at timestamp with time zone) IS 'Loescht eine Patientenakte vollstaendig in Fremdschluesselreihenfolge und schreibt je eigenstaendig geloeschter Zeile eine Journalzeile (ADR-008, LOE-002a). Seit ABR-003d einschliesslich Zahlungserinnerungen, Stornodokumenten, Zahlungen, Rechnungen, ihrer Zeilen und der Empfaenger. Seit LEI-002 bleibt die Person stehen, solange ein Trainingsverhaeltnis auf sie zeigt (ADR-021). Prueft KEINEN Legal Hold und KEINE steuerliche Frist - das tut der Aufrufer.';

CREATE FUNCTION app.delete_training_relationship(p_relationship_id uuid, p_run_id uuid, p_due_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_person uuid;
  v_count  integer := 0;
  v_n      integer;
begin
  select t.person_id
    into v_person
  from public.training_relationships t
  where t.id = p_relationship_id;

  if not found then
    return 0;
  end if;

  -- TRN-008: die Belege zuerst. Sie zeigen mit RESTRICT auf Rechnung,
  -- Leistung und Termin; dieselbe Reihenfolge wie an der Akte
  -- (app.delete_patient_record), dieselbe Datenklasse.
  with geloescht as (
    delete from public.invoice_payment_reminders r
     where r.invoice_id in (
       select i.id from public.invoices i where i.training_relationship_id = p_relationship_id
     )
    returning r.id, r.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_payment_reminders', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.invoice_cancellations c
     where c.invoice_id in (
       select i.id from public.invoices i where i.training_relationship_id = p_relationship_id
     )
    returning c.id, c.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_cancellations', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.payments z
     where z.invoice_id in (
       select i.id from public.invoices i where i.training_relationship_id = p_relationship_id
     )
    returning z.id, z.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'payments', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.invoice_items it
     where it.invoice_id in (
       select i.id from public.invoices i where i.training_relationship_id = p_relationship_id
     )
    returning it.id, it.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoice_items', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.invoices i
     where i.training_relationship_id = p_relationship_id
    returning i.id, i.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'invoices', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.billable_services b
     where b.training_relationship_id = p_relationship_id
    returning b.id, b.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'billable_services', g.id, 'abrechnungsdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- TRN-009: die Protokolle vor ihren Terminen (FK restrict). Kein Beleg,
  -- dieselbe Datenklasse wie das Verhaeltnis (ADR-022 Punkt 7).
  with geloescht as (
    delete from public.training_protocols p
     where p.training_relationship_id = p_relationship_id
    returning p.id, p.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'training_protocols', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Die Termine des Verhaeltnisses. Sie tragen keinen Behandlungsnachweis und
  -- koennen keinen tragen (ADR-022 Punkt 6); `appointment_notifications`
  -- faellt per Kaskade mit.
  with geloescht as (
    delete from public.appointments a
     where a.training_relationship_id = p_relationship_id
    returning a.id, a.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'appointments', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.training_bases b
     where b.training_relationship_id = p_relationship_id
    returning b.id, b.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'training_bases', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  with geloescht as (
    delete from public.training_relationships t
     where t.id = p_relationship_id
    returning t.id, t.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'training_relationships', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Dieselben vier Verweise wie in der Akte, und aus demselben Grund: Die
  -- Person gehoert keinem der beiden Bereiche, sie wird von beiden benutzt.
  with geloescht as (
    delete from public.persons pe
     where pe.id = v_person
       and not exists (select 1 from public.patients x               where x.person_id = pe.id)
       and not exists (select 1 from public.staff_members x          where x.person_id = pe.id)
       and not exists (select 1 from public.user_profiles x          where x.person_id = pe.id)
       and not exists (select 1 from public.training_relationships x where x.person_id = pe.id)
    returning pe.id, pe.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'persons', g.id, 'personenstammdaten', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  return v_count;
end;
$$;

COMMENT ON FUNCTION app.delete_training_relationship(p_relationship_id uuid, p_run_id uuid, p_due_at timestamp with time zone) IS 'Loescht ein faelliges Trainingsverhaeltnis samt seinen Terminen und Klammern, Kinder vor Eltern (LEI-002, CAL-026). Die gemeinsame persons-Zeile faellt nur, wenn kein Verhaeltnis und kein Konto mehr auf sie zeigt (ADR-008 Punkt 9).';

CREATE FUNCTION app.deletion_key_column(p_table text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_table when 'training_contact_details' then 'training_relationship_id' else 'id' end
$$;

COMMENT ON FUNCTION app.deletion_key_column(p_table text) IS 'Die Schluesselspalte, unter der das Loeschjournal eine Zeile fuehrt: id, bei training_contact_details das Verhaeltnis (dort der Primaerschluessel).';

CREATE FUNCTION app.distribute_to_tax_groups(p_tax_groups jsonb, p_amount bigint) RETURNS TABLE(tax_treatment text, tax_rate_permille smallint, brutto bigint, steuer bigint)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with gruppe as (
    select x ->> 'tax_treatment'                 as tt,
           (x ->> 'tax_rate_permille')::smallint as satz,
           (x ->> 'gross_cents')::bigint         as gruppe_brutto,
           (x ->> 'tax_cents')::bigint           as gruppe_steuer,
           sum((x ->> 'gross_cents')::bigint) over () as summe_brutto
    from jsonb_array_elements(coalesce(p_tax_groups, '[]'::jsonb)) as x
  ),
  abgerundet as (
    select g.*,
           case when g.summe_brutto > 0
                then (abs(p_amount) * g.gruppe_brutto) / g.summe_brutto else 0 end as anteil,
           case when g.summe_brutto > 0
                then (abs(p_amount) * g.gruppe_brutto) % g.summe_brutto else 0 end as rest
    from gruppe g
  ),
  verteilt as (
    select a.*,
           row_number() over (order by a.rest desc, a.tt, a.satz) as platz,
           abs(p_amount) - sum(a.anteil) over () as offene_cent
    from abgerundet a
  ),
  roh as (
    select v.tt, v.satz, v.gruppe_steuer,
           sign(p_amount) * case
             when v.summe_brutto > 0 then v.anteil + case when v.platz <= v.offene_cent then 1 else 0 end
             when v.platz = 1 then abs(p_amount)
             else 0
           end as brutto
    from verteilt v
  )
  select r.tt,
         r.satz,
         r.brutto::bigint,
         case when r.gruppe_steuer = 0 then 0::bigint
              else round(r.brutto::numeric * r.satz / (1000 + r.satz))::bigint
         end
  from roh r
$$;

COMMENT ON FUNCTION app.distribute_to_tax_groups(p_tax_groups jsonb, p_amount bigint) IS 'Verteilt einen Betrag in Cent anteilig auf die Steuergruppen eines Rechnungssnapshots (ANN-088), mit Vorzeichen. Grundlage der kumulativen Verteilung in list_revenue_by_service_area (ABN-008, BEF-100).';

CREATE FUNCTION app.documentation_deadline(p_treated_at timestamp with time zone, p_created_at timestamp with time zone, p_time_zone text, p_days integer) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select greatest(
    (((p_treated_at at time zone p_time_zone)::date + (p_days + 1))::timestamp) at time zone p_time_zone,
    (((p_created_at at time zone p_time_zone)::date + (p_days + 1))::timestamp) at time zone p_time_zone
  )
$$;

COMMENT ON FUNCTION app.documentation_deadline(p_treated_at timestamp with time zone, p_created_at timestamp with time zone, p_time_zone text, p_days integer) IS 'Fristende der automatischen Finalisierung: Mitternacht der Praxiszeitzone nach dem N-ten Kalendertag nach Behandlungs- beziehungsweise Anlagetag, je nachdem, was spaeter liegt (DOK-004, ANN-008).';

CREATE FUNCTION app.documentation_photo_deletable(p_organization_id uuid, p_uploaded_by uuid, p_taken_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select (p_taken_at at time zone o.time_zone)::date = (now() at time zone o.time_zone)::date
    from public.organizations o
    where o.id = p_organization_id
  ), false)
  and (p_uploaded_by = auth.uid() or app.has_any_role('owner'))
$$;

COMMENT ON FUNCTION app.documentation_photo_deletable(p_organization_id uuid, p_uploaded_by uuid, p_taken_at timestamp with time zone) IS 'Darf die angemeldete Person dieses Dokumentationsfoto von Hand loeschen? Nur am Aufnahmetag in der Zeitzone der Praxis und nur als aufnehmende Person oder owner (ADR-017 Punkt 48).';

CREATE FUNCTION app.drop_coordinate_on_address_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.street       is distinct from old.street
     or new.house_number is distinct from old.house_number
     or new.postal_code  is distinct from old.postal_code
     or new.city         is distinct from old.city then
    new.lat := null;
    new.lon := null;
    new.geocode_precision := null;
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.drop_coordinate_on_address_change() IS 'MAP-006a, ANN-016: Eine Adressaenderung verwirft die Koordinate im selben Schreibvorgang.';

CREATE FUNCTION app.drop_draft_findings_on_finalisation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status <> 'draft' and new.addendum_to_note_id is null then
    delete from public.treatment_draft_findings f where f.appointment_id = new.appointment_id;
  end if;
  return null;
end;
$$;

CREATE FUNCTION app.drop_garage_coordinate_on_address_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.garage_street       is distinct from old.garage_street
     or new.garage_house_number is distinct from old.garage_house_number
     or new.garage_postal_code  is distinct from old.garage_postal_code
     or new.garage_city         is distinct from old.garage_city then
    new.garage_lat := null;
    new.garage_lon := null;
    new.garage_geocode_precision := null;
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.drop_garage_coordinate_on_address_change() IS 'UBK-015, ANN-016: Eine Aenderung der Garagenadresse verwirft ihre Koordinate im selben Schreibvorgang.';

CREATE FUNCTION app.drop_mailbox_confirmation_on_email_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.email is distinct from old.email then
    delete from public.platform_mailbox_confirmations c where c.account_user_id = new.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.drop_push_subscriptions_on_access_end() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'revoked' and old.status <> 'revoked' then
    delete from public.platform_push_subscriptions p where p.access_id = new.id;
    -- BEF-189
    delete from public.platform_notification_settings s where s.access_id = new.id;
    delete from public.nutrition_diary_reminders r where r.access_id = new.id;
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.drop_unchanged_treatment_basis_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.treatment_basis_versions v
  where v.id = new.id
    and v.content = app.treatment_basis_content(new.treatment_basis_id);
  return null;
end;
$$;

CREATE FUNCTION app.earliest_follow_up_start(p_previous_end timestamp with time zone, p_travel_seconds integer, p_grid_minutes integer, p_time_zone text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_ankunft  timestamp;
  v_tag      timestamp;
  v_sekunden numeric;
  v_raster   numeric;
begin
  if p_previous_end is null or p_travel_seconds is null or p_grid_minutes is null
     or p_time_zone is null then
    return null;
  end if;
  if p_travel_seconds < 0 or p_grid_minutes <= 0 then
    raise exception 'travel time and grid must not be negative' using errcode = '22023';
  end if;

  v_ankunft  := (p_previous_end + make_interval(secs => p_travel_seconds)) at time zone p_time_zone;
  v_tag      := date_trunc('day', v_ankunft);
  v_sekunden := extract(epoch from (v_ankunft - v_tag));
  v_raster   := p_grid_minutes * 60;

  -- Aufrunden auf den ersten Rasterpunkt auf oder nach der Ankunft (§8.1).
  return (v_tag + make_interval(secs => ceil(v_sekunden / v_raster) * v_raster)) at time zone p_time_zone;
end;
$$;

COMMENT ON FUNCTION app.earliest_follow_up_start(p_previous_end timestamp with time zone, p_travel_seconds integer, p_grid_minutes integer, p_time_zone text) IS 'PROJECT_PRINCIPLES.md 8.1: fruehester Beginn des Folgetermins - erster Rasterpunkt auf oder nach Ende plus Fahrzeit, in Ortszeit der Praxis, aufgerundet. Einzige Stelle der Rundungsregel (ANN-097).';

CREATE FUNCTION app.easter_sunday(p_year integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  a integer := p_year % 19;
  b integer := p_year / 100;
  c integer := p_year % 100;
  d integer := b / 4;
  e integer := b % 4;
  f integer := (b + 8) / 25;
  g integer := (b - f + 1) / 3;
  h integer := (19 * a + b - d - g + 15) % 30;
  i integer := c / 4;
  k integer := c % 4;
  l integer := (32 + 2 * e + 2 * i - h - k) % 7;
  m integer := (a + 11 * h + 22 * l) / 451;
begin
  return make_date(p_year, (h + l - 7 * m + 114) / 31, ((h + l - 7 * m + 114) % 31) + 1);
end;
$$;

COMMENT ON FUNCTION app.easter_sunday(p_year integer) IS 'URL-001 (ANN-577): Ostersonntag eines Jahres (gregorianisch). Dieselbe Rechnung wie src/features/vacation/feiertage.ts.';

CREATE FUNCTION app.effective_day(p_org uuid, p_staff_member_id uuid, p_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_abweichungen integer;
  v_abwesend     boolean;
begin
  if exists (
    select 1 from public.staff_leave_requests r
    where r.organization_id = p_org and r.staff_member_id = p_staff_member_id
      and r.kind = 'leave' and r.status = 'approved'
      and p_date between r.starts_on and r.ends_on
  ) then
    return jsonb_build_object('kind', 'leave', 'blocks', '[]'::jsonb);
  end if;

  select count(*), bool_or(a.kind = 'unavailable')
    into v_abweichungen, v_abwesend
  from public.staff_working_hour_exceptions a
  where a.organization_id = p_org and a.staff_member_id = p_staff_member_id
    and a.on_date = p_date;

  if v_abweichungen > 0 then
    if v_abwesend then
      return jsonb_build_object('kind', 'unavailable', 'blocks', '[]'::jsonb);
    end if;
    return jsonb_build_object('kind', 'exception', 'blocks', (
      select jsonb_agg(jsonb_build_object('von', to_char(a.starts_at, 'HH24:MI'),
                                          'bis', to_char(a.ends_at, 'HH24:MI'))
                       order by a.starts_at)
      from public.staff_working_hour_exceptions a
      where a.organization_id = p_org and a.staff_member_id = p_staff_member_id
        and a.on_date = p_date and a.kind = 'block'
    ));
  end if;

  return jsonb_build_object(
    'kind', 'plan',
    'blocks', app.plan_week(p_org, p_staff_member_id, p_date) -> extract(isodow from p_date)::text
  );
end;
$$;

CREATE FUNCTION app.electricity_amount_cents(p_minutes integer, p_km_per_hour integer, p_wh_per_km integer, p_cents_per_kwh integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select ((p_minutes::bigint * p_km_per_hour * p_wh_per_km * p_cents_per_kwh + 30000) / 60000)::integer
$$;

COMMENT ON FUNCTION app.electricity_amount_cents(p_minutes integer, p_km_per_hour integer, p_wh_per_km integer, p_cents_per_kwh integer) IS 'ORG-008 (ANN-605): Betrag des Ladestroms in Cent aus geplanten Minuten, Strecke je Stunde, Verbrauch und Strompreis, kaufmännisch gerundet. Die einzige Stelle am Server.';

CREATE FUNCTION app.electricity_offer(p_org uuid, p_staff_member_id uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_minuten integer := app.reimbursement_working_minutes(p_org, p_staff_member_id, p_month);
  v_o       record;
begin
  select o.electricity_km_per_hour as kmh, o.electricity_wh_per_km as whkm,
         o.electricity_cents_per_kwh as ct
    into v_o
  from public.organizations o where o.id = p_org;
  return jsonb_build_object(
    'month', p_month,
    'working_minutes', v_minuten,
    'km_per_hour', v_o.kmh,
    'wh_per_km', v_o.whkm,
    'cents_per_kwh', v_o.ct,
    'amount_cents', app.electricity_amount_cents(v_minuten, v_o.kmh, v_o.whkm, v_o.ct),
    'already_requested', exists (
      select 1 from public.staff_reimbursements r
      where r.staff_member_id = p_staff_member_id and r.kind = 'electricity'
        and r.period_month = p_month and r.status in ('requested', 'approved', 'paid')
    )
  );
end;
$$;

-- ANN-617
CREATE FUNCTION app.electricity_tour_days(p_org uuid, p_staff_member_id uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tz     text;
  v_ort    jsonb;
  v_tage   jsonb := '[]'::jsonb;
  v_punkte jsonb := null;
  v_tag    date := null;
  v_punkt  jsonb;
  r        record;
begin
  select o.time_zone into v_tz from public.organizations o where o.id = p_org;
  if v_tz is null then
    return '[]'::jsonb;
  end if;

  -- Wie tagesorte() im Browser: der erste Standort nach Namen, seine Garage,
  -- sonst sein Startort; ohne beides beginnt die Tour am ersten Termin.
  select case
           when l.garage_lat is not null then jsonb_build_object('lat', l.garage_lat, 'lon', l.garage_lon)
           when l.lat is not null then jsonb_build_object('lat', l.lat, 'lon', l.lon)
         end
    into v_ort
  from public.locations l
  where l.organization_id = p_org
  order by l.name, l.id
  limit 1;

  for r in
    select (a.starts_at at time zone v_tz)::date as tag,
           case when a.appointment_type = 'home_visit' then a.visit_lat else l.lat end as lat,
           case when a.appointment_type = 'home_visit' then a.visit_lon else l.lon end as lon
    from public.appointments a
    left join public.locations l on l.id = a.location_id and l.organization_id = p_org
    where a.organization_id = p_org
      and a.staff_member_id = p_staff_member_id
      and a.kind in ('therapy', 'training')
      and a.appointment_type in ('home_visit', 'practice')
      and a.status <> 'cancelled'
      and a.starts_at >= (p_month::timestamp) at time zone v_tz
      and a.starts_at <  ((p_month + interval '1 month')::timestamp) at time zone v_tz
    order by a.starts_at, a.id
  loop
    continue when r.lat is null or r.lon is null;
    v_punkt := jsonb_build_object('lat', r.lat, 'lon', r.lon);
    if v_tag is distinct from r.tag then
      -- Der vorige Tag endet am Ort, an dem er begann.
      if v_punkte is not null then
        if v_ort is not null and v_punkte -> -1 <> v_ort then
          v_punkte := v_punkte || jsonb_build_array(v_ort);
        end if;
        if jsonb_array_length(v_punkte) >= 2 then
          v_tage := v_tage || jsonb_build_array(v_punkte);
        end if;
      end if;
      v_tag := r.tag;
      v_punkte := case when v_ort is null then '[]'::jsonb else jsonb_build_array(v_ort) end;
    end if;
    if jsonb_array_length(v_punkte) = 0 or v_punkte -> -1 <> v_punkt then
      v_punkte := v_punkte || jsonb_build_array(v_punkt);
    end if;
  end loop;

  if v_punkte is not null then
    if v_ort is not null and v_punkte -> -1 <> v_ort then
      v_punkte := v_punkte || jsonb_build_array(v_ort);
    end if;
    if jsonb_array_length(v_punkte) >= 2 then
      v_tage := v_tage || jsonb_build_array(v_punkte);
    end if;
  end if;

  return v_tage;
end;
$$;

COMMENT ON FUNCTION app.electricity_tour_days(p_org uuid, p_staff_member_id uuid, p_month date) IS 'BEF-181 (ADR-019 Fassung 6): je Tag mit Fahrt die Koordinaten der geplanten Tour einer Person in einem Monat (Garage oder Startort, Termine mit Ort, zurück) - ohne Datum, Zeit, Kennung oder Namen. Die einzige Stelle, die festlegt, was gefahren wird.';

-- ANN-154
CREATE FUNCTION app.ending_treatment_bases(p_organization_id uuid) RETURNS TABLE(treatment_basis_id uuid, patient_id uuid, prescriber_id uuid, treatment_basis_kind text, issued_on date, follow_up_recommendation text, prescribed integer, used integer, planned integer, last_appointment_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with kandidaten as (
    select tb.id, tb.patient_id, tb.prescriber_id, tb.treatment_basis_kind, tb.issued_on,
           tb.follow_up_recommendation,
           z.prescribed, z.used, z.planned,
           (select max(a.starts_at)
              from public.appointments a
             where a.treatment_basis_id = tb.id
               and a.organization_id = p_organization_id
               and a.status not in ('cancelled', 'no_show')) as letzter
    from public.treatment_bases tb
    join public.patients pa on pa.id = tb.patient_id
    cross join lateral app.treatment_basis_slot_counts(tb.id, p_organization_id) z
    where tb.organization_id = p_organization_id
      and tb.treatment_basis_kind <> 'self_pay'
      and pa.status = 'active'
      and pa.care_concluded_on is null
      -- Ohne Anschluss: keine juengere Grundlage derselben Person.
      and not exists (
        select 1 from public.treatment_bases neu
        where neu.patient_id = tb.patient_id
          and neu.organization_id = p_organization_id
          and (neu.issued_on, neu.created_at) > (tb.issued_on, tb.created_at)
      )
  )
  select k.id, k.patient_id, k.prescriber_id, k.treatment_basis_kind, k.issued_on,
         k.follow_up_recommendation, k.prescribed, k.used, k.planned, k.letzter
  from kandidaten k
  where k.prescribed is not null
    and (
      k.used >= k.prescribed
      or (
        greatest(k.used, k.planned) >= k.prescribed
        and k.letzter is not null
        and k.letzter <= now() + app.reminder_prescription_horizon()
      )
    )
$$;

COMMENT ON FUNCTION app.ending_treatment_bases(p_organization_id uuid) IS 'Verordnungen ohne Anschluss, deren Kontingent genutzt oder ganz verplant ist und deren letzter Termin in den naechsten vierzehn Tagen liegt (PRX-016, ANN-146). Einzige Stelle der Regel; list_ending_prescriptions und get_practice_statistics lesen daraus (STA-001). Ohne Rollenpruefung: nur aus Funktionen mit eigener Pruefung aufrufen.';

CREATE FUNCTION app.enqueue_notification(p_org uuid, p_rel_kind text, p_rel_id uuid, p_kind text, p_subject_id uuid, p_subject_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tz     text;
  v_anzahl integer;
begin
  if p_rel_id is null or not (p_kind = any (app.notification_kinds())) then
    return 0;
  end if;
  if exists (
    select 1 from public.notification_kind_switches k
    where k.organization_id = p_org and k.kind = p_kind
  ) then
    return 0;
  end if;
  select o.time_zone into v_tz from public.organizations o where o.id = p_org;

  insert into public.notification_deliveries
    (organization_id, access_id, kind, channel, subject_id, subject_at, due_at)
  select p_org, a.id, p_kind, w.channel, p_subject_id, p_subject_at, z.due_at
  from public.platform_accesses a
  join public.platform_notification_settings s on s.access_id = a.id
  cross join (values ('email'), ('push')) w(channel)
  cross join lateral (
    select app.notification_due_at(
      now(), v_tz,
      coalesce(s.quiet_from, app.notification_rule('quiet_from')::smallint),
      coalesce(s.quiet_until, app.notification_rule('quiet_until')::smallint)
    ) as due_at
  ) z
  where a.organization_id = p_org
    and a.relationship_kind = p_rel_kind
    and a.relationship_id = p_rel_id
    and app.notification_access_live(a.id)
    and (
      (w.channel = 'email' and p_kind = any (s.email_kinds))
      or (w.channel = 'push' and p_kind = any (s.push_kinds)
          and exists (select 1 from public.platform_push_subscriptions p where p.access_id = a.id))
    )
    and not (
      p_kind in ('appointment_reminder', 'appointment_changed')
      and p_subject_at is not null and p_subject_at <= z.due_at
    )
  on conflict (access_id, kind, channel, subject_id, subject_at)
    where kind = 'appointment_reminder' do nothing;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

