CREATE FUNCTION app.exercise_catalog_entry(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_labels      jsonb := app.exercise_equipment_labels();
  v_schluessel  text;
  v_version     text;
  v_name        text;
  v_laie        text;
  v_region      text;
  v_ziel        text;
  v_stellung    text;
  v_niveau      integer;
  v_hilfsmittel text[] := '{}';
  v_ausruestung text[] := '{}';
  v_eintrag     jsonb;
  v_liste       text;
  v_d           jsonb;
  v_reps        jsonb;
  v_min         integer;
  v_max         integer;
  v_dosis       jsonb;
  v_bild        jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'catalog entry is invalid' using errcode = '22023';
  end if;
  v_schluessel := app.exercise_json_text(p -> 'schluessel');
  if v_schluessel is null or v_schluessel !~ '^[A-Z]{2}-[0-9]{2}$' then
    raise exception 'catalog key is invalid' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p) k
    where k not in ('schluessel', 'version', 'name', 'alltagsname', 'region', 'ziel',
                    'ausgangsstellung', 'hilfsmittel', 'hilfsmittel_optional', 'niveau',
                    'dosierung', 'anleitung', 'fehler', 'hinweise_praxis', 'bild')
  ) then
    raise exception 'catalog entry %: unknown field', v_schluessel using errcode = '22023';
  end if;

  v_version := app.exercise_json_text(p -> 'version');
  if v_version is null or v_version !~ '^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$' then
    raise exception 'catalog entry %: version is invalid', v_schluessel using errcode = '22023';
  end if;
  v_name := app.exercise_required_name(app.exercise_json_text(p -> 'name'), 'name');
  v_laie := app.exercise_required_name(app.exercise_json_text(p -> 'alltagsname'), 'lay name');

  v_region := app.exercise_json_text(p -> 'region');
  if v_region is null or not (v_region = any (app.exercise_body_regions())) then
    raise exception 'catalog entry %: body region is invalid', v_schluessel using errcode = '22023';
  end if;
  v_ziel := app.exercise_json_text(p -> 'ziel');
  if v_ziel is null or not (v_ziel = any (app.exercise_goals())) then
    raise exception 'catalog entry %: goal is invalid', v_schluessel using errcode = '22023';
  end if;
  v_stellung := app.exercise_json_text(p -> 'ausgangsstellung');
  if v_stellung is null or not (v_stellung = any (app.exercise_starting_positions())) then
    raise exception 'catalog entry %: starting position is invalid', v_schluessel using errcode = '22023';
  end if;
  v_niveau := app.exercise_json_int(p -> 'niveau');
  if v_niveau is null or v_niveau not between 1 and 3 then
    raise exception 'catalog entry %: level is invalid', v_schluessel using errcode = '22023';
  end if;

  -- Hilfsmittel aus der festen Liste, keines doppelt, zusammen hoechstens acht.
  foreach v_liste in array array['hilfsmittel', 'hilfsmittel_optional'] loop
    if p ? v_liste and jsonb_typeof(p -> v_liste) <> 'array' then
      raise exception 'catalog entry %: equipment is invalid', v_schluessel using errcode = '22023';
    end if;
    for v_eintrag in select value from jsonb_array_elements(coalesce(p -> v_liste, '[]'::jsonb)) loop
      if app.exercise_json_text(v_eintrag) is null
         or not (v_labels ? (v_eintrag #>> '{}'))
         or (v_eintrag #>> '{}') = any (v_hilfsmittel) then
        raise exception 'catalog entry %: equipment is invalid', v_schluessel using errcode = '22023';
      end if;
      v_hilfsmittel := v_hilfsmittel || (v_eintrag #>> '{}');
      v_ausruestung := v_ausruestung || (
        (v_labels ->> (v_eintrag #>> '{}'))
        || case when v_liste = 'hilfsmittel_optional' then ' (nach Bedarf)' else '' end
      );
    end loop;
  end loop;
  if cardinality(v_ausruestung) > 8 then
    raise exception 'catalog entry %: too many equipment tags', v_schluessel using errcode = '22023';
  end if;

  -- Standarddosierung (ANN-384), in die Form der Planposition gebracht.
  v_d := p -> 'dosierung';
  if v_d is null or jsonb_typeof(v_d) <> 'object' or exists (
    select 1 from jsonb_object_keys(v_d) k
    where k not in ('saetze', 'wiederholungen', 'halten_s', 'dauer_s', 'je_seite', 'taeglich')
  ) then
    raise exception 'catalog entry %: dosage is invalid', v_schluessel using errcode = '22023';
  end if;
  v_reps := v_d -> 'wiederholungen';
  if v_reps is null then
    v_min := null;
    v_max := null;
  elsif jsonb_typeof(v_reps) = 'array' and jsonb_array_length(v_reps) = 2 then
    v_min := app.exercise_json_int(v_reps -> 0);
    v_max := app.exercise_json_int(v_reps -> 1);
    if v_min is null or v_max is null or v_max <= v_min then
      raise exception 'catalog entry %: dosage is invalid', v_schluessel using errcode = '22023';
    end if;
  else
    v_min := app.exercise_json_int(v_reps);
    v_max := v_min;
    if v_min is null then
      raise exception 'catalog entry %: dosage is invalid', v_schluessel using errcode = '22023';
    end if;
  end if;
  if (v_d ? 'saetze' and app.exercise_json_int(v_d -> 'saetze') is null)
     or (v_d ? 'halten_s' and app.exercise_json_int(v_d -> 'halten_s') is null)
     or (v_d ? 'dauer_s' and app.exercise_json_int(v_d -> 'dauer_s') is null)
     or (v_d ? 'taeglich' and app.exercise_json_int(v_d -> 'taeglich') is null)
     or (v_d ? 'je_seite' and jsonb_typeof(v_d -> 'je_seite') <> 'boolean') then
    raise exception 'catalog entry %: dosage is invalid', v_schluessel using errcode = '22023';
  end if;
  v_dosis := jsonb_strip_nulls(jsonb_build_object(
    'sets', coalesce(app.exercise_json_int(v_d -> 'saetze'), 1),
    'reps_min', v_min,
    'reps_max', v_max,
    'duration_seconds', app.exercise_json_int(v_d -> 'dauer_s'),
    'hold_seconds', app.exercise_json_int(v_d -> 'halten_s'),
    'per_side', coalesce((v_d ->> 'je_seite')::boolean, false),
    'times_per_day', app.exercise_json_int(v_d -> 'taeglich')
  ));
  if not app.exercise_dosage_valid(v_dosis) then
    raise exception 'catalog entry %: dosage is invalid', v_schluessel using errcode = '22023';
  end if;

  -- Das Bild (ANN-381): optional; wenn, dann gueltig und klein.
  v_bild := p -> 'bild';
  if v_bild is not null and jsonb_typeof(v_bild) = 'null' then
    v_bild := null;
  end if;
  if not app.exercise_illustration_valid(v_bild) then
    raise exception 'catalog entry %: illustration is invalid', v_schluessel using errcode = '22023';
  end if;
  if p ? 'hinweise_praxis' and app.exercise_json_text(p -> 'hinweise_praxis') is null then
    raise exception 'catalog entry %: practice notes are invalid', v_schluessel using errcode = '22023';
  end if;

  return jsonb_build_object(
    'catalog_key', v_schluessel,
    'catalog_version', v_version,
    'name', v_name,
    'lay_name', v_laie,
    'body_region', v_region,
    'goal', v_ziel,
    'starting_position', v_stellung,
    'level', v_niveau,
    'equipment', to_jsonb(v_ausruestung),
    'instruction', app.exercise_optional_text(
                     app.exercise_catalog_lines(p -> 'anleitung', 1, 'instruction', v_schluessel),
                     'instruction'),
    'common_faults', app.exercise_optional_text(
                       app.exercise_catalog_lines(p -> 'fehler', 0, 'common faults', v_schluessel),
                       'common faults'),
    'practice_notes', app.exercise_optional_text(
                        app.exercise_json_text(p -> 'hinweise_praxis'), 'practice notes'),
    'default_dosage', v_dosis,
    'illustration', v_bild
  );
end;
$_$;

COMMENT ON FUNCTION app.exercise_catalog_entry(p jsonb) IS 'UEB-012 (ANN-382): prueft einen Katalogeintrag vollstaendig (Werte, Laengen, Groessen) und liefert ihn in der Form der Bibliothek. Wirft 22023 mit Schluessel und Grund.';

CREATE FUNCTION app.exercise_catalog_lines(p jsonb, p_min integer, p_feld text, p_schluessel text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_zeilen text[] := '{}';
  v_zeile  jsonb;
  v_text   text;
begin
  if p is null or jsonb_typeof(p) = 'null' then
    p := '[]'::jsonb;
  end if;
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) < p_min or jsonb_array_length(p) > 8 then
    raise exception 'catalog entry %: % is invalid', p_schluessel, p_feld using errcode = '22023';
  end if;
  for v_zeile in select value from jsonb_array_elements(p) loop
    v_text := btrim(coalesce(app.exercise_json_text(v_zeile), ''), E' \t\r\n');
    if v_text = '' or length(v_text) > 240 then
      raise exception 'catalog entry %: % is invalid', p_schluessel, p_feld using errcode = '22023';
    end if;
    v_zeilen := v_zeilen || v_text;
  end loop;
  return nullif(array_to_string(v_zeilen, E'\n'), '');
end;
$$;

CREATE FUNCTION app.exercise_dosage_valid(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_sets integer := app.exercise_json_int(p -> 'sets');
  v_min  integer := app.exercise_json_int(p -> 'reps_min');
  v_max  integer := app.exercise_json_int(p -> 'reps_max');
  v_dur  integer := app.exercise_json_int(p -> 'duration_seconds');
  v_hold integer := app.exercise_json_int(p -> 'hold_seconds');
  v_tag  integer := app.exercise_json_int(p -> 'times_per_day');
  v_feld text;
begin
  if p is null then
    return true;
  end if;
  if jsonb_typeof(p) <> 'object' then
    return false;
  end if;
  for v_feld in select jsonb_object_keys(p) loop
    if v_feld not in ('sets', 'reps_min', 'reps_max', 'duration_seconds', 'hold_seconds',
                      'per_side', 'times_per_day') then
      return false;
    end if;
    -- Ein Feld mit Wert hat den richtigen Typ.
    if jsonb_typeof(p -> v_feld) <> 'null'
       and ((v_feld = 'per_side' and jsonb_typeof(p -> v_feld) <> 'boolean')
         or (v_feld <> 'per_side' and app.exercise_json_int(p -> v_feld) is null)) then
      return false;
    end if;
  end loop;
  return coalesce(
    v_sets between 1 and 20
    and (v_min is null) = (v_max is null)
    and (v_min is null or (v_min between 1 and 100 and v_max between 1 and 100 and v_max >= v_min))
    and (v_dur is null or v_dur between 1 and 3600)
    and ((v_min is null) <> (v_dur is null))
    and (v_hold is null or (v_hold between 1 and 600 and v_min is not null))
    and (v_tag is null or v_tag between 1 and 10),
    false);
end;
$$;

COMMENT ON FUNCTION app.exercise_dosage_valid(p jsonb) IS 'UEB-012 (ANN-384): Pruefung der Standarddosierung einer Variante - dieselben Grenzen wie an der Planposition.';

CREATE FUNCTION app.exercise_equipment_labels() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'stuhl', 'Stuhl',
    'tisch', 'Tisch oder Arbeitsplatte',
    'wand', 'Wand',
    'tuerrahmen', 'Türrahmen',
    'bett', 'Bett',
    'handtuch', 'Handtuch',
    'kissen', 'Kissen',
    'theraband', 'Theraband',
    'stufe', 'Treppe oder Stufe',
    'hantel', 'Hantel oder Wasserflasche',
    'gewichtsmanschette', 'Gewichtsmanschette',
    'ball', 'Ball',
    'stab', 'Stab oder Besenstiel',
    'matte', 'Matte',
    'gehhilfe', 'Gehhilfe',
    'pedaltrainer', 'Bewegungstrainer',
    'alltagsgegenstand', 'Alltagsgegenstand'
  )
$$;

COMMENT ON FUNCTION app.exercise_equipment_labels() IS 'UEB-012 (ANN-383): Hilfsmittel des Katalogs und ihre Bezeichnung in der Ausruestung. Gegenstueck HILFSMITTEL_LABEL in src/features/exercises/katalog/typen.ts.';

CREATE FUNCTION app.exercise_goals() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array[
    'mobilitaet', 'kraft', 'stabilitaet', 'gleichgewicht',
    'dehnung', 'atmung', 'koordination', 'ausdauer'
  ]::text[]
$$;

COMMENT ON FUNCTION app.exercise_goals() IS 'UEB-012 (ANN-383): Ziele einer Variante - eine Ordnung zum Suchen, keine Auswahl (ADR-006 Punkt 10). Gegenstueck in src/features/exercises/katalog/typen.ts.';

CREATE FUNCTION app.exercise_illustration_bases() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array[
    'stand', 'sitz', 'langsitz', 'rueckenlage', 'rueckenlage_angestellt',
    'bauchlage', 'vierfuessler', 'kniestand', 'stand_front', 'sitz_front',
    'seitlage_front'
  ]::text[]
$$;

COMMENT ON FUNCTION app.exercise_illustration_bases() IS 'UEB-012 (ANN-381): Grundstellungen eines Uebungsbilds der Fassung 1. Gegenstueck GRUNDSTELLUNGEN in src/features/exercises/bild/schema.ts.';

CREATE FUNCTION app.exercise_illustration_valid(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p is null
$$;

COMMENT ON FUNCTION app.exercise_illustration_valid(p jsonb) IS 'UEB-012, UEB-013 (ANN-539): Ein Uebungsbild gibt es nicht mehr - gueltig ist nur null. Die eine Stelle, an der ein Bild wieder zugelassen wuerde.';

CREATE FUNCTION app.exercise_json_int(p jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case
    when jsonb_typeof(p) = 'number' and (p #>> '{}') ~ '^[0-9]{1,6}$' then (p #>> '{}')::integer
  end
$_$;

CREATE FUNCTION app.exercise_json_text(p jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when jsonb_typeof(p) = 'string' then p #>> '{}' end
$$;

CREATE FUNCTION app.exercise_library_writer() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_exercise_library() then
    raise exception 'not allowed to manage the exercise library' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage the exercise library' using errcode = '42501';
  end if;
  return v_org;
end;
$$;

CREATE FUNCTION app.exercise_optional_text(p_text text, p_field text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := nullif(btrim(coalesce(p_text, ''), E' \t\r\n'), '');
begin
  if v_text is not null and length(v_text) > 1000 then
    raise exception '% is too long', p_field using errcode = '22023';
  end if;
  return v_text;
end;
$$;

CREATE TABLE public.exercise_plans (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    service_area text NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    title text NOT NULL,
    sessions_per_week smallint,
    status text DEFAULT 'draft'::text NOT NULL,
    previous_plan_id uuid,
    assigned_at timestamp with time zone,
    assigned_by uuid,
    runs_from date,
    runs_until date,
    original_runs_until date,
    extended_at timestamp with time zone,
    extended_by uuid,
    ended_at timestamp with time zone,
    ended_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT exercise_plans_assigned_stamp CHECK ((((status = 'draft'::text) = (assigned_at IS NULL)) AND ((assigned_at IS NULL) = (assigned_by IS NULL)) AND ((assigned_at IS NULL) = (runs_from IS NULL)) AND ((assigned_at IS NULL) = (runs_until IS NULL)) AND ((assigned_at IS NULL) = (original_runs_until IS NULL)))),
    CONSTRAINT exercise_plans_ended_stamp CHECK ((((status = ANY (ARRAY['ended'::text, 'superseded'::text])) = (ended_at IS NOT NULL)) AND ((ended_at IS NULL) = (ended_by IS NULL)))),
    CONSTRAINT exercise_plans_extended_stamp CHECK ((((extended_at IS NULL) = (extended_by IS NULL)) AND ((extended_at IS NULL) OR (assigned_at IS NOT NULL)))),
    CONSTRAINT exercise_plans_one_relationship CHECK ((((service_area = 'therapy'::text) AND (patient_id IS NOT NULL) AND (training_relationship_id IS NULL)) OR ((service_area = 'training'::text) AND (training_relationship_id IS NOT NULL) AND (patient_id IS NULL)))),
    CONSTRAINT exercise_plans_runs CHECK ((runs_until >= runs_from)),
    CONSTRAINT exercise_plans_service_area_check CHECK ((service_area = ANY (ARRAY['therapy'::text, 'training'::text]))),
    CONSTRAINT exercise_plans_sessions_per_week_check CHECK ((sessions_per_week BETWEEN 1 AND 14)),
    CONSTRAINT exercise_plans_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'assigned'::text, 'ended'::text, 'superseded'::text]))),
    CONSTRAINT exercise_plans_title_check CHECK (((length(btrim(title, E' \t\r\n'::text)) >= 1) AND (length(btrim(title, E' \t\r\n'::text)) <= 80)))
);

COMMENT ON TABLE public.exercise_plans IS 'UEB-004: Uebungsplan fuer genau eine Person in genau einem Verhaeltnis (IDEA-TRN-011, ANN-297). Datenklasse je Zeile: service_area therapy = Patientenakte (Therapieplaene, ADR-008), training = Trainingsverhaeltnis (ADR-021 Punkt 4); faellt mit dem Verhaeltnis. Keine Auswahl aus klinischen Angaben (ADR-006 Punkt 10). Kein Tabellenrecht: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.exercise_plans.service_area IS 'Leistungsbereich (ADR-021): therapy haengt an patients, training an training_relationships - genau eines, nie beides (ANN-297).';

COMMENT ON COLUMN public.exercise_plans.title IS 'Bezeichnung des Plans, frei. Darf NIEMALS in Betriebslogs oder in den Auditkontext gelangen (ADR-011).';

COMMENT ON COLUMN public.exercise_plans.status IS 'draft (Entwurf), assigned (zugewiesen, eingefroren - UEB-005), ended (beendet - UEB-007), superseded (durch eine neue Fassung abgeloest - UEB-006).';

COMMENT ON COLUMN public.exercise_plans.original_runs_until IS 'Das Ende, mit dem der Plan zugewiesen wurde; runs_until traegt eine Verlaengerung (UEB-007, ANN-302).';

CREATE FUNCTION app.exercise_plan_for_write(p_plan_id uuid) RETURNS public.exercise_plans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_plan public.exercise_plans%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    raise exception 'not allowed to write exercise plans' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write exercise plans' using errcode = '42501';
  end if;

  select * into v_plan
  from public.exercise_plans p
  where p.id = p_plan_id and p.organization_id = v_org
  for update;

  if not found or not app.can_write_exercise_plans(v_plan.service_area) then
    raise exception 'exercise plan not found' using errcode = 'P0002';
  end if;
  return v_plan;
end;
$$;

-- ANN-480
CREATE TABLE public.exercise_plan_items (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    "position" smallint NOT NULL,
    variant_id uuid NOT NULL,
    sets smallint NOT NULL,
    reps_min smallint,
    reps_max smallint,
    duration_seconds smallint,
    load text,
    tempo text,
    rest_seconds smallint,
    double_progression boolean DEFAULT false NOT NULL,
    note text,
    previous_item_id uuid,
    step_axis text,
    step_direction text,
    exercise_name text,
    exercise_lay_name text,
    variant_name text,
    variant_lay_name text,
    body_region text,
    instruction text,
    equipment text[],
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    hold_seconds smallint,
    per_side boolean DEFAULT false NOT NULL,
    times_per_day smallint,
    illustration jsonb,
    CONSTRAINT exercise_plan_items_double_progression CHECK (((NOT double_progression) OR ((reps_max > reps_min) AND (load IS NOT NULL)))),
    CONSTRAINT exercise_plan_items_duration_seconds_check CHECK ((duration_seconds BETWEEN 1 AND 3600)),
    CONSTRAINT exercise_plan_items_hold CHECK (((hold_seconds IS NULL) OR (reps_min IS NOT NULL))),
    CONSTRAINT exercise_plan_items_hold_seconds_check CHECK ((hold_seconds BETWEEN 1 AND 600)),
    CONSTRAINT exercise_plan_items_illustration_check CHECK (app.exercise_illustration_valid(illustration)),
    CONSTRAINT exercise_plan_items_load_check CHECK (((load IS NULL) OR ((length(btrim(load, E' \t\r\n'::text)) >= 1) AND (length(btrim(load, E' \t\r\n'::text)) <= 40)))),
    CONSTRAINT exercise_plan_items_note_check CHECK (((note IS NULL) OR ((length(btrim(note, E' \t\r\n'::text)) >= 1) AND (length(btrim(note, E' \t\r\n'::text)) <= 500)))),
    CONSTRAINT exercise_plan_items_position_check CHECK (("position" BETWEEN 1 AND 30)),
    CONSTRAINT exercise_plan_items_reps CHECK ((((reps_min IS NULL) = (reps_max IS NULL)) AND ((reps_max IS NULL) OR (reps_max >= reps_min)))),
    CONSTRAINT exercise_plan_items_reps_max_check CHECK ((reps_max BETWEEN 1 AND 100)),
    CONSTRAINT exercise_plan_items_reps_min_check CHECK ((reps_min BETWEEN 1 AND 100)),
    CONSTRAINT exercise_plan_items_reps_or_duration CHECK (((reps_min IS NULL) <> (duration_seconds IS NULL))),
    CONSTRAINT exercise_plan_items_rest_seconds_check CHECK ((rest_seconds BETWEEN 0 AND 600)),
    CONSTRAINT exercise_plan_items_sets_check CHECK ((sets BETWEEN 1 AND 20)),
    CONSTRAINT exercise_plan_items_snapshot CHECK ((((variant_name IS NULL) AND (variant_lay_name IS NULL) AND (exercise_name IS NULL) AND (exercise_lay_name IS NULL) AND (body_region IS NULL) AND (equipment IS NULL) AND (instruction IS NULL)) OR ((variant_name IS NOT NULL) AND (variant_lay_name IS NOT NULL) AND (exercise_name IS NOT NULL) AND (exercise_lay_name IS NOT NULL) AND (body_region IS NOT NULL) AND (equipment IS NOT NULL)))),
    CONSTRAINT exercise_plan_items_step CHECK ((((step_axis IS NULL) = (step_direction IS NULL)) AND ((step_axis IS NULL) OR (previous_item_id IS NOT NULL)) AND ((step_axis IS NULL) OR ((step_axis = ANY (app.exercise_axes())) AND (step_axis <> 'frequenz'::text))))),
    CONSTRAINT exercise_plan_items_step_direction_check CHECK ((step_direction = ANY (ARRAY['harder'::text, 'easier'::text]))),
    CONSTRAINT exercise_plan_items_tempo_check CHECK (((tempo IS NULL) OR ((length(btrim(tempo, E' \t\r\n'::text)) >= 1) AND (length(btrim(tempo, E' \t\r\n'::text)) <= 40)))),
    CONSTRAINT exercise_plan_items_times_per_day_check CHECK ((times_per_day BETWEEN 1 AND 10))
);

COMMENT ON TABLE public.exercise_plan_items IS 'UEB-004: Position eines Uebungsplans - eine Variante der Bibliothek mit Dosierung (ANN-299). Datenklasse wie ihr Plan (Patientenakte oder Trainingsverhaeltnis); faellt mit ihm. Nach der Zuweisung unveraenderlich, mit eingefrorenem Schnappschuss der Bibliothek (ANN-300). Kein Tabellenrecht (ADR-004).';

COMMENT ON COLUMN public.exercise_plan_items.note IS 'Hinweis an die Person. Freitext, der NIEMALS in Betriebslogs oder in den Auditkontext gelangt (ADR-011).';

COMMENT ON COLUMN public.exercise_plan_items.step_axis IS 'Die eine Achse, entlang der diese Position gegenueber der vorigen Fassung gesteigert oder zurueckgenommen wurde (UEB-006, ANN-301). Von Hand gesetzt, nie vorgeschlagen (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercise_plan_items.variant_name IS 'Schnappschuss bei der Zuweisung (ANN-300): Eine spaetere Aenderung der Bibliothek aendert nicht, was die Person bekommen hat (IDEA-TRN-011).';

COMMENT ON COLUMN public.exercise_plan_items.hold_seconds IS 'UEB-012 (ANN-384): jede Wiederholung so viele Sekunden halten; nur mit Wiederholungen.';

COMMENT ON COLUMN public.exercise_plan_items.per_side IS 'UEB-012 (ANN-384): die Dosierung gilt je Koerperseite; keine Achse eines Schritts (ANN-387).';

COMMENT ON COLUMN public.exercise_plan_items.times_per_day IS 'UEB-012 (ANN-384): wie oft am Tag; ohne Angabe gilt sessions_per_week des Plans.';

COMMENT ON COLUMN public.exercise_plan_items.illustration IS 'UEB-012 (ANN-381, ANN-300): Bild der Variante, bei der Zuweisung eingefroren. Datenklasse wie der Plan; enthaelt selbst keine Angabe zur Person.';

CREATE FUNCTION app.exercise_plan_item_json(p_item public.exercise_plan_items) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_item.id,
    'position', p_item.position,
    'variant_id', p_item.variant_id,
    'exercise_name', coalesce(p_item.exercise_name, e.name),
    'exercise_lay_name', coalesce(p_item.exercise_lay_name, e.lay_name),
    'variant_name', coalesce(p_item.variant_name, v.name),
    'variant_lay_name', coalesce(p_item.variant_lay_name, v.lay_name),
    'body_region', coalesce(p_item.body_region, e.body_region),
    'instruction', case when p_item.variant_name is not null then p_item.instruction else v.instruction end,
    'equipment', to_jsonb(coalesce(p_item.equipment, v.equipment)),
    'illustration', case when p_item.variant_name is not null then p_item.illustration else v.illustration end,
    'variant_archived', p_item.variant_name is null and (v.archived_at is not null or e.archived_at is not null),
    'sets', p_item.sets,
    'reps_min', p_item.reps_min,
    'reps_max', p_item.reps_max,
    'duration_seconds', p_item.duration_seconds,
    'hold_seconds', p_item.hold_seconds,
    'per_side', p_item.per_side,
    'times_per_day', p_item.times_per_day,
    'load', p_item.load,
    'tempo', p_item.tempo,
    'rest_seconds', p_item.rest_seconds,
    'double_progression', p_item.double_progression,
    'note', p_item.note,
    'previous_item_id', p_item.previous_item_id,
    'step_axis', p_item.step_axis,
    'step_direction', p_item.step_direction
  )
  from public.exercise_variants v
  join public.exercises e on e.id = v.exercise_id
  where v.id = p_item.variant_id
$$;

CREATE FUNCTION app.exercise_plan_log_read(p_plan public.exercise_plans) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_plan.service_area = 'therapy' then
    perform app.log_record_access(
      p_plan.organization_id, auth.uid(), 'patient_record.viewed', 'patient', p_plan.patient_id,
      'user', jsonb_build_object('surface', 'web', 'view', 'exercise_plans'));
  else
    perform app.log_record_access(
      p_plan.organization_id, auth.uid(), 'training_relationship.viewed', 'training_relationship',
      p_plan.training_relationship_id,
      'user', jsonb_build_object('surface', 'web', 'view', 'exercise_plans'));
  end if;
end;
$$;

CREATE FUNCTION app.exercise_plan_max_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 182
$$;

COMMENT ON FUNCTION app.exercise_plan_max_days() IS 'UEB-005 (ANN-302): die laengste Laufzeit eines Plans in Tagen ab Zuweisung oder Verlaengerung - 26 Wochen. Die eine Stelle fuer die Zahl.';

CREATE FUNCTION app.exercise_plan_relationship_open(p_plan public.exercise_plans) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_plan.service_area = 'training' and exists (
    select 1 from public.training_relationships t
    where t.id = p_plan.training_relationship_id and t.contract_ended_on is not null
  ) then
    raise exception 'training relationship has ended' using errcode = '23514';
  end if;
end;
$$;

CREATE FUNCTION app.exercise_plan_renumber(p_plan_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.exercise_plan_items i
     set position = n.neu
    from (
      select x.id, row_number() over (order by x.position, x.created_at, x.id) as neu
      from public.exercise_plan_items x
      where x.plan_id = p_plan_id
    ) n
   where i.id = n.id and i.position is distinct from n.neu;
$$;

CREATE FUNCTION app.exercise_plan_review_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 7
$$;

COMMENT ON FUNCTION app.exercise_plan_review_days() IS 'UEB-007 (ANN-302): so viele Tage vor dem Ende steht die Wiedervorlage an. Die eine Stelle fuer die Zahl.';

CREATE FUNCTION app.exercise_plan_review_due(p_plan public.exercise_plans) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_plan.status = 'assigned'
     and p_plan.runs_until <= app.training_today(p_plan.organization_id) + app.exercise_plan_review_days()
$$;

COMMENT ON FUNCTION app.exercise_plan_review_due(p_plan public.exercise_plans) IS 'UEB-007 (ANN-302): Die Wiedervorlage steht an, wenn ein zugewiesener Plan in hoechstens app.exercise_plan_review_days() Tagen endet oder schon geendet hat - bis er verlaengert, abgeloest oder beendet ist. Liest nur das Datum (ADR-006 Punkt 11).';

CREATE FUNCTION app.exercise_plan_sessions_json(p_plan_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'performed_on', s.performed_on,
    'started_at', s.started_at,
    'finished_at', s.finished_at,
    -- TRK-007: nach der Uhr des Geraets, wenn ohne Netz erfasst.
    'reported_started_at', s.reported_started_at,
    'reported_finished_at', s.reported_finished_at,
    'sets_done', (select count(*) from public.exercise_plan_session_sets x where x.session_id = s.id),
    'sets_total', (select coalesce(sum(i.sets), 0) from public.exercise_plan_items i
                   where i.plan_id = s.plan_id),
    -- OUT-003 (ANN-366): abgehakte Saetze je Position; eine Position ohne
    -- Haken fehlt.
    'sets_by_item', (select coalesce(jsonb_object_agg(x.item_id, x.n), '{}'::jsonb)
                     from (select y.item_id, count(*) as n
                           from public.exercise_plan_session_sets y
                           where y.session_id = s.id
                           group by y.item_id) x),
    'difficulty_note', s.difficulty_note,
    -- TRK-001: die Angaben der Person, unveraendert (ADR-006 Punkt 3).
    'values', (select coalesce(jsonb_object_agg(v.parameter_key, v.value), '{}'::jsonb)
               from public.exercise_plan_session_values v where v.session_id = s.id),
    'recorded_by_kind', s.platform_access_kind,
    -- Wer beendet und damit "schwierig, weil ..." geschrieben hat.
    'finished_by_kind', s.finished_access_kind
  ) order by s.performed_on desc, s.started_at desc), '[]'::jsonb)
  from public.exercise_plan_sessions s
  where s.plan_id = p_plan_id
$$;

COMMENT ON FUNCTION app.exercise_plan_sessions_json(p_plan_id uuid) IS 'UEB-010, TRK-001, TRK-007, OUT-003: die Einheiten eines Plans - Tag, Zeiten (auch nach der Uhr des Geraets), abgehakte Saetze gesamt und je Position, "schwierig, weil ..." und die Angaben der Person, unveraendert. Ohne Rechtepruefung: nur aus get_exercise_plan und der Auskunft.';

CREATE FUNCTION app.exercise_plan_step_check(p_previous_item_id uuid, p_variant_id uuid, p_sets integer, p_reps_min integer, p_reps_max integer, p_duration_seconds integer, p_load text, p_tempo text, p_rest_seconds integer, p_step_axis text, p_step_direction text, p_hold_seconds integer) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorher   public.exercise_plan_items%rowtype;
  v_achsen   text[] := '{}'::text[];
  v_achse    text;
  v_schwerer boolean;
begin
  select * into v_vorher from public.exercise_plan_items i where i.id = p_previous_item_id;
  if not found then
    raise exception 'previous item belongs to the previous version' using errcode = '23514';
  end if;

  if (p_step_axis is null) <> (p_step_direction is null)
     or (p_step_direction is not null and p_step_direction not in ('harder', 'easier'))
     or (p_step_axis is not null
         and (p_step_axis = 'frequenz' or not (p_step_axis = any (app.exercise_axes())))) then
    raise exception 'step is invalid' using errcode = '22023';
  end if;

  if (p_reps_min is null) <> (v_vorher.reps_min is null) then
    raise exception 'change is not a single step' using errcode = '22023';
  end if;

  if p_variant_id is distinct from v_vorher.variant_id then
    v_achsen := v_achsen || 'variante'::text;
  end if;
  if p_reps_min is distinct from v_vorher.reps_min or p_reps_max is distinct from v_vorher.reps_max
     or p_duration_seconds is distinct from v_vorher.duration_seconds
     or p_hold_seconds is distinct from v_vorher.hold_seconds then
    v_achsen := v_achsen || 'wiederholungen'::text;
  end if;
  if p_sets is distinct from v_vorher.sets then
    v_achsen := v_achsen || 'saetze'::text;
  end if;
  if p_load is distinct from v_vorher.load then
    v_achsen := v_achsen || 'last'::text;
  end if;
  if p_tempo is distinct from v_vorher.tempo then
    v_achsen := v_achsen || 'tempo'::text;
  end if;
  if p_rest_seconds is distinct from v_vorher.rest_seconds then
    v_achsen := v_achsen || 'dichte'::text;
  end if;

  if cardinality(v_achsen) = 0 then
    if p_step_axis is not null then
      raise exception 'step does not match the change' using errcode = '22023';
    end if;
    return;
  end if;
  if cardinality(v_achsen) > 1 then
    raise exception 'only one axis per step' using errcode = '22023';
  end if;
  if p_step_axis is null then
    raise exception 'step axis is required' using errcode = '22023';
  end if;

  v_achse := v_achsen[1];
  v_schwerer := p_step_direction = 'harder';

  if v_achse = 'variante' then
    if not exists (
      select 1 from public.exercise_variant_links l
      where l.axis = p_step_axis
        and ((v_schwerer and l.easier_variant_id = v_vorher.variant_id and l.harder_variant_id = p_variant_id)
          or (not v_schwerer and l.harder_variant_id = v_vorher.variant_id and l.easier_variant_id = p_variant_id))
    ) then
      raise exception 'step does not match the change' using errcode = '22023';
    end if;
    return;
  end if;

  if p_step_axis <> v_achse then
    raise exception 'step does not match the change' using errcode = '22023';
  end if;

  if (v_achse = 'saetze' and (p_sets > v_vorher.sets) <> v_schwerer)
     or (v_achse = 'dichte' and p_rest_seconds is not null and v_vorher.rest_seconds is not null
         and (p_rest_seconds < v_vorher.rest_seconds) <> v_schwerer)
     or (v_achse = 'wiederholungen' and p_reps_max is not null
         and (p_reps_max, p_reps_min) is distinct from (v_vorher.reps_max, v_vorher.reps_min)
         and ((p_reps_max, p_reps_min) > (v_vorher.reps_max, v_vorher.reps_min)) <> v_schwerer)
     or (v_achse = 'wiederholungen' and p_duration_seconds is not null
         and (p_duration_seconds > v_vorher.duration_seconds) <> v_schwerer)
     -- Aendert sich das Halten, passt es zur Richtung - allein wie zusammen
     -- mit den Wiederholungen: laenger (oder neu) halten ist schwerer.
     -- Mehr Wiederholungen bei kuerzerem Halten ist kein Schritt (ANN-387).
     or (v_achse = 'wiederholungen'
         and p_hold_seconds is distinct from v_vorher.hold_seconds
         and (coalesce(p_hold_seconds, 0) > coalesce(v_vorher.hold_seconds, 0)) <> v_schwerer) then
    raise exception 'step direction does not match the change' using errcode = '22023';
  end if;
end;
$$;

COMMENT ON FUNCTION app.exercise_plan_step_check(p_previous_item_id uuid, p_variant_id uuid, p_sets integer, p_reps_min integer, p_reps_max integer, p_duration_seconds integer, p_load text, p_tempo text, p_rest_seconds integer, p_step_axis text, p_step_direction text, p_hold_seconds integer) IS 'UEB-006/UEB-012 (ANN-301): Eine Position der neuen Fassung aendert gegenueber ihrer vorigen hoechstens eine Achse; Achse und Richtung passen zur Aenderung, eine andere Variante nur ueber eine Verbindung der Bibliothek. Halten gehoert zur Achse wiederholungen.';

CREATE FUNCTION app.exercise_plan_text(p_text text, p_max integer, p_field text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := nullif(btrim(coalesce(p_text, ''), E' \t\r\n'), '');
begin
  if v_text is not null and length(v_text) > p_max then
    raise exception '% is too long', p_field using errcode = '22023';
  end if;
  return v_text;
end;
$$;

CREATE FUNCTION app.exercise_plan_weekdays(p_plan_id uuid) RETURNS smallint[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive kette as (
    select p.id, p.previous_plan_id, 0 as tiefe
    from public.exercise_plans p where p.id = p_plan_id
    union all
    select v.id, v.previous_plan_id, k.tiefe + 1
    from kette k join public.exercise_plans v on v.id = k.previous_plan_id
    where k.tiefe < 100
  )
  select d.weekdays
  from kette k join public.exercise_plan_days d on d.plan_id = k.id
  order by k.tiefe
  limit 1
$$;

CREATE FUNCTION app.exercise_required_name(p_text text, p_field text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := btrim(coalesce(p_text, ''), E' \t\r\n');
begin
  if v_text = '' then
    raise exception '% is required', p_field using errcode = '22023';
  end if;
  if length(v_text) > 120 then
    raise exception '% is too long', p_field using errcode = '22023';
  end if;
  return v_text;
end;
$$;

