CREATE FUNCTION app.finish_food_catalog_import(p_source text, p_version text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zurueck integer;
begin
  -- Was im neuen Stand fehlt, wird zurückgezogen, nicht gelöscht.
  update public.food_catalog c set retired_at = now()
  where c.source = p_source and c.source_version <> p_version and c.retired_at is null;
  get diagnostics v_zurueck = row_count;

  update public.food_sources s set
    version = p_version,
    imported_at = now(),
    item_count = (select count(*) from public.food_catalog c
                  where c.source = p_source and c.retired_at is null)
  where s.source = p_source;
  if not found then
    raise exception 'unknown source' using errcode = '22023';
  end if;
  return v_zurueck;
end;
$$;

COMMENT ON FUNCTION app.finish_food_catalog_import(p_source text, p_version text) IS 'ERN-004 (ANN-659): schließt einen Import ab - zieht zurück, was im neuen Stand fehlt, und vermerkt Stand und Anzahl an der Quelle. Allein für den Betrieb.';

