CREATE TABLE public.fleet_bikes (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    bike_type text DEFAULT 'load60_riemen'::text NOT NULL,
    home_depot_id uuid NOT NULL,
    current_depot_id uuid,
    special_location text,
    is_spare boolean DEFAULT false NOT NULL,
    regular_rider_id uuid,
    planned_weekdays smallint[] DEFAULT '{}'::smallint[] NOT NULL,
    battery text,
    note text,
    archived_at timestamp with time zone,
    archived_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT fleet_bikes_archived_stamp CHECK (((archived_at IS NULL) = (archived_by IS NULL))),
    CONSTRAINT fleet_bikes_battery_check CHECK (((battery IS NULL) OR ((length(btrim(battery)) >= 1) AND (length(btrim(battery)) <= 80)))),
    CONSTRAINT fleet_bikes_bike_type_check CHECK ((bike_type = ANY (app.fleet_bike_types()))),
    CONSTRAINT fleet_bikes_location CHECK (((current_depot_id IS NULL) <> (special_location IS NULL))),
    CONSTRAINT fleet_bikes_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60))),
    CONSTRAINT fleet_bikes_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 500)))),
    CONSTRAINT fleet_bikes_planned_weekdays_check CHECK ((planned_weekdays <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint])),
    CONSTRAINT fleet_bikes_spare_without_rider CHECK (((NOT is_spare) OR ((regular_rider_id IS NULL) AND (cardinality(planned_weekdays) = 0)))),
    CONSTRAINT fleet_bikes_special_location_check CHECK (((special_location IS NULL) OR ((length(btrim(special_location)) >= 1) AND (length(btrim(special_location)) <= 120))))
);

COMMENT ON TABLE public.fleet_bikes IS 'FLT-001: ein Rad der Flotte mit Bauart, Stammdepot, Standort, Stammnutzer:in und Wochenplan. Kein Statusfeld: "In Reparatur" ist eine offene Sperre, "im Einsatz" ein entnommener Schluessel (ANN-557). Kein Schluesselcode (ANN-554). Datenklasse: Betriebsdaten der Praxis; Personenbezug nur ueber die Stammnutzer:in, die beim Ausmustern faellt. Frist: in der Flotte bis zur Loeschung durch die Praxis; ausgemustert, bis der Verlauf nach seinen Fristen gefallen ist (Loeschlauf, ANN-557). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.fleet_bikes.planned_weekdays IS 'Wochenplan der Stammnutzer:in: 1 = Montag bis 7 = Sonntag. An den uebrigen Tagen fuer andere planbar.';

CREATE FUNCTION app.fleet_bike_json(p_bike public.fleet_bikes) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_bike.id,
    'name', p_bike.name,
    'bike_type', p_bike.bike_type,
    'home_depot_id', p_bike.home_depot_id,
    'current_depot_id', p_bike.current_depot_id,
    'special_location', p_bike.special_location,
    'is_spare', p_bike.is_spare,
    'regular_rider', case when p_bike.regular_rider_id is null then null else
      jsonb_build_object('id', p_bike.regular_rider_id,
                         'name', app.fleet_staff_name(p_bike.regular_rider_id)) end,
    'planned_weekdays', to_jsonb(p_bike.planned_weekdays),
    'battery', p_bike.battery,
    'note', p_bike.note,
    'updated_at', p_bike.updated_at,
    'key', (
      select jsonb_build_object(
        'holder_staff_id', k.holder_staff_id,
        'holder_name', app.fleet_staff_name(k.holder_staff_id),
        'taken_at', k.taken_at
      )
      from public.fleet_key_handovers k
      where k.bike_id = p_bike.id and k.returned_at is null
    ),
    'block', (
      select jsonb_build_object(
        'id', b.id,
        'blocked_at', b.blocked_at,
        'reason', b.reason,
        'breakdown_id', b.breakdown_id
      )
      from public.fleet_blocks b
      where b.bike_id = p_bike.id and b.released_at is null
    ),
    'open_spots', (
      select count(*) from public.fleet_spots s
      where s.bike_id = p_bike.id and s.resolved_at is null
    ),
    'open_problems', (
      select count(*) from public.fleet_spots s
      where s.bike_id = p_bike.id and s.resolved_at is null and s.severity = 'problem'
    ),
    'last_checkup_at', (
      select max(c.checked_at) from public.fleet_checkups c where c.bike_id = p_bike.id
    )
  )
$$;

