CREATE FUNCTION app.fleet_photos_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Was eine Datei ist, aendert sich nicht (ADR-017 Punkt 8): nur Zustand und
  -- Pruefung. Der Objektschluessel ist generiert und im BEFORE-Trigger leer.
  if (to_jsonb(new) - array['status', 'confirmation_requested_at', 'confirmed_at', 'verified_at',
                            'object_key'])
     is distinct from
     (to_jsonb(old) - array['status', 'confirmation_requested_at', 'confirmed_at', 'verified_at',
                            'object_key']) then
    raise exception 'fleet photos are immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.fleet_report_photos(p_checkup_id uuid, p_breakdown_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(
    jsonb_build_object('id', f.id, 'spot_id', f.spot_id, 'side', f.side)
    order by f.created_at, f.id
  ), '[]'::jsonb)
  from public.fleet_photos f
  where f.status = 'ready'
    and (
      (p_checkup_id is not null and f.checkup_id = p_checkup_id)
      or f.spot_id in (
        select s.id from public.fleet_spots s
        where (p_checkup_id is not null and s.checkup_id = p_checkup_id)
           or (p_breakdown_id is not null and s.breakdown_id = p_breakdown_id)
      )
    )
$$;

CREATE FUNCTION app.fleet_report_spots(p_checkup_id uuid, p_breakdown_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(app.fleet_spot_json(s, null) order by s.created_at, s.seq), '[]'::jsonb)
  from public.fleet_spots s
  where (p_checkup_id is not null and s.checkup_id = p_checkup_id)
     or (p_breakdown_id is not null and s.breakdown_id = p_breakdown_id)
$$;

