      'kurbeln', 'motor', 'akku', 'licht-vorne', 'licht-hinten', 'sattel', 'klingel',
      'schutzblech-vorne', 'schutzblech-hinten', 'staender', 'transportbox',
      'rahmen', 'lenker', 'display', 'lenkung', 'gabel', 'daempfer', 'gepaecktraeger'
    ]::text[]
