COMMENT ON FUNCTION app.fleet_zones(p_bike_type text) IS 'FLT-001: die 27 Bauteile des 3D-Rads (Handoff Lastenrad 3D, Abschnitt 5). Gegenstueck BIKE_ZONES in src/features/fleet/bike3d/zones.ts.';

CREATE TABLE public.fleet_spots (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bike_id uuid NOT NULL,
    checkup_id uuid,
    breakdown_id uuid,
    bike_type text NOT NULL,
    model_version smallint NOT NULL,
    zone text NOT NULL,
    point_x numeric(5,3),
    point_y numeric(5,3),
    point_z numeric(5,3),
    severity text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    seq bigint NOT NULL,
    created_by uuid NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    CONSTRAINT fleet_spots_bike_type_check CHECK ((bike_type = ANY (app.fleet_bike_types()))),
    CONSTRAINT fleet_spots_breakdown_problem CHECK (((breakdown_id IS NULL) OR (severity = 'problem'::text))),
    CONSTRAINT fleet_spots_model_version_check CHECK ((model_version >= 1)),
    CONSTRAINT fleet_spots_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 500)))),
    CONSTRAINT fleet_spots_one_source CHECK (((checkup_id IS NULL) <> (breakdown_id IS NULL))),
    CONSTRAINT fleet_spots_point CHECK ((((point_x IS NULL) AND (point_y IS NULL) AND (point_z IS NULL)) OR ((point_x IS NOT NULL) AND (point_y IS NOT NULL) AND (point_z IS NOT NULL) AND (point_x BETWEEN ('-2'::integer)::numeric AND (2)::numeric) AND (point_y BETWEEN ('-1'::integer)::numeric AND (2)::numeric) AND (point_z BETWEEN ('-1'::integer)::numeric AND (1)::numeric)))),
    CONSTRAINT fleet_spots_resolved_stamp CHECK (((resolved_at IS NULL) = (resolved_by IS NULL))),
    CONSTRAINT fleet_spots_severity_check CHECK ((severity = ANY (ARRAY['problem'::text, 'beobachten'::text]))),
    CONSTRAINT fleet_spots_zone CHECK ((zone = ANY (app.fleet_zones(bike_type))))
);

COMMENT ON TABLE public.fleet_spots IS 'FLT-001: Stelle am 3D-Rad aus einem Check-Up oder einer Panne - Bauteil, Punkt in Modellkoordinaten mit Fassung des Modells, Einstufung, Notiz (ANN-555). Mit "Freigeben" erledigt, bleibt im Verlauf. Datenklasse radflotte_ereignis, faellt mit Check-Up oder Panne (cascade). Kein Tabellenrecht.';

COMMENT ON COLUMN public.fleet_spots.note IS 'Notiz zur Stelle. Kann nebenbei einen Patientenbezug tragen (Handoff Abschnitt 6); der Hinweis steht am Feld, und die Unterlage fuer die Werkstatt bittet um Pruefung vor dem Weitergeben.';

CREATE FUNCTION app.fleet_spot_json(p_spot public.fleet_spots, p_number integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_spot.id,
    'number', p_number,
    'zone', p_spot.zone,
    'point', case when p_spot.point_x is null then null
                  else jsonb_build_array(p_spot.point_x, p_spot.point_y, p_spot.point_z) end,
    'model_version', p_spot.model_version,
    'severity', p_spot.severity,
    'note', p_spot.note,
    'source', case when p_spot.checkup_id is not null then 'checkup' else 'breakdown' end,
    'source_id', coalesce(p_spot.checkup_id, p_spot.breakdown_id),
    'created_at', p_spot.created_at,
    'resolved_at', p_spot.resolved_at
  )
$$;

CREATE FUNCTION app.fleet_staff_name(p_staff_member_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pe.given_name || ' ' || pe.family_name
  from public.staff_members sm
  join public.persons pe on pe.id = sm.person_id
  where sm.id = p_staff_member_id
$$;

CREATE FUNCTION app.fleet_text(p_text text, p_max integer, p_field text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := nullif(btrim(coalesce(p_text, ''), E' \t\r\n'), '');
begin
  if v_text is not null and length(v_text) > p_max then
    raise exception '% is too long', p_field using errcode = '22023';
  end if;
  return v_text;
end;
$$;

CREATE FUNCTION app.fleet_zone_check_item(p_bike_type text, p_zone text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_bike_type = 'load60_riemen' then
    case p_zone
      when 'reifen-vorne' then 'reifen'
      when 'reifen-hinten' then 'reifen'
      when 'laufrad-vorne' then 'speichen'
      when 'laufrad-hinten' then 'speichen'
      when 'bremse-vorne' then 'bremsen'
      when 'bremse-hinten' then 'bremsen'
      when 'bremsgriffe' then 'bremsen'
      when 'riemen' then 'antrieb'
      when 'nabenschaltung' then 'antrieb'
      when 'kurbeln' then 'antrieb'
      when 'motor' then 'antrieb'
      when 'akku' then 'akku'
      when 'licht-vorne' then 'licht_vorne'
      when 'licht-hinten' then 'licht_hinten'
      when 'sattel' then 'schrauben_sattel'
      when 'klingel' then 'klingel'
      when 'schutzblech-vorne' then 'schutzbleche'
      when 'schutzblech-hinten' then 'schutzbleche'
      when 'staender' then 'staender'
      when 'transportbox' then 'transportbox'
    end
  end
$$;

CREATE FUNCTION app.food_search(p_org uuid, p_query text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_q        text := app.food_search_key(p_query);
  v_woerter  text[];
  v_laengstes text;
  v_limit    integer := least(greatest(coalesce(p_limit, 20), 1), 50);
begin
  if length(v_q) < 2 then
    return '[]'::jsonb;
  end if;
  v_q := left(v_q, 100);
  v_woerter := (select array_agg(w) from unnest(string_to_array(v_q, ' ')) w where length(w) >= 2);
  if v_woerter is null then
    return '[]'::jsonb;
  end if;
  select w into v_laengstes from unnest(v_woerter) w order by length(w) desc, w limit 1;

  return coalesce((
    select jsonb_agg(t.eintrag order by t.rang desc, t.laenge, t.name)
    from (
      select
        c.eintrag,
        (case
           when c.name_key = v_q then 4
           when c.name_key like v_q || ' %' then 3
           when c.name_key like v_q || '%' then 2
           when ' ' || c.name_key || ' ' like '% ' || v_q || ' %' then 1.5
           else 0
         end
         -- Allgemeines (BLS) und die Lebensmittel der Praxis vor Marken.
         + case when c.allgemein then 2.5 else 0 end
         + extensions.word_similarity(v_q, c.search_key)) as rang,
        length(c.name_key) as laenge,
        c.name
      from (
        select b.name, b.name_key, b.search_key, true as allgemein,
               jsonb_build_object(
                 'kind', 'catalog', 'id', b.id, 'source', b.source,
                 'source_code', b.source_code, 'name', b.name, 'brand', b.brand,
                 'base_unit', b.base_unit,
                 'per_100', jsonb_build_object(
                   'energy_kcal', b.energy_kcal, 'protein_g', b.protein_g, 'fat_g', b.fat_g,
                   'carbohydrate_g', b.carbohydrate_g, 'sugar_g', b.sugar_g,
                   'fibre_g', b.fibre_g, 'saturated_fat_g', b.saturated_fat_g,
                   'salt_g', b.salt_g),
                 'portions', b.portions) as eintrag
        from public.food_catalog b
        where b.retired_at is null and b.source = 'bls'
          and (b.search_key like '%' || v_laengstes || '%'
               or v_laengstes operator(extensions.<%) b.search_key)
        union all
        select p.name, p.name_key, p.search_key, true, app.custom_food_json(p) - 'updated_at'
        from public.custom_foods p
        where p.organization_id = p_org and p.owner_kind = 'practice' and p.archived_at is null
          and (p.search_key like '%' || v_laengstes || '%'
               or v_laengstes operator(extensions.<%) p.search_key)
        union all
        -- Marken: die 300 nächsten Nachbarn, danach dieselben Regeln.
        select m.name, m.name_key, m.search_key, false,
               jsonb_build_object(
                 'kind', 'catalog', 'id', m.id, 'source', m.source,
                 'source_code', m.source_code, 'name', m.name, 'brand', m.brand,
                 'base_unit', m.base_unit,
                 'per_100', jsonb_build_object(
                   'energy_kcal', m.energy_kcal, 'protein_g', m.protein_g, 'fat_g', m.fat_g,
                   'carbohydrate_g', m.carbohydrate_g, 'sugar_g', m.sugar_g,
                   'fibre_g', m.fibre_g, 'saturated_fat_g', m.saturated_fat_g,
                   'salt_g', m.salt_g),
                 'portions', m.portions)
        from (
          select o.*
          from public.food_catalog o
          where o.retired_at is null and o.source = 'off'
          order by v_q operator(extensions.<<->) o.search_key
          limit 300
        ) m
      ) c
      where not exists (
          select 1 from unnest(v_woerter) w
          where not (c.search_key like '%' || w || '%'
                     or w operator(extensions.<%) c.search_key))
      order by rang desc, laenge, c.name
      limit v_limit
    ) t
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION app.food_search(p_org uuid, p_query text, p_limit integer) IS 'ERN-004/ERN-005 (ANN-658): Kandidaten und Rangfolge der Lebensmittelsuche an einer Stelle - BLS, die Lebensmittel der Praxis dieser Organisation und Marken (300 nächste Nachbarn); jedes Wort enthalten oder per Trigramm ähnlich; Name gleich, beginnt als Wort, beginnt, enthält als Wort; Allgemeines und Praxis vor Marken; Ähnlichkeit; kürzere Namen zuerst. Eigene Lebensmittel der Person nicht: die kennt sie aus ihrem Profil. Ohne Rechteprüfung.';

CREATE FUNCTION app.forget_profile_picture(p_org uuid, p_picture uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at, deleted_at)
  values (p_org, md5('profile_picture:' || p_org::text || ':' || current_date::text)::uuid,
          'staff_profile_pictures', p_picture, 'profilbild',
          date_trunc('day', now()), date_trunc('day', now()));
  delete from public.staff_profile_pictures where id = p_picture;
end;
$$;

CREATE TABLE public.platform_message_attachments (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    message_id uuid NOT NULL,
    media_kind text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    duration_seconds smallint,
    checksum_sha256 text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    confirmation_requested_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    verified_at timestamp with time zone,
    locked_at timestamp with time zone,
    access_id uuid,
    author_kind text NOT NULL,
    author_label text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    object_key text GENERATED ALWAYS AS ((((((organization_id)::text || '/'::text) || (message_id)::text) || '/'::text) || (id)::text)) STORED NOT NULL,
    CONSTRAINT platform_message_attachments_author_kind_check CHECK ((author_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT platform_message_attachments_author_label_check CHECK (((author_label IS NULL) OR ((length(btrim(author_label)) >= 1) AND (length(btrim(author_label)) <= 160)))),
    CONSTRAINT platform_message_attachments_byte_size_check CHECK (((byte_size > 0) AND (byte_size <= 10485760))),
    CONSTRAINT platform_message_attachments_checksum_sha256_check CHECK ((checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT platform_message_attachments_duration_seconds_check CHECK ((duration_seconds BETWEEN 1 AND 30)),
    CONSTRAINT platform_message_attachments_kind_matches CHECK ((((media_kind = 'photo'::text) AND (mime_type = 'image/jpeg'::text) AND (duration_seconds IS NULL)) OR ((media_kind = 'video'::text) AND (mime_type = ANY (ARRAY['video/webm'::text, 'video/mp4'::text])) AND (duration_seconds IS NOT NULL)))),
    CONSTRAINT platform_message_attachments_label CHECK (((author_kind = 'self'::text) = (author_label IS NULL))),
    CONSTRAINT platform_message_attachments_media_kind_check CHECK ((media_kind = ANY (ARRAY['photo'::text, 'video'::text]))),
    CONSTRAINT platform_message_attachments_mime_type_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'video/webm'::text, 'video/mp4'::text]))),
    CONSTRAINT platform_message_attachments_ready_confirmed CHECK (((status = 'ready'::text) = (confirmed_at IS NOT NULL))),
    CONSTRAINT platform_message_attachments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text])))
);

COMMENT ON TABLE public.platform_message_attachments IS 'KOM-005 (ADR-017 Abschnitt L): Foto oder Video an einer Rueckfrage der Plattform. Bezug die Rueckfrage, hoechstens drei je Vorgang. Datenklasse rueckfrageanhang: 30 Tage ab der Aufnahme, faellt frueher mit dem Vorgang, beim Widerruf der Einwilligung sofort. Kein Weg in Akte oder Trainingsprotokoll (Punkt 66). Kein Tabellenrecht.';

COMMENT ON COLUMN public.platform_message_attachments.checksum_sha256 IS 'SHA-256 der abgelegten Bytes, im Browser gerechnet; zum Nachweis des Servers erst mit verified_at (ADR-017 Punkte 9 und 49).';

CREATE FUNCTION app.grant_message_attachment(p_attachment public.platform_message_attachments) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.message_attachment_access_grants g
   where g.organization_id = p_attachment.organization_id
     and g.expires_at <= now();

  insert into public.message_attachment_access_grants (
    organization_id, user_id, attachment_id, expires_at
  )
  values (
    p_attachment.organization_id, auth.uid(), p_attachment.id,
    now() + app.patient_file_access_grant_ttl()
  );

  return query
    select app.message_attachment_bucket(), p_attachment.object_key, p_attachment.mime_type;
end;
$$;

CREATE FUNCTION app.guard_patient_photo_type() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.document_type is distinct from old.document_type
     and (app.is_patient_photo_type(old.document_type) or app.is_patient_photo_type(new.document_type)) then
    raise exception 'the document type of a photo cannot be corrected' using errcode = '22023';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.guard_questionnaire_definition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'questionnaire definitions are immutable' using errcode = '23514';
end;
$$;

CREATE FUNCTION app.guard_questionnaire_response() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if app.patient_merge_active()
     and app.only_patient_id_changed(to_jsonb(new), to_jsonb(old)) then
    return new;
  end if;
  if old.status = 'abgeschlossen' then
    raise exception 'questionnaire response is completed' using errcode = '23514';
  end if;
  if new.organization_id <> old.organization_id
     or new.patient_id <> old.patient_id
     or new.instrument_id <> old.instrument_id
     or new.definition_version <> old.definition_version
     or new.supersedes_response_id is distinct from old.supersedes_response_id then
    raise exception 'questionnaire response identity is fixed' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.guard_therapy_report_correction() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.supersedes_report_id is distinct from old.supersedes_report_id
     or new.change_reason is distinct from old.change_reason then
    raise exception 'therapy report correction is fixed' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.guard_training_protocol_addendum() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'training protocol addenda are immutable' using errcode = '23514';
end;
$$;

