CREATE FUNCTION app.habits_json(p_kind text, p_relationship_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', h.id,
    'action', h.action,
    'cue', h.cue,
    'place', h.place,
    'starts_on', h.starts_on,
    'created_at', h.created_at,
    'paused', h.paused_at is not null,
    'paused_at', h.paused_at,
    'paused_by_kind', h.paused_by_kind,
    'ended_at', h.ended_at,
    'marks', coalesce((
      select jsonb_agg(m.done_on order by m.done_on desc)
      from public.habit_marks m where m.habit_id = h.id
    ), '[]'::jsonb),
    -- Zweitreview S1: die Tage, die eine rechtliche Vertretung vermerkt hat,
    -- wie recorded_by_kind am Check-in.
    'marks_by_representative', coalesce((
      select jsonb_agg(m.done_on order by m.done_on desc)
      from public.habit_marks m
      where m.habit_id = h.id and m.platform_access_kind = 'legal_representative'
    ), '[]'::jsonb)
  ) order by h.ended_at is not null, h.created_at), '[]'::jsonb)
  from public.habits h
  where h.relationship_kind = p_kind and h.relationship_id = p_relationship_id
$$;

COMMENT ON FUNCTION app.habits_json(p_kind text, p_relationship_id uuid) IS 'ALT-003: Gewohnheiten eines Verhaeltnisses mit den vermerkten Tagen (juengster zuerst), laufende vor beendeten. Ohne Rechtepruefung: nur aus get_checkins, export_patient_record und platform_habits.';

