CREATE FUNCTION app.iban_checksum_ok(p_iban text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_iban       text;
  v_umgestellt text;
  v_zeichen    text;
  v_rest       integer := 0;
  v_stelle     integer;
  i            integer;
begin
  if p_iban is null then
    return false;
  end if;

  -- Dieselbe Normalisierung wie beim Schreiben: auf dem Papier steht die
  -- IBAN mit Leerzeichen, in der Datenbank ohne.
  v_iban := upper(replace(btrim(p_iban), ' ', ''));

  if v_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$' then
    return false;
  end if;

  -- Die ersten vier Zeichen wandern ans Ende, Buchstaben werden zu Zahlen
  -- (A = 10 ... Z = 35).
  v_umgestellt := substring(v_iban from 5) || substring(v_iban from 1 for 4);

  for i in 1..length(v_umgestellt) loop
    v_zeichen := substring(v_umgestellt from i for 1);

    if v_zeichen between '0' and '9' then
      v_rest := (v_rest * 10 + v_zeichen::integer) % 97;
    else
      v_stelle := ascii(v_zeichen) - 55;
      v_rest := (v_rest * 100 + v_stelle) % 97;
    end if;
  end loop;

  return v_rest = 1;
end;
$_$;

COMMENT ON FUNCTION app.iban_checksum_ok(p_iban text) IS 'Prueft eine IBAN nach ISO 13616 (mod 97 == 1) einschliesslich ihrer Form (R3-010). Null und jede Zeichenkette, die der Form nicht entspricht, gelten als nicht in Ordnung.';

CREATE FUNCTION app.import_exercise_catalog_for(p_org uuid, p_actor uuid, p_entries jsonb, p_feste_kennungen boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_eintraege   jsonb := '[]'::jsonb;
  v_schluessel  text[] := '{}';
  v_e           jsonb;
  v_neu         jsonb;
  v_uebernommen text[] := '{}';
  v_vorhanden   text[] := '{}';
  v_konflikte   jsonb := '[]'::jsonb;
  v_uebung      uuid;
  v_variante    uuid;
begin
  if p_org is null or p_actor is null then
    raise exception 'organization and actor are required' using errcode = '22023';
  end if;
  if p_entries is null or jsonb_typeof(p_entries) <> 'array'
     or jsonb_array_length(p_entries) = 0 then
    raise exception 'catalog is empty or invalid' using errcode = '22023';
  end if;
  if jsonb_array_length(p_entries) > 500 or octet_length(p_entries::text) > 2000000 then
    raise exception 'catalog is too large' using errcode = '22023';
  end if;

  for v_e in select value from jsonb_array_elements(p_entries) loop
    v_neu := app.exercise_catalog_entry(v_e);
    if (v_neu ->> 'catalog_key') = any (v_schluessel) then
      raise exception 'catalog key % is duplicated', v_neu ->> 'catalog_key' using errcode = '22023';
    end if;
    v_schluessel := v_schluessel || (v_neu ->> 'catalog_key');
    v_eintraege := v_eintraege || jsonb_build_array(v_neu);
  end loop;

  -- Zwei Uebernahmen derselben Praxis zugleich laufen nacheinander.
  perform pg_advisory_xact_lock(hashtext('exercise_catalog_import'), hashtext(p_org::text));

  for v_neu in select value from jsonb_array_elements(v_eintraege) loop
    if exists (
      select 1 from public.exercise_variants v
      where v.organization_id = p_org and v.catalog_key = v_neu ->> 'catalog_key'
    ) then
      v_vorhanden := v_vorhanden || (v_neu ->> 'catalog_key');
      continue;
    end if;
    if exists (
      select 1 from public.exercises e
      where e.organization_id = p_org and lower(btrim(e.name)) = lower(v_neu ->> 'name')
    ) then
      v_konflikte := v_konflikte || jsonb_build_array(jsonb_build_object(
        'catalog_key', v_neu ->> 'catalog_key', 'name', v_neu ->> 'name'));
      continue;
    end if;

    -- ANN-380: Feste Kennungen nur fuer den Seed - derselbe Stand nach jedem Aufsetzen.
    v_uebung := case when p_feste_kennungen
                  then md5(p_org::text || ':uebung:' || (v_neu ->> 'catalog_key'))::uuid
                  else extensions.gen_random_uuid() end;
    v_variante := case when p_feste_kennungen
                    then md5(p_org::text || ':variante:' || (v_neu ->> 'catalog_key'))::uuid
                    else extensions.gen_random_uuid() end;

    insert into public.exercises (
      id, organization_id, name, lay_name, body_region, created_by, updated_by
    )
    values (
      v_uebung, p_org, v_neu ->> 'name', v_neu ->> 'lay_name', v_neu ->> 'body_region',
      p_actor, p_actor
    );
    insert into public.exercise_variants (
      id, organization_id, exercise_id, name, lay_name, instruction, equipment,
      common_faults, practice_notes, catalog_key, catalog_version, goal,
      starting_position, level, default_dosage, illustration, created_by, updated_by
    )
    values (
      v_variante, p_org, v_uebung, v_neu ->> 'name', v_neu ->> 'lay_name',
      v_neu ->> 'instruction',
      array(select jsonb_array_elements_text(v_neu -> 'equipment')),
      v_neu ->> 'common_faults', v_neu ->> 'practice_notes',
      v_neu ->> 'catalog_key', v_neu ->> 'catalog_version', v_neu ->> 'goal',
      v_neu ->> 'starting_position', (v_neu ->> 'level')::smallint,
      v_neu -> 'default_dosage', nullif(v_neu -> 'illustration', 'null'::jsonb),
      p_actor, p_actor
    );
    v_uebernommen := v_uebernommen || (v_neu ->> 'catalog_key');
  end loop;

  return jsonb_build_object(
    'imported', to_jsonb(v_uebernommen),
    'skipped', to_jsonb(v_vorhanden),
    'conflicts', v_konflikte
  );
end;
$$;

COMMENT ON FUNCTION app.import_exercise_catalog_for(p_org uuid, p_actor uuid, p_entries jsonb, p_feste_kennungen boolean) IS 'UEB-012 (ANN-382): uebernimmt Katalogeintraege in die Bibliothek einer Organisation - erst alles pruefen, dann je Eintrag Uebung und Variante; vorhandene catalog_key ueberspringen, Namenskonflikte melden, nie ueberschreiben. Intern: fuer Seed, public.import_exercise_catalog und public.add_catalog_exercises_for_plan (dort nur fuer owner, ANN-293); fuer keine Anwendungsrolle ausfuehrbar; security invoker, weil sie selbst keine Rolle prueft.';

CREATE FUNCTION app.import_food_catalog_batch(p_source text, p_version text, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  if p_source not in ('bls', 'off') or p_version is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid import' using errcode = '22023';
  end if;
  insert into public.food_catalog as c (
    source, source_code, name, brand, base_unit, energy_kcal, protein_g, fat_g, carbohydrate_g,
    sugar_g, fibre_g, saturated_fat_g, salt_g, portions, source_version, imported_at, retired_at
  )
  select p_source, r.source_code, btrim(r.name), nullif(btrim(r.brand), ''),
         coalesce(r.base_unit, 'g'), r.energy_kcal, r.protein_g, r.fat_g, r.carbohydrate_g,
         r.sugar_g, r.fibre_g, r.saturated_fat_g, r.salt_g, coalesce(r.portions, '[]'::jsonb),
         p_version, now(), null
  from jsonb_to_recordset(p_rows) as r(
    source_code text, name text, brand text, base_unit text, energy_kcal numeric,
    protein_g numeric, fat_g numeric, carbohydrate_g numeric, sugar_g numeric, fibre_g numeric,
    saturated_fat_g numeric, salt_g numeric, portions jsonb)
  on conflict (source, source_code) do update set
    name = excluded.name, brand = excluded.brand, base_unit = excluded.base_unit,
    energy_kcal = excluded.energy_kcal, protein_g = excluded.protein_g, fat_g = excluded.fat_g,
    carbohydrate_g = excluded.carbohydrate_g, sugar_g = excluded.sugar_g,
    fibre_g = excluded.fibre_g, saturated_fat_g = excluded.saturated_fat_g,
    salt_g = excluded.salt_g, portions = excluded.portions,
    source_version = excluded.source_version, imported_at = excluded.imported_at,
    retired_at = null;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.import_food_catalog_batch(p_source text, p_version text, p_rows jsonb) IS 'ERN-004 (ANN-659): ein Stapel des Imports - fügt ein oder aktualisiert je Quelle und Schlüssel, holt Zurückgezogenes zurück. Allein für den Betrieb (scripts/lebensmittel/laden.mjs); kein Recht für die Anwendung.';

CREATE FUNCTION app.intake_checklist(p_org uuid, p_patient_id uuid) RETURNS TABLE(item text, state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- ANN-143 (unveraendert): Verordnungsfoto. Erledigt mit einem Scan an der
  -- Person (auch einem noch nicht zugeordneten). Entfaellt, wenn alle
  -- Grundlagen Selbstzahler sind - dann gibt es kein Blatt.
  select 'prescription_photo',
         case
           when exists (
             select 1 from public.patient_files f
             where f.patient_id = p_patient_id and f.organization_id = p_org
               and f.document_type = 'verordnungsscan' and f.status = 'ready'
           ) then 'done'
           when exists (
             select 1 from public.treatment_bases tb
             where tb.patient_id = p_patient_id and tb.organization_id = p_org
           ) and not exists (
             select 1 from public.treatment_bases tb
             where tb.patient_id = p_patient_id and tb.organization_id = p_org
               and tb.treatment_basis_kind <> 'self_pay'
           ) then 'not_needed'
           else 'open'
         end
  union all
  -- ANN-227: Anmeldebogen - das Foto des unterschriebenen Blatts (Art
  -- 'vertrag'). Bestand: die beiden Vermerke aus ANN-224 genuegen weiter.
  select 'registration_form',
         case
           when exists (
             select 1 from public.patient_files f
             where f.patient_id = p_patient_id and f.organization_id = p_org
               and f.document_type = 'vertrag' and f.status = 'ready'
           ) then 'done'
           when exists (
             select 1 from public.patient_privacy_records v
             where v.patient_id = p_patient_id and v.organization_id = p_org
               and v.record_kind = 'privacy_notice_handed_out'
           ) and exists (
             select 1 from public.patient_privacy_records v
             where v.patient_id = p_patient_id and v.organization_id = p_org
               and v.record_kind = 'treatment_contract_signed'
           ) then 'done'
           else 'open'
         end
$$;

COMMENT ON FUNCTION app.intake_checklist(p_org uuid, p_patient_id uuid) IS 'Die zwei Punkte der Erstaufnahme einer Person, abgeleitet aus der Akte (AKTE-007, ANN-224, ANN-227): Verordnungsfoto und Anmeldebogen (Foto des Blatts als Datei der Art vertrag, im Bestand auch die beiden Vermerke); done, open oder not_needed. Keine Pruefung der Rolle - das tun die Aufrufer.';

CREATE FUNCTION app.invoice_cancellations_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'a cancellation document cannot be changed' using errcode = '23514';
end;
$$;

COMMENT ON FUNCTION app.invoice_cancellations_frozen() IS 'Haelt ein Stornodokument unveraenderlich (ABR-003c, ADR-009 Punkt 9). Ein Storno wird nicht zurueckgenommen - eine irrtuemlich stornierte Rechnung wird als Korrekturrechnung neu ausgestellt.';

CREATE FUNCTION app.invoice_item_area_from_service() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_area     text;
  v_patient  uuid;
  v_training uuid;
begin
  select b.service_area, b.patient_id, b.training_relationship_id
    into v_area, v_patient, v_training
  from public.billable_services b
  where b.id = new.billable_service_id;

  if v_area is null then
    return new;
  end if;

  if new.service_area is not null and new.service_area is distinct from v_area then
    raise exception 'service area % does not match the billable service (%)', new.service_area, v_area
      using errcode = '23514';
  end if;

  new.service_area := v_area;

  -- TRN-008: dieselbe Person in beiden Spalten.
  if exists (
    select 1 from public.invoices i
    where i.id = new.invoice_id
      and (i.patient_id is distinct from v_patient
           or i.training_relationship_id is distinct from v_training)
  ) then
    raise exception 'billable service does not belong to the relationship of its invoice'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.invoice_item_area_from_service() IS 'Setzt den Leistungsbereich einer Rechnungszeile aus ihrer Leistung (ABR-009) und weist eine Leistung ab, die an einem anderen Verhaeltnis haengt als ihre Rechnung (TRN-008). Am Trigger, damit jeder Schreibweg ihn traegt; ob der Bereich zur Rechnung passt, entscheidet danach der Fremdschluessel.';

CREATE FUNCTION app.invoice_item_not_from_open_cancellation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_neu    record;
  v_storno uuid;
begin
  select i.* into v_neu from public.invoices i where i.id = new.invoice_id;

  -- Ausgestellte Rechnungen haelt invoice_items_frozen fest.
  if not found or v_neu.status <> 'draft' then
    return new;
  end if;

  v_storno := app.open_cancellation_holding_service(
    new.billable_service_id, v_neu.patient_id, v_neu.training_relationship_id,
    v_neu.service_area, v_neu.treatment_basis_id, v_neu.period_month,
    v_neu.replaces_invoice_id
  );

  if v_storno is not null then
    raise exception 'services of a cancelled invoice are billed on its correction (create_correction_draft)'
      using errcode = '23514', detail = v_storno::text;
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.invoice_item_not_from_open_cancellation() IS 'UX-008b (BEF-062): Eine Leistung aus einer stornierten Rechnung derselben Klammer ohne Korrektur kommt nur auf deren Korrekturrechnung (ADR-009 Punkt 9, ANN-079, ANN-321). Die Kennung der stornierten Rechnung steht im DETAIL der Meldung.';

CREATE FUNCTION app.invoice_items_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_status text;
begin
  select i.status into v_status
  from public.invoices i
  where i.id = new.invoice_id;

  if v_status = 'issued' then
    -- Die Freigabe durch das Storno: nur beim Aendern, nur in eine Richtung,
    -- und nur wenn keine andere Spalte sich bewegt.
    if tg_op = 'UPDATE'
       and old.released_at is null
       and new.released_at is not null
       and new.id = old.id
       and new.organization_id = old.organization_id
       and new.invoice_id = old.invoice_id
       and new.billable_service_id = old.billable_service_id
       and new.sort_order = old.sort_order
       and new.service_area = old.service_area then
      return new;
    end if;

    raise exception 'the items of an issued invoice cannot be changed' using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.invoice_items_frozen() IS 'Haelt die Zeilen einer ausgestellten Rechnung unveraenderlich (ADR-009 Punkt 9). Einzige Ausnahme seit ABR-003c: Das Storno setzt released_at und loest damit die Sperre gegen Doppelabrechnung; die Zeile selbst aendert sich dabei nicht - seit ABR-009 auch ihr Leistungsbereich nicht. Das Loeschen bleibt dem Loeschlauf moeglich (ADR-008).';

CREATE FUNCTION app.invoice_number_prefix(p_organization_id uuid, p_service_area text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_service_area
           when 'training' then b.training_invoice_number_prefix
           else b.invoice_number_prefix
         end
  from public.practice_billing_profiles b
  where b.organization_id = p_organization_id
$$;

COMMENT ON FUNCTION app.invoice_number_prefix(p_organization_id uuid, p_service_area text) IS 'Das Kuerzel des Nummernkreises eines Leistungsbereichs (ABR-010, ADR-009 Punkt 17). Die eine Stelle, die die Zuordnung kennt; null heisst, dass keine Praxis-Stammdaten hinterlegt sind.';

CREATE FUNCTION app.invoice_paid_cents(p_invoice_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(sum(
           case when p.direction = 'incoming' then p.amount_cents else -p.amount_cents end
         ), 0)::integer
  from public.payments p
  where p.invoice_id = p_invoice_id
    and p.voided_at is null
$$;

COMMENT ON FUNCTION app.invoice_paid_cents(p_invoice_id uuid) IS 'Bezahlter Betrag einer Rechnung in Cent: Eingaenge minus Rueckzahlungen, stornierte Zahlungen ausgenommen (ABR-004). Die eine Stelle, an der diese Summe entsteht.';

CREATE FUNCTION app.invoice_party_matches_items() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from public.invoice_items it
    join public.billable_services b on b.id = it.billable_service_id
    where it.invoice_id = new.id
      and (b.patient_id is distinct from new.patient_id
           or b.training_relationship_id is distinct from new.training_relationship_id)
  ) then
    raise exception 'billable service does not belong to the relationship of its invoice'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.invoice_party_matches_items() IS 'Weist das Umhaengen einer Rechnung an ein anderes Verhaeltnis ab, solange ihre Zeilen an Leistungen des bisherigen haengen (TRN-008, Zweitreview).';

CREATE FUNCTION app.invoice_payment_reminders_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'a payment reminder cannot be changed' using errcode = '23514';
end;
$$;

COMMENT ON FUNCTION app.invoice_payment_reminders_frozen() IS 'Haelt eine ausgestellte Zahlungserinnerung unveraenderlich (ABR-003d). Wer eine falsche Angabe verschickt hat, schreibt die naechste Erinnerung - eine Stufe entsteht dadurch nicht.';

CREATE FUNCTION app.invoice_payment_state(p_total_cents integer, p_paid_cents integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
           when p_paid_cents > p_total_cents  then 'overpaid'
           when p_paid_cents >= p_total_cents then 'paid'
           when p_paid_cents <= 0             then 'unpaid'
           else 'partially_paid'
         end
$$;

COMMENT ON FUNCTION app.invoice_payment_state(p_total_cents integer, p_paid_cents integer) IS 'Zahlungsstand einer Rechnung aus Betrag und bezahlter Summe: unpaid, partially_paid, paid, overpaid (ABR-004, ADR-009 Punkt 7 als abgeleiteter Wert). "ueberfaellig" steht daneben und haengt am Faelligkeitsdatum.';

-- ANN-339
CREATE FUNCTION app.invoice_recipient_name(p_status text, p_snapshot jsonb, p_live_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- BEF-141: ausgestellt -> wie auf dem Blatt; sonst live. Jeder Snapshot
  -- traegt `recipient.name`; fehlte er doch, lieber der heutige als keiner.
  select case when p_status = 'issued'
              then coalesce(p_snapshot -> 'recipient' ->> 'name', p_live_name)
              else p_live_name end;
$$;

COMMENT ON FUNCTION app.invoice_recipient_name(p_status text, p_snapshot jsonb, p_live_name text) IS 'BEF-141: Name des Rechnungsempfaengers fuer Listen - bei ausgestellten Rechnungen aus dem Snapshot (ADR-009 Punkt 10), am Entwurf live.';

CREATE FUNCTION app.invoice_reminder_due(p_invoice_id uuid, p_due_on date, p_outstanding integer, p_today date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_outstanding, 0) > 0
     and p_due_on < p_today
     and not exists (
       select 1
       from public.invoice_payment_reminders r
       where r.invoice_id = p_invoice_id
         and r.due_on >= p_today
     )
$$;

COMMENT ON FUNCTION app.invoice_reminder_due(p_invoice_id uuid, p_due_on date, p_outstanding integer, p_today date) IS 'B1 (BEF-151, ANN-516): Eine ausgestellte Rechnung ist zu mahnen, wenn etwas offen ist, das Zahlungsziel verstrichen ist und keine Zahlungserinnerung eine noch laufende Frist gesetzt hat. Keine Stufe, keine Gebuehr (ANN-080).';

CREATE FUNCTION app.invoice_shows_diagnosis() RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- ANN-229: true = die Diagnose der Verordnung steht auf der Rechnung.
  select true
$$;

COMMENT ON FUNCTION app.invoice_shows_diagnosis() IS 'Schalter fuer ANN-229: Steht die Diagnose der Verordnung (ICD-10 und Text) auf der Rechnung? Einzige Stelle; false stellt den Stand vor schema_version 4 her.';

CREATE FUNCTION app.invoices_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status = 'issued' then
    -- PRX-017: Die ausgestellte Rechnung wandert, ihr Inhalt nicht.
    if app.patient_merge_active()
       and app.only_patient_id_changed(to_jsonb(new), to_jsonb(old)) then
      return new;
    end if;
    raise exception 'an issued invoice cannot be changed' using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.invoices_frozen() IS 'Haelt eine ausgestellte Rechnung unveraenderlich (ADR-009 Punkt 9). Korrekturen laufen ueber Storno und Neuausstellung (ABR-EPIC-002b). Das Loeschen bleibt dem Loeschlauf moeglich (ADR-008).';

CREATE FUNCTION app.is_assignable_therapist(p_staff_member_id uuid, p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.staff_members sm
    where sm.id = p_staff_member_id
      and sm.organization_id = p_organization_id
      and sm.employment_status = 'active'
      and (
        -- ANN-226: von owner in den Kalender genommen, ohne Zugang.
        sm.schedulable_treatment
        -- Bisheriger Weg (CAL-001): aktiver Zugang mit therapeutischer Rolle.
        or exists (
          select 1
          from public.user_profiles up
          join public.user_roles ur
            on ur.user_id = up.id
           and ur.organization_id = up.organization_id
          where up.person_id = sm.person_id
            and up.organization_id = sm.organization_id
            and up.is_active
            and ur.role_key in ('therapist', 'team_lead')
        )
      )
  )
$$;

COMMENT ON FUNCTION app.is_assignable_therapist(p_staff_member_id uuid, p_organization_id uuid) IS 'Prueft, ob ein staff_member als behandelnde Person zuordenbar ist (CAL-001, AKTE-009): aktiv beschaeftigt und entweder von owner in den Kalender genommen (schedulable_treatment, ANN-226) oder mit aktivem Zugang in der Rolle therapist oder team_lead. Nur fuer die serverseitigen Schreib- und Lesepfade.';

CREATE FUNCTION app.is_assignable_trainer(p_staff_member_id uuid, p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.staff_members sm
    where sm.id = p_staff_member_id
      and sm.organization_id = p_organization_id
      and sm.employment_status = 'active'
      and (
        -- ANN-226: von owner in den Kalender genommen, ohne Zugang.
        sm.schedulable_training
        -- Bisheriger Weg (TRN-004, ANN-176): aktiver Zugang mit Rolle trainer.
        or exists (
          select 1
          from public.user_profiles up
          join public.user_roles ur
            on ur.user_id = up.id
           and ur.organization_id = up.organization_id
          where up.person_id = sm.person_id
            and up.organization_id = sm.organization_id
            and up.is_active
            and ur.role_key = 'trainer'
        )
      )
  )
$$;

COMMENT ON FUNCTION app.is_assignable_trainer(p_staff_member_id uuid, p_organization_id uuid) IS 'Wer einen Trainingstermin betreuen kann (TRN-004, AKTE-009): aktiv beschaeftigt und entweder von owner in den Kalender genommen (schedulable_training, ANN-226) oder mit aktivem Zugang in der Rolle trainer.';

CREATE FUNCTION app.is_late_cancellation(p_reason text, p_received_at timestamp with time zone, p_starts_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    p_reason in ('patient_request', 'patient_moved')
    and p_received_at is not null
    and p_starts_at - p_received_at < app.cancellation_notice_period()
$$;

COMMENT ON FUNCTION app.is_late_cancellation(p_reason text, p_received_at timestamp with time zone, p_starts_at timestamp with time zone) IS 'Loest diese Absage eine Ausfallgebuehr aus? Weniger als 24 Stunden zwischen Eingang und vereinbartem Beginn, und nur, wenn die Patient:in abgesagt oder verlegt hat (CAL-014b, ABN-006, ANN-047 Fassung 2).';

CREATE FUNCTION app.is_on_appointment_grid(p_start time without time zone, p_minutes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_start is not null
     and p_minutes is not null
     and date_part('second', p_start) = 0
     and (date_part('hour', p_start) * 60 + date_part('minute', p_start))::integer % p_minutes = 0
$$;

COMMENT ON FUNCTION app.is_on_appointment_grid(p_start time without time zone, p_minutes integer) IS 'Prueft eine Ortszeit gegen das Praxisraster - Minuten seit Mitternacht der Praxiszeitzone (CAL-005).';

CREATE FUNCTION app.is_patient_photo_type(p_document_type text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_document_type in ('patientenfoto', 'dokumentationsfoto'), false)
$$;

COMMENT ON FUNCTION app.is_patient_photo_type(p_document_type text) IS 'Ist die Art ein Foto der Person - Arbeitshilfe (patientenfoto) oder Dokumentationsfoto (ADR-017 Punkt 43)? Beide entstehen nur im Kameradialog, sind nur JPEG, haengen an der Patient:in, haben keine Artkorrektur und keinen Download.';

CREATE FUNCTION app.is_platform_account(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.platform_accesses a where a.account_user_id = p_user)
      or exists (
           select 1 from auth.users u
           where u.id = p_user
             and coalesce(u.raw_app_meta_data ->> 'platform_account', '') = 'true'
         )
$$;

CREATE FUNCTION app.is_practice_account() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.has_any_role('owner', 'therapist', 'team_lead', 'office', 'trainer')
$$;

COMMENT ON FUNCTION app.is_practice_account() IS 'Aktives Profil mit mindestens einer Praxisrolle (ADR-023 Punkt 2). Plattformkonten haben weder Profil noch Rolle.';

CREATE FUNCTION app.is_public_holiday(p_date date, p_state text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_ostern date := app.easter_sunday(extract(year from p_date)::integer);
  v_md     text := to_char(p_date, 'MM-DD');
begin
  return v_md in ('01-01', '05-01', '10-03', '11-01', '12-25', '12-26')
      or (p_state = 'BW' and v_md = '01-06')
      or p_date in (v_ostern - 2, v_ostern + 1, v_ostern + 39, v_ostern + 50, v_ostern + 60);
end;
$$;

COMMENT ON FUNCTION app.is_public_holiday(p_date date, p_state text) IS 'URL-001 (ANN-577): ob ein Tag in BW oder NW gesetzlicher Feiertag ist. Dieselbe Liste wie src/features/vacation/feiertage.ts.';

CREATE FUNCTION app.is_staff() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.has_any_role('owner', 'therapist', 'team_lead', 'office')
$$;

-- ANN-037
CREATE FUNCTION app.is_valid_treatment_length(p_laenge interval, p_grid integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_laenge is not null
     and p_grid is not null
     and p_laenge >= make_interval(mins => p_grid)
     and extract(epoch from p_laenge)::numeric % (p_grid * 60) = 0
$$;

COMMENT ON FUNCTION app.is_valid_treatment_length(p_laenge interval, p_grid integer) IS 'Ist diese Laenge fuer einen BEHANDLUNGSTERMIN zulaessig? Mindestens ein Rasterschritt und ein ganzes Vielfaches davon; eine Obergrenze oder feste Werte gibt es seit PROJECT_PRINCIPLES.md 0.11 Abschnitt 8.1 nicht mehr (CAL-020, ANN-056).';

CREATE FUNCTION app.is_within_working_hours(p_staff_member_id uuid, p_organization_id uuid, p_date date, p_start time without time zone, p_end time without time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_abweichungen integer;
  v_abwesend     boolean;
  v_bereiche     app.timemultirange;
begin
  select count(*), bool_or(a.kind = 'unavailable')
    into v_abweichungen, v_abwesend
  from public.staff_working_hour_exceptions a
  where a.staff_member_id = p_staff_member_id
    and a.organization_id = p_organization_id
    and a.on_date = p_date;

  if v_abweichungen > 0 then
    -- Der Tag ist abweichend geregelt; der Wochenplan gilt fuer ihn nicht.
    if v_abwesend then
      return false;
    end if;

    select range_agg(app.timerange(a.starts_at, a.ends_at, '[)'))
      into v_bereiche
    from public.staff_working_hour_exceptions a
    where a.staff_member_id = p_staff_member_id
      and a.organization_id = p_organization_id
      and a.on_date = p_date
      and a.kind = 'block';
  else
    select range_agg(w.zeitraum)
      into v_bereiche
    from (
      select app.timerange(h.starts_at, h.ends_at, '[)') as zeitraum
      from public.staff_working_hours h
      where h.staff_member_id = p_staff_member_id
        and h.organization_id = p_organization_id
        and h.weekday = extract(isodow from p_date)
        and daterange(h.valid_from, h.valid_until, '[]') @> p_date
    ) w;
  end if;

  if v_bereiche is null then
    return false;
  end if;

  return v_bereiche @> app.timerange(p_start, p_end, '[)');
end;
$$;

COMMENT ON FUNCTION app.is_within_working_hours(p_staff_member_id uuid, p_organization_id uuid, p_date date, p_start time without time zone, p_end time without time zone) IS 'Prueft, ob ein Zeitraum vollstaendig durch die Arbeitszeit der Person gedeckt ist. Datumsbezogene Abweichungen ersetzen den Wochenplan; sonst gilt die Fassung des Tages (AZ-001). Ohne hinterlegte Arbeitszeit false (CAL-005).';

CREATE FUNCTION app.issue_platform_invitation(p_org uuid, p_access_id uuid, p_purpose text, p_actor uuid) RETURNS TABLE(invitation_id uuid, code text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_code    text;
  v_expires timestamptz;
  v_inv     uuid;
begin
  update public.platform_access_invitations i
     set status = 'revoked', revoked_at = now()
   where i.platform_access_id = p_access_id and i.status = 'pending';

  v_code := translate(encode(extensions.gen_random_bytes(24), 'base64'), '+/', '-_');
  v_expires := now() + app.platform_invitation_validity();

  insert into public.platform_access_invitations (
    organization_id, platform_access_id, purpose, channel, code_hash, expires_at, created_by
  )
  values (p_org, p_access_id, p_purpose, 'on_site', app.platform_code_hash(v_code), v_expires, p_actor)
  returning id into v_inv;

  return query select v_inv, v_code, v_expires;
end;
$$;

-- ANN-703
CREATE FUNCTION app.journal_patient_file_deletion(p_organization_id uuid, p_file_id uuid, p_document_type text) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  values (
    p_organization_id, extensions.gen_random_uuid(), 'patient_files', p_file_id,
    case when p_document_type = 'patientenfoto' then 'patientenfoto' else 'patientenakte' end,
    now()
  )
$$;

COMMENT ON FUNCTION app.journal_patient_file_deletion(p_organization_id uuid, p_file_id uuid, p_document_type text) IS 'BEF-170: Eintrag im Loeschjournal fuer eine einzeln geloeschte Datei der Akte (ADR-008 Punkt 8, ADR-017 Punkt 26). Klasse patientenfoto fuer die Foto-Arbeitshilfe, sonst patientenakte; faellig mit der Loeschung. Nicht fuer Clients.';

CREATE FUNCTION app.jwt_last_authentication() RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_amr jsonb := auth.jwt() -> 'amr';
begin
  if v_amr is null or jsonb_typeof(v_amr) <> 'array' then
    return null;
  end if;
  -- Nur Anmeldungen mit einem ersten Faktor zählen; ein zweiter Faktor
  -- (`totp`, `phone`, `webauthn`) nicht (Zweitreview SEC-EPIC-001). Der
  -- Passkey (`passkey`) steht in app.jwt_passkey_authentication() und zählt
  -- nur, wenn er freigegeben ist (SEC-009, ANN-329).
  return (
    select to_timestamp(max((e ->> 'timestamp')::double precision))
    from jsonb_array_elements(v_amr) e
    where jsonb_typeof(e) = 'object'
      and jsonb_typeof(e -> 'timestamp') = 'number'
      and e ->> 'method' in (
        'password', 'otp', 'magiclink', 'recovery', 'invite', 'email/signup', 'oauth', 'sso/saml'
      )
  );
end;
$$;

COMMENT ON FUNCTION app.jwt_last_authentication() IS 'Jüngster Zeitstempel einer Anmeldung mit erstem Faktor im Claim amr, ohne Passkey (ADR-025 Punkt 1). Der Passkey zählt über app.last_first_factor() nur freigegeben.';

CREATE FUNCTION app.jwt_passkey_authentication() RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_amr jsonb := auth.jwt() -> 'amr';
begin
  if v_amr is null or jsonb_typeof(v_amr) <> 'array' then
    return null;
  end if;
  return (
    select to_timestamp(max((e ->> 'timestamp')::double precision))
    from jsonb_array_elements(v_amr) e
    where jsonb_typeof(e) = 'object'
      and jsonb_typeof(e -> 'timestamp') = 'number'
      and e ->> 'method' = 'passkey'
  );
end;
$$;

CREATE FUNCTION app.jwt_session_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  return nullif(auth.jwt() ->> 'session_id', '')::uuid;
exception when invalid_text_representation then
  return null;
end;
$$;

COMMENT ON FUNCTION app.jwt_session_id() IS 'Claim session_id des Tokens; null, wenn er fehlt oder keine UUID ist (ADR-025).';

CREATE FUNCTION app.last_first_factor() RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select greatest(
    app.jwt_last_authentication(),
    case when app.passkey_counts(p.zeitpunkt) then p.zeitpunkt end
  )
  from (select app.jwt_passkey_authentication() as zeitpunkt) p
$$;

COMMENT ON FUNCTION app.last_first_factor() IS 'Jüngste echte Anmeldung der laufenden Sitzung: erster Faktor aus amr oder Passkey, wenn dieser freigegeben ist (ANN-329). Eine Freigabe per PIN zählt nicht.';

CREATE FUNCTION app.leave_balance(p_org uuid, p_staff_member_id uuid, p_year integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with anspruch as (
    select e.days, e.carryover_days
    from public.staff_leave_entitlements e
    where e.organization_id = p_org and e.staff_member_id = p_staff_member_id and e.year = p_year
  ),
  tage as (
    select r.status,
           case when extract(year from r.starts_on)::integer = p_year
                then r.days - r.days_following_year
                else r.days_following_year end as tage
    from public.staff_leave_requests r
    where r.organization_id = p_org
      and r.staff_member_id = p_staff_member_id
      and r.kind = 'leave'
      and r.status in ('approved', 'requested')
      and (extract(year from r.starts_on)::integer = p_year
           or extract(year from r.ends_on)::integer = p_year)
  )
  select jsonb_build_object(
    'year', p_year,
    'entitlement', (select a.days from anspruch a),
    'carryover', (select a.carryover_days from anspruch a),
    'approved', coalesce((select sum(t.tage) from tage t where t.status = 'approved'), 0),
    'requested', coalesce((select sum(t.tage) from tage t where t.status = 'requested'), 0),
    'rest', (select a.days + a.carryover_days from anspruch a)
              - coalesce((select sum(t.tage) from tage t where t.status = 'approved'), 0)
  )
$$;

CREATE FUNCTION app.leave_days(p_org uuid, p_staff_member_id uuid, p_from date, p_to date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with tage as (
    select d::date as tag
    from generate_series(p_from, p_to, interval '1 day') as d
  )
  select count(*)::integer
  from tage t
  cross join (select o.federal_state from public.organizations o where o.id = p_org) as o
  where not app.is_public_holiday(t.tag, o.federal_state)
    and (
      exists (
        select 1 from public.staff_working_hours w
        where w.organization_id = p_org and w.staff_member_id = p_staff_member_id
          and w.weekday = extract(isodow from t.tag)
          and daterange(w.valid_from, w.valid_until, '[]') @> t.tag
      )
      or (
        not exists (
          select 1 from public.staff_working_hours w
          where w.organization_id = p_org and w.staff_member_id = p_staff_member_id
            and daterange(w.valid_from, w.valid_until, '[]') @> t.tag
        )
        and extract(isodow from t.tag) <= 5
      )
    )
$$;

COMMENT ON FUNCTION app.leave_days(p_org uuid, p_staff_member_id uuid, p_from date, p_to date) IS 'URL-001 (ANN-577), AZ-001: Urlaubstage eines Zeitraums - Arbeitstage nach der an jedem Tag geltenden Fassung des Wochenplans (ohne Plan Mo-Fr), ohne gesetzliche Feiertage des Bundeslands der Praxis.';

CREATE FUNCTION app.leer_zu_null(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(btrim(p_text), '')
$$;

CREATE FUNCTION app.log_platform_access_event(p_org uuid, p_actor uuid, p_actor_kind text, p_action text, p_access_id uuid, p_context jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- LOG-EPIC-001: Die Akte steht im Kontext, damit Auskunft (Art. 15) und
  -- Legal Hold den Eintrag finden; im Training bleibt sie leer.
  insert into public.audit_log (
    organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
  )
  select p_org, p_actor, p_actor_kind, p_action, 'platform_access', p_access_id, 'success',
         coalesce(p_context, '{}'::jsonb)
           || case when a.patient_id is null then '{}'::jsonb
                   else jsonb_build_object('patient_id', a.patient_id) end
  from (select (select x.patient_id from public.platform_accesses x where x.id = p_access_id) as patient_id) a
$$;

CREATE FUNCTION app.log_platform_representation(p_access_id uuid, p_action text, p_context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang record;
begin
  select a.* into v_zugang
  from public.platform_accesses a
  where a.id = p_access_id
    and a.access_kind <> 'self'
    and a.account_user_id is not null;
  if not found then
    return;
  end if;

  perform app.log_record_access(
    v_zugang.organization_id, v_zugang.account_user_id, p_action,
    case v_zugang.relationship_kind when 'treatment' then 'patient' else 'training_relationship' end,
    v_zugang.relationship_id, 'representative',
    jsonb_build_object('surface', 'platform', 'platform_access_id', v_zugang.id,
                       'access_kind', v_zugang.access_kind)
      || coalesce(p_context, '{}'::jsonb)
  );
end;
$$;

CREATE FUNCTION app.log_record_access(p_organization_id uuid, p_actor uuid, p_action text, p_subject_type text, p_subject_id uuid, p_actor_kind text DEFAULT 'user'::text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zone        text;
  v_tag_beginn  timestamptz;
begin
  if p_action not in ('patient_record.viewed', 'training_relationship.viewed',
                      'platform_representation.read') then
    raise exception 'not a record access action: %', p_action using errcode = '22023';
  end if;
  if p_subject_id is null or p_actor is null then
    return;
  end if;
  -- Nur eine Akte, die es in der Praxis gibt: Ein Aufruf mit unbekannter
  -- Kennung hat nichts gelesen und schreibt nichts.
  if not (
    (p_subject_type = 'patient' and exists (
       select 1 from public.patients p
       where p.id = p_subject_id and p.organization_id = p_organization_id))
    or (p_subject_type = 'training_relationship' and exists (
       select 1 from public.training_relationships t
       where t.id = p_subject_id and t.organization_id = p_organization_id))
  ) then
    return;
  end if;

  select o.time_zone into v_zone
  from public.organizations o
  where o.id = p_organization_id;

  v_tag_beginn := date_trunc('day', now() at time zone v_zone) at time zone v_zone;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    concat_ws(':', 'record_access', p_organization_id, p_actor, p_action,
              p_subject_type, p_subject_id, v_tag_beginn), 0));

  if exists (
    select 1
    from public.audit_log a
    where a.subject_type = p_subject_type
      and a.subject_id = p_subject_id
      and a.organization_id = p_organization_id
      and a.action = p_action
      and a.actor_user_id = p_actor
      and a.occurred_at >= v_tag_beginn
  ) then
    return;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
  )
  values (
    p_organization_id, p_actor, p_actor_kind, p_action, p_subject_type, p_subject_id, 'success',
    coalesce(p_context, '{}'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION app.log_record_access(p_organization_id uuid, p_actor uuid, p_action text, p_subject_type text, p_subject_id uuid, p_actor_kind text, p_context jsonb) IS 'LOG-EPIC-001 (ADR-010): Akte geoeffnet, hoechstens ein Eintrag je Person, Akte und Kalendertag der Praxis. Einzige Stelle fuer patient_record.viewed, training_relationship.viewed und platform_representation.read.';

CREATE FUNCTION app.majority_date(p_date_of_birth date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Geburtstag minus ein Tag plus 18 Jahre plus ein Tag: Der Vortag des
  -- 29. Februar ist der 28., plus 18 Jahre bleibt der 28., plus ein Tag ist
  -- im Nichtschaltjahr der 1. Maerz und im Schaltjahr der 29. Februar.
  select ((p_date_of_birth - 1) + make_interval(years => app.platform_min_age_years()))::date + 1
$$;

COMMENT ON FUNCTION app.majority_date(p_date_of_birth date) IS 'Der Tag, an dem eine Person volljaehrig wird (ab 0 Uhr in der Zeitzone der Praxis): Geburtstag minus ein Tag plus 18 Jahre plus ein Tag (Par. 187 Abs. 2, 188 Abs. 2 BGB). Die eine Altersrechnung der Plattform (ABN-009, BEF-117, ANN-208).';

CREATE FUNCTION app.mark_appointment_documented(p_appointment_id uuid, p_actor uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- B4 (BEF-154): Die Finalisierung setzt den Zustand (ADR-018 Punkt 3), den
  -- Haken nicht. completed_at/completed_by bleiben am Behandlungstermin, wie
  -- sie sind - an einem abgehakten gesetzt, an einem noch nicht abgehakten
  -- leer. Das Trainingsprotokoll schliesst die Einheit weiter mit ab
  -- (ANN-036, ADR-022 Punkt 6): Der Auftrag betrifft die Behandlungsdoku.
  update public.appointments a
     set status       = 'documented',
         completed_at = case when a.kind = 'training' then coalesce(a.completed_at, now())
                             else a.completed_at end,
         updated_at   = now()
   where a.id = p_appointment_id
     and a.status in ('confirmed', 'completed');

  return found;
end;
$$;

COMMENT ON FUNCTION app.mark_appointment_documented(p_appointment_id uuid, p_actor uuid) IS 'ADR-018 Punkt 3, seit B4 (BEF-154, ANN-512): hebt einen bestaetigten oder abgehakten Termin auf documented, wenn seine Dokumentation finalisiert wird. Setzt den Haken (completed_at) am Behandlungstermin nicht mehr mit; am Trainingstermin wie bisher (ANN-036).';

CREATE FUNCTION app.mark_treatment_basis_used() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.treatment_bases b
     set had_appointments = true
   where b.id = new.treatment_basis_id
     and not b.had_appointments;
  return null;
end;
$$;

CREATE FUNCTION app.mask_iban(p_iban text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_iban is null then null
              else left(p_iban, 4) || ' •••• ' || right(p_iban, 4) end
$$;

CREATE FUNCTION app.may_delete_storage_object(p_bucket text, p_object_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.can_execute_storage_deletion()
     and exists (
       select 1
       from public.storage_deletion_orders o
       where o.bucket_id = p_bucket
         and o.object_key = p_object_key
         and o.organization_id = app.current_organization_id()
         and o.receipted_at is null
     )
$$;

CREATE TABLE public.staff_reimbursements (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    kind text NOT NULL,
    period_month date,
    working_days smallint,
    energy_wh_per_day integer,
    rate_cents_per_kwh integer,
    declared_at timestamp with time zone,
    amount_cents integer NOT NULL,
    status text DEFAULT 'requested'::text NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    self_entered boolean DEFAULT false NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note text,
    withdrawn_at timestamp with time zone,
    paid_by uuid,
    paid_at timestamp with time zone,
    working_minutes integer,
    km_per_hour smallint,
    wh_per_km smallint,
    tour_km integer,
    CONSTRAINT staff_reimbursements_amount_cents_check CHECK ((amount_cents BETWEEN 1 AND 1000000)),
    CONSTRAINT staff_reimbursements_decided CHECK (((status = ANY (ARRAY['approved'::text, 'rejected'::text, 'paid'::text])) = ((decided_at IS NOT NULL) AND (decided_by IS NOT NULL)))),
    CONSTRAINT staff_reimbursements_decision_note_check CHECK (((decision_note IS NULL) OR (length(decision_note) BETWEEN 1 AND 500))),
    CONSTRAINT staff_reimbursements_kind_check CHECK ((kind = ANY (ARRAY['electricity'::text, 'purchase'::text]))),
    CONSTRAINT staff_reimbursements_kind_fields CHECK ((((kind = 'electricity'::text) AND (period_month IS NOT NULL) AND (EXTRACT(day FROM period_month) = (1)::numeric) AND (rate_cents_per_kwh BETWEEN 1 AND 1000) AND (declared_at IS NOT NULL) AND (((working_days BETWEEN 1 AND 31) AND ((working_days)::numeric <= EXTRACT(day FROM ((period_month + '1 mon'::interval) - '1 day'::interval))) AND (energy_wh_per_day BETWEEN 1 AND 10000) AND (working_minutes IS NULL) AND (km_per_hour IS NULL) AND (wh_per_km IS NULL) AND (tour_km IS NULL) AND (amount_cents = ((((working_days * energy_wh_per_day) * rate_cents_per_kwh) + 500) / 1000))) OR ((working_days IS NULL) AND (energy_wh_per_day IS NULL) AND (working_minutes >= 1) AND ((working_minutes)::numeric <= ((1440)::numeric * EXTRACT(day FROM ((period_month + '1 mon'::interval) - '1 day'::interval)))) AND (km_per_hour BETWEEN 1 AND 30) AND (wh_per_km BETWEEN 1 AND 100) AND (tour_km IS NULL) AND (amount_cents = ((((((working_minutes)::bigint * km_per_hour) * wh_per_km) * rate_cents_per_kwh) + 30000) / 60000))) OR ((working_days IS NULL) AND (energy_wh_per_day IS NULL) AND (working_minutes >= 1) AND ((working_minutes)::numeric <= ((1440)::numeric * EXTRACT(day FROM ((period_month + '1 mon'::interval) - '1 day'::interval)))) AND (km_per_hour IS NULL) AND (wh_per_km BETWEEN 1 AND 100) AND (tour_km BETWEEN 1 AND 10000) AND (amount_cents = ((((tour_km * wh_per_km) * rate_cents_per_kwh) + 500) / 1000))))) OR ((kind = 'purchase'::text) AND (period_month IS NULL) AND (working_days IS NULL) AND (energy_wh_per_day IS NULL) AND (working_minutes IS NULL) AND (km_per_hour IS NULL) AND (wh_per_km IS NULL) AND (tour_km IS NULL) AND (rate_cents_per_kwh IS NULL) AND (declared_at IS NULL)))),
    CONSTRAINT staff_reimbursements_paid CHECK (((status = 'paid'::text) = ((paid_at IS NOT NULL) AND (paid_by IS NOT NULL)))),
    CONSTRAINT staff_reimbursements_reject_reason CHECK (((status = 'rejected'::text) = (decision_note IS NOT NULL))),
    CONSTRAINT staff_reimbursements_self_entered CHECK (((NOT self_entered) OR ((decided_by = requested_by) AND (status = ANY (ARRAY['approved'::text, 'paid'::text]))))),
    CONSTRAINT staff_reimbursements_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'paid'::text]))),
    CONSTRAINT staff_reimbursements_withdrawn CHECK (((status = 'withdrawn'::text) = (withdrawn_at IS NOT NULL)))
);

COMMENT ON TABLE public.staff_reimbursements IS 'ERS-001 (ANN-598, ANN-599): Erstattungsanträge - Ladestrom je Monat oder Einkauf mit Belegen. Beantragt von/am, entschieden von/am mit Grund, ausgezahlt von/am sind der Nachweis (ADR-010 Punkt 15). Datenklassen erstattung (ausgezahlt: acht Jahre ab Ende des Jahres der Auszahlung, Par. 147 AO) und erstattung_kurz (abgelehnt, zurückgezogen: ein Jahr), ANN-602; beantragte und genehmigte bleiben. Kein Tabellenrecht.';

COMMENT ON COLUMN public.staff_reimbursements.working_minutes IS 'ORG-008: geplante Arbeitsminuten des Monats beim Beantragen (Wochenplan ohne Feiertage und ganztägige Abwesenheit). Anträge vor ORG-008 tragen stattdessen working_days und energy_wh_per_day.';

COMMENT ON COLUMN public.staff_reimbursements.km_per_hour IS 'ORG-008: Strecke je Arbeitsstunde (km) der Praxis beim Beantragen; ein Pauschalwert, nie aus Touren (ANN-605).';

COMMENT ON COLUMN public.staff_reimbursements.wh_per_km IS 'ORG-008: Verbrauch bei höchster Unterstützungsstufe (Wh/km) der Praxis beim Beantragen (ANN-605).';

COMMENT ON COLUMN public.staff_reimbursements.tour_km IS 'BEF-181 (ADR-019 Fassung 6): Monatssumme der geplanten Tourstrecke in ganzen km, berechnet beim Beantragen. Keine Tageswerte, keine Routen. Sehen nur die Person und owner (ANN-616). Null: Antrag nach km je Stunde (ORG-008) oder älter.';

CREATE FUNCTION app.may_pay_reimbursement(p_org uuid, p_reimbursement public.staff_reimbursements) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.can_decide_staff_requests()
         and p_reimbursement.status = 'approved'
         and (p_reimbursement.self_entered
              or p_reimbursement.staff_member_id is distinct from app.own_staff_member(p_org))
$$;

CREATE FUNCTION app.may_read_appointment_context(p_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'training' then app.can_read_training_relationships()
    else app.is_staff()
  end
$$;

COMMENT ON FUNCTION app.may_read_appointment_context(p_kind text) IS 'Welche Rolle welchen Terminkontext lesen darf (ADR-022 Punkt 11). Behandlungstermin und internes Ereignis: die vier Praxisrollen. Trainingstermin: owner, trainer und office wie am Verhaeltnis (LEI-003). Ob die Trainingsrolle INTERNE Termine sieht, gehoert zum Rollenschnitt in E18 Schritt 5 - bis dahin gilt hier die engere Antwort.';

CREATE FUNCTION app.may_read_chat_attachment_object(p_object_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_staff uuid;
  v_grant uuid;
begin
  if v_actor is null or not app.can_use_teamchat() then
    return false;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    return false;
  end if;
  select sm.id into v_staff
  from public.staff_members sm
  where sm.id = app.own_staff_member(v_org) and sm.employment_status = 'active';
  if v_staff is null then
    return false;
  end if;

  -- Das Leserecht gilt auch noch beim Verbrauch: Wer seit der Freigabe aus
  -- dem privaten Kanal genommen wurde, bekommt nichts (wie die Akte).
  select g.id into v_grant
  from public.team_attachment_access_grants g
  join public.team_message_attachments a on a.id = g.attachment_id
  where a.object_key = p_object_key
    and a.status = 'ready'
    and a.message_id is not null
    and a.organization_id = v_org
    and g.organization_id = v_org
    and g.user_id = v_actor
    and g.expires_at > now()
    and (app.team_readable_message(a.message_id, v_org, v_staff)).id is not null
  order by g.created_at
  limit 1
  for update of g skip locked;

  if v_grant is null then
    return false;
  end if;
  delete from public.team_attachment_access_grants where id = v_grant;
  return true;
end;
$$;

