CREATE FUNCTION app.may_read_message_attachment_object(p_object_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid := auth.uid();
  v_org     uuid;
  v_grant   uuid;
begin
  if v_actor is null then
    return false;
  end if;
  v_org := app.current_organization_id();

  select g.id into v_grant
  from public.message_attachment_access_grants g
  join public.platform_message_attachments x on x.id = g.attachment_id
  join public.platform_messages m on m.id = x.message_id
  where x.object_key = p_object_key
    and g.organization_id = x.organization_id
    and g.user_id = v_actor
    and g.expires_at > now()
    and (
      -- BEF-188: Herausgabe an die Person - owner, eigene Organisation, ein
      -- bestaetigter Anhang, auch gesperrt.
      (g.handout
         and v_org is not null and x.organization_id = v_org
         and x.status = 'ready'
         and app.has_any_role('owner'))
      or (
        not g.handout
        and app.message_attachment_visible(x)
        and (
          -- Praxis: wer den Vorgang lesen darf.
          (v_org is not null and x.organization_id = v_org
             and app.can_read_platform_message(m.relationship_kind, m.topic))
          -- Plattform: ein lesbarer Zugang des Kontos zu diesem Verhaeltnis, der
          -- Anhaenge sieht (nie die Begleitung).
          or (v_org is null and exists (
                select 1 from public.platform_accesses a
                where a.account_user_id = v_actor
                  and a.organization_id = x.organization_id
                  and a.relationship_kind = m.relationship_kind
                  and a.relationship_id = m.relationship_id
                  and exists (select 1 from app.platform_visible_attachments(a.id) v where v.id = x.id)
              ))
        )
      )
    )
  order by g.created_at
  limit 1
  for update of g skip locked;

  if v_grant is null then
    return false;
  end if;
  delete from public.message_attachment_access_grants where id = v_grant;
  return true;
end;
$$;

CREATE FUNCTION app.may_read_patient_file_object(p_bucket text, p_object_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_grant uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    return false;
  end if;
  v_org := app.current_organization_id();

  -- POR-014: Ein Plattformkonto hat keine Organisation. Es liest genau die
  -- Datei, fuer die issue_platform_file_link eine Freigabe angelegt hat -
  -- freigegeben, kein Foto, an einem lesbaren Behandlungszugang des Kontos.
  -- Dieselbe zweite Linie wie fuer die Praxis (ADR-023 Punkt 19).
  if v_org is null then
    select g.id into v_grant
    from public.patient_file_access_grants g
    join public.patient_files f on f.id = g.patient_file_id
    where f.object_key = p_object_key
      and app.patient_file_bucket_for(f.document_type) = p_bucket
      and f.status = 'ready'
      and f.released_at is not null
      and not app.is_patient_photo_type(f.document_type)
      and g.organization_id = f.organization_id
      and g.user_id = v_actor
      and g.expires_at > now()
      and exists (
        select 1 from public.platform_accesses a
        where a.account_user_id = v_actor
          and a.relationship_kind = 'treatment'
          and a.relationship_id = f.patient_id
          and a.organization_id = f.organization_id
          and exists (select 1 from app.platform_readable_access(a.id))
      )
    order by g.created_at
    limit 1
    for update of g skip locked;

    if v_grant is null then
      return false;
    end if;
    delete from public.patient_file_access_grants where id = v_grant;
    return true;
  end if;

  select g.id into v_grant
  from public.patient_file_access_grants g
  join public.patient_files f on f.id = g.patient_file_id
  where f.object_key = p_object_key
    and app.patient_file_bucket_for(f.document_type) = p_bucket
    and f.organization_id = v_org
    and f.status = 'ready'
    and g.organization_id = v_org
    and g.user_id = v_actor
    and g.expires_at > now()
    and app.can_see_patient_file_type(f.document_type)
    and (
      f.document_type <> 'patientenfoto'
      or app.patient_photo_accessible(f.patient_id, f.created_at, f.photo_locked_at)
    )
  order by g.created_at
  limit 1
  for update of g skip locked;

  if v_grant is null then
    return false;
  end if;

  delete from public.patient_file_access_grants where id = v_grant;
  return true;
end;
$$;

CREATE FUNCTION app.may_read_platform_messages(p_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'treatment' then app.has_any_role('owner', 'therapist', 'team_lead', 'office')
    when 'training' then app.has_any_role('owner', 'trainer', 'office')
    when 'any' then app.has_any_role('owner', 'therapist', 'team_lead', 'office', 'trainer')
    else false
  end
$$;

