CREATE FUNCTION app.may_read_storage_object_for_deletion(p_bucket text, p_object_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_grant uuid;
begin
  if coalesce(current_setting('storage.operation', true), '') not in (
    'storage.object.delete',
    'storage.object.delete_many',
    'storage.s3.object.delete',
    'storage.s3.object.delete_many'
  ) then
    return false;
  end if;

  v_actor := auth.uid();
  v_org := app.current_organization_id();
  if v_actor is null or v_org is null or not app.can_execute_storage_deletion() then
    return false;
  end if;

  select g.id into v_grant
  from public.patient_file_access_grants g
  join public.storage_deletion_orders o on o.id = g.deletion_order_id
  where o.bucket_id = p_bucket
    and o.object_key = p_object_key
    and o.organization_id = v_org
    and o.receipted_at is null
    and g.organization_id = v_org
    and g.user_id = v_actor
    and g.expires_at > now()
  order by g.created_at
  limit 1
  for update of g skip locked;

  if v_grant is null then
    return false;
  end if;

  delete from public.patient_file_access_grants where id = v_grant;
  return true;
end;
$$;

COMMENT ON FUNCTION app.may_read_storage_object_for_deletion(p_bucket text, p_object_key text) IS 'Leseregel fuer das Objekt eines offenen Loeschauftrags (ADR-017 Punkt 25): nur owner, nur fuer die Entfernen-Operationen der Storage-API (storage.operation) und nur gegen eine einmalige Loeschfreigabe aus claim_storage_deletion_order, die dabei verbraucht wird (FIX-015, BEF-004).';

