COMMENT ON FUNCTION app.may_write_appointment_context(p_kind text) IS 'Welche Rolle einen Termin welchen Kontexts schreiben darf (TRN-004, ANN-176, ADR-022 Punkt 11). Trainingstermin: owner, trainer, office wie am Verhaeltnis. Behandlungstermin und internes Ereignis: die vier Praxisrollen; welche davon was genau darf, pruefen die Schreibwege selbst.';

CREATE FUNCTION app.mdr_released(p_feature_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Freigegebene Kennungen stuenden hier, je mit Verweis auf die Pruefung.
  select p_feature_id = any (array[]::text[])
$$;

COMMENT ON FUNCTION app.mdr_released(p_feature_id text) IS 'Ist die MDR-klassifizierte Funktion nach dokumentierter Pruefung freigegeben (ABN-019, BEF-110, ANN-089)? Heute fuer jede Kennung false. Jede kuenftige Serverfunktion eines Bereichs aus src/app/mdr.ts fragt sie zuerst.';

CREATE FUNCTION app.merge_note(p_target text, p_source text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_source is null or btrim(p_source) = '' then p_target
    when p_target is null or btrim(p_target) = '' then p_source
    when btrim(p_target) = btrim(p_source) then p_target
    else p_target || E'\n\n' || p_source
  end
$$;

CREATE FUNCTION app.merge_take_along(p_target text[], p_source text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(e.eintrag order by e.rang, e.pos), '{}'::text[])
  from (
    select distinct on (lower(x.eintrag)) x.eintrag, x.rang, x.pos
    from (
      select t.eintrag, 1 as rang, t.pos
      from unnest(coalesce(p_target, '{}'::text[])) with ordinality as t(eintrag, pos)
      union all
      select s.eintrag, 2 as rang, s.pos
      from unnest(coalesce(p_source, '{}'::text[])) with ordinality as s(eintrag, pos)
    ) x
    order by lower(x.eintrag), x.rang, x.pos
  ) e
$$;

