    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select false
$$;

COMMENT ON FUNCTION app.message_attachment_scan_required() IS 'KOM-005, KOM-013 (ADR-017 Punkt 69 in Fassung 6): der Schalter der Virenpruefung fuer Anhaenge an Rueckfragen. Aus und vorgesehen aus (ADR-026 abgelehnt, 2026-10-15): ein Anhang wird nach den Pruefungen aus Punkt 49 ready und ist als "nicht auf Schadsoftware geprueft" gekennzeichnet. An: er bliebe pending, bis ein Pruefergebnis vorliegt.';

CREATE FUNCTION app.message_attachment_visible(p_attachment public.platform_message_attachments) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select p_attachment.status = 'ready'
     and p_attachment.locked_at is null
     and p_attachment.created_at + app.retention_interval('rueckfrageanhang') > now()
$$;

CREATE FUNCTION app.message_attachments_offered(p_kind text, p_relationship_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'training' then exists (
      select 1 from public.training_relationships t
      where t.id = p_relationship_id
        and app.external_attachments_enabled(t.organization_id)
    )
    when 'treatment' then exists (
      select 1 from public.aftercare_subscriptions s
      where s.patient_id = p_relationship_id
        and app.external_attachments_enabled(s.organization_id)
        and s.starts_on <= app.training_today(s.organization_id)
        and (s.ends_on is null or s.ends_on >= app.training_today(s.organization_id))
    )
    else false
  end
$$;

COMMENT ON FUNCTION app.message_attachments_offered(p_kind text, p_relationship_id uuid) IS 'KOM-005, KOM-012 (ADR-017 Punkt 59, ANN-332, ANN-371): ob in diesem Verhaeltnis Fotos und Videos an Rueckfragen vorgesehen sind - nur bei eingeschaltetem Schalter der Organisation, dann im Training immer, in der Behandlung nur mit laufendem Nachsorge-Abo.';

CREATE FUNCTION app.message_due_on(p_organization_id uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.add_workdays(app.training_today(o.id), o.message_response_workdays)
  from public.organizations o
  where o.id = p_organization_id
$$;

CREATE FUNCTION app.next_invoice_number(p_organization_id uuid, p_year smallint, p_service_area text, p_prefix text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_number integer;
begin
  -- Beide Wege liefern dieselbe Aussage: `next_number` steht nach der
  -- Anweisung auf der naechsten freien Nummer, vergeben wird die davor.
  insert into public.invoice_number_series as s (organization_id, year, service_area, next_number)
  values (p_organization_id, p_year, p_service_area, 2)
  on conflict (organization_id, year, service_area) do update
    set next_number = s.next_number + 1
  returning s.next_number - 1 into v_number;

  -- Kuerzel, Jahr, vierstellige laufende Nummer: "RG-2026-0001". Vierstellig,
  -- weil eine Praxis dieser Groesse im Jahr keine zehntausend Rechnungen
  -- schreibt - und laenger wird die Nummer trotzdem, wenn doch. Das Kuerzel
  -- unterscheidet die Kreise; es kommt aus den Stammdaten und nicht von hier.
  return p_prefix || '-' || p_year::text || '-' || lpad(v_number::text, 4, '0');
end;
$$;

COMMENT ON FUNCTION app.next_invoice_number(p_organization_id uuid, p_year smallint, p_service_area text, p_prefix text) IS 'Vergibt die naechste Rechnungsnummer eines Kalenderjahres **in einem Leistungsbereich**, lueckenlos je Kreis und unter gleichzeitigen Zugriffen eindeutig (ADR-009 Punkte 8 und 17, ANN-075). Format: Kuerzel-Jahr-vierstellig; das Kuerzel unterscheidet die Kreise.';

CREATE FUNCTION app.next_staff_color(p_org uuid, p_staff uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select f.farbe
  from unnest(app.staff_color_palette()) with ordinality as f(farbe, reihe)
  order by (
             select count(*)
             from public.staff_colors c
             join public.staff_members sm on sm.id = c.staff_member_id
             where c.organization_id = p_org and c.color = f.farbe
               and sm.employment_status = 'active' and sm.id <> p_staff
           ),
           f.reihe
  limit 1
$$;

CREATE FUNCTION app.notification_access_live(p_access_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select a.status = 'active' and coalesce(app.platform_access_ended_at(a.id) > now(), true)
    from public.platform_accesses a
    where a.id = p_access_id
  ), false)
$$;

-- ANN-483
CREATE TABLE public.appointments (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid,
    staff_member_id uuid NOT NULL,
    location_id uuid,
    appointment_type text NOT NULL,
    status text DEFAULT 'confirmed'::text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    visit_street text,
    visit_house_number text,
    visit_postal_code text,
    visit_city text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    completed_at timestamp with time zone,
    completed_by uuid,
    cancellation_reason text,
    no_show_recorded_at timestamp with time zone,
    no_show_recorded_by uuid,
    treatment_basis_id uuid,
    cancellation_received_at timestamp with time zone,
    fee_basis text,
    kind text DEFAULT 'therapy'::text NOT NULL,
    title text,
    event_group_id uuid,
    no_show_protocol_confirmed boolean,
    event_series_id uuid,
    training_relationship_id uuid,
    training_basis_id uuid,
    visit_lat double precision,
    visit_lon double precision,
    visit_geocode_precision text,
    patient_relevant_changed_at timestamp with time zone DEFAULT now() NOT NULL,
    fee_waived_at timestamp with time zone,
    fee_waived_by uuid,
    reopened_at timestamp with time zone,
    reopened_by uuid,
    previous_treatment_basis_id uuid,
    treatment_basis_transferred_at timestamp with time zone,
    treatment_basis_transferred_by uuid,
    occasion text DEFAULT 'regular'::text NOT NULL,
    CONSTRAINT appointments_address_matches_type CHECK ((((appointment_type = 'home_visit'::text) AND (visit_street IS NOT NULL) AND (visit_house_number IS NOT NULL) AND (visit_postal_code IS NOT NULL) AND (visit_city IS NOT NULL)) OR ((appointment_type = ANY (ARRAY['practice'::text, 'video'::text])) AND (visit_street IS NULL) AND (visit_house_number IS NULL) AND (visit_postal_code IS NULL) AND (visit_city IS NULL)))),
    CONSTRAINT appointments_appointment_type_check CHECK ((appointment_type = ANY (ARRAY['home_visit'::text, 'practice'::text, 'video'::text]))),
    CONSTRAINT appointments_cancellation_fields CHECK ((((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (cancelled_by IS NOT NULL)) OR ((status <> 'cancelled'::text) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL)))),
    CONSTRAINT appointments_cancellation_reason_needs_cancellation CHECK (((cancellation_reason IS NULL) OR (status = 'cancelled'::text))),
    CONSTRAINT appointments_cancellation_reason_values CHECK (((cancellation_reason IS NULL) OR (cancellation_reason = ANY (ARRAY['patient_request'::text, 'practice_request'::text, 'patient_moved'::text, 'practice_moved'::text, 'other'::text, 'moved'::text])))),
    CONSTRAINT appointments_cancellation_received_needs_cancellation CHECK (((cancellation_received_at IS NULL) OR (status = 'cancelled'::text))),
    CONSTRAINT appointments_completion_fields CHECK ((((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (completed_by IS NOT NULL)) OR ((status = 'documented'::text) AND ((completed_at IS NOT NULL) OR (completed_by IS NULL))) OR (status = 'invoiced'::text) OR ((status <> ALL (ARRAY['completed'::text, 'documented'::text, 'invoiced'::text])) AND (completed_at IS NULL) AND (completed_by IS NULL)))),
    CONSTRAINT appointments_confirmed_protocol_means_fee CHECK (((no_show_protocol_confirmed IS NOT TRUE) OR (NOT (fee_basis IS DISTINCT FROM 'no_show'::text)))),
    CONSTRAINT appointments_event_group CHECK ((((kind = 'internal'::text) AND (event_group_id IS NOT NULL)) OR ((kind <> 'internal'::text) AND (event_group_id IS NULL)))),
    CONSTRAINT appointments_event_series CHECK (((event_series_id IS NULL) OR (kind = 'internal'::text))),
    CONSTRAINT appointments_event_type CHECK (((kind <> 'internal'::text) OR (appointment_type = ANY (ARRAY['practice'::text, 'video'::text])))),
    CONSTRAINT appointments_fee_basis_values CHECK (((fee_basis IS NULL) OR ((kind = 'therapy'::text) AND (((fee_basis = 'late_cancellation'::text) AND (status = 'cancelled'::text)) OR ((fee_basis = 'no_show'::text) AND (status = 'no_show'::text)))))),
    CONSTRAINT appointments_fee_waiver_by_needs_at CHECK (((fee_waived_by IS NULL) OR (fee_waived_at IS NOT NULL))),
    CONSTRAINT appointments_fee_waiver_needs_fee CHECK (((fee_waived_at IS NULL) OR (fee_basis IS NOT NULL))),
    CONSTRAINT appointments_kind_fields CHECK ((((kind = 'therapy'::text) AND (patient_id IS NOT NULL) AND (training_relationship_id IS NULL) AND (title IS NULL)) OR ((kind = 'internal'::text) AND (patient_id IS NULL) AND (training_relationship_id IS NULL) AND (treatment_basis_id IS NULL) AND (title IS NOT NULL) AND ((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 120))) OR ((kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id IS NOT NULL) AND (treatment_basis_id IS NULL) AND (title IS NULL)))),
    CONSTRAINT appointments_kind_values CHECK ((kind = ANY (ARRAY['therapy'::text, 'internal'::text, 'training'::text]))),
    CONSTRAINT appointments_late_cancellation_needs_receipt CHECK (((fee_basis IS DISTINCT FROM 'late_cancellation'::text) OR (cancellation_received_at IS NOT NULL))),
    CONSTRAINT appointments_location_matches_type CHECK ((((appointment_type = 'practice'::text) AND (location_id IS NOT NULL)) OR ((appointment_type = ANY (ARRAY['home_visit'::text, 'video'::text])) AND (location_id IS NULL)))),
    CONSTRAINT appointments_no_show_fields CHECK ((((status = 'no_show'::text) AND (no_show_recorded_at IS NOT NULL) AND (no_show_recorded_by IS NOT NULL)) OR ((status <> 'no_show'::text) AND (no_show_recorded_at IS NULL) AND (no_show_recorded_by IS NULL)))),
    CONSTRAINT appointments_no_show_protocol_scope CHECK (((no_show_protocol_confirmed IS NULL) OR (status = 'no_show'::text))),
    CONSTRAINT appointments_nutrition_occasion CHECK (((occasion <> 'nutrition_counselling'::text) OR ((kind = ANY (ARRAY['therapy'::text, 'training'::text])) AND (treatment_basis_id IS NULL) AND (training_basis_id IS NULL) AND (fee_basis IS NULL)))),
    CONSTRAINT appointments_occasion_values CHECK ((occasion = ANY (ARRAY['regular'::text, 'nutrition_counselling'::text]))),
    CONSTRAINT appointments_previous_basis_only_after_transfer CHECK (((previous_treatment_basis_id IS NULL) OR (treatment_basis_transferred_at IS NOT NULL))),
    CONSTRAINT appointments_reopened_complete CHECK (((reopened_at IS NULL) = (reopened_by IS NULL))),
    CONSTRAINT appointments_status_check CHECK ((status = ANY (ARRAY['confirmed'::text, 'cancelled'::text, 'no_show'::text, 'completed'::text, 'documented'::text, 'invoiced'::text]))),
    CONSTRAINT appointments_time_order CHECK ((ends_at > starts_at)),
    CONSTRAINT appointments_training_basis_scope CHECK (((training_basis_id IS NULL) OR (kind = 'training'::text))),
    CONSTRAINT appointments_treatment_basis_transfer_complete CHECK (((treatment_basis_transferred_at IS NULL) = (treatment_basis_transferred_by IS NULL))),
    CONSTRAINT appointments_visit_city_check CHECK (((visit_city IS NULL) OR ((length(btrim(visit_city)) >= 1) AND (length(btrim(visit_city)) <= 200)))),
    CONSTRAINT appointments_visit_coordinate_check CHECK ((((visit_lat IS NULL) AND (visit_lon IS NULL) AND (visit_geocode_precision IS NULL)) OR ((visit_lat BETWEEN ('-90'::integer)::double precision AND (90)::double precision) AND (visit_lon BETWEEN ('-180'::integer)::double precision AND (180)::double precision) AND (visit_geocode_precision = ANY (ARRAY['address'::text, 'street'::text, 'locality'::text, 'unknown'::text])) AND (visit_street IS NOT NULL)))),
    CONSTRAINT appointments_visit_house_number_check CHECK (((visit_house_number IS NULL) OR ((length(btrim(visit_house_number)) >= 1) AND (length(btrim(visit_house_number)) <= 20)))),
    CONSTRAINT appointments_visit_postal_code_check CHECK (((visit_postal_code IS NULL) OR ((length(btrim(visit_postal_code)) >= 1) AND (length(btrim(visit_postal_code)) <= 20)))),
    CONSTRAINT appointments_visit_street_check CHECK (((visit_street IS NULL) OR ((length(btrim(visit_street)) >= 1) AND (length(btrim(visit_street)) <= 200))))
);

COMMENT ON TABLE public.appointments IS 'Organisatorische Termine. Enthaelt bewusst KEINE klinischen Inhalte (PROJECT_PRINCIPLES.md 4.6, 5). Datenklasse: organisatorische Behandlungsdaten.';

COMMENT ON COLUMN public.appointments.status IS 'Zustand des Termins nach ADR-018. Geschrieben ausschliesslich von SECURITY-DEFINER-Funktionen mit eigener Rollenpruefung und eigenem Auditereignis; es gibt keinen freien Statuswechsel ueber die Tabelle.';

COMMENT ON COLUMN public.appointments.starts_at IS 'Beginn als timestamptz. Der Kalendertag ergibt sich aus organizations.time_zone, nicht aus der Zeitzone des Aufrufers.';

COMMENT ON COLUMN public.appointments.ends_at IS 'Ende als timestamptz. Das Intervall ist halboffen [starts_at, ends_at): ein direkt anschliessender Termin ist zulaessig.';

COMMENT ON COLUMN public.appointments.visit_street IS 'Adress-Snapshot des Hausbesuchs zum Zeitpunkt der Anlage. Aendert sich mit spaeteren Stammdaten NICHT.';

COMMENT ON COLUMN public.appointments.completed_at IS 'Zeitpunkt des Abschlusses. Wird beim Wiederoeffnen geleert; die Historie bleibt im Auditlog (CAL-004).';

COMMENT ON COLUMN public.appointments.completed_by IS 'auth.users.id des abschliessenden Accounts. Bewusst ohne FK, wie actor_user_id im Auditlog.';

COMMENT ON COLUMN public.appointments.cancellation_reason IS 'Codierter Absagegrund (CAL-008b, ANN-034). Pflicht fuer jede neue Absage; Bestandszeilen tragen null. Kein Freitext - der Termin enthaelt keine klinischen Inhalte.';

COMMENT ON COLUMN public.appointments.no_show_recorded_at IS 'Zeitpunkt des Vermerks "nicht angetroffen". Wird beim Wiederoeffnen geleert; die Historie bleibt im Auditlog (CAL-008c).';

COMMENT ON COLUMN public.appointments.no_show_recorded_by IS 'auth.users.id des vermerkenden Accounts. Bewusst ohne FK, wie actor_user_id im Auditlog.';

COMMENT ON COLUMN public.appointments.treatment_basis_id IS 'Verordnung, aus deren Kontingent dieser Termin geplant wurde (CAL-007). Nullbar: ein Termin entsteht auch ohne Verordnung, und eine geloeschte Verordnung setzt den Verweis zurueck. Organisatorisch - die Verordnung selbst traegt die klinischen Felder.';

COMMENT ON COLUMN public.appointments.cancellation_received_at IS 'Zeitpunkt, zu dem die Absage die Praxis ERREICHT hat - nicht der ihrer Eingabe (das ist cancelled_at). Grundlage der 24-Stunden-Frist (CAL-014b, ADR-018 Fassung 2 Punkt 8). Bestandszeilen tragen null.';

COMMENT ON COLUMN public.appointments.fee_basis IS 'Gebuehrenanlass: woraus eine Gebuehr entstehen soll. null heisst keine. In V1 setzt der Server ausschliesslich late_cancellation; no_show stammt aus dem Pflichtkennzeichen vor ADR-018 Fassung 2. Kein Betrag - Hoehe und Abrechnungsweg gehoeren zu ABR-001 und ABR-003.';

COMMENT ON COLUMN public.appointments.kind IS 'Terminkontext (ADR-022 Punkt 2): therapy = Behandlungstermin mit Patient:in; internal = internes Ereignis des Praxisbetriebs ohne Gegenueber; training = Trainingstermin an einem Trainingsverhaeltnis. Genau ein Kontext je Termin, unveraenderlich ab Anlage (Punkt 10). Die Bestandswerte treatment und event heissen seit CAL-027 wie die Bereiche (ADR-021 Punkt 9).';

COMMENT ON COLUMN public.appointments.title IS 'Bezeichnung eines Ereignisses ("Teambesprechung"). Nur bei kind = event, und ausdruecklich KEIN Freitext ueber Patient:innen - der Termin enthaelt keine klinischen Inhalte (PROJECT_PRINCIPLES.md 4.6, 5).';

COMMENT ON COLUMN public.appointments.event_group_id IS 'Klammer ueber die Zeilen EINES Ereignisses - je beteiligter Person eine (CAL-017). Nur bei kind = event gesetzt, dort verbindlich. Bestandszeilen tragen ihre eigene Kennung; sie werden nicht nachtraeglich zusammengefuehrt.';

COMMENT ON COLUMN public.appointments.no_show_protocol_confirmed IS 'Bestaetigung des Protokolls aus ADR-018 Fassung 3 Punkt 9 (15 Minuten gewartet, geklingelt, angerufen). true nur am Hausbesuch und nur mit Gebuehrenanlass; false, wo das Protokoll nicht gilt (Praxis, Video - ANN-055); null an Zeilen aus der Zeit vor CAL-018. Wird beim Wiederoeffnen geleert.';

COMMENT ON COLUMN public.appointments.event_series_id IS 'Klammer ueber die Vorkommen EINER Serie gleichartiger Ereignisse - Dauerfehlzeit (CAL-021, ANN-059). Neben event_group_id, nicht statt ihrer: die Gruppe ist ein Vorkommen, die Serie sind alle. Null bei jedem Ereignis, das keiner Serie angehoert.';

COMMENT ON COLUMN public.appointments.training_relationship_id IS 'Das Trainingsverhaeltnis, an dem ein Trainingstermin haengt (ADR-022 Punkt 3). Genau bei kind = training gesetzt, sonst leer; die Mandantengrenze traegt der zusammengesetzte Fremdschluessel mit.';

COMMENT ON COLUMN public.appointments.training_basis_id IS 'Optionale Trainingsgrundlage des Termins (ADR-022 Punkt 5). Pflicht ist das Verhaeltnis, nicht die Klammer - die Einzelstunde bleibt moeglich. Der zusammengesetzte Fremdschluessel bindet die Klammer an dasselbe Verhaeltnis wie den Termin.';

COMMENT ON COLUMN public.appointments.visit_lat IS 'Breitengrad des Hausbesuchs-Snapshots (ANN-016, ANN-003). Uebernommen aus der geocodierten Patientenadresse, wenn sie mit visit_* uebereinstimmt; Frist wie der Termin.';

COMMENT ON COLUMN public.appointments.visit_lon IS 'Laengengrad des Hausbesuchs-Snapshots. Siehe visit_lat.';

COMMENT ON COLUMN public.appointments.visit_geocode_precision IS 'Genauigkeit der uebernommenen Koordinate. Siehe patient_contact_details.geocode_precision.';

COMMENT ON COLUMN public.appointments.patient_relevant_changed_at IS 'Zeitpunkt der letzten Aenderung, die die Patient:in betrifft: Beginn, Ende, Terminart, Ort, Adresse, behandelnde Person, Absage (ABN-003, ANN-040). Gesetzt vom Trigger appointments_patient_relevant_change. Der Mitteilungsvermerk gilt, solange notified_at nicht davor liegt.';

COMMENT ON COLUMN public.appointments.fee_waived_at IS 'Zeitpunkt, zu dem die Praxis bewusst auf die Gebuehr aus fee_basis verzichtet hat (ABN-006, BEF-094). Der Anlass bleibt; abrechenbar ist er danach nicht mehr (app.billable_fee_basis).';

COMMENT ON COLUMN public.appointments.fee_waived_by IS 'Konto, das den Verzicht vermerkt hat (ABN-006). Nicht in der Terminsicht - Akteure stehen im Auditlog (ADR-010).';

COMMENT ON COLUMN public.appointments.reopened_by IS 'Wer den Abschluss oder das Nichtantreffen zuletzt zurueckgenommen hat (LOG-EPIC-001). Bewusst ohne FK wie created_by.';

COMMENT ON COLUMN public.appointments.previous_treatment_basis_id IS 'Die Grundlage, von der dieser Termin zuletzt uebertragen wurde (BEF-124, ANN-562). Solange sie hier steht, wird jene Grundlage nicht geloescht. Faellt beim Loeschen der Akte mit (on delete set null).';

COMMENT ON COLUMN public.appointments.treatment_basis_transferred_at IS 'Wann der Termin zuletzt auf eine andere Grundlage uebertragen wurde (BEF-124). Nachweis im Datenmodell statt Auditeintrag (ADR-010 Punkt 15).';

COMMENT ON COLUMN public.appointments.treatment_basis_transferred_by IS 'Wer ihn uebertragen hat (auth.uid()). Zweck nur der Nachweis zur Akte, nie eine Leistungskontrolle (ADR-010 Punkt 20).';

COMMENT ON COLUMN public.appointments.occasion IS 'ERN-011 (ANN-622, ANN-664): Anlass des Termins neben dem Kontext (ADR-022 Punkt 2) - regular = Behandlung bzw. Training, nutrition_counselling = Ernährungsberatung am Verhältnis des Profils (ADR-027 Punkt 15). Steht mit dem Anlegen fest.';

COMMENT ON CONSTRAINT appointments_kind_fields ON public.appointments IS 'Je Kontext genau ein Verhaeltnis, beim internen Termin keines (ADR-022 Punkt 3); die Behandlungsgrundlage bleibt ausserhalb von therapy leer (Punkt 4).';

COMMENT ON CONSTRAINT appointments_nutrition_occasion ON public.appointments IS 'ERN-011 (ANN-664): Ein Beratungstermin hängt an Akte oder Trainingsverhältnis, trägt keine Behandlungsgrundlage, keine Trainingsvereinbarung und keinen Gebührenanlass.';

CREATE FUNCTION app.notification_appointment_relationship(p_appointment public.appointments) RETURNS TABLE(rel_kind text, rel_id uuid)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_appointment.kind when 'therapy' then 'treatment' when 'training' then 'training' end,
         case p_appointment.kind
           when 'therapy' then p_appointment.patient_id
           when 'training' then p_appointment.training_relationship_id
         end
$$;

CREATE FUNCTION app.notification_drop_reason(p_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  d       public.notification_deliveries%rowtype;
  s       public.platform_notification_settings%rowtype;
  v_tz    text;
  v_heute date;
  v_termin public.appointments%rowtype;
  v_tagebuch boolean;
begin
  select * into d from public.notification_deliveries x where x.id = p_id;
  v_tagebuch := d.kind = 'nutrition_diary_reminder';
  if not app.notification_access_live(d.access_id) then
    return 'access_ended';
  end if;
  if exists (
    select 1 from public.notification_kind_switches k
    where k.organization_id = d.organization_id and k.kind = d.kind
  ) then
    return 'switched_off';
  end if;
  select * into s from public.platform_notification_settings x where x.access_id = d.access_id;
  if not found
     or (d.channel = 'email' and not (d.kind = any (s.email_kinds)))
     or (d.channel = 'push' and not (d.kind = any (s.push_kinds))) then
    return 'not_wanted';
  end if;
  if d.channel = 'push' and not exists (
    select 1 from public.platform_push_subscriptions p where p.access_id = d.access_id
  ) then
    return 'no_device';
  end if;
  if d.channel = 'email' and not exists (
    select 1 from public.platform_accesses a
    join auth.users u on u.id = a.account_user_id
    where a.id = d.access_id and coalesce(btrim(u.email), '') <> ''
  ) then
    return 'no_address';
  end if;
  if d.due_at < now() - make_interval(hours => app.notification_rule('stale_hours')) then
    return 'stale';
  end if;

  if d.kind in ('appointment_reminder', 'appointment_changed') then
    select * into v_termin from public.appointments a where a.id = d.subject_id;
    if not found or v_termin.status <> 'confirmed'
       or v_termin.starts_at is distinct from d.subject_at or v_termin.starts_at <= now() then
      return 'obsolete';
    end if;
  elsif d.kind = 'appointment_cancelled' and d.subject_at <= now() then
    return 'obsolete';
  elsif v_tagebuch and not app.nutrition_diary_reminder_live(d.subject_id, d.subject_at) then
    -- ERN-009: Uhrzeit geändert, Tagebuch aus, Widerruf, Beratung beendet,
    -- mehr als zwei Stunden her.
    return 'obsolete';
  end if;

  -- Obergrenzen je Weg: eine je Art und Tag (Tagebuch: je Mahlzeit), eine
  -- Zahl je Woche über die übrigen Arten. Mitgezaehlt wird, was gerade
  -- abgeholt ist.
  select o.time_zone into v_tz from public.organizations o where o.id = d.organization_id;
  v_heute := (now() at time zone v_tz)::date;
  if exists (
    select 1 from public.notification_deliveries x
    where x.access_id = d.access_id and x.channel = d.channel and x.kind = d.kind and x.id <> d.id
      and (not v_tagebuch or x.subject_id = d.subject_id)
      and (x.state = 'sent' or (x.state = 'pending' and x.claimed_at > now() - interval '15 minutes'))
      and (coalesce(x.finished_at, x.claimed_at) at time zone v_tz)::date = v_heute
  ) then
    return 'daily_cap';
  end if;
  if not v_tagebuch and (
    select count(*) from public.notification_deliveries x
    where x.access_id = d.access_id and x.channel = d.channel and x.id <> d.id
      and x.kind <> 'nutrition_diary_reminder'
      and (x.state = 'sent' or (x.state = 'pending' and x.claimed_at > now() - interval '15 minutes'))
      and coalesce(x.finished_at, x.claimed_at) > now() - interval '7 days'
  ) >= app.notification_rule('weekly_cap') then
    return 'weekly_cap';
  end if;
  return null;
end;
$$;

CREATE FUNCTION app.notification_due_at(p_at timestamp with time zone, p_tz text, p_from smallint, p_until smallint) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_ortszeit timestamp := p_at at time zone p_tz;
  v_stunde   integer := extract(hour from v_ortszeit)::integer;
  v_ruhe     boolean;
  v_ende     timestamp;
begin
  if p_from is null or p_until is null or p_from = p_until then
    return p_at;
  end if;
  if p_from > p_until then
    v_ruhe := v_stunde >= p_from or v_stunde < p_until;
  else
    v_ruhe := v_stunde >= p_from and v_stunde < p_until;
  end if;
  if not v_ruhe then
    return p_at;
  end if;
  v_ende := date_trunc('day', v_ortszeit) + make_interval(hours => p_until);
  if v_ende <= v_ortszeit then
    v_ende := v_ende + interval '1 day';
  end if;
  return v_ende at time zone p_tz;
end;
$$;

CREATE FUNCTION app.notification_kinds() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array[
    'appointment_reminder',
    'appointment_changed',
    'appointment_cancelled',
    'message_answered',
    'request_answered',
    'plan_assigned',
    -- ERN-009 (ADR-027 Punkt 12): zu den Zeiten, die die Person wählt.
    'nutrition_diary_reminder'
  ]::text[]
$$;

COMMENT ON FUNCTION app.notification_kinds() IS 'KOM-009 (ADR-024 Punkt 13): der geschlossene Katalog der Benachrichtigungsarten. Wortlaut in src/lib/begriffe.ts (BENACHRICHTIGUNGEN); eine neue Art ist eine Aenderung beider Stellen mit Review.';

CREATE FUNCTION app.notification_reminder_days(p_local timestamp without time zone) RETURNS SETOF date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (p_local::date + n)
  from generate_series(1, case extract(isodow from p_local)::integer
                            when 5 then 3
                            when 6 then 0
                            when 7 then 0
                            else 1
                          end) n
  where extract(hour from p_local) >= app.notification_rule('reminder_hour')
$$;

CREATE FUNCTION app.notification_rule(p_key text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_key
    when 'quiet_from' then 20        -- Ruhezeit ab 20 Uhr (Vorschlag ADR-024)
    when 'quiet_until' then 8        -- bis 8 Uhr
    when 'reminder_hour' then 17     -- Erinnerung am Vortag ab 17 Uhr
    when 'weekly_cap' then 10        -- hoechstens zehn je Woche und Weg
    when 'max_attempts' then 3       -- dann aufgegeben (Punkt 16)
    when 'stale_hours' then 24       -- spaeter als einen Tag nach Faelligkeit: entfaellt
    when 'devices_per_access' then 5 -- hoechstens fuenf Geraete je Zugang (Zweitreview S2)
  end
$$;

-- ANN-346
CREATE FUNCTION app.notify_appointment_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rel record;
begin
  if new.kind not in ('therapy', 'training') then
    return new;
  end if;
  if exists (
    select 1 from public.platform_appointment_requests w
    where w.appointment_id = new.id and w.status = 'open'
  ) then
    return new;
  end if;
  select * into v_rel from app.notification_appointment_relationship(new);

  if old.status = 'confirmed' and new.status = 'cancelled' and old.starts_at > now() then
    perform app.enqueue_notification(new.organization_id, v_rel.rel_kind, v_rel.rel_id,
                                     'appointment_cancelled', new.id, old.starts_at);
  elsif old.status = 'confirmed' and new.status = 'confirmed'
        and new.starts_at is distinct from old.starts_at and new.starts_at > now() then
    perform app.enqueue_notification(new.organization_id, v_rel.rel_kind, v_rel.rel_id,
                                     'appointment_changed', new.id, new.starts_at);
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.notify_message_answered() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorgang public.platform_messages%rowtype;
begin
  if new.side <> 'practice' then
    return new;
  end if;
  select * into v_vorgang from public.platform_messages m where m.id = new.message_id;
  perform app.enqueue_notification(v_vorgang.organization_id, v_vorgang.relationship_kind,
                                   v_vorgang.relationship_id, 'message_answered',
                                   v_vorgang.id, null);
  return new;
end;
$$;

CREATE FUNCTION app.notify_plan_assigned() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'assigned' and (tg_op = 'INSERT' or old.status = 'draft') then
    perform app.enqueue_notification(
      new.organization_id,
      case new.service_area when 'therapy' then 'treatment' else 'training' end,
      coalesce(new.patient_id, new.training_relationship_id),
      'plan_assigned', new.id, null);
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.notify_request_answered() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.status = 'open' and new.status in ('done', 'declined') then
    perform app.enqueue_notification(new.organization_id, new.relationship_kind,
                                     new.relationship_id, 'request_answered', new.id, null);
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.nutrition_calculation(p_weight_kg numeric, p_height_cm numeric, p_age_years integer, p_sex text, p_body_fat_percent numeric, p_pal numeric, p_goal text, p_formula text, p_in_training boolean, p_overrides jsonb DEFAULT '{}'::jsonb, p_target_weight_kg numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  -- Punkt 17: die Stufen der DGE.
  c_pal_stufen      constant numeric[] := array[1.4, 1.6, 1.8, 2.0];
  -- Punkt 18: Energieziel.
  c_defizit         constant integer := 500;
  c_defizit_anteil  constant numeric := 0.20;
  c_ueberschuss     constant integer := 300;
  -- Punkt 19: Makronährstoffe (Atwater-Faktoren 4 / 4 / 9 kcal je g).
  c_eiweiss         constant numeric := 0.8;
  c_eiweiss_alter   constant numeric := 1.0;
  c_alter_ab        constant integer := 65;
  c_eiweiss_aufbau  constant numeric := 1.6;
  c_fett_anteil     constant numeric := 0.30;
  c_kcal_eiweiss    constant integer := 4;
  c_kcal_kh         constant integer := 4;
  c_kcal_fett       constant integer := 9;
  -- Punkt 20: Wasser.
  c_wasser_je_kg    constant integer := 35;
  c_wasser_mindest  constant integer := 1500;
  -- Punkt 21: Zielgewicht.
  c_bmi_unten       constant numeric := 18.5;
  -- ANN-618: Energie je kg Körpergewicht für "Zeit bis zum Ziel" - eine
  -- Näherung, kein Versprechen.
  c_kcal_je_kg      constant integer := 7000;

  v_fehlt        text[] := '{}';
  v_formel       text;
  v_mager        numeric;
  v_varianten    jsonb := '[]'::jsonb;
  v_m            numeric;
  v_w            numeric;
  v_grund        integer;
  v_gemittelt    boolean := false;
  v_gesamt       integer;
  v_regel        text;
  v_aenderung    integer;
  v_energie      integer;
  v_unten        boolean;
  v_energie_eff  integer;
  v_faktor       numeric;
  v_grundlage    text;
  v_eiweiss      integer;
  v_eiweiss_eff  integer;
  v_fett         integer;
  v_fett_eff     integer;
  v_kh           integer;
  v_kh_eff       integer;
  v_wasser       integer;
  v_wasser_eff   integer;
  v_ziel_unten   numeric;
  v_wochen       integer;
  v_tagesdiff    integer;
  v_ueber        jsonb := coalesce(p_overrides, '{}'::jsonb);
begin
  if p_sex is null or p_sex not in ('female', 'male', 'unspecified') then
    raise exception 'unknown sex for the formula' using errcode = '22023';
  end if;
  if p_pal is null or not (p_pal = any (c_pal_stufen)) then
    raise exception 'unknown activity level' using errcode = '22023';
  end if;
  if p_goal is null or p_goal not in ('lose', 'maintain', 'build_muscle', 'gain') then
    raise exception 'unknown goal' using errcode = '22023';
  end if;
  if p_formula is null or p_formula not in ('standard', 'katch_mcardle', 'harris_benedict_revised') then
    raise exception 'unknown formula' using errcode = '22023';
  end if;

  if p_weight_kg is null then v_fehlt := v_fehlt || 'weight'::text; end if;
  if p_height_cm is null then v_fehlt := v_fehlt || 'height'::text; end if;
  if p_age_years is null then v_fehlt := v_fehlt || 'birth_date'::text; end if;
  if p_formula = 'katch_mcardle' and p_body_fat_percent is null then
    v_fehlt := v_fehlt || 'body_fat'::text;
  end if;
  if cardinality(v_fehlt) > 0 then
    return jsonb_build_object('status', 'missing', 'missing', to_jsonb(v_fehlt));
  end if;

  -- Punkt 16: Grundumsatz. Standard Mifflin-St Jeor, mit Körperfettanteil
  -- Cunningham; die Beratung stellt auf Katch-McArdle oder Harris-Benedict
  -- (revidiert, Roza und Shizgal 1984) um.
  v_formel := case
    when p_formula = 'standard' and p_body_fat_percent is null then 'mifflin_st_jeor'
    when p_formula = 'standard' then 'cunningham'
    else p_formula
  end;

  if v_formel in ('cunningham', 'katch_mcardle') then
    v_mager := round(p_weight_kg * (1 - p_body_fat_percent / 100), 1);
    if v_formel = 'cunningham' then
      v_grund := round(500 + 22 * v_mager)::integer;
      v_varianten := jsonb_build_array(jsonb_build_object(
        'sex', null, 'constant', 500, 'kcal', v_grund,
        'terms', jsonb_build_array(jsonb_build_object('factor', 22, 'input', 'lean_mass_kg'))));
    else
      v_grund := round(370 + 21.6 * v_mager)::integer;
      v_varianten := jsonb_build_array(jsonb_build_object(
        'sex', null, 'constant', 370, 'kcal', v_grund,
        'terms', jsonb_build_array(jsonb_build_object('factor', 21.6, 'input', 'lean_mass_kg'))));
    end if;
  else
    if v_formel = 'mifflin_st_jeor' then
      v_m := 10 * p_weight_kg + 6.25 * p_height_cm - 5 * p_age_years + 5;
      v_w := 10 * p_weight_kg + 6.25 * p_height_cm - 5 * p_age_years - 161;
    else
      v_m := 88.362 + 13.397 * p_weight_kg + 4.799 * p_height_cm - 5.677 * p_age_years;
      v_w := 447.593 + 9.247 * p_weight_kg + 3.098 * p_height_cm - 4.330 * p_age_years;
    end if;
    if p_sex in ('male', 'unspecified') then
      v_varianten := v_varianten || jsonb_build_array(jsonb_build_object(
        'sex', 'male',
        'constant', case v_formel when 'mifflin_st_jeor' then 5 else 88.362 end,
        'kcal', round(v_m)::integer,
        'terms', case v_formel
          when 'mifflin_st_jeor' then jsonb_build_array(
            jsonb_build_object('factor', 10, 'input', 'weight_kg'),
            jsonb_build_object('factor', 6.25, 'input', 'height_cm'),
            jsonb_build_object('factor', -5, 'input', 'age_years'))
          else jsonb_build_array(
            jsonb_build_object('factor', 13.397, 'input', 'weight_kg'),
            jsonb_build_object('factor', 4.799, 'input', 'height_cm'),
            jsonb_build_object('factor', -5.677, 'input', 'age_years'))
        end));
    end if;
    if p_sex in ('female', 'unspecified') then
      v_varianten := v_varianten || jsonb_build_array(jsonb_build_object(
        'sex', 'female',
        'constant', case v_formel when 'mifflin_st_jeor' then -161 else 447.593 end,
        'kcal', round(v_w)::integer,
        'terms', case v_formel
          when 'mifflin_st_jeor' then jsonb_build_array(
            jsonb_build_object('factor', 10, 'input', 'weight_kg'),
            jsonb_build_object('factor', 6.25, 'input', 'height_cm'),
            jsonb_build_object('factor', -5, 'input', 'age_years'))
          else jsonb_build_array(
            jsonb_build_object('factor', 9.247, 'input', 'weight_kg'),
            jsonb_build_object('factor', 3.098, 'input', 'height_cm'),
            jsonb_build_object('factor', -4.330, 'input', 'age_years'))
        end));
    end if;
    -- Ohne Angabe "weiblich" oder "männlich": das Mittel beider Varianten,
    -- sichtbar vermerkt (Punkt 16).
    if p_sex = 'unspecified' then
      v_gemittelt := true;
      v_grund := round((round(v_m) + round(v_w)) / 2.0)::integer;
    elsif p_sex = 'male' then
      v_grund := round(v_m)::integer;
    else
      v_grund := round(v_w)::integer;
    end if;
  end if;

  -- Punkt 17: Gesamtumsatz.
  v_gesamt := round(v_grund * p_pal)::integer;

  -- Punkt 18: Energieziel, nie unter dem Grundumsatz.
  if p_goal = 'maintain' then
    v_regel := 'maintain';
    v_aenderung := 0;
  elsif p_goal = 'lose' then
    v_aenderung := -least(c_defizit, round(v_gesamt * c_defizit_anteil)::integer);
    v_regel := case when -v_aenderung < c_defizit then 'deficit_capped' else 'deficit' end;
  else
    v_regel := 'surplus';
    v_aenderung := c_ueberschuss;
  end if;
  v_energie := v_gesamt + v_aenderung;
  v_unten := v_energie < v_grund;
  if v_unten then
    v_energie := v_grund;
  end if;
  -- Punkt 22: Die Beratung überschreibt, auch unter die Untergrenze.
  v_energie_eff := coalesce((v_ueber ->> 'energy_kcal')::integer, v_energie);

  -- Punkt 19: Eiweiß je kg; ab 65 Jahren mehr, bei Muskelaufbau oder im
  -- Training mehr (ANN-618: "im Training" heißt: das Profil hängt an einem
  -- Trainingsverhältnis). Es gilt die höchste zutreffende Stufe.
  v_faktor := c_eiweiss;
  v_grundlage := 'standard';
  if p_age_years >= c_alter_ab then
    v_faktor := c_eiweiss_alter;
    v_grundlage := 'from_65';
  end if;
  if p_goal = 'build_muscle' or coalesce(p_in_training, false) then
    v_faktor := c_eiweiss_aufbau;
    v_grundlage := 'muscle_or_training';
  end if;
  v_eiweiss := round(v_faktor * p_weight_kg)::integer;
  v_eiweiss_eff := coalesce((v_ueber ->> 'protein_g')::integer, v_eiweiss);

  -- Fett mindestens 30 % der Energie (gerechnet mit genau 30 %),
  -- Kohlenhydrate der Rest - je aus dem berechneten und aus dem geltenden
  -- Energieziel.
  v_fett := round(v_energie * c_fett_anteil / c_kcal_fett)::integer;
  v_fett_eff := coalesce((v_ueber ->> 'fat_g')::integer,
                         round(v_energie_eff * c_fett_anteil / c_kcal_fett)::integer);
  v_kh := greatest(0, round((v_energie - c_kcal_eiweiss * v_eiweiss - c_kcal_fett * v_fett)
                            / c_kcal_kh::numeric)::integer);
  v_kh_eff := coalesce((v_ueber ->> 'carbohydrate_g')::integer,
                       greatest(0, round((v_energie_eff - c_kcal_eiweiss * v_eiweiss_eff
                                          - c_kcal_fett * v_fett_eff) / c_kcal_kh::numeric)::integer));

  -- Punkt 20: Wasser.
  v_wasser := greatest(c_wasser_mindest, (round(c_wasser_je_kg * p_weight_kg / 10) * 10)::integer);
  v_wasser_eff := coalesce((v_ueber ->> 'water_ml')::integer, v_wasser);

  -- Punkt 21: Zielgewicht nicht unter BMI 18,5 - aufgerundet, damit das
  -- angezeigte Gewicht selbst nicht darunter liegt.
  v_ziel_unten := round(ceil(c_bmi_unten * (p_height_cm / 100.0) ^ 2 * 10) / 10.0, 1);
  -- Zeit bis zum Ziel nur aus dem geltenden Energieziel und nur, wenn es in
  -- die Richtung des Ziels weist.
  v_tagesdiff := v_gesamt - v_energie_eff;
  if p_target_weight_kg is not null
     and ((p_weight_kg > p_target_weight_kg and v_tagesdiff > 0)
          or (p_weight_kg < p_target_weight_kg and v_tagesdiff < 0)) then
    v_wochen := ceil(abs(p_weight_kg - p_target_weight_kg) * c_kcal_je_kg
                     / abs(v_tagesdiff) / 7.0)::integer;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'inputs', jsonb_build_object(
      'weight_kg', p_weight_kg, 'height_cm', p_height_cm, 'age_years', p_age_years,
      'sex', p_sex, 'body_fat_percent', p_body_fat_percent, 'pal', p_pal, 'goal', p_goal,
      'formula', p_formula, 'in_training', coalesce(p_in_training, false)),
    'bmr', jsonb_build_object(
      'formula', v_formel, 'lean_mass_kg', v_mager, 'averaged', v_gemittelt,
      'variants', v_varianten, 'kcal', v_grund),
    'tee', jsonb_build_object('pal', p_pal, 'kcal', v_gesamt),
    'energy', jsonb_build_object(
      'rule', v_regel, 'change_kcal', v_aenderung, 'deficit_max_kcal', c_defizit,
      'deficit_max_share', c_defizit_anteil, 'floor_applied', v_unten,
      'computed_kcal', v_energie, 'kcal', v_energie_eff,
      'overridden', v_ueber ? 'energy_kcal', 'below_bmr', v_energie_eff < v_grund),
    'protein', jsonb_build_object(
      'g_per_kg', v_faktor, 'basis', v_grundlage, 'computed_g', v_eiweiss, 'g', v_eiweiss_eff,
      'kcal_per_g', c_kcal_eiweiss, 'overridden', v_ueber ? 'protein_g'),
    'fat', jsonb_build_object(
      'share', c_fett_anteil, 'computed_g', v_fett, 'g', v_fett_eff,
      'kcal_per_g', c_kcal_fett, 'overridden', v_ueber ? 'fat_g'),
    'carbohydrate', jsonb_build_object(
      'computed_g', v_kh, 'g', v_kh_eff, 'kcal_per_g', c_kcal_kh,
      'overridden', v_ueber ? 'carbohydrate_g'),
    'water', jsonb_build_object(
      'ml_per_kg', c_wasser_je_kg, 'minimum_ml', c_wasser_mindest,
      'floor_applied', v_wasser = c_wasser_mindest, 'computed_ml', v_wasser, 'ml', v_wasser_eff,
      'overridden', v_ueber ? 'water_ml'),
    'target_weight', jsonb_build_object(
      'kg', p_target_weight_kg, 'floor_kg', v_ziel_unten, 'bmi_floor', c_bmi_unten,
      'below_floor', p_target_weight_kg is not null and p_target_weight_kg < v_ziel_unten,
      'weeks', v_wochen, 'kcal_per_kg', c_kcal_je_kg)
  );
end;
$$;

COMMENT ON FUNCTION app.nutrition_calculation(p_weight_kg numeric, p_height_cm numeric, p_age_years integer, p_sex text, p_body_fat_percent numeric, p_pal numeric, p_goal text, p_formula text, p_in_training boolean, p_overrides jsonb, p_target_weight_kg numeric) IS 'ERN-001 (ADR-027 Punkte 16 bis 22, ADR-006 Punkt 14, ANN-618): Grundumsatz, Gesamtumsatz und Zielwerte mit Rechenweg - die eine Stelle für Formeln, Stufen, Untergrenzen und Rundung. Eingaben: Gewicht, Größe, Alter, Geschlecht für die Formel, Körperfett, PAL, Ziel, Formel, Trainingsverhältnis, Überschreibungen der Beratung, Zielgewicht. Keine Diagnose als Eingabe. Fehlt eine Eingabe: status missing.';

CREATE TABLE public.nutrition_consent_records (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    record_kind text NOT NULL,
    occurred_on date NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by uuid NOT NULL,
    source text DEFAULT 'practice'::text NOT NULL,
    platform_access_id uuid,
    platform_access_kind text,
    representative_name text,
    wording_version text,
    CONSTRAINT nutrition_consent_records_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT nutrition_consent_records_record_kind_check CHECK ((record_kind = ANY (ARRAY['consent_granted'::text, 'consent_withdrawn'::text]))),
    CONSTRAINT nutrition_consent_records_representative_name_check CHECK (((representative_name IS NULL) OR ((length(btrim(representative_name)) >= 1) AND (length(btrim(representative_name)) <= 200)))),
    CONSTRAINT nutrition_consent_records_representative_shape CHECK (((NOT (platform_access_kind IS DISTINCT FROM 'legal_representative'::text)) = (representative_name IS NOT NULL))),
    CONSTRAINT nutrition_consent_records_source_check CHECK ((source = ANY (ARRAY['practice'::text, 'platform'::text]))),
    CONSTRAINT nutrition_consent_records_source_shape CHECK ((((source = 'platform'::text) AND (platform_access_id IS NOT NULL) AND (platform_access_kind IS NOT NULL) AND (wording_version IS NOT NULL)) OR ((source = 'practice'::text) AND (platform_access_id IS NULL) AND (platform_access_kind IS NULL) AND (wording_version IS NULL)))),
    CONSTRAINT nutrition_consent_records_wording_version_check CHECK ((wording_version ~ '^[0-9]{4}-[0-9]{2}$'::text))
);

COMMENT ON TABLE public.nutrition_consent_records IS 'ERN-001 (ADR-027 Punkt 3): ausdrückliche Einwilligung "Ernährungsberatung" nach Art. 9 Abs. 2 lit. a DSGVO am Profil, auch an einer Akte. Nur anhängen, nie ändern: der Stand ist die jüngste Zeile. Ohne erteilte Einwilligung kein Eintrag; ein Widerruf hält Tagebuch und Gewicht an. Datenklasse: Ernährungsberatung, fällt mit dem Profil.';

CREATE FUNCTION app.nutrition_consent(p_profile_id uuid) RETURNS public.nutrition_consent_records
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.*
  from public.nutrition_consent_records r
  where r.profile_id = p_profile_id
  order by r.recorded_at desc, r.id desc
  limit 1
$$;

CREATE FUNCTION app.nutrition_consent_granted(p_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((app.nutrition_consent(p_profile_id)).record_kind = 'consent_granted', false)
$$;

COMMENT ON FUNCTION app.nutrition_consent_granted(p_profile_id uuid) IS 'ERN-001 (ADR-027 Punkt 3): ist die Einwilligung "Ernährungsberatung" am Profil erteilt? Die jüngste Zeile entscheidet. Ohne sie kein Eintrag.';

CREATE FUNCTION app.nutrition_diary_amount(p_food jsonb, p_amount numeric, p_portion_label text, p_portion_count numeric) RETURNS TABLE(amount numeric, portion_label text, portion_amount numeric, portion_count numeric)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_portion numeric;
begin
  if p_portion_label is not null then
    if p_amount is not null or p_portion_count is null
       or p_portion_count <= 0 or p_portion_count > 20 then
      raise exception 'portion or amount' using errcode = '22023';
    end if;
    select (p ->> 'amount')::numeric into v_portion
    from jsonb_array_elements(p_food -> 'portions') p
    where p ->> 'label' = p_portion_label
    limit 1;
    if v_portion is null then
      raise exception 'unknown portion' using errcode = '22023';
    end if;
    return query select round(v_portion * p_portion_count, 1), p_portion_label, v_portion,
                        round(p_portion_count, 2);
    return;
  end if;
  if p_portion_count is not null or p_amount is null or p_amount <= 0 or p_amount > 5000 then
    raise exception 'portion or amount' using errcode = '22023';
  end if;
  return query select round(p_amount, 1), null::text, null::numeric, null::numeric;
end;
$$;

CREATE FUNCTION app.nutrition_diary_day_json(p_profile_id uuid, p_day date, p_origin boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'day', p_day,
    'meals', (
      select jsonb_agg(jsonb_build_object(
               'meal', m.meal,
               'entries', coalesce((
                 select jsonb_agg(app.nutrition_diary_entry_json(e, p_origin)
                                  order by e.created_at, e.id)
                 from public.nutrition_diary_entries e
                 where e.profile_id = p_profile_id and e.eaten_on = p_day and e.meal = m.meal
               ), '[]'::jsonb),
               'totals', app.nutrition_diary_totals(p_profile_id, p_day, m.meal))
             order by m.nr)
      from unnest(array['breakfast', 'lunch', 'dinner', 'snack']) with ordinality m(meal, nr)
    ),
    'totals', app.nutrition_diary_totals(p_profile_id, p_day, null),
    'water_ml', coalesce((
      select w.water_ml from public.nutrition_water_days w
      where w.profile_id = p_profile_id and w.drunk_on = p_day), 0)
  )
$$;

CREATE TABLE public.nutrition_diary_entries (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    eaten_on date NOT NULL,
    meal text NOT NULL,
    food_kind text NOT NULL,
    catalog_food_id uuid,
    custom_food_id uuid,
    food_name text NOT NULL,
    food_brand text,
    base_unit text NOT NULL,
    energy_kcal numeric(5,1) NOT NULL,
    protein_g numeric(5,2) NOT NULL,
    fat_g numeric(5,2) NOT NULL,
    carbohydrate_g numeric(5,2) NOT NULL,
    sugar_g numeric(5,2),
    fibre_g numeric(5,2),
    saturated_fat_g numeric(5,2),
    salt_g numeric(6,3),
    amount numeric(6,1) NOT NULL,
    portion_label text,
    portion_amount numeric(6,1),
    portion_count numeric(4,2),
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT nutrition_diary_entries_amount_check CHECK (((amount > (0)::numeric) AND (amount <= (5000)::numeric))),
    CONSTRAINT nutrition_diary_entries_base_unit_check CHECK ((base_unit = ANY (ARRAY['g'::text, 'ml'::text]))),
    CONSTRAINT nutrition_diary_entries_carbohydrate_g_check CHECK ((carbohydrate_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT nutrition_diary_entries_energy_kcal_check CHECK ((energy_kcal BETWEEN (0)::numeric AND (950)::numeric)),
    CONSTRAINT nutrition_diary_entries_fat_g_check CHECK ((fat_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT nutrition_diary_entries_fibre_g_check CHECK (((fibre_g IS NULL) OR (fibre_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT nutrition_diary_entries_food_brand_check CHECK (((food_brand IS NULL) OR ((length(btrim(food_brand)) >= 1) AND (length(btrim(food_brand)) <= 200)))),
    CONSTRAINT nutrition_diary_entries_food_kind_check CHECK ((food_kind = ANY (ARRAY['catalog'::text, 'practice'::text, 'person'::text]))),
    CONSTRAINT nutrition_diary_entries_food_name_check CHECK (((length(btrim(food_name)) >= 1) AND (length(btrim(food_name)) <= 300))),
    CONSTRAINT nutrition_diary_entries_food_shape CHECK ((((food_kind = 'catalog'::text) AND (custom_food_id IS NULL)) OR ((food_kind = ANY (ARRAY['practice'::text, 'person'::text])) AND (catalog_food_id IS NULL)))),
    CONSTRAINT nutrition_diary_entries_macros_fit CHECK ((((protein_g + fat_g) + carbohydrate_g) <= (105)::numeric)),
    CONSTRAINT nutrition_diary_entries_meal_check CHECK ((meal = ANY (ARRAY['breakfast'::text, 'lunch'::text, 'dinner'::text, 'snack'::text]))),
    CONSTRAINT nutrition_diary_entries_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT nutrition_diary_entries_portion_amount_check CHECK (((portion_amount IS NULL) OR ((portion_amount > (0)::numeric) AND (portion_amount <= (5000)::numeric)))),
    CONSTRAINT nutrition_diary_entries_portion_count_check CHECK (((portion_count IS NULL) OR ((portion_count > (0)::numeric) AND (portion_count <= (20)::numeric)))),
    CONSTRAINT nutrition_diary_entries_portion_label_check CHECK (((portion_label IS NULL) OR ((length(btrim(portion_label)) >= 1) AND (length(btrim(portion_label)) <= 60)))),
    CONSTRAINT nutrition_diary_entries_portion_shape CHECK ((((portion_label IS NULL) = (portion_amount IS NULL)) AND ((portion_label IS NULL) = (portion_count IS NULL)))),
    CONSTRAINT nutrition_diary_entries_protein_g_check CHECK ((protein_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT nutrition_diary_entries_salt_g_check CHECK (((salt_g IS NULL) OR (salt_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT nutrition_diary_entries_saturated_fat_g_check CHECK (((saturated_fat_g IS NULL) OR (saturated_fat_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT nutrition_diary_entries_sugar_g_check CHECK (((sugar_g IS NULL) OR (sugar_g BETWEEN (0)::numeric AND (100)::numeric)))
);

COMMENT ON TABLE public.nutrition_diary_entries IS 'ERN-007 (ADR-027 Punkte 9 und 10): Einträge des Ernährungstagebuchs - Tag, Mahlzeit, Lebensmittel mit seinem Stand je 100 g bzw. ml beim Eintragen (ANN-660), Menge oder Portion. Eingetragen von der Person oder ihrer rechtlichen Vertretung auf der Plattform, nur mit Einwilligung und eingeschaltetem Tagebuch. Lesen allein mit app.can_counsel_nutrition. Datenklasse: Ernährungsberatung, fällt mit dem Profil.';

CREATE FUNCTION app.nutrition_diary_entry_json(p_entry public.nutrition_diary_entries, p_origin boolean) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_entry.id,
    'eaten_on', p_entry.eaten_on,
    'meal', p_entry.meal,
    'food_kind', p_entry.food_kind,
    'food_id', coalesce(p_entry.catalog_food_id, p_entry.custom_food_id),
    'name', p_entry.food_name,
    'brand', p_entry.food_brand,
    'base_unit', p_entry.base_unit,
    'amount', p_entry.amount,
    'portion_label', p_entry.portion_label,
    'portion_amount', p_entry.portion_amount,
    'portion_count', p_entry.portion_count,
    'energy_kcal', round(p_entry.energy_kcal * p_entry.amount / 100),
    'protein_g', round(p_entry.protein_g * p_entry.amount / 100, 1),
    'fat_g', round(p_entry.fat_g * p_entry.amount / 100, 1),
    'carbohydrate_g', round(p_entry.carbohydrate_g * p_entry.amount / 100, 1),
    'per_100', jsonb_build_object(
      'energy_kcal', p_entry.energy_kcal, 'protein_g', p_entry.protein_g,
      'fat_g', p_entry.fat_g, 'carbohydrate_g', p_entry.carbohydrate_g,
      'sugar_g', p_entry.sugar_g, 'fibre_g', p_entry.fibre_g,
      'saturated_fat_g', p_entry.saturated_fat_g, 'salt_g', p_entry.salt_g)
  )
  || case when p_origin then jsonb_build_object(
       'created_at', p_entry.created_at, 'recorded_by_kind', p_entry.platform_access_kind)
     else '{}'::jsonb end
$$;

CREATE TABLE public.nutrition_profiles (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    started_on date NOT NULL,
    ended_on date,
    ended_by uuid,
    height_cm smallint NOT NULL,
    formula_sex text NOT NULL,
    body_fat_percent numeric(3,1),
    activity_pal numeric(2,1) NOT NULL,
    goal text NOT NULL,
    bmr_formula text DEFAULT 'standard'::text NOT NULL,
    target_weight_kg numeric(4,1),
    target_weight_source text,
    energy_kcal_override smallint,
    protein_g_override smallint,
    fat_g_override smallint,
    carbohydrate_g_override smallint,
    water_ml_override smallint,
    notes text,
    diary_enabled boolean DEFAULT false NOT NULL,
    diary_changed_at timestamp with time zone,
    diary_changed_by_kind text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    diary_hide_numbers boolean DEFAULT false NOT NULL,
    CONSTRAINT nutrition_profiles_activity_pal_check CHECK ((activity_pal = ANY (ARRAY[1.4, 1.6, 1.8, 2.0]))),
    CONSTRAINT nutrition_profiles_bmr_formula_check CHECK ((bmr_formula = ANY (ARRAY['standard'::text, 'katch_mcardle'::text, 'harris_benedict_revised'::text]))),
    CONSTRAINT nutrition_profiles_body_fat_percent_check CHECK (((body_fat_percent IS NULL) OR (body_fat_percent BETWEEN (3)::numeric AND (70)::numeric))),
    CONSTRAINT nutrition_profiles_carbohydrate_g_override_check CHECK ((carbohydrate_g_override BETWEEN 0 AND 900)),
    CONSTRAINT nutrition_profiles_diary_changed_by_kind_check CHECK ((diary_changed_by_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT nutrition_profiles_diary_pair CHECK (((diary_changed_at IS NULL) = (diary_changed_by_kind IS NULL))),
    CONSTRAINT nutrition_profiles_end_after_start CHECK (((ended_on IS NULL) OR (ended_on >= started_on))),
    CONSTRAINT nutrition_profiles_ended_pair CHECK (((ended_on IS NULL) = (ended_by IS NULL))),
    CONSTRAINT nutrition_profiles_energy_kcal_override_check CHECK ((energy_kcal_override BETWEEN 500 AND 6000)),
    CONSTRAINT nutrition_profiles_fat_g_override_check CHECK ((fat_g_override BETWEEN 10 AND 400)),
    CONSTRAINT nutrition_profiles_formula_sex_check CHECK ((formula_sex = ANY (ARRAY['female'::text, 'male'::text, 'unspecified'::text]))),
    CONSTRAINT nutrition_profiles_goal_check CHECK ((goal = ANY (ARRAY['lose'::text, 'maintain'::text, 'build_muscle'::text, 'gain'::text]))),
    CONSTRAINT nutrition_profiles_height_cm_check CHECK ((height_cm BETWEEN 100 AND 250)),
    CONSTRAINT nutrition_profiles_katch_needs_body_fat CHECK (((bmr_formula <> 'katch_mcardle'::text) OR (body_fat_percent IS NOT NULL))),
    CONSTRAINT nutrition_profiles_notes_check CHECK (((notes IS NULL) OR (length(notes) BETWEEN 1 AND 4000))),
    CONSTRAINT nutrition_profiles_protein_g_override_check CHECK ((protein_g_override BETWEEN 10 AND 400)),
    CONSTRAINT nutrition_profiles_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT nutrition_profiles_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND (patient_id = relationship_id)) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id = relationship_id)))),
    CONSTRAINT nutrition_profiles_target_weight_kg_check CHECK (((target_weight_kg IS NULL) OR (target_weight_kg BETWEEN (30)::numeric AND (300)::numeric))),
    CONSTRAINT nutrition_profiles_target_weight_pair CHECK (((target_weight_kg IS NULL) = (target_weight_source IS NULL))),
    CONSTRAINT nutrition_profiles_target_weight_source_check CHECK ((target_weight_source = ANY (ARRAY['counsellor'::text, 'person'::text]))),
    CONSTRAINT nutrition_profiles_water_ml_override_check CHECK ((water_ml_override BETWEEN 500 AND 8000))
);

COMMENT ON TABLE public.nutrition_profiles IS 'ERN-001 (ADR-027 Abschnitt A): Ernährungsprofil an genau einem Verhältnis - Körperdaten, Aktivität (PAL), Ziel, Zielgewicht, Überschreibungen und Notizen der Beratung, Schalter des Tagebuchs. Keine Diagnose, kein Befund. Lesen allein mit app.can_counsel_nutrition (ADR-021 Punkt 11). Datenklasse: Ernährungsberatung, drei Jahre nach ended_on; fällt das Verhältnis früher, mit ihm (ADR-008 Fassung 6). Kein Tabellenrecht zum Schreiben (ADR-004).';

COMMENT ON COLUMN public.nutrition_profiles.ended_on IS 'Ende der Beratung - Anker der Frist (ADR-027 Punkt 6). Ohne Ende läuft keine Frist.';

COMMENT ON COLUMN public.nutrition_profiles.formula_sex IS 'Geschlecht allein für die Formel des Grundumsatzes (ADR-027 Punkt 16); unspecified rechnet mit dem Mittel beider Varianten.';

COMMENT ON COLUMN public.nutrition_profiles.diary_hide_numbers IS 'ERN-008 (ADR-027 Punkt 11): "Zahlen ausblenden" - die Person sieht ihr Tagebuch ohne Kalorien und Makronährstoffe. Ihre Einstellung, keine Vorgabe; die Beratung sieht die Zahlen.';

CREATE FUNCTION app.nutrition_diary_favorites_json(p_profile public.nutrition_profiles) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'food', x.essen, 'amount', l.amount, 'portion_label', l.portion_label,
           'portion_count', l.portion_count)
         order by x.essen ->> 'name', x.id), '[]'::jsonb)
  from (
    select f.id, f.food_kind, coalesce(f.catalog_food_id, f.custom_food_id) as food_id,
           app.nutrition_diary_food(p_profile, f.food_kind,
                                    coalesce(f.catalog_food_id, f.custom_food_id)) as essen
    from public.nutrition_diary_favorites f
    where f.profile_id = p_profile.id
  ) x
  left join lateral (
    select e.amount, e.portion_label, e.portion_count
    from public.nutrition_diary_entries e
    where e.profile_id = p_profile.id and e.food_kind = x.food_kind
      and coalesce(e.catalog_food_id, e.custom_food_id) = x.food_id
    order by e.created_at desc
    limit 1
  ) l on true
  where x.essen is not null
$$;

CREATE FUNCTION app.nutrition_diary_food(p_profile public.nutrition_profiles, p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
           'kind', 'catalog', 'id', b.id, 'source', b.source, 'source_code', b.source_code,
           'name', b.name, 'brand', b.brand, 'base_unit', b.base_unit,
           'per_100', jsonb_build_object(
             'energy_kcal', b.energy_kcal, 'protein_g', b.protein_g, 'fat_g', b.fat_g,
             'carbohydrate_g', b.carbohydrate_g, 'sugar_g', b.sugar_g, 'fibre_g', b.fibre_g,
             'saturated_fat_g', b.saturated_fat_g, 'salt_g', b.salt_g),
           'portions', b.portions)
  from public.food_catalog b
  where p_kind = 'catalog' and b.id = p_id and b.retired_at is null
  union all
  select app.custom_food_json(c) - 'updated_at'
  from public.custom_foods c
  where p_kind = c.owner_kind and c.id = p_id
    and c.organization_id = p_profile.organization_id
    and ((c.owner_kind = 'practice' and c.archived_at is null)
         or (c.owner_kind = 'person' and c.profile_id = p_profile.id))
  limit 1
$$;

CREATE FUNCTION app.nutrition_diary_json(p_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'hide_numbers', (select p.diary_hide_numbers from public.nutrition_profiles p
                     where p.id = p_profile_id),
    'entries', coalesce((
      select jsonb_agg(app.nutrition_diary_entry_json(e, true)
                       order by e.eaten_on, e.meal, e.created_at, e.id)
      from public.nutrition_diary_entries e where e.profile_id = p_profile_id), '[]'::jsonb),
    'water', coalesce((
      select jsonb_agg(jsonb_build_object('drunk_on', w.drunk_on, 'water_ml', w.water_ml,
                                          'recorded_by_kind', w.platform_access_kind)
                       order by w.drunk_on)
      from public.nutrition_water_days w where w.profile_id = p_profile_id), '[]'::jsonb),
    'favorites', coalesce((
      select jsonb_agg(jsonb_build_object(
               'food_kind', f.food_kind,
               'food_id', coalesce(f.catalog_food_id, f.custom_food_id),
               'name', coalesce(c.name, u.name),
               'created_at', f.created_at,
               'recorded_by_kind', f.platform_access_kind)
             order by f.created_at, f.id)
      from public.nutrition_diary_favorites f
      left join public.food_catalog c on c.id = f.catalog_food_id
      left join public.custom_foods u on u.id = f.custom_food_id
      where f.profile_id = p_profile_id), '[]'::jsonb)
  )
$$;

COMMENT ON FUNCTION app.nutrition_diary_json(p_profile_id uuid) IS 'ERN-007: das Ernährungstagebuch eines Profils vollständig - Einträge mit Stand und Werten, Wasser je Tag; wer eingetragen hat. Ohne Rechteprüfung: nur aus der Auskunft und (ohne recorded_by_kind) dem Export der Plattform.';

CREATE FUNCTION app.nutrition_diary_platform_shape(d jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select d || jsonb_build_object(
    'entries', (select coalesce(jsonb_agg(e - 'recorded_by_kind'), '[]'::jsonb)
                from jsonb_array_elements(d -> 'entries') e),
    'water', (select coalesce(jsonb_agg(w - 'recorded_by_kind'), '[]'::jsonb)
              from jsonb_array_elements(d -> 'water') w),
    'favorites', (select coalesce(jsonb_agg(f - 'recorded_by_kind'), '[]'::jsonb)
                  from jsonb_array_elements(coalesce(d -> 'favorites', '[]'::jsonb)) f))
$$;

CREATE FUNCTION app.nutrition_diary_recent(p_profile public.nutrition_profiles) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x.eintrag order by x.zuletzt desc), '[]'::jsonb)
  from (
    select l.zuletzt,
           jsonb_build_object(
             'food', app.nutrition_diary_food(p_profile, l.food_kind, l.food_id),
             'amount', l.amount, 'portion_label', l.portion_label,
             'portion_count', l.portion_count) as eintrag
    from (
      select distinct on (e.food_kind, coalesce(e.catalog_food_id, e.custom_food_id))
             e.food_kind, coalesce(e.catalog_food_id, e.custom_food_id) as food_id,
             e.amount, e.portion_label, e.portion_count, e.created_at as zuletzt
      from public.nutrition_diary_entries e
      where e.profile_id = p_profile.id
        and coalesce(e.catalog_food_id, e.custom_food_id) is not null
        and e.eaten_on > app.training_today(p_profile.organization_id)
                         - app.nutrition_diary_rule('recent_days')
      order by e.food_kind, coalesce(e.catalog_food_id, e.custom_food_id), e.created_at desc
    ) l
    where app.nutrition_diary_food(p_profile, l.food_kind, l.food_id) is not null
    order by l.zuletzt desc
    limit app.nutrition_diary_rule('recent_count')
  ) x
$$;

CREATE FUNCTION app.nutrition_diary_reminder_live(p_reminder_id uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select (p_at at time zone o.time_zone)::time = r.remind_at
           and p_at > now() - interval '2 hours'
           and a.access_kind in ('self', 'legal_representative')
           and app.notification_access_live(a.id)
           and n.ended_on is null and n.diary_enabled
           and app.nutrition_consent_granted(n.id)
           and a.organization_id = n.organization_id
           and a.relationship_kind = n.relationship_kind
           and a.relationship_id = n.relationship_id
    from public.nutrition_diary_reminders r
    join public.platform_accesses a on a.id = r.access_id
    join public.nutrition_profiles n on n.id = r.profile_id
    join public.organizations o on o.id = r.organization_id
    where r.id = p_reminder_id
  ), false)
$$;

CREATE FUNCTION app.nutrition_diary_rule(p_key text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_key
    when 'glass_ml' then 250          -- ein Tipp: ein Glas
    when 'water_max_ml' then 10000    -- mehr an einem Tag wird nicht gezählt
    when 'water_step_max_ml' then 2000
    when 'entries_per_day' then 80    -- Grenze gegen Massenanlage
    when 'recent_days' then 60        -- "zuletzt" schaut so weit zurück
    when 'recent_count' then 15
  end
$$;

COMMENT ON FUNCTION app.nutrition_diary_rule(p_key text) IS 'ERN-007 (ANN-661): die Konstanten des Ernährungstagebuchs an einer Stelle - Glas Wasser, Höchstmengen, Grenze je Tag, Fenster von "zuletzt".';

CREATE FUNCTION app.nutrition_diary_totals(p_profile_id uuid, p_day date, p_meal text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'energy_kcal', coalesce(round(sum(e.energy_kcal * e.amount / 100)), 0),
    'protein_g', coalesce(round(sum(e.protein_g * e.amount / 100), 1), 0),
    'fat_g', coalesce(round(sum(e.fat_g * e.amount / 100), 1), 0),
    'carbohydrate_g', coalesce(round(sum(e.carbohydrate_g * e.amount / 100), 1), 0))
  from public.nutrition_diary_entries e
  where e.profile_id = p_profile_id and e.eaten_on = p_day
    and (p_meal is null or e.meal = p_meal)
$$;

CREATE FUNCTION app.nutrition_own_foods_json(p_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(
    (app.custom_food_json(p) - 'kind' - 'source' - 'source_code')
      || jsonb_build_object('created_at', p.created_at,
                            'recorded_by_kind', p.platform_access_kind)
    order by p.name_key, p.id), '[]'::jsonb)
  from public.custom_foods p
  where p.profile_id = p_profile_id and p.owner_kind = 'person'
$$;

CREATE FUNCTION app.nutrition_platform_json(p_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.nutrition_platform_shape(app.nutrition_profile_json(p_profile_id))
$$;

COMMENT ON FUNCTION app.nutrition_platform_json(p_profile_id uuid) IS 'ERN-002/ERN-007 (ADR-023 Punkt 22): ein Ernährungsprofil für den Export der Plattform mit fester Schlüsselliste und Tagebuch - ohne Notizen der Beratung, ohne Kennungen, ohne wer eingetragen hat. Ohne Rechteprüfung.';

CREATE FUNCTION app.nutrition_platform_shape(j jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'started_on', j -> 'started_on',
    'ended_on', j -> 'ended_on',
    'height_cm', j -> 'height_cm',
    'formula_sex', j -> 'formula_sex',
    'body_fat_percent', j -> 'body_fat_percent',
    'activity_pal', j -> 'activity_pal',
    'goal', j -> 'goal',
    'target_weight_kg', j -> 'target_weight_kg',
    'target_weight_source', j -> 'target_weight_source',
    'diary_enabled', j -> 'diary_enabled',
    'diary_changed_at', j -> 'diary_changed_at',
    'consent', case when j -> 'consent' = 'null'::jsonb then null else
      (j -> 'consent') - 'representative_name' - 'platform_access_kind' end,
    'weights', (
      select coalesce(jsonb_agg(w - 'recorded_by_kind'), '[]'::jsonb)
      from jsonb_array_elements(j -> 'weights') w),
    'targets', j -> 'targets',
    'own_foods', (
      select coalesce(jsonb_agg(f - 'recorded_by_kind'), '[]'::jsonb)
      from jsonb_array_elements(j -> 'own_foods') f)
  )
  -- ERN-007: das Tagebuch nur, wo es mitkommt (Export), ohne wer eingetragen hat.
  || case when j ? 'diary' then jsonb_build_object('diary', app.nutrition_diary_platform_shape(j -> 'diary'))
          else '{}'::jsonb end
  where j is not null
$$;

CREATE FUNCTION app.nutrition_profile_base_json(p_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p.id,
    'relationship_kind', p.relationship_kind,
    'started_on', p.started_on,
    'ended_on', p.ended_on,
    'height_cm', p.height_cm,
    'formula_sex', p.formula_sex,
    'body_fat_percent', p.body_fat_percent,
    'activity_pal', p.activity_pal,
    'goal', p.goal,
    'bmr_formula', p.bmr_formula,
    'target_weight_kg', p.target_weight_kg,
    'target_weight_source', p.target_weight_source,
    'overrides', jsonb_build_object(
      'energy_kcal', p.energy_kcal_override,
      'protein_g', p.protein_g_override,
      'fat_g', p.fat_g_override,
      'carbohydrate_g', p.carbohydrate_g_override,
      'water_ml', p.water_ml_override),
    'notes', p.notes,
    'diary_enabled', p.diary_enabled,
    'diary_changed_at', p.diary_changed_at,
    'diary_changed_by_kind', p.diary_changed_by_kind,
    'created_at', p.created_at,
    'updated_at', p.updated_at,
    'consent', (
      select jsonb_build_object(
        'state', case c.record_kind when 'consent_granted' then 'granted' else 'withdrawn' end,
        'occurred_on', c.occurred_on,
        'source', c.source,
        'platform_access_kind', c.platform_access_kind,
        'representative_name', c.representative_name)
      from app.nutrition_consent(p.id) c
      where c.id is not null),
    'consent_history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'record_kind', r.record_kind, 'occurred_on', r.occurred_on, 'source', r.source,
        'platform_access_kind', r.platform_access_kind,
        'representative_name', r.representative_name,
        'wording_version', r.wording_version, 'recorded_at', r.recorded_at)
        order by r.recorded_at desc, r.id desc)
      from public.nutrition_consent_records r where r.profile_id = p.id), '[]'::jsonb),
    'weights', coalesce((
      select jsonb_agg(jsonb_build_object(
        'measured_on', w.measured_on, 'weight_kg', w.weight_kg, 'source', w.source,
        'recorded_by_kind', w.platform_access_kind)
        order by w.measured_on desc)
      from public.nutrition_weight_entries w where w.profile_id = p.id), '[]'::jsonb),
    'targets', app.nutrition_profile_targets(p.id),
    'own_foods', app.nutrition_own_foods_json(p.id)
  )
  from public.nutrition_profiles p
  where p.id = p_profile_id
$$;

COMMENT ON FUNCTION app.nutrition_profile_base_json(p_profile_id uuid) IS 'ERN-007: ein Ernährungsprofil ohne Tagebuch - für die Ansicht der Beratung und der Plattform. Ohne Rechteprüfung.';

CREATE FUNCTION app.nutrition_profile_for_writing(p_profile_id uuid, p_needs_consent boolean) RETURNS public.nutrition_profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  if auth.uid() is null or not app.can_counsel_nutrition() then
    raise exception 'not allowed to counsel nutrition' using errcode = '42501';
  end if;
  select * into v_profil
  from public.nutrition_profiles p
  where p.id = p_profile_id and p.organization_id = app.current_organization_id()
  for update;
  if v_profil.id is null then
    raise exception 'nutrition profile not found' using errcode = 'P0002';
  end if;
  if v_profil.ended_on is not null then
    raise exception 'nutrition profile has ended' using errcode = '22023';
  end if;
  -- Ohne Einwilligung kein Eintrag (ADR-027 Punkt 3).
  if p_needs_consent and not app.nutrition_consent_granted(v_profil.id) then
    raise exception 'nutrition consent missing' using errcode = '42501';
  end if;
  return v_profil;
end;
$$;

CREATE FUNCTION app.nutrition_profile_json(p_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.nutrition_profile_base_json(p_profile_id)
         || jsonb_build_object('diary', app.nutrition_diary_json(p_profile_id))
  where exists (select 1 from public.nutrition_profiles p where p.id = p_profile_id)
$$;

COMMENT ON FUNCTION app.nutrition_profile_json(p_profile_id uuid) IS 'ERN-001/ERN-007: ein Ernährungsprofil vollständig mit Tagebuch - für die Auskunft (Art. 15) und, mit fester Schlüsselliste, den Export der Plattform (Art. 20). Ohne Rechteprüfung.';

CREATE FUNCTION app.nutrition_profile_targets(p_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil  public.nutrition_profiles%rowtype;
  v_gewicht numeric;
  v_geboren date;
  v_heute   date;
begin
  select * into v_profil from public.nutrition_profiles p where p.id = p_profile_id;
  if v_profil.id is null then
    return null;
  end if;
  select w.weight_kg into v_gewicht
  from public.nutrition_weight_entries w
  where w.profile_id = p_profile_id
  order by w.measured_on desc, w.recorded_at desc
  limit 1;
  select r.date_of_birth into v_geboren
  from app.nutrition_relationship(v_profil.relationship_kind, v_profil.relationship_id,
                                  v_profil.organization_id) r;
  v_heute := app.training_today(v_profil.organization_id);

  return app.nutrition_calculation(
    v_gewicht,
    v_profil.height_cm,
    case when v_geboren is not null and v_geboren <= v_heute
         then extract(year from age(v_heute, v_geboren))::integer end,
    v_profil.formula_sex,
    v_profil.body_fat_percent,
    v_profil.activity_pal,
    v_profil.goal,
    v_profil.bmr_formula,
    v_profil.relationship_kind = 'training',
    jsonb_strip_nulls(jsonb_build_object(
      'energy_kcal', v_profil.energy_kcal_override,
      'protein_g', v_profil.protein_g_override,
      'fat_g', v_profil.fat_g_override,
      'carbohydrate_g', v_profil.carbohydrate_g_override,
      'water_ml', v_profil.water_ml_override)),
    v_profil.target_weight_kg
  );
end;
$$;

COMMENT ON FUNCTION app.nutrition_profile_targets(p_profile_id uuid) IS 'ERN-001: Zielwerte eines Profils aus app.nutrition_calculation - mit jüngstem Gewicht, Alter aus dem Geburtsdatum der Stammdaten am Tag der Praxis und den Überschreibungen. Ohne Rechteprüfung.';

CREATE FUNCTION app.nutrition_relationship(p_kind text, p_relationship_id uuid, p_organization_id uuid) RETURNS TABLE(person_id uuid, date_of_birth date, is_open boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.person_id, c.date_of_birth, true
  from public.patients p
  left join public.patient_contact_details c on c.patient_id = p.id
  where p_kind = 'treatment' and p.id = p_relationship_id and p.organization_id = p_organization_id
  union all
  select t.person_id, c.date_of_birth, t.contract_ended_on is null
  from public.training_relationships t
  left join public.training_contact_details c on c.training_relationship_id = t.id
  where p_kind = 'training' and t.id = p_relationship_id and t.organization_id = p_organization_id
$$;

COMMENT ON FUNCTION app.nutrition_relationship(p_kind text, p_relationship_id uuid, p_organization_id uuid) IS 'ERN-001: Person, Geburtsdatum aus den Stammdaten des Verhältnisses und ob es offen ist. Die Akte zählt als offen: Seit B1 ist jede Akte planbar (ANN-510). Ohne Rechteprüfung.';

CREATE FUNCTION app.nutrition_target_weight_floor(p_height_cm numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (app.nutrition_calculation(
    70, p_height_cm, 40, 'unspecified', null, 1.4, 'maintain', 'standard', false
  ) -> 'target_weight' ->> 'floor_kg')::numeric
$$;

COMMENT ON FUNCTION app.nutrition_target_weight_floor(p_height_cm numeric) IS 'ERN-001 (ADR-027 Punkt 21): das niedrigste Zielgewicht, das die Person selbst wählen darf (BMI 18,5), aus app.nutrition_calculation - keine zweite Stelle für die Zahl.';

CREATE FUNCTION app.offline_transfer_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 7
$$;

COMMENT ON FUNCTION app.offline_transfer_days() IS 'TRK-007 (ANN-357, ADR-024 Punkt 5): Eine ohne Netz erfasste Einheit wird hoechstens so viele Tage nach ihrem Tag noch angenommen - die Frist der Ablage auf dem Geraet.';

CREATE FUNCTION app.only_patient_id_changed(p_new jsonb, p_old jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (p_new - 'patient_id') = (p_old - 'patient_id');
$$;

COMMENT ON FUNCTION app.only_patient_id_changed(p_new jsonb, p_old jsonb) IS 'Vergleicht zwei Zeilenstaende ohne patient_id (PRX-017).';

CREATE FUNCTION app.open_cancellation_holding_service(p_billable_service_id uuid, p_patient_id uuid, p_training_relationship_id uuid, p_service_area text, p_treatment_basis_id uuid, p_period_month date, p_except_invoice_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select s.id
  from public.invoice_items alt
  join public.invoices s on s.id = alt.invoice_id
  where alt.billable_service_id = p_billable_service_id
    and alt.released_at is not null
    and s.status = 'issued'
    and s.id is distinct from p_except_invoice_id
    and exists (select 1 from public.invoice_cancellations x where x.invoice_id = s.id)
    and not exists (select 1 from public.invoices r where r.replaces_invoice_id = s.id)
    and s.patient_id is not distinct from p_patient_id
    and s.training_relationship_id is not distinct from p_training_relationship_id
    and s.service_area = p_service_area
    and s.treatment_basis_id is not distinct from p_treatment_basis_id
    and (p_treatment_basis_id is not null or s.period_month = p_period_month)
  order by s.issued_at desc
  limit 1
$$;

COMMENT ON FUNCTION app.open_cancellation_holding_service(p_billable_service_id uuid, p_patient_id uuid, p_training_relationship_id uuid, p_service_area text, p_treatment_basis_id uuid, p_period_month date, p_except_invoice_id uuid) IS 'UX-008b (BEF-062, ANN-321): die stornierte Rechnung ohne Korrektur, die diese Leistung freigegeben hat und in derselben Klammer liegt - sonst null. Die eine Stelle fuer Trigger, Korrekturentwurf und Arbeitsliste.';

CREATE FUNCTION app.open_invoices(p_organization_id uuid) RETURNS TABLE(invoice_id uuid, patient_id uuid, due_on date, paid_cents integer, outstanding_cents integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select i.id,
         i.patient_id,
         i.due_on,
         coalesce(zahlung.bezahlt, 0),
         i.total_cents - coalesce(zahlung.bezahlt, 0)
  from public.invoices i
  -- Die Zahlungssumme einmal je Rechnung (R3-016), dieselbe Rechnung wie
  -- app.invoice_paid_cents.
  left join (
    select p.invoice_id,
           sum(case when p.direction = 'incoming' then p.amount_cents
                    else -p.amount_cents end)::integer as bezahlt
    from public.payments p
    where p.voided_at is null
    group by p.invoice_id
  ) zahlung on zahlung.invoice_id = i.id
  where i.organization_id = p_organization_id
    and i.status = 'issued'
    -- Eine stornierte Rechnung ist keine Forderung mehr (ABR-003c).
    and not exists (select 1 from public.invoice_cancellations c where c.invoice_id = i.id)
    and i.total_cents - coalesce(zahlung.bezahlt, 0) > 0
$$;

COMMENT ON FUNCTION app.open_invoices(p_organization_id uuid) IS 'PRX-008: offene Rechnungen einer Organisation - ausgestellt, nicht storniert, nicht voll bezahlt (ABR-003c). Einzige Stelle der Regel; list_open_items und get_appointment_billing_context lesen daraus. Ohne Rollenpruefung: nur aus Funktionen mit eigener Pruefung aufrufen.';

CREATE FUNCTION app.order_fleet_photo_object_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from storage.objects o
    where o.bucket_id = app.fleet_photo_bucket() and o.name = old.object_key
  ) then
    insert into public.storage_deletion_orders (organization_id, bucket_id, object_key)
    values (old.organization_id, app.fleet_photo_bucket(), old.object_key)
    on conflict do nothing;
  end if;
  return old;
end;
$$;

