$$;

COMMENT ON FUNCTION app.order_patient_file_object_deletion() IS 'Schreibt beim Loeschen einer Dateizeile den Loeschauftrag fuer ihr Objekt (ADR-017 Punkt 25). Haengt am Trigger, damit kein Loeschweg daran vorbeikommt.';

