CREATE FUNCTION app.other_active_owners_exist(p_organization_id uuid, p_except_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.user_roles ur
    join public.user_profiles up on up.id = ur.user_id
    where ur.organization_id = p_organization_id
      and ur.role_key = 'owner'
      and up.organization_id = p_organization_id
      and up.is_active
      and up.id <> p_except_user_id
  )
$$;

COMMENT ON FUNCTION app.other_active_owners_exist(p_organization_id uuid, p_except_user_id uuid) IS 'Gibt es ausser diesem Konto noch eine aktive Praxisinhaberin? Grundlage des Aussperrschutzes (STAFF-002c, ADR-012).';

CREATE FUNCTION app.own_pending_attachment(p_access_id uuid, p_attachment_id uuid) RETURNS public.platform_message_attachments
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.platform_message_attachments%rowtype;
begin
  select x.* into v_anhang
  from public.platform_message_attachments x
  join app.platform_visible_messages(p_access_id) m on m.id = x.message_id
  where x.id = p_attachment_id
    and x.access_id = p_access_id
    and x.created_by = auth.uid()
    and x.status = 'pending'
    and x.confirmation_requested_at is null;
  if v_anhang.id is null then
    raise exception 'attachment not found' using errcode = 'P0002';
  end if;
  return v_anhang;
end;
$$;

CREATE FUNCTION app.own_pending_fleet_photo(p_photo_id uuid) RETURNS public.fleet_photos
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_foto public.fleet_photos%rowtype;
begin
  select f.* into v_foto
  from public.fleet_photos f
  where f.id = p_photo_id
    and f.organization_id = app.current_organization_id()
    and f.created_by = auth.uid()
    and f.status = 'pending'
    and f.confirmation_requested_at is null;
  if v_foto.id is null then
    raise exception 'photo not found' using errcode = 'P0002';
  end if;
  return v_foto;
end;
$$;

CREATE TABLE public.staff_reimbursement_receipts (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    reimbursement_id uuid,
    amount_cents integer,
    purpose text,
    attached_at timestamp with time zone,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    checksum_sha256 text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    confirmation_requested_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    verified_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    object_key text GENERATED ALWAYS AS ((((((organization_id)::text || '/'::text) || (staff_member_id)::text) || '/'::text) || (id)::text)) STORED NOT NULL,
    CONSTRAINT staff_reimbursement_receipts_amount_cents_check CHECK ((amount_cents BETWEEN 1 AND 100000)),
    CONSTRAINT staff_reimbursement_receipts_attached CHECK ((((reimbursement_id IS NULL) = (attached_at IS NULL)) AND ((reimbursement_id IS NULL) = (amount_cents IS NULL)) AND ((reimbursement_id IS NULL) = (purpose IS NULL)) AND ((reimbursement_id IS NULL) OR (status = 'ready'::text)))),
    CONSTRAINT staff_reimbursement_receipts_byte_size_check CHECK (((byte_size > 0) AND (byte_size <= 10485760))),
    CONSTRAINT staff_reimbursement_receipts_checksum_sha256_check CHECK ((checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT staff_reimbursement_receipts_mime_type_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'application/pdf'::text]))),
    CONSTRAINT staff_reimbursement_receipts_purpose_check CHECK (((purpose IS NULL) OR ((length(purpose) BETWEEN 1 AND 200) AND (purpose = btrim(purpose))))),
    CONSTRAINT staff_reimbursement_receipts_ready_confirmed CHECK (((status = 'ready'::text) = (confirmed_at IS NOT NULL))),
    CONSTRAINT staff_reimbursement_receipts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text])))
);

COMMENT ON TABLE public.staff_reimbursement_receipts IS 'ERS-001 (ANN-600): Beleg eines Einkaufs - Foto oder PDF mit Betrag und Zweck. Bis zum Absenden ohne Antrag bei der Person (nach einem Tag verworfen), danach am Antrag und mit ihm in der Datenklasse erstattung bzw. erstattung_kurz (cascade); das Objekt folgt über den Löschauftrag (ADR-017 Punkt 25). Unveränderlich bis auf Zustand, Prüfung und die eine Zuordnung. Kein Tabellenrecht.';

COMMENT ON COLUMN public.staff_reimbursement_receipts.checksum_sha256 IS 'SHA-256 der abgelegten Bytes, im Browser gerechnet; zum Nachweis des Servers erst mit verified_at (ADR-017 Punkte 9 und 49).';

CREATE FUNCTION app.own_pending_reimbursement_receipt(p_receipt_id uuid) RETURNS public.staff_reimbursement_receipts
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_beleg public.staff_reimbursement_receipts%rowtype;
begin
  select b.* into v_beleg
  from public.staff_reimbursement_receipts b
  where b.id = p_receipt_id
    and b.organization_id = app.current_organization_id()
    and b.created_by = auth.uid()
    and b.status = 'pending'
    and b.confirmation_requested_at is null;
  if v_beleg.id is null then
    raise exception 'receipt not found' using errcode = 'P0002';
  end if;
  return v_beleg;
end;
$$;

CREATE FUNCTION app.team_voice_max_seconds() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 120 $$;

COMMENT ON FUNCTION app.team_voice_max_seconds() IS 'TEAM-004 (ADR-017 Punkt 83, ANN-655): Höchstdauer einer Sprachnachricht in Sekunden - die eine Stelle für die Grenze am Server.';

CREATE TABLE public.team_message_attachments (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    message_id uuid,
    "position" smallint,
    attached_at timestamp with time zone,
    staff_member_id uuid,
    display_name text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    checksum_sha256 text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    confirmation_requested_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    verified_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    object_key text GENERATED ALWAYS AS ((((((organization_id)::text || '/'::text) || (channel_id)::text) || '/'::text) || (id)::text)) STORED NOT NULL,
    duration_seconds smallint,
    CONSTRAINT team_message_attachments_attached CHECK ((((message_id IS NULL) = (attached_at IS NULL)) AND ((message_id IS NULL) = ("position" IS NULL)) AND ((message_id IS NULL) OR (status = 'ready'::text)))),
    CONSTRAINT team_message_attachments_byte_size_check CHECK (((byte_size > 0) AND (byte_size <= 10485760))),
    CONSTRAINT team_message_attachments_checksum_sha256_check CHECK ((checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT team_message_attachments_display_name_check CHECK (((length(display_name) BETWEEN 1 AND 120) AND (display_name = btrim(display_name)) AND (display_name !~ '[[:cntrl:]]'::text))),
    CONSTRAINT team_message_attachments_duration CHECK ((((mime_type = ANY (ARRAY['audio/webm'::text, 'audio/mp4'::text])) = (duration_seconds IS NOT NULL)) AND ((duration_seconds IS NULL) OR (duration_seconds BETWEEN 1 AND app.team_voice_max_seconds())))),
    CONSTRAINT team_message_attachments_mime_type_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'application/pdf'::text, 'audio/webm'::text, 'audio/mp4'::text]))),
    CONSTRAINT team_message_attachments_position_check CHECK (("position" >= 1)),
    CONSTRAINT team_message_attachments_ready_confirmed CHECK (((status = 'ready'::text) = (confirmed_at IS NOT NULL))),
    CONSTRAINT team_message_attachments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text])))
);

COMMENT ON TABLE public.team_message_attachments IS 'TEAM-003 und TEAM-004 (ADR-017 Abschnitte M und N): Foto (JPEG, PNG), PDF oder Sprachnachricht (WebM, MP4) an einer Nachricht des Teamchats, bis zu fünf je Nachricht. Bis zum Senden ohne Nachricht bei der hochladenden Person (nach 24 Stunden verworfen, ANN-652), danach an der Nachricht und mit ihr in der Klasse teamchat: Sie fällt mit der Zeile (cascade) und mit ihrem Inhalt (app.team_message_content_removed); das Objekt folgt über den Löschauftrag (ADR-017 Punkt 25). Unveränderlich bis auf Zustand, Prüfung und die eine Bindung. Kein Tabellenrecht.';

COMMENT ON COLUMN public.team_message_attachments.display_name IS 'Anzeigename (Dateiname oder „Foto …“) - steht nur hier, nie im Objektschlüssel, in einer Adresse oder einem Log (ADR-017 Punkt 5, ADR-011).';

COMMENT ON COLUMN public.team_message_attachments.checksum_sha256 IS 'SHA-256 der abgelegten Bytes, im Browser gerechnet; zum Nachweis des Servers erst mit verified_at (ADR-017 Punkte 9 und 49).';

COMMENT ON COLUMN public.team_message_attachments.duration_seconds IS 'TEAM-004 (ADR-017 Punkt 84, ANN-655): Dauer einer Sprachnachricht in ganzen Sekunden, auf dem Gerät gemessen - nur zur Anzeige; bei Foto und PDF leer.';

CREATE FUNCTION app.own_pending_team_attachment(p_attachment_id uuid, p_org uuid, p_staff uuid) RETURNS public.team_message_attachments
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.team_message_attachments%rowtype;
begin
  select a.* into v_anhang
  from public.team_message_attachments a
  where a.id = p_attachment_id
    and a.organization_id = p_org
    and a.staff_member_id = p_staff
    and a.created_by = auth.uid()
    and a.message_id is null
    and a.status = 'pending'
    and a.confirmation_requested_at is null
    and a.created_at > now() - interval '24 hours';
  if v_anhang.id is null then
    raise exception 'team attachment not found' using errcode = 'P0002';
  end if;
  return v_anhang;
end;
$$;

CREATE FUNCTION app.own_staff_member(p_org uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select sm.id
  from public.user_profiles up
  join public.staff_members sm
    on sm.person_id = up.person_id and sm.organization_id = up.organization_id
  where up.id = auth.uid() and up.organization_id = p_org
  limit 1
$$;

COMMENT ON FUNCTION app.own_staff_member(p_org uuid) IS 'URL-001: der Mitarbeiterdatensatz des angemeldeten Kontos in der Praxis - oder null (Patienten- und Plattformkonten haben keinen).';

CREATE FUNCTION app.passkey_counts(p_zeitpunkt timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_urteil boolean;
begin
  if p_zeitpunkt is null then
    return false;
  end if;
  select u.passkey_ok into v_urteil
  from public.session_unlocks u
  where u.session_id = app.jwt_session_id()
    and u.user_id = auth.uid();
  if v_urteil is not null then
    return v_urteil;
  end if;
  return app.passkey_sign_in_approved(p_zeitpunkt);
end;
$$;

CREATE FUNCTION app.passkey_sign_in_approved(p_zeitpunkt timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_ok boolean;
begin
  if p_zeitpunkt is null or auth.uid() is null
     or to_regclass('auth.webauthn_credentials') is null then
    return false;
  end if;
  execute $q$
    select exists (
      select 1
      from public.passkey_approvals a
      where a.user_id = $1
        and a.credential_id = (
          select c.id
          from auth.webauthn_credentials c
          where c.user_id = $1
            and c.last_used_at between $2 - interval '2 minutes' and $2 + interval '2 minutes'
          order by abs(extract(epoch from (c.last_used_at - $2)))
          limit 1
        )
    )
  $q$ into v_ok using auth.uid(), p_zeitpunkt;
  return coalesce(v_ok, false);
exception when others then
  return false;
end;
$_$;

CREATE FUNCTION app.patient_fee_agreement_stays_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.organization_id   is distinct from old.organization_id
     or new.valid_from        is distinct from old.valid_from
     or new.session_fee_cents is distinct from old.session_fee_cents
     or new.created_at        is distinct from old.created_at
     or new.created_by        is distinct from old.created_by then
    raise exception 'fee agreement is immutable' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.patient_file_access_grant_ttl() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select interval '30 seconds'
$$;

COMMENT ON FUNCTION app.patient_file_access_grant_ttl() IS 'Gueltigkeit einer einmaligen Dateifreigabe zwischen Ausstellung und Zugriff (ANN-052).';

CREATE FUNCTION app.patient_file_bucket() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'patientenakte'::text
$$;

COMMENT ON FUNCTION app.patient_file_bucket() IS 'Name des privaten Buckets der Patientenakte (ADR-017 Punkt 3). Die einzige Stelle, an der er steht.';

CREATE FUNCTION app.patient_file_bucket_for(p_document_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_document_type = 'patientenfoto' then app.patient_photo_bucket()
    else app.patient_file_bucket()
  end
$$;

COMMENT ON FUNCTION app.patient_file_bucket_for(p_document_type text) IS 'Der Bucket einer Dokumentart: patientenfoto im eigenen, alle anderen in patientenakte (ADR-017 Punkt 3 und 32). Jede Stelle, die ein Objekt sucht, fragt hier.';

CREATE FUNCTION app.patient_file_max_bytes() RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 10485760::bigint
$$;

COMMENT ON FUNCTION app.patient_file_max_bytes() IS 'Groesse je Datei, hoechstens 10 MB (ADR-017 Punkt 18). Muss mit dem Limit am Bucket uebereinstimmen.';

CREATE FUNCTION app.patient_file_organization(p_patient_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.organization_id
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = app.current_organization_id()
    and app.can_read_patient_directory()
$$;

CREATE FUNCTION app.patient_file_type_is_clinical(p_document_type text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select t.is_clinical
  from public.patient_file_document_types t
  where t.key = p_document_type
$$;

CREATE FUNCTION app.patient_file_verification_required() RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- ANN-053 Fassung 2: aus bis OPS-001. Scharfschalten ist eine Migration,
  -- die diese eine Zeile auf true setzt - ein benannter Schritt vor echten
  -- Dateien, nicht eine Variable, die man vergessen kann.
  select false
$$;

COMMENT ON FUNCTION app.patient_file_verification_required() IS 'Schalter der Pruefung am Server (ADR-017 Punkt 51, ANN-053): true heisst, eine Datei wird erst mit bestandener Pruefung ready. Aus bis OPS-001; Go-live-Vorbedingung (ADR-007 Punkt 5).';

CREATE FUNCTION app.patient_has_upcoming_care(p_patient_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.appointments a
    where a.patient_id = p_patient_id
      and a.kind = 'therapy'
      and a.status <> 'cancelled'
      and a.ends_at > now()
  )
$$;

COMMENT ON FUNCTION app.patient_has_upcoming_care(p_patient_id uuid) IS 'B1 (BEF-151): Hat die Akte einen kuenftigen, nicht abgesagten Behandlungstermin? Dann faellt sie im Loeschlauf nicht, gleich was der Anker sagt.';

CREATE FUNCTION app.patient_merge_active() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(current_setting('app.patient_merge', true), '') = 'on';
$$;

COMMENT ON FUNCTION app.patient_merge_active() IS 'Laeuft gerade merge_patients? Nur dort gesetzt, transaktionslokal (PRX-017). Erlaubt an unveraenderlichen Zeilen ausschliesslich den Wechsel von patient_id.';

CREATE FUNCTION app.patient_merge_plan(p_organization_id uuid, p_source uuid, p_target uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_quelle     record;
  v_ziel       record;
  v_konflikte  text[] := '{}';
  v_angehaengt text[] := '{}';
  v_sperren    text[] := '{}';
  v_zaehler    jsonb;
  v_text       text;
  v_feld       text;
begin
  select p.id, p.status, p.care_concluded_on, p.person_id,
         pe.given_name, pe.family_name,
         c.date_of_birth, c.email, c.phone, c.phone_mobile, c.phone_work,
         c.institution, c.street, c.house_number, c.postal_code, c.city,
         d.primary_therapist_staff_member_id, d.treatment_table_required,
         d.home_visit_access_note, d.special_note, d.remark, d.take_along_items
    into v_quelle
  from public.patients p
  join public.persons pe on pe.id = p.person_id
  left join public.patient_contact_details c on c.patient_id = p.id
  left join public.patient_care_details d on d.patient_id = p.id
  where p.id = p_source and p.organization_id = p_organization_id;
  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  select p.id, p.status, p.care_concluded_on, p.person_id,
         pe.given_name, pe.family_name,
         c.date_of_birth, c.email, c.phone, c.phone_mobile, c.phone_work,
         c.institution, c.street, c.house_number, c.postal_code, c.city,
         d.primary_therapist_staff_member_id, d.treatment_table_required,
         d.home_visit_access_note, d.special_note, d.remark, d.take_along_items
    into v_ziel
  from public.patients p
  join public.persons pe on pe.id = p.person_id
  left join public.patient_contact_details c on c.patient_id = p.id
  left join public.patient_care_details d on d.patient_id = p.id
  where p.id = p_target and p.organization_id = p_organization_id;
  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- Felder, in denen beide Akten etwas anderes tragen: Die bleibende gewinnt,
  -- die Vorschau zeigt beide (ANN-147). Die Anschrift zaehlt als ein Feld.
  foreach v_feld in array array[
    'given_name', 'family_name', 'date_of_birth', 'email', 'phone', 'phone_mobile',
    'phone_work', 'institution', 'primary_therapist_staff_member_id',
    'treatment_table_required'
  ] loop
    if (to_jsonb(v_quelle) ->> v_feld) is not null
       and (to_jsonb(v_ziel) ->> v_feld) is not null
       and lower(btrim(to_jsonb(v_quelle) ->> v_feld)) <> lower(btrim(to_jsonb(v_ziel) ->> v_feld)) then
      v_konflikte := v_konflikte || v_feld;
    end if;
  end loop;

  if coalesce(v_quelle.street, v_quelle.house_number, v_quelle.postal_code, v_quelle.city) is not null
     and coalesce(v_ziel.street, v_ziel.house_number, v_ziel.postal_code, v_ziel.city) is not null
     and row(lower(v_quelle.street), lower(v_quelle.house_number), v_quelle.postal_code, lower(v_quelle.city))
         is distinct from
         row(lower(v_ziel.street), lower(v_ziel.house_number), v_ziel.postal_code, lower(v_ziel.city)) then
    v_konflikte := v_konflikte || 'address'::text;
  end if;

  -- Freitexte: angehaengt, nie verworfen - aber nie ueber die Grenze der
  -- Spalte hinaus gekuerzt. Dann sperrt der Vorgang (ANN-149).
  v_text := app.merge_note(v_ziel.home_visit_access_note, v_quelle.home_visit_access_note);
  if v_text is distinct from v_ziel.home_visit_access_note and v_ziel.home_visit_access_note is not null then
    v_angehaengt := v_angehaengt || 'home_visit_access_note'::text;
  end if;
  if length(btrim(coalesce(v_text, ''))) > 1000 then
    v_sperren := v_sperren || 'note_too_long'::text;
  end if;

  v_text := app.merge_note(v_ziel.special_note, v_quelle.special_note);
  if v_text is distinct from v_ziel.special_note and v_ziel.special_note is not null then
    v_angehaengt := v_angehaengt || 'special_note'::text;
  end if;
  if length(btrim(coalesce(v_text, ''))) > 1000 then
    v_sperren := v_sperren || 'note_too_long'::text;
  end if;

  v_text := app.merge_note(v_ziel.remark, v_quelle.remark);
  if v_text is distinct from v_ziel.remark and v_ziel.remark is not null then
    v_angehaengt := v_angehaengt || 'remark'::text;
  end if;
  if length(btrim(coalesce(v_text, ''))) > 2000 then
    v_sperren := v_sperren || 'note_too_long'::text;
  end if;

  if not app.take_along_items_valid(
    app.merge_take_along(v_ziel.take_along_items, v_quelle.take_along_items)
  ) then
    v_sperren := v_sperren || 'take_along_too_many'::text;
  end if;

  -- Ein Konto an der Dublette: Es verloere seine Akte. Das klaert die Praxis
  -- vorher, nicht der Vorgang (ANN-149).
  if exists (
    select 1 from public.user_profiles up where up.person_id = v_quelle.person_id
  ) then
    v_sperren := v_sperren || 'source_has_account'::text;
  end if;

  -- BEF-132: Ein Plattformzugang an der Dublette endete mit ihr, und die
  -- Person saehe die Antworten auf ihre Rueckfragen nicht mehr, die zur
  -- bleibenden Akte ziehen. Jeder Zugang, der nicht entzogen ist - auch eine
  -- offene Einladung oder ein gesperrter Zugang -, sperrt; die Praxis
  -- entzieht ihn vorher und laedt an der bleibenden Akte ein (ANN-149,
  -- ADR-023 Punkt 5: der Vorgang aendert keinen Zugang).
  if exists (
    select 1 from public.platform_accesses z
    where z.patient_id = p_source and z.status <> 'revoked'
  ) then
    v_sperren := v_sperren || 'source_has_platform_access'::text;
  end if;

  -- Zwei Entwuerfe fuer denselben Monat und Bereich: Einer muss vorher weg.
  if exists (
    select 1
    from public.invoices q
    join public.invoices z
      on z.patient_id = p_target
     and z.status = 'draft'
     and z.period_month = q.period_month
     and z.service_area = q.service_area
     -- ABR-032: Entwuerfe je Grundlage stossen nicht zusammen - die
     -- Grundlagen bleiben verschieden.
     and z.treatment_basis_id is null
    where q.patient_id = p_source
      and q.status = 'draft'
      and q.treatment_basis_id is null
  ) then
    v_sperren := v_sperren || 'draft_invoice_overlap'::text;
  end if;

  -- Zwei offene Eintraege ohne Grundlage auf der Warteliste. Mit Grundlage
  -- koennen sie nicht zusammenstossen: Die Grundlagen wandern mit.
  if exists (
    select 1 from public.waitlist_entries w
    where w.patient_id = p_source and w.status = 'open' and w.treatment_basis_id is null
  ) and exists (
    select 1 from public.waitlist_entries w
    where w.patient_id = p_target and w.status = 'open' and w.treatment_basis_id is null
  ) then
    v_sperren := v_sperren || 'open_waitlist_overlap'::text;
  end if;

  -- ABR-030: Zwei Honorarvereinbarungen ab demselben Tag haetten keine
  -- Antwort auf die Frage, welche gilt.
  if exists (
    select 1
    from public.patient_fee_agreements q
    join public.patient_fee_agreements z on z.valid_from = q.valid_from
    where q.patient_id = p_source and z.patient_id = p_target
  ) then
    v_sperren := v_sperren || 'fee_agreement_overlap'::text;
  end if;

  -- ANG-001: Zwei Abos, deren Zeitraeume sich ueberschneiden, waeren zwei
  -- Vertraege ueber dieselbe Nachsorge; eines muss vorher entfernt sein.
  if exists (
    select 1
    from public.aftercare_subscriptions q
    join public.aftercare_subscriptions z
      on z.starts_on <= coalesce(q.ends_on, 'infinity'::date)
     and q.starts_on <= coalesce(z.ends_on, 'infinity'::date)
    where q.patient_id = p_source and z.patient_id = p_target
  ) then
    v_sperren := v_sperren || 'aftercare_overlap'::text;
  end if;

  -- KND-002: Je Akte hoechstens ein offenes Trainingsangebot (ANN-284).
  if exists (
    select 1
    from public.training_offers q
    join public.training_offers z
      on z.patient_id = p_target
     and app.training_offer_practice_state(z, app.training_today(p_organization_id)) = 'open'
    where q.patient_id = p_source
      and app.training_offer_practice_state(q, app.training_today(p_organization_id)) = 'open'
  ) then
    v_sperren := v_sperren || 'training_offer_overlap'::text;
  end if;

  -- ERN-001: Zwei laufende Ernaehrungsprofile waeren zwei Beratungen derselben
  -- Person (ADR-027 Punkt 1); eines muss vorher beendet sein. Das Profil der
  -- Dublette zieht zur bleibenden Person - gezaehlt wird deshalb jedes ihrer
  -- laufenden Profile, an der Akte wie am Trainingsverhaeltnis. Zusammenfuehren
  -- darf allein owner, der die Faehigkeit traegt.
  if exists (
    select 1 from public.nutrition_profiles q
    where q.patient_id = p_source and q.ended_on is null
  ) and exists (
    select 1
    from public.nutrition_profiles z
    left join public.patients pa on pa.id = z.patient_id
    left join public.training_relationships t on t.id = z.training_relationship_id
    where z.organization_id = p_organization_id and z.ended_on is null
      and z.patient_id is distinct from p_source
      and coalesce(pa.person_id, t.person_id) = v_ziel.person_id
  ) then
    v_sperren := v_sperren || 'nutrition_profile_overlap'::text;
  end if;

  v_zaehler := jsonb_build_object(
    'appointments',
      (select count(*) from public.appointments a where a.patient_id = p_source),
    'treatment_notes',
      (select count(*) from public.treatment_notes n
         join public.appointments a on a.id = n.appointment_id
        where a.patient_id = p_source),
    'treatment_bases',
      (select count(*) from public.treatment_bases b where b.patient_id = p_source),
    'billable_services',
      (select count(*) from public.billable_services s where s.patient_id = p_source),
    'invoices',
      (select count(*) from public.invoices i where i.patient_id = p_source),
    'invoices_issued',
      (select count(*) from public.invoices i where i.patient_id = p_source and i.status = 'issued'),
    'invoice_recipients',
      (select count(*) from public.invoice_recipients r where r.patient_id = p_source),
    'fee_agreements',
      (select count(*) from public.patient_fee_agreements f where f.patient_id = p_source),
    'aftercare_subscriptions',
      (select count(*) from public.aftercare_subscriptions s where s.patient_id = p_source),
    'training_offers',
      (select count(*) from public.training_offers o where o.patient_id = p_source),
    'exercise_plans',
      (select count(*) from public.exercise_plans x where x.patient_id = p_source),
    'patient_files',
      (select count(*) from public.patient_files f where f.patient_id = p_source),
    'privacy_records',
      (select count(*) from public.patient_privacy_records r where r.patient_id = p_source),
    'questionnaire_responses',
      (select count(*) from public.patient_questionnaire_responses r where r.patient_id = p_source),
    'course_events',
      (select count(*) from public.patient_course_events e where e.patient_id = p_source),
    'therapy_reports',
      (select count(*) from public.therapy_reports r where r.patient_id = p_source),
    'tasks',
      (select count(*) from public.tasks t where t.patient_id = p_source),
    -- BEF-132: ziehen seit KOM-004 und BEF-131 mit.
    'platform_messages',
      (select count(*) from public.platform_messages m where m.patient_id = p_source),
    'platform_appointment_requests',
      (select count(*) from public.platform_appointment_requests w where w.patient_id = p_source),
    -- TRK-002: Check-ins ziehen mit; den Takt der Dublette zaehlt der Plan,
    -- ob er mitzieht oder vor dem der bleibenden Akte weicht (ANN-350).
    'checkins',
      (select count(*) from public.checkins c where c.patient_id = p_source),
    'checkin_schedules',
      (select count(*) from public.checkin_schedules s where s.patient_id = p_source),
    -- ALT-003: Gewohnheiten ziehen mit.
    'habits',
      (select count(*) from public.habits h where h.patient_id = p_source),
    'waitlist_entries',
      (select count(*) from public.waitlist_entries w where w.patient_id = p_source),
    'legal_holds',
      (select count(*) from public.legal_holds h
        where h.subject_type = 'patient' and h.subject_id = p_source)
  );

  return jsonb_build_object(
    'source', jsonb_build_object(
      'id', v_quelle.id, 'given_name', v_quelle.given_name, 'family_name', v_quelle.family_name,
      'date_of_birth', v_quelle.date_of_birth, 'status', v_quelle.status,
      'care_concluded_on', v_quelle.care_concluded_on
    ),
    'target', jsonb_build_object(
      'id', v_ziel.id, 'given_name', v_ziel.given_name, 'family_name', v_ziel.family_name,
      'date_of_birth', v_ziel.date_of_birth, 'status', v_ziel.status,
      'care_concluded_on', v_ziel.care_concluded_on
    ),
    'counts', v_zaehler,
    'conflicts', to_jsonb(v_konflikte),
    'appended', to_jsonb(v_angehaengt),
    'blockers', (select coalesce(jsonb_agg(distinct x), '[]'::jsonb) from unnest(v_sperren) x)
  );
end;
$$;

COMMENT ON FUNCTION app.patient_merge_plan(p_organization_id uuid, p_source uuid, p_target uuid) IS 'Plan des Zusammenfuehrens (PRX-017): Kopfdaten, Zaehler je Bereich, widerspruechliche Felder, angehaengte Freitexte, Sperrgruende (ANN-147, ANN-149). Ohne Rollenpruefung; nur fuer preview_patient_merge und merge_patients.';

CREATE FUNCTION app.patient_photo_accessible(p_patient_id uuid, p_taken_at timestamp with time zone, p_locked_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_taken_at is null then
      app.patient_photo_consent_granted(p_patient_id)
      and coalesce(app.patient_photo_due_at(p_patient_id, now()) > now(), false)
    else coalesce(app.patient_photo_due_at(p_patient_id, p_taken_at, p_locked_at) > now(), false)
  end
$$;

COMMENT ON FUNCTION app.patient_photo_accessible(p_patient_id uuid, p_taken_at timestamp with time zone, p_locked_at timestamp with time zone) IS 'Die eine Einwilligungspruefung fuer Patientenfotos (ADR-017 Punkt 36). Ohne Zeitpunkt: neue Aufnahme erlaubt (juengster Vermerk ist eine Erteilung, und ein Foto von jetzt waere nicht schon faellig). Mit Zeitpunkt: vorhandenes Foto nutzbar (weder widerrufen noch faellig noch gesperrt). Gefragt von Vorbereitung, Bestaetigung, Liste, Verweis, Herausgabe und der Leseregel am Objekt.';

CREATE FUNCTION app.patient_photo_bucket() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'patientenfotos'::text
$$;

COMMENT ON FUNCTION app.patient_photo_bucket() IS 'Name des privaten Buckets fuer Patientenfotos (ADR-017 Punkt 32). Die einzige Stelle, an der er steht.';

CREATE FUNCTION app.patient_photo_consent_granted(p_patient_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select r.record_kind = 'consent_granted'
    from public.patient_privacy_records r
    where r.patient_id = p_patient_id
      and r.purpose = 'patient_photos'
    order by r.recorded_at desc, r.id desc
    limit 1
  ), false)
$$;

CREATE FUNCTION app.patient_photo_due_at(p_patient_id uuid, p_taken_at timestamp with time zone, p_locked_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select least(
    p_locked_at,
    p_taken_at + app.retention_interval('patientenfoto'),
    (
      select p.care_concluded_at + app.retention_upper_interval('patientenfoto')
      from public.patients p
      where p.id = p_patient_id
    ),
    (
      select min(r.recorded_at)
      from public.patient_privacy_records r
      where r.patient_id = p_patient_id
        and r.purpose = 'patient_photos'
        and r.record_kind = 'consent_withdrawn'
        and r.recorded_at > p_taken_at
    )
  )
$$;

COMMENT ON FUNCTION app.patient_photo_due_at(p_patient_id uuid, p_taken_at timestamp with time zone, p_locked_at timestamp with time zone) IS 'Faelligkeit eines Patientenfotos (ADR-017 Punkt 38): frueheste von Aufnahme plus zwoelf Monate, care_concluded_at plus drei Monate, Widerruf nach der Aufnahme und festgehaltener Sperre. Das Datum, das jedes Foto als Loeschdatum zeigt.';

CREATE FUNCTION app.patient_photo_usable(p_document_type text, p_patient_id uuid, p_taken_at timestamp with time zone, p_locked_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_document_type = 'patientenfoto'
      then app.patient_photo_accessible(p_patient_id, p_taken_at, p_locked_at)
    else true
  end
$$;

COMMENT ON FUNCTION app.patient_photo_usable(p_document_type text, p_patient_id uuid, p_taken_at timestamp with time zone, p_locked_at timestamp with time zone) IS 'Nutzbarkeit eines Fotos der Person: Arbeitshilfe nach app.patient_photo_accessible (Einwilligung, Frist, Sperre), Dokumentationsfoto immer (ADR-017 Punkt 46).';

CREATE FUNCTION app.patient_record_page(p_organization_id uuid, p_patient_id uuid, p_limit integer, p_before_starts_at timestamp with time zone, p_before_id uuid) RETURNS TABLE(appointment_id uuid, starts_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_limit is null or p_limit < 1 or p_limit > 50 then
    raise exception 'limit out of range' using errcode = '22023';
  end if;

  -- Der Cursor besteht aus beiden Teilen oder gar nicht.
  if (p_before_starts_at is null) <> (p_before_id is null) then
    raise exception 'cursor is incomplete' using errcode = '22023';
  end if;

  return query
    select a.id, a.starts_at
    from public.appointments a
    where a.organization_id = p_organization_id
      and a.patient_id = p_patient_id
      and (
        a.starts_at <= now()
        or exists (
          select 1 from public.treatment_notes t where t.appointment_id = a.id
        )
      )
      and (
        p_before_starts_at is null
        or (a.starts_at, a.id) < (p_before_starts_at, p_before_id)
      )
    order by a.starts_at desc, a.id desc
    limit p_limit;
end;
$$;

COMMENT ON FUNCTION app.patient_record_page(p_organization_id uuid, p_patient_id uuid, p_limit integer, p_before_starts_at timestamp with time zone, p_before_id uuid) IS 'Seitenregel der Akte (DOK-003): begonnene oder dokumentierte Termine eines Patienten, neueste zuerst, Keyset-Cursor. Gemeinsame Grundlage von Behandlungsnachweis und klinischer Sicht.';

CREATE FUNCTION app.patient_retention_anchor(p_patient_id uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select greatest(
    p.care_concluded_on,
    (select max((a.starts_at at time zone o.time_zone)::date)
       from public.appointments a
      where a.patient_id = p.id
        and a.kind = 'therapy'
        and (a.completed_at is not null
             or a.status in ('completed', 'documented', 'invoiced', 'no_show'))),
    (select max(b.performed_on)
       from public.billable_services b
      where b.patient_id = p.id)
  )
  from public.patients p
  join public.organizations o on o.id = p.organization_id
  where p.id = p_patient_id
$$;

COMMENT ON FUNCTION app.patient_retention_anchor(p_patient_id uuid) IS 'B1 (BEF-151, ANN-511, ADR-008 Fassung 3): Fristanker der Patientenakte - das spaeteste Datum aus abgehaktem, dokumentiertem, abgerechnetem oder als nicht angetroffen vermerktem Behandlungstermin, erfasster Leistung und ausdruecklichem Abschluss. Leer ohne jede Behandlung: dann keine Frist. Rechnungen halten ueber ihre eigene Frist (Sperre), nicht ueber den Anker.';

CREATE FUNCTION app.patient_search_min_length() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 3 $$;

CREATE FUNCTION app.patient_treatment_basis_ids(p_organization_id uuid, p_patient_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select array_agg(v.id order by v.issued_on desc, v.created_at desc, v.id desc)
  from (
    select p.id, p.issued_on, p.created_at
    from public.treatment_bases p
    where p.organization_id = p_organization_id
      and p.patient_id = p_patient_id
    order by p.issued_on desc, p.created_at desc, p.id desc
    limit 200
  ) v
$$;

COMMENT ON FUNCTION app.patient_treatment_basis_ids(p_organization_id uuid, p_patient_id uuid) IS 'Behandlungsgrundlagen einer Patientin in der Akte, neueste zuerst, hoechstens 200 (VER-002). Gemeinsame Grundlage der organisatorischen und der klinischen Sicht.';

CREATE FUNCTION app.payment_flows(p_organization_id uuid, p_from date, p_to date) RETURNS TABLE(tag date, betrag bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.paid_on,
         (case p.direction when 'incoming' then p.amount_cents else -p.amount_cents end)::bigint
  from public.payments p
  where p.organization_id = p_organization_id
    and p.voided_at is null
    and p.paid_on >= p_from
    and p.paid_on < p_to
$$;

COMMENT ON FUNCTION app.payment_flows(p_organization_id uuid, p_from date, p_to date) IS 'STA-001: Zahlungseingang (Zufluss) als Buchungen im halboffenen Zeitraum [p_from, p_to); Rueckzahlung negativ, stornierte Zahlungen nicht. Einzige Stelle der Regel fuer Kennzahlen und Monatsreihe. Ohne Rollenpruefung.';

CREATE FUNCTION app.payments_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.voided_at is not null then
    raise exception 'a voided payment cannot be changed again' using errcode = '23514';
  end if;

  if new.organization_id is distinct from old.organization_id
     or new.invoice_id   is distinct from old.invoice_id
     or new.direction    is distinct from old.direction
     or new.amount_cents is distinct from old.amount_cents
     or new.currency     is distinct from old.currency
     or new.paid_on      is distinct from old.paid_on
     or new.method       is distinct from old.method
     or new.note         is distinct from old.note
     or new.created_at   is distinct from old.created_at
     or new.created_by   is distinct from old.created_by then
    raise exception 'a recorded payment can only be voided, not changed' using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.payments_frozen() IS 'Laesst an einer erfassten Zahlung nur das Storno zu, und das nur einmal (ABR-004). Eine falsch erfasste Zahlung wird storniert und neu gebucht, nicht ueberschrieben - sonst bliebe vom Vorgang nichts erklaerbar.';

CREATE FUNCTION app.payments_need_issued_invoice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_status text;
begin
  select i.status into v_status
  from public.invoices i
  where i.id = new.invoice_id;

  if v_status is distinct from 'issued' then
    raise exception 'a payment belongs to an issued invoice' using errcode = '23514';
  end if;

  -- ABN-008 (BEF-100): Nach dem Storno bleibt der eingegangene Betrag stehen.
  -- Er geht als Rueckzahlung an die Zahlende zurueck oder wird mit der
  -- Ersatzrechnung verrechnet - beides ist eine Buchung in Richtung "refund".
  -- Ein neuer Eingang auf eine aufgehobene Forderung bleibt ausgeschlossen.
  if new.direction = 'incoming' and exists (
    select 1 from public.invoice_cancellations c where c.invoice_id = new.invoice_id
  ) then
    raise exception 'a cancelled invoice takes no payment' using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.payments_need_issued_invoice() IS 'Haelt Zahlungen an ausgestellten, nicht stornierten Rechnungen fest (ABR-004, R3-004). An einem Entwurf gibt es nichts zu zahlen (ANN-075), an einer stornierten Rechnung nichts mehr (ADR-009 Punkt 9).';

CREATE FUNCTION app.payout_account_view(p_staff_member_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object('iban_masked', app.mask_iban(a.iban), 'since', a.updated_at)
  from public.staff_payout_accounts a
  where a.staff_member_id = p_staff_member_id
$$;

CREATE FUNCTION app.pin_fresh_authentication() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select interval '10 minutes'
$$;

COMMENT ON FUNCTION app.pin_fresh_authentication() IS 'So kurz nach einer Anmeldung darf eine PIN festgelegt oder geaendert werden (ANN-325).';

CREATE FUNCTION app.pin_max_attempts() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 5
$$;

COMMENT ON FUNCTION app.pin_max_attempts() IS 'Fehlversuche in Folge, nach denen die Sitzung verbraucht ist (ADR-025 Punkt 11, ANN-324).';

CREATE FUNCTION app.pin_problem(p_pin text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p_pin is null or p_pin !~ '^[0-9]{6}$' then
    return 'format';
  end if;
  if p_pin ~ '^(.)\1{5}$'
     or position(p_pin in '0123456789') > 0
     or position(p_pin in '9876543210') > 0 then
    return 'trivial';
  end if;
  return null;
end;
$_$;

COMMENT ON FUNCTION app.pin_problem(p_pin text) IS 'Prueft eine App-PIN: sechs Ziffern, keine gleichen Ziffern, keine auf- oder absteigende Reihe (ADR-025 Punkt 11). null heisst zulaessig, sonst format oder trivial.';

CREATE FUNCTION app.plan_week(p_org uuid, p_staff_member_id uuid, p_date date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_object_agg(t.tag::text, coalesce((
           select jsonb_agg(jsonb_build_object('von', to_char(h.starts_at, 'HH24:MI'),
                                               'bis', to_char(h.ends_at, 'HH24:MI'))
                            order by h.starts_at)
           from public.staff_working_hours h
           where h.organization_id = p_org and h.staff_member_id = p_staff_member_id
             and h.weekday = t.tag
             and daterange(h.valid_from, h.valid_until, '[]') @> p_date
         ), '[]'::jsonb))
  from generate_series(1, 7) as t (tag)
$$;

CREATE FUNCTION app.platform_access_allows(p_access_id uuid, p_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select case
      -- Gesundheit: Lesen, Wuensche, Nachrichten. Jede Vertretung traegt
      -- diesen Bereich nachgewiesen (Constraint platform_accesses_kind_fields).
      when p_capability in ('read', 'request', 'message') then true
      -- Rechnungen und Zahlungen: der eigene Zugang, sonst nur mit
      -- nachgewiesener Vermoegenssorge bzw. Einwilligung (ABN-010).
      when p_capability = 'billing'
        then a.access_kind = 'self' or coalesce(a.finance_scope, false)
      -- ANG-003 (ANN-273): einen Vertrag kuendigen die Person selbst und eine
      -- rechtliche Vertretung mit Vermoegenssorge, nie eine Begleitung.
      when p_capability = 'contract'
        then a.access_kind = 'self'
             or (a.access_kind = 'legal_representative' and coalesce(a.finance_scope, false))
      -- POR-012 (ANN-248): den Befundbogen fuellt die Person selbst oder ihre
      -- rechtliche Vertretung aus - eine Angabe zur Gesundheit, die eine
      -- Begleitung nicht fuer sie macht.
      -- UEB-010 (ANN-306): ebenso die Einheit am Plan.
      -- KOM-005 (ADR-017 Punkte 59 und 67): ebenso Foto und Video an einer
      -- Rueckfrage - die Begleitung liest die Worte, nicht die Bilder.
      -- TRK-003 (ANN-352): ebenso der Check-in - Angaben zur Gesundheit, die
      -- eine Begleitung nicht fuer die Person macht.
      -- ERN-002 (ADR-027 Punkt 3): die Ernaehrungsberatung - die Begleitung
      -- sieht davon nichts, die rechtliche Vertretung handelt wie die Person.
      when p_capability in ('consent', 'export', 'manage_companions', 'questionnaire', 'exercise',
                            'attach', 'checkin', 'nutrition')
        then a.access_kind in ('self', 'legal_representative')
      else false
    end
    from public.platform_accesses a
    where a.id = p_access_id
      and exists (select 1 from app.platform_readable_access(a.id))
  ), false)
$$;

COMMENT ON FUNCTION app.platform_access_allows(p_access_id uuid, p_capability text) IS 'Darf dieser lesbare Zugang das? read/request/message: jeder; billing: eigener Zugang oder finance_scope; consent/export/manage_companions: eigener Zugang und rechtliche Vertretung. Die eine Stelle der Rechte (ADR-023 Punkt 13, ABN-010).';

CREATE FUNCTION app.platform_access_ended_at(p_access_id uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when a.status = 'revoked' then a.revoked_at
    when a.status = 'invited' and not exists (
           select 1 from public.platform_access_invitations i
           where i.platform_access_id = a.id and i.status = 'pending' and i.expires_at > now()
         )
      then (select max(i.expires_at) from public.platform_access_invitations i
            where i.platform_access_id = a.id)
    else
      -- least() uebergeht null: ohne Ende des Verhaeltnisses zaehlt allein
      -- die Volljaehrigkeit, ohne Sorgerecht allein das Ende.
      least(
        -- ANG-004 (ANN-274): Die Lesefrist zaehlt vom Ende des Verhaeltnisses,
        -- in der Behandlung vom Ende des Nachsorge-Abos, wenn es spaeter
        -- endet; solange ein Abo laeuft, gar nicht.
        case when l.lese_ab is not null
          then app.retention_due_at(l.lese_ab, app.platform_read_period(), o.time_zone)
        end,
        case when a.access_kind = 'legal_representative' and a.legal_basis = 'custody'
          then coalesce(
            (app.majority_date(r.date_of_birth)::timestamp at time zone o.time_zone),
            -- Ohne Geburtsdatum ist das Sorgerecht nicht pruefbar: beendet.
            a.created_at)
        end,
        case when a.access_kind <> 'self' and a.legal_basis is distinct from 'custody'
              and coalesce(app.platform_is_minor(r.date_of_birth, o.time_zone), true)
          then a.created_at
        end
      )
  end
  from public.platform_accesses a
  join public.organizations o on o.id = a.organization_id
  left join lateral app.platform_relationship(a.relationship_kind, a.relationship_id) r on true
  left join lateral (
    select app.platform_read_from(a.relationship_kind, a.relationship_id, r.ended_on) as lese_ab
  ) l on true
  where a.id = p_access_id
$$;

CREATE FUNCTION app.platform_access_for_update(p_access_id uuid, p_org uuid) RETURNS public.platform_accesses
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select a.* from public.platform_accesses a
  where a.id = p_access_id and a.organization_id = p_org
  for update
$$;

CREATE FUNCTION app.platform_access_writable(p_access_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select l.lese_ab is null or l.lese_ab > app.training_today(a.organization_id)
    from public.platform_accesses a
    left join lateral app.platform_relationship(a.relationship_kind, a.relationship_id) r on true
    left join lateral (
      select app.platform_read_from(a.relationship_kind, a.relationship_id, r.ended_on) as lese_ab
    ) l on true
    where a.id = p_access_id
      and exists (select 1 from app.platform_readable_access(a.id))
  ), false)
$$;

COMMENT ON FUNCTION app.platform_access_writable(p_access_id uuid) IS 'UEB-010 (ANN-305): ob ein lesbarer Zugang noch schreiben darf - nicht in der Lesefrist nach dem Ende des Verhaeltnisses bzw. des Nachsorge-Abos (DSN-001 4.3, ANN-274).';

CREATE FUNCTION app.platform_accesses_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_person uuid;
begin
  -- Faellt das Verhaeltnis (on delete set null), endet der Zugang, und seine
  -- Einladungen verlieren die Adresse (ADR-023 Punkt 5).
  if tg_op = 'UPDATE'
     and new.patient_id is null and new.training_relationship_id is null
     and (old.patient_id is not null or old.training_relationship_id is not null) then
    if new.status <> 'revoked' then
      new.status := 'revoked';
      new.revoked_at := now();
      new.revoked_by := null;
      new.revoked_reason := 'relationship_deleted';
      new.locked_at := null;
      new.locked_by := null;
    end if;
    update public.platform_access_invitations i
       set email = null,
           status = case when i.status = 'pending' then 'revoked' else i.status end,
           revoked_at = case when i.status = 'pending' then now() else i.revoked_at end
     where i.platform_access_id = new.id;
    -- LOG-EPIC-001: Das Ende mit dem Verhaeltnis zeigt der Zugang selbst
    -- (revoked_reason 'relationship_deleted', revoked_at); im Loeschlauf
    -- zaehlt retention.applied.
    return new;
  end if;

  -- POR-005: Art und Nachweis eines Zugangs aendern sich nie. Ein anderer
  -- Umfang ist eine neue Einladung.
  if tg_op = 'UPDATE' and (
       new.access_kind is distinct from old.access_kind
       or new.legal_basis is distinct from old.legal_basis
       or new.representative_name is distinct from old.representative_name
       or new.proof_documents is distinct from old.proof_documents
       or new.consent_text_version is distinct from old.consent_text_version
       or new.consent_earlier_messages is distinct from old.consent_earlier_messages
       or new.health_scope is distinct from old.health_scope
       or new.finance_scope is distinct from old.finance_scope
       or new.proof_recorded_by is distinct from old.proof_recorded_by
       or new.proof_recorded_at is distinct from old.proof_recorded_at
       or new.consent_recorded_by is distinct from old.consent_recorded_by
       or new.consent_recorded_at is distinct from old.consent_recorded_at
       or new.relationship_kind is distinct from old.relationship_kind
       or new.organization_id is distinct from old.organization_id
       or new.relationship_id is distinct from old.relationship_id) then
    raise exception 'platform access kind and proof are fixed' using errcode = '23514';
  end if;

  if new.account_user_id is not null
     and (tg_op = 'INSERT' or new.account_user_id is distinct from old.account_user_id) then
    perform pg_advisory_xact_lock(hashtext('platform_account:' || new.account_user_id::text));

    if exists (select 1 from public.user_profiles up where up.id = new.account_user_id) then
      raise exception 'practice account cannot hold platform access' using errcode = '23514';
    end if;

    select r.person_id into v_person
    from app.platform_relationship(new.relationship_kind, new.relationship_id) r;

    perform pg_advisory_xact_lock(hashtext('platform_person:' || v_person::text));

    if new.access_kind = 'self' then
      if exists (
        select 1 from public.user_profiles up
        join public.user_roles ur on ur.user_id = up.id
        where up.person_id = v_person
      ) then
        raise exception 'person has a practice account' using errcode = '23514';
      end if;

      if exists (
        select 1
        from public.platform_accesses a
        cross join lateral app.platform_relationship(a.relationship_kind, a.relationship_id) r
        where a.id <> new.id
          and a.access_kind = 'self'
          and a.status <> 'revoked'
          and a.account_user_id is not null
          and a.account_user_id <> new.account_user_id
          and r.person_id = v_person
      ) then
        raise exception 'person already has another account' using errcode = '23514';
      end if;

      if exists (
        select 1
        from public.platform_accesses a
        cross join lateral app.platform_relationship(a.relationship_kind, a.relationship_id) r
        where a.account_user_id = new.account_user_id
          and a.id <> new.id
          and a.access_kind = 'self'
          and a.status <> 'revoked'
          and r.person_id is distinct from v_person
      ) then
        raise exception 'account belongs to another person' using errcode = '23514';
      end if;

      -- POR-005: Wer diese Person vertritt, ist nicht diese Person.
      if exists (
        select 1
        from public.platform_accesses a
        cross join lateral app.platform_relationship(a.relationship_kind, a.relationship_id) r
        where a.account_user_id = new.account_user_id
          and a.id <> new.id
          and a.access_kind <> 'self'
          and a.status <> 'revoked'
          and r.person_id = v_person
      ) then
        raise exception 'account represents this person' using errcode = '23514';
      end if;
    else
      -- POR-005: Eine Vertretung ist nie das Konto der vertretenen Person
      -- (Punkt 13: "Gehoert das Konto nicht zur Person des Verhaeltnisses").
      if exists (
        select 1
        from public.platform_accesses a
        cross join lateral app.platform_relationship(a.relationship_kind, a.relationship_id) r
        where a.account_user_id = new.account_user_id
          and a.id <> new.id
          and a.access_kind = 'self'
          and a.status <> 'revoked'
          and r.person_id = v_person
      ) then
        raise exception 'account belongs to the represented person' using errcode = '23514';
      end if;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.platform_account_still_due(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not exists (select 1 from public.user_profiles up where up.id = p_account)
     and not exists (
       select 1 from public.platform_accesses a
       where a.account_user_id = p_account
         and a.status <> 'revoked'
         and app.platform_access_ended_at(a.id) is null
     )
$$;

CREATE FUNCTION app.platform_appointment_history() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- ANN-251: wie weit die eigene Terminliste zurueckreicht.
  select interval '12 months'
$$;

COMMENT ON FUNCTION app.platform_appointment_history() IS 'POR-008 (ANN-251): Zeitraum der vergangenen Termine in der eigenen Terminliste der Plattform.';

CREATE FUNCTION app.platform_code_hash(p_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select encode(extensions.digest(convert_to(coalesce(p_code, ''), 'UTF8'), 'sha256'), 'hex') $$;

CREATE FUNCTION app.platform_companion_consent_version() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 'begleitung-2026-10-02b' $$;

CREATE FUNCTION app.platform_consent_purposes(p_relationship_kind text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_relationship_kind
    when 'treatment' then array['email_contact', 'prescriber_report', 'patient_photos', 'message_attachments']
    when 'training' then array['training_health_data', 'message_attachments']
    else '{}'::text[]
  end
$$;

CREATE FUNCTION app.platform_consent_wording_version() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select '2026-10'::text
$$;

CREATE FUNCTION app.platform_diary_for_writing(p_access_id uuid, p_day date, p_needs_consent boolean) RETURNS public.nutrition_profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  v_profil := app.platform_nutrition_for_writing(p_access_id, p_needs_consent);
  if p_needs_consent and not v_profil.diary_enabled then
    raise exception 'nutrition diary is off' using errcode = '42501';
  end if;
  if p_day is not null then
    if p_day > app.training_today(v_profil.organization_id) then
      raise exception 'date lies in the future' using errcode = '22023';
    end if;
    if p_day < v_profil.started_on then
      raise exception 'date before the profile' using errcode = '22023';
    end if;
  end if;
  return v_profil;
end;
$$;

CREATE FUNCTION app.platform_exercise_note_allowed(p_kind text, p_relationship_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'treatment' then true
    when 'training' then coalesce((
      select r.record_kind = 'consent_granted'
      from public.training_consent_records r
      where r.training_relationship_id = p_relationship_id
        and r.purpose = 'training_health_data'
      order by r.recorded_at desc, r.id desc
      limit 1
    ), false)
    else false
  end
$$;

COMMENT ON FUNCTION app.platform_exercise_note_allowed(p_kind text, p_relationship_id uuid) IS 'UEB-010 (ANN-306): ob die Person zu einer Einheit "Das war schwierig, weil ..." schreiben darf - in der Behandlung immer, im Training nur mit erteilter Einwilligung zu Gesundheitsangaben (ADR-021 Punkt 4).';

CREATE FUNCTION app.platform_exercise_plan(p_access_id uuid, p_plan_id uuid) RETURNS public.exercise_plans
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.*
  from public.platform_accesses a
  join public.exercise_plans p on p.organization_id = a.organization_id
  where a.id = p_access_id
    and p.id = p_plan_id
    and p.status = 'assigned'
    and p.runs_from <= app.training_today(a.organization_id)
    and (
      (a.relationship_kind = 'treatment' and p.service_area = 'therapy'
         and p.patient_id = a.relationship_id)
      or (a.relationship_kind = 'training' and p.service_area = 'training'
         and p.training_relationship_id = a.relationship_id)
    )
$$;

CREATE FUNCTION app.platform_exercise_plan_item_json(p_item public.exercise_plan_items) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_item.id,
    'position', p_item.position,
    'variant_lay_name', p_item.variant_lay_name,
    'instruction', p_item.instruction,
    'equipment', to_jsonb(coalesce(p_item.equipment, '{}'::text[])),
    'illustration', p_item.illustration,
    'sets', p_item.sets,
    'reps_min', p_item.reps_min,
    'reps_max', p_item.reps_max,
    'duration_seconds', p_item.duration_seconds,
    'hold_seconds', p_item.hold_seconds,
    'per_side', p_item.per_side,
    'times_per_day', p_item.times_per_day,
    'load', p_item.load,
    'tempo', p_item.tempo,
    'rest_seconds', p_item.rest_seconds,
    'double_progression', p_item.double_progression,
    'note', p_item.note
  )
$$;

CREATE TABLE public.habits (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    action text NOT NULL,
    cue text NOT NULL,
    place text,
    starts_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    paused_at timestamp with time zone,
    paused_by_access_id uuid,
    paused_by_kind text,
    ended_at timestamp with time zone,
    ended_by uuid,
    CONSTRAINT habits_action_check CHECK (((length(btrim(action)) >= 1) AND (length(btrim(action)) <= 120))),
    CONSTRAINT habits_cue_check CHECK (((length(btrim(cue)) >= 1) AND (length(btrim(cue)) <= 120))),
    CONSTRAINT habits_ended_pair CHECK (((ended_at IS NULL) = (ended_by IS NULL))),
    CONSTRAINT habits_paused_by_kind_check CHECK ((paused_by_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT habits_paused_pair CHECK ((((paused_at IS NULL) = (paused_by_access_id IS NULL)) AND ((paused_at IS NULL) = (paused_by_kind IS NULL)))),
    CONSTRAINT habits_place_check CHECK (((place IS NULL) OR ((length(btrim(place)) >= 1) AND (length(btrim(place)) <= 120)))),
    CONSTRAINT habits_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT habits_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND (patient_id = relationship_id)) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id = relationship_id))))
);

COMMENT ON TABLE public.habits IS 'ALT-003 (IDEA-ALT-002, ANN-370): Gewohnheiten mit sehr kleinen Zielen am Verhaeltnis - Was, Ausloeser, Wo oder wann; eingetragen und beendet von der Praxis, pausiert von der Person. Keine Serie, keine Quote, kein Vergleich. Datenklasse des Verhaeltnisses; faellt mit ihm. Kein Tabellenrecht (ADR-004).';

CREATE FUNCTION app.platform_habit_for_writing(p_access_id uuid, p_habit_id uuid) RETURNS public.habits
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_habit  public.habits%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'checkin')
     or not app.platform_access_writable(p_access_id) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if not app.platform_exercise_note_allowed(v_zugang.relationship_kind, v_zugang.relationship_id) then
    raise exception 'habit requires consent' using errcode = '42501';
  end if;
  select * into v_habit
  from public.habits h
  where h.id = p_habit_id
    and h.relationship_kind = v_zugang.relationship_kind
    and h.relationship_id = v_zugang.relationship_id
    and h.ended_at is null
  for update;
  if v_habit.id is null then
    raise exception 'habit not found' using errcode = 'P0002';
  end if;
  return v_habit;
end;
$$;

CREATE FUNCTION app.platform_invitation_validity() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select interval '14 days' $$;

CREATE FUNCTION app.platform_is_minor(p_date_of_birth date, p_time_zone text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select (now() at time zone p_time_zone)::date < app.majority_date(p_date_of_birth)
$$;

COMMENT ON FUNCTION app.platform_is_minor(p_date_of_birth date, p_time_zone text) IS 'Minderjaehrig heute in der Zeitzone der Praxis? Vor app.majority_date (ABN-009). null ohne Geburtsdatum.';

CREATE FUNCTION app.platform_mailbox_confirmed(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.platform_mailbox_confirmations c
    join auth.users u on u.id = c.account_user_id
    where c.account_user_id = p_user
      and c.email = lower(btrim(u.email))
  )
$$;

CREATE FUNCTION app.platform_message_attachments_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Was eine Datei ist, aendert sich nicht (Punkt 8): nur Zustand, Pruefung,
  -- Sperre und der fallende Zugang. Der Objektschluessel ist generiert und im
  -- BEFORE-Trigger noch leer; er folgt aus den Kennungen, die hier geprueft
  -- werden.
  if (to_jsonb(new) - array['status', 'confirmation_requested_at', 'confirmed_at', 'verified_at',
                            'locked_at', 'access_id', 'object_key'])
     is distinct from
     (to_jsonb(old) - array['status', 'confirmation_requested_at', 'confirmed_at', 'verified_at',
                            'locked_at', 'access_id', 'object_key']) then
    raise exception 'message attachments are immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.platform_message_body(p_body text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_body is null or length(btrim(p_body)) = 0 then
    raise exception 'message text is required' using errcode = '22023';
  end if;
  if length(btrim(p_body)) > 2000 then
    raise exception 'message text too long' using errcode = '22023';
  end if;
  return btrim(p_body);
end;
$$;

CREATE FUNCTION app.platform_message_entries_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Faellt nur der Zugang oder der Anhang (on delete set null), bleibt der
  -- Eintrag, wie er ist.
  if tg_op = 'UPDATE'
     and (to_jsonb(new) - array['access_id', 'attachment_id'])
         = (to_jsonb(old) - array['access_id', 'attachment_id'])
     and (new.access_id is not distinct from old.access_id
          or (old.access_id is not null and new.access_id is null))
     and (new.attachment_id is not distinct from old.attachment_id
          or (old.attachment_id is not null and new.attachment_id is null)) then
    return new;
  end if;
  raise exception 'platform message entries are immutable' using errcode = '42501';
end;
$$;

CREATE FUNCTION app.platform_message_entries_only_with_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from public.platform_messages m where m.id = old.message_id) then
    raise exception 'platform message entries are deleted only with their message'
      using errcode = '42501';
  end if;
  return old;
end;
$$;

CREATE FUNCTION app.platform_message_topic_allowed(p_kind text, p_relationship_id uuid, p_topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_topic in ('organisational', 'other') then true
    when p_topic in ('exercise', 'complaint')
      then app.platform_exercise_note_allowed(p_kind, p_relationship_id)
    else false
  end
$$;

CREATE FUNCTION app.platform_messages_record_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.record_assigned_at is not null and (
       new.record_assigned_at is distinct from old.record_assigned_at
       or new.record_assigned_by is distinct from old.record_assigned_by
       or new.record_assigned_by_label is distinct from old.record_assigned_by_label
       or new.topic is distinct from old.topic
       -- Nur das Zusammenfuehren zweier Akten verschiebt einen zugeordneten
       -- Vorgang mit (PRX-018, merge_patients).
       or (new.relationship_id is distinct from old.relationship_id
           and not app.patient_merge_active())
     ) then
    raise exception 'record assignment is final' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.platform_min_age_years() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 18 $$;

CREATE FUNCTION app.platform_notifications_json(p_access_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  -- Die eigene Wahl, die Geräte nur als „ein Gerät seit …" (ohne Endpunkt und
  -- Schlüssel: Zugangsdaten zum Push-Dienst), die Tagebuch-Erinnerungen und
  -- die Zustellaufträge, die der Löschlauf noch nicht genommen hat.
  select jsonb_build_object(
    'settings', (
      select jsonb_build_object(
               'email_kinds', s.email_kinds,
               'push_kinds', s.push_kinds,
               'quiet_from', s.quiet_from,
               'quiet_until', s.quiet_until,
               'chosen_at', s.chosen_at)
      from public.platform_notification_settings s
      where s.access_id = p_access_id
    ),
    'devices', (
      select coalesce(jsonb_agg(jsonb_build_object('registered_at', p.created_at)
                                order by p.created_at), '[]'::jsonb)
      from public.platform_push_subscriptions p
      where p.access_id = p_access_id
    ),
    -- ERN-009: die Erinnerungen an das Ernährungstagebuch, je Mahlzeit die
    -- gewählte Uhrzeit (Ortszeit der Praxis). Mit Beginn und Ende der
    -- Beratung, zu der sie gehören: Erinnerungen einer beendeten Beratung
    -- bleiben stehen, bis das Profil fällt, und sähen sonst aus wie die
    -- der laufenden (Zweitreview).
    'diary_reminders', (
      select coalesce(jsonb_agg(jsonb_build_object(
                        'meal', r.meal,
                        'remind_at', r.remind_at,
                        'chosen_at', r.chosen_at,
                        'profile_started_on', n.started_on,
                        'profile_ended_on', n.ended_on)
                      order by n.started_on, r.remind_at, r.meal), '[]'::jsonb)
      from public.nutrition_diary_reminders r
      join public.nutrition_profiles n on n.id = r.profile_id
      where r.access_id = p_access_id
    ),
    'deliveries', (
      select coalesce(jsonb_agg(jsonb_build_object(
                        'kind', d.kind,
                        'channel', d.channel,
                        'created_at', d.created_at,
                        'due_at', d.due_at,
                        'subject_at', d.subject_at,
                        'state', d.state,
                        'finished_at', d.finished_at,
                        'drop_reason', d.drop_reason)
                      order by d.created_at, d.channel), '[]'::jsonb)
      from public.notification_deliveries d
      where d.access_id = p_access_id
    )
  )
$$;

COMMENT ON FUNCTION app.platform_notifications_json(p_access_id uuid) IS 'BEF-147/BEF-189: Wahl, Geraete (nur seit wann), Tagebuch-Erinnerungen und Zustellauftraege eines Zugangs fuer den eigenen Export. Ohne Rechtepruefung.';

CREATE FUNCTION app.platform_nutrition_for_writing(p_access_id uuid, p_needs_consent boolean) RETURNS public.nutrition_profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'nutrition')
     or not app.platform_access_writable(p_access_id) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select p.* into v_profil
  from public.nutrition_profiles p
  where p.id = (app.platform_nutrition_profile(p_access_id)).id
  for update;
  if v_profil.id is null then
    raise exception 'nutrition profile not found' using errcode = 'P0002';
  end if;
  if p_needs_consent and not app.nutrition_consent_granted(v_profil.id) then
    raise exception 'nutrition consent missing' using errcode = '42501';
  end if;
  return v_profil;
end;
$$;

CREATE FUNCTION app.platform_nutrition_profile(p_access_id uuid) RETURNS public.nutrition_profiles
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.*
  from public.nutrition_profiles p
  join public.platform_accesses a
    on a.id = p_access_id
   and a.organization_id = p.organization_id
   and a.relationship_kind = p.relationship_kind
   and a.relationship_id = p.relationship_id
  where p.ended_on is null
$$;

CREATE TABLE public.exercise_plan_sessions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    performed_on date NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    difficulty_note text,
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    recorded_by uuid NOT NULL,
    finished_access_id uuid,
    finished_access_kind text,
    finished_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reported_started_at timestamp with time zone,
    reported_finished_at timestamp with time zone,
    finish_event_id uuid,
    CONSTRAINT exercise_plan_sessions_difficulty_note_check CHECK (((difficulty_note IS NULL) OR ((length(btrim(difficulty_note, E' \t\r\n'::text)) >= 1) AND (length(btrim(difficulty_note, E' \t\r\n'::text)) <= 500)))),
    CONSTRAINT exercise_plan_sessions_finished_access_kind_check CHECK ((finished_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT exercise_plan_sessions_finished_stamp CHECK ((((finished_at IS NULL) = (finished_by IS NULL)) AND ((finished_at IS NULL) = (finished_access_id IS NULL)) AND ((finished_at IS NULL) = (finished_access_kind IS NULL)))),
    CONSTRAINT exercise_plan_sessions_note_when_finished CHECK (((difficulty_note IS NULL) OR (finished_at IS NOT NULL))),
    CONSTRAINT exercise_plan_sessions_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text])))
);

COMMENT ON TABLE public.exercise_plan_sessions IS 'UEB-010: eine Einheit, die die Person an einem zugewiesenen Plan durchfuehrt (IDEA-ORG-003). Datenklasse wie ihr Plan (Patientenakte bzw. Trainingsverhaeltnis); faellt mit ihm. Geschrieben nur ueber die Plattformfunktionen (ANN-305, ANN-306). Kein Tabellenrecht (ADR-004).';

COMMENT ON COLUMN public.exercise_plan_sessions.finished_at IS 'Beendet: Danach aendert sich nichts mehr. Eine nicht beendete Einheit eines frueheren Tages bleibt so stehen - abgebrochen, nicht verloren (ANN-305).';

COMMENT ON COLUMN public.exercise_plan_sessions.difficulty_note IS 'Freitext der Person. Darf NIEMALS in Betriebslogs oder in den Auditkontext gelangen (ADR-011). Im Training nur mit Einwilligung zu Gesundheitsangaben (ADR-021 Punkt 4, ANN-306).';

COMMENT ON COLUMN public.exercise_plan_sessions.reported_started_at IS 'TRK-007 (ADR-024 Punkt 8): Beginn nach der Uhr des Geraets, wenn die Einheit ohne Netz erfasst und spaeter uebertragen wurde - eine Angabe der Person, keine gepruefte Zeit. started_at ist der Eingang am Server. Datenklasse und Frist wie die Einheit (Patientenakte bzw. Trainingsverhaeltnis, ANN-306).';

COMMENT ON COLUMN public.exercise_plan_sessions.reported_finished_at IS 'TRK-007 (ADR-024 Punkt 8): Ende nach der Uhr des Geraets bei einer uebertragenen Einheit. finished_at ist der Eingang am Server. Datenklasse und Frist wie die Einheit.';

COMMENT ON COLUMN public.exercise_plan_sessions.finish_event_id IS 'TRK-007 (ANN-357): Kennung des Endes, die das Geraet vergeben hat - damit ein zweites Senden desselben Endes nichts aendert. Datenklasse wie die Einheit.';

CREATE FUNCTION app.platform_open_exercise_session(p_access_id uuid, p_session_id uuid) RETURNS public.exercise_plan_sessions
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.*
  from public.exercise_plan_sessions s
  where s.id = p_session_id
    and s.finished_at is null
    -- Eine liegengebliebene Einheit eines frueheren Tages bleibt so stehen
    -- (ANN-305, Zweitreview).
    and s.performed_on = app.training_today(s.organization_id)
    and (app.platform_exercise_plan(p_access_id, s.plan_id)).id is not null
$$;

CREATE TABLE public.platform_messages (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    topic text NOT NULL,
    exercise_plan_id uuid,
    exercise_plan_item_id uuid,
    reference_label text,
    status text DEFAULT 'open'::text NOT NULL,
    due_on date,
    created_by_access_id uuid,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_entry_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid,
    closed_by_side text,
    record_assigned_at timestamp with time zone,
    record_assigned_by uuid,
    record_assigned_by_label text,
    CONSTRAINT platform_messages_closed_by_side_check CHECK ((closed_by_side = ANY (ARRAY['person'::text, 'practice'::text]))),
    CONSTRAINT platform_messages_closed_stamp CHECK (((status = 'closed'::text) = ((closed_at IS NOT NULL) AND (closed_by_side IS NOT NULL)))),
    CONSTRAINT platform_messages_due_while_open CHECK (((status = 'open'::text) = (due_on IS NOT NULL))),
    CONSTRAINT platform_messages_record_assigned_by_label_check CHECK (((record_assigned_by_label IS NULL) OR ((length(btrim(record_assigned_by_label)) >= 1) AND (length(btrim(record_assigned_by_label)) <= 160)))),
    CONSTRAINT platform_messages_record_only_treatment CHECK (((record_assigned_at IS NULL) OR (relationship_kind = 'treatment'::text))),
    CONSTRAINT platform_messages_record_stamp CHECK ((((record_assigned_at IS NULL) = (record_assigned_by IS NULL)) AND ((record_assigned_at IS NULL) = (record_assigned_by_label IS NULL)))),
    CONSTRAINT platform_messages_reference_label_check CHECK (((reference_label IS NULL) OR ((length(btrim(reference_label)) >= 1) AND (length(btrim(reference_label)) <= 200)))),
    CONSTRAINT platform_messages_reference_only_exercise CHECK (((topic = 'exercise'::text) OR ((exercise_plan_id IS NULL) AND (exercise_plan_item_id IS NULL) AND (reference_label IS NULL)))),
    CONSTRAINT platform_messages_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT platform_messages_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND (patient_id = relationship_id)) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id = relationship_id)))),
    CONSTRAINT platform_messages_status_check CHECK ((status = ANY (ARRAY['open'::text, 'answered'::text, 'closed'::text]))),
    CONSTRAINT platform_messages_topic_check CHECK ((topic = ANY (ARRAY['exercise'::text, 'complaint'::text, 'organisational'::text, 'other'::text])))
);

COMMENT ON TABLE public.platform_messages IS 'KOM-001: eine Frage an die Praxis als Vorgang mit Thema, Bezug und Zustand (IDEA-KOM-001, ANN-308). Datenklasse in der Behandlung: Patientenkommunikation, drei Jahre ab Ende des Jahres, in dem der Vorgang erledigt wurde; der Akte zugeordnet (KOM-004): wie die Akte. Im Training: wie das Trainingsverhaeltnis. Kein Tabellenrecht (ADR-023 Punkt 19).';

COMMENT ON COLUMN public.platform_messages.created_by IS 'auth.users.id des fragenden Kontos; bei einer Vertretung das Konto der vertretenden Person (ADR-023 Punkt 14).';

CREATE FUNCTION app.platform_open_message(p_access_id uuid, p_message_id uuid) RETURNS public.platform_messages
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorgang public.platform_messages%rowtype;
begin
  select m.* into v_vorgang
  from app.platform_visible_messages(p_access_id) m
  where m.id = p_message_id;
  if v_vorgang.id is null then
    raise exception 'message not found' using errcode = 'P0002';
  end if;
  if v_vorgang.status = 'closed' then
    raise exception 'message is closed' using errcode = '22023';
  end if;
  return v_vorgang;
end;
$$;

CREATE FUNCTION app.platform_own_access_after_reading(p_access_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select true
    from public.platform_accesses a
    where a.id = p_access_id
      and a.access_kind = 'self'
      and a.status = 'active'
      and (a.patient_id is not null or a.training_relationship_id is not null)
      and app.session_open()
      and (
        (a.account_user_id = auth.uid()
         and not exists (select 1 from public.user_profiles up where up.id = auth.uid()))
        or app.platform_preview_grant(a.id)
      )
  ), false)
$$;

COMMENT ON FUNCTION app.platform_own_access_after_reading(p_access_id uuid) IS 'POR-016 (D2, ANN-261): ob ein eigener, aktiver Zugang mit lebendem Verhaeltnis vorliegt - auch nach der Lesefrist. Nur fuer den Widerruf (und den Stand, den er braucht), nie fuer Lesen, Erteilen oder Export.';

CREATE FUNCTION app.platform_own_name(p_access_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case a.access_kind
           when 'self' then (
             select concat_ws(' ', p.given_name, p.family_name)
             from app.platform_relationship(a.relationship_kind, a.relationship_id) r
             join public.persons p on p.id = r.person_id
           )
           else a.representative_name
         end
  from public.platform_accesses a
  where a.id = p_access_id
    and exists (select 1 from app.platform_readable_access(a.id))
$$;

COMMENT ON FUNCTION app.platform_own_name(p_access_id uuid) IS 'DRP-N1 (ANN-690): der eigene Name des Kontos an einem lesbaren Zugang, fuer Gruss und Initialen der Plattform. Person selbst: Vor- und Nachname aus ihrem Verhaeltnis; Vertretung: representative_name aus dem Nachweis, nie der Name der vertretenen Person. Sonst null.';

CREATE FUNCTION app.platform_practice_phone(p_organization_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select b.phone
  from public.practice_billing_profiles b
  where b.organization_id = p_organization_id
$$;

COMMENT ON FUNCTION app.platform_practice_phone(p_organization_id uuid) IS 'DRP-N2 (ANN-691): die Rufnummer der Praxis fuer die Plattform ("Praxis anrufen"), aus dem Absender der Rechnungen. Ohne Absender oder Nummer null. Enthaelt keine Daten einer Person. SECURITY INVOKER: laeuft mit den Rechten der aufrufenden Projektion, prueft selbst nichts.';

