COMMENT ON FUNCTION app.platform_preview_functions() IS 'E-001: die lesenden Projektionen, die public.platform_preview aufruft (DSN-001 D7). Nichts Schreibendes, kein Export, keine Datei- oder Anhangverweise.';

CREATE FUNCTION app.platform_preview_grant(p_access_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Nur innerhalb von public.platform_preview gesetzt, transaktionslokal; eine
  -- Kennung aus dem Browser kommt hier nie an.
  if p_access_id is null
     or coalesce(current_setting('app.platform_preview_access', true), '') <> p_access_id::text then
    return false;
  end if;
  -- Dieselben Bedingungen wie beim Eintritt in die Einsicht: owner mit offener
  -- Sitzung (has_any_role prueft is_active und app.session_open()), der eigene
  -- aktive Zugang der Person in der eigenen Organisation.
  if not app.has_any_role('owner') then
    return false;
  end if;
  if not exists (
    select 1
    from public.platform_accesses a
    where a.id = p_access_id
      and a.organization_id = app.current_organization_id()
      and a.access_kind = 'self'
      and a.status = 'active'
      and a.account_user_id is not null
  ) then
    return false;
  end if;
  -- ANN-529: Was die Einsicht freigibt, wird nur gelesen. Ab hier kann diese
  -- Transaktion nichts mehr schreiben (SQLSTATE 25006) - keinen Schreibweg der
  -- Person, auch keinen, der nur das Recht 'read' verlangt, und keinen
  -- kuenftigen.
  perform pg_catalog.set_config('transaction_read_only', 'on', true);
  return true;
end;
$$;

COMMENT ON FUNCTION app.platform_preview_grant(p_access_id uuid) IS 'E-001: Gibt die Einsicht der Praxisinhaber:in fuer genau diesen Zugang frei - nur innerhalb von public.platform_preview (Einstellung app.platform_preview_access), nur owner der Organisation, nur der eigene aktive Zugang der Person. Schaltet die Transaktion dabei auf nur lesend.';

CREATE FUNCTION app.platform_questionnaire_instrument(p_instrument_id text, p_version text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- ANN-248: nur, was laut Definition die Patient:in ausfuellt und aktiv ist.
  select exists (
    select 1 from public.questionnaire_definitions d
    where d.instrument_id = p_instrument_id
      and d.version = p_version
      and d.definition -> 'meta' ->> 'ausgefuellt_von' = 'patient'
      and (d.definition -> 'meta' ->> 'aktiv')::boolean
  )
$$;

CREATE FUNCTION app.platform_read_from(p_kind text, p_relationship_id uuid, p_ended_on date) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- ANN-274: Das Abo verlaengert die Lesezeit; 30 Tage ab seinem Ende.
  select case
    when p_ended_on is null then null
    when p_kind <> 'treatment' then p_ended_on
    -- Zweitreview: Ein Abo zaehlt erst ab seinem Beginn, und eines, das vor
    -- dem Beginn gekuendigt wurde, zaehlt nie.
    when exists (
      select 1 from public.aftercare_subscriptions s
      where s.patient_id = p_relationship_id and s.ends_on is null
        and s.starts_on <= app.training_today(s.organization_id)
    ) then null
    else greatest(
      p_ended_on,
      (select max(s.ends_on) from public.aftercare_subscriptions s
        where s.patient_id = p_relationship_id and s.ends_on >= s.starts_on
          and s.ends_on is not null)
    )
  end
$$;

COMMENT ON FUNCTION app.platform_read_from(p_kind text, p_relationship_id uuid, p_ended_on date) IS 'ANG-004 (ANN-274): Tag, ab dem die Lesefrist eines Zugangs zaehlt - Ende des Verhaeltnisses, in der Behandlung spaetestens das Ende des Nachsorge-Abos; null, solange Verhaeltnis oder Abo laufen.';

CREATE FUNCTION app.platform_read_period() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select interval '30 days' $$;

CREATE FUNCTION app.platform_readable_access(p_access_id uuid) RETURNS TABLE(organization_id uuid, relationship_kind text, relationship_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select a.organization_id, a.relationship_kind, a.relationship_id
  from public.platform_accesses a
  where a.id = p_access_id
    and a.status = 'active'
    and coalesce(app.platform_access_ended_at(a.id) > now(), true)
    and app.session_open()
    and (
      -- Die Person selbst oder ihre Vertretung (ADR-023 Punkt 19), unveraendert.
      (a.account_user_id = auth.uid()
       and not exists (select 1 from public.user_profiles up where up.id = auth.uid()))
      -- E-001: die Einsicht der Praxisinhaber:in, nur innerhalb von
      -- public.platform_preview; die Transaktion ist dann nur lesend.
      or app.platform_preview_grant(a.id)
    )
$$;

COMMENT ON FUNCTION app.platform_readable_access(p_access_id uuid) IS 'POR-004: die eine Pruefung fuer Plattformprojektionen (ADR-023 Punkt 19): eigenes Konto, aktiver Zugang, Lesefrist nicht abgelaufen (DSN-001 D2). Fuer keine Anwendungsrolle ausfuehrbar.';

CREATE FUNCTION app.platform_relationship(p_kind text, p_id uuid) RETURNS TABLE(organization_id uuid, person_id uuid, email text, date_of_birth date, ended_on date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.organization_id, p.person_id, lower(btrim(c.email)), c.date_of_birth, p.care_concluded_on
  from public.patients p
  left join public.patient_contact_details c on c.patient_id = p.id
  where p_kind = 'treatment' and p.id = p_id
  union all
  select t.organization_id, t.person_id, lower(btrim(c.email)), c.date_of_birth, t.contract_ended_on
  from public.training_relationships t
  left join public.training_contact_details c on c.training_relationship_id = t.id
  where p_kind = 'training' and t.id = p_id
$$;

CREATE FUNCTION app.platform_visible_attachments(p_access_id uuid) RETURNS SETOF public.platform_message_attachments
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.*
  from app.platform_visible_messages(p_access_id) m
  join public.platform_message_attachments x on x.message_id = m.id
  join public.platform_accesses a on a.id = p_access_id
  where a.access_kind in ('self', 'legal_representative')
    and app.platform_access_allows(p_access_id, 'read')
    and app.message_attachment_visible(x)
$$;

CREATE FUNCTION app.platform_visible_exercise_plans(p_kind text, p_relationship_id uuid) RETURNS SETOF public.exercise_plans
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with eigene as (
    select p.*
    from public.exercise_plans p
    where (p_kind = 'treatment' and p.service_area = 'therapy' and p.patient_id = p_relationship_id)
       or (p_kind = 'training' and p.service_area = 'training'
           and p.training_relationship_id = p_relationship_id)
  )
  select e.* from eigene e where e.status = 'assigned'
  union all
  (
    select e.* from eigene e
    where e.status = 'ended'
      and not exists (select 1 from eigene a where a.status = 'assigned')
    order by e.ended_at desc
    limit 1
  )
$$;

COMMENT ON FUNCTION app.platform_visible_exercise_plans(p_kind text, p_relationship_id uuid) IS 'UEB-009 (ANN-304): Plaene, die die Plattform einem Verhaeltnis zeigt - alle zugewiesenen, sonst der zuletzt beendete. Nie Entwurf, nie abgeloeste Fassung. Ohne Rechtepruefung: nur aus Plattformprojektionen nach app.platform_access_allows aufrufen.';

CREATE FUNCTION app.platform_visible_messages(p_access_id uuid) RETURNS SETOF public.platform_messages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.*
  from public.platform_accesses a
  join public.platform_messages m
    on m.organization_id = a.organization_id
   and m.relationship_kind = a.relationship_kind
   and m.relationship_id = a.relationship_id
  where a.id = p_access_id
    and (
      a.access_kind <> 'companion'
      or coalesce(a.consent_earlier_messages, false)
      or coalesce(m.created_at >= a.consent_recorded_at, false)
    )
$$;

COMMENT ON FUNCTION app.platform_visible_messages(p_access_id uuid) IS 'KOM-001: die Vorgaenge, die ein Zugang sieht (ADR-023 Punkt 13). Ohne Rechtepruefung: nur aus Plattformfunktionen nach app.platform_access_allows aufrufen.';

CREATE FUNCTION app.platform_withdrawal_notice_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 14
$$;

CREATE FUNCTION app.practice_message(p_message_id uuid, p_for_answer boolean) RETURNS public.platform_messages
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorgang public.platform_messages%rowtype;
begin
  select m.* into v_vorgang
  from public.platform_messages m
  where m.id = p_message_id and m.organization_id = app.current_organization_id();
  if v_vorgang.id is null
     or not app.can_read_platform_message(v_vorgang.relationship_kind, v_vorgang.topic) then
    raise exception 'message not found' using errcode = 'P0002';
  end if;
  if p_for_answer
     and not app.can_answer_platform_message(v_vorgang.relationship_kind, v_vorgang.topic) then
    raise exception 'not allowed to answer this message' using errcode = '42501';
  end if;
  return v_vorgang;
end;
$$;

CREATE FUNCTION app.practice_today() RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (now() at time zone o.time_zone)::date
  from public.organizations o
  where o.id = app.current_organization_id()
$$;

COMMENT ON FUNCTION app.practice_today() IS 'AZ-001: heute in der Zeitzone der eigenen Praxis (Leseregel des Wochenplans).';

CREATE FUNCTION app.profile_picture_max_bytes() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 65536
$$;

COMMENT ON FUNCTION app.profile_picture_max_bytes() IS 'TEAM-007 (ADR-017 Punkt 89): höchstens so viele Bytes je Profilbild.';

CREATE FUNCTION app.profile_picture_problem(p_image bytea) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  n       integer := coalesce(octet_length(p_image), 0);
  i       integer := 2;
  m       integer;
  laenge  integer;
  ende    integer;
  folge   integer;
  breite  integer;
  hoehe   integer;
  rahmen  boolean := false;
  scan    boolean := false;
begin
  if n < 128 or n > app.profile_picture_max_bytes() then
    return 'size';
  end if;
  if get_byte(p_image, 0) <> 255 or get_byte(p_image, 1) <> 216 then
    return 'format';
  end if;

  loop
    if i >= n or get_byte(p_image, i) <> 255 then
      return 'format';
    end if;
    -- Füllbytes vor einem Marker.
    while i + 1 < n and get_byte(p_image, i + 1) = 255 loop
      i := i + 1;
    end loop;
    if i + 1 >= n then
      return 'format';
    end if;
    m := get_byte(p_image, i + 1);

    exit when m = 217; -- EOI

    -- RST0-7 und TEM tragen keine Länge.
    if m between 208 and 215 or m = 1 then
      i := i + 2;
      continue;
    end if;

    if i + 4 > n then
      return 'format';
    end if;
    laenge := get_byte(p_image, i + 2) * 256 + get_byte(p_image, i + 3);
    ende := i + 2 + laenge;
    if laenge < 2 or ende > n then
      return 'format';
    end if;

    if m = 238 then
      -- APP14 „Adobe“ sagt dem Dekoder nur, wie die Farben umzurechnen sind:
      -- genau 12 Bytes, sonst trüge es mehr (Zweitreview TEAM-007, Befund 2).
      if laenge <> 14 or substring(p_image from i + 5 for 5) <> '\x41646f6265'::bytea then
        return 'metadata';
      end if;
    elsif m between 224 and 239 or m = 254 then
      -- Alle übrigen APPn (JFIF, EXIF, XMP, ICC, IPTC, Hersteller) und COM.
      return 'metadata';
    elsif m between 192 and 207 and m not in (196, 200, 204) then
      -- SOFn: Höhe und Breite - genau ein Rahmen, sonst zeigte ein Dekoder
      -- womöglich einen anderen als den geprüften (Zweitreview, Befund 3).
      if laenge < 8 or rahmen then
        return 'format';
      end if;
      hoehe := get_byte(p_image, i + 5) * 256 + get_byte(p_image, i + 6);
      breite := get_byte(p_image, i + 7) * 256 + get_byte(p_image, i + 8);
      rahmen := true;
    elsif m = 218 then
      -- SOS: Die Bilddaten des Scans gehören zum Segment, bis ein Marker folgt,
      -- der weder Füllung (FF 00) noch Rücksetzmarker ist.
      if not rahmen then
        return 'format';
      end if;
      scan := true;
      while ende < n loop
        if get_byte(p_image, ende) <> 255 then
          ende := ende + 1;
          continue;
        end if;
        exit when ende + 1 >= n;
        folge := get_byte(p_image, ende + 1);
        if folge = 0 or folge between 208 and 215 then
          ende := ende + 2;
          continue;
        end if;
        exit;
      end loop;
    elsif m in (220, 221) then
      -- DNL und DRI tragen genau zwei Bytes.
      if laenge <> 4 then
        return 'format';
      end if;
    elsif m not in (196, 204, 219) then
      -- Außer DHT, DAC, DQT, DNL und DRI kennt die Erlaubnisliste nichts.
      return 'format';
    end if;

    i := ende;
  end loop;

  -- Das Bildende ist das Ende der Datei; ein Bild hat einen Scan.
  if i + 2 <> n or not scan then
    return 'format';
  end if;
  if breite is distinct from app.profile_picture_side()
     or hoehe is distinct from app.profile_picture_side() then
    return 'dimensions';
  end if;
  return null;
end;
$$;

COMMENT ON FUNCTION app.profile_picture_problem(p_image bytea) IS 'TEAM-007 (ADR-017 Punkt 90): Prüfung eines Profilbilds am Inhalt - JPEG ohne Metadaten, 256 × 256, höchstens 64 KiB. Liefert null oder den Grund der Ablehnung (size, format, metadata, dimensions).';

CREATE FUNCTION app.profile_picture_side() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 256
$$;

COMMENT ON FUNCTION app.profile_picture_side() IS 'TEAM-007 (ADR-017 Punkt 89): Kantenlänge eines Profilbilds in Bildpunkten - quadratisch, auf dem Gerät gerechnet.';

CREATE FUNCTION app.progress_appointment_days_json(p_kind text, p_relationship_id uuid, p_org uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(t.tag order by t.tag), '[]'::jsonb)
  from (
    select distinct (a.starts_at at time zone o.time_zone)::date as tag
    from public.appointments a
    join public.organizations o on o.id = a.organization_id
    where a.organization_id = p_org
      and a.status in ('completed', 'documented', 'invoiced')
      and (
        (p_kind = 'treatment' and a.kind = 'therapy' and a.patient_id = p_relationship_id)
        or (p_kind = 'training' and a.kind = 'training'
            and a.training_relationship_id = p_relationship_id)
      )
    order by 1 desc
    limit 100
  ) t
$$;

COMMENT ON FUNCTION app.progress_appointment_days_json(p_kind text, p_relationship_id uuid, p_org uuid) IS 'OUT-001 (IDEA-OUT-005): die Tage der letzten 100 durchgefuehrten Termine eines Verhaeltnisses (abgeschlossen, dokumentiert, abgerechnet) in der Zeitzone der Praxis - nur der Tag. Ohne Rechtepruefung: nur aus get_checkins.';

CREATE FUNCTION app.progress_plan_events_json(p_kind text, p_relationship_id uuid, p_org uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with plaene as (
    select p.*
    from public.exercise_plans p
    where p.organization_id = p_org
      and p.status <> 'draft'
      and (
        (p_kind = 'treatment' and p.service_area = 'therapy' and p.patient_id = p_relationship_id)
        or (p_kind = 'training' and p.service_area = 'training'
            and p.training_relationship_id = p_relationship_id)
      )
  ), zone as (
    select o.time_zone from public.organizations o where o.id = p_org
  ), ereignisse as (
    select (pl.assigned_at at time zone z.time_zone)::date as occurred_on,
           case when pl.previous_plan_id is null then 'plan_assigned' else 'plan_version' end as kind,
           pl.title, pl.assigned_at as zeitpunkt
    from plaene pl cross join zone z
    where pl.assigned_at is not null
    union all
    select (pl.ended_at at time zone z.time_zone)::date, 'plan_ended', pl.title, pl.ended_at
    from plaene pl cross join zone z
    where pl.status = 'ended' and pl.ended_at is not null
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'occurred_on', e.occurred_on, 'kind', e.kind, 'title', e.title
  ) order by e.occurred_on, e.zeitpunkt), '[]'::jsonb)
  from ereignisse e
$$;

COMMENT ON FUNCTION app.progress_plan_events_json(p_kind text, p_relationship_id uuid, p_org uuid) IS 'OUT-001 (IDEA-OUT-005): Planwechsel eines Verhaeltnisses - zugewiesen, neue Fassung, beendet - mit Tag in der Zeitzone der Praxis und Titel. Ohne Rechtepruefung: nur aus get_checkins.';

-- ANN-347
