COMMENT ON FUNCTION app.questionnaire_body_regions() IS 'Kennungen der Koerperbereiche aus src/features/assessments/koerperschema.ts, erzeugt von scripts/definitionen-sql.mjs (ABN-014).';

CREATE FUNCTION app.record_default_services(p_appointment_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_a            record;
  v_actor        uuid;
  v_performed_on date;
  v_version      uuid;
  v_honorar      record;
  v_anzahl       integer;
begin
  select a.id, a.organization_id, a.patient_id, a.kind, a.status, a.completed_at,
         a.completed_by, a.treatment_basis_id, a.fee_basis
    into v_a
  from public.appointments a
  where a.id = p_appointment_id;

  if not found
     or v_a.kind <> 'therapy'
     or v_a.status <> 'documented'
     or v_a.completed_at is null
     or v_a.treatment_basis_id is null
     or v_a.fee_basis is not null
     or v_a.patient_id is null then
    return 0;
  end if;

  if exists (select 1 from public.billable_services b where b.appointment_id = p_appointment_id) then
    return 0;
  end if;

  -- Tuer geoeffnet, aber nicht behandelt (Hausbesuch-Szenario 1, CAL-018):
  -- Der Termin gilt als durchgefuehrt und wird normal abgerechnet
  -- (PROJECT_PRINCIPLES.md §8, ADR-018 Punkt 9 Nr. 2) - keine Ausnahme hier.
  -- Wie die Rechnung den Fall benennt, bleibt Teil von B4.

  -- Wer abgehakt oder festgeschrieben hat; im naechtlichen Lauf der
  -- automatischen Finalisierung die Person, die abgehakt hat.
  v_actor := coalesce(auth.uid(), v_a.completed_by);

  v_performed_on := app.appointment_performed_on(p_appointment_id);
  v_version := app.active_service_catalog_version(v_a.organization_id, v_performed_on);
  if v_version is null then
    return 0;
  end if;

  select h.amount_cents, h.source, h.fee_agreement_id
    into v_honorar
  from app.session_fee_on(v_a.patient_id, v_performed_on) h;
  if v_honorar.amount_cents is null then
    return 0;
  end if;

  begin
    insert into public.billable_services (
      organization_id, patient_id, training_relationship_id, appointment_id, catalog_item_id,
      treatment_base_item_id, quantity, performed_on, created_by
    )
    select v_a.organization_id, v_a.patient_id, null, p_appointment_id, i.id,
           p.id, 1, v_performed_on, v_actor
    from public.treatment_base_items p
    join lateral (
      select c.id
      from public.service_catalog_items c
      where c.catalog_version_id = v_version
        and c.item_kind = 'treatment'
        and c.service_area = 'therapy'
        and c.remedy = p.remedy
      order by c.sort_order, c.id
      limit 1
    ) i on true
    where p.treatment_basis_id = v_a.treatment_basis_id
      and p.used_quantity < p.prescribed_quantity;

    get diagnostics v_anzahl = row_count;
    if v_anzahl = 0 then
      return 0;
    end if;

    insert into public.appointment_session_fees (
      organization_id, appointment_id, amount_cents, source, fee_agreement_id,
      catalog_version_id, performed_on, created_by
    )
    values (
      v_a.organization_id, p_appointment_id, v_honorar.amount_cents, v_honorar.source,
      v_honorar.fee_agreement_id, v_version, v_performed_on, v_actor
    );

    update public.treatment_base_items p
       set used_quantity = p.used_quantity + b.menge
    from (
      select treatment_base_item_id, sum(quantity)::smallint as menge
      from public.billable_services
      where appointment_id = p_appointment_id and treatment_base_item_id is not null
      group by treatment_base_item_id
    ) b
    where p.id = b.treatment_base_item_id;
  exception
    -- Ein paralleler Vorgang hat schon erfasst (unique) oder die Menge ist
    -- inzwischen erschoepft (check): Dann bleibt es beim Buero.
    when unique_violation or check_violation then
      return 0;
  end;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.record_default_services(p_appointment_id uuid) IS 'B7 (BEF-157, ANN-513, ADR-009 Fassung 6): erfasst die Leistungen eines abgehakten und dokumentierten Behandlungstermins mit Grundlage von selbst - je Heilmittel der Grundlage mit Restmenge eine Einheit, dazu das Terminhonorar. Haelt Haken und Finalisierung nie auf; ohne Grundlage, Preisliste oder Honorar entsteht nichts (Buero: Zu erfassen).';

CREATE FUNCTION app.record_denied_owner_read(p_actor uuid, p_action text, p_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app.record_denied_read(p_actor, p_action, p_message);
end;
$$;

COMMENT ON FUNCTION app.record_denied_owner_read(p_actor uuid, p_action text, p_message text) IS 'Schreibt einen abgewiesenen Leseversuch auf einen owner-Pfad ins Auditlog (OPS-004, ADR-010). Nur fuer list_audit_events und list_deletion_runs.';

CREATE FUNCTION app.record_denied_read(p_actor uuid, p_action text, p_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_eintrag uuid;
begin
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception '%', p_message using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    concat_ws(':', 'access_denied', v_org, p_actor, p_action), 0));

  select a.id into v_eintrag
  from public.audit_log a
  where a.organization_id = v_org
    and a.action = 'access.denied'
    and a.actor_user_id is not distinct from p_actor
    and a.context ->> 'operation' = p_action
    and a.occurred_at > now() - interval '10 minutes'
  order by a.occurred_at desc
  limit 1;

  if v_eintrag is not null then
    update public.audit_log a
       set context = a.context || jsonb_build_object(
             'count', coalesce((a.context ->> 'count')::integer, 1) + 1,
             'last_at', now()
           )
     where a.id = v_eintrag;
    return;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, p_actor, 'access.denied', 'organization', v_org, 'denied',
    jsonb_build_object('surface', 'api', 'reason', 'role', 'operation', p_action, 'count', 1)
  );
end;
$$;

COMMENT ON FUNCTION app.record_denied_read(p_actor uuid, p_action text, p_message text) IS 'Schreibt eine Abweisung als access.denied (LOG-EPIC-001, ADR-010). Gleiche Person und operation innerhalb von zehn Minuten: Zaehler im ersten Eintrag statt einer neuen Zeile.';

CREATE FUNCTION app.record_denied_write(p_actor uuid, p_action text, p_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app.record_denied_read(p_actor, p_action, p_message);
  perform pg_catalog.set_config('response.status', '403', true);
end;
$$;

COMMENT ON FUNCTION app.record_denied_write(p_actor uuid, p_action text, p_message text) IS 'Schreibt einen abgewiesenen Schreibversuch ins Auditlog und setzt response.status = 403 (G6c, ADR-010, ANN-115). Aufrufer: die zehn Schreibpfade fuer Rollen und Konten, Legal Hold und Loeschauftraege.';

CREATE FUNCTION app.record_nutrition_service(p_appointment_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_a            record;
  v_performed_on date;
  v_version      uuid;
  v_position     uuid;
begin
  select a.id, a.organization_id, a.patient_id, a.training_relationship_id, a.kind,
         a.status, a.completed_by, a.occasion
    into v_a
  from public.appointments a
  where a.id = p_appointment_id;

  if not found or v_a.occasion <> 'nutrition_counselling' or v_a.status <> 'completed' then
    return 0;
  end if;
  if exists (select 1 from public.billable_services b where b.appointment_id = p_appointment_id) then
    return 0;
  end if;

  v_performed_on := app.appointment_performed_on(p_appointment_id);
  v_version := app.active_service_catalog_version(v_a.organization_id, v_performed_on);
  if v_version is null then
    return 0;
  end if;

  select c.id into v_position
  from public.service_catalog_items c
  where c.catalog_version_id = v_version
    and c.item_kind = 'nutrition_counselling'
    and c.service_area = app.service_area_of_appointment_kind(v_a.kind)
  order by c.sort_order, c.id
  limit 1;
  if v_position is null then
    return 0;
  end if;

  -- Kommt ein paralleler Vorgang dazwischen (unique, check), hält der Haken
  -- nicht an; es bleibt beim Büro („Zu erfassen“).
  begin
    insert into public.billable_services (
      organization_id, patient_id, training_relationship_id, appointment_id, catalog_item_id,
      quantity, performed_on, created_by
    )
    values (
      v_a.organization_id, v_a.patient_id, v_a.training_relationship_id, p_appointment_id,
      v_position, 1, v_performed_on, coalesce(auth.uid(), v_a.completed_by)
    );
  exception
    when unique_violation or check_violation then
      return 0;
  end;
  return 1;
end;
$$;

COMMENT ON FUNCTION app.record_nutrition_service(p_appointment_id uuid) IS 'ERN-011 (ANN-664): Mit dem Haken am Beratungstermin entsteht die erste Position "Ernährungsberatung" des Bereichs aus der am Leistungstag geltenden Preisliste, Menge 1. Ohne Position, ohne Preisliste oder bei einem parallelen Vorgang entsteht nichts; der Termin steht dann unter "Zu erfassen". Ohne Rechteprüfung, nur aus dem Trigger.';

CREATE FUNCTION app.record_treatment_basis_version(p_treatment_basis_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_basis record;
  v_nr    integer;
begin
  select b.id, b.organization_id, b.created_at
    into v_basis
  from public.treatment_bases b
  where b.id = p_treatment_basis_id;

  if not found or v_basis.created_at = now() then
    return;
  end if;

  if exists (
    select 1 from public.treatment_basis_versions v
    where v.treatment_basis_id = p_treatment_basis_id
      and v.replaced_at = now()
  ) then
    return;
  end if;

  select coalesce(max(v.version_no), 0) + 1 into v_nr
  from public.treatment_basis_versions v
  where v.treatment_basis_id = p_treatment_basis_id;

  insert into public.treatment_basis_versions (
    organization_id, treatment_basis_id, version_no, content, replaced_by
  )
  values (
    v_basis.organization_id, p_treatment_basis_id, v_nr,
    app.treatment_basis_content(p_treatment_basis_id), auth.uid()
  );
end;
$$;

CREATE FUNCTION app.reduce_training_relationship(p_relationship_id uuid, p_run_id uuid, p_due_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_count integer := 0;
  v_n     integer;
begin
  -- TRN-009: die Protokolle zuerst - auch die am abgerechneten Termin. Der
  -- Termin bleibt `documented` als Tatsache stehen; was in der Einheit
  -- geschah, traegt die Belegfrist nicht (ANN-183).
  with geloescht as (
    delete from public.training_protocols p
     where p.training_relationship_id = p_relationship_id
    returning p.id, p.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'training_protocols', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- KOM-004: Rueckfragen ueber die Plattform. Sie tragen keine Belegfrist
  -- und fallen nach den drei Jahren aus ADR-021 Punkt 4; die Eintraege mit
  -- ihnen (cascade).
  with geloescht as (
    delete from public.platform_messages m
     where m.training_relationship_id = p_relationship_id
    returning m.id, m.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'platform_messages', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Kontakt, Anschrift, Geburtsdatum. Der Schluessel ist das Verhaeltnis;
  -- er steht als Kennung im Journal.
  with geloescht as (
    delete from public.training_contact_details c
     where c.training_relationship_id = p_relationship_id
    returning c.training_relationship_id as id, c.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'training_contact_details', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Termine ohne Leistung: kein Beleg, nichts, was die Frist traegt.
  with geloescht as (
    delete from public.appointments a
     where a.training_relationship_id = p_relationship_id
       and not exists (select 1 from public.billable_services b where b.appointment_id = a.id)
    returning a.id, a.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'appointments', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- Vereinbarungen, an denen kein verbliebener Termin mehr haengt.
  with geloescht as (
    delete from public.training_bases tb
     where tb.training_relationship_id = p_relationship_id
       and not exists (select 1 from public.appointments a where a.training_basis_id = tb.id)
    returning tb.id, tb.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'training_bases', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  -- ERN-001: die Ernaehrungsberatung am Verhaeltnis. Sie traegt keine
  -- Belegfrist; faellt das Verhaeltnis frueher als ihre eigene Frist, faellt
  -- sie mit ihm (ADR-027 Punkt 6) - auch ein nie beendetes Profil.
  -- Einwilligung und Gewicht mit ihm (cascade).
  with geloescht as (
    delete from public.nutrition_profiles n
     where n.training_relationship_id = p_relationship_id
    returning n.id, n.organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, p_run_id, 'nutrition_profiles', g.id, 'trainingsverhaeltnis', p_due_at
  from geloescht g;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  return v_count;
end;
$$;

COMMENT ON FUNCTION app.reduce_training_relationship(p_relationship_id uuid, p_run_id uuid, p_due_at timestamp with time zone) IS 'Teilloeschung eines Trainingsverhaeltnisses nach drei Jahren, solange seine Belege noch in der steuerlichen Frist liegen (ANN-183, ADR-021 Punkt 4, ADR-008 Punkt 2): Protokolle, Kontakt, Termine ohne Leistung und unbenutzte Vereinbarungen fallen, jeder Datensatz im Journal. Der Rest faellt mit app.delete_training_relationship.';

CREATE FUNCTION app.reimbursement_receipt_bucket() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'erstattungsbelege'::text
$$;

COMMENT ON FUNCTION app.reimbursement_receipt_bucket() IS 'ERS-001 (ANN-600): Name des privaten Buckets der Belege. Die einzige Stelle, an der er steht.';

CREATE FUNCTION app.reimbursement_receipt_limit() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 10
$$;

CREATE FUNCTION app.reimbursement_start(p_iban text) RETURNS TABLE(organization_id uuid, staff_member_id uuid, self_entered boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = 'P0002';
  end if;
  if p_iban is not null then
    perform app.store_payout_account(v_org, v_staff, p_iban);
  end if;
  if not exists (select 1 from public.staff_payout_accounts a where a.staff_member_id = v_staff) then
    raise exception 'payout account missing' using errcode = '22023';
  end if;
  return query select v_org, v_staff, app.can_decide_staff_requests();
end;
$$;

CREATE FUNCTION app.reimbursement_view(p_reimbursement public.staff_reimbursements) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p_reimbursement.id,
    'staff_member_id', p_reimbursement.staff_member_id,
    'name', app.staff_display_name(p_reimbursement.staff_member_id),
    'kind', p_reimbursement.kind,
    'period_month', p_reimbursement.period_month,
    'working_days', p_reimbursement.working_days,
    'energy_wh_per_day', p_reimbursement.energy_wh_per_day,
    'working_minutes', p_reimbursement.working_minutes,
    'km_per_hour', p_reimbursement.km_per_hour,
    'wh_per_km', p_reimbursement.wh_per_km,
    'tour_km', p_reimbursement.tour_km,
    'rate_cents_per_kwh', p_reimbursement.rate_cents_per_kwh,
    'amount_cents', p_reimbursement.amount_cents,
    'status', p_reimbursement.status,
    'self_entered', p_reimbursement.self_entered,
    'requested_at', p_reimbursement.requested_at,
    'decided_at', p_reimbursement.decided_at,
    'decided_by_name', app.account_display_name(p_reimbursement.decided_by),
    'decision_note', p_reimbursement.decision_note,
    'withdrawn_at', p_reimbursement.withdrawn_at,
    'paid_at', p_reimbursement.paid_at,
    'paid_by_name', app.account_display_name(p_reimbursement.paid_by),
    'receipts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', b.id, 'amount_cents', b.amount_cents, 'purpose', b.purpose,
               'mime_type', b.mime_type, 'verified', b.verified_at is not null
             ) order by b.attached_at, b.id)
      from public.staff_reimbursement_receipts b
      where b.reimbursement_id = p_reimbursement.id
    ), '[]'::jsonb)
  )
$$;

CREATE FUNCTION app.reimbursement_view(p_reimbursement public.staff_reimbursements, p_full boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_full or p_reimbursement.tour_km is null then app.reimbursement_view(p_reimbursement)
    else app.reimbursement_view(p_reimbursement) || jsonb_build_object(
      'tour_km', null, 'amount_cents', null, 'wh_per_km', null, 'rate_cents_per_kwh', null
    )
  end
$$;

COMMENT ON FUNCTION app.reimbursement_view(p_reimbursement public.staff_reimbursements, p_full boolean) IS 'BEF-181 (ANN-616): Ansicht eines Antrags; ohne p_full fehlen bei einem Antrag aus Touren tour_km, amount_cents, wh_per_km und rate_cents_per_kwh. Voll nur für die Person selbst und owner (ADR-019 Fassung 6).';

CREATE FUNCTION app.reimbursement_working_minutes(p_org uuid, p_staff_member_id uuid, p_month date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(sum(extract(epoch from (upper(r) - lower(r))) / 60), 0)::integer
  from generate_series(p_month, (p_month + interval '1 month' - interval '1 day')::date,
                       interval '1 day') as d
  cross join (select o.federal_state from public.organizations o where o.id = p_org) as o
  cross join lateral unnest(app.working_ranges(p_staff_member_id, p_org, d::date)) as r
  where not app.is_public_holiday(d::date, o.federal_state)
$$;

COMMENT ON FUNCTION app.reimbursement_working_minutes(p_org uuid, p_staff_member_id uuid, p_month date) IS 'ORG-008: geplante Arbeitsminuten einer Person in einem Monat - Wochenplan in Fassungen mit Abweichungen, ohne Feiertage und ganztägige Abwesenheit. Kein Bezug auf Touren oder Termine.';

CREATE FUNCTION app.reject_password_via_auth_service() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if current_user = 'supabase_auth_admin'
     and coalesce(new.encrypted_password, '') <> ''
     and (tg_op = 'INSERT' or new.encrypted_password is distinct from old.encrypted_password) then
    raise exception 'password sign-in is disabled' using errcode = '42501';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.reject_password_via_auth_service() IS 'Kein Kennwort über den Anmeldedienst (ADR-025 Punkt 9, ANN-330): lehnt jedes Kennwort ab, das supabase_auth_admin setzt. Kennwörter der Testkonten kommen per SQL (Seed, Test-Umgebung).';

CREATE FUNCTION app.reminder_care_idle() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select interval '6 months' $$;

COMMENT ON FUNCTION app.reminder_care_idle() IS 'ANN-146: So lange ohne Behandlungstermin (und ohne kommenden), bis die Frage nach dem Abschluss der Versorgung erscheint.';

CREATE FUNCTION app.reminder_prescription_horizon() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select interval '14 days' $$;

COMMENT ON FUNCTION app.reminder_prescription_horizon() IS 'ANN-146: Eine Verordnung, deren letzter verplanter Termin innerhalb dieses Zeitraums liegt, gilt als endend.';

CREATE FUNCTION app.remove_message_attachments(p_organization_id uuid, p_scope text, p_id uuid, p_run_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  with kandidaten as (
    select x.id,
           least(x.created_at + app.retention_interval('rueckfrageanhang'),
                 coalesce(x.locked_at, 'infinity'::timestamptz)) as due_at,
           x.locked_at,
           m.relationship_kind = 'treatment'
             and app.under_legal_hold(p_organization_id, 'patient', m.patient_id) as gehalten
    from public.platform_message_attachments x
    join public.platform_messages m on m.id = x.message_id
    where x.organization_id = p_organization_id
      and case p_scope
            when 'attachment' then x.id = p_id
            when 'relationship' then m.relationship_id = p_id
            when 'due' then true
            else false
          end
    for update of x
  ),
  betroffen as (
    select k.id, k.locked_at, k.gehalten,
           case when p_scope = 'due' then k.due_at else now() end as due_at
    from kandidaten k
    where p_scope <> 'due' or k.due_at <= now()
  ),
  gesperrt as (
    update public.platform_message_attachments x
       set locked_at = b.due_at
      from betroffen b
     where x.id = b.id and b.gehalten and b.locked_at is null
    returning x.id
  ),
  zu_loeschen as (
    select b.id, b.due_at from betroffen b where not b.gehalten
  ),
  geloescht as (
    delete from public.platform_message_attachments x
    using zu_loeschen z
    where x.id = z.id
    returning x.id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select p_organization_id, p_run_id, 'platform_message_attachments', g.id, 'rueckfrageanhang',
         z.due_at
  from geloescht g
  join zu_loeschen z on z.id = g.id;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.remove_message_attachments(p_organization_id uuid, p_scope text, p_id uuid, p_run_id uuid) IS 'KOM-005 (ADR-017 Punkte 61, 65, 67; ANN-335): loescht Anhaenge mit Loeschjournal - einen, alle eines Verhaeltnisses (Widerruf) oder die faelligen (Lauf). Unter Legal Hold der Akte gesperrt statt geloescht. Der Trigger schreibt die Loeschauftraege fuer die Objekte.';

CREATE FUNCTION app.rest_minutes(p_day jsonb, p_next jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when coalesce(jsonb_array_length(p_day), 0) = 0 or coalesce(jsonb_array_length(p_next), 0) = 0
      then null
    else (24 * 60
          - extract(epoch from (p_day -> (jsonb_array_length(p_day) - 1) ->> 'bis')::time) / 60
          + extract(epoch from (p_next -> 0 ->> 'von')::time) / 60)::integer
  end
$$;

CREATE FUNCTION app.retention_due_at(p_from date, p_interval interval, p_time_zone text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select (((p_from + p_interval)::date + 1)::timestamp) at time zone p_time_zone
$$;

COMMENT ON FUNCTION app.retention_due_at(p_from date, p_interval interval, p_time_zone text) IS 'Faelligkeit einer Aufbewahrungsfrist: Mitternacht der Praxiszeitzone nach dem letzten Tag der Frist (ADR-008, LOE-002a).';

CREATE FUNCTION app.retention_interval(p_class text) RETURNS interval
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_interval interval;
  v_found    boolean;
begin
  select rc.retention_interval, true
    into v_interval, v_found
  from public.retention_classes rc
  where rc.key = p_class;

  if not coalesce(v_found, false) then
    raise exception 'unknown retention class %', p_class using errcode = '22023';
  end if;

  return v_interval;
end;
$$;

COMMENT ON FUNCTION app.retention_interval(p_class text) IS 'Aufbewahrungsdauer einer Datenklasse aus dem Retention Schedule. Leer bedeutet: keine automatische Loeschung (ADR-008, ANN-001).';

CREATE FUNCTION app.retention_upper_interval(p_class text) RETURNS interval
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select rc.upper_bound_interval from public.retention_classes rc where rc.key = p_class
$$;

COMMENT ON FUNCTION app.retention_upper_interval(p_class text) IS 'Obergrenze einer Datenklasse aus dem Retention Schedule, leer ohne Obergrenze (ADR-017 Punkt 38, ANN-001).';

CREATE FUNCTION app.revenue_documents(p_organization_id uuid, p_from date, p_to date) RETURNS TABLE(tag date, bereich text, betrag bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select i.issued_on,
         coalesce(i.snapshot ->> 'service_area', i.service_area),
         app.snapshot_gross_cents(i.snapshot)
  from public.invoices i
  where i.organization_id = p_organization_id
    and i.status = 'issued'
    and i.issued_on >= p_from
    and i.issued_on < p_to
  union all
  select c.cancelled_on,
         coalesce(i.snapshot ->> 'service_area', i.service_area),
         -app.snapshot_gross_cents(i.snapshot)
  from public.invoice_cancellations c
  join public.invoices i on i.id = c.invoice_id
  where c.organization_id = p_organization_id
    and c.cancelled_on >= p_from
    and c.cancelled_on < p_to
$$;

COMMENT ON FUNCTION app.revenue_documents(p_organization_id uuid, p_from date, p_to date) IS 'STA-001: Umsatz nach Rechnungsstellung als Buchungen (Tag, Bereich, Betrag brutto) im halboffenen Zeitraum [p_from, p_to). Einzige Stelle der Regel fuer Kennzahlen und Monatsreihe. Ohne Rollenpruefung.';

CREATE FUNCTION app.revenue_snapshot_items(p_organization_id uuid, p_from date, p_to date) RETURNS TABLE(tag date, code text, label text, betrag bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with dokument as (
    select i.snapshot, i.issued_on as tag, 1 as vorzeichen
    from public.invoices i
    where i.organization_id = p_organization_id
      and i.status = 'issued'
      and i.issued_on >= p_from
      and i.issued_on < p_to
    union all
    select i.snapshot, c.cancelled_on, -1
    from public.invoice_cancellations c
    join public.invoices i on i.id = c.invoice_id
    where c.organization_id = p_organization_id
      and c.cancelled_on >= p_from
      and c.cancelled_on < p_to
  )
  select d.tag,
         z ->> 'code',
         z ->> 'label',
         (d.vorzeichen * (z ->> 'line_total_cents')::bigint)::bigint
  from dokument d
  cross join lateral jsonb_array_elements(coalesce(d.snapshot -> 'items', '[]'::jsonb)) as z
$$;

COMMENT ON FUNCTION app.revenue_snapshot_items(p_organization_id uuid, p_from date, p_to date) IS 'STA-004: Umsatz nach Rechnungsstellung je Zeile des Snapshots im Zeitraum [p_from, p_to) mit Kuerzel und Bezeichnung; Storno am eigenen Tag mit umgekehrtem Vorzeichen. Eingefroren wie das Dokument. Ohne Rollenpruefung.';

CREATE FUNCTION app.revenue_staff_lines(p_organization_id uuid, p_from date, p_to date) RETURNS TABLE(tag date, invoice_id uuid, staff_member_id uuid, betrag bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with dokument as (
    select i.id, i.issued_on as tag, 1 as vorzeichen
    from public.invoices i
    where i.organization_id = p_organization_id
      and i.status = 'issued'
      and i.issued_on >= p_from
      and i.issued_on < p_to
    union all
    select c.invoice_id, c.cancelled_on, -1
    from public.invoice_cancellations c
    where c.organization_id = p_organization_id
      and c.cancelled_on >= p_from
      and c.cancelled_on < p_to
  )
  select d.tag,
         d.id,
         a.staff_member_id,
         -- ABR-031: Anteil am Terminhonorar oder Katalogpreis.
         (d.vorzeichen * app.billable_service_amount(b.id))::bigint
  from dokument d
  join public.invoice_items it         on it.invoice_id = d.id
  join public.billable_services b      on b.id = it.billable_service_id
  join public.service_catalog_items ci on ci.id = b.catalog_item_id
  left join public.appointments a      on a.id = b.appointment_id
$$;

COMMENT ON FUNCTION app.revenue_staff_lines(p_organization_id uuid, p_from date, p_to date) IS 'STA-004: Umsatz nach Rechnungsstellung je Rechnungsposten mit der behandelnden Person des Termins, Storno mit umgekehrtem Vorzeichen. Nicht eingefroren (ein geloeschter Posten faellt weg); STA-006 fuehrt die Differenz zur Praxissumme als ohne Zuordnung (ANN-156). Ohne Rollenpruefung.';

CREATE FUNCTION app.serie_kennung() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select nullif(coalesce(current_setting('app.event_series_id', true), ''), '')::uuid;
$$;

COMMENT ON FUNCTION app.serie_kennung() IS 'Die Serie, zu der die Ereignisse dieser Transaktion gehoeren - oder null. Nur create_event_series setzt sie, transaktionslokal (CAL-021).';

CREATE FUNCTION app.service_area_of_appointment_kind(p_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_kind
           when 'therapy'  then 'therapy'
           when 'training'  then 'training'
           else null
         end;
$$;

COMMENT ON FUNCTION app.service_area_of_appointment_kind(p_kind text) IS 'Der Leistungsbereich zu einem Terminkontext (ADR-009 Punkt 16, ADR-022 Punkt 2): treatment -> therapy, training -> training. null fuer den internen Termin - er erzeugt keine Leistung.';

CREATE FUNCTION app.service_catalog_item_stays_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_published timestamptz;
  v_version   uuid;
begin
  v_version := case when tg_op = 'DELETE' then old.catalog_version_id else new.catalog_version_id end;

  select v.published_at into v_published
  from public.service_catalog_versions v
  where v.id = v_version;

  if v_published is not null then
    raise exception 'published service catalog version is immutable'
      using errcode = '23514';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

COMMENT ON FUNCTION app.service_catalog_item_stays_frozen() IS 'Haelt die Positionen einer veroeffentlichten Katalogversion unveraenderlich (ABR-001). Das Loeschen der Version selbst raeumt sie ueber on delete cascade ab - dorthin kommt nur ein Entwurf.';

CREATE FUNCTION app.service_catalog_version_stays_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.published_at is not null then
      raise exception 'published service catalog version is immutable'
        using errcode = '23514';
    end if;
    return old;
  end if;

  if old.published_at is not null then
    raise exception 'published service catalog version is immutable'
      using errcode = '23514';
  end if;

  -- Der Entwurf darf alles werden ausser einer anderen Organisation.
  if new.organization_id <> old.organization_id then
    raise exception 'service catalog version cannot change organization'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION app.service_catalog_version_stays_frozen() IS 'Haelt eine veroeffentlichte Katalogversion unveraenderlich (ABR-001, ADR-009 Punkt 5). Am Trigger und nicht im Schreibpfad, damit die Zusage fuer jeden Weg in die Tabelle gilt.';

CREATE FUNCTION app.session_consumed() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.session_unlocks u
    where u.session_id = app.jwt_session_id()
      and u.consumed_at is not null
  )
$$;

COMMENT ON FUNCTION app.session_consumed() IS 'Ob die laufende Sitzung durch Fehlversuche mit der App-PIN verbraucht ist (ADR-025 Punkt 11). Eine verbrauchte Sitzung oeffnet sich nie wieder.';

CREATE FUNCTION app.session_fee_lines(p_appointment_id uuid) RETURNS TABLE(billable_service_id uuid, line_cents bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with honorar as (
    select f.amount_cents::bigint as betrag
    from public.appointment_session_fees f
    where f.appointment_id = p_appointment_id
  ),
  zeile as (
    select b.id,
           c.sort_order,
           c.unit_price_cents::bigint as gewicht
    from public.billable_services b
    join public.service_catalog_items c on c.id = b.catalog_item_id
    where b.appointment_id = p_appointment_id
      and c.item_kind = 'treatment'
      and c.remedy is not null
  ),
  summe as (
    select sum(z.gewicht) as gewichte, count(*) as anzahl from zeile z
  ),
  anteil as (
    select z.id, z.sort_order, h.betrag,
           case when s.gewichte > 0 then (h.betrag * z.gewicht) / s.gewichte
                else h.betrag / s.anzahl end as abgerundet,
           case when s.gewichte > 0 then (h.betrag * z.gewicht) % s.gewichte
                else h.betrag % s.anzahl end as rest
    from zeile z cross join honorar h cross join summe s
  ),
  verteilt as (
    select a.*,
           row_number() over (order by a.rest desc, a.sort_order, a.id) as platz,
           a.betrag - sum(a.abgerundet) over () as offen
    from anteil a
  )
  select v.id, (v.abgerundet + case when v.platz <= v.offen then 1 else 0 end)::bigint
  from verteilt v
$$;

COMMENT ON FUNCTION app.session_fee_lines(p_appointment_id uuid) IS 'Teilt das Terminhonorar eines Termins auf seine bestaetigten Heilmittel auf (ABR-031, ADR-009 Punkt 23, ANN-233): anteilig nach den Preisen der Preisliste, Restcents an die groessten Bruchteile. Die Summe ist genau das Honorar. Die eine Stelle der Rechnungsdarstellung (B17).';

CREATE FUNCTION app.session_fee_on(p_patient_id uuid, p_on date, OUT amount_cents integer, OUT source text, OUT fee_agreement_id uuid, OUT valid_from date) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  select p.organization_id into v_org from public.patients p where p.id = p_patient_id;
  if not found then
    return;
  end if;

  select f.session_fee_cents, 'agreement', f.id, f.valid_from
    into amount_cents, source, fee_agreement_id, valid_from
  from public.patient_fee_agreements f
  where f.patient_id = p_patient_id
    and f.valid_from <= p_on
  order by f.valid_from desc
  limit 1;

  if found then
    return;
  end if;

  select v.session_fee_cents, 'tariff', null::uuid, v.valid_from
    into amount_cents, source, fee_agreement_id, valid_from
  from public.service_catalog_versions v
  where v.id = app.active_service_catalog_version(v_org, p_on)
    and v.session_fee_cents is not null;

  if not found then
    amount_cents := null;
    source := null;
    fee_agreement_id := null;
    valid_from := null;
  end if;
end;
$$;

COMMENT ON FUNCTION app.session_fee_on(p_patient_id uuid, p_on date, OUT amount_cents integer, OUT source text, OUT fee_agreement_id uuid, OUT valid_from date) IS 'Das am Leistungstag geltende Terminhonorar einer Person (ABR-030, ADR-009 Punkte 5 und 22, ANN-231): die juengste Honorarvereinbarung bis zu diesem Tag, sonst der Tarif der dann gueltigen Preisliste, sonst null.';

CREATE FUNCTION app.session_idle_timeout() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select interval '30 minutes'
$$;

COMMENT ON FUNCTION app.session_idle_timeout() IS 'Inaktivitaetsfrist (ADR-025 Punkt 2, W1 (a), Jannes 2026-10-06). Gilt fuer Praxis- und Plattformkonten (Punkt 8).';

CREATE FUNCTION app.session_max_duration() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select interval '60 minutes'
$$;

COMMENT ON FUNCTION app.session_max_duration() IS 'Hoechstdauer bis zur erneuten Freigabe, gezaehlt ab der letzten Anmeldung (ADR-025 Punkt 1). Gilt fuer Praxis- und Plattformkonten (Punkt 8).';

CREATE FUNCTION app.session_open() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select now() < t.last_authentication + app.session_max_duration()
       and now() < t.last_activity + app.session_idle_timeout()
       -- Eine Anmeldung aus der Zukunft (falsche Uhr, gebautes Token) oeffnet nichts.
       and t.last_authentication <= now() + interval '1 minute'
    from app.session_times() t
  ), false)
$$;

COMMENT ON FUNCTION app.session_open() IS 'Ob die laufende Sitzung offen ist: hoechstens 60 Minuten nach der letzten Anmeldung und 30 Minuten nach der letzten Bedienung (ADR-025 Punkte 1, 2, 6). Ohne Token, amr oder session_id: false.';

CREATE FUNCTION app.session_times(OUT last_authentication timestamp with time zone, OUT last_activity timestamp with time zone) RETURNS record
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select greatest(a.letzte_anmeldung, f.pin_unlocked_at),
         greatest(a.letzte_anmeldung, f.pin_unlocked_at, (
           select s.last_activity_at
           from public.session_activity s
           where s.session_id = app.jwt_session_id()
             and s.user_id = auth.uid()
         ))
  from (select app.last_first_factor() as letzte_anmeldung) a
  left join lateral (
    select u.pin_unlocked_at
    from public.session_unlocks u
    where u.session_id = app.jwt_session_id()
      and u.user_id = auth.uid()
  ) f on true
  where auth.uid() is not null
    and app.jwt_session_id() is not null
    and a.letzte_anmeldung is not null
    and not app.session_consumed()
$$;

CREATE FUNCTION app.set_patient_file_object_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.object_key := new.organization_id::text || '/'
                      || coalesce(new.treatment_basis_id, new.patient_id)::text || '/'
                      || new.id::text;
  elsif new.object_key is distinct from old.object_key then
    raise exception 'the object key of a patient file cannot be changed' using errcode = '55000';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.set_team_mentions(p_message uuid, p_mentions uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m public.team_messages%rowtype;
begin
  select * into v_m from public.team_messages where id = p_message;
  delete from public.team_message_mentions where message_id = p_message;
  insert into public.team_message_mentions (organization_id, message_id, staff_member_id)
  select distinct v_m.organization_id, p_message, x.staff
  from unnest(coalesce(p_mentions, '{}'::uuid[])) as x (staff)
  where x.staff is distinct from v_m.author_staff_member_id
    and app.teamchat_participant(v_m.organization_id, x.staff)
    and app.team_channel_readable(v_m.channel_id, v_m.organization_id, x.staff);
end;
$$;

CREATE FUNCTION app.set_training_basis_status(p_basis_id uuid, p_status text, p_action text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_alt    record;
begin
  v_actor := auth.uid();
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training bases' using errcode = '42501';
  end if;

  select b.id, b.status, b.training_relationship_id, t.status as relationship_status
    into v_alt
  from public.training_bases b
  join public.training_relationships t on t.id = b.training_relationship_id
  where b.id = p_basis_id
    and b.organization_id = v_org
  for update of b;

  if not found then
    raise exception 'training basis not found' using errcode = 'P0002';
  end if;

  if v_alt.status = p_status then
    return p_basis_id;
  end if;

  if p_status = 'active' and v_alt.relationship_status <> 'active' then
    raise exception 'training relationship is not active' using errcode = '22023';
  end if;

  update public.training_bases
     set status     = p_status,
         updated_at = now(),
         updated_by = v_actor
   where id = p_basis_id;


  return p_basis_id;
end;
$$;

CREATE FUNCTION app.small_business_notice() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'Steuerbefreiung für Kleinunternehmer gemäß § 19 Abs. 1 UStG – es wird keine Umsatzsteuer berechnet.'::text
$$;

COMMENT ON FUNCTION app.small_business_notice() IS 'BEF-165, ANN-541: Wortlaut des Hinweises nach Par. 19 Abs. 1 UStG, den app.build_invoice_document beim Ausstellen in den Schnappschuss schreibt (issuer.small_business_notice). Fester Text wie app.tax_exemption_reason (ANN-082).';

CREATE FUNCTION app.snapshot_gross_cents(p_snapshot jsonb) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(sum((g ->> 'gross_cents')::bigint), 0)::bigint
  from jsonb_array_elements(coalesce(p_snapshot -> 'tax_groups', '[]'::jsonb)) as g
$$;

COMMENT ON FUNCTION app.snapshot_gross_cents(p_snapshot jsonb) IS 'STA-001: Brutto eines ausgestellten Rechnungsdokuments als Summe seiner Steuergruppen im Snapshot - dieselbe Grundlage wie list_revenue_by_service_area (ABR-011).';

CREATE FUNCTION app.staff_can_counsel_nutrition(p_staff_member_id uuid, p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.staff_members sm
    join public.user_profiles up
      on up.person_id = sm.person_id and up.organization_id = sm.organization_id and up.is_active
    join public.user_roles ur
      on ur.user_id = up.id and ur.organization_id = up.organization_id
    where sm.id = p_staff_member_id
      and sm.organization_id = p_organization_id
      and ur.role_key = 'owner'
  )
$$;

COMMENT ON FUNCTION app.staff_can_counsel_nutrition(p_staff_member_id uuid, p_organization_id uuid) IS 'ERN-011: Trägt die Person die Fähigkeit "Ernährungsberatung" (zunächst owner, wie app.can_counsel_nutrition)? Ändert sich die Fähigkeit, ändern sich beide Stellen.';

CREATE FUNCTION app.staff_color_palette() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array['tanne', 'ozean', 'pflaume', 'moos', 'veilchen', 'petrol', 'schiefer', 'nacht']
$$;

COMMENT ON FUNCTION app.staff_color_palette() IS 'TEAM-006 (ANN-666): die acht Farben für Personen im Teamchat in der Reihenfolge der Vergabe. Die einzige Stelle, an der die Schlüssel stehen; die Werte stehen in src/index.css (--color-person-*).';

CREATE FUNCTION app.staff_colors_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.staff_colors (staff_member_id, organization_id, color)
  values (new.id, new.organization_id, app.next_staff_color(new.organization_id, new.id))
  on conflict (staff_member_id) do nothing;
  return null;
end;
$$;

CREATE FUNCTION app.staff_display_name(p_staff_member_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select nullif(btrim(concat_ws(' ', p.given_name, p.family_name)), '')
  from public.staff_members sm
  join public.persons p on p.id = sm.person_id
  where sm.id = p_staff_member_id
$$;

CREATE FUNCTION app.staff_feedback_eligible_count(p_org uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(distinct sm.id)::integer
  from public.staff_members sm
  join public.user_profiles up
    on up.person_id = sm.person_id and up.organization_id = sm.organization_id and up.is_active
  where sm.organization_id = p_org
    and sm.employment_status = 'active'
    and exists (
      select 1 from public.user_roles ur
      where ur.user_id = up.id and ur.organization_id = p_org
        and ur.role_key in ('team_lead', 'office', 'therapist', 'trainer'))
    and not exists (
      select 1 from public.user_roles ur
      where ur.user_id = up.id and ur.organization_id = p_org and ur.role_key = 'owner')
$$;

COMMENT ON FUNCTION app.staff_feedback_eligible_count(p_org uuid) IS 'ORG-006 (§20.2 Nr. 4, ANN-607): Zahl der Beschäftigten, die teilnehmen können - aktiv, mit aktivem Konto und Praxisrolle, ohne owner. Liefert nie Personen.';

CREATE FUNCTION app.staff_feedback_giver(OUT o_org uuid, OUT o_staff uuid) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  o_org := app.staff_request_org(app.can_give_staff_feedback(), 'not allowed to give staff feedback');
  select sm.id into o_staff
  from public.staff_members sm
  where sm.id = app.own_staff_member(o_org) and sm.employment_status = 'active';
  if o_staff is null then
    raise exception 'not allowed to give staff feedback' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION app.staff_feedback_month(p_org uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select date_trunc('month', now() at time zone o.time_zone)::date
  from public.organizations o
  where o.id = p_org
$$;

CREATE FUNCTION app.staff_feedback_scale(p_values smallint[]) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when coalesce(array_length(p_values, 1), 0) < (app.staff_feedback_threshold()).o_answers
      then jsonb_build_object('enough', false)
    else jsonb_build_object(
      'enough', true,
      'answered', array_length(p_values, 1),
      'median', (select round(percentile_cont(0.5) within group (order by v)::numeric, 1)
                 from unnest(p_values) as v),
      'distribution', (select jsonb_agg((select count(*) from unnest(p_values) as v where v = s) order by s)
                       from generate_series(1, 9) as s)
    )
  end
$$;

CREATE FUNCTION app.staff_feedback_text(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := nullif(btrim(coalesce(p_text, '')), '');
begin
  if v_text is not null and length(v_text) > 2000 then
    raise exception 'text is too long' using errcode = '22023';
  end if;
  return v_text;
end;
$$;

CREATE FUNCTION app.staff_feedback_threshold(OUT o_answers integer, OUT o_eligible integer) RETURNS record
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 5, 3
$$;

CREATE FUNCTION app.staff_feedback_window(p_org uuid, p_kind text, OUT o_von date, OUT o_bis date, OUT o_antworten integer) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_monat   date := app.staff_feedback_month(p_org);
  v_letzter date := (v_monat - interval '1 month')::date;
  v_grenze  date := (v_monat - interval '12 months')::date;
  v_start   date;
  v_m       date;
  v_n       integer := 0;
  v_schwelle integer := (app.staff_feedback_threshold()).o_answers;
begin
  -- Zwei gleichzeitige Abrufe schließen einen Block nur einmal (N4).
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('staff_feedback_blocks:' || p_org || ':' || p_kind, 0));

  select (max(b.to_month) + interval '1 month')::date into v_start
  from public.staff_feedback_blocks b
  where b.organization_id = p_org and b.kind = p_kind;
  if v_start is null then
    select min(f.month) into v_start
    from public.staff_feedback f
    where f.organization_id = p_org and f.kind = p_kind and f.staff_member_id is null;
  end if;
  if v_start is not null then
    -- Höchstens zwölf Monate zurück: Ältere waren nie gezeigt.
    v_start := greatest(v_start, v_grenze);
    v_m := v_start;
    while v_m <= v_letzter loop
      v_n := v_n + (select count(*) from public.staff_feedback f
                    where f.organization_id = p_org and f.kind = p_kind
                      and f.staff_member_id is null and f.month = v_m);
      if v_n >= v_schwelle then
        insert into public.staff_feedback_blocks (organization_id, kind, from_month, to_month, answers)
        values (p_org, p_kind, v_start, v_m, v_n)
        on conflict (organization_id, kind, from_month) do nothing;
        v_start := (v_m + interval '1 month')::date;
        v_n := 0;
      end if;
      v_m := (v_m + interval '1 month')::date;
    end loop;
  end if;

  select b.from_month, b.to_month, b.answers into o_von, o_bis, o_antworten
  from public.staff_feedback_blocks b
  where b.organization_id = p_org and b.kind = p_kind and b.to_month >= v_grenze
  order by b.to_month desc
  limit 1;
end;
$$;

CREATE FUNCTION app.staff_profile_picture_on_leave() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_bild uuid;
begin
  select p.id into v_bild from public.staff_profile_pictures p where p.staff_member_id = new.id;
  if v_bild is not null then
    perform app.forget_profile_picture(new.organization_id, v_bild);
  end if;
  return null;
end;
$$;

CREATE FUNCTION app.staff_profile_pictures_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'profile pictures are immutable' using errcode = '42501';
end;
$$;

CREATE FUNCTION app.staff_reimbursement_receipts_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_veraenderlich text[] := array['status', 'confirmation_requested_at', 'confirmed_at',
                                  'verified_at', 'object_key', 'reimbursement_id',
                                  'amount_cents', 'purpose', 'attached_at'];
begin
  -- Was eine Datei ist, ändert sich nicht (ADR-017 Punkt 8): nur Zustand,
  -- Prüfung und - genau einmal - die Zuordnung zum Antrag mit Betrag und
  -- Zweck. Der Objektschlüssel ist generiert und im BEFORE-Trigger leer.
  if (to_jsonb(new) - v_veraenderlich) is distinct from (to_jsonb(old) - v_veraenderlich)
     or (old.reimbursement_id is not null
         and (new.reimbursement_id, new.amount_cents, new.purpose, new.attached_at)
             is distinct from (old.reimbursement_id, old.amount_cents, old.purpose, old.attached_at)) then
    raise exception 'reimbursement receipts are immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.staff_request_org(p_allowed boolean, p_message text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not coalesce(p_allowed, false) then
    raise exception '%', p_message using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception '%', p_message using errcode = '42501';
  end if;
  return v_org;
end;
$$;

COMMENT ON FUNCTION app.staff_request_org(p_allowed boolean, p_message text) IS 'URL-001: gemeinsamer Einstieg der Antragspfade - angemeldet, berechtigt, Organisation; sonst 42501. Liefert die Organisation.';

CREATE FUNCTION app.store_payout_account(p_org uuid, p_staff_member_id uuid, p_iban text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_iban text := upper(replace(btrim(coalesce(p_iban, '')), ' ', ''));
begin
  if not app.iban_checksum_ok(v_iban) then
    raise exception 'invalid iban' using errcode = '22023';
  end if;
  insert into public.staff_payout_accounts (organization_id, staff_member_id, iban, updated_by)
  values (p_org, p_staff_member_id, v_iban, auth.uid())
  on conflict (staff_member_id) do update
    set iban = excluded.iban, updated_by = excluded.updated_by, updated_at = now()
    where public.staff_payout_accounts.iban is distinct from excluded.iban;
end;
$$;

CREATE FUNCTION app.strip_due_team_anchors(p_org uuid, p_time_zone text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[];
begin
  select array_agg(m.id) into v_ids
  from public.team_messages m
  where m.organization_id = p_org and m.parent_id is null
    and (m.removed_kind is distinct from 'retention' or m.author_staff_member_id is not null)
    and app.retention_due_at((m.created_at at time zone p_time_zone)::date,
                             app.retention_interval('teamchat'), p_time_zone) <= now();
  if v_ids is null then
    return;
  end if;
  delete from public.team_message_mentions where message_id = any (v_ids);
  update public.team_messages
     set body = null, edited_at = null, author_staff_member_id = null,
         removed_at = coalesce(removed_at, now()), removed_kind = 'retention',
         removed_by_staff_member_id = null
   where id = any (v_ids);
end;
$$;

CREATE FUNCTION app.suchform(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select replace(
           replace(
             replace(
               replace(
                 translate(
                   lower(coalesce(p_text, '')),
                   'äöüàáâãåèéêëìíîïòóôõùúûýñç',
                   'aouaaaaaeeeeiiiioooouuuync'
                 ),
                 'ß', 'ss'
               ),
               'ae', 'a'
             ),
             'oe', 'o'
           ),
           'ue', 'u'
         )
$$;

COMMENT ON FUNCTION app.suchform(p_text text) IS 'Vergleichsform eines Namens fuer die Suche (UX-004): Kleinschreibung, Umlaute und Akzente auf Grundbuchstaben, ae/oe/ue/ss eingeebnet. Wird auf Name UND Suchbegriff angewendet.';

CREATE FUNCTION app.take_along_items_valid(p_items text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_items is not null
     and coalesce(array_length(p_items, 1), 0) <= 10
     and not exists (
       select 1 from unnest(p_items) as e(eintrag)
       where e.eintrag is null
          or e.eintrag <> btrim(e.eintrag)
          or char_length(e.eintrag) not between 1 and 60
     )
     and (select count(distinct lower(e.eintrag)) from unnest(p_items) as e(eintrag))
         = coalesce(array_length(p_items, 1), 0)
$$;

COMMENT ON FUNCTION app.take_along_items_valid(p_items text[]) IS 'PRX-007: Form der Mitnehmen-Liste - hoechstens zehn Eintraege zu 1 bis 60 Zeichen, ohne Rand, ohne Doppel (ANN-138).';

CREATE FUNCTION app.task_check_input(p_org uuid, p_patient_id uuid, p_assigned_staff_member_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Person und Mitarbeitende nur aus der eigenen Praxis: sonst truege eine
  -- Aufgabe einen fremden Namen.
  if p_patient_id is not null and not exists (
    select 1 from public.patients pa
    where pa.id = p_patient_id and pa.organization_id = p_org
  ) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  if p_assigned_staff_member_id is not null and not exists (
    select 1 from public.staff_members sm
    where sm.id = p_assigned_staff_member_id and sm.organization_id = p_org
  ) then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;
end;
$$;

CREATE FUNCTION app.tax_exemption_reason(p_tax_treatment text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_tax_treatment
           when 'exempt_healthcare'
             then 'Steuerfreie Heilbehandlung nach § 4 Nr. 14 Buchstabe a UStG'
           when 'not_taxable'
             then 'Nicht steuerbar, kein Leistungsaustausch (§ 1 Abs. 1 Nr. 1 UStG)'
           else null
         end;
$$;

COMMENT ON FUNCTION app.tax_exemption_reason(p_tax_treatment text) IS 'Der Grund der Steuerbefreiung als fester Text je Steuerkennzeichen (ABR-006, ADR-009 Punkt 18, Par. 14 Abs. 4 Nr. 8 UStG). ANN-082: fester Text statt Feld an der Katalogposition - er verhindert einen falschen Befreiungstatbestand, wo ein Feld verschiedene erlaubte. Liefert null fuer steuerpflichtige Posten.';

