    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 5
$$;

CREATE FUNCTION app.team_attachment_open_limit() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 20
$$;

CREATE FUNCTION app.team_channel_manageable(p_channel uuid, p_org uuid, p_staff uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.can_manage_team_channels() and exists (
    select 1 from public.team_channels c
    where c.id = p_channel and c.organization_id = p_org
      and (c.kind = 'channel'
           or (c.kind = 'private'
               and exists (select 1 from public.team_channel_members m
                           where m.channel_id = c.id and m.staff_member_id = p_staff)))
  )
$$;

CREATE FUNCTION app.team_channel_name(p_name text, p_description text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_text text := nullif(btrim(coalesce(p_description, '')), '');
begin
  if v_name is null or length(v_name) > 40 or (v_text is not null and length(v_text) > 200) then
    raise exception 'channel name needs one to 40 characters' using errcode = '22023';
  end if;
  return v_name;
end;
$$;

CREATE FUNCTION app.team_channel_read_up_to(p_channel uuid, p_staff uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select rs.read_up_to from public.team_read_states rs
                   where rs.channel_id = p_channel and rs.staff_member_id = p_staff),
                  '-infinity'::timestamptz)
$$;

CREATE FUNCTION app.team_channel_readable(p_channel uuid, p_org uuid, p_staff uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.team_channels c
    where c.id = p_channel and c.organization_id = p_org
      and (c.kind = 'channel'
           or (c.kind = 'fleet' and app.team_staff_reads_fleet(p_org, p_staff))
           -- Mitglieder zählen nur, wo es Mitglieder gibt (Zweitreview R3).
           or (c.kind in ('direct', 'group', 'private')
               and exists (select 1 from public.team_channel_members m
                           where m.channel_id = c.id and m.staff_member_id = p_staff)))
  )
$$;

CREATE FUNCTION app.team_channels_for_new_organization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform app.create_team_fleet_channel(new.id);
  return new;
end;
$$;

CREATE FUNCTION app.team_drop_scheduled(p_org uuid, p_channel uuid, p_staff uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[];
begin
  select coalesce(array_agg(m.id), '{}'::uuid[]) into v_ids
  from public.team_messages m
  where m.organization_id = p_org and m.created_at > now()
    and (p_channel is null or m.channel_id = p_channel)
    and (p_staff is null or m.author_staff_member_id = p_staff);
  if cardinality(v_ids) = 0 then
    return;
  end if;
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at, deleted_at)
  select p_org, md5('team_manual:' || p_org::text || ':' || current_date::text)::uuid,
         'team_messages', x.id, 'teamchat', date_trunc('day', now()), date_trunc('day', now())
  from unnest(v_ids) as x (id);
  delete from public.team_messages where id = any (v_ids);
end;
$$;

CREATE FUNCTION app.team_follow_thread(p_root uuid, p_staff uuid, p_seit timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.team_thread_states
    (organization_id, root_message_id, staff_member_id, following, read_up_to)
  select r.organization_id, r.id, p_staff, true, coalesce(p_seit, r.created_at)
  from public.team_messages r
  where r.id = p_root and r.parent_id is null
  on conflict (root_message_id, staff_member_id) do update set following = true
$$;

CREATE FUNCTION app.team_follows(p_root uuid, p_staff uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select ts.following from public.team_thread_states ts
                   where ts.root_message_id = p_root and ts.staff_member_id = p_staff), false)
$$;

CREATE FUNCTION app.team_forget_channel(p_channel uuid, p_staff uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.team_drop_scheduled(c.organization_id, p_channel, p_staff)
  from public.team_channels c where c.id = p_channel;
  delete from public.team_read_states where channel_id = p_channel and staff_member_id = p_staff;
  delete from public.team_thread_states ts
  using public.team_messages m
  where m.id = ts.root_message_id and m.channel_id = p_channel and ts.staff_member_id = p_staff;
  delete from public.team_channel_settings where channel_id = p_channel and staff_member_id = p_staff;
  delete from public.team_saved_messages s
  using public.team_messages m
  where m.id = s.message_id and m.channel_id = p_channel and s.staff_member_id = p_staff;
$$;

CREATE FUNCTION app.team_leave(p_org uuid, p_without uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'staff_member_id', r.staff_member_id,
           'name', app.staff_display_name(r.staff_member_id),
           'starts_on', r.starts_on,
           'ends_on', r.ends_on
         ) order by r.starts_on, r.ends_on), '[]'::jsonb)
  from public.staff_leave_requests r
  where r.organization_id = p_org
    and r.kind = 'leave'
    and r.status = 'approved'
    and r.staff_member_id is distinct from p_without
    and r.starts_on <= p_to and r.ends_on >= p_from
$$;

CREATE FUNCTION app.team_mark_channel_read(p_channel uuid, p_org uuid, p_staff uuid, p_up_to timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.team_read_states (organization_id, channel_id, staff_member_id, read_up_to)
  select p_org, p_channel, p_staff, max(m.created_at)
  from public.team_messages m
  where m.channel_id = p_channel and (m.parent_id is null or m.also_in_channel)
    and m.created_at <= now()
    and m.created_at <= coalesce(p_up_to, 'infinity'::timestamptz)
  having max(m.created_at) is not null
  on conflict (channel_id, staff_member_id)
  do update set read_up_to = greatest(public.team_read_states.read_up_to, excluded.read_up_to)
$$;

CREATE FUNCTION app.team_mark_thread_read(p_root uuid, p_staff uuid, p_up_to timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.team_thread_states ts
     set read_up_to = greatest(ts.read_up_to, x.bis)
  from (select max(m.created_at) as bis
        from public.team_messages m
        where (m.id = p_root or m.parent_id = p_root) and m.created_at <= now()
          and m.created_at <= coalesce(p_up_to, 'infinity'::timestamptz)) x
  where ts.root_message_id = p_root and ts.staff_member_id = p_staff and x.bis is not null
$$;

CREATE FUNCTION app.team_message_attachments_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_veraenderlich text[] := array['status', 'confirmation_requested_at', 'confirmed_at',
                                  'verified_at', 'object_key', 'message_id', 'position',
                                  'attached_at', 'staff_member_id'];
begin
  -- Was eine Datei ist, ändert sich nicht (ADR-017 Punkt 8): nur Zustand,
  -- Prüfung und - genau einmal - die Bindung an die Nachricht. Die Person
  -- fällt nur über `on delete set null`. Der Objektschlüssel ist generiert
  -- und im BEFORE-Trigger leer.
  if (to_jsonb(new) - v_veraenderlich) is distinct from (to_jsonb(old) - v_veraenderlich)
     or (new.staff_member_id is not null
         and new.staff_member_id is distinct from old.staff_member_id)
     or (old.message_id is not null
         and (new.message_id, new.position, new.attached_at)
             is distinct from (old.message_id, old.position, old.attached_at)) then
    raise exception 'team attachments are immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.team_message_body(p_text text, p_with_attachments boolean) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := btrim(coalesce(p_text, ''));
begin
  if v_text = '' and not coalesce(p_with_attachments, false) then
    raise exception 'message is empty' using errcode = '22023';
  end if;
  if length(v_text) > 4000 then
    raise exception 'message is too long' using errcode = '22023';
  end if;
  return v_text;
end;
$$;

CREATE FUNCTION app.team_message_content_removed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.team_message_mentions where message_id = new.id;
  delete from public.team_message_reactions where message_id = new.id;
  delete from public.team_message_pins where message_id = new.id;
  delete from public.team_saved_messages where message_id = new.id;
  delete from public.team_message_attachments where message_id = new.id;
  return null;
end;
$$;

CREATE FUNCTION app.team_message_key(p_staff uuid, p_device uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select encode(substring(sha256(convert_to(p_staff::text || ':' || p_device::text, 'UTF8'))
                          from 1 for 16), 'hex')::uuid
$$;

CREATE FUNCTION app.team_message_text(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := nullif(btrim(coalesce(p_text, '')), '');
begin
  if v_text is null then
    raise exception 'message is empty' using errcode = '22023';
  end if;
  if length(v_text) > 4000 then
    raise exception 'message is too long' using errcode = '22023';
  end if;
  return v_text;
end;
$$;

CREATE TABLE public.team_messages (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    parent_id uuid,
    author_staff_member_id uuid,
    body text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    edited_at timestamp with time zone,
    removed_at timestamp with time zone,
    removed_kind text,
    removed_by_staff_member_id uuid,
    also_in_channel boolean DEFAULT false NOT NULL,
    CONSTRAINT team_messages_also_in_channel CHECK (((NOT also_in_channel) OR (parent_id IS NOT NULL))),
    CONSTRAINT team_messages_body_check CHECK (((body IS NULL) OR (length(body) <= 4000))),
    CONSTRAINT team_messages_removed CHECK ((((removed_at IS NULL) = (removed_kind IS NULL)) AND ((removed_at IS NULL) = (body IS NOT NULL)) AND ((removed_kind = 'owner'::text) OR (removed_by_staff_member_id IS NULL)) AND ((removed_kind IS NOT NULL) OR (edited_at IS NULL) OR (edited_at >= created_at)))),
    CONSTRAINT team_messages_removed_kind_check CHECK ((removed_kind = ANY (ARRAY['author'::text, 'owner'::text, 'retention'::text])))
);

COMMENT ON TABLE public.team_messages IS 'TEAM-001, TEAM-003: Nachrichten des Teamchats. Zwölf Monate ab ihrem Tag, dann endgültig gelöscht (ANN-610). Anhänge in team_message_attachments (ADR-017 Abschnitt M); keine klinischen Inhalte (§10: die gehören in die Akte).';

COMMENT ON COLUMN public.team_messages.body IS 'Text der Nachricht, höchstens 4000 Zeichen. Leer nur, wenn Anhänge daran hängen (TEAM-003); null, wenn der Inhalt fehlt (removed_at).';

COMMENT ON COLUMN public.team_messages.created_at IS 'Zeitpunkt der Nachricht. Liegt er in der Zukunft, ist sie geplant (ANN-643): Bis dahin sieht sie nur die Person, die sie verfasst hat, unter „Geplant“; danach steht sie im Gespräch wie jede andere.';

COMMENT ON COLUMN public.team_messages.edited_at IS 'Zuletzt bearbeitet - nur für die Marke „bearbeitet“, kein Verlauf früherer Fassungen (ANN-609).';

COMMENT ON COLUMN public.team_messages.removed_kind IS 'Warum der Inhalt fehlt: author (selbst gelöscht, Antworten hängen daran), owner (von der Praxisleitung entfernt), retention (Frist abgelaufen, Antworten laufen noch).';

COMMENT ON COLUMN public.team_messages.removed_by_staff_member_id IS 'Nur bei removed_kind owner: wer entfernt hat - das Datenmodell ist der Nachweis, kein Auditeintrag (ADR-010 Punkt 15).';

COMMENT ON COLUMN public.team_messages.also_in_channel IS 'TEAM-002 (ANN-643): eine Antwort, die zusätzlich im Gespräch steht (wie Slack „auch an den Kanal senden“).';

CREATE FUNCTION app.team_readable_message(p_message uuid, p_org uuid, p_staff uuid) RETURNS public.team_messages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.*
  from public.team_messages m
  where m.id = p_message and m.organization_id = p_org and m.removed_at is null
    and m.created_at <= now()
    and app.team_channel_readable(m.channel_id, p_org, p_staff)
$$;

CREATE FUNCTION app.team_staff_name(p_staff uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.given_name || ' ' || p.family_name
  from public.staff_members sm
  join public.persons p on p.id = sm.person_id
  where sm.id = p_staff
$$;

CREATE FUNCTION app.team_staff_reads_fleet(p_org uuid, p_staff uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.staff_members sm
    join public.user_profiles up
      on up.person_id = sm.person_id and up.organization_id = sm.organization_id and up.is_active
    join public.user_roles ur
      on ur.user_id = up.id and ur.organization_id = sm.organization_id
     and ur.role_key in ('owner', 'therapist', 'team_lead', 'office')
    where sm.id = p_staff and sm.organization_id = p_org and sm.employment_status = 'active'
  )
$$;

CREATE FUNCTION app.team_unread(p_channel uuid, p_parent uuid, p_broadcast boolean, p_created timestamp with time zone, p_author uuid, p_removed timestamp with time zone, p_staff uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_removed is null and p_created <= now()
     and p_author is distinct from p_staff
     and case
           when p_parent is null then p_created > app.team_channel_read_up_to(p_channel, p_staff)
           when p_broadcast then
             p_created > greatest(
               app.team_channel_read_up_to(p_channel, p_staff),
               coalesce((select ts.read_up_to from public.team_thread_states ts
                         where ts.root_message_id = p_parent and ts.staff_member_id = p_staff
                           and ts.following),
                        '-infinity'::timestamptz))
           else coalesce((select ts.following and p_created > ts.read_up_to
                          from public.team_thread_states ts
                          where ts.root_message_id = p_parent and ts.staff_member_id = p_staff),
                         false)
         end
$$;

CREATE FUNCTION app.team_view(p_channel uuid, p_parent uuid) RETURNS SETOF public.team_messages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.*
  from public.team_messages x
  where x.channel_id = p_channel and x.created_at <= now()
    and case when p_parent is null then x.parent_id is null or x.also_in_channel
             else x.parent_id = p_parent end
$$;

CREATE FUNCTION app.teamchat_member(OUT o_org uuid, OUT o_staff uuid) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  o_org := app.staff_request_org(app.can_use_teamchat(), 'not allowed to use the team chat');
  select sm.id into o_staff
  from public.staff_members sm
  where sm.id = app.own_staff_member(o_org) and sm.employment_status = 'active';
  if o_staff is null then
    raise exception 'not allowed to use the team chat' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION app.teamchat_participant(p_org uuid, p_staff uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.staff_members sm
    join public.user_profiles up
      on up.person_id = sm.person_id and up.organization_id = sm.organization_id and up.is_active
    join public.user_roles ur
      on ur.user_id = up.id and ur.organization_id = sm.organization_id
     and ur.role_key in ('owner', 'therapist', 'team_lead', 'office', 'trainer')
    where sm.id = p_staff and sm.organization_id = p_org and sm.employment_status = 'active'
  )
$$;

CREATE FUNCTION app.territory_day_parts_valid(p_parts jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_teil jsonb;
  v_tag  numeric;
begin
  if p_parts is null or jsonb_typeof(p_parts) <> 'array' then
    return false;
  end if;
  if jsonb_array_length(p_parts) > 21 then
    return false;
  end if;
  for v_teil in select value from jsonb_array_elements(p_parts)
  loop
    if jsonb_typeof(v_teil) <> 'object'
       or (select count(*) from jsonb_object_keys(v_teil)) <> 2
       or jsonb_typeof(v_teil -> 'weekday') <> 'number'
       or jsonb_typeof(v_teil -> 'part') <> 'string'
       or (v_teil ->> 'part') not in ('am', 'pm', 'day') then
      return false;
    end if;
    v_tag := (v_teil ->> 'weekday')::numeric;
    if v_tag <> trunc(v_tag) or v_tag not between 1 and 7 then
      return false;
    end if;
  end loop;
  return true;
end;
$$;

COMMENT ON FUNCTION app.territory_day_parts_valid(p_parts jsonb) IS 'Prueft die Tage eines Gebiets: Liste von hoechstens 21 Objekten {weekday 1-7 ISO, part am|pm|day} (PRX-002).';

CREATE FUNCTION app.territory_day_status(p_org uuid, p_postal_code text, p_date date, p_start time without time zone) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with gebiet as (
    select t.day_parts
    from public.territory_postal_codes pc
    join public.territories t on t.id = pc.territory_id
    where pc.organization_id = p_org
      and pc.postal_code = btrim(coalesce(p_postal_code, ''))
  )
  select case
    when not exists (select 1 from gebiet)
      or (select jsonb_array_length(day_parts) from gebiet) = 0 then 'none'
    when exists (
      select 1
      from gebiet g, jsonb_array_elements(g.day_parts) teil
      where (teil ->> 'weekday')::int = extract(isodow from p_date)::int
        and (
          teil ->> 'part' = 'day'
          or (teil ->> 'part' = 'am' and p_start < time '12:00')
          or (teil ->> 'part' = 'pm' and p_start >= time '12:00')
        )
    ) then 'match'
    else 'outside'
  end
$$;

COMMENT ON FUNCTION app.territory_day_status(p_org uuid, p_postal_code text, p_date date, p_start time without time zone) IS 'Gebietstag-Regel (PRX-002, ANN-135): none, match oder outside fuer Postleitzahl, Tag und Beginn in Praxiszeit. Einzige Stelle der Regel; Formulare und Terminsuche rufen sie.';

CREATE FUNCTION app.therapy_report_dokument(p_report_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  b     public.therapy_reports%rowtype;
  v_tz  text;
begin
  select * into b from public.therapy_reports where id = p_report_id;
  if not found then
    return null;
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = b.organization_id;

  return jsonb_build_object(
    'schema_version', 1,

    -- ANN-123: Anschrift ohne Steuer- und Bankangaben.
    'praxis', coalesce(
      (select jsonb_build_object(
         'name', pb.legal_name,
         'street', pb.street,
         'house_number', pb.house_number,
         'postal_code', pb.postal_code,
         'city', pb.city,
         'phone', pb.phone,
         'email', pb.email)
       from public.practice_billing_profiles pb
       where pb.organization_id = b.organization_id),
      (select jsonb_build_object('name', o.name)
       from public.organizations o where o.id = b.organization_id)
    ),

    'empfaenger', (
      select jsonb_build_object(
        'title', vo.title,
        'given_name', vo.given_name,
        'family_name', vo.family_name,
        'practice_name', vo.practice_name,
        'street', vo.street,
        'house_number', vo.house_number,
        'postal_code', vo.postal_code,
        'city', vo.city,
        'fax', vo.fax)
      from public.treatment_bases g
      join public.prescribers vo on vo.id = g.prescriber_id
      where g.id = b.treatment_basis_id
    ),

    'patient', (
      select jsonb_build_object(
        'given_name', pe.given_name,
        'family_name', pe.family_name,
        'date_of_birth', (
          select k.date_of_birth from public.patient_contact_details k
          where k.patient_id = pa.id
        ))
      from public.patients pa
      join public.persons pe on pe.id = pa.person_id
      where pa.id = b.patient_id
    ),

    'verordnung', (
      select jsonb_build_object(
        'treatment_basis_kind', g.treatment_basis_kind,
        'issued_on', g.issued_on,
        'diagnosis', g.diagnosis,
        'items', coalesce((
          select jsonb_agg(jsonb_build_object(
            'remedy', i.remedy,
            'prescribed_quantity', i.prescribed_quantity
          ) order by i.sort_order)
          from public.treatment_base_items i
          where i.treatment_basis_id = g.id
        ), '[]'::jsonb),
        -- Gezaehlt, nicht bewertet: stattgefundene Termine dieser Verordnung.
        'termine_durchgefuehrt', (
          select count(*) from public.appointments t
          where t.treatment_basis_id = g.id
            and t.status in ('completed', 'documented', 'invoiced')
        ),
        'erster_termin', (
          select min((t.starts_at at time zone v_tz)::date) from public.appointments t
          where t.treatment_basis_id = g.id
            and t.status in ('completed', 'documented', 'invoiced')
        ),
        'letzter_termin', (
          select max((t.starts_at at time zone v_tz)::date) from public.appointments t
          where t.treatment_basis_id = g.id
            and t.status in ('completed', 'documented', 'invoiced')
        ))
      from public.treatment_bases g
      where g.id = b.treatment_basis_id
    ),

    -- Woertlich, in der Reihenfolge der Termine.
    'eintraege', coalesce((
      select jsonb_agg(jsonb_build_object(
        'note_id', d.id,
        'datum', (t.starts_at at time zone v_tz)::date,
        'verfasser', (select up.display_name from public.user_profiles up where up.id = d.created_by),
        'inhalt', d.content,
        'ergaenzung', d.addendum_to_note_id is not null
      ) order by t.starts_at, d.created_at)
      from public.treatment_notes d
      join public.appointments t on t.id = d.appointment_id
      where d.id = any (b.note_ids)
        and t.patient_id = b.patient_id
    ), '[]'::jsonb),

    'koerperschema', (
      select jsonb_build_object(
        'erhoben_am', qr.recorded_on,
        'markierungen', (
          select coalesce(jsonb_agg(m.markierung), '[]'::jsonb)
          from jsonb_each(qr.answers) as a(kennung, antwort),
               jsonb_array_elements(
                 case when jsonb_typeof(a.antwort -> 'markierungen') = 'array'
                      then a.antwort -> 'markierungen' else '[]'::jsonb end
               ) as m(markierung)
        ))
      from public.patient_questionnaire_responses qr
      where qr.id = b.body_chart_response_id
    ),

    'text', case when b.report_text is null then null else jsonb_build_object(
      'inhalt', b.report_text,
      'verfasser', (select up.display_name from public.user_profiles up where up.id = b.report_text_updated_by),
      'datum', (b.report_text_updated_at at time zone v_tz)::date
    ) end,

    'empfehlung', case when b.recommendation is null then null else jsonb_build_object(
      'inhalt', b.recommendation,
      'verfasser', (select up.display_name from public.user_profiles up where up.id = b.recommendation_updated_by),
      'datum', (b.recommendation_updated_at at time zone v_tz)::date
    ) end,

    -- ABN-016 (BEF-104): Eine Korrektur nennt den ersetzten Bericht, ihren
    -- Grund, wann und von wem.
    'korrektur', case when b.supersedes_report_id is null then null else jsonb_build_object(
      'ersetzt_bericht', b.supersedes_report_id,
      'ersetzt_abgeschlossen_am', (
        select (alt.completed_at at time zone v_tz)::date
        from public.therapy_reports alt where alt.id = b.supersedes_report_id),
      'grund', b.change_reason,
      'verfasser', (select up.display_name from public.user_profiles up where up.id = b.created_by),
      'datum', (b.created_at at time zone v_tz)::date
    ) end
  );
end;
$$;

CREATE FUNCTION app.therapy_report_pruefen(p_org uuid, p_patient_id uuid, p_note_ids uuid[], p_response uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if cardinality(p_note_ids) > 50 then
    raise exception 'too many entries' using errcode = '22023';
  end if;

  if exists (
    select 1 from unnest(p_note_ids) as gewaehlt(id)
    where not exists (
      select 1
      from public.treatment_notes d
      join public.appointments t on t.id = d.appointment_id
      where d.id = gewaehlt.id
        and d.status = 'final'
        and t.patient_id = p_patient_id
        and t.organization_id = p_org
    )
  ) then
    raise exception 'entry not usable for this report' using errcode = '22023';
  end if;

  if p_response is not null and not exists (
    select 1
    from public.patient_questionnaire_responses qr
    where qr.id = p_response
      and qr.patient_id = p_patient_id
      and qr.organization_id = p_org
      and qr.status = 'abgeschlossen'
      and not exists (
        select 1 from public.patient_questionnaire_responses neu
        where neu.supersedes_response_id = qr.id and neu.status = 'abgeschlossen'
      )
      and exists (
        select 1 from jsonb_each(qr.answers) as a(kennung, antwort)
        where jsonb_typeof(a.antwort) = 'object' and a.antwort ? 'markierungen'
      )
  ) then
    raise exception 'body chart not usable for this report' using errcode = '22023';
  end if;
end;
$$;

CREATE FUNCTION app.therapy_report_unveraenderlich() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status = 'abgeschlossen' then
    if app.patient_merge_active()
       and app.only_patient_id_changed(to_jsonb(new), to_jsonb(old)) then
      return new;
    end if;
    raise exception 'therapy report is completed and cannot be changed' using errcode = '55000';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.time_account_balance(p_org uuid, p_staff_member_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(sum(e.minutes), 0)::integer
  from public.staff_time_account_entries e
  where e.organization_id = p_org and e.staff_member_id = p_staff_member_id and e.status = 'valid'
$$;

CREATE FUNCTION app.time_account_check(p_org uuid, p_staff_member_id uuid, p_kind text, p_on_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_minutes integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_heute    date;
  v_tag      jsonb;
  v_plan     app.timemultirange;
  v_bereich  app.timerange;
  v_innen    app.timemultirange;
  v_probleme text[] := '{}';
  v_minuten  integer;
  v_rest     jsonb := '[]'::jsonb;
  v_termine  integer := 0;
begin
  if p_kind is null or p_kind not in ('overtime', 'time_off', 'correction') then
    raise exception 'kind must be overtime, time_off or correction' using errcode = '22023';
  end if;
  if p_on_date is null then
    raise exception 'date is required' using errcode = '22023';
  end if;
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = p_org;

  -- Außerhalb des Fensters gibt es keinen Tag (Zweitreview B1): Sonst ließe
  -- sich über die Vorschau jedes Datum einer Person abfragen.
  if (p_kind = 'overtime' and (p_on_date < v_heute - 31 or p_on_date > v_heute))
     or (p_kind = 'time_off' and (p_on_date < v_heute - 31 or p_on_date > v_heute + 365))
     or (p_kind = 'correction' and (p_on_date < v_heute - 366 or p_on_date > v_heute)) then
    return jsonb_build_object('day', null, 'minutes', null, 'problems', jsonb_build_array('date_out_of_range'),
                              'remaining', v_rest, 'appointments', v_termine);
  end if;

  -- Minusstunden ohne Lage und ohne Tag; ihren Grund verlangt das Eintragen.
  if p_kind = 'correction' then
    if p_minutes is not null then
      -- Nur abziehen (ANN-606): Plus-Zeit geht als Überstunden mit Lage.
      if p_minutes not between -60000 and -1 then
        v_probleme := array_append(v_probleme, 'correction_invalid');
      else
        v_minuten := p_minutes;
      end if;
    end if;
    return jsonb_build_object('day', null, 'minutes', v_minuten, 'problems', to_jsonb(v_probleme),
                              'remaining', v_rest, 'appointments', v_termine);
  end if;

  v_tag := app.effective_day(p_org, p_staff_member_id, p_on_date);

  select range_agg(app.timerange((b ->> 'von')::time, (b ->> 'bis')::time, '[)'))
    into v_plan
  from jsonb_array_elements(coalesce(v_tag -> 'blocks', '[]'::jsonb)) as b;

  if p_kind = 'time_off' then
    if v_tag ->> 'kind' = 'leave' then
      v_probleme := array_append(v_probleme, 'leave');
    elsif v_tag ->> 'kind' = 'unavailable' then
      v_probleme := array_append(v_probleme, 'absent');
    elsif v_tag ->> 'kind' = 'exception' then
      v_probleme := array_append(v_probleme, 'changed_day');
    elsif v_plan is null then
      v_probleme := array_append(v_probleme, 'no_working_time');
    end if;
  end if;

  -- Ohne Zeiten: nur der Tag.
  if p_starts_at is null and p_ends_at is null then
    return jsonb_build_object('day', v_tag, 'minutes', null, 'problems', to_jsonb(v_probleme),
                              'remaining', v_rest, 'appointments', v_termine);
  end if;

  if p_starts_at is null or p_ends_at is null or p_starts_at >= p_ends_at
     or date_trunc('minute', p_starts_at::interval) <> p_starts_at::interval
     or date_trunc('minute', p_ends_at::interval) <> p_ends_at::interval then
    v_probleme := array_append(v_probleme, 'times_invalid');
    return jsonb_build_object('day', v_tag, 'minutes', null, 'problems', to_jsonb(v_probleme),
                              'remaining', v_rest, 'appointments', v_termine);
  end if;

  v_bereich := app.timerange(p_starts_at, p_ends_at, '[)');

  if p_kind = 'overtime' then
    -- Mehrarbeit liegt außerhalb der Arbeitszeit des Tages, sonst zählte sie
    -- doppelt; an einem freien Tag zählt sie ganz.
    if v_plan is not null and v_plan && v_bereich then
      v_probleme := array_append(v_probleme, 'overlaps_working_hours');
    end if;
    v_minuten := (extract(epoch from (p_ends_at - p_starts_at)) / 60)::integer;
  elsif v_plan is not null and v_tag ->> 'kind' = 'plan' then
    -- Freizeitausgleich: innerhalb der Spanne des Tages, gezählt wird die
    -- Arbeitszeit darin (eine Pause zählt nicht). Es bleiben die übrigen Blöcke.
    v_innen := v_plan * app.timemultirange(v_bereich);
    if isempty(v_innen) or not (app.timerange(lower(v_plan), upper(v_plan), '[)') @> v_bereich) then
      v_probleme := array_append(v_probleme, 'outside_working_hours');
    else
      select -sum(extract(epoch from (upper(r) - lower(r))) / 60)::integer
        into v_minuten
      from unnest(v_innen) as r;
      select coalesce(jsonb_agg(jsonb_build_object('von', to_char(lower(r), 'HH24:MI'),
                                                   'bis', to_char(upper(r), 'HH24:MI'))
                                order by lower(r)), '[]'::jsonb)
        into v_rest
      from unnest(v_plan - app.timemultirange(v_bereich)) as r;
    end if;
    -- Die bestätigten Termine in der freien Zeit - genannt, nie verschoben.
    select count(*)::integer into v_termine
    from public.appointments a
    join public.organizations o on o.id = a.organization_id
    where a.organization_id = p_org
      and a.staff_member_id = p_staff_member_id
      and a.status = 'confirmed'
      and a.starts_at < ((p_on_date + p_ends_at)::timestamp at time zone o.time_zone)
      and a.ends_at > ((p_on_date + p_starts_at)::timestamp at time zone o.time_zone);
  end if;

  if exists (
    select 1 from public.staff_time_account_entries e
    where e.organization_id = p_org and e.staff_member_id = p_staff_member_id
      and e.on_date = p_on_date and e.status = 'valid' and e.kind in ('overtime', 'time_off')
      and app.timerange(e.starts_at, e.ends_at, '[)') && v_bereich
  ) then
    v_probleme := array_append(v_probleme, 'overlaps_entry');
  end if;

  return jsonb_build_object('day', v_tag, 'minutes', v_minuten, 'problems', to_jsonb(v_probleme),
                            'remaining', v_rest, 'appointments', v_termine);
end;
$$;

CREATE FUNCTION app.time_account_foreign_view(p_check jsonb, p_org uuid, p_on_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sicht jsonb := p_check;
  v_heute date;
begin
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = p_org;
  if not app.can_read_staff_leave_balances() then
    if v_sicht -> 'day' ->> 'kind' = 'leave' then
      v_sicht := jsonb_set(v_sicht, '{day,kind}', to_jsonb('unavailable'::text));
    end if;
    v_sicht := jsonb_set(v_sicht, '{problems}', (
      select coalesce(jsonb_agg(case when p.wert = 'leave' then 'absent' else p.wert end order by p.n),
                      '[]'::jsonb)
      from jsonb_array_elements_text(v_sicht -> 'problems') with ordinality as p (wert, n)
    ));
  end if;
  if p_on_date < v_heute and jsonb_typeof(v_sicht -> 'day') = 'object' then
    v_sicht := jsonb_set(v_sicht, '{day,blocks}', 'null'::jsonb);
    v_sicht := jsonb_set(v_sicht, '{remaining}', '[]'::jsonb);
  end if;
  return v_sicht;
end;
$$;

CREATE FUNCTION app.time_account_target(p_org uuid, p_staff_member_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eigen uuid := app.own_staff_member(p_org);
begin
  if p_staff_member_id is null or p_staff_member_id = v_eigen then
    if v_eigen is null then
      raise exception 'no staff member for this account' using errcode = '22023';
    end if;
    return v_eigen;
  end if;
  if not app.can_book_time_accounts() or not exists (
    select 1 from public.staff_members sm
    where sm.id = p_staff_member_id and sm.organization_id = p_org
  ) then
    raise exception 'time account not found' using errcode = 'P0002';
  end if;
  return p_staff_member_id;
end;
$$;

CREATE FUNCTION app.time_off_on_changed_weekdays(p_org uuid, p_staff_member_id uuid, p_on_date date, p_blocks jsonb, p_previous jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.staff_time_account_entries e
    where e.organization_id = p_org and e.staff_member_id = p_staff_member_id
      and e.kind = 'time_off' and e.status = 'valid' and e.on_date >= p_on_date
      and p_blocks -> extract(isodow from e.on_date)::text
          is distinct from p_previous -> extract(isodow from e.on_date)::text
  )
$$;

CREATE FUNCTION app.time_off_started(p_on_date date, p_starts_at time without time zone, p_time_zone text, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select ((p_on_date + p_starts_at) at time zone p_time_zone) <= p_at
$$;

COMMENT ON FUNCTION app.time_off_started(p_on_date date, p_starts_at time without time zone, p_time_zone text, p_at timestamp with time zone) IS 'BEF-180 (ANN-594): ob die freie Zeit eines Freizeitausgleichs zum Zeitpunkt begonnen hat - Tag und Beginn in Ortszeit der Praxis. Bis dahin lässt er sich zurücknehmen, auch am Tag selbst.';

CREATE FUNCTION app.tracking_parameters() RETURNS TABLE(parameter_key text, cadence text, min_value integer, max_value integer, sort_order integer, role text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select * from (values
    ('session_exertion',          'session', 0, 10,  1, 'question'),
    ('session_pain',              'session', 0, 10,  2, 'question'),
    ('session_confidence',        'session', 0, 10,  3, 'question'),
    ('pain_rest',                 'checkin', 0, 10,  1, 'question'),
    ('pain_load',                 'checkin', 0, 10,  2, 'question'),
    ('pain_after_load',           'checkin', 0, 10,  3, 'question'),
    ('pain_night',                'checkin', 0, 10,  4, 'question'),
    ('pain_morning',              'checkin', 0, 10,  5, 'question'),
    ('pain_recovery_hours',       'checkin', 0, 72,  6, 'question'),
    ('pain_quality',              'checkin', 1, 5,   7, 'question'),
    -- ALT-001: an wie vielen der letzten 7 Tage Schmerzmittel bei Bedarf
    -- (IDEA-ALT-004, ANN-368).
    ('painkiller_days_7d',        'checkin', 0, 7,   8, 'question'),
    ('movement_confidence',       'checkin', 0, 10,  9, 'question'),
    ('daily_impairment',          'checkin', 0, 10, 10, 'question'),
    ('sleep_quality',             'checkin', 0, 10, 11, 'question'),
    -- ALT-001: Schlafdauer der letzten Nacht in ganzen Stunden (IDEA-ALT-003,
    -- ANN-368).
    ('sleep_hours',               'checkin', 0, 16, 12, 'question'),
    ('stress',                    'checkin', 0, 10, 13, 'question'),
    ('morning_stiffness_minutes', 'checkin', 0, 240, 14, 'question'),
    ('painkiller_24h',            'checkin', 0, 1,  15, 'context'),
    ('pain_side',                 'checkin', 1, 4,  16, 'context'),
    -- ALT-002: die groesste Belastung ausserhalb der Uebungen seit dem
    -- letzten Check-in (IDEA-ALT-001, ANN-369). Art: 1 nichts Besonderes,
    -- 2 Gehen oder Wandern, 3 Radfahren, 4 Garten oder Haushalt, 5 Sport,
    -- 6 schwere koerperliche Arbeit, 7 Sonstiges. Dauer in Minuten.
    -- Anstrengung: 1 leicht, 2 mittel, 3 anstrengend.
    ('activity_kind',             'checkin', 1, 7,  17, 'context'),
    ('activity_minutes',          'checkin', 0, 600, 18, 'context'),
    ('activity_intensity',        'checkin', 1, 3,  19, 'context')
  ) as t (parameter_key, cadence, min_value, max_value, sort_order, role)
$$;

COMMENT ON FUNCTION app.tracking_parameters() IS 'TRK-001, TRK-004, TRK-005, ALT-001, ALT-002 (ANN-348, ANN-353 bis ANN-355, ANN-368, ANN-369): Katalog der Erfassungsgroessen nach Takt (IDEA-TRK-001) - Schluessel, Takt, Wertebereich, Reihenfolge und Rolle (Frage oder Zusammenhang). Die eine Stelle; Beschriftungen und die Woerter einer Auswahl in src/lib/erfassungsgroessen.ts. Keine Schwelle, keine Bewertung (ADR-006 Punkt 11).';

CREATE FUNCTION app.tracking_value_valid(p_key text, p_cadence text, p_value integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce((
    select p_value between t.min_value and t.max_value
    from app.tracking_parameters() t
    where t.parameter_key = p_key and t.cadence = p_cadence
  ), false)
$$;

COMMENT ON FUNCTION app.tracking_value_valid(p_key text, p_cadence text, p_value integer) IS 'TRK-001: ob ein Wert zu einer Erfassungsgroesse dieses Takts und in ihrem Bereich liegt.';

CREATE FUNCTION app.tracking_values_from_json(p_values jsonb, p_cadence text) RETURNS TABLE(parameter_key text, value smallint)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_key  text;
  v_wert jsonb;
  v_zahl numeric;
begin
  if p_values is null or p_values = 'null'::jsonb then
    return;
  end if;
  if jsonb_typeof(p_values) <> 'object' then
    raise exception 'values must be an object' using errcode = '22023';
  end if;
  for v_key, v_wert in select * from jsonb_each(p_values) loop
    -- null heisst: nicht beantwortet (IDEA-TRK-002, fehlend ist ehrlich).
    continue when jsonb_typeof(v_wert) = 'null';
    -- Schritt fuer Schritt, weil SQL ein OR nicht der Reihe nach auswertet:
    -- Eine riesige Zahl ist ein falscher Wert (22023), kein Ueberlauf
    -- (Zweitreview H1).
    if jsonb_typeof(v_wert) <> 'number' then
      raise exception 'invalid value for %', v_key using errcode = '22023';
    end if;
    v_zahl := (v_wert #>> '{}')::numeric;
    if v_zahl <> trunc(v_zahl) or v_zahl not between -32768 and 32767 then
      raise exception 'invalid value for %', v_key using errcode = '22023';
    end if;
    if not app.tracking_value_valid(v_key, p_cadence, v_zahl::integer) then
      raise exception 'invalid value for %', v_key using errcode = '22023';
    end if;
    parameter_key := v_key;
    value := v_zahl::smallint;
    return next;
  end loop;
end;
$$;

CREATE FUNCTION app.training_billing_retention_due_at(p_relationship_id uuid, p_time_zone text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select max(app.retention_due_at(
           (date_trunc('year', t.beleg_am) + interval '1 year' - interval '1 day')::date,
           app.retention_interval('abrechnungsdaten'),
           p_time_zone
         ))
  from (
    select i.issued_on as beleg_am
    from public.invoices i
    where i.training_relationship_id = p_relationship_id
      and i.status = 'issued'

    union all

    select c.cancelled_on
    from public.invoice_cancellations c
    join public.invoices i on i.id = c.invoice_id
    where i.training_relationship_id = p_relationship_id

    union all

    select r.reminder_on
    from public.invoice_payment_reminders r
    join public.invoices i on i.id = r.invoice_id
    where i.training_relationship_id = p_relationship_id

    union all

    select p.paid_on
    from public.payments p
    join public.invoices i on i.id = p.invoice_id
    where i.training_relationship_id = p_relationship_id
  ) t
$$;

COMMENT ON FUNCTION app.training_billing_retention_due_at(p_relationship_id uuid, p_time_zone text) IS 'Ende der steuerlichen Frist der Belege eines Trainingsverhaeltnisses (TRN-008, ANN-183): Rechnung, Storno, Erinnerung, Zahlung - acht Jahre ab Ende des Kalenderjahres (Par. 147 Abs. 3 AO). Gegenstueck zu app.billing_retention_due_at an der Akte. null, wenn es keinen Beleg gibt.';

CREATE FUNCTION app.training_contract_start_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.contract_started_on is not null and exists (
    select 1 from public.training_packages k
    where k.training_relationship_id = new.id and k.starts_on < new.contract_started_on
  ) then
    raise exception 'a training package starts before the contract start' using errcode = '22023';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.training_contract_start_guard() IS 'ANG-006 (Zweitreview): Der Vertragsbeginn eines Trainingsverhaeltnisses liegt nie nach dem Beginn eines seiner Pakete.';

-- ANN-291
CREATE FUNCTION app.training_contract_wording_version() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Muss deckungsgleich mit VERTRAGSFASSUNG in
  -- src/features/platform/vertragstexte.ts bleiben (ANN-288).
  select '2026-10'::text
$$;

CREATE FUNCTION app.training_health_consent(p_relationship_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.platform_exercise_note_allowed('training', p_relationship_id)
$$;

COMMENT ON FUNCTION app.training_health_consent(p_relationship_id uuid) IS 'OUT-001 (ANN-364): ob im Trainingsverhaeltnis die Einwilligung zu Gesundheitsangaben erteilt ist - der juengste Vermerk entscheidet, wie app.platform_exercise_note_allowed.';

CREATE FUNCTION app.training_offer_blocker(p_offer_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_offer  public.training_offers%rowtype;
  v_person uuid;
  v_offen  boolean;
  v_abschluss date;
begin
  select * into v_offer from public.training_offers o where o.id = p_offer_id;
  select p.person_id into v_person from public.patients p where p.id = v_offer.patient_id;

  if exists (
    select 1 from public.training_relationships t
    where t.person_id = v_person and t.organization_id = v_offer.organization_id
  ) then
    return 'has_training';
  end if;

  select bool_or(p.care_concluded_on is null), max(p.care_concluded_on)
    into v_offen, v_abschluss
  from public.patients p
  where p.person_id = v_person and p.organization_id = v_offer.organization_id;
  if v_offen then
    return 'care_open';
  end if;
  if v_abschluss is not null and v_offer.starts_on < v_abschluss then
    return 'before_care_end';
  end if;

  if not exists (
    select 1 from public.service_catalog_items c
    where c.id = v_offer.catalog_item_id
      and c.catalog_version_id = app.active_service_catalog_version(v_offer.organization_id, v_offer.starts_on)
  ) then
    return 'price_changed';
  end if;
  return null;
end;
$$;

COMMENT ON FUNCTION app.training_offer_blocker(p_offer_id uuid) IS 'KND-003: warum ein Trainingsangebot heute nicht angenommen werden kann (has_training, care_open, before_care_end, price_changed) oder null. Nur fuer die Projektionen der Person selbst.';

CREATE FUNCTION app.training_offer_handover_valid(p_items jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_typeof(p_items) = 'array'
     and jsonb_array_length(p_items) <= 5
     and not exists (
       select 1 from jsonb_array_elements(p_items) e
       where jsonb_typeof(e) <> 'object'
          or (select count(*) from jsonb_object_keys(e)) <> 2
          or jsonb_typeof(e -> 'title') is distinct from 'string'
          or jsonb_typeof(e -> 'body') is distinct from 'string'
          or char_length(btrim(e ->> 'title')) not between 1 and 80
          or (e ->> 'title') <> btrim(e ->> 'title')
          or char_length(btrim(e ->> 'body')) not between 1 and 600
          or (e ->> 'body') <> btrim(e ->> 'body')
     )
$$;

CREATE TABLE public.training_offers (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    catalog_item_id uuid NOT NULL,
    starts_on date NOT NULL,
    valid_until date NOT NULL,
    handover_items jsonb DEFAULT '[]'::jsonb NOT NULL,
    offers_contact boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    withdrawn_at timestamp with time zone,
    withdrawn_by uuid,
    accepted_at timestamp with time zone,
    CONSTRAINT training_offers_handover_shape CHECK (((jsonb_typeof(handover_items) = 'array'::text) AND (jsonb_array_length(handover_items) <= 5))),
    CONSTRAINT training_offers_handover_valid CHECK (app.training_offer_handover_valid(handover_items)),
    CONSTRAINT training_offers_valid_until CHECK ((valid_until <= starts_on)),
    CONSTRAINT training_offers_withdrawn_stamp CHECK (((withdrawn_at IS NULL) = (withdrawn_by IS NULL)))
);

COMMENT ON TABLE public.training_offers IS 'KND-002 (PROJECT_PRINCIPLES.md 4.10): Trainingsangebot aus der Akte - Paket, Beginn, Gueltigkeit und die Uebergabeangaben, die die Person im eigenen Konto freigeben kann (ANN-282 bis ANN-284). Kein Verweis aufs Training (ADR-021 Punkt 3). Datenklasse: Patientenakte, faellt mit ihr. Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.training_offers.valid_until IS 'ANN-284: letzter Tag, an dem die Person annehmen kann - 14 Tage nach dem Angebot, hoechstens der Beginn.';

COMMENT ON COLUMN public.training_offers.handover_items IS 'ANN-283: bis zu fuenf Angaben aus der Behandlung, von der Praxis wortwoertlich formuliert ({title, body}). Ins Training gelangen sie nur als Kopie der einzeln freigegebenen Angaben (ADR-021 Punkt 7, KND-003).';

COMMENT ON COLUMN public.training_offers.offers_contact IS 'Ob die Kontaktdaten der Akte (Geburtsdatum, Anschrift, Telefon, E-Mail) zur Uebernahme angeboten werden; die Person gibt sie beim Annehmen frei oder nicht.';

COMMENT ON COLUMN public.training_offers.accepted_at IS 'KND-003: wann die Person das Angebot in ihrem Konto angenommen hat. Nur die Projektion der Person liest es, damit ein Angebot nicht zweimal angenommen wird; die Akte sieht es nie (ANN-285, PROJECT_PRINCIPLES.md 4.8).';

CREATE FUNCTION app.training_offer_practice_state(p_offer public.training_offers, p_today date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_offer.withdrawn_at is not null then 'withdrawn'
    when p_today > p_offer.valid_until then 'expired'
    else 'open'
  end
$$;

COMMENT ON FUNCTION app.training_offer_practice_state(p_offer public.training_offers, p_today date) IS 'KND-002 (ANN-285): Stand eines Trainingsangebots, wie die Akte ihn sieht - withdrawn, expired oder open, ohne die Annahme (PROJECT_PRINCIPLES.md 4.8).';

CREATE FUNCTION app.training_offer_state(p_offer public.training_offers, p_today date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_offer.accepted_at is not null then 'accepted'
    when p_offer.withdrawn_at is not null then 'withdrawn'
    when p_today > p_offer.valid_until then 'expired'
    else 'open'
  end
$$;

COMMENT ON FUNCTION app.training_offer_state(p_offer public.training_offers, p_today date) IS 'KND-002: Stand eines Trainingsangebots am Tag fuer die Person - accepted, withdrawn, expired (nach valid_until) oder open (ANN-284). Nie fuer die Akte (app.training_offer_practice_state).';

CREATE FUNCTION app.training_package_covering(p_relationship_id uuid, p_day date) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select k.id
  from public.training_packages k
  where k.training_relationship_id = p_relationship_id
    and p_day between k.starts_on and k.ends_on
  limit 1
$$;

COMMENT ON FUNCTION app.training_package_covering(p_relationship_id uuid, p_day date) IS 'ANG-007 (ANN-279): das Trainingspaket, das diesen Tag fuer das Verhaeltnis abdeckt, oder null. Ein Trainingstermin an einem abgedeckten Tag traegt keine eigene Forderung (BEF-114).';

CREATE FUNCTION app.training_package_ends_on(p_starts_on date, p_months integer) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select app.aftercare_month_end(p_starts_on, p_months - 1)
$$;

COMMENT ON FUNCTION app.training_package_ends_on(p_starts_on date, p_months integer) IS 'ANG-006 (ANN-277): letzter Tag eines Trainingspakets mit p_months Monaten Laufzeit ab p_starts_on, nach Paragraf 188 BGB vom Beginn aus gerechnet.';

CREATE FUNCTION app.training_package_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.billable_services b
    where b.training_relationship_id = new.training_relationship_id
      and b.appointment_id is not null
      and b.performed_on between new.starts_on and new.ends_on
  ) then
    raise exception 'training appointments in this period already carry billable services'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION app.training_package_guard() IS 'ANG-007 (ANN-279): Ein Trainingspaket entsteht nicht ueber Tage, an denen schon eine Trainingsleistung am Termin erfasst ist - dieselbe Zeit wird nicht zweimal bezahlt.';

CREATE FUNCTION app.training_package_start_blocker(p_relationship_id uuid, p_starts_on date) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_verh  public.training_relationships%rowtype;
  v_abschluss date;
  v_offen boolean;
begin
  select * into v_verh from public.training_relationships t where t.id = p_relationship_id;
  if not found then
    return 'not_found';
  end if;
  if v_verh.contract_ended_on is not null then
    return 'ended';
  end if;
  if v_verh.contract_started_on is not null and p_starts_on < v_verh.contract_started_on then
    return 'before_contract';
  end if;
  if p_starts_on < app.training_today(v_verh.organization_id) - 14 then
    return 'too_early';
  end if;

  select bool_or(p.care_concluded_on is null), max(p.care_concluded_on)
    into v_offen, v_abschluss
  from public.patients p
  where p.person_id = v_verh.person_id and p.organization_id = v_verh.organization_id;
  if v_offen then
    return 'care_open';
  end if;
  if v_abschluss is not null and p_starts_on < v_abschluss then
    return 'before_care_end';
  end if;
  return null;
end;
$$;

COMMENT ON FUNCTION app.training_package_start_blocker(p_relationship_id uuid, p_starts_on date) IS 'ANG-006: warum ein Trainingspaket an diesem Tag nicht beginnen kann (not_found, ended, before_contract, too_early, care_open, before_care_end) oder null. ANN-278: nicht waehrend einer laufenden Behandlung derselben Person.';

