CREATE FUNCTION app.training_withdrawal_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Par. 355 Abs. 2 BGB: 14 Tage ab Vertragsschluss.
  select 14
$$;

CREATE FUNCTION app.treatment_base_items_json(p_treatment_basis_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',                  i.id,
        'sort_order',          i.sort_order,
        'remedy',              i.remedy,
        'prescribed_quantity', i.prescribed_quantity,
        'used_quantity',       i.used_quantity,
        'remaining_quantity',  i.prescribed_quantity - i.used_quantity
      )
      order by i.sort_order
    ),
    '[]'::jsonb
  )
  from public.treatment_base_items i
  where i.treatment_basis_id = p_treatment_basis_id
$$;

COMMENT ON FUNCTION app.treatment_base_items_json(p_treatment_basis_id uuid) IS 'Positionen einer Behandlungsgrundlage als JSON, inklusive der gerechneten Restmenge (VER-002, ANN-012).';

CREATE FUNCTION app.treatment_bases_basis_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'treatment_bases' then
    if old.billing_released_at is not null and new.billing_released_at is not null
       and (new.appointment_count is distinct from old.appointment_count
            or new.treatment_basis_kind is distinct from old.treatment_basis_kind) then
      raise exception 'treatment basis is in billing' using errcode = '55000';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if app.treatment_basis_locked(old.treatment_basis_id) then
      raise exception 'treatment basis is in billing' using errcode = '55000';
    end if;
    return old;
  end if;

  -- Erst die Spalten, dann die Sperre: Die genutzte Menge folgt den
  -- Leistungen und sperrt die Grundlage nicht (Zweitreview A, Nachtrag).
  if tg_op = 'UPDATE'
     and new.prescribed_quantity is not distinct from old.prescribed_quantity
     and new.remedy is not distinct from old.remedy then
    return new;
  end if;

  if app.treatment_basis_locked(new.treatment_basis_id) then
    raise exception 'treatment basis is in billing' using errcode = '55000';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.treatment_basis_billing(p_treatment_basis_id uuid, OUT appointment_count integer, OUT performed integer, OUT documented integer, OUT open_count integer, OUT past_open integer, OUT planned integer, OUT upcoming integer, OUT complete boolean, OUT ready boolean, OUT released_at timestamp with time zone, OUT invoiced boolean, OUT state text) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entwurf      boolean;
  v_doku_entwurf boolean;
begin
  select b.appointment_count, b.billing_released_at
    into appointment_count, released_at
  from public.treatment_bases b
  where b.id = p_treatment_basis_id;

  if not found then
    return;
  end if;

  -- Erbracht: abgehakt (B4/B7). Dokumentiert und abgehakt: abrechenbar.
  select count(*) filter (where a.completed_at is not null or a.status = 'invoiced'),
         count(*) filter (where a.status in ('documented', 'invoiced')
                           and (a.completed_at is not null or a.status = 'invoiced')),
         -- Offen: jeder Termin, der weder abgehakt und dokumentiert noch
         -- abgesagt oder nicht angetroffen ist - auch ein kuenftiger.
         count(*) filter (where a.status not in ('cancelled', 'no_show', 'invoiced')
                           and not (a.status = 'documented' and a.completed_at is not null)),
         -- Nachzuholen: offen und schon vorbei (Haken oder Doku fehlt).
         count(*) filter (where a.status not in ('cancelled', 'no_show', 'invoiced')
                           and not (a.status = 'documented' and a.completed_at is not null)
                           and a.ends_at <= now()),
         count(*) filter (where a.status not in ('cancelled', 'no_show')),
         count(*) filter (where a.status = 'confirmed' and a.ends_at > now())
    into performed, documented, open_count, past_open, planned, upcoming
  from public.appointments a
  where a.treatment_basis_id = p_treatment_basis_id;

  invoiced := exists (
    select 1
    from public.invoices i
    where i.treatment_basis_id = p_treatment_basis_id
      and i.status = 'issued'
      and not exists (select 1 from public.invoice_cancellations c where c.invoice_id = i.id)
  );
  -- Ein Entwurf zur Grundlage: Das Buero rechnet sie gerade ab.
  v_entwurf := exists (
    select 1
    from public.invoices i
    where i.treatment_basis_id = p_treatment_basis_id
      and i.status = 'draft'
  );

  -- Ein Entwurf an einem Termin der Grundlage, auch ein Nachtrag: Die Doku ist
  -- nicht fertig, und unter der Sperre liesse er sich nicht mehr festschreiben.
  v_doku_entwurf := exists (
    select 1
    from public.treatment_notes t
    join public.appointments a on a.id = t.appointment_id
    where a.treatment_basis_id = p_treatment_basis_id
      and t.status = 'draft'
  );

  complete := appointment_count is not null and performed >= appointment_count;
  ready := released_at is null and not invoiced and not v_entwurf and not v_doku_entwurf
           and documented > 0 and open_count = 0;

  -- Ein Zustand je Grundlage fuer Akte, Liste und Vorschlag (B1, B7).
  state := case
    when invoiced then 'abgerechnet'
    when released_at is not null or v_entwurf then 'in_abrechnung'
    when past_open > 0 or v_doku_entwurf then 'nachholen'
    when ready and complete then 'abrechnen'
    when upcoming > 0 then 'laeuft'
    when coalesce(appointment_count, 0) > planned then 'termine_fehlen'
    when ready then 'abrechnen'
    else 'laeuft'
  end;
end;
$$;

COMMENT ON FUNCTION app.treatment_basis_billing(p_treatment_basis_id uuid, OUT appointment_count integer, OUT performed integer, OUT documented integer, OUT open_count integer, OUT past_open integer, OUT planned integer, OUT upcoming integer, OUT complete boolean, OUT ready boolean, OUT released_at timestamp with time zone, OUT invoiced boolean, OUT state text) IS 'B7 (ANN-514): Stand einer Grundlage fuer die Abrechnung - Terminzahl, erbracht (abgehakt), dokumentiert und abgehakt, offen (weder das noch abgesagt/nicht angetroffen), davon vorbei, verplant, bevorstehend, vollstaendig, bereit zur Freigabe, freigegeben, abgerechnet und ein Zustand (laeuft, termine_fehlen, nachholen, abrechnen, in_abrechnung, abgerechnet). Die eine Stelle; Freigabe, Vorschlag, Akte und Patientenliste fragen sie.';

CREATE FUNCTION app.treatment_basis_content(p_treatment_basis_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'treatment_basis_kind',     b.treatment_basis_kind,
    'prescriber_id',            b.prescriber_id,
    'prescriber_name',          nullif(btrim(concat_ws(' ', v.title, v.given_name, v.family_name)), ''),
    'issued_on',                b.issued_on,
    'appointment_count',        b.appointment_count,
    'frequency_note',           b.frequency_note,
    'note',                     b.note,
    'diagnosis',                b.diagnosis,
    'diagnosis_icd10',          b.diagnosis_icd10,
    'therapy_goal',             b.therapy_goal,
    'prescriber_note',          b.prescriber_note,
    'follow_up_recommendation', b.follow_up_recommendation,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'remedy', i.remedy,
               'prescribed_quantity', i.prescribed_quantity
             ) order by i.sort_order, i.id)
      from public.treatment_base_items i
      where i.treatment_basis_id = b.id
    ), '[]'::jsonb)
  )
  from public.treatment_bases b
  left join public.prescribers v on v.id = b.prescriber_id
  where b.id = p_treatment_basis_id
$$;

CREATE FUNCTION app.treatment_basis_has_clinical_texts(p_treatment_basis_id uuid, p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.treatment_bases b
    where b.id = p_treatment_basis_id
      and b.organization_id = p_org
      and (b.therapy_goal is not null
           or b.prescriber_note is not null
           or b.follow_up_recommendation is not null)
  )
$$;

CREATE FUNCTION app.treatment_basis_locked(p_treatment_basis_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_freigegeben timestamptz;
begin
  select b.billing_released_at into v_freigegeben
  from public.treatment_bases b
  where b.id = p_treatment_basis_id
  for key share;
  return v_freigegeben is not null;
end;
$$;

COMMENT ON FUNCTION app.treatment_basis_locked(p_treatment_basis_id uuid) IS 'B7 (ANN-515): Ist die Grundlage in die Abrechnung gestellt? Dann sind Doku, Zeitpunkt und Anzahl ihrer Termine gesperrt. Liest die Zeile FOR KEY SHARE, damit eine gleichzeitige Freigabe und ein Schreibvorgang nacheinander laufen (ADR-016 Punkt 11).';

CREATE FUNCTION app.treatment_basis_slot_counts(p_treatment_basis_id uuid, p_organization_id uuid, OUT prescribed integer, OUT used integer, OUT planned integer, OUT remaining integer, OUT covered integer, OUT uncovered integer) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Die Terminzahl kommt aus der Grundlage selbst (ANN-064).
  select b.appointment_count
    into prescribed
  from public.treatment_bases b
  where b.id = p_treatment_basis_id
    and b.organization_id = p_organization_id;

  -- Genutzt ist eine Terminzahl: die erbrachten Termine der Grundlage
  -- (ABN-001, ANN-210). Seit B4/B7 (ANN-513) heisst erbracht: abgehakt - ein
  -- dokumentierter Termin ohne Haken zaehlt noch nicht.
  select count(*)
    into used
  from public.appointments a
  where a.treatment_basis_id = p_treatment_basis_id
    and a.organization_id = p_organization_id
    and a.status in ('completed', 'documented', 'invoiced')
    and (a.completed_at is not null or a.status = 'invoiced');

  -- Verplant ist jeder Termin, der stattfindet oder stattgefunden hat.
  -- Abgesagt und nicht angetroffen geben den Platz zurueck.
  select count(*)
    into planned
  from public.appointments a
  where a.treatment_basis_id = p_treatment_basis_id
    and a.organization_id = p_organization_id
    and a.status not in ('cancelled', 'no_show');

  remaining := greatest(coalesce(prescribed, 0) - greatest(coalesce(used, 0), planned), 0);

  -- CAL-022: Gedeckt sind hoechstens so viele Termine, wie die Grundlage
  -- moeglich macht; alles darueber ist geplant, aber ungedeckt.
  covered   := least(coalesce(prescribed, 0), planned);
  uncovered := greatest(planned - coalesce(prescribed, 0), 0);
end;
$$;

COMMENT ON FUNCTION app.treatment_basis_slot_counts(p_treatment_basis_id uuid, p_organization_id uuid, OUT prescribed integer, OUT used integer, OUT planned integer, OUT remaining integer, OUT covered integer, OUT uncovered integer) IS 'Kontingent einer Behandlungsgrundlage, gezaehlt in Terminen (VER-EPIC-002, ANN-064): moegliche Termine aus appointment_count, genutzte aus den abgehakten Terminen (seit B4/B7, ANN-513), verplante aus den Terminen ohne cancelled und no_show (ANN-038, ANN-067), offen ist die Differenz zum groesseren der beiden. Seit CAL-022 dazu gedeckt und ungedeckt. Nur fuer die serverseitigen Lese- und Schreibpfade.';

CREATE FUNCTION app.treatment_basis_version_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'treatment_bases' then
    perform app.record_treatment_basis_version(old.id);
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform app.record_treatment_basis_version(old.treatment_basis_id);
    return old;
  end if;

  if tg_op = 'INSERT' then
    perform app.record_treatment_basis_version(new.treatment_basis_id);
  else
    perform app.record_treatment_basis_version(old.treatment_basis_id);
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.treatment_notes_basis_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_basis uuid;
begin
  if tg_table_name = 'treatment_note_versions' then
    select a.treatment_basis_id into v_basis
    from public.treatment_notes t
    join public.appointments a on a.id = t.appointment_id
    where t.id = new.note_id;
  else
    select a.treatment_basis_id into v_basis
    from public.appointments a
    where a.id = new.appointment_id;
  end if;

  if v_basis is not null and app.treatment_basis_locked(v_basis) then
    raise exception 'treatment basis is in billing' using errcode = '55000';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.under_legal_hold(p_organization_id uuid, p_subject_type text, p_subject_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.legal_holds h
    where h.organization_id = p_organization_id
      and h.subject_type = p_subject_type
      and h.subject_id = p_subject_id
      and h.released_at is null
  )
$$;

COMMENT ON FUNCTION app.under_legal_hold(p_organization_id uuid, p_subject_type text, p_subject_id uuid) IS 'Besteht eine laufende Loeschsperre auf diesem Gegenstand (ADR-008 Punkt 7, LOE-001c)?';

-- ANN-187
CREATE FUNCTION app.user_profiles_not_platform_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.platform_accesses a where a.account_user_id = new.id
  ) then
    raise exception 'platform account cannot be a practice account' using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION app.waitlist_before_basis_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eintrag record;
begin
  for v_eintrag in
    select w.id, w.organization_id, w.patient_id
    from public.waitlist_entries w
    where w.treatment_basis_id = old.id
      and w.status = 'open'
      and exists (
        select 1 from public.waitlist_entries d
        where d.patient_id = w.patient_id
          and d.status = 'open'
          and d.treatment_basis_id is null
      )
    for update
  loop
    update public.waitlist_entries w
       set status = 'withdrawn',
           closed_at = clock_timestamp(),
           closed_by = auth.uid(),
           updated_at = clock_timestamp(),
           updated_by = auth.uid()
     where w.id = v_eintrag.id;

  end loop;
  return old;
end;
$$;

COMMENT ON FUNCTION app.waitlist_before_basis_delete() IS 'Zweitreview PRX-EPIC-001, Befund 2: Faellt eine Grundlage, waehrend die Person zugleich einen offenen Eintrag ohne Grundlage hat, wird der Eintrag der Grundlage zurueckgenommen statt auf null gesetzt - sonst schluege der Eindeutigkeitsindex zu. Auditiert.';

CREATE FUNCTION app.waitlist_check_input(p_org uuid, p_patient_id uuid, p_treatment_basis_id uuid, p_preferred_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_time_windows jsonb, p_earliest_on date, p_needed_by date, p_priority_reason text, p_note text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_appointment_type is null or p_appointment_type not in ('home_visit', 'practice', 'video') then
    raise exception 'invalid appointment type' using errcode = '22023';
  end if;
  if p_duration_minutes is null or p_duration_minutes not between 5 and 240 then
    raise exception 'invalid duration' using errcode = '22023';
  end if;
  if not app.waitlist_windows_valid(coalesce(p_time_windows, '[]'::jsonb)) then
    raise exception 'invalid time windows' using errcode = '22023';
  end if;
  if p_priority_reason is null
     or p_priority_reason not in ('patient_wish', 'prescription_ending', 'practice_priority') then
    raise exception 'invalid priority reason' using errcode = '22023';
  end if;
  if p_earliest_on is not null and p_needed_by is not null and p_needed_by < p_earliest_on then
    raise exception 'needed_by before earliest_on' using errcode = '22023';
  end if;
  if p_note is not null and length(btrim(p_note)) > 500 then
    raise exception 'note too long' using errcode = '22023';
  end if;

  if p_treatment_basis_id is not null and not exists (
    select 1 from public.treatment_bases tb
    where tb.id = p_treatment_basis_id
      and tb.organization_id = p_org
      and tb.patient_id = p_patient_id
  ) then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  if p_preferred_staff_member_id is not null
     and not app.is_assignable_therapist(p_preferred_staff_member_id, p_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;
end;
$$;

CREATE FUNCTION app.waitlist_review_interval() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- ANN-220: acht Wochen unveraendert offen.
  select interval '8 weeks'
$$;

COMMENT ON FUNCTION app.waitlist_review_interval() IS 'Nach wie langer Zeit ohne Aenderung ein offener Wartelisteneintrag zu pruefen ist (ABN-018, BEF-108, ANN-220).';

CREATE FUNCTION app.waitlist_windows_valid(p_windows jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_fenster jsonb;
  v_von     time;
  v_bis     time;
  v_tag     integer;
begin
  if p_windows is null or jsonb_typeof(p_windows) <> 'array' then
    return false;
  end if;
  if jsonb_array_length(p_windows) > 14 then
    return false;
  end if;

  for v_fenster in select value from jsonb_array_elements(p_windows)
  loop
    if jsonb_typeof(v_fenster) <> 'object'
       or (select count(*) from jsonb_object_keys(v_fenster)) <> 3
       or jsonb_typeof(v_fenster -> 'weekday') <> 'number'
       or jsonb_typeof(v_fenster -> 'from') <> 'string'
       or jsonb_typeof(v_fenster -> 'to') <> 'string'
       or (v_fenster ->> 'from') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or (v_fenster ->> 'to') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      return false;
    end if;

    v_tag := (v_fenster ->> 'weekday')::numeric;
    if v_tag <> (v_fenster ->> 'weekday')::numeric or v_tag not between 1 and 7 then
      return false;
    end if;

    v_von := (v_fenster ->> 'from')::time;
    v_bis := (v_fenster ->> 'to')::time;
    if v_bis <= v_von then
      return false;
    end if;
  end loop;

  return true;
end;
$_$;

COMMENT ON FUNCTION app.waitlist_windows_valid(p_windows jsonb) IS 'Prueft die Wunschfenster eines Wartelisteneintrags: Liste von hoechstens 14 Objekten {weekday 1-7 ISO, from HH:MM, to HH:MM}, Ende nach Beginn (PRX-001).';

CREATE FUNCTION app.withdraw_appointment_services(p_appointment_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  if exists (
    select 1 from public.billable_services
    where appointment_id = p_appointment_id and status = 'invoiced'
  ) or exists (
    select 1
    from public.invoice_items it
    join public.billable_services b on b.id = it.billable_service_id
    where b.appointment_id = p_appointment_id
      and it.released_at is null
  ) then
    raise exception 'billable services are in billing' using errcode = '23514';
  end if;

  update public.treatment_base_items p
     set used_quantity = greatest(p.used_quantity - b.menge, 0)
  from (
    select treatment_base_item_id, sum(quantity)::smallint as menge
    from public.billable_services
    where appointment_id = p_appointment_id and treatment_base_item_id is not null
    group by treatment_base_item_id
  ) b
  where p.id = b.treatment_base_item_id;

  delete from public.invoice_items it
   using public.billable_services b
   where it.billable_service_id = b.id
     and b.appointment_id = p_appointment_id
     and it.released_at is not null;

  delete from public.appointment_session_fees where appointment_id = p_appointment_id;

  delete from public.billable_services where appointment_id = p_appointment_id;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION app.withdraw_appointment_services(p_appointment_id uuid) IS 'B4/B7 (BEF-154, BEF-157): nimmt die Leistungen eines Termins zurueck, wenn sein Haken zurueckgenommen wird - ohne eigene Rollenpruefung, nur aus reopen_appointment. Abgerechnete oder in einem Entwurf stehende Leistungen halten den Vorgang an.';

CREATE FUNCTION app.working_day_blocks(p_blocks jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_von time[];
  v_bis time[];
  i     integer;
begin
  if p_blocks is null or jsonb_typeof(p_blocks) <> 'array' then
    raise exception 'blocks must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(p_blocks) > 6 then
    raise exception 'working hour block is invalid' using errcode = '22023';
  end if;
  begin
    select array_agg(w.von order by w.von), array_agg(w.bis order by w.von)
      into v_von, v_bis
    from (
      select (b ->> 'von')::time as von, (b ->> 'bis')::time as bis
      from jsonb_array_elements(p_blocks) as b
    ) w;
  exception
    when invalid_datetime_format or datetime_field_overflow or invalid_text_representation
         or invalid_parameter_value then
      raise exception 'working hour block is invalid' using errcode = '22023';
  end;
  if v_von is null then
    return '[]'::jsonb;
  end if;
  for i in 1 .. array_length(v_von, 1) loop
    if v_von[i] is null or v_bis[i] is null or v_bis[i] <= v_von[i]
       or date_part('second', v_von[i]) <> 0 or date_part('second', v_bis[i]) <> 0 then
      raise exception 'working hour block is invalid' using errcode = '22023';
    end if;
    if i > 1 and v_von[i] < v_bis[i - 1] then
      raise exception 'working hours overlap' using errcode = '23P01';
    end if;
  end loop;
  return (
    select jsonb_agg(jsonb_build_object('von', to_char(v_von[g.n], 'HH24:MI'),
                                        'bis', to_char(v_bis[g.n], 'HH24:MI')) order by g.n)
    from generate_series(1, array_length(v_von, 1)) as g (n)
  );
end;
$$;

CREATE FUNCTION app.working_day_minutes(p_blocks jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(sum(extract(epoch from ((b ->> 'bis')::time - (b ->> 'von')::time)) / 60), 0)::integer
  from jsonb_array_elements(coalesce(p_blocks, '[]'::jsonb)) as b
$$;

CREATE FUNCTION app.working_day_problems(p_blocks jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_probleme text[] := '{}';
  v_arbeit   integer := app.working_day_minutes(p_blocks);
  v_pause    integer := 0;
  v_stueck   integer := 0;
  v_laengste integer := 0;
  v_noetig   integer;
  v_luecke   integer;
  v_block    integer;
  v_vorher   time;
  b          jsonb;
begin
  if p_blocks is null or jsonb_array_length(p_blocks) = 0 then
    return v_probleme;
  end if;
  for b in select x from jsonb_array_elements(p_blocks) as x loop
    v_block := (extract(epoch from ((b ->> 'bis')::time - (b ->> 'von')::time)) / 60)::integer;
    if v_vorher is null then
      v_stueck := v_block;
    else
      v_luecke := (extract(epoch from ((b ->> 'von')::time - v_vorher)) / 60)::integer;
      -- Eine Pause zaehlt ab 15 Minuten; eine kuerzere Unterbrechung
      -- unterbricht das Arbeiten am Stueck nicht (Par. 4 ArbZG).
      if v_luecke >= 15 then
        v_pause := v_pause + v_luecke;
        v_stueck := v_block;
      else
        v_stueck := v_stueck + v_luecke + v_block;
      end if;
    end if;
    v_laengste := greatest(v_laengste, v_stueck);
    v_vorher := (b ->> 'bis')::time;
  end loop;

  if v_arbeit > 600 then
    v_probleme := array_append(v_probleme, 'more_than_ten_hours');
  end if;
  v_noetig := case when v_arbeit > 540 then 45 when v_arbeit > 360 then 30 else 0 end;
  if v_pause < v_noetig then
    v_probleme := array_append(v_probleme, 'break_too_short');
  end if;
  if v_laengste > 360 then
    v_probleme := array_append(v_probleme, 'more_than_six_hours_in_a_row');
  end if;
  return v_probleme;
end;
$$;

CREATE FUNCTION app.working_hour_action(p_vorher integer, p_nachher integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
           when p_vorher = 0 and p_nachher > 0 then 'created'
           when p_vorher > 0 and p_nachher = 0 then 'removed'
           else 'updated'
         end
$$;

COMMENT ON FUNCTION app.working_hour_action(p_vorher integer, p_nachher integer) IS 'Leitet aus Anzahl vorher und nachher die Art des Arbeitszeitvorgangs ab: created, updated oder removed (CAL-005).';

CREATE FUNCTION app.working_ranges(p_staff_member_id uuid, p_organization_id uuid, p_date date) RETURNS app.timemultirange
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_abweichungen integer;
  v_abwesend     boolean;
  v_bereiche     app.timemultirange;
begin
  select count(*), bool_or(a.kind = 'unavailable')
    into v_abweichungen, v_abwesend
  from public.staff_working_hour_exceptions a
  where a.staff_member_id = p_staff_member_id
    and a.organization_id = p_organization_id
    and a.on_date = p_date;

  if v_abweichungen > 0 then
    if v_abwesend then
      return null;
    end if;
    select range_agg(app.timerange(a.starts_at, a.ends_at, '[)'))
      into v_bereiche
    from public.staff_working_hour_exceptions a
    where a.staff_member_id = p_staff_member_id
      and a.organization_id = p_organization_id
      and a.on_date = p_date
      and a.kind = 'block';
  else
    select range_agg(app.timerange(h.starts_at, h.ends_at, '[)'))
      into v_bereiche
    from public.staff_working_hours h
    where h.staff_member_id = p_staff_member_id
      and h.organization_id = p_organization_id
      and h.weekday = extract(isodow from p_date)
      and daterange(h.valid_from, h.valid_until, '[]') @> p_date;
  end if;

  return v_bereiche;
end;
$$;

COMMENT ON FUNCTION app.working_ranges(p_staff_member_id uuid, p_organization_id uuid, p_date date) IS 'Arbeitszeit einer Person an einem Tag als Zeitraeume (PRX-003); dieselbe Regel wie app.is_within_working_hours, mit der Fassung des Tages (AZ-001). Null ohne Arbeitszeit oder bei Abwesenheit.';

CREATE FUNCTION app.working_time_baseline(p_org uuid, p_staff_member_id uuid, p_kind text, p_on_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tag   jsonb;
  v_woche jsonb;
begin
  if not exists (
    select 1 from public.staff_working_hours h
    where h.organization_id = p_org and h.staff_member_id = p_staff_member_id
      and (h.valid_until is null or h.valid_until >= p_on_date)
  ) then
    raise exception 'no working plan' using errcode = '22023';
  end if;

  if p_kind = 'once' then
    -- ZK-001: Einen Tag mit Freizeitausgleich ändert kein Antrag - erst den
    -- Eintrag zurückweisen oder zurücknehmen (ANN-595).
    if exists (
      select 1 from public.staff_working_hour_exceptions e
      where e.organization_id = p_org and e.staff_member_id = p_staff_member_id
        and e.on_date = p_on_date and e.time_account_entry_id is not null
    ) then
      raise exception 'day has time off in lieu' using errcode = '55000';
    end if;
    v_tag := app.effective_day(p_org, p_staff_member_id, p_on_date);
    if v_tag ->> 'kind' = 'leave' then
      raise exception 'day is part of approved leave' using errcode = '55000';
    end if;
    if v_tag ->> 'kind' = 'unavailable' then
      raise exception 'day is marked absent' using errcode = '55000';
    end if;
    return jsonb_build_object(
      'blocks', coalesce(v_tag -> 'blocks', '[]'::jsonb),
      'minutes', app.working_day_minutes(v_tag -> 'blocks')
    );
  end if;

  if exists (
    select 1 from public.staff_working_hours h
    where h.organization_id = p_org and h.staff_member_id = p_staff_member_id
      and h.valid_from > p_on_date
  ) then
    raise exception 'later working plan exists' using errcode = '55000';
  end if;
  v_woche := app.plan_week(p_org, p_staff_member_id, p_on_date);
  return jsonb_build_object(
    'blocks', v_woche,
    'minutes', (select sum(app.working_day_minutes(v_woche -> t.tag::text))::integer
                from generate_series(1, 7) as t (tag))
  );
end;
$$;

CREATE FUNCTION app.working_time_minutes(p_kind text, p_blocks jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_kind = 'once' then app.working_day_minutes(p_blocks)
         else (select sum(app.working_day_minutes(p_blocks -> t.tag::text))::integer
               from generate_series(1, 7) as t (tag)) end
$$;

CREATE FUNCTION app.working_time_normalize(p_kind text, p_blocks jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_woche jsonb := '{}'::jsonb;
  v_tag   integer;
begin
  if p_kind = 'once' then
    return app.working_day_blocks(p_blocks);
  end if;
  if p_blocks is null or jsonb_typeof(p_blocks) <> 'object'
     or exists (select 1 from jsonb_object_keys(p_blocks) as k
                where k not in ('1', '2', '3', '4', '5', '6', '7')) then
    raise exception 'blocks must be a week' using errcode = '22023';
  end if;
  for v_tag in 1 .. 7 loop
    v_woche := v_woche || jsonb_build_object(
      v_tag::text, app.working_day_blocks(coalesce(p_blocks -> v_tag::text, '[]'::jsonb)));
  end loop;
  return v_woche;
end;
$$;

CREATE FUNCTION app.working_time_problems(p_org uuid, p_staff_member_id uuid, p_kind text, p_on_date date, p_blocks jsonb) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_probleme text[] := '{}';
  v_tag      integer;
  v_ruhe     integer;
begin
  if p_kind = 'once' then
    v_probleme := app.working_day_problems(p_blocks);
    v_ruhe := least(
      app.rest_minutes(app.effective_day(p_org, p_staff_member_id, p_on_date - 1) -> 'blocks', p_blocks),
      app.rest_minutes(p_blocks, app.effective_day(p_org, p_staff_member_id, p_on_date + 1) -> 'blocks')
    );
  else
    for v_tag in 1 .. 7 loop
      v_probleme := v_probleme || app.working_day_problems(p_blocks -> v_tag::text);
      v_ruhe := least(v_ruhe, app.rest_minutes(p_blocks -> v_tag::text,
                                               p_blocks -> ((v_tag % 7) + 1)::text));
    end loop;
    v_ruhe := least(v_ruhe, app.rest_minutes(
      app.effective_day(p_org, p_staff_member_id, p_on_date - 1) -> 'blocks',
      p_blocks -> extract(isodow from p_on_date)::text));
    select least(v_ruhe, min(least(
             app.rest_minutes(
               app.day_with_plan(p_org, p_staff_member_id, e.tag - 1, p_on_date, p_blocks),
               app.day_with_plan(p_org, p_staff_member_id, e.tag, p_on_date, p_blocks)),
             app.rest_minutes(
               app.day_with_plan(p_org, p_staff_member_id, e.tag, p_on_date, p_blocks),
               app.day_with_plan(p_org, p_staff_member_id, e.tag + 1, p_on_date, p_blocks)))))
      into v_ruhe
    from (
      select distinct a.on_date as tag
      from public.staff_working_hour_exceptions a
      where a.organization_id = p_org and a.staff_member_id = p_staff_member_id
        and a.kind = 'block' and a.on_date between p_on_date and p_on_date + 366
    ) e;
  end if;
  if v_ruhe is not null and v_ruhe < 660 then
    v_probleme := array_append(v_probleme, 'rest_shorter_than_eleven_hours');
  end if;
  return array(select distinct p from unnest(v_probleme) as p order by p);
end;
$$;

CREATE FUNCTION app.write_training_contact(p_relationship_id uuid, p_org uuid, p_actor uuid, p_date_of_birth date, p_email text, p_phone text, p_street text, p_house_number text, p_postal_code text, p_city text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_date_of_birth is not null and p_date_of_birth > app.training_today(p_org) then
    raise exception 'date of birth is in the future' using errcode = '22023';
  end if;

  insert into public.training_contact_details as d (
    training_relationship_id, organization_id, date_of_birth, email, phone,
    street, house_number, postal_code, city, created_by
  )
  values (
    p_relationship_id, p_org, p_date_of_birth,
    lower(app.leer_zu_null(p_email)), app.leer_zu_null(p_phone),
    app.leer_zu_null(p_street), app.leer_zu_null(p_house_number),
    app.leer_zu_null(p_postal_code), app.leer_zu_null(p_city),
    p_actor
  )
  on conflict (training_relationship_id) do update
     set date_of_birth = excluded.date_of_birth,
         email         = excluded.email,
         phone         = excluded.phone,
         street        = excluded.street,
         house_number  = excluded.house_number,
         postal_code   = excluded.postal_code,
         city          = excluded.city,
         updated_at    = now(),
         updated_by    = p_actor;
end;
$$;

CREATE FUNCTION app.write_treatment_base_items(p_treatment_basis_id uuid, p_organization_id uuid, p_actor uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eintrag       jsonb;
  v_position      smallint := 0;
  v_remedy        text;
  v_terminzahl    integer;
  v_verordnet_num numeric;
  v_genutzt_num   numeric;
  v_verordnet     integer;
  v_genutzt       integer;
  v_bestand       record;
  v_id            uuid;
  v_behalten      uuid[] := array[]::uuid[];
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'items must be an array' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'at least one treatment basis item is required' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 50 then
    raise exception 'too many treatment basis items' using errcode = '22023';
  end if;

  select b.appointment_count into v_terminzahl
  from public.treatment_bases b
  where b.id = p_treatment_basis_id
    and b.organization_id = p_organization_id;

  if v_terminzahl is null then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  for v_eintrag in select * from jsonb_array_elements(p_items) loop
    v_position := v_position + 1;

    v_remedy := nullif(btrim(v_eintrag ->> 'remedy'), '');
    if v_remedy is null then
      raise exception 'remedy is required' using errcode = '22023';
    end if;

    -- Eine mitgelieferte id zaehlt nur, wenn sie zu dieser Grundlage gehoert.
    select i.id, i.prescribed_quantity, i.used_quantity
      into v_bestand
    from public.treatment_base_items i
    where i.treatment_basis_id = p_treatment_basis_id
      and i.id = nullif(v_eintrag ->> 'id', '')::uuid;

    -- Seit VER-EPIC-002 schickt die Oberflaeche nur noch die **Auswahl**: Ein
    -- Heilmittel ist angehakt oder nicht. Mengen sind damit optional, und ein
    -- fehlender Wert heisst ausdruecklich "unveraendert lassen" - nicht
    -- "null". Eine Bestandsmenge darf durch das vereinfachte Formular weder
    -- verloren gehen noch still umgedeutet werden (ANN-064). Eine **neue**
    -- Position erbt die Terminzahl als Leistungsmenge: Jeder moegliche Termin
    -- bringt dieses Heilmittel einmal mit.
    if v_eintrag ? 'prescribed_quantity' and jsonb_typeof(v_eintrag -> 'prescribed_quantity') <> 'null' then
      if jsonb_typeof(v_eintrag -> 'prescribed_quantity') <> 'number' then
        raise exception 'quantities must be numbers' using errcode = '22023';
      end if;
      -- Ueber numeric statt direkt ueber integer lesen: eine Kommazahl
      -- ("6.5") soll dieselbe sprechende Meldung wie ein Text ausloesen, statt
      -- eines rohen "invalid input syntax for type integer"-Fehlers, den der
      -- direkte Cast einer Dezimalzahl auf integer wirft.
      v_verordnet_num := (v_eintrag ->> 'prescribed_quantity')::numeric;
      if v_verordnet_num <> trunc(v_verordnet_num) then
        raise exception 'quantities must be whole numbers' using errcode = '22023';
      end if;
      v_verordnet := v_verordnet_num::integer;
    elsif v_bestand.id is not null then
      v_verordnet := v_bestand.prescribed_quantity;
    else
      v_verordnet := v_terminzahl;
    end if;

    if v_eintrag ? 'used_quantity' and jsonb_typeof(v_eintrag -> 'used_quantity') <> 'null' then
      if jsonb_typeof(v_eintrag -> 'used_quantity') <> 'number' then
        raise exception 'quantities must be numbers' using errcode = '22023';
      end if;
      v_genutzt_num := (v_eintrag ->> 'used_quantity')::numeric;
      if v_genutzt_num <> trunc(v_genutzt_num) then
        raise exception 'quantities must be whole numbers' using errcode = '22023';
      end if;
      v_genutzt := v_genutzt_num::integer;
    elsif v_bestand.id is not null then
      v_genutzt := v_bestand.used_quantity;
    else
      v_genutzt := 0;
    end if;

    if v_verordnet < 1 or v_verordnet > 500 then
      raise exception 'prescribed quantity out of range' using errcode = '22023';
    end if;

    if v_genutzt < 0 or v_genutzt > v_verordnet then
      raise exception 'used quantity out of range' using errcode = '22023';
    end if;

    v_id := v_bestand.id;

    if v_id is null then
      insert into public.treatment_base_items (
        organization_id, treatment_basis_id, sort_order, remedy,
        prescribed_quantity, used_quantity, created_by
      )
      values (
        p_organization_id, p_treatment_basis_id, v_position, v_remedy,
        v_verordnet, v_genutzt, p_actor
      )
      returning id into v_id;
    else
      update public.treatment_base_items
         set sort_order          = v_position,
             remedy              = v_remedy,
             prescribed_quantity = v_verordnet,
             used_quantity       = v_genutzt
       where id = v_id;
    end if;

    v_behalten := array_append(v_behalten, v_id);
  end loop;

  -- Was nicht mehr im Feld steht, ist entfernt worden.
  delete from public.treatment_base_items i
  where i.treatment_basis_id = p_treatment_basis_id
    and not (i.id = any (v_behalten));
end;
$$;

COMMENT ON FUNCTION app.write_treatment_base_items(p_treatment_basis_id uuid, p_organization_id uuid, p_actor uuid, p_items jsonb) IS 'Schreibt die Positionen einer Behandlungsgrundlage aus dem JSON-Feld: prueft die Bezeichnung, vergibt die Reihenfolge und entfernt weggefallene Positionen (VER-003, VER-EPIC-002). Mengen sind optional - fehlt eine, bleibt die des Bestands stehen, eine neue Position erbt die Terminzahl (ANN-064).';

CREATE FUNCTION public.accept_platform_training_offer(p_access_id uuid, p_offer_id uuid, p_release_items integer[], p_release_contact boolean, p_health_consent boolean, p_early_start boolean, p_wording_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid := auth.uid();
  v_zugang  public.platform_accesses%rowtype;
  v_offer   public.training_offers%rowtype;
  v_person  uuid;
  v_zone    text;
  v_heute   date;
  v_grund   text;
  v_item    public.service_catalog_items%rowtype;
  v_mwst    boolean;
  v_ende    date;
  v_frueh   boolean;
  v_rel     uuid;
  v_neu     uuid;
  v_paket   uuid;
  v_vertrag uuid;
  v_kontakt public.patient_contact_details%rowtype;
  v_anzahl  integer;
begin
  -- ANN-289: nur der eigene Zugang der Person zu ihrer Behandlung.
  if not app.platform_access_allows(p_access_id, 'contract') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'treatment' or v_zugang.access_kind <> 'self' then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;

  if p_release_contact is null or p_health_consent is null or p_early_start is null then
    raise exception 'all choices required' using errcode = '22023';
  end if;
  if p_wording_version is distinct from app.training_contract_wording_version() then
    raise exception 'wording outdated' using errcode = '22023';
  end if;

  -- Erst die Akte sperren, dann das Angebot: dieselbe Reihenfolge wie das
  -- Zurueckziehen in der Praxis (KND-002).
  select p.person_id into v_person
  from public.patients p
  where p.id = v_zugang.relationship_id and p.organization_id = v_zugang.organization_id
  for update;

  select * into v_offer
  from public.training_offers o
  where o.id = p_offer_id
    and o.patient_id = v_zugang.relationship_id
    and o.organization_id = v_zugang.organization_id
  for update;
  if not found then
    raise exception 'training offer not found' using errcode = '42501';
  end if;

  select o.time_zone into v_zone from public.organizations o where o.id = v_offer.organization_id;
  v_heute := app.training_today(v_offer.organization_id);

  if app.training_offer_state(v_offer, v_heute) <> 'open' then
    raise exception 'training offer is not open' using errcode = '23514';
  end if;

  -- Die Person kann nur freigeben, was angeboten ist.
  v_anzahl := jsonb_array_length(v_offer.handover_items);
  if exists (
    select 1 from unnest(coalesce(p_release_items, '{}'::integer[])) i
    where i is null or i < 1 or i > v_anzahl
  ) or cardinality(coalesce(p_release_items, '{}'::integer[]))
       <> (select count(distinct i) from unnest(coalesce(p_release_items, '{}'::integer[])) i) then
    raise exception 'release items invalid' using errcode = '22023';
  end if;
  if p_release_contact and not v_offer.offers_contact then
    raise exception 'contact data not offered' using errcode = '22023';
  end if;
  -- ADR-021 Punkt 7: Angaben zur Gesundheit nur mit Einwilligung.
  if cardinality(coalesce(p_release_items, '{}'::integer[])) > 0 and not p_health_consent then
    raise exception 'health consent required for handover items' using errcode = '22023';
  end if;

  v_grund := app.training_offer_blocker(v_offer.id);
  if v_grund is not null then
    raise exception 'training offer cannot be accepted: %', v_grund using errcode = '23514';
  end if;

  select * into v_item from public.service_catalog_items c where c.id = v_offer.catalog_item_id;
  v_ende := app.training_package_ends_on(v_offer.starts_on, v_item.package_months);
  v_frueh := v_offer.starts_on <= v_heute + app.training_withdrawal_days();
  -- ANN-288: Beginnt das Training in der Widerrufsfrist, nur auf
  -- ausdrueckliches Verlangen.
  if v_frueh and not p_early_start then
    raise exception 'early start must be requested' using errcode = '22023';
  end if;
  v_mwst := not coalesce((
    select b.small_business from public.practice_billing_profiles b
    where b.organization_id = v_offer.organization_id
  ), false);

  -- Das Trainingsverhaeltnis: Vertragsbeginn heute, der Tag des Abschlusses.
  insert into public.training_relationships (
    organization_id, person_id, status, contract_started_on, created_by
  )
  values (v_offer.organization_id, v_person, 'active', v_heute, v_actor)
  returning id into v_rel;

  -- Kontaktdaten nur, wenn freigegeben - als Kopie (ANN-283).
  if p_release_contact then
    select * into v_kontakt from public.patient_contact_details d
    where d.patient_id = v_offer.patient_id;
    perform app.write_training_contact(
      v_rel, v_offer.organization_id, v_actor, v_kontakt.date_of_birth, v_kontakt.email,
      coalesce(v_kontakt.phone_mobile, v_kontakt.phone), v_kontakt.street,
      v_kontakt.house_number, v_kontakt.postal_code, v_kontakt.city
    );
  end if;

  -- Der eigene Zugang zum Training, am selben Konto (ADR-023 Punkt 4). Den
  -- Einstieg braucht er nicht: Die Einwilligung hat die Person gerade
  -- entschieden.
  insert into public.platform_accesses (
    organization_id, relationship_kind, relationship_id, training_relationship_id,
    access_kind, account_user_id, status, created_by, activated_at, onboarding_finished_at
  )
  values (
    v_offer.organization_id, 'training', v_rel, v_rel, 'self', v_actor, 'active', v_actor,
    now(), now()
  )
  returning id into v_neu;

  perform app.log_platform_access_event(
    v_offer.organization_id, v_actor, 'platform', 'platform_access.activated', v_neu,
    jsonb_build_object('surface', 'platform', 'via', 'training_contract')
  );

  if p_health_consent then
    insert into public.training_consent_records (
      organization_id, training_relationship_id, record_kind, purpose, occurred_on,
      recorded_by, source, platform_access_id, platform_access_kind, wording_version
    )
    values (
      v_offer.organization_id, v_rel, 'consent_granted', 'training_health_data', v_heute,
      v_actor, 'platform', v_neu, 'self', app.platform_consent_wording_version()
    );
  end if;

  -- Das Paket mit seiner einen Leistung, wie create_training_package
  -- (ANN-276, ANN-277, ANN-278).
  v_grund := app.training_package_start_blocker(v_rel, v_offer.starts_on);
  if v_grund is not null then
    raise exception 'training package cannot start: %', v_grund using errcode = '23514';
  end if;
  insert into public.training_packages (
    organization_id, training_relationship_id, catalog_item_id, starts_on, ends_on, created_by
  )
  values (v_offer.organization_id, v_rel, v_offer.catalog_item_id, v_offer.starts_on, v_ende, v_actor)
  returning id into v_paket;

  insert into public.billable_services (
    organization_id, training_relationship_id, appointment_id, training_package_id,
    catalog_item_id, quantity, performed_on, created_by
  )
  values (
    v_offer.organization_id, v_rel, null, v_paket, v_offer.catalog_item_id, 1,
    v_offer.starts_on, v_actor
  );

  -- Die freigegebenen Angaben als Kopie (ADR-021 Punkt 7, KND-005).
  insert into public.training_takeovers (
    organization_id, training_relationship_id, position, title, body, offered_on,
    released_platform_access_id
  )
  select v_offer.organization_id, v_rel, e.n::smallint, e.wert ->> 'title', e.wert ->> 'body',
         (v_offer.created_at at time zone v_zone)::date, v_neu
  from jsonb_array_elements(v_offer.handover_items) with ordinality as e(wert, n)
  where e.n = any (coalesce(p_release_items, '{}'::integer[]));

  insert into public.training_contracts (
    organization_id, training_relationship_id, training_package_id, package_label,
    package_months, price_cents, currency, tax_rate_permille, vat_included, starts_on, ends_on,
    offered_on, wording_version, early_start_requested, contact_released,
    health_consent_granted, concluded_on, withdrawal_ends_on, platform_access_id
  )
  values (
    v_offer.organization_id, v_rel, v_paket, v_item.label, v_item.package_months,
    v_item.unit_price_cents, v_item.currency, v_item.tax_rate_permille, v_mwst,
    v_offer.starts_on, v_ende, (v_offer.created_at at time zone v_zone)::date,
    p_wording_version, v_frueh and p_early_start, p_release_contact, p_health_consent,
    v_heute, v_heute + app.training_withdrawal_days(), v_neu
  )
  returning id into v_vertrag;

  -- Damit das Angebot nicht zweimal angenommen wird. Die Akte liest den
  -- Zeitpunkt nie (ANN-285).
  update public.training_offers set accepted_at = now() where id = v_offer.id;

  return (
    select jsonb_build_object(
      'contract_id', k.id,
      'training_access_id', v_neu,
      'concluded_at', k.concluded_at,
      'label', k.package_label,
      'package_months', k.package_months,
      'price_cents', k.price_cents,
      'currency', k.currency,
      'starts_on', k.starts_on,
      'ends_on', k.ends_on,
      'withdrawal_ends_on', k.withdrawal_ends_on,
      'early_start_requested', k.early_start_requested,
      'contact_released', k.contact_released,
      'health_consent_granted', k.health_consent_granted,
      'released_titles', coalesce((
        select jsonb_agg(t.title order by t.position)
        from public.training_takeovers t where t.training_relationship_id = v_rel
      ), '[]'::jsonb)
    )
    from public.training_contracts k where k.id = v_vertrag
  );
exception
  when unique_violation then
    -- Zwei gleichzeitige Annahmen derselben Person: Eine gewinnt.
    raise exception 'training offer cannot be accepted: has_training' using errcode = '23514';
end;
$$;

COMMENT ON FUNCTION public.accept_platform_training_offer(p_access_id uuid, p_offer_id uuid, p_release_items integer[], p_release_contact boolean, p_health_consent boolean, p_early_start boolean, p_wording_version text) IS 'KND-003: das Trainingsangebot im eigenen Konto annehmen (nur der eigene Zugang zur Behandlung, ANN-289). Legt in einem Aufruf Trainingsverhaeltnis, freigegebene Kontaktdaten, eigenen Zugang zum Training, Einwilligung, Paket mit Leistung, Kopien der freigegebenen Angaben (nur mit Einwilligung) und den Vertragsnachweis an (ADR-021 Punkt 7, ANN-288). Liefert die Bestaetigung.';

CREATE FUNCTION public.add_appointment_notification(p_appointment_ids uuid[], p_channel text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id     uuid;
  v_anzahl integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Die aufgerufene Funktion prueft dasselbe Recht noch einmal. Hier steht es,
  -- damit die Meldung die Ursache trifft, statt auf halbem Weg zu scheitern.
  if not app.can_update_appointment() then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  if p_appointment_ids is null or array_length(p_appointment_ids, 1) is null then
    return 0;
  end if;

  if array_length(p_appointment_ids, 1) > 50 then
    raise exception 'too many appointments at once' using errcode = '22023';
  end if;

  foreach v_id in array p_appointment_ids loop
    perform public.set_appointment_notification(
      v_id,
      (select coalesce(array_agg(distinct k order by k), array[]::text[])
       from unnest(
         app.appointment_notification_channels(v_id) || array[p_channel]
       ) as k)
    );
    v_anzahl := v_anzahl + 1;
  end loop;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.add_appointment_notification(p_appointment_ids uuid[], p_channel text) IS 'Ergaenzt einen Mitteilungsweg bei mehreren Terminen in einem Vorgang, ohne vorhandene zu verlieren (CAL-012). Ruft je Termin set_appointment_notification auf; alles oder nichts.';

CREATE FUNCTION public.add_catalog_exercises_for_plan(p_plan_id uuid, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor      uuid := auth.uid();
  v_plan       public.exercise_plans%rowtype;
  v_frei       integer;
  v_ergebnis   jsonb;
  v_e          jsonb;
  v_schluessel text;
  v_name       text;
  v_variante   uuid;
  v_archiviert boolean;
  v_anzahl     integer;
  v_varianten  jsonb := '{}'::jsonb;
  v_konflikte  jsonb := '[]'::jsonb;
  v_pflegt     boolean;
  v_gesehen    text[] := '{}';
begin
  -- 42501 ohne Schreibrecht in einem Bereich, P0002 fuer einen fremden Plan
  -- oder einen des anderen Bereichs (ADR-021 Punkt 6). Sperrt die Zeile.
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;
  perform app.exercise_plan_relationship_open(v_plan);

  if p_entries is null or jsonb_typeof(p_entries) <> 'array'
     or jsonb_array_length(p_entries) = 0 then
    raise exception 'catalog is empty or invalid' using errcode = '22023';
  end if;
  select 30 - count(*) into v_frei
  from public.exercise_plan_items i
  where i.plan_id = v_plan.id;
  if jsonb_array_length(p_entries) > v_frei then
    raise exception 'too many exercises in plan' using errcode = '22023';
  end if;

  -- ANN-293: Die Bibliothek pflegt owner - auch das Uebernehmen aus dem
  -- Katalog. Nur dann: erst alles pruefen, dann schreiben; Vorhandenes
  -- ueberspringen, nie ueberschreiben, Namenskonflikte melden (ANN-382).
  -- Fuer andere Rollen dieselbe Pruefung - jeder Eintrag gueltig, kein
  -- Schluessel doppelt -, geschrieben wird nichts.
  v_pflegt := app.can_manage_exercise_library();
  if v_pflegt then
    v_ergebnis := app.import_exercise_catalog_for(
      v_plan.organization_id, v_actor, p_entries, false);
  else
    for v_e in select value from jsonb_array_elements(p_entries) loop
      v_schluessel := app.exercise_catalog_entry(v_e) ->> 'catalog_key';
      if v_schluessel = any (v_gesehen) then
        raise exception 'catalog key % is duplicated', v_schluessel using errcode = '22023';
      end if;
      v_gesehen := v_gesehen || v_schluessel;
    end loop;
    v_ergebnis := jsonb_build_object('imported', '[]'::jsonb);
  end if;

  for v_e in select value from jsonb_array_elements(p_entries) loop
    -- Schluessel und Name hat app.exercise_catalog_entry schon geprueft.
    v_schluessel := v_e ->> 'schluessel';
    v_name := btrim(v_e ->> 'name', E' \t\r\n');

    select v.id, (v.archived_at is not null or e.archived_at is not null)
      into v_variante, v_archiviert
    from public.exercise_variants v
    join public.exercises e on e.id = v.exercise_id
    where v.organization_id = v_plan.organization_id
      and v.catalog_key = v_schluessel;

    if found then
      if v_archiviert then
        v_konflikte := v_konflikte || jsonb_build_array(jsonb_build_object(
          'catalog_key', v_schluessel, 'name', v_name, 'reason', 'archived'));
      else
        v_varianten := v_varianten || jsonb_build_object(v_schluessel, v_variante);
      end if;
      continue;
    end if;

    -- Uebersprungen wegen einer gleichnamigen eigenen Uebung: eindeutig ist
    -- sie mit genau einer Variante, die nicht archiviert ist.
    select count(*), (array_agg(v.id))[1]
      into v_anzahl, v_variante
    from public.exercises e
    join public.exercise_variants v on v.exercise_id = e.id
    where e.organization_id = v_plan.organization_id
      and lower(btrim(e.name)) = lower(v_name)
      and e.archived_at is null
      and v.archived_at is null;

    if v_anzahl = 1 then
      v_varianten := v_varianten || jsonb_build_object(v_schluessel, v_variante);
    else
      -- Mit Uebernahme hat ein gleicher Name sie verhindert; ohne fehlt der
      -- Eintrag der Bibliothek - ausser zwei gleichnamige stehen zur Wahl.
      v_konflikte := v_konflikte || jsonb_build_array(jsonb_build_object(
        'catalog_key', v_schluessel, 'name', v_name,
        'reason', case when v_pflegt or v_anzahl > 1 then 'name' else 'missing' end));
    end if;
  end loop;

  return jsonb_build_object(
    'variants', v_varianten,
    'imported', v_ergebnis -> 'imported',
    'conflicts', v_konflikte
  );
end;
$$;

COMMENT ON FUNCTION public.add_catalog_exercises_for_plan(p_plan_id uuid, p_entries jsonb) IS 'O-002 (ANN-536): liefert fuer die gewaehlten Katalogeintraege eines Planentwurfs die Varianten der Praxis - nach app.can_write_exercise_plans(Bereich des Plans), Plan im Entwurf, hoechstens so viele, wie er noch fasst (30). Uebernehmen, was der Bibliothek fehlt, nur fuer owner (ANN-293, app.can_manage_exercise_library) ueber denselben Pruef- und Schreibweg wie public.import_exercise_catalog: ungeprueft bis zur Durchsicht (ANN-386), nie ueberschreiben. Liefert variants (Schluessel -> Variante der Praxis), imported und conflicts (name, archived, missing). Keine neue Auditaktion: created_by steht an der Zeile.';

CREATE FUNCTION public.add_habit(p_kind text, p_relationship_id uuid, p_action text, p_cue text, p_place text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
  v_id    uuid;
begin
  if v_actor is null
     or not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    raise exception 'not allowed to add habits' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.checkin_relationship(p_kind, p_relationship_id, v_org);
  if v_rel.area is null then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;
  -- Kein Durchgriff zwischen den Bereichen (ADR-021 Punkt 6).
  if not app.can_write_exercise_plans(v_rel.area) then
    raise exception 'not allowed to add habits' using errcode = '42501';
  end if;
  if not v_rel.is_open then
    raise exception 'relationship has ended' using errcode = '22023';
  end if;
  -- ANN-370: im Training nur mit Einwilligung zu Gesundheitsangaben.
  if p_kind = 'training' and not app.training_health_consent(p_relationship_id) then
    raise exception 'health data consent missing' using errcode = '42501';
  end if;

  -- Zwei gleichzeitige Eintraege werden nicht vier laufende.
  perform pg_advisory_xact_lock(hashtextextended('habits:' || p_relationship_id::text, 0));
  if (select count(*) from public.habits h
      where h.relationship_kind = p_kind and h.relationship_id = p_relationship_id
        and h.ended_at is null) >= app.habits_max_running() then
    raise exception 'too many habits' using errcode = '22023';
  end if;

  -- Laengen pruefen die Constraints der Tabelle.
  insert into public.habits (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    action, cue, place, starts_on, created_by
  )
  values (
    v_org, p_kind, p_relationship_id,
    case when p_kind = 'treatment' then p_relationship_id end,
    case when p_kind = 'training' then p_relationship_id end,
    btrim(p_action), btrim(p_cue), nullif(btrim(p_place), ''),
    app.training_today(v_org), v_actor
  )
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.add_habit(p_kind text, p_relationship_id uuid, p_action text, p_cue text, p_place text) IS 'ALT-003 (IDEA-ALT-002, ANN-370): traegt eine Gewohnheit am offenen Verhaeltnis ein - Was und Ausloeser (je 1 bis 120 Zeichen), Wo oder wann freiwillig; hoechstens drei laufende (22023). Wer: app.can_write_exercise_plans des Bereichs; im Training nur mit Einwilligung (42501). Der Schreibvorgang steht am Datensatz (created_by, ADR-010 Fassung 3).';

CREATE FUNCTION public.add_patient_course_event(p_patient_id uuid, p_occurred_on date, p_kind text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_questionnaire_response() then
    raise exception 'not allowed to record course events' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record course events' using errcode = '42501';
  end if;

  perform 1 from public.patients p
  where p.id = p_patient_id and p.organization_id = v_org;
  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  if p_occurred_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;

  -- Art, Notiz und Tag pruefen die Constraints der Tabelle.
  insert into public.patient_course_events (
    organization_id, patient_id, occurred_on, kind, note, created_by
  )
  values (
    v_org, p_patient_id, p_occurred_on, p_kind, nullif(btrim(p_note), ''), v_actor
  )
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.add_patient_course_event(p_patient_id uuid, p_occurred_on date, p_kind text, p_note text) IS 'Setzt eine Markierung im Verlauf (FRB-002e, ANN-106). owner, therapist, team_lead; protokolliert als patient_course_event.created ohne Art und Notiz.';

CREATE FUNCTION public.add_platform_diary_entry(p_access_id uuid, p_eaten_on date, p_meal text, p_food_kind text, p_food_id uuid, p_amount numeric DEFAULT NULL::numeric, p_portion_label text DEFAULT NULL::text, p_portion_count numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_zugang public.platform_accesses%rowtype;
  v_essen  jsonb;
  v_menge  record;
  v_id     uuid;
begin
  -- Erst der Zugang, dann die Eingabe.
  v_profil := app.platform_diary_for_writing(p_access_id, p_eaten_on, true);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if p_eaten_on is null or p_meal is null
     or p_meal not in ('breakfast', 'lunch', 'dinner', 'snack') then
    raise exception 'day and meal are required' using errcode = '22023';
  end if;
  v_essen := app.nutrition_diary_food(v_profil, p_food_kind, p_food_id);
  if v_essen is null then
    raise exception 'food not found' using errcode = 'P0002';
  end if;
  select * into v_menge from app.nutrition_diary_amount(v_essen, p_amount, p_portion_label, p_portion_count);
  if (select count(*) from public.nutrition_diary_entries e
      where e.profile_id = v_profil.id and e.eaten_on = p_eaten_on)
     >= app.nutrition_diary_rule('entries_per_day') then
    raise exception 'too many entries on this day' using errcode = '54000';
  end if;

  insert into public.nutrition_diary_entries (
    organization_id, profile_id, eaten_on, meal, food_kind, catalog_food_id, custom_food_id,
    food_name, food_brand, base_unit, energy_kcal, protein_g, fat_g, carbohydrate_g, sugar_g,
    fibre_g, saturated_fat_g, salt_g, amount, portion_label, portion_amount, portion_count,
    platform_access_id, platform_access_kind, created_by, updated_by
  )
  values (
    v_profil.organization_id, v_profil.id, p_eaten_on, p_meal, p_food_kind,
    case when p_food_kind = 'catalog' then p_food_id end,
    case when p_food_kind <> 'catalog' then p_food_id end,
    v_essen ->> 'name', v_essen ->> 'brand', v_essen ->> 'base_unit',
    (v_essen -> 'per_100' ->> 'energy_kcal')::numeric,
    (v_essen -> 'per_100' ->> 'protein_g')::numeric,
    (v_essen -> 'per_100' ->> 'fat_g')::numeric,
    (v_essen -> 'per_100' ->> 'carbohydrate_g')::numeric,
    (v_essen -> 'per_100' ->> 'sugar_g')::numeric,
    (v_essen -> 'per_100' ->> 'fibre_g')::numeric,
    (v_essen -> 'per_100' ->> 'saturated_fat_g')::numeric,
    (v_essen -> 'per_100' ->> 'salt_g')::numeric,
    v_menge.amount, v_menge.portion_label, v_menge.portion_amount, v_menge.portion_count,
    v_zugang.id, v_zugang.access_kind, auth.uid(), auth.uid()
  )
  returning id into v_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.add_platform_diary_entry(p_access_id uuid, p_eaten_on date, p_meal text, p_food_kind text, p_food_id uuid, p_amount numeric, p_portion_label text, p_portion_count numeric) IS 'ERN-007 (ADR-027 Punkte 9 und 10): ein Lebensmittel ins Tagebuch - an einem Tag zwischen Beginn und heute, zu einer Mahlzeit, mit Portion und Anzahl oder einer Menge in g bzw. ml; Werte rechnet der Server aus dem Lebensmittel (ANN-660). Die Person oder ihre rechtliche Vertretung, mit Einwilligung und eingeschaltetem Tagebuch, nicht in der Lesefrist; nie die Begleitung. Höchstens 80 je Tag.';

CREATE FUNCTION public.add_platform_message_entry(p_access_id uuid, p_message_id uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_vorgang public.platform_messages%rowtype;
  v_text    text;
  v_id      uuid;
begin
  v_zugang := app.assert_platform_message(p_access_id);
  -- BEF-132 (H5): Erst die Zeile sperren, dann den Zustand lesen. Sonst
  -- schreibt ein Nachtrag nach einem gleichzeitigen Erledigen den Vorgang
  -- wieder auf "offen" und scheitert an platform_messages_closed_stamp
  -- (23514) statt mit "message is closed" (22023).
  perform 1 from public.platform_messages m
  where m.id = p_message_id and m.organization_id = v_zugang.organization_id
  for update;
  v_vorgang := app.platform_open_message(p_access_id, p_message_id);
  -- Auch ein Nachtrag zu einer Uebung oder zu Beschwerden ist eine Angabe
  -- zur Gesundheit (ANN-311): nach einem Widerruf im Training nicht mehr.
  if not app.platform_message_topic_allowed(
           v_vorgang.relationship_kind, v_vorgang.relationship_id, v_vorgang.topic) then
    raise exception 'topic needs consent' using errcode = '42501';
  end if;
  v_text := app.platform_message_body(p_body);

  insert into public.platform_message_entries (
    organization_id, message_id, side, body, access_id, author_kind, author_label, created_by
  )
  values (
    v_vorgang.organization_id, v_vorgang.id, 'person', v_text, v_zugang.id, v_zugang.access_kind,
    case when v_zugang.access_kind <> 'self' then v_zugang.representative_name end, auth.uid()
  )
  returning id into v_id;

  -- Die Praxis ist wieder am Zug. War sie es schon, bleibt die Frist.
  update public.platform_messages m
     set status = 'open',
         due_on = case when m.status = 'open' then m.due_on
                       else app.message_due_on(m.organization_id) end,
         last_entry_at = now()
   where m.id = v_vorgang.id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'message')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.add_platform_message_entry(p_access_id uuid, p_message_id uuid, p_body text) IS 'KOM-001: zu einem offenen oder beantworteten Vorgang nachtragen (ANN-308). Die Praxis ist danach wieder am Zug; eine neue Frist nur, wenn sie schon geantwortet hatte (ANN-309).';

CREATE FUNCTION public.add_platform_water(p_access_id uuid, p_drunk_on date, p_delta_ml integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_zugang public.platform_accesses%rowtype;
  v_menge  integer;
begin
  v_profil := app.platform_diary_for_writing(p_access_id, p_drunk_on, true);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if p_drunk_on is null or p_delta_ml is null or p_delta_ml = 0
     or abs(p_delta_ml) > app.nutrition_diary_rule('water_step_max_ml') then
    raise exception 'day and amount are required' using errcode = '22023';
  end if;

  insert into public.nutrition_water_days (
    organization_id, profile_id, drunk_on, water_ml, platform_access_id, platform_access_kind,
    updated_by
  )
  values (
    v_profil.organization_id, v_profil.id, p_drunk_on,
    least(greatest(p_delta_ml, 0), app.nutrition_diary_rule('water_max_ml')),
    v_zugang.id, v_zugang.access_kind, auth.uid()
  )
  on conflict (profile_id, drunk_on) do update
     set water_ml = least(greatest(nutrition_water_days.water_ml + p_delta_ml, 0),
                          app.nutrition_diary_rule('water_max_ml')),
         platform_access_id = excluded.platform_access_id,
         platform_access_kind = excluded.platform_access_kind,
         updated_at = now(),
         updated_by = excluded.updated_by
  returning water_ml into v_menge;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
  return v_menge;
end;
$$;

COMMENT ON FUNCTION public.add_platform_water(p_access_id uuid, p_drunk_on date, p_delta_ml integer) IS 'ERN-007 (ADR-027 Punkt 10, ANN-661): Wasser an einem Tag zählen - ein Glas je Tipp, zurück mit negativem Schritt, nie unter 0 und nicht über 10 l. Wie add_platform_diary_entry: Einwilligung, eingeschaltet, nicht in der Lesefrist, nie die Begleitung. Liefert die Menge des Tages.';

CREATE FUNCTION public.add_team_channel_members(p_channel uuid, p_staff_members uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_neu   integer;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not exists (select 1 from public.team_channels c
                 where c.id = p_channel and c.organization_id = v_org and c.kind = 'private'
                   and c.archived_at is null)
     or not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  insert into public.team_channel_members (organization_id, channel_id, staff_member_id)
  select distinct v_org, p_channel, u.staff
  from unnest(coalesce(p_staff_members, '{}'::uuid[])) as u (staff)
  where u.staff is not null and app.teamchat_participant(v_org, u.staff)
  on conflict (channel_id, staff_member_id) do nothing;
  get diagnostics v_neu = row_count;
  return v_neu;
end;
$$;

CREATE FUNCTION public.add_training_course_event(p_relationship_id uuid, p_occurred_on date, p_kind text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
  v_id    uuid;
begin
  if v_actor is null or not app.can_write_exercise_plans('training') then
    raise exception 'not allowed to record course events' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.checkin_relationship('training', p_relationship_id, v_org);
  if v_rel.area is null then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;
  if not v_rel.is_open then
    raise exception 'relationship has ended' using errcode = '22023';
  end if;
  -- Operation, Erkrankung, Medikation sind Gesundheitsangaben (ANN-364).
  if not app.training_health_consent(p_relationship_id) then
    raise exception 'health data consent missing' using errcode = '42501';
  end if;
  if p_occurred_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;

  -- Art, Notiz und Tag pruefen die Constraints der Tabelle.
  insert into public.training_course_events (
    organization_id, training_relationship_id, occurred_on, kind, note, created_by
  )
  values (
    v_org, p_relationship_id, p_occurred_on, p_kind, nullif(btrim(p_note), ''), v_actor
  )
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.add_training_course_event(p_relationship_id uuid, p_occurred_on date, p_kind text, p_note text) IS 'OUT-001 (ANN-364): vermerkt ein Ereignis im Verlauf eines offenen Trainingsverhaeltnisses. Wer: app.can_write_exercise_plans(training); nur mit Einwilligung zu Gesundheitsangaben. Der Schreibvorgang steht am Datensatz (created_by, ADR-010 Fassung 3).';

CREATE FUNCTION public.add_training_protocol_addendum(p_appointment_id uuid, p_content text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_prot  record;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_access_training_protocols() then
    perform app.record_denied_write(v_actor, 'training_protocol.updated', 'not allowed to write training protocols');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write training protocols' using errcode = '42501';
  end if;

  select p.id, p.status, p.training_relationship_id into v_prot
  from public.training_protocols p
  join public.appointments a on a.id = p.appointment_id
  where p.appointment_id = p_appointment_id and p.organization_id = v_org
    and a.organization_id = v_org;
  if not found then
    raise exception 'training protocol not found' using errcode = 'P0002';
  end if;
  if v_prot.status <> 'final' then
    raise exception 'only a finalized training protocol takes an addendum' using errcode = '22023';
  end if;
  if p_content is null or length(btrim(p_content)) not between 1 and 5000 then
    raise exception 'addendum content out of range' using errcode = '22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) not between 3 and 500 then
    raise exception 'an addendum needs a reason' using errcode = '22023';
  end if;

  insert into public.training_protocol_addenda (organization_id, protocol_id, content, reason, created_by)
  values (v_org, v_prot.id, btrim(p_content), btrim(p_reason), v_actor)
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.add_training_protocol_addendum(p_appointment_id uuid, p_content text, p_reason text) IS 'Haengt einen Nachtrag mit Grund an ein abgeschlossenes Trainingsprotokoll (ABN-022, BEF-113, ANN-185 Fassung 2). owner und Trainingsbetreuung; protokolliert ohne Inhalt.';

CREATE FUNCTION public.answer_platform_message(p_message_id uuid, p_body text, p_attachment_id uuid DEFAULT NULL::uuid, p_mark_seconds integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorgang public.platform_messages%rowtype;
  v_anhang  public.platform_message_attachments%rowtype;
  v_text    text;
  v_id      uuid;
begin
  if auth.uid() is null or not app.may_read_platform_messages('any') then
    raise exception 'not allowed to answer platform messages' using errcode = '42501';
  end if;
  -- BEF-132 (H5): Erst die Zeile sperren, dann den Zustand lesen - wie beim
  -- Nachtrag der Person. Bis hierhin kam die Sperre erst nach der Pruefung.
  perform 1 from public.platform_messages m
  where m.id = p_message_id and m.organization_id = app.current_organization_id()
  for update;
  v_vorgang := app.practice_message(p_message_id, true);
  if v_vorgang.status = 'closed' then
    raise exception 'message is closed' using errcode = '22023';
  end if;
  v_text := app.platform_message_body(p_body);

  if (p_attachment_id is null) <> (p_mark_seconds is null) then
    raise exception 'a mark needs its video' using errcode = '22023';
  end if;
  if p_attachment_id is not null then
    select x.* into v_anhang
    from public.platform_message_attachments x
    where x.id = p_attachment_id and x.message_id = v_vorgang.id and x.media_kind = 'video'
      and app.message_attachment_visible(x);
    if v_anhang.id is null then
      raise exception 'video not found' using errcode = 'P0002';
    end if;
    if p_mark_seconds < 0 or p_mark_seconds > v_anhang.duration_seconds then
      raise exception 'mark outside the video' using errcode = '22023';
    end if;
  end if;

  insert into public.platform_message_entries (
    organization_id, message_id, side, body, access_id, author_kind, author_label, created_by,
    attachment_id, attachment_mark_seconds
  )
  values (
    v_vorgang.organization_id, v_vorgang.id, 'practice', v_text, null, 'staff',
    app.current_display_name(), auth.uid(), v_anhang.id, p_mark_seconds
  )
  returning id into v_id;

  update public.platform_messages m
     set status = 'answered', due_on = null, last_entry_at = now()
   where m.id = v_vorgang.id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.answer_platform_message(p_message_id uuid, p_body text, p_attachment_id uuid, p_mark_seconds integer) IS 'KOM-002/005: Antwort der Praxis auf einen offenen oder beantworteten Vorgang (ANN-308), optional mit Zeitmarke in einem Video des Vorgangs (ADR-017 Punkt 68, ANN-338). Wer antworten darf: app.can_answer_platform_message (ANN-310, ANN-311).';

CREATE FUNCTION public.apply_retention() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_run       uuid := extensions.gen_random_uuid();
  v_org       record;
  v_akte      record;
  v_akten     integer;
  v_gehalten  integer;
  v_steuer    integer;
  v_verhaelt  record;
  v_training  integer;
  v_termine   integer;
  v_audit     integer;
  v_auftraege integer;
  v_journal   integer;
  v_zugang    integer;
  v_fotos     integer;
  v_warte     integer;
  v_aufgaben  integer;
  v_anrufe    integer;
  v_konten    integer;
  v_plattform integer;
  v_wuensche  integer;
  v_nachrichten integer;
  v_anhaenge  integer;
  v_radflotte integer;
  v_urlaub integer;
  v_arbeitszeit integer;
  v_zeitkonto integer;
  v_erstattung integer;
  v_rueckmeldung integer;
  v_teamchat     integer;
  v_ernaehrung   integer;
  v_gesamt    integer := 0;
begin
  for v_org in select o.id, o.time_zone from public.organizations o order by o.id
  loop
    v_akten    := 0;
    v_gehalten := 0;
    v_steuer   := 0;
    v_training := 0;

    -- -------------------------------------------------------------------
    -- Plattform, Teil 1 (POR-002, ADR-023 Punkt 5, ANN-189): Konten beim
    -- Anmeldedienst, 30 Tage nach dem Ende des letzten Zugangs. VOR den
    -- Verhaeltnissen: Solange das Verhaeltnis steht, ist das Ende seines
    -- Zugangs das Ende der Lesefrist (DSN-001 D2) und nicht der Tag, an dem
    -- der Lauf das Verhaeltnis loescht.
    -- -------------------------------------------------------------------
    v_konten := app.delete_due_platform_accounts(v_org.id, v_run);

    -- -------------------------------------------------------------------
    -- Patientenfotos: zwoelf Monate ab Aufnahme, spaetestens drei Monate
    -- nach dem festgehaltenen Abschluss, Widerruf (ADR-017 Punkt 38).
    -- Ein Legal Hold haelt an.
    -- -------------------------------------------------------------------
    v_fotos := app.delete_due_patient_photos(v_org.id, null, v_run, null, 'retention');

    -- -------------------------------------------------------------------
    -- Klinische Patientenakte: zehn Jahre nach Abschluss der Behandlung.
    --
    -- B1 (BEF-151, ADR-008 Fassung 3): Der Anker ist nicht mehr allein der
    -- ausdrueckliche Abschluss, sondern app.patient_retention_anchor - das
    -- spaeteste Datum aus letzter Behandlung, erfasster Leistung und einem
    -- etwaigen ausdruecklichen Abschluss. Eine Akte mit kuenftigem Termin
    -- faellt nie, und ohne jede Behandlung laeuft weiter keine Frist.
    -- -------------------------------------------------------------------
    for v_akte in
      select k.id, k.due_at
      from (
        select p.id,
               app.retention_due_at(
                 app.patient_retention_anchor(p.id),
                 app.retention_interval('patientenakte'),
                 v_org.time_zone
               ) as due_at
        from public.patients p
        where p.organization_id = v_org.id
      ) k
      join public.patients p on p.id = k.id
      where k.due_at is not null
        and k.due_at <= now()
        and not app.patient_has_upcoming_care(k.id)
      order by k.due_at
      for update of p skip locked
    loop
      if app.under_legal_hold(v_org.id, 'patient', v_akte.id) then
        v_gehalten := v_gehalten + 1;
        continue;
      end if;

      -- Neu mit ABR-003: Die steuerliche Frist einer ausgestellten Rechnung
      -- kann die zehn Jahre der Akte ueberdauern. Gesetzliche Aufbewahrung
      -- hat Vorrang vor der regulaeren Loeschung (ADR-008 Punkt 2).
      if app.billing_retention_due_at(v_akte.id, v_org.time_zone) > now() then
        v_steuer := v_steuer + 1;
        continue;
      end if;

      v_akten := v_akten + app.delete_patient_record(v_akte.id, v_run, v_akte.due_at);
    end loop;

    -- -------------------------------------------------------------------
    -- Trainingsverhaeltnis: drei Jahre ab Vertragsende (ADR-021 Punkt 4)
    --
    -- Eigene Schleife und nicht ein Zweig der Akte: Die Frist ist kuerzer,
    -- der Anker ein anderer, und die Rechtsgrundlage traegt die
    -- Heilbehandlungs-Ausnahme nicht. Ohne Vertragsende laeuft keine Frist -
    -- ein laufendes Training wird nie geloescht.
    --
    -- KEIN LEGAL HOLD, UND ZWAR ABSICHTLICH: Loeschsperren stehen heute auf
    -- Patientenebene (ANN-033); ein Hold auf ein Trainingsverhaeltnis ist
    -- nicht darstellbar und waere hier eine Pruefung ohne Gegenstand. Wer
    -- eine Loeschung anhalten muss, raeumt bis dahin contract_ended_on - der
    -- Anker ist genau dafuer ruecknehmbar gebaut (LEI-001). Eine Sperre in
    -- der Behandlung wirkt nicht hierher: Der Hold haengt am Verhaeltnis
    -- (ADR-021), und die gemeinsame Person haelt sie ueber die Akte.
    --
    -- SKIP LOCKED wie bei der Akte: ein Verhaeltnis, an dem gerade jemand
    -- arbeitet, kommt im naechsten Lauf erneut dran.
    -- -------------------------------------------------------------------
    for v_verhaelt in
      select t.id,
             app.retention_due_at(
               t.contract_ended_on,
               app.retention_interval('trainingsverhaeltnis'),
               v_org.time_zone
             ) as due_at
      from public.training_relationships t
      where t.organization_id = v_org.id
        and t.contract_ended_on is not null
        and app.retention_due_at(
              t.contract_ended_on,
              app.retention_interval('trainingsverhaeltnis'),
              v_org.time_zone
            ) <= now()
      order by t.contract_ended_on
      for update of t skip locked
    loop
      -- TRN-008 (ANN-183): Die steuerliche Frist der Belege kann die drei
      -- Jahre des Verhaeltnisses ueberdauern. Gesetzliche Aufbewahrung hat
      -- Vorrang vor der regulaeren Loeschung (ADR-008 Punkt 2) - dieselbe
      -- Regel wie an der Akte.
      if app.training_billing_retention_due_at(v_verhaelt.id, v_org.time_zone) > now() then
        v_steuer := v_steuer + 1;
        -- Zweitreview: gehalten werden nur die Belege und was sie tragen;
        -- der Rest faellt nach den drei Jahren aus ADR-021 Punkt 4.
        v_training := v_training
          + app.reduce_training_relationship(v_verhaelt.id, v_run, v_verhaelt.due_at);
        continue;
      end if;

      v_training := v_training
        + app.delete_training_relationship(v_verhaelt.id, v_run, v_verhaelt.due_at);
    end loop;

    -- -------------------------------------------------------------------
    -- Abgesagte Termine und No-shows ohne Behandlungsnachweis: drei Jahre
    -- ab Ende des Kalenderjahres der Absage beziehungsweise des Vermerks.
    --
    -- Haengt Dokumentation am Termin, gilt die Frist der Akte - der Termin
    -- ist dann Teil des Behandlungsnachweises (ADR-008 Punkt 2). Ein
    -- Vorgang mit Gebuehrenanlass bleibt stehen: er ist die Grundlage
    -- einer Forderung (ANN-035, CAL-014b). Die mit der Abrechnung
    -- angekuendigte Bedingung "ohne Rechnung" ist damit erfuellt: Eine
    -- Rechnung kann nur an einem dokumentierten Termin oder an einem
    -- Gebuehrenanlass haengen, und beide nimmt die Abfrage bereits aus.
    -- -------------------------------------------------------------------
    with faellig as (
      select a.id,
             a.organization_id,
             app.retention_due_at(
               (date_trunc(
                  'year',
                  coalesce(a.cancelled_at, a.no_show_recorded_at) at time zone v_org.time_zone
                ) + interval '1 year' - interval '1 day')::date,
               app.retention_interval('termin_ohne_nachweis'),
               v_org.time_zone
             ) as due_at
      from public.appointments a
      where a.organization_id = v_org.id
        and a.fee_basis is null
        -- CAL-026: NUR Praxistermine. Ein Trainingstermin faellt mit seinem
        -- Verhaeltnis (oben) und nach dessen Frist - nicht hier. Zwei Gruende,
        -- und beide sind hart: Diese Frist rechnet ab Kalenderjahresende statt
        -- ab Vertragsende, und die Sperrpruefung darunter laeuft ueber
        -- a.patient_id, der am Trainingstermin leer ist - eine Sperre am
        -- Verhaeltnis haette die Zeile nicht gehalten (ADR-022, Konsequenzen).
        and a.kind <> 'training'
        and (
          (a.status = 'cancelled' and a.cancelled_at is not null)
          or (a.status = 'no_show' and a.no_show_recorded_at is not null)
        )
        and not exists (
          select 1 from public.treatment_notes t where t.appointment_id = a.id
        )
        and not app.under_legal_hold(v_org.id, 'patient', a.patient_id)
    ),
    geloescht as (
      delete from public.appointments a
      using faellig f
      where a.id = f.id
        and f.due_at <= now()
      returning a.id, a.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'appointments', g.id, 'termin_ohne_nachweis', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_termine = row_count;

    -- -------------------------------------------------------------------
    -- Auditlog: drei Jahre ab dem Ereignis (ANN-029)
    -- -------------------------------------------------------------------
    -- LOG-EPIC-001: zwei Klassen (app.audit_retention_class), und ein Legal
    -- Hold haelt jede Zeile seiner Akte - ueber den Gegenstand oder
    -- context.patient_id, auch fuer zusammengefuehrte Doppelanlagen.
    with geloescht as (
      delete from public.audit_log a
      where a.organization_id = v_org.id
        and a.occurred_at < now() - app.retention_interval(app.audit_retention_class(a.action))
        and not app.audit_entry_held(v_org.id, a.subject_type, a.subject_id, a.context)
      returning a.id, a.organization_id, a.occurred_at, app.audit_retention_class(a.action) as klasse
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'audit_log', g.id, g.klasse,
           g.occurred_at + app.retention_interval(g.klasse)
    from geloescht g;
    get diagnostics v_audit = row_count;

    -- -------------------------------------------------------------------
    -- Quittierte Loeschauftraege der Ablage: drei Jahre ab der Quittung
    -- (LOG-EPIC-001). Offene Auftraege bleiben. Nicht im Journal: Ein
    -- Auftrag ist selbst der Nachweis einer Loeschung, kein Fachdatensatz.
    -- -------------------------------------------------------------------
    delete from public.storage_deletion_orders o
    where o.organization_id = v_org.id
      and o.receipted_at is not null
      and o.receipted_at < now() - app.retention_interval('loeschauftrag');
    get diagnostics v_auftraege = row_count;

    -- -------------------------------------------------------------------
    -- Loeschjournal: 60 Tage ab der Loeschung (ADR-012: Backups 30 Tage,
    -- dazu 30 Tage Puffer). Zuletzt, damit die Eintraege dieses Laufs nicht
    -- mitfallen.
    -- -------------------------------------------------------------------
    delete from public.deletion_journal j
    where j.organization_id = v_org.id
      and j.deleted_at < now() - app.retention_interval('loeschjournal');
    get diagnostics v_journal = row_count;

    -- -------------------------------------------------------------------
    -- Einladungen: zwoelf Monate nach Abschluss des Vorgangs (ANN-026)
    -- -------------------------------------------------------------------
    with faellig as (
      select i.id,
             i.organization_id,
             coalesce(
               i.accepted_at,
               i.revoked_at,
               case when i.status = 'pending' and i.expires_at <= now() then i.expires_at end
             ) + app.retention_interval('zugangseinladung') as due_at
      from public.staff_account_invitations i
      where i.organization_id = v_org.id
    ),
    geloescht as (
      delete from public.staff_account_invitations i
      using faellig f
      where i.id = f.id
        and f.due_at is not null
        and f.due_at <= now()
      returning i.id, i.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'staff_account_invitations', g.id, 'zugangseinladung', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_zugang = row_count;

    -- -------------------------------------------------------------------
    -- Warteliste: zwoelf Monate nach dem Schliessen (ANN-133). Offene
    -- Eintraege fallen nur mit der Akte. Ein Legal Hold an der Akte haelt.
    -- -------------------------------------------------------------------
    with faellig as (
      select w.id,
             w.organization_id,
             w.closed_at + app.retention_interval('warteliste') as due_at
      from public.waitlist_entries w
      where w.organization_id = v_org.id
        and w.status <> 'open'
        and w.closed_at is not null
        and not app.under_legal_hold(v_org.id, 'patient', w.patient_id)
    ),
    geloescht as (
      delete from public.waitlist_entries w
      using faellig f
      where w.id = f.id
        and f.due_at <= now()
      returning w.id, w.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'waitlist_entries', g.id, 'warteliste', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_warte = row_count;

    -- -------------------------------------------------------------------
    -- Aufgaben: zwoelf Monate nach dem Erledigen (ANN-142). Offene
    -- Aufgaben bleiben; mit Personenbezug fallen sie mit der Akte. Ein
    -- Legal Hold an der Akte haelt auch die erledigte Aufgabe.
    -- -------------------------------------------------------------------
    with faellig as (
      select k.id,
             k.organization_id,
             k.done_at + app.retention_interval('aufgabe') as due_at
      from public.tasks k
      where k.organization_id = v_org.id
        and k.status = 'done'
        and k.done_at is not null
        and (k.patient_id is null or not app.under_legal_hold(v_org.id, 'patient', k.patient_id))
    ),
    geloescht as (
      delete from public.tasks k
      using faellig f
      where k.id = f.id
        and f.due_at <= now()
      returning k.id, k.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'tasks', g.id, 'aufgabe', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_aufgaben = row_count;

    -- -------------------------------------------------------------------
    -- Anrufstand: vierzehn Tage nach dem Termin (ANN-144). Ein "nicht
    -- erreicht" soll kein Merkmal der Person werden (§20, IDEA-PRX-041).
    -- -------------------------------------------------------------------
    with faellig as (
      select c.id,
             c.organization_id,
             a.starts_at + app.retention_interval('anrufstand') as due_at
      from public.appointment_call_states c
      join public.appointments a on a.id = c.appointment_id
      where c.organization_id = v_org.id
        -- Ein Legal Hold an der Akte haelt auch den Anrufstand (ADR-008
        -- Punkt 7, Zweitreview).
        and not app.under_legal_hold(v_org.id, 'patient', a.patient_id)
    ),
    geloescht as (
      delete from public.appointment_call_states c
      using faellig f
      where c.id = f.id
        and f.due_at <= now()
      returning c.id, c.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'appointment_call_states', g.id, 'anrufstand', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_anrufe = row_count;

    -- -------------------------------------------------------------------
    -- Terminwuensche der Plattform (POR-009, ANN-246): zwoelf Monate nach
    -- der Antwort der Praxis bzw. dem Zurueckziehen. Offene Wuensche
    -- bleiben; mit dem Verhaeltnis fallen sie ohnehin (cascade). Ein Legal
    -- Hold an der Akte haelt auch den beantworteten Wunsch.
    -- -------------------------------------------------------------------
    with faellig as (
      select w.id,
             w.organization_id,
             w.resolved_at + app.retention_interval('terminwunsch') as due_at
      from public.platform_appointment_requests w
      where w.organization_id = v_org.id
        and w.status <> 'open'
        and w.resolved_at is not null
        and (w.patient_id is null or not app.under_legal_hold(v_org.id, 'patient', w.patient_id))
    ),
    geloescht as (
      delete from public.platform_appointment_requests w
      using faellig f
      where w.id = f.id
        and f.due_at <= now()
      returning w.id, w.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'platform_appointment_requests', g.id, 'terminwunsch', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_wuensche = row_count;

    -- -------------------------------------------------------------------
    -- KOM-005 (ADR-017 Punkt 65): Anhaenge an Rueckfragen, 30 Tage ab der
    -- Aufnahme oder ab ihrer Sperre. Vor den Vorgaengen: ein Anhang, der mit
    -- seinem Vorgang faellt, steht nicht doppelt im Journal. Ein Legal Hold
    -- an der Akte haelt (gesperrt, ANN-335).
    -- -------------------------------------------------------------------
    v_anhaenge := app.remove_message_attachments(v_org.id, 'due', null, v_run);

    -- -------------------------------------------------------------------
    -- FLT-001 (ANN-551): Radflotte - Schluessel 30 Tage nach der Rueckgabe,
    -- Sperren, Check-Ups und Pannen drei Jahre ab Ende des Kalenderjahres;
    -- offene nie. Ohne Patientenbezug, deshalb ohne Legal Hold der Akte.
    -- -------------------------------------------------------------------
    v_radflotte := app.delete_due_fleet_records(v_org.id, v_org.time_zone, v_run);

    -- -------------------------------------------------------------------
    -- URL-001 (ANN-579): Urlaub - genehmigte und stornierte Antraege und
    -- Ansprueche drei Jahre ab Ende des Urlaubsjahres, abgelehnte und
    -- zurueckgezogene ein Jahr nach ihrem Ende; offene nie. Ohne
    -- Patientenbezug, deshalb ohne Legal Hold der Akte.
    -- -------------------------------------------------------------------
    v_urlaub := app.delete_due_staff_leave(v_org.id, v_org.time_zone, v_run);

    -- -------------------------------------------------------------------
    -- AZ-001 (ANN-591): Arbeitszeitaenderungen - genehmigte drei Jahre ab
    -- Ende des Jahres ihrer Wirkung, abgelehnte und zurueckgezogene ein Jahr
    -- nach ihrem Ende; offene nie. Ohne Patientenbezug, ohne Legal Hold.
    -- -------------------------------------------------------------------
    v_arbeitszeit := app.delete_due_working_time_requests(v_org.id, v_org.time_zone, v_run);

    -- -------------------------------------------------------------------
    -- ZK-001 (ANN-597): Zeitkonto - gültige Einträge drei Jahre ab Ende
    -- ihres Jahres, ihr Saldo bleibt als Übertrag; zurückgewiesene und
    -- zurückgenommene ein Jahr nach ihrem Ende. Ohne Patientenbezug.
    -- -------------------------------------------------------------------
    v_zeitkonto := app.delete_due_time_account_entries(v_org.id, v_org.time_zone, v_run);

    -- -------------------------------------------------------------------
    -- ERS-001 (ANN-602): Erstattungen - ausgezahlte acht Jahre ab Ende des
    -- Jahres der Auszahlung (Par. 147 AO), abgelehnte und zurückgezogene ein
    -- Jahr; die Belege fallen mit, ihre Objekte über den Löschauftrag.
    -- -------------------------------------------------------------------
    v_erstattung := app.delete_due_reimbursements(v_org.id, v_org.time_zone, v_run);

    -- -------------------------------------------------------------------
    -- ORG-006 (ANN-607): Rückmeldungen von Beschäftigten - zwölf Monate ab
    -- Ende des Monats der Abgabe, endgültig; Teilnahmemarken nach ihrem
    -- Monat. Bewusst NICHT in der Zusammenfassung unten (ADR-010 Punkt 17,
    -- §20.2): Der Nachweis ist das Löschjournal.
    -- -------------------------------------------------------------------
    v_rueckmeldung := app.delete_due_staff_feedback(v_org.id, v_org.time_zone, v_run);
    -- TEAM-001: der Teamchat (ANN-610).
    v_teamchat := app.delete_due_team_messages(v_org.id, v_org.time_zone, v_run);
    -- ERN-001 (ANN-619): Ernährungsberatung - drei Jahre nach dem Ende des
    -- Profils; ein Legal Hold an der Akte hält.
    v_ernaehrung := app.delete_due_nutrition_profiles(v_org.id, v_org.time_zone, v_run);

    -- -------------------------------------------------------------------
    -- Nachrichten der Behandlung (KOM-001, ADR-008 "Organisatorische
    -- Patientenkommunikation", ANN-001): drei Jahre ab Ende des
    -- Kalenderjahres, in dem der Vorgang abgeschlossen wurde: erledigt, oder
    -- beantwortet und danach nichts mehr von der Person (Anker: die letzte
    -- Antwort; Zweitreview S1, ANN-308). Offene bleiben; der Akte
    -- zugeordnete (KOM-004, ANN-312) fallen erst mit ihr; im Training fallen
    -- sie mit dem Verhaeltnis (cascade). Ein Legal Hold an der Akte haelt.
    -- -------------------------------------------------------------------
    with faellig as (
      select m.id,
             m.organization_id,
             app.retention_due_at(
               (date_trunc('year', coalesce(m.closed_at, m.last_entry_at)
                                     at time zone v_org.time_zone)
                 + interval '1 year' - interval '1 day')::date,
               app.retention_interval('patientenkommunikation'),
               v_org.time_zone
             ) as due_at
      from public.platform_messages m
      where m.organization_id = v_org.id
        and m.relationship_kind = 'treatment'
        and m.status in ('closed', 'answered')
        and m.record_assigned_at is null
        and not app.under_legal_hold(v_org.id, 'patient', m.patient_id)
    ),
    geloescht as (
      delete from public.platform_messages m
      using faellig f
      where m.id = f.id
        and f.due_at <= now()
      returning m.id, m.organization_id
    )
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select g.organization_id, v_run, 'platform_messages', g.id, 'patientenkommunikation', f.due_at
    from geloescht g
    join faellig f on f.id = g.id;
    get diagnostics v_nachrichten = row_count;

    -- -------------------------------------------------------------------
    -- Plattform, Teil 2 (POR-002, ANN-189): Zugaenge mit ihren Einladungen,
    -- drei Jahre nach ihrem Ende. Nach den Verhaeltnissen oben: Ein im
    -- selben Lauf geloeschtes Verhaeltnis hat seinen Zugang da schon beendet.
    -- -------------------------------------------------------------------
    v_plattform := app.delete_due_platform_accesses(v_org.id, v_run);

    v_gesamt := v_gesamt + v_fotos + v_akten + v_training + v_termine + v_audit + v_zugang + v_warte
                + v_aufgaben + v_anrufe + v_konten + v_plattform + v_wuensche + v_nachrichten + v_anhaenge
                + v_radflotte + v_urlaub + v_arbeitszeit + v_zeitkonto + v_erstattung + v_rueckmeldung + v_teamchat
                + v_ernaehrung;

    if v_fotos + v_akten + v_training + v_termine + v_audit + v_zugang + v_warte + v_aufgaben + v_anrufe
       + v_konten + v_plattform + v_auftraege + v_journal + v_wuensche + v_nachrichten + v_anhaenge
       + v_radflotte + v_urlaub + v_arbeitszeit + v_zeitkonto + v_erstattung + v_teamchat + v_ernaehrung > 0
       or v_gehalten > 0 or v_steuer > 0 then
      insert into public.audit_log (
        organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
      )
      values (
        v_org.id, null, 'system', 'retention.applied', 'organization', v_org.id, 'success',
        jsonb_build_object(
          'surface', 'scheduler',
          'run_id', v_run,
          'patientenfoto', v_fotos,
          'patientenakte', v_akten,
          'trainingsverhaeltnis', v_training,
          'termin_ohne_nachweis', v_termine,
          'auditlog', v_audit,
          'loeschauftrag', v_auftraege,
          'loeschjournal', v_journal,
          'zugangseinladung', v_zugang,
          'warteliste', v_warte,
          'aufgabe', v_aufgaben,
          'anrufstand', v_anrufe,
          'plattformkonto', v_konten,
          'plattformzugang', v_plattform,
          'terminwunsch', v_wuensche,
          'patientenkommunikation', v_nachrichten,
          'rueckfrageanhang', v_anhaenge,
          'radflotte', v_radflotte,
          'urlaub', v_urlaub,
          'arbeitszeit', v_arbeitszeit,
          'zeitkonto', v_zeitkonto,
          'erstattung', v_erstattung,
          'teamchat', v_teamchat,
          'ernaehrungsberatung', v_ernaehrung,
          'legal_hold_gehalten', v_gehalten,
          'steuerfrist_gehalten', v_steuer
        )
      );
    end if;
  end loop;

  return v_gesamt;
end;
$$;

COMMENT ON FUNCTION public.apply_retention() IS 'Fuehrt den Loeschlauf ueber alle Datenklassen aus (ADR-008, LOE-002a). Seit ABR-003 haelt er eine Akte zurueck, solange die steuerliche Frist einer ihrer ausgestellten Rechnungen laeuft (Par. 147 AO, ADR-008 Punkt 2). Seit LEI-002 loescht er Trainingsverhaeltnisse nach eigener Frist und eigenem Anker (ADR-021 Punkt 4).';

CREATE FUNCTION public.appointments_context_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.kind is distinct from old.kind then
    raise exception 'appointment context cannot be changed' using errcode = '22023';
  end if;

  if new.training_relationship_id is distinct from old.training_relationship_id then
    raise exception 'training relationship cannot be changed' using errcode = '22023';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION public.appointments_context_guard() IS 'Der Terminkontext und das Verhaeltnis dahinter stehen mit dem Anlegen fest (ADR-022 Punkt 10). Ein falsch angelegter Termin wird abgesagt und neu angelegt, nicht umgedeutet.';

CREATE FUNCTION public.appointments_context_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is not null and not app.may_write_appointment_context(new.kind) then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION public.appointments_context_write_guard() IS 'Kein Durchgriff ueber den gemeinsamen Kalender beim Schreiben (TRN-004, ADR-022 Punkt 11): Wer einen Kontext nicht schreiben darf, findet den Termin nicht - auch ueber einen kuenftigen Schreibweg nicht.';

CREATE FUNCTION public.appointments_event_group_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.event_series_id is distinct from old.event_series_id then
    raise exception 'event series cannot be changed' using errcode = '22023';
  end if;

  if new.kind <> 'internal' then
    return new;
  end if;

  if app.ereignis_gruppenweise_aktiv() then
    return new;
  end if;

  if new.title            is distinct from old.title
     or new.starts_at        is distinct from old.starts_at
     or new.ends_at          is distinct from old.ends_at
     or new.appointment_type is distinct from old.appointment_type
     or new.location_id      is distinct from old.location_id
     or new.event_group_id   is distinct from old.event_group_id then
    raise exception 'event must be changed as a whole' using errcode = '22023';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION public.appointments_event_group_guard() IS 'Haelt die Zeilen eines Ereignisses zusammen: Bezeichnung, Zeit, Art und Ort aendert nur update_appointment_event, und dann fuer alle Beteiligten zugleich (CAL-017). Die Serienkennung aendert ueberhaupt kein Schreibweg (CAL-021). Der Wechsel der beteiligten Person, die Absage und das Wiederoeffnen einer einzelnen Teilnahme bleiben moeglich.';

CREATE FUNCTION public.appointments_event_series_stamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.kind = 'internal' and new.event_series_id is null then
    new.event_series_id := app.serie_kennung();
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION public.appointments_event_series_stamp() IS 'Traegt die laufende Serienkennung in ein neu angelegtes Ereignis ein (CAL-021). Ausserhalb von create_event_series ist sie nicht gesetzt, und die Zeile bleibt ohne Serie.';

CREATE FUNCTION public.appointments_fee_waiver_follows_fee() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.fee_basis is null then
    new.fee_waived_at := null;
    new.fee_waived_by := null;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.appointments_occasion_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.occasion is not distinct from old.occasion then
    return new;
  end if;
  if not (old.occasion = 'regular'
          and new.occasion = 'nutrition_counselling'
          and old.status = 'confirmed'
          and old.created_at = now()
          and not exists (select 1 from public.billable_services b where b.appointment_id = old.id)) then
    raise exception 'appointment occasion cannot be changed' using errcode = '22023';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.appointments_training_protocol_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.kind <> 'training' or new.status is not distinct from old.status then
    return new;
  end if;

  if new.status = 'documented' and not exists (
    select 1 from public.training_protocols p
    where p.appointment_id = new.id and p.status = 'final'
  ) then
    raise exception 'training appointment is documented only by a finalized training protocol'
      using errcode = '23514';
  end if;

  if new.status in ('cancelled', 'no_show') then
    if exists (
      select 1 from public.training_protocols p
      where p.appointment_id = new.id and p.status = 'final'
    ) then
      raise exception 'finalized training protocol exists for this appointment' using errcode = '22023';
    end if;

    -- ANN-186: Absage und Nichtantreffen sagen, dass die Einheit nicht
    -- stattgefunden hat; ein Entwurf daran faellt mit. Seit ABN-022
    -- (BEF-113) steht er im Loeschjournal und taucht nach einer
    -- Wiederherstellung nicht wieder auf; die Oberflaeche warnt vorher.
    with verworfen as (
      delete from public.training_protocols p
       where p.appointment_id = new.id and p.status = 'draft'
      returning p.id, p.organization_id, p.training_relationship_id
    )
    -- LOG-EPIC-001: der Verwurf steht im Loeschjournal, nicht im Auditlog.
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    select v.organization_id, extensions.gen_random_uuid(), 'training_protocols', v.id,
           'trainingsverhaeltnis', now()
    from verworfen v;
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION public.appointments_training_protocol_guard() IS 'Invariante am Trainingstermin (TRN-009, ADR-018 Punkt 3 nach ADR-022 Punkt 8): documented nur mit abgeschlossenem Trainingsprotokoll; keine Absage und kein Nichtantreffen neben einem abgeschlossenen Protokoll; ein Entwurf wird dabei verworfen und protokolliert (Zweitreview, ANN-186).';

CREATE FUNCTION public.approve_own_passkey(p_credential_id uuid, p_webauthn_id text DEFAULT NULL::text, p_public_key text DEFAULT NULL::text, p_public_key_alg integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_da boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.session_open() then
    raise exception 'session locked' using errcode = '42501';
  end if;
  -- Entweder alle drei oder keiner; die Form prueft der Constraint, der
  -- Fehler soll aber vor dem Blick in den Anmeldedienst stehen.
  if (p_webauthn_id is null) <> (p_public_key is null)
     or (p_public_key is null) <> (p_public_key_alg is null)
     or (p_webauthn_id is not null
         and (p_webauthn_id !~ '^[A-Za-z0-9_-]+$' or length(p_webauthn_id) not between 16 and 1366))
     or (p_public_key is not null
         and (p_public_key !~ '^[A-Za-z0-9+/]+={0,2}$' or length(p_public_key) not between 40 and 2048))
     or (p_public_key_alg is not null and p_public_key_alg not in (-7, -8, -257)) then
    raise exception 'invalid offline key' using errcode = '22023';
  end if;
  if to_regclass('auth.webauthn_credentials') is null then
    raise exception 'passkey not approvable' using errcode = 'P0001';
  end if;
  execute $q$
    select exists (
      select 1 from auth.webauthn_credentials c
      where c.id = $1 and c.user_id = $2 and c.created_at >= now() - $3
    )
  $q$ into v_da using p_credential_id, auth.uid(), app.pin_fresh_authentication();
  if not v_da then
    raise exception 'passkey not approvable' using errcode = 'P0001';
  end if;

  insert into public.passkey_approvals (credential_id, user_id, webauthn_id, public_key, public_key_alg)
  values (p_credential_id, auth.uid(), p_webauthn_id, p_public_key, p_public_key_alg)
  on conflict (credential_id) do nothing;

  -- Freigaben zu Passkeys, die es beim Anmeldedienst nicht mehr gibt.
  execute $q$
    delete from public.passkey_approvals a
    where a.user_id = $1
      and not exists (select 1 from auth.webauthn_credentials c where c.id = a.credential_id)
  $q$ using auth.uid();
end;
$_$;

COMMENT ON FUNCTION public.approve_own_passkey(p_credential_id uuid, p_webauthn_id text, p_public_key text, p_public_key_alg integer) IS 'Gibt einen Passkey des eigenen Kontos frei (ADR-025 Punkt 10, ANN-329): nur in offener Sitzung und hoechstens zehn Minuten nach dem Anlegen. Erst ein freigegebener Passkey oeffnet eine Sitzung. Wahlweise mit Kennung und oeffentlichem Schluessel fuer die Freigabe ohne Netz (TRK-009, ANN-359). Keine Auditzeile.';

CREATE FUNCTION public.archive_practice_food(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not app.can_counsel_nutrition() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.custom_foods p set archived_at = now(), updated_at = now(), updated_by = auth.uid()
  where p.id = p_id and p.organization_id = app.current_organization_id()
    and p.owner_kind = 'practice' and p.archived_at is null;
  if not found then
    raise exception 'food not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.archive_practice_food(p_id uuid) IS 'ERN-005: ein Lebensmittel der Praxis ablegen - es verschwindet aus Suche und Liste, bleibt für spätere Verweise erhalten. Allein app.can_counsel_nutrition.';

CREATE FUNCTION public.assign_exercise_plan(p_plan_id uuid, p_runs_until date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid := auth.uid();
  v_plan   public.exercise_plans%rowtype;
  v_heute  date;
  v_vorige public.exercise_plans%rowtype;
begin
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;
  perform app.exercise_plan_relationship_open(v_plan);

  if not exists (select 1 from public.exercise_plan_items i where i.plan_id = v_plan.id) then
    raise exception 'exercise plan has no exercises' using errcode = '22023';
  end if;

  v_heute := app.training_today(v_plan.organization_id);
  if p_runs_until is null or p_runs_until < v_heute
     or p_runs_until > v_heute + app.exercise_plan_max_days() then
    raise exception 'runs until is invalid' using errcode = '22023';
  end if;

  if v_plan.previous_plan_id is not null then
    select * into v_vorige
    from public.exercise_plans p
    where p.id = v_plan.previous_plan_id
    for update;
    if v_vorige.status = 'assigned' then
      update public.exercise_plans
         set status = 'superseded',
             ended_at = now(),
             ended_by = v_actor,
             updated_at = now(),
             updated_by = v_actor
       where id = v_vorige.id;
    end if;
  end if;

  -- Der Schnappschuss (ANN-300), seit UEB-012 mit dem Bild.
  update public.exercise_plan_items i
     set exercise_name = e.name,
         exercise_lay_name = e.lay_name,
         variant_name = v.name,
         variant_lay_name = v.lay_name,
         body_region = e.body_region,
         instruction = v.instruction,
         equipment = v.equipment,
         illustration = v.illustration
    from public.exercise_variants v
    join public.exercises e on e.id = v.exercise_id
   where i.plan_id = v_plan.id
     and v.id = i.variant_id;

  update public.exercise_plans
     set status = 'assigned',
         assigned_at = now(),
         assigned_by = v_actor,
         runs_from = v_heute,
         runs_until = p_runs_until,
         original_runs_until = p_runs_until,
         updated_at = now(),
         updated_by = v_actor
   where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.assign_exercise_plan(p_plan_id uuid, p_runs_until date) IS 'UEB-005/UEB-012: weist einen Entwurf mit mindestens einer Uebung zu - friert Bezeichnungen, Anleitung, Ausruestung, Bild und Dosierung ein (ANN-300), setzt die Laufzeit von heute bis p_runs_until (hoechstens 26 Wochen, ANN-302) und loest eine laufende vorige Fassung ab (ANN-301). Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.assign_platform_message_to_record(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorgang public.platform_messages%rowtype;
begin
  if auth.uid() is null or not app.may_read_platform_messages('any') then
    raise exception 'not allowed to assign platform messages' using errcode = '42501';
  end if;
  v_vorgang := app.practice_message(p_message_id, false);
  if not app.can_assign_platform_message(v_vorgang.relationship_kind) then
    raise exception 'not allowed to assign platform messages' using errcode = '42501';
  end if;
  if v_vorgang.record_assigned_at is not null then
    raise exception 'message already assigned' using errcode = '22023';
  end if;

  update public.platform_messages m
     set record_assigned_at = now(),
         record_assigned_by = auth.uid(),
         record_assigned_by_label = app.current_display_name()
   where m.id = v_vorgang.id and m.record_assigned_at is null;
end;
$$;

COMMENT ON FUNCTION public.assign_platform_message_to_record(p_message_id uuid) IS 'KOM-004 (ANN-312): einen Vorgang der Behandlung der Akte zuordnen - endgueltig, ohne den Inhalt zu veraendern. Wer und wann am Datensatz.';

CREATE FUNCTION public.assign_prescription_scan(p_file_id uuid, p_treatment_basis_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_datei record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_bases() then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = v_org
    and f.status = 'ready'
  for update;

  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  if v_datei.document_type <> 'verordnungsscan' then
    raise exception 'only a prescription scan can be assigned' using errcode = '22023';
  end if;

  if v_datei.treatment_basis_id is not null then
    raise exception 'prescription scan is already assigned' using errcode = '55000';
  end if;

  -- Nur an eine Grundlage derselben Patient:in in derselben Praxis: sonst
  -- traege der Scan eine fremde Akte.
  if not exists (
    select 1
    from public.treatment_bases tb
    where tb.id = p_treatment_basis_id
      and tb.organization_id = v_org
      and tb.patient_id = v_datei.patient_id
  ) then
    raise exception 'treatment basis not accessible' using errcode = '42501';
  end if;

  update public.patient_files
     set treatment_basis_id = p_treatment_basis_id
   where id = p_file_id;

end;
$$;

COMMENT ON FUNCTION public.assign_prescription_scan(p_file_id uuid, p_treatment_basis_id uuid) IS 'Haengt einen offenen Verordnungsscan an eine Grundlage derselben Patient:in (PRX-011) und protokolliert patient_file.assigned (ADR-010). Nur einmal, nur in diese Richtung; wer Grundlagen schreibt (ANN-011).';

CREATE FUNCTION public.auth_email_allowed(p_user_id uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_user_id is null or p_action is null then false
    -- Kein Kennwort, keine Wiederherstellung (ADR-025 Punkt 9).
    when p_action = 'recovery' then false
    -- Plattformkonten bekommen keine Mail des Anmeldedienstes (ADR-023
    -- Fassung 4, Punkt 18; die Einladung verschickt der Zugangsdienst).
    when app.is_platform_account(p_user_id) then false
    -- Praxiskonten: ein Anmeldelink nur zu einer offenen Einladung oder zu
    -- einem Anmeldelink, den die Inhaberin vor höchstens einer Stunde
    -- angestoßen hat (ADR-025 Punkt 12, ANN-328, ANN-331).
    when p_action = 'magiclink' then
      exists (
        select 1
        from public.staff_account_invitations i
        join auth.users u on u.id = p_user_id
        where i.email = lower(u.email)
          and i.status = 'pending'
          and i.expires_at > now()
      )
      or exists (
        select 1
        from public.audit_log a
        join public.staff_members sm on sm.id = a.subject_id
        join public.user_profiles up
          on up.person_id = sm.person_id and up.organization_id = sm.organization_id
        where up.id = p_user_id
          and a.action = 'staff_account.password_reset_requested'
          and a.subject_type = 'staff_member'
          and a.occurred_at > now() - interval '1 hour'
      )
    else true
  end
$$;

COMMENT ON FUNCTION public.auth_email_allowed(p_user_id uuid, p_action text) IS 'Darf der Anmeldedienst diese Mail an dieses Konto schicken? Nie einen Wiederherstellungslink; Plattformkonten nichts; Praxiskonten einen Anmeldelink nur zu offener Einladung oder frisch angestoßenem Anmeldelink (ADR-025 Fassung 2, ANN-331). Nur service_role (Mail-Hook des Zugangsdienstes).';

CREATE FUNCTION public.block_fleet_bike(p_bike_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_reason text;
  v_id     uuid;
begin
  v_org := app.fleet_org(app.can_release_fleet_bike(), 'not allowed to block or release bikes');
  perform 1 from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
  for update;
  if not found then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  v_reason := app.fleet_text(p_reason, 200, 'reason');
  if v_reason is null then
    raise exception 'reason is required' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.fleet_blocks b where b.bike_id = p_bike_id and b.released_at is null
  ) then
    raise exception 'bike is already blocked' using errcode = '55000';
  end if;
  insert into public.fleet_blocks (organization_id, bike_id, reason, blocked_by)
  values (v_org, p_bike_id, v_reason, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.block_fleet_bike(p_bike_id uuid, p_reason text) IS 'FLT-001 (ANN-550): Rad von Hand sperren, mit Grund ("Inspektion in der Werkstatt"). owner und team_lead.';

CREATE FUNCTION public.cancel_aftercare_subscription(p_subscription_id uuid) RETURNS date
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ende date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    raise exception 'not allowed to manage aftercare subscriptions' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.aftercare_subscriptions s
    where s.id = p_subscription_id and s.organization_id = app.current_organization_id()
  ) then
    raise exception 'aftercare subscription not found' using errcode = '42501';
  end if;

  select c.ends_on into v_ende
  from app.cancel_aftercare(p_subscription_id, 'practice', null, null, null) c;
  return v_ende;
end;
$$;

COMMENT ON FUNCTION public.cancel_aftercare_subscription(p_subscription_id uuid) IS 'ANG-003: eine Kuendigung des Nachsorge-Abos eintragen, die bei der Praxis einging (owner, office). Wirkt zum Ende des laufenden Abo-Monats (ANN-270); liefert das Ende.';

CREATE FUNCTION public.cancel_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone, p_reason text, p_received_on date, p_received_time time without time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_tz      text;
  v_alt     record;
  v_eingang timestamptz;
  v_anlass  text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- TRN-004: wie update_appointment - der Riegel an der Zeile entscheidet den Kontext.
  if not (app.can_cancel_appointment() or app.can_write_training_relationships()) then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  -- Die Pflichtangabe wird vor jedem Lesen geprueft: eine unvollstaendige
  -- Eingabe darf nicht erst an der Constraint scheitern.
  if p_reason is null
     or p_reason not in ('patient_request', 'practice_request', 'patient_moved', 'practice_moved', 'other') then
    raise exception 'cancellation reason is required' using errcode = '22023';
  end if;

  -- Halb angegeben ist nicht angegeben: Ein Datum ohne Uhrzeit waere
  -- Mitternacht, und das ist eine Erfindung, keine Angabe.
  if (p_received_on is null) <> (p_received_time is null) then
    raise exception 'cancellation receipt needs date and time' using errcode = '22023';
  end if;

  if p_received_on is null then
    v_eingang := now();
  else
    select o.time_zone into v_tz from public.organizations o where o.id = v_org;
    if v_tz is null then
      raise exception 'organization has no time zone' using errcode = '22023';
    end if;
    v_eingang := (p_received_on + p_received_time) at time zone v_tz;
  end if;

  -- Eine Absage, die noch nicht eingegangen ist, gibt es nicht. Ohne diese
  -- Grenze liesse sich die Frist durch ein Datum in der Zukunft aushebeln.
  if v_eingang > now() then
    raise exception 'cancellation cannot be received in the future' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.staff_member_id, a.status, a.kind, a.starts_at, a.updated_at, a.occasion,
         a.training_relationship_id
    into v_alt
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_alt.status = 'cancelled' then
    raise exception 'appointment is already cancelled' using errcode = '22023';
  end if;

  if v_alt.status in ('completed', 'no_show') then
    raise exception 'completed appointment must be reopened first' using errcode = '22023';
  end if;

  if v_alt.status <> 'confirmed' then
    raise exception 'documented appointment cannot be changed' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  -- Die Frist rechnet der Server, aus dem Eingang und dem VEREINBARTEN Beginn
  -- des Termins - nie aus der Eingabezeit und nie im Browser
  -- (PROJECT_PRINCIPLES.md 8).
  --
  -- Und nur an einer BEHANDLUNG: Ein Ereignis des Praxisbetriebs hat keine
  -- Patient:in, die absagen koennte, und keinen Behandlungsbeginn, auf den
  -- sich eine Frist beziehen liesse (CAL-016, 8.1).
  -- ANN-178: Auch am Trainingstermin nicht - ob der Anlass im Dienstvertrag
  -- ueber Training entsteht, ist eine offene Vertragsfrage (ADR-022).
  v_anlass := case
    -- ERN-011 (ANN-664): Die Ernaehrungsberatung ist keine Behandlung.
    when v_alt.kind = 'therapy' and v_alt.occasion = 'regular'
     and app.is_late_cancellation(p_reason, v_eingang, v_alt.starts_at) then 'late_cancellation'
    else null
  end;

  update public.appointments
     set status                   = 'cancelled',
         cancellation_reason      = p_reason,
         cancellation_received_at = v_eingang,
         fee_basis                = v_anlass,
         cancelled_at             = now(),
         cancelled_by             = v_actor,
         updated_at               = now()
   where id = p_appointment_id
     and updated_at = p_expected_updated_at
     and status = 'confirmed';

  if not found then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;


  return p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.cancel_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone, p_reason text, p_received_on date, p_received_time time without time zone) IS 'Sagt einen bestaetigten Termin mit Pflichtgrund ab, haelt den Eingang der Absage in Ortszeit fest, rechnet die 24-Stunden-Frist serverseitig und protokolliert appointment.cancelled (CAL-003, CAL-008b, CAL-014b, CAL-016, ADR-018 Fassung 2). Ein Gebuehrenanlass entsteht nur an einer Behandlung. Datum und Uhrzeit beide null heisst "jetzt".';

CREATE FUNCTION public.cancel_appointment_event(p_event_group_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_stand  timestamptz;
  v_zeile  record;
  v_anzahl integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Dieselbe Pruefung wie in der aufgerufenen Funktion, hier nur damit die
  -- Meldung die Ursache trifft statt auf halbem Weg zu scheitern.
  if not app.can_cancel_appointment() then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  if p_event_group_id is null or p_expected_updated_at is null then
    raise exception 'event and expected updated_at are required' using errcode = '22023';
  end if;

  perform 1
  from public.appointments a
  where a.organization_id = v_org
    and a.event_group_id  = p_event_group_id
    and a.kind = 'internal'
  for update;

  select max(a.updated_at) into v_stand
  from public.appointments a
  where a.organization_id = v_org
    and a.event_group_id  = p_event_group_id
    and a.kind = 'internal';

  if v_stand is null then
    raise exception 'event not found' using errcode = 'P0002';
  end if;

  if v_stand is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  for v_zeile in
    select a.id, a.updated_at
    from public.appointments a
    where a.organization_id = v_org
      and a.event_group_id  = p_event_group_id
      and a.status = 'confirmed'
    order by a.staff_member_id
  loop
    perform public.cancel_appointment(v_zeile.id, v_zeile.updated_at, p_reason, null, null);
    v_anzahl := v_anzahl + 1;
  end loop;

  -- Kein eigenes Sammelereignis: je Absage steht ein appointment.cancelled im
  -- Auditlog, und das ist der auditpflichtige Vorgang (ADR-010).
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.cancel_appointment_event(p_event_group_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) IS 'Sagt alle noch bestaetigten Zeilen EINES Ereignisses in einer Transaktion ab und liefert ihre Anzahl (CAL-017). Erwartet den juengsten Stand der Gruppe. Ein Gebuehrenanlass entsteht dabei nie (CAL-016).';

CREATE FUNCTION public.cancel_appointment_from_request(p_request_id uuid, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_wunsch  record;
  v_zone    text;
  v_eingang timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  select w.id, w.appointment_id, w.created_at, w.kind into v_wunsch
  from public.platform_appointment_requests w
  where w.id = p_request_id and w.organization_id = v_org and w.status = 'open'
  for update;
  if not found then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if v_wunsch.kind <> 'cancel' or v_wunsch.appointment_id is null then
    raise exception 'request is not a cancellation' using errcode = '22023';
  end if;

  -- D4, ANN-247: Als Eingang gilt der Zeitpunkt des Wunsches. cancel_appointment
  -- rechnet daraus die Frist (ADR-018 Punkt 8) und prueft Rolle, Zustand und
  -- Gleichzeitigkeit wie bei jeder Absage. Der Eingang geht als Datum und
  -- Uhrzeit in Ortszeit hinein - dieselbe Schnittstelle wie die Oberflaeche.
  select o.time_zone into v_zone from public.organizations o where o.id = v_org;
  v_eingang := v_wunsch.created_at;

  perform public.cancel_appointment(
    v_wunsch.appointment_id,
    p_expected_updated_at,
    'patient_request',
    (v_eingang at time zone v_zone)::date,
    (v_eingang at time zone v_zone)::time
  );

  update public.platform_appointment_requests
     set status = 'done', resolved_at = now(), resolved_by = auth.uid()
   where id = p_request_id;

  return v_wunsch.appointment_id;
end;
$$;

COMMENT ON FUNCTION public.cancel_appointment_from_request(p_request_id uuid, p_expected_updated_at timestamp with time zone) IS 'POR-011 (DSN-001 D4, ANN-247): Die Praxis traegt die Absage aus einem Absagewunsch ein: Grund patient_request, Eingang = Zeitpunkt des Wunsches, Frist und Protokoll wie cancel_appointment. Der Wunsch wird erledigt.';

CREATE FUNCTION public.cancel_event_series(p_event_series_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org       uuid;
  v_stand     timestamptz;
  v_vorkommen record;
  v_anzahl    integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_cancel_appointment() then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  if p_event_series_id is null or p_expected_updated_at is null then
    raise exception 'event series and expected updated_at are required' using errcode = '22023';
  end if;

  perform 1
  from public.appointments a
  where a.organization_id = v_org
    and a.event_series_id = p_event_series_id
  for update;

  select max(a.updated_at) into v_stand
  from public.appointments a
  where a.organization_id = v_org
    and a.event_series_id = p_event_series_id;

  if v_stand is null then
    raise exception 'event series not found' using errcode = 'P0002';
  end if;

  if v_stand is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  for v_vorkommen in
    select a.event_group_id,
           max(a.updated_at) as stand
    from public.appointments a
    where a.organization_id = v_org
      and a.event_series_id = p_event_series_id
    group by a.event_group_id
    having min(a.starts_at) > now()
       and count(*) filter (where a.status = 'confirmed') > 0
    order by min(a.starts_at)
  loop
    perform public.cancel_appointment_event(
      v_vorkommen.event_group_id,
      v_vorkommen.stand,
      p_reason
    );
    v_anzahl := v_anzahl + 1;
  end loop;

  -- Kein eigenes Sammelereignis: je Absage steht ein appointment.cancelled im
  -- Auditlog, und das ist der auditpflichtige Vorgang (ADR-010).
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.cancel_event_series(p_event_series_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) IS 'Sagt alle noch nicht begonnenen Vorkommen einer Serie gleichartiger Ereignisse in einer Transaktion ab und liefert ihre Anzahl (CAL-021, ANN-059). Begonnene Vorkommen bleiben stehen. Ein Gebuehrenanlass entsteht dabei nie (CAL-016).';

CREATE FUNCTION public.cancel_invoice(p_invoice_id uuid, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_invoice  record;
  v_zeitzone text;
  v_heute    date;
  v_prefix   text;
  v_nummer   text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.* into v_invoice
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  -- Ein Entwurf wird verworfen, nicht storniert: Er traegt keine Nummer und
  -- hinterlaesst keine Luecke (ADR-009, Konsequenz zu Punkt 8).
  if v_invoice.status <> 'issued' then
    raise exception 'only an issued invoice can be cancelled' using errcode = '23514';
  end if;

  if exists (
    select 1 from public.invoice_cancellations c where c.invoice_id = p_invoice_id
  ) then
    raise exception 'invoice is already cancelled' using errcode = '23514';
  end if;

  -- Ein Storno ohne Grund waere ein Beleg ohne Aussage - dieselbe Zusage wie
  -- beim Zahlungsstorno (ABR-004).
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'a cancellation needs a reason' using errcode = '22023';
  end if;

  -- ABN-008 (BEF-100): Eine stehende Zahlung sperrt das Storno nicht mehr.
  -- Ein tatsaechlich eingegangener Betrag darf nicht verschwinden; er bleibt
  -- an der stornierten Rechnung stehen, bis er zurueckgezahlt oder mit der
  -- Ersatzrechnung verrechnet ist. Ein Zahlungsstorno korrigiert nur eine
  -- falsche Buchung (ANN-079 Fassung 2).

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  v_prefix := app.invoice_number_prefix(v_org, v_invoice.service_area);

  if v_prefix is null then
    raise exception 'practice billing profile missing' using errcode = '22023';
  end if;

  v_nummer := app.next_invoice_number(
    v_org, extract(year from v_heute)::smallint, v_invoice.service_area, v_prefix);

  insert into public.invoice_cancellations (
    organization_id, invoice_id, cancellation_number, reason, cancelled_on, created_by
  )
  values (v_org, p_invoice_id, v_nummer, btrim(p_reason), v_heute, v_actor);

  -- Die Leistungen sind wieder abrechenbar. Beides gehoert zusammen: die
  -- Freigabe der Zeile und der Zustand der Leistung; nur eines von beiden
  -- liesse die Leistung entweder unsichtbar oder doppelt abrechenbar.
  update public.invoice_items it
     set released_at = now()
   where it.invoice_id = p_invoice_id
     and it.released_at is null;

  update public.billable_services b
     set status = 'billable'
   where b.id in (
     select it.billable_service_id
     from public.invoice_items it
     where it.invoice_id = p_invoice_id
   );


  return v_nummer;
end;
$$;

COMMENT ON FUNCTION public.cancel_invoice(p_invoice_id uuid, p_reason text) IS 'Storniert eine ausgestellte Rechnung mit Grund und gibt ihre Leistungen wieder frei (ABR-003c, ADR-009 Punkt 9). Die Rechnung selbst bleibt unveraendert; das Stornodokument traegt eine eigene Nummer aus dem Kreis **ihres** Leistungsbereichs (ABR-010, Punkt 17).';

CREATE FUNCTION public.cancel_platform_aftercare(p_access_id uuid, p_subscription_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_ende   record;
begin
  if not app.platform_access_allows(p_access_id, 'contract') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  if v_zugang.relationship_kind <> 'treatment' or not exists (
    select 1 from public.aftercare_subscriptions s
    where s.id = p_subscription_id
      and s.patient_id = v_zugang.relationship_id
      and s.organization_id = v_zugang.organization_id
  ) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;

  select c.* into v_ende
  from app.cancel_aftercare(
    p_subscription_id, 'platform', v_zugang.id, v_zugang.access_kind,
    case when v_zugang.access_kind = 'legal_representative' then v_zugang.representative_name end
  ) c;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'aftercare_cancelled')
  );

  return jsonb_build_object(
    'ends_on', v_ende.ends_on,
    'cancelled_at', v_ende.cancelled_at,
    'cancelled_on', v_ende.cancelled_on
  );
end;
$$;

COMMENT ON FUNCTION public.cancel_platform_aftercare(p_access_id uuid, p_subscription_id uuid) IS 'ANG-003 (ANN-272, ANN-273): der Kuendigungsknopf der Plattform. Recht contract (Person, rechtliche Vertretung mit Vermoegenssorge). Wirkt zum Ende des laufenden Abo-Monats und liefert die Bestaetigung mit Zeitpunkt.';

CREATE FUNCTION public.cancel_staff_day(p_staff_member_id uuid, p_date date, p_reason text, p_appointment_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_tz      text;
  v_start   timestamptz;
  v_end     timestamptz;
  v_termin  record;
  v_anzahl  integer := 0;
  v_passend integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Die aufgerufene Funktion prueft dasselbe Recht noch einmal. Hier steht es,
  -- damit die Meldung die Ursache trifft, statt auf halbem Weg zu scheitern.
  if not app.can_cancel_appointment() then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to cancel appointments' using errcode = '42501';
  end if;

  if p_staff_member_id is null or p_date is null then
    raise exception 'staff member and date are required' using errcode = '22023';
  end if;

  -- Der Ausfall einer behandelnden Person ist praxisbedingt. Der Grund bleibt
  -- eine Angabe - aber nicht jede (CAL-016).
  if p_reason is null or p_reason not in ('practice_request', 'practice_moved', 'other') then
    raise exception 'day rescheduling needs a practice reason' using errcode = '22023';
  end if;

  -- Eine leere Auswahl sagt nichts ab - das ist kein Umplanen, sondern ein
  -- Fehlgriff der Seite. Eine leere Kennung passt zu keinem Termin
  -- (Zweitreview Überholung 6).
  if p_appointment_ids is not null and cardinality(p_appointment_ids) = 0 then
    raise exception 'appointment selection is empty' using errcode = '22023';
  end if;
  if p_appointment_ids is not null
     and exists (select 1 from unnest(p_appointment_ids) as x where x is null) then
    raise exception 'appointment selection does not match the day' using errcode = '22023';
  end if;

  -- Zielsatz ausschliesslich in der eigenen Organisation suchen; sonst waere
  -- die Funktion ein Orakel fuer fremde Mitarbeiter-IDs
  -- (PROJECT_PRINCIPLES.md 13).
  if not exists (
    select 1 from public.staff_members sm
    where sm.id = p_staff_member_id
      and sm.organization_id = v_org
  ) then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  select o.time_zone into v_tz
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  -- Halboffenes Fenster [Tag 00:00, Folgetag 00:00) in der Zeitzone der Praxis
  -- - dieselbe Auslegung wie in list_day_plan und list_appointments.
  v_start := (p_date::timestamp) at time zone v_tz;
  v_end   := ((p_date + 1)::timestamp) at time zone v_tz;

  -- Die Auswahl passt zum Tag: jede Kennung genau ein bestätigter
  -- Behandlungstermin dieser Person an diesem Tag. Doppelte Kennungen zählen
  -- einmal. Gesperrt wird erst in der Schleife.
  if p_appointment_ids is not null then
    select count(*) into v_passend
    from public.appointments a
    where a.id = any (p_appointment_ids)
      and a.organization_id = v_org
      and a.staff_member_id = p_staff_member_id
      and a.starts_at >= v_start
      and a.starts_at <  v_end
      and a.status = 'confirmed'
      and a.kind = 'therapy';
    if v_passend <> (select count(distinct x) from unnest(p_appointment_ids) as x) then
      raise exception 'appointment selection does not match the day' using errcode = '22023';
    end if;
  end if;

  -- FOR UPDATE ohne SKIP LOCKED: ein Termin, an dem gerade jemand arbeitet,
  -- soll die Umplanung aufhalten und nicht stillschweigend stehen bleiben.
  for v_termin in
    select a.id, a.updated_at
    from public.appointments a
    where a.organization_id = v_org
      and a.staff_member_id = p_staff_member_id
      and a.starts_at >= v_start
      and a.starts_at <  v_end
      and a.status = 'confirmed'
      and a.kind = 'therapy'
      and (p_appointment_ids is null or a.id = any (p_appointment_ids))
    order by a.starts_at, a.id
    for update
  loop
    perform public.cancel_appointment(v_termin.id, v_termin.updated_at, p_reason, null, null);
    v_anzahl := v_anzahl + 1;
  end loop;

  -- Zwischen Prüfung und Sperre kann ein Termin der Auswahl abgeschlossen oder
  -- abgesagt worden sein: dann gilt die Auswahl nicht mehr, und alles wird
  -- zurückgenommen.
  if p_appointment_ids is not null and v_anzahl <> v_passend then
    raise exception 'appointment selection does not match the day' using errcode = '22023';
  end if;

  -- Kein Sammelereignis und kein Auditeintrag: Je Termin weisen
  -- cancelled_by und cancelled_at die Absage nach (ADR-010 Punkt 15, seit
  -- LOG-001b); ein Eintrag "Tag umgeplant" hielte dieselbe Tatsache ein zweites
  -- Mal fest.
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.cancel_staff_day(p_staff_member_id uuid, p_date date, p_reason text, p_appointment_ids uuid[]) IS 'CAL-009, Überholung 6 (ANN-574): sagt die bestaetigten Behandlungstermine einer Person an einem Tag in einem Vorgang ab - alle oder genau die Auswahl (p_appointment_ids), die zum Tag passen muss. Praxisbedingter Grund Pflicht; Ereignisse des Praxisbetriebs bleiben. Nachweis je Termin cancelled_by/cancelled_at, kein Auditeintrag (ADR-010 Punkt 15).';

CREATE FUNCTION public.check_appointment_slots(p_staff_member_id uuid, p_slots jsonb) RETURNS TABLE(slot_index integer, conflict text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_tz      text;
  v_grid    smallint;
  v_heute   date;
  v_dauer   interval;
  v_anzahl  integer;
  v_i       integer;
  v_j       integer;
  v_daten   date[] := array[]::date[];
  v_zeiten  time[] := array[]::time[];
  v_datum   date;
  v_beginn  time;
  v_ende    time;
  v_von     timestamptz;
  v_bis     timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_create_appointment() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to create appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  -- Ohne diese Pruefung waere die Funktion ein Existenz-Orakel fuer fremde
  -- Mitarbeitende (dieselbe Meldung wie in create_appointment).
  if not app.is_assignable_therapist(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;

  if p_slots is null or jsonb_typeof(p_slots) <> 'array' then
    raise exception 'slots must be an array' using errcode = '22023';
  end if;

  if jsonb_array_length(p_slots) > app.appointment_series_limit() then
    raise exception 'series is limited to % appointments', app.appointment_series_limit()
      using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes
    into v_tz, v_grid
  from public.organizations o
  where o.id = v_org;

  v_heute  := (now() at time zone v_tz)::date;
  v_dauer  := make_interval(mins => app.appointment_window_minutes());
  v_anzahl := jsonb_array_length(p_slots);

  -- Erster Durchgang: einlesen. Was sich nicht lesen laesst, wird null und
  -- bekommt im zweiten Durchgang den Befund 'invalid'. Getrennt, weil die
  -- Pruefung auf Doppelungen die Zeilen davor bereits geparst braucht.
  for v_i in 0 .. v_anzahl - 1 loop
    begin
      v_daten[v_i]  := (p_slots -> v_i ->> 'datum')::date;
      v_zeiten[v_i] := (p_slots -> v_i ->> 'beginn')::time;
    exception
      when others then
        v_daten[v_i]  := null;
        v_zeiten[v_i] := null;
    end;
  end loop;

  for v_i in 0 .. v_anzahl - 1 loop
    slot_index := v_i;
    conflict := null;
    v_datum  := v_daten[v_i];
    v_beginn := v_zeiten[v_i];

    -- time + interval laeuft ueber Mitternacht um: 23:30 plus 60 Minuten
    -- ergibt 00:30. Ein Termin ueber den Tageswechsel ist keiner (8.1 rechnet
    -- in Ortszeit), deshalb ist das hier ungueltig und nicht der Folgetag.
    v_ende := case when v_beginn is null then null else v_beginn + v_dauer end;

    if v_datum is null or v_beginn is null or v_ende <= v_beginn then
      conflict := 'invalid';
    elsif v_datum < v_heute then
      conflict := 'past';
    elsif not app.is_on_appointment_grid(v_beginn, v_grid) then
      conflict := 'off_grid';
    else
      v_von := (v_datum + v_beginn) at time zone v_tz;
      v_bis := v_von + v_dauer;

      -- Ueberschneidung innerhalb derselben Serie. Muss vor der Pruefung gegen
      -- die Datenbank stehen: dort stehen die anderen Zeilen noch nicht.
      for v_j in 0 .. v_i - 1 loop
        if v_daten[v_j] is not null and v_zeiten[v_j] is not null
           and (v_daten[v_j] + v_zeiten[v_j]) at time zone v_tz < v_bis
           and ((v_daten[v_j] + v_zeiten[v_j]) at time zone v_tz) + v_dauer > v_von then
          conflict := 'duplicate';
          exit;
        end if;
      end loop;

      if conflict is null
         and exists (
           select 1
           from public.appointments a
           where a.organization_id = v_org
             and a.staff_member_id = p_staff_member_id
             and a.status <> 'cancelled'
             and tstzrange(a.starts_at, a.ends_at, '[)')
                 && tstzrange(v_von, v_bis, '[)')
         ) then
        conflict := 'overlap';
      end if;

      if conflict is null
         and not app.is_within_working_hours(
           p_staff_member_id, v_org, v_datum, v_beginn, v_ende
         ) then
        conflict := 'outside_working_hours';
      end if;
    end if;

    return next;
  end loop;
end;
$$;

COMMENT ON FUNCTION public.check_appointment_slots(p_staff_member_id uuid, p_slots jsonb) IS 'Prueft geplante Terminzeiten einer Serie je Zeile und aendert nichts (CAL-007). Liefert ein Befundwort, nicht den kollidierenden Termin.';

CREATE FUNCTION public.check_dictation_access(p_appointment_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    -- Ausgang der Pruefpfade (G6b): false und ein access.denied-Eintrag.
    perform app.record_denied_read(
      v_actor, 'treatment_note.dictated', 'not allowed to dictate treatment documentation'
    );
    return false;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    return false;
  end if;

  return exists (
    select 1
    from public.appointments a
    where a.id = p_appointment_id
      and a.organization_id = v_org
      and a.kind = 'therapy'
      and a.status not in ('cancelled', 'no_show')
  );
end;
$$;

COMMENT ON FUNCTION public.check_dictation_access(p_appointment_id uuid) IS 'KI-001 (BEF-153, ADR-005): Darf die angemeldete Person zu diesem Behandlungstermin diktieren? Aufgerufen nur vom AI Gateway mit dem Token der Person. Ohne Schreibrecht false mit access.denied (treatment_note.dictated); sonst schreibt die Funktion nichts.';

CREATE FUNCTION public.check_territory_days(p_postal_code text, p_slots jsonb) RETURNS TABLE(slot_index integer, status text, territory_name text, day_parts jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_i      integer;
  v_datum  date;
  v_beginn time;
  v_name   text;
  v_teile  jsonb;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to read territories' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read territories' using errcode = '42501';
  end if;
  if p_slots is null or jsonb_typeof(p_slots) <> 'array' then
    raise exception 'slots must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(p_slots) > app.appointment_series_limit() then
    raise exception 'too many slots' using errcode = '22023';
  end if;

  select t.name, t.day_parts into v_name, v_teile
  from public.territory_postal_codes pc
  join public.territories t on t.id = pc.territory_id
  where pc.organization_id = v_org
    and pc.postal_code = btrim(coalesce(p_postal_code, ''));

  for v_i in 0 .. jsonb_array_length(p_slots) - 1 loop
    slot_index := v_i;
    begin
      v_datum  := (p_slots -> v_i ->> 'datum')::date;
      v_beginn := (p_slots -> v_i ->> 'beginn')::time;
    exception
      when others then
        v_datum := null;
        v_beginn := null;
    end;
    if v_datum is null or v_beginn is null then
      status := 'invalid';
      territory_name := null;
      day_parts := null;
    else
      status := app.territory_day_status(v_org, p_postal_code, v_datum, v_beginn);
      territory_name := case when status = 'none' then null else v_name end;
      day_parts := case when status = 'none' then null else v_teile end;
    end if;
    return next;
  end loop;
end;
$$;

COMMENT ON FUNCTION public.check_territory_days(p_postal_code text, p_slots jsonb) IS 'Hinweis Gebietstag (PRX-002): je Termin none, match, outside oder invalid samt Gebiet. Warnt, sperrt nichts. Rollen der Terminverwaltung.';

CREATE FUNCTION public.check_travel_buffers(p_legs jsonb) RETURNS TABLE(from_appointment_id uuid, to_appointment_id uuid, travel_seconds integer, earliest_start timestamp with time zone, shortfall_minutes integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org  uuid;
  v_tz   text;
  v_grid integer;
  v_leg  jsonb;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_legs is null or jsonb_typeof(p_legs) <> 'array' or jsonb_array_length(p_legs) > 25 then
    raise exception 'legs must be an array of at most 25 pairs' using errcode = '22023';
  end if;

  -- Jedes Paar vollstaendig und wohlgeformt - ein fehlender Schluessel
  -- ergaebe sonst NULL, und NULL loest kein IF aus: Ein Paar ohne Fahrzeit
  -- kaeme als "passt" zurueck. Deshalb die Pruefung als positive Aussage,
  -- deren NULL mit coalesce als "ungueltig" gilt.
  for v_leg in select * from jsonb_array_elements(p_legs) loop
    -- CASE statt AND: Die Umwandlung in eine Zahl darf erst laufen, wenn
    -- feststeht, dass eine Zahl da ist.
    if not coalesce(
      case
        when jsonb_typeof(v_leg) = 'object'
         and jsonb_typeof(v_leg -> 'travel_seconds') = 'number'
         and jsonb_typeof(v_leg -> 'from') = 'string'
         and jsonb_typeof(v_leg -> 'to') = 'string'
        then (v_leg ->> 'travel_seconds')::numeric = floor((v_leg ->> 'travel_seconds')::numeric)
         and (v_leg ->> 'travel_seconds')::numeric between 0 and 86400
         and (v_leg ->> 'from') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         and (v_leg ->> 'to') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        else false
      end,
      false
    ) then
      raise exception 'invalid leg' using errcode = '22023';
    end if;
  end loop;

  select o.time_zone, o.appointment_grid_minutes into v_tz, v_grid
  from public.organizations o where o.id = v_org;

  return query
    select
      a.id,
      b.id,
      (l.leg ->> 'travel_seconds')::integer,
      app.earliest_follow_up_start(a.ends_at, (l.leg ->> 'travel_seconds')::integer, v_grid, v_tz),
      greatest(
        0,
        ceil(extract(epoch from (
          app.earliest_follow_up_start(a.ends_at, (l.leg ->> 'travel_seconds')::integer, v_grid, v_tz)
          - b.starts_at
        )) / 60)
      )::integer
    from jsonb_array_elements(p_legs) as l(leg)
    join public.appointments a
      on a.id = (l.leg ->> 'from')::uuid
     and a.organization_id = v_org
     and app.may_read_appointment_context(a.kind)
    join public.appointments b
      on b.id = (l.leg ->> 'to')::uuid
     and b.organization_id = v_org
     and app.may_read_appointment_context(b.kind)
     and b.staff_member_id = a.staff_member_id
     and b.starts_at >= a.ends_at;
end;
$_$;

COMMENT ON FUNCTION public.check_travel_buffers(p_legs jsonb) IS 'MAP-006c, PROJECT_PRINCIPLES.md 8.1, ANN-097: frueheste Beginne und Unterschreitung je Terminpaar aus einer live abgerufenen Fahrzeit. Warnung, keine Sperre; nichts wird gespeichert.';

CREATE FUNCTION public.check_travel_fit(p_items jsonb) RETURNS TABLE(item_index integer, starts_at timestamp with time zone, arrival_earliest_start timestamp with time zone, arrival_slack_minutes integer, next_earliest_start timestamp with time zone, departure_slack_minutes integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_tz      text;
  v_grid    integer;
  v_item    jsonb;
  v_index   integer;
  v_dauer   integer;
  v_beginn  timestamptz;
  v_vorher  timestamptz;
  v_hin     integer;
  v_danach  timestamptz;
  v_weiter  integer;
  v_frueh   timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_appointments() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 50 then
    raise exception 'items must be an array of at most 50 entries' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes into v_tz, v_grid
  from public.organizations o where o.id = v_org;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    -- Jede Angabe in ihrem Typ, sonst ist der ganze Aufruf ungueltig: Ein
    -- fehlender Wert ergaebe NULL, und NULL loest kein IF aus.
    begin
      if jsonb_typeof(v_item) <> 'object'
         or jsonb_typeof(v_item -> 'index') <> 'number'
         or jsonb_typeof(v_item -> 'duration_minutes') <> 'number' then
        raise exception 'invalid item';
      end if;
      v_index  := (v_item ->> 'index')::integer;
      v_dauer  := (v_item ->> 'duration_minutes')::integer;
      v_beginn := (v_item ->> 'starts_at')::timestamptz;
      v_vorher := (v_item ->> 'previous_end')::timestamptz;
      v_hin    := (v_item ->> 'travel_to_seconds')::integer;
      v_danach := (v_item ->> 'next_start')::timestamptz;
      v_weiter := (v_item ->> 'travel_from_seconds')::integer;
    exception
      when others then
        raise exception 'invalid item' using errcode = '22023';
    end;

    if v_index is null
       or v_dauer is null or v_dauer not between 1 and 600
       or (v_hin is not null and v_hin not between 0 and 86400)
       or (v_weiter is not null and v_weiter not between 0 and 86400) then
      raise exception 'invalid item' using errcode = '22023';
    end if;

    item_index := v_index;
    arrival_earliest_start := null;
    arrival_slack_minutes := null;
    next_earliest_start := null;
    departure_slack_minutes := null;

    -- Anfahrt: vom Ende des Vorgaengers (oder vom Tagesbeginn am Startort).
    if v_vorher is not null and v_hin is not null then
      arrival_earliest_start := app.earliest_follow_up_start(v_vorher, v_hin, v_grid, v_tz);
    end if;

    if v_beginn is null then
      if arrival_earliest_start is null then
        raise exception 'start or arrival is required' using errcode = '22023';
      end if;
      v_beginn := arrival_earliest_start;
    end if;
    starts_at := v_beginn;

    if arrival_earliest_start is not null then
      arrival_slack_minutes :=
        floor(extract(epoch from (v_beginn - arrival_earliest_start)) / 60)::integer;
    end if;

    -- Weiterfahrt: vom eigenen Ende zum Nachfolger (oder zum Tagesende).
    if v_danach is not null and v_weiter is not null then
      next_earliest_start := app.earliest_follow_up_start(
        v_beginn + make_interval(mins => v_dauer), v_weiter, v_grid, v_tz
      );
      departure_slack_minutes :=
        floor(extract(epoch from (v_danach - next_earliest_start)) / 60)::integer;
    end if;

    return next;
  end loop;
end;
$$;

COMMENT ON FUNCTION public.check_travel_fit(p_items jsonb) IS 'UBK-012, ANN-238: fruehester Beginn und Luft (Minuten, negativ = zu knapp) fuer einen geplanten Termin aus hereingereichten Zeiten und Fahrzeiten - mit der Rundungsregel aus §8.1 (app.earliest_follow_up_start). Liest keine Termine, speichert nichts. Warnung, keine Sperre.';

CREATE FUNCTION public.claim_notification_deliveries(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, kind text, channel text, subject_at timestamp with time zone, time_zone text, email text, push_targets jsonb, claimed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auftrag record;
  v_grund   text;
  v_neu     timestamptz;
begin
  for v_auftrag in
    select d.id, d.access_id, d.organization_id, o.time_zone,
           s.quiet_from, s.quiet_until
    from public.notification_deliveries d
    join public.organizations o on o.id = d.organization_id
    left join public.platform_notification_settings s on s.access_id = d.access_id
    where d.state = 'pending'
      and d.due_at <= now()
      and (d.claimed_at is null or d.claimed_at < now() - interval '15 minutes')
    -- Der naechste Termin zuerst: Greift die Tagesgrenze je Art, geht die
    -- Erinnerung an den naechsten Termin, nicht an einen zufaelligen
    -- (Zweitreview S1).
    order by d.due_at, d.subject_at nulls last, d.id
    limit greatest(least(coalesce(p_limit, 50), 200), 1)
    for update of d skip locked
  loop
    v_grund := app.notification_drop_reason(v_auftrag.id);
    if v_grund is not null then
      update public.notification_deliveries d
         set state = 'dropped', drop_reason = v_grund, finished_at = now(), claimed_at = null
       where d.id = v_auftrag.id;
      continue;
    end if;

    v_neu := app.notification_due_at(
      now(), v_auftrag.time_zone,
      coalesce(v_auftrag.quiet_from, app.notification_rule('quiet_from')::smallint),
      coalesce(v_auftrag.quiet_until, app.notification_rule('quiet_until')::smallint));
    if v_neu > now() then
      update public.notification_deliveries d set due_at = v_neu, claimed_at = null
       where d.id = v_auftrag.id;
      continue;
    end if;

    -- Auf Millisekunden (BEF-148): So kommt der Anspruch durch jeden Client
    -- unverändert zurück, auch durch ein JavaScript-Datum.
    update public.notification_deliveries d
       set claimed_at = date_trunc('milliseconds', now()), attempts = d.attempts + 1
     where d.id = v_auftrag.id;

    return query
    select d.id, d.kind, d.channel, d.subject_at, v_auftrag.time_zone,
           case when d.channel = 'email' then (
             select lower(btrim(u.email)) from public.platform_accesses a
             join auth.users u on u.id = a.account_user_id
             where a.id = d.access_id
           ) end,
           case when d.channel = 'push' then (
             select coalesce(jsonb_agg(jsonb_build_object(
                      'endpoint', p.endpoint, 'p256dh', p.p256dh, 'auth', p.auth_secret)
                      order by p.created_at), '[]'::jsonb)
             from public.platform_push_subscriptions p where p.access_id = d.access_id
           ) end,
           d.claimed_at
    from public.notification_deliveries d
    where d.id = v_auftrag.id;
  end loop;
end;
$$;

COMMENT ON FUNCTION public.claim_notification_deliveries(p_limit integer) IS 'KOM-009 (ADR-024 Punkt 16): gibt dem Versand faellige Benachrichtigungen mit Adresse bzw. Push-Zielen und dem Anspruch (claimed_at). Prueft Zugang, Wahl, Schalter, Sinn, Obergrenzen und Ruhezeit beim Abholen. Nur service_role.';

CREATE FUNCTION public.claim_platform_account_deletions(p_limit integer DEFAULT 20) RETURNS TABLE(account_user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Was nicht mehr faellig ist, faellt aus der Schlange. Ein Auftrag nach
  -- einem Restore bleibt immer: Das Konto steht als geloescht im Journal,
  -- und das Wiederherstellen allein macht es nicht wieder gueltig
  -- (Zweitreview B1).
  delete from public.platform_account_deletions d
   where d.reason <> 'reapply'
     and not app.platform_account_still_due(d.account_user_id);

  return query
  with frei as (
    select d.account_user_id
    from public.platform_account_deletions d
    where d.claimed_at is null or d.claimed_at < now() - interval '15 minutes'
    order by d.ordered_at, d.account_user_id
    limit greatest(least(coalesce(p_limit, 20), 100), 1)
    for update skip locked
  )
  update public.platform_account_deletions d
     set claimed_at = now(),
         attempts   = d.attempts + 1
    from frei
   where d.account_user_id = frei.account_user_id
  returning d.account_user_id;
end;
$$;

COMMENT ON FUNCTION public.claim_platform_account_deletions(p_limit integer) IS 'Gibt dem Zugangsdienst faellige Loeschauftraege fuer Plattformkonten (ABN-011). Nur service_role.';

CREATE FUNCTION public.claim_staff_invitation() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid       uuid;
  v_email     text;
  v_vorhanden uuid;
  v_ein       record;
  v_person_id uuid;
  v_name      text;
  v_rolle     text;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Schon eingerichtet: idempotent zurueckgeben, nichts erneut schreiben.
  select up.id into v_vorhanden
  from public.user_profiles up
  where up.id = v_uid;

  if found then
    return v_vorhanden;
  end if;

  select lower(btrim(au.email)) into v_email
  from auth.users au
  where au.id = v_uid;

  if v_email is null or v_email = '' then
    raise exception 'no_open_invitation' using errcode = 'P0002';
  end if;

  select i.id, i.organization_id, i.staff_member_id, i.role_keys, i.invited_by
    into v_ein
  from public.staff_account_invitations i
  where i.email = v_email
    and i.status = 'pending'
    and i.expires_at > now()
  order by i.created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'no_open_invitation' using errcode = 'P0002';
  end if;

  -- Der Datensatz muss zwischen Einladung und Annahme aktiv geblieben sein.
  -- Wer in der Zwischenzeit ausgeschieden ist, bekommt keinen Zugang.
  select sm.person_id, pe.given_name || ' ' || pe.family_name
    into v_person_id, v_name
  from public.staff_members sm
  join public.persons pe on pe.id = sm.person_id
  where sm.id = v_ein.staff_member_id
    and sm.organization_id = v_ein.organization_id
    and sm.employment_status = 'active';

  if v_person_id is null then
    raise exception 'no_open_invitation' using errcode = 'P0002';
  end if;

  -- created_by ist die Praxisinhaberin, die eingeladen hat: sie hat den
  -- Zugang veranlasst, das Konto hat ihn nur angenommen.
  insert into public.user_profiles (id, organization_id, person_id, display_name, is_active, created_by)
  values (v_uid, v_ein.organization_id, v_person_id, v_name, true, v_ein.invited_by);

  foreach v_rolle in array v_ein.role_keys loop
    insert into public.user_roles (user_id, organization_id, role_key, created_by)
    values (v_uid, v_ein.organization_id, v_rolle, v_ein.invited_by);
  end loop;

  update public.staff_account_invitations
     set status = 'accepted', accepted_at = now(), accepted_user_id = v_uid
   where id = v_ein.id;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_ein.organization_id, v_uid, 'staff_account.invitation_accepted', 'staff_member',
    v_ein.staff_member_id, 'success',
    jsonb_build_object('surface', 'web', 'roles', to_jsonb(v_ein.role_keys))
  );

  return v_uid;
end;
$$;

COMMENT ON FUNCTION public.claim_staff_invitation() IS 'Bindet das angemeldete Konto an Organisation, Person und Rollen einer offenen Einladung. Ohne passende Einladung entsteht nichts (STAFF-002b, ANN-025).';

CREATE FUNCTION public.claim_storage_deletion_order(p_order_id uuid) RETURNS TABLE(bucket_id text, object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_auftrag record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_execute_storage_deletion() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'storage_deletion.claimed', 'not allowed to execute deletion orders');
    return;
  end if;

  select o.* into v_auftrag
  from public.storage_deletion_orders o
  where o.id = p_order_id
    and o.organization_id = app.current_organization_id()
    and o.receipted_at is null;

  if not found then
    raise exception 'deletion order not accessible' using errcode = '42501';
  end if;


  delete from public.patient_file_access_grants g
   where g.organization_id = v_auftrag.organization_id
     and g.expires_at <= now();

  insert into public.patient_file_access_grants (
    organization_id, user_id, deletion_order_id, expires_at
  )
  values (
    v_auftrag.organization_id, v_actor, p_order_id, now() + app.patient_file_access_grant_ttl()
  );

  return query select v_auftrag.bucket_id, v_auftrag.object_key;
end;
$$;

COMMENT ON FUNCTION public.claim_storage_deletion_order(p_order_id uuid) IS 'Gibt den Objektschluessel eines offenen Loeschauftrags heraus, protokolliert storage_deletion.claimed und legt die einmalige Loeschfreigabe an (ADR-017 Punkt 25; FIX-015).';

CREATE FUNCTION public.clear_location_garage(p_location_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.has_any_role('owner') then
    raise exception 'not allowed to change the garage' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the garage' using errcode = '42501';
  end if;

  update public.locations l
     set garage_street = null,
         garage_house_number = null,
         garage_postal_code = null,
         garage_city = null,
         garage_lat = null,
         garage_lon = null,
         garage_geocode_precision = null
   where l.id = p_location_id
     and l.organization_id = v_org;

  if not found then
    raise exception 'location not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.clear_location_garage(p_location_id uuid) IS 'UBK-015, ANN-240: entfernt die Garage eines Standorts; die Tour beginnt und endet dann an der Praxis. Nur owner.';

CREATE FUNCTION public.close_platform_message(p_access_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_vorgang public.platform_messages%rowtype;
begin
  v_zugang := app.assert_platform_message(p_access_id);
  -- BEF-144: erst die Zeile sperren, dann den Zustand lesen (wie BEF-132).
  perform 1 from public.platform_messages m
  where m.id = p_message_id and m.organization_id = v_zugang.organization_id
  for update;
  v_vorgang := app.platform_open_message(p_access_id, p_message_id);

  update public.platform_messages m
     set status = 'closed',
         due_on = null,
         closed_at = now(),
         closed_by = auth.uid(),
         closed_by_side = 'person'
   where m.id = v_vorgang.id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'message')
  );
end;
$$;

COMMENT ON FUNCTION public.close_platform_message(p_access_id uuid, p_message_id uuid) IS 'KOM-001: einen Vorgang als erledigt markieren (ANN-308). Danach kein Nachtrag mehr; eine neue Frage ist ein neuer Vorgang.';

CREATE FUNCTION public.close_platform_message_by_practice(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vorgang public.platform_messages%rowtype;
begin
  if auth.uid() is null or not app.may_read_platform_messages('any') then
    raise exception 'not allowed to close platform messages' using errcode = '42501';
  end if;
  -- BEF-144: erst die Zeile sperren, dann den Zustand lesen (wie BEF-132).
  perform 1 from public.platform_messages m
  where m.id = p_message_id and m.organization_id = app.current_organization_id()
  for update;
  v_vorgang := app.practice_message(p_message_id, true);
  if v_vorgang.status = 'closed' then
    raise exception 'message is closed' using errcode = '22023';
  end if;

  update public.platform_messages m
     set status = 'closed', due_on = null, closed_at = now(), closed_by = auth.uid(),
         closed_by_side = 'practice'
   where m.id = v_vorgang.id;
end;
$$;

COMMENT ON FUNCTION public.close_platform_message_by_practice(p_message_id uuid) IS 'KOM-002: einen Vorgang als erledigt markieren (ANN-308) - dieselben Rollen wie beim Antworten.';

CREATE FUNCTION public.close_waitlist_entry(p_entry_id uuid, p_expected_updated_at timestamp with time zone, p_outcome text, p_appointment_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_stand timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;

  select w.updated_at into v_stand
  from public.waitlist_entries w
  where w.id = p_entry_id and w.organization_id = v_org;
  if found and (p_expected_updated_at is null or v_stand <> p_expected_updated_at) then
    raise exception 'waitlist entry changed' using errcode = '40001';
  end if;

  perform app.close_waitlist_entry(v_org, v_actor, p_entry_id, p_outcome, p_appointment_id);
end;
$$;

COMMENT ON FUNCTION public.close_waitlist_entry(p_entry_id uuid, p_expected_updated_at timestamp with time zone, p_outcome text, p_appointment_id uuid) IS 'Schliesst einen offenen Wartelisteneintrag: withdrawn (von der Liste genommen) oder placed mit einem nicht abgesagten Termin derselben Person (PRX-001). Auditiert.';

CREATE FUNCTION public.complete_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- TRN-010 (ANN-186): Am Trainingstermin schliessen die Rollen ab, die ihn
  -- schreiben - owner, trainer, office (app.may_write_appointment_context).
  -- Welcher Kontext, entscheidet die Abfrage unten; eine Rolle ohne Zugang zum
  -- Kontext findet den Termin nicht (ADR-022 Punkt 11).
  if not (app.can_complete_appointment() or app.can_write_training_relationships()) then
    raise exception 'not allowed to complete appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to complete appointments' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.staff_member_id, a.status, a.kind, a.updated_at,
         a.training_relationship_id, a.completed_at
    into v_alt
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_alt.kind = 'internal' then
    raise exception 'event cannot be completed' using errcode = '22023';
  end if;

  if v_alt.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be completed' using errcode = '22023';
  end if;

  if v_alt.status = 'no_show' then
    raise exception 'no-show appointment must be reopened first' using errcode = '22023';
  end if;

  -- B4 (BEF-154, ANN-512): Ein dokumentierter Termin ohne Haken bekommt den
  -- Haken; sein Zustand bleibt 'documented'.
  if not (v_alt.status = 'confirmed'
          or (v_alt.status = 'documented' and v_alt.kind = 'therapy'
              and v_alt.completed_at is null)) then
    raise exception 'appointment is already completed' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  update public.appointments
     set status       = case when status = 'confirmed' then 'completed' else status end,
         completed_at = now(),
         completed_by = v_actor,
         updated_at   = now()
   where id = p_appointment_id
     and updated_at = p_expected_updated_at
     and (status = 'confirmed'
          or (status = 'documented' and kind = 'therapy' and completed_at is null));

  if not found then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;


  return p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.complete_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) IS 'Schliesst einen bestaetigten Behandlungstermin ab und protokolliert appointment.completed. Ein Ereignis wird abgewiesen - aus ihm entsteht keine Leistung (CAL-004, CAL-015b, ADR-018).';

CREATE FUNCTION public.complete_platform_questionnaire_response(p_access_id uuid, p_response_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_alt    record;
begin
  if not app.platform_access_allows(p_access_id, 'questionnaire') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  select r.id, r.status, r.source, r.instrument_id, r.definition_version, r.answers into v_alt
  from public.patient_questionnaire_responses r
  where r.id = p_response_id
    and r.patient_id = v_zugang.relationship_id
    and r.organization_id = v_zugang.organization_id
    and v_zugang.relationship_kind = 'treatment'
  for update;
  if not found or v_alt.source <> 'platform' then
    raise exception 'questionnaire response not found' using errcode = 'P0002';
  end if;
  if v_alt.status <> 'entwurf' then
    raise exception 'questionnaire response is completed' using errcode = '23514';
  end if;
  -- Noch einmal gegen die Definition - der Entwurf koennte mit einer
  -- inzwischen abgeloesten Fassung begonnen worden sein.
  perform app.assert_questionnaire_answers(v_alt.instrument_id, v_alt.definition_version, v_alt.answers);

  update public.patient_questionnaire_responses
     set status = 'abgeschlossen', completed_at = now(), completed_by = auth.uid(),
         updated_at = now(), updated_by = auth.uid()
   where id = p_response_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'questionnaire_complete')
  );
  return true;
end;
$$;

COMMENT ON FUNCTION public.complete_platform_questionnaire_response(p_access_id uuid, p_response_id uuid) IS 'POR-012: Absenden des Befundbogens ueber die Plattform = abgeschlossen (ANN-248); danach aendert die Praxis nur per Korrektur (ANN-103). Nur eigene Plattform-Entwuerfe.';

CREATE FUNCTION public.complete_questionnaire_response(p_response_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_questionnaire_response() then
    raise exception 'not allowed to record questionnaires' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record questionnaires' using errcode = '42501';
  end if;

  select r.status, r.patient_id into v_alt
  from public.patient_questionnaire_responses r
  where r.id = p_response_id and r.organization_id = v_org
  for update;
  if not found then
    raise exception 'questionnaire response not found' using errcode = 'P0002';
  end if;
  if v_alt.status <> 'entwurf' then
    raise exception 'questionnaire response is completed' using errcode = '23514';
  end if;

  update public.patient_questionnaire_responses
     set status       = 'abgeschlossen',
         completed_at = now(),
         completed_by = v_actor,
         updated_at   = now(),
         updated_by   = v_actor
   where id = p_response_id;

end;
$$;

COMMENT ON FUNCTION public.complete_questionnaire_response(p_response_id uuid) IS 'Schliesst eine Erhebung ab; danach ist sie unveraenderlich (FRB-002b, ANN-103). Protokolliert als questionnaire_response.completed.';

CREATE FUNCTION public.complete_therapy_report(p_report_id uuid, p_expected_updated_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  b       public.therapy_reports%rowtype;
  v_tz    text;
  v_jetzt timestamptz;
  v_dok   jsonb;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;

  select * into b from public.therapy_reports r
  where r.id = p_report_id and r.organization_id = v_org
  for update;
  if not found then
    raise exception 'therapy report not found' using errcode = 'P0002';
  end if;
  if b.status <> 'entwurf' then
    raise exception 'therapy report is completed and cannot be changed' using errcode = '55000';
  end if;
  if b.updated_at is distinct from p_expected_updated_at then
    raise exception 'therapy report was changed in the meantime' using errcode = '40001';
  end if;
  if b.report_text is null and b.recommendation is null and cardinality(b.note_ids) = 0 then
    raise exception 'therapy report is empty' using errcode = '22023';
  end if;

  -- Seit dem Speichern kann eine Erhebung ersetzt worden sein.
  perform app.therapy_report_pruefen(v_org, b.patient_id, b.note_ids, b.body_chart_response_id);

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_jetzt := clock_timestamp();
  v_dok := app.therapy_report_dokument(p_report_id)
           || jsonb_build_object('abgeschlossen', jsonb_build_object(
                'datum', (v_jetzt at time zone v_tz)::date,
                'von', (select up.display_name from public.user_profiles up where up.id = v_actor)));

  update public.therapy_reports r
     set status       = 'abgeschlossen',
         snapshot     = v_dok,
         completed_at = v_jetzt,
         completed_by = v_actor,
         updated_at   = v_jetzt,
         updated_by   = v_actor
   where r.id = p_report_id;

end;
$$;

COMMENT ON FUNCTION public.complete_therapy_report(p_report_id uuid, p_expected_updated_at timestamp with time zone) IS 'Schliesst einen Therapiebericht ab und friert ihn als Snapshot ein (DOK-005a, ANN-121). therapist, team_lead; protokolliert als therapy_report.completed.';

CREATE FUNCTION public.complete_treatment(p_appointment_id uuid, p_content text, p_expected_appointment_updated_at timestamp with time zone, p_expected_note_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_visit_without_treatment boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_note_id      uuid;
  v_note_stand   timestamptz;
  v_note_status  text;
  v_org          uuid;
  v_termin       record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  select a.id, a.status, a.appointment_type, a.updated_at
    into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_termin.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be completed' using errcode = '22023';
  end if;

  if v_termin.status = 'no_show' then
    raise exception 'no-show appointment cannot be documented' using errcode = '22023';
  end if;

  -- Veralteter Terminstand: Wer die Seite an einem offenen Termin geoeffnet
  -- hat, schreibt nicht auf einen inzwischen verlegten oder geaenderten Termin.
  -- Bisher prueft das complete_appointment; die Pruefung bleibt hier, auch
  -- wenn nicht mehr abgehakt wird. Ein abgehakter Termin nimmt den Eintrag wie
  -- bisher ohne diese Pruefung an (der Haken aendert updated_at).
  if v_termin.status = 'confirmed'
     and v_termin.updated_at is distinct from p_expected_appointment_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  if p_visit_without_treatment is true and v_termin.appointment_type <> 'home_visit' then
    raise exception 'visit without treatment applies to home visits only' using errcode = '22023';
  end if;

  select t.id, t.updated_at, t.status
    into v_note_id, v_note_stand, v_note_status
  from public.treatment_notes t
  where t.appointment_id = p_appointment_id
    and t.addendum_to_note_id is null;

  if v_note_id is null then
    if p_expected_note_updated_at is not null then
      raise exception 'treatment note was changed meanwhile' using errcode = '40001';
    end if;
    v_note_id := public.create_treatment_note(p_appointment_id, p_content);
  else
    if p_expected_note_updated_at is null
       or v_note_stand is distinct from p_expected_note_updated_at then
      raise exception 'treatment note was changed meanwhile' using errcode = '40001';
    end if;
    if v_note_status = 'final' then
      raise exception 'treatment note is already final' using errcode = '22023';
    end if;
    perform public.update_treatment_note(v_note_id, v_note_stand, p_content);
  end if;

  -- B4 (BEF-154): Kein Abschluss des Termins mehr - abgehakt wird getrennt
  -- (Uebersicht, Kalender).

  -- Der Pflichtvermerk gehoert zum Eintrag, nicht zum Termin: Er sagt etwas
  -- ueber die Behandlung aus, und die steht in der Akte. Ohne `updated_at`,
  -- damit der Stand fuer die Finalisierung gleich darunter derselbe bleibt,
  -- den update_treatment_note hinterlassen hat.
  update public.treatment_notes
     set visit_without_treatment = coalesce(p_visit_without_treatment, false)
   where id = v_note_id;

  -- Nach dem Schreiben neu lesen: update_treatment_note laesst den Stand bei
  -- unveraendertem Text bewusst stehen, bei geaendertem setzt es ihn neu.
  select t.updated_at into v_note_stand
  from public.treatment_notes t
  where t.id = v_note_id;

  -- Dann die Finalisierung, die den Termin auf documented hebt (CAL-008d).
  perform public.finalize_treatment_note(v_note_id, v_note_stand);

  return v_note_id;
end;
$$;

COMMENT ON FUNCTION public.complete_treatment(p_appointment_id uuid, p_content text, p_expected_appointment_updated_at timestamp with time zone, p_expected_note_updated_at timestamp with time zone, p_visit_without_treatment boolean) IS 'Schreibt und finalisiert die Dokumentation eines Termins in einem Schritt (UX-007). Seit B4 (BEF-154) ohne Abschluss des Termins: abgehakt wird getrennt. Traegt auf Wunsch den Pflichtvermerk aus Hausbesuch-Szenario 1 ein (CAL-018). Der Termin steht danach auf documented (ADR-018 Punkt 3).';

CREATE FUNCTION public.conclude_patient_care(p_patient_id uuid, p_concluded_on date DEFAULT NULL::date) RETURNS date
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_heute  date;
  v_tag    date;
  v_start  date;
  v_bisher date;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_conclude_patient_care() then
    raise exception 'not allowed to conclude patient care' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to conclude patient care' using errcode = '42501';
  end if;

  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o
  where o.id = v_org;

  v_tag := coalesce(p_concluded_on, v_heute);

  -- Ein Abschluss in der Zukunft waere eine Frist, die noch nicht laufen darf.
  if v_tag > v_heute then
    raise exception 'conclusion date is in the future' using errcode = '22023';
  end if;

  -- Zielpatient ausschliesslich in der Organisation des Aufrufers suchen: eine
  -- fremde ID ist damit von einer unbekannten nicht zu unterscheiden.
  select p.care_started_on, p.care_concluded_on
    into v_start, v_bisher
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = v_org
  for update;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  if v_bisher is not null then
    raise exception 'patient care is already concluded' using errcode = '22023';
  end if;

  if v_start is not null and v_tag < v_start then
    raise exception 'conclusion date is before the start of care' using errcode = '22023';
  end if;

  update public.patients
     set care_concluded_on = v_tag,
         care_concluded_at = now(),
         care_concluded_by = v_actor
   where id = p_patient_id;


  return v_tag;
end;
$$;

COMMENT ON FUNCTION public.conclude_patient_care(p_patient_id uuid, p_concluded_on date) IS 'Haelt den Abschluss der Versorgung fest und startet damit die zehnjaehrige Aufbewahrung (ADR-008, LOE-001b). Protokolliert patient.care_concluded. Nur owner, therapist, team_lead.';

CREATE FUNCTION public.conclude_training_basis(p_basis_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(auth.uid(), 'training_basis.concluded', 'not allowed to manage training bases');
    return null;
  end if;
  return app.set_training_basis_status(p_basis_id, 'concluded', 'training_basis.concluded');
end;
$$;

COMMENT ON FUNCTION public.conclude_training_basis(p_basis_id uuid) IS 'TRN-005: schliesst eine Trainingsgrundlage ab - keine neuen Termine daran. owner, trainer, office; protokolliert training_basis.concluded.';

CREATE FUNCTION public.confirm_fleet_photo_upload(p_photo_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_foto     public.fleet_photos%rowtype;
  v_metadata jsonb;
begin
  perform app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  v_foto := app.own_pending_fleet_photo(p_photo_id);
  perform 1 from public.fleet_photos f where f.id = v_foto.id for update;

  select o.metadata into v_metadata
  from storage.objects o
  where o.bucket_id = app.fleet_photo_bucket() and o.name = v_foto.object_key;
  if not found then
    raise exception 'object was not uploaded' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'size', '')::bigint is distinct from v_foto.byte_size then
    raise exception 'uploaded size does not match the announced size' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'mimetype', '') is distinct from v_foto.mime_type then
    raise exception 'uploaded media type does not match the announced media type'
      using errcode = '22023';
  end if;

  -- ADR-017 Punkt 51: Ist die Pruefung am Server scharf, wird das Foto erst
  -- mit ihrem Ergebnis ready - derselbe Schalter wie fuer die Akte.
  if app.patient_file_verification_required() then
    update public.fleet_photos set confirmation_requested_at = now() where id = v_foto.id;
  else
    update public.fleet_photos set status = 'ready', confirmed_at = now() where id = v_foto.id;
  end if;
end;
$$;

COMMENT ON FUNCTION public.confirm_fleet_photo_upload(p_photo_id uuid) IS 'FLT-002 (ADR-017 Punkt 7c): Phase (c) - prueft Groesse und Typ gegen storage.objects; ready, solange die Pruefung am Server nicht scharf ist (Punkt 51).';

-- ANN-337
CREATE FUNCTION public.confirm_message_attachment_upload(p_access_id uuid, p_attachment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang   public.platform_message_attachments%rowtype;
  v_vorgang  public.platform_messages%rowtype;
  v_metadata jsonb;
begin
  perform app.assert_platform_message(p_access_id);
  if not app.platform_access_allows(p_access_id, 'attach') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  v_anhang := app.own_pending_attachment(p_access_id, p_attachment_id);
  -- BEF-132 (Zweitreview): wie der Nachtrag erst den Vorgang sperren, dann
  -- seinen Zustand lesen - ein gleichzeitiges Erledigen endet mit 22023
  -- statt mit 23514. Reihenfolge Vorgang vor Anhang wie beim Vorbereiten.
  perform 1 from public.platform_messages m
  where m.id = v_anhang.message_id and m.organization_id = v_anhang.organization_id
  for update;
  v_vorgang := app.platform_open_message(p_access_id, v_anhang.message_id);
  -- Ein Widerruf zwischen Vorbereitung und Bestaetigung laesst den Anhang
  -- nicht mehr sichtbar werden (Punkt 61, wie Punkt 36).
  if app.message_attachment_consent(v_vorgang.relationship_kind, v_vorgang.relationship_id)
     is distinct from 'consent_granted' then
    raise exception 'no consent to attachments' using errcode = '42501';
  end if;

  perform 1 from public.platform_message_attachments x where x.id = v_anhang.id for update;

  select o.metadata into v_metadata
  from storage.objects o
  where o.bucket_id = app.message_attachment_bucket() and o.name = v_anhang.object_key;
  if not found then
    raise exception 'object was not uploaded' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'size', '')::bigint is distinct from v_anhang.byte_size then
    raise exception 'uploaded size does not match the announced size' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'mimetype', '') is distinct from v_anhang.mime_type then
    raise exception 'uploaded media type does not match the announced media type'
      using errcode = '22023';
  end if;

  -- Punkte 51 und 69: Ist eine der Pruefungen scharf, wird der Anhang erst
  -- mit ihrem Ergebnis ready.
  if app.patient_file_verification_required() or app.message_attachment_scan_required() then
    update public.platform_message_attachments
       set confirmation_requested_at = now()
     where id = v_anhang.id;
  else
    update public.platform_message_attachments
       set status = 'ready', confirmed_at = now()
     where id = v_anhang.id;
  end if;

  -- Zweitreview S1: Wie ein Nachtrag (KOM-001) ist die Praxis danach wieder
  -- am Zug; eine neue Frist nur, wenn sie schon geantwortet hatte (ANN-309).
  update public.platform_messages m
     set status = 'open',
         due_on = case when m.status = 'open' then m.due_on
                       else app.message_due_on(m.organization_id) end,
         last_entry_at = now()
   where m.id = v_anhang.message_id;

  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'message')
  );
end;
$$;

COMMENT ON FUNCTION public.confirm_message_attachment_upload(p_access_id uuid, p_attachment_id uuid) IS 'KOM-005 (ADR-017 Punkt 7c): Phase (c) - prueft Groesse und Typ gegen storage.objects; ready, solange weder Pruefung am Server noch Virenpruefung scharf sind (Punkte 51, 69).';

CREATE FUNCTION public.confirm_patient_file_upload(p_file_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_datei    record;
  v_metadata jsonb;
  v_groesse  bigint;
  v_mime     text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = app.current_organization_id()
  for update;

  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  if not app.can_write_patient_file(v_datei.document_type, v_datei.treatment_basis_id) then
    raise exception 'not allowed to confirm this file' using errcode = '42501';
  end if;

  -- Zweitreview: Eine schon bestaetigte, auf die Pruefung wartende Datei wird
  -- nicht ein zweites Mal bestaetigt (sonst ein zweites patient_file.uploaded).
  if v_datei.status <> 'pending' or v_datei.confirmation_requested_at is not null then
    raise exception 'file is not pending' using errcode = '22023';
  end if;

  -- Punkt 36: Ein Widerruf zwischen Vorbereitung und Bestaetigung laesst das
  -- Foto nicht mehr sichtbar werden.
  -- Und das Foto selbst ist seit seiner Aufnahme nicht faellig geworden: Ein
  -- Widerruf mit neuer Erteilung dazwischen gibt es nicht frei.
  if v_datei.document_type = 'patientenfoto'
     and not (
       app.patient_photo_accessible(v_datei.patient_id, null)
       and app.patient_photo_accessible(
         v_datei.patient_id, v_datei.created_at, v_datei.photo_locked_at
       )
     ) then
    raise exception 'no consent to patient photos' using errcode = '42501';
  end if;

  select o.metadata into v_metadata
  from storage.objects o
  where o.bucket_id = app.patient_file_bucket_for(v_datei.document_type)
    and o.name = v_datei.object_key;

  if not found then
    raise exception 'object was not uploaded' using errcode = '22023';
  end if;

  v_groesse := nullif(v_metadata ->> 'size', '')::bigint;
  v_mime    := nullif(v_metadata ->> 'mimetype', '');

  if v_groesse is distinct from v_datei.byte_size then
    raise exception 'uploaded size does not match the announced size' using errcode = '22023';
  end if;

  if v_mime is distinct from v_datei.mime_type then
    raise exception 'uploaded media type does not match the announced media type'
      using errcode = '22023';
  end if;

  if v_groesse > app.patient_file_max_bytes() then
    raise exception 'file too large' using errcode = '22023';
  end if;

  if v_mime not in ('application/pdf', 'image/jpeg', 'image/png') then
    raise exception 'unsupported media type' using errcode = '22023';
  end if;

  -- ABN-024 (ADR-017 Punkt 51): Ist die Pruefung am Server scharf, wird die
  -- Datei erst mit ihrem Ergebnis ready (record_patient_file_verification).
  -- Bis dahin bleibt sie pending und traegt den Zeitpunkt der Bestaetigung.
  if app.patient_file_verification_required() then
    update public.patient_files
       set confirmation_requested_at = now()
     where id = p_file_id;
  else
    update public.patient_files
       set status = 'ready',
           confirmed_at = now()
     where id = p_file_id;
  end if;

end;
$$;

COMMENT ON FUNCTION public.confirm_patient_file_upload(p_file_id uuid) IS 'Phase (c) des zweiphasigen Uploads (ADR-017 Punkt 7c): prueft Groesse und MIME-Typ gegen storage.objects und macht die Datei sichtbar. Auditereignis patient_file.uploaded.';

CREATE FUNCTION public.confirm_platform_account_deletion(p_account_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auftrag public.platform_account_deletions%rowtype;
begin
  select * into v_auftrag
  from public.platform_account_deletions d
  where d.account_user_id = p_account_user_id
  for update;

  if not found then
    raise exception 'no deletion order for this account' using errcode = 'P0002';
  end if;

  if exists (select 1 from auth.users u where u.id = p_account_user_id) then
    raise exception 'account still exists' using errcode = '23514';
  end if;

  -- Beim erneuten Anwenden steht der Eintrag schon im Journal; er gilt erst
  -- jetzt, mit der Bestaetigung, als erneut angewandt (Zweitreview B1).
  if v_auftrag.reason <> 'reapply' then
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at)
    values
      (v_auftrag.organization_id, v_auftrag.run_id, 'auth_users', p_account_user_id,
       'plattformzugang', v_auftrag.due_at);
  else
    update public.deletion_journal
       set reapplied_at = now()
     where target_table = 'auth_users' and target_id = p_account_user_id;
  end if;

  delete from public.platform_account_deletions d where d.account_user_id = p_account_user_id;
end;
$$;

COMMENT ON FUNCTION public.confirm_platform_account_deletion(p_account_user_id uuid) IS 'Bestaetigt die Loeschung eines Plattformkontos beim Anmeldedienst und schreibt das Loeschjournal (ABN-011). Nur service_role; weist ab, solange das Konto noch besteht.';

CREATE FUNCTION public.confirm_reimbursement_receipt_upload(p_receipt_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_beleg    public.staff_reimbursement_receipts%rowtype;
  v_metadata jsonb;
begin
  perform app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_beleg := app.own_pending_reimbursement_receipt(p_receipt_id);
  -- Zweitreview Runde 2: sperren und dabei den Zustand erneut prüfen - ein
  -- gleichzeitig verworfener oder geprüfter Beleg meldet keinen Erfolg.
  perform 1 from public.staff_reimbursement_receipts b
   where b.id = v_beleg.id and b.status = 'pending' and b.confirmation_requested_at is null
     and b.reimbursement_id is null
   for update;
  if not found then
    raise exception 'receipt not found' using errcode = 'P0002';
  end if;

  select o.metadata into v_metadata
  from storage.objects o
  where o.bucket_id = app.reimbursement_receipt_bucket() and o.name = v_beleg.object_key;
  if not found then
    raise exception 'object was not uploaded' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'size', '')::bigint is distinct from v_beleg.byte_size then
    raise exception 'uploaded size does not match the announced size' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'mimetype', '') is distinct from v_beleg.mime_type then
    raise exception 'uploaded media type does not match the announced media type'
      using errcode = '22023';
  end if;

  -- ADR-017 Punkt 51: Ist die Prüfung am Server scharf, wird der Beleg erst
  -- mit ihrem Ergebnis ready - derselbe Schalter wie für die Akte.
  if app.patient_file_verification_required() then
    update public.staff_reimbursement_receipts set confirmation_requested_at = now()
     where id = v_beleg.id;
  else
    update public.staff_reimbursement_receipts set status = 'ready', confirmed_at = now()
     where id = v_beleg.id;
  end if;
end;
$$;

COMMENT ON FUNCTION public.confirm_reimbursement_receipt_upload(p_receipt_id uuid) IS 'ERS-001 (ADR-017 Punkt 7c): Phase (c) - prüft Größe und Typ gegen storage.objects; ready, solange die Prüfung am Server nicht scharf ist (Punkt 51).';

CREATE FUNCTION public.confirm_team_attachment_upload(p_attachment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_staff    uuid;
  v_anhang   public.team_message_attachments%rowtype;
  v_metadata jsonb;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  v_anhang := app.own_pending_team_attachment(p_attachment_id, v_org, v_staff);
  -- Sperren und dabei den Zustand erneut prüfen: Ein gleichzeitig verworfener
  -- oder geprüfter Anhang meldet keinen Erfolg (wie ERS-001).
  perform 1 from public.team_message_attachments a
   where a.id = v_anhang.id and a.status = 'pending' and a.confirmation_requested_at is null
     and a.message_id is null
   for update;
  if not found then
    raise exception 'team attachment not found' using errcode = 'P0002';
  end if;

  select o.metadata into v_metadata
  from storage.objects o
  where o.bucket_id = app.chat_attachment_bucket() and o.name = v_anhang.object_key;
  if not found then
    raise exception 'object was not uploaded' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'size', '')::bigint is distinct from v_anhang.byte_size then
    raise exception 'uploaded size does not match the announced size' using errcode = '22023';
  end if;
  if nullif(v_metadata ->> 'mimetype', '') is distinct from v_anhang.mime_type then
    raise exception 'uploaded media type does not match the announced media type'
      using errcode = '22023';
  end if;

  -- ADR-017 Punkt 51: Ist die Prüfung am Server scharf, wird der Anhang erst
  -- mit ihrem Ergebnis ready - derselbe Schalter wie für die Akte.
  if app.patient_file_verification_required() then
    update public.team_message_attachments set confirmation_requested_at = now()
     where id = v_anhang.id;
  else
    update public.team_message_attachments set status = 'ready', confirmed_at = now()
     where id = v_anhang.id;
  end if;
end;
$$;

COMMENT ON FUNCTION public.confirm_team_attachment_upload(p_attachment_id uuid) IS 'TEAM-003 (ADR-017 Punkt 7c): Phase (c) - prüft Größe und Typ gegen storage.objects; ready, solange die Prüfung am Server nicht scharf ist (Punkt 51).';

CREATE FUNCTION public.confirm_waitlist_entry(p_entry_id uuid, p_expected_updated_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_eintrag public.waitlist_entries;
  v_stand   timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;

  select * into v_eintrag
  from public.waitlist_entries w
  where w.id = p_entry_id and w.organization_id = v_org
  for update;
  if not found then
    raise exception 'waitlist entry not found' using errcode = 'P0002';
  end if;
  if v_eintrag.status <> 'open' then
    raise exception 'waitlist entry closed' using errcode = '22023';
  end if;
  if p_expected_updated_at is null or v_eintrag.updated_at <> p_expected_updated_at then
    raise exception 'waitlist entry changed' using errcode = '40001';
  end if;

  update public.waitlist_entries
     set updated_at = now(), updated_by = v_actor
   where id = p_entry_id
  returning updated_at into v_stand;


  return v_stand;
end;
$$;

COMMENT ON FUNCTION public.confirm_waitlist_entry(p_entry_id uuid, p_expected_updated_at timestamp with time zone) IS 'Bestaetigt einen offenen Wartelisteneintrag als noch aktuell (ABN-018, BEF-108); die Pruefung beginnt von vorn. Wer Termine anlegt; protokolliert als waitlist_entry.reviewed.';

CREATE FUNCTION public.copy_platform_diary(p_access_id uuid, p_from_day date, p_from_meal text, p_to_day date, p_to_meal text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_zugang public.platform_accesses%rowtype;
  v_anzahl integer;
begin
  v_profil := app.platform_diary_for_writing(p_access_id, p_to_day, true);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if p_from_day is null or p_to_day is null
     or (p_from_meal is not null and p_from_meal not in ('breakfast', 'lunch', 'dinner', 'snack'))
     or (p_to_meal is not null and p_to_meal not in ('breakfast', 'lunch', 'dinner', 'snack'))
     or (p_from_meal is null and p_to_meal is not null) then
    raise exception 'day and meal are required' using errcode = '22023';
  end if;
  if p_from_day < v_profil.started_on or p_from_day > app.training_today(v_profil.organization_id) then
    raise exception 'day outside the counselling' using errcode = '22023';
  end if;
  if p_from_day = p_to_day and coalesce(p_to_meal, p_from_meal) is not distinct from p_from_meal then
    raise exception 'copy onto itself' using errcode = '22023';
  end if;

  select count(*) into v_anzahl from public.nutrition_diary_entries e
  where e.profile_id = v_profil.id and e.eaten_on = p_from_day
    and (p_from_meal is null or e.meal = p_from_meal);
  if v_anzahl = 0 then
    return 0;
  end if;
  if v_anzahl + (select count(*) from public.nutrition_diary_entries e
                 where e.profile_id = v_profil.id and e.eaten_on = p_to_day)
     > app.nutrition_diary_rule('entries_per_day') then
    raise exception 'too many entries on this day' using errcode = '54000';
  end if;

  insert into public.nutrition_diary_entries (
    organization_id, profile_id, eaten_on, meal, food_kind, catalog_food_id, custom_food_id,
    food_name, food_brand, base_unit, energy_kcal, protein_g, fat_g, carbohydrate_g, sugar_g,
    fibre_g, saturated_fat_g, salt_g, amount, portion_label, portion_amount, portion_count,
    platform_access_id, platform_access_kind, created_at, created_by, updated_by
  )
  select e.organization_id, e.profile_id, p_to_day, coalesce(p_to_meal, e.meal), e.food_kind,
         e.catalog_food_id, e.custom_food_id, e.food_name, e.food_brand, e.base_unit,
         e.energy_kcal, e.protein_g, e.fat_g, e.carbohydrate_g, e.sugar_g, e.fibre_g,
         e.saturated_fat_g, e.salt_g, e.amount, e.portion_label, e.portion_amount,
         e.portion_count, v_zugang.id, v_zugang.access_kind,
         -- Die Reihenfolge des Tages bleibt erhalten.
         clock_timestamp() + (row_number() over (order by e.created_at, e.id)) * interval '1 microsecond',
         auth.uid(), auth.uid()
  from public.nutrition_diary_entries e
  where e.profile_id = v_profil.id and e.eaten_on = p_from_day
    and (p_from_meal is null or e.meal = p_from_meal);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.copy_platform_diary(p_access_id uuid, p_from_day date, p_from_meal text, p_to_day date, p_to_meal text) IS 'ERN-008 (ADR-027 Punkt 10): eine Mahlzeit oder einen Tag kopieren - mit Stand und Menge der Einträge, an einen Tag zwischen Beginn und heute; höchstens 80 Einträge am Ziel. Wie add_platform_diary_entry: Einwilligung, eingeschaltet, nicht in der Lesefrist, nie die Begleitung. Liefert die Zahl der kopierten Einträge.';

CREATE FUNCTION public.count_orphaned_patient_file_objects() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_anzahl integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if not app.can_execute_storage_deletion() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'storage_deletion.read', 'not allowed to read the storage reconciliation');
    return null;
  end if;

  if v_org is null or not app.can_execute_storage_deletion() then
    raise exception 'not allowed to read the storage reconciliation' using errcode = '42501';
  end if;

  select count(*)
    into v_anzahl
  from storage.objects o
  where o.bucket_id in (app.patient_file_bucket(), app.patient_photo_bucket(),
                        app.message_attachment_bucket(), app.fleet_photo_bucket(),
                        app.reimbursement_receipt_bucket(), app.chat_attachment_bucket())
    and o.name like v_org::text || '/%'
    and not exists (
      select 1
      from public.patient_files f
      where f.object_key = o.name
        and app.patient_file_bucket_for(f.document_type) = o.bucket_id
    )
    and not exists (
      select 1
      from public.platform_message_attachments x
      where x.object_key = o.name
        and o.bucket_id = app.message_attachment_bucket()
    )
    and not exists (
      select 1
      from public.fleet_photos x
      where x.object_key = o.name
        and o.bucket_id = app.fleet_photo_bucket()
    )
    and not exists (
      select 1
      from public.staff_reimbursement_receipts x
      where x.object_key = o.name
        and o.bucket_id = app.reimbursement_receipt_bucket()
    )
    and not exists (
      select 1
      from public.team_message_attachments x
      where x.object_key = o.name
        and o.bucket_id = app.chat_attachment_bucket()
    )
    and not exists (
      select 1
      from public.storage_deletion_orders d
      where d.bucket_id = o.bucket_id
        and d.object_key = o.name
        and d.receipted_at is null
    );

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.count_orphaned_patient_file_objects() IS 'Anzahl der Objekte ohne Datensatz in der eigenen Organisation (ADR-017 Punkt 27).';

CREATE FUNCTION public.create_aftercare_subscription(p_patient_id uuid, p_starts_on date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_frueh  date;
  v_id     uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    raise exception 'not allowed to manage aftercare subscriptions' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  if p_starts_on is null then
    raise exception 'start date required' using errcode = '22023';
  end if;

  perform 1 from public.patients p
  where p.id = p_patient_id and p.organization_id = v_org
  for update;
  if not found then
    raise exception 'patient not found' using errcode = '42501';
  end if;

  v_frueh := app.aftercare_earliest_start(p_patient_id);
  if v_frueh is null then
    raise exception 'care is not concluded' using errcode = '22023';
  end if;
  if p_starts_on < (select p.care_concluded_on from public.patients p where p.id = p_patient_id) then
    raise exception 'aftercare cannot start before care is concluded' using errcode = '22023';
  end if;
  if p_starts_on < v_frueh then
    raise exception 'aftercare cannot start more than 14 days ago' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.aftercare_subscriptions s
    where s.patient_id = p_patient_id
      and (s.ends_on is null or s.ends_on >= p_starts_on)
  ) then
    raise exception 'an aftercare subscription already covers this date' using errcode = '23505';
  end if;

  insert into public.aftercare_subscriptions (organization_id, patient_id, starts_on, created_by)
  values (v_org, p_patient_id, p_starts_on, v_actor)
  returning id into v_id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_aftercare_subscription(p_patient_id uuid, p_starts_on date) IS 'ANG-001: Nachsorge-Abo anlegen (owner, office). Beginn fruehestens am Abschluss der Versorgung und hoechstens 14 Tage zurueck (ANN-268), nach dem Ende jedes frueheren Abos; je Person hoechstens ein laufendes.';

CREATE FUNCTION public.create_appointment(p_patient_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false, p_treatment_basis_id uuid DEFAULT NULL::uuid, p_confirmed_past boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor          uuid;
  v_org            uuid;
  v_time_zone      text;
  v_heute          date;
  v_starts_at      timestamptz;
  v_ends_at        timestamptz;
  v_street         text;
  v_house          text;
  v_postal         text;
  v_city           text;
  v_location_id    uuid;
  v_appointment_id uuid;
  v_grid           smallint;
  v_ausserhalb     boolean;
  v_verordnung     uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_create_appointment() then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  if p_appointment_type is null
     or p_appointment_type not in ('home_visit', 'practice', 'video') then
    raise exception 'unknown appointment type' using errcode = '22023';
  end if;

  if p_date is null or p_start_time is null or p_end_time is null then
    raise exception 'date, start time and end time are required' using errcode = '22023';
  end if;

  if p_end_time <= p_start_time then
    raise exception 'end time must be after start time' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes
    into v_time_zone, v_grid
  from public.organizations o
  where o.id = v_org;

  if v_time_zone is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  v_heute := (now() at time zone v_time_zone)::date;

  -- FIX-019, ANN-057: Die Vergangenheit ist erlaubt, aber nie unbemerkt.
  -- Ohne Bestaetigung bleibt die Abweisung aus CAL-003 - die Oberflaeche
  -- fragt nach und schickt den Vorgang bestaetigt neu.
  if p_date < v_heute and not coalesce(p_confirmed_past, false) then
    raise exception 'appointment date is in the past' using errcode = '22023';
  end if;

  if not app.is_on_appointment_grid(p_start_time, v_grid) then
    raise exception 'start time is not on the appointment grid' using errcode = '22023';
  end if;

  -- PROJECT_PRINCIPLES.md 0.11 Abschnitt 8.1: Die Laenge ist frei, aber sie
  -- liegt im Raster - mindestens ein Rasterschritt, ein ganzes Vielfaches
  -- davon (CAL-020, ANN-056). Mit dem Beginn im Raster liegt so auch das Ende
  -- auf einem Rasterpunkt.
  if not app.is_valid_treatment_length(p_end_time - p_start_time, v_grid) then
    raise exception 'appointment length is not on the appointment grid' using errcode = '22023';
  end if;

  v_starts_at := (p_date + p_start_time) at time zone v_time_zone;
  v_ends_at   := (p_date + p_end_time)   at time zone v_time_zone;

  -- B1 (BEF-151, ANN-510): Jede Akte der Organisation ist planbar - der
  -- Versorgungsstatus ist entfallen. Geprueft wird nur noch, dass es sie gibt.
  perform 1
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- Die Grundlage muss zur Organisation UND zu derselben Patient:in gehoeren.
  -- Eine fremde und eine unbekannte ID erzeugen dieselbe Meldung und taugen
  -- damit nicht als Existenz-Orakel (PROJECT_PRINCIPLES.md 13).
  if p_treatment_basis_id is not null then
    select p.id into v_verordnung
    from public.treatment_bases p
    where p.id = p_treatment_basis_id
      and p.organization_id = v_org
      and p.patient_id = p_patient_id;

    if not found then
      raise exception 'treatment basis not found' using errcode = 'P0002';
    end if;
  end if;

  if not app.is_assignable_therapist(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;

  v_ausserhalb := not app.is_within_working_hours(
    p_staff_member_id, v_org, p_date, p_start_time, p_end_time
  );

  if v_ausserhalb and not coalesce(p_allow_outside_working_hours, false) then
    raise exception 'outside_working_hours' using errcode = '22023';
  end if;

  if p_appointment_type = 'practice' then
    if p_location_id is null then
      raise exception 'practice appointment requires a location' using errcode = '22023';
    end if;

    select l.id into v_location_id
    from public.locations l
    where l.id = p_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  else
    v_location_id := null;
  end if;

  if p_appointment_type = 'home_visit' then
    select
      nullif(btrim(c.street), ''),
      nullif(btrim(c.house_number), ''),
      nullif(btrim(c.postal_code), ''),
      nullif(btrim(c.city), '')
      into v_street, v_house, v_postal, v_city
    from public.patient_contact_details c
    where c.patient_id = p_patient_id;

    if v_street is null or v_house is null or v_postal is null or v_city is null then
      raise exception 'home visit requires a complete patient address' using errcode = '22023';
    end if;
  end if;

  begin
    insert into public.appointments (
      organization_id, patient_id, staff_member_id, location_id,
      appointment_type, kind, status, starts_at, ends_at,
      visit_street, visit_house_number, visit_postal_code, visit_city,
      treatment_basis_id, created_by
    )
    values (
      v_org, p_patient_id, p_staff_member_id, v_location_id,
      -- ADR-018 Punkt 2: Ein angelegter Termin ist bestaetigt. 'requested' und
      -- 'tentative' gibt es erst mit einem Portal, das sie erzeugen kann.
      p_appointment_type, 'therapy', 'confirmed', v_starts_at, v_ends_at,
      v_street, v_house, v_postal, v_city,
      v_verordnung, v_actor
    )
    returning id into v_appointment_id;
  exception
    when exclusion_violation then
      raise exception 'appointment overlaps an existing one' using errcode = '23P01';
  end;


  return v_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.create_appointment(p_patient_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean, p_treatment_basis_id uuid, p_confirmed_past boolean) IS 'Legt einen Behandlungstermin im Zustand confirmed an. Die Laenge ist frei im Praxisraster (CAL-020); geprueft werden Raster des Beginns, Arbeitszeit und Belegung (CAL-003, CAL-005, CAL-007, ADR-018). Ein Tag in der Vergangenheit verlangt p_confirmed_past und steht im Auditkontext (FIX-019, ANN-057).';

CREATE FUNCTION public.create_appointment_event(p_title text, p_staff_member_ids uuid[], p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor       uuid;
  v_org         uuid;
  v_tz          text;
  v_grid        smallint;
  v_heute       date;
  v_starts_at   timestamptz;
  v_ends_at     timestamptz;
  v_titel       text;
  v_location_id uuid;
  v_gruppe      uuid;
  v_personen    uuid[];
  v_person      uuid;
  v_ausserhalb  boolean;
  v_id          uuid;
  v_anzahl      integer := 0;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_create_appointment() then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  v_titel := btrim(coalesce(p_title, ''));
  if v_titel = '' then
    raise exception 'event title is required' using errcode = '22023';
  end if;
  if length(v_titel) > 120 then
    raise exception 'event title is too long' using errcode = '22023';
  end if;

  if p_staff_member_ids is null or array_length(p_staff_member_ids, 1) is null then
    raise exception 'event needs at least one participant' using errcode = '22023';
  end if;

  -- Doppelt genannt ist einmal beteiligt. Ohne das Zusammenfassen bekaeme die
  -- Person zwei Zeilen zur selben Zeit - und die zweite scheiterte an der
  -- Ueberschneidung mit der ersten (CAL-017).
  select coalesce(array_agg(distinct p), array[]::uuid[])
    into v_personen
  from unnest(p_staff_member_ids) as p
  where p is not null;

  if array_length(v_personen, 1) is null then
    raise exception 'event needs at least one participant' using errcode = '22023';
  end if;

  -- Ein Ereignis findet in der Praxis oder als Video statt. Ein Hausbesuch
  -- ohne Patient:in waere ein Termin ohne Anschrift.
  if p_appointment_type is null or p_appointment_type not in ('practice', 'video') then
    raise exception 'unknown appointment type' using errcode = '22023';
  end if;

  if p_date is null or p_start_time is null or p_end_time is null then
    raise exception 'date, start time and end time are required' using errcode = '22023';
  end if;

  if p_end_time <= p_start_time then
    raise exception 'end time must be after start time' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes
    into v_tz, v_grid
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  -- Frei waehlbar heisst frei im RASTER: Beide Enden liegen auf einem
  -- Rasterpunkt. Beim Behandlungstermin genuegt der Beginn, weil die Laenge
  -- fest ist; hier ist sie es nicht (PROJECT_PRINCIPLES.md 8.1).
  if not app.is_on_appointment_grid(p_start_time, v_grid) then
    raise exception 'start time is not on the appointment grid' using errcode = '22023';
  end if;
  if not app.is_on_appointment_grid(p_end_time, v_grid) then
    raise exception 'end time is not on the appointment grid' using errcode = '22023';
  end if;

  v_heute := (now() at time zone v_tz)::date;
  if p_date < v_heute then
    raise exception 'appointment date is in the past' using errcode = '22023';
  end if;

  v_starts_at := (p_date + p_start_time) at time zone v_tz;
  v_ends_at   := (p_date + p_end_time)   at time zone v_tz;

  if p_appointment_type = 'practice' then
    if p_location_id is null then
      raise exception 'practice appointment requires a location' using errcode = '22023';
    end if;

    select l.id into v_location_id
    from public.locations l
    where l.id = p_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  else
    v_location_id := null;
  end if;

  v_gruppe := gen_random_uuid();

  foreach v_person in array v_personen
  loop
    -- Eigene Pruefung statt is_assignable_therapist: Beteiligte eines
    -- Ereignisses sind Beschaeftigte, nicht notwendig Behandelnde.
    if not exists (
      select 1 from public.staff_members sm
      where sm.id = v_person
        and sm.organization_id = v_org
        and sm.employment_status = 'active'
    ) then
      raise exception 'staff member not found' using errcode = 'P0002';
    end if;

    v_ausserhalb := not app.is_within_working_hours(
      v_person, v_org, p_date, p_start_time, p_end_time
    );

    if v_ausserhalb and not coalesce(p_allow_outside_working_hours, false) then
      raise exception 'outside_working_hours' using errcode = '22023';
    end if;

    begin
      insert into public.appointments (
        organization_id, patient_id, staff_member_id, location_id,
        appointment_type, kind, title, event_group_id, status, starts_at, ends_at, created_by
      )
      values (
        v_org, null, v_person, v_location_id,
        p_appointment_type, 'internal', v_titel, v_gruppe, 'confirmed',
        v_starts_at, v_ends_at, v_actor
      )
      returning id into v_id;
    exception
      when exclusion_violation then
        raise exception 'appointment overlaps an existing one' using errcode = '23P01';
    end;


    v_anzahl := v_anzahl + 1;
  end loop;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.create_appointment_event(p_title text, p_staff_member_ids uuid[], p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean) IS 'Legt ein Ereignis des Praxisbetriebs an - je beteiligter Person eine Zeile, alles oder nichts, alle unter einer gemeinsamen Gruppenkennung (CAL-015b, CAL-017). Doppelt genannte Beteiligte zaehlen einmal. Kein Patient, keine Verordnung, keine Leistung.';

CREATE FUNCTION public.create_appointment_from_waitlist(p_entry_id uuid, p_patient_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false, p_treatment_basis_id uuid DEFAULT NULL::uuid, p_confirmed_past boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_eintrag public.waitlist_entries;
  v_termin  uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  select * into v_eintrag
  from public.waitlist_entries w
  where w.id = p_entry_id and w.organization_id = v_org
  for update;
  if not found then
    raise exception 'waitlist entry not found' using errcode = 'P0002';
  end if;
  -- Die Person im Formular muss die des Eintrags sein - ein veralteter oder
  -- veraenderter Verweis legt sonst den Termin fuer jemand anderen an.
  if p_patient_id is null or v_eintrag.patient_id <> p_patient_id then
    raise exception 'waitlist entry belongs to another patient' using errcode = '22023';
  end if;
  if v_eintrag.status <> 'open' then
    raise exception 'waitlist entry closed' using errcode = '22023';
  end if;

  v_termin := public.create_appointment(
    v_eintrag.patient_id,
    p_staff_member_id,
    p_appointment_type,
    p_date,
    p_start_time,
    p_end_time,
    p_location_id,
    p_allow_outside_working_hours,
    p_treatment_basis_id,
    p_confirmed_past
  );

  perform app.close_waitlist_entry(v_org, v_actor, p_entry_id, 'placed', v_termin);

  return v_termin;
end;
$$;

COMMENT ON FUNCTION public.create_appointment_from_waitlist(p_entry_id uuid, p_patient_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean, p_treatment_basis_id uuid, p_confirmed_past boolean) IS 'Nachruecken (PRX-004): legt den Termin fuer die Person eines offenen Wartelisteneintrags ueber create_appointment an und schliesst den Eintrag als eingeplant - in einer Transaktion. Die Person der Adresszeile muss die des Eintrags sein (Zweitreview 3).';

CREATE FUNCTION public.create_appointment_series(p_patient_id uuid, p_treatment_basis_id uuid, p_staff_member_id uuid, p_appointment_type text, p_slots jsonb, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_dauer  interval;
  v_i      integer;
  v_datum  date;
  v_beginn time;
  v_anzahl integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Die aufgerufene Funktion prueft dasselbe Recht noch einmal. Hier steht es,
  -- damit die Meldung die Ursache trifft, statt auf halbem Weg zu scheitern.
  if not app.can_create_appointment() then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  if p_treatment_basis_id is null then
    raise exception 'treatment basis is required' using errcode = '22023';
  end if;

  if p_slots is null or jsonb_typeof(p_slots) <> 'array'
     or jsonb_array_length(p_slots) = 0 then
    raise exception 'slots must be a non-empty array' using errcode = '22023';
  end if;

  if jsonb_array_length(p_slots) > app.appointment_series_limit() then
    raise exception 'series is limited to % appointments', app.appointment_series_limit()
      using errcode = '22023';
  end if;

  v_dauer := make_interval(mins => app.appointment_window_minutes());

  for v_i in 0 .. jsonb_array_length(p_slots) - 1 loop
    v_datum  := (p_slots -> v_i ->> 'datum')::date;
    v_beginn := (p_slots -> v_i ->> 'beginn')::time;

    if v_datum is null or v_beginn is null then
      raise exception 'slot % is incomplete', v_i using errcode = '22023';
    end if;

    -- Laeuft das Fenster ueber Mitternacht, wuerde die Zeitarithmetik
    -- stillschweigend umlaufen (23:30 + 60 Minuten = 00:30). Lieber hier
    -- abweisen als am Folgetag anlegen.
    if (v_beginn + v_dauer)::time <= v_beginn then
      raise exception 'slot % crosses midnight', v_i using errcode = '22023';
    end if;

    perform public.create_appointment(
      p_patient_id,
      p_staff_member_id,
      p_appointment_type,
      v_datum,
      v_beginn,
      (v_beginn + v_dauer)::time,
      p_location_id,
      p_allow_outside_working_hours,
      p_treatment_basis_id
    );
    v_anzahl := v_anzahl + 1;
  end loop;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.create_appointment_series(p_patient_id uuid, p_treatment_basis_id uuid, p_staff_member_id uuid, p_appointment_type text, p_slots jsonb, p_location_id uuid, p_allow_outside_working_hours boolean) IS 'Legt die Termine einer Behandlungsgrundlage in einem Vorgang an (CAL-007). Ruft je Zeile create_appointment auf; alles oder nichts.';

CREATE FUNCTION public.create_correction_draft(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_alt    record;
  v_id     uuid;
  v_anzahl integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.* into v_alt
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.invoice_cancellations c where c.invoice_id = p_invoice_id
  ) then
    raise exception 'only a cancelled invoice can be corrected' using errcode = '23514';
  end if;

  if exists (
    select 1 from public.invoices i
    where i.organization_id = v_org
      and i.patient_id is not distinct from v_alt.patient_id
      and i.training_relationship_id is not distinct from v_alt.training_relationship_id
      and i.service_area = v_alt.service_area
      and i.status = 'draft'
      -- ABR-032: dieselbe Klammer - die Grundlage, ohne sie der Monat.
      and i.treatment_basis_id is not distinct from v_alt.treatment_basis_id
      and (v_alt.treatment_basis_id is not null or i.period_month = v_alt.period_month)
  ) then
    raise exception 'a draft for this patient, month and service area already exists'
      using errcode = '23505';
  end if;

  insert into public.invoices (
    organization_id, patient_id, training_relationship_id, recipient_id, period_month,
    service_area, replaces_invoice_id, treatment_basis_id, created_by
  )
  values (v_org, v_alt.patient_id, v_alt.training_relationship_id, v_alt.recipient_id,
          v_alt.period_month, v_alt.service_area, p_invoice_id, v_alt.treatment_basis_id, v_actor)
  returning id into v_id;

  -- BEF-143: Was die Korrektur aufnimmt, steht einmal in
  -- app.correction_draft_services - get_invoice fragt dort, ob es etwas gibt.
  insert into public.invoice_items (organization_id, invoice_id, billable_service_id, sort_order)
  select v_org, v_id, z.billable_service_id, z.sort_order
  from app.correction_draft_services(p_invoice_id) z;

  get diagnostics v_anzahl = row_count;

  if v_anzahl = 0 then
    raise exception 'no billable services for this patient, month and service area'
      using errcode = '22023';
  end if;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_correction_draft(p_invoice_id uuid) IS 'Legt zu einer stornierten Rechnung den Entwurf der Korrekturrechnung an und verweist von ihm auf die ersetzte Rechnung (ABR-003c, ADR-009 Punkt 9, R3-009). Nimmt alle wieder freien Leistungen der Klammer der stornierten Rechnung auf (ANN-077, ABR-009, TRN-008, ABR-032) - seit UX-008b ohne die, die eine andere offene Stornierung haelt (ANN-321); die Auswahl steht seit BEF-143 in app.correction_draft_services. Sperrt die Rechnung, damit zwei gleichzeitige Aufrufe nicht im Unique-Index enden.';

CREATE FUNCTION public.create_event_series(p_title text, p_staff_member_ids uuid[], p_appointment_type text, p_dates date[], p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_serie  uuid;
  v_anzahl integer;
  v_i      integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Die aufgerufene Funktion prueft dasselbe Recht noch einmal. Hier steht es,
  -- damit die Meldung die Ursache trifft, statt auf halbem Weg zu scheitern.
  if not app.can_create_appointment() then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  v_anzahl := coalesce(array_length(p_dates, 1), 0);

  if v_anzahl = 0 then
    raise exception 'series needs at least one date' using errcode = '22023';
  end if;

  if v_anzahl > app.appointment_series_limit() then
    raise exception 'series is limited to % appointments', app.appointment_series_limit()
      using errcode = '22023';
  end if;

  for v_i in 1 .. v_anzahl loop
    if p_dates[v_i] is null then
      raise exception 'series date % is missing', v_i using errcode = '22023';
    end if;
    if v_i > 1 and p_dates[v_i] <= p_dates[v_i - 1] then
      raise exception 'series dates must be distinct and ascending' using errcode = '22023';
    end if;
  end loop;

  v_serie := gen_random_uuid();
  perform set_config('app.event_series_id', v_serie::text, true);

  for v_i in 1 .. v_anzahl loop
    -- Die Ueberschneidung bekommt ihren Tag mit: Bei einer Serie ueber sechs
    -- Wochen ist "jemand ist belegt" ohne das Datum keine brauchbare Auskunft.
    begin
      perform public.create_appointment_event(
        p_title,
        p_staff_member_ids,
        p_appointment_type,
        p_dates[v_i],
        p_start_time,
        p_end_time,
        p_location_id,
        p_allow_outside_working_hours
      );
    exception
      when sqlstate '23P01' then
        raise exception 'occurrence on % overlaps an existing appointment', p_dates[v_i]
          using errcode = '23P01';
    end;
  end loop;

  perform set_config('app.event_series_id', '', true);

  return v_serie;
end;
$$;

COMMENT ON FUNCTION public.create_event_series(p_title text, p_staff_member_ids uuid[], p_appointment_type text, p_dates date[], p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean) IS 'Legt eine Serie gleichartiger Ereignisse an - je Tag ein Vorkommen, je Vorkommen eine Zeile pro beteiligter Person, alles oder nichts (CAL-021). Ruft je Vorkommen create_appointment_event auf und gibt die Serienkennung zurueck.';

CREATE FUNCTION public.create_exercise_plan(p_area text, p_relationship_id uuid, p_title text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_title text;
  v_ende  date;
  v_id    uuid;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Erst die Rolle, dann die Eingabe (ADR-023 Punkt 21).
  if not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    raise exception 'not allowed to write exercise plans' using errcode = '42501';
  end if;
  if p_area is null or p_area not in ('therapy', 'training') then
    raise exception 'service area is invalid' using errcode = '22023';
  end if;
  if not app.can_write_exercise_plans(p_area) then
    raise exception 'not allowed to write exercise plans' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write exercise plans' using errcode = '42501';
  end if;

  v_title := app.exercise_plan_text(p_title, 80, 'title');
  if v_title is null then
    raise exception 'title is required' using errcode = '22023';
  end if;

  if p_area = 'therapy' then
    if not exists (
      select 1 from public.patients p where p.id = p_relationship_id and p.organization_id = v_org
    ) then
      raise exception 'relationship not found' using errcode = 'P0002';
    end if;
    insert into public.exercise_plans (
      organization_id, service_area, patient_id, title, created_by, updated_by
    )
    values (v_org, 'therapy', p_relationship_id, v_title, v_actor, v_actor)
    returning id into v_id;
  else
    select t.contract_ended_on into v_ende
    from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org;
    if not found then
      raise exception 'relationship not found' using errcode = 'P0002';
    end if;
    if v_ende is not null then
      raise exception 'training relationship has ended' using errcode = '23514';
    end if;
    insert into public.exercise_plans (
      organization_id, service_area, training_relationship_id, title, created_by, updated_by
    )
    values (v_org, 'training', p_relationship_id, v_title, v_actor, v_actor)
    returning id into v_id;
  end if;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_exercise_plan(p_area text, p_relationship_id uuid, p_title text) IS 'UEB-004: legt einen leeren Planentwurf an der Akte (therapy) oder am Trainingsverhaeltnis (training) an. Nur nach app.can_write_exercise_plans(Bereich) (ANN-298).';

CREATE FUNCTION public.create_exercise_plan_version(p_plan_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_plan  public.exercise_plans%rowtype;
  v_id    uuid;
begin
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'assigned' then
    raise exception 'only an assigned exercise plan gets a new version' using errcode = '22023';
  end if;
  perform app.exercise_plan_relationship_open(v_plan);
  if exists (select 1 from public.exercise_plans f where f.previous_plan_id = v_plan.id) then
    raise exception 'exercise plan already has a new version' using errcode = '23505';
  end if;

  begin
    insert into public.exercise_plans (
      organization_id, service_area, patient_id, training_relationship_id, title,
      sessions_per_week, previous_plan_id, created_by, updated_by
    )
    values (
      v_plan.organization_id, v_plan.service_area, v_plan.patient_id,
      v_plan.training_relationship_id, v_plan.title, v_plan.sessions_per_week, v_plan.id,
      v_actor, v_actor
    )
    returning id into v_id;
  exception
    when unique_violation then
      raise exception 'exercise plan already has a new version' using errcode = '23505';
  end;

  insert into public.exercise_plan_items (
    organization_id, plan_id, position, variant_id, sets, reps_min, reps_max,
    duration_seconds, load, tempo, rest_seconds, double_progression, note,
    hold_seconds, per_side, times_per_day, previous_item_id, created_by, updated_by
  )
  select i.organization_id, v_id, i.position, i.variant_id, i.sets, i.reps_min, i.reps_max,
         i.duration_seconds, i.load, i.tempo, i.rest_seconds, i.double_progression, i.note,
         i.hold_seconds, i.per_side, i.times_per_day, i.id, v_actor, v_actor
  from public.exercise_plan_items i
  where i.plan_id = v_plan.id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_exercise_plan_version(p_plan_id uuid) IS 'UEB-006/UEB-012: legt zu einem zugewiesenen Plan die neue Fassung als Entwurf an - Titel, Einheiten je Woche und alle Positionen samt Dosierung mit Verweis auf ihre vorige (ANN-301). Hoechstens eine Folgefassung je Plan. Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.create_invoice_draft(p_patient_id uuid, p_period_month date, p_service_area text DEFAULT 'therapy'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_monat   date;
  v_bereich text;
  v_id      uuid;
  v_empf    uuid;
  v_anzahl  integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  v_monat := date_trunc('month', p_period_month)::date;
  v_bereich := coalesce(nullif(btrim(p_service_area), ''), 'therapy');

  if v_bereich not in ('therapy', 'training') then
    raise exception 'unknown service area %', p_service_area using errcode = '22023';
  end if;

  -- TRN-008: Trainingsleistungen haengen am Trainingsverhaeltnis, nie an der
  -- Akte (ADR-021 Punkt 3). Ihr Entwurf entsteht ueber
  -- create_training_invoice_draft; hier gibt es fuer `training` nichts zu
  -- finden, und die Meldung sagt, wo es steht.
  if v_bereich = 'training' then
    raise exception 'training invoices are drafted for the training relationship (create_training_invoice_draft)'
      using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.patients p
    where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = '42501';
  end if;

  -- Die Vorgabe aus den Stammdaten; ohne sie geht die Rechnung an die
  -- Patientin selbst (ANN-076).
  select r.id into v_empf
  from public.invoice_recipients r
  where r.patient_id = p_patient_id and r.is_default;

  -- ABR-032: Leistungen an Terminen mit Grundlage gehoeren auf die Rechnung
  -- ihrer Grundlage (create_invoice_draft_for_basis); der Monat buendelt nur
  -- noch, was keine hat.
  insert into public.invoices (
    organization_id, patient_id, recipient_id, period_month, service_area, created_by
  )
  values (v_org, p_patient_id, v_empf, v_monat, v_bereich, v_actor)
  returning id into v_id;

  insert into public.invoice_items (organization_id, invoice_id, billable_service_id, sort_order)
  select v_org, v_id, z.id, z.nummer
  from (
    select b.id,
           row_number() over (order by b.performed_on, c.code, b.id)::smallint as nummer
    from public.billable_services b
    join public.service_catalog_items c on c.id = b.catalog_item_id
    -- ANG-002: Ein Abo-Monat hat keinen Termin und damit keine Grundlage.
    left join public.appointments a     on a.id = b.appointment_id
    where b.organization_id = v_org
      and b.patient_id = p_patient_id
      and b.status = 'billable'
      and b.service_area = v_bereich
      and a.treatment_basis_id is null
      and date_trunc('month', b.performed_on)::date = v_monat
      and not exists (
        select 1 from public.invoice_items it
        where it.billable_service_id = b.id and it.released_at is null
      )
  ) z;

  get diagnostics v_anzahl = row_count;

  if v_anzahl = 0 then
    raise exception 'no billable services for this patient, month and service area'
      using errcode = '22023';
  end if;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_invoice_draft(p_patient_id uuid, p_period_month date, p_service_area text) IS 'Legt den Rechnungsentwurf einer Patientin fuer einen Kalendermonat und einen Leistungsbereich an und nimmt alle noch nicht abgerechneten Leistungen dieses Bereichs auf (ABR-003, ABR-009, ANN-077). Je Patientin, Monat und Bereich hoechstens ein Entwurf; eine Person mit beiden Verhaeltnissen bekommt zwei Rechnungen.';

CREATE FUNCTION public.create_invoice_draft_for_basis(p_treatment_basis_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_monat   date;
  v_id      uuid;
  v_empf    uuid;
  v_anzahl  integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select tb.patient_id into v_patient
  from public.treatment_bases tb
  where tb.id = p_treatment_basis_id and tb.organization_id = v_org;

  if not found then
    raise exception 'treatment basis not found' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.invoices i
    where i.treatment_basis_id = p_treatment_basis_id and i.status = 'draft'
  ) then
    raise exception 'a draft for this treatment basis already exists' using errcode = '23505';
  end if;

  -- Der Monat der ersten offenen Leistung: period_month bleibt Pflicht und
  -- nennt in Listen den Beginn.
  select date_trunc('month', min(b.performed_on))::date into v_monat
  from public.billable_services b
  join public.appointments a on a.id = b.appointment_id
  where b.organization_id = v_org
    and b.patient_id = v_patient
    and a.treatment_basis_id = p_treatment_basis_id
    and b.status = 'billable'
    and b.service_area = 'therapy'
    and not exists (
      select 1 from public.invoice_items it
      where it.billable_service_id = b.id and it.released_at is null
    );

  if v_monat is null then
    raise exception 'no billable services for this treatment basis' using errcode = '22023';
  end if;

  -- Die Vorgabe aus den Stammdaten; ohne sie geht die Rechnung an die
  -- Patientin selbst (ANN-076).
  select r.id into v_empf
  from public.invoice_recipients r
  where r.patient_id = v_patient and r.is_default;

  insert into public.invoices (
    organization_id, patient_id, recipient_id, period_month, service_area,
    treatment_basis_id, created_by
  )
  values (v_org, v_patient, v_empf, v_monat, 'therapy', p_treatment_basis_id, v_actor)
  returning id into v_id;

  insert into public.invoice_items (organization_id, invoice_id, billable_service_id, sort_order)
  select v_org, v_id, z.id, z.nummer
  from (
    select b.id,
           row_number() over (order by b.performed_on, c.sort_order, c.code, b.id)::smallint as nummer
    from public.billable_services b
    join public.service_catalog_items c on c.id = b.catalog_item_id
    join public.appointments a          on a.id = b.appointment_id
    where b.organization_id = v_org
      and b.patient_id = v_patient
      and a.treatment_basis_id = p_treatment_basis_id
      and b.status = 'billable'
      and b.service_area = 'therapy'
      and not exists (
        select 1 from public.invoice_items it
        where it.billable_service_id = b.id and it.released_at is null
      )
  ) z;

  get diagnostics v_anzahl = row_count;

  if v_anzahl = 0 then
    raise exception 'no billable services for this treatment basis' using errcode = '22023';
  end if;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_invoice_draft_for_basis(p_treatment_basis_id uuid) IS 'Legt den Rechnungsentwurf ueber alle offenen Leistungen der Termine einer Behandlungsgrundlage an (ABR-032, ADR-009 Punkt 23, ANN-077 Fassung 2). owner und office; je Grundlage hoechstens ein Entwurf.';

CREATE FUNCTION public.create_nutrition_appointment(p_profile_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false, p_confirmed_past boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_id     uuid;
begin
  -- Rolle, Profil (laufend, eigener Mandant) und Einwilligung (ADR-027
  -- Punkte 3 und 4) - eine Stelle mit den übrigen Schreibwegen der Beratung.
  v_profil := app.nutrition_profile_for_writing(p_profile_id, true);

  if not app.staff_can_counsel_nutrition(p_staff_member_id, v_profil.organization_id) then
    raise exception 'staff member does not counsel nutrition' using errcode = '22023';
  end if;

  if v_profil.patient_id is not null then
    v_id := public.create_appointment(
      v_profil.patient_id, p_staff_member_id, p_appointment_type, p_date, p_start_time,
      p_end_time, p_location_id, p_allow_outside_working_hours, null, p_confirmed_past);
  else
    v_id := public.create_training_appointment(
      v_profil.training_relationship_id, p_staff_member_id, p_appointment_type, p_date,
      p_start_time, p_end_time, p_location_id, p_allow_outside_working_hours, null,
      p_confirmed_past);
  end if;

  update public.appointments
     set occasion = 'nutrition_counselling'
   where id = v_id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_nutrition_appointment(p_profile_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean, p_confirmed_past boolean) IS 'ERN-011 (ANN-622, ANN-664): legt einen Termin mit dem Anlass Ernährungsberatung am Verhältnis des laufenden Profils an - an der Akte über create_appointment, am Trainingsverhältnis über create_training_appointment, ohne Grundlage. Allein app.can_counsel_nutrition, nur mit erteilter Einwilligung.';

CREATE FUNCTION public.create_nutrition_profile(p_kind text, p_relationship_id uuid, p_consent_on date, p_height_cm smallint, p_weight_kg numeric, p_formula_sex text, p_activity_pal numeric, p_goal text, p_body_fat_percent numeric DEFAULT NULL::numeric, p_target_weight_kg numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
  v_heute date;
  v_id    uuid;
begin
  if v_actor is null or not app.can_counsel_nutrition() then
    raise exception 'not allowed to counsel nutrition' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if p_kind is null or p_kind not in ('treatment', 'training') then
    raise exception 'unknown relationship kind' using errcode = '22023';
  end if;

  -- Das Verhältnis sperren: zwei gleichzeitige Anlagen werden nicht zwei Profile.
  if p_kind = 'treatment' then
    perform 1 from public.patients p
    where p.id = p_relationship_id and p.organization_id = v_org for update;
  else
    perform 1 from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org for update;
  end if;
  select * into v_rel from app.nutrition_relationship(p_kind, p_relationship_id, v_org);
  if v_rel.person_id is null then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;
  if not v_rel.is_open then
    raise exception 'relationship has ended' using errcode = '22023';
  end if;

  -- Punkt 3: ohne Einwilligung kein Profil.
  v_heute := app.training_today(v_org);
  if p_consent_on is null then
    raise exception 'nutrition consent missing' using errcode = '22023';
  end if;
  if p_consent_on > v_heute then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;
  if p_weight_kg is null then
    raise exception 'weight is required' using errcode = '22023';
  end if;

  -- Punkt 1: höchstens ein laufendes Profil je Person, über beide
  -- Verhältnisse. Die Sperre gilt der Person, nicht dem Verhältnis.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('nutrition:' || v_rel.person_id::text, 0));
  if exists (
    select 1
    from public.nutrition_profiles p
    left join public.patients pa on pa.id = p.patient_id
    left join public.training_relationships t on t.id = p.training_relationship_id
    where p.organization_id = v_org and p.ended_on is null
      and coalesce(pa.person_id, t.person_id) = v_rel.person_id
  ) then
    raise exception 'nutrition profile already running' using errcode = '23505';
  end if;

  -- Längen, Bereiche und Formeln prüfen die Constraints der Tabelle.
  insert into public.nutrition_profiles (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    started_on, height_cm, formula_sex, body_fat_percent, activity_pal, goal,
    target_weight_kg, target_weight_source, notes, created_by, updated_by
  )
  values (
    v_org, p_kind, p_relationship_id,
    case when p_kind = 'treatment' then p_relationship_id end,
    case when p_kind = 'training' then p_relationship_id end,
    v_heute, p_height_cm, p_formula_sex, p_body_fat_percent, p_activity_pal, p_goal,
    p_target_weight_kg, case when p_target_weight_kg is not null then 'counsellor' end,
    nullif(btrim(p_notes), ''), v_actor, v_actor
  )
  returning id into v_id;

  insert into public.nutrition_consent_records (
    organization_id, profile_id, record_kind, occurred_on, recorded_by
  )
  values (v_org, v_id, 'consent_granted', p_consent_on, v_actor);

  insert into public.nutrition_weight_entries (
    organization_id, profile_id, measured_on, weight_kg, source, recorded_by
  )
  values (v_org, v_id, v_heute, p_weight_kg, 'practice', v_actor);

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_nutrition_profile(p_kind text, p_relationship_id uuid, p_consent_on date, p_height_cm smallint, p_weight_kg numeric, p_formula_sex text, p_activity_pal numeric, p_goal text, p_body_fat_percent numeric, p_target_weight_kg numeric, p_notes text) IS 'ERN-001 (ADR-027 Punkte 1 bis 3, 5): legt das Ernährungsprofil am offenen Verhältnis an - mit dem Tag der Einwilligung vom Papier und dem ersten Gewicht, in einem Vorgang. Höchstens ein laufendes Profil je Person über beide Verhältnisse (23505). Allein app.can_counsel_nutrition (42501). Ein Zielgewicht der Beratung darf unter BMI 18,5 liegen und ist dann gekennzeichnet (Punkt 22).';

CREATE FUNCTION public.create_patient(p_given_name text, p_family_name text, p_date_of_birth date, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_house_number text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_phone_work text DEFAULT NULL::text, p_phone_mobile text DEFAULT NULL::text, p_institution text DEFAULT NULL::text, p_primary_therapist_staff_member_id uuid DEFAULT NULL::uuid, p_home_visit_access_note text DEFAULT NULL::text, p_special_note text DEFAULT NULL::text, p_remark text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor      uuid;
  v_org        uuid;
  v_person_id  uuid;
  v_patient_id uuid;
  v_given      text;
  v_family     text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_create_patient() then
    raise exception 'not allowed to create patients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create patients' using errcode = '42501';
  end if;

  -- Eingaben serverseitig normalisieren. Die Pruefung im Client ist
  -- Bedienkomfort, keine Zusicherung (ADR-004).
  v_given  := nullif(btrim(p_given_name), '');
  v_family := nullif(btrim(p_family_name), '');

  if v_given is null or v_family is null then
    raise exception 'given_name and family_name are required' using errcode = '22023';
  end if;

  if p_date_of_birth is null then
    raise exception 'date_of_birth is required' using errcode = '22023';
  end if;

  if p_date_of_birth > current_date then
    raise exception 'date_of_birth must not be in the future' using errcode = '22023';
  end if;

  perform app.assert_staff_member_in_org(p_primary_therapist_staff_member_id, v_org);

  insert into public.persons (organization_id, given_name, family_name, created_by)
  values (v_org, v_given, v_family, v_actor)
  returning id into v_person_id;

  insert into public.patients (organization_id, person_id, status, created_by)
  values (v_org, v_person_id, 'active', v_actor)
  returning id into v_patient_id;

  insert into public.patient_contact_details (
    patient_id, organization_id, date_of_birth,
    email, phone, street, house_number, postal_code, city,
    phone_work, phone_mobile, institution, created_by
  )
  values (
    v_patient_id, v_org, p_date_of_birth,
    nullif(btrim(p_email), ''),
    nullif(btrim(p_phone), ''),
    nullif(btrim(p_street), ''),
    nullif(btrim(p_house_number), ''),
    nullif(btrim(p_postal_code), ''),
    nullif(btrim(p_city), ''),
    nullif(btrim(p_phone_work), ''),
    nullif(btrim(p_phone_mobile), ''),
    nullif(btrim(p_institution), ''),
    v_actor
  );

  insert into public.patient_care_details (
    patient_id, organization_id, primary_therapist_staff_member_id,
    home_visit_access_note, special_note, remark, created_by
  )
  values (
    v_patient_id, v_org, p_primary_therapist_staff_member_id,
    nullif(btrim(p_home_visit_access_note), ''),
    nullif(btrim(p_special_note), ''),
    nullif(btrim(p_remark), ''),
    v_actor
  );


  return v_patient_id;
end;
$$;

COMMENT ON FUNCTION public.create_patient(p_given_name text, p_family_name text, p_date_of_birth date, p_email text, p_phone text, p_street text, p_house_number text, p_postal_code text, p_city text, p_phone_work text, p_phone_mobile text, p_institution text, p_primary_therapist_staff_member_id uuid, p_home_visit_access_note text, p_special_note text, p_remark text) IS 'Legt Person, Patient, Kontaktdaten und Versorgungsangaben atomar an und protokolliert patient.created (PAT-001, PAT-005, ADR-010). Seit SLK-001 ohne Telefax.';

CREATE FUNCTION public.create_patient_fee_agreement(p_patient_id uuid, p_valid_from date, p_session_fee_cents integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage fee agreements' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  if not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = '42501';
  end if;

  if p_valid_from is null then
    raise exception 'valid_from is required' using errcode = '22023';
  end if;

  if p_session_fee_cents is null or p_session_fee_cents not between 0 and 1000000 then
    raise exception 'session fee out of range' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.patient_fee_agreements f
    where f.patient_id = p_patient_id and f.valid_from = p_valid_from
  ) then
    raise exception 'a fee agreement from this day already exists' using errcode = '23505';
  end if;

  insert into public.patient_fee_agreements (
    organization_id, patient_id, valid_from, session_fee_cents, created_by
  )
  values (v_org, p_patient_id, p_valid_from, p_session_fee_cents, v_actor)
  returning id into v_id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_patient_fee_agreement(p_patient_id uuid, p_valid_from date, p_session_fee_cents integer) IS 'Legt eine Honorarvereinbarung ab einem Tag an (ABR-030, ANN-231). Nur owner. Bereits festgeschriebene Honorare aendert sie nicht (ANN-232).';

CREATE FUNCTION public.create_payment_reminder(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  -- Die Frist der Erinnerung, an genau einer Stelle (**ANN-080**). Vierzehn
  -- Tage sind die Frist, die auf dem Blatt steht - keine Rechtsfolge und kein
  -- Verzugsbeginn. Wer sie aendert, aendert sie hier.
  c_frist_tage constant integer := 14;
  v_actor    uuid;
  v_org      uuid;
  v_invoice  record;
  v_zeitzone text;
  v_heute    date;
  v_offen    integer;
  v_id       uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.* into v_invoice
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  -- An einem Entwurf gibt es nichts zu erinnern: Er traegt keine Nummer und
  -- keine Forderung (ANN-075).
  if v_invoice.status <> 'issued' then
    raise exception 'a payment reminder belongs to an issued invoice' using errcode = '23514';
  end if;

  if exists (
    select 1 from public.invoice_cancellations c where c.invoice_id = p_invoice_id
  ) then
    raise exception 'a cancelled invoice is not reminded' using errcode = '23514';
  end if;

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  -- Vor der Faelligkeit gibt es nichts zu erinnern.
  if v_invoice.due_on >= v_heute then
    raise exception 'this invoice is not overdue yet' using errcode = '23514';
  end if;

  -- Der offene Betrag kommt aus derselben Funktion wie jede andere Anzeige
  -- (ANN-078) - und wird hier festgeschrieben, weil er auf ein Blatt geht.
  v_offen := v_invoice.total_cents - app.invoice_paid_cents(p_invoice_id);

  if v_offen <= 0 then
    raise exception 'this invoice has nothing outstanding' using errcode = '23514';
  end if;

  if exists (
    select 1 from public.invoice_payment_reminders r
    where r.invoice_id = p_invoice_id and r.reminder_on = v_heute
  ) then
    raise exception 'a payment reminder for this invoice was already written today'
      using errcode = '23505';
  end if;

  insert into public.invoice_payment_reminders (
    organization_id, invoice_id, reminder_on, due_on, outstanding_cents, currency, created_by
  )
  values (v_org, p_invoice_id, v_heute, v_heute + c_frist_tage, v_offen,
          v_invoice.currency, v_actor)
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_payment_reminder(p_invoice_id uuid) IS 'Stellt zu einer ueberfaelligen Rechnung eine Zahlungserinnerung aus und schreibt den offenen Betrag darin fest (ABR-003d, IDEA-PRX-012, ANN-080, R3-009). Ohne Stufe, ohne Gebuehr, ohne eigene Nummer; sperrt die Rechnung, damit der festgeschriebene Betrag der Stand im selben Moment ist.';

CREATE FUNCTION public.create_prescriber(p_family_name text, p_given_name text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_practice_name text DEFAULT NULL::text, p_speciality text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_house_number text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_fax text DEFAULT NULL::text, p_email text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_family text;
  v_id     uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_manage_prescribers() then
    raise exception 'not allowed to manage prescribers' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage prescribers' using errcode = '42501';
  end if;

  v_family := nullif(btrim(p_family_name), '');
  if v_family is null then
    raise exception 'family_name is required' using errcode = '22023';
  end if;

  insert into public.prescribers (
    organization_id, title, given_name, family_name, practice_name, speciality,
    street, house_number, postal_code, city, phone, fax, email,
    created_by, updated_by
  )
  values (
    v_org,
    nullif(btrim(p_title), ''),
    nullif(btrim(p_given_name), ''),
    v_family,
    nullif(btrim(p_practice_name), ''),
    nullif(btrim(p_speciality), ''),
    nullif(btrim(p_street), ''),
    nullif(btrim(p_house_number), ''),
    nullif(btrim(p_postal_code), ''),
    nullif(btrim(p_city), ''),
    nullif(btrim(p_phone), ''),
    nullif(btrim(p_fax), ''),
    nullif(btrim(p_email), ''),
    v_actor, v_actor
  )
  returning id into v_id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_prescriber(p_family_name text, p_given_name text, p_title text, p_practice_name text, p_speciality text, p_street text, p_house_number text, p_postal_code text, p_city text, p_phone text, p_fax text, p_email text) IS 'Legt eine Verordner:in in der Organisation des Aufrufers an (VER-001).';

CREATE FUNCTION public.create_service_catalog_version(p_label text, p_valid_from date, p_copy_from uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_label text;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  v_label := nullif(btrim(p_label), '');
  if v_label is null then
    raise exception 'label is required' using errcode = '22023';
  end if;

  if p_valid_from is null then
    raise exception 'valid_from is required' using errcode = '22023';
  end if;

  insert into public.service_catalog_versions (organization_id, label, valid_from, created_by)
  values (v_org, v_label, p_valid_from, v_actor)
  returning id into v_id;

  -- ABR-030: Die Kopie nimmt den Tarif des Terminhonorars mit.
  if p_copy_from is not null then
    update public.service_catalog_versions n
       set session_fee_cents = q.session_fee_cents
      from public.service_catalog_versions q
     where n.id = v_id
       and q.id = p_copy_from
       and q.organization_id = v_org;
  end if;

  if p_copy_from is not null then
    insert into public.service_catalog_items (
      organization_id, catalog_version_id, sort_order, code, label,
      item_kind, remedy, unit_price_cents, currency, tax_treatment, tax_rate_permille,
      service_area, package_months, created_by
    )
    select v_org, v_id, q.sort_order, q.code, q.label,
           q.item_kind, q.remedy, q.unit_price_cents, q.currency,
           q.tax_treatment, q.tax_rate_permille, q.service_area,
           -- ANG-005: die Laufzeit des Trainingspakets geht mit.
           q.package_months, v_actor
    from public.service_catalog_items q
    join public.service_catalog_versions qv on qv.id = q.catalog_version_id
    where q.catalog_version_id = p_copy_from
      and qv.organization_id = v_org;

    -- Eine Vorlage, die es nicht gibt, ist ein Tippfehler und kein leerer
    -- Entwurf: Sonst entstuende stillschweigend eine Preisliste ohne Preise.
    if not exists (
      select 1 from public.service_catalog_items where catalog_version_id = v_id
    ) then
      raise exception 'copy source has no items' using errcode = '22023';
    end if;
  end if;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_service_catalog_version(p_label text, p_valid_from date, p_copy_from uuid) IS 'Legt eine Preisliste als Entwurf an, wahlweise als Kopie einer vorhandenen (ABR-001). Die Kopie nimmt seit ABR-008 den Leistungsbereich mit. Nur owner (ANN-071). Protokolliert service_catalog.version_created.';

CREATE FUNCTION public.create_staff_member(p_given_name text, p_family_name text, p_work_email text DEFAULT NULL::text, p_work_phone text DEFAULT NULL::text, p_primary_location_id uuid DEFAULT NULL::uuid, p_date_of_birth date DEFAULT NULL::date, p_private_email text DEFAULT NULL::text, p_private_phone text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor       uuid;
  v_org         uuid;
  v_person_id   uuid;
  v_staff_id    uuid;
  v_given       text;
  v_family      text;
  v_location_id uuid;
  v_priv_email  text;
  v_priv_phone  text;
  v_street      text;
  v_postal      text;
  v_city        text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_manage_staff_master_data() then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  v_given  := btrim(coalesce(p_given_name, ''));
  v_family := btrim(coalesce(p_family_name, ''));

  if v_given = '' or v_family = '' then
    raise exception 'given name and family name are required' using errcode = '22023';
  end if;

  v_priv_email := nullif(btrim(coalesce(p_private_email, '')), '');
  v_priv_phone := nullif(btrim(coalesce(p_private_phone, '')), '');
  v_street     := nullif(btrim(coalesce(p_street, '')), '');
  v_postal     := nullif(btrim(coalesce(p_postal_code, '')), '');
  v_city       := nullif(btrim(coalesce(p_city, '')), '');

  if not app.can_manage_staff_private_details()
     and (p_date_of_birth is not null or v_priv_email is not null or v_priv_phone is not null
          or v_street is not null or v_postal is not null or v_city is not null) then
    raise exception 'private_details_not_allowed' using errcode = '42501';
  end if;

  -- Standort ausschliesslich in der eigenen Organisation suchen: eine fremde
  -- und eine unbekannte ID sind damit ununterscheidbar.
  if p_primary_location_id is not null then
    select l.id into v_location_id
    from public.locations l
    where l.id = p_primary_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  end if;

  insert into public.persons (organization_id, given_name, family_name, created_by)
  values (v_org, v_given, v_family, v_actor)
  returning id into v_person_id;

  insert into public.staff_members (
    organization_id, person_id, primary_location_id,
    employment_status, work_email, work_phone, created_by
  )
  values (
    v_org, v_person_id, v_location_id,
    'active',
    nullif(btrim(coalesce(p_work_email, '')), ''),
    nullif(btrim(coalesce(p_work_phone, '')), ''),
    v_actor
  )
  returning id into v_staff_id;

  -- Die Zeile entsteht immer, auch wenn alle Felder leer bleiben. Damit hat
  -- eine spaetere Aenderung der Privatdaten einen festen Anker und muss nicht
  -- zwischen Anlegen und Aendern unterscheiden.
  insert into public.staff_private_details (
    staff_member_id, organization_id, date_of_birth,
    private_email, private_phone, street, postal_code, city, created_by
  )
  values (
    v_staff_id, v_org, p_date_of_birth,
    v_priv_email, v_priv_phone, v_street, v_postal, v_city, v_actor
  );


  return v_staff_id;
end;
$$;

COMMENT ON FUNCTION public.create_staff_member(p_given_name text, p_family_name text, p_work_email text, p_work_phone text, p_primary_location_id uuid, p_date_of_birth date, p_private_email text, p_private_phone text, p_street text, p_postal_code text, p_city text) IS 'Legt Person und Mitarbeiterdatensatz atomar an (owner und office, E10). Privatangaben nur durch owner. Erzeugt KEINEN Zugang und keine Rollen (STAFF-001, STAFF-002a).';

CREATE FUNCTION public.create_task(p_title text, p_note text DEFAULT NULL::text, p_due_on date DEFAULT NULL::date, p_assigned_staff_member_id uuid DEFAULT NULL::uuid, p_patient_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_tasks() then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;

  perform app.task_check_input(v_org, p_patient_id, p_assigned_staff_member_id);

  insert into public.tasks (
    organization_id, patient_id, assigned_staff_member_id, title, note, due_on,
    created_by, updated_by
  )
  values (
    v_org, p_patient_id, p_assigned_staff_member_id, btrim(p_title),
    nullif(btrim(p_note), ''), p_due_on, v_actor, v_actor
  )
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_task(p_title text, p_note text, p_due_on date, p_assigned_staff_member_id uuid, p_patient_id uuid) IS 'Legt eine Aufgabe an, optional mit Faelligkeit, Zuweisung und Personenbezug (PRX-012). Protokolliert task.created ohne Titel und Notiz (ADR-010). Alle vier Praxisrollen (ANN-142).';

CREATE FUNCTION public.create_team_channel(p_name text, p_description text DEFAULT NULL::text, p_private boolean DEFAULT false, p_members uuid[] DEFAULT '{}'::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_name  text;
  v_text  text := nullif(btrim(coalesce(p_description, '')), '');
  v_id    uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.can_manage_team_channels() then
    raise exception 'not allowed to manage team channels' using errcode = '42501';
  end if;
  v_name := app.team_channel_name(p_name, p_description);
  -- Eindeutig nur unter offenen Kanälen (Befund 5 des Zweitreviews).
  if not coalesce(p_private, false) and exists (
    select 1 from public.team_channels c
    where c.organization_id = v_org and c.kind = 'channel' and lower(c.name) = lower(v_name)
  ) then
    raise exception 'channel name is taken' using errcode = '23505';
  end if;
  insert into public.team_channels (organization_id, kind, name, description)
  values (v_org, case when coalesce(p_private, false) then 'private' else 'channel' end, v_name, v_text)
  returning id into v_id;
  if coalesce(p_private, false) then
    insert into public.team_channel_members (organization_id, channel_id, staff_member_id)
    select v_org, v_id, x.staff
    from (select v_staff as staff
          union
          select distinct u.staff from unnest(coalesce(p_members, '{}'::uuid[])) as u (staff)
          where u.staff is not null and app.teamchat_participant(v_org, u.staff)) x;
  end if;
  return v_id;
end;
$$;

CREATE FUNCTION public.create_text_snippet(p_title text, p_body text, p_shared boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_staff uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_use_text_snippets() then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  if coalesce(p_shared, false) then
    v_staff := null;
  else
    select sm.id into v_staff
    from public.staff_members sm
    where sm.person_id = app.current_person_id()
      and sm.organization_id = v_org;

    if v_staff is null then
      raise exception 'no staff member for this account' using errcode = '22023';
    end if;
  end if;

  perform app.assert_text_snippet_input(p_title, p_body, v_staff);

  insert into public.treatment_text_snippets (
    organization_id, staff_member_id, title, body, created_by, updated_by
  )
  values (v_org, v_staff, btrim(p_title), btrim(p_body, E' \t\r\n'), v_actor, v_actor)
  returning id into v_id;


  return v_id;
exception
  when unique_violation then
    raise exception 'a snippet with this title already exists' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.create_text_snippet(p_title text, p_body text, p_shared boolean) IS 'Legt einen Textbaustein an (UX-008). Praxisweit nur fuer owner; sonst persoenlich fuer die anfragende Person.';

CREATE FUNCTION public.create_therapy_report(p_treatment_basis_id uuid, p_supersedes_report_id uuid DEFAULT NULL::uuid, p_change_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_kind    text;
  v_id      uuid;
  v_alt     record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;

  select g.patient_id, g.treatment_basis_kind into v_patient, v_kind
  from public.treatment_bases g
  where g.id = p_treatment_basis_id and g.organization_id = v_org;
  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;
  if v_kind = 'self_pay' then
    raise exception 'a therapy report needs a prescription' using errcode = '22023';
  end if;

  -- ABN-016 (BEF-104): Eine Korrektur verweist auf den ersetzten,
  -- abgeschlossenen Bericht derselben Verordnung und traegt ihren Grund.
  if p_supersedes_report_id is not null then
    select r.status, r.treatment_basis_id into v_alt
    from public.therapy_reports r
    where r.id = p_supersedes_report_id and r.organization_id = v_org
    for update;
    if not found then
      raise exception 'therapy report not found' using errcode = 'P0002';
    end if;
    if v_alt.status <> 'abgeschlossen' then
      raise exception 'only a completed therapy report can be corrected' using errcode = '23514';
    end if;
    if v_alt.treatment_basis_id <> p_treatment_basis_id then
      raise exception 'correction must use the same treatment basis' using errcode = '23514';
    end if;
    if p_change_reason is null or length(btrim(p_change_reason)) not between 3 and 500 then
      raise exception 'a correction needs a reason' using errcode = '22023';
    end if;
    if exists (
      select 1 from public.therapy_reports r where r.supersedes_report_id = p_supersedes_report_id
    ) then
      raise exception 'therapy report already corrected' using errcode = '23505';
    end if;
  elsif p_change_reason is not null then
    raise exception 'a reason belongs to a correction' using errcode = '22023';
  end if;

  insert into public.therapy_reports (
    organization_id, patient_id, treatment_basis_id, created_by, updated_by,
    supersedes_report_id, change_reason
  )
  values (v_org, v_patient, p_treatment_basis_id, v_actor, v_actor,
          p_supersedes_report_id, nullif(btrim(p_change_reason), ''))
  returning id into v_id;


  return v_id;
end;
$$;

CREATE FUNCTION public.create_training_appointment(p_training_relationship_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false, p_training_basis_id uuid DEFAULT NULL::uuid, p_confirmed_past boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor          uuid;
  v_org            uuid;
  v_time_zone      text;
  v_grid           smallint;
  v_heute          date;
  v_starts_at      timestamptz;
  v_ends_at        timestamptz;
  v_status         text;
  v_basis_status   text;
  v_location_id    uuid;
  v_street         text;
  v_house          text;
  v_postal         text;
  v_city           text;
  v_ausserhalb     boolean;
  v_appointment_id uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_training_relationships() then
    -- Abgewiesen mit bestaetigtem denied-Eintrag und HTTP 403 (G6c, ANN-176).
    perform app.record_denied_write(v_actor, 'appointment.created', 'not allowed to create training appointments');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create training appointments' using errcode = '42501';
  end if;

  if p_appointment_type is null
     or p_appointment_type not in ('home_visit', 'practice', 'video') then
    raise exception 'unknown appointment type' using errcode = '22023';
  end if;

  if p_date is null or p_start_time is null or p_end_time is null then
    raise exception 'date, start time and end time are required' using errcode = '22023';
  end if;

  if p_end_time <= p_start_time then
    raise exception 'end time must be after start time' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes
    into v_time_zone, v_grid
  from public.organizations o
  where o.id = v_org;

  if v_time_zone is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  v_heute := (now() at time zone v_time_zone)::date;

  if p_date < v_heute and not coalesce(p_confirmed_past, false) then
    raise exception 'appointment date is in the past' using errcode = '22023';
  end if;

  if not app.is_on_appointment_grid(p_start_time, v_grid) then
    raise exception 'start time is not on the appointment grid' using errcode = '22023';
  end if;

  if not app.is_valid_treatment_length(p_end_time - p_start_time, v_grid) then
    raise exception 'appointment length is not on the appointment grid' using errcode = '22023';
  end if;

  v_starts_at := (p_date + p_start_time) at time zone v_time_zone;
  v_ends_at   := (p_date + p_end_time)   at time zone v_time_zone;

  select t.status into v_status
  from public.training_relationships t
  where t.id = p_training_relationship_id
    and t.organization_id = v_org;

  if not found then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;

  if v_status <> 'active' then
    raise exception 'training relationship is not active' using errcode = '22023';
  end if;

  -- Eine fremde und eine unbekannte Klammer erzeugen dieselbe Meldung.
  if p_training_basis_id is not null then
    select b.status into v_basis_status
    from public.training_bases b
    where b.id = p_training_basis_id
      and b.organization_id = v_org
      and b.training_relationship_id = p_training_relationship_id;

    if not found then
      raise exception 'training basis not found' using errcode = 'P0002';
    end if;

    if v_basis_status <> 'active' then
      raise exception 'training basis is concluded' using errcode = '22023';
    end if;
  end if;

  if not app.is_assignable_trainer(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;

  v_ausserhalb := not app.is_within_working_hours(
    p_staff_member_id, v_org, p_date, p_start_time, p_end_time
  );

  if v_ausserhalb and not coalesce(p_allow_outside_working_hours, false) then
    raise exception 'outside_working_hours' using errcode = '22023';
  end if;

  if p_appointment_type = 'practice' then
    if p_location_id is null then
      raise exception 'practice appointment requires a location' using errcode = '22023';
    end if;

    select l.id into v_location_id
    from public.locations l
    where l.id = p_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  else
    v_location_id := null;
  end if;

  -- ANN-177: Hausbesuch mit der Anschrift aus dem Trainingskontakt.
  if p_appointment_type = 'home_visit' then
    select x.street, x.house_number, x.postal_code, x.city
      into v_street, v_house, v_postal, v_city
    from app.training_visit_address(p_training_relationship_id) x;

    if v_street is null or v_house is null or v_postal is null or v_city is null then
      raise exception 'home visit requires a complete address' using errcode = '22023';
    end if;
  end if;

  begin
    insert into public.appointments (
      organization_id, training_relationship_id, training_basis_id,
      staff_member_id, location_id, appointment_type, kind, status,
      starts_at, ends_at,
      visit_street, visit_house_number, visit_postal_code, visit_city,
      created_by
    )
    values (
      v_org, p_training_relationship_id, p_training_basis_id,
      p_staff_member_id, v_location_id, p_appointment_type, 'training', 'confirmed',
      v_starts_at, v_ends_at,
      v_street, v_house, v_postal, v_city,
      v_actor
    )
    returning id into v_appointment_id;
  exception
    when exclusion_violation then
      raise exception 'appointment overlaps an existing one' using errcode = '23P01';
  end;


  return v_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.create_training_appointment(p_training_relationship_id uuid, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean, p_training_basis_id uuid, p_confirmed_past boolean) IS 'TRN-004: legt einen Trainingstermin im gemeinsamen Kalender an (ADR-022 Punkte 1, 3, 5, 9). owner, trainer, office (ANN-176); protokolliert appointment.created, abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.create_training_basis(p_relationship_id uuid, p_started_on date DEFAULT NULL::date, p_agreed_quantity integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_status text;
  v_id     uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(v_actor, 'training_basis.created', 'not allowed to manage training bases');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training bases' using errcode = '42501';
  end if;

  select t.status into v_status
  from public.training_relationships t
  where t.id = p_relationship_id
    and t.organization_id = v_org;

  if not found then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;

  if v_status <> 'active' then
    raise exception 'training relationship is not active' using errcode = '22023';
  end if;

  if p_agreed_quantity is not null and p_agreed_quantity not between 1 and 200 then
    raise exception 'agreed quantity must be between 1 and 200' using errcode = '22023';
  end if;

  insert into public.training_bases (
    organization_id, training_relationship_id, status, started_on, agreed_quantity, created_by
  )
  values (
    v_org, p_relationship_id, 'active',
    coalesce(p_started_on, app.training_today(v_org)), p_agreed_quantity, v_actor
  )
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_training_basis(p_relationship_id uuid, p_started_on date, p_agreed_quantity integer) IS 'TRN-005: legt eine Trainingsgrundlage (Vereinbarung) an einem laufenden Trainingsverhaeltnis an (ADR-022 Punkt 5). owner, trainer, office; protokolliert training_basis.created, abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.create_training_client(p_given_name text, p_family_name text, p_date_of_birth date DEFAULT NULL::date, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_contract_started_on date DEFAULT NULL::date, p_house_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_person uuid;
  v_id     uuid;
  v_start  date;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    -- Abgewiesen mit bestaetigtem denied-Eintrag und HTTP 403 (G6c).
    perform app.record_denied_write(v_actor, 'training_relationship.created', 'not allowed to manage training clients');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training clients' using errcode = '42501';
  end if;

  if app.leer_zu_null(p_given_name) is null or app.leer_zu_null(p_family_name) is null then
    raise exception 'name is required' using errcode = '22023';
  end if;

  -- Ohne Angabe beginnt der Vertrag heute.
  v_start := coalesce(p_contract_started_on, app.training_today(v_org));

  insert into public.persons (organization_id, given_name, family_name, created_by)
  values (v_org, btrim(p_given_name), btrim(p_family_name), v_actor)
  returning id into v_person;

  insert into public.training_relationships (
    organization_id, person_id, status, contract_started_on, created_by
  )
  values (v_org, v_person, 'active', v_start, v_actor)
  returning id into v_id;

  perform app.write_training_contact(
    v_id, v_org, v_actor, p_date_of_birth, p_email, p_phone, p_street, p_house_number, p_postal_code, p_city
  );


  return v_id;
end;
$$;

CREATE FUNCTION public.create_training_invoice_draft(p_training_relationship_id uuid, p_period_month date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_monat  date;
  v_id     uuid;
  v_anzahl integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  v_monat := date_trunc('month', p_period_month)::date;

  if v_monat is null then
    raise exception 'period month is required' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.training_relationships t
    where t.id = p_training_relationship_id and t.organization_id = v_org
  ) then
    raise exception 'training relationship not found' using errcode = '42501';
  end if;

  -- ANN-182: kein Empfaenger - die Rechnung geht an die Kund:in selbst.
  insert into public.invoices (
    organization_id, training_relationship_id, recipient_id, period_month, service_area,
    created_by
  )
  values (v_org, p_training_relationship_id, null, v_monat, 'training', v_actor)
  returning id into v_id;

  insert into public.invoice_items (organization_id, invoice_id, billable_service_id, sort_order)
  select v_org, v_id, z.id, z.nummer
  from (
    select b.id,
           row_number() over (order by b.performed_on, c.code, b.id)::smallint as nummer
    from public.billable_services b
    join public.service_catalog_items c on c.id = b.catalog_item_id
    where b.organization_id = v_org
      and b.training_relationship_id = p_training_relationship_id
      and b.status = 'billable'
      and b.service_area = 'training'
      and date_trunc('month', b.performed_on)::date = v_monat
      and not exists (
        select 1 from public.invoice_items it
        where it.billable_service_id = b.id and it.released_at is null
      )
  ) z;

  get diagnostics v_anzahl = row_count;

  if v_anzahl = 0 then
    raise exception 'no billable services for this training client and month'
      using errcode = '22023';
  end if;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_training_invoice_draft(p_training_relationship_id uuid, p_period_month date) IS 'Legt den Rechnungsentwurf einer Trainingskund:in fuer einen Kalendermonat an und nimmt alle noch nicht abgerechneten Trainingsleistungen auf (TRN-008, ANN-077). Je Kund:in und Monat hoechstens ein Entwurf; ohne abweichenden Empfaenger (ANN-182). Die Nummer kommt erst beim Ausstellen, aus dem Kreis des Trainings (ABR-010).';

CREATE FUNCTION public.create_training_offer(p_patient_id uuid, p_catalog_item_id uuid, p_starts_on date, p_handover_items jsonb, p_offers_contact boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor     uuid;
  v_org       uuid;
  v_heute     date;
  v_abschluss date;
  v_id        uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_update_patient() then
    raise exception 'not allowed to make training offers' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  -- Unter Sperre der Akte: Das eine offene Angebot wird gegen den Stand
  -- geprueft, auf den geschrieben wird.
  select p.care_concluded_on into v_abschluss
  from public.patients p
  where p.id = p_patient_id and p.organization_id = v_org
  for update;
  if not found then
    raise exception 'patient not found' using errcode = '42501';
  end if;

  v_heute := app.training_today(v_org);

  if p_starts_on is null or p_offers_contact is null then
    raise exception 'start date and contact choice required' using errcode = '22023';
  end if;
  -- ANN-284: ab heute, hoechstens 90 Tage voraus, nicht vor dem Abschluss.
  if p_starts_on < v_heute or p_starts_on > v_heute + 90 then
    raise exception 'training offer must start within the next 90 days' using errcode = '22023';
  end if;
  if v_abschluss is not null and p_starts_on < v_abschluss then
    raise exception 'training offer cannot start before care is concluded' using errcode = '22023';
  end if;

  if not app.training_offer_handover_valid(coalesce(p_handover_items, '[]'::jsonb)) then
    raise exception 'handover items invalid' using errcode = '22023';
  end if;

  -- Das Paket der Preisliste, die am Beginn gilt (ADR-009 Punkt 5).
  if not exists (
    select 1 from public.service_catalog_items c
    where c.id = p_catalog_item_id
      and c.organization_id = v_org
      and c.item_kind = 'training_package'
      and c.catalog_version_id = app.active_service_catalog_version(v_org, p_starts_on)
  ) then
    raise exception 'training package is not in the price list valid on %', p_starts_on
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.training_offers o
    where o.patient_id = p_patient_id
      and app.training_offer_practice_state(o, v_heute) = 'open'
  ) then
    raise exception 'an open training offer exists' using errcode = '23505';
  end if;

  insert into public.training_offers (
    organization_id, patient_id, catalog_item_id, starts_on, valid_until,
    handover_items, offers_contact, created_by
  )
  values (
    v_org, p_patient_id, p_catalog_item_id, p_starts_on, least(v_heute + 14, p_starts_on),
    coalesce(p_handover_items, '[]'::jsonb), p_offers_contact, v_actor
  )
  returning id into v_id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_training_offer(p_patient_id uuid, p_catalog_item_id uuid, p_starts_on date, p_handover_items jsonb, p_offers_contact boolean) IS 'KND-002: ein Trainingsangebot in der Akte festhalten (owner, therapist, team_lead, office; ANN-282) - Paket der am Beginn geltenden Preisliste, Beginn ab heute bis 90 Tage voraus und nicht vor dem Abschluss, bis zu fuenf Uebergabeangaben (ANN-283), 14 Tage gueltig (ANN-284), je Akte ein offenes.';

CREATE FUNCTION public.create_training_package(p_relationship_id uuid, p_catalog_item_id uuid, p_starts_on date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_grund   text;
  v_monate  smallint;
  v_ende    date;
  v_id      uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_training_packages() then
    raise exception 'not allowed to manage training packages' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  if p_starts_on is null then
    raise exception 'start date required' using errcode = '22023';
  end if;

  perform 1 from public.training_relationships t
  where t.id = p_relationship_id and t.organization_id = v_org
  for update;
  if not found then
    raise exception 'training relationship not found' using errcode = '42501';
  end if;

  v_grund := app.training_package_start_blocker(p_relationship_id, p_starts_on);
  if v_grund is not null then
    raise exception 'training package cannot start: %', v_grund using errcode = '22023';
  end if;

  -- Die Position muss ein Paket der Preisliste sein, die am Beginn gilt
  -- (ADR-009 Punkt 5): Ein spaeter gewaehltes Datum nimmt nicht still den
  -- Preis einer anderen Liste.
  select c.package_months into v_monate
  from public.service_catalog_items c
  where c.id = p_catalog_item_id
    and c.organization_id = v_org
    and c.item_kind = 'training_package'
    and c.catalog_version_id = app.active_service_catalog_version(v_org, p_starts_on);
  if not found then
    raise exception 'training package is not in the price list valid on %', p_starts_on
      using errcode = '22023';
  end if;

  v_ende := app.training_package_ends_on(p_starts_on, v_monate);

  insert into public.training_packages (
    organization_id, training_relationship_id, catalog_item_id, starts_on, ends_on, created_by
  )
  values (v_org, p_relationship_id, p_catalog_item_id, p_starts_on, v_ende, v_actor)
  returning id into v_id;

  insert into public.billable_services (
    organization_id, training_relationship_id, appointment_id, training_package_id,
    catalog_item_id, quantity, performed_on, created_by
  )
  values (v_org, p_relationship_id, null, v_id, p_catalog_item_id, 1, p_starts_on, v_actor);

  return v_id;
exception
  when exclusion_violation then
    raise exception 'a training package already covers this period' using errcode = '23P01';
end;
$$;

COMMENT ON FUNCTION public.create_training_package(p_relationship_id uuid, p_catalog_item_id uuid, p_starts_on date) IS 'ANG-006: Trainingspaket anlegen (owner, office) - mit seiner einen Leistung zum Beginn (ANN-276), zum Preis der am Beginn geltenden Preisliste, ohne Ueberschneidung mit einem anderen Paket, nicht waehrend einer laufenden Behandlung (ANN-278).';

CREATE FUNCTION public.create_treatment_basis(p_patient_id uuid, p_prescriber_id uuid, p_treatment_basis_kind text, p_issued_on date, p_appointment_count integer, p_items jsonb, p_frequency_note text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_diagnosis text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft. ANN-011: ohne office.
  if not app.can_write_treatment_bases() then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  -- Patient ausschliesslich in der eigenen Organisation suchen.
  if not exists (
    select 1 from public.patients pa
    where pa.id = p_patient_id and pa.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  perform app.assert_treatment_basis_input(v_org, p_prescriber_id, p_treatment_basis_kind, p_issued_on);
  perform app.assert_appointment_count(p_appointment_count);

  insert into public.treatment_bases (
    organization_id, patient_id, prescriber_id, treatment_basis_kind, issued_on,
    appointment_count, frequency_note, note, diagnosis, created_by, updated_by
  )
  values (
    v_org, p_patient_id, p_prescriber_id, p_treatment_basis_kind, p_issued_on,
    p_appointment_count,
    nullif(btrim(p_frequency_note), ''),
    nullif(btrim(p_note), ''),
    -- ADR-020 Punkt 4: Die Diagnose gehoert zur Verordnung. Beim Selbstzahler
    -- bleibt sie leer, auch wenn ein Aufrufer sie mitschickt.
    case when p_treatment_basis_kind = 'self_pay'
         then null else nullif(btrim(p_diagnosis), '') end,
    v_actor, v_actor
  )
  returning id into v_id;

  perform app.write_treatment_base_items(v_id, v_org, v_actor, p_items);


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_treatment_basis(p_patient_id uuid, p_prescriber_id uuid, p_treatment_basis_kind text, p_issued_on date, p_appointment_count integer, p_items jsonb, p_frequency_note text, p_note text, p_diagnosis text) IS 'Legt eine Behandlungsgrundlage samt Positionen atomar an und protokolliert treatment_basis.created (VER-003, ADR-010). Alle vier Praxisrollen seit PRX-010 (app.can_write_treatment_bases, ANN-011). Seit VER-EPIC-002 mit der Anzahl moeglicher Termine und ohne Therapieziel, Verordnerhinweis und Empfehlung - eine neue Grundlage hat sie nicht (ANN-064).';

CREATE FUNCTION public.create_treatment_note(p_appointment_id uuid, p_content text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_inhalt text;
  v_termin record;
  v_note   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');

  if v_inhalt = '' then
    raise exception 'documentation must not be empty' using errcode = '22023';
  end if;

  if length(v_inhalt) > 20000 then
    raise exception 'documentation is too long' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.status, a.kind
    into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  -- Ein Ereignis des Praxisbetriebs hat keine Patient:in - eine
  -- Behandlungsdokumentation daran haette kein Gegenueber (CAL-015b).
  if v_termin.kind = 'internal' then
    raise exception 'event cannot be documented' using errcode = '22023';
  end if;

  -- Eine Absage sagt aus, dass die Behandlung NICHT stattgefunden hat.
  -- Bestaetigte und abgeschlossene Termine sind dokumentierbar - der laufende
  -- Hausbesuch ist der Regelfall und noch nicht abgeschlossen.
  if v_termin.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be documented' using errcode = '22023';
  end if;

  -- Nicht angetroffen heisst: keine Behandlung, also auch kein Nachweis
  -- (CAL-008c). Wer sich vertan hat, oeffnet den Termin wieder.
  if v_termin.status = 'no_show' then
    raise exception 'no-show appointment cannot be documented' using errcode = '22023';
  end if;

  begin
    insert into public.treatment_notes (
      organization_id, appointment_id, status, content, created_by, updated_by
    )
    values (
      v_org, p_appointment_id, 'draft', v_inhalt, v_actor, v_actor
    )
    returning id into v_note;
  exception
    when unique_violation then
      raise exception 'treatment note already exists' using errcode = '23505';
  end;


  return v_note;
end;
$$;

COMMENT ON FUNCTION public.create_treatment_note(p_appointment_id uuid, p_content text) IS 'Legt die Behandlungsdokumentation eines Termins als Entwurf an und protokolliert treatment_note.created (DOK-001, ADR-010).';

CREATE FUNCTION public.create_treatment_note_addendum(p_parent_note_id uuid, p_content text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_inhalt   text;
  v_eltern   record;
  v_patient  uuid;
  v_nachtrag uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');

  if v_inhalt = '' then
    raise exception 'documentation must not be empty' using errcode = '22023';
  end if;

  if length(v_inhalt) > 20000 then
    raise exception 'documentation is too long' using errcode = '22023';
  end if;

  select t.id, t.appointment_id, t.status, t.addendum_to_note_id
    into v_eltern
  from public.treatment_notes t
  where t.id = p_parent_note_id
    and t.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment note not found' using errcode = 'P0002';
  end if;

  if v_eltern.addendum_to_note_id is not null then
    raise exception 'addendum cannot be extended' using errcode = '22023';
  end if;

  if v_eltern.status <> 'final' then
    raise exception 'treatment note is not final' using errcode = '22023';
  end if;

  insert into public.treatment_notes (
    organization_id, appointment_id, addendum_to_note_id, status, content, created_by, updated_by
  )
  values (
    v_org, v_eltern.appointment_id, p_parent_note_id, 'draft', v_inhalt, v_actor, v_actor
  )
  returning id into v_nachtrag;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = v_eltern.appointment_id;


  return v_nachtrag;
end;
$$;

COMMENT ON FUNCTION public.create_treatment_note_addendum(p_parent_note_id uuid, p_content text) IS 'Legt einen Nachtrag zu einem finalisierten Eintrag als eigenen Entwurf an und protokolliert treatment_note.addendum_created (DOK-002, ADR-016 Punkt 6).';

CREATE FUNCTION public.create_waitlist_entry(p_patient_id uuid, p_treatment_basis_id uuid, p_preferred_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_time_windows jsonb, p_earliest_on date, p_needed_by date, p_priority_reason text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.patients p
    where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  perform app.waitlist_check_input(
    v_org, p_patient_id, p_treatment_basis_id, p_preferred_staff_member_id,
    p_appointment_type, p_duration_minutes, p_time_windows, p_earliest_on,
    p_needed_by, p_priority_reason, p_note
  );

  begin
    insert into public.waitlist_entries (
      organization_id, patient_id, treatment_basis_id, preferred_staff_member_id,
      appointment_type, duration_minutes, time_windows, earliest_on, needed_by,
      priority_reason, note, created_by, updated_by
    ) values (
      v_org, p_patient_id, p_treatment_basis_id, p_preferred_staff_member_id,
      p_appointment_type, p_duration_minutes, coalesce(p_time_windows, '[]'::jsonb),
      p_earliest_on, p_needed_by, p_priority_reason, nullif(btrim(p_note), ''),
      v_actor, v_actor
    )
    returning id into v_id;
  exception
    when unique_violation then
      raise exception 'patient already on waitlist' using errcode = '23505';
  end;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.create_waitlist_entry(p_patient_id uuid, p_treatment_basis_id uuid, p_preferred_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_time_windows jsonb, p_earliest_on date, p_needed_by date, p_priority_reason text, p_note text) IS 'Setzt eine Patient:in mit Wunschfenstern auf die Warteliste (PRX-001). Terminverwaltung; ein offener Eintrag je Person und Grundlage; auditiert ohne Notiz.';

CREATE FUNCTION public.decide_leave_request(p_request_id uuid, p_approve boolean, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_antrag  record;
  v_text    text := nullif(btrim(coalesce(p_note, '')), '');
begin
  v_org := app.staff_request_org(app.can_decide_staff_requests(), 'not allowed to decide requests');
  if p_approve is null then
    raise exception 'decision is required' using errcode = '22023';
  end if;
  if v_text is not null and length(v_text) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  if not p_approve and v_text is null then
    raise exception 'rejection needs a reason' using errcode = '22023';
  end if;

  select r.* into v_antrag
  from public.staff_leave_requests r
  where r.id = p_request_id and r.organization_id = v_org and r.status = 'requested'
  for update;
  if not found then
    raise exception 'leave request not found' using errcode = 'P0002';
  end if;
  -- Wer selbst beantragt, entscheidet nicht ueber den eigenen Antrag (ANN-576).
  if v_antrag.staff_member_id = app.own_staff_member(v_org) or v_antrag.requested_by = auth.uid() then
    raise exception 'not allowed to decide own request' using errcode = '42501';
  end if;

  if not p_approve then
    update public.staff_leave_requests
       set status = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_note = v_text
     where id = v_antrag.id;
    return jsonb_build_object('status', 'rejected', 'appointments', 0, 'appointment_days', '[]'::jsonb);
  end if;

  if v_antrag.kind = 'leave' then
    -- Inzwischen genehmigter eigener Urlaub fuer dieselben Tage? Dann nicht.
    if exists (
      select 1 from public.staff_leave_requests r
      where r.organization_id = v_org and r.staff_member_id = v_antrag.staff_member_id
        and r.id <> v_antrag.id and r.kind = 'leave' and r.status = 'approved'
        and r.starts_on <= v_antrag.ends_on and r.ends_on >= v_antrag.starts_on
    ) then
      raise exception 'leave overlaps' using errcode = '23P01';
    end if;
    update public.staff_leave_requests
       set status = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = v_text
     where id = v_antrag.id;
    perform app.apply_leave(v_org, v_antrag.id);
    return jsonb_build_object(
      'status', 'approved',
      'appointments', app.appointments_in_leave(
        v_org, v_antrag.staff_member_id, v_antrag.starts_on, v_antrag.ends_on),
      'appointment_days', app.appointment_days_in_leave(
        v_org, v_antrag.staff_member_id, v_antrag.starts_on, v_antrag.ends_on)
    );
  end if;

  -- Ein Storno: der Urlaub ist aufgehoben, seine Abwesenheiten fallen - nur,
  -- solange er nicht begonnen hat (wie beim Beantragen des Stornos).
  if v_antrag.starts_on < (
    select (now() at time zone o.time_zone)::date from public.organizations o where o.id = v_org
  ) then
    raise exception 'leave already started' using errcode = '55000';
  end if;
  update public.staff_leave_requests
     set status = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = v_text
   where id = v_antrag.id;
  update public.staff_leave_requests
     set status = 'cancelled'
   where id = v_antrag.refers_to and status = 'approved';
  delete from public.staff_working_hour_exceptions e where e.leave_request_id = v_antrag.refers_to;
  return jsonb_build_object('status', 'approved', 'appointments', 0, 'appointment_days', '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.decide_leave_request(p_request_id uuid, p_approve boolean, p_note text) IS 'URL-001 (ANN-576, ANN-578): owner entscheidet einen offenen Antrag, nie den eigenen. Ablehnen nur mit Grund. Genehmigter Urlaub sperrt seine Tage in den Arbeitszeiten; ein genehmigter Storno hebt Urlaub und Sperre auf. Antwort: Zustand, Zahl der bestaetigten Termine im Zeitraum und je Tag (zum Umplanen).';

CREATE FUNCTION public.decide_reimbursement(p_reimbursement_id uuid, p_approve boolean, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_antrag public.staff_reimbursements%rowtype;
  v_grund  text := nullif(btrim(coalesce(p_note, '')), '');
begin
  v_org := app.staff_request_org(app.can_decide_staff_requests(), 'not allowed to decide reimbursements');
  select r.* into v_antrag
  from public.staff_reimbursements r
  where r.id = p_reimbursement_id and r.organization_id = v_org
  for update;
  if v_antrag.id is null then
    raise exception 'reimbursement not found' using errcode = 'P0002';
  end if;
  if v_antrag.staff_member_id is not distinct from app.own_staff_member(v_org) then
    raise exception 'not allowed to decide own request' using errcode = '42501';
  end if;
  if v_antrag.status <> 'requested' then
    raise exception 'reimbursement is not open' using errcode = '55000';
  end if;
  if p_approve is null then
    raise exception 'decision missing' using errcode = '22023';
  end if;
  if not p_approve and v_grund is null then
    raise exception 'rejection needs a reason' using errcode = '22023';
  end if;
  if length(v_grund) > 500 then
    raise exception 'reason is too long' using errcode = '22023';
  end if;

  update public.staff_reimbursements
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = auth.uid(),
         decided_at = now(),
         decision_note = case when p_approve then null else v_grund end
   where id = v_antrag.id;
  return jsonb_build_object('status', case when p_approve then 'approved' else 'rejected' end);
end;
$$;

COMMENT ON FUNCTION public.decide_reimbursement(p_reimbursement_id uuid, p_approve boolean, p_note text) IS 'ERS-001 (ANN-598): owner genehmigt oder lehnt mit Grund ab - nie den eigenen Antrag, nur beantragte. Genehmigt heißt nicht ausgezahlt.';

CREATE FUNCTION public.decide_working_time_request(p_request_id uuid, p_approve boolean, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_antrag record;
  v_text   text := nullif(btrim(coalesce(p_note, '')), '');
  v_heute  date;
begin
  v_org := app.staff_request_org(app.can_decide_staff_requests(), 'not allowed to decide requests');
  if p_approve is null then
    raise exception 'decision is required' using errcode = '22023';
  end if;
  if v_text is not null and length(v_text) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  if not p_approve and v_text is null then
    raise exception 'rejection needs a reason' using errcode = '22023';
  end if;

  select r.* into v_antrag
  from public.staff_working_time_requests r
  where r.id = p_request_id and r.organization_id = v_org and r.status = 'requested'
  for update;
  if not found then
    raise exception 'working time request not found' using errcode = 'P0002';
  end if;
  -- Wer selbst beantragt, entscheidet nicht ueber den eigenen Antrag.
  if v_antrag.staff_member_id = app.own_staff_member(v_org) or v_antrag.requested_by = auth.uid() then
    raise exception 'not allowed to decide own request' using errcode = '42501';
  end if;

  if not p_approve then
    update public.staff_working_time_requests
       set status = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_note = v_text
     where id = v_antrag.id;
    return jsonb_build_object('status', 'rejected', 'appointment_days', '[]'::jsonb);
  end if;

  -- Rueckwirkend wird nichts: Ist das Datum erreicht, bleibt nur Ablehnen.
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;
  if v_antrag.on_date <= v_heute then
    raise exception 'working time change date passed' using errcode = '55000';
  end if;
  -- Gegen das, was jetzt gilt - der Plan kann sich seit dem Antrag geaendert
  -- haben (Pflege, ein anderer Antrag, Urlaub).
  perform 1 from public.staff_members sm where sm.id = v_antrag.staff_member_id for no key update;
  -- Der Antrag trägt den ganzen Tag bzw. die ganze Woche. Hat sich das
  -- Bisherige seither geändert - Pflege, ein anderer Antrag, eine
  -- Abweichung -, schriebe Genehmigen das still zurück (Zweitreview B1).
  if (app.working_time_baseline(v_org, v_antrag.staff_member_id, v_antrag.kind, v_antrag.on_date)
        -> 'blocks') is distinct from v_antrag.previous_blocks then
    raise exception 'working plan changed since request' using errcode = '55000';
  end if;
  perform app.assert_working_time_change(
    v_org, v_antrag.staff_member_id, v_antrag.kind, v_antrag.on_date, v_antrag.blocks, '55000');

  update public.staff_working_time_requests
     set status = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = v_text
   where id = v_antrag.id;
  perform app.apply_working_time_change(v_org, v_antrag.id);
  return jsonb_build_object(
    'status', 'approved',
    'appointment_days', app.appointments_outside_working_time(
      v_org, v_antrag.staff_member_id, v_antrag.kind, v_antrag.on_date, v_antrag.blocks)
  );
end;
$$;

COMMENT ON FUNCTION public.decide_working_time_request(p_request_id uuid, p_approve boolean, p_note text) IS 'AZ-001 (ANN-590): owner entscheidet einen offenen Antrag, nie den eigenen. Ablehnen nur mit Grund; genehmigt nur vor dem Datum und nur, wenn die Aenderung gegen den jetzigen Plan weiter zulaessig ist. Antwort: Zustand und die Tage mit Terminen ausserhalb der neuen Zeiten (zum Umplanen).';

CREATE FUNCTION public.delete_aftercare_month(p_billable_service_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    raise exception 'not allowed to manage aftercare subscriptions' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  -- Zweitreview: erst die eigene Praxis, dann der Zustand - eine fremde
  -- Kennung erfaehrt nichts ueber ihren Datensatz.
  perform 1 from public.billable_services b
  where b.id = p_billable_service_id
    and b.organization_id = v_org
    and b.aftercare_subscription_id is not null
  for update;
  if not found then
    raise exception 'aftercare month not found' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.invoice_items it
    where it.billable_service_id = p_billable_service_id and it.released_at is null
  ) then
    raise exception 'aftercare month is on an invoice' using errcode = '23514';
  end if;

  -- BEF-128: Freigegebene Rechnungszeilen fallen mit ihrer Leistung, wie in
  -- delete_billable_services und delete_training_package. Eine nicht
  -- freigegebene Zeile hat der Block darueber abgewiesen.
  delete from public.invoice_items it
   where it.billable_service_id = p_billable_service_id
     and it.released_at is not null;

  delete from public.billable_services b
  where b.id = p_billable_service_id and b.status = 'billable';
  if not found then
    raise exception 'aftercare month is on an invoice' using errcode = '23514';
  end if;
end;
$$;

COMMENT ON FUNCTION public.delete_aftercare_month(p_billable_service_id uuid) IS 'ANG-002: die Erfassung eines Abo-Monats zuruecknehmen (owner, office), solange er auf keiner Rechnung steht. Seit BEF-128 auch nach einem Storno: Die freigegebene Rechnungszeile faellt mit der Leistung.';

CREATE FUNCTION public.delete_aftercare_subscription(p_subscription_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    raise exception 'not allowed to manage aftercare subscriptions' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  -- Zweitreview: erst die eigene Praxis, dann der Zustand.
  perform 1 from public.aftercare_subscriptions s
  where s.id = p_subscription_id and s.organization_id = v_org
  for update;
  if not found then
    raise exception 'aftercare subscription not found' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.billable_services b
    where b.aftercare_subscription_id = p_subscription_id
  ) then
    raise exception 'aftercare subscription has recorded months' using errcode = '23514';
  end if;

  -- Zweitreview: Eine Kuendigung ist ein Nachweis (ANN-272); ein gekuendigtes
  -- Abo ist keine Fehlanlage mehr.
  if exists (
    select 1 from public.aftercare_subscriptions s
    where s.id = p_subscription_id and s.cancelled_at is not null
  ) then
    raise exception 'aftercare subscription is cancelled' using errcode = '23514';
  end if;

  delete from public.aftercare_subscriptions s where s.id = p_subscription_id;
end;
$$;

COMMENT ON FUNCTION public.delete_aftercare_subscription(p_subscription_id uuid) IS 'ANG-001: ein irrtuemlich angelegtes Nachsorge-Abo entfernen, solange keine Leistung daraus entstanden ist (owner, office).';

CREATE FUNCTION public.delete_billable_services(p_appointment_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_anzahl integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_record_billable_services() then
    raise exception 'not allowed to record billable services' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  if not exists (
    select 1 from public.appointments a
    where a.id = p_appointment_id and a.organization_id = v_org
  ) then
    raise exception 'appointment not found' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.billable_services
    where appointment_id = p_appointment_id and status = 'invoiced'
  ) then
    raise exception 'billable service is already invoiced' using errcode = '23514';
  end if;

  -- Neu mit ABR-003: Ein Entwurf haelt seine Leistungen fest. Erst den
  -- Entwurf verwerfen, dann die Erfassung zuruecknehmen.
  if exists (
    select 1
    from public.invoice_items it
    join public.billable_services b on b.id = it.billable_service_id
    where b.appointment_id = p_appointment_id
      and it.released_at is null
  ) then
    raise exception 'billable service is part of an invoice draft' using errcode = '23514';
  end if;

  update public.treatment_base_items p
     set used_quantity = greatest(p.used_quantity - b.menge, 0)
  from (
    select treatment_base_item_id, sum(quantity)::smallint as menge
    from public.billable_services
    where appointment_id = p_appointment_id and treatment_base_item_id is not null
    group by treatment_base_item_id
  ) b
  where p.id = b.treatment_base_item_id;

  -- Freigegebene Rechnungszeilen fallen mit ihrer Leistung: Sie zeigen mit
  -- RESTRICT auf sie, und was die stornierte Rechnung ausgewiesen hat, steht
  -- in ihrem Snapshot und nicht in dieser Zuordnung (ADR-009 Punkt 10). Eine
  -- Zeile, die nicht freigegeben ist, kommt hier nie vorbei - der Block
  -- darueber weist den Vorgang dann schon ab.
  delete from public.invoice_items it
   using public.billable_services b
   where it.billable_service_id = b.id
     and b.appointment_id = p_appointment_id
     and it.released_at is not null;

  -- ABR-031: Das Terminhonorar faellt mit der Erfassung, die es ausgeloest hat.
  delete from public.appointment_session_fees where appointment_id = p_appointment_id;

  delete from public.billable_services where appointment_id = p_appointment_id;
  get diagnostics v_anzahl = row_count;


  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.delete_billable_services(p_appointment_id uuid) IS 'Entfernt die noch nicht abgerechneten Leistungen eines Termins und nimmt die genutzte Menge der Grundlage zurueck (ABR-002). Seit ABR-003 auch dann abgewiesen, wenn die Leistung auf einem Rechnungsentwurf steht. Nach einem Storno ist die Leistung wieder frei und laesst sich entfernen (ABR-003c).';

CREATE FUNCTION public.delete_exercise(p_exercise_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.exercise_library_writer();

  if not exists (
    select 1 from public.exercises e where e.id = p_exercise_id and e.organization_id = v_org
  ) then
    raise exception 'exercise not found' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.exercise_variants v where v.exercise_id = p_exercise_id) then
    raise exception 'exercise has variants' using errcode = '23503';
  end if;

  delete from public.exercises where id = p_exercise_id and organization_id = v_org;
exception
  -- Entsteht zwischen Pruefung und Loeschen eine Variante, haelt der
  -- Fremdschluessel das Loeschen auf - mit derselben Meldung (ANN-296).
  when foreign_key_violation then
    raise exception 'exercise has variants' using errcode = '23503';
end;
$$;

COMMENT ON FUNCTION public.delete_exercise(p_exercise_id uuid) IS 'UEB-001 (ANN-296): loescht eine Uebung ohne Varianten. Nur nach app.can_manage_exercise_library().';

CREATE FUNCTION public.delete_exercise_plan_item(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan public.exercise_plans%rowtype;
  v_item public.exercise_plan_items%rowtype;
begin
  select i.* into v_item from public.exercise_plan_items i where i.id = p_item_id;
  v_plan := app.exercise_plan_for_write(coalesce(v_item.plan_id, extensions.gen_random_uuid()));
  if v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;

  delete from public.exercise_plan_items where id = v_item.id;
  perform app.exercise_plan_renumber(v_plan.id);
  update public.exercise_plans set updated_at = now(), updated_by = auth.uid() where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.delete_exercise_plan_item(p_item_id uuid) IS 'UEB-004: entfernt eine Position aus dem Entwurf; die uebrigen ruecken auf. Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.delete_exercise_plan_template(p_template_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_von uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_exercise_plan_templates() then
    raise exception 'not allowed to write exercise plan templates' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write exercise plan templates' using errcode = '42501';
  end if;

  select t.created_by into v_von
    from public.exercise_plan_templates t
   where t.id = p_template_id and t.organization_id = v_org
   for update;
  if not found then
    raise exception 'template not found' using errcode = 'P0002';
  end if;
  if not app.can_edit_exercise_plan_template(v_von) then
    raise exception 'not allowed to change this template' using errcode = '42501';
  end if;

  delete from public.exercise_plan_templates
   where id = p_template_id and organization_id = v_org;
end;
$$;

COMMENT ON FUNCTION public.delete_exercise_plan_template(p_template_id uuid) IS 'UEB-014 (ANN-560): loescht eine Vorlage der Praxis samt ihren Uebungen. Nur, wer sie angelegt hat, und owner. Plaene aus der Vorlage bleiben: Sie verweisen nicht auf sie.';

CREATE FUNCTION public.delete_exercise_variant(p_variant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.exercise_library_writer();

  delete from public.exercise_variants where id = p_variant_id and organization_id = v_org;
  if not found then
    raise exception 'exercise variant not found' using errcode = 'P0002';
  end if;
exception
  when foreign_key_violation then
    raise exception 'exercise variant is in use' using errcode = '23503';
end;
$$;

COMMENT ON FUNCTION public.delete_exercise_variant(p_variant_id uuid) IS 'UEB-001 (ANN-296): loescht eine Variante, auf die nichts zeigt. Nur nach app.can_manage_exercise_library().';

CREATE FUNCTION public.delete_fleet_depot(p_depot_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.fleet_org(app.can_manage_fleet(), 'not allowed to manage the fleet');
  if not exists (
    select 1 from public.fleet_depots d where d.id = p_depot_id and d.organization_id = v_org
  ) then
    raise exception 'depot not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.fleet_bikes b
    where b.organization_id = v_org
      and (b.home_depot_id = p_depot_id or b.current_depot_id = p_depot_id)
  ) then
    raise exception 'depot still has bikes' using errcode = '55000';
  end if;
  delete from public.fleet_depots d where d.id = p_depot_id and d.organization_id = v_org;
end;
$$;

COMMENT ON FUNCTION public.delete_fleet_depot(p_depot_id uuid) IS 'FLT-001: Depot entfernen, solange kein Rad dort steht oder hingehoert. Nur owner (BEF-066).';

CREATE FUNCTION public.delete_fleet_photo(p_photo_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_foto public.fleet_photos%rowtype;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  select f.* into v_foto
  from public.fleet_photos f
  where f.id = p_photo_id and f.organization_id = v_org and f.status = 'ready'
  for update;
  if v_foto.id is null then
    raise exception 'photo not found' using errcode = 'P0002';
  end if;
  if not app.can_delete_fleet_photo(v_foto) then
    raise exception 'not allowed to delete this photo' using errcode = '42501';
  end if;
  -- Der Trigger schreibt den Loeschauftrag; ordered_by ist dort auth.uid()
  -- (LOG-EPIC-001). Das Loeschjournal haelt die Loeschung fest, damit sie
  -- nach einer Wiederherstellung erneut greift (ADR-008 Punkt 8, ADR-017
  -- Punkt 26) - etwa wenn doch eine Person im Bild war.
  delete from public.fleet_photos where id = v_foto.id;
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  values (v_foto.organization_id, extensions.gen_random_uuid(), 'fleet_photos', v_foto.id,
          'radflotte_ereignis', now());
end;
$$;

COMMENT ON FUNCTION public.delete_fleet_photo(p_photo_id uuid) IS 'FLT-002: Foto am Rad loeschen - die aufnehmende Person am Tag der Aufnahme, owner jederzeit. Nachweis am Loeschauftrag (ordered_by); das Loeschjournal haelt die Loeschung ueber eine Wiederherstellung (ADR-008 Punkt 8).';

CREATE FUNCTION public.delete_invoice_draft(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_status text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.status into v_status
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  if v_status <> 'draft' then
    raise exception 'an issued invoice cannot be deleted' using errcode = '23514';
  end if;

  delete from public.invoices where id = p_invoice_id;

end;
$$;

COMMENT ON FUNCTION public.delete_invoice_draft(p_invoice_id uuid) IS 'Verwirft einen Rechnungsentwurf und gibt seine Leistungen wieder frei (ABR-003). Eine ausgestellte Rechnung wird nicht geloescht, sondern storniert (ADR-009 Punkt 9, ABR-EPIC-002b).';

CREATE FUNCTION public.delete_invoice_recipient(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_kind    text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoice recipients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select r.patient_id, r.recipient_kind
    into v_patient, v_kind
  from public.invoice_recipients r
  where r.id = p_id and r.organization_id = v_org;

  if not found then
    raise exception 'invoice recipient not found' using errcode = '42501';
  end if;

  delete from public.invoice_recipients where id = p_id;

end;
$$;

COMMENT ON FUNCTION public.delete_invoice_recipient(p_id uuid) IS 'Entfernt einen Rechnungsempfaenger (ABR-003a). Haengt eine Rechnung daran, weist der Fremdschluessel die Loeschung ab - der Empfaenger ist Teil ihres Belegs (ADR-009 Punkt 10).';

CREATE FUNCTION public.delete_message_attachment(p_attachment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang  public.platform_message_attachments%rowtype;
  v_vorgang public.platform_messages%rowtype;
begin
  if auth.uid() is null or not app.may_read_platform_messages('any') then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;
  select x.* into v_anhang
  from public.platform_message_attachments x
  where x.id = p_attachment_id and x.organization_id = app.current_organization_id()
    and x.status = 'ready' and x.locked_at is null;
  if v_anhang.id is null then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;
  select m.* into v_vorgang from public.platform_messages m where m.id = v_anhang.message_id;
  if not app.can_read_platform_message(v_vorgang.relationship_kind, v_vorgang.topic) then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;
  if not app.can_answer_platform_message(v_vorgang.relationship_kind, v_vorgang.topic) then
    raise exception 'not allowed to delete this attachment' using errcode = '42501';
  end if;

  perform app.remove_message_attachments(
    v_anhang.organization_id, 'attachment', v_anhang.id, extensions.gen_random_uuid());
end;
$$;

COMMENT ON FUNCTION public.delete_message_attachment(p_attachment_id uuid) IS 'KOM-005 (ADR-017 Punkt 67): die Praxis loescht einen Anhang, etwa wenn er Dritte zeigt - wer auf den Vorgang antworten darf. Nachweis am Loeschauftrag (ordered_by) und im Loeschjournal.';

CREATE FUNCTION public.delete_patient_fee_agreement(p_agreement_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage fee agreements' using errcode = '42501';
  end if;

  begin
    delete from public.patient_fee_agreements f
     where f.id = p_agreement_id
       and f.organization_id = app.current_organization_id();
  exception
    -- Eine angewandte Vereinbarung ist der Nachweis eines festgeschriebenen
    -- Honorars (ABR-031) und bleibt.
    when foreign_key_violation then
      raise exception 'fee agreement is already applied' using errcode = '23514';
  end;

  if not found then
    raise exception 'fee agreement not found' using errcode = '42501';
  end if;
end;
$$;

COMMENT ON FUNCTION public.delete_patient_fee_agreement(p_agreement_id uuid) IS 'Entfernt eine Honorarvereinbarung, die noch an keinem Termin angewandt wurde (ABR-030). Nur owner.';

CREATE FUNCTION public.delete_patient_file(p_file_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_datei record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = app.current_organization_id()
  for update;

  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  -- Loeschen folgt dem Schreibrecht am Bezugsdatensatz (Punkt 13) - und setzt
  -- voraus, dass die Person die Datei ueberhaupt sehen darf. Ohne die zweite
  -- Pruefung koennte die Verwaltung eine klinische Datei loeschen, die sie
  -- nicht kennt.
  if not app.can_write_patient_file(v_datei.document_type, v_datei.treatment_basis_id)
     or not app.can_see_patient_file_type(v_datei.document_type) then
    raise exception 'not allowed to delete this file' using errcode = '42501';
  end if;

  -- Punkt 36: Ein gesperrtes Foto ist fuer niemanden erreichbar. Es faellt mit
  -- der Frist - unter Legal Hold erst, wenn er endet -, nicht von Hand.
  if v_datei.document_type = 'patientenfoto'
     and v_datei.status = 'ready'
     and not app.patient_photo_accessible(
       v_datei.patient_id, v_datei.created_at, v_datei.photo_locked_at
     ) then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  -- Punkt 48: Ein Dokumentationsfoto ist ab dem Tag nach der Aufnahme Teil
  -- der Dokumentation. Am Aufnahmetag (in der Zeitzone der Praxis) loescht
  -- die aufnehmende Person oder owner eine Fehlaufnahme; danach nur noch der
  -- Loeschlauf mit der Akte.
  if v_datei.document_type = 'dokumentationsfoto'
     and not app.documentation_photo_deletable(v_datei.organization_id, v_datei.uploaded_by, v_datei.created_at) then
    raise exception 'a documentation photo can only be deleted on the day it was taken'
      using errcode = '42501';
  end if;

  -- Der Trigger an patient_files schreibt den Loeschauftrag fuer das Objekt;
  -- das Loeschjournal haelt die Loeschung ueber eine Wiederherstellung
  -- (BEF-170, ADR-008 Punkt 8).
  delete from public.patient_files where id = p_file_id;
  perform app.journal_patient_file_deletion(v_datei.organization_id, v_datei.id, v_datei.document_type);
end;
$$;

COMMENT ON FUNCTION public.delete_patient_file(p_file_id uuid) IS 'Loescht eine Datei der Akte. Die Zeile faellt sofort, das Objekt ueber den Loeschauftrag mit Quittung (ADR-017 Punkt 25); das Loeschjournal haelt die Loeschung ueber eine Wiederherstellung (BEF-170, ADR-008 Punkt 8).';

CREATE FUNCTION public.delete_platform_diary_entry(p_access_id uuid, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  -- Löschen braucht weder Einwilligung noch eingeschaltetes Tagebuch: wer
  -- widerrufen oder abgeschaltet hat, räumt trotzdem auf.
  v_profil := app.platform_diary_for_writing(p_access_id, null, false);
  delete from public.nutrition_diary_entries e
  where e.id = p_id and e.profile_id = v_profil.id;
  if not found then
    raise exception 'entry not found' using errcode = 'P0002';
  end if;
  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
end;
$$;

COMMENT ON FUNCTION public.delete_platform_diary_entry(p_access_id uuid, p_id uuid) IS 'ERN-007: einen eigenen Eintrag löschen - auch nach einem Widerruf oder abgeschaltetem Tagebuch; nicht in der Lesefrist (dann löscht die Frist der Datenklasse mit dem Profil), nie die Begleitung.';

CREATE FUNCTION public.delete_platform_food(p_access_id uuid, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  -- Löschen braucht keine Einwilligung: wer widerrufen hat, räumt trotzdem auf.
  v_profil := app.platform_nutrition_for_writing(p_access_id, false);
  delete from public.custom_foods p
  where p.id = p_id and p.profile_id = v_profil.id and p.owner_kind = 'person';
  if not found then
    raise exception 'food not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.delete_platform_food(p_access_id uuid, p_id uuid) IS 'ERN-005: ein eigenes Lebensmittel löschen - die Person oder ihre rechtliche Vertretung, an der laufenden Beratung dieses Zugangs, auch nach einem Widerruf; nie die Begleitung. In der Lesefrist nicht (wie Gewicht und Zielgewicht, platform_access_writable): Dann löscht die Frist der Datenklasse mit dem Profil.';

CREATE FUNCTION public.delete_platform_message_attachment(p_access_id uuid, p_attachment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.platform_message_attachments%rowtype;
begin
  -- "Jederzeit": auch nach der Lesefrist, solange der eigene Zugang aktiv ist
  -- (wie der Widerruf, ANN-261).
  if not (app.platform_access_allows(p_access_id, 'attach')
          or app.platform_own_access_after_reading(p_access_id)) then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;
  select x.* into v_anhang
  from public.platform_message_attachments x
  join public.platform_messages m on m.id = x.message_id
  join public.platform_accesses a on a.id = p_access_id
  where x.id = p_attachment_id
    and m.organization_id = a.organization_id
    and m.relationship_kind = a.relationship_kind
    and m.relationship_id = a.relationship_id
    and x.status = 'ready'
    and x.locked_at is null;
  if v_anhang.id is null then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;

  perform app.remove_message_attachments(
    v_anhang.organization_id, 'attachment', v_anhang.id, extensions.gen_random_uuid());
  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'message')
  );
end;
$$;

COMMENT ON FUNCTION public.delete_platform_message_attachment(p_access_id uuid, p_attachment_id uuid) IS 'KOM-005 (ADR-017 Punkt 67): die Person oder ihre rechtliche Vertretung loescht einen Anhang - jederzeit, die Person auch nach der Lesefrist. Loeschjournal und Loeschauftrag (ordered_by); unter Legal Hold gesperrt (ANN-335).';

CREATE FUNCTION public.delete_service_catalog_version(p_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_published timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select v.published_at into v_published
  from public.service_catalog_versions v
  where v.id = p_version_id and v.organization_id = v_org;

  if not found then
    raise exception 'service catalog version not found' using errcode = '42501';
  end if;

  if v_published is not null then
    raise exception 'published service catalog version is immutable' using errcode = '23514';
  end if;


  delete from public.service_catalog_versions where id = p_version_id;
end;
$$;

COMMENT ON FUNCTION public.delete_service_catalog_version(p_version_id uuid) IS 'Verwirft einen Katalogentwurf samt Positionen (ABR-001). Eine veroeffentlichte Version laesst sich nicht loeschen.';

CREATE FUNCTION public.delete_task(p_task_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_tasks() then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;

  delete from public.tasks k
  where k.id = p_task_id and k.organization_id = v_org
  returning k.patient_id into v_patient;

  if not found then
    raise exception 'task not found' using errcode = 'P0002';
  end if;

end;
$$;

COMMENT ON FUNCTION public.delete_task(p_task_id uuid) IS 'Loescht eine Aufgabe der eigenen Praxis (PRX-012) und protokolliert task.deleted.';

CREATE FUNCTION public.delete_team_message(p_message uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_m       public.team_messages%rowtype;
  v_kind    text;
  v_antwort boolean;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  -- for update: Eine gleichzeitig eingehende Antwort wartet, bis hier
  -- entschieden ist - sonst nähme das Löschen sie über cascade mit.
  select * into v_m from public.team_messages
   where id = p_message and organization_id = v_org and removed_at is null
     and (created_at <= now() or author_staff_member_id = v_staff)
   for update;
  if v_m.id is null or not app.team_channel_readable(v_m.channel_id, v_org, v_staff) then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;

  if v_m.author_staff_member_id = v_staff then
    v_kind := 'author';
  elsif app.has_any_role('owner')
        and exists (select 1 from public.team_channels c
                    where c.id = v_m.channel_id and c.kind in ('channel', 'fleet')) then
    v_kind := 'owner';
  else
    raise exception 'not allowed to delete this team message' using errcode = '42501';
  end if;

  v_antwort := exists (select 1 from public.team_messages r where r.parent_id = v_m.id);
  -- Ins Löschjournal, damit ein Restore den Text nicht zurückbringt (ADR-008
  -- Punkt 8), tageweise gebündelt (Zweitreview TEAM-001, N4).
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at, deleted_at)
  values (v_org, md5('team_manual:' || v_org::text || ':' || current_date::text)::uuid,
          case when v_kind = 'author' and not v_antwort then 'team_messages'
               else 'team_message_contents' end,
          v_m.id, 'teamchat', date_trunc('day', now()), date_trunc('day', now()));
  if v_kind = 'author' and not v_antwort then
    delete from public.team_messages where id = v_m.id;
  else
    -- Der Anker trägt keinen Namen mehr (ADR-008 Punkt 12, Zweitreview N2);
    -- Erwähnungen, Reaktionen, Angeheftetes und „Für später“ fallen über den
    -- Auslöser `team_messages_inhalt_entfernt`.
    update public.team_messages
       set body = null, edited_at = null, author_staff_member_id = null,
           removed_at = now(), removed_kind = v_kind,
           removed_by_staff_member_id = case when v_kind = 'owner' then v_staff end
     where id = v_m.id;
  end if;
end;
$$;

CREATE FUNCTION public.delete_text_snippet(p_snippet_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_use_text_snippets() then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  select s.id, s.staff_member_id, s.title
    into v_alt
  from public.treatment_text_snippets s
  where s.id = p_snippet_id
    and s.organization_id = v_org
    and (
      s.staff_member_id is null
      or s.staff_member_id in (
        select sm.id from public.staff_members sm where sm.person_id = app.current_person_id()
      )
    );

  if not found then
    raise exception 'text snippet not found' using errcode = 'P0002';
  end if;

  if v_alt.staff_member_id is null and not app.can_manage_shared_text_snippets() then
    raise exception 'not allowed to manage shared text snippets' using errcode = '42501';
  end if;

  delete from public.treatment_text_snippets where id = p_snippet_id;

end;
$$;

COMMENT ON FUNCTION public.delete_text_snippet(p_snippet_id uuid) IS 'Loescht einen Textbaustein (UX-008). Praxisweite Bausteine nur fuer owner.';

CREATE FUNCTION public.delete_training_package(p_package_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_training_packages() then
    raise exception 'not allowed to manage training packages' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  -- Erst die eigene Praxis, dann der Zustand: Eine fremde Kennung erfaehrt
  -- nichts ueber ihren Datensatz.
  perform 1 from public.training_packages k
  where k.id = p_package_id and k.organization_id = v_org
  for update;
  if not found then
    raise exception 'training package not found' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.billable_services b
    join public.invoice_items it on it.billable_service_id = b.id
    where b.training_package_id = p_package_id and it.released_at is null
  ) then
    raise exception 'training package is on an invoice' using errcode = '23514';
  end if;

  -- Zweitreview: Freigegebene Rechnungszeilen fallen mit ihrer Leistung,
  -- wie in delete_billable_services. Sie zeigen mit RESTRICT auf sie, und was
  -- die stornierte Rechnung ausgewiesen hat, steht in ihrem Snapshot (ADR-009
  -- Punkt 10). Eine nicht freigegebene Zeile hat der Block darueber abgewiesen.
  delete from public.invoice_items it
   using public.billable_services b
   where it.billable_service_id = b.id
     and b.training_package_id = p_package_id
     and it.released_at is not null;

  delete from public.billable_services b where b.training_package_id = p_package_id;
  delete from public.training_packages k where k.id = p_package_id;
end;
$$;

COMMENT ON FUNCTION public.delete_training_package(p_package_id uuid) IS 'ANG-006: ein irrtuemlich angelegtes Trainingspaket mit seiner Leistung entfernen (owner, office), solange es auf keiner Rechnung steht.';

CREATE FUNCTION public.delete_treatment_basis(p_treatment_basis_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor        uuid;
  v_org          uuid;
  v_patient_id   uuid;
  v_freigegeben  timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_bases() then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  -- Zweitreview A (Nachtrag): erst die Termine und Positionen der Grundlage,
  -- dann die Grundlage - dieselbe Reihenfolge wie jeder Schreiber (Termin,
  -- Position, Grundlage). Mit der Grundlage zuerst warteten das Loeschen
  -- (Termine auf null, Positionen fort) und eine laufende Terminaenderung
  -- (Sperrpruefung an der Grundlage) aufeinander (40P01). Die Termine nur
  -- `for no key update`, wie das Loeschen sie ohnehin aendert: Ein neuer
  -- Eintrag zu einem Termin bleibt so moeglich.
  perform 1
  from public.appointments a
  where a.treatment_basis_id = p_treatment_basis_id
    and a.organization_id = v_org
  order by a.id
  for no key update;

  perform 1
  from public.treatment_base_items i
  where i.treatment_basis_id = p_treatment_basis_id
    and i.organization_id = v_org
  order by i.id
  for update;

  -- B7 (ANN-515): In der Abrechnung erst zurueckholen. Die Zeile wird vor
  -- der Pruefung gesperrt: Eine gleichzeitige Freigabe wartet dann, statt
  -- dass das Loeschen die eben freigegebene Grundlage mitnimmt.
  select b.billing_released_at into v_freigegeben
  from public.treatment_bases b
  where b.id = p_treatment_basis_id
    and b.organization_id = v_org
  for update;

  if v_freigegeben is not null then
    raise exception 'treatment basis is in billing' using errcode = '55000';
  end if;

  -- PRX-010 (Zweitreview): Mit der Grundlage fielen ihre klinischen Texte;
  -- das bleibt den therapeutischen Rollen vorbehalten.
  if not app.can_clear_treatment_basis_clinical_texts()
     and app.treatment_basis_has_clinical_texts(p_treatment_basis_id, v_org) then
    raise exception 'clinical texts on this treatment basis can only be cleared by treating roles'
      using errcode = '42501';
  end if;

  -- BEF-124 (ANN-562): Hing je ein Termin an der Grundlage - auch einer, der
  -- inzwischen woanders haengt -, gehoert sie zur Akte und bleibt (§ 630f BGB).
  -- Erst nach der Rechtepruefung oben: Eine Rolle ohne Recht erfaehrt 42501,
  -- nicht den Zustand der Grundlage.
  -- Nach der Zeilensperre geprueft: Ein Termin, der gleichzeitig an die
  -- Grundlage gehaengt wird, wartet auf sie (Fremdschluessel) und sieht danach
  -- entweder die Grundlage oder ihr Fehlen.
  if exists (
    select 1 from public.treatment_bases b
    where b.id = p_treatment_basis_id and b.had_appointments
  ) or exists (
    select 1 from public.appointments a
    where a.organization_id = v_org
      and (a.treatment_basis_id = p_treatment_basis_id
           or a.previous_treatment_basis_id = p_treatment_basis_id)
  ) then
    raise exception 'treatment basis has appointments' using errcode = '23503';
  end if;

  if exists (
    select 1 from public.therapy_reports r
    where r.treatment_basis_id = p_treatment_basis_id and r.organization_id = v_org
  ) then
    raise exception 'treatment basis has therapy reports' using errcode = '23503';
  end if;

  delete from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org
  returning p.patient_id into v_patient_id;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

end;
$$;

COMMENT ON FUNCTION public.delete_treatment_basis(p_treatment_basis_id uuid) IS 'Loescht eine falsch erfasste Behandlungsgrundlage endgueltig und protokolliert treatment_basis.deleted (VER-003, ADR-008 Punkt 10, Art. 16 DSGVO). Nur owner, therapist und team_lead.';

CREATE FUNCTION public.discard_exercise_plan(p_plan_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan public.exercise_plans%rowtype;
begin
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'draft' then
    raise exception 'only a draft exercise plan can be discarded' using errcode = '22023';
  end if;
  delete from public.exercise_plans where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.discard_exercise_plan(p_plan_id uuid) IS 'UEB-004: verwirft einen Entwurf samt Positionen. Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.discard_fleet_photo_upload(p_photo_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_foto public.fleet_photos%rowtype;
begin
  perform app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  v_foto := app.own_pending_fleet_photo(p_photo_id);
  -- Der Trigger schreibt den Loeschauftrag, falls doch schon ein Objekt liegt.
  delete from public.fleet_photos where id = v_foto.id;
end;
$$;

COMMENT ON FUNCTION public.discard_fleet_photo_upload(p_photo_id uuid) IS 'FLT-002 (ADR-017 Punkt 7): verwirft die eigene, nicht bestaetigte Zeile nach einem abgebrochenen Upload.';

CREATE FUNCTION public.discard_message_attachment_upload(p_access_id uuid, p_attachment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.platform_message_attachments%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'attach') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  v_anhang := app.own_pending_attachment(p_access_id, p_attachment_id);
  -- Der Trigger schreibt den Loeschauftrag, falls doch schon ein Objekt liegt.
  delete from public.platform_message_attachments where id = v_anhang.id;
end;
$$;

COMMENT ON FUNCTION public.discard_message_attachment_upload(p_access_id uuid, p_attachment_id uuid) IS 'KOM-005 (ADR-017 Punkt 7): verwirft die eigene, nicht bestaetigte Zeile nach einem abgebrochenen Upload.';

CREATE FUNCTION public.discard_patient_file_upload(p_file_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_datei record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = app.current_organization_id()
    and f.status = 'pending'
    -- Zweitreview Befund 3: Eine bestaetigte Datei, die auf die Pruefung
    -- wartet, ist kein abgebrochener Upload; verwerfen darf sie nur das
    -- Ergebnis der Pruefung oder der Lauf nach 24 Stunden.
    and f.confirmation_requested_at is null;

  if not found then
    raise exception 'pending upload not accessible' using errcode = '42501';
  end if;

  if not app.can_write_patient_file(v_datei.document_type, v_datei.treatment_basis_id) then
    raise exception 'not allowed to discard this upload' using errcode = '42501';
  end if;

  -- Der Trigger schreibt den Loeschauftrag, falls doch schon ein Objekt liegt.
  delete from public.patient_files where id = p_file_id;
end;
$$;

COMMENT ON FUNCTION public.discard_patient_file_upload(p_file_id uuid) IS 'Verwirft eine nicht bestaetigte Dateizeile nach einem abgebrochenen Upload (ADR-017 Punkt 7).';

CREATE FUNCTION public.discard_platform_questionnaire_response(p_access_id uuid, p_response_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'questionnaire') then
    return false;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  delete from public.patient_questionnaire_responses r
  where r.id = p_response_id
    and r.patient_id = v_zugang.relationship_id
    and r.organization_id = v_zugang.organization_id
    and r.source = 'platform'
    and r.status = 'entwurf';
  if not found then
    return false;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'questionnaire_discard')
  );
  return true;
end;
$$;

COMMENT ON FUNCTION public.discard_platform_questionnaire_response(p_access_id uuid, p_response_id uuid) IS 'POR-012: Die Person verwirft ihren eigenen Plattform-Entwurf des Befundbogens. Abgeschlossenes bleibt.';

CREATE FUNCTION public.discard_questionnaire_response(p_response_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_questionnaire_response() then
    raise exception 'not allowed to record questionnaires' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record questionnaires' using errcode = '42501';
  end if;

  select r.status, r.patient_id into v_alt
  from public.patient_questionnaire_responses r
  where r.id = p_response_id and r.organization_id = v_org
  for update;
  if not found then
    raise exception 'questionnaire response not found' using errcode = 'P0002';
  end if;
  if v_alt.status <> 'entwurf' then
    raise exception 'questionnaire response is completed' using errcode = '23514';
  end if;

  delete from public.patient_questionnaire_responses where id = p_response_id;

end;
$$;

COMMENT ON FUNCTION public.discard_questionnaire_response(p_response_id uuid) IS 'Verwirft einen Entwurf - eine abgeschlossene Erhebung nie (FRB-002b, ANN-103). Protokolliert als questionnaire_response.discarded.';

CREATE FUNCTION public.discard_reimbursement_receipt(p_receipt_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_id  uuid;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  -- Der Trigger schreibt den Löschauftrag, falls schon ein Objekt liegt; das
  -- Journal hält die Löschung über eine Wiederherstellung (ADR-008 Punkt 8).
  delete from public.staff_reimbursement_receipts b
   where b.id = p_receipt_id and b.organization_id = v_org and b.created_by = auth.uid()
     and b.reimbursement_id is null
  returning b.id into v_id;
  if v_id is null then
    raise exception 'receipt not found' using errcode = 'P0002';
  end if;
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  values (v_org, extensions.gen_random_uuid(), 'staff_reimbursement_receipts', v_id,
          'erstattung', now());
end;
$$;

COMMENT ON FUNCTION public.discard_reimbursement_receipt(p_receipt_id uuid) IS 'ERS-001 (ADR-017 Punkt 7): verwirft einen eigenen Beleg, der noch keinem Antrag zugeordnet ist - mit Löschauftrag für das Objekt und Eintrag im Löschjournal (ADR-008 Punkt 8).';

CREATE FUNCTION public.discard_stale_fleet_photo_uploads() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  delete from public.fleet_photos
   where status = 'pending'
     and created_at < now() - interval '24 hours';
  get diagnostics v_anzahl = row_count;
  -- Abgelaufene, nicht verbrauchte Lesefreigaben: Sie hielten sonst fest, wer
  -- wann welches Foto oeffnen wollte (PROJECT_PRINCIPLES.md 20). Gezaehlt
  -- werden weiter nur die verworfenen Uploads.
  delete from public.fleet_photo_access_grants where expires_at <= now();
  return v_anzahl;
end;
$$;

CREATE FUNCTION public.discard_stale_message_attachment_uploads() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  delete from public.platform_message_attachments
   where status = 'pending'
     and created_at < now() - interval '24 hours';
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

CREATE FUNCTION public.discard_stale_patient_file_uploads() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  delete from public.patient_files
   where status = 'pending'
     and created_at < now() - interval '24 hours';

  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.discard_stale_patient_file_uploads() IS 'Verwirft nicht bestaetigte Dateizeilen aelter als 24 Stunden samt Objekt (ADR-017 Punkt 7). Laeuft zeitgesteuert, ohne Aufrufer und ohne Rollenpruefung.';

CREATE FUNCTION public.discard_stale_reimbursement_receipts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  -- Mit Journal: Nach einer Wiederherstellung fallen sie erneut (ADR-008
  -- Punkt 8), statt bis zum nächsten Lauf wieder zuordenbar zu sein.
  with geloescht as (
    delete from public.staff_reimbursement_receipts
     where reimbursement_id is null
       and created_at < now() - interval '24 hours'
    returning id, organization_id
  )
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  select g.organization_id, extensions.gen_random_uuid(), 'staff_reimbursement_receipts', g.id,
         'erstattung', now()
  from geloescht g;
  get diagnostics v_anzahl = row_count;
  -- Abgelaufene, nicht verbrauchte Lesefreigaben hielten sonst fest, wer
  -- wann welchen Beleg öffnen wollte (PROJECT_PRINCIPLES.md 20).
  delete from public.staff_reimbursement_receipt_access_grants where expires_at <= now();
  return v_anzahl;
end;
$$;

CREATE FUNCTION public.discard_stale_team_attachments() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  delete from public.team_message_attachments
   where message_id is null
     and created_at < now() - interval '24 hours';
  get diagnostics v_anzahl = row_count;
  -- Abgelaufene, nicht verbrauchte Lesefreigaben hielten sonst fest, wer
  -- wann welchen Anhang öffnen wollte (PROJECT_PRINCIPLES.md §20).
  delete from public.team_attachment_access_grants where expires_at <= now();
  return v_anzahl;
end;
$$;

CREATE FUNCTION public.discard_team_attachment(p_attachment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_id    uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  -- Der Trigger schreibt den Löschauftrag, falls schon ein Objekt liegt; das
  -- Journal hält das Verwerfen über eine Wiederherstellung (ADR-008 Punkt 8):
  -- Ein jüngerer Anhang wäre danach sonst wieder bindbar (ANN-652).
  delete from public.team_message_attachments a
   where a.id = p_attachment_id and a.organization_id = v_org and a.created_by = auth.uid()
     and a.staff_member_id = v_staff and a.message_id is null
  returning a.id into v_id;
  if v_id is null then
    raise exception 'team attachment not found' using errcode = 'P0002';
  end if;
  -- Tageweise gebündelt wie jedes Löschen im Teamchat (Zweitreview TEAM-001
  -- N4, TEAM-003 Runde 2): sonst stünde jedes Verwerfen sekundengenau im
  -- Nachweis der Praxisleitung.
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at, deleted_at)
  values (v_org, md5('team_manual:' || v_org::text || ':' || current_date::text)::uuid,
          'team_message_attachments', v_id, 'teamchat', date_trunc('day', now()),
          date_trunc('day', now()));
end;
$$;

COMMENT ON FUNCTION public.discard_team_attachment(p_attachment_id uuid) IS 'TEAM-003 (ADR-017 Punkte 7 und 79): verwirft einen eigenen, noch nicht gesendeten Anhang - mit Löschauftrag für das Objekt und Eintrag im Löschjournal (ADR-008 Punkt 8, ANN-652).';

CREATE FUNCTION public.discard_therapy_report(p_report_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_status  text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;

  select r.patient_id, r.status into v_patient, v_status
  from public.therapy_reports r
  where r.id = p_report_id and r.organization_id = v_org
  for update;
  if not found then
    raise exception 'therapy report not found' using errcode = 'P0002';
  end if;
  if v_status <> 'entwurf' then
    raise exception 'therapy report is completed and cannot be changed' using errcode = '55000';
  end if;

  delete from public.therapy_reports r where r.id = p_report_id;

end;
$$;

COMMENT ON FUNCTION public.discard_therapy_report(p_report_id uuid) IS 'Verwirft den Entwurf eines Therapieberichts (DOK-005a). therapist, team_lead; ein abgeschlossener Bericht bleibt; protokolliert als therapy_report.discarded.';

CREATE FUNCTION public.edit_team_message(p_message uuid, p_body text, p_mentions uuid[] DEFAULT '{}'::uuid[], p_mention_all boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_staff    uuid;
  v_text     text;
  v_m        public.team_messages%rowtype;
  v_root     uuid;
  v_seit     timestamptz;
  v_erwaehnt uuid[];
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  select m.* into v_m
  from public.team_messages m
  where m.id = p_message and m.organization_id = v_org
    and m.author_staff_member_id = v_staff and m.removed_at is null
    and app.team_channel_readable(m.channel_id, v_org, v_staff)
    and not exists (select 1 from public.team_channels c
                    where c.id = m.channel_id and c.archived_at is not null)
  for update;
  if v_m.id is null then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  v_text := app.team_message_body(
    p_body,
    exists (select 1 from public.team_message_attachments a where a.message_id = v_m.id)
  );
  update public.team_messages m
     set body = v_text,
         edited_at = case when m.created_at <= now() then now() end
   where m.id = v_m.id
  returning m.* into v_m;
  v_erwaehnt := coalesce(p_mentions, '{}'::uuid[]);
  if coalesce(p_mention_all, false) then
    v_erwaehnt := v_erwaehnt || array(select l.staff_member_id
                                      from public.list_team_channel_members(v_m.channel_id) l
                                      where l.active);
  end if;
  perform app.set_team_mentions(p_message, v_erwaehnt);
  v_root := coalesce(v_m.parent_id, v_m.id);
  v_seit := case when v_m.parent_id is null then v_m.created_at
                 else (select max(x.created_at) from public.team_messages x
                       where (x.id = v_root or x.parent_id = v_root)
                         and x.created_at < v_m.created_at) end;
  perform app.team_follow_thread(v_root, mm.staff_member_id, v_seit)
  from public.team_message_mentions mm where mm.message_id = p_message;
end;
$$;

CREATE FUNCTION public.electricity_suggestions() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_laufend date;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  -- Ohne Mitarbeiterdatensatz gibt es nichts vorzuschlagen.
  if v_staff is null then
    return '[]'::jsonb;
  end if;
  select date_trunc('month', now() at time zone o.time_zone)::date into v_laufend
  from public.organizations o where o.id = v_org;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'month', v.angebot ->> 'month',
             'working_minutes', (v.angebot ->> 'working_minutes')::integer,
             'amount_cents', (v.angebot ->> 'amount_cents')::integer
           ) order by v.monat desc)
    from (
      select m.monat, app.electricity_offer(v_org, v_staff, m.monat) as angebot
      from (
        select (v_laufend - make_interval(months => n))::date as monat
        from generate_series(1, 12) as n
      ) m
      where not exists (
        select 1 from public.staff_reimbursements r
        where r.staff_member_id = v_staff and r.kind = 'electricity'
          and r.period_month = m.monat and r.status in ('requested', 'approved', 'paid')
      )
    ) v
    where (v.angebot ->> 'amount_cents')::integer >= 1
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.electricity_suggestions() IS 'ORG-008: für den Eingang die abgeschlossenen Monate (höchstens zwölf), für die die angemeldete Person noch keinen Ladestrom beantragt hat und geplante Arbeitsstunden hatte - mit fertig gerechnetem Betrag. Nur für sich, keine Summe über alle (PROJECT_PRINCIPLES.md 20).';

CREATE FUNCTION public.electricity_tour_points(p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = 'P0002';
  end if;
  perform app.assert_electricity_month(v_org, p_month);
  return app.electricity_tour_days(v_org, v_staff, p_month);
end;
$$;

COMMENT ON FUNCTION public.electricity_tour_points(p_month date) IS 'BEF-181 (ADR-019 Fassung 6): für die Edge Function electricity-distance die Wegpunkte der eigenen geplanten Touren eines abgeschlossenen Monats, je Tag eine Liste von Koordinaten ohne Datum. Speichert nichts.';

CREATE FUNCTION public.end_checkin_schedule(p_kind text, p_relationship_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
begin
  if v_actor is null
     or not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    raise exception 'not allowed to end checkin schedule' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.checkin_relationship(p_kind, p_relationship_id, v_org);
  if v_rel.area is null then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;
  if not app.can_write_exercise_plans(v_rel.area) then
    raise exception 'not allowed to end checkin schedule' using errcode = '42501';
  end if;

  delete from public.checkin_schedules s
  where s.relationship_kind = p_kind and s.relationship_id = p_relationship_id;
end;
$$;

COMMENT ON FUNCTION public.end_checkin_schedule(p_kind text, p_relationship_id uuid) IS 'TRK-002: beendet den Check-in eines Verhaeltnisses; beantwortete Check-ins bleiben (ANN-350). Dieselben Rollen wie das Einstellen. Auch nach dem Ende des Verhaeltnisses moeglich.';

CREATE FUNCTION public.end_exercise_plan(p_plan_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan public.exercise_plans%rowtype;
begin
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'assigned' then
    raise exception 'only an assigned exercise plan can be ended' using errcode = '22023';
  end if;

  update public.exercise_plans
     set status = 'ended',
         ended_at = now(),
         ended_by = auth.uid(),
         updated_at = now(),
         updated_by = auth.uid()
   where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.end_exercise_plan(p_plan_id uuid) IS 'UEB-007: beendet einen zugewiesenen Plan. Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.end_habit(p_habit_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_habit public.habits%rowtype;
begin
  -- Erst die Rolle, dann die Eingabe (ADR-023 Punkt 21).
  if v_actor is null
     or not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    raise exception 'not allowed to end habits' using errcode = '42501';
  end if;
  select * into v_habit
  from public.habits h
  where h.id = p_habit_id and h.organization_id = app.current_organization_id()
  for update;
  if v_habit.id is null or v_habit.ended_at is not null then
    raise exception 'habit not found' using errcode = 'P0002';
  end if;
  if not app.can_write_exercise_plans(
       case v_habit.relationship_kind when 'treatment' then 'therapy' else 'training' end) then
    raise exception 'not allowed to end habits' using errcode = '42501';
  end if;
  update public.habits set ended_at = now(), ended_by = v_actor where id = p_habit_id;
end;
$$;

COMMENT ON FUNCTION public.end_habit(p_habit_id uuid) IS 'ALT-003 (ANN-370): beendet eine laufende Gewohnheit; die vermerkten Tage bleiben. Wer: app.can_write_exercise_plans des Bereichs - auch nach dem Ende des Verhaeltnisses und ohne Einwilligung, damit nichts gegen den Willen weiterlaeuft. Steht am Datensatz (ended_by).';

CREATE FUNCTION public.end_nutrition_profile(p_profile_id uuid, p_ended_on date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  -- Beenden geht auch ohne Einwilligung - damit nichts gegen den Willen
  -- weiterläuft.
  v_profil := app.nutrition_profile_for_writing(p_profile_id, false);
  if p_ended_on is null or p_ended_on > app.training_today(v_profil.organization_id) then
    raise exception 'end date not allowed' using errcode = '22023';
  end if;
  if p_ended_on < v_profil.started_on then
    raise exception 'end before start' using errcode = '22023';
  end if;
  update public.nutrition_profiles
     set ended_on = p_ended_on,
         ended_by = auth.uid(),
         updated_at = clock_timestamp(),
         updated_by = auth.uid()
   where id = v_profil.id;
end;
$$;

COMMENT ON FUNCTION public.end_nutrition_profile(p_profile_id uuid, p_ended_on date) IS 'ERN-001 (ADR-027 Punkt 2): beendet die Beratung - das Ende ist der Fristanker (Punkt 6). Danach ist das Profil unveränderlich und die Plattform zeigt es nicht mehr. Auch ohne Einwilligung. Allein app.can_counsel_nutrition.';

CREATE FUNCTION public.end_platform_companion(p_access_id uuid, p_companion_access_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eigen      public.platform_accesses%rowtype;
  v_begleitung public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'manage_companions') then
    return false;
  end if;
  select * into v_eigen from public.platform_accesses a where a.id = p_access_id;

  select * into v_begleitung
  from public.platform_accesses a
  where a.id = p_companion_access_id
    and a.organization_id = v_eigen.organization_id
    and a.relationship_kind = v_eigen.relationship_kind
    and a.relationship_id = v_eigen.relationship_id
    and a.access_kind = 'companion'
    and a.status <> 'revoked'
  for update;
  -- Eine rechtliche Vertretung beendet nur die Praxis (Punkt 14); eine
  -- fremde oder schon beendete Begleitung gibt es hier nicht.
  if v_begleitung.id is null then
    return false;
  end if;

  update public.platform_accesses
     set status = 'revoked', revoked_at = now(), revoked_by = auth.uid(),
         revoked_reason = 'consent_withdrawn', locked_at = null, locked_by = null
   where id = v_begleitung.id;

  update public.platform_access_invitations
     set status = 'revoked', revoked_at = now()
   where platform_access_id = v_begleitung.id and status = 'pending';

  perform app.log_platform_access_event(
    v_eigen.organization_id, auth.uid(),
    case when v_eigen.access_kind = 'self' then 'platform' else 'representative' end,
    'platform_access.revoked', v_begleitung.id,
    jsonb_build_object('surface', 'platform', 'reason', 'consent_withdrawn',
                       'platform_access_id', v_eigen.id, 'access_kind', v_eigen.access_kind,
                       'previous_status', v_begleitung.status)
  );
  return true;
end;
$$;

COMMENT ON FUNCTION public.end_platform_companion(p_access_id uuid, p_companion_access_id uuid) IS 'POR-007: Die Person (oder ihre rechtliche Vertretung) beendet eine Begleitung unter "Ich" - der Widerruf der Einwilligung (ADR-023 Punkte 13, 14). Grund consent_withdrawn, protokolliert als platform_access.revoked. Eine rechtliche Vertretung beendet nur die Praxis.';

CREATE FUNCTION public.end_training_relationship(p_relationship_id uuid, p_ended_on date DEFAULT NULL::date) RETURNS date
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_heute  date;
  v_tag    date;
  v_start  date;
  v_bisher date;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(v_actor, 'training_relationship.ended', 'not allowed to manage training clients');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training clients' using errcode = '42501';
  end if;

  v_heute := app.training_today(v_org);
  v_tag := coalesce(p_ended_on, v_heute);
  if v_tag > v_heute then
    raise exception 'contract end is in the future' using errcode = '22023';
  end if;

  select t.contract_started_on, t.contract_ended_on into v_start, v_bisher
  from public.training_relationships t
  where t.id = p_relationship_id and t.organization_id = v_org
  for update;
  if not found then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;
  if v_bisher is not null then
    raise exception 'training relationship has already ended' using errcode = '22023';
  end if;
  if v_start is not null and v_tag < v_start then
    raise exception 'contract end is before the contract start' using errcode = '22023';
  end if;

  -- ANG-006 (ANN-277): Ein Paket ist nicht pausierbar und nicht kuendbar; der
  -- Vertrag endet fruehestens mit seinem letzten Tag.
  if exists (
    select 1 from public.training_packages k
    where k.training_relationship_id = p_relationship_id and k.ends_on > v_tag
  ) then
    raise exception 'a training package runs beyond the contract end' using errcode = '22023';
  end if;

  update public.training_relationships
     set contract_ended_on = v_tag, status = 'inactive'
   where id = p_relationship_id;


  return v_tag;
end;
$$;

COMMENT ON FUNCTION public.end_training_relationship(p_relationship_id uuid, p_ended_on date) IS 'TRN-001: setzt das Vertragsende (Anker der dreijaehrigen Frist, ADR-021 Punkt 4) und den Status inactive. owner, trainer, office; protokolliert training_relationship.ended.';

CREATE FUNCTION public.enqueue_appointment_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    record;
  v_termin record;
  v_anzahl integer := 0;
begin
  for v_org in
    select o.id, o.time_zone from public.organizations o
    where not exists (
      select 1 from public.notification_kind_switches k
      where k.organization_id = o.id and k.kind = 'appointment_reminder'
    )
  loop
    for v_termin in
      select a.id, a.starts_at, r.rel_kind, r.rel_id
      from public.appointments a
      cross join lateral app.notification_appointment_relationship(a) r
      where a.organization_id = v_org.id
        and a.status = 'confirmed'
        and a.kind in ('therapy', 'training')
        and (a.starts_at at time zone v_org.time_zone)::date in (
          select d from app.notification_reminder_days(now() at time zone v_org.time_zone) d
        )
    loop
      v_anzahl := v_anzahl + app.enqueue_notification(
        v_org.id, v_termin.rel_kind, v_termin.rel_id,
        'appointment_reminder', v_termin.id, v_termin.starts_at);
    end loop;
  end loop;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.enqueue_appointment_reminders() IS 'KOM-009 (ADR-024 Punkt 13, ANN-343): legt die Terminerinnerungen fuer den naechsten Tag an (Freitag: bis Montag), stuendlich ab 17 Uhr wiederholbar. Nur fuer den Zeitplan.';

CREATE FUNCTION public.enqueue_nutrition_diary_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  insert into public.notification_deliveries
    (organization_id, access_id, kind, channel, subject_id, subject_at, due_at)
  select r.organization_id, r.access_id, 'nutrition_diary_reminder', w.channel, r.id, z.am, z.am
  from public.nutrition_diary_reminders r
  join public.organizations o on o.id = r.organization_id
  join public.platform_notification_settings s on s.access_id = r.access_id
  cross join (values ('email'), ('push')) w(channel)
  cross join lateral (
    select ((now() at time zone o.time_zone)::date + r.remind_at) at time zone o.time_zone as am
  ) z
  where z.am <= now() and z.am > now() - interval '20 minutes'
    and not exists (
      select 1 from public.notification_kind_switches k
      where k.organization_id = r.organization_id and k.kind = 'nutrition_diary_reminder')
    and (
      (w.channel = 'email' and 'nutrition_diary_reminder' = any (s.email_kinds))
      or (w.channel = 'push' and 'nutrition_diary_reminder' = any (s.push_kinds)
          and exists (select 1 from public.platform_push_subscriptions p
                      where p.access_id = r.access_id))
    )
    -- Was in die Ruhezeit fiele, entfällt (ADR-024 Punkt 15): Eine
    -- Erinnerung an den heutigen Eintrag hat am nächsten Morgen keinen Sinn.
    and app.notification_due_at(
          z.am, o.time_zone,
          coalesce(s.quiet_from, app.notification_rule('quiet_from')::smallint),
          coalesce(s.quiet_until, app.notification_rule('quiet_until')::smallint)) = z.am
    and app.nutrition_diary_reminder_live(r.id, z.am)
  on conflict (access_id, kind, channel, subject_id, subject_at)
    where kind = 'nutrition_diary_reminder' do nothing;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.enqueue_nutrition_diary_reminders() IS 'ERN-009 (ADR-027 Punkt 12): legt die Erinnerungen an das Tagebuch an, die in den letzten 20 Minuten fällig wurden - je gewähltem Weg, nicht in der Ruhezeit, nur mit laufender Beratung, eingeschaltetem Tagebuch und Einwilligung. Alle 15 Minuten wiederholbar. Nur für den Zeitplan.';

CREATE FUNCTION public.exercise_plan_items_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_plan record;
begin
  select p.status, p.previous_plan_id
    into v_plan
  from public.exercise_plans p
  where p.id = case when tg_op = 'DELETE' then old.plan_id else new.plan_id end;

  if tg_op = 'DELETE' then
    -- Faellt der Plan (Entwurf verworfen, Verhaeltnis geloescht), ist er
    -- schon fort.
    if not found or v_plan.status = 'draft' then
      return old;
    end if;
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;

  if not found or v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;

  if tg_op = 'UPDATE' and (
       new.plan_id is distinct from old.plan_id
       or new.organization_id is distinct from old.organization_id
       or new.previous_item_id is distinct from old.previous_item_id) then
    raise exception 'exercise plan item cannot be moved' using errcode = '22023';
  end if;

  if new.previous_item_id is not null and not exists (
    select 1 from public.exercise_plan_items i
    where i.id = new.previous_item_id and i.plan_id = v_plan.previous_plan_id
  ) then
    raise exception 'previous item belongs to the previous version' using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION public.exercise_plan_items_guard() IS 'UEB-004: Positionen aendern sich nur im Entwurf (ANN-300); eine Position der vorigen Fassung stammt aus der vorigen Fassung desselben Plans (ANN-301).';

CREATE FUNCTION public.exercise_plans_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_neu jsonb;
  v_alt jsonb;
begin
  if tg_op = 'INSERT' then
    if new.service_area = 'therapy' and not exists (
      select 1 from public.patients p
      where p.id = new.patient_id and p.organization_id = new.organization_id
    ) then
      raise exception 'exercise plan requires a relationship of the same organization'
        using errcode = '23514';
    end if;
    if new.status <> 'draft' then
      raise exception 'exercise plan starts as a draft' using errcode = '23514';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status = 'draft' then
      return old;
    end if;
    -- Faellt das Verhaeltnis, faellt der Plan mit (on delete cascade): Dann
    -- ist der Elterndatensatz schon fort.
    if (old.patient_id is not null and not exists (
          select 1 from public.patients p where p.id = old.patient_id))
       or (old.training_relationship_id is not null and not exists (
          select 1 from public.training_relationships t where t.id = old.training_relationship_id))
       or (old.previous_plan_id is not null and not exists (
          select 1 from public.exercise_plans p where p.id = old.previous_plan_id)) then
      return old;
    end if;
    raise exception 'only a draft exercise plan can be discarded' using errcode = '22023';
  end if;

  v_neu := to_jsonb(new);
  v_alt := to_jsonb(old);

  if app.patient_merge_active() and new.patient_id is distinct from old.patient_id then
    if not app.only_patient_id_changed(v_neu, v_alt) then
      raise exception 'exercise plan cannot be changed while merging' using errcode = '22023';
    end if;
    return new;
  end if;

  if new.organization_id is distinct from old.organization_id
     or new.service_area is distinct from old.service_area
     or new.patient_id is distinct from old.patient_id
     or new.training_relationship_id is distinct from old.training_relationship_id
     or new.previous_plan_id is distinct from old.previous_plan_id
     or new.created_at is distinct from old.created_at
     or new.created_by is distinct from old.created_by then
    raise exception 'exercise plan cannot be moved' using errcode = '22023';
  end if;

  if old.status = 'draft' then
    if new.status not in ('draft', 'assigned') then
      raise exception 'a draft exercise plan is assigned or discarded' using errcode = '22023';
    end if;
    return new;
  end if;

  if old.status = 'assigned' then
    -- Erlaubt: Laufzeit verlaengern, beenden, abloesen. Der Inhalt bleibt.
    if (v_neu - array['runs_until', 'extended_at', 'extended_by', 'status', 'ended_at',
                      'ended_by', 'updated_at', 'updated_by'])
       is distinct from
       (v_alt - array['runs_until', 'extended_at', 'extended_by', 'status', 'ended_at',
                      'ended_by', 'updated_at', 'updated_by']) then
      raise exception 'assigned exercise plan cannot be changed' using errcode = '22023';
    end if;
    if new.status not in ('assigned', 'ended', 'superseded') then
      raise exception 'assigned exercise plan cannot be changed' using errcode = '22023';
    end if;
    if new.status <> 'assigned' and new.runs_until is distinct from old.runs_until then
      raise exception 'assigned exercise plan cannot be changed' using errcode = '22023';
    end if;
    return new;
  end if;

  raise exception 'ended exercise plan cannot be changed' using errcode = '22023';
end;
$$;

COMMENT ON FUNCTION public.exercise_plans_guard() IS 'UEB-004: Bereich, Verhaeltnis und Herkunft eines Plans stehen fest; ein zugewiesener Plan aendert nur Laufzeit und Ende (ANN-300, ANN-302), ein beendeter nichts; beim Zusammenfuehren nur patient_id (PRX-017). Geloescht wird nur ein Entwurf - ausser mit dem Verhaeltnis.';

CREATE FUNCTION public.export_patient_record(p_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_actor  uuid;
  v_daten  jsonb;
begin
  v_actor := auth.uid();
  v_org   := app.auskunft_organisation(p_patient_id);

  select jsonb_build_object(
    'persons', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pe.id,
        'given_name', pe.given_name,
        'family_name', pe.family_name,
        'created_at', pe.created_at
      ) order by pe.created_at)
      from public.persons pe
      join public.patients pa on pa.person_id = pe.id
      where pa.id = p_patient_id
    ), '[]'::jsonb),

    'patients', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pa.id,
        'status', pa.status,
        'care_started_on', pa.care_started_on,
        'care_concluded_on', pa.care_concluded_on,
        'care_concluded_at', pa.care_concluded_at,
        'created_at', pa.created_at
      ))
      from public.patients pa
      where pa.id = p_patient_id
    ), '[]'::jsonb),

    'patient_contact_details', coalesce((
      select jsonb_agg(jsonb_build_object(
        'date_of_birth', k.date_of_birth,
        'email', k.email,
        'phone', k.phone,
        'phone_mobile', k.phone_mobile,
        'phone_work', k.phone_work,
        'institution', k.institution,
        'street', k.street,
        'house_number', k.house_number,
        'postal_code', k.postal_code,
        'city', k.city,
        -- MAP-006a: die Koordinate ist ein Personendatum wie die Adresse (Art. 15 DSGVO).
        'lat', k.lat,
        'lon', k.lon,
        'geocode_precision', k.geocode_precision,
        'created_at', k.created_at
      ))
      from public.patient_contact_details k
      where k.patient_id = p_patient_id
    ), '[]'::jsonb),

    'patient_care_details', coalesce((
      select jsonb_agg(jsonb_build_object(
        'primary_therapist', (
          select btrim(tp.given_name || ' ' || tp.family_name)
          from public.staff_members sm
          join public.persons tp on tp.id = sm.person_id
          where sm.id = v.primary_therapist_staff_member_id
        ),
        'home_visit_access_note', v.home_visit_access_note,
        'special_note', v.special_note,
        'remark', v.remark,
        -- UX-003a: Behandlungsliege (ANN-116).
        'treatment_table_required', v.treatment_table_required,
        'take_along_items', v.take_along_items,
        'created_at', v.created_at
      ))
      from public.patient_care_details v
      where v.patient_id = p_patient_id
    ), '[]'::jsonb),

    'appointments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id,
        'kind', t.kind,
        'appointment_type', t.appointment_type,
        'status', t.status,
        'title', t.title,
        'starts_at', t.starts_at,
        'ends_at', t.ends_at,
        'staff_member', (
          select btrim(tp.given_name || ' ' || tp.family_name)
          from public.staff_members sm
          join public.persons tp on tp.id = sm.person_id
          where sm.id = t.staff_member_id
        ),
        'visit_street', t.visit_street,
        'visit_house_number', t.visit_house_number,
        'visit_postal_code', t.visit_postal_code,
        'visit_city', t.visit_city,
        'visit_lat', t.visit_lat,
        'visit_lon', t.visit_lon,
        'cancellation_reason', t.cancellation_reason,
        'cancellation_received_at', t.cancellation_received_at,
        'fee_basis', t.fee_basis,
        'fee_waived_at', t.fee_waived_at,
        'no_show_recorded_at', t.no_show_recorded_at,
        'completed_at', t.completed_at,
        'created_at', t.created_at
      ) order by t.starts_at)
      from public.appointments t
      where t.patient_id = p_patient_id
    ), '[]'::jsonb),

    'appointment_notifications', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', n.id,
        'appointment_id', n.appointment_id,
        'channel', n.channel,
        'notified_at', n.notified_at
      ) order by n.notified_at)
      from public.appointment_notifications n
      join public.appointments t on t.id = n.appointment_id
      where t.patient_id = p_patient_id
    ), '[]'::jsonb),

    'treatment_bases', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', g.id,
        'treatment_basis_kind', g.treatment_basis_kind,
        'issued_on', g.issued_on,
        'prescriber', (
          select btrim(coalesce(vo.title || ' ', '') || vo.given_name || ' ' || vo.family_name)
          from public.prescribers vo
          where vo.id = g.prescriber_id
        ),
        'diagnosis', g.diagnosis,
        'therapy_goal', g.therapy_goal,
        'frequency_note', g.frequency_note,
        'prescriber_note', g.prescriber_note,
        'follow_up_recommendation', g.follow_up_recommendation,
        'note', g.note,
        'appointment_count', g.appointment_count,
        'created_at', g.created_at
      ) order by g.issued_on, g.created_at)
      from public.treatment_bases g
      where g.patient_id = p_patient_id
    ), '[]'::jsonb),

    'treatment_base_items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id,
        'treatment_basis_id', i.treatment_basis_id,
        'sort_order', i.sort_order,
        'remedy', i.remedy,
        'prescribed_quantity', i.prescribed_quantity,
        'used_quantity', i.used_quantity
      ) order by i.sort_order)
      from public.treatment_base_items i
      join public.treatment_bases g on g.id = i.treatment_basis_id
      where g.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- BEF-124: fruehere Staende der Grundlagen gehoeren zur Auskunft wie die
    -- Versionen der Dokumentation (Art. 15 DSGVO).
    'treatment_basis_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'treatment_basis_id', gv.treatment_basis_id,
        'version_no', gv.version_no,
        'content', gv.content,
        'replaced_at', gv.replaced_at,
        'replaced_by', (
          select up.display_name from public.user_profiles up where up.id = gv.replaced_by
        )
      ) order by gv.replaced_at, gv.version_no)
      from public.treatment_basis_versions gv
      join public.treatment_bases g on g.id = gv.treatment_basis_id
      where g.patient_id = p_patient_id
    ), '[]'::jsonb),

    'treatment_notes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', d.id,
        'appointment_id', d.appointment_id,
        'status', d.status,
        'content', d.content,
        'visit_without_treatment', d.visit_without_treatment,
        'addendum_to_note_id', d.addendum_to_note_id,
        'finalisation_kind', d.finalisation_kind,
        'finalized_at', d.finalized_at,
        'author', (
          select up.display_name from public.user_profiles up where up.id = d.created_by
        ),
        'created_at', d.created_at,
        'updated_at', d.updated_at,
        -- OFF-002: Uhr des Geraets bei einem ohne Verbindung geschriebenen Entwurf.
        'reported_written_at', d.reported_written_at
      ) order by d.created_at)
      from public.treatment_notes d
      join public.appointments t on t.id = d.appointment_id
      where t.patient_id = p_patient_id
    ), '[]'::jsonb),

    'treatment_note_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', f.id,
        'note_id', f.note_id,
        'version_no', f.version_no,
        'content', f.content,
        'change_reason', f.change_reason,
        'recorded_at', f.recorded_at,
        'author', (
          select up.display_name from public.user_profiles up where up.id = f.author_id
        )
      ) order by f.recorded_at, f.version_no)
      from public.treatment_note_versions f
      join public.treatment_notes d on d.id = f.note_id
      join public.appointments t on t.id = d.appointment_id
      where t.patient_id = p_patient_id
    ), '[]'::jsonb),

    'patient_files', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', da.id,
        'document_type', da.document_type,
        'display_name', da.display_name,
        'mime_type', da.mime_type,
        'byte_size', da.byte_size,
        'checksum_sha256', da.checksum_sha256,
        'status', da.status,
        'treatment_basis_id', da.treatment_basis_id,
        'created_at', da.created_at,
        'confirmed_at', da.confirmed_at,
        'photo_locked_at', da.photo_locked_at
      ) order by da.created_at)
      from public.patient_files da
      where da.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- ABN-017 (BEF-107): Die Fotos gehoeren zur vollstaendigen Kopie, auch
    -- gesperrte, solange sie vorhanden sind. Die Datei selbst gibt owner je
    -- Foto heraus (hand_out_patient_photo, protokolliert); dieser Abschnitt
    -- ist die Liste dazu.
    'patient_photos', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', fo.id,
        'display_name', fo.display_name,
        'art', fo.document_type,
        'aufgenommen_am', fo.created_at,
        'gesperrt', not app.patient_photo_usable(fo.document_type, fo.patient_id, fo.created_at, fo.photo_locked_at),
        'datei_vorhanden', exists (
          select 1 from storage.objects o
          where o.bucket_id = app.patient_file_bucket_for(fo.document_type) and o.name = fo.object_key)
      ) order by fo.created_at)
      from public.patient_files fo
      where fo.patient_id = p_patient_id
        and app.is_patient_photo_type(fo.document_type)
        and fo.status = 'ready'
    ), '[]'::jsonb),

    -- ABN-017 (BEF-107): Datum und Zweck der Zugriffe aus dem Auditlog -
    -- ohne Namen und ohne Kennung der Beschaeftigten (Art. 15 Abs. 4 DSGVO);
    -- eine begruendete Ausnahme prueft owner im Einzelfall (ANN-092).
    'access_log', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zeitpunkt', al.occurred_at,
        'aktion', al.action,
        'gegenstand', al.subject_type,
        'ergebnis', al.outcome,
        'durch', case al.actor_kind
                   when 'user' then 'praxis'
                   when 'system' then 'system'
                   when 'platform' then 'person_selbst'
                   when 'representative' then 'vertretung'
                 end
      )
      -- BEF-189 (Zweitreview): Der Export einer Begleitung umfasst nur ihre
      -- eigene Wahl zu Benachrichtigungen, nicht die Daten der Person.
      || case when al.context ->> 'part' = 'notifications'
              then jsonb_build_object('umfang', 'nur_eigene_benachrichtigungen')
              else '{}'::jsonb end
      order by al.occurred_at)
      from public.audit_log al
      where al.organization_id = v_org
        -- LOG-EPIC-001: Zugriffe, keine Abweisungen. Die Aktionen sind seit
        -- ADR-010 Fassung 3 ohnehin nur noch, was die Daten nicht zeigen.
        and al.outcome = 'success'
        -- Auch die Zugriffe auf zusammengefuehrte Doppelanlagen gehoeren
        -- zu dieser Person (ABN-018, BEF-108).
        and ((al.subject_type = 'patient' and al.subject_id = any(array(
                select p_patient_id
                union all
                select mr2.source_patient_id from public.patient_merge_records mr2
                where mr2.target_patient_id = p_patient_id and mr2.organization_id = v_org)))
             or al.context ->> 'patient_id' = any(array(
                select p_patient_id::text
                union all
                select mr2.source_patient_id::text from public.patient_merge_records mr2
                where mr2.target_patient_id = p_patient_id and mr2.organization_id = v_org)))
    ), '[]'::jsonb),

    -- ABN-018 (BEF-108): Nachweise des Zusammenfuehrens an dieser Akte.
    'patient_merge_records', coalesce((
      select jsonb_agg(jsonb_build_object(
        'merged_at', mr.merged_at,
        'source_patient_id', mr.source_patient_id,
        'counts', mr.counts
      ) order by mr.merged_at)
      from public.patient_merge_records mr
      where mr.target_patient_id = p_patient_id
    ), '[]'::jsonb),

    'legal_holds', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id,
        'reason', s.reason,
        'placed_at', s.placed_at,
        'released_at', s.released_at
      ) order by s.placed_at)
      from public.legal_holds s
      where s.subject_type = 'patient' and s.subject_id = p_patient_id
    ), '[]'::jsonb),

    'billable_services', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', l.id,
        'appointment_id', l.appointment_id,
        'performed_on', l.performed_on,
        'quantity', l.quantity,
        'status', l.status,
        'service_area', l.service_area,
        'service', (
          select btrim(k.code || ' ' || k.label)
          from public.service_catalog_items k
          where k.id = l.catalog_item_id
        )
      ) order by l.performed_on)
      from public.billable_services l
      where l.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- ANG-001: das Nachsorge-Abo mit Beginn, Ende und Kuendigung (Art. 15).
    'aftercare_subscriptions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'starts_on', s.starts_on,
        'ends_on', s.ends_on,
        'created_at', s.created_at,
        'cancelled_on', s.cancelled_on,
        'cancelled_via', s.cancelled_via,
        'cancelled_access_kind', s.cancelled_access_kind,
        'cancelled_representative_name', s.cancelled_representative_name
      ) order by s.starts_on)
      from public.aftercare_subscriptions s
      where s.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- KND-002: die Trainingsangebote aus der Akte mit Uebergabeangaben (Art. 15).
    'training_offers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'label', c.label,
        'starts_on', o.starts_on,
        'valid_until', o.valid_until,
        'handover_items', o.handover_items,
        'offers_contact', o.offers_contact,
        'created_at', o.created_at,
        'withdrawn_at', o.withdrawn_at
      ) order by o.created_at)
      from public.training_offers o
      join public.service_catalog_items c on c.id = o.catalog_item_id
      where o.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- UEB-005: die Uebungsplaene der Behandlung mit Positionen (Art. 15).
    'exercise_plans', coalesce((
      select jsonb_agg(jsonb_build_object(
        'title', x.title,
        'status', x.status,
        'sessions_per_week', x.sessions_per_week,
        'created_at', x.created_at,
        'assigned_at', x.assigned_at,
        'runs_from', x.runs_from,
        'runs_until', x.runs_until,
        'ended_at', x.ended_at,
        'items', coalesce((
          select jsonb_agg(app.exercise_plan_item_json(xi) - 'id' - 'variant_id'
                           - 'previous_item_id' - 'variant_archived' order by xi.position)
          from public.exercise_plan_items xi where xi.plan_id = x.id
        ), '[]'::jsonb),
        -- UEB-011: die Uebungstage, die die Person an diesem Plan gewaehlt hat.
        'weekdays', (select to_jsonb(d.weekdays) from public.exercise_plan_days d
                     where d.plan_id = x.id),
        -- UEB-010: die durchgefuehrten Einheiten, ohne interne Kennung.
        'sessions', (
          select coalesce(jsonb_agg(z - 'id'), '[]'::jsonb)
          from jsonb_array_elements(app.exercise_plan_sessions_json(x.id)) z
        )
      ) order by x.created_at)
      from public.exercise_plans x
      where x.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- KOM-004: die Rueckfragen ueber die Plattform mit allen Eintraegen
    -- (Art. 15), zugeordnete und nicht zugeordnete.
    'platform_messages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'topic', m.topic,
        'reference_label', m.reference_label,
        'status', m.status,
        'created_at', m.created_at,
        'closed_at', m.closed_at,
        'record_assigned_at', m.record_assigned_at,
        'entries', coalesce((
          select jsonb_agg(jsonb_build_object(
            'side', e.side,
            'author_kind', e.author_kind,
            'author_label', e.author_label,
            'body', e.body,
            'created_at', e.created_at
          ) order by e.created_at, e.id)
          from public.platform_message_entries e where e.message_id = m.id
        ), '[]'::jsonb),
        -- BEF-146: die Fotos und Videos an der Rueckfrage (KOM-005) als
        -- Liste, wie `patient_files` - ohne Inhalt, ohne Objektschluessel und
        -- ohne Kennung des Zugangs; wer angehaengt hat, wie an den Eintraegen.
        'attachments', coalesce((
          select jsonb_agg(jsonb_build_object(
            'media_kind', a.media_kind,
            'mime_type', a.mime_type,
            'byte_size', a.byte_size,
            'duration_seconds', a.duration_seconds,
            'status', a.status,
            'author_kind', a.author_kind,
            'author_label', a.author_label,
            'created_at', a.created_at,
            'locked_at', a.locked_at
          ) order by a.created_at, a.id)
          from public.platform_message_attachments a where a.message_id = m.id
        ), '[]'::jsonb)
      ) order by m.created_at)
      from public.platform_messages m
      where m.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- BEF-144: die Terminwuensche ueber die Plattform (POR-009) mit Tagen,
    -- Tageszeiten, Notiz, Zustand und Antwort der Praxis (Art. 15), offene wie
    -- beantwortete. Wer gewuenscht hat, steht wie in der Praxisliste (POR-011):
    -- die Person selbst oder die Vertretung mit Namen.
    'platform_appointment_requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', w.kind,
        'appointment_id', w.appointment_id,
        'preferred_days', to_jsonb(w.preferred_days),
        'preferred_times', to_jsonb(w.preferred_times),
        'note', w.note,
        'status', w.status,
        'requested_by', z.access_kind,
        'representative_name', case when z.access_kind <> 'self' then z.representative_name end,
        'created_at', w.created_at,
        'resolved_at', w.resolved_at,
        'answer', w.answer,
        'resulting_appointment_id', w.resulting_appointment_id
      ) order by w.created_at, w.id)
      from public.platform_appointment_requests w
      join public.platform_accesses z on z.id = w.created_by_access_id
      where w.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- TRK-002: Takt und Fragen des Check-ins (Art. 15), ohne bearbeitendes
    -- Praxiskonto.
    'checkin_schedules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'interval_days', s.interval_days,
        'parameter_keys', to_jsonb(s.parameter_keys),
        'starts_on', s.starts_on,
        'created_at', s.created_at,
        'updated_at', s.updated_at
      ))
      from public.checkin_schedules s
      where s.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- TRK-002: die beantworteten Check-ins mit ihren Angaben, unveraendert.
    'checkins', app.checkins_json('treatment', p_patient_id),

    -- ALT-003: Gewohnheiten mit den vermerkten Tagen (Art. 15), ohne
    -- Praxiskonto und Zugang.
    'habits', app.habits_json('treatment', p_patient_id),

    -- ERN-001 (ADR-027 Punkt 6): die Ernaehrungsberatung an dieser Akte -
    -- Profil, Einwilligung mit Verlauf, Gewicht, Zielwerte mit Rechenweg und
    -- Notizen, auch beendete Profile. Die Auskunft erteilt owner, der die
    -- Faehigkeit traegt (ADR-027 Punkt 4).
    'nutrition_profiles', coalesce((
      select jsonb_agg(app.nutrition_profile_json(n.id) order by n.started_on, n.created_at)
      from public.nutrition_profiles n
      where n.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- BEF-145: die Zugaenge zur Plattform an dieser Akte (Art. 15) - der
    -- eigene und die einer Vertretung oder Begleitung, mit Zustand und
    -- Zeitpunkten, Grundlage, Umfang und Art der angesehenen Nachweise
    -- (ANN-342). Keine Kennung von Zugang, Konto, Verhaeltnis oder
    -- bearbeitendem Praxiskonto.
    'platform_accesses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'access_kind', z.access_kind,
        'representative_name', z.representative_name,
        'legal_basis', z.legal_basis,
        'proof_documents', to_jsonb(z.proof_documents),
        'proof_recorded_at', z.proof_recorded_at,
        'health_scope', z.health_scope,
        'finance_scope', z.finance_scope,
        'consent_text_version', z.consent_text_version,
        'consent_recorded_at', z.consent_recorded_at,
        'consent_earlier_messages', z.consent_earlier_messages,
        'companion_declined_at', z.companion_declined_at,
        'companion_declined_reason', z.companion_declined_reason,
        'status', z.status,
        'created_at', z.created_at,
        'activated_at', z.activated_at,
        'locked_at', z.locked_at,
        'revoked_at', z.revoked_at,
        'revoked_reason', z.revoked_reason,
        'onboarding_finished_at', z.onboarding_finished_at,
        'onboarding_skipped_at', z.onboarding_skipped_at,
        -- Zweitreview BEF-146: die Einladungen zum Zugang - ohne Code
        -- (Zugangsdaten) und ohne Kennung des ausstellenden Kontos. Die
        -- Adresse nur am eigenen Zugang: die einer Vertretung oder Begleitung
        -- ist deren Datum, ihr Name steht schon am Zugang (Art. 15 Abs. 4).
        'invitations', coalesce((
          select jsonb_agg(jsonb_build_object(
            'purpose', i.purpose,
            'channel', i.channel,
            'email', case when z.access_kind = 'self' then i.email end,
            'address_confirmed_at', i.address_confirmed_at,
            'status', i.status,
            'created_at', i.created_at,
            'sent_at', i.sent_at,
            'expires_at', i.expires_at,
            'failed_attempts', i.failed_attempts,
            'redeemed_at', i.redeemed_at,
            'revoked_at', i.revoked_at
          ) order by i.created_at, i.id)
          from public.platform_access_invitations i where i.platform_access_id = z.id
        ), '[]'::jsonb)
      ) order by z.created_at, z.id)
      from public.platform_accesses z
      where z.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- ABR-030: Honorarvereinbarungen sind Daten zur Person (Art. 15 DSGVO).
    -- ABR-031: das festgeschriebene Terminhonorar je Termin (Art. 15 DSGVO).
    'session_fees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'appointment_id', f.appointment_id,
        'performed_on', f.performed_on,
        'amount_cents', f.amount_cents,
        'source', f.source,
        'created_at', f.created_at
      ) order by f.performed_on)
      from public.appointment_session_fees f
      join public.appointments a on a.id = f.appointment_id
      where a.patient_id = p_patient_id
    ), '[]'::jsonb),

    'fee_agreements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', f.id,
        'valid_from', f.valid_from,
        'session_fee_cents', f.session_fee_cents,
        'created_at', f.created_at
      ) order by f.valid_from)
      from public.patient_fee_agreements f
      where f.patient_id = p_patient_id
    ), '[]'::jsonb),

    'invoice_recipients', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', e.id,
        'recipient_kind', e.recipient_kind,
        'name', e.name,
        'street', e.street,
        'house_number', e.house_number,
        'postal_code', e.postal_code,
        'city', e.city,
        'reference', e.reference,
        'is_default', e.is_default,
        'created_at', e.created_at
      ) order by e.created_at)
      from public.invoice_recipients e
      where e.patient_id = p_patient_id
    ), '[]'::jsonb),

    'invoices', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'status', r.status,
        'invoice_number', r.invoice_number,
        'period_month', r.period_month,
        'issued_on', r.issued_on,
        'due_on', r.due_on,
        'total_cents', r.total_cents,
        'tax_total_cents', r.tax_total_cents,
        'currency', r.currency,
        'service_area', r.service_area,
        'snapshot', r.snapshot,
        'created_at', r.created_at
      ) order by r.created_at)
      from public.invoices r
      where r.patient_id = p_patient_id
    ), '[]'::jsonb),

    'invoice_items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', ri.id,
        'invoice_id', ri.invoice_id,
        'billable_service_id', ri.billable_service_id,
        'sort_order', ri.sort_order,
        'service_area', ri.service_area
      ) order by ri.sort_order)
      from public.invoice_items ri
      join public.invoices r on r.id = ri.invoice_id
      where r.patient_id = p_patient_id
    ), '[]'::jsonb),

    'invoice_cancellations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', st.id,
        'invoice_id', st.invoice_id,
        'cancellation_number', st.cancellation_number,
        'reason', st.reason,
        'cancelled_on', st.cancelled_on
      ) order by st.cancelled_on)
      from public.invoice_cancellations st
      join public.invoices r on r.id = st.invoice_id
      where r.patient_id = p_patient_id
    ), '[]'::jsonb),

    'invoice_payment_reminders', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id,
        'invoice_id', m.invoice_id,
        'reminder_on', m.reminder_on,
        'due_on', m.due_on,
        'outstanding_cents', m.outstanding_cents,
        'currency', m.currency
      ) order by m.reminder_on)
      from public.invoice_payment_reminders m
      join public.invoices r on r.id = m.invoice_id
      where r.patient_id = p_patient_id
    ), '[]'::jsonb),

    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', z.id,
        'invoice_id', z.invoice_id,
        'direction', z.direction,
        'amount_cents', z.amount_cents,
        'currency', z.currency,
        'paid_on', z.paid_on,
        'method', z.method,
        'note', z.note,
        'voided_at', z.voided_at,
        'void_reason', z.void_reason
      ) order by z.paid_on)
      from public.payments z
      join public.invoices r on r.id = z.invoice_id
      where r.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- PAT-006: Vermerke zu Datenschutzinformation, Vertrag und Einwilligungen.
    'patient_privacy_records', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pr.id,
        'record_kind', pr.record_kind,
        'purpose', pr.purpose,
        'notice_version', pr.notice_version,
        'occurred_on', pr.occurred_on,
        'recorded_at', pr.recorded_at,
        -- POR-016: Herkunft, Vertretung und Textfassung (Zweitreview).
        'source', pr.source,
        'platform_access_kind', pr.platform_access_kind,
        'representative_name', pr.representative_name,
        'wording_version', pr.wording_version
      ) order by pr.recorded_at)
      from public.patient_privacy_records pr
      where pr.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- FRB-002b: erhobene Fragebögen samt Korrekturen, mit Antworten.
    'patient_questionnaire_responses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', qr.id,
        'instrument_id', qr.instrument_id,
        'definition_version', qr.definition_version,
        'status', qr.status,
        'recorded_on', qr.recorded_on,
        'answers', qr.answers,
        'supersedes_response_id', qr.supersedes_response_id,
        'change_reason', qr.change_reason,
        'author', (
          select up.display_name from public.user_profiles up where up.id = qr.created_by
        ),
        'created_at', qr.created_at,
        'completed_at', qr.completed_at
      ) order by qr.recorded_on, qr.created_at)
      from public.patient_questionnaire_responses qr
      where qr.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- FRB-002e: Ereignisse im Verlauf.
    'patient_course_events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', ce.id,
        'occurred_on', ce.occurred_on,
        'kind', ce.kind,
        'note', ce.note,
        'created_at', ce.created_at,
        -- ABN-013 (BEF-102): Ein entferntes Ereignis bleibt Teil der Akte.
        'removed_at', ce.removed_at
      ) order by ce.occurred_on, ce.created_at)
      from public.patient_course_events ce
      where ce.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- ABN-015: gesicherte, noch nicht uebernommene Befundangaben.
    'treatment_draft_findings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'appointment_id', df.appointment_id,
        'findings', df.findings,
        'updated_at', df.updated_at
      ) order by df.updated_at)
      from public.treatment_draft_findings df
      join public.appointments a on a.id = df.appointment_id
      where a.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- DOK-005a: Therapieberichte an die Verordner:in.
    'therapy_reports', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', tr.id,
        'treatment_basis_id', tr.treatment_basis_id,
        'status', tr.status,
        'report_text', tr.report_text,
        'recommendation', tr.recommendation,
        'note_ids', to_jsonb(tr.note_ids),
        'body_chart_response_id', tr.body_chart_response_id,
        'snapshot', tr.snapshot,
        'author', (
          select up.display_name from public.user_profiles up where up.id = tr.created_by
        ),
        'created_at', tr.created_at,
        'completed_at', tr.completed_at
      ) order by tr.created_at)
      from public.therapy_reports tr
      where tr.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- PRX-001: Wartelisteneintraege mit Wunschfenstern.
    'waitlist_entries', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', w.id,
        'treatment_basis_id', w.treatment_basis_id,
        'appointment_type', w.appointment_type,
        'duration_minutes', w.duration_minutes,
        'time_windows', w.time_windows,
        'earliest_on', w.earliest_on,
        'needed_by', w.needed_by,
        'priority_reason', w.priority_reason,
        'note', w.note,
        'status', w.status,
        'placed_appointment_id', w.placed_appointment_id,
        'created_at', w.created_at,
        'closed_at', w.closed_at
      ) order by w.created_at)
      from public.waitlist_entries w
      where w.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- PRX-012: Aufgaben und Wiedervorlagen mit Bezug auf diese Person.
    'tasks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', k.id,
        'title', k.title,
        'note', k.note,
        'due_on', k.due_on,
        'status', k.status,
        'assigned_to', nullif(btrim(concat_ws(' ', ape.given_name, ape.family_name)), ''),
        'created_at', k.created_at,
        'done_at', k.done_at
      ) order by k.created_at)
      from public.tasks k
      left join public.staff_members asm on asm.id = k.assigned_staff_member_id
      left join public.persons ape on ape.id = asm.person_id
      where k.patient_id = p_patient_id
    ), '[]'::jsonb),

    -- PRX-014: Anrufstand der Termine (nicht erreicht, Nachricht hinterlassen).
    'appointment_call_states', coalesce((
      select jsonb_agg(jsonb_build_object(
        'appointment_id', c.appointment_id,
        'outcome', c.outcome,
        'attempts', c.attempts,
        'recorded_at', c.recorded_at
      ) order by c.recorded_at)
      from public.appointment_call_states c
      join public.appointments a on a.id = c.appointment_id
      where a.patient_id = p_patient_id
    ), '[]'::jsonb)
  )
  into v_daten;

  -- Der Auditeintrag traegt nur Metadaten: wer, wann, welche Akte (ADR-010
  -- Punkt 3). Keine Zahl ueber den Inhalt, kein Name.
  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'patient_record.exported', 'patient', p_patient_id, 'success',
    jsonb_build_object('surface', 'web', 'purpose', 'auskunft_art_15')
  );

  return jsonb_build_object(
    'erstellt_am', now(),
    'organisation', (select o.name from public.organizations o where o.id = v_org),
    'patient_id', p_patient_id,
    'rechtsgrundlage', 'Art. 15 Abs. 3 DSGVO',
    'tabellen', v_daten,
    'nicht_enthalten', jsonb_build_array(
      jsonb_build_object(
        'was', 'Inhalt hochgeladener Dateien und Fotos',
        'grund', 'Die Kopie nennt jede Datei mit Name, Art und Pruefsumme und jedes Foto, auch gesperrte; die Datei selbst wird je Datei herausgegeben (ADR-017, ANN-128).'
      ),
      jsonb_build_object(
        'was', 'Inhalt der Fotos und Videos an Rueckfragen',
        'grund', 'Die Kopie nennt jeden Anhang mit Art, Groesse und Zeitpunkt, auch unbestaetigte und gesperrte. Die Datei oeffnet die Praxis an der Rueckfrage, solange sie bestaetigt, nicht gesperrt und juenger als 30 Tage ist (ADR-017 Punkt 61); eine Kopie gibt owner je Anhang heraus, auch von gesperrten, solange sie vorhanden sind (ADR-017 Punkt 96, BEF-188).'
      ),
      jsonb_build_object(
        'was', 'Benachrichtigungen je Zugang',
        'grund', 'Wahl, Geraete, Zustellungen und Tagebuch-Erinnerungen waehlt jede Person fuer ihren Zugang; die Praxis sieht sie nicht (ANN-344). Jede Person findet ihre eigene Wahl im Export der Plattform, solange der Zugang lesen kann (in der Lesezeit, nicht gesperrt), auch eine Begleitung (ADR-023 Punkt 13). Danach fallen Wahl, Erinnerungen und Geraete im taeglichen Lauf, Zustellungen 30 Tage nach dem Versand (ANN-669, BEF-189).'
      ),
      jsonb_build_object(
        'was', 'Namen der Beschaeftigten im Zugriffsprotokoll',
        'grund', 'Das Protokoll nennt Zeitpunkt und Zweck jedes Zugriffs; wer zugegriffen hat, steht nur auf begruendetes Verlangen nach Pruefung im Einzelfall darin (Art. 15 Abs. 4 DSGVO, ANN-092).'
      ),
      jsonb_build_object(
        'was', 'Daten eines Trainingsverhaeltnisses',
        'grund', 'Training ist ein eigenes Rechtsverhaeltnis mit eigener Akte und eigener Frist (ADR-021); die Auskunft dazu wird getrennt erteilt.'
      ),
      jsonb_build_object(
        'was', 'Interne Kennungen bearbeitender Konten',
        'grund', 'Wo eine Person die Angabe traegt, steht ihr Name; die technische Kennung des Kontos sagt nichts aus.'
      )
    )
  );
end;
$$;

COMMENT ON FUNCTION public.export_patient_record(p_patient_id uuid) IS 'Kopie der Patientenakte nach Art. 15 Abs. 3 DSGVO. Nur owner, nur eigene Organisation, jeder Aufruf als patient_record.exported protokolliert (OPS-006, ADR-007, ADR-010).';

CREATE FUNCTION public.export_training_record(p_training_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_actor  uuid;
  v_id     uuid := p_training_relationship_id;
  v_daten  jsonb;
begin
  v_actor := auth.uid();
  v_org   := app.auskunft_organisation_training(v_id);

  select jsonb_build_object(
    'persons', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pe.id,
        'given_name', pe.given_name,
        'family_name', pe.family_name,
        'created_at', pe.created_at
      ))
      from public.persons pe
      join public.training_relationships t on t.person_id = pe.id
      where t.id = v_id
    ), '[]'::jsonb),

    'training_relationships', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(t)))
      from public.training_relationships t
      where t.id = v_id
    ), '[]'::jsonb),

    -- Die Tabellen des Verhältnisses (KND, TRN): jede Zeile, wie sie
    -- gespeichert ist, ohne interne Kennungen - auch entfernte Einträge,
    -- solange sie da sind.
    'training_contact_details', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)))
      from public.training_contact_details x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_profiles', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)))
      from public.training_profiles x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    -- Mit den Messwerten (OUT-002) - Gesundheitsangaben nach Art. 9.
    'training_assessments', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)) || jsonb_build_object(
        'author', (select up.display_name from public.user_profiles up where up.id = x.created_by),
        'results', coalesce((
          select jsonb_agg(jsonb_build_object(
            'position', w.position,
            'label', w.label,
            'unit', w.unit,
            'value', w.value,
            'value_left', w.value_left,
            'value_right', w.value_right
          ) order by w.position)
          from public.training_assessment_results w where w.assessment_id = x.id
        ), '[]'::jsonb)
      ) order by x.performed_on, x.created_at)
      from public.training_assessments x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_bases', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)) order by x.started_on, x.created_at)
      from public.training_bases x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_consent_records', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)) order by x.occurred_on, x.recorded_at)
      from public.training_consent_records x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_contracts', coalesce((
      select jsonb_agg((app.auskunft_ohne_kennungen(to_jsonb(x)) - 'training_package_id')
                       order by x.offered_on)
      from public.training_contracts x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_course_events', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)) || jsonb_build_object(
        'author', (select up.display_name from public.user_profiles up where up.id = x.created_by)
      ) order by x.occurred_on, x.created_at)
      from public.training_course_events x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    -- Mit den Nachträgen (ABN-022) am Protokoll.
    'training_protocols', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)) || jsonb_build_object(
        'author', (select up.display_name from public.user_profiles up where up.id = x.created_by),
        'addenda', coalesce((
          select jsonb_agg(jsonb_build_object(
            'content', n.content,
            'reason', n.reason,
            'author', (select up.display_name from public.user_profiles up where up.id = n.created_by),
            'created_at', n.created_at
          ) order by n.created_at, n.id)
          from public.training_protocol_addenda n where n.protocol_id = x.id
        ), '[]'::jsonb)
      ) order by x.created_at)
      from public.training_protocols x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_takeovers', coalesce((
      select jsonb_agg(app.auskunft_ohne_kennungen(to_jsonb(x)) order by x.position)
      from public.training_takeovers x where x.training_relationship_id = v_id
    ), '[]'::jsonb),
    'training_packages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'label', c.label,
        'starts_on', x.starts_on,
        'ends_on', x.ends_on,
        'created_at', x.created_at
      ) order by x.starts_on)
      from public.training_packages x
      join public.service_catalog_items c on c.id = x.catalog_item_id
      where x.training_relationship_id = v_id
    ), '[]'::jsonb),

    -- Wie an der Akte: Termine mit Betreuung beim Namen, nicht als Kennung.
    'appointments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id,
        'kind', t.kind,
        'appointment_type', t.appointment_type,
        'status', t.status,
        'title', t.title,
        'starts_at', t.starts_at,
        'ends_at', t.ends_at,
        'staff_member', (
          select btrim(tp.given_name || ' ' || tp.family_name)
          from public.staff_members sm
          join public.persons tp on tp.id = sm.person_id
          where sm.id = t.staff_member_id
        ),
        'visit_street', t.visit_street,
        'visit_house_number', t.visit_house_number,
        'visit_postal_code', t.visit_postal_code,
        'visit_city', t.visit_city,
        'visit_lat', t.visit_lat,
        'visit_lon', t.visit_lon,
        'cancellation_reason', t.cancellation_reason,
        'cancellation_received_at', t.cancellation_received_at,
        'fee_basis', t.fee_basis,
        'fee_waived_at', t.fee_waived_at,
        'no_show_recorded_at', t.no_show_recorded_at,
        'completed_at', t.completed_at,
        'created_at', t.created_at
      ) order by t.starts_at)
      from public.appointments t
      where t.training_relationship_id = v_id
    ), '[]'::jsonb),

    'appointment_notifications', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', n.id,
        'appointment_id', n.appointment_id,
        'channel', n.channel,
        'notified_at', n.notified_at
      ) order by n.notified_at)
      from public.appointment_notifications n
      join public.appointments t on t.id = n.appointment_id
      where t.training_relationship_id = v_id
    ), '[]'::jsonb),

    'session_fees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'appointment_id', f.appointment_id,
        'performed_on', f.performed_on,
        'amount_cents', f.amount_cents,
        'source', f.source,
        'created_at', f.created_at
      ) order by f.performed_on)
      from public.appointment_session_fees f
      join public.appointments a on a.id = f.appointment_id
      where a.training_relationship_id = v_id
    ), '[]'::jsonb),

    -- Zugriffe auf das Verhältnis: Zeitpunkt und Zweck, ohne Namen und
    -- Kennung der Beschäftigten (Art. 15 Abs. 4 DSGVO, ANN-092).
    'access_log', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zeitpunkt', al.occurred_at,
        'aktion', al.action,
        'gegenstand', al.subject_type,
        'ergebnis', al.outcome,
        'durch', case al.actor_kind
                   when 'user' then 'praxis'
                   when 'system' then 'system'
                   when 'platform' then 'person_selbst'
                   when 'representative' then 'vertretung'
                 end
      )
      -- BEF-189 (Zweitreview): Der Export einer Begleitung umfasst nur ihre
      -- eigene Wahl zu Benachrichtigungen, nicht die Daten der Person.
      || case when al.context ->> 'part' = 'notifications'
              then jsonb_build_object('umfang', 'nur_eigene_benachrichtigungen')
              else '{}'::jsonb end
      order by al.occurred_at)
      from public.audit_log al
      where al.organization_id = v_org
        and al.outcome = 'success'
        and ((al.subject_type = 'training_relationship' and al.subject_id = v_id)
             or al.context ->> 'training_relationship_id' = v_id::text)
    ), '[]'::jsonb),

    'billable_services', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', l.id,
        'appointment_id', l.appointment_id,
        'performed_on', l.performed_on,
        'quantity', l.quantity,
        'status', l.status,
        'service_area', l.service_area,
        'service', (
          select btrim(k.code || ' ' || k.label)
          from public.service_catalog_items k
          where k.id = l.catalog_item_id
        )
      ) order by l.performed_on)
      from public.billable_services l
      where l.training_relationship_id = v_id
    ), '[]'::jsonb),

    'invoices', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'status', r.status,
        'invoice_number', r.invoice_number,
        'period_month', r.period_month,
        'issued_on', r.issued_on,
        'due_on', r.due_on,
        'total_cents', r.total_cents,
        'tax_total_cents', r.tax_total_cents,
        'currency', r.currency,
        'service_area', r.service_area,
        'snapshot', r.snapshot,
        'created_at', r.created_at
      ) order by r.created_at)
      from public.invoices r
      where r.training_relationship_id = v_id
    ), '[]'::jsonb),

    'invoice_items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', ri.id,
        'invoice_id', ri.invoice_id,
        'billable_service_id', ri.billable_service_id,
        'sort_order', ri.sort_order,
        'service_area', ri.service_area
      ) order by ri.sort_order)
      from public.invoice_items ri
      join public.invoices r on r.id = ri.invoice_id
      where r.training_relationship_id = v_id
    ), '[]'::jsonb),

    'invoice_cancellations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', st.id,
        'invoice_id', st.invoice_id,
        'cancellation_number', st.cancellation_number,
        'reason', st.reason,
        'cancelled_on', st.cancelled_on
      ) order by st.cancelled_on)
      from public.invoice_cancellations st
      join public.invoices r on r.id = st.invoice_id
      where r.training_relationship_id = v_id
    ), '[]'::jsonb),

    'invoice_payment_reminders', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id,
        'invoice_id', m.invoice_id,
        'reminder_on', m.reminder_on,
        'due_on', m.due_on,
        'outstanding_cents', m.outstanding_cents,
        'currency', m.currency
      ) order by m.reminder_on)
      from public.invoice_payment_reminders m
      join public.invoices r on r.id = m.invoice_id
      where r.training_relationship_id = v_id
    ), '[]'::jsonb),

    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', z.id,
        'invoice_id', z.invoice_id,
        'direction', z.direction,
        'amount_cents', z.amount_cents,
        'currency', z.currency,
        'paid_on', z.paid_on,
        'method', z.method,
        'note', z.note,
        'voided_at', z.voided_at,
        'void_reason', z.void_reason
      ) order by z.paid_on)
      from public.payments z
      join public.invoices r on r.id = z.invoice_id
      where r.training_relationship_id = v_id
    ), '[]'::jsonb),

    'exercise_plans', coalesce((
      select jsonb_agg(jsonb_build_object(
        'title', x.title,
        'status', x.status,
        'sessions_per_week', x.sessions_per_week,
        'created_at', x.created_at,
        'assigned_at', x.assigned_at,
        'runs_from', x.runs_from,
        'runs_until', x.runs_until,
        'ended_at', x.ended_at,
        'items', coalesce((
          select jsonb_agg(app.exercise_plan_item_json(xi) - 'id' - 'variant_id'
                           - 'previous_item_id' - 'variant_archived' order by xi.position)
          from public.exercise_plan_items xi where xi.plan_id = x.id
        ), '[]'::jsonb),
        'weekdays', (select to_jsonb(d.weekdays) from public.exercise_plan_days d
                     where d.plan_id = x.id),
        'sessions', (
          select coalesce(jsonb_agg(z - 'id'), '[]'::jsonb)
          from jsonb_array_elements(app.exercise_plan_sessions_json(x.id)) z
        )
      ) order by x.created_at)
      from public.exercise_plans x
      where x.training_relationship_id = v_id
    ), '[]'::jsonb),

    -- Die Rückfragen über die Plattform mit Einträgen und Anhängen (wie an
    -- der Akte seit BEF-146).
    'platform_messages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'topic', m.topic,
        'reference_label', m.reference_label,
        'status', m.status,
        'created_at', m.created_at,
        'closed_at', m.closed_at,
        'record_assigned_at', m.record_assigned_at,
        'entries', coalesce((
          select jsonb_agg(jsonb_build_object(
            'side', e.side,
            'author_kind', e.author_kind,
            'author_label', e.author_label,
            'body', e.body,
            'created_at', e.created_at
          ) order by e.created_at, e.id)
          from public.platform_message_entries e where e.message_id = m.id
        ), '[]'::jsonb),
        'attachments', coalesce((
          select jsonb_agg(jsonb_build_object(
            'media_kind', a.media_kind,
            'mime_type', a.mime_type,
            'byte_size', a.byte_size,
            'duration_seconds', a.duration_seconds,
            'status', a.status,
            'author_kind', a.author_kind,
            'author_label', a.author_label,
            'created_at', a.created_at,
            'locked_at', a.locked_at
          ) order by a.created_at, a.id)
          from public.platform_message_attachments a where a.message_id = m.id
        ), '[]'::jsonb)
      ) order by m.created_at)
      from public.platform_messages m
      where m.training_relationship_id = v_id
    ), '[]'::jsonb),

    'platform_appointment_requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', w.kind,
        'appointment_id', w.appointment_id,
        'preferred_days', to_jsonb(w.preferred_days),
        'preferred_times', to_jsonb(w.preferred_times),
        'note', w.note,
        'status', w.status,
        'requested_by', z.access_kind,
        'representative_name', case when z.access_kind <> 'self' then z.representative_name end,
        'created_at', w.created_at,
        'resolved_at', w.resolved_at,
        'answer', w.answer,
        'resulting_appointment_id', w.resulting_appointment_id
      ) order by w.created_at, w.id)
      from public.platform_appointment_requests w
      join public.platform_accesses z on z.id = w.created_by_access_id
      where w.training_relationship_id = v_id
    ), '[]'::jsonb),

    'checkin_schedules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'interval_days', s.interval_days,
        'parameter_keys', to_jsonb(s.parameter_keys),
        'starts_on', s.starts_on,
        'created_at', s.created_at,
        'updated_at', s.updated_at
      ))
      from public.checkin_schedules s
      where s.training_relationship_id = v_id
    ), '[]'::jsonb),

    'checkins', app.checkins_json('training', v_id),

    'habits', app.habits_json('training', v_id),

    -- ERN-EPIC-001 (ADR-027 Punkt 6): die Ernährungsberatung am Verhältnis,
    -- mit Notizen der Beratung - die Schlüsselliste der Plattform hat sie nicht.
    'nutrition_profiles', coalesce((
      select jsonb_agg(app.nutrition_profile_json(n.id) order by n.started_on, n.created_at)
      from public.nutrition_profiles n
      where n.training_relationship_id = v_id
    ), '[]'::jsonb),

    'platform_accesses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'access_kind', z.access_kind,
        'representative_name', z.representative_name,
        'legal_basis', z.legal_basis,
        'proof_documents', to_jsonb(z.proof_documents),
        'proof_recorded_at', z.proof_recorded_at,
        'health_scope', z.health_scope,
        'finance_scope', z.finance_scope,
        'consent_text_version', z.consent_text_version,
        'consent_recorded_at', z.consent_recorded_at,
        'consent_earlier_messages', z.consent_earlier_messages,
        'companion_declined_at', z.companion_declined_at,
        'companion_declined_reason', z.companion_declined_reason,
        'status', z.status,
        'created_at', z.created_at,
        'activated_at', z.activated_at,
        'locked_at', z.locked_at,
        'revoked_at', z.revoked_at,
        'revoked_reason', z.revoked_reason,
        'onboarding_finished_at', z.onboarding_finished_at,
        'onboarding_skipped_at', z.onboarding_skipped_at,
        -- Wie an der Akte (Zweitreview BEF-146): ohne Code, die Adresse nur am
        -- eigenen Zugang (Art. 15 Abs. 4).
        'invitations', coalesce((
          select jsonb_agg(jsonb_build_object(
            'purpose', i.purpose,
            'channel', i.channel,
            'email', case when z.access_kind = 'self' then i.email end,
            'address_confirmed_at', i.address_confirmed_at,
            'status', i.status,
            'created_at', i.created_at,
            'sent_at', i.sent_at,
            'expires_at', i.expires_at,
            'failed_attempts', i.failed_attempts,
            'redeemed_at', i.redeemed_at,
            'revoked_at', i.revoked_at
          ) order by i.created_at, i.id)
          from public.platform_access_invitations i where i.platform_access_id = z.id
        ), '[]'::jsonb)
      ) order by z.created_at, z.id)
      from public.platform_accesses z
      where z.training_relationship_id = v_id
    ), '[]'::jsonb)
  )
  into v_daten;

  -- Der Auditeintrag trägt nur Metadaten: wer, wann, welches Verhältnis
  -- (ADR-010 Punkt 3); dieselbe Aktion wie die Auskunft zur Akte.
  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'patient_record.exported', 'training_relationship', v_id, 'success',
    jsonb_build_object('surface', 'web', 'purpose', 'auskunft_art_15')
  );

  return jsonb_build_object(
    'erstellt_am', now(),
    'organisation', (select o.name from public.organizations o where o.id = v_org),
    'training_relationship_id', v_id,
    'rechtsgrundlage', 'Art. 15 Abs. 3 DSGVO',
    'tabellen', v_daten,
    'nicht_enthalten', jsonb_build_array(
      jsonb_build_object(
        'was', 'Inhalt der Fotos und Videos an Rueckfragen',
        'grund', 'Die Kopie nennt jeden Anhang mit Art, Groesse und Zeitpunkt, auch unbestaetigte und gesperrte. Die Datei oeffnet die Praxis an der Rueckfrage, solange sie bestaetigt, nicht gesperrt und juenger als 30 Tage ist (ADR-017 Punkt 61); eine Kopie gibt owner je Anhang heraus, auch von gesperrten, solange sie vorhanden sind (ADR-017 Punkt 96, BEF-188).'
      ),
      jsonb_build_object(
        'was', 'Namen der Beschaeftigten im Zugriffsprotokoll',
        'grund', 'Das Protokoll nennt Zeitpunkt und Zweck jedes Zugriffs; wer zugegriffen hat, steht nur auf begruendetes Verlangen nach Pruefung im Einzelfall darin (Art. 15 Abs. 4 DSGVO, ANN-092).'
      ),
      jsonb_build_object(
        'was', 'Daten einer Behandlung',
        'grund', 'Die Behandlung ist ein eigenes Rechtsverhaeltnis mit eigener Akte (ADR-021); die Auskunft dazu erteilt die Praxis an der Akte.'
      ),
      jsonb_build_object(
        'was', 'Benachrichtigungen je Zugang',
        'grund', 'Wahl, Geraete, Zustellungen und Tagebuch-Erinnerungen waehlt jede Person fuer ihren Zugang; die Praxis sieht sie nicht (ANN-344). Jede Person findet ihre eigene Wahl im Export der Plattform, solange der Zugang lesen kann (in der Lesezeit, nicht gesperrt), auch eine Begleitung (ADR-023 Punkt 13). Danach fallen Wahl, Erinnerungen und Geraete im taeglichen Lauf, Zustellungen 30 Tage nach dem Versand (ANN-669, BEF-189).'
      ),
      jsonb_build_object(
        'was', 'Interne Kennungen bearbeitender Konten',
        'grund', 'An Protokollen, Nachtraegen, Assessments und Ereignissen steht der Name der verfassenden Person; die technische Kennung eines Kontos sagt nichts aus.'
      )
    )
  );
end;
$$;

COMMENT ON FUNCTION public.export_training_record(p_training_relationship_id uuid) IS 'BEF-182: Auskunft nach Art. 15 zu einem Trainingsverhaeltnis - Kopie aller Daten des Verhaeltnisses, nur owner, ein Protokolleintrag patient_record.exported je Kopie (wie export_patient_record).';

CREATE FUNCTION public.extend_exercise_plan(p_plan_id uuid, p_runs_until date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan  public.exercise_plans%rowtype;
  v_heute date;
begin
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'assigned' then
    raise exception 'only an assigned exercise plan can be extended' using errcode = '22023';
  end if;
  perform app.exercise_plan_relationship_open(v_plan);

  v_heute := app.training_today(v_plan.organization_id);
  if p_runs_until is null or p_runs_until <= v_plan.runs_until or p_runs_until < v_heute
     or p_runs_until > v_heute + app.exercise_plan_max_days() then
    raise exception 'runs until is invalid' using errcode = '22023';
  end if;

  update public.exercise_plans
     set runs_until = p_runs_until,
         extended_at = now(),
         extended_by = auth.uid(),
         updated_at = now(),
         updated_by = auth.uid()
   where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.extend_exercise_plan(p_plan_id uuid, p_runs_until date) IS 'UEB-007: verlaengert einen zugewiesenen Plan bis p_runs_until - spaeter als bisher, hoechstens 26 Wochen ab heute (ANN-302). Der Inhalt bleibt (ANN-300). Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.finalize_overdue_treatment_notes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_note  record;
  v_count integer := 0;
begin
  for v_note in
    select t.id,
           t.organization_id,
           t.appointment_id,
           t.content,
           t.updated_by,
           a.patient_id,
           app.documentation_deadline(
             a.starts_at, t.created_at, o.time_zone, o.documentation_auto_finalize_days
           ) as due_at
    from public.treatment_notes t
    join public.appointments a   on a.id = t.appointment_id
    join public.organizations o  on o.id = t.organization_id
    where t.status = 'draft'
      and a.kind = 'therapy'
      and app.documentation_deadline(
            a.starts_at, t.created_at, o.time_zone, o.documentation_auto_finalize_days
          ) <= now()
    order by t.created_at
    for update of t skip locked
  loop
    update public.treatment_notes
       set status            = 'final',
           finalisation_kind = 'automatic',
           finalized_at      = now(),
           finalized_by      = null,
           updated_at        = now()
     where id = v_note.id;

    insert into public.treatment_note_versions (
      organization_id, note_id, version_no, content, change_reason, author_id
    )
    values (
      v_note.organization_id, v_note.id, 1, v_note.content, null, v_note.updated_by
    );


    perform app.mark_appointment_documented(v_note.appointment_id, null);

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;

COMMENT ON FUNCTION public.finalize_overdue_treatment_notes() IS 'Finalisiert alle Entwuerfe, deren Frist abgelaufen ist, als Version 1, protokolliert je Eintrag treatment_note.auto_finalized mit Systemakteur und hebt den zugehoerigen Termin auf documented (DOK-004, ADR-016 Punkt 7, ADR-018 Punkt 3, ANN-007). Nur fuer den Scheduler ausfuehrbar.';

CREATE FUNCTION public.finalize_training_protocol(p_appointment_id uuid, p_content text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor     uuid;
  v_org       uuid;
  v_inhalt    text;
  v_termin    record;
  v_protokoll record;
  v_id        uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_access_training_protocols() then
    perform app.record_denied_write(v_actor, 'training_protocol.finalized', 'not allowed to write training protocols');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write training protocols' using errcode = '42501';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');
  if v_inhalt = '' then
    raise exception 'training protocol must not be empty' using errcode = '22023';
  end if;
  if length(v_inhalt) > 20000 then
    raise exception 'training protocol is too long' using errcode = '22023';
  end if;

  select a.id, a.status, a.training_relationship_id
    into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    and a.kind = 'training'
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_termin.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be protocolled' using errcode = '22023';
  end if;
  if v_termin.status = 'no_show' then
    raise exception 'no-show appointment cannot be protocolled' using errcode = '22023';
  end if;

  select p.id, p.status, p.updated_at
    into v_protokoll
  from public.training_protocols p
  where p.appointment_id = p_appointment_id
  for update;

  if found and v_protokoll.status = 'final' then
    raise exception 'finalized training protocol cannot be changed' using errcode = '22023';
  end if;

  -- Ein Termin ohne Protokoll ist nie `documented` (Trigger); hier also nur
  -- bestaetigt oder durchgefuehrt.
  if v_termin.status not in ('confirmed', 'completed') then
    raise exception 'appointment cannot be documented' using errcode = '22023';
  end if;

  if not found then
    begin
      insert into public.training_protocols (
        organization_id, training_relationship_id, appointment_id, status, content,
        created_by, updated_by, finalized_at, finalized_by
      )
      values (
        v_org, v_termin.training_relationship_id, p_appointment_id, 'final', v_inhalt,
        v_actor, v_actor, now(), v_actor
      )
      returning training_protocols.id into v_id;
    exception
      when unique_violation then
        raise exception 'training protocol already exists' using errcode = '23505';
    end;

  else
    if p_expected_updated_at is null then
      raise exception 'expected updated_at is required' using errcode = '22023';
    end if;
    if v_protokoll.updated_at is distinct from p_expected_updated_at then
      raise exception 'training protocol was changed meanwhile' using errcode = '40001';
    end if;

    v_id := v_protokoll.id;
    update public.training_protocols p
       set content      = v_inhalt,
           status       = 'final',
           updated_at   = now(),
           updated_by   = v_actor,
           finalized_at = now(),
           finalized_by = v_actor
     where p.id = v_id;
  end if;


  -- Zweitreview 3: Ohne den Uebergang nach `documented` gibt es keinen
  -- Abschluss - beide Richtungen der Invariante haengen an diesem Vorgang.
  if not app.mark_appointment_documented(p_appointment_id, v_actor) then
    raise exception 'appointment cannot be documented' using errcode = '40001';
  end if;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.finalize_training_protocol(p_appointment_id uuid, p_content text, p_expected_updated_at timestamp with time zone) IS 'TRN-009/TRN-010: schliesst das Trainingsprotokoll eines Trainingstermins ab (ohne Entwurf: legt es abgeschlossen an) und setzt den Termin im selben Vorgang auf documented (ADR-018 Punkt 3 nach ADR-022 Punkt 8). owner, trainer (ANN-184); unveraenderlich danach (ANN-185); abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.finalize_treatment_note(p_note_id uuid, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_note    record;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select t.id, t.appointment_id, t.content, t.status, t.updated_at, t.updated_by
    into v_note
  from public.treatment_notes t
  where t.id = p_note_id
    and t.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment note not found' using errcode = 'P0002';
  end if;

  if v_note.status = 'final' then
    raise exception 'treatment note is already final' using errcode = '22023';
  end if;

  if v_note.updated_at is distinct from p_expected_updated_at then
    raise exception 'treatment note was changed meanwhile' using errcode = '40001';
  end if;

  update public.treatment_notes
     set status            = 'final',
         finalisation_kind = 'manual',
         finalized_at      = now(),
         finalized_by      = v_actor,
         updated_at        = now(),
         updated_by        = v_actor
   where id = p_note_id
     and updated_at = p_expected_updated_at;

  if not found then
    raise exception 'treatment note was changed meanwhile' using errcode = '40001';
  end if;

  insert into public.treatment_note_versions (
    organization_id, note_id, version_no, content, change_reason, author_id
  )
  values (
    v_org, p_note_id, 1, v_note.content, null, v_note.updated_by
  );

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = v_note.appointment_id;


  -- NEU mit CAL-008d: Die Finalisierung setzt den Terminzustand mit
  -- (ADR-018 Punkt 3). Kein Fehler, sondern der gewollte Seiteneffekt.
  perform app.mark_appointment_documented(v_note.appointment_id, v_actor);

  return p_note_id;
end;
$$;

COMMENT ON FUNCTION public.finalize_treatment_note(p_note_id uuid, p_expected_updated_at timestamp with time zone) IS 'Finalisiert eine Behandlungsdokumentation von Hand, schreibt den Stand als Version 1 fest, protokolliert treatment_note.finalized und hebt den Termin auf documented (DOK-002, DOK-004, ADR-016 Punkt 4, ADR-018 Punkt 3).';

CREATE FUNCTION public.find_free_slots(p_patient_id uuid, p_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_from date, p_to date, p_windows jsonb DEFAULT '[]'::jsonb, p_limit integer DEFAULT 20) RETURNS TABLE(staff_member_id uuid, staff_name text, slot_date date, start_time time without time zone, end_time time without time zone, territory_status text, prev_appointment_id uuid, prev_lat double precision, prev_lon double precision, next_appointment_id uuid, next_lat double precision, next_lon double precision, target_lat double precision, target_lon double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_tz       text;
  v_grid     integer;
  v_heute    date;
  v_jetzt    integer;
  v_von      date;
  v_plz      text;
  v_lat      double precision;
  v_lon      double precision;
  v_fenster  jsonb := coalesce(p_windows, '[]'::jsonb);
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to create appointments');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;
  if p_staff_member_id is not null and not app.is_assignable_therapist(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;
  if p_appointment_type is null or p_appointment_type not in ('home_visit', 'practice', 'video') then
    raise exception 'invalid appointment type' using errcode = '22023';
  end if;
  if not app.waitlist_windows_valid(v_fenster) then
    raise exception 'invalid time windows' using errcode = '22023';
  end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'limit must be between 1 and 50' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes into v_tz, v_grid
  from public.organizations o where o.id = v_org;

  if p_duration_minutes is null or p_duration_minutes > 240
     or not app.is_valid_treatment_length(make_interval(mins => p_duration_minutes), v_grid) then
    raise exception 'invalid duration' using errcode = '22023';
  end if;

  v_heute := (now() at time zone v_tz)::date;
  v_jetzt := extract(hour from (now() at time zone v_tz))::integer * 60
             + extract(minute from (now() at time zone v_tz))::integer;
  v_von := greatest(p_from, v_heute);
  if p_from is null or p_to is null or p_to < v_von or p_to - v_von > 41 then
    raise exception 'date range must lie ahead and span at most 42 days' using errcode = '22023';
  end if;

  if p_appointment_type = 'home_visit' then
    select cd.postal_code, cd.lat, cd.lon into v_plz, v_lat, v_lon
    from public.patient_contact_details cd
    where cd.patient_id = p_patient_id;
  end if;

  return query
  with tage as (
    select d::date as tag
    from generate_series(v_von::timestamp, p_to::timestamp, interval '1 day') d
  ),
  personen as (
    select sm.id,
           nullif(btrim(concat_ws(' ', pe.given_name, pe.family_name)), '') as name
    from public.staff_members sm
    join public.persons pe on pe.id = sm.person_id
    where sm.organization_id = v_org
      and (p_staff_member_id is null or sm.id = p_staff_member_id)
      and app.is_assignable_therapist(sm.id, v_org)
  ),
  arbeit as (
    select p.id as staff, p.name, t.tag, app.working_ranges(p.id, v_org, t.tag) as bereiche
    from personen p cross join tage t
  ),
  -- Belegt ist, was die Person ODER die Patient:in an diesem Tag schon hat
  -- (§8: Patienten- und Therapeutenverfuegbarkeit sind harte Constraints).
  belegt as (
    select a.staff, a.tag,
           range_agg(app.timerange(
             greatest(t.starts_at at time zone v_tz, a.tag::timestamp)::time,
             case when t.ends_at at time zone v_tz >= (a.tag + 1)::timestamp
                  then time '24:00'
                  else (t.ends_at at time zone v_tz)::time end,
             '[)'
           )) as zeiten
    from arbeit a
    join public.appointments t
      on t.organization_id = v_org
     and t.status <> 'cancelled'
     and (t.staff_member_id = a.staff or t.patient_id = p_patient_id)
     and t.starts_at < ((a.tag + 1)::timestamp at time zone v_tz)
     and t.ends_at > (a.tag::timestamp at time zone v_tz)
    where a.bereiche is not null
    group by a.staff, a.tag
  ),
  -- Wunschzeiten als Zeitraeume je Tag; ohne Wunschzeiten der ganze Tag.
  -- Geschnitten wird VOR dem Packen, damit ein Vorschlag am Beginn des
  -- Wunschfensters beginnt und nicht an einem Raster, das die Luecke vorgibt.
  wunsch as (
    select t.tag,
           case when jsonb_array_length(v_fenster) = 0
                then app.timemultirange(app.timerange(time '00:00', time '24:00', '[)'))
                else (
                  select range_agg(app.timerange((w ->> 'from')::time, (w ->> 'to')::time, '[)'))
                  from jsonb_array_elements(v_fenster) w
                  where (w ->> 'weekday')::int = extract(isodow from t.tag)::int
                ) end as zeiten
    from tage t
  ),
  frei as (
    select a.staff, a.name, a.tag,
           unnest((a.bereiche - coalesce(b.zeiten, '{}'::app.timemultirange)) * w.zeiten) as r
    from arbeit a
    join wunsch w on w.tag = a.tag
    left join belegt b on b.staff = a.staff and b.tag = a.tag
    where a.bereiche is not null
      and w.zeiten is not null
  ),
  grenzen as (
    select f.staff, f.name, f.tag,
           (extract(epoch from lower(f.r)) / 60)::integer as von_min,
           (extract(epoch from upper(f.r)) / 60)::integer as bis_min
    from frei f
  ),
  kandidaten as (
    select g.staff, g.name, g.tag, k.beginn
    from grenzen g,
         generate_series(
           (ceil(greatest(
              g.von_min,
              case when g.tag = v_heute then v_jetzt + 1 else 0 end
            )::numeric / v_grid) * v_grid)::integer,
           g.bis_min - p_duration_minutes,
           p_duration_minutes
         ) as k(beginn)
  ),
  passend as (
    select k.*,
           make_time(k.beginn / 60, k.beginn % 60, 0) as zeit_von,
           make_time((k.beginn + p_duration_minutes) / 60 % 24, (k.beginn + p_duration_minutes) % 60, 0) as zeit_bis
    from kandidaten k
    where k.beginn + p_duration_minutes <= 24 * 60 - 1
  ),
  bewertet as (
    select p.*,
           case when p_appointment_type = 'home_visit'
                then app.territory_day_status(v_org, v_plz, p.tag, p.zeit_von)
                else 'none' end as gebiet,
           ((p.tag + p.zeit_von)::timestamp at time zone v_tz) as ab,
           ((p.tag + p.zeit_von)::timestamp at time zone v_tz) + make_interval(mins => p_duration_minutes) as bis
    from passend p
  ),
  auswahl as (
    select b.*
    from bewertet b
    order by (b.gebiet = 'match') desc, (b.gebiet = 'outside') asc, b.tag, b.beginn, b.name
    limit p_limit
  )
  select a.staff,
         a.name,
         a.tag,
         a.zeit_von,
         a.zeit_bis,
         a.gebiet,
         vor.id, vor.visit_lat, vor.visit_lon,
         nach.id, nach.visit_lat, nach.visit_lon,
         v_lat, v_lon
  from auswahl a
  left join lateral (
    select t.id, t.visit_lat, t.visit_lon
    from public.appointments t
    where t.organization_id = v_org
      and t.staff_member_id = a.staff
      and t.status <> 'cancelled'
      -- Zweitreview 1: nur Termine eines lesbaren Kontexts (ADR-022 Punkt 11).
      and app.may_read_appointment_context(t.kind)
      and t.ends_at <= a.ab
      and t.ends_at > (a.tag::timestamp at time zone v_tz)
    order by t.ends_at desc
    limit 1
  ) vor on p_appointment_type = 'home_visit'
  left join lateral (
    select t.id, t.visit_lat, t.visit_lon
    from public.appointments t
    where t.organization_id = v_org
      and t.staff_member_id = a.staff
      and t.status <> 'cancelled'
      and app.may_read_appointment_context(t.kind)
      and t.starts_at >= a.bis
      and t.starts_at < ((a.tag + 1)::timestamp at time zone v_tz)
    order by t.starts_at
    limit 1
  ) nach on p_appointment_type = 'home_visit'
  order by (a.gebiet = 'match') desc, (a.gebiet = 'outside') asc, a.tag, a.beginn, a.name;
end;
$$;

COMMENT ON FUNCTION public.find_free_slots(p_patient_id uuid, p_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_from date, p_to date, p_windows jsonb, p_limit integer) IS 'Terminsuche als Vorschlagsliste (PRX-003): freie Plaetze aus Arbeitszeit, Belegung der Therapeut:innen und der Patient:in, Raster, Dauer und Wunschzeiten; hoechstens 42 Tage und 50 Vorschlaege. Gebietstag zuerst (PRX-002). Beim Hausbesuch mit Nachbarterminen fuer die Fahrzeitpruefung (rate_slot_travel, ANN-136). Reserviert nichts.';

CREATE FUNCTION public.find_possible_duplicates(p_given_name text, p_family_name text, p_date_of_birth date DEFAULT NULL::date) RETURNS TABLE(id uuid, given_name text, family_name text, date_of_birth date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_vorname text;
  v_name    text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_patient_directory() then
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read patient directory');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read patient directory' using errcode = '42501';
  end if;

  v_vorname := app.suchform(btrim(coalesce(p_given_name, '')));
  v_name    := app.suchform(btrim(coalesce(p_family_name, '')));

  -- Ohne Nachnamen keine Aussage - und kein Orakel ueber den Bestand.
  if length(v_name) = 0 then
    return;
  end if;

  return query
    select p.id, pe.given_name, pe.family_name, pc.date_of_birth, p.status
    from public.patients p
    join public.persons pe on pe.id = p.person_id
    left join public.patient_contact_details pc on pc.patient_id = p.id
    where p.organization_id = v_org
      -- ANN-145: gleicher Nachname und (gleiches Geburtsdatum oder gleicher
      -- Vorname).
      and app.suchform(pe.family_name) = v_name
      and (
        (p_date_of_birth is not null and pc.date_of_birth = p_date_of_birth)
        or (length(v_vorname) > 0 and app.suchform(pe.given_name) = v_vorname)
      )
    order by (p.status = 'active') desc, pe.family_name, pe.given_name, p.id
    limit 5;
end;
$$;

COMMENT ON FUNCTION public.find_possible_duplicates(p_given_name text, p_family_name text, p_date_of_birth date) IS 'Moegliche Dubletten beim Anlegen (PRX-015, ANN-145): gleicher Nachname und gleiches Geburtsdatum oder gleicher Vorname, in der Suchform. Hoechstens fuenf, nur Name, Geburtsdatum und Status. Rollen wie die Kartei; ein abgewiesener Versuch wird als patient_directory.read protokolliert.';

CREATE FUNCTION public.find_possible_training_duplicates(p_given_name text, p_family_name text, p_date_of_birth date DEFAULT NULL::date) RETURNS TABLE(kind text, training_relationship_id uuid, person_id uuid, given_name text, family_name text, date_of_birth date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_vorname text;
  v_name    text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_training_relationships() then
    perform app.record_denied_read(auth.uid(), 'training_relationships.read', 'not allowed to read training clients');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training clients' using errcode = '42501';
  end if;

  v_vorname := app.suchform(btrim(coalesce(p_given_name, '')));
  v_name    := app.suchform(btrim(coalesce(p_family_name, '')));
  if length(v_name) = 0 then
    return;
  end if;

  return query
    -- Das Geburtsdatum nur, wenn es das eingegebene ist: Sonst gaebe der
    -- Hinweis Kontaktdaten ohne Protokoll heraus (ANN-175, Zweitreview).
    select 'training'::text, t.id, t.person_id, pe.given_name, pe.family_name,
           case when d.date_of_birth = p_date_of_birth then d.date_of_birth end
    from public.training_relationships t
    join public.persons pe on pe.id = t.person_id
    left join public.training_contact_details d on d.training_relationship_id = t.id
    where t.organization_id = v_org
      and app.suchform(pe.family_name) = v_name
      and (
        (p_date_of_birth is not null and d.date_of_birth = p_date_of_birth)
        or (length(v_vorname) > 0 and app.suchform(pe.given_name) = v_vorname)
      )
    order by pe.family_name, pe.given_name, t.id
    limit 5;

  if app.can_read_patient_directory() and app.can_write_training_relationships() then
    return query
      select 'patient'::text, null::uuid, p.person_id, pe.given_name, pe.family_name, pc.date_of_birth
      from public.patients p
      join public.persons pe on pe.id = p.person_id
      left join public.patient_contact_details pc on pc.patient_id = p.id
      where p.organization_id = v_org
        -- Wer schon trainiert, steht oben als 'training'.
        and not exists (select 1 from public.training_relationships x where x.person_id = p.person_id)
        and app.suchform(pe.family_name) = v_name
        and (
          (p_date_of_birth is not null and pc.date_of_birth = p_date_of_birth)
          or (length(v_vorname) > 0 and app.suchform(pe.given_name) = v_vorname)
        )
      order by pe.family_name, pe.given_name, p.id
      limit 5;
  end if;
end;
$$;

COMMENT ON FUNCTION public.find_possible_training_duplicates(p_given_name text, p_family_name text, p_date_of_birth date) IS 'TRN-002: moegliche Dubletten beim Anlegen einer Trainingskund:in (Regel ANN-145). Trainingstreffer fuer owner, trainer, office; Treffer aus der Kartei nur fuer owner und office (ANN-173). Nicht protokolliert wie die Trefferliste, abgewiesen als training_relationships.read.';

CREATE FUNCTION public.finish_notification_delivery(p_id uuid, p_claimed_at timestamp with time zone, p_outcome text, p_gone_endpoints text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  d public.notification_deliveries%rowtype;
begin
  if p_outcome is null or p_outcome not in ('sent', 'failed', 'gone') then
    raise exception 'invalid outcome' using errcode = '22023';
  end if;
  select * into d from public.notification_deliveries x where x.id = p_id for update;
  -- BEF-148: Nur wer den Anspruch von jetzt hält, meldet. Ein Lauf, der
  -- länger als 15 Minuten brauchte, trifft einen Auftrag, den ein zweiter
  -- Lauf schon wieder abgeholt hat - sein „gesendet" oder „gescheitert"
  -- überschriebe dessen Stand.
  if not found or d.state <> 'pending' or d.claimed_at is null
     or d.claimed_at is distinct from p_claimed_at then
    raise exception 'no claimed delivery' using errcode = 'P0002';
  end if;

  delete from public.platform_push_subscriptions p
   where p.access_id = d.access_id
     and p.endpoint = any (coalesce(p_gone_endpoints, '{}'::text[]));

  if p_outcome = 'sent' then
    update public.notification_deliveries x
       set state = 'sent', finished_at = now()
     where x.id = p_id;
  elsif p_outcome = 'gone' then
    update public.notification_deliveries x
       set state = 'dropped', drop_reason = 'no_device', finished_at = now()
     where x.id = p_id;
  elsif d.attempts >= app.notification_rule('max_attempts') then
    update public.notification_deliveries x
       set state = 'failed', finished_at = now()
     where x.id = p_id;
  else
    update public.notification_deliveries x
       set claimed_at = null,
           due_at = now() + make_interval(mins => 15 * d.attempts)
     where x.id = p_id;
  end if;
end;
$$;

COMMENT ON FUNCTION public.finish_notification_delivery(p_id uuid, p_claimed_at timestamp with time zone, p_outcome text, p_gone_endpoints text[]) IS 'KOM-009 (ADR-024 Punkt 16), BEF-148: der Versand meldet sent, failed oder gone - nur mit dem Anspruch, den er beim Abholen bekam. Abgewiesene Endpunkte fallen, Fehlschlaege werden hoechstens dreimal versucht. Nur service_role.';

CREATE FUNCTION public.finish_platform_exercise_session(p_access_id uuid, p_session_id uuid, p_note text, p_values jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_einheit public.exercise_plan_sessions%rowtype;
  v_notiz   text := nullif(btrim(coalesce(p_note, ''), E' \t\r\n'), '');
  v_keys    text[];
  v_werte   smallint[];
begin
  v_zugang := app.assert_platform_exercise(p_access_id);
  v_einheit := app.platform_open_exercise_session(p_access_id, p_session_id);
  if v_einheit.id is null then
    raise exception 'exercise session not found' using errcode = 'P0002';
  end if;
  if v_notiz is not null then
    if length(v_notiz) > 500 then
      raise exception 'note too long' using errcode = '22023';
    end if;
    if not app.platform_exercise_note_allowed(v_zugang.relationship_kind, v_zugang.relationship_id) then
      raise exception 'note requires consent' using errcode = '42501';
    end if;
  end if;

  -- TRK-001: Erst pruefen, dann schreiben - ein falscher Wert beendet nichts.
  select array_agg(w.parameter_key), array_agg(w.value)
    into v_keys, v_werte
  from app.tracking_values_from_json(p_values, 'session') w;
  if v_keys is not null
     and not app.platform_exercise_note_allowed(v_zugang.relationship_kind, v_zugang.relationship_id) then
    raise exception 'values require consent' using errcode = '42501';
  end if;

  update public.exercise_plan_sessions
     set finished_at = now(), difficulty_note = v_notiz, updated_at = now(),
         finished_access_id = v_zugang.id, finished_access_kind = v_zugang.access_kind,
         finished_by = auth.uid()
   where id = v_einheit.id;

  insert into public.exercise_plan_session_values (organization_id, session_id, parameter_key, value)
  select v_einheit.organization_id, v_einheit.id, w.key, w.value
  from unnest(v_keys, v_werte) as w (key, value);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'exercise_session')
  );
end;
$$;

COMMENT ON FUNCTION public.finish_platform_exercise_session(p_access_id uuid, p_session_id uuid, p_note text, p_values jsonb) IS 'UEB-010, TRK-001, TRK-004: beendet eine offene Einheit, wahlweise mit "Das war schwierig, weil ..." (hoechstens 500 Zeichen) und mit Angaben zur Einheit { session_exertion, session_pain, session_confidence: 0 bis 10 } (ANN-348, ANN-353); im Training beides nur mit Einwilligung (ANN-306). Ein ungueltiger Wert 22023, dann bleibt die Einheit offen. Danach aendert sich an der Einheit nichts mehr.';

CREATE FUNCTION public.finish_platform_onboarding(p_access_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  update public.platform_accesses a
     set onboarding_finished_at = now()
   where a.id = p_access_id
     and a.onboarding_finished_at is null;
  return found;
end;
$$;

COMMENT ON FUNCTION public.finish_platform_onboarding(p_access_id uuid) IS 'POR-019: die Person beendet den Einstieg (auch mit "spaeter"). Nachweis am Zugang; true nur beim ersten Mal.';

CREATE FUNCTION public.fleet_photo_for_verification(p_photo_id uuid, p_user_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text, byte_size bigint, checksum_sha256 text, already_verified boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.fleet_photo_bucket(), f.object_key, f.mime_type, f.byte_size, f.checksum_sha256,
         f.verified_at is not null
  from public.fleet_photos f
  where f.id = p_photo_id
    and f.created_by = p_user_id
    and f.created_at > now() - interval '24 hours'
    and (f.status = 'ready' or f.confirmation_requested_at is not null)
$$;

CREATE FUNCTION public.get_appointment_billing_context(p_appointment_id uuid) RETURNS TABLE(appointment_id uuid, treatment_basis_id uuid, treatment_basis_kind text, treatment_basis_issued_on date, basis_position integer, basis_appointment_count integer, billing_visible boolean, recipient_kind text, open_invoice_count integer, open_outstanding_cents integer, open_overdue boolean, closing_talk_due boolean, checked_at timestamp with time zone, basis_performed integer, basis_open integer, basis_complete boolean, basis_ready boolean, basis_released_at timestamp with time zone, basis_invoiced boolean, basis_state text, can_release boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_patient uuid;
  v_kind    text;
  v_basis   uuid;
  v_haken   timestamptz;
  v_darf    boolean;
  v_heute   date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  select a.patient_id, a.kind, a.treatment_basis_id, a.completed_at
    into v_patient, v_kind, v_basis, v_haken
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- Zweitreview: ein nicht lesbarer Bereich wie ein unbekannter Termin.
    and app.may_read_appointment_context(a.kind);

  if not found then
    return;
  end if;

  -- Die Abrechnungslage gibt es am Behandlungstermin. Training rechnet ueber
  -- ein eigenes Verhaeltnis ab (ADR-021), eine Fehlzeit gar nicht.
  if v_kind <> 'therapy' or v_patient is null then
    raise exception 'a billing context exists only for treatment appointments'
      using errcode = '22023';
  end if;

  -- ANN-139: Zahlungsinformationen nur fuer die Rollen der Abrechnung.
  v_darf := app.can_read_invoicing();
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;

  return query
    select
      p_appointment_id,
      b.id,
      b.treatment_basis_kind,
      b.issued_on,
      app.appointment_basis_position(p_appointment_id),
      b.appointment_count,
      v_darf,
      case when v_darf then coalesce((
        select r.recipient_kind
        from public.invoice_recipients r
        where r.patient_id = v_patient
          and r.organization_id = v_org
          and r.is_default
      ), 'self') end,
      case when v_darf then offen.anzahl end,
      case when v_darf then offen.betrag end,
      case when v_darf then offen.ueberfaellig end,
      -- KND-001: Abschlussgespraech in den letzten Terminen (ANN-286).
      app.closing_talk_due(p_appointment_id),
      -- B4/B7: der Haken des Termins und der Stand seiner Grundlage.
      v_haken,
      stand.performed,
      stand.open_count,
      stand.complete,
      stand.ready,
      stand.released_at,
      stand.invoiced,
      stand.state,
      (b.id is not null and app.can_release_treatment_basis() and coalesce(stand.ready, false))
    from (select 1) eins
    left join public.treatment_bases b on b.id = v_basis and b.organization_id = v_org
    left join lateral app.treatment_basis_billing(b.id) stand on b.id is not null
    left join lateral (
      select count(*)::integer as anzahl,
             coalesce(sum(o.outstanding_cents), 0)::integer as betrag,
             coalesce(bool_or(o.due_on < v_heute), false) as ueberfaellig
      from app.open_invoices(v_org) o
      where o.patient_id = v_patient
    ) offen on v_darf;
end;
$$;

COMMENT ON FUNCTION public.get_appointment_billing_context(p_appointment_id uuid) IS 'PRX-008: Verordnungszaehler und Abrechnungslage am Termin. Position fuer alle Rollen der Terminverwaltung, Empfaenger und offene Rechnungen nur fuer owner und office (ANN-139). Seit KND-001 dazu closing_talk_due (ANN-286). Seit B4/B7 der Haken des Termins und der Stand der Grundlage fuer den Vorschlag „In die Abrechnung stellen“ (ANN-514).';

CREATE FUNCTION public.get_appointment_brief(p_appointment_id uuid) RETURNS TABLE(appointment_id uuid, patient_id uuid, home_visit_access_note text, special_note text, take_along_items text[], primary_therapist_name text, treatment_basis_id uuid, treatment_basis_kind text, treatment_basis_issued_on date, basis_appointment_count integer, basis_used integer, basis_planned integer, basis_items jsonb, last_note_id uuid, last_note_appointment_start timestamp with time zone, last_note_status text, last_note_content text, last_note_visit_without_treatment boolean, last_note_author_name text, organization_time_zone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_kind    text;
  v_start   timestamptz;
  v_basis   uuid;
  v_note    uuid;
  v_prescribed integer;
  v_used       integer;
  v_planned    integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS; die Rollen prueft die Funktion selbst
  -- (ADR-004). Beide Rechte, weil der Blick Termin und Eintrag zeigt.
  if not (app.can_read_appointments() and app.can_read_treatment_note()) then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'appointment_brief.viewed', 'not allowed to read appointment brief');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointment brief' using errcode = '42501';
  end if;

  select a.patient_id, a.kind, a.starts_at, a.treatment_basis_id
    into v_patient, v_kind, v_start, v_basis
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- Zweitreview: Ein Termin aus einem Bereich, den die Rolle nicht sieht
    -- (ADR-022 Punkt 11), ist von einem unbekannten nicht zu unterscheiden.
    and app.may_read_appointment_context(a.kind);

  -- Ein fremder Termin ist von einem unbekannten nicht zu unterscheiden.
  if not found then
    return;
  end if;

  if v_kind <> 'therapy' or v_patient is null then
    raise exception 'an appointment brief exists only for treatment appointments'
      using errcode = '22023';
  end if;

  -- Der letzte Haupteintrag vor diesem Termin, aus einem Behandlungstermin
  -- derselben Person. Nachtraege stehen in der Akte, nicht im Kurzblick.
  -- Geordnet wie ueberall nach Beginn und Kennung.
  select t.id into v_note
  from public.treatment_notes t
  join public.appointments frueher on frueher.id = t.appointment_id
  where frueher.patient_id = v_patient
    and frueher.organization_id = v_org
    and frueher.kind = 'therapy'
    and frueher.id <> p_appointment_id
    and (frueher.starts_at, frueher.id) < (v_start, p_appointment_id)
    and t.addendum_to_note_id is null
  order by frueher.starts_at desc, frueher.id desc
  limit 1;

  if v_basis is not null then
    select z.prescribed, z.used, z.planned
      into v_prescribed, v_used, v_planned
    from app.treatment_basis_slot_counts(v_basis, v_org) z;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', v_patient);


  return query
    select
      p_appointment_id,
      v_patient,
      cd.home_visit_access_note,
      cd.special_note,
      coalesce(cd.take_along_items, '{}'::text[]),
      case when tp.id is null then null else tp.given_name || ' ' || tp.family_name end,
      b.id,
      b.treatment_basis_kind,
      b.issued_on,
      v_prescribed,
      v_used,
      v_planned,
      case when b.id is null then null else coalesce((
        select jsonb_agg(
                 jsonb_build_object(
                   'remedy', i.remedy,
                   'prescribed_quantity', i.prescribed_quantity,
                   'used_quantity', i.used_quantity
                 )
                 order by i.sort_order, i.id
               )
        from public.treatment_base_items i
        where i.treatment_basis_id = b.id
      ), '[]'::jsonb) end,
      t.id,
      frueher.starts_at,
      t.status,
      t.content,
      t.visit_without_treatment,
      verfasser.display_name,
      o.time_zone
    from public.organizations o
    left join public.patient_care_details cd on cd.patient_id = v_patient
    left join public.staff_members tsm       on tsm.id = cd.primary_therapist_staff_member_id
    left join public.persons tp              on tp.id = tsm.person_id
    left join public.treatment_bases b       on b.id = v_basis and b.organization_id = v_org
    left join public.treatment_notes t       on t.id = v_note
    left join public.appointments frueher    on frueher.id = t.appointment_id
    left join public.user_profiles verfasser on verfasser.id = t.created_by
    where o.id = v_org;
end;
$$;

COMMENT ON FUNCTION public.get_appointment_brief(p_appointment_id uuid) IS 'PRX-006: Vertretungs-Kurzblick am Behandlungstermin - Zugangshinweis, Besonderheit, feste Therapeut:in, Mitnehmen (PRX-007), Stand der Grundlage und der letzte Haupteintrag vor diesem Termin im Wortlaut (ADR-006: auswaehlen, nicht deuten). Rollen: Termine und Dokumentation lesen. Protokolliert appointment_brief.viewed und fuer den gezeigten Eintrag treatment_note.viewed (ANN-137); abgewiesen mit denied-Eintrag (G6b).';

CREATE FUNCTION public.get_appointment_services(p_appointment_id uuid) RETURNS TABLE(appointment_id uuid, can_record boolean, services jsonb, recorded_at timestamp with time zone, recorded_by_name text, basis_items jsonb, session_fee_cents integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_basis uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not (app.can_read_billable_services()
          or app.can_record_services_for_appointment(p_appointment_id)) then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'billable_services.read', 'not allowed to read billable services');
    return;
  end if;

  v_org := app.current_organization_id();

  select a.treatment_basis_id into v_basis
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org;

  if not found then
    return;
  end if;

  return query
    select
      p_appointment_id,
      app.can_record_services_for_appointment(p_appointment_id),
      coalesce((
        select jsonb_agg(
                 jsonb_build_object(
                   'code', i.code,
                   'label', i.label,
                   'quantity', s.quantity,
                   'status', s.status
                 )
                 order by i.sort_order, i.id
               )
        from public.billable_services s
        join public.service_catalog_items i on i.id = s.catalog_item_id
        where s.appointment_id = p_appointment_id
      ), '[]'::jsonb),
      (select min(s.created_at) from public.billable_services s
        where s.appointment_id = p_appointment_id),
      (select up.display_name
         from public.billable_services s
         join public.user_profiles up on up.id = s.created_by
        where s.appointment_id = p_appointment_id
        order by s.created_at
        limit 1),
      case when v_basis is null then null else coalesce((
        select jsonb_agg(
                 jsonb_build_object(
                   'remedy', p.remedy,
                   'prescribed_quantity', p.prescribed_quantity,
                   'used_quantity', p.used_quantity
                 )
                 order by p.sort_order, p.id
               )
        from public.treatment_base_items p
        where p.treatment_basis_id = v_basis
      ), '[]'::jsonb) end,
      -- ABR-031: Das Honorar sehen nur die Rollen der Abrechnung; wer am
      -- eigenen Termin Heilmittel bestaetigt, braucht den Preis nicht
      -- (Datenminimierung).
      case when app.can_read_billable_services() then (
        select f.amount_cents from public.appointment_session_fees f
        where f.appointment_id = p_appointment_id
      ) end;
end;
$$;

COMMENT ON FUNCTION public.get_appointment_services(p_appointment_id uuid) IS 'Erfasste Heilmittel eines Termins ohne Preise, die Mengen der Grundlage und seit ABR-031 fuer owner und office das festgeschriebene Terminhonorar (PRX-009, ANN-140, ANN-232).';

CREATE FUNCTION public.get_billable_service_draft(p_appointment_id uuid) RETURNS TABLE(catalog_item_id uuid, code text, label text, item_kind text, unit_price_cents integer, currency text, tax_treatment text, tax_rate_permille smallint, service_area text, suggested boolean, in_session_fee boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org          uuid;
  v_status       text;
  v_fee_basis    text;
  v_basis        uuid;
  v_kind         text;
  v_occasion     text;
  v_bereich      text;
  v_performed_on date;
  v_version      uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- PRX-009 (ANN-140): owner und office an jedem Termin, Behandelnde an
  -- ihrem eigenen. Die Pruefung braucht den Termin und steht deshalb in
  -- app.can_record_services_for_appointment.
  if not app.can_record_services_for_appointment(p_appointment_id) then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'billable_services.read', 'not allowed to record billable services');
    return;
  end if;

  v_org := app.current_organization_id();

  -- ABN-006: Ein Verzicht nimmt dem Anlass die Abrechenbarkeit, nicht den Anlass.
  select a.status, app.billable_fee_basis(a.fee_basis, a.fee_waived_at), a.treatment_basis_id, a.kind, a.occasion
    into v_status, v_fee_basis, v_basis, v_kind, v_occasion
  from public.appointments a
  where a.id = p_appointment_id and a.organization_id = v_org;

  if not found then
    raise exception 'appointment not found' using errcode = '42501';
  end if;

  v_bereich := app.service_area_of_appointment_kind(v_kind);
  if v_bereich is null then
    raise exception 'an appointment of kind % cannot carry billable services', v_kind
      using errcode = '22023';
  end if;

  v_performed_on := app.appointment_performed_on(p_appointment_id);
  v_version := app.active_service_catalog_version(v_org, v_performed_on);

  if v_version is null then
    raise exception 'no published service catalog for %', v_performed_on using errcode = '22023';
  end if;

  -- Die Reihenfolge der Preisliste bleibt die Reihenfolge des Vorschlags.
  return query
  select i.id, i.code, i.label, i.item_kind, i.unit_price_cents, i.currency,
         i.tax_treatment, i.tax_rate_permille, i.service_area,
         case
           when v_fee_basis is not null then i.item_kind = 'absence_fee'
           -- ERN-011: Die Position der Beratung ist der Vorschlag.
           when v_occasion = 'nutrition_counselling' then true
           else i.remedy is not null
                and exists (
                  select 1 from public.treatment_base_items p
                  where p.treatment_basis_id = v_basis and p.remedy = i.remedy
                )
         end as suggested,
         -- ABR-031: Ein Heilmittel an einem Behandlungstermin geht im
         -- Terminhonorar auf; sein Preis ist dann nur noch Gewicht (ANN-233).
         (v_fee_basis is null and v_kind = 'therapy' and i.remedy is not null) as in_session_fee
  from public.service_catalog_items i
  where i.catalog_version_id = v_version
    and i.item_kind = case when v_fee_basis is not null then 'absence_fee'
                           when v_occasion = 'nutrition_counselling' then 'nutrition_counselling'
                           else 'treatment' end
    and i.service_area = v_bereich
  order by i.sort_order;
end;
$$;

COMMENT ON FUNCTION public.get_billable_service_draft(p_appointment_id uuid) IS 'Vorschlag der Leistungserfassung je Termin aus der am Leistungstag gueltigen Preisliste (ABR-002, PRX-009). Seit ABR-031 mit in_session_fee: Heilmittel an einem Behandlungstermin gehen im Terminhonorar auf.';

CREATE FUNCTION public.get_checkins(p_kind text, p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor     uuid := auth.uid();
  v_org       uuid;
  v_area      text;
  v_takt      public.checkin_schedules%rowtype;
  v_offen     boolean;
  v_events    jsonb := '[]'::jsonb;
  v_consent   boolean;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Erst die Rolle, dann die Eingabe (ADR-023 Punkt 21).
  if not (app.can_read_exercise_plans('therapy') or app.can_read_exercise_plans('training')) then
    perform app.record_denied_read(v_actor, 'checkins.read', 'not allowed to read checkins');
    return null;
  end if;
  v_org := app.current_organization_id();
  select r.area, r.is_open into v_area, v_offen
  from app.checkin_relationship(p_kind, p_relationship_id, v_org) r;
  if v_area is null then
    return null;
  end if;
  -- Kein Durchgriff zwischen den Bereichen (ADR-021 Punkt 6).
  if not app.can_read_exercise_plans(v_area) then
    perform app.record_denied_read(v_actor, 'checkins.read', 'not allowed to read checkins');
    return null;
  end if;

  if p_kind = 'treatment' then
    perform app.log_record_access(
      v_org, v_actor, 'patient_record.viewed', 'patient', p_relationship_id,
      'user', jsonb_build_object('surface', 'web', 'view', 'checkins'));
    -- OUT-001: die vermerkten Ereignisse der Akte, wer sie im Befund lesen
    -- darf; das Lesen steht schon als Oeffnen der Akte im Protokoll.
    if app.can_read_treatment_note() then
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', e.id, 'occurred_on', e.occurred_on, 'kind', e.kind, 'note', e.note,
               'created_at', e.created_at, 'author_name', up.display_name
             ) order by e.occurred_on, e.created_at), '[]'::jsonb)
        into v_events
      from public.patient_course_events e
      left join public.user_profiles up on up.id = e.created_by
      where e.patient_id = p_relationship_id and e.organization_id = v_org
        and e.removed_at is null;
    end if;
  else
    perform app.log_record_access(
      v_org, v_actor, 'training_relationship.viewed', 'training_relationship', p_relationship_id,
      'user', jsonb_build_object('surface', 'web', 'view', 'checkins'));
    v_consent := app.training_health_consent(p_relationship_id);
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', e.id, 'occurred_on', e.occurred_on, 'kind', e.kind, 'note', e.note,
             'created_at', e.created_at, 'author_name', up.display_name
           ) order by e.occurred_on, e.created_at), '[]'::jsonb)
      into v_events
    from public.training_course_events e
    left join public.user_profiles up on up.id = e.created_by
    where e.training_relationship_id = p_relationship_id and e.organization_id = v_org
      and e.removed_at is null;
  end if;

  select * into v_takt
  from public.checkin_schedules s
  where s.relationship_kind = p_kind and s.relationship_id = p_relationship_id;

  return jsonb_build_object(
    'today', app.training_today(v_org),
    'can_write', app.can_write_exercise_plans(v_area),
    -- Nach Abschluss bzw. Vertragsende antwortet niemand mehr (Lesefrist);
    -- dann gibt es keinen faelligen Tag (Zweitreview S5, ANN-350).
    'relationship_open', v_offen,
    'schedule', case when v_takt.id is null then null else jsonb_build_object(
      'interval_days', v_takt.interval_days,
      'parameter_keys', to_jsonb(v_takt.parameter_keys),
      'starts_on', v_takt.starts_on,
      'due_on', case when v_offen then app.checkin_due_on(v_takt) end,
      'updated_at', v_takt.updated_at,
      'updated_by_name', (select up.display_name from public.user_profiles up
                          where up.id = v_takt.updated_by)
    ) end,
    'checkins', app.checkins_json(p_kind, p_relationship_id),
    -- TRK-006: Uhrzeiten in der Zeitzone der Praxis (IDEA-TRK-006).
    'time_zone', (select o.time_zone from public.organizations o where o.id = v_org),
    -- TRK-006: die Angaben nach den Einheiten aller Plaene des Verhaeltnisses,
    -- dieselben Rollen wie die Plaene (ANN-351, ANN-356).
    'sessions', app.checkin_sessions_json(p_kind, p_relationship_id),
    -- OUT-001: was neben den Werten steht (IDEA-OUT-005, ANN-364).
    'events', v_events,
    'plan_events', app.progress_plan_events_json(p_kind, p_relationship_id, v_org),
    'appointment_days', app.progress_appointment_days_json(p_kind, p_relationship_id, v_org),
    -- Im Training vermerkt die Betreuung hier; in der Behandlung im Befund.
    'events_writable', p_kind = 'training' and v_offen and coalesce(v_consent, false)
                       and app.can_write_exercise_plans(v_area),
    'health_consent', v_consent,
    -- ALT-003: Gewohnheiten mit vermerkten Tagen (IDEA-ALT-002, ANN-370).
    'habits', app.habits_json(p_kind, p_relationship_id),
    'habits_max', app.habits_max_running(),
    'habits_writable', v_offen and app.can_write_exercise_plans(v_area)
                       and (p_kind = 'treatment' or coalesce(v_consent, false))
  );
end;
$$;

COMMENT ON FUNCTION public.get_checkins(p_kind text, p_relationship_id uuid) IS 'TRK-002, TRK-006, OUT-001, ALT-003: Abschnitt "Zwischen den Terminen" (DSN-001 Abschnitt 6) - Takt, naechster Tag, die Check-ins mit ihren Angaben und die Angaben nach den Einheiten, unveraendert und ohne Bewertung (ADR-006 Punkt 11), mit der Zeitzone der Praxis; dazu die Ereignisse, Planwechsel und Tage durchgefuehrter Termine fuer das Verlaufsbild (IDEA-OUT-005) und die Gewohnheiten mit ihren Tagen (IDEA-ALT-002, ANN-370). Lesen wie die Uebungsplaene (ANN-351), protokolliert wie das Oeffnen von Akte bzw. Trainingsverhaeltnis. Ohne Recht null und eine Abweisung im Protokoll.';

CREATE FUNCTION public.get_exercise_plan(p_plan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_plan  public.exercise_plans%rowtype;
  v_person record;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not (app.can_read_exercise_plans('therapy') or app.can_read_exercise_plans('training')) then
    perform app.record_denied_read(v_actor, 'exercise_plans.read', 'not allowed to read exercise plans');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read exercise plans' using errcode = '42501';
  end if;

  select * into v_plan
  from public.exercise_plans p
  where p.id = p_plan_id and p.organization_id = v_org;
  if not found or not app.can_read_exercise_plans(v_plan.service_area) then
    return null;
  end if;

  perform app.exercise_plan_log_read(v_plan);

  if v_plan.service_area = 'therapy' then
    select pe.given_name, pe.family_name into v_person
    from public.patients pa join public.persons pe on pe.id = pa.person_id
    where pa.id = v_plan.patient_id;
  else
    select pe.given_name, pe.family_name into v_person
    from public.training_relationships t join public.persons pe on pe.id = t.person_id
    where t.id = v_plan.training_relationship_id;
  end if;

  return jsonb_build_object(
    'id', v_plan.id,
    'service_area', v_plan.service_area,
    'relationship_id', coalesce(v_plan.patient_id, v_plan.training_relationship_id),
    'given_name', v_person.given_name,
    'family_name', v_person.family_name,
    'title', v_plan.title,
    'sessions_per_week', v_plan.sessions_per_week,
    'status', v_plan.status,
    'previous_plan_id', v_plan.previous_plan_id,
    'follow_up', (
      select jsonb_build_object('id', f.id, 'status', f.status, 'runs_from', f.runs_from)
      from public.exercise_plans f where f.previous_plan_id = v_plan.id
    ),
    -- O-002: die Stelle in der Kette der Fassungen, 1 = erste. Die Kette
    -- bleibt in der Organisation (Fremdschluessel mit organization_id).
    'version_number', (
      with recursive kette (previous_plan_id, nummer) as (
        select q.previous_plan_id, 1
        from public.exercise_plans q
        where q.id = v_plan.id
        union all
        select q.previous_plan_id, k.nummer + 1
        from kette k
        join public.exercise_plans q on q.id = k.previous_plan_id
        where k.nummer < 1000
      )
      select max(k.nummer) from kette k
    ),
    'assigned_at', v_plan.assigned_at,
    'assigned_by_name', (select up.display_name from public.user_profiles up where up.id = v_plan.assigned_by),
    'runs_from', v_plan.runs_from,
    'runs_until', v_plan.runs_until,
    'original_runs_until', v_plan.original_runs_until,
    'extended_at', v_plan.extended_at,
    'ended_at', v_plan.ended_at,
    'ended_on', (select (v_plan.ended_at at time zone o.time_zone)::date
                 from public.organizations o where o.id = v_org),
    'ended_by_name', (select up.display_name from public.user_profiles up where up.id = v_plan.ended_by),
    'created_at', v_plan.created_at,
    'created_by_name', (select up.display_name from public.user_profiles up where up.id = v_plan.created_by),
    -- O-002: zuletzt geaendert - im Entwurf der Stand der Arbeit.
    'updated_on', (select (v_plan.updated_at at time zone o.time_zone)::date
                   from public.organizations o where o.id = v_org),
    'updated_by_name', (select up.display_name from public.user_profiles up where up.id = v_plan.updated_by),
    'today', app.training_today(v_org),
    'can_write', app.can_write_exercise_plans(v_plan.service_area),
    'review_due', app.exercise_plan_review_due(v_plan),
    'relationship_open', not exists (
      select 1 from public.training_relationships t
      where t.id = v_plan.training_relationship_id and t.contract_ended_on is not null
    ),
    'previous', (
      select jsonb_build_object(
        'id', q.id, 'title', q.title, 'sessions_per_week', q.sessions_per_week,
        'runs_from', q.runs_from, 'runs_until', q.runs_until,
        'items', coalesce((
          select jsonb_agg(app.exercise_plan_item_json(qi) order by qi.position)
          from public.exercise_plan_items qi where qi.plan_id = q.id
        ), '[]'::jsonb)
      )
      from public.exercise_plans q where q.id = v_plan.previous_plan_id
    ),
    'items', coalesce((
      select jsonb_agg(app.exercise_plan_item_json(i) order by i.position)
      from public.exercise_plan_items i where i.plan_id = v_plan.id
    ), '[]'::jsonb),
    -- UEB-010: was die Person an diesem Plan durchgefuehrt hat.
    'sessions', app.exercise_plan_sessions_json(v_plan.id)
  );
end;
$$;

COMMENT ON FUNCTION public.get_exercise_plan(p_plan_id uuid) IS 'UEB-004, O-002: ein Plan mit Positionen und der vorigen Fassung - im Entwurf mit den Bezeichnungen der Bibliothek, nach der Zuweisung mit dem Schnappschuss; dazu die Fassungsnummer aus der Kette und wer zuletzt geaendert hat. Lesen nach app.can_read_exercise_plans(Bereich), protokolliert als Akte geoeffnet (einmal je Tag); andere Rollen: null und access.denied.';

CREATE FUNCTION public.get_fleet_bike(p_bike_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_bike public.fleet_bikes%rowtype;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to read the fleet');

  select b.* into v_bike
  from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null;
  if v_bike.id is null then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'bike', app.fleet_bike_json(v_bike),
    'spots', coalesce((
      select jsonb_agg(
        app.fleet_spot_json(x.stelle, x.nummer)
        order by x.offen desc,
                 x.nummer asc nulls last,
                 x.erledigt desc nulls last,
                 x.angelegt desc,
                 x.folge desc
      )
      from (
        select s as stelle,
               s.resolved_at is null as offen,
               s.created_at as angelegt,
               s.seq as folge,
               s.resolved_at as erledigt,
               case when s.resolved_at is null
                    then (row_number() over (partition by s.resolved_at is null
                                             order by s.created_at, s.seq))::integer
               end as nummer
        from public.fleet_spots s
        where s.bike_id = v_bike.id
      ) x
    ), '[]'::jsonb),
    'checkups', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', c.id,
          'checked_at', c.checked_at,
          'checked_by_name', app.fleet_account_name(c.checked_by),
          'items', c.items,
          'note', c.note
        )
        order by c.checked_at desc, c.id
      )
      from public.fleet_checkups c
      where c.bike_id = v_bike.id
    ), '[]'::jsonb),
    'breakdowns', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', d.id,
          'reported_at', d.reported_at,
          'reported_by_name', app.fleet_account_name(d.reported_by),
          'outcome', d.outcome,
          'blocks', app.fleet_outcome_blocks(d.outcome),
          'summary', d.summary,
          'remark', d.remark,
          'location_note', d.location_note,
          'transport', d.transport
        )
        order by d.reported_at desc, d.id
      )
      from public.fleet_breakdowns d
      where d.bike_id = v_bike.id
    ), '[]'::jsonb),
    'blocks', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', b.id,
          'breakdown_id', b.breakdown_id,
          'reason', b.reason,
          'blocked_at', b.blocked_at,
          'blocked_by_name', app.fleet_account_name(b.blocked_by),
          'released_at', b.released_at,
          'released_by_name', app.fleet_account_name(b.released_by)
        )
        order by b.blocked_at desc, b.id
      )
      from public.fleet_blocks b
      where b.bike_id = v_bike.id
    ), '[]'::jsonb),
    'keys', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'holder_name', app.fleet_staff_name(k.holder_staff_id),
          'taken_at', k.taken_at,
          'returned_at', k.returned_at
        )
        order by k.taken_at desc, k.id
      )
      from public.fleet_key_handovers k
      where k.bike_id = v_bike.id
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_fleet_bike(p_bike_id uuid) IS 'FLT-001: ein Rad mit seinen Stellen (offene nummeriert, Handoff Abschnitt 4) und dem Verlauf aus Check-Ups, Pannen, Sperren und Schluessel. Lesen nach app.can_read_fleet() (BEF-066).';

CREATE FUNCTION public.get_fleet_workshop_sheet(p_bike_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_bike public.fleet_bikes%rowtype;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to read the fleet');

  select b.* into v_bike
  from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null;
  if v_bike.id is null then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'name', v_bike.name,
    'bike_type', v_bike.bike_type,
    'blocked_since', (
      select b.blocked_at from public.fleet_blocks b
      where b.bike_id = v_bike.id and b.released_at is null
    ),
    'spots', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'number', s.nummer,
          'zone', s.zone,
          'point', case when s.point_x is null then null
                        else jsonb_build_array(s.point_x, s.point_y, s.point_z) end,
          'model_version', s.model_version,
          'severity', s.severity,
          'note', s.note,
          'source', case when s.checkup_id is not null then 'checkup' else 'breakdown' end,
          'source_at', coalesce(c.checked_at, d.reported_at)
        )
        order by s.nummer
      )
      from (
        select s.*, (row_number() over (order by s.created_at, s.seq))::integer as nummer
        from public.fleet_spots s
        where s.bike_id = v_bike.id and s.resolved_at is null
      ) s
      left join public.fleet_checkups c on c.id = s.checkup_id
      left join public.fleet_breakdowns d on d.id = s.breakdown_id
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_fleet_workshop_sheet(p_bike_id uuid) IS 'FLT-001 (Handoff Lastenrad 3D, Vorschlag 5): die Unterlage fuer die Werkstatt - Rad, Bauart, gesperrt seit, offene Stellen mit Nummer, Punkt, Einstufung, Notiz und Art und Tag des Ereignisses. Keine Namen, keine Termine, kein Pannenort. Lesen nach app.can_read_fleet().';

CREATE FUNCTION public.get_intake_checklist(p_patient_id uuid) RETURNS TABLE(item text, state text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_patient_directory() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read the intake checklist');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read the intake checklist' using errcode = '42501';
  end if;

  -- Eine fremde Person ist von einer unbekannten nicht zu unterscheiden.
  if not exists (
    select 1 from public.patients pa where pa.id = p_patient_id and pa.organization_id = v_org
  ) then
    return;
  end if;

  return query select c.item, c.state from app.intake_checklist(v_org, p_patient_id) c;
end;
$$;

COMMENT ON FUNCTION public.get_intake_checklist(p_patient_id uuid) IS 'Erstaufnahme-Checkliste einer Person (PRX-013): fuenf Punkte mit done, open oder not_needed. Die vier Praxisrollen; ein abgewiesener Versuch wird als patient_directory.read protokolliert. Nicht auditiert: Die Liste nennt, ob etwas vorliegt, nicht seinen Inhalt (ANN-143).';

CREATE FUNCTION public.get_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_invoice  record;
  v_zeitzone text;
  v_heute    date;
  v_bezahlt  integer;
  v_storno   record;
  v_ersetzt  text;
  v_korrektur record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return null;
  end if;

  v_org := app.current_organization_id();

  select i.* into v_invoice
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  -- Am Entwurf gibt es keinen Zahlungsstand: An ihm kann niemand zahlen.
  v_bezahlt := case when v_invoice.status = 'issued'
                    then app.invoice_paid_cents(p_invoice_id) else 0 end;

  -- Die Kette aus ABR-003c, in beide Richtungen lesbar: das Stornodokument
  -- zu dieser Rechnung, die Rechnung, die sie ersetzt, und die Korrektur, die
  -- sie ersetzt hat.
  select c.cancellation_number, c.reason, c.cancelled_on into v_storno
  from public.invoice_cancellations c
  where c.invoice_id = p_invoice_id;

  select i.invoice_number into v_ersetzt
  from public.invoices i
  where i.id = v_invoice.replaces_invoice_id;

  select i.id, i.invoice_number into v_korrektur
  from public.invoices i
  where i.replaces_invoice_id = p_invoice_id
  order by i.created_at
  limit 1;

  -- Die ausgestellte Rechnung zeigt ihren Snapshot und nicht die heutigen
  -- Stammdaten: Genau dafuer gibt es ihn (ADR-009 Punkt 10).
  return jsonb_build_object(
    'id', v_invoice.id,
    'status', v_invoice.status,
    'patient_id', v_invoice.patient_id,
    'recipient_id', v_invoice.recipient_id,
    'invoice_number', v_invoice.invoice_number,
    'issued_on', v_invoice.issued_on,
    'due_on', v_invoice.due_on,
    'paid_cents', v_bezahlt,
    'outstanding_cents', coalesce(v_invoice.total_cents, 0) - v_bezahlt,
    'payment_state', case when v_invoice.status = 'issued'
                          then app.invoice_payment_state(v_invoice.total_cents, v_bezahlt)
                          else 'unpaid' end,
    'overdue', (v_invoice.status = 'issued' and v_invoice.due_on < v_heute
                and v_bezahlt < v_invoice.total_cents
                and v_storno is null),
    'cancellation', case when v_storno is null then null else
      jsonb_build_object('cancellation_number', v_storno.cancellation_number,
                         'reason', v_storno.reason,
                         'cancelled_on', v_storno.cancelled_on)
    end,
    'replaces_invoice_id', v_invoice.replaces_invoice_id,
    'replaces_invoice_number', v_ersetzt,
    'correction_invoice_id', v_korrektur.id,
    'correction_invoice_number', v_korrektur.invoice_number,
    -- BEF-143: Wartet die stornierte Rechnung auf ihre Korrektur? Nur, wenn
    -- noch keine besteht und die Korrektur eine Zeile haette. Fiel die
    -- einzige Leistung nach dem Storno weg, ist das Storno abgeschlossen
    -- (ADR-009 Punkt 9: "gegebenenfalls eine neue Rechnung").
    'correction_pending', (v_storno.cancellation_number is not null and v_korrektur.id is null
                           and exists (select 1 from app.correction_draft_services(p_invoice_id))),
    'document', coalesce(v_invoice.snapshot, app.build_invoice_document(p_invoice_id))
  );
end;
$$;

COMMENT ON FUNCTION public.get_invoice(p_invoice_id uuid) IS 'Eine Rechnung der Praxis mit Zahlungsstand, Storno- und Korrekturkette (ABR-003c) und ihrem Dokument - ausgestellt aus dem Snapshot (ADR-009 Punkt 10). correction_pending: Die stornierte Rechnung hat keine Korrektur, und die Korrektur haette eine Zeile (BEF-143). Nur fuer can_read_invoicing.';

CREATE FUNCTION public.get_message_response_workdays() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select o.message_response_workdays
  from public.organizations o
  where o.id = app.current_organization_id()
    and app.may_read_platform_messages('any')
$$;

COMMENT ON FUNCTION public.get_message_response_workdays() IS 'KOM-002 (ANN-309): die Antwortfrist der Praxis fuer die Rollen, die Nachrichten lesen.';

CREATE FUNCTION public.get_my_staff_feedback_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_staff  uuid;
  v_monat  date;
  v_kann   boolean;
begin
  v_org := app.staff_request_org(
    app.has_any_role('owner', 'team_lead', 'office', 'therapist', 'trainer'),
    'not allowed to read staff feedback status');
  v_monat := app.staff_feedback_month(v_org);
  v_kann := app.can_give_staff_feedback();
  if v_kann then
    select sm.id into v_staff
    from public.staff_members sm
    where sm.id = app.own_staff_member(v_org) and sm.employment_status = 'active';
    v_kann := v_staff is not null;
  end if;
  return jsonb_build_object(
    'can_take_part', v_kann,
    'can_read', app.can_read_staff_feedback(),
    'month', v_monat,
    'barometer_submitted', v_kann and exists (
      select 1 from public.staff_feedback_participations p
      where p.staff_member_id = v_staff and p.month = v_monat)
  );
end;
$$;

COMMENT ON FUNCTION public.get_my_staff_feedback_status() IS 'ORG-006 (ANN-607): der eigene Stand - nimmt die Person teil, liest sie, und hat sie das Barometer dieses Monats abgegeben. Nur über sich selbst.';

CREATE FUNCTION public.get_nutrition_diary(p_profile_id uuid, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid := auth.uid();
  v_org    uuid;
  v_profil public.nutrition_profiles%rowtype;
  v_heute  date;
  v_bis    date;
  v_von    date;
  v_ziele  jsonb;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Erst die Rolle, dann die Eingabe (ADR-023 Punkt 21).
  if not app.can_counsel_nutrition() then
    perform app.record_denied_read(v_actor, 'nutrition.read', 'not allowed to read nutrition diaries');
    return null;
  end if;
  v_org := app.current_organization_id();
  select * into v_profil from public.nutrition_profiles p
  where p.id = p_profile_id and p.organization_id = v_org;
  if v_profil.id is null then
    return null;
  end if;

  perform app.log_record_access(
    v_org, v_actor,
    case v_profil.relationship_kind when 'treatment' then 'patient_record.viewed'
                                    else 'training_relationship.viewed' end,
    case v_profil.relationship_kind when 'treatment' then 'patient' else 'training_relationship' end,
    v_profil.relationship_id, 'user', jsonb_build_object('surface', 'web', 'view', 'nutrition_diary'));

  v_heute := app.training_today(v_org);
  -- Sieben Tage bis p_to, nicht über das Ende der Beratung, nicht vor ihren Beginn.
  v_bis := least(coalesce(p_to, v_heute), coalesce(v_profil.ended_on, v_heute), v_heute);
  v_bis := greatest(v_bis, v_profil.started_on);
  v_von := greatest(v_bis - 6, v_profil.started_on);
  v_ziele := app.nutrition_profile_targets(v_profil.id);

  return jsonb_build_object(
    'today', v_heute,
    'started_on', v_profil.started_on,
    'from', v_von,
    'to', v_bis,
    'targets', case when v_ziele ->> 'status' = 'ok' then jsonb_build_object(
      'energy_kcal', v_ziele -> 'energy' -> 'kcal',
      'protein_g', v_ziele -> 'protein' -> 'g',
      'fat_g', v_ziele -> 'fat' -> 'g',
      'carbohydrate_g', v_ziele -> 'carbohydrate' -> 'g',
      'water_ml', v_ziele -> 'water' -> 'ml') end,
    -- Der jüngste Tag zuerst.
    'days', (
      select jsonb_agg(app.nutrition_diary_day_json(v_profil.id, d::date, true) order by d desc)
      from generate_series(v_von, v_bis, interval '1 day') d
    )
  );
end;
$$;

COMMENT ON FUNCTION public.get_nutrition_diary(p_profile_id uuid, p_to date) IS 'ERN-010 (ADR-027 Punkte 4 und 10): das Ernährungstagebuch eines Profils für die Beratung - sieben Tage bis p_to (ohne Angabe heute), je Tag Mahlzeiten mit Einträgen, wer eingetragen hat, Summen und Wasser, dazu die geltenden Zielwerte. Allein app.can_counsel_nutrition im eigenen Mandanten; protokolliert wie das Öffnen von Akte bzw. Trainingsverhältnis (view nutrition_diary). Ohne Recht null und eine Abweisung.';

CREATE FUNCTION public.get_nutrition_profile(p_kind text, p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid := auth.uid();
  v_org     uuid;
  v_rel     record;
  v_profil  uuid;
  v_frueher integer;
  v_anderes text;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_counsel_nutrition() then
    perform app.record_denied_read(v_actor, 'nutrition.read', 'not allowed to read nutrition profiles');
    return null;
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.nutrition_relationship(p_kind, p_relationship_id, v_org);
  if v_rel.person_id is null then
    return null;
  end if;

  perform app.log_record_access(
    v_org, v_actor,
    case p_kind when 'treatment' then 'patient_record.viewed' else 'training_relationship.viewed' end,
    case p_kind when 'treatment' then 'patient' else 'training_relationship' end,
    p_relationship_id, 'user', jsonb_build_object('surface', 'web', 'view', 'nutrition'));

  select p.id into v_profil
  from public.nutrition_profiles p
  where p.organization_id = v_org and p.relationship_kind = p_kind
    and p.relationship_id = p_relationship_id
  order by p.ended_on is null desc, p.started_on desc, p.created_at desc
  limit 1;

  select count(*) - 1 into v_frueher
  from public.nutrition_profiles p
  where p.organization_id = v_org and p.relationship_kind = p_kind
    and p.relationship_id = p_relationship_id;

  select p.relationship_kind into v_anderes
  from public.nutrition_profiles p
  left join public.patients pa on pa.id = p.patient_id
  left join public.training_relationships t on t.id = p.training_relationship_id
  where p.organization_id = v_org and p.ended_on is null
    and coalesce(pa.person_id, t.person_id) = v_rel.person_id
    and not (p.relationship_kind = p_kind and p.relationship_id = p_relationship_id)
  limit 1;

  return jsonb_build_object(
    'today', app.training_today(v_org),
    'relationship_open', v_rel.is_open,
    'birth_date_known', v_rel.date_of_birth is not null,
    'running_elsewhere', v_anderes,
    'earlier_count', greatest(coalesce(v_frueher, 0), 0),
    'profile', case when v_profil is null then null else app.nutrition_profile_base_json(v_profil) end
  );
end;
$$;

COMMENT ON FUNCTION public.get_nutrition_profile(p_kind text, p_relationship_id uuid) IS 'ERN-001 (ADR-027): das jüngste Ernährungsprofil eines Verhältnisses mit Einwilligung, Gewicht und Zielwerten samt Rechenweg; dazu, ob am anderen Verhältnis derselben Person eines läuft. Allein app.can_counsel_nutrition; protokolliert wie das Öffnen von Akte bzw. Trainingsverhältnis (view nutrition). Ohne Recht null und eine Abweisung.';

CREATE FUNCTION public.get_patient_aftercare(p_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    perform app.record_denied_read(auth.uid(), 'aftercare.read', 'not allowed to read aftercare subscriptions');
    return null;
  end if;
  v_org := app.current_organization_id();
  if not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    return null;
  end if;
  v_heute := app.training_today(v_org);

  return jsonb_build_object(
    'today', v_heute,
    'earliest_start', app.aftercare_earliest_start(p_patient_id),
    'subscriptions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', s.id,
               'starts_on', s.starts_on,
               'ends_on', s.ends_on,
               'created_at', s.created_at,
               'created_by_name', up.display_name,
               'cancelled_on', s.cancelled_on,
               'cancelled_via', s.cancelled_via,
               'cancelled_access_kind', s.cancelled_access_kind,
               'cancelled_representative_name', s.cancelled_representative_name,
               'current_month_end', case when s.ends_on is null then
                 case when v_heute < s.starts_on then s.starts_on - 1
                      else app.aftercare_month_end(s.starts_on, app.aftercare_month_index(s.starts_on, v_heute))
                 end
               end,
               -- ANG-002: erfasste Abo-Monate und der Preis des naechsten.
               'recorded_months', (
                 select count(*)::integer from public.billable_services b
                 where b.aftercare_subscription_id = s.id
               ),
               'next_month_price_cents', case when s.ends_on is null then (
                 select pr.unit_price_cents
                 from app.aftercare_month_price(v_org,
                   case when v_heute < s.starts_on then s.starts_on
                        else app.aftercare_month_start(s.starts_on, app.aftercare_month_index(s.starts_on, v_heute) + 1)
                   end) pr
               ) end,
               'next_month_start', case when s.ends_on is null then
                 case when v_heute < s.starts_on then s.starts_on
                      else app.aftercare_month_start(s.starts_on, app.aftercare_month_index(s.starts_on, v_heute) + 1)
                 end
               end
             ) order by s.starts_on desc)
      from public.aftercare_subscriptions s
      left join public.user_profiles up on up.id = s.created_by
      where s.patient_id = p_patient_id and s.organization_id = v_org
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_patient_aftercare(p_patient_id uuid) IS 'ANG-001: Nachsorge-Abos einer Akte mit fruehestem Beginn und Stand (owner, office). Andere Rollen: null und ein Eintrag der Abweisung.';

CREATE FUNCTION public.get_patient_session_fee(p_patient_id uuid) RETURNS TABLE(current_cents integer, current_source text, current_valid_from date, agreements jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_billable_services() then
    perform app.record_denied_read(auth.uid(), 'billable_services.read', 'not allowed to read fee agreements');
    return;
  end if;

  v_org := app.current_organization_id();

  if not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    return;
  end if;

  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;

  return query
  select h.amount_cents, h.source, h.valid_from,
         coalesce((
           select jsonb_agg(jsonb_build_object(
                    'id', f.id,
                    'valid_from', f.valid_from,
                    'session_fee_cents', f.session_fee_cents,
                    'created_at', f.created_at,
                    'created_by_name', up.display_name
                  ) order by f.valid_from desc)
           from public.patient_fee_agreements f
           left join public.user_profiles up on up.id = f.created_by
           where f.patient_id = p_patient_id
         ), '[]'::jsonb)
  from app.session_fee_on(p_patient_id, v_heute) h;
end;
$$;

COMMENT ON FUNCTION public.get_patient_session_fee(p_patient_id uuid) IS 'Das heute geltende Terminhonorar einer Person mit Herkunft (Vereinbarung oder Tarif) und ihre Honorarvereinbarungen (ABR-030). owner und office.';

CREATE FUNCTION public.get_patient_training_offers(p_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null or not app.can_update_patient() then
    return null;
  end if;
  if not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    return null;
  end if;
  v_heute := app.training_today(v_org);

  return jsonb_build_object(
    'today', v_heute,
    'care_concluded_on', (select p.care_concluded_on from public.patients p where p.id = p_patient_id),
    -- Ob die Person ein Konto hat, in dem sie annehmen kann: ein aktiver
    -- eigener Zugang zu dieser Akte (KND-003). Nur ja oder nein.
    'has_own_access', exists (
      select 1 from public.platform_accesses a
      where a.patient_id = p_patient_id and a.access_kind = 'self' and a.status = 'active'
    ),
    'offers', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', o.id,
               'state', app.training_offer_practice_state(o, v_heute),
               'label', c.label,
               'package_months', c.package_months,
               'price_cents', c.unit_price_cents,
               'currency', c.currency,
               'starts_on', o.starts_on,
               'valid_until', o.valid_until,
               'handover_items', o.handover_items,
               'offers_contact', o.offers_contact,
               'created_at', o.created_at,
               'created_by_name', up.display_name,
               'withdrawn_at', o.withdrawn_at
             ) order by o.created_at desc)
      from public.training_offers o
      join public.service_catalog_items c on c.id = o.catalog_item_id
      left join public.user_profiles up on up.id = o.created_by
      where o.patient_id = p_patient_id and o.organization_id = v_org
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_patient_training_offers(p_patient_id uuid) IS 'KND-002: Trainingsangebote einer Akte mit Stand, Paket und Uebergabeangaben, dazu ob die Person einen aktiven eigenen Plattformzugang hat (Rollen der Akte). Ob angenommen wurde, steht nicht da - nichts aus dem Training (ANN-285, 4.8). Andere: null.';

CREATE FUNCTION public.get_payment_reminder(p_reminder_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_reminder record;
  v_invoice  record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return null;
  end if;

  v_org := app.current_organization_id();

  select r.* into v_reminder
  from public.invoice_payment_reminders r
  where r.id = p_reminder_id and r.organization_id = v_org;

  if not found then
    raise exception 'payment reminder not found' using errcode = '42501';
  end if;

  select i.* into v_invoice
  from public.invoices i
  where i.id = v_reminder.invoice_id;

  return jsonb_build_object(
    'id', v_reminder.id,
    'invoice_id', v_reminder.invoice_id,
    'invoice_number', v_invoice.invoice_number,
    'issued_on', v_invoice.issued_on,
    'invoice_due_on', v_invoice.due_on,
    'reminder_on', v_reminder.reminder_on,
    'due_on', v_reminder.due_on,
    'outstanding_cents', v_reminder.outstanding_cents,
    'currency', v_reminder.currency,
    -- Der Snapshot der ausgestellten Rechnung: Absender, Empfaenger und
    -- Betrag, wie sie beim Ausstellen galten (ADR-009 Punkt 10).
    'document', v_invoice.snapshot
  );
end;
$$;

COMMENT ON FUNCTION public.get_payment_reminder(p_reminder_id uuid) IS 'Eine Zahlungserinnerung als Dokument, mit dem Snapshot ihrer Rechnung (ABR-003d, ADR-009 Punkt 10).';

CREATE FUNCTION public.get_platform_access(p_relationship_kind text, p_relationship_id uuid) RETURNS TABLE(id uuid, status text, created_at timestamp with time zone, activated_at timestamp with time zone, locked_at timestamp with time zone, revoked_at timestamp with time zone, revoked_reason text, invitation_id uuid, invitation_purpose text, invitation_channel text, invitation_expires_at timestamp with time zone, invitation_sent_at timestamp with time zone, relationship_email text, ended_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_platform_access(p_relationship_kind) then
    perform app.record_denied_read(v_actor, 'platform_accesses.read', 'not allowed to read platform access');
    return;
  end if;
  v_org := app.current_organization_id();

  if not exists (
    select 1 from app.platform_relationship(p_relationship_kind, p_relationship_id) r
    where r.organization_id = v_org
  ) then
    return;
  end if;

  return query
  select a.id, a.status, a.created_at, a.activated_at, a.locked_at, a.revoked_at, a.revoked_reason,
         i.id, i.purpose, i.channel, i.expires_at, i.sent_at,
         -- Die Adresse im Verhaeltnis, damit die Praxis sieht, wohin eine
         -- Mail ginge. Nur fuer die Rollen, die sie ohnehin lesen.
         (select r.email from app.platform_relationship(p_relationship_kind, p_relationship_id) r),
         app.platform_access_ended_at(a.id)
  from (select 1) as eins
  left join lateral (
    select x.*
    from public.platform_accesses x
    where x.organization_id = v_org
      and x.relationship_id = p_relationship_id
      and x.relationship_kind = p_relationship_kind
      and x.access_kind = 'self'
    order by (x.status = 'revoked'), x.created_at desc
    limit 1
  ) a on true
  left join public.platform_access_invitations i
    on i.platform_access_id = a.id and i.status = 'pending' and i.expires_at > now();
end;
$$;

COMMENT ON FUNCTION public.get_platform_access(p_relationship_kind text, p_relationship_id uuid) IS 'POR-002: Zustand des eigenen Plattformzugangs eines Verhaeltnisses fuer den Abschnitt "Plattform". Rollen, die das Verhaeltnis lesen; abgewiesen mit denied (platform_accesses.read). Ohne Code, ohne Konto.';

CREATE FUNCTION public.get_platform_message(p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_vorgang public.platform_messages%rowtype;
  v_name    record;
  v_zone    text;
begin
  if auth.uid() is null or not app.may_read_platform_messages('any') then
    raise exception 'not allowed to read platform messages' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  v_vorgang := app.practice_message(p_message_id, false);
  select o.time_zone into v_zone from public.organizations o where o.id = v_org;

  select pe.given_name, pe.family_name into v_name
  from public.persons pe
  where pe.id = coalesce(
    (select pa.person_id from public.patients pa where pa.id = v_vorgang.patient_id),
    (select t.person_id from public.training_relationships t
      where t.id = v_vorgang.training_relationship_id));

  if v_vorgang.relationship_kind = 'treatment' then
    perform app.log_record_access(v_org, auth.uid(), 'patient_record.viewed', 'patient',
                                  v_vorgang.patient_id);
  else
    perform app.log_record_access(v_org, auth.uid(), 'training_relationship.viewed',
                                  'training_relationship', v_vorgang.training_relationship_id);
  end if;

  return jsonb_build_object(
    'id', v_vorgang.id,
    'relationship_kind', v_vorgang.relationship_kind,
    'relationship_id', v_vorgang.relationship_id,
    'patient_id', v_vorgang.patient_id,
    'training_relationship_id', v_vorgang.training_relationship_id,
    'given_name', v_name.given_name,
    'family_name', v_name.family_name,
    'topic', v_vorgang.topic,
    'reference_label', v_vorgang.reference_label,
    'exercise_plan_id', v_vorgang.exercise_plan_id,
    'status', v_vorgang.status,
    'due_on', v_vorgang.due_on,
    'overdue', v_vorgang.status = 'open' and v_vorgang.due_on < app.training_today(v_org),
    'created_at', v_vorgang.created_at,
    'closed_at', v_vorgang.closed_at,
    'closed_by_side', v_vorgang.closed_by_side,
    'record_assigned_at', v_vorgang.record_assigned_at,
    'record_assigned_by_label', v_vorgang.record_assigned_by_label,
    'can_answer', app.can_answer_platform_message(v_vorgang.relationship_kind, v_vorgang.topic),
    'can_assign', app.can_assign_platform_message(v_vorgang.relationship_kind)
                  and v_vorgang.record_assigned_at is null,
    -- KOM-005 (ADR-017 Punkt 67): sehen, wer den Vorgang liest; loeschen,
    -- wer antworten darf. Ohne Objektschluessel (ANN-052).
    'attachments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', x.id,
        'media_kind', x.media_kind,
        'mime_type', x.mime_type,
        'duration_seconds', x.duration_seconds,
        'created_at', x.created_at,
        'delete_on', ((x.created_at + app.retention_interval('rueckfrageanhang'))
                        at time zone coalesce(v_zone, 'Europe/Berlin'))::date,
        'author_kind', x.author_kind,
        'author_label', x.author_label,
        'server_verified', x.verified_at is not null,
        'malware_scanned', app.message_attachment_scan_required(),
        'object_missing', not exists (
          select 1 from storage.objects o
          where o.bucket_id = app.message_attachment_bucket() and o.name = x.object_key)
      ) order by x.created_at, x.id)
      from public.platform_message_attachments x
      where x.message_id = v_vorgang.id
        and app.message_attachment_visible(x)
    ), '[]'::jsonb),
    'entries', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', e.id,
        'side', e.side,
        'body', e.body,
        'author_kind', e.author_kind,
        'author_label', e.author_label,
        'created_at', e.created_at,
        'attachment_id', e.attachment_id,
        'attachment_mark_seconds', e.attachment_mark_seconds
      ) order by e.created_at, e.id)
      from public.platform_message_entries e
      where e.message_id = v_vorgang.id
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_platform_message(p_message_id uuid) IS 'KOM-002: ein Vorgang der Plattform mit allen Eintraegen fuer die Praxis. Lesen nur, wer ihn lesen darf (ANN-310, ANN-311); protokolliert als "Akte geoeffnet" bzw. "Trainingsverhaeltnis geoeffnet", einmal je Tag (ADR-010 Fassung 3 Punkt 16).';

CREATE FUNCTION public.get_platform_onboarding(p_access_id uuid) RETURNS TABLE(finished_at timestamp with time zone, skipped_at timestamp with time zone, skipped_by_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a
  where a.id = p_access_id and a.organization_id = app.current_organization_id();
  if not found or not app.can_read_platform_access(v_zugang.relationship_kind) then
    return;
  end if;
  return query
  select v_zugang.onboarding_finished_at,
         v_zugang.onboarding_skipped_at,
         (select nullif(btrim(concat_ws(' ', pe.given_name, pe.family_name)), '')
            from public.user_profiles up
            join public.persons pe on pe.id = up.person_id
           where up.id = v_zugang.onboarding_skipped_by);
end;
$$;

COMMENT ON FUNCTION public.get_platform_onboarding(p_access_id uuid) IS 'POR-019: Stand des Einstiegs eines Zugangs fuer den Abschnitt Plattform - beendet, uebersprungen, von wem. Rollen, die den Zugang lesen; sonst keine Zeile.';

CREATE FUNCTION public.get_practice_sender() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.is_staff() then
    perform app.record_denied_read(auth.uid(), 'practice_sender.read',
                                   'not allowed to read the practice sender');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read the practice sender' using errcode = '42501';
  end if;

  -- ANN-123/ANN-323: nur, was auf ein Blatt an Patient:innen gehoert.
  return coalesce(
    (select jsonb_build_object(
       'name', pb.legal_name,
       'street', pb.street,
       'house_number', pb.house_number,
       'postal_code', pb.postal_code,
       'city', pb.city,
       'phone', pb.phone,
       'email', pb.email)
     from public.practice_billing_profiles pb
     where pb.organization_id = v_org),
    (select jsonb_build_object('name', o.name)
     from public.organizations o
     where o.id = v_org)
  );
end;
$$;

COMMENT ON FUNCTION public.get_practice_sender() IS 'UX-009a, ANN-323 (nach ANN-123): Absender fuer Blaetter an Patient:innen (Aufnahmeblatt, Terminzettel) - Name, Anschrift, Telefon, E-Mail aus practice_billing_profiles, ohne Steuer- und Bankangaben; ohne Stammdaten nur der Name der Organisation. Alle vier Praxisrollen; kein Auditeintrag beim Lesen, Abweisung als access.denied.';

CREATE FUNCTION public.get_practice_statistics(p_month date DEFAULT NULL::date) RETURNS TABLE(time_zone text, today date, month date, previous_month date, revenue_cents bigint, revenue_therapy_cents bigint, revenue_training_cents bigint, revenue_previous_cents bigint, payments_cents bigint, payments_previous_cents bigint, open_count integer, open_cents bigint, open_not_due_count integer, open_not_due_cents bigint, open_overdue_1_30_count integer, open_overdue_1_30_cents bigint, open_overdue_31_60_count integer, open_overdue_31_60_cents bigint, open_overdue_over_60_count integer, open_overdue_over_60_cents bigint, utilization_from date, utilization_to date, available_minutes integer, booked_minutes integer, ending_bases integer, uncovered_appointments integer, absences_from date, absences_to date, patient_cancellations integer, no_shows integer, absences_with_fee integer, absence_fee_cents bigint, absences_previous integer, absence_fee_previous_cents bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org        uuid;
  v_tz         text;
  v_heute      date;
  v_monat      date;
  v_vormonat   date;
  v_ausfall_ab date;
  v_vorher_ab  date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_practice_statistics() then
    perform app.record_denied_read(auth.uid(), 'statistics.read', 'not allowed to read practice statistics');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read practice statistics' using errcode = '42501';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_tz)::date;
  v_monat := date_trunc('month', coalesce(p_month, v_heute))::date;
  if v_monat < date '2020-01-01' or v_monat > date '2200-01-01' then
    raise exception 'month out of range' using errcode = '22023';
  end if;
  v_vormonat := (v_monat - interval '1 month')::date;
  -- Vier Wochen einschliesslich heute, davor dieselbe Laenge.
  v_ausfall_ab := v_heute - 27;
  v_vorher_ab  := v_heute - 55;

  return query
  with
  -- ---------------------------------------------------------------------------
  -- (1) Rechnungsstellung: Rechnung am Ausstellungstag, Storno am eigenen Tag
  -- ---------------------------------------------------------------------------
  rechnungsstellung as (
    select r.tag, r.bereich, r.betrag
    from app.revenue_documents(v_org, v_vormonat, (v_monat + interval '1 month')::date) r
  ),
  umsatz as (
    select coalesce(sum(r.betrag) filter (where r.tag >= v_monat), 0)::bigint as gesamt,
           coalesce(sum(r.betrag) filter (where r.tag >= v_monat and r.bereich = 'therapy'), 0)::bigint as behandlung,
           coalesce(sum(r.betrag) filter (where r.tag >= v_monat and r.bereich = 'training'), 0)::bigint as training,
           coalesce(sum(r.betrag) filter (where r.tag < v_monat), 0)::bigint as vormonat
    from rechnungsstellung r
  ),
  -- Zufluss: gebuchte Zahlungen, die Rueckzahlung zieht ab.
  zufluss as (
    select coalesce(sum(z.betrag) filter (where z.tag >= v_monat), 0)::bigint as monat,
           coalesce(sum(z.betrag) filter (where z.tag < v_monat), 0)::bigint as vormonat
    from app.payment_flows(v_org, v_vormonat, (v_monat + interval '1 month')::date) z
  ),
  -- ---------------------------------------------------------------------------
  -- (2) Offene Posten nach Tagen ueber der Faelligkeit
  -- ---------------------------------------------------------------------------
  offen as (
    select o.outstanding_cents::bigint as betrag,
           v_heute - o.due_on as tage
    from app.open_invoices(v_org) o
  ),
  posten as (
    select count(*)::integer as anzahl,
           coalesce(sum(o.betrag), 0)::bigint as summe,
           count(*) filter (where o.tage is null or o.tage <= 0)::integer as n0,
           coalesce(sum(o.betrag) filter (where o.tage is null or o.tage <= 0), 0)::bigint as s0,
           count(*) filter (where o.tage between 1 and 30)::integer as n1,
           coalesce(sum(o.betrag) filter (where o.tage between 1 and 30), 0)::bigint as s1,
           count(*) filter (where o.tage between 31 and 60)::integer as n2,
           coalesce(sum(o.betrag) filter (where o.tage between 31 and 60), 0)::bigint as s2,
           count(*) filter (where o.tage > 60)::integer as n3,
           coalesce(sum(o.betrag) filter (where o.tage > 60), 0)::bigint as s3
    from offen o
  ),
  -- ---------------------------------------------------------------------------
  -- (3) Auslastung: Arbeitszeit und gebuchte Zeit darin, je Person und Tag
  -- gerechnet und nur als Summe geliefert (ANN-152).
  -- ---------------------------------------------------------------------------
  tage as (
    select g::date as tag
    from generate_series(v_heute::timestamp, (v_heute + 13)::timestamp, interval '1 day') g
  ),
  arbeit as (
    select sm.id as staff, t.tag, app.working_ranges(sm.id, v_org, t.tag) as bereiche
    from public.staff_members sm
    cross join tage t
    where sm.organization_id = v_org
      and app.is_assignable_therapist(sm.id, v_org)
  ),
  gebucht as (
    select a.staff, a.tag,
           range_agg(app.timerange(
             greatest(t.starts_at at time zone v_tz, a.tag::timestamp)::time,
             case when t.ends_at at time zone v_tz >= (a.tag + 1)::timestamp
                  then time '24:00'
                  else (t.ends_at at time zone v_tz)::time end,
             '[)'
           )) as zeiten
    from arbeit a
    join public.appointments t
      on t.organization_id = v_org
     and t.staff_member_id = a.staff
     and t.status <> 'cancelled'
     and t.kind in ('therapy', 'training')
     and t.starts_at < ((a.tag + 1)::timestamp at time zone v_tz)
     and t.ends_at > (a.tag::timestamp at time zone v_tz)
    where a.bereiche is not null
    group by a.staff, a.tag
  ),
  auslastung as (
    select coalesce(sum((
             select sum(extract(epoch from (upper(r) - lower(r))) / 60)
             from unnest(a.bereiche) r
           )), 0)::integer as verfuegbar,
           coalesce(sum((
             select sum(extract(epoch from (upper(r) - lower(r))) / 60)
             from unnest(a.bereiche * g.zeiten) r
           )), 0)::integer as belegt
    from arbeit a
    left join gebucht g on g.staff = a.staff and g.tag = a.tag
    where a.bereiche is not null
  ),
  -- ---------------------------------------------------------------------------
  -- (4) Verordnungen ohne Anschluss und ungedeckte kommende Termine
  -- ---------------------------------------------------------------------------
  verordnungen as (
    select count(*)::integer as endend
    from app.ending_treatment_bases(v_org)
  ),
  ungedeckt as (
    select count(*)::integer as termine
    from public.appointments a
    -- Nur Verordnungen: Bei einem Selbstzahler gibt es niemanden anzufragen,
    -- und die Kennzahl gilt den Verordnungen (wie app.ending_treatment_bases).
    join public.treatment_bases tb
      on tb.id = a.treatment_basis_id
     and tb.treatment_basis_kind <> 'self_pay'
    where a.organization_id = v_org
      and a.status = 'confirmed'
      and a.starts_at >= now()
      and app.appointment_is_covered(a.id) is false
  ),
  -- ---------------------------------------------------------------------------
  -- (5) Ausfaelle nach dem Tag des Termins (ANN-153). Eine Absage bleibt
  -- `cancelled`, ein Nichtantreffen `no_show` - auch mit Gebuehr und Rechnung
  -- darueber (Constraints appointments_cancellation_fields, _no_show_fields).
  -- ---------------------------------------------------------------------------
  ausfall as (
    select a.id,
           (a.starts_at at time zone v_tz)::date as tag,
           (a.status = 'cancelled' and a.cancellation_reason in ('patient_request', 'patient_moved')) as absage,
           (a.status = 'no_show') as nicht_angetroffen,
           (app.billable_fee_basis(a.fee_basis, a.fee_waived_at) is not null) as mit_gebuehr
    from public.appointments a
    where a.organization_id = v_org
      and a.kind in ('therapy', 'training')
      and a.starts_at >= (v_vorher_ab::timestamp at time zone v_tz)
      and a.starts_at < ((v_heute + 1)::timestamp at time zone v_tz)
      and (
        (a.status = 'cancelled' and a.cancellation_reason in ('patient_request', 'patient_moved'))
        or a.status = 'no_show'
      )
  ),
  honorar as (
    select f.id,
           coalesce(sum(bs.quantity * ci.unit_price_cents), 0)::bigint as betrag
    from ausfall f
    join public.billable_services bs on bs.appointment_id = f.id
    join public.service_catalog_items ci on ci.id = bs.catalog_item_id and ci.item_kind = 'absence_fee'
    group by f.id
  ),
  ausfaelle as (
    select count(*) filter (where f.tag >= v_ausfall_ab and f.absage)::integer as absagen,
           count(*) filter (where f.tag >= v_ausfall_ab and f.nicht_angetroffen)::integer as nicht_angetroffen,
           count(*) filter (where f.tag >= v_ausfall_ab and f.mit_gebuehr)::integer as mit_gebuehr,
           coalesce(sum(h.betrag) filter (where f.tag >= v_ausfall_ab), 0)::bigint as honorar,
           count(*) filter (where f.tag < v_ausfall_ab)::integer as vorher,
           coalesce(sum(h.betrag) filter (where f.tag < v_ausfall_ab), 0)::bigint as honorar_vorher
    from ausfall f
    left join honorar h on h.id = f.id
  )
  select v_tz,
         v_heute,
         v_monat,
         v_vormonat,
         u.gesamt, u.behandlung, u.training, u.vormonat,
         z.monat, z.vormonat,
         p.anzahl, p.summe, p.n0, p.s0, p.n1, p.s1, p.n2, p.s2, p.n3, p.s3,
         v_heute, v_heute + 13, al.verfuegbar, al.belegt,
         v.endend, ug.termine,
         v_ausfall_ab, v_heute,
         af.absagen, af.nicht_angetroffen, af.mit_gebuehr, af.honorar,
         af.vorher, af.honorar_vorher
  from umsatz u, zufluss z, posten p, auslastung al, verordnungen v, ungedeckt ug, ausfaelle af;
end;
$$;

COMMENT ON FUNCTION public.get_practice_statistics(p_month date) IS 'STA-001: fuenf Kennzahlen der Praxisfuehrung in einer Zeile - Umsatz und Zahlungseingang des Monats gegen den Vormonat (getrennte Grundlagen), offene Posten nach Alter, Auslastung der naechsten vierzehn Tage, Verordnungen ohne Anschluss samt ungedeckter Termine, Ausfaelle der letzten vier Wochen gegen die vier davor. Nur Summen, keine Person. Allein owner; ein abgewiesener Aufruf liefert keine Zeile und wird als statistics.read protokolliert.';

CREATE FUNCTION public.get_practice_targets() RETURNS TABLE(revenue_cents integer, open_items_cents integer, utilization_percent smallint, ending_bases integer, absences integer, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_practice_statistics() then
    perform app.record_denied_read(auth.uid(), 'statistics.read', 'not allowed to read practice targets');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read practice targets' using errcode = '42501';
  end if;

  -- Immer genau eine Zeile: ohne gespeicherte Ziele eine leere.
  return query
  select t.revenue_cents, t.open_items_cents, t.utilization_percent,
         t.ending_bases, t.absences, t.updated_at
  from (select 1) eins
  left join public.practice_targets t on t.organization_id = v_org;
end;
$$;

COMMENT ON FUNCTION public.get_practice_targets() IS 'STA-002: die Zielwerte der Praxis in einer Zeile, leer ohne gespeicherte Ziele. Allein owner; ein abgewiesener Aufruf liefert keine Zeile und wird als statistics.read protokolliert.';

CREATE FUNCTION public.get_staff_feedback_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_von     date;
  v_bis     date;
  v_soll    integer;
  v_baro    jsonb := jsonb_build_object('status', 'too_few');
  v_nachr   jsonb := jsonb_build_object('status', 'too_few');
begin
  v_org := app.staff_request_org(app.can_read_staff_feedback(), 'not allowed to read staff feedback');
  if app.staff_feedback_eligible_count(v_org) < (app.staff_feedback_threshold()).o_eligible then
    return jsonb_build_object('barometer', v_baro, 'messages', v_nachr);
  end if;
  select o_von, o_bis, o_antworten into v_von, v_bis, v_soll
  from app.staff_feedback_window(v_org, 'barometer');
  if v_von is not null then
    select jsonb_build_object(
             'status', 'ready',
             'from_month', v_von,
             'to_month', v_bis,
             'answers', count(*),
             'mood', app.staff_feedback_scale(array_agg(f.mood) filter (where f.mood is not null)),
             'tours', app.staff_feedback_scale(array_agg(f.tours) filter (where f.tours is not null)),
             'team', app.staff_feedback_scale(array_agg(f.team) filter (where f.team is not null)),
             'easier_texts', coalesce(jsonb_agg(f.easier_text order by f.easier_text)
                                        filter (where f.easier_text is not null), '[]'::jsonb),
             'more_texts', coalesce(jsonb_agg(f.more_text order by f.more_text)
                                      filter (where f.more_text is not null), '[]'::jsonb)
           )
      into v_baro
    from public.staff_feedback f
    where f.organization_id = v_org and f.kind = 'barometer' and f.staff_member_id is null
      and f.month between v_von and v_bis;
    -- Liegt ein Teil des Blocks schon hinter der Frist, fehlen Antworten:
    -- dann nichts - die Differenz verriete den gelöschten Monat (N1).
    if (v_baro ->> 'answers')::integer <> v_soll then
      v_baro := jsonb_build_object('status', 'too_few');
    end if;
  end if;

  select o_von, o_bis, o_antworten into v_von, v_bis, v_soll
  from app.staff_feedback_window(v_org, 'message');
  if v_von is not null then
    select jsonb_build_object(
             'status', 'ready',
             'from_month', v_von,
             'to_month', v_bis,
             'answers', count(*),
             'texts', jsonb_agg(f.message_text order by f.message_text)
           )
      into v_nachr
    from public.staff_feedback f
    where f.organization_id = v_org and f.kind = 'message' and f.staff_member_id is null
      and f.month between v_von and v_bis;
    if (v_nachr ->> 'answers')::integer <> v_soll then
      v_nachr := jsonb_build_object('status', 'too_few');
    end if;
  end if;

  return jsonb_build_object('barometer', v_baro, 'messages', v_nachr);
end;
$$;

COMMENT ON FUNCTION public.get_staff_feedback_summary() IS 'ORG-006 (§20.2 Nr. 4, ANN-607): Praxissumme der anonymen Rückmeldungen - nur owner; Skalen mit Median und Verteilung, Freitexte gemischt; nur mit drei Beschäftigten, die teilnehmen können, und fünf anonymen Antworten im jüngsten geschlossenen Block (abgeschlossene Monate, feste nicht überlappende Blöcke, höchstens zwölf Monate), sonst status too_few.';

CREATE FUNCTION public.get_team_chat_summary() RETURNS TABLE(badge integer, unread_conversations integer, threads_new integer, activity_unread integer, saved_open integer, reminders_due integer, scheduled integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org         uuid;
  v_staff       uuid;
  v_direkt      integer;
  v_erwaehnt    integer;
  v_fett        integer;
  v_threads     integer;
  v_aktivitaet  integer;
  v_offen       integer;
  v_faellig     integer;
  v_geplant     integer;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  select coalesce(sum(k.unread) filter (where k.kind in ('direct', 'group') and k.notify <> 'none'), 0),
         coalesce(sum(k.mentions), 0),
         count(*) filter (where k.kind <> 'fleet' and not k.archived
                          and (k.mentions > 0 or (k.notify = 'all' and k.unread > 0)
                               or (k.kind in ('direct', 'group') and k.notify <> 'none' and k.unread > 0)))
    into v_direkt, v_erwaehnt, v_fett
  from public.list_team_channels() k;

  select count(*) filter (where t.new_replies > 0) into v_threads from public.list_team_threads() t;
  select count(*) filter (where a.unread) into v_aktivitaet from public.list_team_activity() a;
  select count(*), count(*) filter (where s.due) into v_offen, v_faellig
  from public.list_team_saved(false) s;
  select count(*) into v_geplant from public.list_team_scheduled();

  return query
  select (v_direkt + v_erwaehnt + v_faellig)::integer, v_fett, v_threads, v_aktivitaet,
         v_offen, v_faellig, v_geplant;
end;
$$;

CREATE FUNCTION public.get_team_person(p_staff uuid) RETURNS TABLE(staff_member_id uuid, name text, roles text[], active boolean, own boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_aktiv boolean;
  -- Die Praxisrollen in der Reihenfolge der Anzeige; `patient` ist keine.
  v_reihe text[] := array['owner', 'therapist', 'team_lead', 'office', 'trainer'];
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not exists (select 1 from public.staff_members sm
                 where sm.id = p_staff and sm.organization_id = v_org) then
    raise exception 'team person not found' using errcode = 'P0002';
  end if;
  v_aktiv := app.teamchat_participant(v_org, p_staff);

  return query
  select p_staff,
         case when v_aktiv then app.team_staff_name(p_staff) end,
         case when v_aktiv then array(
           select ur.role_key
           from public.staff_members sm
           join public.user_profiles up
             on up.person_id = sm.person_id and up.organization_id = sm.organization_id
            and up.is_active
           join public.user_roles ur
             on ur.user_id = up.id and ur.organization_id = sm.organization_id
           where sm.id = p_staff and ur.role_key = any (v_reihe)
           group by ur.role_key
           order by array_position(v_reihe, ur.role_key)
         ) else array[]::text[] end,
         v_aktiv,
         p_staff = v_staff;
end;
$$;

COMMENT ON FUNCTION public.get_team_person(p_staff uuid) IS 'TEAM-009 (ANN-668): Personenkarte im Teamchat - Name, Praxisrollen, im Team. Keine Anwesenheit, kein Status, keine Kontaktdaten.';

CREATE FUNCTION public.get_team_profile_picture(p_picture uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_bild  bytea;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  select p.image into v_bild
  from public.staff_profile_pictures p
  join public.staff_members sm on sm.id = p.staff_member_id
  where p.id = p_picture and p.organization_id = v_org and sm.employment_status = 'active';
  if v_bild is null then
    raise exception 'profile picture not found' using errcode = 'P0002';
  end if;
  return translate(encode(v_bild, 'base64'), E'\n', '');
end;
$$;

COMMENT ON FUNCTION public.get_team_profile_picture(p_picture uuid) IS 'TEAM-007 (ADR-017 Abschnitt O): ein Profilbild der eigenen Praxis als Base64, nur von aktiven Personen.';

CREATE FUNCTION public.get_therapy_report(p_report_id uuid) RETURNS TABLE(id uuid, patient_id uuid, treatment_basis_id uuid, status text, report_text text, recommendation text, note_ids uuid[], body_chart_response_id uuid, updated_at timestamp with time zone, document jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  b       public.therapy_reports%rowtype;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    perform app.record_denied_read(v_actor, 'therapy_report.viewed', 'not allowed to read therapy reports');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read therapy reports' using errcode = '42501';
  end if;

  select * into b from public.therapy_reports r
  where r.id = p_report_id and r.organization_id = v_org;
  if not found then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', b.patient_id);

  return query
    select b.id, b.patient_id, b.treatment_basis_id, b.status, b.report_text,
           b.recommendation, b.note_ids, b.body_chart_response_id, b.updated_at,
           case when b.status = 'abgeschlossen' then b.snapshot
                else app.therapy_report_dokument(b.id) end;
end;
$$;

COMMENT ON FUNCTION public.get_therapy_report(p_report_id uuid) IS 'Ein Therapiebericht mit Dokument - beim Entwurf frisch gebaut, beim abgeschlossenen Bericht der Snapshot (DOK-005a). Alle vier Praxisrollen; protokolliert als therapy_report.viewed.';

CREATE FUNCTION public.get_training_appointment(p_appointment_id uuid) RETURNS TABLE(id uuid, training_relationship_id uuid, training_basis_id uuid, client_given_name text, client_family_name text, staff_member_id uuid, staff_given_name text, staff_family_name text, location_id uuid, location_name text, appointment_type text, status text, starts_at timestamp with time zone, ends_at timestamp with time zone, updated_at timestamp with time zone, visit_street text, visit_house_number text, visit_postal_code text, visit_city text, cancellation_reason text, cancellation_received_at timestamp with time zone, organization_time_zone text, occasion text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_training_relationships() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read training appointments');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training appointments' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.appointments a
    where a.id = p_appointment_id and a.organization_id = v_org and a.kind = 'training'
  ) then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  return query
    select a.id, a.training_relationship_id, a.training_basis_id,
           tp.given_name, tp.family_name,
           a.staff_member_id, sp.given_name, sp.family_name,
           a.location_id, l.name,
           a.appointment_type, a.status, a.starts_at, a.ends_at, a.updated_at,
           a.visit_street, a.visit_house_number, a.visit_postal_code, a.visit_city,
           a.cancellation_reason, a.cancellation_received_at,
           o.time_zone,
           a.occasion
    from public.appointments a
    join public.training_relationships tr on tr.id = a.training_relationship_id
    join public.persons tp                on tp.id = tr.person_id
    join public.staff_members sm          on sm.id = a.staff_member_id
    join public.persons sp                on sp.id = sm.person_id
    join public.organizations o           on o.id = a.organization_id
    left join public.locations l          on l.id = a.location_id
    where a.id = p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.get_training_appointment(p_appointment_id uuid) IS 'TRN-006: ein Trainingstermin mit Kund:in, betreuender Person und Ort; seit ERN-011 mit dem Anlass (occasion). owner, trainer, office; ein anderer Kontext ist nicht gefunden; abgewiesen mit denied unter appointments.read. Nicht protokolliert wie das Termindetail der Behandlung (ANN-180).';

CREATE FUNCTION public.get_training_assessments(p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_exercise_plans('training') then
    perform app.record_denied_read(v_actor, 'assessments.read', 'not allowed to read assessments');
    return null;
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.checkin_relationship('training', p_relationship_id, v_org);
  if v_rel.area is null then
    return null;
  end if;

  perform app.log_record_access(
    v_org, v_actor, 'training_relationship.viewed', 'training_relationship', p_relationship_id,
    'user', jsonb_build_object('surface', 'web', 'view', 'assessments'));

  return jsonb_build_object(
    'today', app.training_today(v_org),
    'can_write', app.can_write_exercise_plans('training'),
    'relationship_open', v_rel.is_open,
    'health_consent', app.training_health_consent(p_relationship_id),
    -- Juengstes zuerst.
    'assessments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', a.id,
               'title', a.title,
               'performed_on', a.performed_on,
               'conditions', a.conditions,
               'next_due_on', a.next_due_on,
               'created_by_name', up.display_name,
               'results', (
                 select coalesce(jsonb_agg(jsonb_build_object(
                          'label', r.label, 'unit', r.unit, 'value', r.value,
                          'left', r.value_left, 'right', r.value_right
                        ) order by r.position), '[]'::jsonb)
                 from public.training_assessment_results r
                 where r.assessment_id = a.id
               )
             ) order by a.performed_on desc, a.created_at desc)
      from public.training_assessments a
      left join public.user_profiles up on up.id = a.created_by
      where a.training_relationship_id = p_relationship_id
        and a.organization_id = v_org
        and a.removed_at is null
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_training_assessments(p_relationship_id uuid) IS 'OUT-002 (IDEA-OUT-007, ANN-365): die Assessments eines Trainingsverhaeltnisses mit Messbedingungen, Wiedervorlage und Ergebnissen, unveraendert und ohne Einordnung. Lesen wie die Plaene im Training (owner, trainer, office), protokolliert als Oeffnen des Trainingsverhaeltnisses (view: assessments). Ohne Recht null und eine Abweisung im Protokoll.';

CREATE FUNCTION public.get_training_client(p_relationship_id uuid) RETURNS TABLE(id uuid, person_id uuid, given_name text, family_name text, status text, contract_started_on date, contract_ended_on date, date_of_birth date, email text, phone text, street text, house_number text, postal_code text, city text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_training_relationships() then
    perform app.record_denied_read(v_actor, 'training_relationship.viewed', 'not allowed to read training clients');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training clients' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org
  ) then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'training_relationship.viewed', 'training_relationship', p_relationship_id);

  return query
    select t.id, t.person_id, pe.given_name, pe.family_name, t.status,
           t.contract_started_on, t.contract_ended_on,
           d.date_of_birth, d.email, d.phone, d.street, d.house_number, d.postal_code, d.city
    from public.training_relationships t
    join public.persons pe on pe.id = t.person_id
    left join public.training_contact_details d on d.training_relationship_id = t.id
    where t.id = p_relationship_id;
end;
$$;

CREATE FUNCTION public.get_training_contracts(p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null or not app.can_manage_training_packages() then
    return null;
  end if;
  if not exists (
    select 1 from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org
  ) then
    return null;
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', k.id,
             'concluded_at', k.concluded_at,
             'concluded_on', k.concluded_on,
             'package_label', k.package_label,
             'price_cents', k.price_cents,
             'currency', k.currency,
             'starts_on', k.starts_on,
             'ends_on', k.ends_on,
             'wording_version', k.wording_version,
             'early_start_requested', k.early_start_requested,
             'withdrawal_ends_on', k.withdrawal_ends_on,
             'withdrawn_on', k.withdrawn_on,
             'withdrawn_access_kind', k.withdrawn_access_kind,
             'withdrawn_representative_name', k.withdrawn_representative_name
           ) order by k.concluded_at desc)
    from public.training_contracts k
    where k.training_relationship_id = p_relationship_id and k.organization_id = v_org
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.get_training_contracts(p_relationship_id uuid) IS 'KND-004: die im Konto geschlossenen Trainingsvertraege eines Verhaeltnisses mit Widerrufsfrist und Widerruf (owner, office). Andere: null.';

CREATE FUNCTION public.get_training_packages(p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_training_packages() then
    perform app.record_denied_read(auth.uid(), 'training_packages.read', 'not allowed to read training packages');
    return null;
  end if;
  v_org := app.current_organization_id();
  if not exists (
    select 1 from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org
  ) then
    return null;
  end if;
  v_heute := app.training_today(v_org);

  return jsonb_build_object(
    'today', v_heute,
    -- Warum heute kein Paket beginnen kann; null: Es kann.
    'start_blocker', app.training_package_start_blocker(p_relationship_id, v_heute),
    'packages', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', k.id,
               'code', c.code,
               'label', c.label,
               'package_months', c.package_months,
               'price_cents', c.unit_price_cents,
               'currency', c.currency,
               'starts_on', k.starts_on,
               'ends_on', k.ends_on,
               'state', case
                 when v_heute < k.starts_on then 'planned'
                 when v_heute <= k.ends_on then 'running'
                 else 'ended'
               end,
               'created_at', k.created_at,
               'created_by_name', up.display_name,
               -- Auf einer Rechnung (auch einem Entwurf), die nicht storniert ist.
               'invoiced', exists (
                 select 1 from public.billable_services b
                 join public.invoice_items it on it.billable_service_id = b.id
                 where b.training_package_id = k.id and it.released_at is null
               )
             ) order by k.starts_on desc)
      from public.training_packages k
      join public.service_catalog_items c on c.id = k.catalog_item_id
      left join public.user_profiles up on up.id = k.created_by
      where k.training_relationship_id = p_relationship_id and k.organization_id = v_org
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_training_packages(p_relationship_id uuid) IS 'ANG-006: Trainingspakete eines Verhaeltnisses mit Preis, Zeitraum und Stand, dazu warum heute keins beginnen kann (owner, office). Andere Rollen: null und ein Eintrag der Abweisung.';

CREATE FUNCTION public.get_training_profile(p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_einwilligung text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- ABN-030 (BEF-137, ANN-287): Lesen nach der einen Regel des Trainings,
  -- auch das Buero. Schreiben bleibt bei app.can_access_training_protocols().
  if not app.can_read_training_content() then
    perform app.record_denied_read(v_actor, 'training_relationship.viewed', 'not allowed to read training profiles');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null or not exists (
    select 1 from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org
  ) then
    return null;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'training_relationship.viewed', 'training_relationship', p_relationship_id,
    'success', jsonb_build_object('surface', 'web', 'view', 'profile')
  );

  select r.record_kind into v_einwilligung
  from public.training_consent_records r
  where r.training_relationship_id = p_relationship_id and r.purpose = 'training_health_data'
  order by r.recorded_at desc, r.id desc
  limit 1;

  return jsonb_build_object(
    'health_consent', v_einwilligung is not distinct from 'consent_granted',
    'profile', (
      select jsonb_build_object(
               'goals', p.goals,
               'equipment', p.equipment,
               'time_budget', p.time_budget,
               'places', p.places,
               'limits', p.limits,
               'history', p.history,
               'preferences', p.preferences,
               'updated_at', p.updated_at,
               'updated_by_name', up.display_name
             )
      from public.training_profiles p
      left join public.user_profiles up on up.id = p.updated_by
      where p.training_relationship_id = p_relationship_id
    ),
    'takeovers', coalesce((
      select jsonb_agg(jsonb_build_object(
               'title', k.title,
               'body', k.body,
               'offered_on', k.offered_on,
               'released_at', k.released_at,
               -- Der Tag in der Zeitzone der Praxis, nicht in UTC (Zweitreview).
               'released_on', (k.released_at at time zone o.time_zone)::date
             ) order by k.position)
      from public.training_takeovers k
      join public.organizations o on o.id = k.organization_id
      where k.training_relationship_id = p_relationship_id
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.get_training_profile(p_relationship_id uuid) IS 'KND-005, ABN-030: Voraussetzungsprofil und Uebernahmen aus der Behandlung eines Trainingsverhaeltnisses (app.can_read_training_content: owner, Trainingsbetreuung, Buero; ANN-287, BEF-137), dazu ob eine Einwilligung zu Gesundheitsangaben vermerkt ist. Jedes Lesen im Auditlog (training_relationship.viewed, view profile); andere Rollen: null und ein Eintrag der Abweisung.';

CREATE FUNCTION public.get_training_protocol(p_appointment_id uuid) RETURNS TABLE(id uuid, appointment_id uuid, status text, content text, created_at timestamp with time zone, updated_at timestamp with time zone, finalized_at timestamp with time zone, author_name text, finalized_by_name text, addenda jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_rel   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- ABN-022 (BEF-113): Lesen ist getrennt vom Schreiben; das Buero liest.
  if not app.can_read_training_protocols() then
    perform app.record_denied_read(v_actor, 'training_protocol.viewed', 'not allowed to read training protocols');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training protocols' using errcode = '42501';
  end if;

  select a.training_relationship_id into v_rel
  from public.appointments a
  where a.id = p_appointment_id and a.organization_id = v_org and a.kind = 'training';

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.training_protocols p where p.appointment_id = p_appointment_id) then
    perform app.log_record_access(v_org, v_actor, 'training_relationship.viewed', 'training_relationship', v_rel);
  end if;

  return query
    select p.id, p.appointment_id, p.status, p.content, p.created_at, p.updated_at,
           p.finalized_at, verfasser.display_name, abschluss.display_name,
           -- ABN-022 (BEF-113): Nachtraege unter dem Text, aelteste zuerst.
           coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', n.id,
                      'content', n.content,
                      'reason', n.reason,
                      'created_at', n.created_at,
                      'author_name', na.display_name
                    ) order by n.created_at)
             from public.training_protocol_addenda n
             left join public.user_profiles na on na.id = n.created_by
             where n.protocol_id = p.id
           ), '[]'::jsonb)
    from public.training_protocols p
    left join public.user_profiles verfasser on verfasser.id = p.created_by
    left join public.user_profiles abschluss on abschluss.id = p.finalized_by
    where p.appointment_id = p_appointment_id;
end;
$$;

CREATE FUNCTION public.get_treatment_basis(p_treatment_basis_id uuid) RETURNS TABLE(id uuid, patient_id uuid, prescriber_id uuid, prescriber_name text, prescriber_practice_name text, treatment_basis_kind text, issued_on date, appointment_count integer, frequency_note text, note text, items jsonb, updated_at timestamp with time zone, diagnosis text, therapy_goal text, prescriber_note text, follow_up_recommendation text, diagnosis_icd10 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor      uuid;
  v_org        uuid;
  v_patient_id uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_basis_clinical() then
    -- G6a: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'treatment_basis.viewed', 'not allowed to read clinical treatment basis data');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read clinical treatment basis data' using errcode = '42501';
  end if;

  select p.patient_id into v_patient_id
  from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org;

  -- Eine fremde und eine unbekannte ID liefern beide nichts.
  if not found then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', v_patient_id);

  return query
    select
      p.id,
      p.patient_id,
      p.prescriber_id,
      -- nullif, damit beim Selbstzahler wirklich NICHTS dasteht: concat_ws
      -- ueberspringt Nullwerte und lieferte sonst den leeren String - eine
      -- Angabe, die es nicht gibt (GRD-001, ADR-020 Punkt 3).
      nullif(btrim(concat_ws(' ', v.title, v.given_name, v.family_name)), ''),
      v.practice_name,
      p.treatment_basis_kind,
      p.issued_on,
      p.appointment_count,
      p.frequency_note,
      p.note,
      app.treatment_base_items_json(p.id),
      p.updated_at,
      p.diagnosis,
      -- Drei Bestandstexte: Das Formular bietet sie seit VER-EPIC-002 nicht
      -- mehr zur Eingabe an, zeigt sie aber weiter an - sonst waere ein
      -- vorhandener Text unsichtbar und damit faktisch verloren.
      p.therapy_goal,
      p.prescriber_note,
      p.follow_up_recommendation,
      p.diagnosis_icd10
    from public.treatment_bases p
    -- LEFT JOIN seit GRD-001: Ein Selbstzahler hat keine Verordner:in
    -- (ADR-020 Punkt 3). Ein innerer Verbund liesse ihn aus der Projektion
    -- fallen - die Zeile waere da, die Akte zeigte sie nicht.
    left join public.prescribers v on v.id = p.prescriber_id
    where p.id = p_treatment_basis_id;
end;
$$;

CREATE FUNCTION public.get_treatment_basis_slots(p_treatment_basis_id uuid) RETURNS TABLE(patient_id uuid, frequency_note text, prescribed integer, used integer, planned integer, remaining integer, covered integer, uncovered integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_zahlen record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_bases() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'treatment_bases.read', 'not allowed to read treatment_bases');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment_bases' using errcode = '42501';
  end if;

  select p.patient_id, p.frequency_note
    into patient_id, frequency_note
  from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  select * into v_zahlen from app.treatment_basis_slot_counts(p_treatment_basis_id, v_org);
  prescribed := v_zahlen.prescribed;
  used       := v_zahlen.used;
  planned    := v_zahlen.planned;
  remaining  := v_zahlen.remaining;
  covered    := v_zahlen.covered;
  uncovered  := v_zahlen.uncovered;
  return next;
end;
$$;

COMMENT ON FUNCTION public.get_treatment_basis_slots(p_treatment_basis_id uuid) IS 'Terminzahl und Frequenz einer Behandlungsgrundlage fuer die Serienplanung (CAL-007, ANN-064), seit CAL-022 mit gedeckt und ungedeckt. Ohne klinische Felder.';

CREATE FUNCTION public.get_treatment_draft_findings(p_appointment_id uuid) RETURNS TABLE(findings jsonb, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    perform app.record_denied_read(v_actor, 'treatment_draft_findings.viewed', 'not allowed to read draft findings');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read draft findings' using errcode = '42501';
  end if;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = p_appointment_id and a.organization_id = v_org;
  if not found then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.treatment_draft_findings f where f.appointment_id = p_appointment_id and f.organization_id = v_org) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', v_patient);
  end if;

  return query
    select f.findings, f.updated_at
    from public.treatment_draft_findings f
    where f.appointment_id = p_appointment_id and f.organization_id = v_org;
end;
$$;

COMMENT ON FUNCTION public.get_treatment_draft_findings(p_appointment_id uuid) IS 'Die gesicherten, noch nicht uebernommenen Befundangaben eines Behandlungstermins (ABN-015). Dokumentierende Rollen; protokolliert als treatment_draft_findings.viewed, abgewiesen mit denied-Eintrag.';

CREATE FUNCTION public.get_treatment_note(p_appointment_id uuid) RETURNS TABLE(id uuid, appointment_id uuid, addendum_to_note_id uuid, status text, content text, visit_without_treatment boolean, created_at timestamp with time zone, updated_at timestamp with time zone, finalized_at timestamp with time zone, finalisation_kind text, version_count integer, author_name text, last_editor_name text, finalized_by_name text, reported_written_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    -- G6a: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'treatment_note.viewed', 'not allowed to read treatment documentation');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment documentation' using errcode = '42501';
  end if;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org;

  if not found then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.treatment_notes t where t.appointment_id = p_appointment_id and t.organization_id = v_org) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', v_patient);
  end if;

  return query
    select t.id,
           t.appointment_id,
           t.addendum_to_note_id,
           t.status,
           t.content,
           t.visit_without_treatment,
           t.created_at,
           t.updated_at,
           t.finalized_at,
           t.finalisation_kind,
           (select count(*) from public.treatment_note_versions v where v.note_id = t.id)::integer,
           verfasser.display_name,
           bearbeiter.display_name,
           finalisierer.display_name,
           t.reported_written_at
    from public.treatment_notes t
    left join public.user_profiles verfasser    on verfasser.id    = t.created_by
    left join public.user_profiles bearbeiter   on bearbeiter.id   = t.updated_by
    left join public.user_profiles finalisierer on finalisierer.id = t.finalized_by
    where t.appointment_id = p_appointment_id
      and t.organization_id = v_org
    order by (t.addendum_to_note_id is not null), t.created_at;
end;
$$;

COMMENT ON FUNCTION public.get_treatment_note(p_appointment_id uuid) IS 'Liefert Haupteintrag und Nachtraege der Behandlungsdokumentation eines Termins samt Art der Finalisierung, Pflichtvermerk aus Hausbesuch-Szenario 1 und - bei einem ohne Verbindung geschriebenen Entwurf - der Zeit des Geraets; protokolliert Akte geoeffnet hoechstens einmal je Tag (DOK-001, DOK-002, DOK-004, CAL-018, OFF-002, ADR-010).';

CREATE FUNCTION public.get_treatment_note_versions(p_note_id uuid) RETURNS TABLE(version_no integer, content text, change_reason text, recorded_at timestamp with time zone, author_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_note    record;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    -- G6a: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'treatment_note.history_viewed', 'not allowed to read treatment documentation');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment documentation' using errcode = '42501';
  end if;

  select t.id, t.appointment_id
    into v_note
  from public.treatment_notes t
  where t.id = p_note_id
    and t.organization_id = v_org;

  if not found then
    return;
  end if;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = v_note.appointment_id;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', v_patient);

  return query
    select v.version_no,
           v.content,
           v.change_reason,
           v.recorded_at,
           urheber.display_name
    from public.treatment_note_versions v
    left join public.user_profiles urheber on urheber.id = v.author_id
    where v.note_id = p_note_id
    order by v.version_no;
end;
$$;

COMMENT ON FUNCTION public.get_treatment_note_versions(p_note_id uuid) IS 'Liefert den Versionsverlauf einer Behandlungsdokumentation und protokolliert treatment_note.history_viewed (DOK-002, ADR-016 Punkt 5, 8 und 9).';

CREATE FUNCTION public.get_visit_position(p_patient_id uuid) RETURNS TABLE(lat double precision, lon double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Dieselben Rollen wie die Terminanlage und die Terminsuche (PRX-003).
  if not app.can_create_appointment() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to create appointments');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;

  if p_patient_id is null or not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- Ohne Kontaktzeile oder ohne Verortung: eine Zeile mit null. Das
  -- Formular sagt dann "Adresse nicht verortet" statt einer Zeit.
  return query
    select cd.lat, cd.lon
    from (select 1) eins
    left join public.patient_contact_details cd
      on cd.patient_id = p_patient_id and cd.organization_id = v_org;
end;
$$;

COMMENT ON FUNCTION public.get_visit_position(p_patient_id uuid) IS 'UBK-012, ANN-238: Koordinate der Patientenadresse fuer einen neuen Hausbesuch - ohne Name und Adresse. Rechte wie find_free_slots (can_create_appointment); abgewiesen mit denied-Eintrag (G6b).';

CREATE FUNCTION public.hand_out_message_attachment(p_attachment_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_anhang  public.platform_message_attachments%rowtype;
  v_vorgang public.platform_messages%rowtype;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Die Rolle vor dem Anhang: Wer nicht herausgeben darf, erfaehrt auch nicht,
  -- ob es die Kennung gibt.
  if not app.has_any_role('owner') then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  select x.* into v_anhang
  from public.platform_message_attachments x
  where x.id = p_attachment_id
    and x.organization_id = app.current_organization_id()
    and x.status = 'ready';
  if v_anhang.id is null then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;

  select m.* into v_vorgang from public.platform_messages m where m.id = v_anhang.message_id;

  -- Dieselbe Pruefung wie die Auskunft zum Verhaeltnis.
  if v_vorgang.relationship_kind = 'treatment' then
    perform app.auskunft_organisation(v_vorgang.patient_id);
  else
    perform app.auskunft_organisation_training(v_vorgang.training_relationship_id);
  end if;

  if not exists (
    select 1 from storage.objects o
    where o.bucket_id = app.message_attachment_bucket() and o.name = v_anhang.object_key
  ) then
    raise exception 'attachment object missing' using errcode = 'P0002';
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_anhang.organization_id, v_actor, 'message_attachment.handed_out',
    'platform_message_attachment', v_anhang.id, 'success',
    jsonb_strip_nulls(jsonb_build_object(
      'surface', 'web',
      'patient_id', v_vorgang.patient_id,
      'training_relationship_id', v_vorgang.training_relationship_id,
      'media_kind', v_anhang.media_kind,
      'gesperrt', not app.message_attachment_visible(v_anhang)
    ))
  );

  delete from public.message_attachment_access_grants g
   where g.organization_id = v_anhang.organization_id
     and g.expires_at <= now();

  -- ANN-052: eine Freigabe, eine Operation, 30 Sekunden.
  insert into public.message_attachment_access_grants (
    organization_id, user_id, attachment_id, expires_at, handout
  )
  values (
    v_anhang.organization_id, v_actor, v_anhang.id,
    now() + app.patient_file_access_grant_ttl(), true
  );

  return query
    select app.message_attachment_bucket(), v_anhang.object_key, v_anhang.mime_type;
end;
$$;

COMMENT ON FUNCTION public.hand_out_message_attachment(p_attachment_id uuid) IS 'BEF-188 (ADR-017 Punkt 96): Kopie eines Fotos oder Videos an einer Rueckfrage an die Person selbst (Art. 15 Abs. 3, Art. 20 DSGVO). Nur owner, jeder bestaetigte Anhang, auch gesperrt; als message_attachment.handed_out protokolliert (ANN-672).';

CREATE FUNCTION public.hand_out_patient_photo(p_file_id uuid) RETURNS TABLE(bucket_id text, object_key text, display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_datei record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Die Rolle vor der Datei: Wer nicht herausgeben darf, erfaehrt auch nicht,
  -- ob eine Kennung ein Foto ist.
  if not app.has_any_role('owner') then
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = app.current_organization_id()
    and app.is_patient_photo_type(f.document_type)
    and f.status = 'ready';

  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  -- Dieselbe Pruefung wie die Auskunft: owner, eigene Organisation, eigene
  -- Akte. Wirft sonst - wie export_patient_record.
  perform app.auskunft_organisation(v_datei.patient_id);

  -- ABN-017 (BEF-107): Ein gesperrtes, noch vorhandenes Foto ist nicht
  -- pauschal von der Kopie ausgeschlossen. Die Sperre gilt der Arbeit mit
  -- dem Foto, nicht der Auskunft an die Person selbst; das Protokoll sagt,
  -- ob es gesperrt war.

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_datei.organization_id, v_actor, 'patient_file.handed_out', 'patient_file', p_file_id, 'success',
    jsonb_build_object(
      'surface', 'web',
      'patient_id', v_datei.patient_id,
      'document_type', v_datei.document_type,
      'gesperrt', not app.patient_photo_usable(
        v_datei.document_type, v_datei.patient_id, v_datei.created_at, v_datei.photo_locked_at)
    )
  );

  delete from public.patient_file_access_grants g
   where g.organization_id = v_datei.organization_id
     and g.expires_at <= now();

  -- ANN-052: eine Freigabe, eine Operation, 30 Sekunden.
  insert into public.patient_file_access_grants (
    organization_id, user_id, patient_file_id, expires_at
  )
  values (
    v_datei.organization_id, v_actor, p_file_id, now() + app.patient_file_access_grant_ttl()
  );

  return query
    select app.patient_file_bucket_for(v_datei.document_type), v_datei.object_key, v_datei.display_name;
end;
$$;

COMMENT ON FUNCTION public.hand_out_patient_photo(p_file_id uuid) IS 'Kopie eines Patientenfotos an die Person selbst (Art. 15 Abs. 3, Art. 20 DSGVO; ADR-017 Punkt 40). Nur owner, nur ein nutzbares Foto, als patient_file.handed_out protokolliert (ANN-128).';

CREATE FUNCTION public.hand_over_fleet_key(p_bike_id uuid, p_holder_staff_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_offen   record;
  v_id      uuid;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');

  if p_holder_staff_id is null then
    raise exception 'staff member is required' using errcode = '22023';
  end if;

  perform 1 from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
  for update;
  if not found then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.fleet_blocks b where b.bike_id = p_bike_id and b.released_at is null
  ) then
    raise exception 'bike is blocked' using errcode = '55000';
  end if;

  select k.id, k.holder_staff_id into v_offen
  from public.fleet_key_handovers k
  where k.bike_id = p_bike_id and k.organization_id = v_org and k.returned_at is null
  for update;
  if not found then
    raise exception 'key is not taken' using errcode = '55000';
  end if;

  perform app.assert_staff_member_in_org(p_holder_staff_id, v_org);
  if v_offen.holder_staff_id = p_holder_staff_id then
    raise exception 'key already with this person' using errcode = '55000';
  end if;

  update public.fleet_key_handovers
     set returned_at = now(), returned_by = auth.uid()
   where id = v_offen.id;

  insert into public.fleet_key_handovers (organization_id, bike_id, holder_staff_id, taken_by)
  values (v_org, p_bike_id, p_holder_staff_id, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.hand_over_fleet_key(p_bike_id uuid, p_holder_staff_id uuid) IS 'Überholung 6 (ANN-575): Schluessel eines Rads von Hand zu Hand - der offene Vorgang endet, ein neuer fuer eine andere Person aus dem Stamm beginnt, in einem Vorgang. Nicht bei gesperrtem Rad, nicht an dieselbe Person. Alle Praxisrollen der Behandlung (BEF-066).';

CREATE FUNCTION public.import_exercise_catalog(p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.exercise_library_writer();
  return app.import_exercise_catalog_for(v_org, auth.uid(), p_entries, false);
end;
$$;

COMMENT ON FUNCTION public.import_exercise_catalog(p_entries jsonb) IS 'UEB-012 (ANN-385): uebernimmt den mitgelieferten Katalog in die Bibliothek der Praxis - nur nach app.can_manage_exercise_library() (owner, ANN-293). Liefert imported, skipped und conflicts. Keine neue Auditaktion: created_by steht an der Zeile.';

CREATE FUNCTION public.invite_platform_access(p_relationship_kind text, p_relationship_id uuid, p_channel text, p_address_confirmed boolean DEFAULT false) RETURNS TABLE(access_id uuid, invitation_id uuid, purpose text, code text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_rel     record;
  v_access  public.platform_accesses%rowtype;
  v_purpose text;
  v_code    text;
  v_inv     uuid;
  v_expires timestamptz;
  v_email   text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_platform_access(p_relationship_kind) then
    perform app.record_denied_write(v_actor, 'platform_access.invited', 'not allowed to manage platform access');
    return;
  end if;
  v_org := app.current_organization_id();

  if p_channel is null or p_channel not in ('on_site', 'email') then
    raise exception 'unknown channel' using errcode = '22023';
  end if;

  select * into v_rel
  from app.platform_relationship(p_relationship_kind, p_relationship_id) r
  where r.organization_id = v_org;
  if not found then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;

  -- Punkt 15 (W4): Unter 18 gibt es keinen eigenen Zugang. Ohne Geburtsdatum
  -- laesst sich das nicht pruefen, und die restriktive Seite gilt (§16,
  -- ANN-190).
  if v_rel.date_of_birth is null then
    raise exception 'date of birth required' using errcode = '22023';
  end if;
  -- W1 (Punkt 2): eine Person mit Praxiskonto bekommt keinen Zugang.
  if exists (
    select 1 from public.user_profiles up
    join public.user_roles ur on ur.user_id = up.id
    where up.person_id = v_rel.person_id
  ) then
    raise exception 'person has a practice account' using errcode = '22023';
  end if;
  -- ABN-009 (BEF-117): dieselbe Rechnung wie ueberall, in der Zeitzone der
  -- Praxis - bisher stand hier UTC.
  if app.platform_is_minor(
       v_rel.date_of_birth,
       (select o.time_zone from public.organizations o where o.id = v_org)) then
    raise exception 'person is under age' using errcode = '22023';
  end if;

  -- Punkt 11 (Fassung 2, ANN-188): Mail nur an die Adresse im Verhaeltnis,
  -- und nur, wenn die einladende Person vermerkt, dass die Person sie selbst
  -- bestaetigt hat.
  if p_channel = 'email' then
    if v_rel.email is null then
      raise exception 'no email address on record' using errcode = '22023';
    end if;
    if not coalesce(p_address_confirmed, false) then
      raise exception 'address must be confirmed by the person' using errcode = '22023';
    end if;
    v_email := v_rel.email;
  end if;

  select * into v_access
  from public.platform_accesses a
  where a.relationship_id = p_relationship_id
    and a.relationship_kind = p_relationship_kind
    and a.access_kind = 'self'
    and a.status <> 'revoked'
  for update;

  if not found then
    insert into public.platform_accesses (
      organization_id, relationship_kind, relationship_id,
      patient_id, training_relationship_id, created_by
    )
    values (
      v_org, p_relationship_kind, p_relationship_id,
      case when p_relationship_kind = 'treatment' then p_relationship_id end,
      case when p_relationship_kind = 'training' then p_relationship_id end,
      v_actor
    )
    returning * into v_access;
    v_purpose := 'activate';
  elsif v_access.status = 'invited' then
    v_purpose := 'activate';
  elsif v_access.status = 'active' then
    v_purpose := 'reset';
    -- Zweitreview: Ein neues Kennwort gilt fuer das ganze Konto und damit
    -- fuer jeden seiner Zugaenge. Ausstellen darf es nur, wer alle lebenden
    -- Zugaenge des Kontos verwalten darf - sonst oeffnete die
    -- Trainingsbetreuung den Weg in die Behandlung und umgekehrt (§4.8).
    if exists (
      select 1 from public.platform_accesses b
      where b.account_user_id = v_access.account_user_id
        and b.status <> 'revoked'
        -- POR-005, Zweitreview: auch ueber Organisationen hinweg. Die Rolle
        -- gilt nur in der eigenen Praxis; ein Konto mit Zugang in einer
        -- zweiten Praxis bekommt hier kein neues Kennwort.
        and (b.organization_id <> v_org or not app.can_manage_platform_access(b.relationship_kind))
    ) then
      raise exception 'reset needs every area of this account' using errcode = '22023';
    end if;
  else
    raise exception 'platform access is locked' using errcode = '22023';
  end if;

  update public.platform_access_invitations i
     set status = 'revoked', revoked_at = now()
   where i.platform_access_id = v_access.id and i.status = 'pending';

  -- 24 Zufallsbytes, URL-tauglich kodiert: 32 Zeichen, nicht zu erraten.
  v_code := translate(encode(extensions.gen_random_bytes(24), 'base64'), '+/', '-_');
  v_expires := now() + app.platform_invitation_validity();

  insert into public.platform_access_invitations (
    organization_id, platform_access_id, purpose, channel, code_hash, email,
    address_confirmed_by, address_confirmed_at, expires_at, created_by
  )
  values (
    v_org, v_access.id, v_purpose, p_channel, app.platform_code_hash(v_code), v_email,
    case when p_channel = 'email' then v_actor end,
    case when p_channel = 'email' then now() end,
    v_expires, v_actor
  )
  returning id into v_inv;

  perform app.log_platform_access_event(
    v_org, v_actor, 'user', 'platform_access.invited', v_access.id,
    jsonb_build_object('surface', 'web', 'channel', p_channel, 'purpose', v_purpose,
                       'relationship_kind', p_relationship_kind)
  );

  return query select v_access.id, v_inv, v_purpose, v_code, v_expires;
end;
$$;

COMMENT ON FUNCTION public.invite_platform_access(p_relationship_kind text, p_relationship_id uuid, p_channel text, p_address_confirmed boolean) IS 'POR-002: laedt zu einem Plattformzugang ein (vor Ort oder per Mail an die bestaetigte Adresse, ANN-188) und liefert den Code einmal. Rollen, die das Verhaeltnis schreiben (ADR-023 Punkt 6); abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.invite_platform_representation(p_relationship_kind text, p_relationship_id uuid, p_access_kind text, p_legal_basis text, p_representative_name text, p_proof_documents text[], p_health_scope boolean, p_consent_version text, p_earlier_messages boolean, p_finance_scope boolean, p_capacity_doubt boolean DEFAULT false) RETURNS TABLE(access_id uuid, invitation_id uuid, purpose text, code text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_rel    record;
  v_access uuid;
  v_inv    record;
  v_docs   text[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_platform_access(p_relationship_kind) then
    perform app.record_denied_write(v_actor, 'platform_access.invited', 'not allowed to manage platform access');
    return;
  end if;
  v_org := app.current_organization_id();

  select * into v_rel
  from app.platform_relationship(p_relationship_kind, p_relationship_id) r
  where r.organization_id = v_org;
  if not found then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;

  perform app.assert_platform_representation(
    p_access_kind, p_legal_basis, v_rel.date_of_birth,
    (select o.time_zone from public.organizations o where o.id = v_org), p_representative_name,
    p_proof_documents, p_health_scope, p_consent_version, p_earlier_messages, p_finance_scope
  );

  -- Ein Zweifel schliesst die Begleitung aus; vermerkt wird er nur an einer
  -- rechtlichen Vertretung (ANN-207 Fassung 2).
  if coalesce(p_capacity_doubt, false) and p_access_kind <> 'legal_representative' then
    raise exception 'a capacity doubt allows only a legal representative' using errcode = '22023';
  end if;

  -- Nur die Dokumente, die zur Art gehoeren; doppelte fallen weg.
  select array_agg(distinct d order by d) into v_docs
  from unnest(p_proof_documents) d
  where d = 'identity_document'
     or (p_access_kind = 'legal_representative' and d = case p_legal_basis
           when 'custody' then 'custody_proof'
           when 'guardianship' then 'guardianship_certificate'
           else 'power_of_attorney' end);

  insert into public.platform_accesses (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    access_kind, legal_basis, representative_name, proof_documents, health_scope, finance_scope,
    proof_recorded_by, proof_recorded_at,
    consent_text_version, consent_recorded_by, consent_recorded_at, consent_earlier_messages,
    companion_declined_at, companion_declined_by, companion_declined_reason,
    created_by
  )
  values (
    v_org, p_relationship_kind, p_relationship_id,
    case when p_relationship_kind = 'treatment' then p_relationship_id end,
    case when p_relationship_kind = 'training' then p_relationship_id end,
    p_access_kind,
    case when p_access_kind = 'legal_representative' then p_legal_basis end,
    btrim(p_representative_name), v_docs,
    -- ABN-010: Gesundheitssorge vermerkt die Praxis bei Betreuung und
    -- Vorsorgevollmacht; das Sorgerecht umfasst sie.
    case when p_access_kind = 'legal_representative' and p_legal_basis <> 'custody' then true end,
    -- Rechnungen nur, wenn nachgewiesen bzw. eingewilligt (BEF-119, BEF-116).
    p_finance_scope,
    v_actor, now(),
    case when p_access_kind = 'companion' then p_consent_version end,
    case when p_access_kind = 'companion' then v_actor end,
    case when p_access_kind = 'companion' then now() end,
    case when p_access_kind = 'companion' then p_earlier_messages end,
    case when coalesce(p_capacity_doubt, false) then now() end,
    case when coalesce(p_capacity_doubt, false) then v_actor end,
    case when coalesce(p_capacity_doubt, false) then 'capacity_doubt' end,
    v_actor
  )
  returning id into v_access;

  select * into v_inv from app.issue_platform_invitation(v_org, v_access, 'activate', v_actor);

  perform app.log_platform_access_event(
    v_org, v_actor, 'user', 'platform_access.invited', v_access,
    jsonb_build_object('surface', 'web', 'channel', 'on_site', 'purpose', 'activate',
                       'relationship_kind', p_relationship_kind, 'access_kind', p_access_kind,
                       'legal_basis', p_legal_basis, 'finance_scope', p_finance_scope)
  );

  return query select v_access, v_inv.invitation_id, 'activate'::text, v_inv.code, v_inv.expires_at;
end;
$$;

COMMENT ON FUNCTION public.invite_platform_representation(p_relationship_kind text, p_relationship_id uuid, p_access_kind text, p_legal_basis text, p_representative_name text, p_proof_documents text[], p_health_scope boolean, p_consent_version text, p_earlier_messages boolean, p_finance_scope boolean, p_capacity_doubt boolean) IS 'Richtet eine Vertretung ein (rechtliche Vertretung oder Begleitung) mit Nachweisvermerk, nachgewiesenen bzw. eingewilligten Bereichen und Code fuer die Uebergabe vor Ort (POR-005, ABN-010). p_capacity_doubt vermerkt am Zugang einer rechtlichen Vertretung den Zweifel an der Einwilligungsfaehigkeit (ADR-023 Punkt 13, LOG-EPIC-001).';

CREATE FUNCTION public.invite_staff_account(p_staff_member_id uuid, p_email text, p_role_keys text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor     uuid;
  v_org       uuid;
  v_email     text;
  v_person_id uuid;
  v_id        uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_accounts() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'staff_account.invited', 'not allowed to manage accounts');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage accounts' using errcode = '42501';
  end if;

  v_email := lower(btrim(coalesce(p_email, '')));
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'invalid email' using errcode = '22023';
  end if;

  perform app.assert_staff_role_keys(p_role_keys);

  -- Zielsatz ausschliesslich in der eigenen Organisation; sonst waere die
  -- Funktion ein Orakel fuer fremde Mitarbeiter-IDs (13).
  select sm.person_id into v_person_id
  from public.staff_members sm
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org
    and sm.employment_status = 'active'
  for update;

  if not found then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  -- Ein zweiter Zugang zu derselben Person waere ein geteilter Zugang durch
  -- die Hintertuer (4.2: ein individuelles Konto ist Pflicht).
  if exists (
    select 1 from public.user_profiles up
    where up.person_id = v_person_id
      and up.organization_id = v_org
  ) then
    raise exception 'account_already_exists' using errcode = '22023';
  end if;

  -- Dieselbe Adresse darf nicht an zwei Zugaenge derselben Praxis gehen.
  if exists (
    select 1
    from public.user_profiles up
    join auth.users au on au.id = up.id
    where up.organization_id = v_org
      and lower(btrim(au.email)) = v_email
  ) then
    raise exception 'email_already_in_use' using errcode = '22023';
  end if;

  insert into public.staff_account_invitations (
    organization_id, staff_member_id, email, role_keys, expires_at, invited_by
  )
  values (
    v_org, p_staff_member_id, v_email, p_role_keys, now() + interval '14 days', v_actor
  )
  returning id into v_id;

  -- Auditeintrag mit den Rollen, aber OHNE die Adresse: die Rollen sind der
  -- sicherheitsrelevante Teil des Vorgangs, die Adresse ist Kontaktdatum
  -- (ADR-010 Punkt 3, PROJECT_PRINCIPLES.md 20).
  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'staff_account.invited', 'staff_member', p_staff_member_id, 'success',
    jsonb_build_object('surface', 'web', 'roles', to_jsonb(p_role_keys))
  );

  return v_id;
end;
$_$;

COMMENT ON FUNCTION public.invite_staff_account(p_staff_member_id uuid, p_email text, p_role_keys text[]) IS 'Legt die Einladung eines Zugangs an - nur owner. Erzeugt weder Konto noch Rollen; beides entsteht erst bei der Annahme (STAFF-002b).';

CREATE FUNCTION public.issue_fleet_photo_link(p_photo_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_foto public.fleet_photos%rowtype;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to read the fleet');
  select f.* into v_foto
  from public.fleet_photos f
  where f.id = p_photo_id and f.organization_id = v_org and f.status = 'ready';
  if v_foto.id is null then
    raise exception 'photo not found' using errcode = 'P0002';
  end if;

  delete from public.fleet_photo_access_grants g
   where g.organization_id = v_org and g.expires_at <= now();
  insert into public.fleet_photo_access_grants (organization_id, user_id, photo_id, expires_at)
  values (v_org, auth.uid(), v_foto.id, now() + app.patient_file_access_grant_ttl());

  return query select app.fleet_photo_bucket(), v_foto.object_key, v_foto.mime_type;
end;
$$;

COMMENT ON FUNCTION public.issue_fleet_photo_link(p_photo_id uuid) IS 'FLT-002 (ADR-017 Punkt 15, ANN-052): einmalige Freigabe fuer genau einen Verweis auf ein Foto am Rad. Lesen nach app.can_read_fleet(). Kein Auditeintrag.';

CREATE FUNCTION public.issue_invoice(p_invoice_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_invoice  record;
  v_zeitzone text;
  v_heute    date;
  v_nummer   text;
  v_prefix   text;
  v_frist    smallint;
  v_dokument jsonb;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.* into v_invoice
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  if v_invoice.status <> 'draft' then
    raise exception 'invoice is already issued' using errcode = '23514';
  end if;

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  select b.payment_term_days into v_frist
  from public.practice_billing_profiles b
  where b.organization_id = v_org;

  -- Ohne Absender keine Rechnung. Der Hinweis nennt die Luecke, damit die
  -- Oberflaeche nicht raten muss, was fehlt (ADR-009 Punkt 10).
  if not found then
    raise exception 'practice billing profile missing' using errcode = '22023';
  end if;

  -- Das Kuerzel des Kreises, in den diese Rechnung gehoert (ABR-010).
  v_prefix := app.invoice_number_prefix(v_org, v_invoice.service_area);

  -- ABR-032: Jede Zeile gehoert zur Grundlage der Rechnung.
  perform app.assert_invoice_items_match_basis(p_invoice_id);

  v_dokument := app.build_invoice_document(p_invoice_id);

  -- Der Par. 14c-Riegel (ABR-007, ADR-009 Punkt 18). Er steht hier und nicht
  -- in der Oberflaeche, weil die Steuerschuld mit dem **Ausweis** entsteht -
  -- nicht mit der Zahlung und nicht mit der Absicht. Was einmal falsch
  -- draufsteht, kostet ein Storno (Punkt 9).
  perform app.assert_invoice_tax_lawful(v_dokument);
  -- ABN-020 (BEF-111): keine Rechnung ohne vollstaendige Empfaengeranschrift.
  perform app.assert_invoice_recipient_address(v_dokument -> 'recipient');

  v_nummer := app.next_invoice_number(
    v_org, extract(year from v_heute)::smallint, v_invoice.service_area, v_prefix);

  -- Der Snapshot traegt Nummer und Daten mit: Er ist das Dokument, nicht ein
  -- Teil davon (ADR-009 Punkt 11).
  v_dokument := v_dokument || jsonb_build_object(
    'invoice_number', v_nummer,
    'issued_on', v_heute,
    'due_on', v_heute + v_frist::integer
  );

  update public.invoices
     set status          = 'issued',
         invoice_number  = v_nummer,
         issued_on       = v_heute,
         issued_at       = now(),
         issued_by       = v_actor,
         due_on          = v_heute + v_frist::integer,
         total_cents     = (v_dokument -> 'totals' ->> 'total_cents')::integer,
         tax_total_cents = (v_dokument -> 'totals' ->> 'tax_total_cents')::integer,
         currency        = v_dokument ->> 'currency',
         snapshot        = v_dokument
   where id = p_invoice_id;

  -- Die Leistung ist ab jetzt abgerechnet; ihr Entfernen laeuft nur noch ueber
  -- Storno (ADR-009 Punkt 9).
  update public.billable_services b
     set status = 'invoiced'
   where b.id in (select it.billable_service_id
                  from public.invoice_items it
                  where it.invoice_id = p_invoice_id);


  return v_nummer;
end;
$$;

COMMENT ON FUNCTION public.issue_invoice(p_invoice_id uuid) IS 'Stellt einen Rechnungsentwurf aus: Par. 14c-Riegel pruefen, Nummer aus dem Kreis des Leistungsbereichs vergeben, Snapshot schreiben, Leistungen auf "invoiced" setzen - in einer Transaktion (ADR-009 Punkte 8 bis 10, 17 und 18). Danach ist die Rechnung unveraenderlich.';

CREATE FUNCTION public.issue_message_attachment_link(p_attachment_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang  public.platform_message_attachments%rowtype;
  v_vorgang public.platform_messages%rowtype;
begin
  if auth.uid() is null or not app.may_read_platform_messages('any') then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;
  select x.* into v_anhang
  from public.platform_message_attachments x
  where x.id = p_attachment_id and x.organization_id = app.current_organization_id();
  if v_anhang.id is null or not app.message_attachment_visible(v_anhang) then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;
  select m.* into v_vorgang from public.platform_messages m where m.id = v_anhang.message_id;
  if not app.can_read_platform_message(v_vorgang.relationship_kind, v_vorgang.topic) then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;

  return query select * from app.grant_message_attachment(v_anhang);
end;
$$;

COMMENT ON FUNCTION public.issue_message_attachment_link(p_attachment_id uuid) IS 'KOM-005 (ADR-017 Punkte 15, 54, 67): einmalige Freigabe fuer genau einen Verweis auf einen Anhang fuer die Praxis - wer den Vorgang lesen darf (app.can_read_platform_message). Kein eigener Auditeintrag: das Oeffnen des Vorgangs steht schon im Protokoll.';

CREATE FUNCTION public.issue_patient_file_link(p_file_id uuid, p_download boolean DEFAULT false) RETURNS TABLE(bucket_id text, object_key text, display_name text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_datei record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = app.current_organization_id()
    and f.status = 'ready';

  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  if not app.can_see_patient_file_type(v_datei.document_type) then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  -- Punkt 36: Ein widerrufenes oder faelliges Foto bekommt keinen Verweis -
  -- auch nicht unter Legal Hold. Dieselbe Meldung wie eine fremde Datei.
  if v_datei.document_type = 'patientenfoto'
     and not app.patient_photo_accessible(
       v_datei.patient_id, v_datei.created_at, v_datei.photo_locked_at
     ) then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  -- ABN-027 (ADR-017 Punkt 55): Herunterladen ist eine eigene Aktion, nicht
  -- fuer die beiden Fotoarten (Punkt 40, ANN-128).
  if coalesce(p_download, false) and app.is_patient_photo_type(v_datei.document_type) then
    raise exception 'photos cannot be downloaded' using errcode = '42501';
  end if;

  -- Protokolliert wird nur das Herunterladen, nicht das Anzeigen (LOG-EPIC-001).
  if coalesce(p_download, false) then
    insert into public.audit_log (
      organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
    )
    values (
      v_datei.organization_id, v_actor, 'patient_file.downloaded', 'patient_file', p_file_id, 'success',
      jsonb_build_object('surface', 'web', 'patient_id', v_datei.patient_id,
                         'document_type', v_datei.document_type)
    );
  end if;

  delete from public.patient_file_access_grants g
   where g.organization_id = v_datei.organization_id
     and g.expires_at <= now();

  -- ANN-052: eine Freigabe, eine Operation, 30 Sekunden.
  insert into public.patient_file_access_grants (
    organization_id, user_id, patient_file_id, expires_at
  )
  values (
    v_datei.organization_id, v_actor, p_file_id, now() + app.patient_file_access_grant_ttl()
  );

  return query
    select app.patient_file_bucket_for(v_datei.document_type), v_datei.object_key,
           v_datei.display_name, v_datei.mime_type;
end;
$$;

COMMENT ON FUNCTION public.issue_patient_file_link(p_file_id uuid, p_download boolean) IS 'Stellt die einmalige Freigabe fuer genau einen Verweis auf genau eine Datei aus und protokolliert sie (ADR-017 Punkte 15, 20, 21). p_download: eigene Aktion Herunterladen mit Kennzeichen im Protokoll, nicht fuer Fotos (Punkt 55).';

CREATE FUNCTION public.issue_platform_file_link(p_access_id uuid, p_file_id uuid) RETURNS TABLE(bucket_id text, object_key text, display_name text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_datei  record;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    raise exception 'file not accessible' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and v_zugang.relationship_kind = 'treatment'
    and f.patient_id = v_zugang.relationship_id
    and f.organization_id = v_zugang.organization_id
    and f.status = 'ready'
    and f.released_at is not null
    and not app.is_patient_photo_type(f.document_type);
  -- Eine fremde, nicht freigegebene und eine nicht vorhandene Datei sehen
  -- gleich aus.
  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  -- BEF-138 (ADR-010 Punkt 22): kein eigener Eintrag fuer den Abruf. Eine
  -- Vertretung liest damit; fuer die Person selbst schreibt der Aufruf nichts.
  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'files')
  );

  delete from public.patient_file_access_grants g
   where g.organization_id = v_datei.organization_id
     and g.expires_at <= now();

  -- ANN-052: eine Freigabe, eine Operation, kurze Frist.
  insert into public.patient_file_access_grants (
    organization_id, user_id, patient_file_id, expires_at
  )
  values (
    v_datei.organization_id, auth.uid(), p_file_id, now() + app.patient_file_access_grant_ttl()
  );

  return query
    select app.patient_file_bucket_for(v_datei.document_type), v_datei.object_key,
           v_datei.display_name, v_datei.mime_type;
end;
$$;

COMMENT ON FUNCTION public.issue_platform_file_link(p_access_id uuid, p_file_id uuid) IS 'POR-014: die einmalige Freigabe fuer genau einen Verweis auf ein freigegebenes Dokument (ADR-017 Punkte 15, 20, 21). Seit BEF-138 ohne eigenen Auditeintrag; eine Vertretung liest (ADR-010 Punkt 22, ADR-023 Punkt 24). Nur Behandlungszugang, nie Fotos.';

CREATE FUNCTION public.issue_platform_message_attachment_link(p_access_id uuid, p_attachment_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.platform_message_attachments%rowtype;
begin
  select x.* into v_anhang
  from app.platform_visible_attachments(p_access_id) x
  where x.id = p_attachment_id;
  -- Fremd, gesperrt, faellig oder nicht vorhanden sehen gleich aus.
  if v_anhang.id is null then
    raise exception 'attachment not accessible' using errcode = '42501';
  end if;

  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'message')
  );

  return query select * from app.grant_message_attachment(v_anhang);
end;
$$;

COMMENT ON FUNCTION public.issue_platform_message_attachment_link(p_access_id uuid, p_attachment_id uuid) IS 'KOM-005 (ADR-017 Punkte 15, 54, 67): einmalige Freigabe fuer genau einen Verweis auf einen eigenen Anhang - Person und rechtliche Vertretung, nie die Begleitung. Kein eigener Auditeintrag; eine Vertretung liest (ADR-023 Punkt 24).';

CREATE FUNCTION public.issue_reimbursement_receipt_link(p_receipt_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_beleg public.staff_reimbursement_receipts%rowtype;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to read reimbursements');
  select b.* into v_beleg
  from public.staff_reimbursement_receipts b
  where b.id = p_receipt_id and b.organization_id = v_org and b.status = 'ready'
    and (b.staff_member_id is not distinct from app.own_staff_member(v_org)
         or (b.reimbursement_id is not null and app.can_read_all_reimbursements()));
  if v_beleg.id is null then
    raise exception 'receipt not found' using errcode = 'P0002';
  end if;

  delete from public.staff_reimbursement_receipt_access_grants g
   where g.organization_id = v_org and g.expires_at <= now();
  insert into public.staff_reimbursement_receipt_access_grants
    (organization_id, user_id, receipt_id, expires_at)
  values (v_org, auth.uid(), v_beleg.id, now() + app.patient_file_access_grant_ttl());

  return query select app.reimbursement_receipt_bucket(), v_beleg.object_key, v_beleg.mime_type;
end;
$$;

COMMENT ON FUNCTION public.issue_reimbursement_receipt_link(p_receipt_id uuid) IS 'ERS-001 (ADR-017 Punkt 15, ANN-052): einmalige Freigabe für genau einen Verweis auf einen Beleg - die eigenen, für owner und Büro die zugeordneten aller. Kein Auditeintrag.';

CREATE FUNCTION public.issue_team_attachment_link(p_attachment_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_staff  uuid;
  v_anhang public.team_message_attachments%rowtype;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  select a.* into v_anhang
  from public.team_message_attachments a
  where a.id = p_attachment_id and a.organization_id = v_org and a.status = 'ready'
    and a.message_id is not null;
  if v_anhang.id is null then
    raise exception 'team attachment not found' using errcode = 'P0002';
  end if;
  -- Gleichzeitiges Löschen wartet auf die Freigabe - oder umgekehrt.
  perform 1 from public.team_messages m
   where m.id = v_anhang.message_id and m.organization_id = v_org for share;
  if (app.team_readable_message(v_anhang.message_id, v_org, v_staff)).id is null then
    raise exception 'team attachment not found' using errcode = 'P0002';
  end if;

  delete from public.team_attachment_access_grants g
   where g.organization_id = v_org and g.expires_at <= now();
  insert into public.team_attachment_access_grants
    (organization_id, user_id, attachment_id, expires_at)
  values (v_org, auth.uid(), v_anhang.id, now() + app.patient_file_access_grant_ttl());

  return query select app.chat_attachment_bucket(), v_anhang.object_key, v_anhang.mime_type;
end;
$$;

COMMENT ON FUNCTION public.issue_team_attachment_link(p_attachment_id uuid) IS 'TEAM-003 (ADR-017 Punkte 15, 76 und 77, ANN-052): einmalige Freigabe für genau einen Verweis auf einen gesendeten Anhang einer lesbaren Nachricht. Kein Auditeintrag (Punkt 78).';

CREATE FUNCTION public.leave_team_channel(p_channel uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not exists (select 1 from public.team_channels c
                 where c.id = p_channel and c.organization_id = v_org and c.kind = 'private')
     or not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  -- Gleichzeitiges Verlassen: einer nach dem anderen.
  perform 1 from public.team_channels where id = p_channel for update;
  delete from public.team_channel_members where channel_id = p_channel and staff_member_id = v_staff;
  perform app.team_forget_channel(p_channel, v_staff);
  if not exists (select 1 from public.team_channel_members m where m.channel_id = p_channel) then
    insert into public.deletion_journal
      (organization_id, run_id, target_table, target_id, retention_class, due_at, deleted_at)
    values (v_org, md5('team_manual:' || v_org::text || ':' || current_date::text)::uuid,
            'team_channels', p_channel, 'teamchat', date_trunc('day', now()), date_trunc('day', now()));
    delete from public.team_channels where id = p_channel;
  end if;
end;
$$;

CREATE FUNCTION public.link_exercise_variants(p_easier_variant_id uuid, p_harder_variant_id uuid, p_axis text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_id    uuid;
begin
  v_org := app.exercise_library_writer();

  if p_axis is null or not (p_axis = any (app.exercise_axes())) then
    raise exception 'axis is invalid' using errcode = '22023';
  end if;
  if p_easier_variant_id is null or p_harder_variant_id is null then
    raise exception 'exercise variant not found' using errcode = 'P0002';
  end if;
  if p_easier_variant_id = p_harder_variant_id then
    raise exception 'variant cannot be linked to itself' using errcode = '22023';
  end if;

  -- Beide Varianten in dieser Praxis; eine fremde und eine nicht vorhandene
  -- sehen gleich aus.
  if (
    select count(*) from public.exercise_variants v
    where v.id in (p_easier_variant_id, p_harder_variant_id) and v.organization_id = v_org
  ) <> 2 then
    raise exception 'exercise variant not found' using errcode = 'P0002';
  end if;

  -- Archiviert ist auch eine Variante, deren Uebung archiviert ist: Beide
  -- stehen nicht mehr in der Bibliothek (ANN-296).
  if exists (
    select 1
    from public.exercise_variants v
    join public.exercises e on e.id = v.exercise_id
    where v.id in (p_easier_variant_id, p_harder_variant_id)
      and (v.archived_at is not null or e.archived_at is not null)
  ) then
    raise exception 'archived variant cannot be linked' using errcode = '22023';
  end if;

  -- Zwei gleichzeitige Verbindungen koennten zusammen einen Kreis schliessen,
  -- den jede fuer sich nicht sieht: je Praxis nacheinander.
  perform pg_advisory_xact_lock(hashtextextended('exercise_variant_links:' || v_org::text, 0));

  if exists (
    select 1 from public.exercise_variant_links l
    where least(l.easier_variant_id, l.harder_variant_id)
            = least(p_easier_variant_id, p_harder_variant_id)
      and greatest(l.easier_variant_id, l.harder_variant_id)
            = greatest(p_easier_variant_id, p_harder_variant_id)
  ) then
    raise exception 'variants are already linked' using errcode = '23505';
  end if;

  -- Kein Kreis: Fuehrt von der schwereren schon ein Weg zur leichteren, waere
  -- die leichtere zugleich schwerer.
  if exists (
    with recursive schwerer_als(variante) as (
      select p_harder_variant_id
      union
      select l.harder_variant_id
      from public.exercise_variant_links l
      join schwerer_als s on s.variante = l.easier_variant_id
      where l.organization_id = v_org
    )
    select 1 from schwerer_als where variante = p_easier_variant_id
  ) then
    raise exception 'link would form a cycle' using errcode = '22023';
  end if;

  insert into public.exercise_variant_links (
    organization_id, easier_variant_id, harder_variant_id, axis, created_by
  )
  values (v_org, p_easier_variant_id, p_harder_variant_id, p_axis, v_actor)
  returning id into v_id;

  return v_id;
exception
  when unique_violation then
    raise exception 'variants are already linked' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.link_exercise_variants(p_easier_variant_id uuid, p_harder_variant_id uuid, p_axis text) IS 'UEB-002: verbindet zwei Varianten von der leichteren zur schwereren entlang einer Achse (ANN-294); hoechstens eine Verbindung je Paar, kein Kreis, keine archivierte Variante. Nur nach app.can_manage_exercise_library().';

CREATE FUNCTION public.list_appointments(p_from date, p_to date, p_staff_member_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'active'::text) RETURNS TABLE(id uuid, patient_id uuid, staff_member_id uuid, location_id uuid, appointment_type text, kind text, title text, status text, starts_at timestamp with time zone, ends_at timestamp with time zone, patient_given_name text, patient_family_name text, staff_given_name text, staff_family_name text, location_name text, training_relationship_id uuid, training_given_name text, training_family_name text, documentation_status text, visit_street text, visit_house_number text, occasion text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_tz    text;
  v_start timestamptz;
  v_end   timestamptz;
  -- Zyklen 2-4: wer den Bearbeitungsstand sehen darf (wie list_day_plan).
  v_darf_nachweis boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- TRN-006: Der Kalender ist auch der Trainingsbetreuung offen; welche
  -- Zeilen sie sieht, entscheidet weiter der Kontext (ADR-022 Punkt 11).
  if not app.can_read_calendar() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_from is null or p_to is null then
    raise exception 'from and to are required' using errcode = '22023';
  end if;

  if p_to <= p_from then
    raise exception 'to must be after from' using errcode = '22023';
  end if;

  if p_to - p_from > 31 then
    raise exception 'requested range is too large' using errcode = '22023';
  end if;

  if p_status is null
     or p_status not in (
       'confirmed', 'cancelled', 'no_show', 'completed', 'documented', 'invoiced',
       'active', 'done', 'all'
     ) then
    raise exception 'unknown status filter' using errcode = '22023';
  end if;

  select o.time_zone into v_tz
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  v_darf_nachweis := app.can_read_treatment_note();

  v_start := (p_from::timestamp) at time zone v_tz;
  v_end   := (p_to::timestamp)   at time zone v_tz;

  return query
    select
      a.id,
      a.patient_id,
      a.staff_member_id,
      a.location_id,
      a.appointment_type,
      a.kind,
      a.title,
      a.status,
      a.starts_at,
      a.ends_at,
      pp.given_name,
      pp.family_name,
      sp.given_name,
      sp.family_name,
      l.name,
      a.training_relationship_id,
      tp.given_name,
      tp.family_name,
      -- Zyklen 2-4: der Stand des Haupteintrags, nur am Behandlungstermin.
      -- ERN-011: Die Ernaehrungsberatung kennt keine Behandlungsdoku.
      case when v_darf_nachweis and a.kind = 'therapy' and a.occasion = 'regular'
           then coalesce(t.status, 'none') end,
      -- UBK-017, ANN-242: Strasse und Hausnummer am Hausbesuch - wer die
      -- Zeile sieht, sieht wohin; Postleitzahl und Ort bleiben am Termin.
      case when a.appointment_type = 'home_visit' then a.visit_street end,
      case when a.appointment_type = 'home_visit' then a.visit_house_number end,
      -- ERN-011 (ANN-664): der Anlass, ohne Inhalt der Beratung.
      a.occasion
    from public.appointments a
    left join public.patients p  on p.id  = a.patient_id
    left join public.persons pp  on pp.id = p.person_id
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    left join public.locations l on l.id  = a.location_id
    -- TRN-006: der Name am Trainingstermin kommt ueber das Verhaeltnis, nie
    -- ueber die Akte (ADR-021 Punkt 3).
    left join public.training_relationships tr on tr.id = a.training_relationship_id
    left join public.persons tp                on tp.id = tr.person_id
    -- Zyklen 2-4: nur der Haupteintrag (ADR-016 Punkt 6).
    left join public.treatment_notes t
           on t.appointment_id = a.id
          and t.addendum_to_note_id is null
    where a.organization_id = v_org
      and app.may_read_appointment_context(a.kind)
      and a.starts_at >= v_start
      and a.starts_at <  v_end
      and (p_staff_member_id is null or a.staff_member_id = p_staff_member_id)
      and (p_location_id     is null or a.location_id     = p_location_id)
      and (
        p_status = 'all'
        or (p_status = 'active' and a.status <> 'cancelled')
        or (p_status = 'done'   and a.status in ('completed', 'documented', 'invoiced'))
        or a.status = p_status
      )
    order by a.starts_at, sp.family_name, sp.given_name, a.id;
end;
$$;

COMMENT ON FUNCTION public.list_appointments(p_from date, p_to date, p_staff_member_id uuid, p_location_id uuid, p_status text) IS 'Liefert die Termine der eigenen Organisation in einem begrenzten Zeitfenster fuer die Kalenderansichten, Behandlungen wie Ereignisse (CAL-002, CAL-004, CAL-008a, CAL-015b), seit TRN-006 auch fuer die Trainingsbetreuung - je Zeile nach Kontext gefiltert (ADR-022 Punkt 11), am Trainingstermin mit Verhaeltnis und Namen. Seit dem UI-Redesign Zyklen 2-4 mit dem Bearbeitungsstand der Dokumentation (documentation_status) am Behandlungstermin, nur fuer Rollen mit app.can_read_treatment_note(). Seit UBK-017 am Hausbesuch mit Strasse und Hausnummer (ANN-242). Seit ERN-011 mit dem Anlass (occasion, ANN-665); an der Ernaehrungsberatung ohne Dokumentationsstand.';

CREATE FUNCTION public.list_assignable_therapists() RETURNS TABLE(staff_member_id uuid, display_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_create_appointment() then
    raise exception 'not allowed to plan appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to plan appointments' using errcode = '42501';
  end if;

  return query
    select sm.id, pe.given_name || ' ' || pe.family_name
    from public.staff_members sm
    join public.persons pe on pe.id = sm.person_id
    where sm.organization_id = v_org
      and app.is_assignable_therapist(sm.id, v_org)
    order by pe.family_name, pe.given_name;
end;
$$;

COMMENT ON FUNCTION public.list_assignable_therapists() IS 'Liefert die als behandelnde Person zuordenbaren Mitarbeitenden der eigenen Organisation (CAL-001).';

CREATE FUNCTION public.list_assignable_trainers() RETURNS TABLE(staff_member_id uuid, display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_training_relationships() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to plan training appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to plan training appointments' using errcode = '42501';
  end if;

  return query
    select sm.id, pe.given_name || ' ' || pe.family_name
    from public.staff_members sm
    join public.persons pe on pe.id = sm.person_id
    where sm.organization_id = v_org
      and app.is_assignable_trainer(sm.id, v_org)
    order by pe.family_name, pe.given_name;
end;
$$;

COMMENT ON FUNCTION public.list_assignable_trainers() IS 'TRN-004: Auswahl fuer die betreuende Person eines Trainingstermins. owner, trainer, office; abgewiesen mit denied unter appointments.read.';

CREATE FUNCTION public.list_audit_events(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_user_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, occurred_at timestamp with time zone, actor_user_id uuid, actor_kind text, actor_display_name text, action text, subject_type text, subject_id uuid, outcome text, denied_operation text, denied_count integer, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_limit  integer;
  v_offset integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Rolle und Organisation werden hier geprueft, weil SECURITY DEFINER die
  -- RLS umgeht. Ohne diese Pruefung waere die Funktion ein offener Kanal.
  -- OPS-004: Abgewiesen wird mit null Zeilen und einem Auditeintrag, nicht
  -- mit einer Ausnahme - die rollte den Eintrag mit zurueck.
  if not app.has_any_role('owner') then
    perform app.record_denied_owner_read(v_actor, 'audit_log.read', 'audit log access denied');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'audit log access denied' using errcode = '42501';
  end if;

  v_limit  := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_offset := greatest(coalesce(p_offset, 0), 0);

  return query
  select
    a.id,
    a.occurred_at,
    a.actor_user_id,
    a.actor_kind,
    up.display_name,
    a.action,
    a.subject_type,
    a.subject_id,
    a.outcome,
    case when a.action = 'access.denied' then a.context ->> 'operation' end,
    case when a.action = 'access.denied' then coalesce((a.context ->> 'count')::integer, 1) end,
    count(*) over () as total_count
  from public.audit_log a
  left join public.user_profiles up
    on up.id = a.actor_user_id
   and up.organization_id = v_org
  where a.organization_id = v_org
    and (p_from is null          or a.occurred_at >= p_from)
    and (p_to is null            or a.occurred_at <  p_to)
    and (p_actor_user_id is null or a.actor_user_id = p_actor_user_id)
    and (p_action is null        or a.action = p_action)
  order by a.occurred_at desc, a.id desc
  limit v_limit offset v_offset;

  -- Das Lesen des Protokolls wird nicht protokolliert (ADR-010 Fassung 3).
end;
$$;

COMMENT ON FUNCTION public.list_audit_events(p_from timestamp with time zone, p_to timestamp with time zone, p_actor_user_id uuid, p_action text, p_limit integer, p_offset integer) IS 'Liest das Auditlog der eigenen Organisation, nur owner (ADR-010 Punkt 13). Ohne context; fuer access.denied nur Operation und Zaehler. Das Lesen selbst wird nicht protokolliert (LOG-EPIC-001).';

CREATE FUNCTION public.list_billable_services(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, appointment_id uuid, patient_id uuid, training_relationship_id uuid, service_area text, patient_name text, performed_on date, code text, label text, item_kind text, quantity smallint, unit_price_cents integer, currency text, tax_treatment text, tax_rate_permille smallint, status text, session_fee boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_billable_services() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'billable_services.read', 'not allowed to read billable services');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select b.id, b.appointment_id, b.patient_id, b.training_relationship_id, b.service_area,
         pe.given_name || ' ' || pe.family_name,
         b.performed_on, i.code, i.label, i.item_kind, b.quantity,
         -- ABR-031: Betrag je Einheit. Im Terminhonorar ist das der Anteil
         -- der Position am Honorar (Menge 1), sonst der Katalogpreis.
         (app.billable_service_amount(b.id) / b.quantity)::integer,
         i.currency, i.tax_treatment, i.tax_rate_permille,
         b.status,
         exists (select 1 from public.appointment_session_fees f
                 where f.appointment_id = b.appointment_id and i.remedy is not null)
  from public.billable_services b
  join public.service_catalog_items i on i.id = b.catalog_item_id
  left join public.patients p on p.id = b.patient_id
  left join public.training_relationships t on t.id = b.training_relationship_id
  join public.persons pe on pe.id = coalesce(p.person_id, t.person_id)
  where b.organization_id = v_org
    and (p_from is null or b.performed_on >= p_from)
    and (p_to   is null or b.performed_on <= p_to)
  order by b.performed_on desc, pe.family_name, i.code
  limit greatest(least(coalesce(p_limit, 200), 500), 1);
end;
$$;

COMMENT ON FUNCTION public.list_billable_services(p_from date, p_to date, p_limit integer) IS 'Erfasste Leistungen mit Kuerzel, Menge, Betrag je Einheit, Steuerkennzeichen und Bereich (ABR-002, TRN-007). Seit ABR-031 ist der Betrag einer Position im Terminhonorar ihr Anteil daran (session_fee = true), sonst der Katalogpreis. Der Name kommt aus dem Verhaeltnis der Leistung.';

CREATE FUNCTION public.list_busy_blocks(p_from date, p_to date, p_staff_member_id uuid DEFAULT NULL::uuid) RETURNS TABLE(staff_member_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_tz    text;
  v_start timestamptz;
  v_end   timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_calendar() then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;
  if p_from is null or p_to is null then
    raise exception 'from and to are required' using errcode = '22023';
  end if;
  if p_to <= p_from then
    raise exception 'to must be after from' using errcode = '22023';
  end if;
  if p_to - p_from > 31 then
    raise exception 'requested range is too large' using errcode = '22023';
  end if;

  -- Wer jeden Termin lesen darf, braucht keinen anonymen Block.
  if app.is_staff() then
    return;
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_start := (p_from::timestamp) at time zone v_tz;
  v_end   := (p_to::timestamp)   at time zone v_tz;

  return query
    with zeiten as (
      select a.staff_member_id as person, tstzrange(a.starts_at, a.ends_at, '[)') as zeit
      from public.appointments a
      where a.organization_id = v_org
        and not app.may_read_appointment_context(a.kind)
        and a.status <> 'cancelled'
        and a.starts_at < v_end
        and a.ends_at > v_start
        and (p_staff_member_id is null or a.staff_member_id = p_staff_member_id)
        and app.is_assignable_trainer(a.staff_member_id, v_org)
    ),
    verschmolzen as (
      select z.person, range_agg(z.zeit) as zeiten from zeiten z group by z.person
    )
    select v.person, lower(u.zeit), upper(u.zeit)
    from verschmolzen v
    cross join lateral unnest(v.zeiten) as u(zeit)
    order by 1, 2;
end;
$$;

COMMENT ON FUNCTION public.list_busy_blocks(p_from date, p_to date, p_staff_member_id uuid) IS 'Anonyme Belegt-Bloecke fuer die Trainingsbetreuung (ABN-021, BEF-112, ANN-180 Fassung 2): genau Person, Beginn, Ende - verschmolzen, ohne Kontext, Namen, Adresse oder Zustand. Praxisrollen bekommen nichts. Fenster hoechstens 31 Tage wie list_appointments.';

CREATE FUNCTION public.list_call_list(p_date date) RETURNS TABLE(appointment_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, location_name text, staff_name text, patient_id uuid, patient_given_name text, patient_family_name text, phone text, phone_mobile text, notified_channels text[], call_outcome text, call_attempts smallint, call_recorded_at timestamp with time zone, call_recorded_by_name text, organization_time_zone text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_tz  text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_update_appointment() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read the call list');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read the call list' using errcode = '42501';
  end if;
  if p_date is null then
    raise exception 'date required' using errcode = '22023';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;

  return query
  select a.id,
         a.starts_at,
         a.ends_at,
         a.appointment_type,
         l.name,
         nullif(btrim(concat_ws(' ', spe.given_name, spe.family_name)), ''),
         a.patient_id,
         pe.given_name,
         pe.family_name,
         cd.phone,
         cd.phone_mobile,
         app.appointment_notification_channels(a.id),
         c.outcome,
         c.attempts,
         c.recorded_at,
         nullif(btrim(concat_ws(' ', rpe.given_name, rpe.family_name)), ''),
         v_tz
  from public.appointments a
  join public.patients pa on pa.id = a.patient_id
  join public.persons pe on pe.id = pa.person_id
  left join public.patient_contact_details cd on cd.patient_id = a.patient_id
  left join public.locations l on l.id = a.location_id
  left join public.staff_members sm on sm.id = a.staff_member_id
  left join public.persons spe on spe.id = sm.person_id
  left join public.appointment_call_states c on c.appointment_id = a.id
  left join public.user_profiles rup on rup.id = c.recorded_by
  left join public.persons rpe on rpe.id = rup.person_id
  where a.organization_id = v_org
    and a.kind = 'therapy'
    and a.status = 'confirmed'
    and (a.starts_at at time zone v_tz)::date = p_date
  order by a.starts_at, pe.family_name, a.id;
end;
$$;

COMMENT ON FUNCTION public.list_call_list(p_date date) IS 'Anrufliste eines Tages (PRX-014): bestaetigte Behandlungstermine mit Person, Rufnummern, gueltigen Mitteilungswegen und Anrufstand. Rollen wie der Mitteilungsvermerk; ein abgewiesener Versuch wird als appointments.read protokolliert. Das Lesen selbst ist wie der Kalender nicht auditiert.';

CREATE FUNCTION public.list_care_without_conclusion() RETURNS TABLE(patient_id uuid, patient_given_name text, patient_family_name text, last_appointment_at timestamp with time zone, patient_created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_conclude_patient_care() then
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read care without conclusion');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read care without conclusion' using errcode = '42501';
  end if;

  return query
  select pa.id,
         pe.given_name,
         pe.family_name,
         letzter.zeit,
         pa.created_at
  from public.patients pa
  join public.persons pe on pe.id = pa.person_id
  cross join lateral (
    select max(a.starts_at) as zeit
    from public.appointments a
    where a.patient_id = pa.id
      and a.organization_id = v_org
      and a.kind = 'therapy'
      and a.status <> 'cancelled'
  ) letzter
  where pa.organization_id = v_org
    -- Ohne jede Behandlung, Leistung und ohne Abschluss: kein Anker (ANN-511).
    and app.patient_retention_anchor(pa.id) is null
    and not app.patient_has_upcoming_care(pa.id)
    -- Der letzte Termin liegt lange zurueck; ohne Termin zaehlt die Anlage.
    and coalesce(letzter.zeit, pa.created_at) < now() - app.reminder_care_idle()
  order by coalesce(letzter.zeit, pa.created_at) asc, pe.family_name, pa.id;
end;
$$;

COMMENT ON FUNCTION public.list_care_without_conclusion() IS 'B1 (ANN-511, Zweitreview A): Akten ohne jede Behandlung, Leistung und ohne Abschluss - also ohne Fristanker -, seit sechs Monaten ohne Termin und ohne kommenden. Fragt nur; der Abschluss in den Stammdaten setzt den Anker (ADR-008 Punkt 3). Rollen, die abschliessen duerfen; ein abgewiesener Versuch wird als patient_directory.read protokolliert.';

CREATE FUNCTION public.list_day_plan(p_date date, p_staff_member_id uuid) RETURNS TABLE(id uuid, patient_id uuid, staff_member_id uuid, appointment_type text, kind text, title text, status text, starts_at timestamp with time zone, ends_at timestamp with time zone, patient_given_name text, patient_family_name text, location_name text, visit_street text, visit_house_number text, visit_postal_code text, visit_city text, patient_phone text, patient_phone_mobile text, home_visit_access_note text, special_note text, documentation_status text, organization_time_zone text, visit_lat double precision, visit_lon double precision, treatment_table_required boolean, take_along_items text[], training_relationship_id uuid, training_given_name text, training_family_name text, checked_at timestamp with time zone, occasion text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org           uuid;
  v_tz            text;
  v_start         timestamptz;
  v_end           timestamptz;
  v_darf_nachweis boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft. Derselbe Schnitt wie beim Kalender: die Tagesliste ist eine
  -- andere Darstellung derselben Termine, kein zweites Recht.
  -- TRN-006: Der Kalender ist auch der Trainingsbetreuung offen; welche
  -- Zeilen sie sieht, entscheidet weiter der Kontext (ADR-022 Punkt 11).
  if not app.can_read_calendar() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_date is null or p_staff_member_id is null then
    raise exception 'date and staff member are required' using errcode = '22023';
  end if;

  select o.time_zone into v_tz
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  -- Halboffenes Fenster [Tag 00:00, Folgetag 00:00) in der Zeitzone der Praxis
  -- - dieselbe Auslegung wie in list_appointments und create_appointment.
  v_start := (p_date::timestamp) at time zone v_tz;
  v_end   := ((p_date + 1)::timestamp) at time zone v_tz;

  v_darf_nachweis := app.can_read_treatment_note();

  return query
    select
      a.id,
      a.patient_id,
      a.staff_member_id,
      a.appointment_type,
      a.kind,
      a.title,
      a.status,
      a.starts_at,
      a.ends_at,
      pp.given_name,
      pp.family_name,
      l.name,
      a.visit_street,
      a.visit_house_number,
      a.visit_postal_code,
      a.visit_city,
      pc.phone,
      pc.phone_mobile,
      -- Zweckbindung: der Zugangshinweis beschreibt die Wohnungstuer. Zu
      -- einem Praxis- oder Videotermin hat er keinen Zweck.
      case when a.appointment_type = 'home_visit' then care.home_visit_access_note end,
      case when a.appointment_type = 'home_visit' then care.special_note end,
      -- ANN-006: Dokumentationsstand ohne Inhalt. Leer, wenn die Rolle den
      -- Behandlungsnachweis nicht lesen darf - eine falsche Angabe waere
      -- schlimmer als keine. An einem Ereignis ebenfalls leer: Dort gibt es
      -- keine Dokumentation, und 'none' hiesse "fehlt noch" (CAL-016). Am
      -- Trainingstermin gilt dasselbe, und zwar dauerhaft (ADR-022 Punkt 6).
      -- ERN-011: Die Ernaehrungsberatung kennt keine Behandlungsdoku.
      case when v_darf_nachweis and a.kind = 'therapy' and a.occasion = 'regular'
           then coalesce(t.status, 'none') end,
      v_tz,
      -- MAP-006d: die Kartenposition des Hausbesuchs fuer den Handoff (ANN-018).
      a.visit_lat,
      a.visit_lon,
      -- UX-003b: Behandlungsliege nur am Behandlungstermin (ANN-116).
      case when a.kind = 'therapy' then coalesce(care.treatment_table_required, false) end,
      -- PRX-007: Mitnehmen nur am Behandlungstermin (ANN-138).
      case when a.kind = 'therapy' then coalesce(care.take_along_items, '{}'::text[]) end,
      a.training_relationship_id,
      tp.given_name,
      tp.family_name,
      -- B4 (BEF-154, ADR-018 Fassung 5): der Haken als eigenes Merkmal. Ein
      -- dokumentierter Termin ist nicht von selbst abgehakt.
      a.completed_at,
      -- ERN-011 (ANN-664): der Anlass.
      a.occasion
    from public.appointments a
    left join public.patients p        on p.id  = a.patient_id
    left join public.persons pp        on pp.id = p.person_id
    left join public.locations l  on l.id  = a.location_id
    left join public.patient_contact_details pc on pc.patient_id = a.patient_id
    left join public.patient_care_details care  on care.patient_id = a.patient_id
    left join public.treatment_notes t
           on t.appointment_id = a.id
          and t.addendum_to_note_id is null
    -- TRN-006: der Name am Trainingstermin kommt ueber das Verhaeltnis, nie
    -- ueber die Akte (ADR-021 Punkt 3).
    left join public.training_relationships tr on tr.id = a.training_relationship_id
    left join public.persons tp                on tp.id = tr.person_id
    where a.organization_id  = v_org
      and app.may_read_appointment_context(a.kind)
      and a.staff_member_id  = p_staff_member_id
      and a.starts_at       >= v_start
      and a.starts_at        < v_end
    order by a.starts_at, a.id;
end;
$$;

COMMENT ON FUNCTION public.list_day_plan(p_date date, p_staff_member_id uuid) IS 'Tagesliste einer Person (UX-001, TRN-006, ABN-005); seit B4 mit checked_at - dem Haken als eigenem Merkmal neben dem Zustand (ADR-018 Fassung 5); seit ERN-011 mit dem Anlass (occasion), an der Ernaehrungsberatung ohne Dokumentationsstand.';

CREATE FUNCTION public.list_day_route(p_date date, p_staff_member_id uuid) RETURNS TABLE(id uuid, kind text, appointment_type text, status text, starts_at timestamp with time zone, ends_at timestamp with time zone, lat double precision, lon double precision, geocode_precision text, position_source text, address_outdated boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_tz    text;
  v_start timestamptz;
  v_end   timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_date is null or p_staff_member_id is null then
    raise exception 'date and staff member are required' using errcode = '22023';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  v_start := (p_date::timestamp) at time zone v_tz;
  v_end   := ((p_date + 1)::timestamp) at time zone v_tz;

  return query
    with stopps as (
      select
        a.*,
        l.lat as ort_lat,
        l.lon as ort_lon,
        l.geocode_precision as ort_precision,
        -- ANN-236: dieselbe Regel wie list_home_visits_with_outdated_address.
        coalesce(
          a.kind = 'therapy'
          and a.appointment_type = 'home_visit'
          and a.status = 'confirmed'
          and a.starts_at > now()
          and nullif(btrim(c.street), '')       is not null
          and nullif(btrim(c.house_number), '') is not null
          and nullif(btrim(c.postal_code), '')  is not null
          and nullif(btrim(c.city), '')         is not null
          and (a.visit_street, a.visit_house_number, a.visit_postal_code, a.visit_city)
              is distinct from
              (nullif(btrim(c.street), ''), nullif(btrim(c.house_number), ''),
               nullif(btrim(c.postal_code), ''), nullif(btrim(c.city), '')),
          false
        ) as veraltet
      from public.appointments a
      left join public.locations l on l.id = a.location_id and l.organization_id = v_org
      left join public.patient_contact_details c
        on c.patient_id = a.patient_id and c.organization_id = v_org
      where a.organization_id = v_org
        and app.may_read_appointment_context(a.kind)
        and a.kind in ('therapy', 'training')
        and a.appointment_type in ('home_visit', 'practice')
        and a.status <> 'cancelled'
        and a.staff_member_id = p_staff_member_id
        and a.starts_at >= v_start
        and a.starts_at <  v_end
    )
    select
      s.id,
      s.kind,
      s.appointment_type,
      s.status,
      s.starts_at,
      s.ends_at,
      case when s.veraltet then null
           when s.appointment_type = 'home_visit' then s.visit_lat else s.ort_lat end,
      case when s.veraltet then null
           when s.appointment_type = 'home_visit' then s.visit_lon else s.ort_lon end,
      case when s.veraltet then null
           when s.appointment_type = 'home_visit' then s.visit_geocode_precision
           else s.ort_precision end,
      case s.appointment_type when 'home_visit' then 'visit' else 'location' end,
      s.veraltet
    from stopps s
    order by s.starts_at, s.id;
end;
$$;

COMMENT ON FUNCTION public.list_day_route(p_date date, p_staff_member_id uuid) IS 'MAP-006b, UBK-007: Stopps der Tagesroute einer Person - Kennung, Zeit, Zustand und Koordinate, ohne Namen und ohne Adresse; address_outdated, wenn ein kuenftiger Hausbesuch noch eine andere Anschrift traegt als die Akte, dann ohne Koordinate (ANN-236). Rechte wie list_day_plan; abgewiesen mit denied-Eintrag (G6b).';

CREATE FUNCTION public.list_deletion_runs(p_limit integer DEFAULT 50) RETURNS TABLE(run_id uuid, deleted_at timestamp with time zone, retention_class text, target_table text, record_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_limit integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Derselbe Schnitt wie beim Auditlog: das Loeschjournal ist ein Nachweis der
  -- Praxisleitung (ADR-010, PROJECT_PRINCIPLES.md 4.1). Abgewiesen wird wie
  -- dort mit null Zeilen und einem Auditeintrag (OPS-004).
  if not app.has_any_role('owner') then
    perform app.record_denied_owner_read(v_actor, 'deletion_runs.read', 'deletion journal access denied');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'deletion journal access denied' using errcode = '42501';
  end if;

  v_limit := least(greatest(coalesce(p_limit, 50), 1), 200);

  return query
    select j.run_id,
           max(j.deleted_at) as deleted_at,
           j.retention_class,
           j.target_table,
           count(*) as record_count
    from public.deletion_journal j
    where j.organization_id = v_org
    group by j.run_id, j.retention_class, j.target_table
    order by max(j.deleted_at) desc, j.retention_class, j.target_table
    limit v_limit;
end;
$$;

COMMENT ON FUNCTION public.list_deletion_runs(p_limit integer) IS 'Zusammenfassung der Loeschlaeufe fuer die Aufbewahrungsuebersicht: je Lauf, Datenklasse und Tabelle eine Zahl (LOE-002a). Nur owner, nur eigene Organisation.';

CREATE FUNCTION public.list_due_aftercare_months() RETURNS TABLE(subscription_id uuid, patient_id uuid, patient_name text, month_start date, month_end date, unit_price_cents integer, currency text, blocker text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    perform app.record_denied_read(auth.uid(), 'aftercare.read', 'not allowed to read aftercare months');
    return;
  end if;
  v_org := app.current_organization_id();
  v_heute := app.training_today(v_org);

  return query
  select s.id,
         s.patient_id,
         pe.given_name || ' ' || pe.family_name,
         m.beginn,
         app.aftercare_month_end(s.starts_on, m.n),
         preis.unit_price_cents,
         preis.currency,
         app.aftercare_month_blocker(s.id, m.beginn)
  from public.aftercare_subscriptions s
  join public.patients p on p.id = s.patient_id
  join public.persons pe on pe.id = p.person_id
  cross join lateral (
    select g.n, app.aftercare_month_start(s.starts_on, g.n) as beginn
    from generate_series(0, least(app.aftercare_month_index(s.starts_on, v_heute), 119)) g(n)
  ) m
  left join lateral app.aftercare_month_price(v_org, m.beginn) preis on true
  where s.organization_id = v_org
    and (s.ends_on is null or m.beginn <= s.ends_on)
    and not exists (
      select 1 from public.billable_services b
      where b.aftercare_subscription_id = s.id and b.performed_on = m.beginn
    )
  order by m.beginn, pe.family_name, s.id
  limit 200;
end;
$$;

COMMENT ON FUNCTION public.list_due_aftercare_months() IS 'ANG-002: Abo-Monate, die begonnen haben und noch keine Leistung tragen, mit Preis und gegebenenfalls dem Grund, warum sie nicht erfasst werden koennen (owner, office).';

CREATE FUNCTION public.list_due_exercise_plans() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    perform app.record_denied_read(v_actor, 'exercise_plans.read', 'not allowed to read exercise plans');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read exercise plans' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'today', app.training_today(v_org),
    'plans', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', p.id,
          'service_area', p.service_area,
          'relationship_id', coalesce(p.patient_id, p.training_relationship_id),
          'given_name', pe.given_name,
          'family_name', pe.family_name,
          'title', p.title,
          'runs_until', p.runs_until,
          'follow_up_draft', exists (
            select 1 from public.exercise_plans f
            where f.previous_plan_id = p.id and f.status = 'draft'
          )
        )
        order by p.runs_until, pe.family_name, pe.given_name, p.id
      )
      from public.exercise_plans p
      left join public.patients pa on pa.id = p.patient_id
      left join public.training_relationships t on t.id = p.training_relationship_id
      join public.persons pe on pe.id = coalesce(pa.person_id, t.person_id)
      where p.organization_id = v_org
        and app.can_write_exercise_plans(p.service_area)
        and app.exercise_plan_review_due(p)
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.list_due_exercise_plans() IS 'UEB-007: die Plaene, deren Wiedervorlage ansteht (ANN-302) - je Bereich nur fuer die Rollen, die ihn schreiben (ANN-298), nach dem Ende sortiert. Andere Rollen: null und access.denied.';

CREATE FUNCTION public.list_ending_prescriptions() RETURNS TABLE(treatment_basis_id uuid, patient_id uuid, patient_given_name text, patient_family_name text, treatment_basis_kind text, issued_on date, prescribed integer, used integer, planned integer, last_appointment_at timestamp with time zone, has_recommendation boolean, prescriber_name text, prescriber_phone text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_treatment_bases() then
    perform app.record_denied_read(auth.uid(), 'treatment_bases.read', 'not allowed to read ending prescriptions');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read ending prescriptions' using errcode = '42501';
  end if;

  return query
  select k.treatment_basis_id,
         k.patient_id,
         pe.given_name,
         pe.family_name,
         k.treatment_basis_kind,
         k.issued_on,
         k.prescribed,
         k.used,
         k.planned,
         k.last_appointment_at,
         (k.follow_up_recommendation is not null or exists (
           select 1 from public.therapy_reports r
           where r.treatment_basis_id = k.treatment_basis_id
             and r.organization_id = v_org
             and r.recommendation is not null
         )),
         nullif(btrim(concat_ws(' ', pr.title, pr.given_name, pr.family_name)), ''),
         pr.phone
  from app.ending_treatment_bases(v_org) k
  join public.patients pa on pa.id = k.patient_id
  join public.persons pe on pe.id = pa.person_id
  left join public.prescribers pr on pr.id = k.prescriber_id
  order by k.last_appointment_at asc nulls first, pe.family_name, k.treatment_basis_id;
end;
$$;

COMMENT ON FUNCTION public.list_ending_prescriptions() IS 'Verordnungen ohne Anschluss, deren Kontingent genutzt oder ganz verplant ist und deren letzter Termin in den naechsten vierzehn Tagen liegt (PRX-016, ANN-146), mit Empfehlung ja/nein und Kontakt der Verordner:in. Fragt nur, setzt nichts. Die vier Praxisrollen; ein abgewiesener Versuch wird als treatment_bases.read protokolliert.';

CREATE FUNCTION public.list_event_participants(p_event_group_id uuid) RETURNS TABLE(appointment_id uuid, staff_member_id uuid, display_name text, status text, group_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_stand timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_event_group_id is null then
    raise exception 'event is required' using errcode = '22023';
  end if;

  select max(a.updated_at) into v_stand
  from public.appointments a
  where a.organization_id = v_org
    and a.event_group_id  = p_event_group_id
    and a.kind = 'internal';

  return query
    select a.id, a.staff_member_id,
           pp.given_name || ' ' || pp.family_name,
           a.status,
           v_stand
    from public.appointments a
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons pp       on pp.id = sm.person_id
    where a.organization_id = v_org
      and a.event_group_id  = p_event_group_id
      and a.kind = 'internal'
    order by pp.family_name, pp.given_name;
end;
$$;

COMMENT ON FUNCTION public.list_event_participants(p_event_group_id uuid) IS 'Beteiligte EINES Ereignisses mit Anzeigename und Zustand ihrer Teilnahme, dazu der juengste Stand der Gruppe (CAL-017). Kein klinischer Inhalt, kein Patientenbezug.';

CREATE FUNCTION public.list_event_series(p_event_series_id uuid) RETURNS TABLE(event_group_id uuid, title text, starts_at timestamp with time zone, ends_at timestamp with time zone, open_count integer, cancelled_count integer, series_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_stand timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_event_series_id is null then
    raise exception 'event series is required' using errcode = '22023';
  end if;

  select max(a.updated_at) into v_stand
  from public.appointments a
  where a.organization_id = v_org
    and a.event_series_id = p_event_series_id;

  return query
    select a.event_group_id,
           min(a.title),
           min(a.starts_at),
           max(a.ends_at),
           count(*) filter (where a.status <> 'cancelled')::integer,
           count(*) filter (where a.status =  'cancelled')::integer,
           v_stand
    from public.appointments a
    where a.organization_id = v_org
      and a.event_series_id = p_event_series_id
    group by a.event_group_id
    order by min(a.starts_at);
end;
$$;

COMMENT ON FUNCTION public.list_event_series(p_event_series_id uuid) IS 'Die Vorkommen EINER Serie gleichartiger Ereignisse mit Zeit, Bezeichnung und Zustand, dazu der juengste Stand der Serie (CAL-021). Kein klinischer Inhalt, kein Patientenbezug.';

CREATE FUNCTION public.list_exercise_library() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_exercise_library() then
    raise exception 'not allowed to read the exercise library' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read the exercise library' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'can_manage', app.can_manage_exercise_library(),
    'exercises', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', e.id,
          'name', e.name,
          'lay_name', e.lay_name,
          'body_region', e.body_region,
          'archived', e.archived_at is not null,
          'variants', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', v.id,
                'name', v.name,
                'lay_name', v.lay_name,
                'instruction', v.instruction,
                'equipment', to_jsonb(v.equipment),
                'common_faults', v.common_faults,
                'practice_notes', v.practice_notes,
                'archived', v.archived_at is not null,
                -- UEB-012
                'catalog_key', v.catalog_key,
                'catalog_version', v.catalog_version,
                'goal', v.goal,
                'starting_position', v.starting_position,
                'level', v.level,
                'default_dosage', v.default_dosage,
                'illustration', v.illustration,
                'reviewed_at', v.reviewed_at,
                'reviewed_by_name', (select up.display_name from public.user_profiles up
                                     where up.id = v.reviewed_by)
              )
              order by lower(v.name), v.id
            )
            from public.exercise_variants v
            where v.exercise_id = e.id and v.organization_id = v_org
          ), '[]'::jsonb)
        )
        order by lower(e.name), e.id
      )
      from public.exercises e
      where e.organization_id = v_org
    ), '[]'::jsonb),
    'links', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', l.id,
          'easier_variant_id', l.easier_variant_id,
          'harder_variant_id', l.harder_variant_id,
          'axis', l.axis
        )
        order by l.created_at, l.id
      )
      from public.exercise_variant_links l
      where l.organization_id = v_org
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.list_exercise_library() IS 'UEB-001/002/012: die Uebungsbibliothek der Praxis mit Varianten (nach Bezeichnung sortiert, nach nichts sonst) samt Herkunft, Ordnungen, Standarddosierung, Bild und Pruefvermerk, dazu die Verbindungen und ob die anfragende Person pflegen darf. Lesen nach app.can_read_exercise_library() (ANN-293).';

CREATE FUNCTION public.list_exercise_plan_templates() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_exercise_library() then
    raise exception 'not allowed to read exercise plan templates' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read exercise plan templates' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'can_create', app.can_write_exercise_plan_templates(),
    'templates', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', t.id,
          'name', t.name,
          'goal', t.goal,
          'can_edit', app.can_edit_exercise_plan_template(t.created_by),
          'created_by_name', (select up.display_name from public.user_profiles up
                              where up.id = t.created_by),
          'updated_on', (t.updated_at at time zone 'Europe/Berlin')::date,
          'items', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'variant_id', i.variant_id,
                'sets', i.sets,
                'reps_min', i.reps_min,
                'reps_max', i.reps_max,
                'duration_seconds', i.duration_seconds,
                'hold_seconds', i.hold_seconds,
                'per_side', i.per_side,
                'times_per_day', i.times_per_day,
                'load', i.load,
                'tempo', i.tempo,
                'rest_seconds', i.rest_seconds,
                'double_progression', i.double_progression
              )
              order by i.position
            )
            from public.exercise_plan_template_items i
            where i.template_id = t.id and i.organization_id = v_org
          ), '[]'::jsonb)
        )
        order by lower(t.name), t.id
      )
      from public.exercise_plan_templates t
      where t.organization_id = v_org
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.list_exercise_plan_templates() IS 'UEB-014 (ANN-560): die Vorlagen der Praxis mit ihren Uebungen, nach Name sortiert und nach nichts sonst (ADR-006 Punkt 10); dazu, ob die anfragende Person anlegen und je Vorlage aendern darf. Lesen nach app.can_read_exercise_library().';

CREATE FUNCTION public.list_exercise_plans(p_area text, p_relationship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Erst die Rolle, dann die Eingabe: Wer gar nicht liest, erfaehrt auch
  -- nichts ueber die Form des Aufrufs (ADR-023 Punkt 21).
  if not (app.can_read_exercise_plans('therapy') or app.can_read_exercise_plans('training')) then
    perform app.record_denied_read(v_actor, 'exercise_plans.read', 'not allowed to read exercise plans');
    return null;
  end if;
  if p_area is null or p_area not in ('therapy', 'training') then
    raise exception 'service area is invalid' using errcode = '22023';
  end if;
  if not app.can_read_exercise_plans(p_area) then
    perform app.record_denied_read(v_actor, 'exercise_plans.read', 'not allowed to read exercise plans');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read exercise plans' using errcode = '42501';
  end if;

  if p_area = 'therapy' then
    if not exists (select 1 from public.patients p where p.id = p_relationship_id and p.organization_id = v_org) then
      return null;
    end if;
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_relationship_id,
      'user', jsonb_build_object('surface', 'web', 'view', 'exercise_plans'));
  else
    if not exists (
      select 1 from public.training_relationships t
      where t.id = p_relationship_id and t.organization_id = v_org
    ) then
      return null;
    end if;
    perform app.log_record_access(v_org, v_actor, 'training_relationship.viewed', 'training_relationship',
      p_relationship_id, 'user', jsonb_build_object('surface', 'web', 'view', 'exercise_plans'));
  end if;

  return jsonb_build_object(
    'can_write', app.can_write_exercise_plans(p_area),
    'today', app.training_today(v_org),
    'plans', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', p.id,
          'title', p.title,
          'status', p.status,
          'sessions_per_week', p.sessions_per_week,
          'previous_plan_id', p.previous_plan_id,
          'assigned_at', p.assigned_at,
          'runs_from', p.runs_from,
          'runs_until', p.runs_until,
          'ended_at', p.ended_at,
          'created_at', p.created_at,
          'item_count', (select count(*) from public.exercise_plan_items i where i.plan_id = p.id),
          'review_due', app.exercise_plan_review_due(p)
        )
        order by case p.status when 'draft' then 0 when 'assigned' then 1 else 2 end,
                 coalesce(p.assigned_at, p.created_at) desc, p.id
      )
      from public.exercise_plans p
      where p.organization_id = v_org
        and p.service_area = p_area
        and (p.patient_id = p_relationship_id or p.training_relationship_id = p_relationship_id)
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.list_exercise_plans(p_area text, p_relationship_id uuid) IS 'UEB-004: die Plaene einer Akte (therapy) oder eines Trainingsverhaeltnisses (training) - Entwuerfe, dann zugewiesene, dann beendete. Lesen nach app.can_read_exercise_plans(Bereich) (ANN-298), protokolliert als Akte geoeffnet (einmal je Tag); andere Rollen: null und access.denied.';

CREATE FUNCTION public.list_fleet(p_week_start date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to read the fleet');

  return jsonb_build_object(
    'can_manage', app.can_manage_fleet(),
    'can_release', app.can_release_fleet_bike(),
    'can_read_reports', app.can_read_fleet_reports(),
    'my_staff_member_id', app.fleet_current_staff_member(v_org),
    'checkup_interval_days', (
      select o.fleet_checkup_interval_days from public.organizations o where o.id = v_org
    ),
    'depots', coalesce((
      select jsonb_agg(
        jsonb_build_object('id', d.id, 'name', d.name, 'note', d.note)
        order by lower(d.name), d.id
      )
      from public.fleet_depots d
      where d.organization_id = v_org
    ), '[]'::jsonb),
    'bikes', coalesce((
      select jsonb_agg(app.fleet_bike_json(b) order by lower(b.name), b.id)
      from public.fleet_bikes b
      where b.organization_id = v_org and b.archived_at is null
    ), '[]'::jsonb),
    -- Aktive Mitarbeitende fuer die Auswahl von Stammnutzer:in und
    -- Schluessel: Name und Kennung, sonst nichts.
    'staff', coalesce((
      select jsonb_agg(
        jsonb_build_object('id', sm.id, 'name', pe.given_name || ' ' || pe.family_name)
        order by lower(pe.family_name), lower(pe.given_name), sm.id
      )
      from public.staff_members sm
      join public.persons pe on pe.id = sm.person_id
      where sm.organization_id = v_org and sm.employment_status = 'active'
    ), '[]'::jsonb),
    'unavailable', case when p_week_start is null then '[]'::jsonb else coalesce((
      select jsonb_agg(
        jsonb_build_object('staff_member_id', e.staff_member_id, 'on_date', e.on_date)
        order by e.on_date, e.staff_member_id
      )
      from public.staff_working_hour_exceptions e
      where e.organization_id = v_org
        and e.kind = 'unavailable'
        and e.on_date between p_week_start and p_week_start + 6
        and exists (
          select 1 from public.fleet_bikes b
          where b.organization_id = v_org and b.archived_at is null
            and b.regular_rider_id = e.staff_member_id
        )
    ), '[]'::jsonb) end
  );
end;
$$;

COMMENT ON FUNCTION public.list_fleet(p_week_start date) IS 'FLT-001, FLT-008, FLT-009: die Flotte in einem Aufruf - Rechte (can_manage, can_release, can_read_reports), Check-Up-Rhythmus der Praxis, Depots, Raeder, aktive Mitarbeitende und ganztaegige Abwesenheiten der Stammnutzer:innen in der Woche. Lesen nach app.can_read_fleet().';

CREATE FUNCTION public.list_fleet_photos(p_bike_id uuid) RETURNS TABLE(id uuid, spot_id uuid, checkup_id uuid, side text, created_at timestamp with time zone, verified boolean, may_delete boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to read the fleet');
  if not exists (
    select 1 from public.fleet_bikes b where b.id = p_bike_id and b.organization_id = v_org
  ) then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  return query
    select f.id, f.spot_id, f.checkup_id, f.side, f.created_at, f.verified_at is not null,
           app.can_delete_fleet_photo(f)
    from public.fleet_photos f
    where f.bike_id = p_bike_id and f.organization_id = v_org and f.status = 'ready'
    order by f.created_at, f.id;
end;
$$;

COMMENT ON FUNCTION public.list_fleet_photos(p_bike_id uuid) IS 'FLT-002, FLT-007: die fertigen Fotos eines Rads mit Bezug (Stelle oder Check-Up), Seite, Zeitpunkt, Pruefstand und ob die anfragende Person loeschen darf. Kein Objektschluessel, kein Verweis. Lesen nach app.can_read_fleet().';

CREATE FUNCTION public.list_fleet_reports(p_since date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_zone  text;
  v_heute date;
  v_ab    date;
begin
  v_org := app.fleet_org(app.can_read_fleet_reports(), 'not allowed to read the fleet reports');

  select o.time_zone into v_zone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zone)::date;
  v_ab := coalesce(p_since, v_heute - 90);
  if v_ab < v_heute - 366 or v_ab > v_heute then
    raise exception 'since must lie within the last year' using errcode = '22023';
  end if;

  return coalesce((
    select jsonb_agg(m.eintrag order by m.zeit desc, m.id)
    from (
      select x.eintrag, x.zeit, x.id
      from (
        select c.checked_at as zeit, c.id,
          jsonb_build_object(
            'kind', 'checkup',
            'id', c.id,
            'bike_id', b.id,
            'bike_name', b.name,
            'bike_type', c.bike_type,
            'at', c.checked_at,
            'by_name', app.fleet_account_name(c.checked_by),
            'items', c.items,
            'note', c.note,
            'ad_surfaces', c.ad_surfaces,
            'ad_surfaces_note', c.ad_surfaces_note,
            'spots', app.fleet_report_spots(c.id, null),
            'photos', app.fleet_report_photos(c.id, null)
          ) as eintrag
        from public.fleet_checkups c
        join public.fleet_bikes b on b.id = c.bike_id and b.organization_id = c.organization_id
        where c.organization_id = v_org and b.archived_at is null
          and c.checked_at >= (v_ab::timestamp at time zone v_zone)
        union all
        select d.reported_at as zeit, d.id,
          jsonb_build_object(
            'kind', 'breakdown',
            'id', d.id,
            'bike_id', b.id,
            'bike_name', b.name,
            'bike_type', b.bike_type,
            'at', d.reported_at,
            'by_name', app.fleet_account_name(d.reported_by),
            'outcome', d.outcome,
            'blocks', app.fleet_outcome_blocks(d.outcome),
            'summary', d.summary,
            'remark', d.remark,
            'location_note', d.location_note,
            'transport', d.transport,
            'spots', app.fleet_report_spots(null, d.id),
            'photos', app.fleet_report_photos(null, d.id)
          ) as eintrag
        from public.fleet_breakdowns d
        join public.fleet_bikes b on b.id = d.bike_id and b.organization_id = d.organization_id
        where d.organization_id = v_org and b.archived_at is null
          and d.reported_at >= (v_ab::timestamp at time zone v_zone)
      ) x
      order by x.zeit desc, x.id
      limit 500
    ) m
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.list_fleet_reports(p_since date) IS 'FLT-008 (ANN-569): alle Check-Ups und Pannen der Flotte ab p_since (ohne Angabe 90 Tage, hoechstens ein Jahr, hoechstens 500), neueste zuerst, mit Pruefpunkten, Werbeflaechen, Stellen und Kennungen der Fotos. Lesen nach app.can_read_fleet_reports() (owner, team_lead). Keine Auswertung je Person (PROJECT_PRINCIPLES.md 20).';

CREATE FUNCTION public.list_food_sources() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'source', s.source, 'title', s.title, 'publisher', s.publisher, 'license', s.license,
    'license_url', s.license_url, 'attribution', s.attribution, 'source_url', s.source_url,
    'version', s.version, 'imported_at', s.imported_at, 'item_count', s.item_count)
    order by s.source), '[]'::jsonb)
  from public.food_sources s
  where auth.uid() is not null
$$;

COMMENT ON FUNCTION public.list_food_sources() IS 'ERN-004 (ADR-027 Punkt 8): die Quellenangabe der Lebensmitteldaten mit Lizenz und Stand - für jede angemeldete Person, Inhalt ohne Personenbezug.';

CREATE FUNCTION public.list_home_visits_with_outdated_address(p_patient_id uuid) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, staff_given_name text, staff_family_name text, visit_street text, visit_house_number text, visit_postal_code text, visit_city text, organization_time_zone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() or not app.may_read_appointment_context('therapy') then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_patient_id is null then
    raise exception 'patient is required' using errcode = '22023';
  end if;

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      sp.given_name,
      sp.family_name,
      a.visit_street,
      a.visit_house_number,
      a.visit_postal_code,
      a.visit_city,
      o.time_zone
    from public.appointments a
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    join public.organizations o  on o.id  = a.organization_id
    join public.patient_contact_details c on c.patient_id = a.patient_id
    where a.organization_id  = v_org
      and a.patient_id       = p_patient_id
      and a.kind             = 'therapy'
      and a.appointment_type = 'home_visit'
      and a.status           = 'confirmed'
      and a.starts_at        > now()
      -- Nur vergleichen, wenn die Stammdaten eine vollstaendige Anschrift
      -- tragen - sonst gibt es nichts, womit der Termin zu aktualisieren waere.
      and nullif(btrim(c.street), '')       is not null
      and nullif(btrim(c.house_number), '') is not null
      and nullif(btrim(c.postal_code), '')  is not null
      and nullif(btrim(c.city), '')         is not null
      and (a.visit_street, a.visit_house_number, a.visit_postal_code, a.visit_city)
          is distinct from
          (nullif(btrim(c.street), ''), nullif(btrim(c.house_number), ''),
           nullif(btrim(c.postal_code), ''), nullif(btrim(c.city), ''))
    order by a.starts_at, a.id;
end;
$$;

COMMENT ON FUNCTION public.list_home_visits_with_outdated_address(p_patient_id uuid) IS 'Kuenftige bestaetigte Hausbesuche einer Patient:in, deren kopierte Anschrift von der aktuellen Stammdatenadresse abweicht (ABN-004, BEF-092, ANN-003). Rein organisatorisch; Rollen der Terminverwaltung, abgewiesen mit appointments.read.';

CREATE FUNCTION public.list_invoice_candidates(p_limit integer DEFAULT 100) RETURNS TABLE(patient_id uuid, training_relationship_id uuid, patient_name text, period_month date, service_area text, service_count integer, total_cents integer, currency text, has_draft boolean, draft_id uuid, treatment_basis_id uuid, basis_kind text, basis_issued_on date, first_performed_on date, last_performed_on date, cancelled_invoice_id uuid, cancelled_invoice_number text, draft_replaces_invoice_number text, basis_released_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  v_org := app.current_organization_id();

  -- Erst buendeln, dann den Entwurf dazusuchen (BEF-018). Der Bereich steht
  -- seit ABR-009 in beiden Schritten: Er ist der dritte Schluessel der
  -- Klammer und nicht eine Spalte, die nebenher mitlaeuft.
  return query
  select k.patient_id,
         k.training_relationship_id,
         k.patient_name,
         k.period_month,
         k.service_area,
         k.service_count,
         k.total_cents,
         k.currency,
         (entwurf.id is not null),
         entwurf.id,
         k.treatment_basis_id,
         tb.treatment_basis_kind,
         tb.issued_on,
         k.erste,
         k.letzte,
         -- UX-008b: die stornierte Rechnung, aus der die Leistungen stammen.
         storno.id,
         storno.invoice_number,
         -- Ist der stehende Entwurf selbst eine Korrektur, welche?
         ersetzt.invoice_number,
         -- K13 (ANN-544): in die Abrechnung gestellt am - erst dann nimmt der
         -- Monatslauf die Verordnung auf. Ohne Grundlage leer.
         tb.billing_released_at
  from (
    select b.patient_id,
           b.training_relationship_id,
           max(pe.given_name || ' ' || pe.family_name) as patient_name,
           max(pe.family_name) as family_name,
           -- ABR-032: Mit Grundlage ist sie die Klammer und der Monat nennt
           -- nur den Beginn; ohne Grundlage ist es der Kalendermonat der
           -- Gruppe - in beiden Faellen der Monat der ersten Leistung.
           date_trunc('month', min(b.performed_on))::date as period_month,
           a.treatment_basis_id,
           min(b.performed_on) as erste,
           max(b.performed_on) as letzte,
           b.service_area,
           count(*)::integer as service_count,
           -- ABR-031: Anteil am Terminhonorar oder Katalogpreis.
           sum(app.billable_service_amount(b.id))::integer as total_cents,
           max(c.currency) as currency,
           -- UX-008b: Welche Leistungen die Gruppe traegt - fuer die Frage,
           -- ob sie aus einer stornierten Rechnung stammen.
           array_agg(b.id) as leistungen
    from public.billable_services b
    join public.service_catalog_items c on c.id = b.catalog_item_id
    -- ANG-002: Ein Abo-Monat hat keinen Termin und buendelt nach dem Monat.
    left join public.appointments a on a.id = b.appointment_id
    left join public.patients p on p.id = b.patient_id
    left join public.training_relationships t on t.id = b.training_relationship_id
    join public.persons pe on pe.id = coalesce(p.person_id, t.person_id)
    where b.organization_id = v_org
      and b.status = 'billable'
      -- Seit ABR-003c zaehlt nur eine Zeile, die nicht freigegeben ist: Nach
      -- einem Storno ist die Leistung wieder abzurechnen.
      and not exists (
        select 1 from public.invoice_items it
        where it.billable_service_id = b.id and it.released_at is null
      )
    group by b.patient_id, b.training_relationship_id, a.treatment_basis_id,
             case when a.treatment_basis_id is null
                  then date_trunc('month', b.performed_on)::date end,
             b.service_area
  ) k
  left join public.treatment_bases tb on tb.id = k.treatment_basis_id
  left join lateral (
    select i.id
    from public.invoices i
    where i.organization_id = v_org
      and i.patient_id is not distinct from k.patient_id
      and i.training_relationship_id is not distinct from k.training_relationship_id
      and i.service_area = k.service_area
      and i.status = 'draft'
      and i.treatment_basis_id is not distinct from k.treatment_basis_id
      and (k.treatment_basis_id is not null or i.period_month = k.period_month)
    limit 1
  ) entwurf on true
  -- UX-008b (BEF-062): Stammen Leistungen der Gruppe aus einer stornierten
  -- Rechnung derselben Klammer, die noch keine Korrektur hat, fuehrt nur
  -- deren Korrekturrechnung weiter - bei zweien die zuletzt ausgestellte.
  left join lateral (
    select s.id, s.invoice_number
    from unnest(k.leistungen) l(id)
    join public.invoices s on s.id = app.open_cancellation_holding_service(
      l.id, k.patient_id, k.training_relationship_id, k.service_area,
      k.treatment_basis_id, k.period_month)
    order by s.issued_at desc
    limit 1
  ) storno on true
  left join public.invoices entwurf_zeile on entwurf_zeile.id = entwurf.id
  left join public.invoices ersetzt on ersetzt.id = entwurf_zeile.replaces_invoice_id
  order by k.period_month desc, k.family_name, k.service_area
  limit greatest(least(coalesce(p_limit, 100), 200), 1);
end;
$$;

COMMENT ON FUNCTION public.list_invoice_candidates(p_limit integer) IS 'Was abzurechnen ist (ABR-003, ABR-032): je Person und Behandlungsgrundlage, ohne Grundlage je Person, Monat und Bereich, mit Anzahl, Betrag, Zeitraum und einem schon stehenden Entwurf. Seit UX-008b mit der stornierten Rechnung derselben Klammer, aus der Leistungen stammen und die noch keine Korrektur hat, und der Nummer, die ein stehender Korrekturentwurf ersetzt (BEF-062, ANN-321). Seit K13 mit dem Zeitpunkt der Freigabe der Verordnung zur Abrechnung (basis_released_at, ANN-544). owner und office.';

CREATE FUNCTION public.list_invoice_payments(p_invoice_id uuid) RETURNS TABLE(id uuid, direction text, amount_cents integer, currency text, paid_on date, method text, note text, voided_at timestamp with time zone, void_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select p.id, p.direction, p.amount_cents, p.currency, p.paid_on, p.method,
         p.note, p.voided_at, p.void_reason
  from public.payments p
  join public.invoices i on i.id = p.invoice_id
  where p.invoice_id = p_invoice_id
    and i.organization_id = v_org
  order by p.paid_on, p.created_at, p.id;
end;
$$;

COMMENT ON FUNCTION public.list_invoice_payments(p_invoice_id uuid) IS 'Zahlungen einer Rechnung, stornierte eingeschlossen und als solche erkennbar (ABR-004).';

CREATE FUNCTION public.list_invoice_recipients(p_patient_id uuid) RETURNS TABLE(id uuid, recipient_kind text, name text, street text, house_number text, postal_code text, city text, reference text, is_default boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoice recipients');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select r.id, r.recipient_kind, r.name, r.street, r.house_number,
         r.postal_code, r.city, r.reference, r.is_default
  from public.invoice_recipients r
  where r.organization_id = v_org
    and r.patient_id = p_patient_id
  order by r.is_default desc, r.name;
end;
$$;

COMMENT ON FUNCTION public.list_invoice_recipients(p_patient_id uuid) IS 'Hinterlegte Rechnungsempfaenger einer Patientin (ABR-003a). Die Patientin selbst steht nicht in der Liste - sie ist die Vorgabe, solange keine Zeile als Vorgabe markiert ist (ANN-076).';

CREATE FUNCTION public.list_invoice_reminders(p_invoice_id uuid) RETURNS TABLE(id uuid, reminder_on date, due_on date, outstanding_cents integer, currency text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select r.id, r.reminder_on, r.due_on, r.outstanding_cents, r.currency
  from public.invoice_payment_reminders r
  where r.invoice_id = p_invoice_id
    and r.organization_id = v_org
