$$;

COMMENT ON FUNCTION public.list_invoice_reminders(p_invoice_id uuid) IS 'Die Zahlungserinnerungen einer Rechnung, die juengste zuerst (ABR-003d). Jede traegt ihren eigenen offenen Betrag - den vom Tag ihrer Ausstellung.';

CREATE FUNCTION public.list_invoices(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_month date DEFAULT NULL::date) RETURNS TABLE(id uuid, status text, invoice_number text, period_month date, service_area text, issued_on date, due_on date, patient_id uuid, training_relationship_id uuid, patient_name text, recipient_name text, recipient_kind text, total_cents integer, currency text, item_count integer, paid_cents integer, outstanding_cents integer, payment_state text, overdue boolean, cancelled boolean, treatment_basis_id uuid, basis_kind text, basis_issued_on date, total_count integer, basis_released_at timestamp with time zone, is_correction boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_zeitzone text;
  v_heute    date;
  v_suche    text := nullif(lower(btrim(coalesce(p_search, ''))), '');
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  if p_status is not null and p_status not in ('draft', 'open', 'overdue', 'paid', 'cancelled') then
    raise exception 'unknown invoice filter' using errcode = '22023';
  end if;
  if v_suche is not null and length(v_suche) > 100 then
    raise exception 'search too long' using errcode = '22023';
  end if;

  v_org := app.current_organization_id();

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  return query
  with basis as (
    -- Was Suche und Filter brauchen: Name, Empfaenger, Zahlungsstand, Storno.
    select i.*,
           pe.given_name || ' ' || pe.family_name as person_name,
           -- BEF-141: Ausgestellt (auch storniert) heisst der Empfaenger,
           -- wie er auf dem Blatt steht; nur der Entwurf liest live.
           app.invoice_recipient_name(i.status, i.snapshot, r.name) as empfaenger_name,
           case when i.status = 'issued'
                then coalesce(i.snapshot -> 'recipient' ->> 'kind', r.recipient_kind)
                else r.recipient_kind end as empfaenger_art,
           coalesce(zahlung.bezahlt, 0) as bezahlt,
           exists (select 1 from public.invoice_cancellations c where c.invoice_id = i.id)
             as storniert
    from public.invoices i
    left join public.patients pa on pa.id = i.patient_id
    left join public.training_relationships t on t.id = i.training_relationship_id
    join public.persons pe on pe.id = coalesce(pa.person_id, t.person_id)
    left join public.invoice_recipients r on r.id = i.recipient_id
    left join lateral (
      select sum(case when p.direction = 'incoming' then p.amount_cents
                      else -p.amount_cents end)::integer as bezahlt
      from public.payments p
      where p.invoice_id = i.id
        and p.voided_at is null
    ) zahlung on true
    where i.organization_id = v_org
      and (p_month is null or i.period_month = date_trunc('month', p_month)::date)
  ),
  gefiltert as (
    select b.*,
           (b.status = 'issued' and b.due_on < v_heute
            and b.bezahlt < b.total_cents and not b.storniert) as ueberfaellig
    from basis b
    where (v_suche is null
           or strpos(lower(coalesce(b.invoice_number, '')), v_suche) > 0
           or strpos(lower(b.person_name), v_suche) > 0
           or strpos(lower(coalesce(b.empfaenger_name, '')), v_suche) > 0)
  ),
  auswahl as (
    select g.*, count(*) over ()::integer as gesamt
    from gefiltert g
    where case p_status
            when 'draft'     then g.status = 'draft'
            -- Offen heisst, was `app.open_invoices` offen nennt - die Regel
            -- steht dort einmal (Zweitreview ABR-033).
            when 'open'      then g.id in (select o.invoice_id from app.open_invoices(v_org) o)
            when 'overdue'   then g.ueberfaellig
            when 'paid'      then g.status = 'issued' and not g.storniert
                                  and g.bezahlt >= g.total_cents
            when 'cancelled' then g.storniert
            else true
          end
    order by g.status, g.period_month desc, g.invoice_number desc nulls first, g.id
    limit greatest(least(coalesce(p_limit, 100), 200), 1)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select i.id, i.status, i.invoice_number, i.period_month, i.service_area, i.issued_on, i.due_on,
         i.patient_id,
         i.training_relationship_id,
         i.person_name,
         coalesce(i.empfaenger_name, i.person_name),
         coalesce(i.empfaenger_art, 'self'),
         -- Der Entwurf rechnet live, die ausgestellte Rechnung zeigt ihren
         -- festgeschriebenen Betrag (ADR-009 Punkt 10).
         coalesce(i.total_cents, summe.brutto)::integer,
         coalesce(i.currency, summe.currency),
         -- BEF-143: Ausgestellt (auch storniert) zaehlt der Snapshot - faellt
         -- nach einem Storno eine Leistung mit ihrer Zeile, steht sie dort
         -- weiter, wie auf dem Blatt. Nur der Entwurf zaehlt live.
         case when i.status = 'issued'
              then jsonb_array_length(coalesce(i.snapshot -> 'items', '[]'::jsonb))
              else summe.anzahl::integer end,
         case when i.status = 'issued' then i.bezahlt else 0 end,
         case when i.status = 'issued' then i.total_cents - i.bezahlt else 0 end,
         case when i.status = 'issued'
              then app.invoice_payment_state(i.total_cents, i.bezahlt)
              else 'unpaid' end,
         i.ueberfaellig,
         i.storniert,
         -- ABR-032: die Verordnung als Klammer der Rechnung.
         i.treatment_basis_id,
         tb.treatment_basis_kind,
         tb.issued_on,
         i.gesamt,
         -- K13 (ANN-544): Der Lauf stellt einen Entwurf zu einer Verordnung
         -- erst mit ihrer Freigabe aus und laesst Korrekturen einzeln.
         tb.billing_released_at,
         (i.replaces_invoice_id is not null)
  from auswahl i
  left join public.treatment_bases tb on tb.id = i.treatment_basis_id
  left join lateral (
    -- ABR-031: Anteil am Terminhonorar oder Katalogpreis.
    select sum(app.billable_service_amount(b.id)) as brutto,
           max(c.currency) as currency,
           count(*) as anzahl
    from public.invoice_items it
    join public.billable_services b     on b.id = it.billable_service_id
    join public.service_catalog_items c on c.id = b.catalog_item_id
    where it.invoice_id = i.id
  ) summe on true
  order by i.status, i.period_month desc, i.invoice_number desc nulls first, i.id;
end;
$$;

COMMENT ON FUNCTION public.list_invoices(p_limit integer, p_offset integer, p_search text, p_status text, p_month date) IS 'Rechnungen der Praxis mit Suche (Nummer, Name, Empfaenger), Filter (draft, open, overdue, paid, cancelled; Monat) und Blaettern; total_count nennt die Treffer vor dem Kuerzen (ABR-033, BEF-061); bei ausgestellten Rechnungen Empfaenger (BEF-141) und Zahl der Positionen (BEF-143) aus dem Snapshot. Seit K13 mit der Freigabe der Verordnung (basis_released_at) und ob ein Entwurf eine Korrektur ist (is_correction, ANN-544). Nur fuer can_read_invoicing.';

CREATE FUNCTION public.list_leave(p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_staff    uuid;
  v_jahr     integer;
  v_entsch   boolean;
  v_konten   boolean;
  v_heute    date;
  v_land     text;
begin
  v_org := app.staff_request_org(app.can_request_leave(), 'not allowed to read leave');
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    raise exception 'leave window is invalid' using errcode = '22023';
  end if;
  v_staff := app.own_staff_member(v_org);
  v_jahr := extract(year from p_from)::integer;
  v_entsch := app.can_decide_staff_requests();
  v_konten := app.can_read_staff_leave_balances();
  select (now() at time zone o.time_zone)::date, o.federal_state into v_heute, v_land
  from public.organizations o where o.id = v_org;

  return jsonb_build_object(
    'my_staff_member_id', v_staff,
    'can_decide', v_entsch,
    'self_entered', app.has_any_role('owner'),
    'can_manage_entitlements', app.can_manage_staff_employment(),
    -- Fuer die Feiertage im Kalender beim Beantragen (ANN-577).
    'federal_state', v_land,
    'balance', case when v_staff is null then null else app.leave_balance(v_org, v_staff, v_jahr) end,
    -- Eigene Antraege mit allem, auch der Nachricht und der Entscheidung.
    'own', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'kind', r.kind, 'refers_to', r.refers_to,
               'starts_on', r.starts_on, 'ends_on', r.ends_on, 'days', r.days,
               'message', r.message, 'status', r.status, 'requested_at', r.requested_at,
               'decided_at', r.decided_at, 'decided_by_name', app.account_display_name(r.decided_by),
               'decision_note', r.decision_note, 'self_entered', r.self_entered,
               'open_cancellation', exists (
                 select 1 from public.staff_leave_requests c
                 where c.refers_to = r.id and c.kind = 'cancellation' and c.status = 'requested')
             ) order by r.starts_on desc, r.requested_at desc)
      from public.staff_leave_requests r
      where r.organization_id = v_org and r.staff_member_id = v_staff
        and (r.status = 'requested' or r.ends_on >= p_from or r.decided_at >= now() - interval '30 days')
    ), '[]'::jsonb),
    -- Fuer die Entscheidenden: offene Antraege anderer mit Konto, wer zur
    -- selben Zeit fehlt und wie viele Termine im Zeitraum liegen.
    'to_decide', case when not v_entsch then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'kind', r.kind, 'refers_to', r.refers_to,
               'staff_member_id', r.staff_member_id,
               'name', app.staff_display_name(r.staff_member_id),
               'starts_on', r.starts_on, 'ends_on', r.ends_on, 'days', r.days,
               -- Das Konto des Beginnjahrs zaehlt nur dessen Tage.
               'days_following_year', r.days_following_year,
               -- Ohne die Notiz: die sieht nur die Person (BEF-066, ANN-580).
               'requested_at', r.requested_at,
               'balance', app.leave_balance(v_org, r.staff_member_id,
                                            extract(year from r.starts_on)::integer),
               'team', app.team_leave(v_org, r.staff_member_id, r.starts_on, r.ends_on),
               'appointments', app.appointments_in_leave(v_org, r.staff_member_id, r.starts_on, r.ends_on),
               'exception_days', case when r.kind = 'leave' then
                 app.exception_days_in_leave(v_org, r.staff_member_id, r.starts_on, r.ends_on)
                 else '[]'::jsonb end
             ) order by r.requested_at)
      from public.staff_leave_requests r
      where r.organization_id = v_org and r.status = 'requested'
        and r.staff_member_id is distinct from v_staff
    ), '[]'::jsonb) end,
    -- Fuer alle: genehmigter Urlaub anderer im Fenster - nur Name und
    -- Zeitraum, und nur ab heute: kein Verlauf ueber die Kolleg:innen
    -- (Zweitreview). owner pflegt die Konten und sieht auch Vergangenes.
    'team', app.team_leave(
      v_org, v_staff,
      case when app.has_any_role('owner') then p_from else greatest(p_from, v_heute) end,
      p_to),
    -- Fremde Urlaubskonten nur fuer owner (ANN-580), je Person, ohne Summe.
    'balances', case when not v_konten then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'staff_member_id', sm.id,
               'name', app.staff_display_name(sm.id),
               'balance', app.leave_balance(v_org, sm.id, v_jahr),
               -- Den Anspruch des Folgejahrs traegt owner vorab ein; die
               -- Seite belegt ihn damit vor, statt ihn leer zu ueberschreiben.
               'next_balance', app.leave_balance(v_org, sm.id, v_jahr + 1)
             ) order by app.staff_display_name(sm.id))
      from public.staff_members sm
      where sm.organization_id = v_org and sm.employment_status = 'active'
    ), '[]'::jsonb) end
  );
end;
$$;

COMMENT ON FUNCTION public.list_leave(p_from date, p_to date) IS 'URL-001: Urlaub in einem Aufruf - eigene Antraege mit Notiz und Konto ganz; fuer owner die offenen Antraege anderer mit Konto, Tagen im Folgejahr und den Tagen mit abweichenden Arbeitszeiten, ohne Notiz; fuer alle genehmigter Urlaub anderer nur mit Name und Zeitraum ab heute; fremde Konten (laufendes und Folgejahr) nur owner (BEF-066, ANN-580). Ohne Summe ueber alle (PROJECT_PRINCIPLES.md 20).';

CREATE FUNCTION public.list_legal_holds() RETURNS TABLE(id uuid, subject_type text, subject_id uuid, subject_name text, reason text, placed_at timestamp with time zone, placed_by_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_legal_hold() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'legal_holds.read', 'not allowed to manage legal holds');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage legal holds' using errcode = '42501';
  end if;

  return query
    select h.id,
           h.subject_type,
           h.subject_id,
           coalesce(pe.given_name || ' ' || pe.family_name,
                    spe.given_name || ' ' || spe.family_name),
           h.reason,
           h.placed_at,
           up.display_name
    from public.legal_holds h
    left join public.patients p       on p.id = h.subject_id and h.subject_type = 'patient'
                                     and p.organization_id = h.organization_id
    left join public.persons pe       on pe.id = p.person_id
    left join public.staff_members sm on sm.id = h.subject_id and h.subject_type = 'staff_member'
                                     and sm.organization_id = h.organization_id
    left join public.persons spe      on spe.id = sm.person_id
    left join public.user_profiles up on up.id = h.placed_by
    where h.organization_id = v_org
      and h.released_at is null
    order by h.placed_at desc;
end;
$$;

COMMENT ON FUNCTION public.list_legal_holds() IS 'Laufende Loeschsperren der eigenen Organisation samt betroffener Person - Akte oder Beschaeftigtendaten (LOE-001c, ANN-674). Nur owner.';

CREATE FUNCTION public.list_message_attachments_for_access_request(p_relationship_kind text, p_relationship_id uuid) RETURNS TABLE(id uuid, media_kind text, mime_type text, duration_seconds smallint, taken_at timestamp with time zone, author_kind text, locked boolean, object_missing boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_relationship_kind = 'treatment' then
    perform app.auskunft_organisation(p_relationship_id);
  elsif p_relationship_kind = 'training' then
    perform app.auskunft_organisation_training(p_relationship_id);
  else
    raise exception 'data subject access denied' using errcode = '42501';
  end if;

  return query
    select x.id,
           x.media_kind,
           x.mime_type,
           x.duration_seconds,
           x.created_at,
           x.author_kind,
           not app.message_attachment_visible(x),
           not exists (
             select 1 from storage.objects o
             where o.bucket_id = app.message_attachment_bucket() and o.name = x.object_key)
    from public.platform_message_attachments x
    join public.platform_messages m on m.id = x.message_id
    where x.organization_id = app.current_organization_id()
      and x.status = 'ready'
      and m.relationship_kind = p_relationship_kind
      and m.relationship_id = p_relationship_id
    order by x.created_at, x.id;
end;
$$;

COMMENT ON FUNCTION public.list_message_attachments_for_access_request(p_relationship_kind text, p_relationship_id uuid) IS 'BEF-188: die bestaetigten Fotos und Videos an Rueckfragen einer Akte oder eines Trainingsverhaeltnisses fuer die Herausgabe - auch gesperrte, solange vorhanden. Nur owner, wie die Auskunft.';

CREATE FUNCTION public.list_missing_patient_file_objects() RETURNS TABLE(file_id uuid, patient_id uuid, patient_name text, document_type text, display_name text, uploaded_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if not app.can_execute_storage_deletion() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'storage_deletion.read', 'not allowed to read the storage reconciliation');
    return;
  end if;

  if v_org is null or not app.can_execute_storage_deletion() then
    raise exception 'not allowed to read the storage reconciliation' using errcode = '42501';
  end if;

  return query
    select f.id,
           f.patient_id,
           btrim(coalesce(pe.given_name, '') || ' ' || coalesce(pe.family_name, '')),
           f.document_type,
           f.display_name,
           f.confirmed_at
    from public.patient_files f
    join public.patients p on p.id = f.patient_id
    join public.persons pe on pe.id = p.person_id
    where f.organization_id = v_org
      and f.status = 'ready'
      and not exists (
        select 1
        from storage.objects o
        where o.bucket_id = app.patient_file_bucket_for(f.document_type)
          and o.name = f.object_key
      )
    order by f.confirmed_at;
end;
$$;

COMMENT ON FUNCTION public.list_missing_patient_file_objects() IS 'Datensaetze ohne Objekt (ADR-017 Punkt 27). Ein sichtbarer Fehler, kein stiller Ausgleich.';

CREATE FUNCTION public.list_open_billable_appointments(p_limit integer DEFAULT 100) RETURNS TABLE(appointment_id uuid, patient_id uuid, training_relationship_id uuid, service_area text, patient_name text, performed_on date, starts_at timestamp with time zone, status text, fee_basis text, appointment_type text, suggestion_count integer, occasion text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_billable_services() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'billable_services.read', 'not allowed to read billable services');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select a.id,
         a.patient_id,
         a.training_relationship_id,
         app.service_area_of_appointment_kind(a.kind),
         pe.given_name || ' ' || pe.family_name,
         (a.starts_at at time zone o.time_zone)::date,
         a.starts_at,
         a.status,
         a.fee_basis,
         a.appointment_type,
         (
           select count(*)::integer
           from public.treatment_base_items q
           join public.service_catalog_items ci
             on ci.remedy = q.remedy
            and ci.catalog_version_id = app.active_service_catalog_version(
                  v_org, (a.starts_at at time zone o.time_zone)::date)
           where q.treatment_basis_id = a.treatment_basis_id
         ),
         a.occasion
  from public.appointments a
  join public.organizations o on o.id = a.organization_id
  left join public.patients p on p.id = a.patient_id
  left join public.training_relationships t on t.id = a.training_relationship_id
  join public.persons pe on pe.id = coalesce(p.person_id, t.person_id)
  where a.organization_id = v_org
    and a.kind in ('therapy', 'training')
    -- ABN-006: Nach einem Verzicht ist der Anlass keine offene Leistung mehr.
    and app.appointment_is_billable(app.billing_kind(a.kind, a.occasion), a.status, app.billable_fee_basis(a.fee_basis, a.fee_waived_at))
    -- B4/B7 (ANN-513): Ohne Haken ist am Behandlungstermin nichts erbracht -
    -- ausser einem Gebuehrenanlass.
    and (app.billable_fee_basis(a.fee_basis, a.fee_waived_at) is not null
         or app.appointment_is_checked(a.kind, a.status, a.completed_at))
    and not exists (
      select 1 from public.billable_services b where b.appointment_id = a.id
    )
    -- ANG-007 (ANN-279): Ein Trainingstermin im Paket ist bezahlt - eine
    -- Ernaehrungsberatung nicht (ERN-011).
    and (a.kind <> 'training'
         or a.occasion = 'nutrition_counselling'
         or app.training_package_covering(
              a.training_relationship_id, (a.starts_at at time zone o.time_zone)::date) is null)
  order by a.starts_at desc, a.id
  limit greatest(least(coalesce(p_limit, 100), 200), 1);
end;
$$;

COMMENT ON FUNCTION public.list_open_billable_appointments(p_limit integer) IS 'Termine, aus denen eine Leistung entstehen darf und an denen noch keine erfasst ist (ABR-002, TRN-007): Behandlung dokumentiert oder mit Gebuehrenanlass, Training durchgefuehrt, Ernaehrungsberatung abgehakt (ERN-011, mit occasion). Der Name kommt aus dem Verhaeltnis des Termins, nie aus der Akte eines Trainingstermins. Die Arbeitsliste des Abrechnungsbereichs.';

CREATE FUNCTION public.list_open_intakes() RETURNS TABLE(patient_id uuid, patient_given_name text, patient_family_name text, open_items text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_patient_directory() then
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read open intakes');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read open intakes' using errcode = '42501';
  end if;

  return query
  select pa.id,
         pe.given_name,
         pe.family_name,
         offen.items
  from public.patients pa
  join public.persons pe on pe.id = pa.person_id
  cross join lateral (
    select array_agg(c.item order by c.ord) as items
    from (
      select k.item, k.state,
             array_position(array['prescription_photo', 'registration_form'], k.item) as ord
      from app.intake_checklist(v_org, pa.id) k
    ) c
    where c.state = 'open'
  ) offen
  where pa.organization_id = v_org
    and pa.status = 'active'
    and pa.care_concluded_on is null
    and offen.items is not null
  order by pe.family_name, pe.given_name, pa.id;
end;
$$;

COMMENT ON FUNCTION public.list_open_intakes() IS 'Personen in Versorgung mit offenen Punkten der Erstaufnahme (AKTE-007, ANN-224), je Person die offenen Punkte in fester Reihenfolge. Die vier Praxisrollen; ein abgewiesener Versuch wird als patient_directory.read protokolliert.';

CREATE FUNCTION public.list_open_items(p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, invoice_number text, patient_id uuid, training_relationship_id uuid, service_area text, patient_name text, recipient_name text, period_month date, issued_on date, due_on date, total_cents integer, paid_cents integer, outstanding_cents integer, currency text, overdue boolean, open_total_cents integer, total_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_zeitzone text;
  v_heute    date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  v_org := app.current_organization_id();

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  return query
  select i.id, i.invoice_number, i.patient_id, i.training_relationship_id, i.service_area,
         pe.given_name || ' ' || pe.family_name,
         coalesce(app.invoice_recipient_name(i.status, i.snapshot, r.name),
                  pe.given_name || ' ' || pe.family_name),
         i.period_month, i.issued_on, i.due_on,
         i.total_cents,
         offen.paid_cents,
         offen.outstanding_cents,
         i.currency,
         (i.due_on < v_heute),
         sum(offen.outstanding_cents) over ()::integer,
         count(*) over ()::integer
  from app.open_invoices(v_org) offen
  join public.invoices i  on i.id = offen.invoice_id
  left join public.patients pa on pa.id = i.patient_id
  left join public.training_relationships t on t.id = i.training_relationship_id
  join public.persons pe on pe.id = coalesce(pa.person_id, t.person_id)
  left join public.invoice_recipients r on r.id = i.recipient_id
  order by i.due_on, i.invoice_number
  limit greatest(least(coalesce(p_limit, 100), 200), 1);
end;
$$;

COMMENT ON FUNCTION public.list_open_items(p_limit integer) IS 'Offene Posten der Praxis, faellig zuerst; open_total_cents und total_count ueber alle offenen Posten vor dem Kuerzen (ABR-033, BEF-061); Empfaenger aus dem Snapshot (BEF-141).';

CREATE FUNCTION public.list_open_prescription_scans() RETURNS TABLE(file_id uuid, patient_id uuid, patient_given_name text, patient_family_name text, uploaded_at timestamp with time zone, uploaded_by_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS; die Rolle prueft die Funktion selbst.
  if not app.can_write_treatment_bases() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'treatment_bases.read', 'not allowed to read open prescription scans');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read open prescription scans' using errcode = '42501';
  end if;

  return query
    select f.id,
           f.patient_id,
           pe.given_name,
           pe.family_name,
           f.confirmed_at,
           nullif(btrim(concat_ws(' ', upe.given_name, upe.family_name)), '')
    from public.patient_files f
    join public.patients pa on pa.id = f.patient_id and pa.organization_id = f.organization_id
    join public.persons pe on pe.id = pa.person_id
    left join public.user_profiles up on up.id = f.uploaded_by
    left join public.persons upe on upe.id = up.person_id
    where f.organization_id = v_org
      and f.document_type = 'verordnungsscan'
      and f.treatment_basis_id is null
      and f.status = 'ready'
    order by f.confirmed_at asc, f.id;
end;
$$;

COMMENT ON FUNCTION public.list_open_prescription_scans() IS 'Verordnungsscans, die noch keiner Behandlungsgrundlage zugeordnet sind (PRX-011): Name, Tag, aufnehmende Person - kein Verweis auf das Bild (ADR-017 Punkt 15). Wer Grundlagen schreibt; ein abgewiesener Versuch wird als treatment_bases.read protokolliert. Das Lesen der Liste selbst ist wie die Kartei nicht auditiert; das Oeffnen des Fotos ist es (patient_file.link_issued).';

CREATE FUNCTION public.list_patient_appointment_slip(p_patient_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, location_name text, location_street text, location_house_number text, location_postal_code text, location_city text, staff_given_name text, staff_family_name text, organization_time_zone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_actor uuid;
  v_limit integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft. Wer den Kalender lesen darf, darf den Zettel drucken.
  if not app.can_read_appointments() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'patient_record.viewed', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_patient_id is null then
    raise exception 'patient is required' using errcode = '22023';
  end if;

  -- Eine unbekannte und eine fremde ID liefern dieselbe leere Antwort und
  -- erzeugen keinen Auditeintrag (PROJECT_PRINCIPLES.md 13).
  if not exists (
    select 1 from public.patients p
    where p.id = p_patient_id and p.organization_id = v_org
  ) then
    return;
  end if;

  v_limit := least(greatest(coalesce(p_limit, 20), 1), 50);

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      a.appointment_type,
      l.name,
      -- UX-009a: Anschrift des Standorts nur am Praxistermin - beim
      -- Hausbesuch ist es die eigene Wohnung, beim Video gibt es keinen Ort.
      case when a.appointment_type = 'practice' then l.street end,
      case when a.appointment_type = 'practice' then l.house_number end,
      case when a.appointment_type = 'practice' then l.postal_code end,
      case when a.appointment_type = 'practice' then l.city end,
      sp.given_name,
      sp.family_name,
      o.time_zone
    from public.appointments a
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    join public.organizations o  on o.id  = a.organization_id
    left join public.locations l on l.id  = a.location_id
    where a.organization_id = v_org
      and a.patient_id      = p_patient_id
      and a.starts_at > now()
      -- Nur bestaetigte Termine: ein abgesagter gehoert nicht auf einen Zettel,
      -- den jemand mitnimmt (ADR-018).
      and a.status = 'confirmed'
    order by a.starts_at, a.id
    limit v_limit;
end;
$$;

COMMENT ON FUNCTION public.list_patient_appointment_slip(p_patient_id uuid, p_limit integer) IS 'Terminzettel (CAL-011): bevorstehende bestaetigte Termine einer Patient:in mit Datum, Ort und behandelnder Person; seit UX-009a am Praxistermin mit der Anschrift des Standorts. Kein Status, keine Verordnung, kein Behandlungsinhalt. Akte geoeffnet hoechstens einmal je Tag (LOG-EPIC-001).';

CREATE FUNCTION public.list_patient_appointments(p_patient_id uuid, p_upcoming boolean DEFAULT false, p_limit integer DEFAULT 20, p_after_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_treatment_basis_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, status text, staff_given_name text, staff_family_name text, notification_channels text[], treatment_basis_id uuid, treatment_basis_kind text, treatment_basis_issued_on date, treatment_basis_covered boolean, organization_time_zone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_upcoming boolean := coalesce(p_upcoming, false);
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_read_appointments() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_patient_id is null then
    raise exception 'patient is required' using errcode = '22023';
  end if;

  if p_limit is null or p_limit < 1 or p_limit > 50 then
    raise exception 'limit out of range' using errcode = '22023';
  end if;

  -- Der Cursor besteht aus beiden Teilen oder gar nicht.
  if (p_after_starts_at is null) <> (p_after_id is null) then
    raise exception 'cursor is incomplete' using errcode = '22023';
  end if;

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      a.appointment_type,
      a.status,
      sp.given_name,
      sp.family_name,
      app.appointment_notification_channels(a.id),
      a.treatment_basis_id,
      -- GRD-001: Die Bauart kommt mit, weil die Liste die Grundlage benennen
      -- soll und nicht raten darf, ob sie eine Verordnung ist (ADR-020 Punkt
      -- 7). Sie ist organisatorisch - eine Diagnose steht hier nicht.
      pr.treatment_basis_kind,
      pr.issued_on,
      -- CAL-022: Ungedeckt heisst sichtbar - auch in der Liste, nicht nur an
      -- der Grundlage.
      app.appointment_is_covered(a.id),
      o.time_zone
    from public.appointments a
    join public.staff_members sm  on sm.id = a.staff_member_id
    join public.persons sp        on sp.id = sm.person_id
    join public.organizations o   on o.id  = a.organization_id
    left join public.treatment_bases pr on pr.id = a.treatment_basis_id
    where a.organization_id = v_org
      and a.patient_id      = p_patient_id
      and (p_treatment_basis_id is null or a.treatment_basis_id = p_treatment_basis_id)
      and (
        case when v_upcoming then a.starts_at > now() else a.starts_at <= now() end
      )
      and (
        p_after_starts_at is null
        or (
          case
            when v_upcoming then (a.starts_at, a.id) > (p_after_starts_at, p_after_id)
            else (a.starts_at, a.id) < (p_after_starts_at, p_after_id)
          end
        )
      )
    -- Die Richtung steckt in der Sortierung: In jedem Lauf sind zwei der vier
    -- Ausdruecke fuer JEDE Zeile null und damit wirkungslos - uebrig bleibt
    -- genau das Paar der gewaehlten Richtung. Das ist billiger als zwei
    -- Rumpfvarianten derselben Abfrage, die getrennt gepflegt werden muessten.
    order by
      case when v_upcoming then a.starts_at end asc,
      case when v_upcoming then a.id end asc,
      case when not v_upcoming then a.starts_at end desc,
      case when not v_upcoming then a.id end desc
    limit p_limit;
end;
$$;

COMMENT ON FUNCTION public.list_patient_appointments(p_patient_id uuid, p_upcoming boolean, p_limit integer, p_after_starts_at timestamp with time zone, p_after_id uuid, p_treatment_basis_id uuid) IS 'Termine einer Patient:in fuer die Akte (AKTE-001): kommend oder vergangen, alle Zustaende, mit Mitteilungsvermerk und Bezug zur Behandlungsgrundlage samt ihrer Bauart und - seit CAL-022 - ihrer Deckung, geblaettert ueber einen Keyset-Cursor. Rein organisatorisch, ohne Anschrift und ohne klinische Inhalte.';

CREATE FUNCTION public.list_patient_course_events(p_patient_id uuid) RETURNS TABLE(id uuid, occurred_on date, kind text, note text, created_at timestamp with time zone, author_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    perform app.record_denied_read(v_actor, 'patient_course_event.viewed', 'not allowed to read course events');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read course events' using errcode = '42501';
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.patient_course_events e where e.patient_id = p_patient_id and e.organization_id = v_org and e.removed_at is null) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
  end if;

  return query
    select e.id, e.occurred_on, e.kind, e.note, e.created_at, up.display_name
    from public.patient_course_events e
    left join public.user_profiles up on up.id = e.created_by
    where e.patient_id = p_patient_id and e.organization_id = v_org and e.removed_at is null
    order by e.occurred_on, e.created_at;
end;
$$;

COMMENT ON FUNCTION public.list_patient_course_events(p_patient_id uuid) IS 'Markierungen im Verlauf einer Akte (FRB-002e). Alle vier Praxisrollen; je Markierung protokolliert als patient_course_event.viewed, abgewiesen mit denied-Eintrag (ADR-010, G6a).';

CREATE FUNCTION public.list_patient_files(p_patient_id uuid, p_treatment_basis_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, treatment_basis_id uuid, document_type text, is_clinical boolean, display_name text, mime_type text, byte_size bigint, uploaded_at timestamp with time zone, uploaded_by_name text, object_missing boolean, verified_at timestamp with time zone, released_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- G6b: Die Rollenpruefung steht vor der Akte, denn app.patient_file_organization
  -- prueft das Leserecht auf das Verzeichnis mit und wiese sonst mit Ausnahme ab.
  if not app.can_read_patient_files() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'patient_files.read', 'not allowed to read patient files');
    return;
  end if;

  v_org := app.patient_file_organization(p_patient_id);
  if v_org is null then
    raise exception 'patient not accessible' using errcode = '42501';
  end if;

  return query
    select f.id,
           f.treatment_basis_id,
           f.document_type,
           t.is_clinical,
           f.display_name,
           f.mime_type,
           f.byte_size,
           f.confirmed_at,
           nullif(btrim(coalesce(pe.given_name, '') || ' ' || coalesce(pe.family_name, '')), ''),
           not exists (
             select 1
             from storage.objects o
             where o.bucket_id = app.patient_file_bucket_for(f.document_type)
               and o.name = f.object_key
           ),
           f.verified_at,
           f.released_at
    from public.patient_files f
    join public.patient_file_document_types t on t.key = f.document_type
    left join public.user_profiles up on up.id = f.uploaded_by
    left join public.persons pe on pe.id = up.person_id
    where f.patient_id = p_patient_id
      and f.organization_id = v_org
      and f.status = 'ready'
      and not app.is_patient_photo_type(f.document_type)
      and (p_treatment_basis_id is null or f.treatment_basis_id = p_treatment_basis_id)
      and app.can_see_patient_file_type(f.document_type)
    order by f.confirmed_at desc, f.id;
end;
$$;

COMMENT ON FUNCTION public.list_patient_files(p_patient_id uuid, p_treatment_basis_id uuid) IS 'Dateien einer Akte oder Grundlage (DAT-001), seit POR-014 mit released_at: fuer die Person auf der Plattform freigegeben (DSN-001 D3).';

CREATE FUNCTION public.list_patient_invoices(p_patient_id uuid) RETURNS TABLE(id uuid, status text, invoice_number text, period_month date, issued_on date, due_on date, total_cents integer, paid_cents integer, outstanding_cents integer, currency text, payment_state text, overdue boolean, cancelled boolean, reminder_due boolean, last_reminder_on date, treatment_basis_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read invoices' using errcode = '42501';
  end if;

  if p_patient_id is null then
    raise exception 'patient is required' using errcode = '22023';
  end if;

  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;

  return query
    with rechnung as (
      select i.*,
             coalesce(z.bezahlt, 0) as bezahlt,
             exists (select 1 from public.invoice_cancellations c where c.invoice_id = i.id)
               as storniert
      from public.invoices i
      left join lateral (
        select sum(case when p.direction = 'incoming' then p.amount_cents
                        else -p.amount_cents end)::integer as bezahlt
        from public.payments p
        where p.invoice_id = i.id
          and p.voided_at is null
      ) z on true
      where i.organization_id = v_org
        and i.patient_id = p_patient_id
    )
    select r.id,
           r.status,
           r.invoice_number,
           r.period_month,
           r.issued_on,
           r.due_on,
           -- Der Entwurf rechnet live, die ausgestellte Rechnung zeigt ihren
           -- festgeschriebenen Betrag (ADR-009 Punkt 10).
           coalesce(r.total_cents, summe.brutto)::integer,
           case when r.status = 'issued' then r.bezahlt else 0 end,
           case when r.status = 'issued' and not r.storniert
                then greatest(r.total_cents - r.bezahlt, 0) else 0 end,
           coalesce(r.currency, summe.currency),
           case when r.status = 'issued'
                then app.invoice_payment_state(r.total_cents, r.bezahlt)
                else 'unpaid' end,
           (r.status = 'issued' and not r.storniert and r.due_on < v_heute
            and r.bezahlt < r.total_cents),
           r.storniert,
           (r.status = 'issued' and not r.storniert
            and app.invoice_reminder_due(r.id, r.due_on, r.total_cents - r.bezahlt, v_heute)),
           (select max(m.reminder_on) from public.invoice_payment_reminders m where m.invoice_id = r.id),
           r.treatment_basis_id
    from rechnung r
    left join lateral (
      select sum(app.billable_service_amount(b.id)) as brutto,
             max(c.currency) as currency
      from public.invoice_items it
      join public.billable_services b     on b.id = it.billable_service_id
      join public.service_catalog_items c on c.id = b.catalog_item_id
      where it.invoice_id = r.id
    ) summe on true
    order by r.status, r.issued_on desc nulls first, r.invoice_number desc nulls first, r.id;
end;
$$;

COMMENT ON FUNCTION public.list_patient_invoices(p_patient_id uuid) IS 'B1 (BEF-151): die Rechnungen einer Person fuer die Akte - Entwurf oder ausgestellt, Betrag, Bezahltes, Offenes, Zahlungsstand, ueberfaellig, storniert, zu mahnen (ANN-516) und die letzte Zahlungserinnerung, dazu die Grundlage. Nur fuer can_read_invoicing (owner, office).';

CREATE FUNCTION public.list_patient_merge_records(p_patient_id uuid) RETURNS TABLE(id uuid, merged_at timestamp with time zone, merged_by_name text, counts jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_patient_directory() then
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read merge records');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    return;
  end if;
  return query
    select mr.id, mr.merged_at, up.display_name, mr.counts
    from public.patient_merge_records mr
    left join public.user_profiles up on up.id = mr.merged_by
    where mr.target_patient_id = p_patient_id and mr.organization_id = v_org
    order by mr.merged_at desc;
end;
$$;

COMMENT ON FUNCTION public.list_patient_merge_records(p_patient_id uuid) IS 'Vermerke des Zusammenfuehrens an einer Akte (ABN-018, BEF-108): wann, durch wen, was mitgezogen ist. Wer das Verzeichnis liest; nur Zahlen, keine Inhalte. Abgewiesen wird protokolliert; ein erfolgreiches Lesen nicht eigens, weil es Teil der Akte ist, deren Oeffnen schon als patient_record.viewed protokolliert wird.';

CREATE FUNCTION public.list_patient_overview() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org        uuid;
  v_zeitzone   text;
  v_heute      date;
  v_abrechnung boolean;
  v_liste      jsonb;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_patient_directory() then
    -- G6b: abgewiesen wird mit leerer Liste und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read the patient directory');
    return '[]'::jsonb;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read the patient directory' using errcode = '42501';
  end if;

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;
  -- ANN-139: Rechnungen und Zahlungen nur fuer die Rollen der Abrechnung.
  v_abrechnung := app.can_read_invoicing();

  with personen as (
    select p.id, pe.given_name, pe.family_name,
           c.date_of_birth, c.email, c.phone, c.postal_code, c.city
    from public.patients p
    join public.persons pe on pe.id = p.person_id
    left join public.patient_contact_details c on c.patient_id = p.id
    where p.organization_id = v_org
  ),
  termine as (
    select a.patient_id,
           max((a.starts_at at time zone v_zeitzone)::date)
             filter (where a.starts_at <= now() and a.status not in ('cancelled', 'no_show'))
             as zuletzt,
           min(a.starts_at)
             filter (where a.status = 'confirmed' and a.starts_at > now())
             as naechster
    from public.appointments a
    where a.organization_id = v_org
      and a.kind = 'therapy'
      and a.patient_id is not null
    group by a.patient_id
  ),
  grundlagen as (
    select tb.patient_id,
           count(*) filter (where s.state in ('laeuft', 'termine_fehlen', 'nachholen', 'abrechnen'))
             as offen,
           count(*) filter (where s.state = 'termine_fehlen') as termine_fehlen,
           count(*) filter (where s.state = 'nachholen') as nachholen,
           count(*) filter (where s.state = 'abrechnen') as abrechnen,
           count(*) filter (where s.state = 'in_abrechnung') as in_abrechnung
    from public.treatment_bases tb
    cross join lateral app.treatment_basis_billing(tb.id) s
    where tb.organization_id = v_org
    group by tb.patient_id
  ),
  rechnungen as (
    select i.patient_id,
           count(*) as gestellt,
           count(*) filter (where z.bezahlt >= i.total_cents) as bezahlt,
           sum(greatest(i.total_cents - z.bezahlt, 0)) as offen_cents,
           count(*) filter (where i.total_cents - z.bezahlt > 0 and i.due_on < v_heute)
             as ueberfaellig,
           count(*) filter (where app.invoice_reminder_due(i.id, i.due_on, i.total_cents - z.bezahlt, v_heute))
             as mahnen
    from public.invoices i
    left join lateral (
      select coalesce(sum(case when p.direction = 'incoming' then p.amount_cents
                               else -p.amount_cents end), 0)::integer as bezahlt
      from public.payments p
      where p.invoice_id = i.id
        and p.voided_at is null
    ) z on true
    where v_abrechnung
      and i.organization_id = v_org
      and i.status = 'issued'
      and i.patient_id is not null
      -- Eine stornierte Rechnung ist keine Forderung mehr (ABR-003c).
      and not exists (select 1 from public.invoice_cancellations c where c.invoice_id = i.id)
    group by i.patient_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', pe.id,
           'given_name', pe.given_name,
           'family_name', pe.family_name,
           'date_of_birth', pe.date_of_birth,
           'email', pe.email,
           'phone', pe.phone,
           'postal_code', pe.postal_code,
           'city', pe.city,
           'last_visit_on', t.zuletzt,
           'next_appointment_at', t.naechster,
           'open_bases', coalesce(g.offen, 0),
           'bases_need_appointments', coalesce(g.termine_fehlen, 0),
           'bases_need_followup', coalesce(g.nachholen, 0),
           'bases_ready', coalesce(g.abrechnen, 0),
           'bases_in_billing', coalesce(g.in_abrechnung, 0),
           'billing_visible', v_abrechnung,
           'invoices_issued', case when v_abrechnung then coalesce(r.gestellt, 0) end,
           'invoices_paid', case when v_abrechnung then coalesce(r.bezahlt, 0) end,
           'outstanding_cents', case when v_abrechnung then coalesce(r.offen_cents, 0) end,
           'invoices_overdue', case when v_abrechnung then coalesce(r.ueberfaellig, 0) end,
           'reminders_due', case when v_abrechnung then coalesce(r.mahnen, 0) end
         ) order by pe.family_name, pe.given_name, pe.id), '[]'::jsonb)
    into v_liste
  from personen pe
  left join termine t on t.patient_id = pe.id
  left join grundlagen g on g.patient_id = pe.id
  left join rechnungen r on r.patient_id = pe.id;

  return v_liste;
end;
$$;

COMMENT ON FUNCTION public.list_patient_overview() IS 'B1/B10 (BEF-151, BEF-160): die Patientenliste als ein JSON-Wert - Name, Geburtsdatum, Ort und Kontakt wie patient_list_entries, dazu zuletzt behandelt, naechster Termin, Grundlagen je Zustand (offen, Termine fehlen, nachholen, abrechnen, in Abrechnung) und fuer owner/office Rechnungen, Bezahltes, Offenes, Ueberfaelliges und zu Mahnendes (ANN-516). Ein Wert statt Zeilen, damit die Liste nicht bei 200 Personen endet. Nur fuer can_read_patient_directory.';

CREATE FUNCTION public.list_patient_photos(p_patient_id uuid) RETURNS TABLE(id uuid, document_type text, display_name text, taken_at timestamp with time zone, taken_by_name text, delete_after timestamp with time zone, deletable boolean, object_missing boolean, verified_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not (app.can_see_patient_file_type('patientenfoto')
          or app.can_see_patient_file_type('dokumentationsfoto')) then
    perform app.record_denied_read(auth.uid(), 'patient_files.read', 'not allowed to read patient photos');
    return;
  end if;

  v_org := app.patient_file_organization(p_patient_id);
  if v_org is null then
    raise exception 'patient not accessible' using errcode = '42501';
  end if;

  return query
    select f.id,
           f.document_type,
           f.display_name,
           f.created_at,
           nullif(btrim(coalesce(pe.given_name, '') || ' ' || coalesce(pe.family_name, '')), ''),
           case when f.document_type = 'patientenfoto'
             then app.patient_photo_due_at(f.patient_id, f.created_at, f.photo_locked_at)
           end,
           app.can_write_patient_file(f.document_type, f.treatment_basis_id)
             and (f.document_type <> 'dokumentationsfoto'
                  or app.documentation_photo_deletable(f.organization_id, f.uploaded_by, f.created_at)),
           not exists (
             select 1
             from storage.objects o
             where o.bucket_id = app.patient_file_bucket_for(f.document_type)
               and o.name = f.object_key
           ),
           f.verified_at
    from public.patient_files f
    left join public.user_profiles up on up.id = f.uploaded_by
    left join public.persons pe on pe.id = up.person_id
    where f.patient_id = p_patient_id
      and f.organization_id = v_org
      and f.status = 'ready'
      and app.is_patient_photo_type(f.document_type)
      and app.can_see_patient_file_type(f.document_type)
      and app.patient_photo_usable(f.document_type, f.patient_id, f.created_at, f.photo_locked_at)
    order by f.created_at desc, f.id;
end;
$$;

CREATE FUNCTION public.list_patient_photos_for_access_request(p_patient_id uuid) RETURNS TABLE(id uuid, document_type text, display_name text, taken_at timestamp with time zone, locked boolean, object_missing boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Dieselbe Pruefung wie die Auskunft: owner, eigene Organisation, eigene Akte.
  v_org := app.auskunft_organisation(p_patient_id);

  return query
    select f.id,
           f.document_type,
           f.display_name,
           f.created_at,
           not app.patient_photo_usable(f.document_type, f.patient_id, f.created_at, f.photo_locked_at),
           not exists (
             select 1 from storage.objects o
             where o.bucket_id = app.patient_file_bucket_for(f.document_type) and o.name = f.object_key)
    from public.patient_files f
    where f.patient_id = p_patient_id
      and f.organization_id = v_org
      and f.status = 'ready'
      and app.is_patient_photo_type(f.document_type)
    order by f.created_at desc, f.id;
end;
$$;

COMMENT ON FUNCTION public.list_patient_photos_for_access_request(p_patient_id uuid) IS 'Die Fotos einer Akte fuer die Herausgabe nach Art. 15 Abs. 3 DSGVO - Dokumentationsfotos und Arbeitshilfen, auch gesperrte, solange sie vorhanden sind (ABN-017, ABN-023). Nur owner, wie export_patient_record; nur Metadaten.';

CREATE FUNCTION public.list_patient_questionnaire_responses(p_patient_id uuid) RETURNS TABLE(id uuid, instrument_id text, definition_version text, status text, recorded_on date, answers jsonb, supersedes_response_id uuid, superseded_by_response_id uuid, change_reason text, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, author_name text, completed_by_name text, source text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    perform app.record_denied_read(v_actor, 'questionnaire_response.viewed', 'not allowed to read questionnaires');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read questionnaires' using errcode = '42501';
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.patient_questionnaire_responses r where r.patient_id = p_patient_id and r.organization_id = v_org) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
  end if;

  return query
    select
      r.id,
      r.instrument_id,
      r.definition_version,
      r.status,
      r.recorded_on,
      r.answers,
      r.supersedes_response_id,
      nachfolger.id,
      r.change_reason,
      r.created_at,
      r.updated_at,
      r.completed_at,
      verfasser.display_name,
      abschluss.display_name,
      r.source
    from public.patient_questionnaire_responses r
    left join public.patient_questionnaire_responses nachfolger
           on nachfolger.supersedes_response_id = r.id
    left join public.user_profiles verfasser on verfasser.id = r.created_by
    left join public.user_profiles abschluss on abschluss.id = r.completed_by
    where r.patient_id = p_patient_id and r.organization_id = v_org
    order by r.recorded_on desc, r.created_at desc;
end;
$$;

COMMENT ON FUNCTION public.list_patient_questionnaire_responses(p_patient_id uuid) IS 'Erhobene Frageboegen einer Akte (FRB-002b), seit POR-012 mit Herkunft (source: practice oder platform). Alle vier Praxisrollen; Akte geoeffnet einmal je Tag (ADR-010 Fassung 3).';

CREATE FUNCTION public.list_patient_therapy_reports(p_patient_id uuid) RETURNS TABLE(id uuid, treatment_basis_id uuid, status text, created_at timestamp with time zone, author_name text, completed_at timestamp with time zone, completed_on date, completed_by_name text, recommendation text, recommendation_by_name text, recommendation_on date, supersedes_report_id uuid, superseded_by_report_id uuid, change_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_tz    text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    perform app.record_denied_read(v_actor, 'therapy_report.viewed', 'not allowed to read therapy reports');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read therapy reports' using errcode = '42501';
  end if;
  select o.time_zone into v_tz from public.organizations o where o.id = v_org;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.therapy_reports r where r.patient_id = p_patient_id and r.organization_id = v_org) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
  end if;

  return query
    select r.id, r.treatment_basis_id, r.status, r.created_at,
           (select up.display_name from public.user_profiles up where up.id = r.created_by),
           r.completed_at,
           (r.completed_at at time zone v_tz)::date,
           (select up.display_name from public.user_profiles up where up.id = r.completed_by),
           -- Nur beim abgeschlossenen Bericht: Ein Entwurf ist noch keine
           -- Empfehlung an irgendwen, und die Liste braucht ihn nicht.
           r.snapshot -> 'empfehlung' ->> 'inhalt',
           r.snapshot -> 'empfehlung' ->> 'verfasser',
           (r.snapshot -> 'empfehlung' ->> 'datum')::date,
           -- ABN-016 (BEF-104): die Kette der Korrekturen.
           r.supersedes_report_id,
           (select n.id from public.therapy_reports n where n.supersedes_report_id = r.id),
           r.change_reason
    from public.therapy_reports r
    where r.patient_id = p_patient_id and r.organization_id = v_org
    order by r.created_at;
end;
$$;

CREATE FUNCTION public.list_patient_treatment_bases(p_patient_id uuid) RETURNS TABLE(id uuid, prescriber_id uuid, prescriber_name text, prescriber_practice_name text, treatment_basis_kind text, issued_on date, frequency_note text, note text, items jsonb, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_ids  uuid[];
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_read_treatment_bases() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'treatment_bases.read', 'not allowed to read treatment_bases');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment_bases' using errcode = '42501';
  end if;

  v_ids := app.patient_treatment_basis_ids(v_org, p_patient_id);
  if v_ids is null then
    return;
  end if;

  return query
    select
      p.id,
      p.prescriber_id,
      -- nullif, damit beim Selbstzahler wirklich NICHTS dasteht: concat_ws
      -- ueberspringt Nullwerte und lieferte sonst den leeren String - eine
      -- Angabe, die es nicht gibt (GRD-001, ADR-020 Punkt 3).
      nullif(btrim(concat_ws(' ', v.title, v.given_name, v.family_name)), ''),
      v.practice_name,
      p.treatment_basis_kind,
      p.issued_on,
      p.frequency_note,
      -- ANN-011: die organisatorische Bemerkung ja, die klinischen Felder
      -- ausdruecklich nicht. Diese Spaltenliste ist die Grenze.
      p.note,
      app.treatment_base_items_json(p.id),
      p.updated_at
    from public.treatment_bases p
    -- LEFT JOIN seit GRD-001: Ein Selbstzahler hat keine Verordner:in
    -- (ADR-020 Punkt 3). Ein innerer Verbund liesse ihn aus der Projektion
    -- fallen - die Zeile waere da, die Akte zeigte sie nicht.
    left join public.prescribers v on v.id = p.prescriber_id
    where p.id = any (v_ids)
    order by p.issued_on desc, p.created_at desc, p.id desc;
end;
$$;

COMMENT ON FUNCTION public.list_patient_treatment_bases(p_patient_id uuid) IS 'Organisatorische Sicht der Behandlungsgrundlagen einer Patientin (VER-002, ANN-011): Verordner:in, Bauart, Datum, Frequenz und Kontingent. Ohne klinische Felder.';

CREATE FUNCTION public.list_patient_treatment_bases_clinical(p_patient_id uuid) RETURNS TABLE(id uuid, prescriber_id uuid, prescriber_name text, prescriber_practice_name text, treatment_basis_kind text, issued_on date, frequency_note text, note text, items jsonb, updated_at timestamp with time zone, diagnosis text, therapy_goal text, prescriber_note text, follow_up_recommendation text, diagnosis_icd10 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_ids   uuid[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Dieselbe Rollenmenge wie bei der Behandlungsdokumentation: die Grundlage
  -- oeffnet keinen zweiten Weg zu klinischem Freitext (4.3, 4.6).
  if not app.can_read_treatment_basis_clinical() then
    -- G6a: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'treatment_basis.viewed', 'not allowed to read clinical treatment basis data');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read clinical treatment basis data' using errcode = '42501';
  end if;

  v_ids := app.patient_treatment_basis_ids(v_org, p_patient_id);
  if v_ids is null then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if coalesce(cardinality(v_ids), 0) > 0 then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
  end if;

  return query
    select
      p.id,
      p.prescriber_id,
      -- nullif, damit beim Selbstzahler wirklich NICHTS dasteht: concat_ws
      -- ueberspringt Nullwerte und lieferte sonst den leeren String - eine
      -- Angabe, die es nicht gibt (GRD-001, ADR-020 Punkt 3).
      nullif(btrim(concat_ws(' ', v.title, v.given_name, v.family_name)), ''),
      v.practice_name,
      p.treatment_basis_kind,
      p.issued_on,
      p.frequency_note,
      p.note,
      app.treatment_base_items_json(p.id),
      p.updated_at,
      p.diagnosis,
      p.therapy_goal,
      p.prescriber_note,
      -- ANN-014: die Empfehlung der Therapeut:in, von ihr selbst erfasst.
      p.follow_up_recommendation,
      p.diagnosis_icd10
    from public.treatment_bases p
    -- LEFT JOIN seit GRD-001: Ein Selbstzahler hat keine Verordner:in
    -- (ADR-020 Punkt 3). Ein innerer Verbund liesse ihn aus der Projektion
    -- fallen - die Zeile waere da, die Akte zeigte sie nicht.
    left join public.prescribers v on v.id = p.prescriber_id
    where p.id = any (v_ids)
    order by p.issued_on desc, p.created_at desc, p.id desc;
end;
$$;

CREATE FUNCTION public.list_patient_treatment_basis_slots(p_patient_id uuid) RETURNS TABLE(treatment_basis_id uuid, prescribed integer, used integer, planned integer, upcoming integer, remaining integer, covered integer, uncovered integer, performed integer, documented integer, open_count integer, past_open integer, state text, released_at timestamp with time zone, invoiced boolean, can_release boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_darf  boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_bases() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'treatment_bases.read', 'not allowed to read treatment_bases');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment_bases' using errcode = '42501';
  end if;

  if p_patient_id is null then
    raise exception 'patient is required' using errcode = '22023';
  end if;

  v_darf := app.can_release_treatment_basis();

  return query
    select
      p.id,
      zahlen.prescribed,
      zahlen.used,
      zahlen.planned,
      (
        select count(*)::integer
        from public.appointments a
        where a.treatment_basis_id = p.id
          and a.organization_id = v_org
          and a.status not in ('cancelled', 'no_show')
          and a.starts_at > now()
      ),
      zahlen.remaining,
      zahlen.covered,
      zahlen.uncovered,
      stand.performed,
      stand.documented,
      stand.open_count,
      stand.past_open,
      stand.state,
      stand.released_at,
      stand.invoiced,
      (v_darf and stand.ready)
    from public.treatment_bases p
    cross join lateral app.treatment_basis_slot_counts(p.id, v_org) zahlen
    cross join lateral app.treatment_basis_billing(p.id) stand
    where p.organization_id = v_org
      and p.patient_id = p_patient_id
    order by p.issued_on desc, p.id desc;
end;
$$;

COMMENT ON FUNCTION public.list_patient_treatment_basis_slots(p_patient_id uuid) IS 'Kontingente aller Grundlagen einer Person, gezaehlt in Terminen (ANN-064), und seit B1/B7 ihr Stand fuer die Abrechnung (ANN-514): erbracht, dokumentiert, offen, nachzuholen, Zustand, freigegeben, abgerechnet und ob die angemeldete Person sie jetzt in die Abrechnung stellen kann.';

CREATE FUNCTION public.list_patient_treatment_evidence(p_patient_id uuid, p_limit integer DEFAULT 20, p_before_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(appointment_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, appointment_status text, staff_given_name text, staff_family_name text, organization_time_zone text, documentation_status text, documented_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_read_treatment_evidence() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'treatment_evidence.read', 'not allowed to read treatment evidence');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment evidence' using errcode = '42501';
  end if;

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      a.appointment_type,
      a.status,
      sp.given_name,
      sp.family_name,
      o.time_zone,
      -- ANN-006: Dokumentationsstand ohne Inhalt, Zeitpunkt nur fuer
      -- finalisierte Eintraege.
      case when t.id is null then 'none' else t.status end,
      case when t.status = 'final' then t.finalized_at else null end
    from app.patient_record_page(
           v_org, p_patient_id, p_limit, p_before_starts_at, p_before_id
         ) seite
    join public.appointments a    on a.id  = seite.appointment_id
    join public.staff_members sm  on sm.id = a.staff_member_id
    join public.persons sp        on sp.id = sm.person_id
    join public.organizations o   on o.id  = a.organization_id
    left join public.treatment_notes t
           on t.appointment_id = a.id
          and t.addendum_to_note_id is null
    order by a.starts_at desc, a.id desc;
end;
$$;

COMMENT ON FUNCTION public.list_patient_treatment_evidence(p_patient_id uuid, p_limit integer, p_before_starts_at timestamp with time zone, p_before_id uuid) IS 'Behandlungsnachweis in der Akte (DOK-003, PROJECT_PRINCIPLES.md 4.4, ANN-006): Termine eines Patienten mit Status und Dokumentationsstand, ohne klinischen Inhalt. Einzige Sicht auf Dokumentationsmetadaten fuer office.';

CREATE FUNCTION public.list_patient_treatment_notes(p_patient_id uuid, p_limit integer DEFAULT 20, p_before_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(appointment_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, appointment_status text, staff_given_name text, staff_family_name text, organization_time_zone text, notes jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_seite uuid[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    -- G6a: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'treatment_note.viewed', 'not allowed to read treatment documentation');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read treatment documentation' using errcode = '42501';
  end if;

  select array_agg(s.appointment_id order by s.starts_at desc, s.appointment_id desc)
    into v_seite
  from app.patient_record_page(
         v_org, p_patient_id, p_limit, p_before_starts_at, p_before_id
       ) s;

  if v_seite is null then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.treatment_notes t where t.appointment_id = any (v_seite)) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
  end if;

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      a.appointment_type,
      a.status,
      sp.given_name,
      sp.family_name,
      o.time_zone,
      coalesce((
        select jsonb_agg(
                 jsonb_build_object(
                   'id',                  t.id,
                   'appointment_id',      t.appointment_id,
                   'addendum_to_note_id', t.addendum_to_note_id,
                   'status',              t.status,
                   'content',             t.content,
                   -- Der Pflichtvermerk aus Hausbesuch-Szenario 1 (CAL-018).
                   'visit_without_treatment', t.visit_without_treatment,
                   'created_at',          t.created_at,
                   'updated_at',          t.updated_at,
                   'finalized_at',        t.finalized_at,
                   'finalisation_kind',   t.finalisation_kind,
                   'version_count',       (select count(*)
                                             from public.treatment_note_versions v
                                            where v.note_id = t.id),
                   'author_name',         verfasser.display_name,
                   'last_editor_name',    bearbeiter.display_name,
                   'finalized_by_name',   finalisierer.display_name
                 )
                 order by (t.addendum_to_note_id is not null), t.created_at
               )
        from public.treatment_notes t
        left join public.user_profiles verfasser    on verfasser.id    = t.created_by
        left join public.user_profiles bearbeiter   on bearbeiter.id   = t.updated_by
        left join public.user_profiles finalisierer on finalisierer.id = t.finalized_by
        where t.appointment_id = a.id
      ), '[]'::jsonb)
    from public.appointments a
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    join public.organizations o  on o.id  = a.organization_id
    where a.id = any (v_seite)
    order by a.starts_at desc, a.id desc;
end;
$$;

COMMENT ON FUNCTION public.list_patient_treatment_notes(p_patient_id uuid, p_limit integer, p_before_starts_at timestamp with time zone, p_before_id uuid) IS 'Klinische Sicht der Akte (DOK-003, DOK-004, ROL-001, CAL-018): Termine eines Patienten mit ihren Eintraegen samt Inhalt, Art der Finalisierung und Pflichtvermerk aus Hausbesuch-Szenario 1, protokolliert je Eintrag treatment_note.viewed (ADR-010, ADR-016 Punkt 8 und 9). owner, therapist, team_lead und office.';

CREATE FUNCTION public.list_patient_upcoming_appointments(p_patient_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, status text, staff_given_name text, staff_family_name text, notification_channels text[], organization_time_zone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_limit integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_appointments() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read appointments');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read appointments' using errcode = '42501';
  end if;

  if p_patient_id is null then
    raise exception 'patient is required' using errcode = '22023';
  end if;

  v_limit := least(greatest(coalesce(p_limit, 5), 1), 20);

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      a.appointment_type,
      a.status,
      sp.given_name,
      sp.family_name,
      app.appointment_notification_channels(a.id),
      o.time_zone
    from public.appointments a
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    join public.organizations o  on o.id  = a.organization_id
    where a.organization_id = v_org
      and a.patient_id      = p_patient_id
      and a.starts_at > now()
      and a.status <> 'cancelled'
    order by a.starts_at, a.id
    limit v_limit;
end;
$$;

COMMENT ON FUNCTION public.list_patient_upcoming_appointments(p_patient_id uuid, p_limit integer) IS 'Die naechsten Termine einer Patientin fuer die Akte (UX-006), mit den seit der letzten Aenderung vermerkten Mitteilungswegen (CAL-012). Ohne Adresse und ohne klinische Inhalte.';

CREATE FUNCTION public.list_payments(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, invoice_id uuid, invoice_number text, patient_name text, recipient_name text, direction text, amount_cents integer, currency text, paid_on date, method text, note text, voided_at timestamp with time zone, void_reason text, total_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoices');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select p.id, p.invoice_id, i.invoice_number,
         pe.given_name || ' ' || pe.family_name,
         coalesce(app.invoice_recipient_name(i.status, i.snapshot, r.name),
                  pe.given_name || ' ' || pe.family_name),
         p.direction, p.amount_cents, p.currency, p.paid_on, p.method,
         p.note, p.voided_at, p.void_reason,
         count(*) over ()::integer
  from public.payments p
  join public.invoices  i  on i.id = p.invoice_id
  -- TRN-008: der Name aus dem Verhaeltnis der Rechnung.
  left join public.patients pa on pa.id = i.patient_id
  left join public.training_relationships t on t.id = i.training_relationship_id
  join public.persons pe on pe.id = coalesce(pa.person_id, t.person_id)
  left join public.invoice_recipients r on r.id = i.recipient_id
  where p.organization_id = v_org
  order by p.paid_on desc, p.created_at desc, p.id
  limit greatest(least(coalesce(p_limit, 100), 200), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;

COMMENT ON FUNCTION public.list_payments(p_limit integer, p_offset integer) IS 'Zahlungen der Praxis, neueste zuerst, mit Blaettern; total_count vor dem Kuerzen (ABR-033, BEF-061); Empfaenger der ausgestellten Rechnung aus dem Snapshot (BEF-141).';

CREATE FUNCTION public.list_platform_aftercare_cancellations() RETURNS TABLE(subscription_id uuid, patient_id uuid, given_name text, family_name text, cancelled_on date, ends_on date, cancelled_access_kind text, cancelled_representative_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null or not app.can_manage_aftercare() then
    return;
  end if;

  return query
  select s.id, s.patient_id, pe.given_name, pe.family_name, s.cancelled_on, s.ends_on,
         s.cancelled_access_kind, s.cancelled_representative_name
  from public.aftercare_subscriptions s
  join public.patients p on p.id = s.patient_id
  join public.persons pe on pe.id = p.person_id
  where s.organization_id = v_org
    and s.cancelled_via = 'platform'
    and s.cancelled_at > now() - make_interval(days => app.platform_withdrawal_notice_days())
  order by s.cancelled_at desc, s.id;
end;
$$;

COMMENT ON FUNCTION public.list_platform_aftercare_cancellations() IS 'ANG-003: Kuendigungen des Nachsorge-Abos ueber die Plattform der letzten 14 Tage fuer Offene Punkte (owner, office; wie ANN-263). Ohne Recht keine Zeile.';

CREATE FUNCTION public.list_platform_appointment_requests(p_status text DEFAULT 'open'::text) RETURNS TABLE(id uuid, kind text, relationship_kind text, patient_id uuid, training_relationship_id uuid, given_name text, family_name text, appointment_id uuid, appointment_starts_at timestamp with time zone, appointment_ends_at timestamp with time zone, appointment_updated_at timestamp with time zone, appointment_status text, preferred_days date[], preferred_times text[], note text, status text, created_at timestamp with time zone, requested_by text, representative_name text, resolved_at timestamp with time zone, answer text, resulting_appointment_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not (app.may_write_appointment_context('therapy')
          or app.may_write_appointment_context('training')) then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to read requests');
    return;
  end if;
  v_org := app.current_organization_id();
  if p_status is not null and p_status not in ('open', 'done', 'declined', 'withdrawn') then
    raise exception 'unknown status' using errcode = '22023';
  end if;

  return query
  select w.id, w.kind, w.relationship_kind, w.patient_id, w.training_relationship_id,
         pe.given_name, pe.family_name,
         w.appointment_id, a.starts_at, a.ends_at, a.updated_at, a.status,
         w.preferred_days, w.preferred_times, w.note, w.status, w.created_at,
         z.access_kind, case when z.access_kind <> 'self' then z.representative_name end,
         w.resolved_at, w.answer, w.resulting_appointment_id
  from public.platform_appointment_requests w
  join public.platform_accesses z on z.id = w.created_by_access_id
  left join public.patients pa on pa.id = w.patient_id
  left join public.training_relationships t on t.id = w.training_relationship_id
  left join public.persons pe on pe.id = coalesce(pa.person_id, t.person_id)
  left join public.appointments a on a.id = w.appointment_id
  where w.organization_id = v_org
    and (p_status is null or w.status = p_status)
    -- Je Kontext nur, wer dort Termine verwaltet (4.8).
    and app.may_write_appointment_context(
          case w.relationship_kind when 'training' then 'training' else 'therapy' end)
  order by (w.status <> 'open'), w.created_at, w.id;
end;
$$;

COMMENT ON FUNCTION public.list_platform_appointment_requests(p_status text) IS 'POR-011: Terminwuensche von der Plattform fuer die Praxis (DSN-001 Abschnitt 6): je Kontext die Rollen der Terminverwaltung (app.may_write_appointment_context). Mit Person, Termin und Urheber (Person oder Vertretung). Abgewiesen wird mit null Zeilen und denied-Eintrag.';

CREATE FUNCTION public.list_platform_consent_withdrawals() RETURNS TABLE(id uuid, relationship_kind text, patient_id uuid, training_relationship_id uuid, given_name text, family_name text, purpose text, occurred_on date, recorded_at timestamp with time zone, platform_access_kind text, representative_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    return;
  end if;

  return query
  select x.id, x.relationship_kind, x.patient_id, x.training_relationship_id, x.given_name,
         x.family_name, x.purpose, x.occurred_on, x.recorded_at, x.platform_access_kind,
         x.representative_name
  from (
    select r.id, 'treatment'::text as relationship_kind, r.patient_id,
           null::uuid as training_relationship_id, pe.given_name, pe.family_name,
           r.purpose, r.occurred_on, r.recorded_at, r.platform_access_kind, r.representative_name
    from public.patient_privacy_records r
    join public.patients p on p.id = r.patient_id
    join public.persons pe on pe.id = p.person_id
    where app.can_read_patient_directory()
      and r.organization_id = v_org
      and r.source = 'platform'
      and r.record_kind = 'consent_withdrawn'
      and r.recorded_at > now() - make_interval(days => app.platform_withdrawal_notice_days())
    union all
    select r.id, 'training'::text, null::uuid, r.training_relationship_id, pe.given_name,
           pe.family_name, r.purpose, r.occurred_on, r.recorded_at, r.platform_access_kind,
           r.representative_name
    from public.training_consent_records r
    join public.training_relationships t on t.id = r.training_relationship_id
    join public.persons pe on pe.id = t.person_id
    where app.can_read_training_relationships()
      and r.organization_id = v_org
      and r.source = 'platform'
      and r.record_kind = 'consent_withdrawn'
      and r.recorded_at > now() - make_interval(days => app.platform_withdrawal_notice_days())
    union all
    -- ERN-002: Widerrufe der Ernaehrungsberatung nur fuer die Faehigkeit
    -- (ADR-027 Punkt 4) - die Rollen der Kartei sehen sie nicht.
    select r.id, n.relationship_kind, n.patient_id, n.training_relationship_id, pe.given_name,
           pe.family_name, 'nutrition_counselling'::text, r.occurred_on, r.recorded_at,
           r.platform_access_kind, r.representative_name
    from public.nutrition_consent_records r
    join public.nutrition_profiles n on n.id = r.profile_id
    left join public.patients p on p.id = n.patient_id
    left join public.training_relationships t on t.id = n.training_relationship_id
    join public.persons pe on pe.id = coalesce(p.person_id, t.person_id)
    where app.can_counsel_nutrition()
      and r.organization_id = v_org
      and r.source = 'platform'
      and r.record_kind = 'consent_withdrawn'
      and r.recorded_at > now() - make_interval(days => app.platform_withdrawal_notice_days())
  ) x
  order by x.recorded_at desc, x.id;
end;
$$;

COMMENT ON FUNCTION public.list_platform_consent_withdrawals() IS 'POR-016/017 (ANN-263): Widerrufe ueber die Plattform der letzten 14 Tage fuer Offene Punkte - Behandlung fuer die Rollen der Kartei, Training fuer die Rollen, die das Trainingsverhaeltnis lesen. Ohne Recht keine Zeile.';

CREATE FUNCTION public.list_platform_messages(p_kind text DEFAULT NULL::text, p_relationship_id uuid DEFAULT NULL::uuid, p_with_closed boolean DEFAULT false) RETURNS TABLE(id uuid, relationship_kind text, relationship_id uuid, patient_id uuid, training_relationship_id uuid, given_name text, family_name text, topic text, reference_label text, status text, due_on date, overdue boolean, created_at timestamp with time zone, last_entry_at timestamp with time zone, closed_at timestamp with time zone, closed_by_side text, entry_count integer, asked_by text, representative_name text, can_answer boolean, record_assigned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_heute date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_kind is not null and p_kind not in ('treatment', 'training') then
    raise exception 'unknown relationship kind' using errcode = '22023';
  end if;
  if not app.may_read_platform_messages(coalesce(p_kind, 'any')) then
    perform app.record_denied_read(auth.uid(), 'platform_messages.read',
                                   'not allowed to read platform messages');
    return;
  end if;
  v_org := app.current_organization_id();
  v_heute := app.training_today(v_org);

  return query
  select m.id, m.relationship_kind, m.relationship_id, m.patient_id, m.training_relationship_id,
         pe.given_name, pe.family_name,
         m.topic, m.reference_label, m.status, m.due_on,
         (m.status = 'open' and m.due_on < v_heute),
         m.created_at, m.last_entry_at, m.closed_at, m.closed_by_side,
         (select count(*)::integer from public.platform_message_entries e where e.message_id = m.id),
         (select e.author_kind from public.platform_message_entries e
           where e.message_id = m.id order by e.created_at, e.id limit 1),
         (select e.author_label from public.platform_message_entries e
           where e.message_id = m.id and e.author_kind <> 'self'
           order by e.created_at, e.id limit 1),
         app.can_answer_platform_message(m.relationship_kind, m.topic),
         m.record_assigned_at
  from public.platform_messages m
  left join public.patients pa on pa.id = m.patient_id
  left join public.training_relationships t on t.id = m.training_relationship_id
  left join public.persons pe on pe.id = coalesce(pa.person_id, t.person_id)
  where m.organization_id = v_org
    and (p_kind is null or m.relationship_kind = p_kind)
    and (p_relationship_id is null or m.relationship_id = p_relationship_id)
    and (p_with_closed or m.status <> 'closed')
    and app.can_read_platform_message(m.relationship_kind, m.topic)
  order by (m.status = 'closed'), (m.status <> 'open'), m.due_on nulls last, m.last_entry_at desc,
           m.id;
end;
$$;

COMMENT ON FUNCTION public.list_platform_messages(p_kind text, p_relationship_id uuid, p_with_closed boolean) IS 'KOM-002: Vorgaenge der Plattform fuer die Praxis (DSN-001 Abschnitt 6) - ohne Text, mit Person, Thema, Zustand, Frist und Ueberfaelligkeit (ANN-309). Je Vorgang nur, wer ihn lesen darf (ANN-310, ANN-311). Optional ein Bereich und ein Verhaeltnis.';

CREATE FUNCTION public.list_platform_representations(p_relationship_kind text, p_relationship_id uuid) RETURNS TABLE(id uuid, access_kind text, legal_basis text, representative_name text, status text, created_at timestamp with time zone, activated_at timestamp with time zone, locked_at timestamp with time zone, revoked_at timestamp with time zone, revoked_reason text, proof_documents text[], health_scope boolean, finance_scope boolean, proof_recorded_at timestamp with time zone, proof_recorded_by_name text, consent_recorded_at timestamp with time zone, consent_earlier_messages boolean, invitation_purpose text, invitation_expires_at timestamp with time zone, ended_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_platform_access(p_relationship_kind) then
    perform app.record_denied_read(v_actor, 'platform_accesses.read', 'not allowed to read platform access');
    return;
  end if;
  v_org := app.current_organization_id();

  return query
  select a.id, a.access_kind, a.legal_basis, a.representative_name, a.status,
         a.created_at, a.activated_at, a.locked_at, a.revoked_at, a.revoked_reason,
         a.proof_documents, a.health_scope, a.finance_scope, a.proof_recorded_at,
         up.display_name, a.consent_recorded_at, a.consent_earlier_messages,
         i.purpose, i.expires_at,
         app.platform_access_ended_at(a.id)
  from public.platform_accesses a
  left join public.user_profiles up
    on up.id = a.proof_recorded_by and up.organization_id = v_org
  left join public.platform_access_invitations i
    on i.platform_access_id = a.id and i.status = 'pending' and i.expires_at > now()
  where a.organization_id = v_org
    and a.relationship_kind = p_relationship_kind
    and a.relationship_id = p_relationship_id
    and a.access_kind <> 'self'
    -- Das Verhaeltnis muss leben; der Nachweis eines geloeschten bleibt
    -- unsichtbar (ADR-023 Punkt 5).
    and (a.patient_id is not null or a.training_relationship_id is not null)
  order by (a.status = 'revoked'), a.created_at desc;
end;
$$;

CREATE FUNCTION public.list_platform_training_withdrawals() RETURNS TABLE(contract_id uuid, training_relationship_id uuid, given_name text, family_name text, withdrawn_on date, package_label text, withdrawn_access_kind text, withdrawn_representative_name text, package_open boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null or not app.can_manage_training_packages() then
    return;
  end if;

  return query
  select k.id, k.training_relationship_id, pe.given_name, pe.family_name, k.withdrawn_on,
         k.package_label, k.withdrawn_access_kind, k.withdrawn_representative_name,
         k.training_package_id is not null
  from public.training_contracts k
  join public.training_relationships t on t.id = k.training_relationship_id
  join public.persons pe on pe.id = t.person_id
  where k.organization_id = v_org
    and k.withdrawn_at is not null
    -- ANN-341: bis das Paket entfernt oder das Verhaeltnis beendet ist,
    -- mindestens 14 Tage.
    and ((k.training_package_id is not null
          and (t.contract_ended_on is null
               or t.contract_ended_on >= app.training_today(v_org)))
         or k.withdrawn_at > now() - make_interval(days => app.platform_withdrawal_notice_days()))
  order by k.withdrawn_at desc, k.id;
end;
$$;

COMMENT ON FUNCTION public.list_platform_training_withdrawals() IS 'KND-004, BEF-129 (ANN-341): Widerrufe von Trainingsvertraegen ueber die Plattform fuer Offene Punkte (owner, office) - solange das Paket besteht und das Verhaeltnis nicht beendet ist, mindestens 14 Tage; package_open sagt, ob es noch besteht. Ohne Recht keine Zeile.';

CREATE FUNCTION public.list_practice_foods() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not app.can_counsel_nutrition() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(app.custom_food_json(p) order by p.name_key, p.id)
    from public.custom_foods p
    where p.organization_id = app.current_organization_id()
      and p.owner_kind = 'practice' and p.archived_at is null
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.list_practice_foods() IS 'ERN-005: die Lebensmittel der Praxis (nicht abgelegt) - allein app.can_counsel_nutrition.';

CREATE FUNCTION public.list_practice_revenue_months(p_months integer DEFAULT 12) RETURNS TABLE(month date, revenue_cents bigint, revenue_therapy_cents bigint, revenue_training_cents bigint, payments_cents bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_tz    text;
  v_bis   date;
  v_von   date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_practice_statistics() then
    perform app.record_denied_read(auth.uid(), 'statistics.read', 'not allowed to read practice statistics');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read practice statistics' using errcode = '42501';
  end if;
  if p_months is null or p_months < 1 or p_months > 36 then
    raise exception 'months out of range' using errcode = '22023';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  -- Bis einschliesslich des laufenden Monats in der Zeitzone der Praxis.
  v_bis := (date_trunc('month', (now() at time zone v_tz)::date) + interval '1 month')::date;
  v_von := (v_bis - make_interval(months => p_months))::date;

  return query
  with monate as (
    select g::date as monat
    from generate_series(v_von::timestamp, (v_bis - interval '1 month')::timestamp, interval '1 month') g
  ),
  umsatz as (
    select date_trunc('month', r.tag)::date as monat,
           sum(r.betrag)::bigint as gesamt,
           sum(r.betrag) filter (where r.bereich = 'therapy')::bigint as behandlung,
           sum(r.betrag) filter (where r.bereich = 'training')::bigint as training
    from app.revenue_documents(v_org, v_von, v_bis) r
    group by 1
  ),
  zufluss as (
    select date_trunc('month', z.tag)::date as monat, sum(z.betrag)::bigint as summe
    from app.payment_flows(v_org, v_von, v_bis) z
    group by 1
  )
  select m.monat,
         coalesce(u.gesamt, 0)::bigint,
         coalesce(u.behandlung, 0)::bigint,
         coalesce(u.training, 0)::bigint,
         coalesce(z.summe, 0)::bigint
  from monate m
  left join umsatz u  on u.monat = m.monat
  left join zufluss z on z.monat = m.monat
  order by m.monat;
end;
$$;

COMMENT ON FUNCTION public.list_practice_revenue_months(p_months integer) IS 'STA-004: je Monat (bis einschliesslich des laufenden) Umsatz nach Rechnungsstellung, getrennt je Bereich, und Zahlungseingang - zwei Grundlagen, nie verrechnet. Nur Summen, allein owner; abgewiesen als statistics.read.';

CREATE FUNCTION public.list_record_platform_messages(p_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null or not app.may_read_platform_messages('treatment') then
    raise exception 'not allowed to read platform messages' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if not exists (select 1 from public.patients p
                 where p.id = p_patient_id and p.organization_id = v_org) then
    return '[]'::jsonb;
  end if;
  perform app.log_record_access(v_org, auth.uid(), 'patient_record.viewed', 'patient', p_patient_id);

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', m.id,
      'topic', m.topic,
      'reference_label', m.reference_label,
      'status', m.status,
      'created_at', m.created_at,
      'record_assigned_at', m.record_assigned_at,
      'record_assigned_by_label', m.record_assigned_by_label,
      'entries', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', e.id,
          'side', e.side,
          'body', e.body,
          'author_kind', e.author_kind,
          'author_label', e.author_label,
          'created_at', e.created_at
        ) order by e.created_at, e.id)
        from public.platform_message_entries e where e.message_id = m.id
      ), '[]'::jsonb)
    ) order by m.created_at desc, m.id)
    from public.platform_messages m
    where m.organization_id = v_org
      and m.patient_id = p_patient_id
      and m.record_assigned_at is not null
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.list_record_platform_messages(p_patient_id uuid) IS 'KOM-004: die der Akte zugeordneten Vorgaenge mit allen Eintraegen und ihrer Herkunft (IDEA-KOM-007). Lesen die vier Praxisrollen (E15); protokolliert als "Akte geoeffnet".';

CREATE FUNCTION public.list_reimbursements(p_staff_member_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_eigene uuid;
  v_person uuid;
  v_alle   boolean;
  v_entsch boolean;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to read reimbursements');
  v_eigene := app.own_staff_member(v_org);
  v_alle := app.can_read_all_reimbursements();
  v_entsch := app.can_decide_staff_requests();
  v_person := coalesce(p_staff_member_id, v_eigene);
  -- Eine fremde Person nur für owner und Büro; sonst sieht sie aus wie
  -- eine, die es nicht gibt.
  if p_staff_member_id is not null and p_staff_member_id is distinct from v_eigene
     and (not v_alle or not exists (
       select 1 from public.staff_members s
       where s.id = p_staff_member_id and s.organization_id = v_org
     )) then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'my_staff_member_id', v_eigene,
    'can_decide', v_entsch,
    'can_read_all', v_alle,
    'person', case when v_person is null then null else jsonb_build_object(
      'staff_member_id', v_person,
      'name', app.staff_display_name(v_person),
      'account', app.payout_account_view(v_person),
      'reimbursements', coalesce((
        -- Voll für die eigene Person und für owner; das Büro sieht bei
        -- Anträgen aus Touren keine Kilometer und keinen Betrag (ANN-616).
        select jsonb_agg(app.reimbursement_view(r, v_person = v_eigene or v_entsch)
                         order by r.requested_at desc, r.id)
        from public.staff_reimbursements r
        where r.organization_id = v_org and r.staff_member_id = v_person
      ), '[]'::jsonb)
    ) end,
    -- owner: was zu entscheiden und was auszuzahlen ist, je Antrag mit Namen.
    'to_decide', case when not v_entsch then '[]'::jsonb else coalesce((
      select jsonb_agg(app.reimbursement_view(r, true) order by r.requested_at, r.id)
      from public.staff_reimbursements r
      where r.organization_id = v_org and r.status = 'requested'
        and r.staff_member_id is distinct from v_eigene
    ), '[]'::jsonb) end,
    'to_pay', case when not v_entsch then '[]'::jsonb else coalesce((
      select jsonb_agg(app.reimbursement_view(r, true)
                       || jsonb_build_object('iban_masked',
                            app.mask_iban((select a.iban from public.staff_payout_accounts a
                                            where a.staff_member_id = r.staff_member_id)))
                       order by r.decided_at, r.id)
      from public.staff_reimbursements r
      where r.organization_id = v_org and app.may_pay_reimbursement(v_org, r)
    ), '[]'::jsonb) end,
    -- owner und Büro: die Personen mit Erstattungen, je Person die offenen -
    -- keine Summe über alle (PROJECT_PRINCIPLES.md 20).
    'people', case when not v_alle then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'staff_member_id', x.staff_member_id,
               'name', app.staff_display_name(x.staff_member_id),
               'open', x.offen
             ) order by app.staff_display_name(x.staff_member_id), x.staff_member_id)
      from (
        select r.staff_member_id,
               count(*) filter (where r.status in ('requested', 'approved'))::integer as offen
        from public.staff_reimbursements r
        where r.organization_id = v_org and r.staff_member_id is distinct from v_eigene
        group by r.staff_member_id
      ) x
    ), '[]'::jsonb) end
  );
end;
$$;

COMMENT ON FUNCTION public.list_reimbursements(p_staff_member_id uuid) IS 'ERS-001 (ANN-598, ANN-601): die eigenen Erstattungen mit Belegen und maskierter IBAN; für owner und Büro auf Wunsch die einer anderen Person und die Personen mit Erstattungen (ohne Summe über alle); für owner zu entscheiden und auszuzahlen. Nie die volle IBAN, nie ein Objektschlüssel.';

CREATE FUNCTION public.list_rejected_time_off() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_eigen uuid;
  v_heute date;
begin
  v_org := app.staff_request_org(app.can_keep_time_account(), 'not allowed to keep a time account');
  v_eigen := app.own_staff_member(v_org);
  if v_eigen is null then
    return '[]'::jsonb;
  end if;
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', e.id,
             'on_date', e.on_date,
             'starts_at', to_char(e.starts_at, 'HH24:MI'),
             'ends_at', to_char(e.ends_at, 'HH24:MI')
           ) order by e.on_date, e.starts_at, e.id), '[]'::jsonb)
    from public.staff_time_account_entries e
    where e.organization_id = v_org
      and e.staff_member_id = v_eigen
      and e.kind = 'time_off'
      and e.status = 'rejected'
      and e.on_date >= v_heute
  );
end;
$$;

COMMENT ON FUNCTION public.list_rejected_time_off() IS 'BEF-179 (ANN-675): die eigenen zurückgewiesenen Freizeitausgleiche, deren Tag noch nicht vorbei ist - für „noch offen“ in der Übersicht. Nur Tag, Beginn und Ende, ohne Grund; den liest das Zeitkonto. Keine Benachrichtigung.';

CREATE FUNCTION public.list_removed_patient_course_events(p_patient_id uuid) RETURNS TABLE(id uuid, occurred_on date, kind text, note text, created_at timestamp with time zone, author_name text, removed_at timestamp with time zone, removed_by_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_note() then
    perform app.record_denied_read(v_actor, 'patient_course_event.viewed', 'not allowed to read course events');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read course events' using errcode = '42501';
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.patient_course_events e where e.patient_id = p_patient_id and e.organization_id = v_org and e.removed_at is not null) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
  end if;

  return query
    select e.id, e.occurred_on, e.kind, e.note, e.created_at, up.display_name,
           e.removed_at, rp.display_name
    from public.patient_course_events e
    left join public.user_profiles up on up.id = e.created_by
    left join public.user_profiles rp on rp.id = e.removed_by
    where e.patient_id = p_patient_id and e.organization_id = v_org and e.removed_at is not null
    order by e.removed_at desc;
end;
$$;

COMMENT ON FUNCTION public.list_removed_patient_course_events(p_patient_id uuid) IS 'Entfernte Ereignisse einer Akte mit Inhalt, Urheber und wer wann entfernt hat (ABN-013, BEF-102). Leserecht und Protokoll wie list_patient_course_events.';

CREATE FUNCTION public.list_revenue_by_service_area(p_basis text, p_year integer DEFAULT NULL::integer) RETURNS TABLE(basis text, year integer, service_area text, tax_treatment text, tax_rate_permille smallint, currency text, gross_cents bigint, tax_cents bigint, net_cents bigint, document_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_zeitzone text;
  v_jahr     integer;
  v_von      date;
  v_bis      date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoicing figures');
    return;
  end if;

  -- Festlegung 1: ohne genannte Grundlage keine Zahl.
  if p_basis is null or p_basis not in ('accrual', 'cash') then
    raise exception 'unknown revenue basis' using errcode = '22023';
  end if;

  v_org := app.current_organization_id();

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_jahr := coalesce(p_year, extract(year from (now() at time zone v_zeitzone))::integer);

  if v_jahr < 2020 or v_jahr > 2200 then
    raise exception 'year out of range' using errcode = '22023';
  end if;

  v_von := make_date(v_jahr, 1, 1);
  v_bis := make_date(v_jahr + 1, 1, 1);

  return query
  with dokument as (
    -- Grundlage Rechnungsstellung, Teil 1: die ausgestellte Rechnung mit
    -- ihrem Ausstellungstag. Der Bereich steht seit ABR-010 im Snapshot; die
    -- Spalte bleibt als Rueckfallweg fuer aeltere Snapshots (schema_version 1
    -- und 2), die es ausserhalb von Entwicklungsdatenbanken nicht gibt.
    select i.id                                                      as document_id,
           coalesce(i.snapshot ->> 'service_area', i.service_area)   as service_area,
           i.currency                                                as currency,
           i.snapshot -> 'tax_groups'                                as tax_groups,
           1                                                         as vorzeichen
    from public.invoices i
    where p_basis = 'accrual'
      and i.organization_id = v_org
      and i.status = 'issued'
      and i.issued_on >= v_von and i.issued_on < v_bis
    union all
    -- Teil 2: das Stornodokument mit seinem eigenen Tag und umgekehrtem
    -- Vorzeichen (Festlegung 4). Es traegt keine eigenen Betraege - es nimmt
    -- die seiner Rechnung zurueck, und genau das steht darin.
    select c.id,
           coalesce(i.snapshot ->> 'service_area', i.service_area),
           i.currency,
           i.snapshot -> 'tax_groups',
           -1
    from public.invoice_cancellations c
    join public.invoices i on i.id = c.invoice_id
    where p_basis = 'accrual'
      and c.organization_id = v_org
      and c.cancelled_on >= v_von and c.cancelled_on < v_bis
  ),
  nach_rechnungsstellung as (
    select d.service_area,
           g ->> 'tax_treatment'                            as tax_treatment,
           (g ->> 'tax_rate_permille')::smallint            as tax_rate_permille,
           d.currency,
           d.document_id,
           d.vorzeichen * (g ->> 'gross_cents')::bigint     as brutto,
           d.vorzeichen * (g ->> 'tax_cents')::bigint       as steuer,
           d.vorzeichen * (g ->> 'net_cents')::bigint       as netto
    from dokument d
    cross join lateral jsonb_array_elements(d.tax_groups) as g
  ),
  zahlung as (
    -- Grundlage Zufluss: gebuchte Zahlungen. Eine stornierte Zahlung ist aus
    -- jeder Summe heraus (`voided_at`), eine Rueckzahlung kehrt das Vorzeichen
    -- um. Der Bereich und die Steuergruppen kommen aus der Rechnung, zu der
    -- die Zahlung gehoert - eine Zahlung kennt sie nicht selbst.
    --
    -- ABN-008 (BEF-100, ANN-088 Fassung 2): KUMULATIV. Verteilt wird die
    -- Summe aller Zahlungen der Rechnung bis einschliesslich dieser, davon
    -- abgezogen die Verteilung bis zur vorigen. Mehrere Teilzahlungen ergeben
    -- so bei voller Zahlung genau die Gruppen des Dokuments, und eine
    -- Rueckzahlung nimmt ihre Verteilung centgenau zurueck. Die Reihenfolge
    -- ist fest: Zahlungstag, Erfassung, Kennung. Gezaehlt werden auch
    -- Zahlungen frueherer Jahre - sie bestimmen, wo die Rechnung steht.
    select p.id                                                    as document_id,
           p.paid_on                                               as paid_on,
           i.currency                                              as currency,
           coalesce(i.snapshot ->> 'service_area', i.service_area) as service_area,
           i.snapshot -> 'tax_groups'                              as tax_groups,
           sum(case p.direction when 'incoming' then p.amount_cents else -p.amount_cents end)
             over (partition by p.invoice_id
                   order by p.paid_on, p.created_at, p.id)::bigint as nach,
           sum(case p.direction when 'incoming' then p.amount_cents else -p.amount_cents end)
             over (partition by p.invoice_id
                   order by p.paid_on, p.created_at, p.id)::bigint
             - case p.direction when 'incoming' then p.amount_cents else -p.amount_cents end
                                                                   as vor
    from public.payments p
    join public.invoices i on i.id = p.invoice_id
    where p_basis = 'cash'
      and p.organization_id = v_org
      and p.voided_at is null
      and p.paid_on < v_bis
  ),
  nach_zufluss as (
    select z.service_area,
           n.tax_treatment,
           n.tax_rate_permille,
           z.currency,
           z.document_id,
           n.brutto - v.brutto                            as brutto,
           n.steuer - v.steuer                            as steuer,
           (n.brutto - v.brutto) - (n.steuer - v.steuer)  as netto
    from zahlung z
    cross join lateral app.distribute_to_tax_groups(z.tax_groups, z.nach) n
    join lateral app.distribute_to_tax_groups(z.tax_groups, z.vor) v
      on v.tax_treatment = n.tax_treatment
     and v.tax_rate_permille = n.tax_rate_permille
    where z.paid_on >= v_von
  ),
  alles as (
    select * from nach_rechnungsstellung
    union all
    select * from nach_zufluss
  )
  select p_basis,
         v_jahr,
         a.service_area,
         a.tax_treatment,
         a.tax_rate_permille,
         a.currency,
         sum(a.brutto)::bigint,
         sum(a.steuer)::bigint,
         sum(a.netto)::bigint,
         count(distinct a.document_id)::integer
  from alles a
  group by a.service_area, a.tax_treatment, a.tax_rate_permille, a.currency
  order by a.service_area, a.tax_treatment, a.tax_rate_permille, a.currency;
end;
$$;

COMMENT ON FUNCTION public.list_revenue_by_service_area(p_basis text, p_year integer) IS 'Einnahmen je Leistungsart (ABR-011, ADR-009 Punkt 19): Erloese getrennt je Leistungsbereich, darin je Steuerkennzeichen und Satz. Grundlage ist Pflicht - accrual (Rechnungsstellung) oder cash (Zufluss) -, steht in jeder Zeile und wird nie gemischt. Rechnet ausschliesslich aus Snapshots ausgestellter Rechnungen, Stornodokumenten und gebuchten Zahlungen; deterministisch und ohne KI. Kein steuerlicher Abschluss und kein Personenbezug.';

CREATE FUNCTION public.list_revenue_by_staff(p_months integer DEFAULT 6) RETURNS TABLE(month date, staff_member_id uuid, staff_name text, revenue_cents bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_tz     text;
  v_bis    date;
  v_von    date;
  v_eigene uuid;
  v_alle   boolean;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  v_alle := app.has_any_role('owner');
  if not v_alle and v_org is not null then
    select sm.id into v_eigene
    from public.staff_members sm
    where sm.organization_id = v_org
      and sm.person_id = app.current_person_id();
  end if;

  if not v_alle and (v_eigene is null or not app.has_revenue_share(v_eigene, v_org)) then
    perform app.record_denied_read(v_actor, 'statistics.read', 'not allowed to read revenue by staff');
    return;
  end if;
  if v_org is null then
    raise exception 'not allowed to read revenue by staff' using errcode = '42501';
  end if;
  if p_months is null or p_months < 1 or p_months > 36 then
    raise exception 'months out of range' using errcode = '22023';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_bis := (date_trunc('month', (now() at time zone v_tz)::date) + interval '1 month')::date;
  v_von := (v_bis - make_interval(months => p_months))::date;


  return query
  with zugeordnet as (
    select date_trunc('month', l.tag)::date as monat, l.staff_member_id as person, sum(l.betrag)::bigint as summe
    from app.revenue_staff_lines(v_org, v_von, v_bis) l
    where v_alle or l.staff_member_id = v_eigene
    group by 1, 2
  ),
  praxis as (
    select date_trunc('month', r.tag)::date as monat, sum(r.betrag)::bigint as summe
    from app.revenue_documents(v_org, v_von, v_bis) r
    group by 1
  ),
  rest as (
    -- Nur fuer owner: was keiner Person zugeordnet werden kann.
    select coalesce(p.monat, z.monat) as monat,
           coalesce(p.summe, 0) - coalesce(z.summe, 0) as summe
    from praxis p
    full join (
      select monat, sum(summe)::bigint as summe
      from zugeordnet
      where person is not null
      group by monat
    ) z on z.monat = p.monat
    where v_alle
  ),
  alles as (
    select z.monat, z.person, z.summe from zugeordnet z where z.person is not null
    union all
    select r.monat, null::uuid, r.summe from rest r
  )
  select a.monat,
         a.person,
         case when a.person is null then null
              else nullif(btrim(concat_ws(' ', pe.given_name, pe.family_name)), '') end,
         sum(a.summe)::bigint
  from alles a
  left join public.staff_members sm on sm.id = a.person
  left join public.persons pe       on pe.id = sm.person_id
  group by 1, 2, 3
  having sum(a.summe) <> 0
  order by 1, 3 nulls last, 2;
end;
$$;

COMMENT ON FUNCTION public.list_revenue_by_staff(p_months integer) IS 'STA-006: Umsatz nach Rechnungsstellung je Monat und behandelnder Person (ANN-156). owner alle, eine Person mit Umsatzbeteiligung nur sich selbst, sonst abgewiesen als statistics.read. Jeder Aufruf protokolliert statistics.staff_revenue_viewed ohne Betraege.';

CREATE FUNCTION public.list_revenue_years() RETURNS TABLE(year integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_invoicing() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'invoicing.read', 'not allowed to read invoicing figures');
    return;
  end if;

  v_org := app.current_organization_id();

  return query
  select distinct j.jahr
  from (
    select extract(year from i.issued_on)::integer as jahr
    from public.invoices i
    where i.organization_id = v_org and i.status = 'issued' and i.issued_on is not null
    union all
    select extract(year from c.cancelled_on)::integer
    from public.invoice_cancellations c
    where c.organization_id = v_org
    union all
    select extract(year from p.paid_on)::integer
    from public.payments p
    where p.organization_id = v_org and p.voided_at is null
  ) j
  order by j.jahr desc;
end;
$$;

COMMENT ON FUNCTION public.list_revenue_years() IS 'Kalenderjahre, in denen ein Dokument oder eine Zahlung liegt (ABR-011). Grundlage der Jahreswahl in der Auswertung; kein Personenbezug.';

CREATE FUNCTION public.list_staff_feedback_named() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.staff_request_org(app.can_read_staff_feedback(), 'not allowed to read staff feedback');
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', f.id,
             'kind', f.kind,
             'month', f.month,
             'name', app.staff_display_name(f.staff_member_id),
             'mood', f.mood,
             'tours', f.tours,
             'team', f.team,
             'easier_text', f.easier_text,
             'more_text', f.more_text,
             'message_text', f.message_text
           ) order by f.month desc, f.submitted_at desc, f.id), '[]'::jsonb)
    from public.staff_feedback f
    where f.organization_id = v_org and f.staff_member_id is not null
  );
end;
$$;

COMMENT ON FUNCTION public.list_staff_feedback_named() IS 'ORG-006 (§20.2 Nr. 3): namentliche Rückmeldungen einzeln - Name, Monat, Inhalt, die neueste zuerst; nur owner. Kein Filter je Person, kein Verlauf.';

CREATE FUNCTION public.list_staff_future_appointments(p_staff_member_id uuid) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, kind text, title text, patient_id uuid, patient_given_name text, patient_family_name text, location_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_employment() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to manage staff');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  -- Zielsatz ausschliesslich in der eigenen Organisation suchen; sonst waere
  -- die Funktion ein Orakel fuer fremde Mitarbeiter-IDs.
  if not exists (
    select 1 from public.staff_members sm
    where sm.id = p_staff_member_id
      and sm.organization_id = v_org
  ) then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  return query
    select
      a.id,
      a.starts_at,
      a.ends_at,
      a.appointment_type,
      a.kind,
      a.title,
      a.patient_id,
      pp.given_name,
      pp.family_name,
      l.name
    from public.appointments a
    left join public.patients p  on p.id  = a.patient_id
    left join public.persons pp  on pp.id = p.person_id
    left join public.locations l on l.id = a.location_id
    where a.organization_id = v_org
      and a.staff_member_id = p_staff_member_id
      and a.status = 'confirmed'
      and a.ends_at > now()
    order by a.starts_at, a.id;
end;
$$;

COMMENT ON FUNCTION public.list_staff_future_appointments(p_staff_member_id uuid) IS 'Offene zukuenftige Termine einer Person - Behandlungen und Ereignisse (STAFF-003, CAL-015b). Nur fuer Rollen, die Beschaeftigung verwalten duerfen.';

CREATE FUNCTION public.list_storage_deletion_orders() RETURNS TABLE(id uuid, bucket_id text, ordered_at timestamp with time zone, object_present boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if not app.can_execute_storage_deletion() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'storage_deletion.read', 'not allowed to read deletion orders');
    return;
  end if;

  if v_org is null or not app.can_execute_storage_deletion() then
    raise exception 'not allowed to read deletion orders' using errcode = '42501';
  end if;

  return query
    select o.id,
           o.bucket_id,
           o.ordered_at,
           exists (
             select 1
             from storage.objects s
             where s.bucket_id = o.bucket_id
               and s.name = o.object_key
           )
    from public.storage_deletion_orders o
    where o.organization_id = v_org
      and o.receipted_at is null
    order by o.ordered_at, o.id;
end;
$$;

COMMENT ON FUNCTION public.list_storage_deletion_orders() IS 'Offene Loeschauftraege der eigenen Organisation (ADR-017 Punkt 25). Ohne Objektschluessel: die Oberflaeche braucht ihn nicht, und er gehoert nicht in eine Liste.';

CREATE FUNCTION public.list_tasks(p_status text DEFAULT 'open'::text, p_patient_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, note text, due_on date, status text, patient_id uuid, patient_given_name text, patient_family_name text, assigned_staff_member_id uuid, assigned_name text, created_at timestamp with time zone, created_by_name text, done_at timestamp with time zone, done_by_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_tasks() then
    perform app.record_denied_read(auth.uid(), 'tasks.read', 'not allowed to read tasks');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read tasks' using errcode = '42501';
  end if;
  if p_status is null or p_status not in ('open', 'done') then
    raise exception 'invalid status filter' using errcode = '22023';
  end if;

  return query
  select k.id,
         k.title,
         k.note,
         k.due_on,
         k.status,
         k.patient_id,
         pe.given_name,
         pe.family_name,
         k.assigned_staff_member_id,
         nullif(btrim(concat_ws(' ', ape.given_name, ape.family_name)), ''),
         k.created_at,
         nullif(btrim(concat_ws(' ', cpe.given_name, cpe.family_name)), ''),
         k.done_at,
         nullif(btrim(concat_ws(' ', dpe.given_name, dpe.family_name)), '')
  from public.tasks k
  left join public.patients pa on pa.id = k.patient_id
  left join public.persons pe on pe.id = pa.person_id
  left join public.staff_members asm on asm.id = k.assigned_staff_member_id
  left join public.persons ape on ape.id = asm.person_id
  left join public.user_profiles cup on cup.id = k.created_by
  left join public.persons cpe on cpe.id = cup.person_id
  left join public.user_profiles dup on dup.id = k.done_by
  left join public.persons dpe on dpe.id = dup.person_id
  where k.organization_id = v_org
    and k.status = p_status
    and (p_patient_id is null or k.patient_id = p_patient_id)
  order by
    case when p_status = 'open' then k.due_on end asc nulls last,
    case when p_status = 'open' then k.created_at end asc,
    case when p_status = 'done' then k.done_at end desc
  limit case when p_status = 'done' then 100 end;
end;
$$;

COMMENT ON FUNCTION public.list_tasks(p_status text, p_patient_id uuid) IS 'Aufgaben der eigenen Praxis (PRX-012): offen nach Faelligkeit oder die letzten 100 erledigten; optional je Person. Alle vier Praxisrollen; ein abgewiesener Versuch wird als tasks.read protokolliert. Das Lesen selbst ist wie die Warteliste nicht auditiert (ANN-134).';

CREATE FUNCTION public.list_team_activity() RETURNS TABLE(id uuid, channel_id uuid, channel_kind text, parent_id uuid, author_staff_member_id uuid, author_name text, body text, created_at timestamp with time zone, reason text, unread boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select m.id, m.channel_id, c.kind, m.parent_id,
         m.author_staff_member_id, app.team_staff_name(m.author_staff_member_id), m.body,
         m.created_at,
         case when exists (select 1 from public.team_message_mentions mm
                           where mm.message_id = m.id and mm.staff_member_id = v_staff)
              then 'mention' else 'reply' end,
         app.team_unread(m.channel_id, m.parent_id, m.also_in_channel, m.created_at,
                         m.author_staff_member_id, m.removed_at, v_staff)
  from public.team_messages m
  join public.team_channels c on c.id = m.channel_id
  where m.organization_id = v_org and m.removed_at is null and m.created_at <= now()
    and m.author_staff_member_id is distinct from v_staff
    and app.team_channel_readable(m.channel_id, v_org, v_staff)
    and (exists (select 1 from public.team_message_mentions mm
                 where mm.message_id = m.id and mm.staff_member_id = v_staff)
         or (m.parent_id is not null and app.team_follows(m.parent_id, v_staff)))
  order by m.created_at desc, m.id desc
  limit 50;
end;
$$;

CREATE FUNCTION public.list_team_avatars() RETURNS TABLE(staff_member_id uuid, color text, picture_id uuid, own boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select sm.id, coalesce(c.color, 'schiefer'),
         case when sm.employment_status = 'active' then p.id end,
         sm.id = v_staff
  from public.staff_members sm
  left join public.staff_colors c on c.staff_member_id = sm.id
  left join public.staff_profile_pictures p on p.staff_member_id = sm.id
  where sm.organization_id = v_org
  order by sm.id;
end;
$$;

COMMENT ON FUNCTION public.list_team_avatars() IS 'TEAM-006, TEAM-007: Farbe und Kennung des Profilbilds je Mitarbeiterdatensatz der eigenen Praxis, für alle, die am Teamchat teilnehmen; own markiert die eigene Zeile. Ausgeschiedene ohne Bild.';

CREATE FUNCTION public.list_team_channel_attachments(p_channel uuid, p_limit integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, message_id uuid, parent_id uuid, display_name text, mime_type text, byte_size bigint, created_at timestamp with time zone, author_name text, verified boolean, duration_seconds smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  return query
  select a.id, m.id, m.parent_id, a.display_name, a.mime_type, a.byte_size, m.created_at,
         app.team_staff_name(m.author_staff_member_id), a.verified_at is not null,
         a.duration_seconds
  from public.team_message_attachments a
  join public.team_messages m on m.id = a.message_id
  where a.channel_id = p_channel and a.organization_id = v_org and a.status = 'ready'
    and m.channel_id = p_channel and m.removed_at is null and m.created_at <= now()
  order by m.created_at desc, m.id desc, a.position
  limit least(greatest(coalesce(p_limit, 100), 1), 200);
end;
$$;

COMMENT ON FUNCTION public.list_team_channel_attachments(p_channel uuid, p_limit integer) IS 'TEAM-003 und TEAM-004 (ADR-017 Punkte 51, 80 und 86): Dateien eines lesbaren Gesprächs - Name, Art, Größe, Dauer einer Sprachnachricht, von wem, wann, ob am Server geprüft; ohne Vorschaubild und ohne Objektschlüssel.';

CREATE FUNCTION public.list_team_channel_members(p_channel uuid) RETURNS TABLE(staff_member_id uuid, name text, active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_kind  text;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  select c.kind into v_kind from public.team_channels c where c.id = p_channel;

  return query
  select sm.id, p.given_name || ' ' || p.family_name, app.teamchat_participant(v_org, sm.id)
  from public.staff_members sm
  join public.persons p on p.id = sm.person_id
  where sm.organization_id = v_org
    and case v_kind
          when 'channel' then app.teamchat_participant(v_org, sm.id)
          when 'fleet' then app.team_staff_reads_fleet(v_org, sm.id)
          else exists (select 1 from public.team_channel_members m
                       where m.channel_id = p_channel and m.staff_member_id = sm.id)
        end
  order by p.given_name, p.family_name;
end;
$$;

CREATE FUNCTION public.list_team_channels() RETURNS TABLE(id uuid, kind text, name text, description text, archived boolean, partner_staff_member_id uuid, partner_name text, partner_active boolean, member_names text[], member_count integer, unread integer, mentions integer, last_message_at timestamp with time zone, notify text, starred boolean, manageable boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select c.id, c.kind, c.name, c.description, c.archived_at is not null,
         pm.staff_member_id,
         app.team_staff_name(pm.staff_member_id),
         case when pm.staff_member_id is null then null
              else app.teamchat_participant(v_org, pm.staff_member_id) end,
         case when c.kind = 'group' then
           array(select app.team_staff_name(m.staff_member_id)
                 from public.team_channel_members m
                 where m.channel_id = c.id and m.staff_member_id <> v_staff
                 order by 1)
         end,
         case when c.kind in ('group', 'private') then
           (select count(*)::integer from public.team_channel_members m where m.channel_id = c.id)
         end,
         (select count(*)::integer from public.team_messages m
          where m.channel_id = c.id and (m.parent_id is null or m.also_in_channel)
            and app.team_unread(m.channel_id, m.parent_id, m.also_in_channel, m.created_at,
                                m.author_staff_member_id, m.removed_at, v_staff)),
         (select count(*)::integer from public.team_messages m
          join public.team_message_mentions mm on mm.message_id = m.id and mm.staff_member_id = v_staff
          where m.channel_id = c.id
            and app.team_unread(m.channel_id, m.parent_id, m.also_in_channel, m.created_at,
                                m.author_staff_member_id, m.removed_at, v_staff)),
         (select max(m.created_at) from public.team_messages m
          where m.channel_id = c.id and m.created_at <= now()),
         coalesce(cs.notify, 'all'),
         coalesce(cs.starred, false),
         app.team_channel_manageable(c.id, v_org, v_staff)
  from public.team_channels c
  left join public.team_channel_settings cs on cs.channel_id = c.id and cs.staff_member_id = v_staff
  left join lateral (
    select m.staff_member_id from public.team_channel_members m
    where m.channel_id = c.id and m.staff_member_id <> v_staff
    limit 1
  ) pm on c.kind = 'direct'
  where c.organization_id = v_org
    and app.team_channel_readable(c.id, v_org, v_staff);
end;
$$;

CREATE FUNCTION public.list_team_messages(p_channel uuid, p_parent uuid DEFAULT NULL::uuid, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_around uuid DEFAULT NULL::uuid, p_limit integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, parent_id uuid, author_staff_member_id uuid, author_name text, body text, created_at timestamp with time zone, edited boolean, removed_kind text, also_in_channel boolean, reply_count integer, last_reply_at timestamp with time zone, mentions uuid[], own boolean, new_replies integer, mentioned_in_new_replies boolean, unread boolean, following boolean, reactions jsonb, pinned boolean, saved boolean, root_author_name text, root_body text, attachments jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_staff  uuid;
  v_grenze integer;
  v_ids    uuid[];
  v_mitte  public.team_messages%rowtype;
  c_min    constant uuid := '00000000-0000-0000-0000-000000000000';
  c_max    constant uuid := 'ffffffff-ffff-ffff-ffff-ffffffffffff';
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  if p_parent is not null and not exists (
    select 1 from public.team_messages m
    where m.id = p_parent and m.channel_id = p_channel and m.parent_id is null
      and m.created_at <= now()
  ) then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  -- Im Gespräch höchstens 100 je Seite, im Thread 200.
  v_grenze := case when p_parent is null then least(greatest(coalesce(p_limit, 50), 1), 100)
                   else least(greatest(coalesce(p_limit, 100), 1), 200) end;

  if p_around is not null then
    select x.* into v_mitte from app.team_view(p_channel, p_parent) x where x.id = p_around;
    if v_mitte.id is null then
      raise exception 'team message not found' using errcode = 'P0002';
    end if;
    select array_agg(w.id) into v_ids from (
      (select x.id from app.team_view(p_channel, p_parent) x
        where (x.created_at, x.id) <= (v_mitte.created_at, v_mitte.id)
        order by x.created_at desc, x.id desc
        limit v_grenze / 2 + 1)
      union all
      (select x.id from app.team_view(p_channel, p_parent) x
        where (x.created_at, x.id) > (v_mitte.created_at, v_mitte.id)
        order by x.created_at, x.id
        limit v_grenze / 2)
    ) w;
  elsif p_after_at is not null then
    select array_agg(w.id) into v_ids from (
      select x.id from app.team_view(p_channel, p_parent) x
      where (x.created_at, x.id) > (p_after_at, coalesce(p_after_id, c_min))
      order by x.created_at, x.id
      limit v_grenze
    ) w;
  else
    select array_agg(w.id) into v_ids from (
      select x.id from app.team_view(p_channel, p_parent) x
      where p_before_at is null
         or (x.created_at, x.id) < (p_before_at, coalesce(p_before_id, c_max))
      order by x.created_at desc, x.id desc
      limit v_grenze
    ) w;
  end if;
  -- Im Thread steht die Ausgangsnachricht auf jeder Seite oben.
  if p_parent is not null then
    v_ids := array_append(coalesce(v_ids, '{}'::uuid[]), p_parent);
  end if;

  return query
  select m.id, m.parent_id, m.author_staff_member_id,
         app.team_staff_name(m.author_staff_member_id),
         m.body, m.created_at, m.edited_at is not null, m.removed_kind, m.also_in_channel,
         (select count(*)::integer from public.team_messages r
          where r.parent_id = m.id and r.created_at <= now()),
         (select max(r.created_at) from public.team_messages r
          where r.parent_id = m.id and r.created_at <= now()),
         coalesce((select array_agg(mm.staff_member_id order by mm.staff_member_id)
                   from public.team_message_mentions mm where mm.message_id = m.id), '{}'::uuid[]),
         -- Am Anker fehlt die Verfasser:in: dann nicht eigen (bis TEAM-001 leer).
         coalesce(m.author_staff_member_id = v_staff, false),
         case when m.parent_id is null and coalesce(ts.following, false) then
           (select count(*)::integer from public.team_messages r
            where r.parent_id = m.id and r.removed_at is null and r.created_at <= now()
              and r.created_at > ts.read_up_to
              and r.author_staff_member_id is distinct from v_staff)
         else 0 end,
         m.parent_id is null and coalesce(ts.following, false) and exists (
           select 1 from public.team_messages r
           join public.team_message_mentions mm
             on mm.message_id = r.id and mm.staff_member_id = v_staff
           where r.parent_id = m.id and r.removed_at is null and r.created_at <= now()
             and r.created_at > ts.read_up_to),
         app.team_unread(m.channel_id, m.parent_id, m.also_in_channel, m.created_at,
                         m.author_staff_member_id, m.removed_at, v_staff),
         coalesce(ts.following, false),
         coalesce((
           select jsonb_agg(jsonb_build_object(
                    'reaction', x.reaction, 'count', x.anzahl, 'own', x.eigen, 'names', x.namen)
                  order by x.rang)
           from (
             select r.reaction,
                    array_position(array['daumen', 'erledigt', 'augen', 'danke', 'herz',
                                         'lachen', 'feier', 'frage'], r.reaction) as rang,
                    count(*)::integer as anzahl,
                    bool_or(r.staff_member_id = v_staff) as eigen,
                    array_agg(app.team_staff_name(r.staff_member_id)
                              order by app.team_staff_name(r.staff_member_id)) as namen
             from public.team_message_reactions r
             -- Am leeren Anker nichts, auch nach einem Rennen mit dem Entfernen.
             where r.message_id = m.id and m.removed_at is null
             group by r.reaction
           ) x), '[]'::jsonb),
         m.removed_at is null
           and exists (select 1 from public.team_message_pins p where p.message_id = m.id),
         exists (select 1 from public.team_saved_messages s
                 where s.message_id = m.id and s.staff_member_id = v_staff),
         case when m.also_in_channel then app.team_staff_name(w.author_staff_member_id) end,
         case when m.also_in_channel then left(w.body, 200) end,
         coalesce((
           select jsonb_agg(jsonb_build_object(
                    'id', a.id, 'name', a.display_name, 'mime_type', a.mime_type,
                    'byte_size', a.byte_size, 'verified', a.verified_at is not null,
                    'duration_seconds', a.duration_seconds)
                  order by a.position)
           from public.team_message_attachments a
           where a.message_id = m.id and a.status = 'ready' and m.removed_at is null
         ), '[]'::jsonb)
  from public.team_messages m
  left join public.team_thread_states ts
    on ts.root_message_id = m.id and ts.staff_member_id = v_staff
  left join public.team_messages w on w.id = m.parent_id
  where m.id = any (coalesce(v_ids, '{}'::uuid[]))
  order by m.created_at, m.id;
end;
$$;

CREATE FUNCTION public.list_team_people() RETURNS TABLE(staff_member_id uuid, name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select sm.id, p.given_name || ' ' || p.family_name
  from public.staff_members sm
  join public.persons p on p.id = sm.person_id
  where sm.organization_id = v_org and sm.id <> v_staff
    and app.teamchat_participant(v_org, sm.id)
  order by p.given_name, p.family_name;
end;
$$;

CREATE FUNCTION public.list_team_pins(p_channel uuid) RETURNS TABLE(id uuid, parent_id uuid, author_staff_member_id uuid, author_name text, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;

  return query
  select m.id, m.parent_id, m.author_staff_member_id,
         app.team_staff_name(m.author_staff_member_id), m.body, m.created_at
  from public.team_message_pins p
  join public.team_messages m on m.id = p.message_id
  where p.channel_id = p_channel and m.removed_at is null and m.created_at <= now()
  order by m.created_at desc, m.id desc;
end;
$$;

CREATE FUNCTION public.list_team_saved(p_done boolean DEFAULT false) RETURNS TABLE(id uuid, channel_id uuid, channel_kind text, parent_id uuid, author_staff_member_id uuid, author_name text, body text, created_at timestamp with time zone, remind_at timestamp with time zone, done boolean, due boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select m.id, m.channel_id, c.kind, m.parent_id, m.author_staff_member_id,
         app.team_staff_name(m.author_staff_member_id), m.body, m.created_at, s.remind_at, s.done,
         not s.done and s.remind_at is not null and s.remind_at <= now()
  from public.team_saved_messages s
  join public.team_messages m on m.id = s.message_id
  join public.team_channels c on c.id = m.channel_id
  where s.staff_member_id = v_staff and s.organization_id = v_org
    and s.done = coalesce(p_done, false)
    and m.removed_at is null and m.created_at <= now()
    and app.team_channel_readable(m.channel_id, v_org, v_staff)
  order by (not s.done and s.remind_at is not null and s.remind_at <= now()) desc,
           s.remind_at nulls last, m.created_at desc, m.id
  limit 200;
end;
$$;

CREATE FUNCTION public.list_team_scheduled() RETURNS TABLE(id uuid, channel_id uuid, channel_kind text, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select m.id, m.channel_id, c.kind, m.body, m.created_at
  from public.team_messages m
  join public.team_channels c on c.id = m.channel_id
  where m.organization_id = v_org and m.author_staff_member_id = v_staff
    and m.created_at > now() and m.removed_at is null
    and app.team_channel_readable(m.channel_id, v_org, v_staff)
  order by m.created_at, m.id;
end;
$$;

CREATE FUNCTION public.list_team_threads() RETURNS TABLE(id uuid, channel_id uuid, channel_kind text, author_staff_member_id uuid, author_name text, body text, removed_kind text, reply_count integer, last_reply_at timestamp with time zone, new_replies integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  return query
  select x.id, x.channel_id, x.kind, x.author_staff_member_id, x.author_name, x.body,
         x.removed_kind, x.reply_count, x.last_reply_at, x.new_replies
  from (
    select m.id, m.channel_id, c.kind,
           m.author_staff_member_id,
           app.team_staff_name(m.author_staff_member_id) as author_name, m.body, m.removed_kind,
           (select count(*)::integer from public.team_messages r
            where r.parent_id = m.id and r.created_at <= now()) as reply_count,
           (select max(r.created_at) from public.team_messages r
            where r.parent_id = m.id and r.created_at <= now()) as last_reply_at,
           (select count(*)::integer from public.team_messages r
            where r.parent_id = m.id and r.removed_at is null and r.created_at <= now()
              and r.author_staff_member_id is distinct from v_staff
              and r.created_at > ts.read_up_to) as new_replies
    from public.team_thread_states ts
    join public.team_messages m on m.id = ts.root_message_id
    join public.team_channels c on c.id = m.channel_id
    where ts.staff_member_id = v_staff and ts.following and ts.organization_id = v_org
      and m.created_at <= now()
      and exists (select 1 from public.team_messages r
                  where r.parent_id = m.id and r.created_at <= now())
      and app.team_channel_readable(m.channel_id, v_org, v_staff)
  ) x
  order by (x.new_replies > 0) desc, x.last_reply_at desc, x.id
  limit 50;
end;
$$;

CREATE FUNCTION public.list_territories() RETURNS TABLE(id uuid, name text, day_parts jsonb, postal_codes text[], updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to read territories' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read territories' using errcode = '42501';
  end if;

  return query
  select t.id,
         t.name,
         t.day_parts,
         coalesce(
           (select array_agg(pc.postal_code order by pc.postal_code)
              from public.territory_postal_codes pc
             where pc.territory_id = t.id),
           array[]::text[]
         ),
         t.updated_at
  from public.territories t
  where t.organization_id = v_org
  order by lower(t.name);
end;
$$;

COMMENT ON FUNCTION public.list_territories() IS 'Gebiete der eigenen Praxis mit Postleitzahlen und Gebietstagen (PRX-002). Rollen der Terminverwaltung. Kein Personenbezug, deshalb ohne Leseprotokoll.';

CREATE FUNCTION public.list_text_snippets() RETURNS TABLE(id uuid, title text, body text, shared boolean, editable boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_person uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_use_text_snippets() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'text_snippets.read', 'not allowed to use text snippets');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  v_person := app.current_person_id();

  return query
    select
      s.id,
      s.title,
      s.body,
      s.staff_member_id is null,
      case
        when s.staff_member_id is null then app.can_manage_shared_text_snippets()
        else true
      end
    from public.treatment_text_snippets s
    where s.organization_id = v_org
      and (
        s.staff_member_id is null
        or s.staff_member_id in (
          select sm.id from public.staff_members sm where sm.person_id = v_person
        )
      )
    order by (s.staff_member_id is null) desc, lower(s.title), s.id;
end;
$$;

COMMENT ON FUNCTION public.list_text_snippets() IS 'Textbausteine der anfragenden Person: praxisweite zuerst, dann die eigenen (UX-008). Fremde persoenliche Bausteine sind nicht enthalten.';

CREATE FUNCTION public.list_therapy_report_sources(p_report_id uuid) RETURNS TABLE(kind text, id uuid, occurred_on date, author_name text, content text, in_treatment_basis boolean, is_addendum boolean, body_chart jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_tz    text;
  b       public.therapy_reports%rowtype;
  v_notizen uuid[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    perform app.record_denied_read(v_actor, 'treatment_note.viewed', 'not allowed to write therapy reports');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;

  select * into b from public.therapy_reports r
  where r.id = p_report_id and r.organization_id = v_org;
  if not found then
    raise exception 'therapy report not found' using errcode = 'P0002';
  end if;
  select o.time_zone into v_tz from public.organizations o where o.id = v_org;

  select coalesce(array_agg(n.id), '{}') into v_notizen
  from (
    select d.id
    from public.treatment_notes d
    join public.appointments t on t.id = d.appointment_id
    where t.patient_id = b.patient_id and t.organization_id = v_org and d.status = 'final'
    order by t.starts_at desc, d.created_at desc
    limit 200
  ) n;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if coalesce(cardinality(v_notizen), 0) > 0 then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', b.patient_id);
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.patient_questionnaire_responses qr where qr.patient_id = b.patient_id and qr.organization_id = v_org and qr.status = 'abgeschlossen' and not exists (select 1 from public.patient_questionnaire_responses neu where neu.supersedes_response_id = qr.id and neu.status = 'abgeschlossen') and exists (select 1 from jsonb_each(qr.answers) as a(kennung, antwort) where jsonb_typeof(a.antwort) = 'object' and a.antwort ? 'markierungen')) then
    perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', b.patient_id);
  end if;

  return query
    select 'eintrag'::text, d.id, (t.starts_at at time zone v_tz)::date,
           (select up.display_name from public.user_profiles up where up.id = d.created_by),
           d.content,
           t.treatment_basis_id is not distinct from b.treatment_basis_id,
           d.addendum_to_note_id is not null,
           null::jsonb
    from public.treatment_notes d
    join public.appointments t on t.id = d.appointment_id
    where d.id = any (v_notizen)
    union all
    select 'koerperschema'::text, qr.id, qr.recorded_on,
           (select up.display_name from public.user_profiles up where up.id = qr.created_by),
           null::text, null::boolean, false,
           (select coalesce(jsonb_agg(m.markierung), '[]'::jsonb)
            from jsonb_each(qr.answers) as a(kennung, antwort),
                 jsonb_array_elements(
                   case when jsonb_typeof(a.antwort -> 'markierungen') = 'array'
                        then a.antwort -> 'markierungen' else '[]'::jsonb end
                 ) as m(markierung))
    from public.patient_questionnaire_responses qr
    where qr.patient_id = b.patient_id and qr.organization_id = v_org
      and qr.status = 'abgeschlossen'
      and not exists (select 1 from public.patient_questionnaire_responses neu
                      where neu.supersedes_response_id = qr.id and neu.status = 'abgeschlossen')
      and exists (select 1 from jsonb_each(qr.answers) as a(kennung, antwort)
                  where jsonb_typeof(a.antwort) = 'object' and a.antwort ? 'markierungen')
    order by 1, 3, 2;
end;
$$;

COMMENT ON FUNCTION public.list_therapy_report_sources(p_report_id uuid) IS 'Was sich in einen Therapiebericht uebernehmen laesst: finalisierte Eintraege der Akte (hoechstens 200) und abgeschlossene Erhebungen mit Koerperschema (DOK-005a, ANN-122). therapist, team_lead; je Eintrag und Erhebung protokolliert.';

CREATE FUNCTION public.list_time_account(p_staff_member_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_eigen  uuid;
  v_andere boolean;
  v_owner  boolean;
  v_ziel   uuid;
  v_zone   text;
begin
  v_org := app.staff_request_org(app.can_keep_time_account(), 'not allowed to keep a time account');
  v_eigen := app.own_staff_member(v_org);
  v_andere := app.can_book_time_accounts();
  v_owner := app.can_decide_staff_requests();
  v_ziel := case when p_staff_member_id is null then v_eigen
                 else app.time_account_target(v_org, p_staff_member_id) end;
  select o.time_zone into v_zone
  from public.organizations o where o.id = v_org;

  return jsonb_build_object(
    'my_staff_member_id', v_eigen,
    'can_book_others', v_andere,
    'can_reject', v_owner,
    'account', case when v_ziel is null then null else jsonb_build_object(
      'staff_member_id', v_ziel,
      'name', app.staff_display_name(v_ziel),
      'balance_minutes', app.time_account_balance(v_org, v_ziel),
      'entries', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'id', e.id,
                 'kind', e.kind,
                 'on_date', e.on_date,
                 'starts_at', to_char(e.starts_at, 'HH24:MI'),
                 'ends_at', to_char(e.ends_at, 'HH24:MI'),
                 'minutes', e.minutes,
                 'note', e.note,
                 'status', e.status,
                 'entered_at', e.entered_at,
                 'entered_by_name', case when e.entered_for_other then app.account_display_name(e.entered_by) end,
                 'rejected_at', e.rejected_at,
                 'rejected_by_name', app.account_display_name(e.rejected_by),
                 'rejection_note', e.rejection_note,
                 'withdrawn_at', e.withdrawn_at,
                 -- Ein Übertrag hat niemanden, der ihn eingetragen hat.
                 'can_withdraw', coalesce(e.status = 'valid' and e.entered_by = auth.uid()
                                 and (e.kind <> 'time_off'
                                      or not app.time_off_started(e.on_date, e.starts_at, v_zone, now()))
                                 and (not (e.entered_for_other or e.kind = 'correction') or v_andere),
                                 false),
                 'can_reject', v_owner and e.status = 'valid' and e.kind <> 'carryover'
                               and e.staff_member_id is distinct from v_eigen
               ) order by e.on_date desc, e.starts_at desc nulls last, e.entered_at desc), '[]'::jsonb)
        from public.staff_time_account_entries e
        where e.organization_id = v_org and e.staff_member_id = v_ziel
      )
    ) end,
    'accounts', case when not v_andere then '[]'::jsonb else (
      select coalesce(jsonb_agg(jsonb_build_object(
               'staff_member_id', k.id,
               'name', k.name,
               'balance_minutes', app.time_account_balance(v_org, k.id)
             ) order by k.name, k.id), '[]'::jsonb)
      from (
        select sm.id, app.staff_display_name(sm.id) as name
        from public.staff_members sm
        where sm.organization_id = v_org
          and (sm.employment_status = 'active' or exists (
            select 1 from public.staff_time_account_entries e
            where e.staff_member_id = sm.id and e.status = 'valid'))
      ) k
    ) end
  );
end;
$$;

COMMENT ON FUNCTION public.list_time_account(p_staff_member_id uuid) IS 'ZK-001 (ANN-596, BEF-066 Option 2 mit Büro): das Zeitkonto in einem Aufruf - das eigene mit allen Einträgen; owner und Büro auch das einer anderen Person und die Salden aller je Person, ohne Summe über alle (PROJECT_PRINCIPLES.md 20).';

CREATE FUNCTION public.list_top_services(p_month date DEFAULT NULL::date, p_limit integer DEFAULT 10) RETURNS TABLE(code text, label text, revenue_cents bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_tz    text;
  v_monat date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_practice_statistics() then
    perform app.record_denied_read(auth.uid(), 'statistics.read', 'not allowed to read practice statistics');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read practice statistics' using errcode = '42501';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 50 then
    raise exception 'limit out of range' using errcode = '22023';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_monat := date_trunc('month', coalesce(p_month, (now() at time zone v_tz)::date))::date;
  if v_monat < date '2020-01-01' or v_monat > date '2200-01-01' then
    raise exception 'month out of range' using errcode = '22023';
  end if;

  return query
  select l.code, l.label, sum(l.betrag)::bigint
  from app.revenue_snapshot_items(v_org, v_monat, (v_monat + interval '1 month')::date) l
  -- Kuerzel und Bezeichnung zusammen: dasselbe Kuerzel in zwei Katalogen
  -- bleibt zwei Zeilen.
  group by l.code, l.label
  -- Eine Leistung, die im Monat nur storniert wurde, bleibt als negative Zeile
  -- sichtbar - verschweigen waere eine Bewertung (wie ABR-011).
  having sum(l.betrag) <> 0
  order by sum(l.betrag) desc, l.code, l.label
  limit p_limit;
end;
$$;

COMMENT ON FUNCTION public.list_top_services(p_month date, p_limit integer) IS 'STA-004: Umsatz eines Monats je Leistung (Kuerzel, Bezeichnung) nach Rechnungsstellung, absteigend. Nur Summen, keine Person; allein owner, abgewiesen als statistics.read.';

CREATE FUNCTION public.list_training_bases(p_relationship_id uuid) RETURNS TABLE(id uuid, status text, started_on date, agreed_quantity integer, appointment_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_training_relationships() then
    perform app.record_denied_read(auth.uid(), 'training_relationships.read', 'not allowed to read training clients');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training clients' using errcode = '42501';
  end if;

  return query
    select b.id, b.status, b.started_on, b.agreed_quantity,
           (select count(*)::integer
              from public.appointments a
             where a.training_basis_id = b.id
               and a.status <> 'cancelled')
    from public.training_bases b
    where b.training_relationship_id = p_relationship_id
      and b.organization_id = v_org
    order by (b.status = 'active') desc, b.started_on desc, b.created_at desc;
end;
$$;

COMMENT ON FUNCTION public.list_training_bases(p_relationship_id uuid) IS 'TRN-005: Vereinbarungen einer Trainingskund:in mit Terminzahl (ohne Abgesagte). owner, trainer, office; abgewiesen mit denied unter training_relationships.read.';

CREATE FUNCTION public.list_training_client_appointments(p_relationship_id uuid, p_from date DEFAULT NULL::date) RETURNS TABLE(id uuid, training_basis_id uuid, staff_member_id uuid, staff_given_name text, staff_family_name text, appointment_type text, status text, starts_at timestamp with time zone, ends_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_tz   text;
  v_from date;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_training_relationships() then
    perform app.record_denied_read(auth.uid(), 'training_relationships.read', 'not allowed to read training clients');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training clients' using errcode = '42501';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_from := coalesce(p_from, app.training_today(v_org) - 30);

  return query
    select a.id, a.training_basis_id, a.staff_member_id, sp.given_name, sp.family_name,
           a.appointment_type, a.status, a.starts_at, a.ends_at
    from public.appointments a
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    where a.organization_id = v_org
      and a.kind = 'training'
      and a.training_relationship_id = p_relationship_id
      and a.starts_at >= (v_from::timestamp at time zone v_tz)
    order by a.starts_at, a.id
    limit 100;
end;
$$;

COMMENT ON FUNCTION public.list_training_client_appointments(p_relationship_id uuid, p_from date) IS 'TRN-006: Trainingstermine einer Trainingskund:in ab einem Tag (Standard: 30 Tage zurueck), hoechstens 100. owner, trainer, office; Teil der protokollierten Detailansicht (ANN-175), abgewiesen mit denied unter training_relationships.read.';

CREATE FUNCTION public.list_training_clients() RETURNS TABLE(id uuid, person_id uuid, given_name text, family_name text, status text, contract_started_on date, contract_ended_on date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_training_relationships() then
    perform app.record_denied_read(auth.uid(), 'training_relationships.read', 'not allowed to read training clients');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training clients' using errcode = '42501';
  end if;

  return query
    select t.id, t.person_id, pe.given_name, pe.family_name, t.status,
           t.contract_started_on, t.contract_ended_on
    from public.training_relationships t
    join public.persons pe on pe.id = t.person_id
    where t.organization_id = v_org
    order by (t.status = 'active') desc, pe.family_name, pe.given_name, t.id;
end;
$$;

COMMENT ON FUNCTION public.list_training_clients() IS 'TRN-001: Trefferliste der Trainingskund:innen (Name, Status, Vertragsdaten). owner, trainer, office; nicht protokolliert (ADR-010), abgewiesen als training_relationships.read.';

CREATE FUNCTION public.list_training_offer_packages(p_on date) RETURNS TABLE(catalog_item_id uuid, label text, package_months smallint, unit_price_cents integer, currency text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null or not app.can_update_patient() then
    return;
  end if;

  return query
  select c.id, c.label, c.package_months, c.unit_price_cents, c.currency
  from public.service_catalog_items c
  where c.catalog_version_id = app.active_service_catalog_version(v_org, p_on)
    and c.item_kind = 'training_package'
  order by c.sort_order;
end;
$$;

COMMENT ON FUNCTION public.list_training_offer_packages(p_on date) IS 'KND-002: die Trainingspakete der am Tag geltenden Preisliste fuer das Angebot aus der Akte (owner, therapist, team_lead, office). Andere: keine Zeile.';

CREATE FUNCTION public.list_training_package_items(p_on date) RETURNS TABLE(catalog_item_id uuid, code text, label text, package_months smallint, unit_price_cents integer, currency text, tax_rate_permille smallint)
    LANGUAGE plpgsql SECURITY DEFINER
