COMMENT ON FUNCTION public.list_training_package_items(p_on date) IS 'ANG-006: die Trainingspakete der Preisliste, die am Tag gilt, mit Laufzeit und Preis (owner, office).';

CREATE FUNCTION public.list_training_protocols(p_relationship_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, appointment_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, staff_given_name text, staff_family_name text, status text, content text, finalized_at timestamp with time zone, author_name text, organization_time_zone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_ids   uuid[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- ABN-022 (BEF-113): Lesen ist getrennt vom Schreiben; das Buero liest.
  if not app.can_read_training_protocols() then
    perform app.record_denied_read(v_actor, 'training_protocol.viewed', 'not allowed to read training protocols');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read training protocols' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.training_relationships t
    where t.id = p_relationship_id and t.organization_id = v_org
  ) then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;

  select array_agg(s.id)
    into v_ids
  from (
    select p.id
    from public.training_protocols p
    join public.appointments a on a.id = p.appointment_id
    where p.training_relationship_id = p_relationship_id
      and p.organization_id = v_org
    order by a.starts_at desc, p.id desc
    limit least(greatest(coalesce(p_limit, 50), 1), 100)
  ) s;

  if v_ids is null then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  if exists (select 1 from public.training_protocols p where p.id = any (v_ids)) then
    perform app.log_record_access(v_org, v_actor, 'training_relationship.viewed', 'training_relationship', p_relationship_id);
  end if;

  return query
    select p.id, p.appointment_id, a.starts_at, a.ends_at, a.appointment_type,
           sp.given_name, sp.family_name, p.status, p.content, p.finalized_at,
           verfasser.display_name, o.time_zone
    from public.training_protocols p
    join public.appointments a   on a.id  = p.appointment_id
    join public.staff_members sm on sm.id = a.staff_member_id
    join public.persons sp       on sp.id = sm.person_id
    join public.organizations o  on o.id  = p.organization_id
    left join public.user_profiles verfasser on verfasser.id = p.created_by
    where p.id = any (v_ids)
    order by a.starts_at desc, p.id desc;
end;
$$;

COMMENT ON FUNCTION public.list_training_protocols(p_relationship_id uuid, p_limit integer) IS 'TRN-009: die Trainingsprotokolle einer Trainingskund:in, neueste zuerst, hoechstens 100. owner, trainer (ANN-184); jedes gezeigte Protokoll protokolliert als training_protocol.viewed, abgewiesen mit denied.';

CREATE FUNCTION public.list_treatment_basis_versions(p_treatment_basis_id uuid) RETURNS TABLE(version_no integer, content jsonb, replaced_at timestamp with time zone, replaced_by_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor      uuid;
  v_org        uuid;
  v_patient_id uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_read_treatment_basis_clinical() then
    -- G6a: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(v_actor, 'treatment_basis.viewed', 'not allowed to read clinical treatment basis data');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read clinical treatment basis data' using errcode = '42501';
  end if;

  select p.patient_id into v_patient_id
  from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org;

  if not found then
    return;
  end if;

  -- Akte geoeffnet, hoechstens einmal je Tag (LOG-EPIC-001, ADR-010).
  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', v_patient_id);

  return query
    select v.version_no,
           v.content,
           v.replaced_at,
           person.display_name
    from public.treatment_basis_versions v
    left join public.user_profiles person on person.id = v.replaced_by
    where v.treatment_basis_id = p_treatment_basis_id
      and v.organization_id = v_org
    order by v.version_no desc;
end;
$$;

COMMENT ON FUNCTION public.list_treatment_basis_versions(p_treatment_basis_id uuid) IS 'BEF-124: Die frueheren Staende einer Behandlungsgrundlage, juengster zuerst, mit Zeitpunkt und Person der Aenderung. Recht wie get_treatment_basis (klinisch lesen); Abweisung mit null Zeilen und access.denied.';

CREATE FUNCTION public.list_waitlist_entries(p_status text DEFAULT 'open'::text, p_patient_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, patient_id uuid, patient_given_name text, patient_family_name text, phone text, phone_mobile text, postal_code text, treatment_basis_id uuid, treatment_basis_kind text, treatment_basis_issued_on date, preferred_staff_member_id uuid, preferred_staff_name text, appointment_type text, duration_minutes smallint, time_windows jsonb, earliest_on date, needed_by date, priority_reason text, note text, status text, placed_appointment_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, closed_at timestamp with time zone, review_due boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    perform app.record_denied_read(auth.uid(), 'waitlist.read', 'not allowed to read waitlist');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read waitlist' using errcode = '42501';
  end if;
  if p_status is not null and p_status not in ('open', 'closed') then
    raise exception 'invalid status filter' using errcode = '22023';
  end if;

  return query
  select w.id,
         w.patient_id,
         pe.given_name,
         pe.family_name,
         cd.phone,
         cd.phone_mobile,
         cd.postal_code,
         w.treatment_basis_id,
         tb.treatment_basis_kind,
         tb.issued_on,
         w.preferred_staff_member_id,
         nullif(btrim(concat_ws(' ', spe.given_name, spe.family_name)), ''),
         w.appointment_type,
         w.duration_minutes,
         w.time_windows,
         w.earliest_on,
         w.needed_by,
         w.priority_reason,
         w.note,
         w.status,
         w.placed_appointment_id,
         w.created_at,
         w.updated_at,
         w.closed_at,
         -- ABN-018 (BEF-108): lange unveraendert offen - zu pruefen.
         (w.status = 'open' and w.updated_at < now() - app.waitlist_review_interval())
  from public.waitlist_entries w
  join public.patients pa on pa.id = w.patient_id
  join public.persons pe on pe.id = pa.person_id
  left join public.patient_contact_details cd on cd.patient_id = w.patient_id
  left join public.treatment_bases tb on tb.id = w.treatment_basis_id
  left join public.staff_members sm on sm.id = w.preferred_staff_member_id
  left join public.persons spe on spe.id = sm.person_id
  where w.organization_id = v_org
    and (p_patient_id is null or w.patient_id = p_patient_id)
    and (
      p_status is null
      or (p_status = 'open' and w.status = 'open')
      or (p_status = 'closed' and w.status <> 'open')
    )
  order by (w.status = 'open') desc,
           w.needed_by asc nulls last,
           w.created_at asc;
end;
$$;

CREATE FUNCTION public.list_waitlist_matches(p_staff_member_id uuid, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_exclude_patient_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, patient_id uuid, patient_given_name text, patient_family_name text, phone text, phone_mobile text, treatment_basis_id uuid, appointment_type text, duration_minutes smallint, time_windows jsonb, needed_by date, priority_reason text, territory_status text, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_tz    text;
  v_platz integer;
  v_von   integer;
  v_ab    timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    perform app.record_denied_read(auth.uid(), 'waitlist.read', 'not allowed to read waitlist');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read waitlist' using errcode = '42501';
  end if;
  if p_date is null or p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
    raise exception 'invalid slot' using errcode = '22023';
  end if;
  if p_staff_member_id is null or not app.is_assignable_therapist(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;

  select o.time_zone into v_tz from public.organizations o where o.id = v_org;
  v_von   := (extract(epoch from p_start_time) / 60)::integer;
  v_platz := (extract(epoch from (p_end_time - p_start_time)) / 60)::integer;
  v_ab    := (p_date + p_start_time)::timestamp at time zone v_tz;

  return query
  select w.id,
         w.patient_id,
         pe.given_name,
         pe.family_name,
         cd.phone,
         cd.phone_mobile,
         w.treatment_basis_id,
         w.appointment_type,
         w.duration_minutes,
         w.time_windows,
         w.needed_by,
         w.priority_reason,
         case when w.appointment_type = 'home_visit'
              then app.territory_day_status(v_org, cd.postal_code, p_date, p_start_time)
              else 'none' end,
         w.updated_at
  from public.waitlist_entries w
  join public.patients pa on pa.id = w.patient_id
  join public.persons pe on pe.id = pa.person_id
  left join public.patient_contact_details cd on cd.patient_id = w.patient_id
  where w.organization_id = v_org
    and w.status = 'open'
    and w.duration_minutes <= v_platz
    and (w.earliest_on is null or w.earliest_on <= p_date)
    and (w.preferred_staff_member_id is null or w.preferred_staff_member_id = p_staff_member_id)
    and (p_exclude_patient_id is null or w.patient_id <> p_exclude_patient_id)
    and (
      jsonb_array_length(w.time_windows) = 0
      or exists (
        select 1 from jsonb_array_elements(w.time_windows) f
        where (f ->> 'weekday')::int = extract(isodow from p_date)::int
          and v_von >= (extract(epoch from (f ->> 'from')::time) / 60)::integer
          and v_von + w.duration_minutes <= (extract(epoch from (f ->> 'to')::time) / 60)::integer
      )
    )
    and not exists (
      select 1 from public.appointments a
      where a.organization_id = v_org
        and a.patient_id = w.patient_id
        and a.status <> 'cancelled'
        and tstzrange(a.starts_at, a.ends_at, '[)')
            && tstzrange(v_ab, v_ab + make_interval(mins => w.duration_minutes), '[)')
    )
  order by w.needed_by asc nulls last, w.created_at asc
  limit 20;
end;
$$;

COMMENT ON FUNCTION public.list_waitlist_matches(p_staff_member_id uuid, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_exclude_patient_id uuid) IS 'Nachruecken (PRX-004): offene Wartelisteneintraege, die auf einen freien Platz passen - Dauer, fruehestens ab, Wunschzeit, Wunsch-Therapeut:in, keine eigene Ueberschneidung. Hoechstens 20, geordnet wie die Liste. Nur Terminverwaltung; versendet nichts.';

CREATE FUNCTION public.list_working_time() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_entsch  boolean;
  v_heute   date;
  v_naechst date;
begin
  v_org := app.staff_request_org(app.can_request_working_time(), 'not allowed to read working time');
  v_staff := app.own_staff_member(v_org);
  v_entsch := app.can_decide_staff_requests();
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;
  select min(h.valid_from) into v_naechst
  from public.staff_working_hours h
  where h.organization_id = v_org and h.staff_member_id = v_staff and h.valid_from > v_heute;

  return jsonb_build_object(
    'my_staff_member_id', v_staff,
    'can_decide', v_entsch,
    'self_entered', app.has_any_role('owner'),
    'today', v_heute,
    -- Der eigene Plan: was heute gilt und, wenn schon genehmigt, ab wann ein
    -- neuer gilt. Auch fuer die Trainingsbetreuung, die die Tabelle nicht liest.
    'plan', case when v_staff is null then null else jsonb_build_object(
      'has_plan', exists (
        select 1 from public.staff_working_hours h
        where h.organization_id = v_org and h.staff_member_id = v_staff
          and (h.valid_until is null or h.valid_until >= v_heute)),
      'current', app.plan_week(v_org, v_staff, v_heute),
      'next_from', v_naechst,
      'next', case when v_naechst is null then null else app.plan_week(v_org, v_staff, v_naechst) end
    ) end,
    -- Eigene Antraege mit allem, auch dem Grund und der Entscheidung.
    'own', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'kind', r.kind, 'on_date', r.on_date,
               'blocks', r.blocks, 'previous_blocks', r.previous_blocks,
               'previous_minutes', r.previous_minutes, 'new_minutes', r.new_minutes,
               'message', r.message, 'status', r.status, 'requested_at', r.requested_at,
               'decided_at', r.decided_at, 'decided_by_name', app.account_display_name(r.decided_by),
               'decision_note', r.decision_note, 'self_entered', r.self_entered
             ) order by r.requested_at desc)
      from public.staff_working_time_requests r
      where r.organization_id = v_org and r.staff_member_id = v_staff
        and (r.status = 'requested' or r.on_date >= v_heute or r.decided_at >= now() - interval '30 days'
             or r.withdrawn_at >= now() - interval '30 days')
    ), '[]'::jsonb),
    -- Fuer owner: offene Antraege anderer mit bisher und neu, Grund und den
    -- Tagen mit Terminen ausserhalb der neuen Zeiten.
    'to_decide', case when not v_entsch then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'kind', r.kind, 'on_date', r.on_date,
               'staff_member_id', r.staff_member_id,
               'name', app.staff_display_name(r.staff_member_id),
               'blocks', r.blocks, 'previous_blocks', r.previous_blocks,
               'previous_minutes', r.previous_minutes, 'new_minutes', r.new_minutes,
               'message', r.message, 'requested_at', r.requested_at,
               'appointment_days', app.appointments_outside_working_time(
                 v_org, r.staff_member_id, r.kind, r.on_date, r.blocks)
             ) order by r.requested_at)
      from public.staff_working_time_requests r
      where r.organization_id = v_org and r.status = 'requested'
        and r.staff_member_id is distinct from v_staff
    ), '[]'::jsonb) end
  );
end;
$$;

COMMENT ON FUNCTION public.list_working_time() IS 'AZ-001: Arbeitszeit in einem Aufruf - der eigene Plan (heute und ein schon genehmigter kuenftiger), eigene Antraege ganz; fuer owner die offenen Antraege anderer mit bisher, neu, Grund und Terminen ausserhalb. Keine Auswertung ueber Personen (PROJECT_PRINCIPLES.md 20).';

CREATE FUNCTION public.log_account_security_event(p_event text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_event is null or p_event not in (
    'password_changed', 'sessions_ended', 'mfa_enrolled', 'mfa_removed'
  ) then
    raise exception 'unknown account event' using errcode = '22023';
  end if;

  -- Die Organisation stammt aus dem Profil, nicht aus einem Parameter. Ein
  -- Konto ohne Profil kann kein Ereignis schreiben: Es gehoert zu keiner
  -- Praxis, und das Auditlog ist organisationsgebunden.
  select up.organization_id into v_org
  from public.user_profiles up
  where up.id = v_actor;

  if v_org is null then
    raise exception 'no practice account' using errcode = '42501';
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'account.' || p_event, 'user_account', v_actor, 'success',
    jsonb_build_object('surface', 'web')
  );
end;
$$;

COMMENT ON FUNCTION public.log_account_security_event(p_event text) IS 'Haelt fest, dass das eigene Konto Kennwort, Sitzungen oder zweiten Faktor geaendert hat. Fuehrt den Vorgang nicht aus - das tut der Anmeldedienst (STAFF-004, ADR-010).';

CREATE FUNCTION public.log_patient_record_view(p_patient_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select p.organization_id
    into v_org
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = app.current_organization_id()
    and app.can_read_patient_directory();

  if v_org is null then
    raise exception 'patient not accessible' using errcode = '42501';
  end if;

  perform app.log_record_access(v_org, v_actor, 'patient_record.viewed', 'patient', p_patient_id);
end;
$$;

COMMENT ON FUNCTION public.log_patient_record_view(p_patient_id uuid) IS 'Protokolliert das Oeffnen einer Patientenakte in der Detailansicht (ADR-010).';

CREATE FUNCTION public.log_therapy_report_export(p_report_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_status  text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_treatment_note() then
    raise exception 'not allowed to read therapy reports' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read therapy reports' using errcode = '42501';
  end if;

  select r.patient_id, r.status into v_patient, v_status
  from public.therapy_reports r
  where r.id = p_report_id and r.organization_id = v_org;
  if not found then
    raise exception 'therapy report not found' using errcode = 'P0002';
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'therapy_report.exported', 'therapy_report', p_report_id, 'success',
    jsonb_build_object('surface', 'web', 'patient_id', v_patient, 'status', v_status)
  );
end;
$$;

COMMENT ON FUNCTION public.log_therapy_report_export(p_report_id uuid) IS 'Protokolliert den Druck eines Therapieberichts als therapy_report.exported (DOK-005a, ADR-010 Punkt 2). Alle vier Praxisrollen.';

CREATE FUNCTION public.mark_all_team_channels_read() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  perform app.team_mark_channel_read(c.id, v_org, v_staff, null)
  from public.team_channels c
  where c.organization_id = v_org and app.team_channel_readable(c.id, v_org, v_staff);
  perform app.team_mark_thread_read(ts.root_message_id, v_staff, null)
  from public.team_thread_states ts
  join public.team_messages m on m.id = ts.root_message_id
  where ts.staff_member_id = v_staff and ts.following and ts.organization_id = v_org
    and app.team_channel_readable(m.channel_id, v_org, v_staff);
end;
$$;

CREATE FUNCTION public.mark_platform_exercise_set(p_access_id uuid, p_session_id uuid, p_item_id uuid, p_set_number integer, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_einheit public.exercise_plan_sessions%rowtype;
  v_saetze  smallint;
begin
  v_zugang := app.assert_platform_exercise(p_access_id);
  v_einheit := app.platform_open_exercise_session(p_access_id, p_session_id);
  if v_einheit.id is null then
    raise exception 'exercise session not found' using errcode = 'P0002';
  end if;

  select i.sets into v_saetze
  from public.exercise_plan_items i
  where i.id = p_item_id and i.plan_id = v_einheit.plan_id;
  if v_saetze is null then
    raise exception 'exercise not found' using errcode = 'P0002';
  end if;
  if p_set_number is null or p_set_number < 1 or p_set_number > v_saetze then
    raise exception 'set out of range' using errcode = '22023';
  end if;

  if coalesce(p_done, false) then
    insert into public.exercise_plan_session_sets (session_id, organization_id, item_id, set_number)
    values (v_einheit.id, v_einheit.organization_id, p_item_id, p_set_number)
    on conflict do nothing;
  else
    delete from public.exercise_plan_session_sets
    where session_id = v_einheit.id and item_id = p_item_id and set_number = p_set_number;
  end if;

  update public.exercise_plan_sessions set updated_at = now() where id = v_einheit.id;
end;
$$;

COMMENT ON FUNCTION public.mark_platform_exercise_set(p_access_id uuid, p_session_id uuid, p_item_id uuid, p_set_number integer, p_done boolean) IS 'UEB-010: hakt einen Satz einer Uebung in einer offenen Einheit ab oder nimmt den Haken zurueck - sofort gespeichert (ANN-305). Satznummer 1 bis zu den Saetzen der Position. Dieselben Rechte wie das Beginnen.';

CREATE FUNCTION public.mark_platform_habit(p_access_id uuid, p_habit_id uuid, p_done_on date, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_habit  public.habits%rowtype;
  v_zugang public.platform_accesses%rowtype;
  v_heute  date;
begin
  v_habit := app.platform_habit_for_writing(p_access_id, p_habit_id);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_habit.paused_at is not null then
    raise exception 'habit is paused' using errcode = '22023';
  end if;
  v_heute := app.training_today(v_zugang.organization_id);
  -- ANN-370: heute und die Tage davor, nicht vor dem Eintragen.
  if p_done_on is null or p_done is null
     or p_done_on > v_heute
     or p_done_on <= v_heute - app.habit_mark_days()
     or p_done_on < v_habit.starts_on then
    raise exception 'day not open' using errcode = '22023';
  end if;

  if p_done then
    insert into public.habit_marks (
      organization_id, habit_id, done_on, platform_access_id, platform_access_kind, recorded_by
    )
    values (
      v_zugang.organization_id, v_habit.id, p_done_on, v_zugang.id, v_zugang.access_kind, auth.uid()
    )
    on conflict (habit_id, done_on) do nothing;
  else
    delete from public.habit_marks m where m.habit_id = v_habit.id and m.done_on = p_done_on;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'habit')
  );
end;
$$;

COMMENT ON FUNCTION public.mark_platform_habit(p_access_id uuid, p_habit_id uuid, p_done_on date, p_done boolean) IS 'ALT-003 (ANN-370): vermerkt einen Tag einer laufenden, nicht pausierten Gewohnheit oder nimmt ihn zurueck - heute und die sechs Tage davor, nicht vor dem Eintragen (22023). Nur die Person und ihre rechtliche Vertretung, nicht in der Lesefrist, im Training nur mit Einwilligung (42501). Fremde oder beendete Gewohnheit P0002. Keine Benachrichtigung, keine Serie.';

CREATE FUNCTION public.mark_reimbursement_paid(p_reimbursement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_antrag public.staff_reimbursements%rowtype;
begin
  v_org := app.staff_request_org(app.can_decide_staff_requests(), 'not allowed to pay reimbursements');
  select r.* into v_antrag
  from public.staff_reimbursements r
  where r.id = p_reimbursement_id and r.organization_id = v_org
  for update;
  if v_antrag.id is null then
    raise exception 'reimbursement not found' using errcode = 'P0002';
  end if;
  if v_antrag.status = 'approved' and not app.may_pay_reimbursement(v_org, v_antrag) then
    raise exception 'not allowed to decide own request' using errcode = '42501';
  end if;
  if v_antrag.status <> 'approved' then
    raise exception 'reimbursement is not approved' using errcode = '55000';
  end if;
  update public.staff_reimbursements
     set status = 'paid', paid_by = auth.uid(), paid_at = now()
   where id = v_antrag.id;
  return jsonb_build_object('status', 'paid', 'paid_at', now());
end;
$$;

COMMENT ON FUNCTION public.mark_reimbursement_paid(p_reimbursement_id uuid) IS 'ERS-001 (ANN-598): owner vermerkt die Auszahlung eines genehmigten Antrags - nicht den eigenen eines anderen Kontos, den selbst eingetragenen schon. Ausgezahlt von/am ist der Nachweis; überwiesen wird bei der Bank.';

CREATE FUNCTION public.mark_team_channel_read(p_channel uuid, p_up_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  perform app.team_mark_channel_read(p_channel, v_org, v_staff, p_up_to);
end;
$$;

CREATE FUNCTION public.mark_team_thread_read(p_root uuid, p_up_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_kanal uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  select m.channel_id into v_kanal from public.team_messages m
  where m.id = p_root and m.organization_id = v_org and m.parent_id is null
    and m.created_at <= now();
  if v_kanal is null or not app.team_channel_readable(v_kanal, v_org, v_staff) then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  perform app.team_mark_thread_read(p_root, v_staff, p_up_to);
end;
$$;

CREATE FUNCTION public.mark_team_unread(p_message uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_m     public.team_messages%rowtype;
  v_bis   timestamptz;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  select * into v_m from public.team_messages
  where id = p_message and organization_id = v_org and created_at <= now();
  if v_m.id is null or not app.team_channel_readable(v_m.channel_id, v_org, v_staff) then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  if v_m.parent_id is null or v_m.also_in_channel then
    v_bis := coalesce((select max(x.created_at) from public.team_messages x
                       where x.channel_id = v_m.channel_id
                         and (x.parent_id is null or x.also_in_channel)
                         and x.created_at < v_m.created_at), '-infinity'::timestamptz);
    insert into public.team_read_states (organization_id, channel_id, staff_member_id, read_up_to)
    values (v_org, v_m.channel_id, v_staff, v_bis)
    on conflict (channel_id, staff_member_id) do update set read_up_to = excluded.read_up_to;
  end if;
  if v_m.parent_id is not null then
    v_bis := coalesce((select max(x.created_at) from public.team_messages x
                       where (x.id = v_m.parent_id or x.parent_id = v_m.parent_id)
                         and x.created_at < v_m.created_at), '-infinity'::timestamptz);
    insert into public.team_thread_states
      (organization_id, root_message_id, staff_member_id, following, read_up_to)
    values (v_org, v_m.parent_id, v_staff, true, v_bis)
    on conflict (root_message_id, staff_member_id)
    do update set following = true, read_up_to = excluded.read_up_to;
  end if;
end;
$$;

CREATE FUNCTION public.merge_patients(p_source_patient_id uuid, p_target_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor       uuid;
  v_org         uuid;
  v_plan        jsonb;
  v_quelle      public.patients%rowtype;
  v_ziel        public.patients%rowtype;
  v_person      uuid;
  v_status      text;
  v_ende_on     date;
  v_ende_at     timestamptz;
  v_ende_by     uuid;
  v_beginn      date;
  v_anschrift   boolean;
  v_fotos       integer := 0;
  v_sperre      uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_merge_patients() then
    perform app.record_denied_write(v_actor, 'patient.merged', 'not allowed to merge patients');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to merge patients' using errcode = '42501';
  end if;

  if p_source_patient_id is not distinct from p_target_patient_id then
    raise exception 'a patient cannot be merged into itself' using errcode = '22023';
  end if;

  -- Beide Akten sperren, in fester Reihenfolge - zwei gleichzeitige Vorgaenge
  -- ueber dasselbe Paar warten aufeinander statt sich zu verklemmen.
  perform 1 from public.patients p
  where p.id in (p_source_patient_id, p_target_patient_id)
    and p.organization_id = v_org
  order by p.id
  for update;
  -- ERN-001: dieselbe Sperre je Person wie beim Anlegen eines
  -- Ernaehrungsprofils - zwischen Plan und Umzug entsteht so keine zweite
  -- laufende Beratung der bleibenden Person (ADR-027 Punkt 1). NACH den
  -- Zeilensperren, wie dort: Das Anlegen sperrt erst die Zeile seines
  -- Verhaeltnisses, dann die Person - dieselbe Reihenfolge verklemmt nicht.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('nutrition:' || p.person_id::text, 0))
  from public.patients p
  where p.id in (p_source_patient_id, p_target_patient_id)
    and p.organization_id = v_org
  order by p.person_id;

  select * into v_quelle from public.patients p
  where p.id = p_source_patient_id and p.organization_id = v_org;
  select * into v_ziel from public.patients p
  where p.id = p_target_patient_id and p.organization_id = v_org;
  if v_quelle.id is null or v_ziel.id is null then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  v_plan := app.patient_merge_plan(v_org, v_quelle.id, v_ziel.id);
  if jsonb_array_length(v_plan -> 'blockers') > 0 then
    raise exception 'patient merge blocked: %',
      (select string_agg(x, ', ') from jsonb_array_elements_text(v_plan -> 'blockers') x)
      using errcode = '22023';
  end if;

  -- Was vor dem Zusammenfuehren schon faellig war, faellt unter dem Stand, der
  -- es faellig gemacht hat (ADR-017 Punkt 36 und 38).
  v_fotos := v_fotos + app.delete_due_patient_photos(
    v_org, v_quelle.id, extensions.gen_random_uuid(), v_actor, 'patient_merged'
  );
  v_fotos := v_fotos + app.delete_due_patient_photos(
    v_org, v_ziel.id, extensions.gen_random_uuid(), v_actor, 'patient_merged'
  );

  -- Die Zahlen des Nachweises erst jetzt: Ein eben geloeschtes Foto ist
  -- nicht mitgewandert und steht schon in photos_deleted.
  v_plan := app.patient_merge_plan(v_org, v_quelle.id, v_ziel.id);

  perform pg_catalog.set_config('app.patient_merge', 'on', true);

  -- Stammdaten (ANN-147) --------------------------------------------------
  if exists (select 1 from public.patient_contact_details c where c.patient_id = v_ziel.id) then
    select coalesce(z.street, z.house_number, z.postal_code, z.city) is null
       and coalesce(q.street, q.house_number, q.postal_code, q.city) is not null
      into v_anschrift
    from public.patient_contact_details z
    left join public.patient_contact_details q on q.patient_id = v_quelle.id
    where z.patient_id = v_ziel.id;

    update public.patient_contact_details z
       set date_of_birth = coalesce(z.date_of_birth, q.date_of_birth),
           email         = coalesce(z.email, q.email),
           phone         = coalesce(z.phone, q.phone),
           phone_mobile  = coalesce(z.phone_mobile, q.phone_mobile),
           phone_work    = coalesce(z.phone_work, q.phone_work),
           institution   = coalesce(z.institution, q.institution),
           street        = case when v_anschrift then q.street else z.street end,
           house_number  = case when v_anschrift then q.house_number else z.house_number end,
           postal_code   = case when v_anschrift then q.postal_code else z.postal_code end,
           city          = case when v_anschrift then q.city else z.city end
      from public.patient_contact_details q
     where z.patient_id = v_ziel.id
       and q.patient_id = v_quelle.id;

    -- Zweiter Schritt, weil der Trigger die Koordinate bei jeder
    -- Adressaenderung leert: Die Anschrift kommt mit ihrer Verortung.
    if v_anschrift then
      update public.patient_contact_details z
         set lat = q.lat, lon = q.lon, geocode_precision = q.geocode_precision
        from public.patient_contact_details q
       where z.patient_id = v_ziel.id
         and q.patient_id = v_quelle.id;
    end if;
  else
    update public.patient_contact_details
       set patient_id = v_ziel.id
     where patient_id = v_quelle.id;
  end if;

  if exists (select 1 from public.patient_care_details d where d.patient_id = v_ziel.id) then
    update public.patient_care_details z
       set primary_therapist_staff_member_id =
             coalesce(z.primary_therapist_staff_member_id, q.primary_therapist_staff_member_id),
           treatment_table_required = coalesce(z.treatment_table_required, q.treatment_table_required),
           home_visit_access_note = app.merge_note(z.home_visit_access_note, q.home_visit_access_note),
           special_note           = app.merge_note(z.special_note, q.special_note),
           remark                 = app.merge_note(z.remark, q.remark),
           take_along_items       = app.merge_take_along(z.take_along_items, q.take_along_items)
      from public.patient_care_details q
     where z.patient_id = v_ziel.id
       and q.patient_id = v_quelle.id;
  else
    update public.patient_care_details
       set patient_id = v_ziel.id
     where patient_id = v_quelle.id;
  end if;

  -- Der Bezug wechselt ----------------------------------------------------
  -- Zwei Standardempfaenger kann es nicht geben; der der bleibenden Akte bleibt.
  if exists (
    select 1 from public.invoice_recipients r where r.patient_id = v_ziel.id and r.is_default
  ) then
    update public.invoice_recipients
       set is_default = false
     where patient_id = v_quelle.id and is_default;
  end if;

  update public.invoice_recipients           set patient_id = v_ziel.id where patient_id = v_quelle.id;
  -- ABR-030: Die Honorarvereinbarungen ziehen mit; gleiche Tage sperrt der Plan.
  update public.patient_fee_agreements       set patient_id = v_ziel.id where patient_id = v_quelle.id;
  -- ANG-001: Das Nachsorge-Abo zieht mit; sich ueberschneidende sperrt der Plan.
  update public.aftercare_subscriptions      set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.training_offers              set patient_id = v_ziel.id where patient_id = v_quelle.id;
  -- UEB-004: Die Behandlungsplaene ziehen mit; der Riegel laesst nur patient_id wechseln.
  update public.exercise_plans               set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.treatment_bases              set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.appointments                 set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.billable_services            set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.invoices                     set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.patient_files                set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.patient_privacy_records      set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.patient_questionnaire_responses set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.patient_course_events        set patient_id = v_ziel.id where patient_id = v_quelle.id;
  -- KOM-004: Rueckfragen ueber die Plattform ziehen mit, zugeordnete wie
  -- nicht zugeordnete - sonst fielen sie mit der Dublette (cascade). Der
  -- Riegel an der Zuordnung laesst das Verhaeltnis nur hier wechseln.
  update public.platform_messages
     set patient_id = v_ziel.id, relationship_id = v_ziel.id
   where patient_id = v_quelle.id;
  -- BEF-131: Terminwuensche ueber die Plattform ziehen mit, offene wie
  -- beantwortete - sonst fielen sie mit der Dublette (cascade). Der
  -- Plattformzugang der Dublette bleibt als Nachweis (set null, BEF-132).
  update public.platform_appointment_requests
     set patient_id = v_ziel.id, relationship_id = v_ziel.id
   where patient_id = v_quelle.id;
  -- TRK-002: Check-ins ziehen mit, sonst fielen sie mit der Dublette
  -- (cascade). Den Takt behaelt die bleibende Akte; hat sie keinen, zieht
  -- der der Dublette mit (ANN-350).
  update public.checkins
     set patient_id = v_ziel.id, relationship_id = v_ziel.id
   where patient_id = v_quelle.id;
  if exists (select 1 from public.checkin_schedules s where s.patient_id = v_ziel.id) then
    delete from public.checkin_schedules where patient_id = v_quelle.id;
  else
    update public.checkin_schedules
       set patient_id = v_ziel.id, relationship_id = v_ziel.id
     where patient_id = v_quelle.id;
  end if;
  -- ALT-003: Gewohnheiten ziehen mit ihren Tagen mit, sonst fielen sie mit
  -- der Dublette (cascade). Mehr als drei laufende sind danach moeglich; die
  -- Grenze gilt beim Eintragen (ANN-370).
  update public.habits
     set patient_id = v_ziel.id, relationship_id = v_ziel.id
   where patient_id = v_quelle.id;
  -- ERN-001: Ernaehrungsprofile ziehen mit Einwilligung und Gewicht mit, sonst
  -- fielen sie mit der Dublette (cascade). Zwei laufende sperrt der Plan. Bewusst
  -- ohne Zaehler im Vermerk: Den lesen auch Rollen ohne die Faehigkeit (ADR-027
  -- Punkt 4).
  update public.nutrition_profiles
     set patient_id = v_ziel.id, relationship_id = v_ziel.id
   where patient_id = v_quelle.id;
  update public.therapy_reports              set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.tasks                        set patient_id = v_ziel.id where patient_id = v_quelle.id;
  update public.waitlist_entries             set patient_id = v_ziel.id where patient_id = v_quelle.id;
  -- Ein Legal Hold folgt den Daten, die er schuetzt (ANN-150). Seit ABN-018
  -- (BEF-108) bleiben alle Gruende wirksam: Eine Akte kann mehrere aktive
  -- Sperren tragen, keine wird beim Zusammenfuehren aufgehoben.
  v_sperre := null;
  update public.legal_holds
     set subject_id = v_ziel.id
   where subject_type = 'patient' and subject_id = v_quelle.id;
  -- Fruehere Nachweise der Dublette ziehen mit (ABN-018).
  update public.patient_merge_records set target_patient_id = v_ziel.id
   where target_patient_id = v_quelle.id;

  perform pg_catalog.set_config('app.patient_merge', 'off', true);

  -- Versorgungsstand (ANN-148) --------------------------------------------
  v_status := case
    when v_quelle.status = 'active' or v_ziel.status = 'active' then 'active'
    else 'inactive'
  end;
  v_beginn := least(v_quelle.care_started_on, v_ziel.care_started_on);

  if v_quelle.care_concluded_on is null or v_ziel.care_concluded_on is null then
    null;
  elsif (v_quelle.care_concluded_on, v_quelle.care_concluded_at)
        > (v_ziel.care_concluded_on, v_ziel.care_concluded_at) then
    v_ende_on := v_quelle.care_concluded_on;
    v_ende_at := v_quelle.care_concluded_at;
    v_ende_by := v_quelle.care_concluded_by;
  else
    v_ende_on := v_ziel.care_concluded_on;
    v_ende_at := v_ziel.care_concluded_at;
    v_ende_by := v_ziel.care_concluded_by;
  end if;

  update public.patients
     set status            = v_status,
         care_started_on   = v_beginn,
         care_concluded_on = v_ende_on,
         care_concluded_at = v_ende_at,
         care_concluded_by = v_ende_by
   where id = v_ziel.id;

  -- Die Einwilligungsvermerke beider Akten gelten jetzt gemeinsam: Ein
  -- Widerruf in der einen trifft die aelteren Fotos der anderen - sofort,
  -- wie beim Widerruf selbst (ADR-017 Punkt 36).
  v_fotos := v_fotos + app.delete_due_patient_photos(
    v_org, v_ziel.id, extensions.gen_random_uuid(), v_actor, 'patient_merged'
  );

  -- Die leere Akte faellt (ANN-150) -----------------------------------------
  -- Was noch an ihr haengt, faellt mit ihr (Kontakt und Versorgungsangaben der
  -- Dublette, soweit sie in die bleibende Akte eingeflossen sind).
  delete from public.patient_contact_details where patient_id = v_quelle.id;
  delete from public.patient_care_details where patient_id = v_quelle.id;
  delete from public.patients where id = v_quelle.id;

  -- Die Person nur, wenn nichts anderes an ihr haengt: Mitarbeiter:in, Konto,
  -- Trainingsverhaeltnis (ADR-021) bleiben, wie sie sind.
  v_person := v_quelle.person_id;
  if not exists (select 1 from public.patients p where p.person_id = v_person)
     and not exists (select 1 from public.staff_members s where s.person_id = v_person)
     and not exists (select 1 from public.user_profiles u where u.person_id = v_person)
     and not exists (select 1 from public.training_relationships t where t.person_id = v_person) then
    delete from public.persons where id = v_person;
  end if;

  -- Nachweis an der bleibenden Akte, so lange wie sie (ABN-018, BEF-108):
  -- nicht allein im dreijaehrigen Auditlog.
  insert into public.patient_merge_records (
    organization_id, target_patient_id, source_patient_id, merged_by, counts, photos_deleted
  )
  values (v_org, v_ziel.id, v_quelle.id, v_actor, v_plan -> 'counts', v_fotos);


  return jsonb_build_object(
    'target_patient_id', v_ziel.id,
    'moved', v_plan -> 'counts',
    'photos_deleted', v_fotos
  );
end;
$$;

COMMENT ON FUNCTION public.merge_patients(p_source_patient_id uuid, p_target_patient_id uuid) IS 'Fuehrt eine Dublette in die bleibende Akte ueber (PRX-017, ANN-147 bis ANN-150): Bezuege wechseln, Inhalte nicht; die leere Akte faellt, ihre Person nur ohne andere Bezuege. Nur owner; protokolliert patient.merged, abgewiesen mit denied-Eintrag und HTTP 403 (G6c). Nicht rueckgaengig.';

CREATE FUNCTION public.message_attachment_for_verification(p_attachment_id uuid, p_user_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text, byte_size bigint, checksum_sha256 text, already_verified boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.message_attachment_bucket(), x.object_key, x.mime_type, x.byte_size,
         x.checksum_sha256, x.verified_at is not null
  from public.platform_message_attachments x
  where x.id = p_attachment_id
    and x.created_by = p_user_id
    and x.created_at > now() - interval '24 hours'
    and (x.status = 'ready' or x.confirmation_requested_at is not null)
$$;

CREATE FUNCTION public.move_exercise_plan_item(p_item_id uuid, p_direction text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan    public.exercise_plans%rowtype;
  v_item    public.exercise_plan_items%rowtype;
  v_nachbar public.exercise_plan_items%rowtype;
begin
  select i.* into v_item from public.exercise_plan_items i where i.id = p_item_id;
  v_plan := app.exercise_plan_for_write(coalesce(v_item.plan_id, extensions.gen_random_uuid()));
  if v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;
  if p_direction is null or p_direction not in ('up', 'down') then
    raise exception 'direction is invalid' using errcode = '22023';
  end if;

  select i.* into v_nachbar
  from public.exercise_plan_items i
  where i.plan_id = v_plan.id
    and case when p_direction = 'up' then i.position < v_item.position
             else i.position > v_item.position end
  order by case when p_direction = 'up' then -i.position else i.position end
  limit 1;

  if not found then
    return;
  end if;

  -- Die Eindeutigkeit der Position wird erst am Ende der Transaktion geprueft.
  update public.exercise_plan_items set position = v_nachbar.position where id = v_item.id;
  update public.exercise_plan_items set position = v_item.position where id = v_nachbar.id;
  update public.exercise_plans set updated_at = now(), updated_by = auth.uid() where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.move_exercise_plan_item(p_item_id uuid, p_direction text) IS 'UEB-004: tauscht eine Position im Entwurf mit ihrer Nachbarin (up, down). Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.notification_kind_switches() RETURNS TABLE(kind text, disabled_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not app.has_any_role('owner') then
    raise exception 'owner only' using errcode = '42501';
  end if;
  return query
  select k.kind, k.disabled_at
  from public.notification_kind_switches k
  where k.organization_id = app.current_organization_id()
  order by k.kind;
end;
$$;

COMMENT ON FUNCTION public.notification_kind_switches() IS 'KOM-009 (ADR-024 Punkt 15): die Benachrichtigungsarten, die die Praxis fuer alle abgeschaltet hat. Nur owner; sagt nichts ueber die Wahl einzelner Personen (ANN-344).';

CREATE FUNCTION public.nutrition_appointment_documentation_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.appointments a
    where a.id = new.appointment_id and a.occasion = 'nutrition_counselling'
  ) then
    raise exception 'a nutrition counselling appointment carries no treatment documentation or training protocol'
      using errcode = '22023';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.offset_payment(p_cancelled_invoice_id uuid, p_replacement_invoice_id uuid, p_amount_cents integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_alt      record;
  v_neu      record;
  v_zeitzone text;
  v_heute    date;
  v_gruppe   uuid := extensions.gen_random_uuid();
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'a payment needs a positive amount' using errcode = '22023';
  end if;

  -- Beide Rechnungen in fester Reihenfolge sperren (nach Kennung), damit zwei
  -- gleichzeitige Vorgaenge sich nicht kreuzweise blockieren.
  perform 1 from public.invoices i
   where i.id in (p_cancelled_invoice_id, p_replacement_invoice_id)
     and i.organization_id = v_org
   order by i.id
   for update;

  select i.* into v_alt
  from public.invoices i
  where i.id = p_cancelled_invoice_id and i.organization_id = v_org;
  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  select i.* into v_neu
  from public.invoices i
  where i.id = p_replacement_invoice_id and i.organization_id = v_org;
  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.invoice_cancellations c where c.invoice_id = p_cancelled_invoice_id
  ) then
    raise exception 'only a cancelled invoice can pass on its payments' using errcode = '23514';
  end if;

  -- Verrechnet wird mit der Rechnung, die diese ersetzt - nicht mit einer
  -- beliebigen offenen Rechnung derselben Person (ANN-215).
  if v_neu.replaces_invoice_id is distinct from p_cancelled_invoice_id
     or v_neu.status <> 'issued'
     or exists (
       select 1 from public.invoice_cancellations c where c.invoice_id = p_replacement_invoice_id
     ) then
    raise exception 'payments are offset only against the issued replacement invoice'
      using errcode = '23514';
  end if;

  if v_neu.currency <> v_alt.currency then
    raise exception 'currencies differ' using errcode = '23514';
  end if;

  if p_amount_cents > app.invoice_paid_cents(p_cancelled_invoice_id) then
    raise exception 'an offset cannot exceed the payments received' using errcode = '23514';
  end if;

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  insert into public.payments (
    organization_id, invoice_id, direction, amount_cents, currency,
    paid_on, method, offset_group, created_by
  )
  values
    (v_org, p_cancelled_invoice_id,   'refund',   p_amount_cents, v_alt.currency,
     v_heute, 'offset', v_gruppe, v_actor),
    (v_org, p_replacement_invoice_id, 'incoming', p_amount_cents, v_neu.currency,
     v_heute, 'offset', v_gruppe, v_actor);


  return v_gruppe;
end;
$$;

COMMENT ON FUNCTION public.offset_payment(p_cancelled_invoice_id uuid, p_replacement_invoice_id uuid, p_amount_cents integer) IS 'Verrechnet einen an einer stornierten Rechnung eingegangenen Betrag mit ihrer ausgestellten Ersatzrechnung: zwei verbundene Buchungen (refund und incoming, method offset). Hoechstens der eingegangene Betrag. Protokolliert payment.offset (ABN-008, BEF-100, ANN-215).';

CREATE FUNCTION public.open_team_direct(p_staff_member uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_id    uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if p_staff_member is null or p_staff_member = v_staff
     or not app.teamchat_participant(v_org, p_staff_member) then
    raise exception 'team chat partner is not available' using errcode = '22023';
  end if;

  -- Gleichzeitiges Öffnen durch beide legt nur ein Gespräch an.
  perform pg_advisory_xact_lock(
    hashtextextended('team_direct:' || least(v_staff, p_staff_member)::text
                     || greatest(v_staff, p_staff_member)::text, 0));

  select c.id into v_id
  from public.team_channels c
  where c.organization_id = v_org and c.kind = 'direct'
    and exists (select 1 from public.team_channel_members m
                where m.channel_id = c.id and m.staff_member_id = v_staff)
    and exists (select 1 from public.team_channel_members m
                where m.channel_id = c.id and m.staff_member_id = p_staff_member)
  limit 1;

  if v_id is null then
    insert into public.team_channels (organization_id, kind) values (v_org, 'direct')
    returning id into v_id;
    insert into public.team_channel_members (organization_id, channel_id, staff_member_id)
    values (v_org, v_id, v_staff), (v_org, v_id, p_staff_member);
  end if;
  return v_id;
end;
$$;

CREATE FUNCTION public.open_team_group(p_staff_members uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_staff  uuid;
  v_andere uuid[];
  v_alle   uuid[];
  v_id     uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  v_andere := array(select distinct u.staff from unnest(coalesce(p_staff_members, '{}'::uuid[])) as u (staff)
                    where u.staff is not null and u.staff <> v_staff
                    order by 1);
  if cardinality(v_andere) = 0 or cardinality(v_andere) > 8 then
    raise exception 'a group needs three to nine people' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_andere) as u (staff)
             where not app.teamchat_participant(v_org, u.staff)) then
    raise exception 'team chat partner is not available' using errcode = '22023';
  end if;
  if cardinality(v_andere) = 1 then
    return public.open_team_direct(v_andere[1]);
  end if;
  v_alle := array(select u.staff from unnest(v_andere || v_staff) as u (staff) order by 1);

  -- Gleichzeitiges Öffnen legt nur ein Gespräch an.
  perform pg_advisory_xact_lock(hashtextextended('team_group:' || array_to_string(v_alle, ','), 0));

  select c.id into v_id
  from public.team_channels c
  where c.organization_id = v_org and c.kind = 'group'
    and (select array_agg(m.staff_member_id order by m.staff_member_id)
         from public.team_channel_members m where m.channel_id = c.id) = v_alle
  limit 1;

  if v_id is null then
    insert into public.team_channels (organization_id, kind) values (v_org, 'group')
    returning id into v_id;
    insert into public.team_channel_members (organization_id, channel_id, staff_member_id)
    select v_org, v_id, u.staff from unnest(v_alle) as u (staff);
  end if;
  return v_id;
end;
$$;

CREATE FUNCTION public.order_orphaned_object_deletion() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_anzahl integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_execute_storage_deletion() then
    perform app.record_denied_write(auth.uid(), 'storage_deletion.ordered', 'not allowed to order deletions');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to order deletions' using errcode = '42501';
  end if;

  insert into public.storage_deletion_orders (organization_id, bucket_id, object_key)
  select v_org, o.bucket_id, o.name
  from storage.objects o
  where o.bucket_id in (app.patient_file_bucket(), app.patient_photo_bucket(),
                        app.message_attachment_bucket(), app.fleet_photo_bucket(),
                        app.reimbursement_receipt_bucket(), app.chat_attachment_bucket())
    and o.name like v_org::text || '/%'
    and not exists (
      select 1
      from public.patient_files f
      where f.object_key = o.name
        and app.patient_file_bucket_for(f.document_type) = o.bucket_id
    )
    and not exists (
      select 1
      from public.platform_message_attachments x
      where x.object_key = o.name
        and o.bucket_id = app.message_attachment_bucket()
    )
    and not exists (
      select 1
      from public.fleet_photos x
      where x.object_key = o.name
        and o.bucket_id = app.fleet_photo_bucket()
    )
    and not exists (
      select 1
      from public.staff_reimbursement_receipts x
      where x.object_key = o.name
        and o.bucket_id = app.reimbursement_receipt_bucket()
    )
    and not exists (
      select 1
      from public.team_message_attachments x
      where x.object_key = o.name
        and o.bucket_id = app.chat_attachment_bucket()
    )
  on conflict do nothing;

  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.order_orphaned_object_deletion() IS 'Schreibt fuer jedes verwaiste Objekt einen Loeschauftrag (ADR-017 Punkt 27). Geloescht wird danach ueber den gewoehnlichen Weg mit Quittung.';

CREATE FUNCTION public.own_offline_passkeys() RETURNS TABLE(webauthn_id text, public_key text, public_key_alg integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if auth.uid() is null or not app.session_open() then
    raise exception 'session locked' using errcode = '42501';
  end if;
  if to_regclass('auth.webauthn_credentials') is null then
    return;
  end if;
  return query execute $q$
    select a.webauthn_id, a.public_key, a.public_key_alg
    from public.passkey_approvals a
    where a.user_id = $1
      and a.public_key is not null
      and exists (select 1 from auth.webauthn_credentials c
                  where c.id = a.credential_id and c.user_id = $1)
    order by a.approved_at
  $q$ using auth.uid();
end;
$_$;

COMMENT ON FUNCTION public.own_offline_passkeys() IS 'TRK-009 (ADR-025 Punkt 16, ANN-359): Kennung und oeffentlicher Schluessel der freigegebenen Passkeys des eigenen Kontos, die es beim Anmeldedienst noch gibt - fuer die Freigabe ohne Netz auf dem Geraet. Nur in offener Sitzung (42501).';

CREATE FUNCTION public.own_passkey_approvals() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select a.credential_id from public.passkey_approvals a where a.user_id = auth.uid()
$$;

COMMENT ON FUNCTION public.own_passkey_approvals() IS 'Die freigegebenen Passkeys des eigenen Kontos (Kennungen), für „Mein Konto“ und die Einrichtung (ANN-329).';

CREATE FUNCTION public.own_pin_status() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.account_pins p where p.user_id = auth.uid())
$$;

COMMENT ON FUNCTION public.own_pin_status() IS 'Ob das eigene Konto eine App-PIN hat (ADR-025 Punkt 11). Auch in gesperrter Sitzung: Die Sperrseite bietet die PIN nur an, wenn es eine gibt. Kein Inhalt.';

CREATE FUNCTION public.patient_file_for_verification(p_file_id uuid, p_user_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text, byte_size bigint, checksum_sha256 text, already_verified boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.patient_file_bucket_for(f.document_type),
         f.object_key,
         f.mime_type,
         f.byte_size,
         f.checksum_sha256,
         f.verified_at is not null
  from public.patient_files f
  join public.user_profiles up
    on up.id = p_user_id
   and up.organization_id = f.organization_id
   and up.is_active
  where f.id = p_file_id
    and f.uploaded_by = p_user_id
    and f.created_at > now() - interval '24 hours'
    and (f.status = 'ready' or f.confirmation_requested_at is not null)
$$;

COMMENT ON FUNCTION public.patient_file_for_verification(p_file_id uuid, p_user_id uuid) IS 'Nur fuer den Dienst patient-file-verify (service_role): Bucket, Objektschluessel, Ankuendigung und Pruefstand einer bestaetigten Datei aus der Organisation der ausloesenden Person (ADR-017 Punkt 50). Kein Name, kein Personenbezug.';

CREATE FUNCTION public.patient_retention_status(p_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org        uuid;
  v_zone       text;
  v_abschluss  date;
  v_anker      date;
  v_akte       record;
  v_abr        record;
  v_jahr       date;
  v_klassen    jsonb := '[]'::jsonb;
begin
  v_org := app.auskunft_organisation(p_patient_id);

  select o.time_zone into v_zone from public.organizations o where o.id = v_org;

  select p.care_concluded_on into v_abschluss
  from public.patients p where p.id = p_patient_id;

  -- B1 (ADR-008 Fassung 3): Anker aus letzter Behandlung, erfasster Leistung
  -- und einem etwaigen ausdruecklichen Abschluss. Ohne jede Behandlung laeuft
  -- keine Frist; ein kuenftiger Termin haelt die Akte (dann kein Datum).
  v_anker := case when app.patient_has_upcoming_care(p_patient_id) then null
                  else app.patient_retention_anchor(p_patient_id) end;

  select k.key, k.legal_reference, k.retention_interval, k.anchor
    into v_akte
  from public.retention_classes k where k.key = 'patientenakte';

  v_klassen := v_klassen || jsonb_build_array(jsonb_build_object(
    'key', v_akte.key,
    'legal_reference', v_akte.legal_reference,
    'anchor', v_akte.anchor,
    'anker_datum', v_anker,
    'frist_ende', case when v_anker is null then null
                       else (v_anker + v_akte.retention_interval)::date end,
    'loeschbar_ab', case when v_anker is null then null
                         else app.retention_due_at(v_anker, v_akte.retention_interval, v_zone) end,
    'datensaetze', (select count(*) from public.patients p where p.id = p_patient_id)
  ));

  -- Abrechnung: eigene Frist ab Ende des Kalenderjahres der letzten
  -- ausgestellten Rechnung. Sie haelt die Akte laenger fest als die Akte sich
  -- selbst, wenn spaet abgerechnet wurde (ADR-008, Konsequenz zu ADR-009).
  select k.key, k.legal_reference, k.retention_interval, k.anchor
    into v_abr
  from public.retention_classes k where k.key = 'abrechnungsdaten';

  select make_date(extract(year from max(r.issued_on))::int, 12, 31)
    into v_jahr
  from public.invoices r
  where r.patient_id = p_patient_id and r.issued_on is not null;

  v_klassen := v_klassen || jsonb_build_array(jsonb_build_object(
    'key', v_abr.key,
    'legal_reference', v_abr.legal_reference,
    'anchor', v_abr.anchor,
    'anker_datum', v_jahr,
    'frist_ende', case when v_jahr is null then null
                       else (v_jahr + v_abr.retention_interval)::date end,
    'loeschbar_ab', case when v_jahr is null then null
                         else app.retention_due_at(v_jahr, v_abr.retention_interval, v_zone) end,
    'datensaetze', (select count(*) from public.invoices r
                    where r.patient_id = p_patient_id and r.issued_on is not null)
  ));

  return jsonb_build_object(
    'patient_id', p_patient_id,
    'zeitzone', v_zone,
    'versorgung_abgeschlossen_am', v_abschluss,
    'klassen', v_klassen,
    -- ABN-018 (BEF-108): Eine Akte kann mehrere aktive Sperren tragen; der
    -- Stand nennt die frueheste und alle Gruende.
    'loeschsperre', (
      select jsonb_build_object(
               'seit', min(s.placed_at),
               'grund', string_agg(s.reason, '; ' order by s.placed_at))
      from public.legal_holds s
      where s.subject_type = 'patient'
        and s.subject_id = p_patient_id
        and s.released_at is null
      having count(*) > 0
    )
  );
end;
$$;

COMMENT ON FUNCTION public.patient_retention_status(p_patient_id uuid) IS 'Laufende Aufbewahrungsfristen einer Akte als Grundlage der begruendeten Ablehnung nach Art. 17 Abs. 3 lit. b DSGVO (OPS-006, ADR-008).';

CREATE FUNCTION public.pause_platform_habit(p_access_id uuid, p_habit_id uuid, p_paused boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_habit public.habits%rowtype;
begin
  v_habit := app.platform_habit_for_writing(p_access_id, p_habit_id);
  if p_paused is null then
    raise exception 'paused is required' using errcode = '22023';
  end if;
  if p_paused and v_habit.paused_at is null then
    update public.habits
       set paused_at = now(), paused_by_access_id = p_access_id,
           paused_by_kind = (select a.access_kind from public.platform_accesses a
                             where a.id = p_access_id)
     where id = v_habit.id;
  elsif not p_paused and v_habit.paused_at is not null then
    update public.habits
       set paused_at = null, paused_by_access_id = null, paused_by_kind = null
     where id = v_habit.id;
  end if;
  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'habit')
  );
end;
$$;

COMMENT ON FUNCTION public.pause_platform_habit(p_access_id uuid, p_habit_id uuid, p_paused boolean) IS 'ALT-003 (IDEA-ALT-002, ANN-370): pausiert eine laufende Gewohnheit oder setzt sie fort - bei Krankheit wird pausiert, nicht gebrochen. Dieselben Rechte wie mark_platform_habit. Wiederholt ohne Wirkung.';

CREATE FUNCTION public.place_legal_hold(p_patient_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_hold  uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_legal_hold() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'legal_hold.placed', 'not allowed to manage legal holds');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage legal holds' using errcode = '42501';
  end if;

  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'a legal hold needs a reason' using errcode = '22023';
  end if;

  -- Zielakte ausschliesslich in der Organisation des Aufrufers suchen - und
  -- sperren, damit ein gleichzeitiges Zusammenfuehren zuerst fertig wird.
  perform 1
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = v_org
  for share;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- ABN-018 (BEF-108): Eine weitere Sperre mit eigenem Grund ist zulaessig;
  -- jede bleibt wirksam, bis sie selbst aufgehoben ist.

  insert into public.legal_holds (
    organization_id, subject_type, subject_id, reason, placed_by
  )
  values (v_org, 'patient', p_patient_id, btrim(p_reason), v_actor)
  returning id into v_hold;


  return v_hold;
end;
$$;

COMMENT ON FUNCTION public.place_legal_hold(p_patient_id uuid, p_reason text) IS 'Setzt eine Loeschsperre auf eine Patientenakte und protokolliert legal_hold.placed (ADR-008 Punkt 7, LOE-001c). Nur owner. Der Grund steht in der Tabelle, nicht im Auditkontext.';

CREATE FUNCTION public.place_staff_legal_hold(p_staff_member_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_hold  uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_legal_hold() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'legal_hold.placed', 'not allowed to manage legal holds');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage legal holds' using errcode = '42501';
  end if;

  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'a legal hold needs a reason' using errcode = '22023';
  end if;

  perform 1
  from public.staff_members s
  where s.id = p_staff_member_id
    and s.organization_id = v_org;

  if not found then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  -- Wie bei der Akte (ABN-018): Eine weitere Sperre mit eigenem Grund ist
  -- zulaessig; jede bleibt wirksam, bis sie selbst aufgehoben ist.
  insert into public.legal_holds (
    organization_id, subject_type, subject_id, reason, placed_by
  )
  values (v_org, 'staff_member', p_staff_member_id, btrim(p_reason), v_actor)
  returning id into v_hold;

  return v_hold;
end;
$$;

COMMENT ON FUNCTION public.place_staff_legal_hold(p_staff_member_id uuid, p_reason text) IS 'Setzt eine Loeschsperre auf die Beschaeftigtendaten einer Person des Teams: Urlaub, Arbeitszeitaenderungen, Zeitkonto, Erstattungen (ADR-008 Punkt 7, BEF-178, ANN-674). Nur owner. Nachweis an der Sperre (placed_by, placed_at), kein Auditeintrag.';

-- ANN-217
CREATE FUNCTION public.platform_accesses_take_back_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.account_user_id is not null and new.status in ('active', 'locked') then
    delete from public.platform_account_deletions d
     where d.account_user_id = new.account_user_id
       and d.reason <> 'reapply'
       and d.claimed_at is null;
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.platform_aftercare(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_abo    public.aftercare_subscriptions%rowtype;
  v_heute  date;
  v_naechster date;
begin
  if not app.platform_access_allows(p_access_id, 'billing') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'treatment' then
    return null;
  end if;

  select * into v_abo
  from public.aftercare_subscriptions s
  where s.patient_id = v_zugang.relationship_id
    and s.organization_id = v_zugang.organization_id
  order by s.starts_on desc
  limit 1;
  if not found then
    return null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'aftercare')
  );

  v_heute := app.training_today(v_abo.organization_id);
  if v_abo.ends_on is null then
    v_naechster := case
      when v_heute < v_abo.starts_on then v_abo.starts_on
      else app.aftercare_month_start(v_abo.starts_on, app.aftercare_month_index(v_abo.starts_on, v_heute) + 1)
    end;
  end if;

  return jsonb_build_object(
    'id', v_abo.id,
    'starts_on', v_abo.starts_on,
    'ends_on', v_abo.ends_on,
    'state', case
      when v_abo.ends_on is null then 'running'
      when v_abo.ends_on >= v_heute then 'ending'
      else 'ended'
    end,
    'next_month_start', v_naechster,
    'next_month_price_cents', (
      select pr.unit_price_cents from app.aftercare_month_price(v_abo.organization_id, v_naechster) pr
    ),
    'cancel_effective_on', case when v_abo.ends_on is null
      then app.aftercare_cancellation_end(v_abo.starts_on, v_heute) end,
    'cancelled_at', v_abo.cancelled_at,
    'cancelled_via', v_abo.cancelled_via,
    'can_cancel', v_abo.ends_on is null and app.platform_access_allows(p_access_id, 'contract')
  );
end;
$$;

COMMENT ON FUNCTION public.platform_aftercare(p_access_id uuid) IS 'ANG-003: Plattformprojektion "Nachsorge-Abo" - das juengste Abo der Akte hinter dem Zugang mit Stand, naechstem Monat und Preis. Recht billing; den Kuendigungsknopf traegt can_cancel (Recht contract, ANN-273). Vertretung protokolliert.';

CREATE FUNCTION public.platform_appointment_requests(p_access_id uuid) RETURNS TABLE(id uuid, kind text, appointment_id uuid, preferred_days date[], preferred_times text[], note text, status text, created_at timestamp with time zone, resolved_at timestamp with time zone, answer text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'requests')
  );

  return query
  select w.id, w.kind, w.appointment_id, w.preferred_days, w.preferred_times, w.note,
         w.status, w.created_at, w.resolved_at, w.answer
  from public.platform_appointment_requests w
  where w.organization_id = v_zugang.organization_id
    and w.relationship_kind = v_zugang.relationship_kind
    and w.relationship_id = v_zugang.relationship_id
  order by (w.status <> 'open'), w.created_at desc, w.id;
end;
$$;

COMMENT ON FUNCTION public.platform_appointment_requests(p_access_id uuid) IS 'POR-009: Plattformprojektion der eigenen Terminwuensche des Verhaeltnisses (offene zuerst), mit Zustand und Antwort der Praxis. Nur ueber einen lesbaren Zugang; Vertretung protokolliert (ADR-023 Punkt 24).';

CREATE FUNCTION public.platform_appointments(p_access_id uuid) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, appointment_type text, status text, staff_name text, location_name text, visit_street text, visit_house_number text, visit_postal_code text, visit_city text, late_notice boolean, open_request_kind text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'appointments')
  );

  return query
  select a.id,
         a.starts_at,
         a.ends_at,
         a.appointment_type,
         case a.status
           when 'documented' then 'completed'
           when 'invoiced' then
             case a.fee_basis
               when 'no_show' then 'no_show'
               when 'late_cancellation' then 'cancelled'
               else 'completed'
             end
           else a.status
         end,
         nullif(concat_ws(' ', pe.given_name, pe.family_name), ''),
         l.name,
         a.visit_street,
         a.visit_house_number,
         a.visit_postal_code,
         a.visit_city,
         case when a.status = 'confirmed' and a.starts_at > now()
           then a.starts_at - now() < app.cancellation_notice_period()
         end,
         (select w.kind from public.platform_appointment_requests w
           where w.appointment_id = a.id and w.status = 'open' limit 1)
  from public.appointments a
  left join public.staff_members s on s.id = a.staff_member_id
  left join public.persons pe on pe.id = s.person_id
  left join public.locations l on l.id = a.location_id
  where a.organization_id = v_zugang.organization_id
    and (
      (v_zugang.relationship_kind = 'treatment'
         and a.kind = 'therapy'
         and a.patient_id = v_zugang.relationship_id)
      or
      (v_zugang.relationship_kind = 'training'
         and a.kind = 'training'
         and a.training_relationship_id = v_zugang.relationship_id)
    )
    and a.starts_at >= now() - app.platform_appointment_history()
  order by a.starts_at, a.id;
end;
$$;

COMMENT ON FUNCTION public.platform_appointments(p_access_id uuid) IS 'POR-008/POR-010: Plattformprojektion "Termine" (DSN-001 4.1): die eigenen Termine des Verhaeltnisses hinter einem lesbaren Zugang, kuenftige und die der letzten zwoelf Monate (ANN-251), mit Frist des Ausfallhonorars (late_notice, ADR-018 Punkt 8) und offenem Wunsch. Feste Spaltenliste (ADR-023 Punkt 22). Ueber eine Vertretung protokolliert (Punkt 24).';

CREATE FUNCTION public.platform_checkins(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_heute   date;
  v_takt    public.checkin_schedules%rowtype;
  v_faellig date;
  v_einwilligung boolean;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_heute := app.training_today(v_zugang.organization_id);
  select * into v_takt
  from public.checkin_schedules s
  where s.relationship_kind = v_zugang.relationship_kind
    and s.relationship_id = v_zugang.relationship_id;
  if v_takt.id is not null then
    v_faellig := app.checkin_due_on(v_takt);
  end if;
  v_einwilligung := app.platform_exercise_note_allowed(
    v_zugang.relationship_kind, v_zugang.relationship_id);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'checkins')
  );

  return jsonb_build_object(
    'today', v_heute,
    'schedule', case when v_takt.id is null then null else jsonb_build_object(
      'interval_days', v_takt.interval_days,
      'parameter_keys', to_jsonb(v_takt.parameter_keys)
    ) end,
    'due_on', v_faellig,
    'due', v_faellig is not null and v_faellig <= v_heute,
    -- Darf dieser Zugang jetzt antworten? Recht, Lesefrist, Einwilligung.
    'can_answer', v_faellig is not null and v_faellig <= v_heute
                  and app.platform_access_allows(p_access_id, 'checkin')
                  and app.platform_access_writable(p_access_id)
                  and v_einwilligung,
    -- Im Training fehlt die Einwilligung zu Gesundheitsangaben (ADR-021 Punkt 4).
    'consent_needed', not v_einwilligung,
    -- Die juengste Angabe je Groesse, nur als Hinweis (ANN-349).
    'last_values', coalesce((
      select jsonb_object_agg(l.parameter_key, l.value)
      from (
        select distinct on (v.parameter_key) v.parameter_key, v.value
        from public.checkins c
        join public.checkin_values v on v.checkin_id = c.id
        where c.relationship_kind = v_zugang.relationship_kind
          and c.relationship_id = v_zugang.relationship_id
        order by v.parameter_key, c.answered_on desc, c.recorded_at desc
      ) l
    ), '{}'::jsonb),
    'history', (
      select coalesce(jsonb_agg(z - 'recorded_at'), '[]'::jsonb)
      from jsonb_array_elements(
        app.checkins_json(v_zugang.relationship_kind, v_zugang.relationship_id)) z
    ),
    -- OUT-004 (ANN-367): die eigenen Angaben nach den Einheiten, mit fester
    -- Schluesselliste - Tag, Plan, wer erfasst hat, Werte.
    'session_history', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'performed_on', z -> 'performed_on',
               'plan_title', z -> 'plan_title',
               'recorded_by_kind', z -> 'recorded_by_kind',
               'values', z -> 'values')), '[]'::jsonb)
      from jsonb_array_elements(
        app.checkin_sessions_json(v_zugang.relationship_kind, v_zugang.relationship_id)) z
    )
  );
end;
$$;

COMMENT ON FUNCTION public.platform_checkins(p_access_id uuid) IS 'TRK-003, OUT-004: Plattformprojektion Check-in (DSN-001 4.1, 5) - Takt und Fragen, ob heute faellig und ob dieser Zugang antworten darf, die letzte Angabe je Groesse als Hinweis, der eigene Verlauf ("Meine Angaben") und die eigenen Angaben nach den Einheiten, mit fester Schluesselliste (ADR-023 Punkt 22). Ueber eine Vertretung protokolliert (Punkt 24). Ohne Recht null.';

CREATE FUNCTION public.platform_consents(p_access_id uuid) RETURNS TABLE(purpose text, state text, occurred_on date, source text, can_grant boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang   public.platform_accesses%rowtype;
  v_erteilen boolean;
begin
  v_erteilen := app.platform_access_allows(p_access_id, 'consent');
  if not (v_erteilen or app.platform_own_access_after_reading(p_access_id)) then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'consents')
  );

  if v_zugang.relationship_kind = 'treatment' then
    return query
    select z.zweck,
           case
             when j.record_kind is null then 'open'
             when j.record_kind = 'consent_granted' then 'granted'
             when j.record_kind = 'consent_withdrawn' then 'withdrawn'
             else 'refused'
           end,
           j.occurred_on,
           j.source,
           v_erteilen
    from unnest(app.platform_consent_purposes('treatment')) with ordinality as z(zweck, nr)
    left join lateral (
      select r.record_kind, r.occurred_on, r.source
      from public.patient_privacy_records r
      where r.patient_id = v_zugang.relationship_id
        and r.organization_id = v_zugang.organization_id
        and r.purpose = z.zweck
      order by r.recorded_at desc, r.id desc
      limit 1
    ) j on true
    order by z.nr;
  else
    return query
    select z.zweck,
           case
             when j.record_kind is null then 'open'
             when j.record_kind = 'consent_granted' then 'granted'
             else 'withdrawn'
           end,
           j.occurred_on,
           j.source,
           v_erteilen
    from unnest(app.platform_consent_purposes('training')) with ordinality as z(zweck, nr)
    left join lateral (
      select r.record_kind, r.occurred_on, r.source
      from public.training_consent_records r
      where r.training_relationship_id = v_zugang.relationship_id
        and r.organization_id = v_zugang.organization_id
        and r.purpose = z.zweck
      order by r.recorded_at desc, r.id desc
      limit 1
    ) j on true
    order by z.nr;
  end if;
end;
$$;

COMMENT ON FUNCTION public.platform_consents(p_access_id uuid) IS 'POR-016/017: Plattformprojektion der eigenen Einwilligungen je Zweck (Stand aus der juengsten Zeile, Datum, Herkunft), Behandlung und Training. Recht consent (Person, rechtliche Vertretung), die Person auch nach der Lesefrist (ANN-261); nie die Begleitung.';

CREATE FUNCTION public.platform_context() RETURNS TABLE(access_id uuid, organization_name text, relationship_kind text, status text, readable boolean, read_until timestamp with time zone, access_kind text, represented_name text, own_name text, practice_phone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zeile record;
begin
  if auth.uid() is null
     or exists (select 1 from public.user_profiles up where up.id = auth.uid()) then
    return;
  end if;

  for v_zeile in
    select a.id, o.name, a.organization_id, a.relationship_kind, a.status, a.access_kind,
           exists (select 1 from app.platform_readable_access(a.id)) as lesbar,
           app.platform_access_ended_at(a.id) as bis,
           a.relationship_id, a.created_at
    from public.platform_accesses a
    join public.organizations o on o.id = a.organization_id
    where a.account_user_id = auth.uid()
      and a.status in ('active', 'locked')
    -- Die eigenen Bereiche zuerst, dann die Vertretungen.
    order by (a.access_kind <> 'self'), a.relationship_kind desc, a.created_at
  loop
    access_id := v_zeile.id;
    organization_name := v_zeile.name;
    relationship_kind := v_zeile.relationship_kind;
    status := v_zeile.status;
    readable := v_zeile.lesbar;
    read_until := v_zeile.bis;
    access_kind := v_zeile.access_kind;
    represented_name := null;
    own_name := app.platform_own_name(v_zeile.id);
    practice_phone := app.platform_practice_phone(v_zeile.organization_id);

    if v_zeile.access_kind <> 'self' and v_zeile.lesbar then
      select concat_ws(' ', p.given_name, p.family_name) into represented_name
      from app.platform_relationship(v_zeile.relationship_kind, v_zeile.relationship_id) r
      join public.persons p on p.id = r.person_id;

      perform app.log_platform_representation(
        v_zeile.id, 'platform_representation.read', jsonb_build_object('view', 'context')
      );
    end if;

    return next;
  end loop;
end;
$$;

COMMENT ON FUNCTION public.platform_context() IS 'POR-004/POR-006/DRP-N1/DRP-N2: Plattformprojektion fuer das Geruest (DSN-001 Abschnitt 3, D6): Praxisname und Rufnummer der Praxis (ANN-691), eigene Zugaenge und Vertretungen mit Art, an einem lesbaren Zugang der eigene Name (ANN-690). Bei einer lesbaren Vertretung der Name der vertretenen Person ("Sie handeln fuer ...", ADR-023 Punkt 14) und ein Auditeintrag (Punkt 24, ANN-209). Eigenes Lesen wird nicht protokolliert.';

CREATE FUNCTION public.platform_diary_reminders(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_profil public.nutrition_profiles%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'nutrition') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_profil := app.platform_nutrition_profile(p_access_id);
  if v_profil.id is null then
    return jsonb_build_object('reminders', null);
  end if;
  -- Kein Vertretungseintrag: die Wahl ist Sache des eigenen Zugangs (wie
  -- platform_notification_settings).
  return jsonb_build_object(
    'reminders', coalesce((
      select jsonb_agg(jsonb_build_object('meal', r.meal, 'time', to_char(r.remind_at, 'HH24:MI'))
                       order by r.remind_at, r.meal)
      from public.nutrition_diary_reminders r
      where r.access_id = p_access_id and r.profile_id = v_profil.id), '[]'::jsonb),
    'email', coalesce((
      select 'nutrition_diary_reminder' = any (s.email_kinds)
      from public.platform_notification_settings s where s.access_id = p_access_id), false),
    'push', coalesce((
      select 'nutrition_diary_reminder' = any (s.push_kinds)
      from public.platform_notification_settings s where s.access_id = p_access_id), false),
    'switched_off', exists (
      select 1 from public.notification_kind_switches k
      where k.organization_id = v_zugang.organization_id and k.kind = 'nutrition_diary_reminder'),
    'quiet_from', coalesce((select s.quiet_from from public.platform_notification_settings s
                            where s.access_id = p_access_id),
                           app.notification_rule('quiet_from')::smallint),
    'quiet_until', coalesce((select s.quiet_until from public.platform_notification_settings s
                             where s.access_id = p_access_id),
                            app.notification_rule('quiet_until')::smallint)
  );
end;
$$;

COMMENT ON FUNCTION public.platform_diary_reminders(p_access_id uuid) IS 'ERN-009 (ADR-027 Punkt 12): die eigenen Erinnerungen an das Tagebuch - je Mahlzeit eine Uhrzeit, ob per Mail und Push, ob die Praxis die Art abgeschaltet hat, die Ruhezeit. Recht nutrition (Person, rechtliche Vertretung; nie die Begleitung), nur für diesen Zugang. Ohne Recht null; ohne laufende Beratung reminders null.';

CREATE FUNCTION public.platform_exercise_plans(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_zone   text;
  v_heute  date;
  v_darf   boolean;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;
  v_heute := app.training_today(v_zugang.organization_id);
  v_darf := app.platform_access_allows(p_access_id, 'exercise')
            and app.platform_access_writable(p_access_id);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'exercise_plans')
  );

  return jsonb_build_object(
    'today', v_heute,
    'plans', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id,
        'service_area', p.service_area,
        'title', p.title,
        'status', p.status,
        'sessions_per_week', p.sessions_per_week,
        'assigned_on', (p.assigned_at at time zone v_zone)::date,
        'runs_from', p.runs_from,
        'runs_until', p.runs_until,
        'ended_on', (p.ended_at at time zone v_zone)::date,
        -- UEB-010: Darf dieser Zugang heute an diesem Plan ueben?
        'can_exercise', v_darf and p.status = 'assigned' and p.runs_from <= v_heute,
        'note_allowed', app.platform_exercise_note_allowed(
                          v_zugang.relationship_kind, v_zugang.relationship_id),
        -- Die heute begonnene, nicht beendete Einheit mit ihren Haken.
        'open_session', (
          select jsonb_build_object(
            'id', s.id,
            'sets', coalesce((
              select jsonb_agg(jsonb_build_object('item_id', x.item_id, 'set_number', x.set_number)
                               order by x.item_id, x.set_number)
              from public.exercise_plan_session_sets x where x.session_id = s.id
            ), '[]'::jsonb)
          )
          from public.exercise_plan_sessions s
          where s.plan_id = p.id and s.performed_on = v_heute and s.finished_at is null
          order by s.started_at desc
          limit 1
        ),
        -- Die Tage der letzten vier Wochen, an denen die Person geuebt hat.
        -- UEB-011: Tage waehlen geht schon vor dem Beginn der Laufzeit.
        'can_choose_days', v_darf and p.status = 'assigned',
        -- UEB-011: die gewaehlten Uebungstage, auch aus der vorigen Fassung.
        'weekdays', to_jsonb(coalesce(app.exercise_plan_weekdays(p.id), '{}'::smallint[])),
        'recent_sessions', coalesce((
          select jsonb_agg(jsonb_build_object('performed_on', s.performed_on,
                                              'finished', s.finished_at is not null)
                           order by s.performed_on desc, s.started_at desc)
          from public.exercise_plan_sessions s
          where s.plan_id = p.id and s.performed_on > v_heute - 28
        ), '[]'::jsonb),
        'items', coalesce((
          select jsonb_agg(app.platform_exercise_plan_item_json(i) order by i.position)
          from public.exercise_plan_items i where i.plan_id = p.id
        ), '[]'::jsonb)
      ) order by p.status, p.runs_from, p.id)
      from app.platform_visible_exercise_plans(v_zugang.relationship_kind, v_zugang.relationship_id) p
      where p.organization_id = v_zugang.organization_id
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.platform_exercise_plans(p_access_id uuid) IS 'UEB-009/UEB-010: Plattformprojektion "Uebungen" bzw. "Training" (DSN-001 4.1, 5): die laufenden Plaene des Verhaeltnisses hinter einem lesbaren Zugang, sonst der zuletzt beendete (ANN-304), als Schnappschuss in Alltagssprache mit fester Schluesselliste (ADR-023 Punkt 22); dazu, ob heute geuebt werden darf, die offene Einheit und die Tage der letzten vier Wochen (ANN-305). Ueber eine Vertretung protokolliert (Punkt 24). Ohne Recht null.';

CREATE FUNCTION public.platform_export(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_person  jsonb;
  v_ergebnis jsonb;
begin
  if not app.platform_access_allows(p_access_id, 'export') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  -- Die Stammdaten, die die Person der Praxis gegeben hat. Keine
  -- Einrichtung, keine Koordinaten (abgeleitet, nicht von ihr).
  if v_zugang.relationship_kind = 'treatment' then
    select jsonb_build_object(
             'given_name', pe.given_name,
             'family_name', pe.family_name,
             'date_of_birth', c.date_of_birth,
             'email', c.email,
             'phone', c.phone,
             'phone_mobile', c.phone_mobile,
             'phone_work', c.phone_work,
             'street', c.street,
             'house_number', c.house_number,
             'postal_code', c.postal_code,
             'city', c.city
           )
      into v_person
    from public.patients p
    join public.persons pe on pe.id = p.person_id
    left join public.patient_contact_details c on c.patient_id = p.id
    where p.id = v_zugang.relationship_id and p.organization_id = v_zugang.organization_id;
  else
    select jsonb_build_object(
             'given_name', pe.given_name,
             'family_name', pe.family_name,
             'date_of_birth', c.date_of_birth,
             'email', c.email,
             'phone', c.phone,
             'street', c.street,
             'house_number', c.house_number,
             'postal_code', c.postal_code,
             'city', c.city
           )
      into v_person
    from public.training_relationships t
    join public.persons pe on pe.id = t.person_id
    left join public.training_contact_details c on c.training_relationship_id = t.id
    where t.id = v_zugang.relationship_id and t.organization_id = v_zugang.organization_id;
  end if;

  v_ergebnis := jsonb_build_object(
    'format', 'plattform-export',
    'format_version', 1,
    'exported_at', now(),
    'organization', (select o.name from public.organizations o where o.id = v_zugang.organization_id),
    'relationship', v_zugang.relationship_kind,
    'exported_by', v_zugang.access_kind,
    'person', coalesce(v_person, '{}'::jsonb),
    'appointments', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
                     from public.platform_appointments(p_access_id) x),
    'appointment_requests', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
                             from public.platform_appointment_requests(p_access_id) x),
    'questionnaires', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
                       from public.platform_questionnaire(p_access_id) x),
    -- Rechnungen nur mit dem Recht billing - die Projektion prueft selbst.
    'invoices', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
                 from public.platform_invoices(p_access_id) x),
    -- Nur die Liste; jedes Dokument holt die Person einzeln (protokolliert).
    'documents', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
                  from public.platform_files(p_access_id) x),
    'consents', (select coalesce(jsonb_agg(to_jsonb(x) - 'can_grant'), '[]'::jsonb)
                 from public.platform_consents(p_access_id) x),
    -- ANG-008: die eigenen Trainingspakete, wie die Plattform sie zeigt
    -- (Recht billing; ohne Recht oder in der Behandlung leer).
    'training_packages', coalesce(public.platform_training_packages(p_access_id), '[]'::jsonb),
    -- KND-003: der im Konto geschlossene Trainingsvertrag (Recht billing;
    -- ohne Recht, in der Behandlung oder ohne Vertrag null).
    'training_contract', public.platform_training_contract(p_access_id),
    -- UEB-009 bis UEB-011: die eigenen Plaene mit Uebungstagen und den Tagen,
    -- an denen geuebt wurde - wie die Plattform sie zeigt (Zweitreview).
    'exercise_plans', coalesce(public.platform_exercise_plans(p_access_id) -> 'plans', '[]'::jsonb),
    -- KOM-004: die Nachrichten, wie die Plattform sie zeigt.
    'messages', coalesce(public.platform_messages(p_access_id) -> 'messages', '[]'::jsonb),
    -- TRK-003: die eigenen Check-ins mit Takt und Angaben, wie die Plattform
    -- sie zeigt.
    'checkins', (
      select jsonb_build_object('schedule', c -> 'schedule', 'history', c -> 'history')
      from (select public.platform_checkins(p_access_id) as c) x
    ),
    -- ALT-003: die eigenen Gewohnheiten mit Tagen, wie die Plattform sie zeigt.
    'habits', coalesce(public.platform_habits(p_access_id) -> 'habits', '[]'::jsonb),
    -- ERN-002 (ADR-027 Punkt 6): die eigene Ernaehrungsberatung an diesem
    -- Verhaeltnis, auch beendete, mit der Schluesselliste der Plattform -
    -- ohne Notizen der Beratung. Das Recht export traegt dieselben Zugaenge
    -- wie nutrition.
    'nutrition', (
      select coalesce(jsonb_agg(app.nutrition_platform_json(n.id) order by n.started_on), '[]'::jsonb)
      from public.nutrition_profiles n
      where n.organization_id = v_zugang.organization_id
        and n.relationship_kind = v_zugang.relationship_kind
        and n.relationship_id = v_zugang.relationship_id
    ),
    -- BEF-147: die Benachrichtigungen dieses Zugangs (ANN-669). Seit BEF-189 aus
    -- app.platform_notifications_json - dieselbe Liste wie im Export einer
    -- Begleitung.
    'notifications', app.platform_notifications_json(p_access_id)
  );

  -- ANN-265: ein Eintrag je Export, wie die Auskunft in der Praxis.
  insert into public.audit_log (
    organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
  )
  values (
    v_zugang.organization_id, auth.uid(),
    case when v_zugang.access_kind = 'self' then 'platform' else 'representative' end,
    'patient_record.exported',
    case v_zugang.relationship_kind when 'treatment' then 'patient' else 'training_relationship' end,
    v_zugang.relationship_id, 'success',
    jsonb_build_object('surface', 'platform', 'purpose', 'platform_export',
                       'platform_access_id', v_zugang.id, 'access_kind', v_zugang.access_kind)
  );

  return v_ergebnis;
end;
$$;

COMMENT ON FUNCTION public.platform_export(p_access_id uuid) IS 'POR-018 (IDEA-QSN-003): die eigenen Daten der Plattform als JSON - zusammengesetzt aus den Plattformprojektionen (feste Feldlisten, ADR-023 Punkt 22) und den eigenen Stammdaten. Recht export (Person, rechtliche Vertretung), nie Begleitung; protokolliert als patient_record.exported (ANN-265). Keine Akteneinsicht.';

CREATE FUNCTION public.platform_export_notifications(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang   public.platform_accesses%rowtype;
  v_ergebnis jsonb;
begin
  -- Nur der eigene, lesbare Zugang einer Begleitung - nicht über die Einsicht
  -- der Praxis (das Konto muss das der Begleitung sein), nicht nach der
  -- Lesefrist, nicht gesperrt oder entzogen.
  select a.* into v_zugang
  from public.platform_accesses a
  where a.id = p_access_id
    and a.access_kind = 'companion'
    and a.account_user_id = auth.uid()
    and exists (select 1 from app.platform_readable_access(a.id));
  if not found then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;

  -- Dasselbe Format wie der eigene Export, nur mit den Benachrichtigungen:
  -- keine Angaben zur Person, keine Termine, keine Nachrichten.
  v_ergebnis := jsonb_build_object(
    'format', 'plattform-export',
    'format_version', 1,
    'exported_at', now(),
    'organization', (select o.name from public.organizations o where o.id = v_zugang.organization_id),
    'relationship', v_zugang.relationship_kind,
    'exported_by', v_zugang.access_kind,
    -- Ohne die Tagebuch-Erinnerungen: Von der Ernaehrungsberatung sieht eine
    -- Begleitung nichts (ADR-027 Punkt 3) - auch nicht, wann sie lief.
    'notifications', app.platform_notifications_json(p_access_id) - 'diary_reminders'
  );

  -- Wie jeder Export (ADR-023 Punkt 24, ANN-265): ein Eintrag, keine neue
  -- Aktion; `part` sagt, dass nur die Benachrichtigungen gingen.
  insert into public.audit_log (
    organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
  )
  values (
    v_zugang.organization_id, auth.uid(), 'representative', 'patient_record.exported',
    case v_zugang.relationship_kind when 'treatment' then 'patient' else 'training_relationship' end,
    v_zugang.relationship_id, 'success',
    jsonb_build_object('surface', 'platform', 'purpose', 'platform_export',
                       'platform_access_id', v_zugang.id, 'access_kind', v_zugang.access_kind,
                       'part', 'notifications')
  );

  return v_ergebnis;
end;
$$;

COMMENT ON FUNCTION public.platform_export_notifications(p_access_id uuid) IS 'BEF-189 (ADR-023 Punkt 13, Fassung 6): Export einer Begleitung - nur ihre eigene Wahl zu Benachrichtigungen, nur am eigenen lesbaren Zugang, protokolliert als patient_record.exported.';

CREATE FUNCTION public.platform_files(p_access_id uuid) RETURNS TABLE(id uuid, document_type text, display_name text, mime_type text, byte_size bigint, released_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'treatment' then
    return;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'files')
  );

  return query
  select f.id, f.document_type, f.display_name, f.mime_type, f.byte_size, f.released_at
  from public.patient_files f
  where f.patient_id = v_zugang.relationship_id
    and f.organization_id = v_zugang.organization_id
    and f.status = 'ready'
    and f.released_at is not null
    and not app.is_patient_photo_type(f.document_type)
  order by f.released_at desc, f.id;
end;
$$;

COMMENT ON FUNCTION public.platform_files(p_access_id uuid) IS 'POR-014: Plattformprojektion "Dokumente" (DSN-001 D3): die einzeln freigegebenen Dateien der Akte, nie Fotos. Nur Behandlungszugang; Vertretung protokolliert (ADR-023 Punkt 24).';

CREATE FUNCTION public.platform_habits(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_einwilligung boolean;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_einwilligung := app.platform_exercise_note_allowed(
    v_zugang.relationship_kind, v_zugang.relationship_id);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'habits')
  );

  return jsonb_build_object(
    'today', app.training_today(v_zugang.organization_id),
    'mark_days', app.habit_mark_days(),
    -- Darf dieser Zugang vermerken? Recht, Lesefrist, Einwilligung.
    'can_mark', app.platform_access_allows(p_access_id, 'checkin')
                and app.platform_access_writable(p_access_id)
                and v_einwilligung,
    'consent_needed', not v_einwilligung,
    -- Feste Schluesselliste (ADR-023 Punkt 22): ohne Eintrage- und
    -- Pausenzeitpunkt; ended_at bleibt fuer den eigenen Export.
    'habits', (
      select coalesce(jsonb_agg(
        h - 'created_at' - 'paused_at'
      ), '[]'::jsonb)
      from jsonb_array_elements(
        app.habits_json(v_zugang.relationship_kind, v_zugang.relationship_id)) h
    )
  );
end;
$$;

COMMENT ON FUNCTION public.platform_habits(p_access_id uuid) IS 'ALT-003: Plattformprojektion Gewohnheiten - die eigenen Gewohnheiten mit den vermerkten Tagen, ob dieser Zugang vermerken darf und wie viele Tage zurueck (ANN-370). Feste Schluesselliste (ADR-023 Punkt 22), ueber eine Vertretung protokolliert (Punkt 24). Ohne Recht null.';

CREATE FUNCTION public.platform_invitation_failed(p_code_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_stand smallint;
begin
  update public.platform_access_invitations i
     set failed_attempts = least(i.failed_attempts + 1, 5),
         status = case when i.failed_attempts + 1 >= 5 then 'revoked' else i.status end,
         revoked_at = case when i.failed_attempts + 1 >= 5 then now() else i.revoked_at end
   where i.code_hash = lower(p_code_hash)
     and i.status = 'pending'
  returning i.failed_attempts into v_stand;
  return coalesce(v_stand < 5, false);
end;
$$;

CREATE FUNCTION public.platform_invitation_lookup(p_code_hash text) RETURNS TABLE(purpose text, account_user_id uuid, organization_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select i.purpose, a.account_user_id, o.name
  from public.platform_access_invitations i
  join public.platform_accesses a on a.id = i.platform_access_id
  join public.organizations o on o.id = i.organization_id
  where i.code_hash = lower(p_code_hash)
    and i.status = 'pending'
    and i.expires_at > now()
    and (
      (i.purpose = 'activate' and a.status = 'invited')
      or (i.purpose = 'reset' and a.status = 'active')
    )
$$;

COMMENT ON FUNCTION public.platform_invitation_lookup(p_code_hash text) IS 'POR-003: Zugangsdienst. Gilt der Code, und wofuer? Nur service_role. Unbekannt, abgelaufen und benutzt liefern gleich: keine Zeile.';

CREATE FUNCTION public.platform_invitation_mail(p_invitation_id uuid, p_code_hash text) RETURNS TABLE(email text, organization_name text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_inv    record;
  v_aktuell text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  select i.id, i.email, i.expires_at, i.status, i.channel, i.code_hash,
         a.id as access_id, a.relationship_kind, a.relationship_id
    into v_inv
  from public.platform_access_invitations i
  join public.platform_accesses a on a.id = i.platform_access_id
  where i.id = p_invitation_id and i.organization_id = v_org
  for update of i;

  if v_inv.id is null or not app.can_manage_platform_access(v_inv.relationship_kind) then
    perform app.record_denied_write(v_actor, 'platform_access.invitation_sent', 'not allowed to manage platform access');
    return;
  end if;

  if v_inv.channel <> 'email' or v_inv.status <> 'pending' or v_inv.expires_at <= now()
     or v_inv.code_hash is distinct from lower(p_code_hash) then
    raise exception 'invitation cannot be sent' using errcode = '22023';
  end if;

  select r.email into v_aktuell
  from app.platform_relationship(v_inv.relationship_kind, v_inv.relationship_id) r;
  if v_aktuell is distinct from v_inv.email then
    raise exception 'address changed since invitation' using errcode = '22023';
  end if;

  update public.platform_access_invitations set sent_at = now() where id = v_inv.id;

  -- Der Versand steht an der Einladung (sent_at), nicht im Log (LOG-EPIC-001).

  return query
  select v_inv.email, o.name, v_inv.expires_at
  from public.organizations o where o.id = v_org;
end;
$$;

CREATE FUNCTION public.platform_invoice(p_access_id uuid, p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_invoice record;
  v_storno  record;
  v_ersetzt text;
  v_korrektur text;
  v_bezahlt integer;
begin
  if not app.platform_access_allows(p_access_id, 'billing') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  select i.* into v_invoice
  from public.invoices i
  where i.id = p_invoice_id
    and i.organization_id = v_zugang.organization_id
    and i.status = 'issued'
    and (
      (v_zugang.relationship_kind = 'treatment' and i.patient_id = v_zugang.relationship_id)
      or
      (v_zugang.relationship_kind = 'training'
         and i.training_relationship_id = v_zugang.relationship_id)
    );
  if not found then
    return null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read',
    jsonb_build_object('view', 'invoice', 'invoice_id', p_invoice_id)
  );

  v_bezahlt := app.invoice_paid_cents(p_invoice_id);
  select c.cancellation_number, c.reason, c.cancelled_on into v_storno
  from public.invoice_cancellations c where c.invoice_id = p_invoice_id;
  select i.invoice_number into v_ersetzt
  from public.invoices i where i.id = v_invoice.replaces_invoice_id;
  select i.invoice_number into v_korrektur
  from public.invoices i
  where i.replaces_invoice_id = p_invoice_id and i.status = 'issued'
  order by i.created_at limit 1;

  -- Der Snapshot, wie die Praxis ihn druckt (ADR-009 Punkt 10) - die Person
  -- bekommt dasselbe Blatt. Steuernummer und Bankverbindung der Praxis
  -- gehoeren auf eine Rechnung und stehen deshalb mit drin.
  return jsonb_build_object(
    'id', v_invoice.id,
    'invoice_number', v_invoice.invoice_number,
    'issued_on', v_invoice.issued_on,
    'due_on', v_invoice.due_on,
    'paid_cents', v_bezahlt,
    'outstanding_cents', v_invoice.total_cents - v_bezahlt,
    'payment_state', app.invoice_payment_state(v_invoice.total_cents, v_bezahlt),
    'cancellation', case when v_storno is null then null else
      jsonb_build_object('cancellation_number', v_storno.cancellation_number,
                         'cancelled_on', v_storno.cancelled_on)
    end,
    'replaces_invoice_number', v_ersetzt,
    'correction_invoice_number', v_korrektur,
    'document', v_invoice.snapshot
  );
end;
$$;

COMMENT ON FUNCTION public.platform_invoice(p_access_id uuid, p_invoice_id uuid) IS 'POR-013: eine eigene ausgestellte Rechnung als Blatt - der Snapshot der Praxis (ADR-009 Punkt 10) mit Zahlungsstand und Storno-Kette. Nur ueber einen Zugang mit Recht billing; fremde und Entwuerfe: null.';

CREATE FUNCTION public.platform_invoices(p_access_id uuid) RETURNS TABLE(id uuid, invoice_number text, issued_on date, due_on date, total_cents integer, currency text, paid_cents integer, outstanding_cents integer, payment_state text, overdue boolean, cancelled boolean, cancelled_on date, recipient_kind text, recipient_name text, service_from date, service_to date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_zone   text;
  v_heute  date;
begin
  if not app.platform_access_allows(p_access_id, 'billing') then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;
  v_heute := (now() at time zone v_zone)::date;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'invoices')
  );

  return query
  select i.id,
         i.invoice_number,
         i.issued_on,
         i.due_on,
         i.total_cents,
         i.currency,
         bezahlt.cents,
         i.total_cents - bezahlt.cents,
         app.invoice_payment_state(i.total_cents, bezahlt.cents),
         (i.due_on < v_heute and bezahlt.cents < i.total_cents and c.id is null),
         c.id is not null,
         c.cancelled_on,
         i.snapshot -> 'recipient' ->> 'kind',
         i.snapshot -> 'recipient' ->> 'name',
         (i.snapshot -> 'service_period' ->> 'from')::date,
         (i.snapshot -> 'service_period' ->> 'to')::date
  from public.invoices i
  left join public.invoice_cancellations c on c.invoice_id = i.id
  cross join lateral (select app.invoice_paid_cents(i.id) as cents) bezahlt
  where i.organization_id = v_zugang.organization_id
    and i.status = 'issued'
    and (
      (v_zugang.relationship_kind = 'treatment' and i.patient_id = v_zugang.relationship_id)
      or
      (v_zugang.relationship_kind = 'training'
         and i.training_relationship_id = v_zugang.relationship_id)
    )
  order by i.issued_on desc, i.invoice_number desc;
end;
$$;

COMMENT ON FUNCTION public.platform_invoices(p_access_id uuid) IS 'POR-013: Plattformprojektion "Rechnungen" (DSN-001 D3, ANN-250): die ausgestellten Rechnungen des Verhaeltnisses mit Zahlungsstand, Storno-Vermerk und Adressat aus dem Snapshot; nie Entwuerfe. Recht billing (ABN-010); Vertretung protokolliert (ADR-023 Punkt 24).';

CREATE FUNCTION public.platform_messages(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_anhang  boolean;
  v_zone    text;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_anhang := v_zugang.access_kind in ('self', 'legal_representative');
  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'messages')
  );

  return jsonb_build_object(
    'response_workdays', (
      select o.message_response_workdays from public.organizations o
      where o.id = v_zugang.organization_id
    ),
    'can_write', app.platform_access_allows(p_access_id, 'message')
                 and app.platform_access_writable(p_access_id),
    'health_topics', app.platform_message_topic_allowed(
                       v_zugang.relationship_kind, v_zugang.relationship_id, 'complaint'),
    -- KOM-005: Ob angehaengt werden kann (Stufe, Art des Zugangs), und der
    -- Stand der Einwilligung - sie wird beim ersten Anhaengen angeboten.
    'can_attach', app.platform_access_allows(p_access_id, 'attach')
                  and app.platform_access_allows(p_access_id, 'message')
                  and app.platform_access_writable(p_access_id)
                  and app.message_attachments_offered(
                        v_zugang.relationship_kind, v_zugang.relationship_id),
    'attachment_consent', case
      when not v_anhang then null
      else case app.message_attachment_consent(v_zugang.relationship_kind, v_zugang.relationship_id)
        when 'consent_granted' then 'granted'
        when 'consent_withdrawn' then 'withdrawn'
        when 'consent_refused' then 'refused'
        else 'open'
      end
    end,
    'attachment_limit', app.message_attachment_limit(),
    'attachment_max_seconds', app.message_attachment_max_seconds(),
    'messages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id,
        'topic', m.topic,
        'reference_label', m.reference_label,
        'status', m.status,
        'due_on', m.due_on,
        'created_at', m.created_at,
        'last_entry_at', m.last_entry_at,
        'closed_at', m.closed_at,
        'closed_by_side', m.closed_by_side,
        -- Fuer die Grenze von drei (Punkt 59); die Begleitung erfaehrt nicht
        -- einmal, dass es Anhaenge gibt.
        'attachment_count', case when v_anhang then (
          select count(*)::integer from public.platform_message_attachments x
          where x.message_id = m.id
            and x.locked_at is null
            and x.created_at + app.retention_interval('rueckfrageanhang') > now()) end,
        'attachments', case when not v_anhang then '[]'::jsonb else coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', x.id,
            'media_kind', x.media_kind,
            'mime_type', x.mime_type,
            'duration_seconds', x.duration_seconds,
            'created_at', x.created_at,
            'delete_on', ((x.created_at + app.retention_interval('rueckfrageanhang'))
                            at time zone coalesce(v_zone, 'Europe/Berlin'))::date,
            'author', case
              when x.access_id = p_access_id then 'you'
              when x.author_kind = 'self' then 'person'
              else 'representative'
            end,
            'author_label', x.author_label,
            'server_verified', x.verified_at is not null,
            'malware_scanned', app.message_attachment_scan_required()
          ) order by x.created_at, x.id)
          from app.platform_visible_attachments(p_access_id) x
          where x.message_id = m.id
        ), '[]'::jsonb) end,
        'entries', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', e.id,
            'side', e.side,
            'body', e.body,
            'created_at', e.created_at,
            'author', case
              when e.side = 'practice' then 'practice'
              when e.access_id = p_access_id then 'you'
              when e.author_kind = 'self' then 'person'
              else 'representative'
            end,
            'author_label', case when e.side = 'person' then e.author_label end,
            'attachment_id', case when v_anhang then e.attachment_id end,
            'attachment_mark_seconds', case when v_anhang then e.attachment_mark_seconds end
          ) order by e.created_at, e.id)
          from public.platform_message_entries e
          where e.message_id = m.id
        ), '[]'::jsonb)
      ) order by (m.status = 'closed'), m.last_entry_at desc, m.id)
      from app.platform_visible_messages(p_access_id) m
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.platform_messages(p_access_id uuid) IS 'KOM-001/005: Plattformprojektion "Nachrichten" (DSN-001 4.1): die Vorgaenge des Verhaeltnisses mit Eintraegen und - fuer Person und rechtliche Vertretung - ihren Anhaengen mit Loeschdatum (ADR-017 Punkte 65, 67), feste Schluesselliste (ADR-023 Punkt 22), dazu Antwortfrist, Schreib- und Anhangrecht und Stand der Einwilligung. Ueber eine Vertretung protokolliert (Punkt 24). Ohne Recht null.';

CREATE FUNCTION public.platform_notification_settings(p_access_id uuid, p_endpoint text DEFAULT NULL::text) RETURNS TABLE(email_kinds text[], push_kinds text[], quiet_from smallint, quiet_until smallint, chosen_at timestamp with time zone, disabled_kinds text[], device_registered boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  return query
  select coalesce(s.email_kinds, '{}'::text[]),
         coalesce(s.push_kinds, '{}'::text[]),
         coalesce(s.quiet_from, app.notification_rule('quiet_from')::smallint),
         coalesce(s.quiet_until, app.notification_rule('quiet_until')::smallint),
         s.chosen_at,
         coalesce((select array_agg(k.kind order by k.kind)
                   from public.notification_kind_switches k
                   where k.organization_id = v_zugang.organization_id), '{}'::text[]),
         p_endpoint is not null and exists (
           select 1 from public.platform_push_subscriptions p
           where p.access_id = p_access_id and p.endpoint = p_endpoint)
  from (select 1) eins
  left join public.platform_notification_settings s on s.access_id = p_access_id;
end;
$$;

COMMENT ON FUNCTION public.platform_notification_settings(p_access_id uuid, p_endpoint text) IS 'KOM-009 (ADR-024 Punkt 15): die eigene Wahl zu Benachrichtigungen fuer einen lesbaren Zugang, die von der Praxis abgeschalteten Arten und ob dieses Geraet fuer Push registriert ist. Kein Vertretungseintrag: die Wahl ist Sache des eigenen Zugangs.';

CREATE FUNCTION public.platform_nutrition(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_profil public.nutrition_profiles%rowtype;
  v_einwilligung boolean;
  v_schreibbar boolean;
begin
  if not app.platform_access_allows(p_access_id, 'nutrition') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_profil := app.platform_nutrition_profile(p_access_id);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition')
  );

  if v_profil.id is null then
    return jsonb_build_object('profile', null);
  end if;
  v_einwilligung := app.nutrition_consent_granted(v_profil.id);
  v_schreibbar := app.platform_access_writable(p_access_id);

  return jsonb_build_object(
    'today', app.training_today(v_zugang.organization_id),
    'can_write', v_schreibbar and v_einwilligung,
    'can_grant', v_schreibbar and not v_einwilligung,
    'wording_version', app.platform_consent_wording_version(),
    'target_weight_floor_kg', app.nutrition_target_weight_floor(v_profil.height_cm),
    'profile', app.nutrition_platform_shape(app.nutrition_profile_base_json(v_profil.id))
  );
end;
$$;

COMMENT ON FUNCTION public.platform_nutrition(p_access_id uuid) IS 'ERN-002: Plattformprojektion Ernährung - die laufende Beratung am Verhältnis dieses Zugangs mit Zielwerten samt Rechenweg, Gewicht, Zielgewicht und seiner Untergrenze, Tagebuchschalter und Einwilligung. Recht nutrition (Person, rechtliche Vertretung; nie die Begleitung), feste Schlüsselliste ohne Notizen (ADR-023 Punkt 22), über eine Vertretung protokolliert (Punkt 24). Ohne Recht null; ohne laufendes Profil profile null.';

CREATE FUNCTION public.platform_nutrition_diary(p_access_id uuid, p_day date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_profil  public.nutrition_profiles%rowtype;
  v_heute   date;
  v_tag     date;
  v_ziele   jsonb;
begin
  if not app.platform_access_allows(p_access_id, 'nutrition') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_profil := app.platform_nutrition_profile(p_access_id);
  if v_profil.id is null then
    return jsonb_build_object('diary', null);
  end if;
  v_heute := app.training_today(v_zugang.organization_id);
  v_tag := coalesce(p_day, v_heute);
  if v_tag > v_heute or v_tag < v_profil.started_on then
    raise exception 'day outside the counselling' using errcode = '22023';
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );

  v_ziele := app.nutrition_profile_targets(v_profil.id);
  return jsonb_build_object(
    'today', v_heute,
    'started_on', v_profil.started_on,
    'enabled', v_profil.diary_enabled,
    'can_write', v_profil.diary_enabled and app.platform_access_writable(p_access_id)
                 and app.nutrition_consent_granted(v_profil.id),
    'can_delete', app.platform_access_writable(p_access_id),
    'glass_ml', app.nutrition_diary_rule('glass_ml'),
    -- ERN-008: die Einstellung der Person, zuletzt und Favoriten.
    'hide_numbers', v_profil.diary_hide_numbers,
    'recent', app.nutrition_diary_recent(v_profil),
    'favorites', app.nutrition_diary_favorites_json(v_profil),
    'targets', case when v_ziele ->> 'status' = 'ok' then jsonb_build_object(
      'energy_kcal', v_ziele -> 'energy' -> 'kcal',
      'protein_g', v_ziele -> 'protein' -> 'g',
      'fat_g', v_ziele -> 'fat' -> 'g',
      'carbohydrate_g', v_ziele -> 'carbohydrate' -> 'g',
      'water_ml', v_ziele -> 'water' -> 'ml') end,
    'day', app.nutrition_diary_day_json(v_profil.id, v_tag, false)
  );
end;
$$;

COMMENT ON FUNCTION public.platform_nutrition_diary(p_access_id uuid, p_day date) IS 'ERN-007 (ADR-027 Punkte 10 und 11): ein Tag des eigenen Ernährungstagebuchs - Mahlzeiten mit Einträgen und Summen, Wasser, die geltenden Zielwerte für "noch übrig". Recht nutrition (Person, rechtliche Vertretung; nie die Begleitung), nur an der laufenden Beratung dieses Zugangs; der Tag zwischen Beginn und heute (22023). Über eine Vertretung protokolliert. Ohne Recht null; ohne laufendes Profil diary null.';

CREATE FUNCTION public.platform_onboarding(p_access_id uuid) RETURNS TABLE(pending boolean, finished_at timestamp with time zone, skipped_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return;
  end if;
  -- Kein Vertretungseintrag: Der Stand des Einstiegs ist kein Inhalt der
  -- vertretenen Person, sondern einer des eigenen Zugangs.
  return query
  select a.onboarding_finished_at is null and a.onboarding_skipped_at is null,
         a.onboarding_finished_at,
         a.onboarding_skipped_at
  from public.platform_accesses a
  where a.id = p_access_id;
end;
$$;

COMMENT ON FUNCTION public.platform_onboarding(p_access_id uuid) IS 'POR-019: ob der Einstieg fuer diesen Zugang noch aussteht, wann er beendet bzw. von der Praxis uebersprungen wurde - ohne Namen. Nur ueber einen lesbaren eigenen Zugang.';

CREATE FUNCTION public.platform_preview(p_access_id uuid, p_function text, p_args jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid := auth.uid();
  v_zugang   public.platform_accesses%rowtype;
  v_rechnung uuid;
  v_ergebnis jsonb;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- ANN-525: Die Einsicht hat nur owner ("ueber meinen Zugang"). Abgewiesen
  -- wird wie jeder Lesepfad: access.denied mit HTTP 403; ohne Organisation
  -- (Plattformkonto, gesperrte Sitzung) mit 42501 und ohne Eintrag.
  if not app.has_any_role('owner') then
    perform app.record_denied_write(v_actor, 'platform_preview.read',
                                    'not allowed to preview the platform');
    return null;
  end if;

  -- Erst die Rolle, dann die Eingabe (ADR-023 Punkt 21): nur die feste Liste.
  if p_function is null or not (p_function = any (app.platform_preview_functions())) then
    perform app.record_denied_write(v_actor, 'platform_preview.read',
                                    'function not allowed in the preview');
    return null;
  end if;

  -- ANN-526: nur der eigene, aktive Zugang der Person in der eigenen
  -- Organisation. Fremd, eingeladen, gesperrt, entzogen und jede Vertretung
  -- antworten gleich.
  select a.* into v_zugang
  from public.platform_accesses a
  where a.id = p_access_id
    and a.organization_id = app.current_organization_id()
    and a.access_kind = 'self'
    and a.status = 'active'
    and a.account_user_id is not null;
  if not found then
    perform app.record_denied_write(v_actor, 'platform_preview.read',
                                    'platform access not available for the preview');
    return null;
  end if;

  -- Die Werte aus p_args typisiert und vor dem Protokoll; nur bekannte Namen.
  if p_args is not null and jsonb_typeof(p_args) <> 'object' then
    raise exception 'invalid preview arguments' using errcode = '22023';
  end if;
  if p_function = 'platform_invoice' then
    v_rechnung := (p_args ->> 'p_invoice_id')::uuid;
  end if;

  -- ADR-023 Punkt 24 letzter Satz: protokolliert wie ein Lesezugriff auf die
  -- Akte - dieselbe Aktion, hoechstens einmal je Person, Akte und Tag.
  perform app.log_record_access(
    v_zugang.organization_id, v_actor,
    case v_zugang.relationship_kind
      when 'treatment' then 'patient_record.viewed' else 'training_relationship.viewed' end,
    case v_zugang.relationship_kind
      when 'treatment' then 'patient' else 'training_relationship' end,
    v_zugang.relationship_id, 'user',
    jsonb_build_object('surface', 'web', 'view', 'platform_preview')
  );

  -- Ab hier nur lesend (wie app.platform_preview_grant), dann die Einsicht fuer
  -- genau diesen Zugang.
  perform pg_catalog.set_config('transaction_read_only', 'on', true);
  perform pg_catalog.set_config('app.platform_preview_access', v_zugang.id::text, true);

  if p_function = 'platform_context' then
    -- Dieselbe Form wie ein Eintrag aus public.platform_context(); dazu fuer
    -- die Leiste der Einsicht und den Rueckweg in die Praxis die Kennung des
    -- Verhaeltnisses und der Name der Person - beides sieht owner in der Akte.
    -- DRP-N1, DRP-N2: eigener Name und Rufnummer aus denselben Funktionen wie
    -- in public.platform_context().
    select jsonb_build_array(jsonb_build_object(
             'access_id', a.id,
             'organization_name', o.name,
             'relationship_kind', a.relationship_kind,
             'status', a.status,
             'readable', exists (select 1 from app.platform_readable_access(a.id)),
             'read_until', app.platform_access_ended_at(a.id),
             'access_kind', a.access_kind,
             'represented_name', null,
             'own_name', app.platform_own_name(a.id),
             'practice_phone', app.platform_practice_phone(a.organization_id),
             'relationship_id', a.relationship_id,
             'person_name', (
               select concat_ws(' ', p.given_name, p.family_name)
               from app.platform_relationship(a.relationship_kind, a.relationship_id) r
               join public.persons p on p.id = r.person_id
             )
           ))
      into v_ergebnis
    from public.platform_accesses a
    join public.organizations o on o.id = a.organization_id
    where a.id = v_zugang.id;
  elsif p_function = 'platform_onboarding' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_onboarding(v_zugang.id) t;
  elsif p_function = 'platform_appointments' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_appointments(v_zugang.id) t;
  elsif p_function = 'platform_appointment_requests' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_appointment_requests(v_zugang.id) t;
  elsif p_function = 'platform_questionnaire' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_questionnaire(v_zugang.id) t;
  elsif p_function = 'platform_invoices' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_invoices(v_zugang.id) t;
  elsif p_function = 'platform_invoice' then
    v_ergebnis := public.platform_invoice(v_zugang.id, v_rechnung);
  elsif p_function = 'platform_files' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_files(v_zugang.id) t;
  elsif p_function = 'platform_consents' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_consents(v_zugang.id) t;
  elsif p_function = 'platform_representatives' then
    select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_ergebnis
    from public.platform_representatives(v_zugang.id) t;
  elsif p_function = 'platform_aftercare' then
    v_ergebnis := public.platform_aftercare(v_zugang.id);
  elsif p_function = 'platform_training_offer' then
    v_ergebnis := public.platform_training_offer(v_zugang.id);
  elsif p_function = 'platform_training_contract' then
    v_ergebnis := public.platform_training_contract(v_zugang.id);
  elsif p_function = 'platform_training_packages' then
    v_ergebnis := public.platform_training_packages(v_zugang.id);
  elsif p_function = 'platform_training_offers' then
    v_ergebnis := public.platform_training_offers(v_zugang.id);
  elsif p_function = 'platform_exercise_plans' then
    v_ergebnis := public.platform_exercise_plans(v_zugang.id);
    -- ANN-307 (Jannes): Die Uebungstage waehlt die Person fuer sich; die
    -- Praxis liest sie nicht (public.exercise_plan_days ohne Policy), nur die
    -- Auskunft nach Art. 15 nennt sie. Auch die Einsicht bekommt je Plan eine
    -- leere Liste - die einzige Stelle, an der sie von der Sicht der Person
    -- abweicht.
    if jsonb_typeof(v_ergebnis -> 'plans') = 'array' then
      v_ergebnis := jsonb_set(v_ergebnis, '{plans}', coalesce((
        select jsonb_agg(p.plan || jsonb_build_object('weekdays', '[]'::jsonb) order by p.nr)
        from jsonb_array_elements(v_ergebnis -> 'plans') with ordinality as p(plan, nr)
      ), '[]'::jsonb));
    end if;
  elsif p_function = 'platform_messages' then
    v_ergebnis := public.platform_messages(v_zugang.id);
  elsif p_function = 'platform_checkins' then
    v_ergebnis := public.platform_checkins(v_zugang.id);
  elsif p_function = 'platform_habits' then
    v_ergebnis := public.platform_habits(v_zugang.id);
  else
    -- Die Liste und die Zweige laufen nie auseinander (Test); sonst lieber ab.
    raise exception 'preview function without branch: %', p_function using errcode = 'XX000';
  end if;

  perform pg_catalog.set_config('app.platform_preview_access', '', true);
  return v_ergebnis;
end;
$$;

COMMENT ON FUNCTION public.platform_preview(p_access_id uuid, p_function text, p_args jsonb) IS 'E-001 (DSN-001 D7, ADR-023 Fassung 5): Einsicht der Praxisinhaber:in in die Plattform einer Person, nur lesend. Nur owner, nur der eigene aktive Zugang der Person, feste Liste lesender Projektionen (app.platform_preview_functions), Ergebnis wie fuer die Person ausser den Uebungstagen (ANN-307: nur die Person); protokolliert als patient_record.viewed bzw. training_relationship.viewed (ADR-023 Punkt 24), die Transaktion ist danach nur lesend. Abgewiesen: access.denied mit HTTP 403.';

CREATE FUNCTION public.platform_questionnaire(p_access_id uuid) RETURNS TABLE(id uuid, instrument_id text, definition_version text, status text, recorded_on date, source text, answers jsonb, updated_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'treatment' then
    return;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'questionnaire')
  );

  return query
  select r.id, r.instrument_id, r.definition_version, r.status, r.recorded_on, r.source,
         case when r.source = 'platform' then r.answers end,
         r.updated_at, r.completed_at
  from public.patient_questionnaire_responses r
  where r.patient_id = v_zugang.relationship_id
    and r.organization_id = v_zugang.organization_id
    -- Ein Entwurf der Praxis ist deren Arbeit, keine Tatsache fuer die Person.
    and (r.source = 'platform' or r.status = 'abgeschlossen')
    -- Nur Boegen, die die Person ausfuellt (ANN-248); eine durch Korrektur
    -- ersetzte Erhebung gilt nicht mehr.
    and exists (
      select 1 from public.questionnaire_definitions d
      where d.instrument_id = r.instrument_id
        and d.definition -> 'meta' ->> 'ausgefuellt_von' = 'patient'
    )
    and not exists (
      select 1 from public.patient_questionnaire_responses n
      where n.supersedes_response_id = r.id and n.status = 'abgeschlossen'
    )
  order by r.instrument_id, (r.status = 'entwurf') desc, r.recorded_on desc, r.created_at desc;
end;
$$;

COMMENT ON FUNCTION public.platform_questionnaire(p_access_id uuid) IS 'POR-012: Plattformprojektion "Befundbogen": Stand der Boegen, die die Person ausfuellt (ANN-248) - eigene Entwuerfe und Abschluesse mit Antworten, in der Praxis erhobene nur als Tatsache. Nur Behandlungszugang; Vertretung protokolliert (ADR-023 Punkt 24).';

CREATE FUNCTION public.platform_representatives(p_access_id uuid) RETURNS TABLE(access_id uuid, access_kind text, legal_basis text, representative_name text, status text, since timestamp with time zone, can_end boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_eigen public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'manage_companions') then
    return;
  end if;
  select * into v_eigen from public.platform_accesses a where a.id = p_access_id;

  -- Ueber eine rechtliche Vertretung ist auch dieses Lesen protokolliert
  -- (Punkt 24, ANN-209); fuer die Person selbst nicht.
  perform app.log_platform_representation(
    v_eigen.id, 'platform_representation.read', jsonb_build_object('view', 'representatives')
  );

  return query
  select a.id, a.access_kind, a.legal_basis, a.representative_name, a.status,
         coalesce(a.activated_at, a.created_at),
         a.access_kind = 'companion'
  from public.platform_accesses a
  where a.organization_id = v_eigen.organization_id
    and a.relationship_kind = v_eigen.relationship_kind
    and a.relationship_id = v_eigen.relationship_id
    and a.id <> v_eigen.id
    and a.access_kind <> 'self'
    and a.status in ('invited', 'active', 'locked')
    -- Zweitreview: eine beendete Vertretung (Sorgerecht ab 18, Lesefrist)
    -- steht hier nicht mehr, auch solange der Loeschlauf sie noch fuehrt.
    and coalesce(app.platform_access_ended_at(a.id) > now(), true)
  order by a.access_kind, a.created_at;
end;
$$;

COMMENT ON FUNCTION public.platform_representatives(p_access_id uuid) IS 'POR-007: Plattformprojektion unter "Ich": wer fuer die Person Zugang hat (ADR-023 Punkt 14). Nur ueber einen eigenen Zugang oder eine rechtliche Vertretung (manage_companions), nie ueber eine Begleitung. Name und Art der Vertretung, kein Konto, kein Nachweis.';

CREATE FUNCTION public.platform_training_contract(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_heute  date;
begin
  if not app.platform_access_allows(p_access_id, 'billing') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'training' then
    return null;
  end if;
  if not exists (
    select 1 from public.training_contracts k
    where k.training_relationship_id = v_zugang.relationship_id
  ) then
    return null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'training_contract')
  );
  v_heute := app.training_today(v_zugang.organization_id);

  return (
    select jsonb_build_object(
      'id', k.id,
      'concluded_at', k.concluded_at,
      'label', k.package_label,
      'package_months', k.package_months,
      'price_cents', k.price_cents,
      'currency', k.currency,
      'tax_rate_permille', k.tax_rate_permille,
      'vat_included', k.vat_included,
      'starts_on', k.starts_on,
      'ends_on', k.ends_on,
      'offered_on', k.offered_on,
      'wording_version', k.wording_version,
      'early_start_requested', k.early_start_requested,
      'contact_released', k.contact_released,
      'health_consent_granted', k.health_consent_granted,
      'withdrawal_ends_on', k.withdrawal_ends_on,
      -- KND-004: der Widerruf und ob der Knopf da ist (Recht contract).
      'withdrawn_at', k.withdrawn_at,
      'can_withdraw', k.withdrawn_at is null and v_heute <= k.withdrawal_ends_on
                      and app.platform_access_allows(p_access_id, 'contract'),
      'released_titles', coalesce((
        select jsonb_agg(t.title order by t.position)
        from public.training_takeovers t where t.training_relationship_id = k.training_relationship_id
      ), '[]'::jsonb)
    )
    from public.training_contracts k
    where k.training_relationship_id = v_zugang.relationship_id
    order by k.concluded_at desc
    limit 1
  );
end;
$$;

COMMENT ON FUNCTION public.platform_training_contract(p_access_id uuid) IS 'KND-003: Plattformprojektion "Mein Trainingsvertrag" - der im Konto geschlossene Vertrag mit Paket, Preis, Zeitraum, Widerrufsfrist und Freigaben (Bestaetigung in Textform bis B13). Recht billing; Vertretung protokolliert.';

CREATE FUNCTION public.platform_training_offer(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_offer  public.training_offers%rowtype;
  v_heute  date;
  v_grund  text;
begin
  if not app.platform_access_allows(p_access_id, 'contract') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'treatment' then
    return null;
  end if;
  v_heute := app.training_today(v_zugang.organization_id);

  select * into v_offer
  from public.training_offers o
  where o.patient_id = v_zugang.relationship_id
    and o.organization_id = v_zugang.organization_id
    and app.training_offer_state(o, v_heute) = 'open'
  order by o.created_at desc
  limit 1;
  if not found then
    return null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'training_offer')
  );

  -- Zweitreview (4.8): Der Grund liest ueber die gemeinsame Identitaet
  -- (Training, andere Akten). Nur die Person selbst sieht ihn; einer
  -- Vertretung der Behandlung verriete er ein Trainingsverhaeltnis.
  if v_zugang.access_kind = 'self' then
    v_grund := app.training_offer_blocker(v_offer.id);
  end if;

  return (
    select jsonb_build_object(
      'id', v_offer.id,
      'label', c.label,
      'package_months', c.package_months,
      'price_cents', c.unit_price_cents,
      'currency', c.currency,
      'tax_rate_permille', c.tax_rate_permille,
      'vat_included', not coalesce(b.small_business, false),
      'starts_on', v_offer.starts_on,
      'ends_on', app.training_package_ends_on(v_offer.starts_on, c.package_months),
      'valid_until', v_offer.valid_until,
      'offered_on', (v_offer.created_at at time zone o.time_zone)::date,
      'handover_items', v_offer.handover_items,
      'contact', case when v_offer.offers_contact then (
        select jsonb_build_object(
                 'date_of_birth', d.date_of_birth,
                 'street', d.street,
                 'house_number', d.house_number,
                 'postal_code', d.postal_code,
                 'city', d.city,
                 'phone', coalesce(d.phone_mobile, d.phone),
                 'email', d.email
               )
        from public.patient_contact_details d
        where d.patient_id = v_offer.patient_id
      ) end,
      'early_start', v_offer.starts_on <= v_heute + app.training_withdrawal_days(),
      'withdrawal_days', app.training_withdrawal_days(),
      'wording_version', app.training_contract_wording_version(),
      'blocker', v_grund,
      'can_accept', v_zugang.access_kind = 'self' and v_grund is null,
      'practice', jsonb_build_object(
        'name', coalesce(b.legal_name, o.name),
        'street', b.street,
        'house_number', b.house_number,
        'postal_code', b.postal_code,
        'city', b.city,
        'phone', b.phone,
        'email', b.email
      )
    )
    from public.service_catalog_items c
    join public.organizations o on o.id = v_offer.organization_id
    left join public.practice_billing_profiles b on b.organization_id = v_offer.organization_id
    where c.id = v_offer.catalog_item_id
  );
end;
$$;

COMMENT ON FUNCTION public.platform_training_offer(p_access_id uuid) IS 'KND-003: Plattformprojektion "Angebot der Praxis" - das offene Trainingsangebot der Akte hinter dem Zugang mit Paket, Preis, Zeitraum, Uebergabeangaben, angebotenen Kontaktdaten, Praxisanschrift fuer die Belehrung und warum es (noch) nicht angenommen werden kann. Recht contract; annehmen nur der eigene Zugang (ANN-289). Vertretung protokolliert.';

CREATE FUNCTION public.platform_training_offers(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_heute  date;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'training' then
    return null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'training_offers')
  );

  v_heute := app.training_today(v_zugang.organization_id);

  return jsonb_build_object(
    'vat_included', not coalesce((
      select b.small_business from public.practice_billing_profiles b
      where b.organization_id = v_zugang.organization_id
    ), false),
    'offers', coalesce((
      select jsonb_agg(jsonb_build_object(
               'code', c.code,
               'label', c.label,
               'package_months', c.package_months,
               'price_cents', c.unit_price_cents,
               'currency', c.currency,
               'tax_rate_permille', c.tax_rate_permille
             ) order by c.sort_order)
      from public.service_catalog_items c
      where c.catalog_version_id = app.active_service_catalog_version(v_zugang.organization_id, v_heute)
        and c.item_kind = 'training_package'
    ), '[]'::jsonb)
  );
end;
$$;

COMMENT ON FUNCTION public.platform_training_offers(p_access_id uuid) IS 'ANG-008 (IDEA-ANG-004, ANN-281): Plattformprojektion "Angebote" - die Trainingspakete der heute geltenden Preisliste mit Laufzeit, Gesamtpreis und Steuersatz. Nur Zugaenge zum Training mit Recht read; Vertretung protokolliert.';

CREATE FUNCTION public.platform_training_packages(p_access_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_heute  date;
begin
  if not app.platform_access_allows(p_access_id, 'billing') then
    return null;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'training' then
    return null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'training_packages')
  );

  v_heute := app.training_today(v_zugang.organization_id);

  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'label', c.label,
             'package_months', c.package_months,
             'price_cents', c.unit_price_cents,
             'currency', c.currency,
             'starts_on', k.starts_on,
             'ends_on', k.ends_on,
             'state', case
               when v_heute < k.starts_on then 'planned'
               when v_heute <= k.ends_on then 'running'
               else 'ended'
             end
           ) order by k.starts_on desc)
    from public.training_packages k
    join public.service_catalog_items c on c.id = k.catalog_item_id
    where k.training_relationship_id = v_zugang.relationship_id
      and k.organization_id = v_zugang.organization_id
  ), '[]'::jsonb);
end;
$$;

COMMENT ON FUNCTION public.platform_training_packages(p_access_id uuid) IS 'ANG-008: Plattformprojektion "Mein Paket" - die Trainingspakete des Verhaeltnisses hinter dem Zugang mit Zeitraum, Preis und Stand. Recht billing; Vertretung protokolliert.';

CREATE FUNCTION public.post_team_message(p_channel uuid, p_parent uuid, p_body text, p_mentions uuid[] DEFAULT '{}'::uuid[], p_id uuid DEFAULT NULL::uuid, p_mention_all boolean DEFAULT false, p_also_in_channel boolean DEFAULT false, p_send_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_attachments uuid[] DEFAULT '{}'::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org       uuid;
  v_staff     uuid;
  v_text      text;
  v_anhaenge  uuid[] := coalesce(p_attachments, '{}'::uuid[]);
  v_gebunden  integer;
  v_channel   public.team_channels%rowtype;
  v_vorhanden public.team_messages%rowtype;
  v_id        uuid;
  v_neu       uuid;
  v_zeit      timestamptz;
  v_seit      timestamptz;
  v_erwaehnt  uuid[];
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if cardinality(v_anhaenge) > app.team_attachment_limit() then
    raise exception 'too many attachments' using errcode = '22023';
  end if;
  if array_position(v_anhaenge, null) is not null
     or cardinality(v_anhaenge) <> (select count(distinct x) from unnest(v_anhaenge) x) then
    raise exception 'invalid attachments' using errcode = '22023';
  end if;
  v_text := app.team_message_body(p_body, cardinality(v_anhaenge) > 0);

  if p_id is null then
    v_id := extensions.gen_random_uuid();
  else
    -- Eine Zeile mit dieser Kennung kann nur die eigene sein - als Nachricht
    -- oder als Anker, nachdem die Person sie mit Antworten gelöscht hat. Kam
    -- sie schon an, hängen auch ihre Anhänge schon daran.
    v_id := app.team_message_key(v_staff, p_id);
    select * into v_vorhanden from public.team_messages where id = v_id;
    if v_vorhanden.id is not null then
      if v_vorhanden.channel_id = p_channel and v_vorhanden.parent_id is not distinct from p_parent then
        return v_id;
      end if;
      raise exception 'message id is already used' using errcode = '22023';
    end if;
    -- Eine Wiederholung nach dem eigenen Löschen bringt nichts zurück.
    if exists (select 1 from public.deletion_journal j
               where j.organization_id = v_org and j.target_id = v_id
                 and j.target_table in ('team_messages', 'team_message_contents')) then
      return v_id;
    end if;
  end if;

  -- Prüfen und Einfügen sehen denselben Kanal: Herausnehmen, Verlassen und
  -- Archivieren sperren ihn zum Ändern und warten so auf das Senden - oder
  -- umgekehrt (Zweitreview TEAM-002, Runde 3, Befund 2).
  perform 1 from public.team_channels c where c.id = p_channel and c.organization_id = v_org for share;
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  select * into v_channel from public.team_channels where id = p_channel;
  if v_channel.archived_at is not null then
    raise exception 'team channel is archived' using errcode = '22023';
  end if;
  -- In eine Direktnachricht nur, solange die andere Person teilnehmen kann; in
  -- eine Gruppennachricht, solange es noch jemand kann.
  if v_channel.kind in ('direct', 'group') and not exists (
    select 1 from public.team_channel_members m
    where m.channel_id = p_channel and m.staff_member_id <> v_staff
      and app.teamchat_participant(v_org, m.staff_member_id)
  ) then
    raise exception 'team chat partner is not available' using errcode = '22023';
  end if;
  if p_parent is not null and not exists (
    select 1 from public.team_messages m
    where m.id = p_parent and m.channel_id = p_channel and m.parent_id is null
      and m.created_at <= now()
  ) then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  if coalesce(p_also_in_channel, false) and p_parent is null then
    raise exception 'only a reply can also go to the conversation' using errcode = '22023';
  end if;
  if p_send_at is not null and (
       p_parent is not null
       or p_send_at < now() + interval '1 minute'
       or p_send_at > now() + interval '30 days') then
    raise exception 'send time must be one minute to 30 days ahead' using errcode = '22023';
  end if;
  if p_send_at is not null and cardinality(v_anhaenge) > 0 then
    raise exception 'a scheduled message has no attachments' using errcode = '22023';
  end if;

  insert into public.team_messages
    (id, organization_id, channel_id, parent_id, author_staff_member_id, body, also_in_channel, created_at)
  values (v_id, v_org, p_channel, p_parent, v_staff, v_text,
          coalesce(p_also_in_channel, false), coalesce(p_send_at, now()))
  on conflict (id) do nothing
  returning id, created_at into v_neu, v_zeit;

  if v_neu is null then
    -- Gleichzeitig mit derselben Kennung: Die andere Anfrage hat angelegt.
    select * into v_vorhanden from public.team_messages where id = v_id;
    if v_vorhanden.channel_id = p_channel and v_vorhanden.parent_id is not distinct from p_parent then
      return v_id;
    end if;
    raise exception 'message id is already used' using errcode = '22023';
  end if;

  -- Anhänge binden: gesperrt in fester Reihenfolge, damit zwei Sendungen mit
  -- denselben Anhängen nicht ineinander warten; nur eine gewinnt.
  if cardinality(v_anhaenge) > 0 then
    perform 1 from public.team_message_attachments a
     where a.id = any (v_anhaenge)
     order by a.id
     for update;
    update public.team_message_attachments a
       set message_id = v_id,
           attached_at = now(),
           position = array_position(v_anhaenge, a.id)
     where a.id = any (v_anhaenge)
       and a.organization_id = v_org
       and a.channel_id = p_channel
       and a.staff_member_id = v_staff
       and a.created_by = auth.uid()
       and a.message_id is null
       and a.status = 'ready'
       and a.created_at > now() - interval '24 hours';
    get diagnostics v_gebunden = row_count;
    if v_gebunden <> cardinality(v_anhaenge) then
      raise exception 'team attachment not found' using errcode = 'P0002';
    end if;
  end if;

  -- @alle: alle, die das Gespräch lesen; set_team_mentions prüft jede Person.
  v_erwaehnt := coalesce(p_mentions, '{}'::uuid[]);
  if coalesce(p_mention_all, false) then
    v_erwaehnt := v_erwaehnt || array(select l.staff_member_id
                                      from public.list_team_channel_members(p_channel) l
                                      where l.active);
  end if;
  perform app.set_team_mentions(v_id, v_erwaehnt);

  -- Senden zieht keinen Lesestand vor: Eigenes ist nie neu, und was andere
  -- inzwischen schrieben, gilt erst als gelesen, wenn die Ansicht es gezeigt
  -- hat (ANN-640; Zweitreview TEAM-002, Runde 3, Befund 5).
  if p_parent is null then
    -- Wer beginnt oder erwähnt ist, folgt dem Thread ab hier.
    perform app.team_follow_thread(v_id, v_staff, v_zeit);
    perform app.team_follow_thread(v_id, mm.staff_member_id, v_zeit)
    from public.team_message_mentions mm where mm.message_id = v_id;
  else
    v_seit := (select max(m.created_at) from public.team_messages m
               where (m.id = p_parent or m.parent_id = p_parent) and m.created_at < v_zeit);
    perform app.team_follow_thread(p_parent, v_staff, v_zeit);
    -- Erwähnte folgen; was vor der Erwähnung kam, gilt für sie als gesehen.
    perform app.team_follow_thread(p_parent, mm.staff_member_id, v_seit)
    from public.team_message_mentions mm where mm.message_id = v_id;
    -- In Direkt- und Gruppennachrichten folgen alle jedem Thread (wie Slack).
    if v_channel.kind in ('direct', 'group') then
      perform app.team_follow_thread(p_parent, m.staff_member_id, v_seit)
      from public.team_channel_members m
      where m.channel_id = p_channel and m.staff_member_id <> v_staff;
    end if;
  end if;
  return v_id;
end;
$$;

CREATE FUNCTION public.prepare_fleet_photo_upload(p_spot_id uuid, p_checkup_id uuid, p_byte_size bigint, p_checksum_sha256 text, p_side text DEFAULT NULL::text) RETURNS TABLE(photo_id uuid, bucket_id text, object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org     uuid;
  v_bike    uuid;
  v_von     uuid;
  v_am      timestamptz;
  v_offen   boolean := true;
  v_id      uuid;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  if (p_spot_id is null) = (p_checkup_id is null) then
    raise exception 'photo needs exactly one reference' using errcode = '22023';
  end if;
  if p_side is not null and (p_checkup_id is null or not (p_side = any (app.fleet_photo_sides()))) then
    raise exception 'unknown side' using errcode = '22023';
  end if;

  -- Der Bezug ist gesperrt, damit die Zahl auch gleichzeitig stimmt.
  if p_spot_id is not null then
    select s.bike_id, s.created_by, s.created_at, s.resolved_at is null
      into v_bike, v_von, v_am, v_offen
    from public.fleet_spots s
    where s.id = p_spot_id and s.organization_id = v_org
    for update;
  else
    select c.bike_id, c.checked_by, c.checked_at
      into v_bike, v_von, v_am
    from public.fleet_checkups c
    where c.id = p_checkup_id and c.organization_id = v_org
    for update;
  end if;
  -- Fremd, alt, erledigt, an einem ausgemusterten Rad oder nicht vorhanden
  -- sehen gleich aus.
  if v_bike is null or v_von <> auth.uid() or v_am <= now() - interval '24 hours'
     or not v_offen
     or not exists (
       select 1 from public.fleet_bikes b where b.id = v_bike and b.archived_at is null
     ) then
    raise exception 'reference not found' using errcode = 'P0002';
  end if;

  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > app.patient_file_max_bytes() then
    raise exception 'file too large or empty' using errcode = '22023';
  end if;
  if p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid checksum' using errcode = '22023';
  end if;
  if p_side is not null then
    -- Ein abgebrochener Versuch derselben Seite (eigene, unbestaetigte Zeile
    -- wie in discard_fleet_photo_upload) weicht dem neuen: Sonst hielte er
    -- die Seite, bis der Aufraeumlauf ihn nach 24 Stunden verwirft - dann ist
    -- das Fenster fuer Fotos zum Check-Up schon zu. Der Trigger schreibt den
    -- Loeschauftrag, falls doch schon ein Objekt liegt.
    delete from public.fleet_photos f
     where f.checkup_id = p_checkup_id and f.side = p_side
       and f.organization_id = v_org
       and f.created_by = auth.uid()
       and f.status = 'pending'
       and f.confirmation_requested_at is null;
    if exists (
      select 1 from public.fleet_photos f
      where f.checkup_id = p_checkup_id and f.side = p_side
    ) then
      raise exception 'side already has a photo' using errcode = '23505';
    end if;
  elsif (select count(*) from public.fleet_photos f
          where f.spot_id is not distinct from p_spot_id
            and f.checkup_id is not distinct from p_checkup_id
            and f.side is null)
        >= app.fleet_photo_limit() then
    raise exception 'too many photos' using errcode = '23514';
  end if;

  insert into public.fleet_photos (
    organization_id, bike_id, spot_id, checkup_id, side, mime_type, byte_size, checksum_sha256,
    created_by
  )
  values (
    v_org, v_bike, p_spot_id, p_checkup_id, p_side, 'image/jpeg', p_byte_size, p_checksum_sha256,
    auth.uid()
  )
  returning id into v_id;

  return query
    select f.id, app.fleet_photo_bucket(), f.object_key
    from public.fleet_photos f where f.id = v_id;
end;
$_$;

COMMENT ON FUNCTION public.prepare_fleet_photo_upload(p_spot_id uuid, p_checkup_id uuid, p_byte_size bigint, p_checksum_sha256 text, p_side text) IS 'FLT-002, FLT-007 (ANN-552, ANN-568, ADR-017 Punkt 7a): Phase (a) - Foto zur eigenen Stelle oder zum eigenen Check-Up, binnen 24 Stunden, hoechstens vier weitere je Bezug und je Seite eines (p_side, nur am Check-Up), nur JPEG; liefert den Objektschluessel, bevor Bytes fliessen.';

CREATE FUNCTION public.prepare_message_attachment_upload(p_access_id uuid, p_message_id uuid, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text, p_duration_seconds integer) RETURNS TABLE(attachment_id uuid, bucket_id text, object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_vorgang public.platform_messages%rowtype;
  v_art     text;
  v_id      uuid;
begin
  v_zugang := app.assert_platform_message(p_access_id);
  if not app.platform_access_allows(p_access_id, 'attach') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  v_vorgang := app.platform_open_message(p_access_id, p_message_id);

  if not app.message_attachments_offered(v_vorgang.relationship_kind, v_vorgang.relationship_id) then
    raise exception 'attachments not offered' using errcode = '42501';
  end if;
  if app.message_attachment_consent(v_vorgang.relationship_kind, v_vorgang.relationship_id)
     is distinct from 'consent_granted' then
    raise exception 'no consent to attachments' using errcode = '42501';
  end if;
  -- Wie beim Nachtrag (ANN-311): im Training ist ein Bild zur Uebung oder zu
  -- Beschwerden eine Angabe zur Gesundheit.
  if not app.platform_message_topic_allowed(
           v_vorgang.relationship_kind, v_vorgang.relationship_id, v_vorgang.topic) then
    raise exception 'topic needs consent' using errcode = '42501';
  end if;

  if p_mime_type = 'image/jpeg' then
    v_art := 'photo';
    if p_duration_seconds is not null then
      raise exception 'a photo has no duration' using errcode = '22023';
    end if;
  elsif p_mime_type in ('video/webm', 'video/mp4') then
    v_art := 'video';
    if p_duration_seconds is null
       or p_duration_seconds not between 1 and app.message_attachment_max_seconds() then
      raise exception 'video too long or empty' using errcode = '22023';
    end if;
  else
    raise exception 'unsupported media type' using errcode = '22023';
  end if;
  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > app.patient_file_max_bytes() then
    raise exception 'file too large or empty' using errcode = '22023';
  end if;
  if p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid checksum' using errcode = '22023';
  end if;

  -- Hoechstens drei je Vorgang, auch gleichzeitig: der Vorgang ist gesperrt.
  perform 1 from public.platform_messages m where m.id = v_vorgang.id for update;
  -- Zweitreview H4: gezaehlt wird, was einen Platz belegt - unterwegs oder
  -- sichtbar; gesperrte und abgelaufene nicht.
  if (select count(*) from public.platform_message_attachments x
       where x.message_id = v_vorgang.id
         and x.locked_at is null
         and x.created_at + app.retention_interval('rueckfrageanhang') > now())
     >= app.message_attachment_limit() then
    raise exception 'too many attachments' using errcode = '23514';
  end if;

  insert into public.platform_message_attachments (
    organization_id, message_id, media_kind, mime_type, byte_size, duration_seconds,
    checksum_sha256, access_id, author_kind, author_label, created_by
  )
  values (
    v_vorgang.organization_id, v_vorgang.id, v_art, p_mime_type, p_byte_size, p_duration_seconds,
    p_checksum_sha256, v_zugang.id, v_zugang.access_kind,
    case when v_zugang.access_kind <> 'self' then v_zugang.representative_name end, auth.uid()
  )
  returning id into v_id;

  return query
    select x.id, app.message_attachment_bucket(), x.object_key
    from public.platform_message_attachments x where x.id = v_id;
end;
$_$;

COMMENT ON FUNCTION public.prepare_message_attachment_upload(p_access_id uuid, p_message_id uuid, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text, p_duration_seconds integer) IS 'KOM-005 (ADR-017 Punkte 7a, 59 bis 63): Phase (a) - prueft Zugang, Stufe, Einwilligung, Zahl und Format, bevor Bytes fliessen, und liefert den Objektschluessel.';

CREATE FUNCTION public.prepare_patient_file_upload(p_patient_id uuid, p_treatment_basis_id uuid, p_document_type text, p_display_name text, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text) RETURNS TABLE(file_id uuid, bucket_id text, object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  v_org := app.patient_file_organization(p_patient_id);
  if v_org is null then
    raise exception 'patient not accessible' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.patient_file_document_types t where t.key = p_document_type
  ) then
    raise exception 'unknown document type %', p_document_type using errcode = '22023';
  end if;

  -- Die Grundlage muss zu genau dieser Patientin in dieser Organisation
  -- gehoeren. Sonst haenge der Scan an einem fremden Auftrag - und traege
  -- dessen Frist.
  if p_treatment_basis_id is not null and not exists (
    select 1
    from public.treatment_bases pr
    where pr.id = p_treatment_basis_id
      and pr.patient_id = p_patient_id
      and pr.organization_id = v_org
  ) then
    raise exception 'treatment basis not accessible' using errcode = '42501';
  end if;

  -- ANN-316 (ADR-017 Fassung 4 Punkt 57, BEF-135): Eine neue Arbeitshilfe
  -- entsteht nicht mehr. Was schon liegt, bleibt bis Frist oder Widerruf.
  if p_document_type = 'patientenfoto' then
    raise exception 'photo aids are no longer taken' using errcode = '22023';
  end if;

  if not app.can_write_patient_file(p_document_type, p_treatment_basis_id) then
    raise exception 'not allowed to upload this document type' using errcode = '42501';
  end if;

  -- Fotos der Person (ADR-017 Punkte 32, 36 und 45): nur an der Patient:in,
  -- nur JPEG. Die Einwilligung verlangt nur die Arbeitshilfe; das
  -- Dokumentationsfoto stuetzt sich auf die Behandlung (Punkt 45, ANN-126).
  -- Geprueft vor jedem Byte.
  if app.is_patient_photo_type(p_document_type) then
    if p_treatment_basis_id is not null then
      raise exception 'a patient photo belongs to the patient' using errcode = '22023';
    end if;
    if p_mime_type is distinct from 'image/jpeg' then
      raise exception 'unsupported media type' using errcode = '22023';
    end if;
    -- Seit ABN-032 unerreichbar (Abweisung oben); bleibt fuer die Ruecknahme
    -- nach ANN-316.
    if p_document_type = 'patientenfoto'
       and not app.patient_photo_accessible(p_patient_id, null) then
      raise exception 'no consent to patient photos' using errcode = '42501';
    end if;
  end if;

  -- Allowlist und Groesse, erste von zwei Durchsetzungen (Punkt 18). Die
  -- zweite steht am Bucket; die dritte prueft bei der Bestaetigung gegen das,
  -- was tatsaechlich abgelegt wurde.
  if p_mime_type is null or p_mime_type not in ('application/pdf', 'image/jpeg', 'image/png') then
    raise exception 'unsupported media type' using errcode = '22023';
  end if;

  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > app.patient_file_max_bytes() then
    raise exception 'file too large or empty' using errcode = '22023';
  end if;

  if p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid checksum' using errcode = '22023';
  end if;

  if p_display_name is null or length(btrim(p_display_name)) not between 1 and 200 then
    raise exception 'invalid display name' using errcode = '22023';
  end if;

  insert into public.patient_files (
    organization_id, patient_id, treatment_basis_id, document_type,
    display_name, mime_type, byte_size, checksum_sha256, uploaded_by
  )
  values (
    v_org, p_patient_id, p_treatment_basis_id, p_document_type,
    btrim(p_display_name), p_mime_type, p_byte_size, p_checksum_sha256, v_actor
  )
  returning id into v_id;

  return query
    select f.id, app.patient_file_bucket_for(f.document_type), f.object_key
    from public.patient_files f
    where f.id = v_id;
end;
$_$;

COMMENT ON FUNCTION public.prepare_patient_file_upload(p_patient_id uuid, p_treatment_basis_id uuid, p_document_type text, p_display_name text, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text) IS 'Phase (a) des zweiphasigen Uploads (ADR-017 Punkt 7a): prueft die Berechtigung, bevor Bytes fliessen, und liefert den Objektschluessel.';

CREATE FUNCTION public.prepare_reimbursement_receipt_upload(p_mime_type text, p_byte_size bigint, p_checksum_sha256 text) RETURNS TABLE(receipt_id uuid, bucket_id text, object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org   uuid;
  v_staff uuid;
  v_id    uuid;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = 'P0002';
  end if;
  -- Die Person ist gesperrt, damit die Zahl auch gleichzeitig stimmt.
  perform 1 from public.staff_members s where s.id = v_staff for no key update;

  if p_mime_type is null or p_mime_type not in ('image/jpeg', 'image/png', 'application/pdf') then
    raise exception 'unsupported media type' using errcode = '22023';
  end if;
  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > app.patient_file_max_bytes() then
    raise exception 'file too large or empty' using errcode = '22023';
  end if;
  if p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid checksum' using errcode = '22023';
  end if;
  if (select count(*) from public.staff_reimbursement_receipts b
       where b.staff_member_id = v_staff and b.reimbursement_id is null
         and b.created_at > now() - interval '24 hours')
     >= app.reimbursement_receipt_limit() then
    raise exception 'too many receipts' using errcode = '23514';
  end if;

  insert into public.staff_reimbursement_receipts (
    organization_id, staff_member_id, mime_type, byte_size, checksum_sha256, created_by
  )
  values (v_org, v_staff, p_mime_type, p_byte_size, p_checksum_sha256, auth.uid())
  returning id into v_id;

  return query
    select b.id, app.reimbursement_receipt_bucket(), b.object_key
    from public.staff_reimbursement_receipts b where b.id = v_id;
end;
$_$;

COMMENT ON FUNCTION public.prepare_reimbursement_receipt_upload(p_mime_type text, p_byte_size bigint, p_checksum_sha256 text) IS 'ERS-001 (ANN-600, ADR-017 Punkt 7a): Phase (a) - ein Beleg der eigenen Person, JPEG, PNG oder PDF bis 10 MB, höchstens zehn unzugeordnet; liefert den Objektschlüssel, bevor Bytes fließen.';

CREATE FUNCTION public.prepare_team_attachment_upload(p_channel uuid, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text, p_name text, p_duration_seconds integer DEFAULT NULL::integer) RETURNS TABLE(attachment_id uuid, bucket_id text, object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_org   uuid;
  v_staff uuid;
  v_name  text := btrim(coalesce(p_name, ''));
  v_ton   boolean;
  v_id    uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  -- Die Person ist gesperrt, damit die Zahl auch gleichzeitig stimmt.
  perform 1 from public.staff_members s where s.id = v_staff for no key update;

  perform 1 from public.team_channels c where c.id = p_channel and c.organization_id = v_org for share;
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.team_channels c where c.id = p_channel and c.archived_at is not null) then
    raise exception 'team channel is archived' using errcode = '22023';
  end if;

  if p_mime_type is null
     or p_mime_type not in ('image/jpeg', 'image/png', 'application/pdf', 'audio/webm', 'audio/mp4') then
    raise exception 'unsupported media type' using errcode = '22023';
  end if;
  -- Eine Sprachnachricht hat eine Dauer, sonst nichts (Punkt 84).
  v_ton := p_mime_type in ('audio/webm', 'audio/mp4');
  if v_ton <> (p_duration_seconds is not null)
     or (p_duration_seconds is not null
         and p_duration_seconds not between 1 and app.team_voice_max_seconds()) then
    raise exception 'invalid duration' using errcode = '22023';
  end if;
  if p_byte_size is null or p_byte_size <= 0 or p_byte_size > app.patient_file_max_bytes() then
    raise exception 'file too large or empty' using errcode = '22023';
  end if;
  if p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid checksum' using errcode = '22023';
  end if;
  if length(v_name) not between 1 and 120 or v_name ~ '[[:cntrl:]]' then
    raise exception 'invalid file name' using errcode = '22023';
  end if;
  if (select count(*) from public.team_message_attachments a
       where a.staff_member_id = v_staff and a.message_id is null
         and a.created_at > now() - interval '24 hours')
     >= app.team_attachment_open_limit() then
    raise exception 'too many unsent attachments' using errcode = '23514';
  end if;

  insert into public.team_message_attachments (
    organization_id, channel_id, staff_member_id, display_name, mime_type, byte_size,
    checksum_sha256, duration_seconds, created_by
  )
  values (v_org, p_channel, v_staff, v_name, p_mime_type, p_byte_size, p_checksum_sha256,
          p_duration_seconds, auth.uid())
  returning id into v_id;

  return query
    select a.id, app.chat_attachment_bucket(), a.object_key
    from public.team_message_attachments a where a.id = v_id;
end;
$_$;

COMMENT ON FUNCTION public.prepare_team_attachment_upload(p_channel uuid, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text, p_name text, p_duration_seconds integer) IS 'TEAM-003 und TEAM-004 (ADR-017 Punkte 7a, 71 und 84): Phase (a) - ein Anhang für ein lesbares, nicht archiviertes Gespräch, JPEG, PNG oder PDF bis 10 MB oder eine Sprachnachricht (WebM, MP4) mit Dauer von 1 bis 120 Sekunden, höchstens 20 ungesendet; liefert den Objektschlüssel, bevor Bytes fließen.';

CREATE FUNCTION public.preview_electricity_reimbursement(p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = 'P0002';
  end if;
  perform app.assert_electricity_month(v_org, p_month);
  return app.electricity_offer(v_org, v_staff, p_month);
end;
$$;

COMMENT ON FUNCTION public.preview_electricity_reimbursement(p_month date) IS 'ORG-008: Ladestrom eines Monats für sich - geplante Arbeitsminuten (Wochenplan ohne Feiertage und ganztägige Abwesenheit), Strecke, Verbrauch und Satz der Praxis, der Betrag und ob der Monat schon beantragt ist. Nur die zwölf abgeschlossenen Monate vor dem laufenden.';

CREATE FUNCTION public.preview_leave(p_starts_on date, p_ends_on date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_tage  integer;
  v_folge integer := 0;
  v_jahr  integer;
begin
  v_org := app.staff_request_org(app.can_request_leave(), 'not allowed to request leave');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = '22023';
  end if;
  perform app.assert_leave_period(v_org, p_starts_on, p_ends_on);

  v_jahr := extract(year from p_starts_on)::integer;
  v_tage := app.leave_days(v_org, v_staff, p_starts_on, p_ends_on);
  if extract(year from p_ends_on)::integer > v_jahr then
    v_folge := app.leave_days(v_org, v_staff, make_date(v_jahr + 1, 1, 1), p_ends_on);
  end if;

  return jsonb_build_object(
    'days', v_tage,
    'days_following_year', v_folge,
    'balance', app.leave_balance(v_org, v_staff, v_jahr),
    'overlaps_own', exists (
      select 1 from public.staff_leave_requests r
      where r.organization_id = v_org and r.staff_member_id = v_staff
        and r.kind = 'leave' and r.status in ('requested', 'approved')
        and r.starts_on <= p_ends_on and r.ends_on >= p_starts_on
    ),
    'team', app.team_leave(v_org, v_staff, p_starts_on, p_ends_on),
    'self_entered', app.has_any_role('owner'),
    -- Eigene Termine und abweichende Arbeitszeiten im Zeitraum: Wer selbst
    -- eintraegt, plant danach um bzw. aendert vorher (ANN-578).
    'appointment_days', app.appointment_days_in_leave(v_org, v_staff, p_starts_on, p_ends_on),
    'exception_days', app.exception_days_in_leave(v_org, v_staff, p_starts_on, p_ends_on)
  );
end;
$$;

COMMENT ON FUNCTION public.preview_leave(p_starts_on date, p_ends_on date) IS 'URL-001: was ein Urlaubsantrag fuer die eigene Person ergaebe - Tage (am Server gezaehlt), Konto, ob er sich mit einem eigenen ueberschneidet, wer zur selben Zeit genehmigt fehlt (nur Name und Zeitraum), die eigenen Termine je Tag und die Tage mit abweichenden Arbeitszeiten im Zeitraum.';

CREATE FUNCTION public.preview_patient_merge(p_source_patient_id uuid, p_target_patient_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_merge_patients() then
    perform app.record_denied_write(v_actor, 'patient.merged', 'not allowed to merge patients');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to merge patients' using errcode = '42501';
  end if;

  if p_source_patient_id is not distinct from p_target_patient_id then
    raise exception 'a patient cannot be merged into itself' using errcode = '22023';
  end if;

  return app.patient_merge_plan(v_org, p_source_patient_id, p_target_patient_id);
end;
$$;

COMMENT ON FUNCTION public.preview_patient_merge(p_source_patient_id uuid, p_target_patient_id uuid) IS 'Vorschau des Zusammenfuehrens einer Dublette (PRX-017): beide Kopfdaten, Zaehler, Konflikte, angehaengte Freitexte, Sperrgruende. Nur owner; abgewiesen mit denied-Eintrag patient.merged und HTTP 403 (G6c).';

CREATE FUNCTION public.preview_time_account_entry(p_staff_member_id uuid, p_kind text, p_on_date date, p_starts_at time without time zone DEFAULT NULL::time without time zone, p_ends_at time without time zone DEFAULT NULL::time without time zone, p_minutes integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_staff  uuid;
  v_pruef  jsonb;
  v_saldo  integer;
begin
  v_org := app.staff_request_org(app.can_keep_time_account(), 'not allowed to keep a time account');
  v_staff := app.time_account_target(v_org, p_staff_member_id);
  v_pruef := app.time_account_check(v_org, v_staff, p_kind, p_on_date, p_starts_at, p_ends_at, p_minutes);
  if v_staff is distinct from app.own_staff_member(v_org) then
    v_pruef := app.time_account_foreign_view(v_pruef, v_org, p_on_date);
  end if;
  v_saldo := app.time_account_balance(v_org, v_staff);
  return v_pruef || jsonb_build_object(
    'balance_minutes', v_saldo,
    'balance_after', case when v_pruef ->> 'minutes' is null then null
                          else v_saldo + (v_pruef ->> 'minutes')::integer end
  );
end;
$$;

COMMENT ON FUNCTION public.preview_time_account_entry(p_staff_member_id uuid, p_kind text, p_on_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_minutes integer) IS 'ZK-001: Was ein Eintrag im Zeitkonto ergäbe - der Tag, Minuten, Saldo danach, Gründe dagegen, Termine in einem Freizeitausgleich. Schreibt nichts.';

CREATE FUNCTION public.preview_working_time_change(p_kind text, p_on_date date, p_blocks jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_bisher  jsonb;
  v_neu     jsonb;
  v_minuten integer;
begin
  v_org := app.staff_request_org(app.can_request_working_time(), 'not allowed to request working time');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = '22023';
  end if;
  perform app.assert_working_time_date(v_org, p_kind, p_on_date);
  v_bisher := app.working_time_baseline(v_org, v_staff, p_kind, p_on_date);
  if p_blocks is null then
    return jsonb_build_object(
      'previous', v_bisher -> 'blocks',
      'previous_minutes', (v_bisher ->> 'minutes')::integer,
      'self_entered', app.has_any_role('owner')
    );
  end if;
  v_neu := app.working_time_normalize(p_kind, p_blocks);
  v_minuten := app.working_time_minutes(p_kind, v_neu);
  return jsonb_build_object(
    'previous', v_bisher -> 'blocks',
    'previous_minutes', (v_bisher ->> 'minutes')::integer,
    'new_minutes', v_minuten,
    'unchanged', v_neu = v_bisher -> 'blocks',
    'reduced', v_minuten < (v_bisher ->> 'minutes')::integer,
    -- ZK-001: Hielte das Beantragen an einem Freizeitausgleich an, steht der
    -- Grund schon hier (Zweitreview Runde 2).
    'problems', to_jsonb(app.working_time_problems(v_org, v_staff, p_kind, p_on_date, v_neu)
                         || case when p_kind = 'permanent' and app.time_off_on_changed_weekdays(
                                   v_org, v_staff, p_on_date, v_neu, v_bisher -> 'blocks')
                                 then array['time_off_in_lieu'] else '{}'::text[] end),
    'appointment_days', app.appointments_outside_working_time(v_org, v_staff, p_kind, p_on_date, v_neu),
    'self_entered', app.has_any_role('owner')
  );
end;
$$;

COMMENT ON FUNCTION public.preview_working_time_change(p_kind text, p_on_date date, p_blocks jsonb) IS 'AZ-001: was fuer die eigene Person bisher gilt (einmalig der Tag, dauerhaft der Wochenplan am Datum) und, mit neuen Zeiten, Arbeitszeit bisher und neu, was nach ArbZG dagegen spricht und welche Termine ausserhalb laegen. Schreibt nichts.';

CREATE FUNCTION public.publish_service_catalog_version(p_version_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_published timestamptz;
  v_valid_from date;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select v.published_at, v.valid_from into v_published, v_valid_from
  from public.service_catalog_versions v
  where v.id = p_version_id and v.organization_id = v_org;

  if not found then
    raise exception 'service catalog version not found' using errcode = '42501';
  end if;

  if v_published is not null then
    raise exception 'service catalog version is already published' using errcode = '23514';
  end if;

  if not exists (
    select 1 from public.service_catalog_items where catalog_version_id = p_version_id
  ) then
    raise exception 'service catalog version has no items' using errcode = '22023';
  end if;

  update public.service_catalog_versions
     set published_at = now(), published_by = v_actor
   where id = p_version_id;


  return p_version_id;
end;
$$;

COMMENT ON FUNCTION public.publish_service_catalog_version(p_version_id uuid) IS 'Setzt eine Preisliste in Kraft und macht sie damit unveraenderlich (ABR-001, ADR-009 Punkt 5). Protokolliert service_catalog.version_published.';

CREATE FUNCTION public.purge_notification_deliveries() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  delete from public.notification_deliveries d
   where d.state <> 'pending'
     and d.finished_at < now() - app.retention_interval('benachrichtigung');
  get diagnostics v_anzahl = row_count;
  -- BEF-148: Push-Registrierungen eines Zugangs, der geendet hat - zeitlich
  -- (Lesefrist, Volljährigkeit) oder durch Widerruf. Beim Widerruf fallen sie
  -- schon sofort (Trigger). Eine Sperre ist kein Ende: Sie lässt sich
  -- aufheben, und die Registrierung des Geräts bleibt dafür stehen
  -- (Zweitreview); geschickt wird während der Sperre ohnehin nichts.
  delete from public.platform_push_subscriptions p
   using public.platform_accesses a
   where a.id = p.access_id
     and (a.status = 'revoked' or coalesce(app.platform_access_ended_at(a.id) <= now(), false));
  -- BEF-189 (ANN-669): ebenso die Wahl und die Tagebuch-Erinnerungen. Danach
  -- gibt es über sie nichts mehr, worüber Auskunft zu geben wäre.
  delete from public.platform_notification_settings s
   using public.platform_accesses a
   where a.id = s.access_id
     and (a.status = 'revoked' or coalesce(app.platform_access_ended_at(a.id) <= now(), false));
  delete from public.nutrition_diary_reminders r
   using public.platform_accesses a
   where a.id = r.access_id
     and (a.status = 'revoked' or coalesce(app.platform_access_ended_at(a.id) <= now(), false));
  return v_anzahl;
end;
$$;

CREATE FUNCTION public.rate_slot_travel(p_items jsonb) RETURNS TABLE(item_index integer, status text, shortfall_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_tz      text;
  v_grid    integer;
  v_item    jsonb;
  v_staff   uuid;
  v_tag     date;
  v_ab      timestamptz;
  v_bis     timestamptz;
  v_zu      integer;
  v_von     integer;
  v_ende    timestamptz;
  v_beginn  timestamptz;
  v_knapp   boolean;
  v_unklar  boolean;
  v_frueh   timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    perform app.record_denied_read(auth.uid(), 'appointments.read', 'not allowed to create appointments');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to create appointments' using errcode = '42501';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 25 then
    raise exception 'items must be an array of at most 25 entries' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes into v_tz, v_grid
  from public.organizations o where o.id = v_org;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      item_index := (v_item ->> 'index')::integer;
      v_staff := (v_item ->> 'staff_member_id')::uuid;
      v_tag   := (v_item ->> 'date')::date;
      v_ab    := (v_tag + (v_item ->> 'start')::time)::timestamp at time zone v_tz;
      v_bis   := (v_tag + (v_item ->> 'end')::time)::timestamp at time zone v_tz;
      v_zu    := nullif(v_item ->> 'travel_to_seconds', '')::numeric::integer;
      v_von   := nullif(v_item ->> 'travel_from_seconds', '')::numeric::integer;
    exception
      when others then
        raise exception 'invalid item' using errcode = '22023';
    end;
    if item_index is null or v_staff is null or v_tag is null
       or (v_zu is not null and v_zu not between 0 and 86400)
       or (v_von is not null and v_von not between 0 and 86400) then
      raise exception 'invalid item' using errcode = '22023';
    end if;

    v_knapp := false;
    v_unklar := false;
    shortfall_minutes := 0;

    if v_item ->> 'prev_appointment_id' is not null then
      -- Ein Nachbar, den diese Person nicht lesen darf oder der nicht passt,
      -- ist "nicht geprueft" - ohne zu sagen, ob es ihn gibt.
      v_ende := null;
      begin
        select a.ends_at into v_ende from public.appointments a
        where a.id = (v_item ->> 'prev_appointment_id')::uuid
          and a.organization_id = v_org
          and a.staff_member_id = v_staff
          and a.status <> 'cancelled'
          and app.may_read_appointment_context(a.kind)
          and a.ends_at <= v_ab
          and a.ends_at > (v_tag::timestamp at time zone v_tz);
      exception
        when invalid_text_representation then
          v_ende := null;
      end;
      if v_ende is null or v_zu is null then
        v_unklar := true;
      else
        v_frueh := app.earliest_follow_up_start(v_ende, v_zu, v_grid, v_tz);
        if v_frueh > v_ab then
          v_knapp := true;
          shortfall_minutes := greatest(
            shortfall_minutes, ceil(extract(epoch from (v_frueh - v_ab)) / 60)::integer
          );
        end if;
      end if;
    end if;

    if v_item ->> 'next_appointment_id' is not null then
      v_beginn := null;
      begin
        select a.starts_at into v_beginn from public.appointments a
        where a.id = (v_item ->> 'next_appointment_id')::uuid
          and a.organization_id = v_org
          and a.staff_member_id = v_staff
          and a.status <> 'cancelled'
          and app.may_read_appointment_context(a.kind)
          and a.starts_at >= v_bis
          and a.starts_at < ((v_tag + 1)::timestamp at time zone v_tz);
      exception
        when invalid_text_representation then
          v_beginn := null;
      end;
      if v_beginn is null or v_von is null then
        v_unklar := true;
      else
        v_frueh := app.earliest_follow_up_start(v_bis, v_von, v_grid, v_tz);
        if v_frueh > v_beginn then
          v_knapp := true;
          shortfall_minutes := greatest(
            shortfall_minutes, ceil(extract(epoch from (v_frueh - v_beginn)) / 60)::integer
          );
        end if;
      end if;
    end if;

    status := case when v_knapp then 'tight' when v_unklar then 'unknown' else 'ok' end;
    return next;
  end loop;
end;
$$;

COMMENT ON FUNCTION public.rate_slot_travel(p_items jsonb) IS 'Fahrzeit der Vorschlaege aus find_free_slots (PRX-003, ANN-136): ok, tight (mit fehlenden Minuten) oder unknown. Die Fahrzeiten kommen live aus dem eigenen Kartendienst und werden nicht gespeichert (ANN-097); gerundet wird hier mit app.earliest_follow_up_start (§8.1). Warnung, keine Sperre.';

CREATE FUNCTION public.reapply_deletion_journal() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_reihenfolge text[] := array[
    'invoice_payment_reminders',
    'invoice_cancellations',
    'payments',
    'invoice_items',
    'invoices',
    'invoice_recipients',
    'billable_services',
    'treatment_note_versions',
    'treatment_notes',
    'patient_files',
    -- Vor Grundlage und Termin: ein Eintrag zeigt auf beide (on delete set
    -- null) - geloescht wird er vorher, damit nichts umgeschrieben wird
    -- (PRX-001, Zweitreview 5).
    'waitlist_entries',
    -- PRX-012: eine Aufgabe zeigt auf Person und Mitarbeitende (cascade
    -- beziehungsweise set null) - geloescht wird sie vorher.
    'tasks',
    -- TRN-009: das Trainingsprotokoll haengt am Termin (restrict) und faellt
    -- vor ihm - dieselbe Reihenfolge wie im Lauf.
    'training_protocols',
    -- PRX-014: der Anrufstand haengt am Termin und faellt vor ihm.
    'appointment_call_states',
    -- POR-009: ein Terminwunsch zeigt auf Termin (set null) und Verhaeltnis
    -- (cascade) - geloescht wird er vorher.
    'platform_appointment_requests',
    -- KOM-005: ein Anhang haengt am Vorgang (cascade) und faellt vor ihm.
    'platform_message_attachments',
    -- KOM-001: ein Vorgang zeigt auf Plan, Uebung (set null) und Akte
    -- (cascade); seine Eintraege fallen mit ihm.
    'platform_messages',
    -- FLT-001: die Radflotte haengt an keiner Akte. Schluessel und Sperren
    -- vor den Pannen (eine Sperre zeigt auf ihre Panne, set null); einzeln
    -- geloeschte Fotos vor Check-Up und Panne, deren Stellen und uebrige
    -- Fotos mit ihnen fallen (cascade); das ausgemusterte Rad zuletzt.
    'fleet_key_handovers',
    'fleet_blocks',
    'fleet_photos',
    'fleet_checkups',
    'fleet_breakdowns',
    'fleet_bikes',
    -- URL-001: Storno und Abwesenheiten in den Arbeitszeiten fallen mit ihrem
    -- Urlaub (cascade).
    'staff_leave_requests',
    'staff_leave_entitlements',
    -- AZ-001: Arbeitszeitaenderungen haengen an keiner anderen Zeile.
    'staff_working_time_requests',
    -- ZK-001: ein Eintrag im Zeitkonto; seine Abweichung faellt mit ihm
    -- (cascade).
    'staff_time_account_entries',
    -- ERS-001: einzeln verworfene Belege vor ihrem Antrag; eine Erstattung
    -- nimmt ihre übrigen Belege mit (cascade), deren Objekte über den
    -- Löschauftrag.
    'staff_reimbursement_receipts',
    'staff_reimbursements',
    -- ORG-006: Rückmeldungen von Beschäftigten hängen an keiner anderen Zeile.
    'staff_feedback',
    -- TEAM-007: ein Profilbild hängt an keiner anderen Zeile; entfernt,
    -- ersetzt oder mit dem Ausscheiden gefallen, bleibt es fort.
    'staff_profile_pictures',
    -- TEAM-003: einzeln verworfene, nie gesendete Anhänge (ANN-652) vor den
    -- Nachrichten; gesendete fallen mit ihrer Nachricht (cascade) oder ihrem
    -- Inhalt (Auslöser), ihre Objekte über den Löschauftrag.
    'team_message_attachments',
    -- TEAM-001: erst geleerte Inhalte (die Zeile bleibt als Anker), dann
    -- Nachrichten vor ihren Gesprächen; Antworten, Erwähnungen und Lesestand
    -- fallen mit (cascade).
    'team_message_contents',
    'team_messages',
    'team_channels',
    -- ERN-001: das Ernährungsprofil vor seinem Verhältnis; Einwilligung und
    -- Gewicht fallen mit ihm (cascade).
    'nutrition_profiles',
    'treatment_base_items',
    'treatment_bases',
    'appointments',
    'legal_holds',
    'patient_contact_details',
    'patient_care_details',
    'patients',
    -- TRN-EPIC-003 (Zweitreview): Kontaktdaten des Trainings aus der
    -- Teilloeschung. Ihr Schluessel ist das Verhaeltnis, nicht `id`.
    'training_contact_details',
    -- TRN-005: die Vereinbarung nach ihren Terminen (on delete set null) und
    -- vor ihrem Verhaeltnis (restrict) - dieselbe Reihenfolge wie im Lauf
    -- (app.delete_training_relationship). Fehlte seit CAL-026.
    'training_bases',
    -- Vor persons: die Person faellt erst, wenn kein Verhaeltnis mehr auf
    -- sie zeigt - nach einem Restore genauso wie im Lauf (LEI-002).
    'training_relationships',
    'persons',
    'audit_log',
    'staff_account_invitations',
    -- POR-002: der Zugang mit seinen Einladungen (on delete cascade) und das
    -- Konto beim Anmeldedienst. `auth_users` ist kein Tabellenname in
    -- public, sondern die eine Ausnahme unten.
    'platform_accesses',
    'auth_users'
  ];
  v_tabelle   text;
  v_ids       uuid[];
  v_geloescht uuid[];
  v_unbekannt text[];
  v_gesamt    integer := 0;
begin
  select array_agg(distinct j.target_table)
    into v_unbekannt
  from public.deletion_journal j
  where not (j.target_table = any (v_reihenfolge));

  if v_unbekannt is not null then
    raise exception 'deletion journal references tables without a reapply order: %', v_unbekannt
      using errcode = '22023';
  end if;

  foreach v_tabelle in array v_reihenfolge
  loop
    select array_agg(j.target_id)
      into v_ids
    from public.deletion_journal j
    where j.target_table = v_tabelle;

    continue when v_ids is null;

    -- Das Konto einer Plattform liegt beim Anmeldedienst (ADR-023 Punkt 5).
    -- ABN-011 (BEF-115): auch hier ueber die Admin-API. Was nach dem Restore
    -- wieder da ist, verliert sofort jeden Zugang und bekommt einen
    -- Loeschauftrag. Als erneut angewandt gilt der Journaleintrag erst mit
    -- der Bestaetigung (confirm_platform_account_deletion, Zweitreview B1).
    if v_tabelle = 'auth_users' then
      update public.platform_accesses a
         set status = 'revoked',
             revoked_at = coalesce(a.revoked_at, now()),
             revoked_by = null,
             revoked_reason = 'account_deleted',
             locked_at = null,
             locked_by = null
       where a.account_user_id = any (v_ids) and a.status <> 'revoked';

      perform app.order_platform_account_deletion(
        j.target_id, j.organization_id, null, j.due_at, 'reapply')
      from public.deletion_journal j
      join auth.users u on u.id = j.target_id
      where j.target_table = 'auth_users'
        and j.target_id = any (v_ids);
      v_geloescht := null;
    -- TEAM-001: Nur der Inhalt fiel (Anker mit Antworten) - leeren, nicht
    -- löschen, sonst nähme cascade die Antworten mit. Wer entfernt hat, steht
    -- nach einem Restore nicht mehr fest; der Anker heißt dann „gelöscht“.
    elsif v_tabelle = 'team_message_contents' then
      delete from public.team_message_mentions where message_id = any (v_ids);
      with g as (
        update public.team_messages
           set body = null, edited_at = null, author_staff_member_id = null,
               removed_at = coalesce(removed_at, now()),
               removed_kind = coalesce(removed_kind, 'author')
         where id = any (v_ids) and body is not null
        returning id
      )
      select array_agg(id) into v_geloescht from g;
    else
    -- Tabellenname aus der festen Liste oben, nie aus Benutzereingabe;
    -- die Kennungen gehen als Parameter, nicht als Text.
    execute format(
      'with g as (delete from public.%I where %I = any($1) returning %I as id) select array_agg(id) from g',
      v_tabelle,
      app.deletion_key_column(v_tabelle),
      app.deletion_key_column(v_tabelle)
    )
    into v_geloescht
    using v_ids;
    end if;

    if v_geloescht is not null then
      update public.deletion_journal
         set reapplied_at = now()
       where target_table = v_tabelle
         and target_id = any (v_geloescht);

      v_gesamt := v_gesamt + array_length(v_geloescht, 1);
    end if;
  end loop;

  -- ORG-006 (Nachprüfung N2): Anonyme Rückmeldungen schreibt der Lauf mit
  -- neuer Kennung neu - ein älteres Backup trägt andere Kennungen als das
  -- Journal. Was nach dem Restore über der Frist liegt, fällt hier nach der
  -- Regel selbst, nicht erst im nächsten Lauf.
  delete from public.staff_feedback f
  using public.organizations o
  where o.id = f.organization_id
    and app.retention_due_at(
          (f.month + interval '1 month' - interval '1 day')::date,
          app.retention_interval('rueckmeldung'),
          o.time_zone
        ) <= now();

  -- TEAM-001: Fällige Ausgangsnachrichten mit laufenden Antworten verlieren
  -- ihren Inhalt nach der Regel, nicht über das Journal (ANN-610).
  perform app.strip_due_team_anchors(o.id, o.time_zone) from public.organizations o;

  -- TEAM-007: Ein Bild, das ein Restore zurückbringt, obwohl die Person
  -- inzwischen ausgeschieden ist, fällt nach der Regel (ANN-667) - mit
  -- Eintrag im Löschjournal wie jede Löschung eines Bildes (Zweitreview,
  -- Befund 4).
  perform app.forget_profile_picture(p.organization_id, p.id)
  from public.staff_profile_pictures p
  join public.staff_members sm on sm.id = p.staff_member_id
  where sm.employment_status <> 'active';

  -- Die Wiederanwendung weist deletion_journal.reapplied_at nach (LOG-EPIC-001).

  return v_gesamt;
end;
$_$;

COMMENT ON FUNCTION public.reapply_deletion_journal() IS 'Zieht nach einer Wiederherstellung die Loeschungen des Journals erneut nach (ADR-008 Punkt 8). Seit ABR-003d einschliesslich Zahlungserinnerungen, Stornodokumenten, Zahlungen, Rechnungen, ihrer Zeilen und der Empfaenger, seit LEI-002 einschliesslich der Trainingsverhaeltnisse.';

CREATE FUNCTION public.receipt_storage_deletion_order(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_auftrag record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_execute_storage_deletion() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'storage_deletion.receipted', 'not allowed to execute deletion orders');
    return;
  end if;

  select o.* into v_auftrag
  from public.storage_deletion_orders o
  where o.id = p_order_id
    and o.organization_id = app.current_organization_id()
    and o.receipted_at is null
  for update;

  if not found then
    raise exception 'deletion order not accessible' using errcode = '42501';
  end if;

  if exists (
    select 1
    from storage.objects s
    where s.bucket_id = v_auftrag.bucket_id
      and s.name = v_auftrag.object_key
  ) then
    raise exception 'object is still present' using errcode = '22023';
  end if;

  update public.storage_deletion_orders
     set receipted_at = now(),
         receipted_by = v_actor
   where id = p_order_id;

end;
$$;

COMMENT ON FUNCTION public.receipt_storage_deletion_order(p_order_id uuid) IS 'Quittiert einen Loeschauftrag - aber nur, wenn das Objekt tatsaechlich nicht mehr da ist (ADR-017 Punkt 25).';

CREATE FUNCTION public.record_aftercare_month(p_subscription_id uuid, p_month_start date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_abo     public.aftercare_subscriptions%rowtype;
  v_grund   text;
  v_position uuid;
  v_id      uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_aftercare() then
    raise exception 'not allowed to manage aftercare subscriptions' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  -- Unter Sperre der Akte: Kuendigung und Wiederaufnahme der Behandlung
  -- laufen nicht an der Pruefung vorbei.
  perform 1 from public.patients p
  join public.aftercare_subscriptions s on s.patient_id = p.id
  where s.id = p_subscription_id and s.organization_id = v_org
  for update of p;
  select * into v_abo from public.aftercare_subscriptions s
  where s.id = p_subscription_id and s.organization_id = v_org;
  if not found then
    raise exception 'aftercare subscription not found' using errcode = '42501';
  end if;

  v_grund := app.aftercare_month_blocker(p_subscription_id, p_month_start);
  if v_grund is not null then
    raise exception 'aftercare month cannot be recorded: %', v_grund using errcode = '22023';
  end if;

  select pr.catalog_item_id into v_position
  from app.aftercare_month_price(v_org, p_month_start) pr;

  insert into public.billable_services (
    organization_id, patient_id, appointment_id, aftercare_subscription_id,
    catalog_item_id, quantity, performed_on, created_by
  )
  values (v_org, v_abo.patient_id, null, v_abo.id, v_position, 1, p_month_start, v_actor)
  returning id into v_id;

  return v_id;
exception
  when unique_violation then
    raise exception 'aftercare month already recorded' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.record_aftercare_month(p_subscription_id uuid, p_month_start date) IS 'ANG-002: einen Abo-Monat als Leistung erfassen (owner, office) - zum Preis der am ersten Tag geltenden Preisliste, je Monat hoechstens einmal (ADR-009 Punkte 4, 5, 21).';

CREATE FUNCTION public.record_billable_services(p_appointment_id uuid, p_items jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor        uuid;
  v_org          uuid;
  v_status       text;
  v_fee_basis    text;
  v_basis        uuid;
  v_patient      uuid;
  v_kind         text;
  v_training     uuid;
  v_occasion     text;
  v_performed_on date;
  v_version      uuid;
  v_erwartet     text;
  v_anzahl       integer;
  v_honorar      record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- PRX-009 (ANN-140): owner und office an jedem Termin, Behandelnde an
  -- ihrem eigenen Behandlungstermin (TRN-007). Ein fremder Termin ist von
  -- einem unbekannten nicht zu unterscheiden - beide scheitern hier gleich.
  if not app.can_record_services_for_appointment(p_appointment_id) then
    raise exception 'not allowed to record billable services' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  -- ABN-006: Ein Verzicht nimmt dem Anlass die Abrechenbarkeit, nicht den Anlass.
  select a.status, app.billable_fee_basis(a.fee_basis, a.fee_waived_at), a.treatment_basis_id, a.patient_id, a.kind,
         a.training_relationship_id, a.occasion
    into v_status, v_fee_basis, v_basis, v_patient, v_kind, v_training, v_occasion
  from public.appointments a
  where a.id = p_appointment_id and a.organization_id = v_org
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = '42501';
  end if;

  -- TRN-007: Ein interner Termin hat kein Gegenueber und erzeugt nichts
  -- (Paragraf 19). Die Meldung bleibt die bisherige.
  if v_patient is null and v_training is null then
    raise exception 'appointment has no patient' using errcode = '22023';
  end if;

  -- Paragraf 19: Behandlung aus "dokumentiert" oder einem Gebuehrenanlass,
  -- ohne Override (ANN-072); Training aus dem durchgefuehrten Termin
  -- (ANN-181). Eine Stelle: app.appointment_is_billable.
  -- ERN-011 (ANN-622, ANN-664): Die Ernaehrungsberatung aus dem abgehakten
  -- Termin, in beiden Bereichen.
  if not app.appointment_is_billable(app.billing_kind(v_kind, v_occasion), v_status, v_fee_basis) then
    if v_occasion = 'nutrition_counselling' then
      raise exception 'nutrition counselling has not taken place' using errcode = '22023';
    end if;
    if v_kind = 'training' then
      raise exception 'training appointment has not taken place' using errcode = '22023';
    end if;
    raise exception 'appointment is neither documented nor a fee occasion'
      using errcode = '22023';
  end if;

  if exists (select 1 from public.billable_services where appointment_id = p_appointment_id) then
    raise exception 'appointment already has billable services' using errcode = '23505';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'items must be a non-empty array' using errcode = '22023';
  end if;

  v_performed_on := app.appointment_performed_on(p_appointment_id);
  v_version := app.active_service_catalog_version(v_org, v_performed_on);

  if v_version is null then
    raise exception 'no published service catalog for %', v_performed_on using errcode = '22023';
  end if;

  -- ERN-011: Am Beratungstermin nur die Position der Ernaehrungsberatung.
  v_erwartet := case when v_fee_basis is not null then 'absence_fee'
                     when v_occasion = 'nutrition_counselling' then 'nutrition_counselling'
                     else 'treatment' end;

  -- Zweitreview (ANN-140): Am eigenen Termin bestaetigen Behandelnde die
  -- Heilmittel. Ein Ausfallhonorar ist eine Forderung gegen die Patient:in
  -- und bleibt beim Buero.
  if v_erwartet = 'absence_fee' and not app.can_record_billable_services() then
    raise exception 'not allowed to record billable services' using errcode = '42501';
  end if;

  insert into public.billable_services (
    organization_id, patient_id, training_relationship_id, appointment_id, catalog_item_id,
    treatment_base_item_id, quantity, performed_on, created_by
  )
  select
    v_org,
    v_patient,
    v_training,
    p_appointment_id,
    i.id,
    -- Die Position der Grundlage, deren Menge diese Leistung verbraucht. Ein
    -- Trainingstermin hat keine Behandlungsgrundlage (ADR-022 Punkt 4); die
    -- Unterabfrage bleibt dann leer.
    (select p.id
       from public.treatment_base_items p
      where p.treatment_basis_id = v_basis
        and p.remedy = i.remedy
      limit 1),
    coalesce((zeile.eintrag ->> 'quantity')::smallint, 1::smallint),
    v_performed_on,
    v_actor
  from jsonb_array_elements(p_items) as zeile(eintrag)
  join public.service_catalog_items i
    on i.id = (zeile.eintrag ->> 'catalog_item_id')::uuid
   and i.catalog_version_id = v_version
   and i.item_kind = v_erwartet
   -- TRN-007: nur Positionen des Bereichs dieses Termins. Der Trigger wiese
   -- eine fremde ab; hier faellt sie aus dem Join und der ganze Vorgang
   -- scheitert mit einer Meldung, die den Grund nennt.
   and i.service_area = app.service_area_of_appointment_kind(v_kind);

  get diagnostics v_anzahl = row_count;

  -- Eine Position, die es in der geltenden Preisliste nicht gibt oder die
  -- nicht zum Anlass passt, faellt aus dem Join heraus. Stillschweigend
  -- weniger zu schreiben, als verlangt wurde, waere genau der Fehler aus
  -- Paragraf 13 - also scheitert der ganze Vorgang.
  if v_anzahl <> jsonb_array_length(p_items) then
    raise exception 'item does not belong to the catalog version valid on % or does not match %',
      v_performed_on, v_erwartet using errcode = '22023';
  end if;

  -- ABR-031 (ADR-009 Punkt 22, ANN-232): Traegt ein Behandlungstermin
  -- mindestens ein Heilmittel, entsteht genau einmal das Terminhonorar - mit
  -- dem Betrag, der am Leistungstag gilt, festgeschrieben. Die Auswahl der
  -- Heilmittel aendert ihn nicht. Im Honorar ist die Menge je Heilmittel 1:
  -- eine Doppelbehandlung ist eine eigene Position.
  if v_kind = 'therapy' and v_erwartet = 'treatment' and exists (
    select 1
    from public.billable_services b
    join public.service_catalog_items c on c.id = b.catalog_item_id
    where b.appointment_id = p_appointment_id and c.remedy is not null
  ) then
    if exists (
      select 1
      from public.billable_services b
      join public.service_catalog_items c on c.id = b.catalog_item_id
      where b.appointment_id = p_appointment_id and c.remedy is not null and b.quantity <> 1
    ) then
      raise exception 'within the session fee each remedy is recorded once' using errcode = '22023';
    end if;

    select h.amount_cents, h.source, h.fee_agreement_id
      into v_honorar
    from app.session_fee_on(v_patient, v_performed_on) h;

    if v_honorar.amount_cents is null then
      raise exception 'no session fee for %', v_performed_on using errcode = '22023';
    end if;

    insert into public.appointment_session_fees (
      organization_id, appointment_id, amount_cents, source, fee_agreement_id,
      catalog_version_id, performed_on, created_by
    )
    values (
      v_org, p_appointment_id, v_honorar.amount_cents, v_honorar.source,
      v_honorar.fee_agreement_id, v_version, v_performed_on, v_actor
    );
  end if;

  -- Die genutzte Menge der Grundlage wird jetzt fortgeschrieben (ANN-073).
  -- Die Constraint used_quantity <= prescribed_quantity bleibt bestehen und
  -- schuetzt die Abrechnung (ADR-020 Punkt 5); sie bekommt hier nur eine
  -- verstaendliche Meldung.
  begin
    update public.treatment_base_items p
       set used_quantity = p.used_quantity + b.menge
    from (
      select treatment_base_item_id, sum(quantity)::smallint as menge
      from public.billable_services
      where appointment_id = p_appointment_id and treatment_base_item_id is not null
      group by treatment_base_item_id
    ) b
    where p.id = b.treatment_base_item_id;
  exception
    when check_violation then
      raise exception 'treatment basis quantity exhausted' using errcode = '23514';
  end;


  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.record_billable_services(p_appointment_id uuid, p_items jsonb) IS 'Erfasst die Leistungen eines Termins, alles oder nichts (ABR-002). Behandlung nur aus "dokumentiert" oder einem Gebuehrenanlass, ohne Override (PROJECT_PRINCIPLES.md 19, ANN-072); Training aus dem durchgefuehrten Termin, am Trainingsverhaeltnis (TRN-007, ANN-181). Schreibt die genutzte Menge der Grundlage fort (ANN-073) und protokolliert billable_service.recorded.';

CREATE FUNCTION public.record_call_outcome(p_appointment_id uuid, p_outcome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_update_appointment() then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;
  if p_outcome is null or p_outcome not in ('reached', 'not_reached', 'voicemail', 'cleared') then
    raise exception 'unknown call outcome' using errcode = '22023';
  end if;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    and a.kind = 'therapy'
    and a.patient_id is not null
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if p_outcome = 'reached' then
    perform public.add_appointment_notification(array[p_appointment_id], 'phone');
    delete from public.appointment_call_states c where c.appointment_id = p_appointment_id;
  elsif p_outcome = 'cleared' then
    delete from public.appointment_call_states c where c.appointment_id = p_appointment_id;
  else
    insert into public.appointment_call_states
      (organization_id, appointment_id, outcome, attempts, recorded_by)
    values (v_org, p_appointment_id, p_outcome, 1, v_actor)
    on conflict (appointment_id) do update
      set outcome     = excluded.outcome,
          attempts    = least(public.appointment_call_states.attempts + 1, 99),
          recorded_at = now(),
          recorded_by = excluded.recorded_by;
  end if;

end;
$$;

COMMENT ON FUNCTION public.record_call_outcome(p_appointment_id uuid, p_outcome text) IS 'Haelt das Ergebnis eines Anrufs der Anrufliste fest (PRX-014): reached setzt den Mitteilungsvermerk phone, not_reached und voicemail den Anrufstand, cleared raeumt ihn. Protokolliert appointment.call_recorded.';

CREATE FUNCTION public.record_companion_consent_withdrawn(p_access_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_access public.platform_accesses%rowtype;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  v_access := app.platform_access_for_update(p_access_id, v_org);
  if v_access.id is null or not app.can_manage_platform_access(v_access.relationship_kind) then
    perform app.record_denied_write(v_actor, 'platform_access.revoked', 'not allowed to manage platform access');
    return null;
  end if;
  if v_access.access_kind <> 'companion' then
    raise exception 'only a companion rests on consent' using errcode = '22023';
  end if;
  if v_access.status = 'revoked' then
    raise exception 'platform access is already revoked' using errcode = '22023';
  end if;

  update public.platform_accesses
     set status = 'revoked', revoked_at = now(), revoked_by = v_actor,
         revoked_reason = 'consent_withdrawn', locked_at = null, locked_by = null
   where id = v_access.id;

  update public.platform_access_invitations
     set status = 'revoked', revoked_at = now()
   where platform_access_id = v_access.id and status = 'pending';

  perform app.log_platform_access_event(
    v_org, v_actor, 'user', 'platform_access.revoked', v_access.id,
    jsonb_build_object('surface', 'web', 'reason', 'consent_withdrawn',
                       'previous_status', v_access.status)
  );
  return 'revoked';
end;
$$;

COMMENT ON FUNCTION public.record_companion_consent_withdrawn(p_access_id uuid) IS 'POR-005: vermerkt den in der Praxis erklaerten Widerruf der Einwilligung zur Begleitung (ADR-023 Punkte 5, 13) und beendet sie mit Grund consent_withdrawn. Rollen, die das Verhaeltnis schreiben; abgewiesen mit denied und HTTP 403.';

-- ANN-615
CREATE FUNCTION public.record_electricity_tour_distance(p_reimbursement_id uuid, p_account_id uuid, p_month date, p_km integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_antrag public.staff_reimbursements;
  v_betrag integer;
begin
  if p_km is null or p_km not between 1 and 10000 then
    raise exception 'distance out of range' using errcode = '22023';
  end if;

  select r.* into v_antrag
  from public.staff_reimbursements r
  where r.id = p_reimbursement_id
  for update;

  if not found
     or v_antrag.kind <> 'electricity'
     or v_antrag.requested_by is distinct from p_account_id
     or v_antrag.period_month is distinct from p_month
     or v_antrag.working_minutes is null
     or v_antrag.tour_km is not null
     or v_antrag.requested_at < now() - interval '10 minutes'
     or not (v_antrag.status = 'requested'
             or (v_antrag.status = 'approved' and v_antrag.self_entered))
     -- Die eigene Person des Kontos in derselben Praxis, aktiv.
     or not exists (
       select 1
       from public.user_profiles up
       join public.staff_members sm
         on sm.person_id = up.person_id and sm.organization_id = up.organization_id
       where up.id = p_account_id and up.is_active
         and up.organization_id = v_antrag.organization_id
         and sm.id = v_antrag.staff_member_id
     ) then
    raise exception 'reimbursement not eligible' using errcode = 'P0002';
  end if;

  v_betrag := (p_km * v_antrag.wh_per_km * v_antrag.rate_cents_per_kwh + 500) / 1000;
  if v_betrag < 1 then
    raise exception 'distance out of range' using errcode = '22023';
  end if;

  update public.staff_reimbursements r
     set tour_km = p_km,
         km_per_hour = null,
         amount_cents = v_betrag
   where r.id = v_antrag.id;

  return jsonb_build_object('id', v_antrag.id, 'tour_km', p_km, 'amount_cents', v_betrag);
end;
$$;

COMMENT ON FUNCTION public.record_electricity_tour_distance(p_reimbursement_id uuid, p_account_id uuid, p_month date, p_km integer) IS 'BEF-181 (ADR-019 Fassung 6): trägt die Monatssumme der geplanten Tourstrecke am eben gestellten eigenen Ladestrom-Antrag ein und rechnet den Betrag neu (km × Wh/km × ct/kWh). Nur service_role (Edge Function electricity-distance); einmal, binnen zehn Minuten, vor einer Entscheidung durch andere. Ohne Auditeintrag (ADR-010 Fassung 3).';

CREATE FUNCTION public.record_fleet_breakdown(p_bike_id uuid, p_outcome text, p_summary text, p_remark text, p_location_note text, p_transport text, p_spots jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_bike    public.fleet_bikes%rowtype;
  v_summary text;
  v_id      uuid;
  v_spots   jsonb;
  v_blocked boolean := false;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');

  select b.* into v_bike
  from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
  for update;
  if v_bike.id is null then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  if p_outcome is null or not (p_outcome = any (app.fleet_breakdown_outcomes())) then
    raise exception 'unknown outcome' using errcode = '22023';
  end if;
  v_summary := app.fleet_text(p_summary, 1000, 'summary');
  if v_summary is null then
    raise exception 'summary is required' using errcode = '22023';
  end if;
  if p_transport is not null and p_transport not in ('carsharing', 'fahrdienst') then
    raise exception 'unknown transport' using errcode = '22023';
  end if;
  -- ANN-558: Ein Ort gehoert nur zum zurueckgelassenen Rad, und dieser
  -- Abschluss sperrt - die Freigabe leert ihn also wieder.
  if app.fleet_text(p_location_note, 200, 'location note') is not null
     and p_outcome <> 'transportFortsetzung' then
    raise exception 'location note only for a bike left behind' using errcode = '22023';
  end if;

  insert into public.fleet_breakdowns (
    organization_id, bike_id, outcome, summary, remark, location_note, transport, reported_by
  )
  values (
    v_org, v_bike.id, p_outcome, v_summary, app.fleet_text(p_remark, 1000, 'remark'),
    app.fleet_text(p_location_note, 200, 'location note'), p_transport, auth.uid()
  )
  returning id into v_id;

  v_spots := app.fleet_insert_spots(v_org, v_bike, null, v_id, coalesce(p_spots, '[]'::jsonb));

  if app.fleet_outcome_blocks(p_outcome) then
    v_blocked := true;
    if not exists (
      select 1 from public.fleet_blocks b where b.bike_id = v_bike.id and b.released_at is null
    ) then
      insert into public.fleet_blocks (organization_id, bike_id, breakdown_id, blocked_by)
      values (v_org, v_bike.id, v_id, auth.uid());
    end if;
  end if;

  return jsonb_build_object('breakdown_id', v_id, 'spot_ids', v_spots, 'blocked', v_blocked);
end;
$$;

COMMENT ON FUNCTION public.record_fleet_breakdown(p_bike_id uuid, p_outcome text, p_summary text, p_remark text, p_location_note text, p_transport text, p_spots jsonb) IS 'FLT-001: Panne melden - Abschluss des Assistenten, Text, auffaellige Stelle, Standort des zurueckgelassenen Rads (ANN-558), Weiterfahrt und Stellen am Rad (jede ein Schaden). Sperrt nach app.fleet_outcome_blocks. Versendet nichts. Alle Praxisrollen der Behandlung (BEF-066).';

CREATE FUNCTION public.record_fleet_checkup(p_bike_id uuid, p_items jsonb, p_note text, p_spots jsonb, p_confirmed boolean, p_ad_surfaces text, p_ad_surfaces_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_bike     public.fleet_bikes%rowtype;
  v_keys     text[];
  v_item     jsonb;
  v_items    jsonb := '[]'::jsonb;
  v_i        integer := 0;
  v_rating   text;
  v_spot     jsonb;
  v_check    text;
  v_need     text;
  v_id       uuid;
  v_spots    jsonb;
  v_ad_note  text;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  if p_confirmed is distinct from true then
    raise exception 'checkup must be confirmed' using errcode = '22023';
  end if;

  select b.* into v_bike
  from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null;
  if v_bike.id is null then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;

  -- ANN-568: abgewischt - oder der Grund, warum nicht.
  if p_ad_surfaces is null or p_ad_surfaces not in ('wiped', 'not_possible') then
    raise exception 'ad surfaces must be wiped or explained' using errcode = '22023';
  end if;
  v_ad_note := app.fleet_text(p_ad_surfaces_note, 200, 'ad surfaces reason');
  if p_ad_surfaces = 'wiped' then
    v_ad_note := null;
  elsif v_ad_note is null then
    raise exception 'ad surfaces reason is required' using errcode = '22023';
  end if;

  v_keys := app.fleet_check_items(v_bike.bike_type);
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) <> cardinality(v_keys) then
    raise exception 'checkup needs every check item' using errcode = '22023';
  end if;
  for v_item in select e from jsonb_array_elements(p_items) e
  loop
    v_i := v_i + 1;
    if jsonb_typeof(v_item) <> 'object' or (v_item ->> 'key') is distinct from v_keys[v_i] then
      raise exception 'check items out of order' using errcode = '22023';
    end if;
    v_rating := v_item ->> 'rating';
    if v_rating is null or v_rating not in ('ok', 'beobachten', 'problem') then
      raise exception 'unknown rating' using errcode = '22023';
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', v_keys[v_i],
      'rating', v_rating,
      'note', app.fleet_text(v_item ->> 'note', 300, 'item note')
    ));
  end loop;

  -- Anheben, nie absenken: Jede Stelle mit Pruefpunkt verlangt mindestens
  -- ihre Einstufung an diesem Pruefpunkt.
  if p_spots is not null and jsonb_typeof(p_spots) = 'array' then
    for v_spot in select e from jsonb_array_elements(p_spots) e
    loop
      v_check := app.fleet_zone_check_item(v_bike.bike_type, v_spot ->> 'zone');
      continue when v_check is null;
      v_need := v_spot ->> 'severity';
      select x ->> 'rating' into v_rating
      from jsonb_array_elements(v_items) x where x ->> 'key' = v_check;
      if (v_need = 'problem' and v_rating <> 'problem')
         or (v_need = 'beobachten' and v_rating = 'ok') then
        raise exception 'a spot raises its check item' using errcode = '22023';
      end if;
    end loop;
  end if;

  insert into public.fleet_checkups (
    organization_id, bike_id, bike_type, items, note, checked_by, ad_surfaces, ad_surfaces_note
  )
  values (v_org, v_bike.id, v_bike.bike_type, v_items, app.fleet_text(p_note, 1000, 'note'),
          auth.uid(), p_ad_surfaces, v_ad_note)
  returning id into v_id;

  v_spots := app.fleet_insert_spots(v_org, v_bike, v_id, null, coalesce(p_spots, '[]'::jsonb));

  return jsonb_build_object('checkup_id', v_id, 'spot_ids', v_spots);
end;
$$;

COMMENT ON FUNCTION public.record_fleet_checkup(p_bike_id uuid, p_items jsonb, p_note text, p_spots jsonb, p_confirmed boolean, p_ad_surfaces text, p_ad_surfaces_note text) IS 'FLT-001, FLT-007: Check-Up erfassen - alle Pruefpunkte der Bauart in ihrer Reihenfolge, Notiz, Stellen am Rad, Werbeflaechen abgewischt oder der Grund (ANN-568), Bestaetigung der angemeldeten Person (ANN-553). Eine Stelle hebt ihren Pruefpunkt an, nie ab (ANN-555). Sperrt das Rad nicht. Alle Praxisrollen der Behandlung (BEF-066).';

CREATE FUNCTION public.record_fleet_photo_verification(p_photo_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_foto public.fleet_photos%rowtype;
begin
  if p_content_type_ok is null or p_checksum_ok is null or p_metadata_ok is null then
    raise exception 'incomplete verification result' using errcode = '22023';
  end if;

  select f.* into v_foto from public.fleet_photos f where f.id = p_photo_id for update;
  if not found then
    return 'not_found';
  end if;
  if v_foto.verified_at is not null then
    return 'already_verified';
  end if;
  if v_foto.status <> 'ready' and v_foto.confirmation_requested_at is null then
    return 'not_confirmed';
  end if;

  if p_content_type_ok and p_checksum_ok and p_metadata_ok then
    update public.fleet_photos
       set verified_at = now(),
           status = 'ready',
           confirmed_at = coalesce(confirmed_at, now())
     where id = p_photo_id;
    return 'passed';
  end if;

  -- Punkt 52: Befund heisst verwerfen; der Trigger schreibt den Loeschauftrag,
  -- das Loeschjournal haelt es ueber eine Wiederherstellung (Punkt 26).
  delete from public.fleet_photos where id = p_photo_id;
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  values (v_foto.organization_id, extensions.gen_random_uuid(), 'fleet_photos', v_foto.id,
          'radflotte_ereignis', now());
  return 'rejected';
end;
$$;

COMMENT ON FUNCTION public.record_fleet_photo_verification(p_photo_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) IS 'FLT-002 (ADR-017 Punkte 49 bis 52, ANN-552): Ergebnis der Pruefung am Inhalt - Typ an der Signatur, Pruefsumme, keine Metadaten. Bestanden: geprueft und ready. Befund: verworfen mit Loeschauftrag. Nur fuer den Dienst.';

CREATE FUNCTION public.record_message_attachment_verification(p_attachment_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean, p_no_audio_ok boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.platform_message_attachments%rowtype;
begin
  if p_content_type_ok is null or p_checksum_ok is null or p_metadata_ok is null
     or p_no_audio_ok is null then
    raise exception 'incomplete verification result' using errcode = '22023';
  end if;

  select x.* into v_anhang
  from public.platform_message_attachments x
  where x.id = p_attachment_id
  for update;
  if not found then
    return 'not_found';
  end if;
  if v_anhang.verified_at is not null then
    return 'already_verified';
  end if;
  if v_anhang.status <> 'ready' and v_anhang.confirmation_requested_at is null then
    return 'not_confirmed';
  end if;

  if p_content_type_ok and p_checksum_ok and p_metadata_ok and p_no_audio_ok then
    update public.platform_message_attachments
       set verified_at = now(),
           -- Ohne scharfe Virenpruefung ist der Anhang damit fertig; mit ihr
           -- wartet er auf deren Ergebnis (Punkt 69).
           status = case when app.message_attachment_scan_required() then status else 'ready' end,
           confirmed_at = case when app.message_attachment_scan_required() then confirmed_at
                               else coalesce(confirmed_at, now()) end
     where id = p_attachment_id;
    return 'passed';
  end if;

  -- Punkt 52: Befund heisst verwerfen. Unter Legal Hold gesperrt statt
  -- geloescht (ANN-335). Kein Auditeintrag (ANN-334).
  perform app.remove_message_attachments(
    v_anhang.organization_id, 'attachment', v_anhang.id, extensions.gen_random_uuid());
  return 'rejected';
end;
$$;

COMMENT ON FUNCTION public.record_message_attachment_verification(p_attachment_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean, p_no_audio_ok boolean) IS 'KOM-005 (ADR-017 Punkte 49 bis 52, 63): Ergebnis der Pruefung am Inhalt - Typ an der Signatur, Pruefsumme, keine Metadaten, keine Tonspur. Bestanden: geprueft und, ohne scharfe Virenpruefung, ready. Befund: verworfen mit Loeschjournal und Loeschauftrag. Nur fuer den Dienst.';

CREATE FUNCTION public.record_no_show(p_appointment_id uuid, p_expected_updated_at timestamp with time zone, p_protocol_confirmed boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_alt      record;
  v_protokoll boolean;
  v_anlass   text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_record_no_show() then
    raise exception 'not allowed to record no-shows' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record no-shows' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.staff_member_id, a.status, a.kind, a.occasion,
         a.appointment_type, a.updated_at
    into v_alt
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_alt.kind = 'internal' then
    raise exception 'event cannot be recorded as no-show' using errcode = '22023';
  end if;

  if v_alt.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be recorded as no-show' using errcode = '22023';
  end if;

  if v_alt.status = 'no_show' then
    raise exception 'appointment is already recorded as no-show' using errcode = '22023';
  end if;

  if v_alt.status <> 'confirmed' then
    raise exception 'completed appointment must be reopened first' using errcode = '22023';
  end if;

  -- Wo dokumentiert wurde, hat eine Behandlung stattgefunden. Der Vermerk
  -- waere ein Widerspruch zum Nachweis - und wuerde die Invariante aus
  -- ADR-018 Punkt 3 aushebeln.
  if exists (
    select 1 from public.treatment_notes t where t.appointment_id = p_appointment_id
  ) then
    raise exception 'documented appointment cannot be recorded as no-show' using errcode = '22023';
  end if;

  -- ERN-011 (ANN-664): An der Ernaehrungsberatung Vermerk ja, Forderung nein.
  if v_alt.kind <> 'therapy' or v_alt.occasion <> 'regular' then
    -- Der Trainingstermin: Vermerk ja, Forderung nein. Das Protokoll aus
    -- ANN-055 traegt den Anlass; ohne Anlass hat es nichts zu bestaetigen.
    if p_protocol_confirmed is true then
      raise exception 'no-show protocol applies to treatment appointments only'
        using errcode = '22023';
    end if;
    v_protokoll := false;
    v_anlass    := null;

  -- Das Protokoll ist ein Hausbesuchsprotokoll (ANN-055). An der Praxistuer
  -- gibt es nichts zu klingeln, und eine Bestaetigung, die niemand geben
  -- kann, waere hier die Grundlage einer Forderung.
  elsif v_alt.appointment_type = 'home_visit' then
    if p_protocol_confirmed is not true then
      raise exception 'no-show protocol must be confirmed for home visits'
        using errcode = '22023';
    end if;
    v_protokoll := true;
    v_anlass    := 'no_show';
  else
    if p_protocol_confirmed is true then
      raise exception 'no-show protocol applies to home visits only'
        using errcode = '22023';
    end if;
    v_protokoll := false;
    v_anlass    := null;
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  update public.appointments
     set status                    = 'no_show',
         no_show_recorded_at       = now(),
         no_show_recorded_by       = v_actor,
         no_show_protocol_confirmed = v_protokoll,
         fee_basis                 = v_anlass,
         updated_at                = now()
   where id = p_appointment_id
     and updated_at = p_expected_updated_at
     and status = 'confirmed';

  if not found then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;


  return p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.record_no_show(p_appointment_id uuid, p_expected_updated_at timestamp with time zone, p_protocol_confirmed boolean) IS 'Vermerkt einen bestaetigten Behandlungstermin als nicht angetroffen. Am Hausbesuch nur mit bestaetigtem Protokoll (15 Minuten, Klingeln, Anruf) und setzt dann fee_basis = no_show serverseitig; an Praxis- und Videoterminen bleibt der Vermerk ohne Gebuehr (ANN-055). An einem Ereignis nicht moeglich. Protokolliert appointment.no_show (CAL-018, ADR-018 Fassung 3 Punkt 9).';

CREATE FUNCTION public.record_nutrition_consent(p_profile_id uuid, p_record_kind text, p_occurred_on date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_letzte public.nutrition_consent_records%rowtype;
  v_zeit   timestamptz;
  v_id     uuid;
begin
  -- Erteilen und Widerrufen gehen ohne bestehende Einwilligung.
  v_profil := app.nutrition_profile_for_writing(p_profile_id, false);
  if p_record_kind is null or p_record_kind not in ('consent_granted', 'consent_withdrawn') then
    raise exception 'unknown record kind' using errcode = '22023';
  end if;
  if p_occurred_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;
  if p_occurred_on > app.training_today(v_profil.organization_id) then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;

  v_letzte := app.nutrition_consent(v_profil.id);
  if p_record_kind = 'consent_granted' and v_letzte.record_kind is not distinct from 'consent_granted' then
    raise exception 'consent already granted' using errcode = '23514';
  end if;
  if p_record_kind = 'consent_withdrawn' then
    if v_letzte.record_kind is distinct from 'consent_granted' then
      raise exception 'no consent to withdraw' using errcode = '23514';
    end if;
    if p_occurred_on < v_letzte.occurred_on then
      raise exception 'withdrawal before consent' using errcode = '22023';
    end if;
  end if;
  -- Der Nachweis bleibt zeitlich geordnet (Art. 7 Abs. 1 DSGVO): Eine erneut
  -- erteilte Einwilligung liegt nicht vor dem Widerruf, den sie aufhebt.
  if p_record_kind = 'consent_granted' and p_occurred_on < v_letzte.occurred_on then
    raise exception 'consent before withdrawal' using errcode = '22023';
  end if;

  -- Der jüngste Vermerk, auch neben einem gleichzeitigen (wie POR-016).
  select greatest(now(), max(r.recorded_at) + interval '1 microsecond') into v_zeit
  from public.nutrition_consent_records r where r.profile_id = v_profil.id;

  insert into public.nutrition_consent_records (
    organization_id, profile_id, record_kind, occurred_on, recorded_at, recorded_by
  )
  values (v_profil.organization_id, v_profil.id, p_record_kind, p_occurred_on,
          coalesce(v_zeit, now()), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_nutrition_consent(p_profile_id uuid, p_record_kind text, p_occurred_on date) IS 'ERN-001 (ADR-027 Punkt 3): Einwilligung "Ernährungsberatung" vom Papier erneut vermerken oder ihren Widerruf - an einem laufenden Profil. Der Nachweis steht am Datensatz, kein Auditeintrag (ADR-010 Fassung 3). Allein app.can_counsel_nutrition.';

CREATE FUNCTION public.record_nutrition_weight(p_profile_id uuid, p_measured_on date, p_weight_kg numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  v_profil := app.nutrition_profile_for_writing(p_profile_id, true);
  if p_measured_on is null or p_weight_kg is null then
    raise exception 'date and weight are required' using errcode = '22023';
  end if;
  if p_measured_on > app.training_today(v_profil.organization_id) then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;
  if p_measured_on < v_profil.started_on then
    raise exception 'date before the profile' using errcode = '22023';
  end if;

  insert into public.nutrition_weight_entries (
    organization_id, profile_id, measured_on, weight_kg, source, recorded_by
  )
  values (v_profil.organization_id, v_profil.id, p_measured_on, p_weight_kg, 'practice', auth.uid())
  on conflict (profile_id, measured_on) do update
     set weight_kg = excluded.weight_kg,
         source = 'practice',
         platform_access_id = null,
         platform_access_kind = null,
         recorded_at = now(),
         recorded_by = excluded.recorded_by;
end;
$$;

COMMENT ON FUNCTION public.record_nutrition_weight(p_profile_id uuid, p_measured_on date, p_weight_kg numeric) IS 'ERN-001 (ADR-027 Punkt 5): Gewicht durch die Beratung, eines je Tag - ein zweiter Eintrag am selben Tag ersetzt den ersten. Nicht in der Zukunft, nicht vor dem Profil. Laufendes Profil mit Einwilligung, allein app.can_counsel_nutrition.';

CREATE FUNCTION public.record_patient_file_verification(p_file_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_datei record;
begin
  if p_content_type_ok is null or p_checksum_ok is null then
    raise exception 'incomplete verification result' using errcode = '22023';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
  for update;

  if not found then
    return 'not_found';
  end if;

  -- Einmal geprueft bleibt geprueft: Ein zweiter Lauf aendert nichts.
  if v_datei.verified_at is not null then
    return 'already_verified';
  end if;

  if v_datei.status <> 'ready' and v_datei.confirmation_requested_at is null then
    return 'not_confirmed';
  end if;

  -- Bilder bekommen ein Metadatenergebnis, PDF nicht (Punkt 49).
  if (v_datei.mime_type in ('image/jpeg', 'image/png')) <> (p_metadata_ok is not null) then
    raise exception 'metadata result does not match the media type' using errcode = '22023';
  end if;

  if p_content_type_ok and p_checksum_ok and coalesce(p_metadata_ok, true) then
    update public.patient_files
       set verified_at           = now(),
           content_type_verified = true,
           checksum_verified     = true,
           metadata_verified     = p_metadata_ok,
           status                = 'ready',
           confirmed_at          = coalesce(confirmed_at, now())
     where id = p_file_id;
    return 'passed';
  end if;

  -- Zweitreview Befund 2: Eine Datei unter Legal Hold wird nie verworfen,
  -- auch nicht nach Befund (ADR-017 Punkt 24, ANN-033). Der Befund steht im
  -- Protokoll; die Datei bleibt ungeprueft.
  if app.under_legal_hold(v_datei.organization_id, 'patient', v_datei.patient_id) then
    insert into public.audit_log (
      organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
    )
    values (
      v_datei.organization_id, null, 'system', 'access.denied', 'patient_file',
      p_file_id, 'denied',
      jsonb_build_object(
        'surface', 'edge_function',
        'operation', 'patient_file.verification',
        'patient_id', v_datei.patient_id,
        'document_type', v_datei.document_type,
        'content_type_ok', p_content_type_ok,
        'checksum_ok', p_checksum_ok,
        'metadata_ok', p_metadata_ok,
        'was_ready', v_datei.status = 'ready',
        'held', true
      )
    );
    return 'held';
  end if;

  -- Punkt 52: Befund heisst verwerfen. Das Protokoll nennt, welche Pruefung
  -- anschlug - nie Name, Schluessel oder Inhalt (ADR-010 Punkt 3).
  -- ANN-009: ein Ereignis ohne handelnden Account (der Dienst) ist 'system'.
  insert into public.audit_log (
    organization_id, actor_user_id, actor_kind, action, subject_type, subject_id, outcome, context
  )
  values (
    v_datei.organization_id, null, 'system', 'access.denied', 'patient_file', p_file_id,
    'denied',
    jsonb_build_object(
      'surface', 'edge_function',
        'operation', 'patient_file.verification',
      'patient_id', v_datei.patient_id,
      'document_type', v_datei.document_type,
      'content_type_ok', p_content_type_ok,
      'checksum_ok', p_checksum_ok,
      'metadata_ok', p_metadata_ok,
      'was_ready', v_datei.status = 'ready'
    )
  );

  -- Der Trigger an patient_files schreibt den Loeschauftrag fuer das Objekt;
  -- das Loeschjournal haelt die Loeschung ueber eine Wiederherstellung
  -- (BEF-170, ADR-017 Punkt 26).
  delete from public.patient_files where id = p_file_id;
  perform app.journal_patient_file_deletion(v_datei.organization_id, v_datei.id, v_datei.document_type);
  return 'rejected';
end;
$$;

COMMENT ON FUNCTION public.record_patient_file_verification(p_file_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) IS 'Nur fuer den Dienst patient-file-verify (service_role): traegt das Ergebnis der Pruefung am Inhalt ein. Bestanden: verified_at, bei scharfer Pruefung ready. Befund: Zeile verworfen, Loeschauftrag fuer das Objekt, Eintrag im Loeschjournal (BEF-170) und access.denied mit operation patient_file.verification; unter Legal Hold bleibt die Datei (ADR-017 Punkte 24, 49 bis 52).';

CREATE FUNCTION public.record_patient_privacy_entry(p_patient_id uuid, p_record_kind text, p_purpose text, p_notice_version text, p_occurred_on date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_zone     text;
  v_letzte   record;
  v_id       uuid;
  v_zeit     timestamptz;
  v_fotos    integer := 0;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_update_patient() then
    raise exception 'not allowed to record privacy entries' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record privacy entries' using errcode = '42501';
  end if;

  -- Eine fremde Akte und eine nicht vorhandene sehen gleich aus (ADR-003).
  perform 1
  from public.patients p
  where p.id = p_patient_id and p.organization_id = v_org
  for update;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  if p_occurred_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;

  select o.time_zone into v_zone from public.organizations o where o.id = v_org;
  if p_occurred_on > (now() at time zone coalesce(v_zone, 'Europe/Berlin'))::date then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;

  -- KOM-005 (ADR-017 Punkt 61, ANN-333): Die Einwilligung zu Anhaengen an
  -- Rueckfragen erteilt die Person auf der Plattform, wenn sie zum ersten Mal
  -- etwas anhaengen will. Die Praxis vermerkt nur den Widerruf vom Papier.
  if p_purpose = 'message_attachments' and p_record_kind <> 'consent_withdrawn' then
    raise exception 'this consent is given on the platform' using errcode = '22023';
  end if;

  if p_record_kind in ('consent_granted', 'consent_withdrawn', 'consent_refused') then
    select r.record_kind, r.occurred_on
      into v_letzte
    from public.patient_privacy_records r
    where r.patient_id = p_patient_id
      and r.purpose = p_purpose
    order by r.recorded_at desc, r.id desc
    limit 1;

    if p_record_kind = 'consent_granted'
       and v_letzte.record_kind is not distinct from 'consent_granted' then
      raise exception 'consent already granted' using errcode = '23514';
    end if;

    if p_record_kind = 'consent_withdrawn' then
      if v_letzte.record_kind is distinct from 'consent_granted' then
        raise exception 'no consent to withdraw' using errcode = '23514';
      end if;
      if p_occurred_on < v_letzte.occurred_on then
        raise exception 'withdrawal before consent' using errcode = '22023';
      end if;
    end if;

    -- Punkt 35: Eine Ablehnung ist ein eigener Vermerk, kein Widerruf. Wer
    -- eingewilligt hat, widerruft; zweimal hintereinander abgelehnt ist
    -- nichts Neues.
    if p_record_kind = 'consent_refused' then
      if v_letzte.record_kind is not distinct from 'consent_granted' then
        raise exception 'consent is granted, record a withdrawal' using errcode = '23514';
      end if;
      if v_letzte.record_kind is not distinct from 'consent_refused' then
        raise exception 'consent already refused' using errcode = '23514';
      end if;
    end if;
  end if;

  -- Wertebereich und Form pruefen die Constraints der Tabelle.
  -- POR-016 (Zweitreview): Der neue Vermerk ist der juengste, auch wenn
  -- ein gleichzeitiger Aufruf spaeter begann und vorher schrieb.
  select greatest(now(), max(r.recorded_at) + interval '1 microsecond') into v_zeit
  from public.patient_privacy_records r
  where r.patient_id = p_patient_id;
  v_zeit := coalesce(v_zeit, now());

  insert into public.patient_privacy_records (
    organization_id, patient_id, record_kind, purpose, notice_version,
    occurred_on, recorded_by, recorded_at
  )
  values (
    v_org, p_patient_id, p_record_kind, p_purpose, p_notice_version,
    p_occurred_on, v_actor, v_zeit
  )
  returning id into v_id;

  -- Punkt 36: Der Widerruf der Fotoeinwilligung sperrt sofort und loescht in
  -- derselben Transaktion - Zeilen, Loeschauftraege, Loeschjournal. Unter
  -- Legal Hold bleiben die Fotos gesperrt stehen (release_legal_hold).
  if p_record_kind = 'consent_withdrawn' and p_purpose = 'patient_photos' then
    v_fotos := app.delete_due_patient_photos(
      v_org, p_patient_id, extensions.gen_random_uuid(), v_actor, 'consent_withdrawn'
    );
  end if;

  -- KOM-005 (Punkt 61): Der Widerruf zu Anhaengen loescht sofort alle
  -- Anhaenge der Akte, auch vom Papier vermerkt.
  if p_record_kind = 'consent_withdrawn' and p_purpose = 'message_attachments' then
    perform app.remove_message_attachments(
      v_org, 'relationship', p_patient_id, extensions.gen_random_uuid());
  end if;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_patient_privacy_entry(p_patient_id uuid, p_record_kind text, p_purpose text, p_notice_version text, p_occurred_on date) IS 'Vermerkt Aushaendigung der Datenschutzinformation, Unterschrift des Behandlungsvertrags oder Erteilung/Widerruf einer Einwilligung je Zweck (PAT-006, ANN-093). Nur anhaengen; jeder Vermerk als patient_privacy.recorded protokolliert.';

CREATE FUNCTION public.record_payment(p_invoice_id uuid, p_amount_cents integer, p_paid_on date, p_method text, p_direction text DEFAULT 'incoming'::text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor     uuid;
  v_org       uuid;
  v_invoice   record;
  v_zeitzone  text;
  v_heute     date;
  v_eingang   integer;
  v_rueck     integer;
  v_id        uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.* into v_invoice
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  if v_invoice.status <> 'issued' then
    raise exception 'a payment belongs to an issued invoice' using errcode = '23514';
  end if;

  -- Eine stornierte Rechnung ist keine Forderung mehr und nimmt keinen
  -- Eingang an. Seit ABN-008 (BEF-100) nimmt sie eine RUECKZAHLUNG an: Der
  -- vor dem Storno eingegangene Betrag geht tatsaechlich zurueck. Die
  -- Verrechnung mit der Ersatzrechnung laeuft ueber offset_payment.
  if coalesce(p_direction, 'incoming') = 'incoming' and exists (
    select 1 from public.invoice_cancellations c where c.invoice_id = p_invoice_id
  ) then
    raise exception 'a cancelled invoice takes no payment' using errcode = '23514';
  end if;

  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'a payment needs a positive amount' using errcode = '22023';
  end if;

  if p_direction is null or p_direction not in ('incoming', 'refund') then
    raise exception 'unknown payment direction' using errcode = '22023';
  end if;

  if p_method is null or p_method not in ('bank_transfer', 'other') then
    raise exception 'unknown payment method' using errcode = '22023';
  end if;

  select o.time_zone into v_zeitzone from public.organizations o where o.id = v_org;
  v_heute := (now() at time zone v_zeitzone)::date;

  -- Kein Datum in der Zukunft: Eine Zahlung wird erfasst, wenn sie da ist,
  -- nicht wenn sie erwartet wird. Ein erwarteter Eingang ist ein offener
  -- Posten, und den fuehrt die Rechnung selbst.
  if p_paid_on is null or p_paid_on > v_heute then
    raise exception 'a payment cannot be dated in the future' using errcode = '22023';
  end if;

  -- Rueckgezahlt werden kann hoechstens, was eingegangen ist. Ueberzahlung
  -- dagegen bleibt erlaubt: ADR-009 nennt sie ausdruecklich (Konsequenz zu
  -- Punkt 12), und eine Rechnung, die zu viel Geld bekommen hat, ist ein
  -- Sachverhalt und kein Eingabefehler.
  if p_direction = 'refund' then
    select coalesce(sum(case when p.direction = 'incoming' then p.amount_cents else 0 end), 0),
           coalesce(sum(case when p.direction = 'refund'   then p.amount_cents else 0 end), 0)
      into v_eingang, v_rueck
    from public.payments p
    where p.invoice_id = p_invoice_id and p.voided_at is null;

    if v_rueck + p_amount_cents > v_eingang then
      raise exception 'a refund cannot exceed the payments received'
        using errcode = '23514';
    end if;
  end if;

  insert into public.payments (
    organization_id, invoice_id, direction, amount_cents, currency,
    paid_on, method, note, created_by
  )
  values (
    v_org, p_invoice_id, p_direction, p_amount_cents, v_invoice.currency,
    p_paid_on, p_method, nullif(btrim(coalesce(p_note, '')), ''), v_actor
  )
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_payment(p_invoice_id uuid, p_amount_cents integer, p_paid_on date, p_method text, p_direction text, p_note text) IS 'Erfasst einen Zahlungseingang oder eine Rueckzahlung zu einer ausgestellten, nicht stornierten Rechnung (ABR-004, ADR-009 Punkt 12, R3-004). Teilzahlung und Ueberzahlung sind erlaubt; eine Rueckzahlung darf die eingegangene Summe nicht uebersteigen.';

CREATE FUNCTION public.record_platform_consent(p_access_id uuid, p_purpose text, p_grant boolean, p_wording_version text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_zone    text;
  v_heute   date;
  v_letzte  text;
  v_zeit    timestamptz;
  v_art     text;
  v_name    text;
  v_id      uuid;
begin
  if p_grant is null then
    raise exception 'grant or withdraw' using errcode = '22023';
  end if;
  -- Erteilen nur mit dem Recht consent (Person, rechtliche Vertretung, in der
  -- Lesezeit); widerrufen zusaetzlich die Person selbst nach der Lesefrist.
  if not (app.platform_access_allows(p_access_id, 'consent')
          or (not p_grant and app.platform_own_access_after_reading(p_access_id))) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  if p_purpose is null
     or not (p_purpose = any (app.platform_consent_purposes(v_zugang.relationship_kind))) then
    raise exception 'unknown purpose' using errcode = '22023';
  end if;
  if p_wording_version is distinct from app.platform_consent_wording_version() then
    raise exception 'wording outdated' using errcode = '22023';
  end if;

  -- Gleichzeitige Aufrufe desselben Verhaeltnisses nacheinander: Der Stand,
  -- gegen den geprueft wird, ist der, auf den geschrieben wird.
  if v_zugang.relationship_kind = 'treatment' then
    perform 1 from public.patients p
    where p.id = v_zugang.relationship_id and p.organization_id = v_zugang.organization_id
    for update;
  else
    perform 1 from public.training_relationships t
    where t.id = v_zugang.relationship_id and t.organization_id = v_zugang.organization_id
    for update;
  end if;
  if not found then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;

  if v_zugang.relationship_kind = 'treatment' then
    select r.record_kind into v_letzte
    from public.patient_privacy_records r
    where r.patient_id = v_zugang.relationship_id and r.purpose = p_purpose
    order by r.recorded_at desc, r.id desc
    limit 1;
  else
    select r.record_kind into v_letzte
    from public.training_consent_records r
    where r.training_relationship_id = v_zugang.relationship_id and r.purpose = p_purpose
    order by r.recorded_at desc, r.id desc
    limit 1;
  end if;

  -- Der neue Vermerk ist der juengste, auch wenn ein gleichzeitiger Aufruf
  -- spaeter begann und vorher schrieb (Zweitreview): now(), mindestens aber
  -- eine Mikrosekunde nach dem bisher juengsten.
  if v_zugang.relationship_kind = 'treatment' then
    select greatest(now(), max(r.recorded_at) + interval '1 microsecond') into v_zeit
    from public.patient_privacy_records r where r.patient_id = v_zugang.relationship_id;
  else
    select greatest(now(), max(r.recorded_at) + interval '1 microsecond') into v_zeit
    from public.training_consent_records r
    where r.training_relationship_id = v_zugang.relationship_id;
  end if;
  v_zeit := coalesce(v_zeit, now());

  if p_grant then
    if v_letzte is not distinct from 'consent_granted' then
      raise exception 'consent already granted' using errcode = '23514';
    end if;
    v_art := 'consent_granted';
  else
    if v_letzte is distinct from 'consent_granted' then
      raise exception 'no consent to withdraw' using errcode = '23514';
    end if;
    v_art := 'consent_withdrawn';
  end if;

  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;
  v_heute := (now() at time zone coalesce(v_zone, 'Europe/Berlin'))::date;
  v_name := case when v_zugang.access_kind = 'legal_representative'
                 then v_zugang.representative_name end;

  if v_zugang.relationship_kind = 'treatment' then
    insert into public.patient_privacy_records (
      organization_id, patient_id, record_kind, purpose, occurred_on, recorded_by, recorded_at,
      source, platform_access_id, platform_access_kind, representative_name, wording_version
    )
    values (
      v_zugang.organization_id, v_zugang.relationship_id, v_art, p_purpose, v_heute, auth.uid(),
      v_zeit,
      'platform', v_zugang.id, v_zugang.access_kind, v_name, p_wording_version
    )
    returning id into v_id;

    -- ADR-017 Punkt 36: Der Widerruf der Fotoeinwilligung loescht sofort.
    if v_art = 'consent_withdrawn' and p_purpose = 'patient_photos' then
      perform app.delete_due_patient_photos(
        v_zugang.organization_id, v_zugang.relationship_id, extensions.gen_random_uuid(),
        auth.uid(), 'consent_withdrawn'
      );
    end if;
  else
    insert into public.training_consent_records (
      organization_id, training_relationship_id, record_kind, purpose, occurred_on, recorded_by,
      recorded_at, source, platform_access_id, platform_access_kind, representative_name,
      wording_version
    )
    values (
      v_zugang.organization_id, v_zugang.relationship_id, v_art, p_purpose, v_heute, auth.uid(),
      v_zeit,
      'platform', v_zugang.id, v_zugang.access_kind, v_name, p_wording_version
    )
    returning id into v_id;
  end if;

  -- KOM-005 (ADR-017 Punkt 61): Der Widerruf der Einwilligung zu Anhaengen
  -- loescht sofort alle Anhaenge des Verhaeltnisses, in derselben
  -- Transaktion, mit Loeschjournal und Loeschauftraegen; unter Legal Hold
  -- gesperrt (ANN-335).
  if v_art = 'consent_withdrawn' and p_purpose = 'message_attachments' then
    perform app.remove_message_attachments(
      v_zugang.organization_id, 'relationship', v_zugang.relationship_id,
      extensions.gen_random_uuid());
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read',
    jsonb_build_object('view', case when p_grant then 'consent_granted' else 'consent_withdrawn' end)
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_platform_consent(p_access_id uuid, p_purpose text, p_grant boolean, p_wording_version text) IS 'POR-016/017, KOM-005: Einwilligung erteilen oder widerrufen ueber die Plattform (ADR-023 Punkt 13), Behandlung und Training. Recht consent; widerrufen auch die Person selbst nach der Lesefrist (ANN-261). Zeile mit Herkunft und Textfassung (ANN-262); Widerruf der Fotos loescht sofort (ADR-017 Punkt 36), ebenso der Widerruf zu Anhaengen an Rueckfragen (Punkt 61).';

CREATE FUNCTION public.record_platform_nutrition_consent(p_access_id uuid, p_grant boolean, p_wording_version text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_profil public.nutrition_profiles%rowtype;
  v_letzte public.nutrition_consent_records%rowtype;
  v_zeit   timestamptz;
  v_id     uuid;
begin
  -- Erst der Zugang, dann die Eingabe. Erteilen mit dem Recht nutrition in
  -- der Lesezeit; widerrufen zusätzlich die Person selbst nach der Lesefrist
  -- (ANN-261). Ohne Angabe gilt die schwächste Bedingung, die des Widerrufs.
  if not ((app.platform_access_allows(p_access_id, 'nutrition')
           and (not coalesce(p_grant, false) or app.platform_access_writable(p_access_id)))
          or (not coalesce(p_grant, false)
              and app.platform_own_access_after_reading(p_access_id))) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  if p_grant is null then
    raise exception 'grant or withdraw' using errcode = '22023';
  end if;
  if p_wording_version is distinct from app.platform_consent_wording_version() then
    raise exception 'wording outdated' using errcode = '22023';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  select p.* into v_profil
  from public.nutrition_profiles p
  where p.id = (app.platform_nutrition_profile(p_access_id)).id
  for update;
  if v_profil.id is null then
    raise exception 'nutrition profile not found' using errcode = 'P0002';
  end if;

  v_letzte := app.nutrition_consent(v_profil.id);
  if p_grant and v_letzte.record_kind is not distinct from 'consent_granted' then
    raise exception 'consent already granted' using errcode = '23514';
  end if;
  if not p_grant and v_letzte.record_kind is distinct from 'consent_granted' then
    raise exception 'no consent to withdraw' using errcode = '23514';
  end if;

  select greatest(now(), max(r.recorded_at) + interval '1 microsecond') into v_zeit
  from public.nutrition_consent_records r where r.profile_id = v_profil.id;

  insert into public.nutrition_consent_records (
    organization_id, profile_id, record_kind, occurred_on, recorded_at, recorded_by,
    source, platform_access_id, platform_access_kind, representative_name, wording_version
  )
  values (
    v_profil.organization_id, v_profil.id,
    case when p_grant then 'consent_granted' else 'consent_withdrawn' end,
    app.training_today(v_profil.organization_id), coalesce(v_zeit, now()), auth.uid(),
    'platform', v_zugang.id, v_zugang.access_kind,
    case when v_zugang.access_kind = 'legal_representative' then v_zugang.representative_name end,
    p_wording_version
  )
  returning id into v_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read',
    jsonb_build_object('view', case when p_grant then 'consent_granted' else 'consent_withdrawn' end)
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_platform_nutrition_consent(p_access_id uuid, p_grant boolean, p_wording_version text) IS 'ERN-002 (ADR-027 Punkt 3, ADR-023 Punkt 13): die Person oder ihre rechtliche Vertretung erteilt oder widerruft die Einwilligung "Ernährungsberatung" am laufenden Profil; widerrufen auch die Person selbst nach der Lesefrist (ANN-261). Zeile mit Herkunft und Textfassung (ANN-262); nie die Begleitung. Ein Widerruf hält Tagebuch und Gewicht an.';

CREATE FUNCTION public.record_platform_nutrition_weight(p_access_id uuid, p_measured_on date, p_weight_kg numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_zugang public.platform_accesses%rowtype;
begin
  v_profil := app.platform_nutrition_for_writing(p_access_id, true);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if p_measured_on is null or p_weight_kg is null then
    raise exception 'date and weight are required' using errcode = '22023';
  end if;
  if p_measured_on > app.training_today(v_profil.organization_id) then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;
  if p_measured_on < v_profil.started_on then
    raise exception 'date before the profile' using errcode = '22023';
  end if;

  -- ANN-621: eines je Tag; der jüngste Eintrag des Tages gilt, gleich ob von
  -- der Person oder der Beratung - wer, steht am Eintrag.
  insert into public.nutrition_weight_entries (
    organization_id, profile_id, measured_on, weight_kg, source, platform_access_id,
    platform_access_kind, recorded_by
  )
  values (
    v_profil.organization_id, v_profil.id, p_measured_on, p_weight_kg, 'platform', v_zugang.id,
    v_zugang.access_kind, auth.uid()
  )
  on conflict (profile_id, measured_on) do update
     set weight_kg = excluded.weight_kg,
         source = 'platform',
         platform_access_id = excluded.platform_access_id,
         platform_access_kind = excluded.platform_access_kind,
         recorded_at = now(),
         recorded_by = excluded.recorded_by;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_weight')
  );
end;
$$;

COMMENT ON FUNCTION public.record_platform_nutrition_weight(p_access_id uuid, p_measured_on date, p_weight_kg numeric) IS 'ERN-002 (ADR-027 Punkt 5, ANN-621): die Person oder ihre rechtliche Vertretung trägt ihr Gewicht ein, eines je Tag; nicht in der Zukunft, nicht vor der Beratung. Laufendes Profil mit Einwilligung, nicht in der Lesefrist (42501).';

CREATE FUNCTION public.record_reimbursement_receipt_verification(p_receipt_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_beleg public.staff_reimbursement_receipts%rowtype;
begin
  if p_content_type_ok is null or p_checksum_ok is null then
    raise exception 'incomplete verification result' using errcode = '22023';
  end if;

  select b.* into v_beleg from public.staff_reimbursement_receipts b
   where b.id = p_receipt_id for update;
  -- Ein zugeordneter Beleg wird nicht mehr geprüft: Er hängt an einem Antrag.
  if not found or v_beleg.reimbursement_id is not null then
    return 'not_found';
  end if;
  if v_beleg.verified_at is not null then
    return 'already_verified';
  end if;
  if v_beleg.status <> 'ready' and v_beleg.confirmation_requested_at is null then
    return 'not_confirmed';
  end if;
  -- Bilder bekommen ein Metadatenergebnis, PDF nicht (Punkt 49).
  if (v_beleg.mime_type in ('image/jpeg', 'image/png')) <> (p_metadata_ok is not null) then
    raise exception 'metadata result does not match the media type' using errcode = '22023';
  end if;

  if p_content_type_ok and p_checksum_ok and coalesce(p_metadata_ok, true) then
    update public.staff_reimbursement_receipts
       set verified_at = now(),
           status = 'ready',
           confirmed_at = coalesce(confirmed_at, now())
     where id = p_receipt_id;
    return 'passed';
  end if;

  -- Punkt 52: Befund heißt verwerfen; der Trigger schreibt den Löschauftrag,
  -- das Journal hält es über eine Wiederherstellung (Punkt 26).
  delete from public.staff_reimbursement_receipts where id = p_receipt_id;
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  values (v_beleg.organization_id, extensions.gen_random_uuid(), 'staff_reimbursement_receipts',
          v_beleg.id, 'erstattung', now());
  return 'rejected';
end;
$$;

COMMENT ON FUNCTION public.record_reimbursement_receipt_verification(p_receipt_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) IS 'ERS-001 (ADR-017 Punkte 49 bis 52, ANN-600): Ergebnis der Prüfung am Inhalt eines Belegs ohne Antrag - Typ an der Signatur, Prüfsumme, bei Bildern keine Metadaten. Bestanden: geprüft und ready. Befund: verworfen mit Löschauftrag. Nur für den Dienst.';

CREATE FUNCTION public.record_team_attachment_verification(p_attachment_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anhang public.team_message_attachments%rowtype;
begin
  if p_content_type_ok is null or p_checksum_ok is null then
    raise exception 'incomplete verification result' using errcode = '22023';
  end if;

  select a.* into v_anhang from public.team_message_attachments a
   where a.id = p_attachment_id for update;
  -- Ein gesendeter Anhang wird nicht mehr geprüft: Er hängt an der Nachricht.
  if not found or v_anhang.message_id is not null then
    return 'not_found';
  end if;
  if v_anhang.verified_at is not null then
    return 'already_verified';
  end if;
  if v_anhang.status <> 'ready' and v_anhang.confirmation_requested_at is null then
    return 'not_confirmed';
  end if;
  -- Bilder und Sprachnachrichten bekommen ein Metadatenergebnis, PDF nicht
  -- (Punkte 49 und 84).
  if (v_anhang.mime_type in ('image/jpeg', 'image/png', 'audio/webm', 'audio/mp4'))
     <> (p_metadata_ok is not null) then
    raise exception 'metadata result does not match the media type' using errcode = '22023';
  end if;

  if p_content_type_ok and p_checksum_ok and coalesce(p_metadata_ok, true) then
    update public.team_message_attachments
       set verified_at = now(),
           status = 'ready',
           confirmed_at = coalesce(confirmed_at, now())
     where id = p_attachment_id;
    return 'passed';
  end if;

  -- Punkt 52: Befund heißt verwerfen; der Trigger schreibt den Löschauftrag,
  -- das Journal hält es über eine Wiederherstellung (ADR-008 Punkt 8).
  delete from public.team_message_attachments where id = p_attachment_id;
  -- Tageweise gebündelt wie das Verwerfen von Hand.
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at, deleted_at)
  values (v_anhang.organization_id,
          md5('team_manual:' || v_anhang.organization_id::text || ':' || current_date::text)::uuid,
          'team_message_attachments', p_attachment_id, 'teamchat', date_trunc('day', now()),
          date_trunc('day', now()));
  return 'rejected';
end;
$$;

COMMENT ON FUNCTION public.record_team_attachment_verification(p_attachment_id uuid, p_content_type_ok boolean, p_checksum_ok boolean, p_metadata_ok boolean) IS 'TEAM-003 und TEAM-004 (ADR-017 Punkte 49 bis 52, 73 und 84): Ergebnis der Prüfung am Inhalt eines noch nicht gesendeten Anhangs - Typ an der Signatur bzw. Struktur, Prüfsumme, bei Bildern und Sprachnachrichten keine Metadaten. Bestanden: geprüft und ready. Befund: verworfen mit Löschauftrag und Journal. Nur für den Dienst.';

CREATE FUNCTION public.record_time_account_entry(p_staff_member_id uuid, p_kind text, p_on_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_minutes integer, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_staff    uuid;
  v_andere   boolean;
  v_text     text := nullif(btrim(coalesce(p_note, '')), '');
  v_pruef    jsonb;
  v_problem  text;
  v_id       uuid;
begin
  v_org := app.staff_request_org(app.can_keep_time_account(), 'not allowed to keep a time account');
  v_staff := app.time_account_target(v_org, p_staff_member_id);
  v_andere := v_staff is distinct from app.own_staff_member(v_org);
  if v_text is not null and length(v_text) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  -- Korrekturen buchen owner und Büro; im eigenen Konto nur owner (ANN-594).
  if p_kind = 'correction' and not (app.can_book_time_accounts() and (v_andere or app.has_any_role('owner'))) then
    raise exception 'not allowed to book corrections' using errcode = '42501';
  end if;

  -- Gesperrt wird die Person wie bei Urlaub, Arbeitszeit und Pflege: Zwei
  -- Einträge und eine gleichzeitige Pflege laufen nicht gegeneinander.
  perform 1 from public.staff_members sm where sm.id = v_staff for no key update;

  if p_kind <> 'correction' and (p_starts_at is null or p_ends_at is null) then
    raise exception 'time account rule: times_invalid' using errcode = '22023';
  end if;
  if p_kind = 'correction' and (p_minutes is null or v_text is null) then
    raise exception 'time account rule: correction_invalid' using errcode = '22023';
  end if;
  v_pruef := app.time_account_check(v_org, v_staff, p_kind, p_on_date, p_starts_at, p_ends_at, p_minutes);
  v_problem := case when v_andere then app.time_account_foreign_view(v_pruef, v_org, p_on_date)
                    else v_pruef end -> 'problems' ->> 0;
  if v_problem is not null then
    raise exception 'time account rule: %', v_problem
      using errcode = case
        when v_problem in ('leave', 'absent', 'changed_day') then '55000'
        when v_problem = 'overlaps_entry' then '23P01'
        else '22023'
      end;
  end if;

  begin
    insert into public.staff_time_account_entries (
      organization_id, staff_member_id, kind, on_date, starts_at, ends_at, minutes, note,
      entered_by, entered_for_other
    )
    values (
      v_org, v_staff, p_kind, p_on_date,
      case when p_kind <> 'correction' then p_starts_at end,
      case when p_kind <> 'correction' then p_ends_at end,
      (v_pruef ->> 'minutes')::integer, v_text, auth.uid(), v_andere
    )
    returning id into v_id;
  exception
    when exclusion_violation then
      raise exception 'time account rule: overlaps_entry' using errcode = '23P01';
  end;

  -- Der Freizeitausgleich als Abweichung: die übrigen Blöcke des Tages, oder
  -- der ganze Tag abwesend (ANN-595).
  if p_kind = 'time_off' then
    if jsonb_array_length(v_pruef -> 'remaining') = 0 then
      insert into public.staff_working_hour_exceptions
        (organization_id, staff_member_id, on_date, kind, created_by, time_account_entry_id)
      values (v_org, v_staff, p_on_date, 'unavailable', auth.uid(), v_id);
    else
      insert into public.staff_working_hour_exceptions
        (organization_id, staff_member_id, on_date, kind, starts_at, ends_at, created_by,
         time_account_entry_id)
      select v_org, v_staff, p_on_date, 'block', (b ->> 'von')::time, (b ->> 'bis')::time,
             auth.uid(), v_id
      from jsonb_array_elements(v_pruef -> 'remaining') as b;
    end if;
  end if;

  return jsonb_build_object(
    'id', v_id,
    'minutes', (v_pruef ->> 'minutes')::integer,
    'balance_minutes', app.time_account_balance(v_org, v_staff),
    'appointments', coalesce((v_pruef ->> 'appointments')::integer, 0)
  );
end;
$$;

COMMENT ON FUNCTION public.record_time_account_entry(p_staff_member_id uuid, p_kind text, p_on_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_minutes integer, p_note text) IS 'ZK-001 (ANN-593 bis ANN-595): Mehrarbeit oder Freizeitausgleich mit Datum, Beginn und Ende eintragen - gilt sofort; owner und Büro auch für andere und Korrekturen. Ein Freizeitausgleich wirkt als Abweichung in den Arbeitszeiten. Kein Auditeintrag (ADR-010 Punkt 15).';

CREATE FUNCTION public.record_training_assessment(p_relationship_id uuid, p_title text, p_performed_on date, p_conditions text, p_next_due_on date, p_results jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
  v_id    uuid;
  v_n     integer;
begin
  if v_actor is null or not app.can_write_exercise_plans('training') then
    raise exception 'not allowed to record assessments' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.checkin_relationship('training', p_relationship_id, v_org);
  if v_rel.area is null then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;
  if not v_rel.is_open then
    raise exception 'relationship has ended' using errcode = '22023';
  end if;
  -- ANN-365: Testergebnisse sind Gesundheitsangaben.
  if not app.training_health_consent(p_relationship_id) then
    raise exception 'health data consent missing' using errcode = '42501';
  end if;
  if p_performed_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;
  if p_performed_on > app.training_today(v_org) then
    raise exception 'assessment date in the future' using errcode = '22023';
  end if;
  if p_results is null or jsonb_typeof(p_results) <> 'array' then
    raise exception 'results invalid' using errcode = '22023';
  end if;
  v_n := jsonb_array_length(p_results);
  if v_n not between 1 and 20 then
    raise exception 'results invalid' using errcode = '22023';
  end if;
  -- Jede Messung ist ein Objekt mit Zahlen, wo Zahlen stehen; was sonst
  -- darin steht, faellt weg.
  if exists (
    select 1 from jsonb_array_elements(p_results) r
    where jsonb_typeof(r) <> 'object'
       or coalesce(jsonb_typeof(r -> 'label'), '') <> 'string'
       or (r ? 'unit' and jsonb_typeof(r -> 'unit') not in ('string', 'null'))
       or (r ? 'value' and jsonb_typeof(r -> 'value') not in ('number', 'null'))
       or (r ? 'left' and jsonb_typeof(r -> 'left') not in ('number', 'null'))
       or (r ? 'right' and jsonb_typeof(r -> 'right') not in ('number', 'null'))
  ) then
    raise exception 'results invalid' using errcode = '22023';
  end if;

  -- Titel, Bedingungen, Wiedervorlage pruefen die Constraints der Tabelle.
  insert into public.training_assessments (
    organization_id, training_relationship_id, title, performed_on, conditions, next_due_on,
    created_by
  )
  values (
    v_org, p_relationship_id, btrim(p_title), p_performed_on, nullif(btrim(p_conditions), ''),
    p_next_due_on, v_actor
  )
  returning id into v_id;

  insert into public.training_assessment_results (
    organization_id, assessment_id, position, label, unit, value, value_left, value_right
  )
  select v_org, v_id, r.ordinality::smallint, btrim(r.value ->> 'label'),
         nullif(btrim(r.value ->> 'unit'), ''),
         (r.value ->> 'value')::numeric, (r.value ->> 'left')::numeric,
         (r.value ->> 'right')::numeric
  from jsonb_array_elements(p_results) with ordinality r;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_training_assessment(p_relationship_id uuid, p_title text, p_performed_on date, p_conditions text, p_next_due_on date, p_results jsonb) IS 'OUT-002 (IDEA-OUT-007, ANN-365): haelt ein Assessment im offenen Trainingsverhaeltnis fest - Titel, Tag (nicht in der Zukunft), Messbedingungen, geplante Wiederholung und 1 bis 20 Messungen mit einem Wert oder beiden Seiten. Wer: app.can_write_exercise_plans(training); nur mit Einwilligung zu Gesundheitsangaben. Der Schreibvorgang steht am Datensatz (created_by, ADR-010 Fassung 3).';

CREATE FUNCTION public.record_training_consent_entry(p_training_relationship_id uuid, p_record_kind text, p_occurred_on date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_zone   text;
  v_letzte record;
  v_zeit   timestamptz;
  v_id     uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    raise exception 'not allowed to record training consents' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  perform 1 from public.training_relationships t
  where t.id = p_training_relationship_id and t.organization_id = v_org
  for update;
  if not found then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;

  if p_record_kind is null or p_record_kind not in ('consent_granted', 'consent_withdrawn') then
    raise exception 'unknown record kind' using errcode = '22023';
  end if;
  if p_occurred_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;
  select o.time_zone into v_zone from public.organizations o where o.id = v_org;
  if p_occurred_on > (now() at time zone coalesce(v_zone, 'Europe/Berlin'))::date then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;

  select r.record_kind, r.occurred_on into v_letzte
  from public.training_consent_records r
  where r.training_relationship_id = p_training_relationship_id
    and r.purpose = 'training_health_data'
  order by r.recorded_at desc, r.id desc
  limit 1;

  if p_record_kind = 'consent_granted'
     and v_letzte.record_kind is not distinct from 'consent_granted' then
    raise exception 'consent already granted' using errcode = '23514';
  end if;
  if p_record_kind = 'consent_withdrawn' then
    if v_letzte.record_kind is distinct from 'consent_granted' then
      raise exception 'no consent to withdraw' using errcode = '23514';
    end if;
    if p_occurred_on < v_letzte.occurred_on then
      raise exception 'withdrawal before consent' using errcode = '22023';
    end if;
  end if;

  -- Der juengste Vermerk, auch neben einem gleichzeitigen (Zweitreview).
  select greatest(now(), max(r.recorded_at) + interval '1 microsecond') into v_zeit
  from public.training_consent_records r
  where r.training_relationship_id = p_training_relationship_id;
  v_zeit := coalesce(v_zeit, now());

  insert into public.training_consent_records (
    organization_id, training_relationship_id, record_kind, purpose, occurred_on, recorded_by,
    recorded_at
  )
  values (
    v_org, p_training_relationship_id, p_record_kind, 'training_health_data', p_occurred_on, v_actor,
    v_zeit
  )
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.record_training_consent_entry(p_training_relationship_id uuid, p_record_kind text, p_occurred_on date) IS 'POR-017: Einwilligung zu Gesundheitsangaben im Training vom Papier vermerken oder ihren Widerruf. owner, Trainingsbetreuung, Buero (wer das Verhaeltnis schreibt). Nachweis am Datensatz, kein Auditeintrag (ADR-010 Fassung 3).';

CREATE FUNCTION public.redeem_platform_invitation(p_code_hash text, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_inv    record;
begin
  if p_user_id is null then
    raise exception 'invitation not valid' using errcode = '22023';
  end if;

  select i.id, i.purpose, i.organization_id, a.id as access_id, a.status as access_status,
         a.account_user_id
    into v_inv
  from public.platform_access_invitations i
  join public.platform_accesses a on a.id = i.platform_access_id
  where i.code_hash = lower(p_code_hash)
    and i.status = 'pending'
    and i.expires_at > now()
  for update of i, a;

  if v_inv.id is null
     or (v_inv.purpose = 'activate' and v_inv.access_status <> 'invited')
     or (v_inv.purpose = 'reset' and (v_inv.access_status <> 'active'
                                      or v_inv.account_user_id is distinct from p_user_id)) then
    raise exception 'invitation not valid' using errcode = '22023';
  end if;

  if v_inv.purpose = 'activate' then
    -- Der Riegel am Zugang prueft Praxiskonto und Person (Punkte 2 und 4).
    -- ANN-191: Das Konto hat der Zugangsdienst angelegt oder per Kennwort
    -- bestaetigt; seine Adresse darf von der im Verhaeltnis abweichen.
    update public.platform_accesses
       set status = 'active', account_user_id = p_user_id, activated_at = now()
     where id = v_inv.access_id;
  else
    -- Zweitreview: Das neue Kennwort setzt der Dienst erst NACH diesem
    -- Aufruf; der Code ist dann verbraucht, ein zweiter Aufruf scheitert.
    -- Laufende Sitzungen des Kontos enden hier: Wer das alte Kennwort
    -- kannte, bleibt nicht angemeldet (ADR-023 Punkt 18).
    if to_regclass('auth.sessions') is not null then
      execute 'delete from auth.sessions where user_id = $1' using p_user_id;
    end if;
  end if;

  update public.platform_access_invitations
     set status = 'redeemed', redeemed_at = now()
   where id = v_inv.id;

  -- LOG-EPIC-001: protokolliert wird die Aktivierung; ein neues Kennwort
  -- weist die Einladung selbst nach (created_by, redeemed_at).
  if v_inv.purpose = 'activate' then
    perform app.log_platform_access_event(
      v_inv.organization_id, p_user_id, 'platform', 'platform_access.activated',
      v_inv.access_id, jsonb_build_object('surface', 'platform')
    );
  end if;

  return v_inv.access_id;
end;
$_$;

COMMENT ON FUNCTION public.redeem_platform_invitation(p_code_hash text, p_user_id uuid) IS 'POR-003: Zugangsdienst. Bindet ein Konto an den Zugang (activate) oder bestaetigt das neue Kennwort (reset). Nur service_role; Akteur im Auditlog ist das Plattformkonto (actor_kind platform).';

CREATE FUNCTION public.register_platform_push_subscription(p_access_id uuid, p_endpoint text, p_p256dh text, p_auth text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    raise exception 'platform access denied' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if not app.push_endpoint_allowed(p_endpoint) then
    raise exception 'invalid push subscription' using errcode = '22023';
  end if;
  if (
    select count(*) from public.platform_push_subscriptions p
    where p.access_id = p_access_id and p.endpoint <> p_endpoint
  ) >= app.notification_rule('devices_per_access') then
    raise exception 'too many devices' using errcode = '22023';
  end if;
  begin
    insert into public.platform_push_subscriptions
      (organization_id, access_id, endpoint, p256dh, auth_secret)
    values (v_zugang.organization_id, p_access_id, p_endpoint, p_p256dh, p_auth)
    on conflict (access_id, endpoint) do update
      set p256dh = excluded.p256dh, auth_secret = excluded.auth_secret;
  exception when check_violation or not_null_violation then
    raise exception 'invalid push subscription' using errcode = '22023';
  end;
end;
$$;

COMMENT ON FUNCTION public.register_platform_push_subscription(p_access_id uuid, p_endpoint text, p_p256dh text, p_auth text) IS 'KOM-009 (ADR-024 Punkte 15, 17): registriert dieses Geraet fuer Push an einem lesbaren Zugang. Erst nach der Browserabfrage auf dem Geraet.';

CREATE FUNCTION public.reimbursement_payout_details(p_reimbursement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_antrag public.staff_reimbursements%rowtype;
  v_konto  public.staff_payout_accounts%rowtype;
begin
  v_org := app.staff_request_org(app.can_decide_staff_requests(), 'not allowed to pay reimbursements');
  select r.* into v_antrag
  from public.staff_reimbursements r
  where r.id = p_reimbursement_id and r.organization_id = v_org;
  if v_antrag.id is null then
    raise exception 'reimbursement not found' using errcode = 'P0002';
  end if;
  if not app.may_pay_reimbursement(v_org, v_antrag) then
    raise exception 'reimbursement is not approved' using errcode = '55000';
  end if;
  select a.* into v_konto from public.staff_payout_accounts a
   where a.staff_member_id = v_antrag.staff_member_id;
  return app.reimbursement_view(v_antrag) || jsonb_build_object(
    'iban', v_konto.iban,
    'account_since', v_konto.updated_at
  );
end;
$$;

COMMENT ON FUNCTION public.reimbursement_payout_details(p_reimbursement_id uuid) IS 'ERS-001 (ANN-601): die volle IBAN und seit wann sie hinterlegt ist - nur für owner, nur zu einem genehmigten Antrag, den er auszahlen darf. Die einzige Stelle, an der die IBAN die Datenbank verlässt.';

CREATE FUNCTION public.reimbursement_receipt_for_verification(p_receipt_id uuid, p_user_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text, byte_size bigint, checksum_sha256 text, already_verified boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.reimbursement_receipt_bucket(), b.object_key, b.mime_type, b.byte_size,
         b.checksum_sha256, b.verified_at is not null
  from public.staff_reimbursement_receipts b
  where b.id = p_receipt_id
    and b.created_by = p_user_id
    and b.reimbursement_id is null
    and b.created_at > now() - interval '24 hours'
    and (b.status = 'ready' or b.confirmation_requested_at is not null)
$$;

CREATE FUNCTION public.reject_time_account_entry(p_entry_id uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_text    text := nullif(btrim(coalesce(p_note, '')), '');
  v_eintrag record;
begin
  v_org := app.staff_request_org(app.can_decide_staff_requests(), 'not allowed to reject time account entries');
  if v_text is null then
    raise exception 'rejection needs a reason' using errcode = '22023';
  end if;
  if length(v_text) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  select e.id, e.staff_member_id, e.kind into v_eintrag
  from public.staff_time_account_entries e
  where e.id = p_entry_id and e.organization_id = v_org and e.status = 'valid'
    and e.kind <> 'carryover'
  for update;
  if not found then
    raise exception 'time account entry not found' using errcode = 'P0002';
  end if;
  if v_eintrag.staff_member_id = app.own_staff_member(v_org) then
    raise exception 'not allowed to reject own entry' using errcode = '42501';
  end if;
  perform 1 from public.staff_members sm where sm.id = v_eintrag.staff_member_id for no key update;
  update public.staff_time_account_entries
     set status = 'rejected', rejected_by = auth.uid(), rejected_at = now(), rejection_note = v_text
   where id = v_eintrag.id;
  delete from public.staff_working_hour_exceptions e where e.time_account_entry_id = v_eintrag.id;
  return jsonb_build_object('status', 'rejected', 'freed', v_eintrag.kind = 'time_off');
end;
$$;

COMMENT ON FUNCTION public.reject_time_account_entry(p_entry_id uuid, p_note text) IS 'ZK-001 (ANN-594): owner weist einen gültigen Eintrag mit Grund zurück, nie im eigenen Konto. Er bleibt sichtbar und zählt nicht; ein Freizeitausgleich gibt die Zeit wieder frei.';

CREATE FUNCTION public.release_fleet_bike(p_bike_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_blocks  integer;
  v_spots   integer;
begin
  v_org := app.fleet_org(app.can_release_fleet_bike(), 'not allowed to block or release bikes');
  perform 1 from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
  for update;
  if not found then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;

  update public.fleet_blocks b
     set released_at = now(), released_by = auth.uid()
   where b.bike_id = p_bike_id and b.released_at is null;
  get diagnostics v_blocks = row_count;
  update public.fleet_spots s
     set resolved_at = now(), resolved_by = auth.uid()
   where s.bike_id = p_bike_id and s.resolved_at is null;
  get diagnostics v_spots = row_count;

  if v_blocks + v_spots = 0 then
    raise exception 'nothing to release' using errcode = '55000';
  end if;
  -- Der Ort, an dem das Rad zurueckgelassen wurde, hat seinen Zweck mit der
  -- Freigabe erfuellt: Das Rad ist wieder da. Er kann ein Hausbesuch sein und
  -- bleibt deshalb nicht die drei Jahre der Meldung stehen (ANN-558).
  update public.fleet_breakdowns d
     set location_note = null
   where d.bike_id = p_bike_id and d.location_note is not null;
  return jsonb_build_object('released', v_blocks > 0, 'resolved_spots', v_spots);
end;
$$;

COMMENT ON FUNCTION public.release_fleet_bike(p_bike_id uuid) IS 'FLT-001 (ANN-550, ANN-555, ANN-558): Rad freigeben - schliesst die offene Sperre und erledigt alle offenen Stellen; beides bleibt im Verlauf. Der Pannenort des Rads wird geleert. owner und team_lead. Versendet nichts.';

CREATE FUNCTION public.release_legal_hold(p_hold_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor        uuid;
  v_org          uuid;
  v_subject      uuid;
  v_subject_type text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_legal_hold() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'legal_hold.released', 'not allowed to manage legal holds');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage legal holds' using errcode = '42501';
  end if;

  select h.subject_id, h.subject_type into v_subject, v_subject_type
  from public.legal_holds h
  where h.id = p_hold_id
    and h.organization_id = v_org
    and h.released_at is null
  for update;

  if not found then
    raise exception 'legal hold not found' using errcode = 'P0002';
  end if;

  update public.legal_holds
     set released_at = now(),
         released_by = v_actor
   where id = p_hold_id;

  -- Punkt 36: Was der Hold gesperrt gehalten hat, faellt, sobald er endet -
  -- nicht erst im naechsten Loeschlauf.
  if v_subject_type = 'patient' then
    perform app.delete_due_patient_photos(
      v_org, v_subject, extensions.gen_random_uuid(), v_actor, 'legal_hold_released'
    );
  end if;
end;
$$;

COMMENT ON FUNCTION public.release_legal_hold(p_hold_id uuid) IS 'Hebt eine laufende Loeschsperre auf, an einer Akte oder an Beschaeftigtendaten (LOE-001c, ANN-674). Die Zeile bleibt als Nachweis bestehen. Nur owner.';

CREATE FUNCTION public.release_treatment_basis_for_billing(p_treatment_basis_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_stand record;
  v_zeit  timestamptz := now();
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_release_treatment_basis() then
    raise exception 'not allowed to release treatment bases for billing' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to release treatment bases for billing' using errcode = '42501';
  end if;

  perform 1
  from public.treatment_bases b
  where b.id = p_treatment_basis_id
    and b.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  select * into v_stand from app.treatment_basis_billing(p_treatment_basis_id);

  if v_stand.released_at is not null then
    raise exception 'treatment basis is already in billing' using errcode = '22023';
  end if;

  if v_stand.open_count > 0 then
    raise exception 'treatment basis has open appointments' using errcode = '22023';
  end if;

  if v_stand.documented = 0 then
    raise exception 'treatment basis has no documented appointment' using errcode = '22023';
  end if;

  -- Ein Entwurf, auch ein Nachtrag: Unter der Sperre liesse er sich weder
  -- festschreiben noch automatisch finalisieren (ADR-016 Punkt 7).
  if exists (
    select 1
    from public.treatment_notes t
    join public.appointments a on a.id = t.appointment_id
    where a.treatment_basis_id = p_treatment_basis_id
      and t.status = 'draft'
  ) then
    raise exception 'treatment basis has draft documentation' using errcode = '22023';
  end if;

  update public.treatment_bases
     set billing_released_at = v_zeit,
         billing_released_by = v_actor
   where id = p_treatment_basis_id;

  return v_zeit;
end;
$$;

COMMENT ON FUNCTION public.release_treatment_basis_for_billing(p_treatment_basis_id uuid) IS 'B7 (BEF-157): stellt eine Grundlage in die Abrechnung - nur wenn jeder ihrer Termine abgehakt und dokumentiert (oder abgesagt, nicht angetroffen) ist und kein Entwurf mehr an ihnen haengt. Danach sperrt sie Doku, Zeitpunkt und Anzahl ihrer Termine (ANN-515). Keine Auditaktion: Zeitpunkt und Person stehen an der Grundlage.';

CREATE FUNCTION public.remove_fleet_bike(p_bike_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.fleet_org(app.can_manage_fleet(), 'not allowed to manage the fleet');
  perform 1 from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
  for update;
  if not found then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.fleet_key_handovers k where k.bike_id = p_bike_id and k.returned_at is null
  ) then
    raise exception 'key is taken' using errcode = '55000';
  end if;

  if exists (select 1 from public.fleet_checkups c where c.bike_id = p_bike_id)
     or exists (select 1 from public.fleet_breakdowns d where d.bike_id = p_bike_id)
     or exists (select 1 from public.fleet_blocks b where b.bike_id = p_bike_id)
     or exists (select 1 from public.fleet_key_handovers k where k.bike_id = p_bike_id) then
    update public.fleet_blocks b
       set released_at = now(), released_by = auth.uid()
     where b.bike_id = p_bike_id and b.released_at is null;
    update public.fleet_spots s
       set resolved_at = now(), resolved_by = auth.uid()
     where s.bike_id = p_bike_id and s.resolved_at is null;
    -- Wie bei der Freigabe: kein Pannenort ueber das Rad hinaus (ANN-558).
    update public.fleet_breakdowns d
       set location_note = null
     where d.bike_id = p_bike_id and d.location_note is not null;
    update public.fleet_bikes b
       set archived_at = now(),
           archived_by = auth.uid(),
           regular_rider_id = null,
           planned_weekdays = '{}'::smallint[],
           note = null,
           updated_at = now(),
           updated_by = auth.uid()
     where b.id = p_bike_id;
    return 'archived';
  end if;

  delete from public.fleet_bikes b where b.id = p_bike_id;
  return 'deleted';
end;
$$;

COMMENT ON FUNCTION public.remove_fleet_bike(p_bike_id uuid) IS 'FLT-001 (ANN-557): Rad entfernen. Ohne Verlauf geloescht, mit Verlauf ausgemustert - aus der Flotte, offene Sperre und Stellen erledigt, Stammnutzer:in entfernt, Verlauf bis zum Ende seiner Frist; danach faellt das Rad im Loeschlauf. Nur owner (BEF-066).';

CREATE FUNCTION public.remove_own_profile_picture() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_alt   uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  perform 1 from public.staff_members sm
  where sm.id = v_staff and sm.employment_status = 'active' for no key update;
  if not found then
    raise exception 'not allowed to use the team chat' using errcode = '42501';
  end if;
  select p.id into v_alt from public.staff_profile_pictures p where p.staff_member_id = v_staff;
  if v_alt is null then
    return false;
  end if;
  perform app.forget_profile_picture(v_org, v_alt);
  return true;
end;
$$;

COMMENT ON FUNCTION public.remove_own_profile_picture() IS 'TEAM-007 (ADR-017 Abschnitt O): das eigene Profilbild entfernen, mit Löschjournal. Liefert, ob eines da war.';

CREATE FUNCTION public.remove_patient_course_event(p_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_questionnaire_response() then
    raise exception 'not allowed to record course events' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record course events' using errcode = '42501';
  end if;

  -- ABN-013: Die Zeile bleibt; ein schon entferntes Ereignis gilt als nicht gefunden.
  update public.patient_course_events e
     set removed_at = now(), removed_by = v_actor
   where e.id = p_event_id and e.organization_id = v_org and e.removed_at is null
  returning e.patient_id into v_patient;

  if v_patient is null then
    raise exception 'course event not found' using errcode = 'P0002';
  end if;

end;
$$;

COMMENT ON FUNCTION public.remove_patient_course_event(p_event_id uuid) IS 'Entfernt eine Markierung aus dem Verlauf (FRB-002e, ANN-106, ABN-013): markiert sie mit removed_at/removed_by, die Zeile bleibt in der Akte. owner, therapist, team_lead; protokolliert als patient_course_event.removed.';

CREATE FUNCTION public.remove_platform_push_subscription(p_endpoint text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_anzahl integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  delete from public.platform_push_subscriptions p
   using public.platform_accesses a
   where a.id = p.access_id
     and a.account_user_id = auth.uid()
     and p.endpoint = p_endpoint;
  get diagnostics v_anzahl = row_count;
  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.remove_platform_push_subscription(p_endpoint text) IS 'KOM-009 (ADR-024 Punkt 17): loescht die Push-Registrierung dieses Geraets an allen eigenen Zugaengen - beim Abmelden und beim Ausschalten.';

CREATE FUNCTION public.remove_team_channel_member(p_channel uuid, p_staff_member uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  -- Wie Verlassen und Archivieren: Ein gleichzeitiges Senden wartet (Runde 3,
  -- Befund 2). Die Sperre steht vor den Prüfungen, damit zwei Verwaltende, die
  -- sich gleichzeitig gegenseitig herausnehmen, nacheinander geprüft werden
  -- (Runde 4, N3).
  perform 1 from public.team_channels where id = p_channel and organization_id = v_org for update;
  if not exists (select 1 from public.team_channels c
                 where c.id = p_channel and c.organization_id = v_org and c.kind = 'private')
     or not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  if not app.team_channel_manageable(p_channel, v_org, v_staff) then
    raise exception 'not allowed to manage team channels' using errcode = '42501';
  end if;
  if p_staff_member is null or p_staff_member = v_staff then
    raise exception 'leave the channel instead' using errcode = '22023';
  end if;
  delete from public.team_channel_members
  where channel_id = p_channel and staff_member_id = p_staff_member;
  if not found then
    raise exception 'team chat partner is not available' using errcode = '22023';
  end if;
  perform app.team_forget_channel(p_channel, p_staff_member);
end;
$$;

CREATE FUNCTION public.remove_territory(p_territory_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_working_hours() then
    raise exception 'not allowed to write territories' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write territories' using errcode = '42501';
  end if;

  delete from public.territories t where t.id = p_territory_id and t.organization_id = v_org;
  if not found then
    raise exception 'territory not found' using errcode = 'P0002';
  end if;

end;
$$;

COMMENT ON FUNCTION public.remove_territory(p_territory_id uuid) IS 'Entfernt ein Gebiet samt Postleitzahlen (PRX-002). owner, team_lead, office; auditiert. Termine bleiben unberuehrt.';

CREATE FUNCTION public.remove_training_assessment(p_assessment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  if v_actor is null or not app.can_write_exercise_plans('training') then
    raise exception 'not allowed to remove assessments' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  update public.training_assessments a
     set removed_at = now(), removed_by = v_actor
   where a.id = p_assessment_id
     and a.organization_id = v_org
     and a.removed_at is null;
  if not found then
    raise exception 'assessment not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.remove_training_assessment(p_assessment_id uuid) IS 'OUT-002 (ANN-365): nimmt ein falsch festgehaltenes Assessment aus dem Verlauf; Inhalt, Urheber und wer entfernt hat bleiben am Datensatz. Wer: app.can_write_exercise_plans(training).';

CREATE FUNCTION public.remove_training_course_event(p_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  if v_actor is null or not app.can_write_exercise_plans('training') then
    raise exception 'not allowed to remove course events' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  update public.training_course_events e
     set removed_at = now(), removed_by = v_actor
   where e.id = p_event_id
     and e.organization_id = v_org
     and e.removed_at is null;
  if not found then
    raise exception 'course event not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.remove_training_course_event(p_event_id uuid) IS 'OUT-001 (ANN-364): nimmt ein Ereignis aus dem Verlauf des Trainings; Inhalt, Urheber und wer entfernt hat bleiben am Datensatz. Wer: app.can_write_exercise_plans(training). Auch nach Vertragsende, damit ein falscher Vermerk nicht stehen bleibt.';

CREATE FUNCTION public.renew_platform_representation_code(p_access_id uuid) RETURNS TABLE(access_id uuid, invitation_id uuid, purpose text, code text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_access  public.platform_accesses%rowtype;
  v_purpose text;
  v_inv     record;
  v_minderjaehrig boolean;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  v_access := app.platform_access_for_update(p_access_id, v_org);
  if v_access.id is null or not app.can_manage_platform_access(v_access.relationship_kind) then
    perform app.record_denied_write(v_actor, 'platform_access.invited', 'not allowed to manage platform access');
    return;
  end if;

  if v_access.access_kind = 'self' then
    raise exception 'use invite_platform_access for the person' using errcode = '22023';
  end if;
  -- Eine abgelaufene Lesefrist bekommt keinen neuen Code, und keine
  -- Vertretung, deren Art nicht mehr zum Alter passt - auch nicht als offene
  -- Einladung (Zweitreview; Punkt 15, ANN-208): ein Sorgerecht ab 18, jede
  -- andere Art unter 18 oder ohne Geburtsdatum.
  v_minderjaehrig := app.platform_is_minor(
    (select r.date_of_birth
       from app.platform_relationship(v_access.relationship_kind, v_access.relationship_id) r),
    (select o.time_zone from public.organizations o where o.id = v_org)
  );
  if (v_access.status = 'active'
      and coalesce(app.platform_access_ended_at(v_access.id) <= now(), false))
     or v_minderjaehrig is null
     or v_minderjaehrig <> (v_access.legal_basis is not distinct from 'custody') then
    raise exception 'platform access has ended' using errcode = '22023';
  end if;

  if v_access.status = 'invited' then
    v_purpose := 'activate';
  elsif v_access.status = 'active' then
    v_purpose := 'reset';
    -- Wie POR-002: Ein neues Kennwort gilt fuer das ganze Konto. Zweitreview:
    -- auch ueber Organisationen hinweg - die Rolle hier gilt nur hier.
    if exists (
      select 1 from public.platform_accesses b
      where b.account_user_id = v_access.account_user_id
        and b.status <> 'revoked'
        and (b.organization_id <> v_org or not app.can_manage_platform_access(b.relationship_kind))
    ) then
      raise exception 'reset needs every area of this account' using errcode = '22023';
    end if;
  elsif v_access.status = 'locked' then
    raise exception 'platform access is locked' using errcode = '22023';
  else
    raise exception 'platform access is already revoked' using errcode = '22023';
  end if;

  select * into v_inv from app.issue_platform_invitation(v_org, v_access.id, v_purpose, v_actor);

  perform app.log_platform_access_event(
    v_org, v_actor, 'user', 'platform_access.invited', v_access.id,
    jsonb_build_object('surface', 'web', 'channel', 'on_site', 'purpose', v_purpose,
                       'relationship_kind', v_access.relationship_kind,
                       'access_kind', v_access.access_kind)
  );

  return query select v_access.id, v_inv.invitation_id, v_purpose, v_inv.code, v_inv.expires_at;
end;
$$;

COMMENT ON FUNCTION public.renew_platform_representation_code(p_access_id uuid) IS 'POR-005: neuer Code vor Ort fuer eine Vertretung - Einladung, solange eingeladen, neues Kennwort, wenn aktiv (ADR-023 Punkt 10). Rollen, die das Verhaeltnis schreiben; abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.reopen_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- TRN-010 (ANN-186): dieselbe Rollenmenge wie beim Abschliessen.
  if not (app.can_reopen_appointment() or app.can_write_training_relationships()) then
    raise exception 'not allowed to reopen appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to reopen appointments' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.staff_member_id, a.status, a.updated_at,
         a.kind, a.training_relationship_id, a.completed_at, a.occasion
    into v_alt
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_alt.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be reopened' using errcode = '22023';
  end if;

  -- 'invoiced' hat keinen Rueckweg (Rechnungsstorno, ADR-018 Punkt 2). Ein
  -- 'documented' Termin kehrt nicht nach 'confirmed' zurueck; seit B4 laesst
  -- sich dort aber der Haken zuruecknehmen (ANN-512).
  -- Am Trainingstermin bleibt es beim Bisherigen (ADR-022 Punkt 6).
  if not (v_alt.status in ('completed', 'no_show')
          or (v_alt.status = 'documented' and v_alt.kind = 'therapy'
              and v_alt.completed_at is not null)) then
    raise exception 'appointment is not completed' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  -- ERN-011: Am Beratungstermin faellt die Position mit dem Haken, in
  -- beiden Bereichen - sie ist mit ihm entstanden.
  if v_alt.status = 'no_show'
     or (v_alt.kind <> 'therapy' and v_alt.occasion <> 'nutrition_counselling') then
    -- Ein Ausfallhonorar haengt am Vermerk, eine Trainingsleistung am
    -- Training (ABR-002): Zurueck geht es wie bisher nur ueber
    -- delete_billable_services im Buero (R3-002).
    if exists (
      select 1 from public.billable_services b where b.appointment_id = p_appointment_id
    ) then
      raise exception 'billable services recorded, remove them first' using errcode = '23514';
    end if;
  else
    -- B7 (BEF-157): Mit dem Haken gilt die Behandlung als erbracht; ohne ihn
    -- nicht mehr. Ihre Leistungen fallen mit, solange keine Rechnung und kein
    -- Entwurf sie fuehrt - sonst haelt der Vorgang an.
    perform app.withdraw_appointment_services(p_appointment_id);
  end if;

  if v_alt.status = 'documented' then
    update public.appointments
       set completed_at = null,
           completed_by = null,
           reopened_at  = now(),
           reopened_by  = v_actor,
           updated_at   = now()
     where id = p_appointment_id
       and updated_at = p_expected_updated_at
       and status = 'documented'
       and kind = 'therapy';
  else
    update public.appointments
       set status                     = 'confirmed',
           completed_at               = null,
           completed_by               = null,
           no_show_recorded_at        = null,
           no_show_recorded_by        = null,
           no_show_protocol_confirmed = null,
           fee_basis                  = null,
           -- LOG-EPIC-001: die Ruecknahme steht im Datenmodell, nicht im Log.
           reopened_at                = now(),
           reopened_by                = v_actor,
           updated_at                 = now()
     where id = p_appointment_id
       and updated_at = p_expected_updated_at
       and status in ('completed', 'no_show');
  end if;

  if not found then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;


  return p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.reopen_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) IS 'Nimmt den Haken zurueck (ADR-018 Fassung 5, B4): completed oder no_show -> confirmed; an documented nur das Merkmal completed_at, die Doku bleibt finalisiert. Die Leistungen eines Behandlungstermins fallen mit, solange keine Rechnung sie fuehrt; ein Ausfallhonorar oder eine Trainingsleistung haelt den Vorgang wie bisher an (R3-002).';

CREATE FUNCTION public.reopen_patient_care(p_patient_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_bisher date;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_conclude_patient_care() then
    raise exception 'not allowed to conclude patient care' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to conclude patient care' using errcode = '42501';
  end if;

  select p.care_concluded_on into v_bisher
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = v_org
  for update;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- Kein Abschluss, kein Vorgang: weder Schreibzugriff noch Auditeintrag.
  if v_bisher is null then
    return;
  end if;

  perform app.delete_due_patient_photos(
    v_org, p_patient_id, extensions.gen_random_uuid(), v_actor, 'care_reopened'
  );

  update public.patients
     set care_concluded_on = null,
         care_concluded_at = null,
         care_concluded_by = null
   where id = p_patient_id;

end;
$$;

COMMENT ON FUNCTION public.reopen_patient_care(p_patient_id uuid) IS 'Nimmt den Abschluss der Versorgung zurueck; die Aufbewahrungsfrist beginnt mit dem naechsten Abschluss neu (LOE-001b). Protokolliert patient.care_reopened. Nur owner, therapist, team_lead.';

CREATE FUNCTION public.reopen_training_basis(p_basis_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(auth.uid(), 'training_basis.reopened', 'not allowed to manage training bases');
    return null;
  end if;
  return app.set_training_basis_status(p_basis_id, 'active', 'training_basis.reopened');
end;
$$;

COMMENT ON FUNCTION public.reopen_training_basis(p_basis_id uuid) IS 'TRN-005: oeffnet eine abgeschlossene Trainingsgrundlage wieder, nur an einem laufenden Verhaeltnis. owner, trainer, office; protokolliert training_basis.reopened.';

CREATE FUNCTION public.reopen_training_relationship(p_relationship_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_bisher date;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(v_actor, 'training_relationship.reopened', 'not allowed to manage training clients');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training clients' using errcode = '42501';
  end if;

  select t.contract_ended_on into v_bisher
  from public.training_relationships t
  where t.id = p_relationship_id and t.organization_id = v_org
  for update;
  if not found then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;
  if v_bisher is null then
    raise exception 'training relationship has not ended' using errcode = '22023';
  end if;

  -- Wer nach einer Pause weitertrainiert, bekommt kein zweites Verhaeltnis
  -- (LEI-001): Das Ende wird geraeumt, die Frist laeuft nicht mehr.
  update public.training_relationships
     set contract_ended_on = null, status = 'active'
   where id = p_relationship_id;


  return p_relationship_id;
end;
$$;

COMMENT ON FUNCTION public.reopen_training_relationship(p_relationship_id uuid) IS 'TRN-001: raeumt das Vertragsende wieder (die Frist laeuft nicht mehr) und setzt den Status active. owner, trainer, office; protokolliert training_relationship.reopened mit dem alten Tag.';

CREATE FUNCTION public.request_leave(p_starts_on date, p_ends_on date, p_message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_tage    integer;
  v_folge   integer := 0;
  v_jahr    integer;
  v_text    text := nullif(btrim(coalesce(p_message, '')), '');
  v_selbst  boolean;
  v_id      uuid;
begin
  v_org := app.staff_request_org(app.can_request_leave(), 'not allowed to request leave');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = '22023';
  end if;
  perform app.assert_leave_period(v_org, p_starts_on, p_ends_on);
  if v_text is not null and length(v_text) > 500 then
    raise exception 'message is too long' using errcode = '22023';
  end if;

  -- Zwei eigene Antraege fuer dieselben Tage gibt es nicht. Gesperrt wird die
  -- Person, damit zwei gleichzeitige Antraege nicht beide durchgehen.
  perform 1 from public.staff_members sm where sm.id = v_staff for no key update;
  if exists (
    select 1 from public.staff_leave_requests r
    where r.organization_id = v_org and r.staff_member_id = v_staff
      and r.kind = 'leave' and r.status in ('requested', 'approved')
      and r.starts_on <= p_ends_on and r.ends_on >= p_starts_on
  ) then
    raise exception 'leave overlaps' using errcode = '23P01';
  end if;

  v_jahr := extract(year from p_starts_on)::integer;
  v_tage := app.leave_days(v_org, v_staff, p_starts_on, p_ends_on);
  if v_tage = 0 then
    raise exception 'no working days in period' using errcode = '22023';
  end if;
  if extract(year from p_ends_on)::integer > v_jahr then
    v_folge := app.leave_days(v_org, v_staff, make_date(v_jahr + 1, 1, 1), p_ends_on);
  end if;

  -- Den eigenen Urlaub traegt owner selbst ein (ANN-576).
  v_selbst := app.has_any_role('owner');

  insert into public.staff_leave_requests (
    organization_id, staff_member_id, kind, starts_on, ends_on, days, days_following_year,
    message, status, requested_by, decided_by, decided_at, self_entered
  )
  values (
    v_org, v_staff, 'leave', p_starts_on, p_ends_on, v_tage, v_folge, v_text,
    case when v_selbst then 'approved' else 'requested' end, auth.uid(),
    case when v_selbst then auth.uid() end, case when v_selbst then now() end, v_selbst
  )
  returning id into v_id;

  if v_selbst then
    perform app.apply_leave(v_org, v_id);
  end if;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.request_leave(p_starts_on date, p_ends_on date, p_message text) IS 'URL-001 (ANN-576): Urlaub fuer die eigene Person beantragen - die Tage zaehlt der Server, keine Ueberschneidung mit eigenem Urlaub, nicht in der Vergangenheit. owner traegt den eigenen Urlaub direkt ein (genehmigt, self_entered). Kein Auditeintrag (ADR-010 Punkt 15).';

CREATE FUNCTION public.request_leave_cancellation(p_request_id uuid, p_message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_urlaub  record;
  v_heute   date;
  v_text    text := nullif(btrim(coalesce(p_message, '')), '');
  v_selbst  boolean;
  v_id      uuid;
begin
  v_org := app.staff_request_org(app.can_request_leave(), 'not allowed to request leave');
  v_staff := app.own_staff_member(v_org);
  if v_text is not null and length(v_text) > 500 then
    raise exception 'message is too long' using errcode = '22023';
  end if;

  select r.id, r.starts_on, r.ends_on, r.days, r.days_following_year into v_urlaub
  from public.staff_leave_requests r
  where r.id = p_request_id and r.organization_id = v_org and r.staff_member_id = v_staff
    and r.kind = 'leave' and r.status = 'approved'
  for update;
  if not found then
    raise exception 'leave request not found' using errcode = 'P0002';
  end if;

  -- Storniert wird ein Urlaub, der noch nicht begonnen hat. Ein laufender
  -- gaebe sonst Tage frei, die schon genommen sind (ANN-576).
  select (now() at time zone o.time_zone)::date into v_heute
  from public.organizations o where o.id = v_org;
  if v_urlaub.starts_on < v_heute then
    raise exception 'leave already started' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.staff_leave_requests r
    where r.refers_to = v_urlaub.id and r.kind = 'cancellation' and r.status = 'requested'
  ) then
    raise exception 'cancellation already requested' using errcode = '55000';
  end if;

  v_selbst := app.has_any_role('owner');
  insert into public.staff_leave_requests (
    organization_id, staff_member_id, kind, refers_to, starts_on, ends_on, days,
    days_following_year, message, status, requested_by, decided_by, decided_at, self_entered
  )
  values (
    v_org, v_staff, 'cancellation', v_urlaub.id, v_urlaub.starts_on, v_urlaub.ends_on,
    v_urlaub.days, v_urlaub.days_following_year, v_text,
    case when v_selbst then 'approved' else 'requested' end, auth.uid(),
    case when v_selbst then auth.uid() end, case when v_selbst then now() end, v_selbst
  )
  returning id into v_id;

  if v_selbst then
    update public.staff_leave_requests set status = 'cancelled' where id = v_urlaub.id;
    delete from public.staff_working_hour_exceptions e where e.leave_request_id = v_urlaub.id;
  end if;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.request_leave_cancellation(p_request_id uuid, p_message text) IS 'URL-001 (ANN-576): einen genehmigten eigenen Urlaub stornieren - als neuer Antrag mit Bezug, der wieder entschieden wird; owner storniert den eigenen direkt. Nur vor Beginn des Urlaubs.';

CREATE FUNCTION public.request_platform_appointment(p_access_id uuid, p_days date[], p_times text[], p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_zone   text;
  v_heute  date;
  v_tage   date[];
  v_id     uuid;
begin
  -- Wuenschen duerfen alle drei Arten des Zugangs (ADR-023 Punkt 13, W3).
  if not app.platform_access_allows(p_access_id, 'request') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;
  v_heute := (now() at time zone v_zone)::date;

  -- Tage: mindestens einer, hoechstens 14, keiner vor heute, keiner weiter
  -- als ein Jahr voraus; doppelte werden zusammengefasst.
  select array_agg(distinct t order by t) into v_tage
  from unnest(coalesce(p_days, '{}'::date[])) t;
  if v_tage is null or cardinality(v_tage) = 0 then
    raise exception 'at least one day is required' using errcode = '22023';
  end if;
  if cardinality(v_tage) > 14 then
    raise exception 'too many days' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_tage) t where t < v_heute or t > v_heute + 365) then
    raise exception 'day out of range' using errcode = '22023';
  end if;
  if not (coalesce(p_times, '{}'::text[]) <@ array['morning', 'midday', 'afternoon']::text[]) then
    raise exception 'unknown time of day' using errcode = '22023';
  end if;
  if p_note is not null and length(btrim(p_note)) > 500 then
    raise exception 'note too long' using errcode = '22023';
  end if;

  insert into public.platform_appointment_requests (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    kind, preferred_days, preferred_times, note, created_by_access_id, created_by
  )
  values (
    v_zugang.organization_id, v_zugang.relationship_kind, v_zugang.relationship_id,
    v_zugang.patient_id, v_zugang.training_relationship_id,
    'new', v_tage,
    (select coalesce(array_agg(distinct t), '{}'::text[]) from unnest(coalesce(p_times, '{}'::text[])) t),
    nullif(btrim(p_note), ''), v_zugang.id, auth.uid()
  )
  returning id into v_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'request')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.request_platform_appointment(p_access_id uuid, p_days date[], p_times text[], p_note text) IS 'POR-009: Termin wuenschen ueber die Plattform (PROJECT_PRINCIPLES.md 8, ANN-246): Tage, Tageszeiten, freie Zeile. Ein Wunsch, kein Termin; Recht request (alle Arten des Zugangs). Nachweis am Datensatz, Vertretung protokolliert.';

CREATE FUNCTION public.request_platform_appointment_change(p_access_id uuid, p_appointment_id uuid, p_kind text, p_days date[], p_times text[], p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_termin record;
  v_zone   text;
  v_heute  date;
  v_tage   date[];
  v_id     uuid;
begin
  if not app.platform_access_allows(p_access_id, 'request') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  if p_kind is null or p_kind not in ('change', 'cancel') then
    raise exception 'unknown request kind' using errcode = '22023';
  end if;

  -- Nur der eigene, bestaetigte, kuenftige Termin. Ein fremder und ein nicht
  -- vorhandener sehen gleich aus.
  select a.id, a.status, a.starts_at into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_zugang.organization_id
    and (
      (v_zugang.relationship_kind = 'treatment' and a.kind = 'therapy'
         and a.patient_id = v_zugang.relationship_id)
      or
      (v_zugang.relationship_kind = 'training' and a.kind = 'training'
         and a.training_relationship_id = v_zugang.relationship_id)
    );
  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;
  if v_termin.status <> 'confirmed' then
    raise exception 'appointment is not confirmed' using errcode = '22023';
  end if;
  if v_termin.starts_at <= now() then
    raise exception 'appointment has started' using errcode = '22023';
  end if;

  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;
  v_heute := (now() at time zone v_zone)::date;

  -- Wunschtage nur bei einer Aenderung; dieselben Grenzen wie POR-009.
  if p_kind = 'change' then
    select coalesce(array_agg(distinct t order by t), '{}'::date[]) into v_tage
    from unnest(coalesce(p_days, '{}'::date[])) t;
    if cardinality(v_tage) > 14 then
      raise exception 'too many days' using errcode = '22023';
    end if;
    if exists (select 1 from unnest(v_tage) t where t < v_heute or t > v_heute + 365) then
      raise exception 'day out of range' using errcode = '22023';
    end if;
    if not (coalesce(p_times, '{}'::text[]) <@ array['morning', 'midday', 'afternoon']::text[]) then
      raise exception 'unknown time of day' using errcode = '22023';
    end if;
  else
    v_tage := '{}'::date[];
  end if;
  if p_note is not null and length(btrim(p_note)) > 500 then
    raise exception 'note too long' using errcode = '22023';
  end if;

  begin
    insert into public.platform_appointment_requests (
      organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
      appointment_id, kind, preferred_days, preferred_times, note, created_by_access_id, created_by
    )
    values (
      v_zugang.organization_id, v_zugang.relationship_kind, v_zugang.relationship_id,
      v_zugang.patient_id, v_zugang.training_relationship_id,
      p_appointment_id, p_kind, v_tage,
      case when p_kind = 'change'
        then (select coalesce(array_agg(distinct t), '{}'::text[])
              from unnest(coalesce(p_times, '{}'::text[])) t)
        else '{}'::text[] end,
      nullif(btrim(p_note), ''), v_zugang.id, auth.uid()
    )
    returning id into v_id;
  exception when unique_violation then
    raise exception 'request already open' using errcode = '23505';
  end;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read',
    jsonb_build_object('view', 'request_' || p_kind)
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.request_platform_appointment_change(p_access_id uuid, p_appointment_id uuid, p_kind text, p_days date[], p_times text[], p_note text) IS 'POR-010: Aenderungs- oder Absagewunsch am eigenen bestaetigten, kuenftigen Termin (DSN-001 D4, ANN-247). Ein Wunsch, keine Absage; als Eingang gilt spaeter der Zeitpunkt des Wunsches. Hoechstens ein offener Wunsch je Termin (23505).';

CREATE FUNCTION public.request_staff_password_reset(p_staff_member_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_user  uuid;
  v_email text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_accounts() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'staff_account.password_reset_requested', 'not allowed to manage accounts');
    return null;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage accounts' using errcode = '42501';
  end if;

  select up.id into v_user
  from public.staff_members sm
  join public.user_profiles up
    on up.person_id = sm.person_id
   and up.organization_id = sm.organization_id
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org;

  if not found then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  select au.email into v_email
  from auth.users au
  where au.id = v_user;

  if v_email is null or v_email = '' then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'staff_account.password_reset_requested', 'staff_member',
    p_staff_member_id, 'success', jsonb_build_object('surface', 'web')
  );

  return v_email;
end;
$$;

COMMENT ON FUNCTION public.request_staff_password_reset(p_staff_member_id uuid) IS 'Protokolliert, dass die Praxisinhaberin ein Zuruecksetzen angestossen hat, und liefert die Anmeldeadresse fuer die Auth-Mail des Providers. Aendert selbst kein Kennwort (STAFF-003, B13).';

CREATE FUNCTION public.request_working_time_change(p_kind text, p_on_date date, p_blocks jsonb, p_message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_neu     jsonb;
  v_pruef   jsonb;
  v_text    text := nullif(btrim(coalesce(p_message, '')), '');
  v_selbst  boolean;
  v_id      uuid;
begin
  v_org := app.staff_request_org(app.can_request_working_time(), 'not allowed to request working time');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = '22023';
  end if;
  perform app.assert_working_time_date(v_org, p_kind, p_on_date);
  if v_text is not null and length(v_text) > 500 then
    raise exception 'message is too long' using errcode = '22023';
  end if;
  v_neu := app.working_time_normalize(p_kind, p_blocks);

  -- Gesperrt wird die Person, damit zwei gleichzeitige Antraege und eine
  -- gleichzeitige Pflege nicht gegeneinander laufen.
  perform 1 from public.staff_members sm where sm.id = v_staff for no key update;
  if exists (
    select 1 from public.staff_working_time_requests r
    where r.organization_id = v_org and r.staff_member_id = v_staff and r.status = 'requested'
      and r.kind = p_kind and (p_kind = 'permanent' or r.on_date = p_on_date)
  ) then
    raise exception 'working time request already open' using errcode = '55000';
  end if;
  v_pruef := app.assert_working_time_change(v_org, v_staff, p_kind, p_on_date, v_neu, '22023');

  -- Die eigene Aenderung traegt owner selbst ein (ANN-590).
  v_selbst := app.has_any_role('owner');

  insert into public.staff_working_time_requests (
    organization_id, staff_member_id, kind, on_date, blocks, previous_blocks, previous_minutes,
    new_minutes, message, status, requested_by, decided_by, decided_at, self_entered
  )
  values (
    v_org, v_staff, p_kind, p_on_date, v_neu, v_pruef -> 'blocks', (v_pruef ->> 'minutes')::integer,
    (v_pruef ->> 'new_minutes')::integer, v_text,
    case when v_selbst then 'approved' else 'requested' end, auth.uid(),
    case when v_selbst then auth.uid() end, case when v_selbst then now() end, v_selbst
  )
  returning id into v_id;

  if v_selbst then
    perform app.apply_working_time_change(v_org, v_id);
  end if;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.request_working_time_change(p_kind text, p_on_date date, p_blocks jsonb, p_message text) IS 'AZ-001 (ANN-588, ANN-590): Aenderung der eigenen Arbeitszeit beantragen - einmalig ein Tag oder dauerhaft der Wochenplan ab einem Datum, frühestens morgen; nie weniger Stunden, nach ArbZG zulaessig. owner traegt die eigene direkt ein. Kein Auditeintrag (ADR-010 Punkt 15).';

CREATE FUNCTION public.reschedule_team_message(p_message uuid, p_send_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_m     public.team_messages%rowtype;
  v_zeit  timestamptz;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if p_send_at is not null
     and (p_send_at < now() + interval '1 minute' or p_send_at > now() + interval '30 days') then
    raise exception 'send time must be one minute to 30 days ahead' using errcode = '22023';
  end if;
  v_zeit := coalesce(p_send_at, now());
  update public.team_messages m
     set created_at = v_zeit
   where m.id = p_message and m.organization_id = v_org and m.author_staff_member_id = v_staff
     and m.created_at > now() and m.removed_at is null
     and app.team_channel_readable(m.channel_id, v_org, v_staff)
     and not exists (select 1 from public.team_channels c
                     where c.id = m.channel_id and c.archived_at is not null)
  returning m.* into v_m;
  if v_m.id is null then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  -- Wer folgt, folgt ab der neuen Zeit. Den Lesestand zieht auch „Jetzt
  -- senden“ nicht vor (ANN-640; Zweitreview TEAM-002, Runde 4).
  update public.team_thread_states set read_up_to = v_zeit where root_message_id = v_m.id;
end;
$$;

CREATE FUNCTION public.resolve_platform_appointment_request(p_request_id uuid, p_outcome text, p_answer text DEFAULT NULL::text, p_resulting_appointment_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_wunsch record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to resolve requests' using errcode = '42501';
  end if;
  if p_outcome is null or p_outcome not in ('done', 'declined') then
    raise exception 'unknown outcome' using errcode = '22023';
  end if;
  if p_answer is not null and length(btrim(p_answer)) > 300 then
    raise exception 'answer too long' using errcode = '22023';
  end if;

  select w.id, w.relationship_kind, w.kind, w.patient_id, w.training_relationship_id into v_wunsch
  from public.platform_appointment_requests w
  where w.id = p_request_id and w.organization_id = v_org and w.status = 'open'
  for update;
  if not found then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if not app.may_write_appointment_context(
           case v_wunsch.relationship_kind when 'training' then 'training' else 'therapy' end) then
    raise exception 'not allowed to resolve requests' using errcode = '42501';
  end if;

  -- Ein Termin als Ergebnis nur an einem erledigten Wunsch, und nur einer der
  -- eigenen Praxis.
  if p_resulting_appointment_id is not null then
    if p_outcome <> 'done' then
      raise exception 'resulting appointment needs outcome done' using errcode = '22023';
    end if;
    -- Der Termin gehoert zum Verhaeltnis des Wunsches (Zweitreview).
    perform 1 from public.appointments a
    where a.id = p_resulting_appointment_id
      and a.organization_id = v_org
      and (
        (v_wunsch.relationship_kind = 'treatment' and a.patient_id = v_wunsch.patient_id)
        or
        (v_wunsch.relationship_kind = 'training'
           and a.training_relationship_id = v_wunsch.training_relationship_id)
      );
    if not found then
      raise exception 'appointment not found' using errcode = 'P0002';
    end if;
  end if;

  update public.platform_appointment_requests
     set status = p_outcome,
         resolved_at = now(),
         resolved_by = auth.uid(),
         answer = nullif(btrim(p_answer), ''),
         resulting_appointment_id = p_resulting_appointment_id
   where id = p_request_id;
  return true;
end;
$$;

COMMENT ON FUNCTION public.resolve_platform_appointment_request(p_request_id uuid, p_outcome text, p_answer text, p_resulting_appointment_id uuid) IS 'POR-011: Die Praxis beantwortet einen Terminwunsch (erledigt oder nicht moeglich) mit einer kurzen Antwort an die Person; Nachweis am Datensatz (resolved_by). Rollen der Terminverwaltung des Kontexts.';

CREATE FUNCTION public.return_fleet_key(p_bike_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  if not exists (
    select 1 from public.fleet_bikes b where b.id = p_bike_id and b.organization_id = v_org
  ) then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  update public.fleet_key_handovers k
     set returned_at = now(), returned_by = auth.uid()
   where k.bike_id = p_bike_id and k.organization_id = v_org and k.returned_at is null;
  if not found then
    raise exception 'key is not taken' using errcode = '55000';
  end if;
end;
$$;

COMMENT ON FUNCTION public.return_fleet_key(p_bike_id uuid) IS 'FLT-001: Schluessel eines Rads zuruecklegen - wer ihn hat oder eine Kollegin fuer sie. Alle Praxisrollen der Behandlung (BEF-066).';

CREATE FUNCTION public.revise_treatment_note(p_note_id uuid, p_expected_updated_at timestamp with time zone, p_content text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor     uuid;
  v_org       uuid;
  v_inhalt    text;
  v_grund     text;
  v_alt       record;
  v_patient   uuid;
  v_version   integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');

  if v_inhalt = '' then
    raise exception 'documentation must not be empty' using errcode = '22023';
  end if;

  if length(v_inhalt) > 20000 then
    raise exception 'documentation is too long' using errcode = '22023';
  end if;

  v_grund := btrim(coalesce(p_reason, ''), E' \t\r\n');

  if v_grund = '' then
    raise exception 'change reason is required' using errcode = '22023';
  end if;

  if length(v_grund) > 500 then
    raise exception 'change reason is too long' using errcode = '22023';
  end if;

  select t.id, t.appointment_id, t.content, t.status, t.updated_at
    into v_alt
  from public.treatment_notes t
  where t.id = p_note_id
    and t.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment note not found' using errcode = 'P0002';
  end if;

  if v_alt.status <> 'final' then
    raise exception 'treatment note is not final' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'treatment note was changed meanwhile' using errcode = '40001';
  end if;

  -- Eine Korrektur ohne Aenderung ist keine Korrektur. Sie waere eine Version
  -- ohne Aussage und wuerde den Verlauf verwaessern, den ADR-016 lesbar halten
  -- will.
  if v_alt.content = v_inhalt then
    raise exception 'documentation is unchanged' using errcode = '22023';
  end if;

  select coalesce(max(v.version_no), 0) + 1
    into v_version
  from public.treatment_note_versions v
  where v.note_id = p_note_id;

  insert into public.treatment_note_versions (
    organization_id, note_id, version_no, content, change_reason, author_id
  )
  values (
    v_org, p_note_id, v_version, v_inhalt, v_grund, v_actor
  );

  update public.treatment_notes
     set content    = v_inhalt,
         updated_at = now(),
         updated_by = v_actor
   where id = p_note_id
     and updated_at = p_expected_updated_at;

  if not found then
    raise exception 'treatment note was changed meanwhile' using errcode = '40001';
  end if;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = v_alt.appointment_id;


  return p_note_id;
end;
$$;

COMMENT ON FUNCTION public.revise_treatment_note(p_note_id uuid, p_expected_updated_at timestamp with time zone, p_content text, p_reason text) IS 'Korrigiert eine finalisierte Behandlungsdokumentation als neue Version mit Begruendung und protokolliert treatment_note.revised (DOK-002, ADR-016 Punkt 5 und 6).';

CREATE FUNCTION public.revoke_platform_access(p_access_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_access public.platform_accesses%rowtype;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  v_access := app.platform_access_for_update(p_access_id, v_org);
  if v_access.id is null or not app.can_manage_platform_access(v_access.relationship_kind) then
    perform app.record_denied_write(v_actor, 'platform_access.revoked', 'not allowed to manage platform access');
    return null;
  end if;

  if v_access.status = 'revoked' then
    raise exception 'platform access is already revoked' using errcode = '22023';
  end if;

  update public.platform_accesses
     set status = 'revoked', revoked_at = now(), revoked_by = v_actor, revoked_reason = 'practice',
         locked_at = null, locked_by = null
   where id = v_access.id;

  update public.platform_access_invitations
     set status = 'revoked', revoked_at = now()
   where platform_access_id = v_access.id and status = 'pending';

  perform app.log_platform_access_event(
    v_org, v_actor, 'user', 'platform_access.revoked', v_access.id,
    jsonb_build_object('surface', 'web', 'previous_status', v_access.status)
  );
  return 'revoked';
end;
$$;

COMMENT ON FUNCTION public.revoke_platform_access(p_access_id uuid) IS 'POR-002: entzieht einen Plattformzugang endgueltig und nimmt offene Einladungen zurueck. Aendert nie das Verhaeltnis (ADR-023 Punkt 5).';

CREATE FUNCTION public.revoke_staff_invitation(p_invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_staff uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_accounts() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'staff_account.invitation_revoked', 'not allowed to manage accounts');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage accounts' using errcode = '42501';
  end if;

  update public.staff_account_invitations
     set status = 'revoked', revoked_at = now(), revoked_by = v_actor
   where id = p_invitation_id
     and organization_id = v_org
     and status = 'pending'
  returning staff_member_id into v_staff;

  if not found then
    raise exception 'invitation not found' using errcode = 'P0002';
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'staff_account.invitation_revoked', 'staff_member', v_staff, 'success',
    jsonb_build_object('surface', 'web')
  );
end;
$$;

COMMENT ON FUNCTION public.revoke_staff_invitation(p_invitation_id uuid) IS 'Nimmt eine offene Einladung zurueck - nur owner. Die Zeile bleibt als Nachweis stehen (STAFF-002b, ADR-010).';

CREATE FUNCTION public.save_exercise(p_exercise_id uuid, p_name text, p_lay_name text, p_body_region text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid := auth.uid();
  v_org      uuid;
  v_name     text;
  v_lay_name text;
  v_id       uuid;
begin
  v_org := app.exercise_library_writer();
  v_name := app.exercise_required_name(p_name, 'name');
  v_lay_name := app.exercise_required_name(p_lay_name, 'lay name');
  if p_body_region is null or not (p_body_region = any (app.exercise_body_regions())) then
    raise exception 'body region is invalid' using errcode = '22023';
  end if;

  if p_exercise_id is null then
    insert into public.exercises (
      organization_id, name, lay_name, body_region, created_by, updated_by
    )
    values (v_org, v_name, v_lay_name, p_body_region, v_actor, v_actor)
    returning id into v_id;
    return v_id;
  end if;

  update public.exercises
     set name = v_name,
         lay_name = v_lay_name,
         body_region = p_body_region,
         updated_at = now(),
         updated_by = v_actor
   where id = p_exercise_id and organization_id = v_org
  returning id into v_id;

  if v_id is null then
    raise exception 'exercise not found' using errcode = 'P0002';
  end if;
  return v_id;
exception
  when unique_violation then
    raise exception 'an exercise with this name already exists' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.save_exercise(p_exercise_id uuid, p_name text, p_lay_name text, p_body_region text) IS 'UEB-001: legt eine Uebung an (ohne Kennung) oder aendert sie. Nur nach app.can_manage_exercise_library() (ANN-293).';

CREATE FUNCTION public.save_exercise_plan(p_plan_id uuid, p_title text, p_sessions_per_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan  public.exercise_plans%rowtype;
  v_title text;
begin
  v_plan := app.exercise_plan_for_write(p_plan_id);
  if v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;
  perform app.exercise_plan_relationship_open(v_plan);

  v_title := app.exercise_plan_text(p_title, 80, 'title');
  if v_title is null then
    raise exception 'title is required' using errcode = '22023';
  end if;
  if p_sessions_per_week is not null and p_sessions_per_week not between 1 and 14 then
    raise exception 'sessions per week is invalid' using errcode = '22023';
  end if;

  update public.exercise_plans
     set title = v_title,
         sessions_per_week = p_sessions_per_week,
         updated_at = now(),
         updated_by = auth.uid()
   where id = v_plan.id;
end;
$$;

COMMENT ON FUNCTION public.save_exercise_plan(p_plan_id uuid, p_title text, p_sessions_per_week integer) IS 'UEB-004: aendert Titel und Einheiten je Woche eines Entwurfs. Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.save_exercise_plan_item(p_item_id uuid, p_plan_id uuid, p_variant_id uuid, p_sets integer, p_reps_min integer, p_reps_max integer, p_duration_seconds integer, p_load text, p_tempo text, p_rest_seconds integer, p_double_progression boolean, p_note text, p_step_axis text, p_step_direction text, p_hold_seconds integer DEFAULT NULL::integer, p_per_side boolean DEFAULT false, p_times_per_day integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid := auth.uid();
  v_plan   public.exercise_plans%rowtype;
  v_item   public.exercise_plan_items%rowtype;
  v_load   text;
  v_tempo  text;
  v_note   text;
  v_id     uuid;
  v_anzahl integer;
begin
  if p_item_id is not null then
    select i.* into v_item
    from public.exercise_plan_items i
    where i.id = p_item_id;
    -- Fremde Kennung: dieselbe Antwort wie ein fremder Plan.
    v_plan := app.exercise_plan_for_write(coalesce(v_item.plan_id, extensions.gen_random_uuid()));
  else
    v_plan := app.exercise_plan_for_write(p_plan_id);
  end if;
  if v_plan.status <> 'draft' then
    raise exception 'exercise plan is not a draft' using errcode = '22023';
  end if;
  perform app.exercise_plan_relationship_open(v_plan);

  -- Dosierung (ANN-299, ANN-384)
  if p_sets is null or p_sets not between 1 and 20 then
    raise exception 'sets is invalid' using errcode = '22023';
  end if;
  if (p_reps_min is null) <> (p_reps_max is null)
     or (p_reps_min is not null and (p_reps_min not between 1 and 100
         or p_reps_max not between 1 and 100 or p_reps_max < p_reps_min)) then
    raise exception 'repetitions are invalid' using errcode = '22023';
  end if;
  if p_duration_seconds is not null and p_duration_seconds not between 1 and 3600 then
    raise exception 'duration is invalid' using errcode = '22023';
  end if;
  if (p_reps_min is null) = (p_duration_seconds is null) then
    raise exception 'repetitions or duration is required' using errcode = '22023';
  end if;
  if p_rest_seconds is not null and p_rest_seconds not between 0 and 600 then
    raise exception 'rest is invalid' using errcode = '22023';
  end if;
  if p_hold_seconds is not null and (p_hold_seconds not between 1 and 600 or p_reps_min is null) then
    raise exception 'hold is invalid' using errcode = '22023';
  end if;
  if p_times_per_day is not null and p_times_per_day not between 1 and 10 then
    raise exception 'times per day is invalid' using errcode = '22023';
  end if;
  v_load := app.exercise_plan_text(p_load, 40, 'load');
  v_tempo := app.exercise_plan_text(p_tempo, 40, 'tempo');
  v_note := app.exercise_plan_text(p_note, 500, 'note');
  if coalesce(p_double_progression, false)
     and not (p_reps_min is not null and p_reps_max > p_reps_min and v_load is not null) then
    raise exception 'double progression needs a repetition range and a load' using errcode = '22023';
  end if;

  -- Die Variante: aus der Bibliothek dieser Praxis, nicht archiviert - ausser
  -- die Position behaelt sie.
  if p_variant_id is distinct from v_item.variant_id then
    if not exists (
      select 1
      from public.exercise_variants v
      join public.exercises e on e.id = v.exercise_id
      where v.id = p_variant_id
        and v.organization_id = v_plan.organization_id
        and v.archived_at is null
        and e.archived_at is null
    ) then
      raise exception 'exercise variant not found' using errcode = 'P0002';
    end if;
  end if;

  -- Der Schritt (ANN-301): nur an einer Position aus der vorigen Fassung.
  if v_item.previous_item_id is null then
    if p_step_axis is not null or p_step_direction is not null then
      raise exception 'step needs a previous version' using errcode = '22023';
    end if;
  else
    perform app.exercise_plan_step_check(
      v_item.previous_item_id, p_variant_id, p_sets, p_reps_min, p_reps_max,
      p_duration_seconds, v_load, v_tempo, p_rest_seconds, p_step_axis, p_step_direction,
      p_hold_seconds);
  end if;

  if p_item_id is null then
    select count(*) into v_anzahl from public.exercise_plan_items i where i.plan_id = v_plan.id;
    if v_anzahl >= 30 then
      raise exception 'too many exercises in plan' using errcode = '22023';
    end if;
    insert into public.exercise_plan_items (
      organization_id, plan_id, position, variant_id, sets, reps_min, reps_max,
      duration_seconds, load, tempo, rest_seconds, double_progression, note,
      hold_seconds, per_side, times_per_day, created_by, updated_by
    )
    values (
      v_plan.organization_id, v_plan.id, v_anzahl + 1, p_variant_id, p_sets, p_reps_min,
      p_reps_max, p_duration_seconds, v_load, v_tempo, p_rest_seconds,
      coalesce(p_double_progression, false), v_note,
      p_hold_seconds, coalesce(p_per_side, false), p_times_per_day, v_actor, v_actor
    )
    returning id into v_id;
  else
    update public.exercise_plan_items
       set variant_id = p_variant_id,
           sets = p_sets,
           reps_min = p_reps_min,
           reps_max = p_reps_max,
           duration_seconds = p_duration_seconds,
           load = v_load,
           tempo = v_tempo,
           rest_seconds = p_rest_seconds,
           double_progression = coalesce(p_double_progression, false),
           note = v_note,
           hold_seconds = p_hold_seconds,
           per_side = coalesce(p_per_side, false),
           times_per_day = p_times_per_day,
           step_axis = p_step_axis,
           step_direction = p_step_direction,
           updated_at = now(),
           updated_by = v_actor
     where id = v_item.id
    returning id into v_id;
  end if;

  update public.exercise_plans
     set updated_at = now(), updated_by = v_actor
   where id = v_plan.id;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_exercise_plan_item(p_item_id uuid, p_plan_id uuid, p_variant_id uuid, p_sets integer, p_reps_min integer, p_reps_max integer, p_duration_seconds integer, p_load text, p_tempo text, p_rest_seconds integer, p_double_progression boolean, p_note text, p_step_axis text, p_step_direction text, p_hold_seconds integer, p_per_side boolean, p_times_per_day integer) IS 'UEB-004/006/012: legt eine Position im Entwurf an (ohne Kennung, ans Ende) oder aendert sie - Variante und Dosierung samt Halten, je Seite und Haeufigkeit am Tag (ANN-299, ANN-384); an einer Position aus der vorigen Fassung hoechstens ein Schritt entlang genau einer Achse (ANN-301). Nur nach app.can_write_exercise_plans(Bereich).';

CREATE FUNCTION public.save_exercise_plan_template(p_template_id uuid, p_name text, p_goal text, p_items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_name  text := btrim(coalesce(p_name, ''), E' \t\r\n');
  v_goal  text := nullif(btrim(coalesce(p_goal, ''), E' \t\r\n'), '');
  v_id    uuid;
  v_von   uuid;
  v_item  jsonb;
  v_pos   integer := 0;
  v_var   uuid;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_exercise_plan_templates() then
    raise exception 'not allowed to write exercise plan templates' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write exercise plan templates' using errcode = '42501';
  end if;

  if v_name = '' then
    raise exception 'name is required' using errcode = '22023';
  end if;
  if length(v_name) > 80 then
    raise exception 'name is too long' using errcode = '22023';
  end if;
  if v_goal is not null and length(v_goal) > 200 then
    raise exception 'goal is too long' using errcode = '22023';
  end if;
  if p_items is not null and jsonb_typeof(p_items) <> 'array' then
    raise exception 'items are invalid' using errcode = '22023';
  end if;
  if p_template_id is null and (p_items is null or jsonb_array_length(p_items) = 0) then
    raise exception 'a template needs at least one exercise' using errcode = '22023';
  end if;
  if p_items is not null and jsonb_array_length(p_items) = 0 then
    raise exception 'a template needs at least one exercise' using errcode = '22023';
  end if;
  if p_items is not null and jsonb_array_length(p_items) > 30 then
    raise exception 'a template has at most 30 exercises' using errcode = '22023';
  end if;

  begin
    if p_template_id is null then
      insert into public.exercise_plan_templates (
        organization_id, name, goal, created_by, updated_by
      )
      values (v_org, v_name, v_goal, v_actor, v_actor)
      returning id into v_id;
    else
      select t.created_by into v_von
        from public.exercise_plan_templates t
       where t.id = p_template_id and t.organization_id = v_org
       for update;
      if not found then
        raise exception 'template not found' using errcode = 'P0002';
      end if;
      if not app.can_edit_exercise_plan_template(v_von) then
        raise exception 'not allowed to change this template' using errcode = '42501';
      end if;
      update public.exercise_plan_templates
         set name = v_name,
             goal = v_goal,
             updated_at = now(),
             updated_by = v_actor
       where id = p_template_id and organization_id = v_org
      returning id into v_id;
    end if;
  exception
    when unique_violation then
      raise exception 'a template with this name already exists' using errcode = '23505';
  end;

  if p_items is null then
    return v_id;
  end if;

  delete from public.exercise_plan_template_items where template_id = v_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_pos := v_pos + 1;
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'items are invalid' using errcode = '22023';
    end if;
    begin
      v_var := (v_item ->> 'variant_id')::uuid;
    exception
      when invalid_text_representation then
        raise exception 'items are invalid' using errcode = '22023';
    end;
    -- Nur eine Variante der eigenen Bibliothek, die nicht archiviert ist -
    -- weder sie noch ihre Uebung.
    if v_var is null or not exists (
      select 1
        from public.exercise_variants v
        join public.exercises e on e.id = v.exercise_id and e.organization_id = v.organization_id
       where v.id = v_var and v.organization_id = v_org
         and v.archived_at is null and e.archived_at is null
    ) then
      raise exception 'exercise is not in the library' using errcode = '22023';
    end if;
    begin
      insert into public.exercise_plan_template_items (
        organization_id, template_id, position, variant_id, sets, reps_min, reps_max,
        duration_seconds, hold_seconds, per_side, times_per_day, load, tempo, rest_seconds,
        double_progression
      )
      values (
        v_org, v_id, v_pos, v_var,
        (v_item ->> 'sets')::smallint,
        (v_item ->> 'reps_min')::smallint,
        (v_item ->> 'reps_max')::smallint,
        (v_item ->> 'duration_seconds')::smallint,
        (v_item ->> 'hold_seconds')::smallint,
        coalesce((v_item ->> 'per_side')::boolean, false),
        (v_item ->> 'times_per_day')::smallint,
        nullif(btrim(coalesce(v_item ->> 'load', ''), E' \t\r\n'), ''),
        nullif(btrim(coalesce(v_item ->> 'tempo', ''), E' \t\r\n'), ''),
        (v_item ->> 'rest_seconds')::smallint,
        coalesce((v_item ->> 'double_progression')::boolean, false)
      );
    exception
      when unique_violation then
        raise exception 'an exercise appears twice' using errcode = '22023';
      when check_violation or not_null_violation or invalid_text_representation
           or numeric_value_out_of_range then
        raise exception 'dosage is invalid' using errcode = '22023';
    end;
  end loop;

  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_exercise_plan_template(p_template_id uuid, p_name text, p_goal text, p_items jsonb) IS 'UEB-014 (ANN-560): legt eine Vorlage der Praxis an (ohne Kennung) oder aendert sie; p_items ersetzt die Uebungen, null laesst sie stehen. Anlegen nach app.can_write_exercise_plan_templates(), aendern nur, wer sie angelegt hat, und owner.';

CREATE FUNCTION public.save_exercise_variant(p_variant_id uuid, p_exercise_id uuid, p_name text, p_lay_name text, p_instruction text, p_equipment text[], p_common_faults text, p_practice_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor          uuid := auth.uid();
  v_org            uuid;
  v_name           text;
  v_lay_name       text;
  v_instruction    text;
  v_equipment      text[];
  v_common_faults  text;
  v_practice_notes text;
  v_alt            public.exercise_variants%rowtype;
  v_geaendert      boolean;
  v_id             uuid;
begin
  v_org := app.exercise_library_writer();
  v_name := app.exercise_required_name(p_name, 'name');
  v_lay_name := app.exercise_required_name(p_lay_name, 'lay name');

  -- Schlagworte getrimmt, ohne leere und ohne doppelte (gross/klein egal), in
  -- der Reihenfolge der Eingabe; von doppelten bleibt die erste Schreibweise.
  select coalesce(array_agg(eintrag order by erste), '{}'::text[])
    into v_equipment
  from (
    select (array_agg(btrim(e, E' \t\r\n') order by nr))[1] as eintrag, min(nr) as erste
    from unnest(coalesce(p_equipment, '{}'::text[])) with ordinality as t(e, nr)
    where btrim(coalesce(e, ''), E' \t\r\n') <> ''
    group by lower(btrim(e, E' \t\r\n'))
  ) s;
  if cardinality(v_equipment) > 8 then
    raise exception 'too many equipment tags' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_equipment) e where length(e) > 40) then
    raise exception 'equipment tag is too long' using errcode = '22023';
  end if;
  v_instruction := app.exercise_optional_text(p_instruction, 'instruction');
  v_common_faults := app.exercise_optional_text(p_common_faults, 'common faults');
  v_practice_notes := app.exercise_optional_text(p_practice_notes, 'practice notes');

  if p_variant_id is null then
    if not exists (
      select 1 from public.exercises e where e.id = p_exercise_id and e.organization_id = v_org
    ) then
      raise exception 'exercise not found' using errcode = 'P0002';
    end if;

    insert into public.exercise_variants (
      organization_id, exercise_id, name, lay_name, instruction, equipment,
      common_faults, practice_notes, created_by, updated_by
    )
    values (
      v_org, p_exercise_id, v_name, v_lay_name, v_instruction, v_equipment,
      v_common_faults, v_practice_notes, v_actor, v_actor
    )
    returning id into v_id;
    return v_id;
  end if;

  select v.* into v_alt
  from public.exercise_variants v
  where v.id = p_variant_id and v.organization_id = v_org
  for update;
  if not found then
    raise exception 'exercise variant not found' using errcode = 'P0002';
  end if;

  -- ANN-386: Jede tatsaechliche Aenderung am Inhalt nimmt den Pruefvermerk.
  v_geaendert := (v_alt.name, v_alt.lay_name, v_alt.instruction, v_alt.equipment,
                  v_alt.common_faults, v_alt.practice_notes)
                 is distinct from
                 (v_name, v_lay_name, v_instruction, v_equipment,
                  v_common_faults, v_practice_notes);

  update public.exercise_variants
     set name = v_name,
         lay_name = v_lay_name,
         instruction = v_instruction,
         equipment = v_equipment,
         common_faults = v_common_faults,
         practice_notes = v_practice_notes,
         reviewed_at = case when v_geaendert then null else reviewed_at end,
         reviewed_by = case when v_geaendert then null else reviewed_by end,
         updated_at = now(),
         updated_by = v_actor
   where id = v_alt.id
  returning id into v_id;

  return v_id;
exception
  when unique_violation then
    raise exception 'a variant with this name already exists' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.save_exercise_variant(p_variant_id uuid, p_exercise_id uuid, p_name text, p_lay_name text, p_instruction text, p_equipment text[], p_common_faults text, p_practice_notes text) IS 'UEB-001/UEB-012: legt eine Variante an einer Uebung an (ohne Kennung) oder aendert sie; die Uebung bleibt dieselbe. Aendert sich der Inhalt tatsaechlich, faellt der Pruefvermerk (ANN-386). Nur nach app.can_manage_exercise_library() (ANN-293).';

CREATE FUNCTION public.save_fleet_bike(p_bike_id uuid, p_name text, p_bike_type text, p_home_depot_id uuid, p_current_depot_id uuid, p_special_location text, p_is_spare boolean, p_regular_rider_id uuid, p_planned_weekdays smallint[], p_battery text, p_note text, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org       uuid;
  v_name      text;
  v_type      text := coalesce(p_bike_type, 'load60_riemen');
  v_special   text;
  v_spare     boolean := coalesce(p_is_spare, false);
  v_rider     uuid := p_regular_rider_id;
  v_days      smallint[] := coalesce(p_planned_weekdays, '{}'::smallint[]);
  v_id        uuid;
  v_stand     timestamptz;
begin
  v_org := app.fleet_org(app.can_manage_fleet(), 'not allowed to manage the fleet');

  v_name := btrim(coalesce(p_name, ''), E' \t\r\n');
  if v_name = '' or length(v_name) > 60 then
    raise exception 'bike name is required and at most 60 characters' using errcode = '22023';
  end if;
  if not (v_type = any (app.fleet_bike_types())) then
    raise exception 'unknown bike type' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.fleet_depots d where d.id = p_home_depot_id and d.organization_id = v_org
  ) then
    raise exception 'depot not found' using errcode = 'P0002';
  end if;
  v_special := app.fleet_text(p_special_location, 120, 'special location');
  if (p_current_depot_id is null) = (v_special is null) then
    raise exception 'bike needs either a current depot or a named location' using errcode = '22023';
  end if;
  if p_current_depot_id is not null and not exists (
    select 1 from public.fleet_depots d where d.id = p_current_depot_id and d.organization_id = v_org
  ) then
    raise exception 'depot not found' using errcode = 'P0002';
  end if;
  if v_spare then
    -- Ein Ersatzrad hat keine Stammnutzer:in und keinen Wochenplan.
    v_rider := null;
    v_days := '{}'::smallint[];
  end if;
  if v_rider is not null then
    perform app.assert_staff_member_in_org(v_rider, v_org);
  end if;
  if not (v_days <@ array[1, 2, 3, 4, 5, 6, 7]::smallint[]) then
    raise exception 'weekday out of range' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct d order by d), '{}'::smallint[]) into v_days
  from unnest(v_days) d;

  if p_bike_id is null then
    insert into public.fleet_bikes (
      organization_id, name, bike_type, home_depot_id, current_depot_id, special_location,
      is_spare, regular_rider_id, planned_weekdays, battery, note, created_by, updated_by
    )
    values (
      v_org, v_name, v_type, p_home_depot_id, p_current_depot_id, v_special,
      v_spare, v_rider, v_days, app.fleet_text(p_battery, 80, 'battery'),
      app.fleet_text(p_note, 500, 'note'), auth.uid(), auth.uid()
    )
    returning id into v_id;
  else
    select b.updated_at into v_stand
    from public.fleet_bikes b
    where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
    for update;
    if not found then
      raise exception 'bike not found' using errcode = 'P0002';
    end if;
    if p_expected_updated_at is not null and v_stand <> p_expected_updated_at then
      raise exception 'bike was changed meanwhile' using errcode = '40001';
    end if;
    update public.fleet_bikes b
       set name = v_name,
           bike_type = v_type,
           home_depot_id = p_home_depot_id,
           current_depot_id = p_current_depot_id,
           special_location = v_special,
           is_spare = v_spare,
           regular_rider_id = v_rider,
           planned_weekdays = v_days,
           battery = app.fleet_text(p_battery, 80, 'battery'),
           note = app.fleet_text(p_note, 500, 'note'),
           updated_at = now(),
           updated_by = auth.uid()
     where b.id = p_bike_id
    returning b.id into v_id;
  end if;
  return v_id;
exception
  when unique_violation then
    raise exception 'bike name already in use' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.save_fleet_bike(p_bike_id uuid, p_name text, p_bike_type text, p_home_depot_id uuid, p_current_depot_id uuid, p_special_location text, p_is_spare boolean, p_regular_rider_id uuid, p_planned_weekdays smallint[], p_battery text, p_note text, p_expected_updated_at timestamp with time zone) IS 'FLT-001: Rad anlegen (p_bike_id null) oder aendern - Name, Bauart, Stammdepot, Standort (Depot oder benannter Ort), Ersatzrad, Stammnutzer:in, Wochenplan, Akku, Notiz. Nur owner (BEF-066). Gleichzeitige Aenderung: 40001.';

CREATE FUNCTION public.save_fleet_depot(p_depot_id uuid, p_name text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org  uuid;
  v_name text;
  v_note text;
  v_id   uuid;
begin
  v_org := app.fleet_org(app.can_manage_fleet(), 'not allowed to manage the fleet');
  v_name := btrim(coalesce(p_name, ''), E' \t\r\n');
  if v_name = '' or length(v_name) > 80 then
    raise exception 'depot name is required and at most 80 characters' using errcode = '22023';
  end if;
  v_note := app.fleet_text(p_note, 200, 'depot note');

  if p_depot_id is null then
    insert into public.fleet_depots (organization_id, name, note, created_by, updated_by)
    values (v_org, v_name, v_note, auth.uid(), auth.uid())
    returning id into v_id;
  else
    update public.fleet_depots d
       set name = v_name, note = v_note, updated_at = now(), updated_by = auth.uid()
     where d.id = p_depot_id and d.organization_id = v_org
    returning d.id into v_id;
    if v_id is null then
      raise exception 'depot not found' using errcode = 'P0002';
    end if;
  end if;
  return v_id;
exception
  when unique_violation then
    raise exception 'depot name already in use' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.save_fleet_depot(p_depot_id uuid, p_name text, p_note text) IS 'FLT-001: Depot anlegen (p_depot_id null) oder umbenennen. Nur owner (BEF-066).';

CREATE FUNCTION public.save_invoice_recipient(p_id uuid, p_patient_id uuid, p_recipient_kind text, p_name text, p_street text, p_house_number text, p_postal_code text, p_city text, p_reference text, p_is_default boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoice recipients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  if not exists (
    select 1 from public.patients p
    where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = '42501';
  end if;

  -- Zuerst die alte Vorgabe raeumen, sonst schlaegt der Teilindex zu, bevor
  -- die neue Zeile steht.
  if coalesce(p_is_default, false) then
    update public.invoice_recipients
       set is_default = false, updated_at = now(), updated_by = v_actor
     where patient_id = p_patient_id
       and is_default
       and (p_id is null or id <> p_id);
  end if;

  if p_id is null then
    insert into public.invoice_recipients (
      organization_id, patient_id, recipient_kind, name,
      street, house_number, postal_code, city, reference, is_default,
      created_by, updated_by
    )
    values (
      v_org, p_patient_id, p_recipient_kind, btrim(p_name),
      nullif(btrim(p_street), ''), nullif(btrim(p_house_number), ''),
      nullif(btrim(p_postal_code), ''), nullif(btrim(p_city), ''),
      nullif(btrim(p_reference), ''), coalesce(p_is_default, false),
      v_actor, v_actor
    )
    returning id into v_id;
  else
    update public.invoice_recipients
       set recipient_kind = p_recipient_kind,
           name           = btrim(p_name),
           street         = nullif(btrim(p_street), ''),
           house_number   = nullif(btrim(p_house_number), ''),
           postal_code    = nullif(btrim(p_postal_code), ''),
           city           = nullif(btrim(p_city), ''),
           reference      = nullif(btrim(p_reference), ''),
           is_default     = coalesce(p_is_default, false),
           updated_at     = now(),
           updated_by     = v_actor
     where id = p_id
       and organization_id = v_org
       and patient_id = p_patient_id
    returning id into v_id;

    if v_id is null then
      raise exception 'invoice recipient not found' using errcode = '42501';
    end if;
  end if;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_invoice_recipient(p_id uuid, p_patient_id uuid, p_recipient_kind text, p_name text, p_street text, p_house_number text, p_postal_code text, p_city text, p_reference text, p_is_default boolean) IS 'Legt einen Rechnungsempfaenger an oder aendert ihn (ABR-003a). Hoechstens einer je Patientin traegt die Vorgabe; die alte wird dabei zurueckgesetzt (ANN-076).';

CREATE FUNCTION public.save_platform_food(p_access_id uuid, p_id uuid, p_food jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_zugang public.platform_accesses%rowtype;
  v_f      jsonb;
  v_id     uuid;
begin
  -- Recht nutrition, Lesefrist, laufende Beratung, Einwilligung.
  v_profil := app.platform_nutrition_for_writing(p_access_id, true);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  v_f := app.custom_food_input(p_food);

  if p_id is null then
    -- Eine Grenze gegen Massenanlage: 500 eigene je Profil.
    if (select count(*) from public.custom_foods p where p.profile_id = v_profil.id) >= 500 then
      raise exception 'too many own foods' using errcode = '54000';
    end if;
    insert into public.custom_foods (
      organization_id, owner_kind, profile_id, name, brand, base_unit, energy_kcal, protein_g,
      fat_g, carbohydrate_g, sugar_g, fibre_g, saturated_fat_g, salt_g, portions,
      platform_access_id, platform_access_kind, created_by, updated_by
    )
    values (
      v_profil.organization_id, 'person', v_profil.id, btrim(v_f ->> 'name'),
      nullif(btrim(v_f ->> 'brand'), ''), coalesce(v_f ->> 'base_unit', 'g'),
      (v_f ->> 'energy_kcal')::numeric, (v_f ->> 'protein_g')::numeric,
      (v_f ->> 'fat_g')::numeric, (v_f ->> 'carbohydrate_g')::numeric,
      (v_f ->> 'sugar_g')::numeric, (v_f ->> 'fibre_g')::numeric,
      (v_f ->> 'saturated_fat_g')::numeric, (v_f ->> 'salt_g')::numeric,
      coalesce(v_f -> 'portions', '[]'::jsonb), v_zugang.id, v_zugang.access_kind,
      auth.uid(), auth.uid()
    )
    returning id into v_id;
    return v_id;
  end if;

  update public.custom_foods p set
    name = btrim(v_f ->> 'name'), brand = nullif(btrim(v_f ->> 'brand'), ''),
    base_unit = coalesce(v_f ->> 'base_unit', 'g'),
    energy_kcal = (v_f ->> 'energy_kcal')::numeric, protein_g = (v_f ->> 'protein_g')::numeric,
    fat_g = (v_f ->> 'fat_g')::numeric, carbohydrate_g = (v_f ->> 'carbohydrate_g')::numeric,
    sugar_g = (v_f ->> 'sugar_g')::numeric, fibre_g = (v_f ->> 'fibre_g')::numeric,
    saturated_fat_g = (v_f ->> 'saturated_fat_g')::numeric,
    salt_g = (v_f ->> 'salt_g')::numeric, portions = coalesce(v_f -> 'portions', '[]'::jsonb),
    platform_access_id = v_zugang.id, platform_access_kind = v_zugang.access_kind,
    updated_at = now(), updated_by = auth.uid()
  where p.id = p_id and p.profile_id = v_profil.id and p.owner_kind = 'person'
  returning p.id into v_id;
  if v_id is null then
    raise exception 'food not found' using errcode = 'P0002';
  end if;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_platform_food(p_access_id uuid, p_id uuid, p_food jsonb) IS 'ERN-005 (ADR-027 Punkt 9): ein eigenes Lebensmittel anlegen (p_id null) oder ändern - die Person oder ihre rechtliche Vertretung, mit Einwilligung, an der laufenden Beratung dieses Zugangs; nie die Begleitung. Höchstens 500 je Profil. Wer, steht am Datensatz.';

CREATE FUNCTION public.save_platform_questionnaire_response(p_access_id uuid, p_response_id uuid, p_instrument_id text, p_definition_version text, p_answers jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_zone   text;
  v_heute  date;
  v_alt    record;
  v_id     uuid;
begin
  if not app.platform_access_allows(p_access_id, 'questionnaire') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'treatment' then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;

  if not app.platform_questionnaire_instrument(p_instrument_id, p_definition_version) then
    raise exception 'questionnaire not available on the platform' using errcode = '22023';
  end if;

  -- Jede Antwort gegen die Definition ihrer Fassung (ABN-014, ANN-105).
  perform app.assert_questionnaire_answers(p_instrument_id, p_definition_version, p_answers);

  -- Liegt der Bogen schon abgeschlossen vor (gleich woher), fuellt die Person
  -- ihn nicht noch einmal: Aenderungen sind Sache des Termins.
  if exists (
    select 1 from public.patient_questionnaire_responses r
    where r.patient_id = v_zugang.relationship_id
      and r.organization_id = v_zugang.organization_id
      and r.instrument_id = p_instrument_id
      and r.status = 'abgeschlossen'
      and not exists (
        select 1 from public.patient_questionnaire_responses n
        where n.supersedes_response_id = r.id and n.status = 'abgeschlossen'
      )
  ) then
    raise exception 'questionnaire already completed' using errcode = '23505';
  end if;

  select o.time_zone into v_zone from public.organizations o where o.id = v_zugang.organization_id;
  v_heute := (now() at time zone v_zone)::date;

  if p_response_id is not null then
    select r.id, r.status, r.source, r.instrument_id, r.definition_version into v_alt
    from public.patient_questionnaire_responses r
    where r.id = p_response_id
      and r.patient_id = v_zugang.relationship_id
      and r.organization_id = v_zugang.organization_id
    for update;
    if not found or v_alt.source <> 'platform' then
      raise exception 'questionnaire response not found' using errcode = 'P0002';
    end if;
    if v_alt.status <> 'entwurf' then
      raise exception 'questionnaire response is completed' using errcode = '23514';
    end if;
    if v_alt.instrument_id <> p_instrument_id or v_alt.definition_version <> p_definition_version then
      raise exception 'draft identity is fixed' using errcode = '22023';
    end if;

    update public.patient_questionnaire_responses
       set answers = p_answers, recorded_on = v_heute, updated_at = now(), updated_by = auth.uid()
     where id = p_response_id;
    v_id := p_response_id;
  else
    -- Hoechstens ein Plattform-Entwurf je Bogen: ein zweiter ueberschreibt ihn.
    -- Seine Fassung steht fest (Trigger guard_questionnaire_response); eine
    -- neue Fassung heisst Entwurf verwerfen und neu beginnen (Zweitreview).
    select r.id, r.definition_version into v_alt
    from public.patient_questionnaire_responses r
    where r.patient_id = v_zugang.relationship_id
      and r.organization_id = v_zugang.organization_id
      and r.instrument_id = p_instrument_id
      and r.source = 'platform'
      and r.status = 'entwurf'
    for update;
    if found then
      if v_alt.definition_version <> p_definition_version then
        raise exception 'draft identity is fixed' using errcode = '22023';
      end if;
      v_id := v_alt.id;
      update public.patient_questionnaire_responses
         set answers = p_answers, recorded_on = v_heute, updated_at = now(), updated_by = auth.uid()
       where id = v_id;
    else
      insert into public.patient_questionnaire_responses (
        organization_id, patient_id, instrument_id, definition_version, recorded_on, answers,
        created_by, updated_by, source, source_access_id
      )
      values (
        v_zugang.organization_id, v_zugang.relationship_id, p_instrument_id, p_definition_version,
        v_heute, p_answers, auth.uid(), auth.uid(), 'platform', v_zugang.id
      )
      returning id into v_id;
    end if;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'questionnaire_save')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_platform_questionnaire_response(p_access_id uuid, p_response_id uuid, p_instrument_id text, p_definition_version text, p_answers jsonb) IS 'POR-012 (ANN-248): Die Person legt ueber die Plattform einen Entwurf ihres Befundbogens an oder ueberschreibt ihn; nur Instrumente fuer die Patient:in, Antworten gegen die Definition geprueft (ABN-014); kein zweiter Bogen, wenn einer abgeschlossen vorliegt. Recht questionnaire (Person, rechtliche Vertretung).';

CREATE FUNCTION public.save_practice_billing_profile(p_legal_name text, p_street text, p_house_number text, p_postal_code text, p_city text, p_phone text, p_email text, p_tax_number text, p_vat_id text, p_small_business boolean, p_bank_name text, p_account_holder text, p_iban text, p_bic text, p_invoice_number_prefix text, p_payment_term_days smallint, p_training_invoice_number_prefix text DEFAULT 'TR'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_neu      boolean;
  v_prefix   text;
  v_training text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_billing_profile() then
    raise exception 'not allowed to manage the billing profile' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  -- ABN-008 (BEF-100): Steuernummer ODER USt-IdNr. (Par. 14 Abs. 4 Nr. 2
  -- UStG). Die Tabelle haelt dieselbe Zusage; hier steht sie mit einer
  -- Meldung, die sagt, was fehlt.
  if nullif(btrim(coalesce(p_tax_number, '')), '') is null
     and nullif(btrim(coalesce(p_vat_id, '')), '') is null then
    raise exception 'a tax number or a vat id is required' using errcode = '22023';
  end if;

  if p_small_business is null then
    raise exception 'the vat status must be stated explicitly' using errcode = '22023';
  end if;

  -- Die IBAN wird geprueft, bevor sie in den Snapshot jeder spaeteren
  -- Rechnung wandert (ADR-009 Punkt 10). Die Tabelle haelt dieselbe Zusage;
  -- hier steht sie, damit die Meldung sagt, was zu tun ist.
  if not app.iban_checksum_ok(p_iban) then
    raise exception 'the iban checksum does not match' using errcode = '22023';
  end if;

  v_prefix   := coalesce(upper(nullif(btrim(p_invoice_number_prefix), '')), 'RG');
  v_training := coalesce(upper(nullif(btrim(p_training_invoice_number_prefix), '')), 'TR');

  -- Dieselbe Zusage wie die Constraint, nur mit einer Meldung, die sagt, was
  -- zu tun ist (ADR-009 Punkt 17).
  if v_prefix = v_training then
    raise exception 'the two invoice number prefixes must differ' using errcode = '22023';
  end if;

  v_neu := not exists (
    select 1 from public.practice_billing_profiles where organization_id = v_org
  );

  insert into public.practice_billing_profiles as b (
    organization_id, legal_name, street, house_number, postal_code, city,
    phone, email, tax_number, vat_id, small_business,
    bank_name, account_holder, iban, bic,
    invoice_number_prefix, training_invoice_number_prefix, payment_term_days,
    created_by, updated_by
  )
  values (
    v_org,
    btrim(p_legal_name), btrim(p_street), nullif(btrim(p_house_number), ''),
    btrim(p_postal_code), btrim(p_city),
    nullif(btrim(p_phone), ''), nullif(btrim(p_email), ''),
    nullif(btrim(p_tax_number), ''), nullif(btrim(p_vat_id), ''), p_small_business,
    nullif(btrim(p_bank_name), ''), nullif(btrim(p_account_holder), ''),
    -- Die IBAN steht auf dem Papier mit Leerzeichen und in der Datenbank ohne.
    upper(replace(btrim(p_iban), ' ', '')),
    upper(nullif(btrim(p_bic), '')),
    v_prefix, v_training,
    coalesce(p_payment_term_days, 14::smallint),
    v_actor, v_actor
  )
  on conflict (organization_id) do update set
    legal_name                    = excluded.legal_name,
    street                        = excluded.street,
    house_number                  = excluded.house_number,
    postal_code                   = excluded.postal_code,
    city                          = excluded.city,
    phone                         = excluded.phone,
    email                         = excluded.email,
    tax_number                    = excluded.tax_number,
    vat_id                        = excluded.vat_id,
    small_business                = excluded.small_business,
    bank_name                     = excluded.bank_name,
    account_holder                = excluded.account_holder,
    iban                          = excluded.iban,
    bic                           = excluded.bic,
    invoice_number_prefix         = excluded.invoice_number_prefix,
    training_invoice_number_prefix = excluded.training_invoice_number_prefix,
    payment_term_days             = excluded.payment_term_days,
    updated_at                    = now(),
    updated_by                    = v_actor
  where b.organization_id = v_org;

end;
$$;

COMMENT ON FUNCTION public.save_practice_billing_profile(p_legal_name text, p_street text, p_house_number text, p_postal_code text, p_city text, p_phone text, p_email text, p_tax_number text, p_vat_id text, p_small_business boolean, p_bank_name text, p_account_holder text, p_iban text, p_bic text, p_invoice_number_prefix text, p_payment_term_days smallint, p_training_invoice_number_prefix text) IS 'Legt die Praxis-Stammdaten fuer Rechnungen an oder aendert sie (ABR-000, R3-010). Nur owner (ANN-074). Prueft die IBAN nach ISO 13616 und seit ABR-010, dass die beiden Nummernkreis-Kuerzel sich unterscheiden (ADR-009 Punkt 17). Protokolliert organization.billing_profile_changed ohne Inhalte (ADR-011).';

CREATE FUNCTION public.save_practice_food(p_id uuid, p_food jsonb, p_expected timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_f     jsonb;
  v_id    uuid;
begin
  if v_actor is null or not app.can_counsel_nutrition() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  v_f := app.custom_food_input(p_food);

  if p_id is null then
    insert into public.custom_foods (
      organization_id, owner_kind, name, brand, base_unit, energy_kcal, protein_g, fat_g,
      carbohydrate_g, sugar_g, fibre_g, saturated_fat_g, salt_g, portions, created_by, updated_by
    )
    values (
      v_org, 'practice', btrim(v_f ->> 'name'), nullif(btrim(v_f ->> 'brand'), ''),
      coalesce(v_f ->> 'base_unit', 'g'), (v_f ->> 'energy_kcal')::numeric,
      (v_f ->> 'protein_g')::numeric, (v_f ->> 'fat_g')::numeric,
      (v_f ->> 'carbohydrate_g')::numeric, (v_f ->> 'sugar_g')::numeric,
      (v_f ->> 'fibre_g')::numeric, (v_f ->> 'saturated_fat_g')::numeric,
      (v_f ->> 'salt_g')::numeric, coalesce(v_f -> 'portions', '[]'::jsonb), v_actor, v_actor
    )
    returning id into v_id;
    return v_id;
  end if;

  update public.custom_foods p set
    name = btrim(v_f ->> 'name'), brand = nullif(btrim(v_f ->> 'brand'), ''),
    base_unit = coalesce(v_f ->> 'base_unit', 'g'),
    energy_kcal = (v_f ->> 'energy_kcal')::numeric, protein_g = (v_f ->> 'protein_g')::numeric,
    fat_g = (v_f ->> 'fat_g')::numeric, carbohydrate_g = (v_f ->> 'carbohydrate_g')::numeric,
    sugar_g = (v_f ->> 'sugar_g')::numeric, fibre_g = (v_f ->> 'fibre_g')::numeric,
    saturated_fat_g = (v_f ->> 'saturated_fat_g')::numeric,
    salt_g = (v_f ->> 'salt_g')::numeric, portions = coalesce(v_f -> 'portions', '[]'::jsonb),
    updated_at = now(), updated_by = v_actor
  where p.id = p_id and p.organization_id = v_org and p.owner_kind = 'practice'
    and p.archived_at is null
    and (p_expected is null or p.updated_at = p_expected)
  returning p.id into v_id;
  if v_id is null then
    if exists (select 1 from public.custom_foods p
               where p.id = p_id and p.organization_id = v_org and p.owner_kind = 'practice'
                 and p.archived_at is null) then
      raise exception 'food changed meanwhile' using errcode = '40001';
    end if;
    raise exception 'food not found' using errcode = 'P0002';
  end if;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_practice_food(p_id uuid, p_food jsonb, p_expected timestamp with time zone) IS 'ERN-005 (ADR-027 Punkt 9): ein Lebensmittel der Praxis anlegen (p_id null) oder ändern - Nährwerte von der Verpackung je 100 g bzw. ml, Portionen. Allein app.can_counsel_nutrition; mit p_expected gegen gleichzeitiges Ändern.';

CREATE FUNCTION public.save_questionnaire_response(p_patient_id uuid, p_response_id uuid, p_instrument_id text, p_definition_version text, p_recorded_on date, p_answers jsonb, p_supersedes_response_id uuid DEFAULT NULL::uuid, p_change_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_zone     text;
  v_alt      record;
  v_id       uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_questionnaire_response() then
    raise exception 'not allowed to record questionnaires' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to record questionnaires' using errcode = '42501';
  end if;

  -- Eine fremde Akte und eine nicht vorhandene sehen gleich aus (ADR-003).
  perform 1 from public.patients p
  where p.id = p_patient_id and p.organization_id = v_org;
  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  if p_recorded_on is null then
    raise exception 'date is required' using errcode = '22023';
  end if;
  select o.time_zone into v_zone from public.organizations o where o.id = v_org;
  if p_recorded_on > (now() at time zone coalesce(v_zone, 'Europe/Berlin'))::date then
    raise exception 'date lies in the future' using errcode = '22023';
  end if;

  -- ABN-014 (BEF-101): Form, dann Inhalt gegen die Definition dieser Fassung.
  perform app.assert_questionnaire_answers(p_instrument_id, p_definition_version, p_answers);

  if p_response_id is not null then
    select r.status, r.patient_id, r.instrument_id, r.definition_version,
           r.supersedes_response_id, r.recorded_on
      into v_alt
    from public.patient_questionnaire_responses r
    where r.id = p_response_id and r.organization_id = v_org
    for update;

    if not found or v_alt.patient_id <> p_patient_id then
      raise exception 'questionnaire response not found' using errcode = 'P0002';
    end if;
    if v_alt.status <> 'entwurf' then
      raise exception 'questionnaire response is completed' using errcode = '23514';
    end if;
    -- Was ein Entwurf festhaelt, laesst sich beim Ueberschreiben nicht
    -- aendern - und wird dann abgewiesen statt still uebergangen.
    if v_alt.instrument_id <> p_instrument_id
       or v_alt.definition_version <> p_definition_version
       or p_supersedes_response_id is not null
       or p_change_reason is not null then
      raise exception 'draft identity is fixed' using errcode = '22023';
    end if;
    -- ABN-014: Eine Korrektur bleibt am Erhebungstag der korrigierten.
    if v_alt.supersedes_response_id is not null and p_recorded_on <> v_alt.recorded_on then
      raise exception 'a correction keeps the date of the original' using errcode = '22023';
    end if;

    update public.patient_questionnaire_responses
       set answers     = p_answers,
           recorded_on = p_recorded_on,
           updated_at  = now(),
           updated_by  = v_actor
     where id = p_response_id;


    return p_response_id;
  end if;

  if p_supersedes_response_id is not null then
    select r.status, r.patient_id, r.instrument_id, r.recorded_on
      into v_alt
    from public.patient_questionnaire_responses r
    where r.id = p_supersedes_response_id and r.organization_id = v_org
    for update;

    if not found or v_alt.patient_id <> p_patient_id then
      raise exception 'questionnaire response not found' using errcode = 'P0002';
    end if;
    if v_alt.status <> 'abgeschlossen' then
      raise exception 'only a completed questionnaire can be corrected' using errcode = '23514';
    end if;
    if v_alt.instrument_id <> p_instrument_id then
      raise exception 'correction must use the same instrument' using errcode = '23514';
    end if;
    -- ABN-014 (BEF-101 Punkt 2): Erhebungstag und Korrekturzeitpunkt sind
    -- getrennt. Der Tag bleibt der der korrigierten Erhebung; wann korrigiert
    -- wurde, sagt created_at.
    if p_recorded_on <> v_alt.recorded_on then
      raise exception 'a correction keeps the date of the original' using errcode = '22023';
    end if;
    if p_change_reason is null or length(btrim(p_change_reason)) < 3 then
      raise exception 'a correction needs a reason' using errcode = '22023';
    end if;
    if exists (
      select 1 from public.patient_questionnaire_responses r
      where r.supersedes_response_id = p_supersedes_response_id
    ) then
      raise exception 'questionnaire response already corrected' using errcode = '23505';
    end if;
  elsif p_change_reason is not null then
    raise exception 'a reason belongs to a correction' using errcode = '22023';
  end if;

  -- Kennung und Version pruefen die Constraints der Tabelle.
  insert into public.patient_questionnaire_responses (
    organization_id, patient_id, instrument_id, definition_version, recorded_on, answers,
    supersedes_response_id, change_reason, created_by, updated_by
  )
  values (
    v_org, p_patient_id, p_instrument_id, p_definition_version, p_recorded_on, p_answers,
    p_supersedes_response_id, nullif(btrim(p_change_reason), ''), v_actor, v_actor
  )
  returning id into v_id;


  return v_id;
end;
$$;

COMMENT ON FUNCTION public.save_questionnaire_response(p_patient_id uuid, p_response_id uuid, p_instrument_id text, p_definition_version text, p_recorded_on date, p_answers jsonb, p_supersedes_response_id uuid, p_change_reason text) IS 'Legt eine Erhebung an, korrigiert eine abgeschlossene als neue Erhebung oder ueberschreibt einen Entwurf (FRB-002b, ANN-103). owner, therapist, team_lead; protokolliert als questionnaire_response.created/updated.';

CREATE FUNCTION public.save_team_message(p_message uuid, p_remind_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_m     public.team_messages%rowtype;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  -- Auf ein gleichzeitiges Entfernen warten und danach frisch lesen: Was es
  -- übersteht, hinge sonst am leeren Anker (Zweitreview TEAM-002, Runde 4).
  perform 1 from public.team_messages where id = p_message and organization_id = v_org for share;
  v_m := app.team_readable_message(p_message, v_org, v_staff);
  if v_m.id is null then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  if p_remind_at is not null
     and (p_remind_at < now() + interval '1 minute' or p_remind_at > now() + interval '90 days') then
    raise exception 'reminder must be one minute to 90 days ahead' using errcode = '22023';
  end if;
  insert into public.team_saved_messages (organization_id, message_id, staff_member_id, remind_at)
  values (v_org, p_message, v_staff, p_remind_at)
  on conflict (message_id, staff_member_id)
  do update set remind_at = excluded.remind_at, done = false;
end;
$$;

CREATE FUNCTION public.save_territory(p_territory_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_postal_codes text[], p_day_parts jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor  uuid;
  v_org    uuid;
  v_id     uuid;
  v_stand  timestamptz;
  v_codes  text[];
  v_belegt text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_working_hours() then
    raise exception 'not allowed to write territories' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write territories' using errcode = '42501';
  end if;

  if p_name is null or length(btrim(p_name)) not between 1 and 60 then
    raise exception 'invalid name' using errcode = '22023';
  end if;
  if not app.territory_day_parts_valid(coalesce(p_day_parts, '[]'::jsonb)) then
    raise exception 'invalid day parts' using errcode = '22023';
  end if;

  select coalesce(array_agg(distinct btrim(c) order by btrim(c)), array[]::text[])
    into v_codes
  from unnest(coalesce(p_postal_codes, array[]::text[])) c
  where btrim(c) <> '';
  if cardinality(v_codes) > 200 then
    raise exception 'too many postal codes' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_codes) c where c !~ '^[0-9]{5}$') then
    raise exception 'invalid postal code' using errcode = '22023';
  end if;

  if p_territory_id is null then
    begin
      insert into public.territories (organization_id, name, day_parts, created_by, updated_by)
      values (v_org, btrim(p_name), coalesce(p_day_parts, '[]'::jsonb), v_actor, v_actor)
      returning id into v_id;
    exception
      when unique_violation then
        raise exception 'territory name taken' using errcode = '23505';
    end;
  else
    select t.updated_at into v_stand
    from public.territories t
    where t.id = p_territory_id and t.organization_id = v_org
    for update;
    if not found then
      raise exception 'territory not found' using errcode = 'P0002';
    end if;
    if p_expected_updated_at is null or v_stand <> p_expected_updated_at then
      raise exception 'territory changed' using errcode = '40001';
    end if;
    begin
      update public.territories t
         set name       = btrim(p_name),
             day_parts  = coalesce(p_day_parts, '[]'::jsonb),
             updated_at = clock_timestamp(),
             updated_by = v_actor
       where t.id = p_territory_id;
    exception
      when unique_violation then
        raise exception 'territory name taken' using errcode = '23505';
    end;
    v_id := p_territory_id;
    delete from public.territory_postal_codes pc where pc.territory_id = v_id;
  end if;

  -- Eine Postleitzahl, die schon einem anderen Gebiet gehoert, wird genannt:
  -- Sie ist eine Praxisregel und kein Personendatum.
  select pc.postal_code into v_belegt
  from public.territory_postal_codes pc
  where pc.organization_id = v_org
    and pc.postal_code = any (v_codes)
  order by pc.postal_code
  limit 1;
  if v_belegt is not null then
    raise exception 'postal code already assigned: %', v_belegt using errcode = '23505';
  end if;

  insert into public.territory_postal_codes (organization_id, territory_id, postal_code)
  select v_org, v_id, c from unnest(v_codes) c;


  return v_id;
end;
$_$;

COMMENT ON FUNCTION public.save_territory(p_territory_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_postal_codes text[], p_day_parts jsonb) IS 'Legt ein Gebiet an oder ersetzt Name, Postleitzahlen und Gebietstage (PRX-002). owner, team_lead, office; Stand-Pruefung; eine Postleitzahl hoechstens in einem Gebiet; auditiert.';

CREATE FUNCTION public.save_training_profile(p_relationship_id uuid, p_fields jsonb, p_expected timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_ende   date;
  v_stand  timestamptz;
  v_neu    timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_access_training_protocols() then
    raise exception 'not allowed to write training profiles' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  select t.contract_ended_on into v_ende
  from public.training_relationships t
  where t.id = p_relationship_id and t.organization_id = v_org
  for update;
  if not found then
    raise exception 'training relationship not found' using errcode = '42501';
  end if;
  if v_ende is not null then
    raise exception 'training relationship has ended' using errcode = '23514';
  end if;

  if p_fields is null or jsonb_typeof(p_fields) <> 'object' or exists (
    select 1 from jsonb_object_keys(p_fields) k
    where k not in ('goals', 'equipment', 'time_budget', 'places', 'limits', 'history', 'preferences')
  ) or exists (
    select 1 from jsonb_each(p_fields) e
    where jsonb_typeof(e.value) not in ('string', 'null')
  ) then
    raise exception 'profile fields invalid' using errcode = '22023';
  end if;

  select p.updated_at into v_stand
  from public.training_profiles p
  where p.training_relationship_id = p_relationship_id;
  if v_stand is distinct from p_expected then
    raise exception 'training profile changed meanwhile' using errcode = '40001';
  end if;

  -- Ein leeres Feld ist kein Eintrag (app.leer_zu_null).
  insert into public.training_profiles as p (
    training_relationship_id, organization_id, goals, equipment, time_budget, places,
    limits, history, preferences, created_by, updated_by
  )
  values (
    p_relationship_id, v_org,
    app.leer_zu_null(p_fields ->> 'goals'),
    app.leer_zu_null(p_fields ->> 'equipment'),
    app.leer_zu_null(p_fields ->> 'time_budget'),
    app.leer_zu_null(p_fields ->> 'places'),
    app.leer_zu_null(p_fields ->> 'limits'),
    app.leer_zu_null(p_fields ->> 'history'),
    app.leer_zu_null(p_fields ->> 'preferences'),
    v_actor, v_actor
  )
  on conflict (training_relationship_id) do update
     set goals       = excluded.goals,
         equipment   = excluded.equipment,
         time_budget = excluded.time_budget,
         places      = excluded.places,
         limits      = excluded.limits,
         history     = excluded.history,
         preferences = excluded.preferences,
         -- Mindestens eine Mikrosekunde spaeter: Der neue Stand unterscheidet
         -- sich immer vom erwarteten, auch in derselben Transaktion.
         updated_at  = greatest(now(), p.updated_at + interval '1 microsecond'),
         updated_by  = v_actor
  returning p.updated_at into v_neu;

  return v_neu;
end;
$$;

COMMENT ON FUNCTION public.save_training_profile(p_relationship_id uuid, p_fields jsonb, p_expected timestamp with time zone) IS 'KND-005: Voraussetzungsprofil schreiben (owner, Trainingsbetreuung; ANN-287) - sieben Freitexte, mit erwartetem Stand gegen stilles Ueberschreiben, nicht nach dem Vertragsende. Liefert den neuen Stand.';

CREATE FUNCTION public.save_training_protocol(p_appointment_id uuid, p_content text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(id uuid, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_inhalt   text;
  v_termin   record;
  v_protokoll record;
  v_id       uuid;
  v_stand    timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_access_training_protocols() then
    perform app.record_denied_write(v_actor, 'training_protocol.updated', 'not allowed to write training protocols');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write training protocols' using errcode = '42501';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');
  if v_inhalt = '' then
    raise exception 'training protocol must not be empty' using errcode = '22023';
  end if;
  if length(v_inhalt) > 20000 then
    raise exception 'training protocol is too long' using errcode = '22023';
  end if;

  select a.id, a.status, a.training_relationship_id
    into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    and a.kind = 'training'
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_termin.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be protocolled' using errcode = '22023';
  end if;
  if v_termin.status = 'no_show' then
    raise exception 'no-show appointment cannot be protocolled' using errcode = '22023';
  end if;

  select p.id, p.status, p.updated_at
    into v_protokoll
  from public.training_protocols p
  where p.appointment_id = p_appointment_id
  for update;

  -- IF und RAISE lassen FOUND stehen; das "if not found" unten liest weiter
  -- das Ergebnis der Abfrage oben.
  if found and v_protokoll.status = 'final' then
    raise exception 'finalized training protocol cannot be changed' using errcode = '22023';
  end if;

  -- Zweitreview 2: Ein Entwurf entsteht nur am bestaetigten oder
  -- durchgefuehrten Termin - nie an einem dokumentierten, dessen Protokoll
  -- der Loeschlauf genommen hat (ANN-183).
  if v_termin.status not in ('confirmed', 'completed') then
    raise exception 'appointment cannot be protocolled' using errcode = '22023';
  end if;

  if not found then
    begin
      insert into public.training_protocols (
        organization_id, training_relationship_id, appointment_id, status, content,
        created_by, updated_by
      )
      values (
        v_org, v_termin.training_relationship_id, p_appointment_id, 'draft', v_inhalt,
        v_actor, v_actor
      )
      returning training_protocols.id, training_protocols.updated_at into v_id, v_stand;
    exception
      when unique_violation then
        raise exception 'training protocol already exists' using errcode = '23505';
    end;


    return query select v_id, v_stand;
    return;
  end if;

  if v_protokoll.status = 'final' then
    raise exception 'finalized training protocol cannot be changed' using errcode = '22023';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;
  if v_protokoll.updated_at is distinct from p_expected_updated_at then
    raise exception 'training protocol was changed meanwhile' using errcode = '40001';
  end if;

  update public.training_protocols p
     set content    = v_inhalt,
         updated_at = now(),
         updated_by = v_actor
   where p.id = v_protokoll.id
  returning p.updated_at into v_stand;


  return query select v_protokoll.id, v_stand;
end;
$$;

COMMENT ON FUNCTION public.save_training_protocol(p_appointment_id uuid, p_content text, p_expected_updated_at timestamp with time zone) IS 'TRN-009: legt das Trainingsprotokoll eines Trainingstermins als Entwurf an oder aendert den Entwurf (erwarteter Stand Pflicht). owner, trainer (ANN-184); protokolliert training_protocol.created/updated ohne Inhalt, abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.save_treatment_draft_findings(p_appointment_id uuid, p_findings jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_termin  record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  select a.id, a.patient_id, a.kind into v_termin
  from public.appointments a
  where a.id = p_appointment_id and a.organization_id = v_org;
  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;
  if v_termin.kind <> 'therapy' then
    raise exception 'only a treatment appointment can be documented' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.treatment_notes t
    where t.appointment_id = p_appointment_id and t.addendum_to_note_id is null
      and t.status <> 'draft'
  ) then
    raise exception 'documentation is already finalized' using errcode = '22023';
  end if;

  if p_findings is null or p_findings = '{}'::jsonb
     or (p_findings ? 'auswahl' and p_findings->'auswahl' = '{}'::jsonb) then
    delete from public.treatment_draft_findings f where f.appointment_id = p_appointment_id;
  else
    if jsonb_typeof(p_findings) <> 'object' or octet_length(p_findings::text) > 65536 then
      raise exception 'findings must be a small object' using errcode = '22023';
    end if;
    insert into public.treatment_draft_findings (organization_id, appointment_id, findings, updated_by)
    values (v_org, p_appointment_id, p_findings, v_actor)
    on conflict (appointment_id) do update
      set findings = excluded.findings, updated_at = now(), updated_by = v_actor;
  end if;

end;
$$;

COMMENT ON FUNCTION public.save_treatment_draft_findings(p_appointment_id uuid, p_findings jsonb) IS 'Sichert die noch nicht uebernommenen Befundangaben eines Behandlungstermins, getrennt vom Dokumentationsentwurf; leer verwirft sie (ABN-015, BEF-103). Dokumentierende Rollen; nur solange die Dokumentation nicht festgeschrieben ist; protokolliert ohne Inhalt.';

CREATE FUNCTION public.search_foods(p_query text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not app.can_counsel_nutrition() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return app.food_search(app.current_organization_id(), p_query, p_limit);
end;
$$;

COMMENT ON FUNCTION public.search_foods(p_query text, p_limit integer) IS 'ERN-004: Lebensmittelsuche der Beratung (app.can_counsel_nutrition) im eigenen Katalog - höchstens 50 Treffer mit Nährwerten je 100 g bzw. ml und Portionen. Der Suchbegriff wird nicht gespeichert.';

CREATE FUNCTION public.search_patients(p_query text, p_limit integer DEFAULT 10) RETURNS TABLE(id uuid, given_name text, family_name text, date_of_birth date, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_such  text;
  v_limit integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft. Derselbe Schnitt wie die Kartei: wer sie lesen darf, darf in ihr
  -- suchen - die Suche ist kein zweites Recht (ADR-004 Punkt 6).
  if not app.can_read_patient_directory() then
    -- G6b: abgewiesen wird mit null Zeilen und einem denied-Eintrag.
    perform app.record_denied_read(auth.uid(), 'patient_directory.read', 'not allowed to read patient directory');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to read patient directory' using errcode = '42501';
  end if;

  v_such := app.suchform(btrim(coalesce(p_query, '')));

  -- Zu kurz ist kein Fehler, sondern schlicht kein Treffer. Eine Meldung
  -- taugte hier als Existenz-Orakel und hilft niemandem beim Tippen.
  if length(v_such) < app.patient_search_min_length() then
    return;
  end if;

  v_limit := least(greatest(coalesce(p_limit, 10), 1), 25);

  return query
    select
      p.id,
      pe.given_name,
      pe.family_name,
      pc.date_of_birth,
      p.status
    from public.patients p
    join public.persons pe on pe.id = p.person_id
    left join public.patient_contact_details pc on pc.patient_id = p.id
    where p.organization_id = v_org
      and (
        -- Beide Schreibrichtungen: "Mustermann Max" und "Max Mustermann"
        -- fuehren zum selben Treffer.
        position(v_such in app.suchform(pe.given_name || ' ' || pe.family_name)) > 0
        or position(v_such in app.suchform(pe.family_name || ' ' || pe.given_name)) > 0
      )
    -- Laufende Versorgung zuerst: wer heute behandelt wird, wird oefter
    -- gesucht als ein abgeschlossener Fall.
    order by (p.status = 'active') desc, pe.family_name, pe.given_name, p.id
    limit v_limit;
end;
$$;

COMMENT ON FUNCTION public.search_patients(p_query text, p_limit integer) IS 'Serverseitige Patientensuche fuer das Suchfeld auf jeder Seite (UX-004). Mindestens drei Zeichen, hoechstens 25 Treffer, nur Name, Geburtsdatum und Versorgungsstatus.';

CREATE FUNCTION public.search_platform_foods(p_access_id uuid, p_query text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  -- Nur, wer die Ernährung sehen darf und eine laufende Beratung hat - die
  -- Begleitung nie (ADR-027 Punkt 3).
  if not app.platform_access_allows(p_access_id, 'nutrition')
     or (app.platform_nutrition_profile(p_access_id)).id is null then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select a.organization_id into v_org from public.platform_accesses a where a.id = p_access_id;
  return app.food_search(v_org, p_query, p_limit);
end;
$$;

COMMENT ON FUNCTION public.search_platform_foods(p_access_id uuid, p_query text, p_limit integer) IS 'ERN-004: Lebensmittelsuche auf der Plattform - Recht nutrition (Person, rechtliche Vertretung; nie die Begleitung) und eine laufende Beratung am Verhältnis des Zugangs. Liefert Bezugsdaten, keine Personendaten; darum kein Eintrag platform_representation.read. Der Suchbegriff wird nicht gespeichert.';

CREATE FUNCTION public.search_team_messages(p_query text DEFAULT NULL::text, p_channel uuid DEFAULT NULL::uuid, p_author uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(id uuid, channel_id uuid, channel_kind text, parent_id uuid, author_staff_member_id uuid, author_name text, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_nadel text := btrim(coalesce(p_query, ''));
  v_zone  text;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if length(v_nadel) > 100
     or (v_nadel <> '' and length(v_nadel) < 2)
     or (v_nadel = '' and (p_channel is null or p_author is not null)) then
    raise exception 'search needs two to 100 characters' using errcode = '22023';
  end if;
  select coalesce(o.time_zone, 'Europe/Berlin') into v_zone
  from public.organizations o where o.id = v_org;

  return query
  select m.id, m.channel_id, c.kind, m.parent_id, m.author_staff_member_id,
         app.team_staff_name(m.author_staff_member_id), m.body, m.created_at
  from public.team_messages m
  join public.team_channels c on c.id = m.channel_id
  where m.organization_id = v_org and m.removed_at is null and m.created_at <= now()
    and app.team_channel_readable(m.channel_id, v_org, v_staff)
    and (p_channel is null or m.channel_id = p_channel)
    and (p_author is null or m.author_staff_member_id = p_author)
    and (p_from is null or (m.created_at at time zone v_zone)::date >= p_from)
    and (p_to is null or (m.created_at at time zone v_zone)::date <= p_to)
    and (v_nadel = '' or strpos(lower(m.body), lower(v_nadel)) > 0)
  order by m.created_at desc, m.id desc
  limit 50;
end;
$$;

CREATE FUNCTION public.session_status(p_bedient boolean DEFAULT false) RETURNS TABLE(locked boolean, reason text, seconds_until_idle integer, seconds_until_max integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session uuid := app.jwt_session_id();
  v_passkey timestamptz := app.jwt_passkey_authentication();
  v_offen boolean;
  v_zeiten record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if v_session is not null and v_passkey is not null then
    insert into public.session_unlocks as u (session_id, user_id, passkey_ok)
    values (v_session, auth.uid(), app.passkey_sign_in_approved(v_passkey))
    on conflict (session_id) do update
      set passkey_ok = coalesce(u.passkey_ok, excluded.passkey_ok)
      where u.user_id = excluded.user_id;
  end if;

  v_offen := app.session_open();

  if p_bedient and v_offen then
    insert into public.session_activity as s (session_id, user_id, last_activity_at)
    values (v_session, auth.uid(), now())
    on conflict (session_id) do update
      set last_activity_at = excluded.last_activity_at
      where s.user_id = excluded.user_id;

    delete from public.session_activity s
    where s.last_activity_at < now() - interval '1 day';
  end if;

  if not v_offen and app.session_consumed() then
    return query select true, 'verbraucht'::text, 0, 0;
    return;
  end if;

  select * into v_zeiten from app.session_times();

  if not v_offen then
    return query select
      true,
      case
        when v_zeiten.last_authentication is null
          or v_zeiten.last_authentication > now() + interval '1 minute' then 'unbekannt'
        when now() >= v_zeiten.last_authentication + app.session_max_duration() then 'hoechstdauer'
        else 'inaktiv'
      end,
      0,
      0;
    return;
  end if;

  return query select
    false,
    null::text,
    greatest(0, floor(extract(epoch from (v_zeiten.last_activity + app.session_idle_timeout() - now())))::integer),
    greatest(0, floor(extract(epoch from (v_zeiten.last_authentication + app.session_max_duration() - now())))::integer);
end;
$$;

COMMENT ON FUNCTION public.session_status(p_bedient boolean) IS 'Stand der Sitzungssperre (ADR-025): gesperrt mit Grund (inaktiv, hoechstdauer, verbraucht, unbekannt), sonst die Sekunden bis zu beiden Fristen. Mit p_bedient = true vermerkt der Aufruf eine Bedienung - nur, solange die Sitzung offen ist. Kein Inhalt, keine Auditzeile.';

CREATE FUNCTION public.set_appointment_grid(p_minutes smallint) RETURNS smallint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   smallint;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_change_appointment_grid() then
    raise exception 'not allowed to change the appointment grid' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the appointment grid' using errcode = '42501';
  end if;

  if p_minutes is null or p_minutes not in (5, 10, 15) then
    raise exception 'unsupported appointment grid' using errcode = '22023';
  end if;

  select o.appointment_grid_minutes into v_alt
  from public.organizations o
  where o.id = v_org
  for update;

  if not found then
    raise exception 'organization not found' using errcode = 'P0002';
  end if;

  -- Speichern ohne tatsaechliche Aenderung ist kein Vorgang.
  if v_alt = p_minutes then
    return v_alt;
  end if;

  update public.organizations
     set appointment_grid_minutes = p_minutes
   where id = v_org;


  return p_minutes;
end;
$$;

COMMENT ON FUNCTION public.set_appointment_grid(p_minutes smallint) IS 'Setzt das praxisweite Minutenraster (5, 10 oder 15) und protokolliert organization.appointment_grid_changed (CAL-005, ADR-010). Nur owner.';

CREATE FUNCTION public.set_appointment_notification(p_appointment_id uuid, p_channels text[]) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_patient  uuid;
  v_kind     text;
  v_stand    timestamptz;
  v_kanaele  text[];
  v_kanal    text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Der Vermerk gehoert zur Terminorganisation und traegt dasselbe Recht wie
  -- das Aendern eines Termins (ADR-004).
  if not app.can_update_appointment() then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  select a.patient_id, a.kind, a.patient_relevant_changed_at
    into v_patient, v_kind, v_stand
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_kind = 'internal' then
    raise exception 'event has nobody to notify' using errcode = '22023';
  end if;

  -- Doppelte Angaben sind kein Fehler, aber auch kein zweiter Vermerk.
  v_kanaele := (
    select coalesce(array_agg(distinct k order by k), array[]::text[])
    from unnest(coalesce(p_channels, array[]::text[])) as k
    where k is not null
  );

  foreach v_kanal in array v_kanaele loop
    if v_kanal not in ('slip', 'phone', 'in_person', 'email') then
      raise exception 'unknown notification channel' using errcode = '22023';
    end if;
  end loop;

  -- Nur die gueltigen Zeilen weichen; die aelteren bleiben als Historie.
  delete from public.appointment_notifications n
  where n.appointment_id = p_appointment_id
    and n.notified_at >= v_stand;

  insert into public.appointment_notifications
    (organization_id, appointment_id, channel, notified_by)
  select v_org, p_appointment_id, k, v_actor
  from unnest(v_kanaele) as k;


  return v_kanaele;
end;
$$;

COMMENT ON FUNCTION public.set_appointment_notification(p_appointment_id uuid, p_channels text[]) IS 'Setzt die gueltigen Mitteilungswege eines Termins auf genau diese Menge; eine leere Liste nimmt den Vermerk zurueck (CAL-012, CAL-016). An einem Ereignis nicht moeglich - es gibt niemanden, dem etwas mitzuteilen waere.';

CREATE FUNCTION public.set_checkin_schedule(p_kind text, p_relationship_id uuid, p_interval_days integer, p_parameter_keys text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_rel   record;
begin
  if v_actor is null
     or not (app.can_write_exercise_plans('therapy') or app.can_write_exercise_plans('training')) then
    raise exception 'not allowed to set checkin schedule' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  select * into v_rel from app.checkin_relationship(p_kind, p_relationship_id, v_org);
  if v_rel.area is null then
    raise exception 'relationship not found' using errcode = 'P0002';
  end if;
  if not app.can_write_exercise_plans(v_rel.area) then
    raise exception 'not allowed to set checkin schedule' using errcode = '42501';
  end if;
  if not v_rel.is_open then
    raise exception 'relationship has ended' using errcode = '22023';
  end if;
  if p_interval_days is null or p_interval_days not between 1 and 28 then
    raise exception 'interval out of range' using errcode = '22023';
  end if;
  if not coalesce(app.checkin_keys_valid(p_parameter_keys), false) then
    raise exception 'invalid checkin questions' using errcode = '22023';
  end if;

  insert into public.checkin_schedules (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    interval_days, parameter_keys, starts_on, created_by, updated_by
  )
  values (
    v_org, p_kind, p_relationship_id,
    case when p_kind = 'treatment' then p_relationship_id end,
    case when p_kind = 'training' then p_relationship_id end,
    p_interval_days, p_parameter_keys, app.training_today(v_org), v_actor, v_actor
  )
  -- Aendern laesst den Anfang stehen: Der naechste Check-in rechnet vom
  -- letzten (ANN-350).
  on conflict (relationship_kind, relationship_id) do update
     set interval_days = excluded.interval_days,
         parameter_keys = excluded.parameter_keys,
         updated_at = now(),
         updated_by = excluded.updated_by;
end;
$$;

COMMENT ON FUNCTION public.set_checkin_schedule(p_kind text, p_relationship_id uuid, p_interval_days integer, p_parameter_keys text[]) IS 'TRK-002: stellt den Check-in eines offenen Verhaeltnisses ein oder aendert ihn - alle 1 bis 28 Tage (ANN-350), eine bis fuenf Fragen des Takts checkin (ANN-349). Wer: app.can_write_exercise_plans des Bereichs (ANN-351). Der Schreibvorgang steht am Datensatz (updated_by, ADR-010 Fassung 3).';

CREATE FUNCTION public.set_documentation_deadline(p_days smallint) RETURNS smallint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   smallint;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_change_documentation_deadline() then
    raise exception 'not allowed to change the documentation deadline' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the documentation deadline' using errcode = '42501';
  end if;

  if p_days is null or p_days < 0 or p_days > 30 then
    raise exception 'unsupported documentation deadline' using errcode = '22023';
  end if;

  select o.documentation_auto_finalize_days into v_alt
  from public.organizations o
  where o.id = v_org
  for update;

  if not found then
    raise exception 'organization not found' using errcode = 'P0002';
  end if;

  -- Speichern ohne tatsaechliche Aenderung ist kein Vorgang.
  if v_alt = p_days then
    return v_alt;
  end if;

  update public.organizations
     set documentation_auto_finalize_days = p_days
   where id = v_org;


  return p_days;
end;
$$;

COMMENT ON FUNCTION public.set_documentation_deadline(p_days smallint) IS 'Setzt die Frist der automatischen Finalisierung in Kalendertagen (0 bis 30) und protokolliert organization.documentation_deadline_changed (DOK-004, ADR-010). Nur owner.';

CREATE FUNCTION public.set_electricity_settings(p_cents_per_kwh integer, p_wh_per_km integer, p_km_per_hour integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.has_any_role('owner') then
    raise exception 'not allowed to change electricity settings' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change electricity settings' using errcode = '42501';
  end if;
  -- Abgewiesen statt begrenzt: gespeichert wird, was eingegeben wurde.
  if p_cents_per_kwh is null or p_cents_per_kwh not between 1 and 200
     or p_wh_per_km is null or p_wh_per_km not between 1 and 100
     or p_km_per_hour is null or p_km_per_hour not between 1 and 30 then
    raise exception 'electricity settings out of range' using errcode = '22023';
  end if;

  update public.organizations o
     set electricity_cents_per_kwh = p_cents_per_kwh,
         electricity_wh_per_km = p_wh_per_km,
         electricity_km_per_hour = p_km_per_hour
   where o.id = v_org;

  return jsonb_build_object(
    'cents_per_kwh', p_cents_per_kwh, 'wh_per_km', p_wh_per_km, 'km_per_hour', p_km_per_hour
  );
end;
$$;

COMMENT ON FUNCTION public.set_electricity_settings(p_cents_per_kwh integer, p_wh_per_km integer, p_km_per_hour integer) IS 'ORG-008: setzt Strompreis (ct/kWh, 1-200), Verbrauch bei höchster Stufe (Wh/km, 1-100) und Strecke je Arbeitsstunde (km, 1-30) der eigenen Praxis. Nur owner. Ohne Auditeintrag (ADR-010 Fassung 3).';

CREATE FUNCTION public.set_exercise_archived(p_exercise_id uuid, p_archived boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  v_org := app.exercise_library_writer();
  if p_archived is null then
    raise exception 'archived is required' using errcode = '22023';
  end if;

  update public.exercises
     set archived_at = case when p_archived then coalesce(archived_at, now()) end,
         archived_by = case when p_archived then coalesce(archived_by, v_actor) end,
         updated_at = now(),
         updated_by = v_actor
   where id = p_exercise_id and organization_id = v_org;

  if not found then
    raise exception 'exercise not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.set_exercise_archived(p_exercise_id uuid, p_archived boolean) IS 'UEB-001 (ANN-296): nimmt eine Uebung aus der Bibliothek oder holt sie zurueck. Nur nach app.can_manage_exercise_library().';

CREATE FUNCTION public.set_exercise_variant_archived(p_variant_id uuid, p_archived boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  v_org := app.exercise_library_writer();
  if p_archived is null then
    raise exception 'archived is required' using errcode = '22023';
  end if;

  update public.exercise_variants
     set archived_at = case when p_archived then coalesce(archived_at, now()) end,
         archived_by = case when p_archived then coalesce(archived_by, v_actor) end,
         updated_at = now(),
         updated_by = v_actor
   where id = p_variant_id and organization_id = v_org;

  if not found then
    raise exception 'exercise variant not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.set_exercise_variant_archived(p_variant_id uuid, p_archived boolean) IS 'UEB-001 (ANN-296): nimmt eine Variante aus der Bibliothek oder holt sie zurueck. Nur nach app.can_manage_exercise_library().';

CREATE FUNCTION public.set_exercise_variant_reviewed(p_variant_id uuid, p_reviewed boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_org   uuid;
begin
  v_org := app.exercise_library_writer();
  if p_reviewed is null then
    raise exception 'reviewed is required' using errcode = '22023';
  end if;

  update public.exercise_variants
     set reviewed_at = case when p_reviewed then coalesce(reviewed_at, now()) end,
         reviewed_by = case when p_reviewed then coalesce(reviewed_by, v_actor) end,
         updated_at = now(),
         updated_by = v_actor
   where id = p_variant_id and organization_id = v_org;

  if not found then
    raise exception 'exercise variant not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.set_exercise_variant_reviewed(p_variant_id uuid, p_reviewed boolean) IS 'UEB-012 (ANN-386): setzt oder nimmt den Pruefvermerk einer Variante - die Praxis hat sie fachlich durchgesehen. Nur nach app.can_manage_exercise_library(); Person und Zeit stehen an der Zeile.';

CREATE FUNCTION public.set_fleet_checkup_interval(p_days integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.fleet_org(app.can_manage_fleet(), 'not allowed to change the checkup interval');
  if p_days is not null and (p_days < 1 or p_days > 90) then
    raise exception 'checkup interval must be between 1 and 90 days' using errcode = '22023';
  end if;
  update public.organizations o
     set fleet_checkup_interval_days = p_days
   where o.id = v_org;
end;
$$;

COMMENT ON FUNCTION public.set_fleet_checkup_interval(p_days integer) IS 'FLT-009 (ANN-570): setzt den Check-Up-Rhythmus der Praxis in Tagen (1 bis 90, null = aus). Nur owner (app.can_manage_fleet). Ohne Auditeintrag (ADR-010 Fassung 3).';

CREATE FUNCTION public.set_invoice_recipient(p_invoice_id uuid, p_recipient_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_status  text;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select i.status, i.patient_id into v_status, v_patient
  from public.invoices i
  where i.id = p_invoice_id and i.organization_id = v_org
  for update;

  if not found then
    raise exception 'invoice not found' using errcode = '42501';
  end if;

  if v_status <> 'draft' then
    raise exception 'an issued invoice cannot be changed' using errcode = '23514';
  end if;

  -- Ein Empfaenger einer anderen Patientin waere die Falschzuordnung aus
  -- PROJECT_PRINCIPLES.md 13 - und zwar die teuerste: eine Rechnung mit
  -- fremden Leistungen an eine fremde Anschrift.
  if p_recipient_id is not null and not exists (
    select 1 from public.invoice_recipients r
    where r.id = p_recipient_id and r.patient_id = v_patient and r.organization_id = v_org
  ) then
    raise exception 'recipient does not belong to this patient' using errcode = '22023';
  end if;

  update public.invoices set recipient_id = p_recipient_id where id = p_invoice_id;

end;
$$;

COMMENT ON FUNCTION public.set_invoice_recipient(p_invoice_id uuid, p_recipient_id uuid) IS 'Waehlt den Empfaenger eines Rechnungsentwurfs (ABR-003a). null heisst: die Patientin selbst. Ein Empfaenger einer anderen Patientin wird abgewiesen (PROJECT_PRINCIPLES.md 13).';

CREATE FUNCTION public.set_leave_entitlement(p_staff_member_id uuid, p_year integer, p_days integer, p_carryover_days integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.staff_request_org(app.can_manage_staff_employment(), 'not allowed to manage leave entitlements');
  perform app.assert_staff_member_in_org(p_staff_member_id, v_org);
  if p_staff_member_id is null then
    raise exception 'staff member is required' using errcode = '22023';
  end if;
  if p_year is null or p_year not between 2000 and 2100
     or p_days is null or p_days not between 0 and 60
     or coalesce(p_carryover_days, 0) not between 0 and 60 then
    raise exception 'leave entitlement is invalid' using errcode = '22023';
  end if;

  insert into public.staff_leave_entitlements
    (organization_id, staff_member_id, year, days, carryover_days, updated_by)
  values (v_org, p_staff_member_id, p_year, p_days, coalesce(p_carryover_days, 0), auth.uid())
  on conflict (organization_id, staff_member_id, year)
  do update set days = excluded.days,
                carryover_days = excluded.carryover_days,
                updated_at = now(),
                updated_by = excluded.updated_by;
end;
$$;

COMMENT ON FUNCTION public.set_leave_entitlement(p_staff_member_id uuid, p_year integer, p_days integer, p_carryover_days integer) IS 'URL-001: Urlaubsanspruch und Uebertrag einer Person fuer ein Jahr eintragen - nur owner (Beschaeftigungsangaben, app.can_manage_staff_employment).';

CREATE FUNCTION public.set_location_garage(p_location_id uuid, p_street text, p_house_number text, p_postal_code text, p_city text, p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.has_any_role('owner') then
    raise exception 'not allowed to change the garage' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the garage' using errcode = '42501';
  end if;

  if nullif(btrim(p_street), '') is null
     or nullif(btrim(p_postal_code), '') is null
     or nullif(btrim(p_city), '') is null then
    raise exception 'street, postal code and city are required' using errcode = '22023';
  end if;

  perform app.assert_geocode_result(p_lat, p_lon, p_precision, p_confirmed);

  -- Adresse zuerst, dann die Koordinate: Der Trigger verwirft sie sonst im
  -- selben Schreibvorgang als "zur alten Adresse gehoerig".
  update public.locations l
     set garage_street       = btrim(p_street),
         garage_house_number = nullif(btrim(p_house_number), ''),
         garage_postal_code  = btrim(p_postal_code),
         garage_city         = btrim(p_city)
   where l.id = p_location_id
     and l.organization_id = v_org;

  if not found then
    raise exception 'location not found' using errcode = 'P0002';
  end if;

  update public.locations l
     set garage_lat = p_lat,
         garage_lon = p_lon,
         garage_geocode_precision = p_precision
   where l.id = p_location_id;
end;
$$;

COMMENT ON FUNCTION public.set_location_garage(p_location_id uuid, p_street text, p_house_number text, p_postal_code text, p_city text, p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean) IS 'UBK-015, ANN-240: setzt Adresse und Koordinate der Garage eines Standorts (Beginn und Ende der Tour). Nur owner, ohne Auditeintrag.';

CREATE FUNCTION public.set_location_tour_start(p_location_id uuid, p_street text, p_house_number text, p_postal_code text, p_city text, p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.has_any_role('owner') then
    raise exception 'not allowed to change the tour start' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the tour start' using errcode = '42501';
  end if;

  if nullif(btrim(p_street), '') is null
     or nullif(btrim(p_postal_code), '') is null
     or nullif(btrim(p_city), '') is null then
    raise exception 'street, postal code and city are required' using errcode = '22023';
  end if;

  perform app.assert_geocode_result(p_lat, p_lon, p_precision, p_confirmed);

  -- Adresse zuerst, dann die Koordinate: Der Trigger verwirft sie sonst im
  -- selben Schreibvorgang als "zur alten Adresse gehoerig".
  update public.locations l
     set street       = btrim(p_street),
         house_number = nullif(btrim(p_house_number), ''),
         postal_code  = btrim(p_postal_code),
         city         = btrim(p_city)
   where l.id = p_location_id
     and l.organization_id = v_org;

  if not found then
    raise exception 'location not found' using errcode = 'P0002';
  end if;

  update public.locations l
     set lat = p_lat,
         lon = p_lon,
         geocode_precision = p_precision
   where l.id = p_location_id;

end;
$$;

COMMENT ON FUNCTION public.set_location_tour_start(p_location_id uuid, p_street text, p_house_number text, p_postal_code text, p_city text, p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean) IS 'MAP-006a: setzt Adresse und Koordinate des Startorts einer Tagesroute (Depot des Standorts). Nur owner.';

CREATE FUNCTION public.set_message_response_workdays(p_workdays integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not app.has_any_role('owner') then
    raise exception 'not allowed to change the response time' using errcode = '42501';
  end if;
  if p_workdays is null or p_workdays not between 1 and 10 then
    raise exception 'response time out of range' using errcode = '22023';
  end if;
  update public.organizations o
     set message_response_workdays = p_workdays
   where o.id = app.current_organization_id();
end;
$$;

COMMENT ON FUNCTION public.set_message_response_workdays(p_workdays integer) IS 'KOM-002 (ANN-309): die Antwortfrist der Praxis in Werktagen, 1 bis 10. Nur owner. Gilt fuer Fragen, die danach eingehen.';

CREATE FUNCTION public.set_notification_kind_enabled(p_kind text, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not app.has_any_role('owner') then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if p_kind is null or not (p_kind = any (app.notification_kinds())) or p_enabled is null then
    raise exception 'invalid notification kind' using errcode = '22023';
  end if;
  if p_enabled then
    delete from public.notification_kind_switches k
     where k.organization_id = app.current_organization_id() and k.kind = p_kind;
  else
    insert into public.notification_kind_switches (organization_id, kind, disabled_by)
    values (app.current_organization_id(), p_kind, auth.uid())
    on conflict (organization_id, kind) do nothing;
  end if;
end;
$$;

COMMENT ON FUNCTION public.set_notification_kind_enabled(p_kind text, p_enabled boolean) IS 'KOM-009 (ADR-024 Punkt 15): owner schaltet eine Art fuer alle ab oder wieder frei - fuer eine einzelne Person einschalten kann die Praxis nie.';

CREATE FUNCTION public.set_nutrition_notes(p_profile_id uuid, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  v_profil := app.nutrition_profile_for_writing(p_profile_id, true);
  update public.nutrition_profiles
     set notes = nullif(btrim(p_notes), ''),
         updated_at = clock_timestamp(),
         updated_by = auth.uid()
   where id = v_profil.id;
end;
$$;

COMMENT ON FUNCTION public.set_nutrition_notes(p_profile_id uuid, p_notes text) IS 'ERN-001 (ADR-027 Punkt 5): Notizen der Beratung (bis 4000 Zeichen), intern - in keiner Plattformprojektion. Allein app.can_counsel_nutrition.';

CREATE FUNCTION public.set_nutrition_overrides(p_profile_id uuid, p_energy_kcal smallint, p_protein_g smallint, p_fat_g smallint, p_carbohydrate_g smallint, p_water_ml smallint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  v_profil := app.nutrition_profile_for_writing(p_profile_id, true);
  -- Punkt 22: jeder Wert überschreibbar, auch unter die Untergrenzen; leer
  -- heißt wieder berechnet. Die Bereiche prüfen die Constraints.
  update public.nutrition_profiles
     set energy_kcal_override = p_energy_kcal,
         protein_g_override = p_protein_g,
         fat_g_override = p_fat_g,
         carbohydrate_g_override = p_carbohydrate_g,
         water_ml_override = p_water_ml,
         updated_at = clock_timestamp(),
         updated_by = auth.uid()
   where id = v_profil.id;
end;
$$;

COMMENT ON FUNCTION public.set_nutrition_overrides(p_profile_id uuid, p_energy_kcal smallint, p_protein_g smallint, p_fat_g smallint, p_carbohydrate_g smallint, p_water_ml smallint) IS 'ERN-001 (ADR-027 Punkt 22): Überschreibungen der Beratung für Energie, Eiweiß, Fett, Kohlenhydrate und Wasser; leer heißt berechnet. Auch unter Grundumsatz - dann gekennzeichnet. Allein app.can_counsel_nutrition, laufendes Profil mit Einwilligung.';

CREATE FUNCTION public.set_own_payout_account(p_iban text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  if v_staff is null then
    raise exception 'no staff member for this account' using errcode = 'P0002';
  end if;
  perform app.store_payout_account(v_org, v_staff, p_iban);
  return app.payout_account_view(v_staff);
end;
$$;

COMMENT ON FUNCTION public.set_own_payout_account(p_iban text) IS 'ERS-001 (ANN-601): hinterlegt oder ersetzt die eigene IBAN für Erstattungen, mit Prüfziffer am Server. Liefert sie maskiert.';

CREATE FUNCTION public.set_own_pin(p_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_problem text;
  v_angemeldet timestamptz := app.last_first_factor();
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.session_open() then
    raise exception 'session locked' using errcode = '42501';
  end if;
  -- Eine Freigabe per PIN zählt hier nicht: nur eine echte Anmeldung
  -- (ANN-325), ein Passkey nur freigegeben (ANN-329).
  if v_angemeldet is null or v_angemeldet < now() - app.pin_fresh_authentication() then
    raise exception 'reauthentication required' using errcode = 'P0001';
  end if;
  v_problem := app.pin_problem(p_pin);
  if v_problem is not null then
    raise exception 'pin rejected: %', v_problem using errcode = '22023';
  end if;

  insert into public.account_pins as p (user_id, pin_hash, set_at)
  values (auth.uid(), extensions.crypt(p_pin, extensions.gen_salt('bf', 10)), now())
  on conflict (user_id) do update
    set pin_hash = excluded.pin_hash,
        set_at = excluded.set_at;
end;
$$;

COMMENT ON FUNCTION public.set_own_pin(p_pin text) IS 'Legt die App-PIN des eigenen Kontos fest (ADR-025 Punkt 11): nur in offener Sitzung und hoechstens zehn Minuten nach einer Anmeldung (ANN-325); sechs Ziffern, keine triviale Folge. Speichert nur den bcrypt-Hash. Keine Auditzeile.';

CREATE FUNCTION public.set_own_profile_picture(p_image text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_bild    bytea;
  v_grund   text;
  v_alt     uuid;
  v_neu     uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();

  if p_image is null or length(p_image) > 4 * app.profile_picture_max_bytes() / 3 + 4 then
    raise exception 'profile picture rejected: size' using errcode = '22023';
  end if;
  begin
    v_bild := decode(p_image, 'base64');
  exception when others then
    raise exception 'profile picture rejected: format' using errcode = '22023';
  end;
  v_grund := app.profile_picture_problem(v_bild);
  if v_grund is not null then
    raise exception 'profile picture rejected: %', v_grund using errcode = '22023';
  end if;

  -- Je Person nacheinander: zwei gleichzeitige Bilder ersetzen einander. Wer
  -- währenddessen ausscheidet, setzt danach kein Bild mehr (Zweitreview,
  -- Befund 1) - geprüft erst nach der Sperre.
  perform 1 from public.staff_members sm
  where sm.id = v_staff and sm.employment_status = 'active' for no key update;
  if not found then
    raise exception 'not allowed to use the team chat' using errcode = '42501';
  end if;
  select p.id into v_alt from public.staff_profile_pictures p where p.staff_member_id = v_staff;
  if v_alt is not null then
    perform app.forget_profile_picture(v_org, v_alt);
  end if;

  insert into public.staff_profile_pictures (organization_id, staff_member_id, image)
  values (v_org, v_staff, v_bild)
  returning id into v_neu;
  return v_neu;
end;
$$;

COMMENT ON FUNCTION public.set_own_profile_picture(p_image text) IS 'TEAM-007 (ADR-017 Abschnitt O): das eigene Profilbild setzen oder ersetzen - Base64 eines JPEG 256 × 256 ohne Metadaten; das alte fällt mit Löschjournal. Liefert die Kennung des neuen Bildes.';

CREATE FUNCTION public.set_own_team_color(p_color text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if p_color is null or not (p_color = any (app.staff_color_palette())) then
    raise exception 'unknown color' using errcode = '22023';
  end if;

  insert into public.staff_colors (staff_member_id, organization_id, color)
  values (v_staff, v_org, p_color)
  on conflict (staff_member_id) do update set color = excluded.color;
end;
$$;

COMMENT ON FUNCTION public.set_own_team_color(p_color text) IS 'TEAM-006 (ANN-666): die eigene Farbe aus der Reihe wählen - nur für sich selbst.';

CREATE FUNCTION public.set_patient_address_coordinate(p_patient_id uuid, p_street text, p_house_number text, p_postal_code text, p_city text, p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_termine  integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Dasselbe Recht wie das Aendern der Adresse: Die Koordinate ist ein Teil
  -- von ihr (ANN-016).
  if not app.can_update_patient() then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.patients p where p.id = p_patient_id and p.organization_id = v_org
  ) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  perform app.assert_geocode_result(p_lat, p_lon, p_precision, p_confirmed);

  update public.patient_contact_details c
     set lat = p_lat,
         lon = p_lon,
         geocode_precision = p_precision
   where c.patient_id = p_patient_id
     and c.organization_id = v_org
     and c.street is not null and c.postal_code is not null and c.city is not null
     and c.street       is not distinct from nullif(btrim(p_street), '')
     and c.house_number is not distinct from nullif(btrim(p_house_number), '')
     and c.postal_code  is not distinct from nullif(btrim(p_postal_code), '')
     and c.city         is not distinct from nullif(btrim(p_city), '');

  if not found then
    -- Die Adresse wurde zwischen Geocoding und Speichern geaendert (oder ist
    -- unvollstaendig): Eine Koordinate zu einer anderen Adresse wird nicht
    -- geschrieben.
    raise exception 'address changed since geocoding' using errcode = '40001';
  end if;

  update public.appointments a
     set visit_lat = p_lat,
         visit_lon = p_lon,
         visit_geocode_precision = p_precision
   where a.patient_id = p_patient_id
     and a.organization_id = v_org
     and a.appointment_type = 'home_visit'
     and a.starts_at >= now()
     and a.visit_street       is not distinct from nullif(btrim(p_street), '')
     and a.visit_house_number is not distinct from nullif(btrim(p_house_number), '')
     and a.visit_postal_code  is not distinct from nullif(btrim(p_postal_code), '')
     and a.visit_city         is not distinct from nullif(btrim(p_city), '');
  get diagnostics v_termine = row_count;


  return v_termine;
end;
$$;

COMMENT ON FUNCTION public.set_patient_address_coordinate(p_patient_id uuid, p_street text, p_house_number text, p_postal_code text, p_city text, p_lat double precision, p_lon double precision, p_precision text, p_confirmed boolean) IS 'MAP-006a, ANN-016: einziger Schreiber der Koordinate einer Patientenadresse; uebertraegt sie in kuenftige Hausbesuche derselben Adresse (ANN-095).';

CREATE FUNCTION public.set_patient_file_document_type(p_file_id uuid, p_document_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_datei record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select f.* into v_datei
  from public.patient_files f
  where f.id = p_file_id
    and f.organization_id = app.current_organization_id()
    and f.status = 'ready'
  for update;

  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.patient_file_document_types t where t.key = p_document_type
  ) then
    raise exception 'unknown document type %', p_document_type using errcode = '22023';
  end if;

  if not app.can_correct_patient_file_type()
     or not app.can_see_patient_file_type(v_datei.document_type)
     or not app.can_see_patient_file_type(p_document_type) then
    raise exception 'not allowed to correct this document type' using errcode = '42501';
  end if;

  -- Punkt 32: Eine Korrektur verschoebe Bucket, Klasse und
  -- Einwilligungsbindung. Ein Foto in der falschen Art wird geloescht und neu
  -- aufgenommen; eine Datei wird nie nachtraeglich zum Patientenfoto.
  -- Punkt 47: auch nicht zwischen den beiden Fotoarten.
  if app.is_patient_photo_type(v_datei.document_type) or app.is_patient_photo_type(p_document_type) then
    raise exception 'the document type of a photo cannot be corrected' using errcode = '22023';
  end if;

  -- Der Verordnungsscan haengt an einer Behandlungsgrundlage (Punkt 10);
  -- umgekehrt darf eine Datei an einer Grundlage nicht zu etwas werden, das dort nichts
  -- verloren hat. Die Check-Constraint faengt nur die eine Richtung.
  if p_document_type = 'verordnungsscan' and v_datei.treatment_basis_id is null then
    raise exception 'a prescription scan needs a treatment basis' using errcode = '22023';
  end if;

  if p_document_type = v_datei.document_type then
    return;
  end if;

  update public.patient_files
     set document_type = p_document_type
   where id = p_file_id;

end;
$$;

COMMENT ON FUNCTION public.set_patient_file_document_type(p_file_id uuid, p_document_type text) IS 'Korrigiert die Dokumentart und damit die Sichtbarkeit einer Datei (ADR-017 Punkt 13). Nur therapeutische Rollen, protokolliert, nur zwischen Arten, die die Person selbst sehen darf.';

CREATE FUNCTION public.set_patient_file_release(p_file_id uuid, p_released boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_datei record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- ANN-249: die Behandlungsrollen, die klinische Dateien ablegen (Punkt 13).
  if not app.can_write_clinical_patient_files() then
    raise exception 'not allowed to release files' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  select f.id, f.document_type, f.released_at into v_datei
  from public.patient_files f
  where f.id = p_file_id and f.organization_id = v_org and f.status = 'ready'
  for update;
  if not found then
    raise exception 'file not accessible' using errcode = '42501';
  end if;
  if app.is_patient_photo_type(v_datei.document_type) then
    raise exception 'photos cannot be released' using errcode = '22023';
  end if;

  if coalesce(p_released, false) then
    update public.patient_files
       set released_at = coalesce(released_at, now()),
           released_by = coalesce(released_by, v_actor)
     where id = p_file_id;
    return true;
  else
    update public.patient_files
       set released_at = null, released_by = null
     where id = p_file_id;
    return false;
  end if;
end;
$$;

COMMENT ON FUNCTION public.set_patient_file_release(p_file_id uuid, p_released boolean) IS 'POR-014 (DSN-001 D3, ANN-249): eine Datei der Akte fuer die Person auf der Plattform freigeben oder die Freigabe zuruecknehmen. owner, therapist, team_lead; nie Fotos. Nachweis am Datensatz.';

CREATE FUNCTION public.set_platform_access_locked(p_access_id uuid, p_locked boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_access public.platform_accesses%rowtype;
  v_action text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_action := case when coalesce(p_locked, false) then 'platform_access.locked'
                   else 'platform_access.unlocked' end;
  v_org := app.current_organization_id();

  v_access := app.platform_access_for_update(p_access_id, v_org);
  -- Die Rolle haengt am Verhaeltnis. Ein Zugang der eigenen Praxis, den die
  -- Rolle nicht verwalten darf, und ein unbekannter werden gleich
  -- abgewiesen: Die Kennung stammt vom Aufrufer.
  if v_access.id is null or not app.can_manage_platform_access(v_access.relationship_kind) then
    perform app.record_denied_write(v_actor, v_action, 'not allowed to manage platform access');
    return null;
  end if;

  if p_locked and v_access.status = 'active' then
    update public.platform_accesses
       set status = 'locked', locked_at = now(), locked_by = v_actor
     where id = v_access.id;
    -- Zweitreview: Ein offener Code zum neuen Kennwort gilt nach dem
    -- Entsperren nicht wieder auf.
    update public.platform_access_invitations
       set status = 'revoked', revoked_at = now()
     where platform_access_id = v_access.id and status = 'pending';
  elsif not p_locked and v_access.status = 'locked' then
    update public.platform_accesses
       set status = 'active', locked_at = null, locked_by = null
     where id = v_access.id;
  else
    raise exception 'platform access is not in a state for this' using errcode = '22023';
  end if;

  perform app.log_platform_access_event(
    v_org, v_actor, 'user', v_action, v_access.id, jsonb_build_object('surface', 'web')
  );
  return case when p_locked then 'locked' else 'active' end;
end;
$$;

COMMENT ON FUNCTION public.set_platform_access_locked(p_access_id uuid, p_locked boolean) IS 'POR-002: sperrt oder entsperrt einen Plattformzugang; wirkt bei der naechsten Anfrage (ADR-023 Punkt 18). Rollen, die das Verhaeltnis schreiben; abgewiesen mit denied und HTTP 403.';

CREATE FUNCTION public.set_platform_diary_favorite(p_access_id uuid, p_food_kind text, p_food_id uuid, p_favorite boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_zugang public.platform_accesses%rowtype;
begin
  -- Markieren wie Eintragen; abnehmen geht immer (wie löschen).
  v_profil := app.platform_diary_for_writing(p_access_id, null, coalesce(p_favorite, false));
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if p_favorite is null or p_food_kind is null or p_food_id is null then
    raise exception 'food and choice are required' using errcode = '22023';
  end if;

  if not p_favorite then
    delete from public.nutrition_diary_favorites f
    where f.profile_id = v_profil.id and f.food_kind = p_food_kind
      and coalesce(f.catalog_food_id, f.custom_food_id) = p_food_id;
  else
    if app.nutrition_diary_food(v_profil, p_food_kind, p_food_id) is null then
      raise exception 'food not found' using errcode = 'P0002';
    end if;
    if (select count(*) from public.nutrition_diary_favorites f where f.profile_id = v_profil.id)
       >= 200 then
      raise exception 'too many favorites' using errcode = '54000';
    end if;
    insert into public.nutrition_diary_favorites (
      organization_id, profile_id, food_kind, catalog_food_id, custom_food_id,
      platform_access_id, platform_access_kind, created_by
    )
    values (
      v_profil.organization_id, v_profil.id, p_food_kind,
      case when p_food_kind = 'catalog' then p_food_id end,
      case when p_food_kind <> 'catalog' then p_food_id end,
      v_zugang.id, v_zugang.access_kind, auth.uid()
    )
    on conflict do nothing;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
end;
$$;

COMMENT ON FUNCTION public.set_platform_diary_favorite(p_access_id uuid, p_food_kind text, p_food_id uuid, p_favorite boolean) IS 'ERN-008: ein Lebensmittel als Favorit markieren (mit Einwilligung, eingeschaltetem Tagebuch) oder abnehmen (immer); höchstens 200. Die Person oder ihre rechtliche Vertretung, nicht in der Lesefrist, nie die Begleitung.';

CREATE FUNCTION public.set_platform_diary_hide_numbers(p_access_id uuid, p_hide boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  -- Eine Einstellung der Ansicht, keine Angabe: ohne Einwilligung möglich.
  v_profil := app.platform_nutrition_for_writing(p_access_id, false);
  if p_hide is null then
    raise exception 'choice is required' using errcode = '22023';
  end if;
  update public.nutrition_profiles set diary_hide_numbers = p_hide where id = v_profil.id;
  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
end;
$$;

COMMENT ON FUNCTION public.set_platform_diary_hide_numbers(p_access_id uuid, p_hide boolean) IS 'ERN-008 (ADR-027 Punkt 11): "Zahlen ausblenden" ein- und ausschalten - die Einstellung der Person bzw. ihrer rechtlichen Vertretung; nicht in der Lesefrist, nie die Begleitung.';

CREATE FUNCTION public.set_platform_diary_reminders(p_access_id uuid, p_reminders jsonb, p_email boolean, p_push boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_zugang public.platform_accesses%rowtype;
  v_profil public.nutrition_profiles%rowtype;
  v_aus    boolean;
  v_art    constant text := 'nutrition_diary_reminder';
begin
  if not app.platform_access_allows(p_access_id, 'nutrition') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  if p_email is null or p_push is null or jsonb_typeof(p_reminders) is distinct from 'array'
     or jsonb_array_length(p_reminders) > 4
     or exists (
       select 1 from jsonb_array_elements(p_reminders) e
       where jsonb_typeof(e) <> 'object'
          or (e ->> 'meal') is null
          or (e ->> 'meal') not in ('breakfast', 'lunch', 'dinner', 'snack')
          or coalesce(e ->> 'time', '') !~ '^([01][0-9]|2[0-3]):(00|15|30|45)$'
          or exists (select 1 from jsonb_object_keys(e) k where k not in ('meal', 'time')))
     or (select count(distinct e ->> 'meal') from jsonb_array_elements(p_reminders) e)
        <> jsonb_array_length(p_reminders) then
    raise exception 'invalid reminders' using errcode = '22023';
  end if;
  v_aus := jsonb_array_length(p_reminders) = 0 and not p_email and not p_push;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  select p.* into v_profil from public.nutrition_profiles p
  where p.id = (app.platform_nutrition_profile(p_access_id)).id
  for update;
  if v_profil.id is null then
    raise exception 'nutrition profile not found' using errcode = 'P0002';
  end if;
  if not v_aus then
    if not app.platform_access_writable(p_access_id)
       or not app.nutrition_consent_granted(v_profil.id) then
      raise exception 'nutrition consent missing' using errcode = '42501';
    end if;
    if not v_profil.diary_enabled then
      raise exception 'nutrition diary is off' using errcode = '42501';
    end if;
  end if;

  -- Je Mahlzeit bleibt die Zeile (und ihre Kennung) erhalten: Die Grenze
  -- "eine je Mahlzeit und Tag" zählt über sie (ANN-662, Zweitreview).
  delete from public.nutrition_diary_reminders r
  where r.access_id = p_access_id and r.profile_id = v_profil.id
    and not exists (select 1 from jsonb_array_elements(p_reminders) e where e ->> 'meal' = r.meal);
  insert into public.nutrition_diary_reminders
    (organization_id, profile_id, access_id, meal, remind_at, chosen_by)
  select v_profil.organization_id, v_profil.id, p_access_id, e ->> 'meal', (e ->> 'time')::time,
         auth.uid()
  from jsonb_array_elements(p_reminders) e
  on conflict (access_id, profile_id, meal) do update
    set remind_at = excluded.remind_at,
        chosen_at = case when nutrition_diary_reminders.remind_at = excluded.remind_at
                         then nutrition_diary_reminders.chosen_at else now() end,
        chosen_by = case when nutrition_diary_reminders.remind_at = excluded.remind_at
                         then nutrition_diary_reminders.chosen_by else excluded.chosen_by end;

  -- Die Wege dieser einen Art in der Wahl des Zugangs (ADR-024 Punkt 15);
  -- die anderen Arten bleiben, wie sie sind.
  insert into public.platform_notification_settings
    (access_id, organization_id, email_kinds, push_kinds, chosen_at, chosen_by)
  values (
    p_access_id, v_zugang.organization_id,
    case when p_email then array[v_art] else '{}' end,
    case when p_push then array[v_art] else '{}' end,
    now(), auth.uid()
  )
  on conflict (access_id) do update
    set email_kinds = (
          select coalesce(array_agg(distinct k order by k), '{}')
          from unnest(array_remove(platform_notification_settings.email_kinds, v_art)
                      || case when p_email then array[v_art] else '{}'::text[] end) k),
        push_kinds = (
          select coalesce(array_agg(distinct k order by k), '{}')
          from unnest(array_remove(platform_notification_settings.push_kinds, v_art)
                      || case when p_push then array[v_art] else '{}'::text[] end) k),
        chosen_at = now(),
        chosen_by = auth.uid();
end;
$_$;

COMMENT ON FUNCTION public.set_platform_diary_reminders(p_access_id uuid, p_reminders jsonb, p_email boolean, p_push boolean) IS 'ERN-009 (ADR-027 Punkt 12, ADR-024 Punkt 15): die eigenen Erinnerungen an das Tagebuch wählen - je Mahlzeit höchstens eine Uhrzeit in Schritten von 15 Minuten, dazu Mail und Push dieser Art. Einschalten mit Einwilligung, eingeschaltetem Tagebuch, nicht in der Lesefrist; alles aus geht immer. Nur für diesen Zugang, nie die Begleitung. Kein Auditereignis.';

CREATE FUNCTION public.set_platform_exercise_days(p_access_id uuid, p_plan_id uuid, p_weekdays integer[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_plan   public.exercise_plans%rowtype;
  v_tage   smallint[];
begin
  v_zugang := app.assert_platform_exercise(p_access_id);
  -- Nur ein zugewiesener Plan des eigenen Verhaeltnisses - auch einer, der
  -- erst spaeter beginnt.
  select p.* into v_plan
  from app.platform_visible_exercise_plans(v_zugang.relationship_kind, v_zugang.relationship_id) p
  where p.id = p_plan_id and p.status = 'assigned' and p.organization_id = v_zugang.organization_id;
  if v_plan.id is null then
    raise exception 'exercise plan not found' using errcode = 'P0002';
  end if;

  if exists (select 1 from unnest(coalesce(p_weekdays, '{}'::integer[])) t
             where t is null or t not between 1 and 7) then
    raise exception 'weekday out of range' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct t order by t), '{}'::smallint[])::smallint[] into v_tage
  from unnest(coalesce(p_weekdays, '{}'::integer[])) t;

  insert into public.exercise_plan_days (
    organization_id, plan_id, weekdays, platform_access_id, platform_access_kind, recorded_by
  )
  values (
    v_plan.organization_id, v_plan.id, v_tage, v_zugang.id, v_zugang.access_kind, auth.uid()
  )
  on conflict (plan_id) do update
    set weekdays = excluded.weekdays,
        platform_access_id = excluded.platform_access_id,
        platform_access_kind = excluded.platform_access_kind,
        recorded_by = excluded.recorded_by,
        updated_at = now();

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'exercise_days')
  );
end;
$$;

COMMENT ON FUNCTION public.set_platform_exercise_days(p_access_id uuid, p_plan_id uuid, p_weekdays integer[]) IS 'UEB-011: die Person waehlt die Wochentage (1 Montag bis 7 Sonntag), an denen sie einen zugewiesenen Plan ueben moechte; leer heisst keine Tage (ANN-307). Rechte wie das Ueben (ANN-306), nicht in der Lesefrist (ANN-305).';

CREATE FUNCTION public.set_platform_notification_settings(p_access_id uuid, p_email_kinds text[], p_push_kinds text[], p_quiet_from smallint, p_quiet_until smallint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'read') then
    raise exception 'platform access denied' using errcode = '42501';
  end if;
  if p_email_kinds is null or p_push_kinds is null
     or not (p_email_kinds <@ app.notification_kinds())
     or not (p_push_kinds <@ app.notification_kinds())
     or p_quiet_from is null or p_quiet_until is null
     or p_quiet_from not between 0 and 23 or p_quiet_until not between 0 and 23 then
    raise exception 'invalid notification settings' using errcode = '22023';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  insert into public.platform_notification_settings
    (access_id, organization_id, email_kinds, push_kinds, quiet_from, quiet_until, chosen_at, chosen_by)
  values (
    p_access_id, v_zugang.organization_id,
    (select coalesce(array_agg(distinct k order by k), '{}') from unnest(p_email_kinds) k),
    (select coalesce(array_agg(distinct k order by k), '{}') from unnest(p_push_kinds) k),
    p_quiet_from, p_quiet_until, now(), auth.uid()
  )
  on conflict (access_id) do update
    set email_kinds = excluded.email_kinds,
        push_kinds  = excluded.push_kinds,
        quiet_from  = excluded.quiet_from,
        quiet_until = excluded.quiet_until,
        chosen_at   = excluded.chosen_at,
        chosen_by   = excluded.chosen_by;
end;
$$;

COMMENT ON FUNCTION public.set_platform_notification_settings(p_access_id uuid, p_email_kinds text[], p_push_kinds text[], p_quiet_from smallint, p_quiet_until smallint) IS 'KOM-009 (ADR-024 Punkt 15): die eigene Wahl je Art und Weg mit Ruhezeit, mit Zeitpunkt am Zugang. Abschalten geht immer, auch in der Lesefrist.';

CREATE FUNCTION public.set_platform_nutrition_diary(p_access_id uuid, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  -- Erst der Zugang, dann die Eingabe. Einschalten braucht die Einwilligung;
  -- Abschalten nimmt nichts weg und geht immer (ADR-027 Punkt 2).
  v_profil := app.platform_nutrition_for_writing(p_access_id, coalesce(p_enabled, false));
  if p_enabled is null then
    raise exception 'enabled is required' using errcode = '22023';
  end if;
  if v_profil.diary_enabled is distinct from p_enabled then
    update public.nutrition_profiles
       set diary_enabled = p_enabled,
           diary_changed_at = now(),
           diary_changed_by_kind = (select a.access_kind from public.platform_accesses a
                                    where a.id = p_access_id)
     where id = v_profil.id;
  end if;
  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
end;
$$;

COMMENT ON FUNCTION public.set_platform_nutrition_diary(p_access_id uuid, p_enabled boolean) IS 'ERN-002 (ADR-027 Punkt 2): die Person schaltet ihr Ernährungstagebuch ein (mit Einwilligung) und aus (immer); von Anfang an aus. Nicht in der Lesefrist. Wiederholt ohne Wirkung.';

CREATE FUNCTION public.set_platform_nutrition_target_weight(p_access_id uuid, p_target_weight_kg numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
begin
  v_profil := app.platform_nutrition_for_writing(p_access_id, true);
  -- ADR-027 Punkt 21: frei wählbar, aber nicht unter BMI 18,5 - die Zahl aus
  -- der einen Rechnung. Leer nimmt das Zielgewicht zurück.
  if p_target_weight_kg is not null
     and p_target_weight_kg < app.nutrition_target_weight_floor(v_profil.height_cm) then
    raise exception 'target weight below floor' using errcode = '22023';
  end if;
  update public.nutrition_profiles
     set target_weight_kg = p_target_weight_kg,
         target_weight_source = case when p_target_weight_kg is null then null else 'person' end,
         updated_at = clock_timestamp(),
         updated_by = auth.uid()
   where id = v_profil.id;
  perform app.log_platform_representation(
    p_access_id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_target')
  );
end;
$$;

COMMENT ON FUNCTION public.set_platform_nutrition_target_weight(p_access_id uuid, p_target_weight_kg numeric) IS 'ERN-002 (ADR-027 Punkt 21, ADR-006 Punkt 14 c): die Person wählt ihr Zielgewicht, nicht unter BMI 18,5 (22023); leer nimmt es zurück. Laufendes Profil mit Einwilligung, nicht in der Lesefrist.';

CREATE FUNCTION public.set_practice_target(p_kpi text, p_value integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   integer;
  v_max   integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_read_practice_statistics() then
    raise exception 'not allowed to change practice targets' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change practice targets' using errcode = '42501';
  end if;

  v_max := case p_kpi
    when 'revenue_cents'       then 100000000
    when 'open_items_cents'    then 100000000
    when 'utilization_percent' then 100
    when 'ending_bases'        then 10000
    when 'absences'            then 10000
  end;
  if v_max is null then
    raise exception 'unknown practice target' using errcode = '22023';
  end if;
  if p_value is not null and (p_value < 0 or p_value > v_max) then
    raise exception 'practice target out of range' using errcode = '22023';
  end if;

  -- Die Zeile sperren, falls es sie gibt; ohne Zeile ist jeder Zielwert leer.
  select case p_kpi
           when 'revenue_cents'       then t.revenue_cents
           when 'open_items_cents'    then t.open_items_cents
           when 'utilization_percent' then t.utilization_percent::integer
           when 'ending_bases'        then t.ending_bases
           when 'absences'            then t.absences
         end
    into v_alt
  from public.practice_targets t
  where t.organization_id = v_org
  for update;

  -- Speichern ohne tatsaechliche Aenderung ist kein Vorgang - und schreibt
  -- auch keine Zeile.
  if v_alt is not distinct from p_value then
    return p_value;
  end if;

  insert into public.practice_targets as t (
    organization_id, revenue_cents, open_items_cents, utilization_percent,
    ending_bases, absences, updated_at, updated_by
  )
  values (
    v_org,
    case when p_kpi = 'revenue_cents'       then p_value end,
    case when p_kpi = 'open_items_cents'    then p_value end,
    case when p_kpi = 'utilization_percent' then p_value::smallint end,
    case when p_kpi = 'ending_bases'        then p_value end,
    case when p_kpi = 'absences'            then p_value end,
    now(),
    v_actor
  )
  on conflict (organization_id) do update
     set revenue_cents       = case when p_kpi = 'revenue_cents'       then p_value else t.revenue_cents end,
         open_items_cents    = case when p_kpi = 'open_items_cents'    then p_value else t.open_items_cents end,
         utilization_percent = case when p_kpi = 'utilization_percent' then p_value::smallint else t.utilization_percent end,
         ending_bases        = case when p_kpi = 'ending_bases'        then p_value else t.ending_bases end,
         absences            = case when p_kpi = 'absences'            then p_value else t.absences end,
         updated_at          = now(),
         updated_by          = v_actor;


  return p_value;
end;
$$;

COMMENT ON FUNCTION public.set_practice_target(p_kpi text, p_value integer) IS 'STA-002: setzt oder leert (null) einen Zielwert der Praxisfuehrung und protokolliert organization.practice_target_changed mit altem und neuem Wert. Allein owner.';

CREATE FUNCTION public.set_service_catalog_session_fee(p_version_id uuid, p_session_fee_cents integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_published timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  select v.published_at into v_published
  from public.service_catalog_versions v
  where v.id = p_version_id
    and v.organization_id = app.current_organization_id();

  if not found then
    raise exception 'service catalog version not found' using errcode = '42501';
  end if;

  if v_published is not null then
    raise exception 'published service catalog version is immutable' using errcode = '23514';
  end if;

  if p_session_fee_cents is not null and p_session_fee_cents not between 0 and 1000000 then
    raise exception 'session fee out of range' using errcode = '22023';
  end if;

  update public.service_catalog_versions
     set session_fee_cents = p_session_fee_cents
   where id = p_version_id;
end;
$$;

COMMENT ON FUNCTION public.set_service_catalog_session_fee(p_version_id uuid, p_session_fee_cents integer) IS 'Setzt den Tarif des Terminhonorars an einem Entwurf der Preisliste (ABR-030, ANN-231). Nur owner; eine veroeffentlichte Version bleibt unveraenderlich.';

CREATE FUNCTION public.set_staff_account_active(p_staff_member_id uuid, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_user  uuid;
  v_alt   boolean;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_accounts() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, case when p_active is false then 'staff_account.locked' else 'staff_account.unlocked' end, 'not allowed to manage accounts');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage accounts' using errcode = '42501';
  end if;

  if p_active is null then
    raise exception 'unknown account state' using errcode = '22023';
  end if;

  select up.id, up.is_active into v_user, v_alt
  from public.staff_members sm
  join public.user_profiles up
    on up.person_id = sm.person_id
   and up.organization_id = sm.organization_id
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org
  for update of up;

  if not found then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  -- Kein Wechsel, kein Vorgang.
  if v_alt = p_active then
    return;
  end if;

  if not p_active then
    if v_user = v_actor then
      raise exception 'cannot_lock_own_account' using errcode = '22023';
    end if;

    if exists (
      select 1 from public.user_roles ur
      where ur.user_id = v_user and ur.organization_id = v_org and ur.role_key = 'owner'
    ) and not app.other_active_owners_exist(v_org, v_user) then
      raise exception 'last_owner_required' using errcode = '22023';
    end if;
  end if;

  update public.user_profiles
     set is_active = p_active
   where id = v_user
     and organization_id = v_org;

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor,
    case when p_active then 'staff_account.unlocked' else 'staff_account.locked' end,
    'staff_member', p_staff_member_id, 'success',
    jsonb_build_object('surface', 'web')
  );
end;
$$;

COMMENT ON FUNCTION public.set_staff_account_active(p_staff_member_id uuid, p_active boolean) IS 'Sperrt oder entsperrt den Zugang eines Mitarbeiterdatensatzes - nur owner. Beruehrt weder den Beschaeftigungsstatus noch das Konto beim Provider (STAFF-003).';

CREATE FUNCTION public.set_staff_account_roles(p_staff_member_id uuid, p_role_keys text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_user   uuid;
  v_alt    text[];
  v_neu    text[];
  v_dazu   text[];
  v_weg    text[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_accounts() then
    -- G6c: abgewiesen wird mit einem bestaetigten denied-Eintrag und HTTP 403.
    perform app.record_denied_write(v_actor, 'staff_account.roles_changed', 'not allowed to manage accounts');
    return;
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage accounts' using errcode = '42501';
  end if;

  perform app.assert_staff_role_keys(p_role_keys);

  -- Zielkonto ueber den Mitarbeiterdatensatz, ausschliesslich in der eigenen
  -- Organisation. Die Sperre haelt zwei gleichzeitige Rollenwechsel
  -- auseinander.
  select up.id into v_user
  from public.staff_members sm
  join public.user_profiles up
    on up.person_id = sm.person_id
   and up.organization_id = sm.organization_id
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org
  for update of up;

  if not found then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(ur.role_key order by ur.role_key), array[]::text[])
    into v_alt
  from public.user_roles ur
  where ur.user_id = v_user
    and ur.organization_id = v_org;

  select array_agg(x order by x) into v_neu
  from unnest(p_role_keys) as t(x);

  select coalesce(array_agg(x order by x), array[]::text[]) into v_dazu
  from unnest(v_neu) as t(x) where not (x = any (v_alt));

  select coalesce(array_agg(x order by x), array[]::text[]) into v_weg
  from unnest(v_alt) as t(x) where not (x = any (v_neu));

  -- Kein Unterschied, kein Vorgang.
  if cardinality(v_dazu) = 0 and cardinality(v_weg) = 0 then
    return;
  end if;

  if 'owner' = any (v_weg)
     and not app.other_active_owners_exist(v_org, v_user) then
    raise exception 'last_owner_required' using errcode = '22023';
  end if;

  delete from public.user_roles ur
   where ur.user_id = v_user
     and ur.organization_id = v_org
     and ur.role_key = any (v_weg);

  insert into public.user_roles (user_id, organization_id, role_key, created_by)
  select v_user, v_org, x, v_actor
  from unnest(v_dazu) as t(x);

  insert into public.audit_log (
    organization_id, actor_user_id, action, subject_type, subject_id, outcome, context
  )
  values (
    v_org, v_actor, 'staff_account.roles_changed', 'staff_member', p_staff_member_id, 'success',
    jsonb_build_object('surface', 'web', 'added', to_jsonb(v_dazu), 'removed', to_jsonb(v_weg))
  );
end;
$$;

COMMENT ON FUNCTION public.set_staff_account_roles(p_staff_member_id uuid, p_role_keys text[]) IS 'Setzt die Rollen eines bestehenden Zugangs - nur owner. Die letzte aktive Praxisinhaberin behaelt ihre Rolle (STAFF-002c, ADR-010, ADR-012).';

CREATE FUNCTION public.set_staff_compensation_model(p_staff_member_id uuid, p_model text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.has_any_role('owner') then
    raise exception 'not allowed to change the compensation model' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the compensation model' using errcode = '42501';
  end if;
  if p_model is not null and p_model not in ('fixed_salary', 'revenue_share') then
    raise exception 'unknown compensation model' using errcode = '22023';
  end if;

  -- Die Person sperren: Sie muss zur Organisation gehoeren.
  perform 1 from public.staff_members sm
   where sm.id = p_staff_member_id and sm.organization_id = v_org
   for update;
  if not found then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  select m.model into v_alt
  from public.staff_compensation_models m
  where m.staff_member_id = p_staff_member_id
  for update;

  if v_alt is not distinct from p_model then
    return p_model;
  end if;

  if p_model is null then
    delete from public.staff_compensation_models where staff_member_id = p_staff_member_id;
  else
    insert into public.staff_compensation_models (staff_member_id, organization_id, model, changed_at, changed_by)
    values (p_staff_member_id, v_org, p_model, now(), v_actor)
    on conflict (staff_member_id) do update
       set model = excluded.model, changed_at = now(), changed_by = v_actor;
  end if;


  return p_model;
end;
$$;

COMMENT ON FUNCTION public.set_staff_compensation_model(p_staff_member_id uuid, p_model text) IS 'STA-005: setzt (fixed_salary, revenue_share) oder entfernt (null) das Verguetungsmodell einer Person; allein owner, protokolliert als staff_member.compensation_model_changed.';

CREATE FUNCTION public.set_staff_employment_status(p_staff_member_id uuid, p_status text, p_acknowledge_future_appointments boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_alt    text;
  v_offen  integer := 0;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_employment() then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  if p_status is null or p_status not in ('active', 'inactive') then
    raise exception 'unknown employment status' using errcode = '22023';
  end if;

  -- FOR UPDATE ist hier nicht optional: die Sperre steht im Konflikt mit dem
  -- FOR-SHARE-Lock der Terminanlage. Erst danach wird gezaehlt, damit eine
  -- parallel angelegte Terminzuweisung in der Zaehlung enthalten ist.
  select sm.employment_status into v_alt
  from public.staff_members sm
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org
  for update;

  if not found then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  -- Kein Wechsel, kein Vorgang: weder Schreibzugriff noch Auditeintrag.
  if v_alt = p_status then
    return;
  end if;

  if p_status = 'inactive' then
    v_offen := app.count_staff_future_appointments(p_staff_member_id, v_org);

    if v_offen > 0 and not coalesce(p_acknowledge_future_appointments, false) then
      -- Nichts geschrieben, nichts abgesagt, nichts umgebucht.
      raise exception 'staff_has_future_appointments' using errcode = '22023';
    end if;
  end if;

  update public.staff_members
     set employment_status = p_status
   where id = p_staff_member_id
     and organization_id = v_org;

end;
$$;

COMMENT ON FUNCTION public.set_staff_employment_status(p_staff_member_id uuid, p_status text, p_acknowledge_future_appointments boolean) IS 'Deaktiviert oder reaktiviert einen Mitarbeiterdatensatz - nur owner (E10). Fragt bei offenen zukuenftigen Terminen zurueck und aendert diese Termine nie (STAFF-001, STAFF-002a).';

CREATE FUNCTION public.set_staff_member_schedulable(p_staff_member_id uuid, p_treatment boolean, p_training boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor     uuid;
  v_org       uuid;
  v_alt       record;
  v_geaendert text[] := array[]::text[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_staff_accounts() then
    -- G6c: wie die uebrigen Schreibpfade fuer Konten abgewiesen - bestaetigter
    -- denied-Eintrag, HTTP 403, keine Ausnahme, nichts geaendert.
    perform app.record_denied_write(v_actor, 'staff_member.updated', 'not allowed to manage staff');
    return;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;
  if p_staff_member_id is null or p_treatment is null or p_training is null then
    raise exception 'staff member and both values are required' using errcode = '22023';
  end if;

  select sm.schedulable_treatment, sm.schedulable_training
    into v_alt
  from public.staff_members sm
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org
  for update;

  if not found then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  if v_alt.schedulable_treatment is distinct from p_treatment then
    v_geaendert := array_append(v_geaendert, 'schedulable_treatment');
  end if;
  if v_alt.schedulable_training is distinct from p_training then
    v_geaendert := array_append(v_geaendert, 'schedulable_training');
  end if;

  -- Kein Unterschied, kein Ereignis (ADR-010).
  if array_length(v_geaendert, 1) is null then
    return;
  end if;

  update public.staff_members
     set schedulable_treatment = p_treatment,
         schedulable_training  = p_training
   where id = p_staff_member_id
     and organization_id = v_org;

end;
$$;

COMMENT ON FUNCTION public.set_staff_member_schedulable(p_staff_member_id uuid, p_treatment boolean, p_training boolean) IS 'Nimmt eine Person in den Kalender fuer Behandlungen und/oder Training auf oder nimmt sie heraus - ohne Zugang, Kennwort oder Rolle (AKTE-009, ANN-226). Allein owner; protokolliert als staff_member.updated mit den geaenderten Feldnamen, eine Abweisung als denied-Eintrag mit HTTP 403 (G6c).';

CREATE FUNCTION public.set_staff_working_hour_exception(p_staff_member_id uuid, p_date date, p_unavailable boolean, p_blocks jsonb DEFAULT '[]'::jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_tz       text;
  v_abwesend boolean;
  v_alt      jsonb;
  v_neu      jsonb;
  v_alt_ids  uuid[];
  v_neu_ids  uuid[];
  v_aktion   text;
  v_art      text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_working_hours() then
    raise exception 'not allowed to manage working hours' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage working hours' using errcode = '42501';
  end if;

  select o.time_zone into v_tz
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  if p_date is null then
    raise exception 'date is required' using errcode = '22023';
  end if;

  if not app.is_assignable_therapist(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;

  if p_blocks is null or jsonb_typeof(p_blocks) <> 'array' then
    raise exception 'blocks must be an array' using errcode = '22023';
  end if;

  v_abwesend := coalesce(p_unavailable, false);

  if v_abwesend and jsonb_array_length(p_blocks) > 0 then
    raise exception 'an unavailable day cannot have blocks' using errcode = '22023';
  end if;

  -- URL-001: dieselbe Sperre wie app.apply_leave, dann der Urlaubstag.
  perform 1 from public.staff_members sm where sm.id = p_staff_member_id for no key update;

  -- Gegen den genehmigten Urlaub, nicht gegen die Zeile: Ein Tag, der vor
  -- der Genehmigung von Hand abwesend stand, gehoert ebenso dazu (Zweitreview
  -- Runde 2).
  if exists (
    select 1 from public.staff_leave_requests r
    where r.organization_id = v_org
      and r.staff_member_id = p_staff_member_id
      and r.kind = 'leave'
      and r.status = 'approved'
      and p_date between r.starts_on and r.ends_on
  ) then
    raise exception 'day is part of approved leave' using errcode = '55000';
  end if;

  select coalesce(
           jsonb_agg(
             jsonb_build_array(a.kind, a.starts_at::text, a.ends_at::text)
             order by a.kind, a.starts_at nulls first
           ),
           '[]'::jsonb
         ),
         coalesce(array_agg(a.id order by a.kind, a.starts_at nulls first), '{}'::uuid[])
    into v_alt, v_alt_ids
  from public.staff_working_hour_exceptions a
  where a.staff_member_id = p_staff_member_id
    and a.organization_id = v_org
    and a.on_date = p_date;

  if v_abwesend then
    v_neu := jsonb_build_array(jsonb_build_array('unavailable', null, null));
  else
    begin
      select coalesce(
               jsonb_agg(jsonb_build_array('block', w.von::text, w.bis::text) order by w.von),
               '[]'::jsonb
             )
        into v_neu
      from (
        select (b ->> 'von')::time as von, (b ->> 'bis')::time as bis
        from jsonb_array_elements(p_blocks) as b
      ) w;
    exception
      when invalid_datetime_format or datetime_field_overflow
           or invalid_text_representation then
        raise exception 'working hour block is invalid' using errcode = '22023';
    end;
  end if;

  if v_alt = v_neu then
    return jsonb_array_length(v_alt);
  end if;

  -- ZK-001: ebenso ein Tag mit Freizeitausgleich - der Eintrag zählte sonst
  -- weiter im Saldo, die freie Zeit wäre aber wieder Arbeitszeit. Erst
  -- zurückweisen oder zurücknehmen (55000, ANN-595). Erst nach dem Vergleich:
  -- Unverändert Gespeichertes verrät nichts (Zweitreview Runde 2).
  if exists (
    select 1 from public.staff_working_hour_exceptions a
    where a.organization_id = v_org
      and a.staff_member_id = p_staff_member_id
      and a.on_date = p_date
      and a.time_account_entry_id is not null
  ) then
    raise exception 'day has time off in lieu' using errcode = '55000';
  end if;

  delete from public.staff_working_hour_exceptions
   where staff_member_id = p_staff_member_id
     and organization_id = v_org
     and on_date = p_date;

  if v_abwesend then
    with eingefuegt as (
      insert into public.staff_working_hour_exceptions (
        organization_id, staff_member_id, on_date, kind, created_by
      )
      values (v_org, p_staff_member_id, p_date, 'unavailable', v_actor)
      returning id
    )
    select coalesce(array_agg(id), '{}'::uuid[]) into v_neu_ids from eingefuegt;
  else
    begin
      with eingefuegt as (
        insert into public.staff_working_hour_exceptions (
          organization_id, staff_member_id, on_date, kind, starts_at, ends_at, created_by
        )
        select v_org, p_staff_member_id, p_date, 'block',
               (b ->> 'von')::time, (b ->> 'bis')::time, v_actor
        from jsonb_array_elements(p_blocks) as b
        returning id
      )
      select coalesce(array_agg(id), '{}'::uuid[]) into v_neu_ids from eingefuegt;
    exception
      when exclusion_violation then
        raise exception 'working hours overlap' using errcode = '23P01';
      when check_violation or not_null_violation
           or invalid_datetime_format or datetime_field_overflow then
        raise exception 'working hour block is invalid' using errcode = '22023';
    end;
  end if;

  v_aktion := app.working_hour_action(
    jsonb_array_length(v_alt), jsonb_array_length(v_neu)
  );

  -- Art der organisatorischen Aktion, nicht ihre Uhrzeiten.
  v_art := case
             when v_aktion = 'removed' then null
             when v_abwesend then 'unavailable'
             else 'block'
           end;


  return jsonb_array_length(v_neu);
end;
$$;

COMMENT ON FUNCTION public.set_staff_working_hour_exception(p_staff_member_id uuid, p_date date, p_unavailable boolean, p_blocks jsonb) IS 'Ersetzt die datumsbezogene Abweichung einer Person fuer einen Kalendertag vollstaendig und protokolliert staff_working_hour_exception.created/.updated/.removed (CAL-005, ADR-010). Ohne Abwesenheit und ohne Bloecke gilt wieder der Wochenplan.';

CREATE FUNCTION public.set_staff_working_hours(p_staff_member_id uuid, p_weekday smallint, p_blocks jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor    uuid;
  v_org      uuid;
  v_tz       text;
  v_heute    date;
  v_ab       date;
  v_bis      date;
  v_alt      jsonb;
  v_neu      jsonb;
  v_alt_ids  uuid[];
  v_neu_ids  uuid[];
  v_aktion   text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_working_hours() then
    raise exception 'not allowed to manage working hours' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage working hours' using errcode = '42501';
  end if;

  -- Arbeitszeiten sind Ortszeiten. Ohne hinterlegte Praxiszeitzone waeren sie
  -- nicht auswertbar; dieselbe Vorbedingung gilt an allen Schreibpfaden mit
  -- Zeitbezug (CAL-001).
  select o.time_zone into v_tz
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  if p_weekday is null or p_weekday not between 1 and 7 then
    raise exception 'weekday must be between 1 and 7' using errcode = '22023';
  end if;

  -- Fremde und unbekannte Personen sind ununterscheidbar.
  if not app.is_assignable_therapist(p_staff_member_id, v_org) then
    raise exception 'staff member not assignable' using errcode = 'P0002';
  end if;

  if p_blocks is null or jsonb_typeof(p_blocks) <> 'array' then
    raise exception 'blocks must be an array' using errcode = '22023';
  end if;

  -- AZ-001: dieselbe Sperre wie app.apply_working_time_change.
  perform 1 from public.staff_members sm where sm.id = p_staff_member_id for no key update;

  -- Die heute gueltige Fassung und ihre Grenzen (ANN-589).
  v_heute := (now() at time zone v_tz)::date;
  select h.valid_from, h.valid_until into v_ab, v_bis
  from public.staff_working_hours h
  where h.staff_member_id = p_staff_member_id
    and h.organization_id = v_org
    and daterange(h.valid_from, h.valid_until, '[]') @> v_heute
  limit 1;
  if not found then
    select max(h.valid_until) + 1 into v_ab
    from public.staff_working_hours h
    where h.staff_member_id = p_staff_member_id and h.organization_id = v_org
      and h.valid_until < v_heute;
    select min(h.valid_from) - 1 into v_bis
    from public.staff_working_hours h
    where h.staff_member_id = p_staff_member_id and h.organization_id = v_org
      and h.valid_from > v_heute;
  end if;

  -- Bestehender Stand, normalisiert und sortiert - Grundlage fuer die
  -- No-op-Erkennung und fuer die Art des Vorgangs.
  select coalesce(
           jsonb_agg(jsonb_build_array(h.starts_at::text, h.ends_at::text) order by h.starts_at),
           '[]'::jsonb
         ),
         coalesce(array_agg(h.id order by h.starts_at), '{}'::uuid[])
    into v_alt, v_alt_ids
  from public.staff_working_hours h
  where h.staff_member_id = p_staff_member_id
    and h.organization_id = v_org
    and h.weekday = p_weekday
    and daterange(h.valid_from, h.valid_until, '[]') @> v_heute;

  begin
    select coalesce(
             jsonb_agg(jsonb_build_array(w.von::text, w.bis::text) order by w.von),
             '[]'::jsonb
           )
      into v_neu
    from (
      select (b ->> 'von')::time as von, (b ->> 'bis')::time as bis
      from jsonb_array_elements(p_blocks) as b
    ) w;
  exception
    -- Unbrauchbare Zeitangaben im Array sind ein Eingabefehler, kein interner
    -- Fehler. Bewusst nur diese Faelle - ein `when others` wuerde echte
    -- Stoerungen verschlucken.
    when invalid_datetime_format or datetime_field_overflow
         or invalid_text_representation then
      raise exception 'working hour block is invalid' using errcode = '22023';
  end;

  -- Speichern ohne tatsaechliche Aenderung ist kein Vorgang: weder
  -- Schreibzugriff noch Auditeintrag.
  if v_alt = v_neu then
    return jsonb_array_length(v_alt);
  end if;

  -- ZK-001 (Zweitreview B4): Ein Freizeitausgleich ab heute an diesem
  -- Wochentag rechnet mit den bisherigen Zeiten - erst zurückweisen oder
  -- zurücknehmen (55000, ANN-595).
  if exists (
    select 1 from public.staff_time_account_entries e
    where e.organization_id = v_org and e.staff_member_id = p_staff_member_id
      and e.kind = 'time_off' and e.status = 'valid'
      and e.on_date >= v_heute and (v_bis is null or e.on_date <= v_bis)
      and extract(isodow from e.on_date) = p_weekday
  ) then
    raise exception 'day has time off in lieu' using errcode = '55000';
  end if;

  delete from public.staff_working_hours
   where staff_member_id = p_staff_member_id
     and organization_id = v_org
     and weekday = p_weekday
     and daterange(valid_from, valid_until, '[]') @> v_heute;

  begin
    with eingefuegt as (
      insert into public.staff_working_hours (
        organization_id, staff_member_id, weekday, starts_at, ends_at, created_by,
        valid_from, valid_until
      )
      select v_org, p_staff_member_id, p_weekday,
             (b ->> 'von')::time, (b ->> 'bis')::time, v_actor, v_ab, v_bis
      from jsonb_array_elements(p_blocks) as b
      returning id
    )
    select coalesce(array_agg(id), '{}'::uuid[]) into v_neu_ids from eingefuegt;
  exception
    when exclusion_violation then
      raise exception 'working hours overlap' using errcode = '23P01';
    when check_violation or not_null_violation
         or invalid_datetime_format or datetime_field_overflow then
      raise exception 'working hour block is invalid' using errcode = '22023';
  end;

  v_aktion := app.working_hour_action(
    jsonb_array_length(v_alt), jsonb_array_length(v_neu)
  );


  return jsonb_array_length(v_neu);
end;
$$;

COMMENT ON FUNCTION public.set_staff_working_hours(p_staff_member_id uuid, p_weekday smallint, p_blocks jsonb) IS 'Ersetzt einen Wochentag der heute gueltigen Fassung des Wochenplans (CAL-005, AZ-001 ANN-589). Eine kuenftige Fassung aus einem genehmigten Antrag bleibt unberuehrt. Ein leeres Array loescht den Tag. Nicht, solange ab heute ein Freizeitausgleich an dem Wochentag gilt (ZK-001, ANN-595).';

CREATE FUNCTION public.set_staff_working_week(p_staff_member_id uuid, p_days jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tag    jsonb;
  v_nr     smallint;
  v_schon  smallint[] := '{}';
  v_anzahl integer := 0;
  v_state  text;
  v_text   text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- Erst das Recht, dann die Eingabe: Wer nicht pflegen darf, erfährt nichts
  -- über die Form (ADR-023 Punkt 21). Je Tag prüft set_staff_working_hours
  -- dasselbe noch einmal.
  if not app.can_manage_working_hours() or app.current_organization_id() is null then
    raise exception 'not allowed to manage working hours' using errcode = '42501';
  end if;
  if p_days is null or jsonb_typeof(p_days) <> 'array'
     or jsonb_array_length(p_days) not between 1 and 7 then
    raise exception 'days must be an array of one to seven weekdays' using errcode = '22023';
  end if;

  for v_tag in select d from jsonb_array_elements(p_days) as d loop
    begin
      v_nr := (v_tag ->> 'weekday')::smallint;
    exception
      when invalid_text_representation or numeric_value_out_of_range then
        raise exception 'weekday must be between 1 and 7' using errcode = '22023';
    end;
    -- Jeder Wochentag höchstens einmal, verglichen nach dem Umwandeln ("01"
    -- ist 1; Zweitreview): Sonst entschiede die Reihenfolge.
    if v_nr = any (v_schon) then
      raise exception 'weekday given twice' using errcode = '22023';
    end if;
    v_schon := v_schon || v_nr;
    begin
      perform public.set_staff_working_hours(p_staff_member_id, v_nr, v_tag -> 'blocks');
    exception
      when others then
        -- Derselbe Fehler, dazu der Tag; die Transaktion fällt ganz zurück.
        get stacked diagnostics v_state = returned_sqlstate, v_text = message_text;
        raise exception using errcode = v_state, message = v_text, hint = 'weekday ' || v_nr;
    end;
    v_anzahl := v_anzahl + 1;
  end loop;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.set_staff_working_week(p_staff_member_id uuid, p_days jsonb) IS 'Wochenplan in einem Zug: ersetzt mehrere Wochentage der heute gueltigen Fassung in einer Transaktion ([{weekday, blocks}], ein bis sieben, je Tag einmal). Jeder Tag laeuft durch public.set_staff_working_hours; scheitert einer, faellt alles zurueck und der Hinweis nennt den Tag. Ohne Auditeintrag.';

CREATE FUNCTION public.set_take_along_items(p_patient_id uuid, p_items text[]) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_neu   text[];
  v_alt   text[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_update_patient() then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  if p_patient_id is null or p_items is null then
    raise exception 'patient and items are required' using errcode = '22023';
  end if;

  perform 1
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- Normalisieren: Rand weg, Leeres weg, Doppel (ohne Gross/klein) weg, die
  -- Reihenfolge der Eingabe bleibt.
  select coalesce(array_agg(x.eintrag order by x.nr), '{}'::text[])
    into v_neu
  from (
    select distinct on (lower(btrim(e.eintrag))) btrim(e.eintrag) as eintrag, e.nr
    from unnest(p_items) with ordinality as e(eintrag, nr)
    where e.eintrag is not null and btrim(e.eintrag) <> ''
    order by lower(btrim(e.eintrag)), e.nr
  ) x;

  if not app.take_along_items_valid(v_neu) then
    raise exception 'take-along items must be at most 10 entries of 1 to 60 characters'
      using errcode = '22023';
  end if;

  select cd.take_along_items into v_alt
  from public.patient_care_details cd
  where cd.patient_id = p_patient_id;

  if not found then
    insert into public.patient_care_details (
      patient_id, organization_id, take_along_items, created_by
    )
    values (p_patient_id, v_org, v_neu, v_actor);
  elsif v_alt is distinct from v_neu then
    update public.patient_care_details
       set take_along_items = v_neu
     where patient_id = p_patient_id;
  else
    return v_neu;
  end if;


  return v_neu;
end;
$$;

COMMENT ON FUNCTION public.set_take_along_items(p_patient_id uuid, p_items text[]) IS 'PRX-007: setzt die Mitnehmen-Liste einer Person, normalisiert (Rand, Leeres, Doppel). Rollen wie update_patient; protokolliert patient.updated mit dem Feldnamen (ADR-010, ANN-138).';

CREATE FUNCTION public.set_task_done(p_task_id uuid, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_patient uuid;
  v_status  text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_tasks() then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;
  if p_done is null then
    raise exception 'done flag required' using errcode = '22023';
  end if;

  select k.patient_id, k.status into v_patient, v_status
  from public.tasks k
  where k.id = p_task_id and k.organization_id = v_org
  for update;

  if not found then
    raise exception 'task not found' using errcode = 'P0002';
  end if;

  -- Ohne Wechsel kein Eintrag: Ein doppelter Tipp schreibt nichts zweimal.
  if (v_status = 'done') = p_done then
    return;
  end if;

  update public.tasks
     set status     = case when p_done then 'done' else 'open' end,
         done_at    = case when p_done then now() end,
         done_by    = case when p_done then v_actor end,
         updated_at = now(),
         updated_by = v_actor
   where id = p_task_id;

end;
$$;

COMMENT ON FUNCTION public.set_task_done(p_task_id uuid, p_done boolean) IS 'Erledigt eine Aufgabe oder oeffnet sie wieder (PRX-012); protokolliert task.completed beziehungsweise task.reopened. Ohne Wechsel kein Eintrag.';

CREATE FUNCTION public.set_team_channel_archived(p_channel uuid, p_archived boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.can_manage_team_channels() then
    raise exception 'not allowed to manage team channels' using errcode = '42501';
  end if;
  if not app.team_channel_manageable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  update public.team_channels c
     set archived_at = case when p_archived then coalesce(c.archived_at, now()) end
   where c.id = p_channel;
  if p_archived then
    perform app.team_drop_scheduled(v_org, p_channel, null);
  end if;
end;
$$;

CREATE FUNCTION public.set_team_channel_preferences(p_channel uuid, p_notify text DEFAULT NULL::text, p_starred boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_readable(p_channel, v_org, v_staff) then
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  if p_notify is not null and p_notify not in ('all', 'mentions', 'none') then
    raise exception 'notify must be all, mentions or none' using errcode = '22023';
  end if;
  insert into public.team_channel_settings (organization_id, channel_id, staff_member_id, notify, starred)
  values (v_org, p_channel, v_staff, coalesce(p_notify, 'all'), coalesce(p_starred, false))
  on conflict (channel_id, staff_member_id)
  do update set notify = coalesce(p_notify, public.team_channel_settings.notify),
                starred = coalesce(p_starred, public.team_channel_settings.starred);
end;
$$;

CREATE FUNCTION public.set_team_message_pinned(p_message uuid, p_pinned boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_m     public.team_messages%rowtype;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  -- Auf ein gleichzeitiges Entfernen warten und danach frisch lesen: Was es
  -- übersteht, hinge sonst am leeren Anker (Zweitreview TEAM-002, Runde 4).
  perform 1 from public.team_messages where id = p_message and organization_id = v_org for share;
  v_m := app.team_readable_message(p_message, v_org, v_staff);
  if v_m.id is null then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.team_channels c where c.id = v_m.channel_id and c.archived_at is not null) then
    raise exception 'team channel is archived' using errcode = '22023';
  end if;
  if not coalesce(p_pinned, false) then
    delete from public.team_message_pins where message_id = p_message;
    return;
  end if;
  -- Gleichzeitiges Anheften: die Grenze gilt für beide.
  perform 1 from public.team_channels where id = v_m.channel_id for update;
  if (select count(*) from public.team_message_pins p
      join public.team_messages pm on pm.id = p.message_id
      where p.channel_id = v_m.channel_id and pm.removed_at is null) >= 50
     and not exists (select 1 from public.team_message_pins p where p.message_id = p_message) then
    raise exception 'at most 50 pinned messages' using errcode = '22023';
  end if;
  insert into public.team_message_pins (organization_id, channel_id, message_id)
  values (v_org, v_m.channel_id, p_message)
  on conflict (message_id) do nothing;
end;
$$;

CREATE FUNCTION public.set_team_thread_following(p_root uuid, p_following boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_kanal uuid;
  v_bis   timestamptz;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  select m.channel_id into v_kanal from public.team_messages m
  where m.id = p_root and m.organization_id = v_org and m.parent_id is null
    and m.created_at <= now();
  if v_kanal is null or not app.team_channel_readable(v_kanal, v_org, v_staff) then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  v_bis := (select max(m.created_at) from public.team_messages m
            where (m.id = p_root or m.parent_id = p_root) and m.created_at <= now());
  insert into public.team_thread_states
    (organization_id, root_message_id, staff_member_id, following, read_up_to)
  values (v_org, p_root, v_staff, coalesce(p_following, false), v_bis)
  on conflict (root_message_id, staff_member_id)
  do update set following = excluded.following,
                read_up_to = case when excluded.following
                                  then greatest(public.team_thread_states.read_up_to, excluded.read_up_to)
                                  else public.team_thread_states.read_up_to end;
end;
$$;

CREATE FUNCTION public.set_travel_time_factor(p_factor numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.has_any_role('owner') then
    raise exception 'not allowed to change the travel time factor' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to change the travel time factor' using errcode = '42501';
  end if;

  -- Schritte von 0,1: Ein Wert wie 1,55 wuerde die Spalte still runden.
  -- Abgewiesen statt gerundet - gespeichert wird, was gewaehlt wurde.
  if p_factor is null
     or p_factor < 1.0
     or p_factor > 2.5
     or p_factor <> round(p_factor, 1) then
    raise exception 'travel time factor must be between 1.0 and 2.5 in steps of 0.1'
      using errcode = '22023';
  end if;

  update public.organizations o
     set travel_time_factor = p_factor
   where o.id = v_org;
end;
$$;

COMMENT ON FUNCTION public.set_travel_time_factor(p_factor numeric) IS 'UBK-010, ANN-237: setzt den Fahrzeitfaktor der Praxis (1,0 bis 2,5, Schritt 0,1). Nur owner. Ohne Auditeintrag (ADR-010 Fassung 3).';

CREATE FUNCTION public.set_treatment_basis_clinical_note(p_treatment_basis_id uuid, p_prescriber_note text, p_expected_updated_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_alt     record;
  v_text    text;
  v_stand   timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- ANN-214 (Abnahme 2026-10-09, BEF-134): wie die Grundlage selbst - alle
  -- Praxisrollen, auch das Buero; die reine Trainingsbetreuung nicht.
  if not app.can_write_treatment_bases() then
    raise exception 'not allowed to write clinical treatment basis notes' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write clinical treatment basis notes' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select t.id, t.patient_id, t.treatment_basis_kind, t.prescriber_note, t.updated_at
    into v_alt
  from public.treatment_bases t
  where t.id = p_treatment_basis_id
    and t.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  if v_alt.treatment_basis_kind = 'self_pay' then
    raise exception 'a self-pay basis carries no clinical note' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'treatment basis was changed meanwhile' using errcode = '40001';
  end if;

  -- Leer heisst: kein Hinweis. Die Laengengrenze haelt die Constraint
  -- treatment_bases_prescriber_note_check; hier bekommt sie eine Meldung.
  v_text := nullif(btrim(p_prescriber_note), '');
  if v_text is not null and length(v_text) > 2000 then
    raise exception 'clinical note is too long' using errcode = '22023';
  end if;

  update public.treatment_bases
     set prescriber_note = v_text,
         updated_at      = now(),
         updated_by      = v_actor
   where id = p_treatment_basis_id
  returning updated_at into v_stand;


  return v_stand;
end;
$$;

COMMENT ON FUNCTION public.set_treatment_basis_clinical_note(p_treatment_basis_id uuid, p_prescriber_note text, p_expected_updated_at timestamp with time zone) IS 'ABN-007, ABN-031: behandlungsrelevanter Hinweis aus einer Verordnung, an der Verordnung in der Akte. Schreiben: app.can_write_treatment_bases() (alle Praxisrollen, ANN-214 nach BEF-134). Nie am Selbstzahler.';

CREATE FUNCTION public.set_treatment_basis_icd10(p_treatment_basis_id uuid, p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor      uuid;
  v_org        uuid;
  v_patient_id uuid;
  v_kind       text;
  v_code       text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_bases() then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  select p.patient_id, p.treatment_basis_kind into v_patient_id, v_kind
  from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  v_code := nullif(upper(btrim(p_code)), '');
  if v_code is not null and v_kind = 'self_pay' then
    raise exception 'self pay treatment bases have no diagnosis' using errcode = '22023';
  end if;
  if v_code is not null
     and v_code !~ '^[A-Z][0-9]{2}(\.[0-9A-Z!*+-]{1,5})?[GVZALR]?$' then
    raise exception 'invalid ICD-10 code' using errcode = '22023';
  end if;

  update public.treatment_bases
     set diagnosis_icd10 = v_code,
         updated_at      = now(),
         updated_by      = v_actor
   where id = p_treatment_basis_id;

end;
$_$;

CREATE FUNCTION public.set_treatment_table_required(p_patient_id uuid, p_required boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   boolean;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft (ADR-004).
  if not app.can_update_patient() then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  if p_patient_id is null or p_required is null then
    raise exception 'patient and value are required' using errcode = '22023';
  end if;

  -- Nur in der eigenen Organisation suchen: ein fremder Patient ist von einer
  -- unbekannten ID nicht zu unterscheiden.
  perform 1
  from public.patients p
  where p.id = p_patient_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  select cd.treatment_table_required into v_alt
  from public.patient_care_details cd
  where cd.patient_id = p_patient_id;

  if not found then
    insert into public.patient_care_details (
      patient_id, organization_id, treatment_table_required, created_by
    )
    values (p_patient_id, v_org, p_required, v_actor);
  elsif v_alt is distinct from p_required then
    update public.patient_care_details
       set treatment_table_required = p_required
     where patient_id = p_patient_id;
  else
    -- Keine tatsaechliche Aenderung: weder Schreibzugriff noch Auditeintrag,
    -- wie bei update_patient.
    return;
  end if;

end;
$$;

COMMENT ON FUNCTION public.set_treatment_table_required(p_patient_id uuid, p_required boolean) IS 'UX-003a: setzt das Merkmal Behandlungsliege einer Person. Rollen wie update_patient; protokolliert patient.updated mit dem Feldnamen (ADR-010, ANN-116).';

CREATE FUNCTION public.skip_platform_onboarding(p_access_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_zugang public.platform_accesses%rowtype;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  select * into v_zugang from public.platform_accesses a
  where a.id = p_access_id and a.organization_id = v_org
  for update;
  -- Fremd, nicht vorhanden und ohne Recht sehen gleich aus.
  if not found or not app.can_manage_platform_access(v_zugang.relationship_kind) then
    raise exception 'not allowed to manage platform access' using errcode = '42501';
  end if;
  if v_zugang.status not in ('invited', 'active') then
    raise exception 'access is not live' using errcode = '23514';
  end if;
  if v_zugang.onboarding_finished_at is not null or v_zugang.onboarding_skipped_at is not null then
    return false;
  end if;

  update public.platform_accesses
     set onboarding_skipped_at = now(), onboarding_skipped_by = v_actor
   where id = p_access_id;
  return true;
end;
$$;

COMMENT ON FUNCTION public.skip_platform_onboarding(p_access_id uuid) IS 'POR-019 (IDEA-LZK-005): die Praxis ueberspringt den Einstieg fuer die Person. Rollen, die den Zugang verwalten; nie Einwilligungen. Nachweis am Zugang (onboarding_skipped_at/by), kein Auditeintrag (ADR-010 Fassung 3).';

CREATE FUNCTION public.start_platform_exercise_session(p_access_id uuid, p_plan_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_plan   public.exercise_plans%rowtype;
  v_heute  date;
  v_id     uuid;
begin
  v_zugang := app.assert_platform_exercise(p_access_id);
  v_plan := app.platform_exercise_plan(p_access_id, p_plan_id);
  if v_plan.id is null then
    raise exception 'exercise plan not found' using errcode = 'P0002';
  end if;
  v_heute := app.training_today(v_zugang.organization_id);

  -- Eine heute begonnene, nicht beendete Einheit geht weiter (ANN-305):
  -- Abbrechen und wieder Anfangen verliert nichts.
  insert into public.exercise_plan_sessions (
    organization_id, plan_id, performed_on, platform_access_id, platform_access_kind, recorded_by
  )
  values (
    v_plan.organization_id, v_plan.id, v_heute, v_zugang.id, v_zugang.access_kind, auth.uid()
  )
  on conflict (plan_id, performed_on) where finished_at is null do nothing
  returning id into v_id;

  if v_id is null then
    select s.id into v_id
    from public.exercise_plan_sessions s
    where s.plan_id = v_plan.id and s.performed_on = v_heute and s.finished_at is null;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'exercise_session')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.start_platform_exercise_session(p_access_id uuid, p_plan_id uuid) IS 'UEB-010: beginnt eine Einheit am laufenden Plan des Verhaeltnisses oder setzt die heute begonnene fort (ANN-305). Nur die Person und ihre rechtliche Vertretung (ANN-306), nicht in der Lesefrist. Sonst 42501, ein fremder oder nicht laufender Plan P0002.';

CREATE FUNCTION public.start_platform_message(p_access_id uuid, p_topic text, p_body text, p_plan_id uuid, p_item_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_text   text;
  v_plan   public.exercise_plans%rowtype;
  v_label  text;
  v_id     uuid;
begin
  v_zugang := app.assert_platform_message(p_access_id);

  if p_topic is null or p_topic not in ('exercise', 'complaint', 'organisational', 'other') then
    raise exception 'unknown topic' using errcode = '22023';
  end if;
  if not app.platform_message_topic_allowed(
           v_zugang.relationship_kind, v_zugang.relationship_id, p_topic) then
    raise exception 'topic needs consent' using errcode = '42501';
  end if;
  v_text := app.platform_message_body(p_body);

  -- Bezug nur bei "Uebung" und nur auf einen Plan, den die Plattform dem
  -- Verhaeltnis zeigt (ANN-304); die Uebung muss in diesem Plan stehen.
  if p_item_id is not null and p_plan_id is null then
    raise exception 'exercise needs its plan' using errcode = '22023';
  end if;
  if p_plan_id is not null then
    if p_topic <> 'exercise' then
      raise exception 'reference only for exercise questions' using errcode = '22023';
    end if;
    select p.* into v_plan
    from app.platform_visible_exercise_plans(v_zugang.relationship_kind, v_zugang.relationship_id) p
    where p.id = p_plan_id and p.organization_id = v_zugang.organization_id;
    if v_plan.id is null then
      raise exception 'exercise plan not found' using errcode = 'P0002';
    end if;
    v_label := v_plan.title;
    if p_item_id is not null then
      select i.variant_lay_name into v_label
      from public.exercise_plan_items i
      where i.id = p_item_id and i.plan_id = v_plan.id;
      if not found then
        raise exception 'exercise not found' using errcode = 'P0002';
      end if;
    end if;
    v_label := left(btrim(v_label), 200);
  end if;

  insert into public.platform_messages (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    topic, exercise_plan_id, exercise_plan_item_id, reference_label,
    status, due_on, created_by_access_id, created_by
  )
  values (
    v_zugang.organization_id, v_zugang.relationship_kind, v_zugang.relationship_id,
    v_zugang.patient_id, v_zugang.training_relationship_id,
    p_topic, v_plan.id, p_item_id, nullif(v_label, ''),
    'open', app.message_due_on(v_zugang.organization_id), v_zugang.id, auth.uid()
  )
  returning id into v_id;

  insert into public.platform_message_entries (
    organization_id, message_id, side, body, access_id, author_kind, author_label, created_by
  )
  values (
    v_zugang.organization_id, v_id, 'person', v_text, v_zugang.id, v_zugang.access_kind,
    case when v_zugang.access_kind <> 'self' then v_zugang.representative_name end, auth.uid()
  );

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'message')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.start_platform_message(p_access_id uuid, p_topic text, p_body text, p_plan_id uuid, p_item_id uuid) IS 'KOM-001: eine Frage an die Praxis stellen (IDEA-KOM-001, ANN-308): Thema, Text, optional Plan und Uebung. Recht message, nicht in der Lesefrist (ANN-313); im Training Uebung und Beschwerden nur mit Einwilligung (ANN-311). Antwort faellig nach den Werktagen der Praxis (ANN-309).';

CREATE FUNCTION public.start_training_for_person(p_person_id uuid, p_contract_started_on date DEFAULT NULL::date, p_date_of_birth date DEFAULT NULL::date, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_house_number text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_id    uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(v_actor, 'training_relationship.created', 'not allowed to manage training clients');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training clients' using errcode = '42501';
  end if;

  -- Die Person sperren und pruefen, dass der Aufrufer sie aus dem anderen
  -- Bereich kennt. app.is_staff() ist die Behandlungsseite; die Trainings-
  -- betreuung allein hat sie nicht.
  perform 1
  from public.persons pe
  where pe.id = p_person_id
    and pe.organization_id = v_org
    and app.is_staff()
    and (
      exists (select 1 from public.patients x where x.person_id = pe.id and x.organization_id = v_org)
      or exists (select 1 from public.staff_members x where x.person_id = pe.id and x.organization_id = v_org)
    )
  for update of pe;
  if not found then
    raise exception 'person not found' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.training_relationships t where t.person_id = p_person_id) then
    raise exception 'training relationship already exists' using errcode = '23505';
  end if;

  insert into public.training_relationships (
    organization_id, person_id, status, contract_started_on, created_by
  )
  values (
    v_org, p_person_id, 'active',
    coalesce(p_contract_started_on, app.training_today(v_org)), v_actor
  )
  returning id into v_id;

  -- Aus der Akte wird nichts uebernommen (ANN-173). Was im Formular steht,
  -- hat die anlegende Person fuer das Training eingegeben - das kommt mit,
  -- sonst gingen ihre Eingaben still verloren (Zweitreview TRN-EPIC-001).
  perform app.write_training_contact(
    v_id, v_org, v_actor, p_date_of_birth, p_email, p_phone, p_street, p_house_number, p_postal_code, p_city
  );


  return v_id;
end;
$$;

CREATE FUNCTION public.submit_electricity_reimbursement(p_month date, p_declared boolean, p_iban text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_start  record;
  v_o      record;
  v_minuten integer;
  v_betrag integer;
  v_id     uuid;
  v_status text;
begin
  select * into v_start from app.reimbursement_start(p_iban);
  perform app.assert_electricity_month(v_start.organization_id, p_month);
  -- Die Erklärung: zu Hause geladen. Im Depot lädt die Praxis selbst - dann
  -- gibt es nichts zu erstatten.
  if p_declared is distinct from true then
    raise exception 'declaration missing' using errcode = '22023';
  end if;

  select o.electricity_km_per_hour as kmh, o.electricity_wh_per_km as whkm,
         o.electricity_cents_per_kwh as ct
    into v_o
  from public.organizations o where o.id = v_start.organization_id;
  v_minuten := app.reimbursement_working_minutes(v_start.organization_id, v_start.staff_member_id, p_month);
  v_betrag := app.electricity_amount_cents(v_minuten, v_o.kmh, v_o.whkm, v_o.ct);
  if v_minuten < 1 or v_betrag < 1 then
    raise exception 'no planned working hours' using errcode = '22023';
  end if;

  v_status := case when v_start.self_entered then 'approved' else 'requested' end;
  begin
    insert into public.staff_reimbursements (
      organization_id, staff_member_id, kind, period_month, working_minutes, km_per_hour,
      wh_per_km, rate_cents_per_kwh, declared_at, amount_cents, status, requested_by,
      self_entered, decided_by, decided_at
    )
    values (
      v_start.organization_id, v_start.staff_member_id, 'electricity', p_month, v_minuten,
      v_o.kmh, v_o.whkm, v_o.ct, now(), v_betrag, v_status, auth.uid(),
      v_start.self_entered,
      case when v_start.self_entered then auth.uid() end,
      case when v_start.self_entered then now() end
    )
    returning id into v_id;
  exception
    when unique_violation then
      raise exception 'month already requested' using errcode = '23505';
  end;

  return jsonb_build_object('id', v_id, 'status', v_status, 'amount_cents', v_betrag);
end;
$$;

COMMENT ON FUNCTION public.submit_electricity_reimbursement(p_month date, p_declared boolean, p_iban text) IS 'ORG-008 (ANN-598): Ladestrom eines abgeschlossenen Monats beantragen - der Server rechnet geplante Arbeitsminuten × Strecke × Verbrauch × Satz der Praxis und hält alle Werte fest; die Erklärung (zu Hause geladen) als Haken; je Person und Monat einmal. Optional die IBAN dazu. owner trägt ein (gilt als genehmigt).';

CREATE FUNCTION public.submit_platform_checkin(p_access_id uuid, p_values jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
  v_takt   public.checkin_schedules%rowtype;
  v_heute  date;
  v_keys   text[];
  v_werte  smallint[];
  v_id     uuid;
begin
  if not app.platform_access_allows(p_access_id, 'checkin')
     or not app.platform_access_writable(p_access_id) then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if not app.platform_exercise_note_allowed(v_zugang.relationship_kind, v_zugang.relationship_id) then
    raise exception 'checkin requires consent' using errcode = '42501';
  end if;

  -- Die Zeile des Takts sperrt: Zwei schnelle Absendungen werden nicht zwei
  -- Check-ins an einem Tag (ANN-350).
  select * into v_takt
  from public.checkin_schedules s
  where s.relationship_kind = v_zugang.relationship_kind
    and s.relationship_id = v_zugang.relationship_id
  for update;
  if v_takt.id is null then
    raise exception 'no checkin schedule' using errcode = 'P0002';
  end if;
  v_heute := app.training_today(v_zugang.organization_id);
  if app.checkin_due_on(v_takt) > v_heute then
    raise exception 'checkin not due' using errcode = '22023';
  end if;

  select array_agg(w.parameter_key), array_agg(w.value)
    into v_keys, v_werte
  from app.tracking_values_from_json(p_values, 'checkin') w;
  -- Jede Frage ist freiwillig, mindestens eine beantwortet (ANN-349); eine
  -- Angabe zum Zusammenhang allein ist kein Check-in (TRK-005, ANN-355).
  if v_keys is null or not exists (
    select 1 from unnest(v_keys) k
    join app.tracking_parameters() t on t.parameter_key = k and t.cadence = 'checkin'
    where t.role = 'question'
  ) then
    raise exception 'no answer' using errcode = '22023';
  end if;
  if not v_keys <@ v_takt.parameter_keys then
    raise exception 'question not asked' using errcode = '22023';
  end if;

  insert into public.checkins (
    organization_id, relationship_kind, relationship_id, patient_id, training_relationship_id,
    answered_on, platform_access_id, platform_access_kind, recorded_by
  )
  values (
    v_zugang.organization_id, v_zugang.relationship_kind, v_zugang.relationship_id,
    case when v_zugang.relationship_kind = 'treatment' then v_zugang.relationship_id end,
    case when v_zugang.relationship_kind = 'training' then v_zugang.relationship_id end,
    v_heute, v_zugang.id, v_zugang.access_kind, auth.uid()
  )
  returning id into v_id;

  insert into public.checkin_values (organization_id, checkin_id, parameter_key, value)
  select v_zugang.organization_id, v_id, w.key, w.value
  from unnest(v_keys, v_werte) as w (key, value);

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'checkin')
  );
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.submit_platform_checkin(p_access_id uuid, p_values jsonb) IS 'TRK-003, TRK-005: beantwortet den faelligen Check-in des Verhaeltnisses - { Schluessel: Wert } nur zu den eingestellten Fragen und Angaben zum Zusammenhang, mindestens eine Frage (ANN-349, ANN-355); hoechstens einer am Tag (ANN-350). Nur die Person und ihre rechtliche Vertretung (ANN-352), nicht in der Lesefrist, im Training nur mit Einwilligung (42501). Ohne Takt P0002, nicht faellig oder falscher Wert 22023. Keine Benachrichtigung an die Praxis (DSN-001 D5).';

CREATE FUNCTION public.submit_purchase_reimbursement(p_items jsonb, p_iban text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_start  record;
  v_posten record;
  v_ids    uuid[];
  v_summe  integer;
  v_id     uuid;
  v_status text;
begin
  select * into v_start from app.reimbursement_start(p_iban);
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) not between 1 and app.reimbursement_receipt_limit() then
    raise exception 'one to ten receipts' using errcode = '22023';
  end if;

  -- Die Posten in Spalten; was sich nicht lesen lässt, ist ungültig.
  begin
    create temporary table if not exists erstattung_posten (
      receipt_id uuid, amount_cents integer, purpose text
    ) on commit drop;
    -- Mit WHERE: Über PostgREST lädt Supabase `safeupdate`, das ein DELETE
    -- ohne WHERE abweist (in der CI über die Oberfläche gefunden, ERS-001).
    delete from erstattung_posten where true;
    insert into erstattung_posten (receipt_id, amount_cents, purpose)
    select (p ->> 'receipt_id')::uuid, (p ->> 'amount_cents')::integer,
           nullif(btrim(p ->> 'purpose'), '')
    from jsonb_array_elements(p_items) as p;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'receipt item is invalid' using errcode = '22023';
  end;
  if exists (
       select 1 from erstattung_posten
       where receipt_id is null or amount_cents is null or amount_cents not between 1 and 100000
          or purpose is null or length(purpose) > 200
     )
     or (select count(distinct receipt_id) from erstattung_posten) <> jsonb_array_length(p_items) then
    raise exception 'receipt item is invalid' using errcode = '22023';
  end if;

  -- Erst sperren, dann wählen (Zweitreview): Wartet die Sperre auf ein
  -- gleichzeitiges Verwerfen, Aufräumen oder Zuordnen, sieht die Auswahl
  -- danach mit neuem Schnappschuss, was davon übrig ist. Nur eigene, fertige,
  -- noch nicht zugeordnete Belege; fremde und verworfene sehen gleich aus.
  perform 1 from public.staff_reimbursement_receipts b
   where b.id in (select receipt_id from erstattung_posten)
     and b.organization_id = v_start.organization_id
     and b.created_by = auth.uid()
   order by b.id
   for update;
  select array_agg(b.id) into v_ids
  from public.staff_reimbursement_receipts b
  where b.id in (select receipt_id from erstattung_posten)
    and b.organization_id = v_start.organization_id
    and b.staff_member_id = v_start.staff_member_id
    and b.created_by = auth.uid()
    and b.reimbursement_id is null
    and b.status = 'ready'
    and b.created_at > now() - interval '24 hours';
  if coalesce(array_length(v_ids, 1), 0) <> jsonb_array_length(p_items) then
    raise exception 'receipt not found' using errcode = 'P0002';
  end if;

  select sum(amount_cents)::integer into v_summe from erstattung_posten;
  v_status := case when v_start.self_entered then 'approved' else 'requested' end;
  insert into public.staff_reimbursements (
    organization_id, staff_member_id, kind, amount_cents, status, requested_by, self_entered,
    decided_by, decided_at
  )
  values (
    v_start.organization_id, v_start.staff_member_id, 'purchase', v_summe, v_status, auth.uid(),
    v_start.self_entered,
    case when v_start.self_entered then auth.uid() end,
    case when v_start.self_entered then now() end
  )
  returning id into v_id;

  -- Jede Zuordnung muss treffen; sonst fällt der ganze Antrag zurück - ein
  -- Betrag ohne seinen Beleg entsteht nie (ANN-600).
  for v_posten in select * from erstattung_posten loop
    update public.staff_reimbursement_receipts
       set reimbursement_id = v_id, amount_cents = v_posten.amount_cents,
           purpose = v_posten.purpose, attached_at = now()
     where id = v_posten.receipt_id and reimbursement_id is null;
    if not found then
      raise exception 'receipt not found' using errcode = 'P0002';
    end if;
  end loop;

  return jsonb_build_object('id', v_id, 'status', v_status, 'amount_cents', v_summe);
end;
$$;

COMMENT ON FUNCTION public.submit_purchase_reimbursement(p_items jsonb, p_iban text) IS 'ERS-001 (ANN-598, ANN-600): Einkauf beantragen - ein bis zehn eigene, fertige Belege, je Beleg Betrag (0,01 bis 1 000 Euro) und Zweck (bis 200 Zeichen); der Betrag ist ihre Summe. Optional die IBAN dazu. owner trägt ein (gilt als genehmigt).';

CREATE FUNCTION public.submit_staff_barometer(p_named boolean, p_mood integer, p_tours integer, p_team integer, p_easier text, p_more text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_wer    record;
  v_monat  date;
  v_easier text;
  v_more   text;
begin
  select * into v_wer from app.staff_feedback_giver();
  if p_named is null then
    raise exception 'choose with or without name' using errcode = '22023';
  end if;
  if (p_mood is not null and p_mood not between 1 and 9)
     or (p_tours is not null and p_tours not between 1 and 9)
     or (p_team is not null and p_team not between 1 and 9) then
    raise exception 'scale value out of range' using errcode = '22023';
  end if;
  v_easier := app.staff_feedback_text(p_easier);
  v_more := app.staff_feedback_text(p_more);
  if num_nonnulls(p_mood, p_tours, p_team, v_easier, v_more) = 0 then
    raise exception 'feedback is empty' using errcode = '22023';
  end if;
  v_monat := app.staff_feedback_month(v_wer.o_org);

  -- Erst die Marke: Gibt es sie schon, endet hier alles (auch bei zwei
  -- gleichzeitigen Abgaben - die zweite wartet auf die erste).
  insert into public.staff_feedback_participations (organization_id, staff_member_id, month)
  values (v_wer.o_org, v_wer.o_staff, v_monat)
  on conflict (staff_member_id, month) do nothing;
  if not found then
    raise exception 'barometer already submitted' using errcode = '23505';
  end if;

  insert into public.staff_feedback (
    organization_id, kind, month, staff_member_id, submitted_at,
    mood, tours, team, easier_text, more_text
  )
  values (
    v_wer.o_org, 'barometer', v_monat,
    case when p_named then v_wer.o_staff end,
    case when p_named then now() end,
    p_mood, p_tours, p_team, v_easier, v_more
  );

  -- Ohne Namen: alle anonymen Barometer dieses Monats neu schreiben, in
  -- zufälliger Reihenfolge (Nachprüfung zu Befund 1). Dann teilt die neue
  -- Marke ihre Transaktion mit allen Antworten des Monats, nicht mit einer.
  if not p_named then
    with alt as (
      delete from public.staff_feedback f
      where f.organization_id = v_wer.o_org and f.kind = 'barometer'
        and f.staff_member_id is null and f.month = v_monat
      returning f.organization_id, f.month, f.mood, f.tours, f.team, f.easier_text, f.more_text
    )
    insert into public.staff_feedback
      (organization_id, kind, month, mood, tours, team, easier_text, more_text)
    select a.organization_id, 'barometer', a.month, a.mood, a.tours, a.team,
           a.easier_text, a.more_text
    from alt a
    order by random();
  end if;

  return jsonb_build_object('month', v_monat, 'named', p_named);
end;
$$;

COMMENT ON FUNCTION public.submit_staff_barometer(p_named boolean, p_mood integer, p_tours integer, p_team integer, p_easier text, p_more text) IS 'ORG-006 (ANN-607): das Barometer des laufenden Monats abgeben - einmal je Person und Monat, mit oder ohne Namen; nie owner. Ohne Namen ohne Person und Zeitpunkt. Kein Auditeintrag.';

CREATE FUNCTION public.submit_staff_feedback_message(p_named boolean, p_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_wer   record;
  v_monat date;
  v_text  text;
begin
  select * into v_wer from app.staff_feedback_giver();
  if p_named is null then
    raise exception 'choose with or without name' using errcode = '22023';
  end if;
  v_text := app.staff_feedback_text(p_text);
  if v_text is null then
    raise exception 'feedback is empty' using errcode = '22023';
  end if;
  v_monat := app.staff_feedback_month(v_wer.o_org);

  insert into public.staff_feedback (
    organization_id, kind, month, staff_member_id, submitted_at, message_text
  )
  values (
    v_wer.o_org, 'message', v_monat,
    case when p_named then v_wer.o_staff end,
    case when p_named then now() end,
    v_text
  );

  return jsonb_build_object('month', v_monat, 'named', p_named);
end;
$$;

COMMENT ON FUNCTION public.submit_staff_feedback_message(p_named boolean, p_text text) IS 'ORG-006 (ANN-608): Rückmeldung an die Praxisleitung - jederzeit, ein Freitext, mit oder ohne Namen; nie owner. Kein Auditeintrag.';

CREATE FUNCTION public.sync_offline_treatment_note(p_offline_id uuid, p_appointment_id uuid, p_content text, p_written_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_inhalt text;
  v_termin record;
  v_da     record;
  v_note   uuid;
begin
  -- Gesperrt ist nicht entzogen: eigener Code, damit das Geraet nichts
  -- verwirft (TRK-007, Zweitreview B1).
  v_actor := auth.uid();
  if v_actor is null or not app.session_open() then
    raise exception 'session locked' using errcode = '28000';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  if p_offline_id is null or p_appointment_id is null or p_written_at is null then
    raise exception 'invalid offline draft' using errcode = '22023';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');
  if v_inhalt = '' then
    raise exception 'documentation must not be empty' using errcode = '22023';
  end if;
  if length(v_inhalt) > 20000 then
    raise exception 'documentation is too long' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.status, a.kind
    into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  -- Wiedererkennen vor jeder weiteren Pruefung: Kam der Entwurf schon an und
  -- ging nur die Antwort verloren, ist das ein Erfolg - auch wenn der Termin
  -- inzwischen abgesagt ist.
  select t.id, t.appointment_id, t.content, t.status
    into v_da
  from public.treatment_notes t
  where t.created_by = v_actor
    and t.offline_id = p_offline_id
    and t.organization_id = v_org;

  if found then
    if v_da.appointment_id <> p_appointment_id then
      raise exception 'invalid offline draft' using errcode = '22023';
    end if;
    -- Ging die Antwort verloren und wurde danach weitergeschrieben, traegt
    -- dieselbe Kennung einen neueren Text: Der ist kein Wiedererkennen,
    -- sonst fiele er still vom Geraet (Zweitreview B1). Er bleibt dort als
    -- Konflikt neben dem angekommenen Entwurf.
    if v_da.content <> v_inhalt then
      return jsonb_build_object(
        'status', 'conflict', 'note_id', v_da.id, 'note_status', v_da.status
      );
    end if;
    return jsonb_build_object('status', 'known', 'note_id', v_da.id);
  end if;

  if v_termin.kind = 'internal' then
    raise exception 'event cannot be documented' using errcode = '22023';
  end if;
  if v_termin.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be documented' using errcode = '22023';
  end if;
  if v_termin.status = 'no_show' then
    raise exception 'no-show appointment cannot be documented' using errcode = '22023';
  end if;

  -- Nichts einmischen (ADR-024 Punkt 7).
  select t.id, t.status
    into v_da
  from public.treatment_notes t
  where t.appointment_id = p_appointment_id
    and t.addendum_to_note_id is null;

  if found then
    return jsonb_build_object('status', 'conflict', 'note_id', v_da.id, 'note_status', v_da.status);
  end if;

  begin
    insert into public.treatment_notes (
      organization_id, appointment_id, status, content, created_by, updated_by,
      offline_id, reported_written_at
    )
    values (
      v_org, p_appointment_id, 'draft', v_inhalt, v_actor, v_actor,
      -- Eine Uhr aus der Zukunft ist eine falsche Uhr; die Angabe bleibt
      -- hoechstens der Eingang.
      p_offline_id, least(p_written_at, now())
    )
    returning id into v_note;
  exception
    when unique_violation then
      -- Gleichzeitig angekommen: derselbe Entwurf zweimal oder ein anderer
      -- Eintrag am Termin.
      select t.id, t.content, t.status into v_da
      from public.treatment_notes t
      where t.created_by = v_actor and t.offline_id = p_offline_id;
      if found then
        if v_da.content <> v_inhalt then
          return jsonb_build_object(
            'status', 'conflict', 'note_id', v_da.id, 'note_status', v_da.status
          );
        end if;
        return jsonb_build_object('status', 'known', 'note_id', v_da.id);
      end if;
      select t.id, t.status into v_da
      from public.treatment_notes t
      where t.appointment_id = p_appointment_id and t.addendum_to_note_id is null;
      return jsonb_build_object('status', 'conflict', 'note_id', v_da.id, 'note_status', v_da.status);
  end;

  return jsonb_build_object('status', 'created', 'note_id', v_note);
end;
$$;

COMMENT ON FUNCTION public.sync_offline_treatment_note(p_offline_id uuid, p_appointment_id uuid, p_content text, p_written_at timestamp with time zone) IS 'OFF-002 (ADR-024 Punkte 7 und 8, ANN-362): Uebertraegt einen ohne Verbindung geschriebenen Entwurf - additiv, wiederholbar, ohne Einmischen in eine vorhandene Dokumentation. Dieselben Pruefungen wie create_treatment_note, 28000 bei gesperrter Sitzung. Kein Auditeintrag.';

CREATE FUNCTION public.sync_platform_exercise_session(p_access_id uuid, p_plan_id uuid, p_session_id uuid, p_performed_on date, p_started_at timestamp with time zone, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang     public.platform_accesses%rowtype;
  v_plan       public.exercise_plans%rowtype;
  v_einheit    public.exercise_plan_sessions%rowtype;
  v_heute      date;
  v_neu        boolean := false;
  v_verworfen  boolean := false;
  v_ereignis   jsonb;
  v_nummer     integer := 0;
  v_anzahl     integer;
  v_art        text;
  v_saetze     smallint;
  v_satz       integer;
  v_zeit       timestamptz;
  v_notiz      text;
  v_keys       text[];
  v_werte      smallint[];
  v_erlaubt    boolean;
  v_tag        date;
begin
  -- Gesperrt ist nicht entzogen: eigener Code, damit das Geraet nichts
  -- verwirft (Zweitreview B1).
  if auth.uid() is null or not app.session_open() then
    raise exception 'session locked' using errcode = '28000';
  end if;
  v_zugang := app.assert_platform_exercise(p_access_id);
  v_plan := app.platform_exercise_plan(p_access_id, p_plan_id);
  if v_plan.id is null then
    raise exception 'exercise plan not found' using errcode = 'P0002';
  end if;
  v_heute := app.training_today(v_zugang.organization_id);

  if p_session_id is null or p_performed_on is null or p_events is null
     or jsonb_typeof(p_events) <> 'array' then
    raise exception 'invalid transfer' using errcode = '22023';
  end if;
  v_anzahl := jsonb_array_length(p_events);
  -- Mehr tippt niemand in einer Einheit; schuetzt vor einer endlosen Liste.
  if v_anzahl > 1000 then
    raise exception 'too many events' using errcode = '22023';
  end if;
  -- Der Tag der Einheit ist die Angabe des Geraets - aber nicht in der
  -- Zukunft, nicht vor dem Planbeginn und nicht aelter als die Ablage. Ein
  -- Tag voraus ist Zeitzone oder Uhr des Geraets und zaehlt als heute
  -- (Zweitreview S3).
  if p_performed_on > v_heute + 1 then
    raise exception 'session in the future' using errcode = '22023';
  end if;
  v_tag := least(p_performed_on, v_heute);
  if v_tag < v_heute - app.offline_transfer_days()
     or v_tag < v_plan.runs_from then
    raise exception 'session too old' using errcode = 'P0002';
  end if;

  -- Wiedererkennen: dieselbe Kennung, derselbe Plan. Eine fremde Kennung
  -- antwortet wie ein fremder Plan (ADR-024 Punkt 7).
  select * into v_einheit from public.exercise_plan_sessions s where s.id = p_session_id;
  if v_einheit.id is not null then
    if v_einheit.plan_id <> v_plan.id
       or v_einheit.performed_on < v_heute - app.offline_transfer_days() then
      raise exception 'exercise session not found' using errcode = 'P0002';
    end if;
    if v_einheit.finished_at is not null then
      -- Dasselbe Ende noch einmal: angekommen. Sonst nimmt sie nichts mehr an.
      if v_einheit.finish_event_id is not null
         and exists (select 1 from jsonb_array_elements(p_events) e
                     where e ->> 'kind' = 'finish'
                       and e ->> 'id' = v_einheit.finish_event_id::text) then
        return jsonb_build_object('session_id', v_einheit.id, 'status', 'finished',
                                  'note_dropped', false);
      end if;
      return jsonb_build_object('session_id', v_einheit.id, 'status', 'closed',
                                'note_dropped', false);
    end if;
    -- Eine offene Einheit eines anderen Tages bleibt stehen (ANN-305).
    if v_einheit.performed_on <> v_tag then
      return jsonb_build_object('session_id', v_einheit.id, 'status', 'closed',
                                'note_dropped', false);
    end if;
  else
    -- Neu: anlegen. Ist an diesem Tag schon eine offen (zweites Geraet,
    -- Vertretung), kommen die Haken dazu - wie online (ANN-305).
    insert into public.exercise_plan_sessions (
      id, organization_id, plan_id, performed_on, platform_access_id, platform_access_kind,
      recorded_by, reported_started_at
    )
    values (
      p_session_id, v_plan.organization_id, v_plan.id, v_tag, v_zugang.id,
      v_zugang.access_kind, auth.uid(), p_started_at
    )
    on conflict (plan_id, performed_on) where finished_at is null do nothing
    returning * into v_einheit;
    if v_einheit.id is null then
      select * into v_einheit
      from public.exercise_plan_sessions s
      where s.plan_id = v_plan.id and s.performed_on = v_tag and s.finished_at is null;
    else
      v_neu := true;
    end if;
  end if;

  for v_ereignis in select e from jsonb_array_elements(p_events) e loop
    v_nummer := v_nummer + 1;
    if jsonb_typeof(v_ereignis) <> 'object' then
      raise exception 'invalid event' using errcode = '22023';
    end if;
    v_art := v_ereignis ->> 'kind';
    begin
      v_zeit := (v_ereignis ->> 'at')::timestamptz;
    exception when others then
      raise exception 'invalid event time' using errcode = '22023';
    end;

    if v_art = 'set' then
      if v_ereignis ->> 'id' is null then
        raise exception 'event without id' using errcode = '22023';
      end if;
      begin
        v_satz := (v_ereignis ->> 'set_number')::integer;
      exception when others then
        raise exception 'invalid set' using errcode = '22023';
      end;
      select i.sets into v_saetze
      from public.exercise_plan_items i
      where i.id = (v_ereignis ->> 'item_id')::uuid and i.plan_id = v_plan.id;
      if v_saetze is null then
        raise exception 'exercise not found' using errcode = 'P0002';
      end if;
      if v_satz is null or v_satz < 1 or v_satz > v_saetze then
        raise exception 'set out of range' using errcode = '22023';
      end if;
      if jsonb_typeof(v_ereignis -> 'done') is distinct from 'boolean' then
        raise exception 'invalid set' using errcode = '22023';
      end if;
      if (v_ereignis ->> 'done')::boolean then
        -- Die Kennung des Hakens ist die Zeile: zweimal gesendet ist einmal
        -- gespeichert. Ein schon gesetzter Satz bleibt, wie er ist.
        insert into public.exercise_plan_session_sets (
          id, session_id, organization_id, item_id, set_number, reported_done_at
        )
        values (
          (v_ereignis ->> 'id')::uuid, v_einheit.id, v_einheit.organization_id,
          (v_ereignis ->> 'item_id')::uuid, v_satz, v_zeit
        )
        on conflict do nothing;
      else
        delete from public.exercise_plan_session_sets x
        where x.session_id = v_einheit.id
          and x.item_id = (v_ereignis ->> 'item_id')::uuid
          and x.set_number = v_satz;
      end if;

    elsif v_art = 'finish' then
      if v_nummer <> v_anzahl or v_ereignis ->> 'id' is null then
        raise exception 'finish must be last' using errcode = '22023';
      end if;
      v_notiz := nullif(btrim(coalesce(v_ereignis ->> 'note', ''), E' \t\r\n'), '');
      if v_notiz is not null and length(v_notiz) > 500 then
        raise exception 'note too long' using errcode = '22023';
      end if;
      select array_agg(w.parameter_key), array_agg(w.value)
        into v_keys, v_werte
      from app.tracking_values_from_json(v_ereignis -> 'values', 'session') w;
      -- Der Server urteilt beim Eingang (Punkt 8): Ist die Einwilligung
      -- inzwischen widerrufen, kommen Satz und Angaben nicht an; die Einheit
      -- wird trotzdem beendet, und die Ansicht sagt es (ANN-357).
      v_erlaubt := app.platform_exercise_note_allowed(v_zugang.relationship_kind,
                                                      v_zugang.relationship_id);
      if not v_erlaubt and (v_notiz is not null or v_keys is not null) then
        v_verworfen := true;
        v_notiz := null;
        v_keys := null;
        v_werte := null;
      end if;
      -- Ohne einen Haken gibt es nichts zu beenden (wie in der Ansicht).
      if not exists (select 1 from public.exercise_plan_session_sets x
                     where x.session_id = v_einheit.id) then
        exit;
      end if;
      update public.exercise_plan_sessions
         set finished_at = now(), difficulty_note = v_notiz, updated_at = now(),
             finished_access_id = v_zugang.id, finished_access_kind = v_zugang.access_kind,
             finished_by = auth.uid(), reported_finished_at = v_zeit,
             finish_event_id = (v_ereignis ->> 'id')::uuid
       where id = v_einheit.id;
      insert into public.exercise_plan_session_values (organization_id, session_id, parameter_key, value)
      select v_einheit.organization_id, v_einheit.id, w.key, w.value
      from unnest(v_keys, v_werte) as w (key, value);

    else
      raise exception 'invalid event kind' using errcode = '22023';
    end if;
  end loop;

  -- Eine neu angelegte Einheit ohne einen Haken traegt nichts: Sie entstuende
  -- nur, weil ein zweites Senden alles schon vorfand (ANN-357).
  if v_neu and not exists (select 1 from public.exercise_plan_session_sets x
                           where x.session_id = v_einheit.id) then
    delete from public.exercise_plan_sessions s where s.id = v_einheit.id;
    return jsonb_build_object('session_id', v_einheit.id, 'status', 'empty',
                              'note_dropped', false);
  end if;

  update public.exercise_plan_sessions set updated_at = now()
   where id = v_einheit.id and finished_at is null;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'exercise_session')
  );
  return jsonb_build_object('session_id', v_einheit.id, 'status', 'ok',
                            'note_dropped', v_verworfen);
end;
$$;

COMMENT ON FUNCTION public.sync_platform_exercise_session(p_access_id uuid, p_plan_id uuid, p_session_id uuid, p_performed_on date, p_started_at timestamp with time zone, p_events jsonb) IS 'TRK-007 (ADR-024 Punkte 7 und 8, ANN-357): uebertraegt eine Einheit mit ihren Haken und wahlweise dem Ende, so wie das Geraet sie erfasst hat - additiv und wiederholbar ueber die Kennungen des Geraets. Dieselben Rechte und Pruefungen wie Beginnen, Abhaken und Beenden, beim Eingang. Fremde Kennung wie fremder Plan (P0002). Ohne Einwilligung im Training fallen Satz und Angaben weg (note_dropped).';

CREATE FUNCTION public.take_fleet_key(p_bike_id uuid, p_holder_staff_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org    uuid;
  v_holder uuid;
  v_id     uuid;
begin
  v_org := app.fleet_org(app.can_read_fleet(), 'not allowed to use the fleet');
  perform 1 from public.fleet_bikes b
  where b.id = p_bike_id and b.organization_id = v_org and b.archived_at is null
  for update;
  if not found then
    raise exception 'bike not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.fleet_blocks b where b.bike_id = p_bike_id and b.released_at is null
  ) then
    raise exception 'bike is blocked' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.fleet_key_handovers k where k.bike_id = p_bike_id and k.returned_at is null
  ) then
    raise exception 'key already taken' using errcode = '55000';
  end if;

  v_holder := coalesce(p_holder_staff_id, app.fleet_current_staff_member(v_org));
  if v_holder is null then
    raise exception 'no staff member for this account' using errcode = '22023';
  end if;
  perform app.assert_staff_member_in_org(v_holder, v_org);

  insert into public.fleet_key_handovers (organization_id, bike_id, holder_staff_id, taken_by)
  values (v_org, p_bike_id, v_holder, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

COMMENT ON FUNCTION public.take_fleet_key(p_bike_id uuid, p_holder_staff_id uuid) IS 'FLT-001: Schluessel eines Rads nehmen - fuer sich selbst (p_holder_staff_id null) oder fuer eine Mitarbeiterin aus dem Stamm. Nicht bei gesperrtem Rad, nicht doppelt. Alle Praxisrollen der Behandlung (BEF-066).';

CREATE FUNCTION public.team_attachment_for_verification(p_attachment_id uuid, p_user_id uuid) RETURNS TABLE(bucket_id text, object_key text, mime_type text, byte_size bigint, checksum_sha256 text, already_verified boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select app.chat_attachment_bucket(), a.object_key, a.mime_type, a.byte_size,
         a.checksum_sha256, a.verified_at is not null
  from public.team_message_attachments a
  where a.id = p_attachment_id
    and a.created_by = p_user_id
    and a.message_id is null
    and a.created_at > now() - interval '24 hours'
    and (a.status = 'ready' or a.confirmation_requested_at is not null)
$$;

CREATE FUNCTION public.toggle_team_reaction(p_message uuid, p_reaction text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_m     public.team_messages%rowtype;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if p_reaction is null
     or p_reaction not in ('daumen', 'erledigt', 'augen', 'danke', 'herz', 'lachen', 'feier', 'frage') then
    raise exception 'unknown reaction' using errcode = '22023';
  end if;
  -- Auf ein gleichzeitiges Entfernen warten und danach frisch lesen: Was es
  -- übersteht, hinge sonst am leeren Anker (Zweitreview TEAM-002, Runde 4).
  perform 1 from public.team_messages where id = p_message and organization_id = v_org for share;
  v_m := app.team_readable_message(p_message, v_org, v_staff);
  if v_m.id is null then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.team_channels c where c.id = v_m.channel_id and c.archived_at is not null) then
    raise exception 'team channel is archived' using errcode = '22023';
  end if;
  delete from public.team_message_reactions
  where message_id = p_message and staff_member_id = v_staff and reaction = p_reaction;
  if found then
    return false;
  end if;
  insert into public.team_message_reactions (organization_id, message_id, staff_member_id, reaction)
  values (v_org, p_message, v_staff, p_reaction)
  on conflict do nothing;
  return true;
end;
$$;

CREATE FUNCTION public.training_protocols_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_termin record;
begin
  if tg_op = 'UPDATE' then
    if old.status = 'final' then
      raise exception 'finalized training protocol cannot be changed' using errcode = '22023';
    end if;
    if new.appointment_id is distinct from old.appointment_id
       or new.training_relationship_id is distinct from old.training_relationship_id
       or new.organization_id is distinct from old.organization_id then
      raise exception 'training protocol cannot be moved' using errcode = '22023';
    end if;
    return new;
  end if;

  select a.kind, a.training_relationship_id, a.organization_id
    into v_termin
  from public.appointments a
  where a.id = new.appointment_id;

  if not found
     or v_termin.kind <> 'training'
     or v_termin.training_relationship_id is distinct from new.training_relationship_id
     or v_termin.organization_id is distinct from new.organization_id then
    raise exception 'training protocol requires a training appointment of the same relationship'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION public.training_protocols_guard() IS 'Ein Trainingsprotokoll haengt an einem Trainingstermin desselben Verhaeltnisses und derselben Organisation (ADR-022 Punkte 6 und 7) und ist nach dem Abschluss unveraenderlich (ANN-185).';

CREATE FUNCTION public.transfer_appointments_to_treatment_basis(p_treatment_basis_id uuid, p_appointment_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org        uuid;
  v_actor      uuid := auth.uid();
  v_patient    uuid;
  v_anzahl     integer;
  v_geschickt  integer;
  v_quellen    uuid[];
  v_fehlend    text;
  v_leistungen integer := 0;
  v_mengen     jsonb   := '[]'::jsonb;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Uebertragen aendert einen Termin, nicht die Grundlage: Es ist dasselbe
  -- Recht wie das Umplanen (ADR-004). Wer eine Verordnung schreiben darf, hat
  -- es ohnehin; das Office plant Termine und darf deshalb auch uebertragen.
  if not app.can_update_appointment() then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  if p_treatment_basis_id is null then
    raise exception 'treatment basis is required' using errcode = '22023';
  end if;

  if p_appointment_ids is null or cardinality(p_appointment_ids) = 0 then
    raise exception 'appointments must be a non-empty array' using errcode = '22023';
  end if;

  -- Die Zielgrundlage bestimmt die Patient:in. Sie wird hier gelesen und nicht
  -- vom Aufrufer entgegengenommen: Eine mitgeschickte Patientenkennung waere
  -- eine zweite Wahrheit, die auseinanderlaufen kann.
  select p.patient_id
    into v_patient
  from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  -- Alles oder nichts: Erst wird gezaehlt, was die Bedingungen erfuellt, dann
  -- geschrieben. Eine Kennung, die durchfaellt - fremde Organisation, andere
  -- Patient:in, abgesagt, abgerechnet oder ein Ereignis ohne Patient:in -,
  -- laesst den ganzen Vorgang scheitern.
  v_geschickt := cardinality(array(select distinct unnest(p_appointment_ids)));

  select count(*), array_agg(distinct a.treatment_basis_id)
    into v_anzahl, v_quellen
  from public.appointments a
  where a.id = any(p_appointment_ids)
    and a.organization_id = v_org
    and a.patient_id      = v_patient
    and a.status not in ('cancelled', 'invoiced')
    -- Abgerechnet ist die Leistung, nicht der Termin (ANN-081): Der Zustand
    -- 'invoiced' an appointments entsteht im Betrieb nicht, issue_invoice
    -- setzt ihn nicht. Geprueft wird deshalb der Zustand, den es wirklich
    -- gibt. Die Bedingung oben bleibt daneben stehen - sie kostet nichts und
    -- traegt weiter, falls ADR-018 spaeter vollstaendig umgesetzt wird.
    and not exists (
      select 1 from public.billable_services b
      where b.appointment_id = a.id
        and b.status = 'invoiced'
    );

  if v_anzahl <> v_geschickt then
    raise exception 'appointments are not transferable' using errcode = '22023';
  end if;

  -- ---------------------------------------------------------------------------
  -- ABN-002: Die erfassten Leistungen, die eine Position tragen und noch nicht
  -- am Ziel haengen. Je alter Position die Zielposition mit demselben
  -- Heilmittel; fehlt eine, ist der ganze Vorgang abzuweisen - bevor
  -- irgendetwas geschrieben wurde.
  -- ---------------------------------------------------------------------------
  create temp table abn_umzug on commit drop as
    select b.id              as leistung_id,
           b.quantity        as menge,
           alt.id            as alte_position,
           alt.remedy        as remedy,
           neu.id            as neue_position
    from public.billable_services b
    join public.treatment_base_items alt on alt.id = b.treatment_base_item_id
    left join public.treatment_base_items neu
           on neu.treatment_basis_id = p_treatment_basis_id
          and neu.remedy = alt.remedy
    where b.appointment_id = any(p_appointment_ids)
      and b.organization_id = v_org
      and b.status = 'billable'
      and alt.treatment_basis_id <> p_treatment_basis_id;

  select string_agg(distinct u.remedy, ', ' order by u.remedy)
    into v_fehlend
  from abn_umzug u
  where u.neue_position is null;

  if v_fehlend is not null then
    raise exception 'target basis has no position for remedy %', v_fehlend
      using errcode = '22023';
  end if;

  select count(*) into v_leistungen from abn_umzug;

  if v_leistungen > 0 then
    -- Genau das zuruecknehmen, was das Erfassen gesetzt hat (wie
    -- delete_billable_services) ...
    update public.treatment_base_items p
       set used_quantity = greatest(p.used_quantity - s.menge, 0)
    from (select alte_position, sum(menge)::smallint as menge from abn_umzug group by alte_position) s
    where p.id = s.alte_position;

    -- ... und am Ziel neu verbrauchen. Die Constraint
    -- used_quantity <= prescribed_quantity schuetzt die Abrechnung (ADR-020
    -- Punkt 5); sie bekommt hier nur eine verstaendliche Meldung.
    begin
      update public.treatment_base_items p
         set used_quantity = p.used_quantity + s.menge
      from (select neue_position, sum(menge)::smallint as menge from abn_umzug group by neue_position) s
      where p.id = s.neue_position;
    exception
      when check_violation then
        raise exception 'target basis quantity exhausted' using errcode = '23514';
    end;

    update public.billable_services b
       set treatment_base_item_id = u.neue_position
    from abn_umzug u
    where b.id = u.leistung_id;

    select coalesce(jsonb_agg(jsonb_build_object('remedy', remedy, 'quantity', menge) order by remedy), '[]'::jsonb)
      into v_mengen
    from (select remedy, sum(menge) as menge from abn_umzug group by remedy) m;
  end if;

  -- Der Termin behaelt Tag, Zeit, Person und Ort. `updated_at` bleibt deshalb
  -- unberuehrt: Der Mitteilungsvermerk haengt daran (CAL-012) und gilt weiter -
  -- mitgeteilt wurde ein Zeitpunkt, keine Grundlage.
  --
  -- BEF-124: Wer von wo uebertragen hat, steht am Termin. Ein Termin, der
  -- schon am Ziel haengt, wird nicht umgehaengt und bekommt keinen Vermerk.
  update public.appointments a
     set treatment_basis_id             = p_treatment_basis_id,
         previous_treatment_basis_id    = case
                                            when a.treatment_basis_id is distinct from p_treatment_basis_id
                                            then a.treatment_basis_id
                                            else a.previous_treatment_basis_id
                                          end,
         treatment_basis_transferred_at = case
                                            when a.treatment_basis_id is distinct from p_treatment_basis_id
                                            then now()
                                            else a.treatment_basis_transferred_at
                                          end,
         treatment_basis_transferred_by = case
                                            when a.treatment_basis_id is distinct from p_treatment_basis_id
                                            then v_actor
                                            else a.treatment_basis_transferred_by
                                          end
   where a.id = any(p_appointment_ids)
     and a.organization_id = v_org;


  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.transfer_appointments_to_treatment_basis(p_treatment_basis_id uuid, p_appointment_ids uuid[]) IS 'Uebertraegt Termine auf eine andere Behandlungsgrundlage derselben Patient:in (CAL-022, ANN-068, ANN-081, R3-001, ABN-002): alles oder nichts, die Patient:in kommt aus der Zielgrundlage, abgesagte Termine und solche mit abgerechneter Leistung sind ausgeschlossen. Erfasste, nicht abgerechnete Leistungen ziehen in derselben Transaktion auf die Position der Zielgrundlage mit demselben Heilmittel mit, die genutzte Menge wandert; ohne passende Position oder bei erschoepftem Kontingent wird abgewiesen. Kein Kontingentabbruch fuer die Planung. Protokolliert ein Ereignis je Vorgang (ADR-010).';

CREATE FUNCTION public.treatment_notes_context_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_kind text;
begin
  select a.kind into v_kind
  from public.appointments a
  where a.id = new.appointment_id;

  if v_kind is distinct from 'therapy' then
    raise exception 'only a treatment appointment can be documented'
      using errcode = '22023';
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION public.treatment_notes_context_guard() IS 'Par. 630f BGB gilt fuer die Behandlung: ein Dokumentationseintrag entsteht nur am Behandlungstermin (ADR-022 Punkt 6, ADR-016). Das Trainingsprotokoll ist kein Eintrag in diesem Sinne und haengt am Verhaeltnis, nicht am Termin (Punkt 7).';

CREATE FUNCTION public.undo_appointment_creation(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_termin record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Dieselbe Rollenmenge wie beim Anlegen (create_appointment).
  if not app.can_create_appointment() then
    raise exception 'not allowed to undo appointment creation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to undo appointment creation' using errcode = '42501';
  end if;

  if p_appointment_id is null or p_expected_updated_at is null then
    raise exception 'appointment and expected updated_at are required' using errcode = '22023';
  end if;

  -- Gesperrt bis zum Ende der Transaktion: Wer gleichzeitig etwas an den
  -- Termin haengt (Fremdschluessel), wartet - und danach sieht die Pruefung
  -- unten seine Zeile, oder sein Eintrag scheitert am fehlenden Termin.
  select a.id, a.kind, a.status, a.patient_id, a.created_by, a.created_at, a.updated_at
    into v_termin
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  -- ANN-534: nur, wer angelegt hat - auch owner nimmt fremde Termine nicht
  -- zurueck; dafuer gibt es die Absage.
  if v_termin.created_by is distinct from v_actor then
    raise exception 'not allowed to undo appointment creation' using errcode = '42501';
  end if;

  -- ANN-534: hoechstens 15 Minuten nach dem Anlegen.
  if now() - v_termin.created_at > interval '15 minutes' then
    raise exception 'undo window has passed' using errcode = '22023';
  end if;

  -- Der Stand, den die Aufrufende kennt, und kein geaenderter: Die
  -- Schreibwege am Termin setzen updated_at neu, create_appointment legt ihn
  -- gleich created_at an. So greift die Pruefung auch, wenn der Stand erst
  -- jetzt gelesen wurde - eine neue Person, ein anderer Ort oder ein anderes
  -- Ende fallen nicht still mit dem Termin. Ausnahme:
  -- transfer_appointments_to_treatment_basis laesst updated_at stehen
  -- (log_001b); eine Uebertragung auf eine andere Grundlage innerhalb der
  -- 15 Minuten faellt mit dem Termin weg - nichts Wirksames, der Termin hat
  -- weder Doku noch Leistung (ANN-534).
  if v_termin.updated_at is distinct from p_expected_updated_at
     or v_termin.updated_at is distinct from v_termin.created_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  -- Nur, was create_appointment anlegt: ein Behandlungstermin, noch geplant.
  if v_termin.kind <> 'therapy' or v_termin.status <> 'confirmed' then
    raise exception 'appointment creation cannot be undone' using errcode = '22023';
  end if;

  if exists (select 1 from public.treatment_notes x where x.appointment_id = p_appointment_id)
     or exists (
       select 1 from public.treatment_draft_findings x where x.appointment_id = p_appointment_id
     )
     or exists (select 1 from public.billable_services x where x.appointment_id = p_appointment_id)
     or exists (
       select 1 from public.appointment_session_fees x where x.appointment_id = p_appointment_id
     )
     or exists (select 1 from public.training_protocols x where x.appointment_id = p_appointment_id)
     or exists (
       select 1 from public.appointment_call_states x where x.appointment_id = p_appointment_id
     )
     or exists (
       select 1 from public.waitlist_entries x where x.placed_appointment_id = p_appointment_id
     )
     or exists (
       select 1 from public.platform_appointment_requests x
       where x.appointment_id = p_appointment_id or x.resulting_appointment_id = p_appointment_id
     )
     -- Eine Serie (create_appointment_series) entsteht in einer Transaktion:
     -- dieselbe Person, derselbe Zeitpunkt now(). Die Serie ist keine
     -- Entitaet (ADR-018 Punkt 5) - erkennbar ist sie nur daran.
     or exists (
       select 1 from public.appointments b
       where b.organization_id = v_org
         and b.created_by = v_termin.created_by
         and b.created_at = v_termin.created_at
         and b.id <> p_appointment_id
     ) then
    raise exception 'appointment creation cannot be undone' using errcode = '22023';
  end if;

  -- Mitgeteilt ist mitgeteilt: von Hand (Mitteilungsvermerk, CAL-012) oder
  -- als Benachrichtigung, die zugestellt ist oder gerade versandt wird
  -- (abgeholt, noch ohne Ergebnis).
  perform 1
  from public.notification_deliveries d
  where d.subject_id = p_appointment_id
    and d.kind in ('appointment_reminder', 'appointment_changed', 'appointment_cancelled')
  for update;

  if exists (
       select 1 from public.appointment_notifications x where x.appointment_id = p_appointment_id
     )
     or exists (
       select 1 from public.notification_deliveries d
       where d.subject_id = p_appointment_id
         and d.kind in ('appointment_reminder', 'appointment_changed', 'appointment_cancelled')
         and (d.state = 'sent' or (d.state = 'pending' and d.claimed_at is not null))
     ) then
    raise exception 'patient already notified' using errcode = '22023';
  end if;

  -- Zweitreview F2: Sieht die Person ihre Termine auf der Plattform - eigener
  -- Zugang oder Begleitung, aktiv -, hat sie diesen womoeglich schon gesehen.
  -- Dann faellt er nicht still weg (ADR-018 Punkt 2); die Oberflaeche sagt
  -- ihn stattdessen als Praxis ab, und die Person sieht die Absage. Ebenso,
  -- wenn der Zugang seit dem Anlegen gesperrt oder entzogen wurde: Bis dahin
  -- war der Termin sichtbar (Zweitreview Endstand, Befund 2; locked_at leert
  -- das Entsperren, revoked_at bleibt).
  if exists (
    select 1 from public.platform_accesses z
    where z.organization_id = v_org
      and z.relationship_kind = 'treatment'
      and z.patient_id = v_termin.patient_id
      and (z.status = 'active'
           or z.locked_at >= v_termin.created_at
           or z.revoked_at >= v_termin.created_at)
  ) then
    raise exception 'appointment is visible on the platform' using errcode = '22023';
  end if;

  -- Offene, verworfene und aufgegebene Auftraege fallen mit dem Termin.
  delete from public.notification_deliveries d
   where d.subject_id = p_appointment_id
     and d.kind in ('appointment_reminder', 'appointment_changed', 'appointment_cancelled');

  delete from public.appointments a where a.id = p_appointment_id;

  -- Wie beim Verwerfen eines Nachtrags (abn_022): eigener Lauf, due_at ist der
  -- Zeitpunkt des Zuruecknehmens, keine abgelaufene Frist. Die Datenklasse ist
  -- die des abgesagten Termins ohne Nachweis - eine eigene Klasse fuer
  -- Verworfenes waere ein eigener Auftrag (ANN-534).
  insert into public.deletion_journal
    (organization_id, run_id, target_table, target_id, retention_class, due_at)
  values
    (v_org, extensions.gen_random_uuid(), 'appointments', p_appointment_id,
     'termin_ohne_nachweis', now());
end;
$$;

COMMENT ON FUNCTION public.undo_appointment_creation(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) IS 'O-001 (B8, ANN-534): nimmt einen eben angelegten Behandlungstermin zurueck und loescht ihn - nur die anlegende Person mit Rolle der Terminverwaltung, hoechstens 15 Minuten nach dem Anlegen, noch geplant, seitdem unveraendert (updated_at = created_at, passend zum erwarteten Stand), ohne Doku, Entwurf, Leistung, Honorar, Anrufstand, Warteliste, Plattformwunsch, Serie und ohne Mitteilung, und nur, wenn die Person ihre Termine nicht auf der Plattform sieht. Offene Zustellauftraege fallen mit. Kein Auditeintrag; im Loeschjournal (ADR-008 Punkt 8).';

CREATE FUNCTION public.unlink_exercise_variants(p_link_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
begin
  v_org := app.exercise_library_writer();

  delete from public.exercise_variant_links where id = p_link_id and organization_id = v_org;
  if not found then
    raise exception 'exercise variant link not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.unlink_exercise_variants(p_link_id uuid) IS 'UEB-002: loest eine Verbindung zweier Varianten. Nur nach app.can_manage_exercise_library().';

CREATE FUNCTION public.unlock_with_pin(p_pin text) RETURNS TABLE(unlocked boolean, attempts_left integer, consumed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_konto   uuid := auth.uid();
  v_sitzung uuid := app.jwt_session_id();
  v_hash    text;
  v_zeile   public.session_unlocks%rowtype;
  v_versuche integer;
begin
  -- Ohne Token, Sitzung und echte Anmeldung gibt es keinen Versuch: Die PIN
  -- meldet nie an. Eine Sitzung aus einem nicht freigegebenen Passkey hat
  -- keinen - sonst brächte jeder neue fremde Passkey fünf neue Versuche.
  if v_konto is null or v_sitzung is null or app.last_first_factor() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select p.pin_hash into v_hash from public.account_pins p where p.user_id = v_konto;
  if v_hash is null then
    raise exception 'no pin' using errcode = 'P0002';
  end if;

  -- Eigene Löschregel der Datenklasse sitzungsvermerk für diese Tabelle:
  -- ohne offenen Fehlversuch oder verbraucht einen Tag nach der letzten
  -- Änderung; mit offenem Fehlversuch, sobald es die Sitzung beim
  -- Anmeldedienst nicht mehr gibt. Ein Tag trägt, solange jwt_expiry unter
  -- einem Tag liegt (heute 3600 Sekunden).
  delete from public.session_unlocks u
  where u.changed_at < now() - interval '1 day'
    and (u.failed_attempts = 0 or u.consumed_at is not null)
    and u.session_id <> v_sitzung;
  if to_regclass('auth.sessions') is not null then
    begin
      execute $q$
        delete from public.session_unlocks u
        where u.changed_at < now() - interval '1 day'
          and u.session_id <> $1
          and not exists (select 1 from auth.sessions s where s.id = u.session_id)
      $q$ using v_sitzung;
    exception when others then
      null;
    end;
  end if;

  insert into public.session_unlocks (session_id, user_id)
  values (v_sitzung, v_konto)
  on conflict (session_id) do nothing;

  select * into v_zeile
  from public.session_unlocks u
  where u.session_id = v_sitzung
  for update;

  if v_zeile.user_id <> v_konto then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if v_zeile.consumed_at is not null then
    return query select false, 0, true;
    return;
  end if;

  if extensions.crypt(coalesce(p_pin, ''), v_hash) = v_hash then
    update public.session_unlocks u
    set pin_unlocked_at = now(), failed_attempts = 0, changed_at = now()
    where u.session_id = v_sitzung;
    return query select true, app.pin_max_attempts(), false;
    return;
  end if;

  update public.session_unlocks u
  set failed_attempts = u.failed_attempts + 1, changed_at = now()
  where u.session_id = v_sitzung
  returning u.failed_attempts into v_versuche;

  if v_versuche >= app.pin_max_attempts() then
    update public.session_unlocks u
    set consumed_at = now()
    where u.session_id = v_sitzung;
    -- Die Sitzung endet auch beim Anmeldedienst. Scheitert das, trägt die
    -- Sperre über consumed_at allein: kein Zurückrollen des Verbrauchs
    -- (Zweitreview SEC-EPIC-002, Befund 3).
    if to_regclass('auth.sessions') is not null then
      begin
        execute 'delete from auth.sessions where id = $1' using v_sitzung;
      exception when others then
        null;
      end;
    end if;
    return query select false, 0, true;
    return;
  end if;

  return query select false, app.pin_max_attempts() - v_versuche, false;
end;
$_$;

COMMENT ON FUNCTION public.unlock_with_pin(p_pin text) IS 'Gibt die laufende, gesperrte Sitzung mit der App-PIN des eigenen Kontos frei (ADR-025 Punkt 11). Meldet nie an. Nach fuenf Fehlversuchen in Folge ist die Sitzung verbraucht und beim Anmeldedienst beendet. Keine Auditzeile.';

CREATE FUNCTION public.unsave_team_message(p_message uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  delete from public.team_saved_messages
  where message_id = p_message and staff_member_id = v_staff and organization_id = v_org;
end;
$$;

CREATE FUNCTION public.update_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false, p_confirmed_past boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor       uuid;
  v_org         uuid;
  v_tz          text;
  v_heute       date;
  v_starts_at   timestamptz;
  v_ends_at     timestamptz;
  v_location_id uuid;
  v_street      text;
  v_house       text;
  v_postal      text;
  v_city        text;
  v_alt         record;
  v_geaendert   text[] := array[]::text[];
  v_zeit        boolean := false;
  v_organisch   boolean := false;
  v_aktion      text;
  v_grid        smallint;
  v_ausserhalb  boolean := false;
  v_alt_laenge  interval;
  v_neu_laenge  interval;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- TRN-004: Die Trainingsbetreuung verschiebt Trainingstermine; welchen
  -- Kontext jemand schreiben darf, entscheidet der Riegel an der Zeile.
  if not (app.can_update_appointment() or app.can_write_training_relationships()) then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.staff_member_id, a.location_id, a.appointment_type,
         a.kind, a.status, a.starts_at, a.ends_at, a.updated_at,
         a.visit_street, a.visit_house_number, a.visit_postal_code, a.visit_city,
         a.training_relationship_id
    into v_alt
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
    -- TRN-006: kein Durchgriff ueber den gemeinsamen Kalender (ADR-022 Punkt 11).
    and app.may_write_appointment_context(a.kind)
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  -- Abgesagte Termine sind terminal (ADR-018 Punkt 2).
  if v_alt.status = 'cancelled' then
    raise exception 'cancelled appointment cannot be changed' using errcode = '22023';
  end if;

  -- Durchgefuehrt und nicht angetroffen sind nicht terminal, aber auch nicht
  -- direkt aenderbar: erst wieder oeffnen, dann bearbeiten (CAL-004, CAL-008c).
  if v_alt.status in ('completed', 'no_show') then
    raise exception 'completed appointment must be reopened first' using errcode = '22023';
  end if;

  -- Dokumentiert und abgerechnet haben keinen Rueckweg (ADR-018 Punkt 2).
  if v_alt.status <> 'confirmed' then
    raise exception 'documented appointment cannot be changed' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  if p_appointment_type is null
     or p_appointment_type not in ('home_visit', 'practice', 'video') then
    raise exception 'unknown appointment type' using errcode = '22023';
  end if;

  -- Ein Ereignis hat keine Patientenanschrift, also auch keinen Hausbesuch.
  if v_alt.kind = 'internal' and p_appointment_type = 'home_visit' then
    raise exception 'unknown appointment type' using errcode = '22023';
  end if;

  if p_date is null or p_start_time is null or p_end_time is null then
    raise exception 'date, start time and end time are required' using errcode = '22023';
  end if;

  if p_end_time <= p_start_time then
    raise exception 'end time must be after start time' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes
    into v_tz, v_grid
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  -- PROJECT_PRINCIPLES.md 0.11 Abschnitt 8.1, ANN-056: Die Laenge einer
  -- Behandlung ist frei im Raster, und geprueft wird sie nur, wenn sie sich
  -- aendert. Beide Laengen in Ortszeit, damit ein Bestandstermin an einem
  -- Umstellungstag nicht allein deshalb als geaendert gilt.
  --
  -- Ein Ereignis ist ans Raster gebunden, und zwar an beiden Enden (CAL-015b).
  v_alt_laenge := (v_alt.ends_at   at time zone v_tz)
                - (v_alt.starts_at at time zone v_tz);
  v_neu_laenge := p_end_time - p_start_time;

  -- TRN-004: Ein Trainingstermin ist frei im Raster wie die Behandlung.
  if v_alt.kind in ('therapy', 'training') then
    if v_neu_laenge is distinct from v_alt_laenge
       and not app.is_valid_treatment_length(v_neu_laenge, v_grid) then
      raise exception 'appointment length is not on the appointment grid' using errcode = '22023';
    end if;
  elsif not app.is_on_appointment_grid(p_end_time, v_grid) then
    raise exception 'end time is not on the appointment grid' using errcode = '22023';
  end if;

  v_heute := (now() at time zone v_tz)::date;

  -- FIX-019, ANN-057: Die Vergangenheit ist erlaubt, aber nie unbemerkt.
  -- Ohne Bestaetigung bleibt die Abweisung aus CAL-003 - die Oberflaeche
  -- fragt nach und schickt den Vorgang bestaetigt neu.
  if p_date < v_heute and not coalesce(p_confirmed_past, false) then
    raise exception 'appointment date is in the past' using errcode = '22023';
  end if;

  v_starts_at := (p_date + p_start_time) at time zone v_tz;
  v_ends_at   := (p_date + p_end_time)   at time zone v_tz;

  if v_starts_at is distinct from v_alt.starts_at
     and not app.is_on_appointment_grid(p_start_time, v_grid) then
    raise exception 'start time is not on the appointment grid' using errcode = '22023';
  end if;

  -- Behandeln darf nur, wer zuordenbar ist; an einem Ereignis nimmt auch das
  -- Buero teil (CAL-015b).
  if v_alt.kind = 'therapy' then
    if not app.is_assignable_therapist(p_staff_member_id, v_org) then
      raise exception 'staff member not assignable' using errcode = 'P0002';
    end if;
  elsif v_alt.kind = 'training' then
    -- ANN-176: Einen Trainingstermin betreut, wer die Rolle Trainingsbetreuung hat.
    if not app.is_assignable_trainer(p_staff_member_id, v_org) then
      raise exception 'staff member not assignable' using errcode = 'P0002';
    end if;
  elsif not exists (
    select 1 from public.staff_members sm
    where sm.id = p_staff_member_id
      and sm.organization_id = v_org
      and sm.employment_status = 'active'
  ) then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  if v_starts_at is distinct from v_alt.starts_at
     or v_ends_at is distinct from v_alt.ends_at
     or p_staff_member_id is distinct from v_alt.staff_member_id then
    v_ausserhalb := not app.is_within_working_hours(
      p_staff_member_id, v_org, p_date, p_start_time, p_end_time
    );

    if v_ausserhalb and not coalesce(p_allow_outside_working_hours, false) then
      raise exception 'outside_working_hours' using errcode = '22023';
    end if;
  end if;

  if p_appointment_type = 'practice' then
    if p_location_id is null then
      raise exception 'practice appointment requires a location' using errcode = '22023';
    end if;

    select l.id into v_location_id
    from public.locations l
    where l.id = p_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  else
    v_location_id := null;
  end if;

  if p_appointment_type = 'home_visit' then
    if v_alt.appointment_type = 'home_visit' then
      v_street := v_alt.visit_street;
      v_house  := v_alt.visit_house_number;
      v_postal := v_alt.visit_postal_code;
      v_city   := v_alt.visit_city;
    elsif v_alt.kind = 'training' then
      -- ANN-177: Die Anschrift kommt aus dem Trainingskontakt, nie aus der Akte.
      select x.street, x.house_number, x.postal_code, x.city
        into v_street, v_house, v_postal, v_city
      from app.training_visit_address(v_alt.training_relationship_id) x;

      if v_street is null or v_house is null or v_postal is null or v_city is null then
        raise exception 'home visit requires a complete address' using errcode = '22023';
      end if;
    else
      select
        nullif(btrim(c.street), ''),
        nullif(btrim(c.house_number), ''),
        nullif(btrim(c.postal_code), ''),
        nullif(btrim(c.city), '')
        into v_street, v_house, v_postal, v_city
      from public.patient_contact_details c
      where c.patient_id = v_alt.patient_id;

      if v_street is null or v_house is null or v_postal is null or v_city is null then
        raise exception 'home visit requires a complete patient address' using errcode = '22023';
      end if;
    end if;
  end if;

  if v_alt.staff_member_id is distinct from p_staff_member_id then
    v_geaendert := array_append(v_geaendert, 'staff_member_id');
    v_organisch := true;
  end if;
  if v_alt.appointment_type is distinct from p_appointment_type then
    v_geaendert := array_append(v_geaendert, 'appointment_type');
    v_organisch := true;
  end if;
  if v_alt.location_id is distinct from v_location_id then
    v_geaendert := array_append(v_geaendert, 'location_id');
    v_organisch := true;
  end if;
  if v_alt.starts_at is distinct from v_starts_at then
    v_geaendert := array_append(v_geaendert, 'starts_at');
    v_zeit := true;
  end if;
  if v_alt.ends_at is distinct from v_ends_at then
    v_geaendert := array_append(v_geaendert, 'ends_at');
    v_zeit := true;
  end if;

  if array_length(v_geaendert, 1) is null then
    return p_appointment_id;
  end if;

  begin
    update public.appointments
       set staff_member_id    = p_staff_member_id,
           appointment_type   = p_appointment_type,
           location_id        = v_location_id,
           starts_at          = v_starts_at,
           ends_at            = v_ends_at,
           visit_street       = v_street,
           visit_house_number = v_house,
           visit_postal_code  = v_postal,
           visit_city         = v_city,
           updated_at         = now()
     where id = p_appointment_id
       and updated_at = p_expected_updated_at;

    if not found then
      raise exception 'appointment was changed meanwhile' using errcode = '40001';
    end if;
  exception
    when exclusion_violation then
      raise exception 'appointment overlaps an existing one' using errcode = '23P01';
  end;

  v_aktion := case
    when v_zeit and not v_organisch then 'appointment.rescheduled'
    else 'appointment.updated'
  end;


  return p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.update_appointment(p_appointment_id uuid, p_expected_updated_at timestamp with time zone, p_staff_member_id uuid, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean, p_confirmed_past boolean) IS 'Aendert einen bestaetigten Termin. Prueft eine geaenderte Laenge gegen das Praxisraster (CAL-020), einen geaenderten Beginn gegen das Raster und eine Neuplanung gegen die Arbeitszeit (CAL-003, CAL-005, CAL-015b, ADR-018). Ein Tag in der Vergangenheit verlangt p_confirmed_past und steht im Auditkontext (FIX-019, ANN-057).';

CREATE FUNCTION public.update_appointment_event(p_event_group_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor       uuid;
  v_org         uuid;
  v_tz          text;
  v_grid        smallint;
  v_heute       date;
  v_starts_at   timestamptz;
  v_ends_at     timestamptz;
  v_titel       text;
  v_location_id uuid;
  v_stand       timestamptz;
  v_zeile       record;
  v_ausserhalb  boolean;
  v_konflikt    text;
  v_anzahl      integer := 0;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_update_appointment() then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  if p_event_group_id is null or p_expected_updated_at is null then
    raise exception 'event and expected updated_at are required' using errcode = '22023';
  end if;

  v_titel := btrim(coalesce(p_title, ''));
  if v_titel = '' then
    raise exception 'event title is required' using errcode = '22023';
  end if;
  if length(v_titel) > 120 then
    raise exception 'event title is too long' using errcode = '22023';
  end if;

  if p_appointment_type is null or p_appointment_type not in ('practice', 'video') then
    raise exception 'unknown appointment type' using errcode = '22023';
  end if;

  if p_date is null or p_start_time is null or p_end_time is null then
    raise exception 'date, start time and end time are required' using errcode = '22023';
  end if;

  if p_end_time <= p_start_time then
    raise exception 'end time must be after start time' using errcode = '22023';
  end if;

  select o.time_zone, o.appointment_grid_minutes
    into v_tz, v_grid
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  if not app.is_on_appointment_grid(p_start_time, v_grid) then
    raise exception 'start time is not on the appointment grid' using errcode = '22023';
  end if;
  if not app.is_on_appointment_grid(p_end_time, v_grid) then
    raise exception 'end time is not on the appointment grid' using errcode = '22023';
  end if;

  v_heute := (now() at time zone v_tz)::date;
  if p_date < v_heute then
    raise exception 'appointment date is in the past' using errcode = '22023';
  end if;

  v_starts_at := (p_date + p_start_time) at time zone v_tz;
  v_ends_at   := (p_date + p_end_time)   at time zone v_tz;

  if p_appointment_type = 'practice' then
    if p_location_id is null then
      raise exception 'practice appointment requires a location' using errcode = '22023';
    end if;

    select l.id into v_location_id
    from public.locations l
    where l.id = p_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  else
    v_location_id := null;
  end if;

  -- Alle Zeilen der Gruppe sperren, bevor irgendetwas geprueft wird: Sonst
  -- entschiede ein paralleler Vorgang zwischen Pruefung und Schreiben.
  perform 1
  from public.appointments a
  where a.organization_id = v_org
    and a.event_group_id  = p_event_group_id
    and a.kind = 'internal'
  for update;

  select max(a.updated_at) into v_stand
  from public.appointments a
  where a.organization_id = v_org
    and a.event_group_id  = p_event_group_id
    and a.kind = 'internal';

  if v_stand is null then
    raise exception 'event not found' using errcode = 'P0002';
  end if;

  if v_stand is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  -- Eine abgesagte Zeile ist terminal; ein Ereignis mit einer solchen ist als
  -- Ganzes nicht mehr aenderbar (ADR-018 Punkt 2). Fuer einen neuen Zeitraum
  -- wird ein neues Ereignis eingetragen.
  if exists (
    select 1 from public.appointments a
    where a.organization_id = v_org
      and a.event_group_id  = p_event_group_id
      and a.status <> 'confirmed'
  ) then
    raise exception 'cancelled appointment cannot be changed' using errcode = '22023';
  end if;

  for v_zeile in
    select a.id, a.staff_member_id, a.starts_at, a.ends_at
    from public.appointments a
    where a.organization_id = v_org
      and a.event_group_id  = p_event_group_id
    order by a.staff_member_id
  loop
    -- Arbeitszeit je Beteiligter, und nur wenn sich der Zeitraum wirklich
    -- aendert - sonst fragte ein blosses Umbenennen nach einer Bestaetigung,
    -- die mit der Aenderung nichts zu tun hat.
    if v_starts_at is distinct from v_zeile.starts_at
       or v_ends_at is distinct from v_zeile.ends_at then
      v_ausserhalb := not app.is_within_working_hours(
        v_zeile.staff_member_id, v_org, p_date, p_start_time, p_end_time
      );
      if v_ausserhalb and not coalesce(p_allow_outside_working_hours, false) then
        raise exception 'outside_working_hours' using errcode = '22023';
      end if;
    end if;

    -- Konflikt VOR dem Schreiben, und mit Namen: Die Constraint greift sonst
    -- bei irgendeiner Zeile, und die Meldung sagt nicht, wen es trifft.
    select coalesce(pp.given_name || ' ' || pp.family_name, 'Eine beteiligte Person')
      into v_konflikt
    from public.appointments b
    join public.staff_members sm on sm.id = b.staff_member_id
    join public.persons pp       on pp.id = sm.person_id
    where b.organization_id = v_org
      and b.staff_member_id = v_zeile.staff_member_id
      and b.status <> 'cancelled'
      and b.event_group_id is distinct from p_event_group_id
      and tstzrange(b.starts_at, b.ends_at, '[)')
          && tstzrange(v_starts_at, v_ends_at, '[)')
    limit 1;

    if v_konflikt is not null then
      raise exception 'appointment overlaps an existing one for %', v_konflikt
        using errcode = '23P01';
    end if;
  end loop;

  -- Der Riegel aus Abschnitt 7 laesst eine Zeitaenderung an einer Ereigniszeile
  -- nur zu, wenn sie aus genau diesem Vorgang kommt. Transaktionslokal, und
  -- unten ausdruecklich wieder zurueckgenommen.
  perform set_config('app.event_group_update', 'on', true);

  for v_zeile in
    select a.id, a.staff_member_id, a.starts_at, a.ends_at,
           a.appointment_type, a.location_id, a.title
    from public.appointments a
    where a.organization_id = v_org
      and a.event_group_id  = p_event_group_id
    order by a.staff_member_id
  loop
    update public.appointments
       set title            = v_titel,
           appointment_type = p_appointment_type,
           location_id      = v_location_id,
           starts_at        = v_starts_at,
           ends_at          = v_ends_at,
           updated_at       = now()
     where id = v_zeile.id;


    v_anzahl := v_anzahl + 1;
  end loop;

  perform set_config('app.event_group_update', 'off', true);

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.update_appointment_event(p_event_group_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_appointment_type text, p_date date, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean) IS 'Aendert Bezeichnung, Zeit, Laenge, Art und Ort EINES Ereignisses fuer alle Beteiligten in einer Transaktion (CAL-017). Erwartet den juengsten Stand der Gruppe; prueft Arbeitszeit und Ueberschneidung fuer jede beteiligte Person vor dem Schreiben. Wer teilnimmt, aendert update_appointment an der einzelnen Zeile.';

CREATE FUNCTION public.update_event_series(p_event_series_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_appointment_type text, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid DEFAULT NULL::uuid, p_allow_outside_working_hours boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org      uuid;
  v_tz       text;
  v_stand    timestamptz;
  v_vorkommen record;
  v_anzahl   integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_update_appointment() then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  if p_event_series_id is null or p_expected_updated_at is null then
    raise exception 'event series and expected updated_at are required' using errcode = '22023';
  end if;

  select o.time_zone into v_tz
  from public.organizations o
  where o.id = v_org;

  if v_tz is null then
    raise exception 'organization has no time zone' using errcode = '22023';
  end if;

  -- Erst sperren, dann pruefen: sonst entschiede ein paralleler Vorgang
  -- zwischen Pruefung und Schreiben (wie in update_appointment_event).
  perform 1
  from public.appointments a
  where a.organization_id = v_org
    and a.event_series_id = p_event_series_id
  for update;

  select max(a.updated_at) into v_stand
  from public.appointments a
  where a.organization_id = v_org
    and a.event_series_id = p_event_series_id;

  if v_stand is null then
    raise exception 'event series not found' using errcode = 'P0002';
  end if;

  if v_stand is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  for v_vorkommen in
    select a.event_group_id,
           min(a.starts_at) as beginn,
           max(a.updated_at) as stand
    from public.appointments a
    where a.organization_id = v_org
      and a.event_series_id = p_event_series_id
    group by a.event_group_id
    having min(a.starts_at) > now()
       and count(*) filter (where a.status <> 'confirmed') = 0
    order by min(a.starts_at)
  loop
    perform public.update_appointment_event(
      v_vorkommen.event_group_id,
      v_vorkommen.stand,
      p_title,
      p_appointment_type,
      (v_vorkommen.beginn at time zone v_tz)::date,
      p_start_time,
      p_end_time,
      p_location_id,
      p_allow_outside_working_hours
    );
    v_anzahl := v_anzahl + 1;
  end loop;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.update_event_series(p_event_series_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_appointment_type text, p_start_time time without time zone, p_end_time time without time zone, p_location_id uuid, p_allow_outside_working_hours boolean) IS 'Aendert Bezeichnung, Uhrzeit, Laenge, Art und Ort ALLER noch nicht begonnenen Vorkommen einer Serie in einer Transaktion (CAL-021, ANN-059). Die Tage bleiben; begonnene und abgesagte Vorkommen bleiben unberuehrt. Erwartet den juengsten Stand der Serie.';

CREATE FUNCTION public.update_home_visit_addresses(p_appointment_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org       uuid;
  v_actor     uuid := auth.uid();
  v_geschickt integer;
  v_anzahl    integer;
  v_zeile     record;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_update_appointment() or not app.may_write_appointment_context('therapy') then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update appointments' using errcode = '42501';
  end if;

  if p_appointment_ids is null or cardinality(p_appointment_ids) = 0 then
    raise exception 'appointments must be a non-empty array' using errcode = '22023';
  end if;

  v_geschickt := cardinality(array(select distinct unnest(p_appointment_ids)));

  create temp table abn_adressen on commit drop as
    select a.id,
           a.patient_id,
           nullif(btrim(c.street), '')       as street,
           nullif(btrim(c.house_number), '') as house_number,
           nullif(btrim(c.postal_code), '')  as postal_code,
           nullif(btrim(c.city), '')         as city
    from public.appointments a
    join public.patient_contact_details c on c.patient_id = a.patient_id
    where a.id = any(p_appointment_ids)
      and a.organization_id  = v_org
      and a.kind             = 'therapy'
      and a.appointment_type = 'home_visit'
      and a.status           = 'confirmed'
      and a.starts_at        > now();

  select count(*) into v_anzahl from abn_adressen;
  if v_anzahl <> v_geschickt then
    raise exception 'appointments are not updatable' using errcode = '22023';
  end if;

  if exists (
    select 1 from abn_adressen
    where street is null or house_number is null or postal_code is null or city is null
  ) then
    raise exception 'home visit requires a complete patient address' using errcode = '22023';
  end if;

  for v_zeile in select * from abn_adressen loop
    update public.appointments a
       set visit_street       = v_zeile.street,
           visit_house_number = v_zeile.house_number,
           visit_postal_code  = v_zeile.postal_code,
           visit_city         = v_zeile.city,
           updated_at         = now()
     where a.id = v_zeile.id;

  end loop;

  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.update_home_visit_addresses(p_appointment_ids uuid[]) IS 'Setzt kuenftige bestaetigte Hausbesuche auf die aktuelle Stammdatenadresse ihrer Patient:in (ABN-004, BEF-092): alles oder nichts, nur auf ausdrueckliche Bestaetigung, ein Auditeintrag appointment.updated je Termin mit changed_fields visit_address. Vergangene Termine behalten ihre damalige Adresse (ANN-003).';

CREATE FUNCTION public.update_nutrition_profile(p_profile_id uuid, p_expected timestamp with time zone, p_height_cm smallint, p_formula_sex text, p_body_fat_percent numeric, p_activity_pal numeric, p_goal text, p_bmr_formula text, p_target_weight_kg numeric) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil public.nutrition_profiles%rowtype;
  v_jetzt  timestamptz := clock_timestamp();
begin
  v_profil := app.nutrition_profile_for_writing(p_profile_id, true);
  if p_expected is distinct from v_profil.updated_at then
    raise exception 'nutrition profile changed meanwhile' using errcode = '40001';
  end if;

  update public.nutrition_profiles
     set height_cm = p_height_cm,
         formula_sex = p_formula_sex,
         body_fat_percent = p_body_fat_percent,
         activity_pal = p_activity_pal,
         goal = p_goal,
         bmr_formula = coalesce(p_bmr_formula, 'standard'),
         -- Ein unverändertes Zielgewicht behält, wer es gewählt hat.
         target_weight_source = case
           when p_target_weight_kg is null then null
           when p_target_weight_kg = v_profil.target_weight_kg then v_profil.target_weight_source
           else 'counsellor'
         end,
         target_weight_kg = p_target_weight_kg,
         updated_at = v_jetzt,
         updated_by = auth.uid()
   where id = v_profil.id;
  return v_jetzt;
end;
$$;

COMMENT ON FUNCTION public.update_nutrition_profile(p_profile_id uuid, p_expected timestamp with time zone, p_height_cm smallint, p_formula_sex text, p_body_fat_percent numeric, p_activity_pal numeric, p_goal text, p_bmr_formula text, p_target_weight_kg numeric) IS 'ERN-001 (ADR-027 Punkte 5, 16 bis 21): ändert Körperdaten, Aktivität, Ziel, Formel und Zielgewicht eines laufenden Profils mit Einwilligung. p_expected ist updated_at beim Laden (40001, wenn inzwischen geändert). Allein app.can_counsel_nutrition.';

CREATE FUNCTION public.update_patient(p_patient_id uuid, p_given_name text, p_family_name text, p_date_of_birth date, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_house_number text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_phone_work text DEFAULT NULL::text, p_phone_mobile text DEFAULT NULL::text, p_institution text DEFAULT NULL::text, p_primary_therapist_staff_member_id uuid DEFAULT NULL::uuid, p_home_visit_access_note text DEFAULT NULL::text, p_special_note text DEFAULT NULL::text, p_remark text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor          uuid;
  v_org            uuid;
  v_person_id      uuid;
  v_given          text;
  v_family         text;
  v_email          text;
  v_phone          text;
  v_street         text;
  v_house          text;
  v_postal         text;
  v_city           text;
  v_phone_work     text;
  v_phone_mobile   text;
  v_institution    text;
  v_zugang         text;
  v_besonderheit   text;
  v_bemerkung      text;
  v_alt_given      text;
  v_alt_family     text;
  v_alt_dob        date;
  v_alt_email      text;
  v_alt_phone      text;
  v_alt_street     text;
  v_alt_house      text;
  v_alt_postal     text;
  v_alt_city       text;
  v_alt_work       text;
  v_alt_mobile     text;
  v_alt_inst       text;
  v_alt_therapist  uuid;
  v_alt_zugang     text;
  v_alt_besonder   text;
  v_alt_bemerkung  text;
  v_hat_kontakt    boolean;
  v_hat_versorgung boolean;
  v_geaendert      text[] := array[]::text[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- SECURITY DEFINER umgeht RLS, deshalb wird die Berechtigung hier selbst
  -- geprueft.
  if not app.can_update_patient() then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to update patients' using errcode = '42501';
  end if;

  -- Eingaben serverseitig normalisieren. Die Pruefung im Client ist
  -- Bedienkomfort, keine Zusicherung (ADR-004).
  v_given        := nullif(btrim(p_given_name), '');
  v_family       := nullif(btrim(p_family_name), '');
  v_email        := nullif(btrim(p_email), '');
  v_phone        := nullif(btrim(p_phone), '');
  v_street       := nullif(btrim(p_street), '');
  v_house        := nullif(btrim(p_house_number), '');
  v_postal       := nullif(btrim(p_postal_code), '');
  v_city         := nullif(btrim(p_city), '');
  v_phone_work   := nullif(btrim(p_phone_work), '');
  v_phone_mobile := nullif(btrim(p_phone_mobile), '');
  v_institution  := nullif(btrim(p_institution), '');
  v_zugang       := nullif(btrim(p_home_visit_access_note), '');
  v_besonderheit := nullif(btrim(p_special_note), '');
  v_bemerkung    := nullif(btrim(p_remark), '');

  if v_given is null or v_family is null then
    raise exception 'given_name and family_name are required' using errcode = '22023';
  end if;

  if p_date_of_birth is null then
    raise exception 'date_of_birth is required' using errcode = '22023';
  end if;

  if p_date_of_birth > current_date then
    raise exception 'date_of_birth must not be in the future' using errcode = '22023';
  end if;

  -- Zielpatient ausschliesslich in der Organisation des Aufrufers suchen. Ein
  -- Patient einer fremden Praxis wird damit nicht gefunden und ist von einer
  -- unbekannten ID nicht zu unterscheiden.
  select p.person_id, pe.given_name, pe.family_name
    into v_person_id, v_alt_given, v_alt_family
  from public.patients p
  join public.persons pe on pe.id = p.person_id
  where p.id = p_patient_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  -- Erst nach der Existenzpruefung: eine fremde Mitarbeiter-ID darf nicht
  -- verraten, ob der Patient existiert - und umgekehrt.
  perform app.assert_staff_member_in_org(p_primary_therapist_staff_member_id, v_org);

  select c.date_of_birth, c.email, c.phone, c.street, c.house_number,
         c.postal_code, c.city, c.phone_work, c.phone_mobile, c.institution
    into v_alt_dob, v_alt_email, v_alt_phone, v_alt_street, v_alt_house,
         v_alt_postal, v_alt_city, v_alt_work, v_alt_mobile, v_alt_inst
  from public.patient_contact_details c
  where c.patient_id = p_patient_id;
  v_hat_kontakt := found;

  select cd.primary_therapist_staff_member_id, cd.home_visit_access_note,
         cd.special_note, cd.remark
    into v_alt_therapist, v_alt_zugang, v_alt_besonder, v_alt_bemerkung
  from public.patient_care_details cd
  where cd.patient_id = p_patient_id;
  v_hat_versorgung := found;

  -- Nur die NAMEN der tatsaechlich geaenderten Felder werden spaeter
  -- protokolliert - niemals alte oder neue Werte (ADR-010, ADR-011).
  if v_alt_given  is distinct from v_given  then v_geaendert := array_append(v_geaendert, 'given_name');    end if;
  if v_alt_family is distinct from v_family then v_geaendert := array_append(v_geaendert, 'family_name');   end if;
  if v_alt_dob    is distinct from p_date_of_birth then v_geaendert := array_append(v_geaendert, 'date_of_birth'); end if;
  if v_alt_email  is distinct from v_email  then v_geaendert := array_append(v_geaendert, 'email');         end if;
  if v_alt_phone  is distinct from v_phone  then v_geaendert := array_append(v_geaendert, 'phone');         end if;
  if v_alt_street is distinct from v_street then v_geaendert := array_append(v_geaendert, 'street');        end if;
  if v_alt_house  is distinct from v_house  then v_geaendert := array_append(v_geaendert, 'house_number');  end if;
  if v_alt_postal is distinct from v_postal then v_geaendert := array_append(v_geaendert, 'postal_code');   end if;
  if v_alt_city   is distinct from v_city   then v_geaendert := array_append(v_geaendert, 'city');          end if;
  if v_alt_work   is distinct from v_phone_work   then v_geaendert := array_append(v_geaendert, 'phone_work');   end if;
  if v_alt_mobile is distinct from v_phone_mobile then v_geaendert := array_append(v_geaendert, 'phone_mobile'); end if;
  if v_alt_inst   is distinct from v_institution  then v_geaendert := array_append(v_geaendert, 'institution');  end if;
  if v_alt_therapist is distinct from p_primary_therapist_staff_member_id
    then v_geaendert := array_append(v_geaendert, 'primary_therapist_staff_member_id'); end if;
  if v_alt_zugang    is distinct from v_zugang       then v_geaendert := array_append(v_geaendert, 'home_visit_access_note'); end if;
  if v_alt_besonder  is distinct from v_besonderheit then v_geaendert := array_append(v_geaendert, 'special_note');           end if;
  if v_alt_bemerkung is distinct from v_bemerkung    then v_geaendert := array_append(v_geaendert, 'remark');                 end if;

  -- Ein Absenden ohne tatsaechliche Aenderung ist kein Vorgang: weder
  -- Schreibzugriff noch Auditeintrag.
  if array_length(v_geaendert, 1) is null then
    return p_patient_id;
  end if;

  update public.persons
     set given_name = v_given,
         family_name = v_family
   where id = v_person_id;

  if v_hat_kontakt then
    update public.patient_contact_details
       set date_of_birth = p_date_of_birth,
           email         = v_email,
           phone         = v_phone,
           street        = v_street,
           house_number  = v_house,
           postal_code   = v_postal,
           city          = v_city,
           phone_work    = v_phone_work,
           phone_mobile  = v_phone_mobile,
           institution   = v_institution
     where patient_id = p_patient_id;
  else
    -- Bestandsdaten ohne Kontaktsatz: der Satz entsteht mit der ersten
    -- Aenderung, in der Organisation des Patienten.
    insert into public.patient_contact_details (
      patient_id, organization_id, date_of_birth,
      email, phone, street, house_number, postal_code, city,
      phone_work, phone_mobile, institution, created_by
    )
    values (
      p_patient_id, v_org, p_date_of_birth,
      v_email, v_phone, v_street, v_house, v_postal, v_city,
      v_phone_work, v_phone_mobile, v_institution, v_actor
    );
  end if;

  if v_hat_versorgung then
    update public.patient_care_details
       set primary_therapist_staff_member_id = p_primary_therapist_staff_member_id,
           home_visit_access_note            = v_zugang,
           special_note                      = v_besonderheit,
           remark                            = v_bemerkung
     where patient_id = p_patient_id;
  else
    insert into public.patient_care_details (
      patient_id, organization_id, primary_therapist_staff_member_id,
      home_visit_access_note, special_note, remark, created_by
    )
    values (
      p_patient_id, v_org, p_primary_therapist_staff_member_id,
      v_zugang, v_besonderheit, v_bemerkung, v_actor
    );
  end if;


  return p_patient_id;
end;
$$;

COMMENT ON FUNCTION public.update_patient(p_patient_id uuid, p_given_name text, p_family_name text, p_date_of_birth date, p_email text, p_phone text, p_street text, p_house_number text, p_postal_code text, p_city text, p_phone_work text, p_phone_mobile text, p_institution text, p_primary_therapist_staff_member_id uuid, p_home_visit_access_note text, p_special_note text, p_remark text) IS 'Aendert Person, Kontaktdaten und Versorgungsangaben eines Patienten atomar und protokolliert patient.updated mit den geaenderten Feldnamen (PAT-002, PAT-005, ADR-010). Seit SLK-001 ohne Telefax.';

CREATE FUNCTION public.update_platform_diary_entry(p_access_id uuid, p_id uuid, p_meal text, p_amount numeric DEFAULT NULL::numeric, p_portion_count numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profil  public.nutrition_profiles%rowtype;
  v_zugang  public.platform_accesses%rowtype;
  v_eintrag public.nutrition_diary_entries%rowtype;
  v_menge   numeric;
  v_anzahl  numeric;
begin
  v_profil := app.platform_diary_for_writing(p_access_id, null, true);
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  select * into v_eintrag from public.nutrition_diary_entries e
  where e.id = p_id and e.profile_id = v_profil.id
  for update;
  if v_eintrag.id is null then
    raise exception 'entry not found' using errcode = 'P0002';
  end if;
  if p_meal is null or p_meal not in ('breakfast', 'lunch', 'dinner', 'snack') then
    raise exception 'meal is required' using errcode = '22023';
  end if;
  if v_eintrag.portion_label is not null then
    if p_amount is not null or p_portion_count is null
       or p_portion_count <= 0 or p_portion_count > 20 then
      raise exception 'portion or amount' using errcode = '22023';
    end if;
    v_anzahl := round(p_portion_count, 2);
    v_menge := round(v_eintrag.portion_amount * v_anzahl, 1);
  else
    if p_portion_count is not null or p_amount is null or p_amount <= 0 or p_amount > 5000 then
      raise exception 'portion or amount' using errcode = '22023';
    end if;
    v_menge := round(p_amount, 1);
  end if;

  update public.nutrition_diary_entries e
     set meal = p_meal, amount = v_menge, portion_count = v_anzahl,
         platform_access_id = v_zugang.id, platform_access_kind = v_zugang.access_kind,
         updated_at = now(), updated_by = auth.uid()
   where e.id = v_eintrag.id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'nutrition_diary')
  );
end;
$$;

COMMENT ON FUNCTION public.update_platform_diary_entry(p_access_id uuid, p_id uuid, p_meal text, p_amount numeric, p_portion_count numeric) IS 'ERN-007: einen eigenen Eintrag ändern - Mahlzeit und Menge bzw. Anzahl der Portion. Wie add_platform_diary_entry: Einwilligung, eingeschaltet, nicht in der Lesefrist, nie die Begleitung.';

CREATE FUNCTION public.update_prescriber(p_prescriber_id uuid, p_family_name text, p_given_name text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_practice_name text DEFAULT NULL::text, p_speciality text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_house_number text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_fax text DEFAULT NULL::text, p_email text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_family text;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_prescribers() then
    raise exception 'not allowed to manage prescribers' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage prescribers' using errcode = '42501';
  end if;

  v_family := nullif(btrim(p_family_name), '');
  if v_family is null then
    raise exception 'family_name is required' using errcode = '22023';
  end if;

  -- Ziel ausschliesslich in der eigenen Organisation suchen: eine fremde und
  -- eine unbekannte ID sind nicht zu unterscheiden (PROJECT_PRINCIPLES.md 13).
  update public.prescribers
     set title         = nullif(btrim(p_title), ''),
         given_name    = nullif(btrim(p_given_name), ''),
         family_name   = v_family,
         practice_name = nullif(btrim(p_practice_name), ''),
         speciality    = nullif(btrim(p_speciality), ''),
         street        = nullif(btrim(p_street), ''),
         house_number  = nullif(btrim(p_house_number), ''),
         postal_code   = nullif(btrim(p_postal_code), ''),
         city          = nullif(btrim(p_city), ''),
         phone         = nullif(btrim(p_phone), ''),
         fax           = nullif(btrim(p_fax), ''),
         email         = nullif(btrim(p_email), ''),
         updated_at    = now(),
         updated_by    = v_actor
   where id = p_prescriber_id
     and organization_id = v_org;

  if not found then
    raise exception 'prescriber not found' using errcode = 'P0002';
  end if;

  return p_prescriber_id;
end;
$$;

COMMENT ON FUNCTION public.update_prescriber(p_prescriber_id uuid, p_family_name text, p_given_name text, p_title text, p_practice_name text, p_speciality text, p_street text, p_house_number text, p_postal_code text, p_city text, p_phone text, p_fax text, p_email text) IS 'Aendert eine Verordner:in der eigenen Organisation (VER-001).';

CREATE FUNCTION public.update_service_catalog_version(p_version_id uuid, p_label text, p_valid_from date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_label text;
  v_published timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select v.published_at into v_published
  from public.service_catalog_versions v
  where v.id = p_version_id and v.organization_id = v_org;

  if not found then
    raise exception 'service catalog version not found' using errcode = '42501';
  end if;

  if v_published is not null then
    raise exception 'published service catalog version is immutable' using errcode = '23514';
  end if;

  v_label := nullif(btrim(p_label), '');
  if v_label is null then
    raise exception 'label is required' using errcode = '22023';
  end if;

  if p_valid_from is null then
    raise exception 'valid_from is required' using errcode = '22023';
  end if;

  update public.service_catalog_versions
     set label = v_label, valid_from = p_valid_from
   where id = p_version_id;


  return p_version_id;
end;
$$;

COMMENT ON FUNCTION public.update_service_catalog_version(p_version_id uuid, p_label text, p_valid_from date) IS 'Aendert Bezeichnung und Gueltigkeitsbeginn eines Katalogentwurfs (ABR-001). Eine veroeffentlichte Version bleibt unveraenderlich.';

CREATE FUNCTION public.update_staff_member(p_staff_member_id uuid, p_given_name text, p_family_name text, p_work_email text DEFAULT NULL::text, p_work_phone text DEFAULT NULL::text, p_primary_location_id uuid DEFAULT NULL::uuid, p_date_of_birth date DEFAULT NULL::date, p_private_email text DEFAULT NULL::text, p_private_phone text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor       uuid;
  v_org         uuid;
  v_person_id   uuid;
  v_location_id uuid;
  v_given       text;
  v_family      text;
  v_work_email  text;
  v_work_phone  text;
  v_priv_email  text;
  v_priv_phone  text;
  v_street      text;
  v_postal      text;
  v_city        text;
  v_privat      boolean;
  v_alt         record;
  v_geaendert   text[] := array[]::text[];
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_staff_master_data() then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage staff' using errcode = '42501';
  end if;

  v_given  := btrim(coalesce(p_given_name, ''));
  v_family := btrim(coalesce(p_family_name, ''));

  if v_given = '' or v_family = '' then
    raise exception 'given name and family name are required' using errcode = '22023';
  end if;

  v_work_email := nullif(btrim(coalesce(p_work_email, '')), '');
  v_work_phone := nullif(btrim(coalesce(p_work_phone, '')), '');
  v_priv_email := nullif(btrim(coalesce(p_private_email, '')), '');
  v_priv_phone := nullif(btrim(coalesce(p_private_phone, '')), '');
  v_street     := nullif(btrim(coalesce(p_street, '')), '');
  v_postal     := nullif(btrim(coalesce(p_postal_code, '')), '');
  v_city       := nullif(btrim(coalesce(p_city, '')), '');

  v_privat := app.can_manage_staff_private_details();

  if not v_privat
     and (p_date_of_birth is not null or v_priv_email is not null or v_priv_phone is not null
          or v_street is not null or v_postal is not null or v_city is not null) then
    raise exception 'private_details_not_allowed' using errcode = '42501';
  end if;

  -- Zielsatz ausschliesslich in der eigenen Organisation suchen.
  select sm.id, sm.person_id, sm.primary_location_id, sm.work_email, sm.work_phone
    into v_alt
  from public.staff_members sm
  where sm.id = p_staff_member_id
    and sm.organization_id = v_org
  for update;

  if not found then
    raise exception 'staff member not found' using errcode = 'P0002';
  end if;

  v_person_id := v_alt.person_id;

  if p_primary_location_id is not null then
    select l.id into v_location_id
    from public.locations l
    where l.id = p_primary_location_id
      and l.organization_id = v_org;

    if not found then
      raise exception 'location not found' using errcode = 'P0002';
    end if;
  end if;

  -- Identitaetskern
  if exists (
    select 1 from public.persons pe
    where pe.id = v_person_id
      and (pe.given_name is distinct from v_given or pe.family_name is distinct from v_family)
  ) then
    update public.persons
       set given_name = v_given, family_name = v_family
     where id = v_person_id
       and organization_id = v_org;
    v_geaendert := array_append(v_geaendert, 'name');
  end if;

  -- Dienstliche Angaben
  if v_alt.work_email is distinct from v_work_email then
    v_geaendert := array_append(v_geaendert, 'work_email');
  end if;
  if v_alt.work_phone is distinct from v_work_phone then
    v_geaendert := array_append(v_geaendert, 'work_phone');
  end if;
  if v_alt.primary_location_id is distinct from v_location_id then
    v_geaendert := array_append(v_geaendert, 'primary_location_id');
  end if;

  update public.staff_members
     set work_email          = v_work_email,
         work_phone          = v_work_phone,
         primary_location_id = v_location_id
   where id = p_staff_member_id
     and organization_id = v_org;

  -- Privatdaten. Nur fuer Rollen, die sie auch lesen duerfen; fuer alle
  -- anderen bleibt die Zeile unberuehrt. Beschaeftigtendaten bleiben auf
  -- staff_private_details beschraenkt (PROJECT_PRINCIPLES.md 20).
  if v_privat then
    if exists (
      select 1 from public.staff_private_details spd
      where spd.staff_member_id = p_staff_member_id
    ) then
      if exists (
        select 1 from public.staff_private_details spd
        where spd.staff_member_id = p_staff_member_id
          and (
            spd.date_of_birth is distinct from p_date_of_birth
            or spd.private_email is distinct from v_priv_email
            or spd.private_phone is distinct from v_priv_phone
            or spd.street        is distinct from v_street
            or spd.postal_code   is distinct from v_postal
            or spd.city          is distinct from v_city
          )
      ) then
        v_geaendert := array_append(v_geaendert, 'private_details');
      end if;

      update public.staff_private_details
         set date_of_birth = p_date_of_birth,
             private_email = v_priv_email,
             private_phone = v_priv_phone,
             street        = v_street,
             postal_code   = v_postal,
             city          = v_city
       where staff_member_id = p_staff_member_id
         and organization_id = v_org;
    else
      insert into public.staff_private_details (
        staff_member_id, organization_id, date_of_birth,
        private_email, private_phone, street, postal_code, city, created_by
      )
      values (
        p_staff_member_id, v_org, p_date_of_birth,
        v_priv_email, v_priv_phone, v_street, v_postal, v_city, v_actor
      );

      if p_date_of_birth is not null or v_priv_email is not null or v_priv_phone is not null
         or v_street is not null or v_postal is not null or v_city is not null then
        v_geaendert := array_append(v_geaendert, 'private_details');
      end if;
    end if;
  end if;

  -- Kein Unterschied, kein Ereignis. Der Schreibvorgang oben ist dann
  -- wertgleich; ein Auditeintrag wuerde eine Aenderung behaupten, die es nicht
  -- gab (ADR-010).
  if array_length(v_geaendert, 1) is null then
    return p_staff_member_id;
  end if;


  return p_staff_member_id;
end;
$$;

COMMENT ON FUNCTION public.update_staff_member(p_staff_member_id uuid, p_given_name text, p_family_name text, p_work_email text, p_work_phone text, p_primary_location_id uuid, p_date_of_birth date, p_private_email text, p_private_phone text, p_street text, p_postal_code text, p_city text) IS 'Aendert die Stammdaten eines Mitarbeiterdatensatzes (owner und office, E10); Privatangaben nur durch owner. Protokolliert ausschliesslich die Namen der geaenderten Felder (STAFF-001, STAFF-002a, ADR-010).';

CREATE FUNCTION public.update_task(p_task_id uuid, p_title text, p_note text DEFAULT NULL::text, p_due_on date DEFAULT NULL::date, p_assigned_staff_member_id uuid DEFAULT NULL::uuid, p_patient_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_manage_tasks() then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write tasks' using errcode = '42501';
  end if;

  perform app.task_check_input(v_org, p_patient_id, p_assigned_staff_member_id);

  update public.tasks
     set title                    = btrim(p_title),
         note                     = nullif(btrim(p_note), ''),
         due_on                   = p_due_on,
         assigned_staff_member_id = p_assigned_staff_member_id,
         patient_id               = p_patient_id,
         updated_at               = now(),
         updated_by               = v_actor
   where id = p_task_id
     and organization_id = v_org;

  if not found then
    raise exception 'task not found' using errcode = 'P0002';
  end if;

end;
$$;

COMMENT ON FUNCTION public.update_task(p_task_id uuid, p_title text, p_note text, p_due_on date, p_assigned_staff_member_id uuid, p_patient_id uuid) IS 'Aendert eine Aufgabe der eigenen Praxis (PRX-012) und protokolliert task.updated ohne Titel und Notiz.';

CREATE FUNCTION public.update_team_channel(p_channel uuid, p_name text, p_description text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
  v_name  text;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if not app.team_channel_manageable(p_channel, v_org, v_staff) then
    if app.team_channel_readable(p_channel, v_org, v_staff) then
      raise exception 'not allowed to manage team channels' using errcode = '42501';
    end if;
    raise exception 'team channel not found' using errcode = 'P0002';
  end if;
  v_name := app.team_channel_name(p_name, p_description);
  if exists (select 1 from public.team_channels x where x.id = p_channel and x.kind = 'channel')
     and exists (select 1 from public.team_channels c
                 where c.organization_id = v_org and c.kind = 'channel'
                   and lower(c.name) = lower(v_name) and c.id <> p_channel) then
    raise exception 'channel name is taken' using errcode = '23505';
  end if;
  update public.team_channels
     set name = v_name, description = nullif(btrim(coalesce(p_description, '')), '')
   where id = p_channel;
end;
$$;

CREATE FUNCTION public.update_team_saved(p_message uuid, p_done boolean DEFAULT NULL::boolean, p_remind_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_clear_reminder boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  select o_org, o_staff into v_org, v_staff from app.teamchat_member();
  if p_remind_at is not null
     and (p_remind_at < now() + interval '1 minute' or p_remind_at > now() + interval '90 days') then
    raise exception 'reminder must be one minute to 90 days ahead' using errcode = '22023';
  end if;
  update public.team_saved_messages s
     set done = coalesce(p_done, s.done),
         remind_at = case when coalesce(p_clear_reminder, false) then null
                          else coalesce(p_remind_at, s.remind_at) end
   where s.message_id = p_message and s.staff_member_id = v_staff and s.organization_id = v_org;
  if not found then
    raise exception 'team message not found' using errcode = 'P0002';
  end if;
end;
$$;

CREATE FUNCTION public.update_text_snippet(p_snippet_id uuid, p_title text, p_body text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_use_text_snippets() then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to use text snippets' using errcode = '42501';
  end if;

  select s.id, s.staff_member_id
    into v_alt
  from public.treatment_text_snippets s
  where s.id = p_snippet_id
    and s.organization_id = v_org
    and (
      s.staff_member_id is null
      or s.staff_member_id in (
        select sm.id from public.staff_members sm where sm.person_id = app.current_person_id()
      )
    )
  for update;

  -- Ein fremder persoenlicher Baustein und ein nicht existierender sehen
  -- gleich aus: die Meldung taugt nicht als Existenz-Orakel.
  if not found then
    raise exception 'text snippet not found' using errcode = 'P0002';
  end if;

  perform app.assert_text_snippet_input(p_title, p_body, v_alt.staff_member_id);

  update public.treatment_text_snippets
     set title      = btrim(p_title),
         body       = btrim(p_body, E' \t\r\n'),
         updated_at = now(),
         updated_by = v_actor
   where id = p_snippet_id;

exception
  when unique_violation then
    raise exception 'a snippet with this title already exists' using errcode = '23505';
end;
$$;

COMMENT ON FUNCTION public.update_text_snippet(p_snippet_id uuid, p_title text, p_body text) IS 'Aendert Titel und Text eines Bausteins (UX-008). Der Geltungsbereich bleibt unveraendert.';

CREATE FUNCTION public.update_therapy_report(p_report_id uuid, p_report_text text, p_recommendation text, p_note_ids uuid[], p_body_chart_response_id uuid, p_expected_updated_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  b        public.therapy_reports%rowtype;
  v_text   text := nullif(btrim(p_report_text), '');
  v_empf   text := nullif(btrim(p_recommendation), '');
  v_ids    uuid[];
  v_stand  timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write therapy reports' using errcode = '42501';
  end if;

  select * into b from public.therapy_reports r
  where r.id = p_report_id and r.organization_id = v_org
  for update;
  if not found then
    raise exception 'therapy report not found' using errcode = 'P0002';
  end if;
  if b.status <> 'entwurf' then
    raise exception 'therapy report is completed and cannot be changed' using errcode = '55000';
  end if;
  if b.updated_at is distinct from p_expected_updated_at then
    raise exception 'therapy report was changed in the meantime' using errcode = '40001';
  end if;

  -- Reihenfolge der Auswahl ist ohne Bedeutung; doppelte Kreuze zaehlen einmal.
  select coalesce(array_agg(distinct x), '{}') into v_ids
  from unnest(coalesce(p_note_ids, '{}'::uuid[])) as x;

  perform app.therapy_report_pruefen(v_org, b.patient_id, v_ids, p_body_chart_response_id);

  v_stand := clock_timestamp();

  update public.therapy_reports r
     set report_text               = v_text,
         report_text_updated_by    = case when v_text is distinct from b.report_text
                                          then case when v_text is null then null else v_actor end
                                          else r.report_text_updated_by end,
         report_text_updated_at    = case when v_text is distinct from b.report_text
                                          then case when v_text is null then null else v_stand end
                                          else r.report_text_updated_at end,
         recommendation            = v_empf,
         recommendation_updated_by = case when v_empf is distinct from b.recommendation
                                          then case when v_empf is null then null else v_actor end
                                          else r.recommendation_updated_by end,
         recommendation_updated_at = case when v_empf is distinct from b.recommendation
                                          then case when v_empf is null then null else v_stand end
                                          else r.recommendation_updated_at end,
         note_ids                  = v_ids,
         body_chart_response_id    = p_body_chart_response_id,
         updated_at                = v_stand,
         updated_by                = v_actor
   where r.id = p_report_id;


  return v_stand;
end;
$$;

COMMENT ON FUNCTION public.update_therapy_report(p_report_id uuid, p_report_text text, p_recommendation text, p_note_ids uuid[], p_body_chart_response_id uuid, p_expected_updated_at timestamp with time zone) IS 'Speichert den Entwurf eines Therapieberichts (DOK-005a, ANN-122). therapist, team_lead; nur Eintraege und Erhebungen der eigenen Akte; protokolliert als therapy_report.updated.';

CREATE FUNCTION public.update_training_client(p_relationship_id uuid, p_given_name text, p_family_name text, p_date_of_birth date, p_email text, p_phone text, p_street text, p_postal_code text, p_city text, p_contract_started_on date, p_house_number text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_person uuid;
  v_ende   date;
  v_alt    record;
  v_felder text[] := '{}';
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_write_training_relationships() then
    perform app.record_denied_write(v_actor, 'training_relationship.updated', 'not allowed to manage training clients');
    return null;
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to manage training clients' using errcode = '42501';
  end if;

  if app.leer_zu_null(p_given_name) is null or app.leer_zu_null(p_family_name) is null then
    raise exception 'name is required' using errcode = '22023';
  end if;

  select t.person_id, t.contract_ended_on into v_person, v_ende
  from public.training_relationships t
  where t.id = p_relationship_id and t.organization_id = v_org
  for update;
  if not found then
    raise exception 'training relationship not found' using errcode = 'P0002';
  end if;

  if p_contract_started_on is null then
    raise exception 'contract start is required' using errcode = '22023';
  end if;
  if v_ende is not null and p_contract_started_on > v_ende then
    raise exception 'contract start is after the contract end' using errcode = '22023';
  end if;

  -- Welche Felder sich aendern - nur die Namen der Felder gehen ins Protokoll.
  select pe.given_name, pe.family_name, t.contract_started_on,
         d.date_of_birth, d.email, d.phone, d.street, d.house_number, d.postal_code, d.city
    into v_alt
  from public.training_relationships t
  join public.persons pe on pe.id = t.person_id
  left join public.training_contact_details d on d.training_relationship_id = t.id
  where t.id = p_relationship_id;

  if v_alt.given_name is distinct from btrim(p_given_name)
     or v_alt.family_name is distinct from btrim(p_family_name) then
    v_felder := array_append(v_felder, 'name');
  end if;
  if v_alt.contract_started_on is distinct from p_contract_started_on then
    v_felder := array_append(v_felder, 'contract_started_on');
  end if;
  if v_alt.date_of_birth is distinct from p_date_of_birth
     or v_alt.email is distinct from lower(app.leer_zu_null(p_email))
     or v_alt.phone is distinct from app.leer_zu_null(p_phone)
     or v_alt.street is distinct from app.leer_zu_null(p_street)
     or v_alt.house_number is distinct from app.leer_zu_null(p_house_number)
     or v_alt.postal_code is distinct from app.leer_zu_null(p_postal_code)
     or v_alt.city is distinct from app.leer_zu_null(p_city) then
    v_felder := array_append(v_felder, 'contact');
  end if;

  if cardinality(v_felder) = 0 then
    return p_relationship_id;
  end if;

  -- Der Name einer Mitarbeiter:in oder eines Kontos gehoert in die
  -- Mitarbeiterstammdaten: Aendern darf ihn dort nur, wer sie pflegt
  -- (app.can_manage_staff_master_data, ANN-174). Aus dem Training heraus
  -- ginge das an Pruefung und Protokoll vorbei (Zweitreview TRN-EPIC-001).
  -- Die Meldung verraet nichts, was §4.8 schuetzt: Zugehoerigkeit zum Team
  -- ist kein Behandlungsdatum.
  if array_position(v_felder, 'name') is not null
     and not app.can_manage_staff_master_data()
     and (
       exists (select 1 from public.staff_members x where x.person_id = v_person)
       or exists (select 1 from public.user_profiles x where x.person_id = v_person)
     ) then
    raise exception 'name is managed in staff master data' using errcode = '42501';
  end if;

  -- Der Name gehoert der Person, nicht dem Verhaeltnis (ANN-174).
  update public.persons
     set given_name = btrim(p_given_name), family_name = btrim(p_family_name)
   where id = v_person
     and (given_name is distinct from btrim(p_given_name)
          or family_name is distinct from btrim(p_family_name));

  update public.training_relationships
     set contract_started_on = p_contract_started_on
   where id = p_relationship_id
     and contract_started_on is distinct from p_contract_started_on;

  perform app.write_training_contact(
    p_relationship_id, v_org, v_actor, p_date_of_birth, p_email, p_phone, p_street, p_house_number, p_postal_code, p_city
  );


  return p_relationship_id;
end;
$$;

CREATE FUNCTION public.update_treatment_basis(p_treatment_basis_id uuid, p_prescriber_id uuid, p_treatment_basis_kind text, p_issued_on date, p_appointment_count integer, p_items jsonb, p_frequency_note text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_diagnosis text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor      uuid;
  v_org        uuid;
  v_patient_id uuid;
  v_selbstzahler boolean;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_bases() then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment_bases' using errcode = '42501';
  end if;

  select p.patient_id into v_patient_id
  from public.treatment_bases p
  where p.id = p_treatment_basis_id
    and p.organization_id = v_org;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  perform app.assert_treatment_basis_input(v_org, p_prescriber_id, p_treatment_basis_kind, p_issued_on);
  perform app.assert_appointment_count(p_appointment_count);

  v_selbstzahler := p_treatment_basis_kind = 'self_pay';

  -- PRX-010 (Zweitreview): Office tippt die Verordnung ab, raeumt aber keine
  -- klinischen Texte der Therapeut:innen ab. Der Wechsel auf Selbstzahler
  -- loescht Therapieziel, Verordnerhinweis und Empfehlung (ADR-020 Punkt 4) -
  -- stehen welche da, bleibt er den therapeutischen Rollen vorbehalten.
  if v_selbstzahler
     and not app.can_clear_treatment_basis_clinical_texts()
     and app.treatment_basis_has_clinical_texts(p_treatment_basis_id, v_org) then
    raise exception 'clinical texts on this treatment basis can only be cleared by treating roles'
      using errcode = '42501';
  end if;

  -- Therapieziel, Verordnerhinweis und Empfehlung stehen seit VER-EPIC-002
  -- nicht mehr im Formular. Sie kommen deshalb in dieser Anweisung nicht vor
  -- und bleiben unveraendert stehen - **ausser** beim Wechsel auf
  -- "Selbstzahler": Dort verlangt ADR-020 Punkt 4 sie leer, und das entscheidet
  -- der Server, nicht der Aufrufer.
  update public.treatment_bases
     set prescriber_id            = p_prescriber_id,
         treatment_basis_kind     = p_treatment_basis_kind,
         issued_on                = p_issued_on,
         appointment_count        = p_appointment_count,
         frequency_note           = nullif(btrim(p_frequency_note), ''),
         note                     = nullif(btrim(p_note), ''),
         diagnosis                = case when v_selbstzahler
                                         then null else nullif(btrim(p_diagnosis), '') end,
         therapy_goal             = case when v_selbstzahler then null else therapy_goal end,
         prescriber_note          = case when v_selbstzahler then null else prescriber_note end,
         follow_up_recommendation = case when v_selbstzahler
                                         then null else follow_up_recommendation end,
         updated_at               = now(),
         updated_by               = v_actor
   where id = p_treatment_basis_id;

  perform app.write_treatment_base_items(p_treatment_basis_id, v_org, v_actor, p_items);


  return p_treatment_basis_id;
end;
$$;

COMMENT ON FUNCTION public.update_treatment_basis(p_treatment_basis_id uuid, p_prescriber_id uuid, p_treatment_basis_kind text, p_issued_on date, p_appointment_count integer, p_items jsonb, p_frequency_note text, p_note text, p_diagnosis text) IS 'Aendert eine Behandlungsgrundlage samt Positionen atomar und protokolliert treatment_basis.updated (VER-003, ADR-010). Alle vier Praxisrollen seit PRX-010 (ANN-011). Die Patientin bleibt unveraendert. Ohne Therapieziel, Verordnerhinweis und Empfehlung: Bestandstexte bleiben unangetastet, beim Selbstzahler raeumt sie der Server ab (ADR-020 Punkt 4, ANN-064).';

CREATE FUNCTION public.update_treatment_note(p_note_id uuid, p_expected_updated_at timestamp with time zone, p_content text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_inhalt  text;
  v_alt     record;
  v_patient uuid;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_write_treatment_note() then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write treatment documentation' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  v_inhalt := btrim(coalesce(p_content, ''), E' \t\r\n');

  if v_inhalt = '' then
    raise exception 'documentation must not be empty' using errcode = '22023';
  end if;

  if length(v_inhalt) > 20000 then
    raise exception 'documentation is too long' using errcode = '22023';
  end if;

  select t.id, t.appointment_id, t.content, t.updated_at, t.status
    into v_alt
  from public.treatment_notes t
  where t.id = p_note_id
    and t.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment note not found' using errcode = 'P0002';
  end if;

  if v_alt.status <> 'draft' then
    raise exception 'finalized treatment note requires a revision' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'treatment note was changed meanwhile' using errcode = '40001';
  end if;

  if v_alt.content = v_inhalt then
    return p_note_id;
  end if;

  update public.treatment_notes
     set content    = v_inhalt,
         updated_at = now(),
         updated_by = v_actor
   where id = p_note_id
     and updated_at = p_expected_updated_at;

  if not found then
    raise exception 'treatment note was changed meanwhile' using errcode = '40001';
  end if;

  select a.patient_id into v_patient
  from public.appointments a
  where a.id = v_alt.appointment_id;


  return p_note_id;
end;
$$;

COMMENT ON FUNCTION public.update_treatment_note(p_note_id uuid, p_expected_updated_at timestamp with time zone, p_content text) IS 'Aendert den Entwurf einer Behandlungsdokumentation auf Basis eines erwarteten Standes und protokolliert treatment_note.updated (DOK-001, ADR-001, ADR-010). Fuer finalisierte Eintraege gilt revise_treatment_note (DOK-002).';

CREATE FUNCTION public.update_waitlist_entry(p_entry_id uuid, p_expected_updated_at timestamp with time zone, p_treatment_basis_id uuid, p_preferred_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_time_windows jsonb, p_earliest_on date, p_needed_by date, p_priority_reason text, p_note text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_eintrag public.waitlist_entries;
  v_stand   timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_create_appointment() then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to write waitlist' using errcode = '42501';
  end if;

  select * into v_eintrag
  from public.waitlist_entries w
  where w.id = p_entry_id and w.organization_id = v_org
  for update;
  if not found then
    raise exception 'waitlist entry not found' using errcode = 'P0002';
  end if;
  if v_eintrag.status <> 'open' then
    raise exception 'waitlist entry closed' using errcode = '22023';
  end if;
  if p_expected_updated_at is null or v_eintrag.updated_at <> p_expected_updated_at then
    raise exception 'waitlist entry changed' using errcode = '40001';
  end if;

  perform app.waitlist_check_input(
    v_org, v_eintrag.patient_id, p_treatment_basis_id, p_preferred_staff_member_id,
    p_appointment_type, p_duration_minutes, p_time_windows, p_earliest_on,
    p_needed_by, p_priority_reason, p_note
  );

  begin
    update public.waitlist_entries w
       set treatment_basis_id        = p_treatment_basis_id,
           preferred_staff_member_id = p_preferred_staff_member_id,
           appointment_type          = p_appointment_type,
           duration_minutes          = p_duration_minutes,
           time_windows              = coalesce(p_time_windows, '[]'::jsonb),
           earliest_on               = p_earliest_on,
           needed_by                 = p_needed_by,
           priority_reason           = p_priority_reason,
           note                      = nullif(btrim(p_note), ''),
           updated_at                = clock_timestamp(),
           updated_by                = v_actor
     where w.id = p_entry_id
    returning w.updated_at into v_stand;
  exception
    when unique_violation then
      raise exception 'patient already on waitlist' using errcode = '23505';
  end;


  return v_stand;
end;
$$;

COMMENT ON FUNCTION public.update_waitlist_entry(p_entry_id uuid, p_expected_updated_at timestamp with time zone, p_treatment_basis_id uuid, p_preferred_staff_member_id uuid, p_appointment_type text, p_duration_minutes integer, p_time_windows jsonb, p_earliest_on date, p_needed_by date, p_priority_reason text, p_note text) IS 'Aendert einen offenen Wartelisteneintrag mit Stand-Pruefung (PRX-001). Auditiert ohne Notiz.';

CREATE FUNCTION public.void_offset_payments(p_offset_group uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_zeile   record;
  v_eingang integer;
  v_rueck   integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'a void needs a reason' using errcode = '22023';
  end if;

  perform 1 from public.invoices i
   where i.id in (select p.invoice_id from public.payments p where p.offset_group = p_offset_group)
     and i.organization_id = v_org
   order by i.id
   for update;

  perform 1 from public.payments p
   where p.offset_group = p_offset_group and p.organization_id = v_org
   order by p.id
   for update;

  if not exists (
    select 1 from public.payments p
    where p.offset_group = p_offset_group and p.organization_id = v_org and p.voided_at is null
  ) then
    raise exception 'payment not found' using errcode = '42501';
  end if;

  -- An der Ersatzrechnung faellt ein Eingang weg. Stehen dort Rueckzahlungen,
  -- die ohne ihn ueber dem Eingang laegen, zuerst diese stornieren - dieselbe
  -- Regel wie bei einem einzelnen Eingang.
  for v_zeile in
    select p.invoice_id from public.payments p
    where p.offset_group = p_offset_group and p.direction = 'incoming'
  loop
    select coalesce(sum(case when p.direction = 'incoming' then p.amount_cents else 0 end), 0),
           coalesce(sum(case when p.direction = 'refund'   then p.amount_cents else 0 end), 0)
      into v_eingang, v_rueck
    from public.payments p
    where p.invoice_id = v_zeile.invoice_id
      and p.voided_at is null
      and p.offset_group is distinct from p_offset_group;

    if v_rueck > v_eingang then
      raise exception 'voiding this payment would leave refunds without payments received'
        using errcode = '23514';
    end if;
  end loop;

  update public.payments
     set voided_at   = now(),
         voided_by   = v_actor,
         void_reason = btrim(p_reason)
   where offset_group = p_offset_group
     and voided_at is null;

end;
$$;

COMMENT ON FUNCTION public.void_offset_payments(p_offset_group uuid, p_reason text) IS 'Storniert beide Buchungen einer Verrechnung gemeinsam, mit Grund (ABN-008). Eine Haelfte allein liesse Geld an einer Rechnung auftauchen oder verschwinden.';

CREATE FUNCTION public.void_payment(p_payment_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor   uuid;
  v_org     uuid;
  v_payment record;
  v_eingang integer;
  v_rueck   integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_invoicing() then
    raise exception 'not allowed to manage invoices' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  -- ABN-008: Eine Verrechnung besteht aus zwei Buchungen, einer an jeder
  -- Rechnung. Sie werden nur gemeinsam storniert; eine Haelfte allein liesse
  -- Geld an einer Rechnung auftauchen oder verschwinden. Uebergeben wird
  -- VOR jeder Sperre: void_offset_payments sperrt erst beide Rechnungen,
  -- dann beide Zeilen - in fester Reihenfolge (Zweitreview B6).
  if exists (
    select 1 from public.payments p
    where p.id = p_payment_id and p.organization_id = v_org and p.offset_group is not null
  ) then
    perform public.void_offset_payments(
      (select p.offset_group from public.payments p where p.id = p_payment_id), p_reason);
    return;
  end if;

  select p.* into v_payment
  from public.payments p
  where p.id = p_payment_id and p.organization_id = v_org
  for update;

  if not found then
    raise exception 'payment not found' using errcode = '42501';
  end if;

  if v_payment.voided_at is not null then
    raise exception 'payment is already voided' using errcode = '23514';
  end if;

  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'a void needs a reason' using errcode = '22023';
  end if;

  -- Dieselbe Sperre wie in record_payment: Beide Vorgaenge aendern die
  -- Zahlungssumme derselben Rechnung und muessen deshalb hintereinander
  -- laufen, nicht nebeneinander.
  perform 1 from public.invoices i where i.id = v_payment.invoice_id for update;

  -- Wird ein Eingang storniert, koennten bereits gebuchte Rueckzahlungen
  -- ueber der verbliebenen Summe liegen. Dann zuerst die Rueckzahlung
  -- stornieren - sonst stuende am Ende mehr ausgezahlt als eingegangen.
  if v_payment.direction = 'incoming' then
    select coalesce(sum(case when p.direction = 'incoming' then p.amount_cents else 0 end), 0),
           coalesce(sum(case when p.direction = 'refund'   then p.amount_cents else 0 end), 0)
      into v_eingang, v_rueck
    from public.payments p
    where p.invoice_id = v_payment.invoice_id
      and p.voided_at is null
      and p.id <> p_payment_id;

    if v_rueck > v_eingang then
      raise exception 'voiding this payment would leave refunds without payments received'
        using errcode = '23514';
    end if;
  end if;

  update public.payments
     set voided_at   = now(),
         voided_by   = v_actor,
         void_reason = btrim(p_reason)
   where id = p_payment_id;

end;
$$;

COMMENT ON FUNCTION public.void_payment(p_payment_id uuid, p_reason text) IS 'Storniert eine erfasste Zahlung mit Grund (ABR-004, R3-015). Die Zeile bleibt sichtbar stehen und faellt aus jeder Summe; geaendert oder geloescht wird eine Zahlung nie. Sperrt die Rechnung wie record_payment, damit Storno und Buchung nicht aneinander vorbeilaufen.';

CREATE FUNCTION public.waive_appointment_fee(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_alt   record;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_record_billable_services() then
    raise exception 'not allowed to waive fees' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to waive fees' using errcode = '42501';
  end if;

  if p_expected_updated_at is null then
    raise exception 'expected updated_at is required' using errcode = '22023';
  end if;

  select a.id, a.patient_id, a.status, a.fee_basis, a.fee_waived_at, a.updated_at
    into v_alt
  from public.appointments a
  where a.id = p_appointment_id
    and a.organization_id = v_org
  for update;

  if not found then
    raise exception 'appointment not found' using errcode = 'P0002';
  end if;

  if v_alt.fee_basis is null then
    raise exception 'appointment has no fee occasion' using errcode = '22023';
  end if;

  if v_alt.fee_waived_at is not null then
    raise exception 'fee is already waived' using errcode = '22023';
  end if;

  if v_alt.status = 'invoiced' then
    raise exception 'fee is already invoiced' using errcode = '22023';
  end if;

  if exists (select 1 from public.billable_services b where b.appointment_id = p_appointment_id) then
    raise exception 'fee is already recorded as a service' using errcode = '22023';
  end if;

  if v_alt.updated_at is distinct from p_expected_updated_at then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;

  update public.appointments
     set fee_waived_at = now(),
         fee_waived_by = v_actor,
         updated_at    = now()
   where id = p_appointment_id
     and updated_at = p_expected_updated_at;

  if not found then
    raise exception 'appointment was changed meanwhile' using errcode = '40001';
  end if;


  return p_appointment_id;
end;
$$;

COMMENT ON FUNCTION public.waive_appointment_fee(p_appointment_id uuid, p_expected_updated_at timestamp with time zone) IS 'Vermerkt den bewussten Verzicht auf die Gebuehr eines Termins mit Gebuehrenanlass; der Anlass bleibt. Nur owner und office, nur solange keine Leistung erfasst und nichts abgerechnet ist. Protokolliert appointment.fee_waived (ABN-006, BEF-094, ANN-213).';

CREATE FUNCTION public.withdraw_leave_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  v_org := app.staff_request_org(app.can_request_leave(), 'not allowed to request leave');
  v_staff := app.own_staff_member(v_org);
  update public.staff_leave_requests r
     set status = 'withdrawn', withdrawn_at = now()
   where r.id = p_request_id
     and r.organization_id = v_org
     and r.staff_member_id = v_staff
     and r.status = 'requested';
  if not found then
    raise exception 'leave request not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.withdraw_leave_request(p_request_id uuid) IS 'URL-001: den eigenen offenen Antrag (Urlaub oder Storno) zurueckziehen. Fremde, entschiedene und unbekannte Antraege sind nicht zu unterscheiden.';

CREATE FUNCTION public.withdraw_platform_appointment_request(p_access_id uuid, p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang public.platform_accesses%rowtype;
begin
  if not app.platform_access_allows(p_access_id, 'request') then
    return false;
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;

  update public.platform_appointment_requests w
     set status = 'withdrawn', resolved_at = now(), resolved_by = auth.uid()
   where w.id = p_request_id
     and w.organization_id = v_zugang.organization_id
     and w.relationship_kind = v_zugang.relationship_kind
     and w.relationship_id = v_zugang.relationship_id
     and w.status = 'open';
  if not found then
    return false;
  end if;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'request_withdrawn')
  );
  return true;
end;
$$;

COMMENT ON FUNCTION public.withdraw_platform_appointment_request(p_access_id uuid, p_request_id uuid) IS 'POR-009: Die Person zieht einen offenen Terminwunsch zurueck; der Vorgang bleibt als zurueckgezogen stehen (Frist ANN-246). Nur ueber einen lesbaren Zugang des eigenen Verhaeltnisses.';

CREATE FUNCTION public.withdraw_platform_training_contract(p_access_id uuid, p_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zugang  public.platform_accesses%rowtype;
  v_vertrag public.training_contracts%rowtype;
  v_heute   date;
begin
  if not app.platform_access_allows(p_access_id, 'contract') then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;
  select * into v_zugang from public.platform_accesses a where a.id = p_access_id;
  if v_zugang.relationship_kind <> 'training' then
    raise exception 'platform access not allowed' using errcode = '42501';
  end if;

  perform 1 from public.training_relationships t
  where t.id = v_zugang.relationship_id and t.organization_id = v_zugang.organization_id
  for update;

  select * into v_vertrag
  from public.training_contracts k
  where k.id = p_contract_id
    and k.training_relationship_id = v_zugang.relationship_id
    and k.organization_id = v_zugang.organization_id
  for update;
  if not found then
    raise exception 'training contract not found' using errcode = '42501';
  end if;
  if v_vertrag.withdrawn_at is not null then
    raise exception 'training contract already withdrawn' using errcode = '23514';
  end if;

  v_heute := app.training_today(v_vertrag.organization_id);
  if v_heute > v_vertrag.withdrawal_ends_on then
    raise exception 'withdrawal period has ended' using errcode = '23514';
  end if;

  update public.training_contracts k
     set withdrawn_at = now(),
         withdrawn_on = v_heute,
         withdrawn_platform_access_id = v_zugang.id,
         withdrawn_access_kind = v_zugang.access_kind,
         withdrawn_representative_name = case when v_zugang.access_kind = 'legal_representative'
                                              then v_zugang.representative_name end
   where k.id = p_contract_id;

  perform app.log_platform_representation(
    v_zugang.id, 'platform_representation.read', jsonb_build_object('view', 'training_contract_withdrawn')
  );

  return (
    select jsonb_build_object(
      'withdrawn_at', k.withdrawn_at,
      'withdrawn_on', k.withdrawn_on,
      'label', k.package_label,
      'concluded_at', k.concluded_at
    )
    from public.training_contracts k where k.id = p_contract_id
  );
end;
$$;

COMMENT ON FUNCTION public.withdraw_platform_training_contract(p_access_id uuid, p_contract_id uuid) IS 'KND-004 (Par. 356a BGB): die Widerrufsfunktion der Plattform. Recht contract (Person, rechtliche Vertretung mit Vermoegenssorge), nur innerhalb der Frist und einmal. Liefert die Eingangsbestaetigung mit Zeitpunkt; die Abwicklung macht die Praxis (ANN-290).';

CREATE FUNCTION public.withdraw_reimbursement(p_reimbursement_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_staff   uuid;
  v_antrag  public.staff_reimbursements%rowtype;
begin
  v_org := app.staff_request_org(app.can_request_reimbursements(), 'not allowed to request reimbursements');
  v_staff := app.own_staff_member(v_org);
  select r.* into v_antrag
  from public.staff_reimbursements r
  where r.id = p_reimbursement_id and r.organization_id = v_org
    and r.staff_member_id is not distinct from v_staff
  for update;
  if v_antrag.id is null then
    raise exception 'reimbursement not found' using errcode = 'P0002';
  end if;
  if v_antrag.status <> 'requested' then
    raise exception 'reimbursement is not open' using errcode = '55000';
  end if;
  update public.staff_reimbursements
     set status = 'withdrawn', withdrawn_at = now()
   where id = v_antrag.id;
end;
$$;

COMMENT ON FUNCTION public.withdraw_reimbursement(p_reimbursement_id uuid) IS 'ERS-001 (ANN-598): den eigenen Antrag zurückziehen, solange er beantragt ist. Er bleibt ein Jahr sichtbar (erstattung_kurz).';

CREATE FUNCTION public.withdraw_time_account_entry(p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org     uuid;
  v_eintrag record;
begin
  v_org := app.staff_request_org(app.can_keep_time_account(), 'not allowed to keep a time account');
  select e.id, e.staff_member_id, e.kind, e.on_date, e.starts_at, o.time_zone into v_eintrag
  from public.staff_time_account_entries e
  join public.organizations o on o.id = e.organization_id
  where e.id = p_entry_id
    and e.organization_id = v_org
    and e.status = 'valid'
    and e.entered_by = auth.uid()
    -- Wer für andere gebucht hat, nimmt das nur zurück, solange er es noch
    -- darf (Zweitreview B5).
    and (not (e.entered_for_other or e.kind = 'correction') or app.can_book_time_accounts())
  for update of e;
  if not found then
    raise exception 'time account entry not found' using errcode = 'P0002';
  end if;
  -- Genommene Zeit holt niemand zurück (ANN-594): Hat die freie Zeit
  -- begonnen, bleibt der Freizeitausgleich stehen.
  if v_eintrag.kind = 'time_off'
     and app.time_off_started(v_eintrag.on_date, v_eintrag.starts_at, v_eintrag.time_zone, now()) then
    raise exception 'time off has begun' using errcode = '55000';
  end if;
  perform 1 from public.staff_members sm where sm.id = v_eintrag.staff_member_id for no key update;
  update public.staff_time_account_entries
     set status = 'withdrawn', withdrawn_at = now()
   where id = v_eintrag.id;
  delete from public.staff_working_hour_exceptions e where e.time_account_entry_id = v_eintrag.id;
end;
$$;

COMMENT ON FUNCTION public.withdraw_time_account_entry(p_entry_id uuid) IS 'ZK-001 (ANN-594), BEF-180: die eigene Eingabe zurücknehmen, solange sie gilt; einen Freizeitausgleich, bis seine freie Zeit beginnt (auch am Tag selbst, sonst 55000), eine Buchung für andere oder eine Korrektur nur mit dem Recht dazu. Fremde, entschiedene und unbekannte Einträge sind nicht zu unterscheiden.';

CREATE FUNCTION public.withdraw_training_offer(p_offer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor  uuid;
  v_org    uuid;
  v_offer  public.training_offers%rowtype;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not app.can_update_patient() then
    raise exception 'not allowed to make training offers' using errcode = '42501';
  end if;
  v_org := app.current_organization_id();

  -- Erst die Akte sperren, dann das Angebot: dieselbe Reihenfolge wie das
  -- Annehmen (KND-003), damit beide nicht gegeneinander warten.
  perform 1 from public.patients p
  join public.training_offers o on o.patient_id = p.id
  where o.id = p_offer_id and o.organization_id = v_org
  for update of p;

  select * into v_offer from public.training_offers o
  where o.id = p_offer_id and o.organization_id = v_org
  for update;
  if not found then
    raise exception 'training offer not found' using errcode = '42501';
  end if;
  -- ANN-285: dieselbe Sicht wie die Akte - eine Annahme hindert nicht und
  -- verraet sich nicht.
  if app.training_offer_practice_state(v_offer, app.training_today(v_org)) <> 'open' then
    raise exception 'training offer is not open' using errcode = '23514';
  end if;

  update public.training_offers
     set withdrawn_at = now(), withdrawn_by = v_actor
   where id = p_offer_id;
end;
$$;

COMMENT ON FUNCTION public.withdraw_training_offer(p_offer_id uuid) IS 'KND-002: ein offenes Trainingsangebot zurueckziehen (Rollen der Akte). Angenommene, abgelaufene und schon zurueckgezogene Angebote bleiben, wie sie sind.';

CREATE FUNCTION public.withdraw_treatment_basis_from_billing(p_treatment_basis_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_frei  timestamptz;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_release_treatment_basis() then
    raise exception 'not allowed to release treatment bases for billing' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();
  if v_org is null then
    raise exception 'not allowed to release treatment bases for billing' using errcode = '42501';
  end if;

  select b.billing_released_at into v_frei
  from public.treatment_bases b
  where b.id = p_treatment_basis_id
    and b.organization_id = v_org
  for update;

  if not found then
    raise exception 'treatment basis not found' using errcode = 'P0002';
  end if;

  if v_frei is null then
    raise exception 'treatment basis is not in billing' using errcode = '22023';
  end if;

  -- Eine Rechnung (Entwurf oder ausgestellt, nicht storniert) haelt die
  -- Grundlage: Was abgerechnet wird, aendert sich nicht mehr (ADR-009 Punkt 9).
  if exists (
    select 1
    from public.invoices i
    where i.treatment_basis_id = p_treatment_basis_id
      and not exists (select 1 from public.invoice_cancellations c where c.invoice_id = i.id)
  ) then
    raise exception 'treatment basis has an invoice' using errcode = '23514';
  end if;

  update public.treatment_bases
     set billing_released_at  = null,
         billing_released_by  = null,
         billing_withdrawn_at = now(),
         billing_withdrawn_by = v_actor
   where id = p_treatment_basis_id;
end;
$$;

COMMENT ON FUNCTION public.withdraw_treatment_basis_from_billing(p_treatment_basis_id uuid) IS 'B7 (BEF-157): holt eine Grundlage aus der Abrechnung zurueck, solange keine Rechnung (Entwurf oder ausgestellt, nicht storniert) sie fuehrt. Hebt die Sperre auf; Zeitpunkt und Person des Zurueckholens stehen an der Grundlage.';

CREATE FUNCTION public.withdraw_working_time_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org   uuid;
  v_staff uuid;
begin
  v_org := app.staff_request_org(app.can_request_working_time(), 'not allowed to request working time');
  v_staff := app.own_staff_member(v_org);
  update public.staff_working_time_requests r
     set status = 'withdrawn', withdrawn_at = now()
   where r.id = p_request_id
     and r.organization_id = v_org
     and r.staff_member_id = v_staff
     and r.status = 'requested';
  if not found then
    raise exception 'working time request not found' using errcode = 'P0002';
  end if;
end;
$$;

COMMENT ON FUNCTION public.withdraw_working_time_request(p_request_id uuid) IS 'AZ-001: den eigenen offenen Antrag zurueckziehen. Fremde, entschiedene und unbekannte Antraege sind nicht zu unterscheiden.';

CREATE FUNCTION public.write_service_catalog_items(p_version_id uuid, p_items jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid;
  v_org   uuid;
  v_published timestamptz;
  v_anzahl integer;
begin
  v_actor := auth.uid();
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not app.can_manage_service_catalog() then
    raise exception 'not allowed to manage the service catalog' using errcode = '42501';
  end if;

  v_org := app.current_organization_id();

  select v.published_at into v_published
  from public.service_catalog_versions v
  where v.id = p_version_id and v.organization_id = v_org;

  if not found then
    raise exception 'service catalog version not found' using errcode = '42501';
  end if;

  if v_published is not null then
    raise exception 'published service catalog version is immutable' using errcode = '23514';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'items must be an array' using errcode = '22023';
  end if;

  delete from public.service_catalog_items where catalog_version_id = p_version_id;

  insert into public.service_catalog_items (
    organization_id, catalog_version_id, sort_order, code, label,
    item_kind, remedy, unit_price_cents, currency, tax_treatment, tax_rate_permille,
    service_area, package_months, created_by
  )
  select
    v_org,
    p_version_id,
    (zeile.ordinalitaet)::smallint,
    btrim(zeile.eintrag ->> 'code'),
    btrim(zeile.eintrag ->> 'label'),
    coalesce(zeile.eintrag ->> 'item_kind', 'treatment'),
    nullif(btrim(coalesce(zeile.eintrag ->> 'remedy', '')), ''),
    (zeile.eintrag ->> 'unit_price_cents')::integer,
    'EUR',
    coalesce(zeile.eintrag ->> 'tax_treatment', 'exempt_healthcare'),
    coalesce((zeile.eintrag ->> 'tax_rate_permille')::smallint, 0::smallint),
    coalesce(zeile.eintrag ->> 'service_area', 'therapy'),
    -- ANG-005: die Laufzeit eines Trainingspakets; sonst leer.
    (zeile.eintrag ->> 'package_months')::smallint,
    v_actor
  from jsonb_array_elements(p_items) with ordinality as zeile(eintrag, ordinalitaet);

  select count(*) into v_anzahl
  from public.service_catalog_items where catalog_version_id = p_version_id;


  return v_anzahl;
end;
$$;

COMMENT ON FUNCTION public.write_service_catalog_items(p_version_id uuid, p_items jsonb) IS 'Ersetzt die Positionen eines Katalogentwurfs vollstaendig, alles oder nichts (ABR-001). Seit ABR-008 traegt jede Position ihren Leistungsbereich; ohne Angabe ist sie eine Behandlungsposition. Eine veroeffentlichte Version bleibt unveraenderlich.';

CREATE TABLE public.account_pins (
    user_id uuid NOT NULL,
    pin_hash text NOT NULL,
    set_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.account_pins IS 'App-PIN je Konto als bcrypt-Hash aus pgcrypto (ADR-025 Punkt 11, PROJECT_PRINCIPLES.md 3.4 Ausnahme). Nie im Klartext, kein direkter Zugriff; geschrieben nur ueber set_own_pin, geprueft nur ueber unlock_with_pin. Datenklasse accountdaten: faellt mit dem Konto.';

CREATE TABLE public.aftercare_subscriptions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    starts_on date NOT NULL,
    ends_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancelled_on date,
    cancelled_via text,
    cancelled_platform_access_id uuid,
    cancelled_access_kind text,
    cancelled_representative_name text,
    CONSTRAINT aftercare_subscriptions_cancellation_complete CHECK ((((cancelled_at IS NULL) AND (cancelled_on IS NULL) AND (cancelled_via IS NULL) AND (cancelled_platform_access_id IS NULL) AND (cancelled_access_kind IS NULL) AND (cancelled_representative_name IS NULL) AND (ends_on IS NULL)) OR ((cancelled_at IS NOT NULL) AND (cancelled_on IS NOT NULL) AND (cancelled_via IS NOT NULL) AND (ends_on IS NOT NULL)))),
    CONSTRAINT aftercare_subscriptions_cancelled_access_kind_check CHECK ((cancelled_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT aftercare_subscriptions_cancelled_representative_name_check CHECK (((cancelled_representative_name IS NULL) OR ((length(btrim(cancelled_representative_name)) >= 1) AND (length(btrim(cancelled_representative_name)) <= 200)))),
    CONSTRAINT aftercare_subscriptions_cancelled_via_check CHECK ((cancelled_via = ANY (ARRAY['practice'::text, 'platform'::text]))),
    CONSTRAINT aftercare_subscriptions_end_after_start CHECK (((ends_on IS NULL) OR (ends_on >= (starts_on - 1)))),
    CONSTRAINT aftercare_subscriptions_platform_origin CHECK (((cancelled_via IS DISTINCT FROM 'platform'::text) OR (cancelled_access_kind IS NOT NULL)))
);

COMMENT ON TABLE public.aftercare_subscriptions IS 'Nachsorge-Abo einer Patientin (ANG-001, PROJECT_PRINCIPLES.md 4.6 und 19, ADR-009 Punkt 21): monatlich kuendbare Leistung der Praxis im Bereich therapy, Beginn fruehestens mit dem Abschluss der Behandlung (ANN-268). Datenklasse: Abrechnungsdaten; faellt mit der Akte (on delete cascade), nachdem die Leistungen daraus geloescht sind (FK restrict). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.aftercare_subscriptions.ends_on IS 'Letzter Tag des Abos. Leer: laeuft. Gesetzt mit der Kuendigung auf das Ende des laufenden Abo-Monats (ANN-270); vor dem Beginn auf den Vortag des Beginns.';

COMMENT ON COLUMN public.aftercare_subscriptions.cancelled_on IS 'Tag, an dem die Kuendigung einging, in der Zeitzone der Praxis.';

COMMENT ON COLUMN public.aftercare_subscriptions.cancelled_via IS 'Woher die Kuendigung kam: von der Praxis eingetragen (Telefon, Brief) oder ueber den Kuendigungsknopf der Plattform (ANG-003).';

CREATE TABLE public.appointment_call_states (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    outcome text NOT NULL,
    attempts smallint DEFAULT 1 NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by uuid,
    CONSTRAINT appointment_call_states_attempts_check CHECK ((attempts BETWEEN 1 AND 99)),
    CONSTRAINT appointment_call_states_outcome_check CHECK ((outcome = ANY (ARRAY['not_reached'::text, 'voicemail'::text])))
);

COMMENT ON TABLE public.appointment_call_states IS 'Stand der Anrufliste am Termin (PRX-014): nicht erreicht oder Nachricht hinterlassen, mit Zahl der Versuche. Erreicht ist ein Mitteilungsvermerk (appointment_notifications, Weg phone). Kein direkter Zugriff. Datenklasse: anrufstand, vierzehn Tage nach dem Termin (ANN-144); faellt mit dem Termin.';

CREATE TABLE public.appointment_notifications (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    channel text NOT NULL,
    notified_at timestamp with time zone DEFAULT now() NOT NULL,
    notified_by uuid,
    CONSTRAINT appointment_notifications_channel_check CHECK ((channel = ANY (ARRAY['slip'::text, 'phone'::text, 'in_person'::text, 'email'::text])))
);

COMMENT ON TABLE public.appointment_notifications IS 'Vermerk, dass ein Termin der Patient:in mitgeteilt wurde, und auf welchem Weg (CAL-012, ANN-040). Die Anwendung versendet nichts - der Vermerk beschreibt einen Vorgang ausserhalb (B15). Gueltig nur, solange notified_at >= appointments.updated_at. Datenklasse: organisatorische Behandlungsdaten, faellt mit dem Termin.';

COMMENT ON COLUMN public.appointment_notifications.channel IS 'Weg der Mitteilung. Kein automatischer Versand: auch ''email'' heisst, dass die Praxis die Nachricht selbst geschrieben hat (B15).';

COMMENT ON COLUMN public.appointment_notifications.notified_at IS 'Zeitpunkt der Mitteilung. Liegt er VOR appointments.updated_at, ist der Vermerk ungueltig - der Termin hat sich seitdem geaendert.';

CREATE TABLE public.locations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    street text,
    house_number text,
    postal_code text,
    city text,
    lat double precision,
    lon double precision,
    geocode_precision text,
    garage_street text,
    garage_house_number text,
    garage_postal_code text,
    garage_city text,
    garage_lat double precision,
    garage_lon double precision,
    garage_geocode_precision text,
    CONSTRAINT locations_city_check CHECK (((city IS NULL) OR ((length(btrim(city)) >= 1) AND (length(btrim(city)) <= 200)))),
    CONSTRAINT locations_coordinate_check CHECK ((((lat IS NULL) AND (lon IS NULL) AND (geocode_precision IS NULL)) OR ((lat BETWEEN ('-90'::integer)::double precision AND (90)::double precision) AND (lon BETWEEN ('-180'::integer)::double precision AND (180)::double precision) AND (geocode_precision = ANY (ARRAY['address'::text, 'street'::text, 'locality'::text, 'unknown'::text])) AND (street IS NOT NULL) AND (postal_code IS NOT NULL) AND (city IS NOT NULL)))),
    CONSTRAINT locations_garage_city_check CHECK (((garage_city IS NULL) OR ((length(btrim(garage_city)) >= 1) AND (length(btrim(garage_city)) <= 200)))),
    CONSTRAINT locations_garage_coordinate_check CHECK ((((garage_lat IS NULL) AND (garage_lon IS NULL) AND (garage_geocode_precision IS NULL)) OR ((garage_lat IS NOT NULL) AND (garage_lon IS NOT NULL) AND (garage_geocode_precision IS NOT NULL) AND (garage_lat BETWEEN ('-90'::integer)::double precision AND (90)::double precision) AND (garage_lon BETWEEN ('-180'::integer)::double precision AND (180)::double precision) AND (garage_geocode_precision = ANY (ARRAY['address'::text, 'street'::text, 'locality'::text, 'unknown'::text])) AND (garage_street IS NOT NULL) AND (garage_postal_code IS NOT NULL) AND (garage_city IS NOT NULL)))),
    CONSTRAINT locations_garage_house_number_check CHECK (((garage_house_number IS NULL) OR ((length(btrim(garage_house_number)) >= 1) AND (length(btrim(garage_house_number)) <= 20)))),
    CONSTRAINT locations_garage_postal_code_check CHECK (((garage_postal_code IS NULL) OR ((length(btrim(garage_postal_code)) >= 2) AND (length(btrim(garage_postal_code)) <= 12)))),
    CONSTRAINT locations_garage_street_check CHECK (((garage_street IS NULL) OR ((length(btrim(garage_street)) >= 1) AND (length(btrim(garage_street)) <= 200)))),
    CONSTRAINT locations_house_number_check CHECK (((house_number IS NULL) OR ((length(btrim(house_number)) >= 1) AND (length(btrim(house_number)) <= 20)))),
    CONSTRAINT locations_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT locations_postal_code_check CHECK (((postal_code IS NULL) OR ((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12)))),
    CONSTRAINT locations_street_check CHECK (((street IS NULL) OR ((length(btrim(street)) >= 1) AND (length(btrim(street)) <= 200))))
);

COMMENT ON TABLE public.locations IS 'Standort einer Organisation (ADR-003). Keine Multi-Location-Fachlogik in V1 (ADR-014). Datenklasse: Stammdaten.';

COMMENT ON COLUMN public.locations.lat IS 'Startort der Tagesroute (Depot des Standorts, TOUR-001, MAP-006a). Adresse der Praxis, keine Personenadresse. Geschrieben nur von set_location_tour_start.';

COMMENT ON COLUMN public.locations.garage_street IS 'UBK-015, ANN-240: Garage (Abstellort der Raeder) - Beginn und Ende der Tour, wenn gesetzt. Adresse der Praxis, keine Personenadresse (§20). Geschrieben nur von set_location_garage/clear_location_garage.';

COMMENT ON COLUMN public.locations.garage_lat IS 'UBK-015, ANN-240: Koordinate der Garage. Verfaellt mit jeder Aenderung ihrer Adresse (ANN-016). Nie in Logs (ADR-011).';

COMMENT ON COLUMN public.locations.garage_lon IS 'UBK-015, ANN-240: siehe garage_lat.';

CREATE TABLE public.organizations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    time_zone text NOT NULL,
    appointment_grid_minutes smallint DEFAULT 5 NOT NULL,
    documentation_auto_finalize_days smallint DEFAULT 1 NOT NULL,
    travel_time_factor numeric(2,1) DEFAULT 1.5 NOT NULL,
    message_response_workdays smallint DEFAULT 2 NOT NULL,
    external_attachments_enabled boolean DEFAULT true NOT NULL,
    fleet_checkup_interval_days smallint DEFAULT 14,
    federal_state text DEFAULT 'BW'::text NOT NULL,
    electricity_cents_per_kwh smallint DEFAULT 37 NOT NULL,
    electricity_wh_per_km smallint DEFAULT 18 NOT NULL,
    electricity_km_per_hour smallint DEFAULT 6 NOT NULL,
    CONSTRAINT organizations_appointment_grid_minutes_check CHECK ((appointment_grid_minutes = ANY (ARRAY[5, 10, 15]))),
    CONSTRAINT organizations_documentation_auto_finalize_days_check CHECK ((documentation_auto_finalize_days BETWEEN 0 AND 30)),
    CONSTRAINT organizations_electricity_cents_per_kwh_check CHECK ((electricity_cents_per_kwh BETWEEN 1 AND 200)),
    CONSTRAINT organizations_electricity_km_per_hour_check CHECK ((electricity_km_per_hour BETWEEN 1 AND 30)),
    CONSTRAINT organizations_electricity_wh_per_km_check CHECK ((electricity_wh_per_km BETWEEN 1 AND 100)),
    CONSTRAINT organizations_federal_state CHECK ((federal_state = ANY (ARRAY['BW'::text, 'NW'::text]))),
    CONSTRAINT organizations_fleet_checkup_interval_days_check CHECK ((fleet_checkup_interval_days BETWEEN 1 AND 90)),
    CONSTRAINT organizations_message_response_workdays_check CHECK ((message_response_workdays BETWEEN 1 AND 10)),
    CONSTRAINT organizations_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT organizations_time_zone_check CHECK (((length(btrim(time_zone)) >= 1) AND (length(btrim(time_zone)) <= 100))),
    CONSTRAINT organizations_travel_time_factor_check CHECK ((travel_time_factor BETWEEN 1.0 AND 2.5))
);

COMMENT ON TABLE public.organizations IS 'Praxis/Organisation. V1 wird fuer genau eine Organisation betrieben (ADR-003). Datenklasse: Stammdaten, keine gesetzliche Frist.';

COMMENT ON COLUMN public.organizations.created_by IS 'auth.users.id des handelnden Accounts. Bewusst ohne FK, um Bootstrap-Zyklen zu vermeiden.';

COMMENT ON COLUMN public.organizations.time_zone IS 'IANA-Zeitzone der Praxis (z. B. Europe/Berlin). Massgeblich fuer die Auslegung von Kalendertagen und Uhrzeiten (CAL-001, ADR-014). Bewusst ohne Default: jede Organisation legt sie ausdruecklich fest.';

COMMENT ON COLUMN public.organizations.appointment_grid_minutes IS 'Minutenraster fuer den Beginn von Terminen (5, 10 oder 15). Gilt praxisweit und wird gegen Mitternacht der Praxiszeitzone gerechnet (CAL-005).';

COMMENT ON COLUMN public.organizations.documentation_auto_finalize_days IS 'Frist der automatischen Finalisierung in Kalendertagen nach dem Behandlungstag, gerechnet gegen Mitternacht der Praxiszeitzone (ADR-016 Punkt 7, ANN-008). 0 = Ende des Behandlungstages, 1 = Ende des Folgetages.';

COMMENT ON COLUMN public.organizations.travel_time_factor IS 'UBK-010, ANN-237: Faktor auf jede Fahrzeit des Kartendienstes (1,0 bis 2,5 in Schritten von 0,1; Voreinstellung 1,5). Angewendet im Browser an genau einer Stelle, bevor Anzeige und Fahrpufferpruefung rechnen.';

COMMENT ON COLUMN public.organizations.message_response_workdays IS 'KOM-001 (ANN-309): Antwort auf eine Nachricht in der Regel innerhalb so vieler Werktage (Montag bis Freitag). Steht als Zusage ueber dem Eingabefeld der Plattform und als "Antwort faellig bis" in der Praxis. Keine Benachrichtigung, keine Eskalation.';

COMMENT ON COLUMN public.organizations.external_attachments_enabled IS 'KOM-012, KOM-013 (ANN-371 Fassung 2, ADR-017 Fassung 6): ob Patient:innen und Kund:innen Fotos und Videos an Rueckfragen anhaengen koennen. Standard an, ohne Virenpruefung (Entscheidung Jannes 2026-10-15). Aus nur von Hand in der Datenbank; keine Funktion aendert ihn.';

COMMENT ON COLUMN public.organizations.fleet_checkup_interval_days IS 'FLT-009 (ANN-570): nach wie vielen Tagen ein Rad wieder einen Check-Up braucht (1 bis 90, Voreinstellung 14); null heisst keine Hinweise. Nur ein Praxiswert - wann ein Rad faellig ist, rechnet die Oberflaeche (src/features/fleet/rhythmus.ts).';

COMMENT ON COLUMN public.organizations.federal_state IS 'URL-001 (ANN-577): Bundesland der Praxis fuer die gesetzlichen Feiertage beim Zaehlen von Urlaubstagen. BW (Tuebingen) oder NW (Koeln); Voreinstellung BW.';

COMMENT ON COLUMN public.organizations.electricity_cents_per_kwh IS 'ORG-008: Strompreis für den Ladestrom in Cent je kWh (1 bis 200; Vorbelegung 37). Gesetzt nur von owner; der Antrag hält ihn fest.';

COMMENT ON COLUMN public.organizations.electricity_wh_per_km IS 'ORG-008: Verbrauch des Lastenrads bei höchster Unterstützungsstufe in Wh je km (1 bis 100; Vorbelegung 18). Gesetzt nur von owner; der Antrag hält ihn fest.';

COMMENT ON COLUMN public.organizations.electricity_km_per_hour IS 'ORG-008: Strecke je Arbeitsstunde in km, ein Pauschalwert der Praxis - kein Messwert einer Person, kein Bezug auf Touren (1 bis 30; Vorbelegung 6). Gesetzt nur von owner; der Antrag hält ihn fest.';

CREATE TABLE public.patients (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    person_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    care_started_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    care_concluded_on date,
    care_concluded_at timestamp with time zone,
    care_concluded_by uuid,
    CONSTRAINT patients_care_conclusion_after_start CHECK (((care_concluded_on IS NULL) OR (care_started_on IS NULL) OR (care_concluded_on >= care_started_on))),
    CONSTRAINT patients_care_conclusion_complete CHECK ((((care_concluded_on IS NULL) AND (care_concluded_at IS NULL) AND (care_concluded_by IS NULL)) OR ((care_concluded_on IS NOT NULL) AND (care_concluded_at IS NOT NULL) AND (care_concluded_by IS NOT NULL)))),
    CONSTRAINT patients_status_active_only CHECK ((status = 'active'::text))
);

COMMENT ON TABLE public.patients IS 'Patientenrolle einer Person. Enthaelt KEINE klinischen Inhalte. Datenklasse: klinische Patientenakte, 10 Jahre nach Behandlungsabschluss (ADR-008).';

COMMENT ON COLUMN public.patients.status IS 'Seit B1 (BEF-151, ANN-510) immer ''active'': „Nicht in Versorgung“ ist entfallen und sperrt keine Termine mehr. Die Spalte bleibt, bis die Sichten und Funktionen, die sie lesen, aufgeräumt sind.';

COMMENT ON COLUMN public.patients.care_concluded_on IS 'Tag des Abschlusses der Behandlung im Sinne von Par. 630f Abs. 3 BGB. Anker der zehnjaehrigen Aufbewahrung (ADR-008, LOE-001b). Leer bedeutet: laufende Versorgung, keine Frist. Nicht zu verwechseln mit status = inactive (ANN-002).';

COMMENT ON COLUMN public.patients.care_concluded_at IS 'Zeitpunkt, zu dem der Abschluss festgehalten wurde. Der fachliche Tag steht in care_concluded_on und darf davor liegen.';

COMMENT ON COLUMN public.patients.care_concluded_by IS 'auth.users.id der abschliessenden Person. Bewusst ohne FK (ADR-008).';

CREATE TABLE public.persons (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    given_name text NOT NULL,
    family_name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT persons_family_name_check CHECK (((length(btrim(family_name)) >= 1) AND (length(btrim(family_name)) <= 100))),
    CONSTRAINT persons_given_name_check CHECK (((length(btrim(given_name)) >= 1) AND (length(btrim(given_name)) <= 100)))
);

COMMENT ON TABLE public.persons IS 'Identitaetskern einer natuerlichen Person: ausschliesslich Name. Kontakt-, Adress- und Geburtsdaten liegen kontextbezogen in patient_contact_details bzw. staff_private_details.';

CREATE TABLE public.staff_members (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    person_id uuid NOT NULL,
    primary_location_id uuid,
    employment_status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    work_email text,
    work_phone text,
    schedulable_treatment boolean DEFAULT false NOT NULL,
    schedulable_training boolean DEFAULT false NOT NULL,
    CONSTRAINT staff_members_employment_status_check CHECK ((employment_status = ANY (ARRAY['active'::text, 'inactive'::text]))),
    CONSTRAINT staff_members_work_email_check CHECK (((work_email IS NULL) OR (work_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT staff_members_work_phone_check CHECK (((work_phone IS NULL) OR ((length(btrim(work_phone)) >= 3) AND (length(btrim(work_phone)) <= 40))))
);

COMMENT ON TABLE public.staff_members IS 'Beschaeftigtenrolle einer Person. Beschaeftigtendaten unterliegen zusaetzlich PROJECT_PRINCIPLES.md 20. Datenklasse: Beschaeftigtenstammdaten.';

COMMENT ON COLUMN public.staff_members.work_email IS 'Dienstliche Erreichbarkeit. Fuer Praxisrollen sichtbar - im Unterschied zu staff_private_details.';

COMMENT ON COLUMN public.staff_members.schedulable_treatment IS 'Steht im Kalender fuer Behandlungen, auch ohne eigenen Zugang (AKTE-009, ANN-226). Setzt allein owner ueber set_staff_member_schedulable.';

COMMENT ON COLUMN public.staff_members.schedulable_training IS 'Steht im Kalender fuer Personal Training, auch ohne eigenen Zugang (AKTE-009, ANN-226). Setzt allein owner ueber set_staff_member_schedulable.';

-- ANN-063
CREATE VIEW public.appointment_directory WITH (security_invoker='true') AS
 SELECT a.id,
    a.organization_id,
    a.patient_id,
    a.staff_member_id,
    a.location_id,
    a.treatment_basis_id,
    a.appointment_type,
    a.kind,
    a.title,
    a.event_group_id,
    a.event_series_id,
    a.status,
    a.starts_at,
    a.ends_at,
    a.updated_at,
    a.visit_street,
    a.visit_house_number,
    a.visit_postal_code,
    a.visit_city,
    a.completed_at,
    a.cancellation_reason,
    a.cancellation_received_at,
    a.fee_basis,
    a.no_show_recorded_at,
    a.no_show_protocol_confirmed,
    pp.given_name AS patient_given_name,
    pp.family_name AS patient_family_name,
    sp.given_name AS staff_given_name,
    sp.family_name AS staff_family_name,
    l.name AS location_name,
    o.time_zone AS organization_time_zone,
    COALESCE(( SELECT array_agg(DISTINCT n.channel ORDER BY n.channel) AS array_agg
           FROM public.appointment_notifications n
          WHERE ((n.appointment_id = a.id) AND (n.notified_at >= a.patient_relevant_changed_at))), ARRAY[]::text[]) AS notification_channels,
    app.appointment_is_covered(a.id) AS treatment_basis_covered,
    a.fee_waived_at,
    a.occasion
   FROM ((((((public.appointments a
     LEFT JOIN public.patients p ON ((p.id = a.patient_id)))
     LEFT JOIN public.persons pp ON ((pp.id = p.person_id)))
     JOIN public.staff_members sm ON ((sm.id = a.staff_member_id)))
     JOIN public.persons sp ON ((sp.id = sm.person_id)))
     JOIN public.organizations o ON ((o.id = a.organization_id)))
     LEFT JOIN public.locations l ON ((l.id = a.location_id)));

COMMENT ON VIEW public.appointment_directory IS 'Terminsicht fuer die Anwendung, Behandlungen wie Ereignisse. security_invoker: RLS der Basistabellen gilt unveraendert. Enthaelt nur organisatorische Angaben. Die vermerkende Person bleibt aussen vor - Akteure stehen im Auditlog (ADR-010). Seit CAL-017 mit der Gruppenkennung des Ereignisses, seit CAL-018 mit der Protokollbestaetigung des Nichtantreffens, seit CAL-021 mit der Serienkennung der Dauerfehlzeit, seit GRD-001 mit der Behandlungsgrundlage statt der Verordnung, seit CAL-022 mit ihrer Deckung (null: keine Grundlage oder abgesagt), seit ABN-003 gilt der Mitteilungsvermerk bis zur naechsten fuer die Patient:in relevanten Aenderung, seit ABN-006 mit dem Zeitpunkt eines Gebuehrenverzichts.';

CREATE TABLE public.appointment_session_fees (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    source text NOT NULL,
    fee_agreement_id uuid,
    catalog_version_id uuid NOT NULL,
    performed_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT appointment_session_fees_amount_cents_check CHECK ((amount_cents BETWEEN 0 AND 1000000)),
    CONSTRAINT appointment_session_fees_currency_check CHECK ((currency = 'EUR'::text)),
    CONSTRAINT appointment_session_fees_source_check CHECK ((source = ANY (ARRAY['agreement'::text, 'tariff'::text]))),
    CONSTRAINT appointment_session_fees_source_matches CHECK (((source = 'agreement'::text) = (fee_agreement_id IS NOT NULL)))
);

COMMENT ON TABLE public.appointment_session_fees IS 'Das Terminhonorar eines Behandlungstermins (ABR-031, ADR-009 Punkt 22, ANN-232): genau ein Eintrag je Termin, mit dem Betrag, der am Leistungstag galt, festgeschrieben beim Bestaetigen der Heilmittel. Unveraenderlich. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Nur ueber Funktionen erreichbar.';

COMMENT ON COLUMN public.appointment_session_fees.source IS 'agreement = Honorarvereinbarung mit der Person (fee_agreement_id), tariff = allgemeiner Tarif der Preisliste (catalog_version_id). Nachweis, woher der Betrag kam.';

COMMENT ON COLUMN public.appointment_session_fees.catalog_version_id IS 'Die am Leistungstag gueltige Preisliste. Ihre Heilmittelpreise sind die Gewichte der Aufteilung auf der Rechnung (ANN-233), auch wenn der Betrag aus einer Vereinbarung kommt.';

CREATE TABLE public.audit_log (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    actor_user_id uuid,
    action text NOT NULL,
    subject_type text NOT NULL,
    subject_id uuid NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    context jsonb DEFAULT '{}'::jsonb NOT NULL,
    outcome text DEFAULT 'success'::text NOT NULL,
    actor_kind text DEFAULT 'user'::text NOT NULL,
    CONSTRAINT audit_log_action_check CHECK ((action = ANY (ARRAY['patient_record.viewed'::text, 'training_relationship.viewed'::text, 'patient_file.downloaded'::text, 'patient_record.exported'::text, 'therapy_report.exported'::text, 'patient_file.handed_out'::text, 'message_attachment.handed_out'::text, 'platform_representation.read'::text, 'platform_access.invited'::text, 'platform_access.activated'::text, 'platform_access.locked'::text, 'platform_access.unlocked'::text, 'platform_access.revoked'::text, 'staff_account.invited'::text, 'staff_account.invitation_revoked'::text, 'staff_account.invitation_accepted'::text, 'staff_account.roles_changed'::text, 'staff_account.locked'::text, 'staff_account.unlocked'::text, 'staff_account.password_reset_requested'::text, 'account.password_changed'::text, 'account.sessions_ended'::text, 'account.mfa_enrolled'::text, 'account.mfa_removed'::text, 'organization.bootstrapped'::text, 'access.denied'::text, 'retention.applied'::text]))),
    CONSTRAINT audit_log_actor_consistent CHECK (((actor_kind = ANY (ARRAY['user'::text, 'platform'::text, 'representative'::text])) = (actor_user_id IS NOT NULL))),
    CONSTRAINT audit_log_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['user'::text, 'system'::text, 'platform'::text, 'representative'::text]))),
    CONSTRAINT audit_log_outcome_check CHECK ((outcome = ANY (ARRAY['success'::text, 'denied'::text]))),
    CONSTRAINT audit_log_subject_type_check CHECK ((subject_type = ANY (ARRAY['patient'::text, 'training_relationship'::text, 'patient_file'::text, 'platform_message_attachment'::text, 'therapy_report'::text, 'platform_access'::text, 'staff_member'::text, 'user_account'::text, 'organization'::text])))
);

COMMENT ON TABLE public.audit_log IS 'Auditnachweis sensibler Zugriffe (ADR-010). Enthaelt ausschliesslich Metadaten. Datenklasse: Patientenakten-Auditlog, initial 3 Jahre (ADR-008).';

COMMENT ON COLUMN public.audit_log.actor_user_id IS 'auth.users.id des handelnden Accounts; leer nur bei actor_kind = system. Bewusst ohne FK, damit ein spaeter geloeschter Account den Nachweis nicht entfernt (ADR-008).';

COMMENT ON COLUMN public.audit_log.context IS 'Zusaetzliche Metadaten. Es duerfen KEINE klinischen Inhalte und keine Freitexte aus der Akte abgelegt werden.';

COMMENT ON COLUMN public.audit_log.outcome IS 'Ergebnis des protokollierten Vorgangs. denied schreiben list_audit_events, list_deletion_runs (OPS-004) und die fuenf Lesepfade auf klinische Dokumente (G6a); die uebrigen Abweisungen rollen ihren Eintrag weiter mit zurueck (ROADMAP G6b).';

COMMENT ON COLUMN public.audit_log.actor_kind IS 'user: Praxiskonto; platform: Plattformkonto der Person selbst; representative: Plattformkonto, das ueber einen Vertretungszugang handelt (ADR-023 Punkt 14, POR-005); system: Loeschlauf und andere Vorgaenge ohne Person.';

CREATE TABLE public.billable_services (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid,
    appointment_id uuid,
    catalog_item_id uuid NOT NULL,
    treatment_base_item_id uuid,
    quantity smallint DEFAULT 1 NOT NULL,
    performed_on date NOT NULL,
    status text DEFAULT 'billable'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    service_area text NOT NULL,
    training_relationship_id uuid,
    aftercare_subscription_id uuid,
    training_package_id uuid,
    CONSTRAINT billable_services_party CHECK ((((service_area = 'therapy'::text) AND (patient_id IS NOT NULL) AND (training_relationship_id IS NULL)) OR ((service_area = 'training'::text) AND (training_relationship_id IS NOT NULL) AND (patient_id IS NULL)))),
    CONSTRAINT billable_services_quantity_check CHECK ((quantity BETWEEN 1 AND 10)),
    CONSTRAINT billable_services_source CHECK ((((appointment_id IS NOT NULL) AND (aftercare_subscription_id IS NULL) AND (training_package_id IS NULL)) OR ((appointment_id IS NULL) AND (aftercare_subscription_id IS NOT NULL) AND (training_package_id IS NULL) AND (service_area = 'therapy'::text) AND (patient_id IS NOT NULL) AND (quantity = 1)) OR ((appointment_id IS NULL) AND (aftercare_subscription_id IS NULL) AND (training_package_id IS NOT NULL) AND (service_area = 'training'::text) AND (training_relationship_id IS NOT NULL) AND (quantity = 1)))),
    CONSTRAINT billable_services_status_check CHECK ((status = ANY (ARRAY['billable'::text, 'invoiced'::text])))
);

COMMENT ON TABLE public.billable_services IS 'Abrechenbare Leistung aus einem Termin (ABR-002, ADR-009 Punkt 3). Enthaelt einen Patientenbezug und damit Gesundheitsdaten im weiteren Sinn; Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008, ADR-009). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen dieser Migration (ADR-004).';

COMMENT ON COLUMN public.billable_services.treatment_base_item_id IS 'Position der Behandlungsgrundlage, deren genutzte Menge diese Leistung erhoeht hat (ANN-073). null heisst: keine - etwa beim Ausfallhonorar oder bei einem Termin ohne Grundlage.';

COMMENT ON COLUMN public.billable_services.performed_on IS 'Leistungstag in der Zeitzone der Organisation. Er entscheidet, welche Preisliste gilt - nicht der Tag der Erfassung (ADR-009 Punkt 5).';

COMMENT ON COLUMN public.billable_services.status IS 'Eigener Abrechnungsstand der Leistung (ADR-009 Punkt 3). "invoiced" steht im Wertebereich, hat aber heute keinen Schreiber: Die Rechnungsausstellung setzt ihn in derselben Transaktion (ABR-003). Nichts wird dafuer prophylaktisch gebaut (ADR-014).';

COMMENT ON COLUMN public.billable_services.service_area IS 'Leistungsbereich dieser Leistung (ADR-009 Punkt 16). Abgeleitet aus der Katalogposition, nicht eingegeben: Der Trigger setzt ihn, der zusammengesetzte Fremdschluessel haelt ihn. Er steht hier und nicht nur am Join, weil die Rechnung ihre Invariante ueber ihn traegt (ABR-009).';

COMMENT ON COLUMN public.billable_services.training_relationship_id IS 'Das Trainingsverhaeltnis, fuer das die Leistung erbracht wurde (TRN-007, ADR-021 Punkt 5). Gesetzt genau im Bereich training; patient_id ist dann leer. Kein Weg fuehrt von hier in die Akte.';

COMMENT ON COLUMN public.billable_services.aftercare_subscription_id IS 'ANG-002: das Nachsorge-Abo, aus dem diese Leistung als Abo-Monat entstanden ist (ADR-009 Punkt 21). Dann ohne Termin; performed_on ist der erste Tag des Abo-Monats.';

COMMENT ON COLUMN public.billable_services.training_package_id IS 'ANG-006: das Trainingspaket, aus dem diese Leistung entstanden ist (ADR-009 Punkt 21). Dann ohne Termin; performed_on ist der Beginn des Pakets.';

COMMENT ON CONSTRAINT billable_services_party ON public.billable_services IS 'Eine Leistung haengt an genau einem Verhaeltnis, und zwar an dem ihres Bereichs: Behandlung an patients, Training an training_relationships (ADR-021 Punkt 3, ADR-022 Punkt 3). Eine Trainingsleistung mit Patientenbezug ist schemaseitig unmoeglich.';

COMMENT ON CONSTRAINT billable_services_source ON public.billable_services IS 'ANG-002, ANG-006: Eine Leistung entsteht an einem Termin, als Abo-Monat aus einem Nachsorge-Abo oder als Trainingspaket - aus genau einer Quelle.';

CREATE TABLE public.checkin_values (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    checkin_id uuid NOT NULL,
    parameter_key text NOT NULL,
    value smallint NOT NULL,
    CONSTRAINT checkin_values_valid CHECK (app.tracking_value_valid(parameter_key, 'checkin'::text, (value)::integer))
);

COMMENT ON TABLE public.checkin_values IS 'TRK-002: die Angaben eines Check-ins, je Groesse eine Zeile, unveraendert (ANN-348). Faellt mit dem Check-in. Kein Tabellenrecht (ADR-004).';

CREATE TABLE public.checkins (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    answered_on date NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    recorded_by uuid NOT NULL,
    CONSTRAINT checkins_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT checkins_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT checkins_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND (patient_id = relationship_id)) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id = relationship_id))))
);

COMMENT ON TABLE public.checkins IS 'TRK-002: ein beantworteter Check-in eines Verhaeltnisses, von der Person oder ihrer rechtlichen Vertretung (TRK-003). Datenklasse des Verhaeltnisses; faellt mit ihm. Kein Alarm, keine Bewertung (DSN-001 D5, ADR-006 Punkt 11). Kein Tabellenrecht (ADR-004).';

CREATE TABLE public.deletion_journal (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    run_id uuid NOT NULL,
    target_table text NOT NULL,
    target_id uuid NOT NULL,
    retention_class text NOT NULL,
    due_at timestamp with time zone NOT NULL,
    deleted_at timestamp with time zone DEFAULT now() NOT NULL,
    reapplied_at timestamp with time zone,
    CONSTRAINT deletion_journal_target_table_check CHECK ((target_table ~ '^[a-z_]+$'::text))
);

COMMENT ON TABLE public.deletion_journal IS 'Nachweis wirksam gewordener Loeschungen (ADR-008 Punkt 8, LOE-002a). Traegt Tabelle, Kennung, Datenklasse und Zeitpunkt - keinen Namen, keinen Inhalt. Datenklasse: Loeschjournal, ohne eigene Frist (ANN-031). Muss den Restore ueberleben: das Verfahren dazu steht in ANN-031 und gehoert zu OPS-003.';

COMMENT ON COLUMN public.deletion_journal.due_at IS 'Zeitpunkt, zu dem die Frist abgelaufen war. Macht nachpruefbar, dass nicht zu frueh geloescht wurde.';

COMMENT ON COLUMN public.deletion_journal.reapplied_at IS 'Wann diese Loeschung zuletzt nach einer Wiederherstellung erneut angewendet werden musste (ADR-008 Punkt 8). Leer bedeutet: bisher nicht noetig.';

CREATE TABLE public.exercise_plan_days (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    weekdays smallint[] NOT NULL,
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    recorded_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT exercise_plan_days_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT exercise_plan_days_weekdays CHECK (((cardinality(weekdays) <= 7) AND (weekdays <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint])))
);

COMMENT ON TABLE public.exercise_plan_days IS 'UEB-011: die Wochentage, an denen die Person einen Plan ueben moechte (IDEA-ORG-004, ANN-307). Ihre eigene Planung, nicht die der Praxis: Die Praxis liest sie nicht; nur die Auskunft nach Art. 15 nennt sie. Datenklasse wie der Plan; faellt mit ihm. Kein Tabellenrecht (ADR-004).';

CREATE TABLE public.exercise_plan_session_sets (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    item_id uuid NOT NULL,
    set_number smallint NOT NULL,
    done_at timestamp with time zone DEFAULT now() NOT NULL,
    reported_done_at timestamp with time zone,
    CONSTRAINT exercise_plan_session_sets_set_number_check CHECK ((set_number BETWEEN 1 AND 20))
);

COMMENT ON TABLE public.exercise_plan_session_sets IS 'UEB-010: ein abgehakter Satz einer Uebung in einer Einheit. Gespeichert mit dem Haken, nicht erst am Ende (ANN-305). Datenklasse wie die Einheit; faellt mit ihr. Kein Tabellenrecht (ADR-004).';

COMMENT ON COLUMN public.exercise_plan_session_sets.reported_done_at IS 'TRK-007 (ADR-024 Punkt 8): Zeitpunkt des Hakens nach der Uhr des Geraets bei einer uebertragenen Einheit. done_at ist der Eingang am Server. Datenklasse und Frist wie die Einheit.';

CREATE TABLE public.exercise_plan_session_values (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    session_id uuid NOT NULL,
    parameter_key text NOT NULL,
    value smallint NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT exercise_plan_session_values_valid CHECK (app.tracking_value_valid(parameter_key, 'session'::text, (value)::integer))
);

COMMENT ON TABLE public.exercise_plan_session_values IS 'TRK-001: Angaben der Person zu einer beendeten Einheit (Takt session, ANN-348) - Anstrengung und Schmerz, je 0 bis 10, freiwillig. Datenklasse wie die Einheit; faellt mit ihr. Geschrieben nur ueber finish_platform_exercise_session. Kein Tabellenrecht (ADR-004).';

CREATE TABLE public.exercise_plan_template_items (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    template_id uuid NOT NULL,
    "position" smallint NOT NULL,
    variant_id uuid NOT NULL,
    sets smallint NOT NULL,
    reps_min smallint,
    reps_max smallint,
    duration_seconds smallint,
    hold_seconds smallint,
    per_side boolean DEFAULT false NOT NULL,
    times_per_day smallint,
    load text,
    tempo text,
    rest_seconds smallint,
    double_progression boolean DEFAULT false NOT NULL,
    CONSTRAINT exercise_plan_template_items_double_progression CHECK (((NOT double_progression) OR ((reps_max > reps_min) AND (load IS NOT NULL)))),
    CONSTRAINT exercise_plan_template_items_duration_seconds_check CHECK ((duration_seconds BETWEEN 1 AND 3600)),
    CONSTRAINT exercise_plan_template_items_hold CHECK (((hold_seconds IS NULL) OR (reps_min IS NOT NULL))),
    CONSTRAINT exercise_plan_template_items_hold_seconds_check CHECK ((hold_seconds BETWEEN 1 AND 600)),
    CONSTRAINT exercise_plan_template_items_load_check CHECK (((load IS NULL) OR ((length(btrim(load, E' \t\r\n'::text)) >= 1) AND (length(btrim(load, E' \t\r\n'::text)) <= 40)))),
    CONSTRAINT exercise_plan_template_items_position_check CHECK (("position" BETWEEN 1 AND 30)),
    CONSTRAINT exercise_plan_template_items_reps CHECK ((((reps_min IS NULL) = (reps_max IS NULL)) AND ((reps_max IS NULL) OR (reps_max >= reps_min)))),
    CONSTRAINT exercise_plan_template_items_reps_max_check CHECK ((reps_max BETWEEN 1 AND 100)),
    CONSTRAINT exercise_plan_template_items_reps_min_check CHECK ((reps_min BETWEEN 1 AND 100)),
    CONSTRAINT exercise_plan_template_items_reps_or_duration CHECK (((reps_min IS NULL) <> (duration_seconds IS NULL))),
    CONSTRAINT exercise_plan_template_items_rest_seconds_check CHECK ((rest_seconds BETWEEN 0 AND 600)),
    CONSTRAINT exercise_plan_template_items_sets_check CHECK ((sets BETWEEN 1 AND 20)),
    CONSTRAINT exercise_plan_template_items_tempo_check CHECK (((tempo IS NULL) OR ((length(btrim(tempo, E' \t\r\n'::text)) >= 1) AND (length(btrim(tempo, E' \t\r\n'::text)) <= 40)))),
    CONSTRAINT exercise_plan_template_items_times_per_day_check CHECK ((times_per_day BETWEEN 1 AND 10))
);

COMMENT ON TABLE public.exercise_plan_template_items IS 'UEB-014 (ANN-560): die Uebungen einer Vorlage der Praxis mit Dosierung, ohne Notiz und ohne Schnappschuss. Datenklasse: Betriebsdaten der Praxis OHNE Patientenbezug. Frist: faellt mit ihrer Vorlage oder ihrer Variante (on delete cascade). Kein Tabellenrecht und keine Policy (ADR-004).';

CREATE TABLE public.exercise_plan_templates (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    goal text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT exercise_plan_templates_goal_check CHECK (((goal IS NULL) OR ((length(btrim(goal, E' \t\r\n'::text)) >= 1) AND (length(btrim(goal, E' \t\r\n'::text)) <= 200)))),
    CONSTRAINT exercise_plan_templates_name_check CHECK (((length(btrim(name, E' \t\r\n'::text)) >= 1) AND (length(btrim(name, E' \t\r\n'::text)) <= 80)))
);

COMMENT ON TABLE public.exercise_plan_templates IS 'UEB-014 (ANN-560): Vorlage der Praxis fuer Uebungsplaene - Name und Ziel, die Uebungen in exercise_plan_template_items. Fachwissen ohne Patientenbezug wie die Bibliothek (ANN-292), fuer Behandlung und Training. Datenklasse: Betriebsdaten der Praxis OHNE Patientenbezug, keine Gesundheitsdaten; wer angelegt und geaendert hat, ist ein Beschaeftigtendatum wie an der Bibliothek. Frist: bis zur Loeschung durch die Praxis. Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.exercise_plan_templates.name IS 'Name nach Region und Ziel (ANN-560), nie nach Person oder Diagnose; die Liste sortiert danach und nach nichts sonst (ADR-006 Punkt 10).';

CREATE TABLE public.exercise_variant_links (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    easier_variant_id uuid NOT NULL,
    harder_variant_id uuid NOT NULL,
    axis text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    CONSTRAINT exercise_variant_links_axis_check CHECK ((axis = ANY (app.exercise_axes()))),
    CONSTRAINT exercise_variant_links_not_self CHECK ((easier_variant_id <> harder_variant_id))
);

COMMENT ON TABLE public.exercise_variant_links IS 'UEB-002: gerichtete Verbindung zweier Varianten der Uebungsbibliothek - von der leichteren zur schwereren, entlang genau einer Achse (IDEA-TRN-004, IDEA-TRN-005, ANN-294). Wird nur angezeigt, nie zur Auswahl benutzt (ADR-006 Punkt 10). Datenklasse: Betriebsdaten der Praxis OHNE Personenbezug. Frist: bis die Praxis die Verbindung loest. Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.exercise_variant_links.axis IS 'Die eine Achse, in der sich die beiden Varianten unterscheiden (app.exercise_axes(), ANN-294).';

CREATE TABLE public.exercise_variants (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    exercise_id uuid NOT NULL,
    name text NOT NULL,
    lay_name text NOT NULL,
    instruction text,
    equipment text[] DEFAULT '{}'::text[] NOT NULL,
    common_faults text,
    practice_notes text,
    archived_at timestamp with time zone,
    archived_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    catalog_key text,
    catalog_version text,
    goal text,
    starting_position text,
    level smallint,
    default_dosage jsonb,
    illustration jsonb,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    CONSTRAINT exercise_variants_archived_stamp CHECK (((archived_at IS NULL) = (archived_by IS NULL))),
    CONSTRAINT exercise_variants_catalog_key_check CHECK (((catalog_key IS NULL) OR (catalog_key ~ '^[A-Z]{2}-[0-9]{2}$'::text))),
    CONSTRAINT exercise_variants_catalog_origin CHECK (((catalog_key IS NULL) = (catalog_version IS NULL))),
    CONSTRAINT exercise_variants_catalog_version_check CHECK (((catalog_version IS NULL) OR (catalog_version ~ '^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$'::text))),
    CONSTRAINT exercise_variants_common_faults_check CHECK (((common_faults IS NULL) OR ((length(btrim(common_faults, E' \t\r\n'::text)) >= 1) AND (length(btrim(common_faults, E' \t\r\n'::text)) <= 1000)))),
    CONSTRAINT exercise_variants_default_dosage_check CHECK (app.exercise_dosage_valid(default_dosage)),
    CONSTRAINT exercise_variants_equipment_check CHECK ((cardinality(equipment) <= 8)),
    CONSTRAINT exercise_variants_goal_check CHECK (((goal IS NULL) OR (goal = ANY (app.exercise_goals())))),
    CONSTRAINT exercise_variants_illustration_check CHECK (app.exercise_illustration_valid(illustration)),
    CONSTRAINT exercise_variants_instruction_check CHECK (((instruction IS NULL) OR ((length(btrim(instruction, E' \t\r\n'::text)) >= 1) AND (length(btrim(instruction, E' \t\r\n'::text)) <= 1000)))),
    CONSTRAINT exercise_variants_lay_name_check CHECK (((length(btrim(lay_name)) >= 1) AND (length(btrim(lay_name)) <= 120))),
    CONSTRAINT exercise_variants_level_check CHECK ((level BETWEEN 1 AND 3)),
    CONSTRAINT exercise_variants_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT exercise_variants_practice_notes_check CHECK (((practice_notes IS NULL) OR ((length(btrim(practice_notes, E' \t\r\n'::text)) >= 1) AND (length(btrim(practice_notes, E' \t\r\n'::text)) <= 1000)))),
    CONSTRAINT exercise_variants_reviewed_stamp CHECK (((reviewed_at IS NULL) = (reviewed_by IS NULL))),
    CONSTRAINT exercise_variants_starting_position_check CHECK (((starting_position IS NULL) OR (starting_position = ANY (app.exercise_starting_positions()))))
);

COMMENT ON TABLE public.exercise_variants IS 'UEB-001: Variante einer Uebung (IDEA-TRN-005) - die Form, in der geuebt wird. Fachlich und alltagssprachlich benannt (IDEA-QSN-002), mit Kurzanleitung, Ausruestung, Ausweichbewegungen und Hinweisen fuer die Praxis. Datenklasse: Betriebsdaten der Praxis OHNE Personenbezug. Frist: bis zur Loeschung durch die Praxis (ANN-296). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.exercise_variants.instruction IS 'Kurzanleitung in Alltagssprache (IDEA-QSN-002). Freitext, der nie in Logs erscheint (ADR-011).';

COMMENT ON COLUMN public.exercise_variants.equipment IS 'Ausruestung als freie Schlagworte (ANN-295), hoechstens acht, je hoechstens 40 Zeichen.';

COMMENT ON COLUMN public.exercise_variants.practice_notes IS 'Hinweise fuer die Praxis (Vorsicht, Abgrenzung). Nur zum Nachlesen - keine Funktion gleicht sie mit Diagnose, Befund oder Verlauf ab (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercise_variants.catalog_key IS 'UEB-012 (ANN-382): Herkunft aus dem mitgelieferten Katalog (KN-01 ...); leer bei eigenen Uebungen. Je Praxis hoechstens einmal - ein spaeterer Import ueberspringt sie und ueberschreibt nichts.';

COMMENT ON COLUMN public.exercise_variants.catalog_version IS 'UEB-012 (ANN-382): Fassung des Katalogeintrags bei der Uebernahme (semver).';

COMMENT ON COLUMN public.exercise_variants.goal IS 'UEB-012 (ANN-383): Ziel aus app.exercise_goals() - zum Suchen, nie aus Angaben einer Person vorbelegt (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercise_variants.starting_position IS 'UEB-012 (ANN-383): Ausgangsstellung aus app.exercise_starting_positions() - zum Suchen, keine Auswahl (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercise_variants.level IS 'UEB-012 (ANN-383): Niveau 1 bis 3 des Katalogs - zum Suchen, fuer alle gleich, nie aus Angaben einer Person abgeleitet (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercise_variants.default_dosage IS 'UEB-012 (ANN-384): Standarddosierung des Katalogs in der Form der Planposition. Fuer alle gleich, nie aus Angaben einer Person abgeleitet (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercise_variants.illustration IS 'UEB-012 (ANN-381): Posen-Beschreibung des Uebungsbilds (jsonb, Fassung 1, hoechstens 4096 Byte) - keine Datei (ADR-017 Punkt 4).';

COMMENT ON COLUMN public.exercise_variants.reviewed_at IS 'UEB-012 (ANN-386): Pruefvermerk - die Praxis hat Text, Dosierung und Bild fachlich durchgesehen. Ohne Vermerk gilt eine uebernommene Variante als ungeprueft; das blockiert nur das Scharfschalten (PROJECT_PRINCIPLES.md 15.2). Faellt, sobald sich der Inhalt aendert (save_exercise_variant).';

COMMENT ON COLUMN public.exercise_variants.reviewed_by IS 'UEB-012 (ANN-386): wer den Pruefvermerk gesetzt hat (owner, set_exercise_variant_reviewed); nur zusammen mit reviewed_at. Nachweis an der Zeile statt Auditaktion (ADR-010 Fassung 3).';

CREATE TABLE public.exercises (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    lay_name text NOT NULL,
    body_region text NOT NULL,
    archived_at timestamp with time zone,
    archived_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT exercises_archived_stamp CHECK (((archived_at IS NULL) = (archived_by IS NULL))),
    CONSTRAINT exercises_body_region_check CHECK ((body_region = ANY (app.exercise_body_regions()))),
    CONSTRAINT exercises_lay_name_check CHECK (((length(btrim(lay_name)) >= 1) AND (length(btrim(lay_name)) <= 120))),
    CONSTRAINT exercises_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120)))
);

COMMENT ON TABLE public.exercises IS 'UEB-001: Uebung der Bibliothek (IDEA-TRN-005) mit fachlicher und alltagssprachlicher Bezeichnung (IDEA-QSN-002). Eine Bibliothek fuer Behandlung und Training (ANN-292). Datenklasse: Betriebsdaten der Praxis OHNE Personenbezug, keine Gesundheitsdaten. Frist: bis zur Loeschung durch die Praxis (ANN-296). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.exercises.lay_name IS 'Bezeichnung in Alltagssprache (IDEA-QSN-002): was Patient:innen und Kund:innen lesen.';

COMMENT ON COLUMN public.exercises.body_region IS 'Koerperregion aus app.exercise_body_regions() (ANN-295). Fuer Suche und Filter, nie fuer eine Auswahl aus klinischen Angaben (ADR-006 Punkt 10).';

COMMENT ON COLUMN public.exercises.archived_at IS 'Archiviert statt geloescht (ANN-296): erscheint nicht mehr in der Bibliothek, bleibt aber nachlesbar.';

CREATE TABLE public.fleet_blocks (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bike_id uuid NOT NULL,
    breakdown_id uuid,
    reason text,
    blocked_at timestamp with time zone DEFAULT now() NOT NULL,
    blocked_by uuid NOT NULL,
    released_at timestamp with time zone,
    released_by uuid,
    CONSTRAINT fleet_blocks_order CHECK (((released_at IS NULL) OR (released_at >= blocked_at))),
    CONSTRAINT fleet_blocks_reason_check CHECK (((reason IS NULL) OR ((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 200)))),
    CONSTRAINT fleet_blocks_released_stamp CHECK (((released_at IS NULL) = (released_by IS NULL)))
);

COMMENT ON TABLE public.fleet_blocks IS 'FLT-001: Sperre eines Rads ("In Reparatur") aus einer Panne oder von Hand, bis zur Freigabe (owner, team_lead; ANN-550). Datenklasse radflotte_ereignis: drei Jahre ab Ende des Kalenderjahres der Freigabe; offene nie (ANN-551). Kein Tabellenrecht.';

CREATE TABLE public.fleet_breakdowns (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bike_id uuid NOT NULL,
    outcome text NOT NULL,
    summary text NOT NULL,
    remark text,
    location_note text,
    transport text,
    reported_at timestamp with time zone DEFAULT now() NOT NULL,
    reported_by uuid NOT NULL,
    CONSTRAINT fleet_breakdowns_location_note_check CHECK (((location_note IS NULL) OR ((length(btrim(location_note)) >= 1) AND (length(btrim(location_note)) <= 200)))),
    CONSTRAINT fleet_breakdowns_outcome_check CHECK ((outcome = ANY (app.fleet_breakdown_outcomes()))),
    CONSTRAINT fleet_breakdowns_remark_check CHECK (((remark IS NULL) OR ((length(btrim(remark)) >= 1) AND (length(btrim(remark)) <= 1000)))),
    CONSTRAINT fleet_breakdowns_summary_check CHECK (((length(btrim(summary)) >= 1) AND (length(btrim(summary)) <= 1000))),
    CONSTRAINT fleet_breakdowns_transport_check CHECK (((transport IS NULL) OR (transport = ANY (ARRAY['carsharing'::text, 'fahrdienst'::text]))))
);

COMMENT ON TABLE public.fleet_breakdowns IS 'FLT-001: Pannenmeldung aus dem Pannenassistenten mit Abschluss, auffaelliger Stelle, Standort des zurueckgelassenen Rads (ANN-558) und Stellen am Rad. Ein sperrender Abschluss legt eine Sperre an (fleet_blocks). Datenklasse radflotte_ereignis: drei Jahre ab Ende des Kalenderjahres, nie solange eine Stelle oder ihre Sperre offen ist (ANN-551). Kein Tabellenrecht.';

COMMENT ON COLUMN public.fleet_breakdowns.location_note IS 'Standort des zurueckgelassenen Rads als Freitext (ANN-558). Kann nebenbei einen Patientenbezug tragen; geht deshalb an keinen Dienst und nicht in die Unterlage fuer die Werkstatt und wird mit der Freigabe oder dem Ausmustern des Rads geleert.';

CREATE TABLE public.fleet_checkups (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bike_id uuid NOT NULL,
    bike_type text NOT NULL,
    items jsonb NOT NULL,
    note text,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    checked_by uuid NOT NULL,
    ad_surfaces text,
    ad_surfaces_note text,
    CONSTRAINT fleet_checkups_ad_surfaces_check CHECK ((ad_surfaces = ANY (ARRAY['wiped'::text, 'not_possible'::text]))),
    CONSTRAINT fleet_checkups_ad_surfaces_note CHECK ((((ad_surfaces IS NULL) AND (ad_surfaces_note IS NULL)) OR ((ad_surfaces = 'wiped'::text) AND (ad_surfaces_note IS NULL)) OR ((ad_surfaces = 'not_possible'::text) AND (ad_surfaces_note IS NOT NULL)))),
    CONSTRAINT fleet_checkups_ad_surfaces_note_check CHECK (((ad_surfaces_note IS NULL) OR ((length(btrim(ad_surfaces_note)) >= 1) AND (length(btrim(ad_surfaces_note)) <= 200)))),
    CONSTRAINT fleet_checkups_bike_type_check CHECK ((bike_type = ANY (app.fleet_bike_types()))),
    CONSTRAINT fleet_checkups_items_check CHECK ((jsonb_typeof(items) = 'array'::text)),
    CONSTRAINT fleet_checkups_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 1000))))
);

COMMENT ON TABLE public.fleet_checkups IS 'FLT-001: Fahrrad-Check-Up - zwoelf Pruefpunkte mit In Ordnung, Beobachten oder Problem, Notiz, Stellen am Rad (fleet_spots) und Fotos. Bestaetigt durch die angemeldete Person (ANN-553). Datenklasse radflotte_ereignis: drei Jahre ab Ende des Kalenderjahres, nie solange eine Stelle offen ist (ANN-551). Kein Tabellenrecht.';

COMMENT ON COLUMN public.fleet_checkups.ad_surfaces IS 'FLT-007 (ANN-568): Werbeflaechen mit Desinfektions- oder Reinigungstuch abgewischt (wiped) oder nicht moeglich (not_possible, Grund in ad_surfaces_note). Null: Check-Up vor der Einfuehrung, nicht erfasst.';

COMMENT ON COLUMN public.fleet_checkups.ad_surfaces_note IS 'FLT-007 (ANN-568): warum die Werbeflaechen nicht abgewischt werden konnten. Keine Angaben zu Patient:innen.';

CREATE TABLE public.fleet_depots (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT fleet_depots_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 80))),
    CONSTRAINT fleet_depots_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 200))))
);

COMMENT ON TABLE public.fleet_depots IS 'FLT-001: Abstellort der Raeder (Raddepot). Ein betrieblicher Ort, kein Behandlungsraum; keine Zugangscodes (ANN-554). Datenklasse: Betriebsdaten der Praxis OHNE Personenbezug. Frist: bis zur Loeschung durch die Praxis. Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

CREATE TABLE public.fleet_key_handovers (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bike_id uuid NOT NULL,
    holder_staff_id uuid NOT NULL,
    taken_at timestamp with time zone DEFAULT now() NOT NULL,
    taken_by uuid NOT NULL,
    returned_at timestamp with time zone,
    returned_by uuid,
    CONSTRAINT fleet_key_handovers_order CHECK (((returned_at IS NULL) OR (returned_at >= taken_at))),
    CONSTRAINT fleet_key_handovers_returned_stamp CHECK (((returned_at IS NULL) = (returned_by IS NULL)))
);

COMMENT ON TABLE public.fleet_key_handovers IS 'FLT-001: Schluesselstand eines Rads - wer ihn wann genommen und zurueckgelegt hat. Hoechstens ein offener Vorgang je Rad. Beschaeftigtendaten ohne Auswertung je Person (PROJECT_PRINCIPLES.md 20). Datenklasse schluesselverlauf: 30 Tage nach der Rueckgabe (ANN-551); offene nie. Kein Tabellenrecht.';

CREATE TABLE public.fleet_photo_access_grants (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    photo_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT fleet_photo_access_grants_short_lived CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))))
);

COMMENT ON TABLE public.fleet_photo_access_grants IS 'FLT-002: einmalige, personengebundene Freigabe fuer genau einen Verweis auf ein Foto am Rad (ANN-052). Verbraucht beim ersten Zugriff, verfaellt nach 30 Sekunden; abgelaufene loescht public.discard_stale_fleet_photo_uploads taeglich. Keine Schluessel, keine Namen. Datenklasse radflotte_ereignis, faellt spaetestens mit dem Foto (cascade).';

ALTER TABLE public.fleet_spots ALTER COLUMN seq ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.fleet_spots_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.food_catalog (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    source text NOT NULL,
    source_code text NOT NULL,
    name text NOT NULL,
    brand text,
    base_unit text DEFAULT 'g'::text NOT NULL,
    energy_kcal numeric(5,1) NOT NULL,
    protein_g numeric(5,2) NOT NULL,
    fat_g numeric(5,2) NOT NULL,
    carbohydrate_g numeric(5,2) NOT NULL,
    sugar_g numeric(5,2),
    fibre_g numeric(5,2),
    saturated_fat_g numeric(5,2),
    salt_g numeric(6,3),
    portions jsonb DEFAULT '[]'::jsonb NOT NULL,
    name_key text GENERATED ALWAYS AS (app.food_search_key(name)) STORED,
    search_key text GENERATED ALWAYS AS (app.food_search_key((name || COALESCE((' '::text || brand), ''::text)))) STORED,
    source_version text NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_at timestamp with time zone,
    CONSTRAINT food_catalog_base_unit_check CHECK ((base_unit = ANY (ARRAY['g'::text, 'ml'::text]))),
    CONSTRAINT food_catalog_brand_check CHECK (((brand IS NULL) OR ((length(btrim(brand)) >= 1) AND (length(btrim(brand)) <= 200)))),
    CONSTRAINT food_catalog_brand_only_off CHECK (((source = 'off'::text) OR (brand IS NULL))),
    CONSTRAINT food_catalog_carbohydrate_g_check CHECK ((carbohydrate_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT food_catalog_code_shape CHECK ((((source = 'bls'::text) AND (source_code ~ '^[A-Z][0-9]{6}$'::text)) OR ((source = 'off'::text) AND (source_code ~ '^[0-9]{8,14}$'::text)))),
    CONSTRAINT food_catalog_energy_kcal_check CHECK ((energy_kcal BETWEEN (0)::numeric AND (950)::numeric)),
    CONSTRAINT food_catalog_fat_g_check CHECK ((fat_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT food_catalog_fibre_g_check CHECK (((fibre_g IS NULL) OR (fibre_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT food_catalog_macros_fit CHECK ((((protein_g + fat_g) + carbohydrate_g) <= (105)::numeric)),
    CONSTRAINT food_catalog_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 300))),
    CONSTRAINT food_catalog_portions_check CHECK (app.food_portions_valid(portions)),
    CONSTRAINT food_catalog_protein_g_check CHECK ((protein_g BETWEEN (0)::numeric AND (100)::numeric)),
    CONSTRAINT food_catalog_salt_g_check CHECK (((salt_g IS NULL) OR (salt_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT food_catalog_saturated_fat_g_check CHECK (((saturated_fat_g IS NULL) OR (saturated_fat_g BETWEEN (0)::numeric AND (100)::numeric))),
    CONSTRAINT food_catalog_source_version_check CHECK ((length(source_version) BETWEEN 1 AND 60)),
    CONSTRAINT food_catalog_sugar_g_check CHECK (((sugar_g IS NULL) OR (sugar_g BETWEEN (0)::numeric AND (100)::numeric)))
);

COMMENT ON TABLE public.food_catalog IS 'ERN-004 (ADR-027 Punkte 7 und 8, ANN-656): Bundeslebensmittelschlüssel 4.0 und der Open-Food-Facts-Auszug Deutschland in der eigenen Datenbank - Nährwerte je 100 g bzw. 100 ml, Portionen der Quelle. Bezugsdaten ohne Personenbezug und ohne Organisation. Kein Tabellenrecht; gesucht wird über search_foods und search_platform_foods, geschrieben allein über den Import.';

CREATE TABLE public.food_sources (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    source text NOT NULL,
    title text NOT NULL,
    publisher text NOT NULL,
    license text NOT NULL,
    license_url text NOT NULL,
    attribution text NOT NULL,
    source_url text NOT NULL,
    version text,
    imported_at timestamp with time zone,
    item_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT food_sources_import_pair CHECK (((version IS NULL) = (imported_at IS NULL))),
    CONSTRAINT food_sources_item_count_check CHECK ((item_count >= 0)),
    CONSTRAINT food_sources_source_check CHECK ((source = ANY (ARRAY['bls'::text, 'off'::text]))),
    CONSTRAINT food_sources_version_check CHECK (((version IS NULL) OR (length(version) BETWEEN 1 AND 60)))
);

COMMENT ON TABLE public.food_sources IS 'ERN-004 (ADR-027 Punkte 7 und 8, ANN-657): die Quellen der Lebensmitteldaten mit Lizenz, Quellenangabe und Stand des letzten Imports. Inhalt ohne Personenbezug.';

CREATE TABLE public.habit_marks (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    habit_id uuid NOT NULL,
    done_on date NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    recorded_by uuid NOT NULL,
    CONSTRAINT habit_marks_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text])))
);

COMMENT ON TABLE public.habit_marks IS 'ALT-003 (ANN-370): ein Tag, an dem die Person ihre Gewohnheit gemacht hat - von ihr oder ihrer rechtlichen Vertretung vermerkt, zuruecknehmbar in den letzten sieben Tagen. Faellt mit der Gewohnheit. Kein Tabellenrecht (ADR-004).';

CREATE TABLE public.invoice_cancellations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    cancellation_number text NOT NULL,
    reason text NOT NULL,
    cancelled_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT invoice_cancellations_cancellation_number_check CHECK (((length(btrim(cancellation_number)) >= 3) AND (length(btrim(cancellation_number)) <= 40))),
    CONSTRAINT invoice_cancellations_reason_check CHECK (((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 500)))
);

COMMENT ON TABLE public.invoice_cancellations IS 'Stornodokument zu einer ausgestellten Rechnung (ABR-003c, ADR-009 Punkt 9). Seine Existenz ist der Zustand "storniert" - an der Rechnung steht dazu keine Spalte. Enthaelt ueber die Rechnung einen Patientenbezug, aber keine klinischen Angaben. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen dieser Migration (ADR-004).';

COMMENT ON COLUMN public.invoice_cancellations.cancellation_number IS 'Eigene Nummer aus demselben lueckenlosen Nummernkreis wie die Rechnung (ANN-075, ANN-079). Das Storno geht an denselben Empfaenger und ist damit selbst ein ausgehendes Dokument.';

COMMENT ON COLUMN public.invoice_cancellations.reason IS 'Warum storniert wurde, im Klartext und verpflichtend. Steht in der Zeile und NICHT im Auditeintrag: Ein freier Text kann Patientenbezug tragen, und Logs fuehren keinen (ADR-011).';

CREATE TABLE public.invoice_items (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    billable_service_id uuid NOT NULL,
    sort_order smallint NOT NULL,
    released_at timestamp with time zone,
    service_area text NOT NULL,
    CONSTRAINT invoice_items_sort_order_check CHECK ((sort_order BETWEEN 1 AND 500))
);

COMMENT ON TABLE public.invoice_items IS 'Zuordnung einer erfassten Leistung zu einer Rechnung (ABR-003). Haelt die Invariante gegen Doppelabrechnung: eine Leistung steht auf hoechstens einer Rechnung (ADR-009 Punkt 4). Datenklasse: Abrechnungsdaten (ADR-008).';

COMMENT ON COLUMN public.invoice_items.released_at IS 'Gesetzt heisst: Die Rechnung wurde storniert und die Leistung ist wieder abrechenbar (ABR-003c). Die Zeile bleibt stehen - sie sagt weiter, auf welcher Rechnung die Leistung einmal stand.';

COMMENT ON COLUMN public.invoice_items.service_area IS 'Leistungsbereich dieser Zeile (ADR-009 Punkt 16). Abgeleitet aus der Leistung; die beiden zusammengesetzten Fremdschluessel binden ihn an Rechnung und Leistung zugleich und machen die gemischte Rechnung schemaseitig unmoeglich.';

CREATE TABLE public.invoice_number_series (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    year smallint NOT NULL,
    next_number integer DEFAULT 1 NOT NULL,
    service_area text NOT NULL,
    CONSTRAINT invoice_number_series_next_number_check CHECK ((next_number >= 1)),
    CONSTRAINT invoice_number_series_service_area_check CHECK ((service_area = ANY (ARRAY['therapy'::text, 'training'::text]))),
    CONSTRAINT invoice_number_series_year_check CHECK ((year BETWEEN 2020 AND 2200))
);

COMMENT ON TABLE public.invoice_number_series IS 'Naechste freie Rechnungsnummer je Organisation, Kalenderjahr und Leistungsbereich (ABR-010, ADR-009 Punkte 8 und 17, ANN-075). Kein Personenbezug; sie ist der Nachweis, dass jeder Kreis lueckenlos laeuft und keine Nummer zweimal vergeben wurde. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Kein Tabellenrecht: erreichbar nur ueber app.next_invoice_number.';

COMMENT ON COLUMN public.invoice_number_series.service_area IS 'Der Kreis, den diese Zeile fuehrt (ADR-009 Punkt 17). Mehrere Zahlenreihen sind nach Par. 14 Abs. 4 Nr. 4 UStG zulaessig; dass keine Nummer zweimal vorkommt, tragen die unterschiedlichen Kuerzel und der Unique-Index an invoices.';

CREATE TABLE public.invoice_payment_reminders (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    reminder_on date NOT NULL,
    due_on date NOT NULL,
    outstanding_cents integer NOT NULL,
    currency text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT invoice_payment_reminders_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT invoice_payment_reminders_due_after_reminder CHECK ((due_on > reminder_on)),
    CONSTRAINT invoice_payment_reminders_outstanding_cents_check CHECK ((outstanding_cents > 0))
);

COMMENT ON TABLE public.invoice_payment_reminders IS 'Zahlungserinnerung zu einer ueberfaelligen Rechnung (ABR-003d, IDEA-PRX-012). Ein Dokument ohne Stufe, ohne Gebuehr und ohne eigene Nummer. Enthaelt ueber die Rechnung einen Patientenbezug, aber keine klinischen Angaben. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen dieser Migration (ADR-004).';

COMMENT ON COLUMN public.invoice_payment_reminders.due_on IS 'Die neue Frist, die das Dokument setzt. Vierzehn Tage ab Ausstellung (ANN-080) - kein Rechtsanspruch, sondern die Frist, die auf dem Blatt steht.';

COMMENT ON COLUMN public.invoice_payment_reminders.outstanding_cents IS 'Der offene Betrag am Tag der Erinnerung, festgeschrieben (ANN-080). Nicht gerechnet: Ein Beleg, dessen Zahl sich nachtraeglich aendert, ist keiner. Der heutige Stand steht weiter an der Rechnung und wird dort gerechnet (ANN-078).';

CREATE TABLE public.invoice_recipients (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    recipient_kind text NOT NULL,
    name text NOT NULL,
    street text,
    house_number text,
    postal_code text,
    city text,
    reference text,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT invoice_recipients_city_check CHECK (((city IS NULL) OR ((length(btrim(city)) >= 1) AND (length(btrim(city)) <= 120)))),
    CONSTRAINT invoice_recipients_house_number_check CHECK (((house_number IS NULL) OR ((length(btrim(house_number)) >= 1) AND (length(btrim(house_number)) <= 20)))),
    CONSTRAINT invoice_recipients_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT invoice_recipients_postal_code_check CHECK (((postal_code IS NULL) OR ((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12)))),
    CONSTRAINT invoice_recipients_recipient_kind_check CHECK ((recipient_kind = ANY (ARRAY['legal_representative'::text, 'guardian'::text, 'aid_authority'::text, 'private_insurer'::text, 'other'::text]))),
    CONSTRAINT invoice_recipients_reference_check CHECK (((reference IS NULL) OR ((length(btrim(reference)) >= 1) AND (length(btrim(reference)) <= 60)))),
    CONSTRAINT invoice_recipients_street_check CHECK (((street IS NULL) OR ((length(btrim(street)) >= 1) AND (length(btrim(street)) <= 120))))
);

COMMENT ON TABLE public.invoice_recipients IS 'Rechnungsempfaenger einer Patientin, die nicht sie selbst ist (ABR-003a, ADR-009 Punkt 2): Eltern, Betreuung, Beihilfestelle, private Versicherung. Enthaelt einen Patientenbezug. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen dieser Migration (ADR-004).';

COMMENT ON COLUMN public.invoice_recipients.recipient_kind IS 'Art des Empfaengers. Steuert Anrede und Aktenzeichen auf der Rechnung - nicht die Berechtigung: Ein Empfaenger ist kein Zugang zur Akte (ADR-009, Konsequenz zu B5).';

COMMENT ON COLUMN public.invoice_recipients.reference IS 'Aktenzeichen oder Versichertennummer beim Empfaenger, Freitext. Geht in den Rechnungssnapshot, weil die Zahlung sonst nicht zugeordnet werden kann.';

COMMENT ON COLUMN public.invoice_recipients.is_default IS 'Vorbelegung neuer Rechnungsentwuerfe dieser Patientin. Hoechstens eine je Patientin; ist keine gesetzt, geht die Rechnung an die Patientin selbst (ANN-076).';

CREATE TABLE public.invoices (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid,
    recipient_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    period_month date NOT NULL,
    invoice_number text,
    issued_on date,
    issued_at timestamp with time zone,
    issued_by uuid,
    due_on date,
    total_cents integer,
    tax_total_cents integer,
    currency text,
    snapshot jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    replaces_invoice_id uuid,
    service_area text NOT NULL,
    training_relationship_id uuid,
    treatment_basis_id uuid,
    CONSTRAINT invoices_basis_only_therapy CHECK (((treatment_basis_id IS NULL) OR (service_area = 'therapy'::text))),
    CONSTRAINT invoices_currency_check CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT invoices_invoice_number_check CHECK (((invoice_number IS NULL) OR ((length(btrim(invoice_number)) >= 3) AND (length(btrim(invoice_number)) <= 40)))),
    CONSTRAINT invoices_issued_is_complete CHECK (
CASE status
    WHEN 'draft'::text THEN ((invoice_number IS NULL) AND (issued_on IS NULL) AND (snapshot IS NULL))
    WHEN 'issued'::text THEN ((invoice_number IS NOT NULL) AND (issued_on IS NOT NULL) AND (due_on IS NOT NULL) AND (snapshot IS NOT NULL) AND (total_cents IS NOT NULL) AND (tax_total_cents IS NOT NULL) AND (currency IS NOT NULL))
    ELSE NULL::boolean
END),
    CONSTRAINT invoices_party CHECK ((((service_area = 'therapy'::text) AND (patient_id IS NOT NULL) AND (training_relationship_id IS NULL)) OR ((service_area = 'training'::text) AND (training_relationship_id IS NOT NULL) AND (patient_id IS NULL)))),
    CONSTRAINT invoices_period_is_month CHECK ((period_month = date_trunc('month'::text, (period_month)::timestamp with time zone))),
    CONSTRAINT invoices_service_area_check CHECK ((service_area = ANY (ARRAY['therapy'::text, 'training'::text]))),
    CONSTRAINT invoices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'issued'::text]))),
    CONSTRAINT invoices_tax_total_cents_check CHECK (((tax_total_cents IS NULL) OR (tax_total_cents >= 0))),
    CONSTRAINT invoices_total_cents_check CHECK (((total_cents IS NULL) OR (total_cents >= 0)))
);

COMMENT ON TABLE public.invoices IS 'Privatrechnung aus erfassten Leistungen (ABR-003, ADR-009). Enthaelt einen Patientenbezug und im Snapshot Leistungsdaten. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen dieser Migration (ADR-004).';

COMMENT ON COLUMN public.invoices.recipient_id IS 'Der Empfaenger dieser Rechnung. null heisst: die Patientin selbst (ANN-076). Nach dem Ausstellen steht der Empfaenger ohnehin im Snapshot; die Spalte bleibt als Verweis auf die Stammdaten.';

COMMENT ON COLUMN public.invoices.period_month IS 'Erster Tag des Kalendermonats, dessen Leistungen diese Rechnung zusammenfasst (ANN-077). Je Patientin und Monat hoechstens ein Entwurf.';

COMMENT ON COLUMN public.invoices.invoice_number IS 'Wird erst beim Ausstellen vergeben (ADR-009 Punkt 8). Eindeutig je Organisation, lueckenlos je Kalenderjahr, nie wiederverwendet (ANN-075).';

COMMENT ON COLUMN public.invoices.total_cents IS 'Rechnungsbetrag in ganzen Cent (ADR-014). Der Katalogpreis ist der Endpreis; eine enthaltene Umsatzsteuer wird herausgerechnet und getrennt ausgewiesen (ANN-074).';

COMMENT ON COLUMN public.invoices.snapshot IS 'Das ausgestellte Dokument mit allen rechnungsrelevanten Stamm-, Leistungs-, Preis- und Steuerangaben (ADR-009 Punkt 10). Traegt eine eigene schema_version und ist damit von spaeteren Schemaaenderungen unabhaengig - die offene Folgefrage des ADR. Enthaelt KEINE klinischen Inhalte.';

COMMENT ON COLUMN public.invoices.replaces_invoice_id IS 'Die stornierte Rechnung, die diese Rechnung ersetzt (ABR-003c, ADR-009 Punkt 9). null heisst: eine gewoehnliche Rechnung. Mehrfache Korrektur ergibt eine Kette, in der jede Rechnung auf genau ihre Vorgaengerin zeigt.';

COMMENT ON COLUMN public.invoices.service_area IS 'Der eine Leistungsbereich dieser Rechnung (ADR-009 Punkt 16). Gemischte Rechnungen sind ausgeschlossen - nicht durch eine Regel der Oberflaeche, sondern durch die Fremdschluessel der Rechnungszeile.';

COMMENT ON COLUMN public.invoices.training_relationship_id IS 'Das Trainingsverhaeltnis, dessen Leistungen diese Rechnung abrechnet (TRN-008, ADR-021 Punkt 5). Gesetzt genau im Bereich training; patient_id ist dann leer.';

COMMENT ON COLUMN public.invoices.treatment_basis_id IS 'Die Behandlungsgrundlage, deren Leistungen diese Rechnung zusammenfasst (ABR-032, ADR-009 Punkt 23, ANN-077 Fassung 2). null: Leistungen an Terminen ohne Grundlage, gebuendelt nach Kalendermonat, oder Training. period_month nennt bei einer Grundlage den Monat der ersten Leistung.';

COMMENT ON CONSTRAINT invoices_party ON public.invoices IS 'Eine Rechnung haengt an genau einem Verhaeltnis, und zwar an dem ihres Bereichs (ADR-021 Punkt 3, ADR-009 Punkt 16). Eine Trainingsrechnung mit Patientenbezug ist schemaseitig unmoeglich.';

CREATE TABLE public.legal_holds (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    subject_type text NOT NULL,
    subject_id uuid NOT NULL,
    reason text NOT NULL,
    placed_at timestamp with time zone DEFAULT now() NOT NULL,
    placed_by uuid NOT NULL,
    released_at timestamp with time zone,
    released_by uuid,
    CONSTRAINT legal_holds_reason_check CHECK (((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 1000))),
    CONSTRAINT legal_holds_release_after_place CHECK (((released_at IS NULL) OR (released_at >= placed_at))),
    CONSTRAINT legal_holds_release_complete CHECK ((((released_at IS NULL) AND (released_by IS NULL)) OR ((released_at IS NOT NULL) AND (released_by IS NOT NULL)))),
    CONSTRAINT legal_holds_subject_type_check CHECK ((subject_type = ANY (ARRAY['patient'::text, 'staff_member'::text])))
);

COMMENT ON TABLE public.legal_holds IS 'Loeschsperre fuer laufende rechtliche Vorgaenge (ADR-008 Punkt 7, LOE-001c). Setzt die automatische Loeschung aus, nicht die Zugriffsregeln (ADR-004). Gegenstand: eine Patientenakte (ANN-033) oder die Beschaeftigtendaten einer Person des Teams (ANN-674). Datenklasse: wie der Gegenstand - der Grund ist eine Angabe ueber die betroffene Person.';

COMMENT ON COLUMN public.legal_holds.reason IS 'Warum die Loeschung ausgesetzt ist. Freitext ohne klinische Inhalte; erscheint nie in Logs (ADR-011) und nie im Auditkontext.';

COMMENT ON COLUMN public.legal_holds.placed_by IS 'auth.users.id der verantwortlichen Person. Bewusst ohne FK, damit ein spaeter geloeschtes Konto den Nachweis nicht entfernt (ADR-008).';

CREATE TABLE public.message_attachment_access_grants (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    attachment_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    handout boolean DEFAULT false NOT NULL,
    CONSTRAINT message_attachment_access_grants_short_lived CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))))
);

COMMENT ON TABLE public.message_attachment_access_grants IS 'KOM-005: einmalige, personengebundene Freigabe fuer genau einen Verweis auf einen Anhang (ANN-052). Verbraucht beim ersten Zugriff, verfaellt nach 30 Sekunden. Keine Schluessel, keine Namen.';

COMMENT ON COLUMN public.message_attachment_access_grants.handout IS 'BEF-188: Freigabe aus hand_out_message_attachment - gilt fuer owner der eigenen Organisation auch fuer einen gesperrten Anhang, nie fuer einen unbestaetigten.';

CREATE TABLE public.notification_deliveries (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    access_id uuid NOT NULL,
    kind text NOT NULL,
    channel text NOT NULL,
    subject_id uuid,
    subject_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    due_at timestamp with time zone NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    claimed_at timestamp with time zone,
    attempts smallint DEFAULT 0 NOT NULL,
    finished_at timestamp with time zone,
    drop_reason text,
    CONSTRAINT notification_deliveries_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT notification_deliveries_channel_check CHECK ((channel = ANY (ARRAY['email'::text, 'push'::text]))),
    CONSTRAINT notification_deliveries_drop_reason_check CHECK ((drop_reason = ANY (ARRAY['access_ended'::text, 'switched_off'::text, 'not_wanted'::text, 'no_address'::text, 'no_device'::text, 'obsolete'::text, 'daily_cap'::text, 'weekly_cap'::text, 'stale'::text]))),
    CONSTRAINT notification_deliveries_finished CHECK ((((state = 'pending'::text) = (finished_at IS NULL)) AND ((state = 'dropped'::text) = (drop_reason IS NOT NULL)))),
    CONSTRAINT notification_deliveries_kind_check CHECK ((kind = ANY (app.notification_kinds()))),
    CONSTRAINT notification_deliveries_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text, 'dropped'::text])))
);

COMMENT ON TABLE public.notification_deliveries IS 'KOM-009 (ADR-024 Punkte 16, 17): Zustellauftraege fuer Benachrichtigungen an Plattformzugaenge. Katalogschluessel, Weg, Zeitpunkte, Zustand - kein Text, keine Adresse, kein Endpunkt. 30 Tage nach dem Abschluss geloescht (purge_notification_deliveries). Nur ueber Funktionen.';

CREATE TABLE public.notification_kind_switches (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    kind text NOT NULL,
    disabled_at timestamp with time zone DEFAULT now() NOT NULL,
    disabled_by uuid NOT NULL,
    CONSTRAINT notification_kind_switches_kind_check CHECK ((kind = ANY (app.notification_kinds())))
);

COMMENT ON TABLE public.notification_kind_switches IS 'KOM-009 (ADR-024 Punkt 15): Arten, die die Praxis fuer alle abgeschaltet hat. Eine Zeile heisst aus; einschalten loescht sie. Nur owner, nur ueber Funktionen.';

CREATE TABLE public.nutrition_diary_favorites (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    food_kind text NOT NULL,
    catalog_food_id uuid,
    custom_food_id uuid,
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    CONSTRAINT nutrition_diary_favorites_food_kind_check CHECK ((food_kind = ANY (ARRAY['catalog'::text, 'practice'::text, 'person'::text]))),
    CONSTRAINT nutrition_diary_favorites_food_shape CHECK ((((food_kind = 'catalog'::text) AND (catalog_food_id IS NOT NULL) AND (custom_food_id IS NULL)) OR ((food_kind = ANY (ARRAY['practice'::text, 'person'::text])) AND (custom_food_id IS NOT NULL) AND (catalog_food_id IS NULL)))),
    CONSTRAINT nutrition_diary_favorites_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text])))
);

COMMENT ON TABLE public.nutrition_diary_favorites IS 'ERN-008 (ADR-027 Punkt 10): Favoriten im Ernährungstagebuch - ein Lebensmittel je Zeile, von der Person oder ihrer rechtlichen Vertretung markiert. Lesen allein mit app.can_counsel_nutrition. Datenklasse: Ernährungsberatung, fällt mit dem Profil.';

CREATE TABLE public.nutrition_diary_reminders (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    access_id uuid NOT NULL,
    meal text NOT NULL,
    remind_at time without time zone NOT NULL,
    chosen_at timestamp with time zone DEFAULT now() NOT NULL,
    chosen_by uuid NOT NULL,
    CONSTRAINT nutrition_diary_reminders_meal_check CHECK ((meal = ANY (ARRAY['breakfast'::text, 'lunch'::text, 'dinner'::text, 'snack'::text]))),
    CONSTRAINT nutrition_diary_reminders_remind_at_check CHECK (((((EXTRACT(minute FROM remind_at))::integer % 15) = 0) AND (EXTRACT(second FROM remind_at) = (0)::numeric)))
);

COMMENT ON TABLE public.nutrition_diary_reminders IS 'ERN-009 (ADR-027 Punkt 12, ADR-024 Punkt 15): Erinnerungen an das Ernährungstagebuch - je Zugang und Mahlzeit eine Uhrzeit, von der Person bzw. ihrer rechtlichen Vertretung gewählt. Ohne Zeile keine Erinnerung. Kein Tabellenrecht und keine Lese-Policy: die Praxis sieht nicht, wer Erinnerungen gewählt hat (ANN-344). Datenklasse: Ernährungsberatung, fällt mit dem Profil und mit dem Zugang.';

CREATE TABLE public.nutrition_water_days (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    drunk_on date NOT NULL,
    water_ml integer NOT NULL,
    platform_access_id uuid NOT NULL,
    platform_access_kind text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT nutrition_water_days_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT nutrition_water_days_water_ml_check CHECK ((water_ml BETWEEN 0 AND 10000))
);

COMMENT ON TABLE public.nutrition_water_days IS 'ERN-007 (ADR-027 Punkt 10): getrunkenes Wasser je Tag, mit einem Tipp je Glas (ANN-661). Datenklasse: Ernährungsberatung, fällt mit dem Profil.';

CREATE TABLE public.nutrition_weight_entries (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    measured_on date NOT NULL,
    weight_kg numeric(4,1) NOT NULL,
    source text NOT NULL,
    platform_access_id uuid,
    platform_access_kind text,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by uuid NOT NULL,
    CONSTRAINT nutrition_weight_entries_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT nutrition_weight_entries_source_check CHECK ((source = ANY (ARRAY['practice'::text, 'platform'::text]))),
    CONSTRAINT nutrition_weight_entries_source_shape CHECK ((((source = 'platform'::text) = (platform_access_id IS NOT NULL)) AND ((source = 'platform'::text) = (platform_access_kind IS NOT NULL)))),
    CONSTRAINT nutrition_weight_entries_weight_kg_check CHECK ((weight_kg BETWEEN (20)::numeric AND (350)::numeric))
);

COMMENT ON TABLE public.nutrition_weight_entries IS 'ERN-001 (ADR-027 Punkt 5): Körpergewicht mit Verlauf, eingetragen von der Person auf der Plattform oder von der Beratung; eines je Tag. Datenklasse: Ernährungsberatung, fällt mit dem Profil.';

CREATE TABLE public.passkey_approvals (
    credential_id uuid NOT NULL,
    user_id uuid NOT NULL,
    approved_at timestamp with time zone DEFAULT now() NOT NULL,
    webauthn_id text,
    public_key text,
    public_key_alg integer,
    CONSTRAINT passkey_approvals_offline_key CHECK ((((webauthn_id IS NULL) = (public_key IS NULL)) AND ((public_key IS NULL) = (public_key_alg IS NULL)) AND ((webauthn_id IS NULL) OR ((webauthn_id ~ '^[A-Za-z0-9_-]+$'::text) AND (length(webauthn_id) BETWEEN 16 AND 1366))) AND ((public_key IS NULL) OR ((public_key ~ '^[A-Za-z0-9+/]+={0,2}$'::text) AND (length(public_key) BETWEEN 40 AND 2048))) AND ((public_key_alg IS NULL) OR (public_key_alg = ANY (ARRAY['-7'::integer, '-8'::integer, '-257'::integer])))))
);

COMMENT ON TABLE public.passkey_approvals IS 'Passkeys, die das Konto in offener Sitzung freigegeben hat (ADR-025 Punkt 10, ANN-329). Nur die Kennung des Passkeys beim Anmeldedienst, kein Schlüssel. Kein direkter Zugriff; geschrieben nur über approve_own_passkey. Datenklasse accountdaten: fällt mit dem Konto; eine Freigabe zu einem entfernten Passkey räumt approve_own_passkey ab.';

COMMENT ON COLUMN public.passkey_approvals.webauthn_id IS 'TRK-009 (ANN-359): Kennung des Passkeys beim Browser (rawId, base64url) - damit die Freigabe ohne Netz genau diesen Passkey anfragt.';

COMMENT ON COLUMN public.passkey_approvals.public_key IS 'TRK-009 (ANN-359): oeffentlicher Schluessel des Passkeys (SPKI, base64), beim Einrichten aus der Antwort des Browsers gelesen. Kein Geheimnis; nur fuer die Freigabe ohne Netz auf dem Geraet (ADR-025 Punkt 16).';

COMMENT ON COLUMN public.passkey_approvals.public_key_alg IS 'TRK-009 (ANN-359): COSE-Algorithmus des Schluessels: -7 ES256, -8 EdDSA, -257 RS256.';

CREATE TABLE public.patient_care_details (
    patient_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    primary_therapist_staff_member_id uuid,
    home_visit_access_note text,
    special_note text,
    remark text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    treatment_table_required boolean,
    take_along_items text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT patient_care_details_home_visit_access_note_check CHECK (((home_visit_access_note IS NULL) OR ((length(btrim(home_visit_access_note)) >= 1) AND (length(btrim(home_visit_access_note)) <= 1000)))),
    CONSTRAINT patient_care_details_remark_check CHECK (((remark IS NULL) OR ((length(btrim(remark)) >= 1) AND (length(btrim(remark)) <= 2000)))),
    CONSTRAINT patient_care_details_special_note_check CHECK (((special_note IS NULL) OR ((length(btrim(special_note)) >= 1) AND (length(btrim(special_note)) <= 1000)))),
    CONSTRAINT patient_care_details_take_along_items_valid CHECK (app.take_along_items_valid(take_along_items))
);

COMMENT ON TABLE public.patient_care_details IS 'Interne organisatorische Angaben der Praxis zur Versorgung einer Patientin (PAT-005, ANN-010). Keine klinischen Inhalte. Sichtbar nur fuer die Rollen der Patientenkartei, nicht fuer das Patientenkonto. Datenklasse: wie Patientenakte, 10 Jahre nach Behandlungsabschluss (ADR-008).';

COMMENT ON COLUMN public.patient_care_details.primary_therapist_staff_member_id IS 'Fest zugeordnete behandelnde Person. Organisatorische Vorbelegung, KEINE Zugriffsbeschraenkung - 4.2 bleibt unveraendert.';

COMMENT ON COLUMN public.patient_care_details.home_visit_access_note IS 'Zugangshinweis fuer den Hausbesuch: Etage, Klingelname, Schluessel, Hund, Radabstellplatz. Organisatorisch, kein Gesundheitsdatum. Darf nie in Logs erscheinen (ADR-011).';

COMMENT ON COLUMN public.patient_care_details.special_note IS 'Organisatorische Besonderheit, die vor dem Besuch bekannt sein muss. Klinische Inhalte gehoeren in die Behandlungsdokumentation (PROJECT_PRINCIPLES.md 5).';

COMMENT ON COLUMN public.patient_care_details.treatment_table_required IS 'Behandlungsliege mitnehmen (UX-003a, ANN-116): ja, nein oder leer - noch nicht entschieden (PRX-013, ANN-143). Organisatorisches Merkmal der Person wie der Zugangshinweis; der klinische Grund steht im Befund, nicht hier.';

COMMENT ON COLUMN public.patient_care_details.take_along_items IS 'Mitnehmen (PRX-007, ANN-138): von Hand gepflegte Liste, was fuer einen Besuch aufs Rad muss. Nie aus Dokumentation abgeleitet (ADR-006).';

CREATE TABLE public.patient_contact_details (
    patient_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    date_of_birth date,
    email text,
    phone text,
    street text,
    postal_code text,
    city text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    house_number text,
    phone_work text,
    phone_mobile text,
    institution text,
    lat double precision,
    lon double precision,
    geocode_precision text,
    CONSTRAINT patient_contact_details_coordinate_check CHECK ((((lat IS NULL) AND (lon IS NULL) AND (geocode_precision IS NULL)) OR ((lat BETWEEN ('-90'::integer)::double precision AND (90)::double precision) AND (lon BETWEEN ('-180'::integer)::double precision AND (180)::double precision) AND (geocode_precision = ANY (ARRAY['address'::text, 'street'::text, 'locality'::text, 'unknown'::text])) AND (street IS NOT NULL) AND (postal_code IS NOT NULL) AND (city IS NOT NULL)))),
    CONSTRAINT patient_contact_details_email_check CHECK (((email IS NULL) OR (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT patient_contact_details_house_number_check CHECK (((house_number IS NULL) OR ((length(btrim(house_number)) >= 1) AND (length(btrim(house_number)) <= 20)))),
    CONSTRAINT patient_contact_details_institution_check CHECK (((institution IS NULL) OR ((length(btrim(institution)) >= 1) AND (length(btrim(institution)) <= 200)))),
    CONSTRAINT patient_contact_details_phone_check CHECK (((phone IS NULL) OR ((length(btrim(phone)) >= 3) AND (length(btrim(phone)) <= 40)))),
    CONSTRAINT patient_contact_details_phone_mobile_check CHECK (((phone_mobile IS NULL) OR ((length(btrim(phone_mobile)) >= 3) AND (length(btrim(phone_mobile)) <= 40)))),
    CONSTRAINT patient_contact_details_phone_work_check CHECK (((phone_work IS NULL) OR ((length(btrim(phone_work)) >= 3) AND (length(btrim(phone_work)) <= 40)))),
    CONSTRAINT patient_contact_details_postal_code_check CHECK (((postal_code IS NULL) OR ((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12))))
);

COMMENT ON TABLE public.patient_contact_details IS 'Kontakt- und Adressdaten im Patientenkontext. Organisatorische Daten, keine klinischen Inhalte. Datenklasse: wie Patientenakte, 10 Jahre nach Behandlungsabschluss (ADR-008).';

COMMENT ON COLUMN public.patient_contact_details.house_number IS 'Hausnummer getrennt von der Strasse - erleichtert spaetere Geokodierung fuer die Tourenplanung (ADR-002, PROJECT_PRINCIPLES.md 9).';

COMMENT ON COLUMN public.patient_contact_details.phone_work IS 'Geschaeftliche Telefonnummer der Person. Erreichbarkeit, keine Beschaeftigtendaten der Praxis.';

COMMENT ON COLUMN public.patient_contact_details.phone_mobile IS 'Mobilnummer. Im Hausbesuch die Nummer, unter der eine Verspaetung angekuendigt wird.';

COMMENT ON COLUMN public.patient_contact_details.institution IS 'Einrichtung, in der die Person lebt oder betreut wird (Pflegeheim, betreutes Wohnen). Organisatorisch, kein Rechnungsempfaenger - der kommt mit ABR-003a.';

COMMENT ON COLUMN public.patient_contact_details.lat IS 'Breitengrad der geocodierten Adresse (ANN-016). Abgeleitetes Stammdatum mit Datenklasse und Frist der Adresse. Geschrieben nur von set_patient_address_coordinate; verfaellt bei jeder Adressaenderung. Nie in Logs (ADR-011).';

COMMENT ON COLUMN public.patient_contact_details.lon IS 'Laengengrad der geocodierten Adresse (ANN-016). Siehe lat.';

COMMENT ON COLUMN public.patient_contact_details.geocode_precision IS 'Genauigkeit des Geocoding-Treffers: address, street, locality, unknown. Unterhalb address hat die erfassende Person den Treffer bestaetigt (ANN-016).';

CREATE TABLE public.patient_course_events (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    occurred_on date NOT NULL,
    kind text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    removed_at timestamp with time zone,
    removed_by uuid,
    CONSTRAINT patient_course_events_kind_check CHECK ((kind = ANY (ARRAY['operation'::text, 'erkrankung'::text, 'urlaub'::text, 'medikation'::text, 'sonstiges'::text]))),
    CONSTRAINT patient_course_events_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 200)))),
    CONSTRAINT patient_course_events_occurred_on_check CHECK ((occurred_on >= '1900-01-01'::date)),
    CONSTRAINT patient_course_events_removed_check CHECK (((removed_at IS NULL) = (removed_by IS NULL)))
);

COMMENT ON TABLE public.patient_course_events IS 'Ereignisse im Verlauf einer Akte - Operation, Erkrankung, Urlaub, Medikation, Sonstiges (FRB-002e, IDEA-OUT-005, ANN-106). Markierung ohne Bewertung. Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: Patientenakte, faellt mit der Akte.';

COMMENT ON COLUMN public.patient_course_events.removed_at IS 'Wann das Ereignis entfernt wurde (ABN-013, BEF-102). Entfernt heisst: nicht mehr im Verlauf, aber in der Akte nachvollziehbar.';

COMMENT ON COLUMN public.patient_course_events.removed_by IS 'Wer das Ereignis entfernt hat (Benutzerkennung, ABN-013).';

CREATE VIEW public.patient_directory WITH (security_invoker='true') AS
 SELECT p.id,
    p.organization_id,
    p.status,
    p.care_started_on,
    p.care_concluded_on,
    p.care_concluded_at,
    pe.given_name,
    pe.family_name,
    c.date_of_birth,
    c.email,
    c.phone,
    c.phone_work,
    c.phone_mobile,
    c.institution,
    c.street,
    c.house_number,
    c.postal_code,
    c.city,
    cd.primary_therapist_staff_member_id,
        CASE
            WHEN (tp.id IS NULL) THEN NULL::text
            ELSE ((tp.given_name || ' '::text) || tp.family_name)
        END AS primary_therapist_name,
    cd.home_visit_access_note,
    cd.special_note,
    cd.remark,
    c.geocode_precision,
    cd.treatment_table_required,
    cd.take_along_items
   FROM (((((public.patients p
     JOIN public.persons pe ON ((pe.id = p.person_id)))
     LEFT JOIN public.patient_contact_details c ON ((c.patient_id = p.id)))
     LEFT JOIN public.patient_care_details cd ON ((cd.patient_id = p.id)))
     LEFT JOIN public.staff_members tsm ON ((tsm.id = cd.primary_therapist_staff_member_id)))
     LEFT JOIN public.persons tp ON ((tp.id = tsm.person_id)));

COMMENT ON VIEW public.patient_directory IS 'Patientenkartei fuer die Anwendung. security_invoker: RLS der Basistabellen gilt unveraendert - die internen Versorgungsangaben bleiben fuer ein Patientenkonto leer (PAT-005, ANN-010). Seit LOE-001b mit dem Abschluss der Versorgung. Seit SLK-001 ohne Telefax.';

CREATE TABLE public.patient_fee_agreements (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    valid_from date NOT NULL,
    session_fee_cents integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT patient_fee_agreements_session_fee_cents_check CHECK ((session_fee_cents BETWEEN 0 AND 1000000))
);

COMMENT ON TABLE public.patient_fee_agreements IS 'Mit einer Person vereinbartes Terminhonorar ab einem Tag (ABR-030, ADR-009 Punkte 5 und 22, ANN-231). Unveraenderlich; eine Aenderung ist ein neuer Eintrag. Datenklasse: Abrechnungsdaten der Akte. Nur ueber Funktionen erreichbar.';

COMMENT ON COLUMN public.patient_fee_agreements.valid_from IS 'Erster Leistungstag, an dem die Vereinbarung gilt. Am Leistungstag gilt die juengste bis zu diesem Tag; sie geht dem allgemeinen Tarif vor.';

CREATE TABLE public.patient_file_access_grants (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    patient_file_id uuid,
    deletion_order_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT patient_file_access_grants_one_subject CHECK (((patient_file_id IS NULL) <> (deletion_order_id IS NULL))),
    CONSTRAINT patient_file_access_grants_short_lived CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))))
);

COMMENT ON TABLE public.patient_file_access_grants IS 'Einmalige Freigabe fuer genau eine Storage-Operation an einer Datei der Akte oder am Objekt eines Loeschauftrags (FIX-015, BEF-004, ANN-052). Angelegt nur von issue_patient_file_link und claim_storage_deletion_order, verbraucht und geloescht durch die RLS auf storage.objects. Datenklasse: technische Zugriffsfreigabe ohne Inhalt; lebt Sekunden, faellt spaetestens mit Datei oder Auftrag.';

CREATE TABLE public.patient_file_document_types (
    key text NOT NULL,
    is_clinical boolean NOT NULL,
    sort_order smallint DEFAULT 100 NOT NULL,
    note text NOT NULL,
    CONSTRAINT patient_file_document_types_key_check CHECK ((key ~ '^[a-z_]+$'::text)),
    CONSTRAINT patient_file_document_types_note_check CHECK (((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 500)))
);

COMMENT ON TABLE public.patient_file_document_types IS 'Fester Katalog der Dokumentarten (ADR-017 Punkt 12). is_clinical bestimmt das Schreibrecht (klinisch: owner/therapist/team_lead, organisatorisch zusaetzlich office) und bleibt der Rollenschnitt fuer Patientenkonten und Dritte; lesen duerfen seit E15 alle vier Praxisrollen. Datenklasse: Konfiguration, kein Personenbezug.';

COMMENT ON COLUMN public.patient_file_document_types.is_clinical IS 'true: die Datei kann Gesundheitsdaten zeigen. Lesen alle vier Praxisrollen (E15); hochladen und loeschen nur owner, therapist und team_lead. Eine falsch gewaehlte Art bleibt ein Mangel nach PROJECT_PRINCIPLES.md 13 - sie bestimmt das Schreibrecht und, sobald es sie gibt, die Sicht von Patientenkonten und Dritten.';

CREATE TABLE public.patient_files (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    treatment_basis_id uuid,
    document_type text NOT NULL,
    display_name text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    checksum_sha256 text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    uploaded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    object_key text NOT NULL,
    photo_locked_at timestamp with time zone,
    verified_at timestamp with time zone,
    content_type_verified boolean,
    checksum_verified boolean,
    metadata_verified boolean,
    confirmation_requested_at timestamp with time zone,
    released_at timestamp with time zone,
    released_by uuid,
    CONSTRAINT patient_files_byte_size_check CHECK (((byte_size > 0) AND (byte_size <= 10485760))),
    CONSTRAINT patient_files_checksum_sha256_check CHECK ((checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT patient_files_display_name_check CHECK (((length(btrim(display_name)) >= 1) AND (length(btrim(display_name)) <= 200))),
    CONSTRAINT patient_files_lock_only_for_photos CHECK (((photo_locked_at IS NULL) OR (document_type = 'patientenfoto'::text))),
    CONSTRAINT patient_files_mime_type_check CHECK ((mime_type = ANY (ARRAY['application/pdf'::text, 'image/jpeg'::text, 'image/png'::text]))),
    CONSTRAINT patient_files_photo_belongs_to_patient CHECK (((document_type <> ALL (ARRAY['patientenfoto'::text, 'dokumentationsfoto'::text])) OR (treatment_basis_id IS NULL))),
    CONSTRAINT patient_files_photo_is_jpeg CHECK (((document_type <> ALL (ARRAY['patientenfoto'::text, 'dokumentationsfoto'::text])) OR (mime_type = 'image/jpeg'::text))),
    CONSTRAINT patient_files_ready_has_confirmation CHECK (((status = 'ready'::text) = (confirmed_at IS NOT NULL))),
    CONSTRAINT patient_files_release_not_photo CHECK (((released_at IS NULL) OR (document_type <> ALL (ARRAY['patientenfoto'::text, 'dokumentationsfoto'::text])))),
    CONSTRAINT patient_files_release_stamp CHECK (((released_at IS NULL) = (released_by IS NULL))),
    CONSTRAINT patient_files_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text]))),
    CONSTRAINT patient_files_verification_complete CHECK ((((verified_at IS NULL) = (content_type_verified IS NULL)) AND ((verified_at IS NULL) = (checksum_verified IS NULL)) AND ((verified_at IS NOT NULL) OR (metadata_verified IS NULL)))),
    CONSTRAINT patient_files_verification_passed CHECK (((verified_at IS NULL) OR (content_type_verified AND checksum_verified AND COALESCE(metadata_verified, true))))
);

COMMENT ON TABLE public.patient_files IS 'Dateien der Patientenakte (ADR-017). Die Zeile fuehrt, das Objekt folgt. Datenklasse: patientenakte, zehn Jahre nach Abschluss der Versorgung (ADR-008 Punkt 4). Kein Tabellenrecht, keine Policy: erreichbar nur ueber die Funktionen dieser Migration.';

COMMENT ON COLUMN public.patient_files.treatment_basis_id IS 'Die Behandlungsgrundlage, an der die Datei haengt (ADR-017 Punkt 10). Leer bei einem Verordnungsscan heisst: noch zu erfassen (PRX-011) - ein offener Punkt der Bueroliste, bis assign_prescription_scan ihn zuordnet.';

COMMENT ON COLUMN public.patient_files.checksum_sha256 IS 'SHA-256 der hochgeladenen Bytes, im Browser gerechnet. Die Datenbank sieht die Bytes nie und kann die Summe nicht nachrechnen - sie ist eine festgehaltene Erklaerung, kein serverseitig erhobener Messwert (ANN-053, ADR-017 Punkt 9).';

COMMENT ON COLUMN public.patient_files.status IS 'pending: Zeile angelegt, Objekt noch nicht bestaetigt. ready: Groesse und MIME-Typ gegen storage.objects geprueft. Nur ready ist sichtbar und verweisfaehig (ADR-017 Punkt 7).';

COMMENT ON COLUMN public.patient_files.object_key IS 'Objektschluessel nach ADR-017 Punkt 5 - nur Kennungen, keine Endung, kein Name. Beim Anlegen vom Trigger gesetzt (organization/grundlage-oder-patient/datei) und danach unveraenderlich (PRX-011): Das Zuordnen eines Scans aendert den Bezug, nicht den Ort des Objekts. Verlaesst die Datenbank ausschliesslich ueber prepare_patient_file_upload und issue_patient_file_link (ANN-052).';

COMMENT ON COLUMN public.patient_files.photo_locked_at IS 'Nur Patientenfotos: seit wann das Foto faellig und gesperrt ist, festgehalten, solange ein Legal Hold die Loeschung anhaelt. Haelt die Sperre auch, wenn ein Anker spaeter wegfaellt (Wiederaufnahme der Versorgung).';

COMMENT ON COLUMN public.patient_files.verified_at IS 'Wann die Pruefung am Server (Edge Function patient-file-verify) die Datei bestanden hat. Leer: nicht serverseitig geprueft (ADR-017 Punkte 49 und 51).';

COMMENT ON COLUMN public.patient_files.content_type_verified IS 'Typ an der Signatur der ersten Bytes passt zu Allowlist und Ankuendigung (ADR-017 Punkt 49 Nr. 1).';

COMMENT ON COLUMN public.patient_files.checksum_verified IS 'SHA-256 ueber die abgelegten Bytes passt zur angekuendigten Pruefsumme (ADR-017 Punkt 49 Nr. 2).';

COMMENT ON COLUMN public.patient_files.metadata_verified IS 'JPEG und PNG: keine Metadaten ausserhalb der Erlaubnisliste (ADR-017 Punkt 49 Nr. 3, ANN-125). Leer bei PDF.';

COMMENT ON COLUMN public.patient_files.confirmation_requested_at IS 'Nur bei scharfer Pruefung: wann die Bestaetigung (Phase c) bestanden war; ready wird die Datei erst mit dem Ergebnis (ADR-017 Punkt 51).';

COMMENT ON COLUMN public.patient_files.released_at IS 'POR-014 (DSN-001 D3, ANN-249): seit wann die Datei fuer die Person auf der Plattform sichtbar ist; null = nicht freigegeben.';

COMMENT ON COLUMN public.patient_files.released_by IS 'POR-014: wer die Datei freigegeben hat (owner, therapist, team_lead).';

CREATE VIEW public.patient_list_entries WITH (security_invoker='true') AS
 SELECT p.id,
    p.organization_id,
    p.status,
    pe.given_name,
    pe.family_name,
    c.date_of_birth,
    c.email,
    c.phone,
    c.postal_code,
    c.city
   FROM ((public.patients p
     JOIN public.persons pe ON ((pe.id = p.person_id)))
     LEFT JOIN public.patient_contact_details c ON ((c.patient_id = p.id)));

COMMENT ON VIEW public.patient_list_entries IS 'Schlanke Projektion fuer die Patientenliste (ADR-004, R3-012): Name, Geburtsdatum, Ort, Postleitzahl, Telefon, E-Mail und Status - genau das, was die Liste zeigt und wonach sie sucht. Keine Versorgungsangaben, keine Strasse, keine feste Therapeut:in; dafuer gibt es patient_directory in der Akte. security_invoker: die RLS der Basistabellen gilt unveraendert.';

CREATE TABLE public.patient_merge_records (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    target_patient_id uuid NOT NULL,
    source_patient_id uuid NOT NULL,
    merged_at timestamp with time zone DEFAULT now() NOT NULL,
    merged_by uuid,
    counts jsonb NOT NULL,
    photos_deleted integer DEFAULT 0 NOT NULL,
    CONSTRAINT patient_merge_records_counts_check CHECK ((jsonb_typeof(counts) = 'object'::text)),
    CONSTRAINT patient_merge_records_photos_deleted_check CHECK ((photos_deleted >= 0))
);

COMMENT ON TABLE public.patient_merge_records IS 'Nachweis des Zusammenfuehrens zweier Akten an der bleibenden Akte (ABN-018, BEF-108, ANN-150 Fassung 2). Lebt so lange wie die Akte (FK on delete cascade, Klasse patientenakte), nicht nur drei Jahre wie das Auditlog. Kein direkter Zugriff.';

CREATE TABLE public.patient_privacy_records (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    record_kind text NOT NULL,
    purpose text,
    notice_version text,
    occurred_on date NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by uuid,
    source text DEFAULT 'practice'::text NOT NULL,
    platform_access_id uuid,
    platform_access_kind text,
    representative_name text,
    wording_version text,
    CONSTRAINT patient_privacy_records_notice_version_check CHECK ((notice_version ~ '^[0-9]{4}-[0-9]{2}$'::text)),
    CONSTRAINT patient_privacy_records_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT patient_privacy_records_purpose_check CHECK ((purpose = ANY (ARRAY['email_contact'::text, 'prescriber_report'::text, 'patient_photos'::text, 'message_attachments'::text]))),
    CONSTRAINT patient_privacy_records_purpose_shape CHECK (((record_kind = ANY (ARRAY['consent_granted'::text, 'consent_withdrawn'::text, 'consent_refused'::text])) = (purpose IS NOT NULL))),
    CONSTRAINT patient_privacy_records_record_kind_check CHECK ((record_kind = ANY (ARRAY['privacy_notice_handed_out'::text, 'treatment_contract_signed'::text, 'consent_granted'::text, 'consent_withdrawn'::text, 'consent_refused'::text]))),
    CONSTRAINT patient_privacy_records_representative_name_check CHECK (((representative_name IS NULL) OR ((length(btrim(representative_name)) >= 1) AND (length(btrim(representative_name)) <= 200)))),
    CONSTRAINT patient_privacy_records_representative_shape CHECK (((NOT (platform_access_kind IS DISTINCT FROM 'legal_representative'::text)) = (representative_name IS NOT NULL))),
    CONSTRAINT patient_privacy_records_source_check CHECK ((source = ANY (ARRAY['practice'::text, 'platform'::text]))),
    CONSTRAINT patient_privacy_records_source_shape CHECK ((((source = 'platform'::text) AND (record_kind = ANY (ARRAY['consent_granted'::text, 'consent_withdrawn'::text])) AND (platform_access_id IS NOT NULL) AND (platform_access_kind IS NOT NULL) AND (wording_version IS NOT NULL)) OR ((source = 'practice'::text) AND (platform_access_id IS NULL) AND (platform_access_kind IS NULL) AND (wording_version IS NULL)))),
    CONSTRAINT patient_privacy_records_version_shape CHECK (((record_kind = 'privacy_notice_handed_out'::text) = (notice_version IS NOT NULL))),
    CONSTRAINT patient_privacy_records_wording_version_check CHECK ((wording_version ~ '^[0-9]{4}-[0-9]{2}$'::text))
);

COMMENT ON TABLE public.patient_privacy_records IS 'Vermerke zu Datenschutzinformation, Behandlungsvertrag und Einwilligungen je Zweck (PAT-006, ANN-093). Nur anhaengen, nie aendern: der Stand eines Zwecks ist seine juengste Zeile. Die Dokumente selbst bleiben Papier. Datenklasse: Patientenakte, faellt mit der Akte.';

COMMENT ON COLUMN public.patient_privacy_records.occurred_on IS 'Datum auf dem Papier (ausgehaendigt, unterschrieben, erteilt, widerrufen) - nicht das der Eingabe, das steht in recorded_at.';

COMMENT ON COLUMN public.patient_privacy_records.source IS 'POR-016: practice = Vermerk der Praxis vom Papier (PAT-006); platform = die Person oder ihre rechtliche Vertretung auf der Plattform.';

COMMENT ON COLUMN public.patient_privacy_records.platform_access_id IS 'POR-016: der Zugang, ueber den der Vermerk entstand. Ohne FK: der Zugang faellt drei Jahre nach seinem Ende, der Vermerk mit der Akte.';

COMMENT ON COLUMN public.patient_privacy_records.representative_name IS 'POR-016: bei einer rechtlichen Vertretung ihr Name als Teil des Nachweises (ADR-023 Konsequenzen), weil Konto und Zugang frueher fallen.';

COMMENT ON COLUMN public.patient_privacy_records.wording_version IS 'POR-016 (ANN-262): die Fassung des Einwilligungstexts, die die Person auf der Plattform gesehen hat (src/features/platform/einwilligungstexte.ts).';

CREATE TABLE public.patient_questionnaire_responses (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    instrument_id text NOT NULL,
    definition_version text NOT NULL,
    status text DEFAULT 'entwurf'::text NOT NULL,
    recorded_on date NOT NULL,
    answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    supersedes_response_id uuid,
    change_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    completed_at timestamp with time zone,
    completed_by uuid,
    source text DEFAULT 'practice'::text NOT NULL,
    source_access_id uuid,
    CONSTRAINT patient_questionnaire_responses_answers_shape CHECK (((jsonb_typeof(answers) = 'object'::text) AND (octet_length((answers)::text) <= 65536))),
    CONSTRAINT patient_questionnaire_responses_change_reason_check CHECK (((change_reason IS NULL) OR ((length(btrim(change_reason)) >= 3) AND (length(btrim(change_reason)) <= 500)))),
    CONSTRAINT patient_questionnaire_responses_completion_shape CHECK (((status = 'abgeschlossen'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT patient_questionnaire_responses_correction_shape CHECK (((supersedes_response_id IS NULL) = (change_reason IS NULL))),
    CONSTRAINT patient_questionnaire_responses_definition_version_check CHECK ((definition_version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'::text)),
    CONSTRAINT patient_questionnaire_responses_instrument_id_check CHECK (((instrument_id ~ '^[a-z][a-z0-9_]*$'::text) AND (length(instrument_id) <= 80))),
    CONSTRAINT patient_questionnaire_responses_source_access CHECK (((source_access_id IS NULL) OR (source = 'platform'::text))),
    CONSTRAINT patient_questionnaire_responses_source_check CHECK ((source = ANY (ARRAY['practice'::text, 'platform'::text]))),
    CONSTRAINT patient_questionnaire_responses_status_check CHECK ((status = ANY (ARRAY['entwurf'::text, 'abgeschlossen'::text])))
);

COMMENT ON TABLE public.patient_questionnaire_responses IS 'Erhobene Fragebögen der Akte (FRB-EPIC-002, PROJECT_PRINCIPLES.md 7). Abgeschlossen unveraenderlich; Korrektur als neue Erhebung mit Verweis und Begruendung (ANN-103). Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: Patientenakte, faellt mit der Akte.';

COMMENT ON COLUMN public.patient_questionnaire_responses.answers IS 'Kennung des Items -> Antwort. Auswahl speichert die Kennung der Option (ANN-102). Gegen die Definition geprueft in der Anwendung (ANN-105).';

COMMENT ON COLUMN public.patient_questionnaire_responses.source IS 'POR-012: practice (in der Praxis erhoben) oder platform (von der Person ueber die Plattform ausgefuellt, ANN-248).';

COMMENT ON COLUMN public.patient_questionnaire_responses.source_access_id IS 'POR-012: der Plattformzugang, ueber den die Erhebung entstand (Person oder Vertretung, ADR-023 Punkt 14).';

CREATE TABLE public.payments (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    direction text NOT NULL,
    amount_cents integer NOT NULL,
    currency text NOT NULL,
    paid_on date NOT NULL,
    method text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    offset_group uuid,
    CONSTRAINT payments_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT payments_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT payments_direction_check CHECK ((direction = ANY (ARRAY['incoming'::text, 'refund'::text]))),
    CONSTRAINT payments_method_check CHECK ((method = ANY (ARRAY['bank_transfer'::text, 'other'::text, 'offset'::text]))),
    CONSTRAINT payments_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 200)))),
    CONSTRAINT payments_offset_group_iff_offset CHECK (((method = 'offset'::text) = (offset_group IS NOT NULL))),
    CONSTRAINT payments_void_is_complete CHECK ((((voided_at IS NULL) AND (voided_by IS NULL) AND (void_reason IS NULL)) OR ((voided_at IS NOT NULL) AND (voided_by IS NOT NULL) AND (void_reason IS NOT NULL)))),
    CONSTRAINT payments_void_reason_check CHECK (((void_reason IS NULL) OR ((length(btrim(void_reason)) >= 3) AND (length(btrim(void_reason)) <= 200))))
);

COMMENT ON TABLE public.payments IS 'Zahlungseingang oder Rueckzahlung zu einer ausgestellten Rechnung (ABR-004, ADR-009 Punkt 12). Eigene Transaktion: Der Zahlungsstand der Rechnung wird daraus gerechnet und nirgends gepflegt. Enthaelt ueber die Rechnung einen Patientenbezug, aber keine klinischen Angaben. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen dieser Migration (ADR-004).';

COMMENT ON COLUMN public.payments.direction IS 'incoming = Eingang, refund = Rueckzahlung. Eigene Richtung statt negativem Betrag: ein negativer Betrag gaebe derselben Spalte zwei Bedeutungen.';

COMMENT ON COLUMN public.payments.amount_cents IS 'Betrag in ganzen Cent, immer positiv (ADR-014). Die Richtung steht in direction.';

COMMENT ON COLUMN public.payments.paid_on IS 'Tag des Zahlungseingangs beziehungsweise der Rueckzahlung in der Zeitzone der Praxis - nicht der Tag der Erfassung. Der steht in created_at.';

COMMENT ON COLUMN public.payments.voided_at IS 'Gesetzt heisst: storniert und aus jeder Summe heraus. Die Zeile bleibt sichtbar stehen (ADR-009 Punkt 9 sinngemaess); geaendert oder geloescht wird eine Zahlung nie.';

COMMENT ON COLUMN public.payments.offset_group IS 'Verbindet die beiden Buchungen einer Verrechnung (ABN-008): refund an der stornierten Rechnung, incoming an der Ersatzrechnung. Genau dann gesetzt, wenn method = offset.';

CREATE TABLE public.platform_access_invitations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    platform_access_id uuid NOT NULL,
    purpose text NOT NULL,
    channel text NOT NULL,
    code_hash text NOT NULL,
    email text,
    address_confirmed_by uuid,
    address_confirmed_at timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    sent_at timestamp with time zone,
    failed_attempts smallint DEFAULT 0 NOT NULL,
    redeemed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT platform_access_invitations_channel_check CHECK ((channel = ANY (ARRAY['on_site'::text, 'email'::text]))),
    CONSTRAINT platform_access_invitations_code_hash_check CHECK ((code_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT platform_access_invitations_email_channel CHECK (((channel = 'on_site'::text) OR ((address_confirmed_by IS NOT NULL) AND (address_confirmed_at IS NOT NULL)))),
    CONSTRAINT platform_access_invitations_email_check CHECK (((email IS NULL) OR ((email = lower(btrim(email))) AND (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text)))),
    CONSTRAINT platform_access_invitations_failed_attempts_check CHECK ((failed_attempts BETWEEN 0 AND 5)),
    CONSTRAINT platform_access_invitations_on_site_without_email CHECK (((channel = 'email'::text) OR ((email IS NULL) AND (sent_at IS NULL)))),
    CONSTRAINT platform_access_invitations_purpose_check CHECK ((purpose = ANY (ARRAY['activate'::text, 'reset'::text]))),
    CONSTRAINT platform_access_invitations_redeemed_stamp CHECK (((status = 'redeemed'::text) = (redeemed_at IS NOT NULL))),
    CONSTRAINT platform_access_invitations_revoked_stamp CHECK (((status = 'revoked'::text) = (revoked_at IS NOT NULL))),
    CONSTRAINT platform_access_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'redeemed'::text, 'revoked'::text])))
);

COMMENT ON TABLE public.platform_access_invitations IS 'Einladung zu einem Plattformzugang (ADR-023 Punkte 7, 8, 11). Nur der Hash des Codes ist gespeichert. Faellt mit ihrem Zugang.';

COMMENT ON COLUMN public.platform_access_invitations.code_hash IS 'SHA-256 des einmaligen Codes, hexadezimal. Der Code selbst wird nie gespeichert und nie protokolliert (ADR-011).';

CREATE TABLE public.platform_account_deletions (
    account_user_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    run_id uuid,
    due_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    ordered_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    attempts smallint DEFAULT 0 NOT NULL,
    CONSTRAINT platform_account_deletions_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT platform_account_deletions_reason_check CHECK ((reason = ANY (ARRAY['retention'::text, 'unbound'::text, 'reapply'::text])))
);

COMMENT ON TABLE public.platform_account_deletions IS 'Loeschauftraege fuer Plattformkonten beim Anmeldedienst (ABN-011, BEF-115). Der Loeschlauf gibt sie, der Zugangsdienst fuehrt sie ueber die Admin-API aus und bestaetigt; die Bestaetigung schreibt das Loeschjournal und entfernt den Auftrag. Enthaelt nur Kennungen und Fristen. Kein Tabellenrecht, keine Policy: nur ueber die Funktionen dieser Migration.';

CREATE TABLE public.platform_appointment_requests (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    relationship_kind text NOT NULL,
    relationship_id uuid NOT NULL,
    patient_id uuid,
    training_relationship_id uuid,
    appointment_id uuid,
    kind text NOT NULL,
    preferred_days date[] DEFAULT '{}'::date[] NOT NULL,
    preferred_times text[] DEFAULT '{}'::text[] NOT NULL,
    note text,
    status text DEFAULT 'open'::text NOT NULL,
    created_by_access_id uuid NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    answer text,
    resulting_appointment_id uuid,
    CONSTRAINT platform_appointment_requests_answer_check CHECK (((answer IS NULL) OR ((length(btrim(answer)) >= 1) AND (length(btrim(answer)) <= 300)))),
    CONSTRAINT platform_appointment_requests_answer_needs_resolution CHECK (((answer IS NULL) OR (status = ANY (ARRAY['done'::text, 'declined'::text])))),
    CONSTRAINT platform_appointment_requests_kind_check CHECK ((kind = ANY (ARRAY['new'::text, 'change'::text, 'cancel'::text]))),
    CONSTRAINT platform_appointment_requests_kind_fields CHECK ((((kind = 'new'::text) AND (appointment_id IS NULL) AND (cardinality(preferred_days) >= 1)) OR (kind = ANY (ARRAY['change'::text, 'cancel'::text])))),
    CONSTRAINT platform_appointment_requests_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 500)))),
    CONSTRAINT platform_appointment_requests_preferred_days_check CHECK ((cardinality(preferred_days) <= 14)),
    CONSTRAINT platform_appointment_requests_preferred_times_check CHECK ((preferred_times <@ ARRAY['morning'::text, 'midday'::text, 'afternoon'::text])),
    CONSTRAINT platform_appointment_requests_relationship_kind_check CHECK ((relationship_kind = ANY (ARRAY['treatment'::text, 'training'::text]))),
    CONSTRAINT platform_appointment_requests_relationship_matches CHECK ((((relationship_kind = 'treatment'::text) AND (training_relationship_id IS NULL) AND (patient_id = relationship_id)) OR ((relationship_kind = 'training'::text) AND (patient_id IS NULL) AND (training_relationship_id = relationship_id)))),
    CONSTRAINT platform_appointment_requests_resolution_stamp CHECK (((status = 'open'::text) = (resolved_at IS NULL))),
    CONSTRAINT platform_appointment_requests_resolved_by_needs_at CHECK (((resolved_by IS NULL) OR (resolved_at IS NOT NULL))),
    CONSTRAINT platform_appointment_requests_result_needs_done CHECK (((resulting_appointment_id IS NULL) OR (status = 'done'::text))),
    CONSTRAINT platform_appointment_requests_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'declined'::text, 'withdrawn'::text])))
);

COMMENT ON TABLE public.platform_appointment_requests IS 'Terminwunsch ueber die Plattform (POR-009, ANN-246): Tage und Tageszeiten oder eine Aenderung bzw. Absage am eigenen Termin; einen Termin macht daraus das Buero (PROJECT_PRINCIPLES.md 8). Datenklasse: Terminwunsch, zwoelf Monate nach der Antwort.';

COMMENT ON COLUMN public.platform_appointment_requests.created_by IS 'auth.users.id des schreibenden Kontos; bei einer Vertretung das Konto der vertretenden Person (ADR-023 Punkt 14).';

-- ANN-218
CREATE TABLE public.platform_mailbox_confirmations (
    account_user_id uuid NOT NULL,
    email text NOT NULL,
    confirmed_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_via text NOT NULL,
    CONSTRAINT platform_mailbox_confirmations_confirmed_via_check CHECK ((confirmed_via = 'link'::text)),
    CONSTRAINT platform_mailbox_confirmations_email_check CHECK (((email = lower(btrim(email))) AND (length(email) BETWEEN 3 AND 254)))
);

COMMENT ON TABLE public.platform_mailbox_confirmations IS 'Eigenes Merkmal: Das Postfach eines Plattformkontos ist per Link bestaetigt, fuer genau diese Adresse (ABN-012, BEF-118). Der Bestaetigungsstatus des Anmeldedienstes zaehlt nicht. Faellt mit dem Konto. Kein Tabellenrecht, keine Policy.';

CREATE TABLE public.platform_message_entries (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    message_id uuid NOT NULL,
    side text NOT NULL,
    body text NOT NULL,
    access_id uuid,
    author_kind text NOT NULL,
    author_label text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    attachment_id uuid,
    attachment_mark_seconds smallint,
    CONSTRAINT platform_message_entries_attachment_mark_seconds_check CHECK ((attachment_mark_seconds BETWEEN 0 AND 30)),
    CONSTRAINT platform_message_entries_author_kind_check CHECK ((author_kind = ANY (ARRAY['self'::text, 'legal_representative'::text, 'companion'::text, 'staff'::text]))),
    CONSTRAINT platform_message_entries_author_label_check CHECK (((author_label IS NULL) OR ((length(btrim(author_label)) >= 1) AND (length(btrim(author_label)) <= 160)))),
    CONSTRAINT platform_message_entries_body_check CHECK (((length(btrim(body)) >= 1) AND (length(btrim(body)) <= 2000))),
    CONSTRAINT platform_message_entries_label CHECK (((author_kind = 'self'::text) = (author_label IS NULL))),
    CONSTRAINT platform_message_entries_mark_complete CHECK (((attachment_id IS NULL) OR (attachment_mark_seconds IS NOT NULL))),
    CONSTRAINT platform_message_entries_mark_practice CHECK (((attachment_mark_seconds IS NULL) OR (side = 'practice'::text))),
    CONSTRAINT platform_message_entries_side_check CHECK ((side = ANY (ARRAY['person'::text, 'practice'::text]))),
    CONSTRAINT platform_message_entries_side_fields CHECK ((((side = 'person'::text) AND (author_kind = ANY (ARRAY['self'::text, 'legal_representative'::text, 'companion'::text]))) OR ((side = 'practice'::text) AND (author_kind = 'staff'::text) AND (access_id IS NULL))))
);

COMMENT ON TABLE public.platform_message_entries IS 'KOM-001: Eintraege eines Vorgangs - Frage, Antwort der Praxis, Nachtrag (ANN-308). Unveraenderlich; fallen mit dem Vorgang. Datenklasse wie der Vorgang. Kein Tabellenrecht.';

COMMENT ON COLUMN public.platform_message_entries.attachment_mark_seconds IS 'KOM-005 (ADR-017 Punkt 68, ANN-338): die Stelle im Video, auf die die Antwort der Praxis zeigt ("bei 0:12"). Bleibt, wenn das Video nach seiner Frist faellt.';

CREATE TABLE public.platform_notification_settings (
    access_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    email_kinds text[] DEFAULT '{}'::text[] NOT NULL,
    push_kinds text[] DEFAULT '{}'::text[] NOT NULL,
    quiet_from smallint,
    quiet_until smallint,
    chosen_at timestamp with time zone DEFAULT now() NOT NULL,
    chosen_by uuid NOT NULL,
    CONSTRAINT platform_notification_settings_email_kinds_check CHECK ((email_kinds <@ app.notification_kinds())),
    CONSTRAINT platform_notification_settings_push_kinds_check CHECK ((push_kinds <@ app.notification_kinds())),
    CONSTRAINT platform_notification_settings_quiet_both CHECK (((quiet_from IS NULL) = (quiet_until IS NULL))),
    CONSTRAINT platform_notification_settings_quiet_from_check CHECK ((quiet_from BETWEEN 0 AND 23)),
    CONSTRAINT platform_notification_settings_quiet_until_check CHECK ((quiet_until BETWEEN 0 AND 23))
);

COMMENT ON TABLE public.platform_notification_settings IS 'KOM-009 (ADR-024 Punkt 15): welche Arten ein Plattformzugang auf welchem Weg bekommen will, mit Ruhezeit und Zeitpunkt der Wahl. Ohne Zeile ist alles aus. Je Zugang - eine Vertretung waehlt fuer ihren Zugang selbst. Kein Tabellenrecht: nur ueber die Funktionen dieser Migration.';

CREATE TABLE public.platform_push_subscriptions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    access_id uuid NOT NULL,
    endpoint text NOT NULL,
    p256dh text NOT NULL,
    auth_secret text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_push_subscriptions_auth_secret_check CHECK ((auth_secret ~ '^[A-Za-z0-9_-]{22}$'::text)),
    CONSTRAINT platform_push_subscriptions_endpoint_check CHECK (app.push_endpoint_allowed(endpoint)),
    CONSTRAINT platform_push_subscriptions_p256dh_check CHECK ((p256dh ~ '^[A-Za-z0-9_-]{87}$'::text))
);

COMMENT ON TABLE public.platform_push_subscriptions IS 'KOM-009 (ADR-024 Punkt 17): Push-Registrierung eines Geraets fuer einen Zugang. Faellt beim Abmelden auf dem Geraet, wenn der Push-Dienst den Endpunkt abweist, mit dem Ende des Zugangs und mit dem Konto.';

CREATE TABLE public.practice_billing_profiles (
    organization_id uuid NOT NULL,
    legal_name text NOT NULL,
    street text NOT NULL,
    house_number text,
    postal_code text NOT NULL,
    city text NOT NULL,
    phone text,
    email text,
    tax_number text,
    vat_id text,
    small_business boolean NOT NULL,
    bank_name text,
    account_holder text,
    iban text NOT NULL,
    bic text,
    invoice_number_prefix text DEFAULT 'RG'::text NOT NULL,
    payment_term_days smallint DEFAULT 14 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    training_invoice_number_prefix text DEFAULT 'TR'::text NOT NULL,
    CONSTRAINT practice_billing_profiles_account_holder_check CHECK (((account_holder IS NULL) OR ((length(btrim(account_holder)) >= 1) AND (length(btrim(account_holder)) <= 200)))),
    CONSTRAINT practice_billing_profiles_bank_name_check CHECK (((bank_name IS NULL) OR ((length(btrim(bank_name)) >= 1) AND (length(btrim(bank_name)) <= 120)))),
    CONSTRAINT practice_billing_profiles_bic_check CHECK (((bic IS NULL) OR (bic ~ '^[A-Z0-9]{8}([A-Z0-9]{3})?$'::text))),
    CONSTRAINT practice_billing_profiles_city_check CHECK (((length(btrim(city)) >= 1) AND (length(btrim(city)) <= 120))),
    CONSTRAINT practice_billing_profiles_email_check CHECK (((email IS NULL) OR (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT practice_billing_profiles_house_number_check CHECK (((house_number IS NULL) OR ((length(btrim(house_number)) >= 1) AND (length(btrim(house_number)) <= 20)))),
    CONSTRAINT practice_billing_profiles_iban_check CHECK ((iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$'::text)),
    CONSTRAINT practice_billing_profiles_iban_checksum CHECK (app.iban_checksum_ok(iban)),
    CONSTRAINT practice_billing_profiles_invoice_number_prefix_check CHECK ((invoice_number_prefix ~ '^[A-Z0-9-]{1,10}$'::text)),
    CONSTRAINT practice_billing_profiles_legal_name_check CHECK (((length(btrim(legal_name)) >= 1) AND (length(btrim(legal_name)) <= 200))),
    CONSTRAINT practice_billing_profiles_payment_term_days_check CHECK ((payment_term_days BETWEEN 0 AND 90)),
    CONSTRAINT practice_billing_profiles_phone_check CHECK (((phone IS NULL) OR ((length(btrim(phone)) >= 3) AND (length(btrim(phone)) <= 40)))),
    CONSTRAINT practice_billing_profiles_postal_code_check CHECK (((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12))),
    CONSTRAINT practice_billing_profiles_prefixes_differ CHECK ((invoice_number_prefix <> training_invoice_number_prefix)),
    CONSTRAINT practice_billing_profiles_street_check CHECK (((length(btrim(street)) >= 1) AND (length(btrim(street)) <= 120))),
    CONSTRAINT practice_billing_profiles_tax_id_present CHECK (((tax_number IS NOT NULL) OR (vat_id IS NOT NULL))),
    CONSTRAINT practice_billing_profiles_tax_number_check CHECK (((tax_number IS NULL) OR ((length(btrim(tax_number)) >= 3) AND (length(btrim(tax_number)) <= 40)))),
    CONSTRAINT practice_billing_profiles_training_invoice_number_prefix_check CHECK ((training_invoice_number_prefix ~ '^[A-Z0-9-]{1,10}$'::text)),
    CONSTRAINT practice_billing_profiles_vat_id_check CHECK (((vat_id IS NULL) OR ((length(btrim(vat_id)) >= 3) AND (length(btrim(vat_id)) <= 20))))
);

COMMENT ON TABLE public.practice_billing_profiles IS 'Praxis-Stammdaten fuer Rechnungen (ABR-000, ADR-009 Punkt 10): Absender, Bankverbindung, Steuernummer und umsatzsteuerlicher Status. Enthaelt KEINE Patientendaten. Datenklasse: Abrechnungsdaten, steuerliche Frist (ADR-008). Lesbar fuer owner und office; geschrieben ausschliesslich ueber save_practice_billing_profile.';

COMMENT ON COLUMN public.practice_billing_profiles.tax_number IS 'Steuernummer der Praxis. Seit ABN-008 optional, wenn eine USt-IdNr. eingetragen ist - eine von beiden muss stehen (Par. 14 Abs. 4 Nr. 2 UStG, Constraint practice_billing_profiles_tax_id_present).';

COMMENT ON COLUMN public.practice_billing_profiles.small_business IS 'Kleinunternehmerregelung nach Par. 19 UStG: true heisst, die Rechnung weist keine Umsatzsteuer aus und traegt den Hinweis. Ohne Vorgabewert - die Software raet den steuerlichen Status nicht (ANN-074, G13 offen).';

COMMENT ON COLUMN public.practice_billing_profiles.iban IS 'Bankverbindung der Praxis. Im Seed eine synthetische IBAN; echte Kontodaten traegt allein die Praxis in ihrer eigenen Umgebung ein.';

COMMENT ON COLUMN public.practice_billing_profiles.invoice_number_prefix IS 'Kuerzel vor der Rechnungsnummer im Bereich **Behandlung** (ADR-009 Punkt 17). Das Format der Nummer selbst legt app.next_invoice_number fest (ANN-075); hier steht nur, was die Praxis daran waehlen darf.';

COMMENT ON COLUMN public.practice_billing_profiles.payment_term_days IS 'Zahlungsziel in Tagen ab Ausstellung. Geht in den Snapshot und bestimmt das Faelligkeitsdatum der ausgestellten Rechnung (ADR-009 Punkt 10). Mahnwesen und Ueberfaelligkeit entscheidet ABR-EPIC-003, nicht diese Spalte.';

COMMENT ON COLUMN public.practice_billing_profiles.training_invoice_number_prefix IS 'Kuerzel vor der Rechnungsnummer im Bereich **Training** (ABR-010, ADR-009 Punkt 17). Es muss sich vom Kuerzel der Behandlung unterscheiden - sonst waeren zwei lueckenlose Kreise ueber alle Kreise nicht mehr eindeutig, und am Dokument waere nicht erkennbar, aus welchem seine Nummer stammt.';

COMMENT ON CONSTRAINT practice_billing_profiles_prefixes_differ ON public.practice_billing_profiles IS 'Zwei Nummernkreise, zwei Kuerzel (ADR-009 Punkt 17): "jede vergebene Nummer bleibt innerhalb der Organisation einmalig".';

-- ANN-004
CREATE TABLE public.practice_targets (
    organization_id uuid NOT NULL,
    revenue_cents integer,
    open_items_cents integer,
    utilization_percent smallint,
    ending_bases integer,
    absences integer,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT practice_targets_absences_check CHECK (((absences IS NULL) OR (absences BETWEEN 0 AND 10000))),
    CONSTRAINT practice_targets_ending_bases_check CHECK (((ending_bases IS NULL) OR (ending_bases BETWEEN 0 AND 10000))),
    CONSTRAINT practice_targets_open_items_cents_check CHECK (((open_items_cents IS NULL) OR (open_items_cents BETWEEN 0 AND 100000000))),
    CONSTRAINT practice_targets_revenue_cents_check CHECK (((revenue_cents IS NULL) OR (revenue_cents BETWEEN 0 AND 100000000))),
    CONSTRAINT practice_targets_utilization_percent_check CHECK (((utilization_percent IS NULL) OR (utilization_percent BETWEEN 0 AND 100)))
);

COMMENT ON TABLE public.practice_targets IS 'Zielwerte zu den Kennzahlen der Praxisfuehrung (STA-002): Umsatz, offene Posten, Auslastung, Verordnungen ohne Anschluss, Ausfaelle. Keine Patientendaten; updated_by nennt das Konto der letzten Aenderung. Kein direkter Zugriff; lesen und schreiben allein owner ueber get_practice_targets und set_practice_target. Datenklasse: Stammdaten der Praxis, faellt mit der Organisation.';

CREATE TABLE public.prescribers (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    title text,
    given_name text,
    family_name text NOT NULL,
    practice_name text,
    speciality text,
    street text,
    house_number text,
    postal_code text,
    city text,
    phone text,
    fax text,
    email text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT prescribers_city_check CHECK (((city IS NULL) OR ((length(btrim(city)) >= 1) AND (length(btrim(city)) <= 100)))),
    CONSTRAINT prescribers_email_check CHECK (((email IS NULL) OR (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT prescribers_family_name_check CHECK (((length(btrim(family_name)) >= 1) AND (length(btrim(family_name)) <= 100))),
    CONSTRAINT prescribers_fax_check CHECK (((fax IS NULL) OR ((length(btrim(fax)) >= 3) AND (length(btrim(fax)) <= 40)))),
    CONSTRAINT prescribers_given_name_check CHECK (((given_name IS NULL) OR ((length(btrim(given_name)) >= 1) AND (length(btrim(given_name)) <= 100)))),
    CONSTRAINT prescribers_house_number_check CHECK (((house_number IS NULL) OR ((length(btrim(house_number)) >= 1) AND (length(btrim(house_number)) <= 20)))),
    CONSTRAINT prescribers_phone_check CHECK (((phone IS NULL) OR ((length(btrim(phone)) >= 3) AND (length(btrim(phone)) <= 40)))),
    CONSTRAINT prescribers_postal_code_check CHECK (((postal_code IS NULL) OR ((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12)))),
    CONSTRAINT prescribers_practice_name_check CHECK (((practice_name IS NULL) OR ((length(btrim(practice_name)) >= 1) AND (length(btrim(practice_name)) <= 200)))),
    CONSTRAINT prescribers_speciality_check CHECK (((speciality IS NULL) OR ((length(btrim(speciality)) >= 1) AND (length(btrim(speciality)) <= 100)))),
    CONSTRAINT prescribers_street_check CHECK (((street IS NULL) OR ((length(btrim(street)) >= 1) AND (length(btrim(street)) <= 200)))),
    CONSTRAINT prescribers_title_check CHECK (((title IS NULL) OR ((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 60))))
);

COMMENT ON TABLE public.prescribers IS 'Verordner:innen (VER-001, ANN-013). Berufliche Kontaktdaten Dritter, kein Patientenbezug. Datenklasse: Stammdaten; aufbewahrt, solange eine Verordnung darauf verweist.';

COMMENT ON COLUMN public.prescribers.speciality IS 'Fachrichtung als Freitext, etwa "Orthopaedie". Bewusst kein Katalog: er waere Pflege ohne Nutzen.';

CREATE TABLE public.questionnaire_definitions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    instrument_id text NOT NULL,
    version text NOT NULL,
    definition jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT questionnaire_definitions_definition_check CHECK ((jsonb_typeof(definition) = 'object'::text)),
    CONSTRAINT questionnaire_definitions_instrument_id_check CHECK (((instrument_id ~ '^[a-z][a-z0-9_]*$'::text) AND (length(instrument_id) <= 80))),
    CONSTRAINT questionnaire_definitions_matches_meta CHECK (((((definition -> 'meta'::text) ->> 'id'::text) = instrument_id) AND (((definition -> 'meta'::text) ->> 'version'::text) = version))),
    CONSTRAINT questionnaire_definitions_version_check CHECK ((version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'::text))
);

COMMENT ON TABLE public.questionnaire_definitions IS 'Fassungen der Fragebogen-Definitionen fuer die Serverpruefung der Antworten (ABN-014, BEF-101). Erzeugt aus src/features/assessments/definitionen/scores/ durch scripts/definitionen-sql.mjs (ANN-219). Produktinhalt ohne Personenbezug; eine Fassung wird nie geaendert.';

CREATE TABLE public.retention_assignments (
    table_name text NOT NULL,
    class_key text NOT NULL,
    deletion_mode text NOT NULL,
    scope_note text NOT NULL,
    sort_order smallint DEFAULT 100 NOT NULL,
    CONSTRAINT retention_assignments_deletion_mode_check CHECK ((deletion_mode = ANY (ARRAY['automatisch'::text, 'ueber_elterndatensatz'::text, 'keine'::text]))),
    CONSTRAINT retention_assignments_scope_note_check CHECK (((length(btrim(scope_note)) >= 1) AND (length(btrim(scope_note)) <= 1000))),
    CONSTRAINT retention_assignments_table_name_check CHECK ((table_name ~ '^[a-z_]+$'::text))
);

COMMENT ON TABLE public.retention_assignments IS 'Zuordnung Tabelle zu Datenklasse samt Loeschweg (ADR-008, ADR-014). Vollstaendigkeit gegen pg_tables prueft supabase/tests/retention.test.ts. Datenklasse: Konfiguration, kein Personenbezug.';

CREATE TABLE public.retention_classes (
    key text NOT NULL,
    basis text NOT NULL,
    legal_reference text,
    anchor text NOT NULL,
    retention_interval interval,
    assumption_key text,
    note text NOT NULL,
    sort_order smallint DEFAULT 100 NOT NULL,
    upper_bound_anchor text,
    upper_bound_interval interval,
    CONSTRAINT retention_classes_anchor_check CHECK ((anchor = ANY (ARRAY['care_concluded'::text, 'contract_ended'::text, 'counselling_ended'::text, 'calendar_year_end'::text, 'event_time'::text, 'case_closed'::text, 'none'::text]))),
    CONSTRAINT retention_classes_assumption_key_check CHECK (((assumption_key IS NULL) OR (assumption_key ~ '^ANN-[0-9]{3}$'::text))),
    CONSTRAINT retention_classes_basis_check CHECK ((basis = ANY (ARRAY['gesetzlich'::text, 'gesetzlich_gepraegt'::text, 'intern'::text, 'abgeleitet'::text, 'offen'::text]))),
    CONSTRAINT retention_classes_interval_matches_anchor CHECK ((((anchor = 'none'::text) AND (retention_interval IS NULL)) OR ((anchor <> 'none'::text) AND (retention_interval IS NOT NULL)))),
    CONSTRAINT retention_classes_key_check CHECK ((key ~ '^[a-z_]+$'::text)),
    CONSTRAINT retention_classes_legal_reference_check CHECK (((legal_reference IS NULL) OR ((length(btrim(legal_reference)) >= 1) AND (length(btrim(legal_reference)) <= 200)))),
    CONSTRAINT retention_classes_note_check CHECK (((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 1000))),
    CONSTRAINT retention_classes_upper_bound_anchor_check CHECK (((upper_bound_anchor IS NULL) OR (upper_bound_anchor = 'care_concluded_recorded'::text))),
    CONSTRAINT retention_classes_upper_bound_complete CHECK (((upper_bound_anchor IS NULL) = (upper_bound_interval IS NULL)))
);

COMMENT ON TABLE public.retention_classes IS 'Retention Schedule nach ADR-008: Datenklasse, Frist, Anker und Grundlage. Die einzige Stelle, an der eine Frist steht (ANN-001). Datenklasse: Konfiguration, kein Personenbezug.';

COMMENT ON COLUMN public.retention_classes.basis IS 'gesetzlich: Frist steht im Gesetz. gesetzlich_gepraegt: folgt einer gesetzlichen Frist an anderer Stelle. intern: Initialentscheidung aus ADR-008, validierungsbeduerftig (ANN-001). abgeleitet: folgt einer anderen Klasse. offen: Frist noch nicht entschieden, deshalb keine automatische Loeschung.';

COMMENT ON COLUMN public.retention_classes.retention_interval IS 'Aufbewahrungsdauer ab dem Anker. Leer bedeutet: keine automatische Loeschung; die Begruendung steht in note.';

COMMENT ON COLUMN public.retention_classes.assumption_key IS 'Eintrag in docs/decisions/ASSUMPTIONS.md, der diese Frist traegt. Leer nur bei gesetzlich bestimmten Fristen.';

COMMENT ON COLUMN public.retention_classes.upper_bound_anchor IS 'Optionaler zweiter Anker: Faellig ist der Datensatz zum fruehesten von Frist und Obergrenze. care_concluded_recorded ist patients.care_concluded_at - der Zeitpunkt, zu dem die Praxis den Abschluss festhaelt, nicht der ruecknehmbare Tag (ADR-017 Punkt 38).';

COMMENT ON COLUMN public.retention_classes.upper_bound_interval IS 'Intervall der optionalen Obergrenze ab upper_bound_anchor (ADR-017 Punkt 38). Leer genau dann, wenn es keine Obergrenze gibt.';

CREATE TABLE public.roles (
    key text NOT NULL,
    label text NOT NULL,
    description text NOT NULL,
    sort_order smallint DEFAULT 100 NOT NULL,
    CONSTRAINT roles_key_check CHECK ((key ~ '^[a-z_]+$'::text))
);

COMMENT ON TABLE public.roles IS 'Rollenkatalog. Referenzdaten, organisationsuebergreifend. Datenklasse: Konfiguration, kein Personenbezug.';

CREATE TABLE public.service_catalog_items (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    catalog_version_id uuid NOT NULL,
    sort_order smallint NOT NULL,
    code text NOT NULL,
    label text NOT NULL,
    item_kind text NOT NULL,
    remedy text,
    unit_price_cents integer NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    tax_treatment text NOT NULL,
    tax_rate_permille smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    service_area text NOT NULL,
    package_months smallint,
    CONSTRAINT service_catalog_items_absence_fee_without_remedy CHECK (((item_kind <> 'absence_fee'::text) OR (remedy IS NULL))),
    CONSTRAINT service_catalog_items_aftercare_month CHECK (((item_kind <> 'aftercare_month'::text) OR ((service_area = 'therapy'::text) AND (remedy IS NULL) AND app.aftercare_tax_allowed(tax_treatment, tax_rate_permille)))),
    CONSTRAINT service_catalog_items_code_check CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 20))),
    CONSTRAINT service_catalog_items_currency_check CHECK ((currency = 'EUR'::text)),
    CONSTRAINT service_catalog_items_item_kind_check CHECK ((item_kind = ANY (ARRAY['treatment'::text, 'absence_fee'::text, 'aftercare_month'::text, 'training_package'::text, 'nutrition_counselling'::text]))),
    CONSTRAINT service_catalog_items_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 120))),
    CONSTRAINT service_catalog_items_nutrition_counselling CHECK (((item_kind <> 'nutrition_counselling'::text) OR (remedy IS NULL))),
    CONSTRAINT service_catalog_items_package_months_check CHECK (((package_months IS NULL) OR (package_months BETWEEN 1 AND 24))),
    CONSTRAINT service_catalog_items_reduced_rate_not_activated CHECK ((tax_rate_permille <> 70)),
    CONSTRAINT service_catalog_items_remedy_check CHECK (((remedy IS NULL) OR ((length(btrim(remedy)) >= 1) AND (length(btrim(remedy)) <= 200)))),
    CONSTRAINT service_catalog_items_service_area_check CHECK ((service_area = ANY (ARRAY['therapy'::text, 'training'::text]))),
    CONSTRAINT service_catalog_items_sort_order_check CHECK ((sort_order BETWEEN 1 AND 200)),
    CONSTRAINT service_catalog_items_tax_rate_matches_treatment CHECK ((((tax_treatment = ANY (ARRAY['exempt_healthcare'::text, 'not_taxable'::text])) AND (tax_rate_permille = 0)) OR ((tax_treatment = 'taxable'::text) AND (tax_rate_permille > 0)))),
    CONSTRAINT service_catalog_items_tax_rate_permille_check CHECK ((tax_rate_permille BETWEEN 0 AND 1000)),
    CONSTRAINT service_catalog_items_tax_treatment_check CHECK ((tax_treatment = ANY (ARRAY['exempt_healthcare'::text, 'taxable'::text, 'not_taxable'::text]))),
    CONSTRAINT service_catalog_items_taxable_rate_known CHECK (((tax_treatment <> 'taxable'::text) OR (tax_rate_permille = ANY (ARRAY[190, 70])))),
    CONSTRAINT service_catalog_items_training_is_not_healthcare CHECK (((service_area <> 'training'::text) OR (tax_treatment <> 'exempt_healthcare'::text))),
    CONSTRAINT service_catalog_items_training_package CHECK ((((item_kind = 'training_package'::text) = (package_months IS NOT NULL)) AND ((item_kind <> 'training_package'::text) OR ((service_area = 'training'::text) AND (remedy IS NULL) AND app.training_package_tax_allowed(tax_treatment, tax_rate_permille))))),
    CONSTRAINT service_catalog_items_unit_price_cents_check CHECK ((unit_price_cents BETWEEN 0 AND 1000000))
);

COMMENT ON TABLE public.service_catalog_items IS 'Position einer Preisliste: Kuerzel, Bezeichnung, Einzelpreis, Waehrung und steuerliche Einordnung (ABR-001, ADR-009 Punkte 5 und 6). Unveraenderlich, sobald ihre Version veroeffentlicht ist.';

COMMENT ON COLUMN public.service_catalog_items.item_kind IS 'treatment = erbrachte Behandlung (die Hausbesuchspauschale ist eine davon), absence_fee = Ausfallhonorar zu einem Gebuehrenanlass nach ADR-018 Fassung 2, aftercare_month = Monat des Nachsorge-Abos, training_package = Trainingspaket, nutrition_counselling = Ernaehrungsberatung (ADR-027 Punkt 15). ABR-002 laesst Behandlung und Ausfallhonorar nie ineinander rutschen.';

COMMENT ON COLUMN public.service_catalog_items.remedy IS 'Heilmittel, zu dem diese Position gehoert - derselbe Wert wie in treatment_base_items.remedy. Er belegt die Leistungserfassung vor (ABR-002). null heisst: keine Vorbelegung ueber die Grundlage.';

COMMENT ON COLUMN public.service_catalog_items.unit_price_cents IS 'Einzelpreis in Cent. Ganzzahlig und damit exakt - Fliesskomma ist fuer Geldwerte ausgeschlossen (ADR-014).';

COMMENT ON COLUMN public.service_catalog_items.tax_treatment IS 'Steuerliche Einordnung, ausdruecklich je Position gespeichert und nie abgeleitet (ADR-009 Punkt 6): exempt_healthcare = umsatzsteuerfreie Heilbehandlung, taxable = steuerpflichtig (etwa Praevention oder Training), not_taxable = nicht steuerbar, weil kein Leistungsaustausch vorliegt - der Fall des Ausfallhonorars. Die Einordnung im Einzelfall trifft die Praxis mit ihrer Steuerberatung (G13, B4); ADR-009 nimmt sie ausdruecklich aus (ANN-070).';

COMMENT ON COLUMN public.service_catalog_items.tax_rate_permille IS 'Steuersatz in Promille (190 = 19 Prozent). Promille, weil ein Satz von 7,7 Prozent in ganzen Prozent nicht darstellbar waere. Steuerfrei heisst 0.';

COMMENT ON COLUMN public.service_catalog_items.service_area IS 'Leistungsbereich dieser Position (ADR-009 Punkt 16, ADR-021 Punkt 2): therapy = Heilbehandlung, training = Leistung ohne Heilbehandlungszweck. Die erfasste Leistung traegt ihn von hier, und die Rechnung von der Leistung - eine Rechnung traegt genau einen Bereich.';

COMMENT ON COLUMN public.service_catalog_items.package_months IS 'ANG-005 (ANN-275): Laufzeit eines Trainingspakets in Monaten, gerechnet nach Paragraf 188 BGB vom Beginn aus. Nur an der Art training_package gesetzt, dort Pflicht.';

COMMENT ON CONSTRAINT service_catalog_items_aftercare_month ON public.service_catalog_items IS 'ANG-002: Der Abo-Monat ist eine Leistung des Bereichs therapy (ADR-009 Punkt 21), ohne Heilmittel und mit dem Steuerkennzeichen aus app.aftercare_tax_allowed (ANN-269).';

COMMENT ON CONSTRAINT service_catalog_items_nutrition_counselling ON public.service_catalog_items IS 'ERN-003 (ADR-027 Punkt 15, ANN-622): Die Ernährungsberatung ist keine Behandlung mit Heilmittel; sie steht je Bereich als eigene Position. Das Steuerkennzeichen trägt der Posten (voreingestellt steuerpflichtig 19 %, bis G13/B4).';

COMMENT ON CONSTRAINT service_catalog_items_reduced_rate_not_activated ON public.service_catalog_items IS 'Das dritte Steuerkennzeichen aus ADR-009 Punkt 15 ("therapy_reduced") ist angelegt, aber nicht aktiviert: Seine Rechtslage ist umstritten und die Freigabe steht bei der Steuerberatung (B4, G13). Diese eine Constraint faellt mit der Freigabe - sonst aendert sich nichts.';

COMMENT ON CONSTRAINT service_catalog_items_taxable_rate_known ON public.service_catalog_items IS 'Ein steuerpflichtiger Posten traegt den Regelsatz (190 Promille, Par. 12 Abs. 1 UStG) oder den ermaessigten Satz (70 Promille, Par. 12 Abs. 2 UStG). Ein dritter Satz ist in Deutschland keiner (ADR-009 Punkt 15).';

COMMENT ON CONSTRAINT service_catalog_items_training_is_not_healthcare ON public.service_catalog_items IS 'Eine Trainingsposition ist nie eine steuerfreie Heilbehandlung (ADR-021, Par. 4 Nr. 14 Buchstabe a UStG). Das Kennzeichen wird damit nicht aus dem Bereich abgeleitet (ADR-009 Punkt 15) - nur eine unmoegliche Kombination ausgeschlossen.';

COMMENT ON CONSTRAINT service_catalog_items_training_package ON public.service_catalog_items IS 'ANG-005: Ein Trainingspaket ist eine Leistung des Bereichs training (ADR-009 Punkt 21), ohne Heilmittel, mit Laufzeit und mit dem Steuerkennzeichen aus app.training_package_tax_allowed (ANN-275). Eine Laufzeit traegt nur das Paket.';

CREATE TABLE public.service_catalog_versions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    label text NOT NULL,
    valid_from date NOT NULL,
    published_at timestamp with time zone,
    published_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    session_fee_cents integer,
    CONSTRAINT service_catalog_versions_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 100))),
    CONSTRAINT service_catalog_versions_session_fee_cents_check CHECK (((session_fee_cents IS NULL) OR (session_fee_cents BETWEEN 0 AND 1000000)))
);

COMMENT ON TABLE public.service_catalog_versions IS 'Eine Preisliste mit Gueltigkeitsbeginn (ABR-001, ADR-009 Punkt 5). Enthaelt keine Patientendaten. Datenklasse: Abrechnungsstammdaten, steuerliche Frist (ADR-008). Lesbar fuer alle Praxisrollen; geschrieben ausschliesslich ueber die Funktionen dieser Migration.';

COMMENT ON COLUMN public.service_catalog_versions.valid_from IS 'Erster Tag, an dem diese Preisliste gilt. Massgeblich ist das Leistungsdatum, nicht der Tag der Erfassung - sonst aenderte eine spaete Erfassung den Preis einer laengst erbrachten Behandlung (ADR-009 Punkt 5).';

COMMENT ON COLUMN public.service_catalog_versions.published_at IS 'null heisst Entwurf und aenderbar; gesetzt heisst veroeffentlicht und damit unveraenderlich - Positionen eingeschlossen. Zurueck geht es nicht: eine Preisaenderung ist eine neue Version (ANN-070).';

COMMENT ON COLUMN public.service_catalog_versions.session_fee_cents IS 'Allgemeiner Tarif des Terminhonorars in Cent (ABR-030, ADR-009 Punkt 22, ANN-231): je durchgefuehrtem Behandlungstermin genau einmal, einschliesslich Dokumentation und Hausbesuch. Mit der Version veroeffentlicht und eingefroren. null heisst: diese Preisliste kennt kein Terminhonorar.';

CREATE TABLE public.session_activity (
    session_id uuid NOT NULL,
    user_id uuid NOT NULL,
    last_activity_at timestamp with time zone NOT NULL
);

COMMENT ON TABLE public.session_activity IS 'Letzte Bedienung je Sitzung des Anmeldedienstes (ADR-025 Punkt 2, W2 (a), ANN-256). Nur Zeitpunkt und Konto, kein Inhalt, keine Seite. Geschrieben nur ueber session_status(true), hoechstens einmal je Minute. Kein direkter Zugriff. Datenklasse sitzungsvermerk: ein Tag nach der letzten Bedienung; faellt mit dem Konto.';

CREATE TABLE public.session_unlocks (
    session_id uuid NOT NULL,
    user_id uuid NOT NULL,
    pin_unlocked_at timestamp with time zone,
    failed_attempts integer DEFAULT 0 NOT NULL,
    consumed_at timestamp with time zone,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    passkey_ok boolean,
    CONSTRAINT session_unlocks_failed_attempts_check CHECK ((failed_attempts >= 0))
);

COMMENT ON TABLE public.session_unlocks IS 'Freigabe per App-PIN und Fehlversuche je Sitzung des Anmeldedienstes (ADR-025 Punkt 11, ANN-324). Nur Zeitpunkte und ein Zaehler, kein Inhalt. Kein direkter Zugriff; geschrieben nur ueber unlock_with_pin. Datenklasse sitzungsvermerk: ein Tag nach der letzten Aenderung, solange kein Fehlversuch offen ist.';

COMMENT ON COLUMN public.session_unlocks.passkey_ok IS 'Ob die Passkey-Anmeldung dieser Sitzung von einem freigegebenen Passkey stammt (ANN-329); null bis zur ersten Prüfung durch session_status.';

CREATE TABLE public.user_profiles (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    person_id uuid NOT NULL,
    display_name text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT user_profiles_display_name_check CHECK (((length(btrim(display_name)) >= 1) AND (length(btrim(display_name)) <= 200)))
);

COMMENT ON TABLE public.user_profiles IS 'Zuordnung Authentifizierungsaccount zu Person und Organisation. Datenklasse: Accountdaten, getrennt von aufbewahrungspflichtigen Fachdaten (ADR-008).';

COMMENT ON COLUMN public.user_profiles.is_active IS 'Ist der Zugang freigeschaltet? false sperrt jeden Datenzugriff (app.current_organization_id() liefert dann null), laesst das Konto beim Provider aber bestehen (STAFF-003).';

CREATE TABLE public.user_roles (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    role_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT user_roles_no_patient_role CHECK ((role_key <> 'patient'::text))
);

COMMENT ON TABLE public.user_roles IS 'Rollenzuweisung. Mehrfachzuweisung ist ausdruecklich vorgesehen (ADR-004). Aenderungen sind auditpflichtig (ADR-010).';

COMMENT ON CONSTRAINT user_roles_no_patient_role ON public.user_roles IS 'ADR-023 Punkt 3: Plattformrechte folgen dem Zugang (platform_accesses), nie einer Rolle.';

CREATE VIEW public.staff_account_directory WITH (security_invoker='true') AS
 SELECT sm.id AS staff_member_id,
    sm.organization_id,
    up.id AS user_id,
    up.is_active AS account_active,
    ( SELECT array_agg(ur.role_key ORDER BY ur.role_key) AS array_agg
           FROM public.user_roles ur
          WHERE ((ur.user_id = up.id) AND (ur.organization_id = up.organization_id))) AS role_keys
   FROM (public.staff_members sm
     LEFT JOIN public.user_profiles up ON (((up.person_id = sm.person_id) AND (up.organization_id = sm.organization_id))));

COMMENT ON VIEW public.staff_account_directory IS 'Zugangsstand je Mitarbeiterdatensatz. security_invoker: RLS der Basistabellen gilt unveraendert (STAFF-002b).';

CREATE TABLE public.staff_account_invitations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    email text NOT NULL,
    role_keys text[] NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    invited_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    accepted_user_id uuid,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    CONSTRAINT staff_account_invitations_check CHECK (((status = 'accepted'::text) = (accepted_at IS NOT NULL))),
    CONSTRAINT staff_account_invitations_check1 CHECK (((status = 'revoked'::text) = (revoked_at IS NOT NULL))),
    CONSTRAINT staff_account_invitations_email_check CHECK ((email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text)),
    CONSTRAINT staff_account_invitations_email_check1 CHECK ((email = lower(btrim(email)))),
    CONSTRAINT staff_account_invitations_role_keys_check CHECK ((cardinality(role_keys) BETWEEN 1 AND 4)),
    CONSTRAINT staff_account_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'revoked'::text])))
);

COMMENT ON TABLE public.staff_account_invitations IS 'Einladung eines Zugangs (STAFF-002b). Haelt die BERECHTIGUNG fest - Organisation, Mitarbeiterdatensatz, Rollen; das Konto selbst entsteht beim Provider. Datenklasse: Zugangsdatum, 12 Monate nach Abschluss (ADR-008, ANN-026).';

COMMENT ON COLUMN public.staff_account_invitations.email IS 'Normalisiert klein und getrimmt. Einziger Anknuepfungspunkt zum spaeter entstehenden Konto.';

COMMENT ON COLUMN public.staff_account_invitations.role_keys IS 'Rollen, die bei der Annahme gesetzt werden. Die dauerhafte Zuordnung steht in user_roles.';

COMMENT ON COLUMN public.staff_account_invitations.accepted_user_id IS 'auth.users.id des annehmenden Kontos. Bewusst ohne FK, damit ein spaeter geloeschter Zugang den Nachweis nicht entfernt (ADR-008, ADR-010).';

CREATE TABLE public.staff_colors (
    staff_member_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    color text NOT NULL,
    CONSTRAINT staff_colors_color_check CHECK ((color = ANY (app.staff_color_palette())))
);

COMMENT ON TABLE public.staff_colors IS 'TEAM-006 (ANN-666): Farbe einer Person im Teamchat - hinter den Initialen oder als Umriss um das Profilbild. Vergeben mit dem Mitarbeiterdatensatz, geändert nur von der Person selbst. Datenklasse beschaeftigtendaten, fällt mit dem Mitarbeiterdatensatz (cascade). Kein Tabellenrecht.';

CREATE TABLE public.staff_compensation_models (
    staff_member_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    model text NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by uuid,
    CONSTRAINT staff_compensation_models_model_check CHECK ((model = ANY (ARRAY['fixed_salary'::text, 'revenue_share'::text])))
);

COMMENT ON TABLE public.staff_compensation_models IS 'Verguetungsmodell je Mitarbeiter:in (STA-005): Festgehalt oder Umsatzbeteiligung. Ohne Zeile kein Modell hinterlegt (zaehlt wie Festgehalt, ANN-157). Lesen owner und die Person selbst, schreiben allein owner ueber set_staff_compensation_model. Datenklasse: Beschaeftigtendaten; faellt mit dem Mitarbeiterdatensatz.';

CREATE TABLE public.staff_private_details (
    staff_member_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    date_of_birth date,
    private_email text,
    private_phone text,
    street text,
    postal_code text,
    city text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT staff_private_details_postal_code_check CHECK (((postal_code IS NULL) OR ((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12)))),
    CONSTRAINT staff_private_details_private_email_check CHECK (((private_email IS NULL) OR (private_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT staff_private_details_private_phone_check CHECK (((private_phone IS NULL) OR ((length(btrim(private_phone)) >= 3) AND (length(btrim(private_phone)) <= 40))))
);

COMMENT ON TABLE public.staff_private_details IS 'Privatdaten von Mitarbeitenden. Zugriff ausschliesslich owner und die betroffene Person selbst (PROJECT_PRINCIPLES.md 20). Datenklasse: Beschaeftigtendaten.';

CREATE VIEW public.staff_directory WITH (security_invoker='true') AS
 SELECT sm.id,
    sm.organization_id,
    sm.person_id,
    pe.given_name,
    pe.family_name,
    sm.employment_status,
    sm.work_email,
    sm.work_phone,
    sm.primary_location_id,
    l.name AS primary_location_name,
    spd.date_of_birth,
    spd.private_email,
    spd.private_phone,
    spd.street,
    spd.postal_code,
    spd.city,
    sm.schedulable_treatment,
    sm.schedulable_training
   FROM (((public.staff_members sm
     JOIN public.persons pe ON ((pe.id = sm.person_id)))
     LEFT JOIN public.locations l ON ((l.id = sm.primary_location_id)))
     LEFT JOIN public.staff_private_details spd ON ((spd.staff_member_id = sm.id)));

COMMENT ON VIEW public.staff_directory IS 'Mitarbeiterliste fuer die Anwendung. security_invoker: RLS der Basistabellen gilt unveraendert. Privatdaten erscheinen nur fuer owner und die betroffene Person (PROJECT_PRINCIPLES.md 20).';

CREATE TABLE public.staff_feedback (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    kind text NOT NULL,
    month date NOT NULL,
    staff_member_id uuid,
    submitted_at timestamp with time zone,
    mood smallint,
    tours smallint,
    team smallint,
    easier_text text,
    more_text text,
    message_text text,
    CONSTRAINT staff_feedback_easier_text_check CHECK (((easier_text IS NULL) OR (length(easier_text) BETWEEN 1 AND 2000))),
    CONSTRAINT staff_feedback_kind CHECK ((((kind = 'barometer'::text) AND (message_text IS NULL) AND (num_nonnulls(mood, tours, team, easier_text, more_text) > 0)) OR ((kind = 'message'::text) AND (message_text IS NOT NULL) AND (num_nonnulls(mood, tours, team, easier_text, more_text) = 0)))),
    CONSTRAINT staff_feedback_kind_check CHECK ((kind = ANY (ARRAY['barometer'::text, 'message'::text]))),
    CONSTRAINT staff_feedback_message_text_check CHECK (((message_text IS NULL) OR (length(message_text) BETWEEN 1 AND 2000))),
    CONSTRAINT staff_feedback_month_check CHECK ((EXTRACT(day FROM month) = (1)::numeric)),
    CONSTRAINT staff_feedback_mood_check CHECK ((mood BETWEEN 1 AND 9)),
    CONSTRAINT staff_feedback_more_text_check CHECK (((more_text IS NULL) OR (length(more_text) BETWEEN 1 AND 2000))),
    CONSTRAINT staff_feedback_named CHECK (((staff_member_id IS NULL) = (submitted_at IS NULL))),
    CONSTRAINT staff_feedback_team_check CHECK ((team BETWEEN 1 AND 9)),
    CONSTRAINT staff_feedback_tours_check CHECK ((tours BETWEEN 1 AND 9))
);

COMMENT ON TABLE public.staff_feedback IS 'ORG-006 (§20.2, ANN-607, ANN-608): Rückmeldungen von Beschäftigten - Barometer (drei Skalen 1-9, zwei Freitexte) und Rückmeldung an die Praxisleitung. Mit Namen: Person und Zeitpunkt; ohne Namen: nur Organisation und Monat, keine Person, kein Konto, keine Uhrzeit, zufällige Kennung. Liest allein owner über public.list_staff_feedback_named und public.get_staff_feedback_summary (Schwelle 3/5). Datenklasse rueckmeldung: zwölf Monate ab Ende des Monats der Abgabe, endgültig gelöscht (ADR-008 Fassung 4). Kein Tabellenrecht, kein Auditeintrag.';

CREATE TABLE public.staff_feedback_blocks (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    kind text NOT NULL,
    from_month date NOT NULL,
    to_month date NOT NULL,
    answers integer NOT NULL,
    CONSTRAINT staff_feedback_blocks_answers_check CHECK ((answers >= 5)),
    CONSTRAINT staff_feedback_blocks_check CHECK ((to_month >= from_month)),
    CONSTRAINT staff_feedback_blocks_from_month_check CHECK ((EXTRACT(day FROM from_month) = (1)::numeric)),
    CONSTRAINT staff_feedback_blocks_kind_check CHECK ((kind = ANY (ARRAY['barometer'::text, 'message'::text]))),
    CONSTRAINT staff_feedback_blocks_to_month_check CHECK ((EXTRACT(day FROM to_month) = (1)::numeric))
);

COMMENT ON TABLE public.staff_feedback_blocks IS 'ORG-006 (§20.2 Nr. 4, ANN-607): geschlossene, nicht überlappende Zeiträume der Praxissumme je Art - ein Block hat mindestens fünf anonyme Antworten und ändert sich nie. Keine Person, keine Antwort. Wird mit den Rückmeldungen nach zwölf Monaten gelöscht. Kein Tabellenrecht.';

CREATE TABLE public.staff_feedback_participations (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    month date NOT NULL,
    CONSTRAINT staff_feedback_participations_month_check CHECK ((EXTRACT(day FROM month) = (1)::numeric))
);

COMMENT ON TABLE public.staff_feedback_participations IS 'ORG-006 (ANN-607): Teilnahme am Barometer je Person und Monat - nur damit der Hinweis verschwindet und niemand doppelt abgibt. Ohne Zeitstempel und ohne Bezug zur Antwort; liest nur die Person selbst (public.get_my_staff_feedback_status). Datenklasse rueckmeldung_teilnahme: fällt nach dem Monat im nächsten Lauf, ohne Journal (die Regel hängt am Monat allein und greift nach einem Restore ebenso). Kein Tabellenrecht.';

CREATE TABLE public.staff_leave_entitlements (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    year smallint NOT NULL,
    days smallint NOT NULL,
    carryover_days smallint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT staff_leave_entitlements_carryover_days_check CHECK ((carryover_days BETWEEN 0 AND 60)),
    CONSTRAINT staff_leave_entitlements_days_check CHECK ((days BETWEEN 0 AND 60)),
    CONSTRAINT staff_leave_entitlements_year_check CHECK ((year BETWEEN 2000 AND 2100))
);

COMMENT ON TABLE public.staff_leave_entitlements IS 'URL-001: Urlaubsanspruch einer Person fuer ein Kalenderjahr - Tage und Uebertrag aus dem Vorjahr, eingetragen von owner. Kein automatischer Verfall (Hinweispflicht nach EuGH C-684/16). Beschaeftigtendaten; Datenklasse urlaub: drei Jahre ab Ende des Jahres (ANN-579). Kein Tabellenrecht.';

CREATE TABLE public.staff_leave_requests (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    kind text DEFAULT 'leave'::text NOT NULL,
    refers_to uuid,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    days smallint NOT NULL,
    days_following_year smallint DEFAULT 0 NOT NULL,
    message text,
    status text DEFAULT 'requested'::text NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note text,
    withdrawn_at timestamp with time zone,
    self_entered boolean DEFAULT false NOT NULL,
    CONSTRAINT staff_leave_requests_check CHECK (((days_following_year BETWEEN 0 AND 93) AND (days_following_year <= days))),
    CONSTRAINT staff_leave_requests_days_check CHECK ((days BETWEEN 0 AND 93)),
    CONSTRAINT staff_leave_requests_decided CHECK (((status = ANY (ARRAY['approved'::text, 'rejected'::text, 'cancelled'::text])) = ((decided_at IS NOT NULL) AND (decided_by IS NOT NULL)))),
    CONSTRAINT staff_leave_requests_decision_note_check CHECK (((decision_note IS NULL) OR (length(decision_note) BETWEEN 1 AND 500))),
    CONSTRAINT staff_leave_requests_kind_check CHECK ((kind = ANY (ARRAY['leave'::text, 'cancellation'::text]))),
    CONSTRAINT staff_leave_requests_message_check CHECK (((message IS NULL) OR (length(message) BETWEEN 1 AND 500))),
    CONSTRAINT staff_leave_requests_period CHECK (((ends_on >= starts_on) AND ((ends_on - starts_on) <= 92))),
    CONSTRAINT staff_leave_requests_reference CHECK ((((kind = 'leave'::text) AND (refers_to IS NULL)) OR ((kind = 'cancellation'::text) AND (refers_to IS NOT NULL)))),
    CONSTRAINT staff_leave_requests_reject_reason CHECK (((status <> 'rejected'::text) OR (decision_note IS NOT NULL))),
    CONSTRAINT staff_leave_requests_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'cancelled'::text]))),
    CONSTRAINT staff_leave_requests_withdrawn CHECK (((status = 'withdrawn'::text) = (withdrawn_at IS NOT NULL)))
);

COMMENT ON TABLE public.staff_leave_requests IS 'URL-001 (ANN-576): Urlaubsantraege und Stornos. Beantragt von/am, entschieden von/am, Grund - der Nachweis (ADR-010 Punkt 15). Die Notiz (message) sieht nur die Person selbst (BEF-066, ANN-580). Datenklasse urlaub (genehmigt, storniert: drei Jahre ab Ende des Urlaubsjahres) bzw. urlaub_kurz (abgelehnt, zurueckgezogen: ein Jahr), ANN-579. Kein Tabellenrecht.';

COMMENT ON COLUMN public.staff_leave_requests.days IS 'Urlaubstage am Server gezaehlt (app.leave_days) beim Beantragen - spaetere Aenderungen am Wochenplan aendern einen Antrag nicht.';

CREATE TABLE public.staff_payout_accounts (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    iban text NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_payout_accounts_iban CHECK (((iban = upper(replace(iban, ' '::text, ''::text))) AND app.iban_checksum_ok(iban)))
);

COMMENT ON TABLE public.staff_payout_accounts IS 'ERS-001 (ANN-601): die IBAN, auf die eine Person ihre Erstattungen bekommt - eine je Person, von ihr selbst hinterlegt. Gelesen nur maskiert; voll nur in public.reimbursement_payout_details für owner. Datenklasse Beschäftigtendaten (ANN-030). Kein Tabellenrecht.';

CREATE TABLE public.staff_profile_pictures (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    image bytea NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT staff_profile_pictures_image_check CHECK ((octet_length(image) BETWEEN 128 AND 65536))
);

COMMENT ON TABLE public.staff_profile_pictures IS 'TEAM-007 (ADR-017 Abschnitt O, ANN-667): Profilbild einer Person im Teamchat - JPEG 256 × 256 ohne Metadaten, höchstens 64 KiB, gesetzt nur von der Person selbst. Unveränderlich: ein neues Bild ist eine neue Zeile. Klasse profilbild: fällt beim Entfernen, Ersetzen und Ausscheiden, mit Löschjournal. Kein Tabellenrecht.';

COMMENT ON COLUMN public.staff_profile_pictures.id IS 'Kennung und zugleich Fassung des Bildes - ändert sich mit jedem neuen Bild; die Anwendung hält ein Bild je Kennung.';

CREATE TABLE public.staff_reimbursement_receipt_access_grants (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT staff_reimbursement_receipt_access_grants_short_lived CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))))
);

COMMENT ON TABLE public.staff_reimbursement_receipt_access_grants IS 'ERS-001: einmalige, personengebundene Freigabe für genau einen Verweis auf einen Beleg (ANN-052). Verbraucht beim ersten Zugriff, verfällt nach 30 Sekunden; abgelaufene löscht public.discard_stale_reimbursement_receipts täglich. Fällt spätestens mit dem Beleg (cascade).';

CREATE TABLE public.staff_time_account_entries (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    kind text NOT NULL,
    on_date date NOT NULL,
    starts_at time without time zone,
    ends_at time without time zone,
    minutes integer NOT NULL,
    note text,
    status text DEFAULT 'valid'::text NOT NULL,
    entered_by uuid,
    entered_at timestamp with time zone DEFAULT now() NOT NULL,
    entered_for_other boolean DEFAULT false NOT NULL,
    rejected_by uuid,
    rejected_at timestamp with time zone,
    rejection_note text,
    withdrawn_at timestamp with time zone,
    CONSTRAINT staff_time_account_entries_carryover CHECK ((((kind = 'carryover'::text) = (entered_by IS NULL)) AND ((kind <> 'carryover'::text) OR ((status = 'valid'::text) AND (NOT entered_for_other))))),
    CONSTRAINT staff_time_account_entries_check CHECK ((((minutes <> 0) OR (kind = 'carryover'::text)) AND ((kind = 'carryover'::text) OR (minutes BETWEEN '-1000000'::integer AND 1000000)))),
    CONSTRAINT staff_time_account_entries_kind_check CHECK ((kind = ANY (ARRAY['overtime'::text, 'time_off'::text, 'correction'::text, 'carryover'::text]))),
    CONSTRAINT staff_time_account_entries_note_check CHECK (((note IS NULL) OR (length(note) BETWEEN 1 AND 500))),
    CONSTRAINT staff_time_account_entries_rejected CHECK (((status = 'rejected'::text) = ((rejected_at IS NOT NULL) AND (rejected_by IS NOT NULL) AND (rejection_note IS NOT NULL)))),
    CONSTRAINT staff_time_account_entries_rejection_note_check CHECK (((rejection_note IS NULL) OR (length(rejection_note) BETWEEN 1 AND 500))),
    CONSTRAINT staff_time_account_entries_sign CHECK (((kind = ANY (ARRAY['correction'::text, 'carryover'::text])) OR ((kind = 'overtime'::text) AND (minutes > 0)) OR ((kind = 'time_off'::text) AND (minutes < 0)))),
    CONSTRAINT staff_time_account_entries_status_check CHECK ((status = ANY (ARRAY['valid'::text, 'rejected'::text, 'withdrawn'::text]))),
    CONSTRAINT staff_time_account_entries_times CHECK ((((kind = ANY (ARRAY['correction'::text, 'carryover'::text])) AND (starts_at IS NULL) AND (ends_at IS NULL) AND ((kind = 'carryover'::text) OR (note IS NOT NULL))) OR ((kind = ANY (ARRAY['overtime'::text, 'time_off'::text])) AND (starts_at IS NOT NULL) AND (ends_at IS NOT NULL) AND (starts_at < ends_at)))),
    CONSTRAINT staff_time_account_entries_withdrawn CHECK (((status = 'withdrawn'::text) = (withdrawn_at IS NOT NULL)))
);

COMMENT ON TABLE public.staff_time_account_entries IS 'ZK-001 (ANN-593 bis ANN-597): Einträge im Zeitkonto - Mehrarbeit und Freizeitausgleich mit Datum, Beginn und Ende, Korrekturen durch owner und Büro, Überträge des Löschlaufs. Gelten sofort; zurückgewiesen (owner, mit Grund) oder zurückgenommen zählen sie nicht. Eingetragen von/am, zurückgewiesen von/am und Grund sind der Nachweis (ADR-010 Punkt 15). Datenklassen zeitkonto (gültige: drei Jahre ab Ende des Jahres, der Saldo bleibt als Übertrag) und zeitkonto_kurz (zurückgewiesene und zurückgenommene: ein Jahr); Überträge bleiben Beschäftigtendaten (ANN-030). Kein Tabellenrecht.';

CREATE TABLE public.staff_working_hour_exceptions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    on_date date NOT NULL,
    kind text NOT NULL,
    starts_at time without time zone,
    ends_at time without time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    leave_request_id uuid,
    working_time_request_id uuid,
    time_account_entry_id uuid,
    CONSTRAINT staff_working_hour_exceptions_kind_check CHECK ((kind = ANY (ARRAY['unavailable'::text, 'block'::text]))),
    CONSTRAINT staff_working_hour_exceptions_kind_fields CHECK ((((kind = 'unavailable'::text) AND (starts_at IS NULL) AND (ends_at IS NULL)) OR ((kind = 'block'::text) AND (starts_at IS NOT NULL) AND (ends_at IS NOT NULL) AND (ends_at > starts_at)))),
    CONSTRAINT staff_working_hour_exceptions_whole_minutes CHECK ((((starts_at IS NULL) OR (date_part('second'::text, starts_at) = (0)::double precision)) AND ((ends_at IS NULL) OR (date_part('second'::text, ends_at) = (0)::double precision))))
);

COMMENT ON TABLE public.staff_working_hour_exceptions IS 'Datumsbezogene Abweichung vom Wochenplan (CAL-005). Ersetzt den Wochenplan fuer dieses Datum vollstaendig. Ausdruecklich keine Urlaubsverwaltung und keine Arbeitszeiterfassung.';

COMMENT ON COLUMN public.staff_working_hour_exceptions.kind IS '"unavailable" = an diesem Tag keine Termine; "block" = abweichender Zeitblock. Beides schliesst sich am selben Tag gegenseitig aus.';

COMMENT ON COLUMN public.staff_working_hour_exceptions.leave_request_id IS 'URL-001 (ANN-578): Abwesenheit aus einem genehmigten Urlaubsantrag. Ein Storno entfernt genau diese Zeilen, die Frist des Antrags loescht sie mit (cascade); von Hand eingetragene tragen null.';

COMMENT ON COLUMN public.staff_working_hour_exceptions.working_time_request_id IS 'AZ-001 (ANN-591): Abweichung aus einer genehmigten einmaligen Arbeitszeitänderung; die Frist des Antrags löscht sie mit (cascade). Von Hand eingetragene tragen null.';

COMMENT ON COLUMN public.staff_working_hour_exceptions.time_account_entry_id IS 'ZK-001 (ANN-595): Abweichung aus einem Freizeitausgleich - die übrigen Blöcke des Tages oder die ganztägige Abwesenheit. Fällt mit dem Eintrag. Von Hand eingetragene tragen null.';

CREATE TABLE public.staff_working_hours (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    weekday smallint NOT NULL,
    starts_at time without time zone NOT NULL,
    ends_at time without time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    valid_from date,
    valid_until date,
    CONSTRAINT staff_working_hours_time_order CHECK ((ends_at > starts_at)),
    CONSTRAINT staff_working_hours_validity CHECK (((valid_from IS NULL) OR (valid_until IS NULL) OR (valid_until >= valid_from))),
    CONSTRAINT staff_working_hours_weekday_check CHECK ((weekday BETWEEN 1 AND 7)),
    CONSTRAINT staff_working_hours_whole_minutes CHECK (((date_part('second'::text, starts_at) = (0)::double precision) AND (date_part('second'::text, ends_at) = (0)::double precision)))
);

COMMENT ON TABLE public.staff_working_hours IS 'Wiederkehrender Wochenplan einer Person in Ortszeit der Praxis (CAL-005), in Fassungen mit Gueltigkeit (AZ-001, ANN-589). Datenklasse: organisatorische Personaldaten, keine Gesundheitsdaten. Fruehere Fassungen liest nur der Server.';

COMMENT ON COLUMN public.staff_working_hours.weekday IS 'ISO-8601-Wochentag: 1 = Montag ... 7 = Sonntag.';

COMMENT ON COLUMN public.staff_working_hours.created_by IS 'auth.users.id des handelnden Accounts. Bewusst ohne FK, wie an den uebrigen Fachtabellen.';

COMMENT ON COLUMN public.staff_working_hours.valid_from IS 'AZ-001 (ANN-589): erster Tag der Fassung; leer = seit jeher. Alle Zeilen einer Fassung tragen dieselben Grenzen.';

COMMENT ON COLUMN public.staff_working_hours.valid_until IS 'AZ-001 (ANN-589): letzter Tag der Fassung; leer = offen. Eine genehmigte dauerhafte Aenderung setzt ihn auf den Vortag ihres Datums.';

CREATE TABLE public.staff_working_time_requests (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    kind text NOT NULL,
    on_date date NOT NULL,
    blocks jsonb NOT NULL,
    previous_blocks jsonb NOT NULL,
    previous_minutes integer NOT NULL,
    new_minutes integer NOT NULL,
    message text,
    status text DEFAULT 'requested'::text NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note text,
    withdrawn_at timestamp with time zone,
    self_entered boolean DEFAULT false NOT NULL,
    CONSTRAINT staff_working_time_requests_decided CHECK (((status = ANY (ARRAY['approved'::text, 'rejected'::text])) = ((decided_at IS NOT NULL) AND (decided_by IS NOT NULL)))),
    CONSTRAINT staff_working_time_requests_decision_note_check CHECK (((decision_note IS NULL) OR (length(decision_note) BETWEEN 1 AND 500))),
    CONSTRAINT staff_working_time_requests_kind_check CHECK ((kind = ANY (ARRAY['once'::text, 'permanent'::text]))),
    CONSTRAINT staff_working_time_requests_message_check CHECK (((message IS NULL) OR (length(message) BETWEEN 1 AND 500))),
    CONSTRAINT staff_working_time_requests_new_minutes_check CHECK ((new_minutes BETWEEN 0 AND 10080)),
    CONSTRAINT staff_working_time_requests_no_reduction CHECK ((new_minutes >= previous_minutes)),
    CONSTRAINT staff_working_time_requests_previous_minutes_check CHECK ((previous_minutes BETWEEN 0 AND 10080)),
    CONSTRAINT staff_working_time_requests_reject_reason CHECK (((status <> 'rejected'::text) OR (decision_note IS NOT NULL))),
    CONSTRAINT staff_working_time_requests_shape CHECK ((((kind = 'once'::text) AND (jsonb_typeof(blocks) = 'array'::text) AND (jsonb_typeof(previous_blocks) = 'array'::text)) OR ((kind = 'permanent'::text) AND (jsonb_typeof(blocks) = 'object'::text) AND (jsonb_typeof(previous_blocks) = 'object'::text)))),
    CONSTRAINT staff_working_time_requests_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text]))),
    CONSTRAINT staff_working_time_requests_withdrawn CHECK (((status = 'withdrawn'::text) = (withdrawn_at IS NOT NULL)))
);

COMMENT ON TABLE public.staff_working_time_requests IS 'AZ-001 (ANN-590): Antraege auf Aenderung der eigenen Arbeitszeit - einmalig fuer einen Tag oder dauerhaft ab einem Datum, nie mit weniger Stunden. Beantragt von/am, bisher und neu, entschieden von/am, Grund - der Nachweis (ADR-010 Punkt 15). Den Grund (message) sehen die Person und owner. Datenklasse arbeitszeit (genehmigt: drei Jahre ab Ende des Jahres der Wirkung) bzw. arbeitszeit_kurz (abgelehnt, zurueckgezogen: ein Jahr), ANN-591. Kein Tabellenrecht.';

CREATE TABLE public.storage_deletion_orders (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    bucket_id text NOT NULL,
    object_key text NOT NULL,
    ordered_at timestamp with time zone DEFAULT now() NOT NULL,
    receipted_at timestamp with time zone,
    receipted_by uuid,
    ordered_by uuid DEFAULT auth.uid(),
    CONSTRAINT storage_deletion_orders_bucket_id_check CHECK (((length(btrim(bucket_id)) >= 1) AND (length(btrim(bucket_id)) <= 100))),
    CONSTRAINT storage_deletion_orders_object_key_check CHECK (((length(btrim(object_key)) >= 1) AND (length(btrim(object_key)) <= 500))),
    CONSTRAINT storage_deletion_orders_receipt_complete CHECK (((receipted_at IS NULL) = (receipted_by IS NULL)))
);

COMMENT ON TABLE public.storage_deletion_orders IS 'Loeschauftraege fuer Objekte im Objektspeicher (ADR-017 Punkt 25). Offen bedeutet: die Zeile ist weg, das Objekt noch nicht. Die Quittung schliesst die Loeschung ab. Datenklasse: Loeschjournal, ohne eigene Frist (ANN-031) - er muss den Restore ueberleben.';

COMMENT ON COLUMN public.storage_deletion_orders.ordered_by IS 'Wer die Loeschung ausgeloest hat; leer, wenn ein zeitgesteuerter Vorgang loescht (LOG-EPIC-001).';

CREATE TABLE public.tasks (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid,
    assigned_staff_member_id uuid,
    title text NOT NULL,
    note text,
    due_on date,
    status text DEFAULT 'open'::text NOT NULL,
    done_at timestamp with time zone,
    done_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT tasks_done CHECK (((status = 'done'::text) = (done_at IS NOT NULL))),
    CONSTRAINT tasks_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 1000)))),
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text]))),
    CONSTRAINT tasks_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200)))
);

COMMENT ON TABLE public.tasks IS 'Aufgaben und Wiedervorlagen der Praxis (PRX-012), optional mit Bezug auf eine Person. Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: erledigt zwoelf Monate nach dem Erledigen (aufgabe, ANN-142); offen mit Bezug faellt mit der Akte.';

COMMENT ON COLUMN public.tasks.title IS 'Was zu tun ist, organisatorisch ("Verordnung nachfordern"). Keine klinischen Angaben - die Oberflaeche sagt es. Steht nie im Auditlog.';

COMMENT ON COLUMN public.tasks.due_on IS 'Faellig am (Kalendertag der Praxis). Leer heisst: ohne Termin.';

CREATE TABLE public.team_attachment_access_grants (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    attachment_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT team_attachment_access_grants_short_lived CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))))
);

COMMENT ON TABLE public.team_attachment_access_grants IS 'TEAM-003: einmalige, personengebundene Freigabe für genau einen Verweis auf einen Anhang im Teamchat (ANN-052). Verbraucht beim ersten Zugriff, verfällt nach 30 Sekunden; abgelaufene löscht public.discard_stale_team_attachments täglich. Fällt spätestens mit dem Anhang (cascade).';

CREATE TABLE public.team_channel_members (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    staff_member_id uuid NOT NULL
);

COMMENT ON TABLE public.team_channel_members IS 'TEAM-001, TEAM-002: die Mitglieder einer Direktnachricht (zwei), einer Gruppennachricht (drei bis neun) und eines privaten Kanals. Nur sie lesen das Gespräch, auch owner nicht (ANN-609, ANN-642).';

CREATE TABLE public.team_channel_settings (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    notify text DEFAULT 'all'::text NOT NULL,
    starred boolean DEFAULT false NOT NULL,
    CONSTRAINT team_channel_settings_notify_check CHECK ((notify = ANY (ARRAY['all'::text, 'mentions'::text, 'none'::text])))
);

COMMENT ON TABLE public.team_channel_settings IS 'TEAM-002 (ANN-647): je Person und Gespräch die Benachrichtigungsstufe (alle, nur Erwähnungen, stumm) und der Favorit - nur für die Person selbst lesbar. Fällt mit dem Gespräch, beim Verlassen und mit dem Ausscheiden.';

CREATE TABLE public.team_channels (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    kind text NOT NULL,
    name text,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    CONSTRAINT team_channels_description_check CHECK (((description IS NULL) OR (length(description) BETWEEN 1 AND 200))),
    CONSTRAINT team_channels_direct CHECK (((kind = ANY (ARRAY['channel'::text, 'private'::text])) OR ((description IS NULL) AND (archived_at IS NULL)))),
    CONSTRAINT team_channels_kind_check CHECK ((kind = ANY (ARRAY['channel'::text, 'private'::text, 'direct'::text, 'group'::text, 'fleet'::text]))),
    CONSTRAINT team_channels_name CHECK (((kind = ANY (ARRAY['channel'::text, 'private'::text])) = (name IS NOT NULL))),
    CONSTRAINT team_channels_name_check CHECK (((name IS NULL) OR (length(name) BETWEEN 1 AND 40)))
);

COMMENT ON TABLE public.team_channels IS 'TEAM-001, TEAM-002: Gespräche des Teamchats - offene Kanäle (alle Teilnehmenden der Praxis), private Kanäle und Gruppennachrichten (nur ihre Mitglieder, team_channel_members, ANN-642), Direktnachrichten (genau zwei Personen) und das eine Gespräch der Radflotte (wer die Flotte liest, ANN-613). Datenklasse teamchat (ANN-610).';

COMMENT ON COLUMN public.team_channels.archived_at IS 'Archiviert: nur noch lesbar, keine neuen Nachrichten. Hält keine Löschung auf.';

CREATE TABLE public.team_message_mentions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    message_id uuid NOT NULL,
    staff_member_id uuid NOT NULL
);

COMMENT ON TABLE public.team_message_mentions IS 'TEAM-001: wer in einer Nachricht erwähnt ist - für den eigenen Zähler „Für dich“. Fällt mit der Nachricht oder ihrem Inhalt.';

CREATE TABLE public.team_message_pins (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    message_id uuid NOT NULL
);

COMMENT ON TABLE public.team_message_pins IS 'TEAM-002 (ANN-645): angeheftete Nachrichten eines Gesprächs, höchstens 50, für alle, die es lesen. Fällt mit der Nachricht oder ihrem Inhalt - Dauerhaftes gehört in den Fachprozess (§10).';

CREATE TABLE public.team_message_reactions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    message_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    reaction text NOT NULL,
    CONSTRAINT team_message_reactions_reaction_check CHECK ((reaction = ANY (ARRAY['daumen'::text, 'erledigt'::text, 'augen'::text, 'danke'::text, 'herz'::text, 'lachen'::text, 'feier'::text, 'frage'::text])))
);

COMMENT ON TABLE public.team_message_reactions IS 'TEAM-002 (ANN-644): Reaktionen auf Nachrichten aus einer festen Auswahl. Wer reagiert hat, sehen alle, die das Gespräch lesen - eine freiwillige Antwort, keine Lesebestätigung, ohne Zeitpunkt (§20). Fällt mit der Nachricht oder ihrem Inhalt.';

CREATE TABLE public.team_read_states (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    read_up_to timestamp with time zone NOT NULL
);

COMMENT ON TABLE public.team_read_states IS 'TEAM-001, TEAM-002 (§20, ANN-609): der eigene Lesestand je Gespräch über das, was im Gespräch steht - Antworten im Thread zählt der Stand am Thread (team_thread_states). Nur für die eigenen Zähler, nur für die Person selbst lesbar, auch nicht für owner. Keine Lesebestätigung.';

COMMENT ON COLUMN public.team_read_states.read_up_to IS 'Erstellzeit der neuesten gesehenen Nachricht, nicht der Zeitpunkt des Lesens.';

CREATE TABLE public.team_saved_messages (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    message_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    remind_at timestamp with time zone,
    done boolean DEFAULT false NOT NULL
);

COMMENT ON TABLE public.team_saved_messages IS 'TEAM-002 (ANN-646): Nachrichten „für später“ - nur für die Person selbst lesbar, mit Erinnerung in der App und „erledigt“. Verlängert die Frist der Nachricht nicht; fällt mit ihr oder ihrem Inhalt, beim Verlassen des Gesprächs und mit dem Ausscheiden.';

CREATE TABLE public.team_thread_states (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    root_message_id uuid NOT NULL,
    staff_member_id uuid NOT NULL,
    following boolean DEFAULT true NOT NULL,
    read_up_to timestamp with time zone NOT NULL
);

COMMENT ON TABLE public.team_thread_states IS 'TEAM-002 (ANN-640): der eigene Stand an einem Thread - ob die Person folgt und bis zu welcher Nachricht sie ihn gesehen hat. Nur für die eigenen Zähler, nur für die Person selbst lesbar (ANN-609). Datenklasse teamchat.';

COMMENT ON COLUMN public.team_thread_states.read_up_to IS 'Erstellzeit der neuesten gesehenen Nachricht im Thread, nicht der Zeitpunkt des Lesens.';

CREATE TABLE public.territories (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    day_parts jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT territories_day_parts_check CHECK (app.territory_day_parts_valid(day_parts)),
    CONSTRAINT territories_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60)))
);

COMMENT ON TABLE public.territories IS 'Gebiete fuer die Terminvergabe (PRX-002): Name und Gebietstage. Praxisregel ohne Personenbezug. Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: Betriebsdaten.';

COMMENT ON COLUMN public.territories.day_parts IS 'Gebietstage [{weekday 1-7 ISO, part am|pm|day}]; am = Beginn vor 12:00, pm = Beginn ab 12:00, Praxiszeit (ANN-135).';

CREATE TABLE public.territory_postal_codes (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    territory_id uuid NOT NULL,
    postal_code text NOT NULL,
    CONSTRAINT territory_postal_codes_postal_code_check CHECK ((postal_code ~ '^[0-9]{5}$'::text))
);

COMMENT ON TABLE public.territory_postal_codes IS 'Postleitzahlen eines Gebiets (PRX-002, ANN-135). Eine Postleitzahl gehoert hoechstens zu einem Gebiet. Datenklasse: Betriebsdaten.';

CREATE TABLE public.therapy_reports (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    treatment_basis_id uuid NOT NULL,
    status text DEFAULT 'entwurf'::text NOT NULL,
    report_text text,
    report_text_updated_by uuid,
    report_text_updated_at timestamp with time zone,
    recommendation text,
    recommendation_updated_by uuid,
    recommendation_updated_at timestamp with time zone,
    note_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    body_chart_response_id uuid,
    snapshot jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    completed_at timestamp with time zone,
    completed_by uuid,
    supersedes_report_id uuid,
    change_reason text,
    CONSTRAINT therapy_reports_abschluss CHECK ((((status = 'abgeschlossen'::text) = (completed_at IS NOT NULL)) AND ((status = 'abgeschlossen'::text) = (snapshot IS NOT NULL)))),
    CONSTRAINT therapy_reports_change_reason_check CHECK (((change_reason IS NULL) OR ((length(btrim(change_reason)) >= 3) AND (length(btrim(change_reason)) <= 500)))),
    CONSTRAINT therapy_reports_correction_shape CHECK (((supersedes_report_id IS NULL) = (change_reason IS NULL))),
    CONSTRAINT therapy_reports_note_ids_check CHECK ((cardinality(note_ids) <= 50)),
    CONSTRAINT therapy_reports_recommendation_check CHECK (((recommendation IS NULL) OR ((length(btrim(recommendation)) >= 1) AND (length(btrim(recommendation)) <= 2000)))),
    CONSTRAINT therapy_reports_report_text_check CHECK (((report_text IS NULL) OR ((length(btrim(report_text)) >= 1) AND (length(btrim(report_text)) <= 8000)))),
    CONSTRAINT therapy_reports_status_check CHECK ((status = ANY (ARRAY['entwurf'::text, 'abgeschlossen'::text])))
);

COMMENT ON TABLE public.therapy_reports IS 'Therapieberichte an die Verordner:in (DOK-005, ANN-121). Entwurf aenderbar, abgeschlossen als Snapshot eingefroren. Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: Patientenakte, faellt mit der Akte.';

COMMENT ON COLUMN public.therapy_reports.recommendation IS 'Empfehlung der Therapeut:in zum Verordnungsende - von ihr formuliert und verantwortet, nie von der Anwendung erzeugt oder bewertet (ANN-014, ADR-006 Punkt 4).';

COMMENT ON COLUMN public.therapy_reports.supersedes_report_id IS 'Der abgeschlossene Bericht, den dieser korrigiert (ABN-016, BEF-104). Faellt mit ihm und der Akte.';

COMMENT ON COLUMN public.therapy_reports.change_reason IS 'Grund der Korrektur, 3 bis 500 Zeichen (ABN-016). Zeitpunkt und Verfasser:in sind created_at/created_by.';

CREATE TABLE public.training_assessment_results (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    assessment_id uuid NOT NULL,
    "position" smallint NOT NULL,
    label text NOT NULL,
    unit text,
    value numeric(9,2),
    value_left numeric(9,2),
    value_right numeric(9,2),
    CONSTRAINT training_assessment_results_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 80))),
    CONSTRAINT training_assessment_results_one_or_sides CHECK ((((value IS NOT NULL) AND (value_left IS NULL) AND (value_right IS NULL)) OR ((value IS NULL) AND (value_left IS NOT NULL) AND (value_right IS NOT NULL)))),
    CONSTRAINT training_assessment_results_position_check CHECK (("position" BETWEEN 1 AND 20)),
    CONSTRAINT training_assessment_results_unit_check CHECK (((unit IS NULL) OR ((length(btrim(unit)) >= 1) AND (length(btrim(unit)) <= 20))))
);

COMMENT ON TABLE public.training_assessment_results IS 'OUT-002 (IDEA-OUT-007): die Ergebnisse eines Assessments im Training, je Messung eine Zeile - ein Wert oder links und rechts. Unveraendert, ohne Einordnung. Datenklasse: Trainingsverhaeltnis, faellt mit dem Assessment.';

CREATE TABLE public.training_assessments (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    title text NOT NULL,
    performed_on date NOT NULL,
    conditions text,
    next_due_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    removed_at timestamp with time zone,
    removed_by uuid,
    CONSTRAINT training_assessments_conditions_check CHECK (((conditions IS NULL) OR ((length(btrim(conditions)) >= 1) AND (length(btrim(conditions)) <= 500)))),
    CONSTRAINT training_assessments_due_after CHECK (((next_due_on IS NULL) OR (next_due_on > performed_on))),
    CONSTRAINT training_assessments_performed_on_check CHECK ((performed_on >= '1900-01-01'::date)),
    CONSTRAINT training_assessments_removed_pair CHECK (((removed_at IS NULL) = (removed_by IS NULL))),
    CONSTRAINT training_assessments_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 80)))
);

COMMENT ON TABLE public.training_assessments IS 'OUT-002 (IDEA-OUT-007, ANN-365): durchgefuehrte Assessments im Training mit Messbedingungen und geplanter Wiederholung. Anzeigen und aufzeichnen, nicht bewerten (ADR-006 Punkt 13). Gesundheitsangabe, nur mit Einwilligung. Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: Trainingsverhaeltnis.';

CREATE TABLE public.training_bases (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    started_on date NOT NULL,
    agreed_quantity integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT training_bases_agreed_quantity_check CHECK (((agreed_quantity IS NULL) OR (agreed_quantity BETWEEN 1 AND 200))),
    CONSTRAINT training_bases_status_check CHECK ((status = ANY (ARRAY['active'::text, 'concluded'::text])))
);

COMMENT ON TABLE public.training_bases IS 'Trainingsgrundlage: die Planungsklammer des Trainingsverhaeltnisses (ADR-022 Punkt 5). Eigene Klammer neben public.treatment_bases, ausdruecklich KEINE dritte Bauart davon. Enthaelt KEINE klinischen Felder. Datenklasse: Trainingsverhaeltnis, drei Jahre ab Vertragsende (ADR-021 Punkt 4, ADR-008).';

COMMENT ON COLUMN public.training_bases.training_relationship_id IS 'Das Verhaeltnis, zu dem die Klammer gehoert. Bewusst kein Verweis auf public.patients und keiner auf public.treatment_bases (ADR-021 Punkt 3).';

COMMENT ON COLUMN public.training_bases.started_on IS 'Tag der Vereinbarung. Gegenstueck zu treatment_bases.issued_on, das bei einem Selbstzahler dasselbe bedeutet (ADR-020 Punkt 3).';

COMMENT ON COLUMN public.training_bases.agreed_quantity IS 'Vereinbarte Anzahl moeglicher Termine. NULLBAR - die Einzelstunde ohne Vereinbarung bleibt moeglich (ADR-022 Punkt 5). Keine Deckungsregel und kein used_quantity: was im Training abgerechnet wird, entscheidet ABR-EPIC-005.';

COMMENT ON COLUMN public.training_bases.created_by IS 'auth.users.id des handelnden Accounts. Ohne FK wie ueberall im Fundament (ADR-014).';

CREATE TABLE public.training_consent_records (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    record_kind text NOT NULL,
    purpose text NOT NULL,
    occurred_on date NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by uuid,
    source text DEFAULT 'practice'::text NOT NULL,
    platform_access_id uuid,
    platform_access_kind text,
    representative_name text,
    wording_version text,
    CONSTRAINT training_consent_records_platform_access_kind_check CHECK ((platform_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT training_consent_records_purpose_check CHECK ((purpose = ANY (ARRAY['training_health_data'::text, 'message_attachments'::text]))),
    CONSTRAINT training_consent_records_record_kind_check CHECK ((record_kind = ANY (ARRAY['consent_granted'::text, 'consent_withdrawn'::text]))),
    CONSTRAINT training_consent_records_representative_name_check CHECK (((representative_name IS NULL) OR ((length(btrim(representative_name)) >= 1) AND (length(btrim(representative_name)) <= 200)))),
    CONSTRAINT training_consent_records_representative_shape CHECK (((NOT (platform_access_kind IS DISTINCT FROM 'legal_representative'::text)) = (representative_name IS NOT NULL))),
    CONSTRAINT training_consent_records_source_check CHECK ((source = ANY (ARRAY['practice'::text, 'platform'::text]))),
    CONSTRAINT training_consent_records_source_shape CHECK ((((source = 'platform'::text) AND (platform_access_id IS NOT NULL) AND (platform_access_kind IS NOT NULL) AND (wording_version IS NOT NULL)) OR ((source = 'practice'::text) AND (platform_access_id IS NULL) AND (platform_access_kind IS NULL) AND (wording_version IS NULL)))),
    CONSTRAINT training_consent_records_wording_version_check CHECK ((wording_version ~ '^[0-9]{4}-[0-9]{2}$'::text))
);

COMMENT ON TABLE public.training_consent_records IS 'POR-017: Einwilligung zu Angaben zur Gesundheit im Training (Art. 9 Abs. 2 lit. a, ADR-021 Punkt 4). Nur anhaengen, nie aendern: der Stand ist die juengste Zeile. Datenklasse: Trainingsverhaeltnis, faellt mit ihm.';

CREATE TABLE public.training_contact_details (
    training_relationship_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    date_of_birth date,
    email text,
    phone text,
    street text,
    postal_code text,
    city text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone,
    updated_by uuid,
    house_number text,
    CONSTRAINT training_contact_details_city_check CHECK (((city IS NULL) OR ((length(btrim(city)) >= 1) AND (length(btrim(city)) <= 100)))),
    CONSTRAINT training_contact_details_email_check CHECK (((email IS NULL) OR (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))),
    CONSTRAINT training_contact_details_house_number_check CHECK (((house_number IS NULL) OR ((length(btrim(house_number)) >= 1) AND (length(btrim(house_number)) <= 20)))),
    CONSTRAINT training_contact_details_phone_check CHECK (((phone IS NULL) OR ((length(btrim(phone)) >= 3) AND (length(btrim(phone)) <= 40)))),
    CONSTRAINT training_contact_details_postal_code_check CHECK (((postal_code IS NULL) OR ((length(btrim(postal_code)) >= 2) AND (length(btrim(postal_code)) <= 12)))),
    CONSTRAINT training_contact_details_street_check CHECK (((street IS NULL) OR ((length(btrim(street)) >= 1) AND (length(btrim(street)) <= 200))))
);

COMMENT ON TABLE public.training_contact_details IS 'Kontakt- und Adressdaten im Trainingskontext (TRN-001). Gegenstueck zu patient_contact_details: haengt am Verhaeltnis, nicht an persons, damit Training und Behandlung keine Kontaktdaten teilen (ADR-021 Punkt 3). Keine Screening- und Gesundheitsangaben. Datenklasse: Trainingsverhaeltnis, faellt mit ihm.';

COMMENT ON COLUMN public.training_contact_details.house_number IS 'Hausnummer, getrennt von der Strasse wie in der Akte (ABN-020, BEF-111, ANN-177 Fassung 2).';

CREATE TABLE public.training_contracts (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    training_package_id uuid,
    package_label text NOT NULL,
    package_months smallint NOT NULL,
    price_cents integer NOT NULL,
    currency text NOT NULL,
    tax_rate_permille smallint NOT NULL,
    vat_included boolean NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    offered_on date NOT NULL,
    wording_version text NOT NULL,
    early_start_requested boolean NOT NULL,
    contact_released boolean NOT NULL,
    health_consent_granted boolean NOT NULL,
    concluded_at timestamp with time zone DEFAULT now() NOT NULL,
    concluded_on date NOT NULL,
    withdrawal_ends_on date NOT NULL,
    platform_access_id uuid NOT NULL,
    withdrawn_at timestamp with time zone,
    withdrawn_on date,
    withdrawn_platform_access_id uuid,
    withdrawn_access_kind text,
    withdrawn_representative_name text,
    CONSTRAINT training_contracts_package_months_check CHECK ((package_months BETWEEN 1 AND 24)),
    CONSTRAINT training_contracts_period CHECK ((ends_on >= starts_on)),
    CONSTRAINT training_contracts_price_cents_check CHECK ((price_cents >= 0)),
    CONSTRAINT training_contracts_withdrawal CHECK ((withdrawal_ends_on >= concluded_on)),
    CONSTRAINT training_contracts_withdrawal_shape CHECK ((((withdrawn_at IS NULL) AND (withdrawn_on IS NULL) AND (withdrawn_platform_access_id IS NULL) AND (withdrawn_access_kind IS NULL) AND (withdrawn_representative_name IS NULL)) OR ((withdrawn_at IS NOT NULL) AND (withdrawn_on IS NOT NULL) AND (withdrawn_platform_access_id IS NOT NULL) AND (withdrawn_access_kind IS NOT NULL) AND ((withdrawn_access_kind = 'legal_representative'::text) = (withdrawn_representative_name IS NOT NULL))))),
    CONSTRAINT training_contracts_withdrawn_access_kind_check CHECK ((withdrawn_access_kind = ANY (ARRAY['self'::text, 'legal_representative'::text]))),
    CONSTRAINT training_contracts_withdrawn_representative_name_check CHECK (((withdrawn_representative_name IS NULL) OR ((length(btrim(withdrawn_representative_name)) >= 1) AND (length(btrim(withdrawn_representative_name)) <= 200)))),
    CONSTRAINT training_contracts_wording_version_check CHECK ((wording_version ~ '^[0-9]{4}-[0-9]{2}$'::text))
);

COMMENT ON TABLE public.training_contracts IS 'KND-003 (PROJECT_PRINCIPLES.md 4.10): Nachweis eines Trainingsvertrags, den die Person im eigenen Konto geschlossen hat - Paket und Preis wie gebucht, Fassung der Widerrufsbelehrung, frueher Beginn, Freigaben (ANN-288). Datenklasse: Trainingsverhaeltnis, faellt mit ihm. Kein Tabellenrecht und keine Policy.';

COMMENT ON COLUMN public.training_contracts.offered_on IS 'Tag des Angebots aus der Akte - als Wert, ohne Verweis auf die Akte (ADR-021 Punkt 3).';

COMMENT ON COLUMN public.training_contracts.early_start_requested IS 'Die Person hat verlangt, dass das Training vor dem Ende der Widerrufsfrist beginnt (Par. 356 Abs. 4, 357a Abs. 2 BGB; ANN-288).';

COMMENT ON COLUMN public.training_contracts.withdrawn_at IS 'KND-004 (Par. 356a BGB): Eingang des Widerrufs ueber die Schaltflaeche im Konto. Loescht und storniert nichts selbst; die Praxis wickelt ab (ANN-290).';

CREATE TABLE public.training_course_events (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    occurred_on date NOT NULL,
    kind text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    removed_at timestamp with time zone,
    removed_by uuid,
    CONSTRAINT training_course_events_kind_check CHECK ((kind = ANY (ARRAY['operation'::text, 'erkrankung'::text, 'urlaub'::text, 'medikation'::text, 'sonstiges'::text]))),
    CONSTRAINT training_course_events_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 200)))),
    CONSTRAINT training_course_events_occurred_on_check CHECK ((occurred_on >= '1900-01-01'::date)),
    CONSTRAINT training_course_events_removed_pair CHECK (((removed_at IS NULL) = (removed_by IS NULL)))
);

COMMENT ON TABLE public.training_course_events IS 'OUT-001 (IDEA-OUT-005, ANN-364): Ereignisse im Verlauf eines Trainingsverhaeltnisses - Operation, Erkrankung, Urlaub, Medikation, Sonstiges. Markierung ohne Bewertung; Gesundheitsangabe, nur mit Einwilligung. Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: Trainingsverhaeltnis, faellt mit ihm.';

CREATE TABLE public.training_packages (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    catalog_item_id uuid NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT training_packages_end_after_start CHECK ((ends_on >= starts_on))
);

COMMENT ON TABLE public.training_packages IS 'Trainingspaket einer Kund:in (ANG-006, PROJECT_PRINCIPLES.md 4.10 und 19, ADR-009 Punkt 21): fester Zeitraum, nicht pausierbar, eine Leistung des Bereichs training zum Beginn (ANN-276, ANN-277). Datenklasse: Abrechnungsdaten; faellt mit dem Trainingsverhaeltnis (on delete cascade), nachdem die Leistung daraus geloescht ist (FK restrict). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

COMMENT ON COLUMN public.training_packages.catalog_item_id IS 'Die Position der Preisliste, die am Beginn galt. Sie ist unveraenderlich, sobald ihre Liste in Kraft ist - damit bleibt der Preis des Pakets fest (ADR-009 Punkt 5).';

COMMENT ON COLUMN public.training_packages.ends_on IS 'Letzter Tag des Pakets: Beginn plus Laufzeit der Position nach Paragraf 188 BGB (app.training_package_ends_on, ANN-277). Kein Pausieren, kein Verlaengern.';

CREATE TABLE public.training_profiles (
    training_relationship_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    goals text,
    equipment text,
    time_budget text,
    places text,
    limits text,
    history text,
    preferences text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT training_profiles_equipment_check CHECK (((equipment IS NULL) OR (char_length(equipment) BETWEEN 1 AND 1000))),
    CONSTRAINT training_profiles_goals_check CHECK (((goals IS NULL) OR (char_length(goals) BETWEEN 1 AND 1000))),
    CONSTRAINT training_profiles_history_check CHECK (((history IS NULL) OR (char_length(history) BETWEEN 1 AND 1000))),
    CONSTRAINT training_profiles_limits_check CHECK (((limits IS NULL) OR (char_length(limits) BETWEEN 1 AND 1000))),
    CONSTRAINT training_profiles_places_check CHECK (((places IS NULL) OR (char_length(places) BETWEEN 1 AND 1000))),
    CONSTRAINT training_profiles_preferences_check CHECK (((preferences IS NULL) OR (char_length(preferences) BETWEEN 1 AND 1000))),
    CONSTRAINT training_profiles_time_budget_check CHECK (((time_budget IS NULL) OR (char_length(time_budget) BETWEEN 1 AND 1000)))
);

COMMENT ON TABLE public.training_profiles IS 'KND-005 (IDEA-LZK-004): Voraussetzungsprofil einer Trainingskund:in - Ziele, Ausruestung, Zeitbudget, Orte, Belastungsgrenzen, Vorgeschichte, Vorlieben als Freitext. Gesundheitsangaben des Trainings (ADR-021 Punkt 4); owner und Trainingsbetreuung (ANN-287). Datenklasse: Trainingsverhaeltnis, faellt mit ihm. Kein Tabellenrecht und keine Policy: erreichbar nur ueber die Funktionen (ADR-004).';

CREATE TABLE public.training_protocol_addenda (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    protocol_id uuid NOT NULL,
    content text NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    CONSTRAINT training_protocol_addenda_content_check CHECK (((length(btrim(content)) >= 1) AND (length(btrim(content)) <= 5000))),
    CONSTRAINT training_protocol_addenda_reason_check CHECK (((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 500)))
);

COMMENT ON TABLE public.training_protocol_addenda IS 'Nachtraege zu abgeschlossenen Trainingsprotokollen mit Grund, Verfasser:in und Zeitpunkt (ABN-022, BEF-113, ANN-185 Fassung 2). Unveraenderlich; fallen mit dem Protokoll. Kein direkter Zugriff.';

CREATE TABLE public.training_protocols (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    content text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    finalized_at timestamp with time zone,
    finalized_by uuid,
    CONSTRAINT training_protocols_content_check CHECK (((length(btrim(content, E' \t\r\n'::text)) >= 1) AND (length(btrim(content, E' \t\r\n'::text)) <= 20000))),
    CONSTRAINT training_protocols_final_has_stamp CHECK (((status = 'final'::text) = ((finalized_at IS NOT NULL) AND (finalized_by IS NOT NULL)))),
    CONSTRAINT training_protocols_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'final'::text])))
);

COMMENT ON TABLE public.training_protocols IS 'Trainingsprotokoll je Trainingstermin (TRN-009, ADR-022 Punkt 7). Fachdatum des Trainingsverhaeltnisses, kein Eintrag nach ADR-016, keine klinische Bewertung (ADR-006 Punkt 9). Datenklasse: Trainingsverhaeltnis, drei Jahre ab Vertragsende.';

COMMENT ON COLUMN public.training_protocols.content IS 'Freitext der Einheit. Darf NIEMALS in Betriebslogs oder in den Auditkontext gelangen (ADR-010, ADR-011).';

COMMENT ON COLUMN public.training_protocols.created_by IS 'auth.users.id der verfassenden Person. Bewusst ohne FK, wie an der Behandlungsdokumentation.';

CREATE TABLE public.training_relationships (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    person_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    contract_started_on date,
    contract_ended_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT training_relationships_end_after_start CHECK (((contract_ended_on IS NULL) OR (contract_started_on IS NULL) OR (contract_ended_on >= contract_started_on))),
    CONSTRAINT training_relationships_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text])))
);

COMMENT ON TABLE public.training_relationships IS 'Trainingsverhaeltnis einer Person (Dienstvertrag ueber Training, Par. 611 BGB). Steht neben public.patients und teilt mit ihm ausschliesslich person_id (ADR-021 Punkt 2 und 3). Enthaelt KEINE klinischen und KEINE Screening-Angaben. Datenklasse: Trainingsverhaeltnis, drei Jahre ab Vertragsende (ADR-021 Punkt 4, ADR-008).';

COMMENT ON COLUMN public.training_relationships.person_id IS 'Die gemeinsame Identitaet - der einzige geteilte Punkt zwischen Training und Behandlung (ADR-021 Punkt 3). Bewusst kein Verweis auf public.patients.';

COMMENT ON COLUMN public.training_relationships.contract_started_on IS 'Beginn des Trainingsverhaeltnisses. Gegenstueck zu patients.care_started_on.';

COMMENT ON COLUMN public.training_relationships.contract_ended_on IS 'Anker der Aufbewahrungsfrist: Ende des Vertrages. Gesetzt und wieder raeumbar wie patients.care_concluded_on (LOE-001b); ohne ihn laeuft keine Frist und es wird nichts geloescht (ADR-008).';

COMMENT ON COLUMN public.training_relationships.created_by IS 'auth.users.id des handelnden Accounts. Ohne FK wie ueberall im Fundament (ADR-014).';

CREATE TABLE public.training_takeovers (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    training_relationship_id uuid NOT NULL,
    "position" smallint NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    source text DEFAULT 'treatment'::text NOT NULL,
    offered_on date NOT NULL,
    released_at timestamp with time zone DEFAULT now() NOT NULL,
    released_platform_access_id uuid NOT NULL,
    CONSTRAINT training_takeovers_body_check CHECK ((char_length(body) BETWEEN 1 AND 600)),
    CONSTRAINT training_takeovers_position_check CHECK (("position" BETWEEN 1 AND 5)),
    CONSTRAINT training_takeovers_source_check CHECK ((source = 'treatment'::text)),
    CONSTRAINT training_takeovers_title_check CHECK ((char_length(title) BETWEEN 1 AND 80))
);

COMMENT ON TABLE public.training_takeovers IS 'KND-005 (ADR-021 Punkt 7, ANN-283): Angaben aus der Behandlung, die die Person beim Abschluss des Trainingsvertrags einzeln freigegeben hat - als Kopie mit Herkunftsvermerk, nie als Verweis auf die Akte. Unveraenderlich. Datenklasse: Trainingsverhaeltnis, faellt mit ihm. Kein Tabellenrecht und keine Policy.';

CREATE TABLE public.treatment_base_items (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    treatment_basis_id uuid NOT NULL,
    sort_order smallint NOT NULL,
    remedy text NOT NULL,
    prescribed_quantity smallint NOT NULL,
    used_quantity smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT treatment_base_items_prescribed_quantity_check CHECK ((prescribed_quantity BETWEEN 1 AND 500)),
    CONSTRAINT treatment_base_items_remedy_check CHECK (((length(btrim(remedy)) >= 1) AND (length(btrim(remedy)) <= 200))),
    CONSTRAINT treatment_base_items_sort_order_check CHECK ((sort_order BETWEEN 1 AND 50)),
    CONSTRAINT treatment_base_items_used_quantity_check CHECK ((used_quantity >= 0)),
    CONSTRAINT treatment_base_items_used_within_prescribed CHECK ((used_quantity <= prescribed_quantity))
);

COMMENT ON TABLE public.treatment_base_items IS 'Positionen einer Behandlungsgrundlage: Heilmittel, verordnete beziehungsweise vereinbarte und genutzte Menge (VER-001, ADR-020 Punkt 5). Datenklasse wie die Grundlage. Kein Tabellenrecht und keine Policy.';

COMMENT ON COLUMN public.treatment_base_items.remedy IS 'Bezeichnung des Heilmittels als Freitext, etwa "Krankengymnastik". Ein versionierter Katalog kommt mit ABR-001; bis dahin waere eine Auswahlliste eine Erfindung ohne Preise.';

COMMENT ON COLUMN public.treatment_base_items.prescribed_quantity IS 'Leistungsmenge dieses Heilmittels (ANN-064). Seit VER-EPIC-002 ausdruecklich NICHT die Terminzahl - die steht in treatment_bases.appointment_count.';

COMMENT ON COLUMN public.treatment_base_items.used_quantity IS 'Genutzte Leistungsmenge. Seit VER-EPIC-002 keine Eingabe der Oberflaeche mehr; der Bestand bleibt stehen, fortgeschrieben wird sie mit ABR-002 (ANN-064 loest ANN-012 ab).';

CREATE TABLE public.treatment_bases (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    prescriber_id uuid,
    treatment_basis_kind text NOT NULL,
    issued_on date NOT NULL,
    frequency_note text,
    note text,
    diagnosis text,
    therapy_goal text,
    prescriber_note text,
    follow_up_recommendation text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    appointment_count integer NOT NULL,
    diagnosis_icd10 text,
    billing_released_at timestamp with time zone,
    billing_released_by uuid,
    billing_withdrawn_at timestamp with time zone,
    billing_withdrawn_by uuid,
    had_appointments boolean DEFAULT false NOT NULL,
    CONSTRAINT treatment_bases_appointment_count_check CHECK ((appointment_count BETWEEN 1 AND 500)),
    CONSTRAINT treatment_bases_billing_release_complete CHECK (((billing_released_at IS NULL) = (billing_released_by IS NULL))),
    CONSTRAINT treatment_bases_clinical_only_for_prescription CHECK (((treatment_basis_kind <> 'self_pay'::text) OR ((diagnosis IS NULL) AND (therapy_goal IS NULL) AND (prescriber_note IS NULL) AND (follow_up_recommendation IS NULL)))),
    CONSTRAINT treatment_bases_diagnosis_check CHECK (((diagnosis IS NULL) OR ((length(btrim(diagnosis)) >= 1) AND (length(btrim(diagnosis)) <= 2000)))),
    CONSTRAINT treatment_bases_diagnosis_icd10_check CHECK ((diagnosis_icd10 ~ '^[A-Z][0-9]{2}(\.[0-9A-Z!*+-]{1,5})?[GVZALR]?$'::text)),
    CONSTRAINT treatment_bases_follow_up_recommendation_check CHECK (((follow_up_recommendation IS NULL) OR ((length(btrim(follow_up_recommendation)) >= 1) AND (length(btrim(follow_up_recommendation)) <= 2000)))),
    CONSTRAINT treatment_bases_frequency_note_check CHECK (((frequency_note IS NULL) OR ((length(btrim(frequency_note)) >= 1) AND (length(btrim(frequency_note)) <= 100)))),
    CONSTRAINT treatment_bases_icd10_only_for_prescription CHECK (((treatment_basis_kind <> 'self_pay'::text) OR (diagnosis_icd10 IS NULL))),
    CONSTRAINT treatment_bases_kind_check CHECK ((treatment_basis_kind = ANY (ARRAY['first'::text, 'follow_up'::text, 'self_pay'::text]))),
    CONSTRAINT treatment_bases_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 2000)))),
    CONSTRAINT treatment_bases_prescriber_matches_kind CHECK (
CASE treatment_basis_kind
    WHEN 'self_pay'::text THEN (prescriber_id IS NULL)
    ELSE (prescriber_id IS NOT NULL)
END),
    CONSTRAINT treatment_bases_prescriber_note_check CHECK (((prescriber_note IS NULL) OR ((length(btrim(prescriber_note)) >= 1) AND (length(btrim(prescriber_note)) <= 2000)))),
    CONSTRAINT treatment_bases_therapy_goal_check CHECK (((therapy_goal IS NULL) OR ((length(btrim(therapy_goal)) >= 1) AND (length(btrim(therapy_goal)) <= 2000))))
);

COMMENT ON TABLE public.treatment_bases IS 'Behandlungsgrundlage: die Klammer, an der ein Termin haengt (GRD-001, ADR-020). Zwei Bauarten - Verordnung (first, follow_up) und Selbstzahler (self_pay). Enthaelt Gesundheitsdaten. Datenklasse: klinische Patientenakte, 10 Jahre nach Abschluss der Behandlung (ADR-008, ANN-011). Kein Tabellenrecht und keine Policy: erreichbar nur ueber die rollenabhaengigen Lesefunktionen (ADR-004).';

COMMENT ON COLUMN public.treatment_bases.prescriber_id IS 'Verordner:in - Pflicht bei first und follow_up, ausgeschlossen bei self_pay (ADR-020 Punkt 3, Constraint treatment_bases_prescriber_matches_kind).';

COMMENT ON COLUMN public.treatment_bases.treatment_basis_kind IS 'Die Bauart: first und follow_up sind Verordnungen, self_pay ist der Selbstzahler (ADR-020 Punkt 1). Bewusst nicht der GKV-Rezepttyp: die Praxis rechnet privat ab, das Privatrezept IST die Verordnung (ADR-009, ADR-020).';

COMMENT ON COLUMN public.treatment_bases.issued_on IS 'Ausstellungsdatum der Verordnung; beim Selbstzahler der Tag der Vereinbarung (ADR-020 Punkt 3). Pflicht fuer beide Bauarten.';

COMMENT ON COLUMN public.treatment_bases.frequency_note IS 'Verordnete beziehungsweise vereinbarte Frequenz als Freitext, wie sie auf dem Papier steht ("2x pro Woche"). Organisatorisch. Bewusst keine Zahl: "1-2x" liesse sich sonst nicht erfassen.';

COMMENT ON COLUMN public.treatment_bases.note IS 'Organisatorische Bemerkung zur Grundlage. Fuer alle Praxisrollen sichtbar - klinische Angaben gehoeren in die Felder darunter.';

COMMENT ON COLUMN public.treatment_bases.diagnosis IS 'Diagnose beziehungsweise Leitsymptomatik der Verordnung. KLINISCH (PROJECT_PRINCIPLES.md 4.3). Beim Selbstzahler leer: die Oberflaeche fragt sie dort nicht ab (ADR-020 Punkt 4).';

COMMENT ON COLUMN public.treatment_bases.prescriber_note IS 'Behandlungsrelevanter Hinweis aus der Verordnung (klinisch), etwa eine Belastungsgrenze. Seit ABN-007 wieder beschreibbar, nur ueber public.set_treatment_basis_clinical_note; lesbar in der klinischen Sicht (BEF-098, ANN-214).';

COMMENT ON COLUMN public.treatment_bases.follow_up_recommendation IS 'Empfehlung der Therapeut:in zum Verordnungsende, von ihr selbst erfasst (ANN-014). KLINISCH. Ausdruecklich KEINE Systemempfehlung: die Anwendung erzeugt keine Therapieempfehlung (ADR-006 Punkt 4).';

COMMENT ON COLUMN public.treatment_bases.appointment_count IS 'Anzahl moeglicher Termine dieser Grundlage - verordnet beim Rezept, vereinbart beim Selbstzahler (ADR-020 Punkt 5, VER-EPIC-002, ANN-064). Eine Terminzahl, keine Summe von Heilmitteln: die Leistungsmenge steht an der Position.';

COMMENT ON COLUMN public.treatment_bases.diagnosis_icd10 IS 'ICD-10-GM-Code der Verordnung, etwa G20.00 oder M54.5G (Akte entschlacken, 2026-10-03). Klinisch wie diagnosis; beim Selbstzahler leer.';

COMMENT ON COLUMN public.treatment_bases.billing_released_at IS 'B7 (BEF-157, ADR-020 Fassung 2): in die Abrechnung gestellt am. Gesetzt sperrt die Grundlage Doku, Zeitpunkt und Anzahl ihrer Termine (ANN-515). Organisatorisch, kein klinischer Inhalt; Datenklasse der Grundlage (klinische Patientenakte).';

COMMENT ON COLUMN public.treatment_bases.billing_released_by IS 'B7: auth.users.id der Person, die freigegeben hat. Ohne FK wie created_by, damit ein spaeter geloeschtes Konto den Nachweis nicht entfernt.';

COMMENT ON COLUMN public.treatment_bases.billing_withdrawn_at IS 'B7: zuletzt aus der Abrechnung zurueckgeholt am (leer, solange nie zurueckgeholt).';

COMMENT ON COLUMN public.treatment_bases.billing_withdrawn_by IS 'B7: auth.users.id der Person, die zuletzt zurueckgeholt hat.';

COMMENT ON COLUMN public.treatment_bases.had_appointments IS 'Hing je ein Termin an dieser Grundlage (BEF-124, ANN-562)? Einmal gesetzt, bleibt er; delete_treatment_basis weist sie dann ab. Gesetzt nur vom Trigger an appointments.';

COMMENT ON CONSTRAINT treatment_bases_clinical_only_for_prescription ON public.treatment_bases IS 'ADR-020 Punkt 4: Diagnose, Therapieziel, Verordnerhinweis und Empfehlung gehoeren zur Verordnung. Beim Selbstzahler bleiben sie leer - unabhaengig davon, welchen Schreibweg jemand nimmt.';

COMMENT ON CONSTRAINT treatment_bases_prescriber_matches_kind ON public.treatment_bases IS 'ADR-020 Punkt 3: Was eine Verordnung braucht, verlangt die Datenbank weiter - aber nur von ihr. Ein Selbstzahler hat keine Verordner:in.';

CREATE TABLE public.treatment_basis_versions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    treatment_basis_id uuid NOT NULL,
    version_no integer NOT NULL,
    content jsonb NOT NULL,
    replaced_at timestamp with time zone DEFAULT now() NOT NULL,
    replaced_by uuid,
    CONSTRAINT treatment_basis_versions_content_check CHECK ((jsonb_typeof(content) = 'object'::text)),
    CONSTRAINT treatment_basis_versions_version_no_check CHECK ((version_no >= 1))
);

COMMENT ON TABLE public.treatment_basis_versions IS 'Fruehere Staende einer Behandlungsgrundlage (BEF-124, ANN-562, § 630f Abs. 1 BGB): je Aenderung der Inhalt VOR ihr, mit Zeitpunkt und Person. Geschrieben nur von Triggern, nie geaendert. Enthaelt Gesundheitsdaten. Datenklasse: klinische Patientenakte wie die Grundlage, faellt mit ihr (FK on delete cascade, ADR-008). Kein Tabellenrecht und keine Policy: gelesen nur ueber list_treatment_basis_versions.';

COMMENT ON COLUMN public.treatment_basis_versions.version_no IS 'Fortlaufend je Grundlage ab 1. Fassung 1 ist der erste ersetzte Stand; der aktuelle Stand steht in treatment_bases.';

COMMENT ON COLUMN public.treatment_basis_versions.content IS 'Der Inhalt bis zu dieser Aenderung, wie app.treatment_basis_content ihn bildet: Bauart, Verordner:in (Kennung und Name zu dem Zeitpunkt), Datum, Terminzahl, Frequenz, Anmerkung, die klinischen Felder und die Positionen (Heilmittel, Menge). KLINISCH.';

COMMENT ON COLUMN public.treatment_basis_versions.replaced_at IS 'Wann dieser Stand ersetzt wurde (Beginn der Transaktion). Gueltig war er ab der vorigen Fassung, bei Fassung 1 ab created_at der Grundlage.';

COMMENT ON COLUMN public.treatment_basis_versions.replaced_by IS 'Wer ihn ersetzt hat (auth.uid()); leer nur bei Aenderungen ausserhalb einer Anmeldung, etwa einer Migration. Bewusst ohne Fremdschluessel wie treatment_note_versions.author_id: Der Verlauf ueberdauert ein geloeschtes Konto.';

CREATE TABLE public.treatment_draft_findings (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    findings jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT treatment_draft_findings_findings_check CHECK (((jsonb_typeof(findings) = 'object'::text) AND (octet_length((findings)::text) <= 65536)))
);

COMMENT ON TABLE public.treatment_draft_findings IS 'Gesicherte, noch nicht uebernommene Befundangaben aus den Bausteinen je Behandlungstermin (ABN-015, BEF-103, ANN-120 Fassung 2). Kein Teil der Dokumentation; faellt beim Festschreiben weg. Kein direkter Zugriff.';

CREATE TABLE public.treatment_note_versions (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    note_id uuid NOT NULL,
    version_no integer NOT NULL,
    content text NOT NULL,
    change_reason text,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    author_id uuid NOT NULL,
    CONSTRAINT treatment_note_versions_change_reason_check CHECK (((change_reason IS NULL) OR ((length(btrim(change_reason, E' \t\r\n'::text)) >= 1) AND (length(btrim(change_reason, E' \t\r\n'::text)) <= 500)))),
    CONSTRAINT treatment_note_versions_content_check CHECK (((length(btrim(content, E' \t\r\n'::text)) >= 1) AND (length(btrim(content, E' \t\r\n'::text)) <= 20000))),
    CONSTRAINT treatment_note_versions_reason_only_on_correction CHECK (((version_no = 1) = (change_reason IS NULL))),
    CONSTRAINT treatment_note_versions_version_no_check CHECK ((version_no >= 1))
);

COMMENT ON TABLE public.treatment_note_versions IS 'Festgeschriebene Staende einer Behandlungsdokumentation (ADR-016 Punkt 5, 630f Abs. 1 BGB). Enthaelt klinischen Freitext. Datenklasse: klinische Patientenakte, 10 Jahre nach Behandlungsabschluss (ADR-008).';

COMMENT ON COLUMN public.treatment_note_versions.content IS 'Klinischer Freitext dieser Version. Darf NIEMALS in Betriebslogs oder in den Auditkontext gelangen (ADR-010, ADR-011).';

COMMENT ON COLUMN public.treatment_note_versions.change_reason IS 'Begruendung der Korrektur. Kann klinische Angaben enthalten und wird deshalb wie Inhalt behandelt - insbesondere niemals im Auditlog.';

COMMENT ON COLUMN public.treatment_note_versions.recorded_at IS 'Zeitpunkt, zu dem dieser Stand festgeschrieben wurde - bei Version 1 die Finalisierung, sonst die Korrektur.';

COMMENT ON COLUMN public.treatment_note_versions.author_id IS 'auth.users.id der Person, von der der Text dieser Version stammt (ADR-016 Punkt 1). Bei Version 1 ist das die zuletzt am Entwurf schreibende Person, nicht zwingend die finalisierende.';

CREATE TABLE public.treatment_notes (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    content text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    finalized_at timestamp with time zone,
    finalized_by uuid,
    addendum_to_note_id uuid,
    finalisation_kind text,
    visit_without_treatment boolean DEFAULT false NOT NULL,
    offline_id uuid,
    reported_written_at timestamp with time zone,
    CONSTRAINT treatment_notes_addendum_not_self CHECK (((addendum_to_note_id IS NULL) OR (addendum_to_note_id <> id))),
    CONSTRAINT treatment_notes_content_check CHECK (((length(btrim(content, E' \t\r\n'::text)) >= 1) AND (length(btrim(content, E' \t\r\n'::text)) <= 20000))),
    CONSTRAINT treatment_notes_finalisation_consistent CHECK (
CASE
    WHEN (status = 'draft'::text) THEN ((finalized_at IS NULL) AND (finalized_by IS NULL) AND (finalisation_kind IS NULL))
    WHEN (finalisation_kind = 'manual'::text) THEN ((finalized_at IS NOT NULL) AND (finalized_by IS NOT NULL))
    WHEN (finalisation_kind = 'automatic'::text) THEN ((finalized_at IS NOT NULL) AND (finalized_by IS NULL))
    ELSE false
END),
    CONSTRAINT treatment_notes_finalisation_kind_check CHECK ((finalisation_kind = ANY (ARRAY['manual'::text, 'automatic'::text]))),
    CONSTRAINT treatment_notes_offline_consistent CHECK (((offline_id IS NULL) = (reported_written_at IS NULL))),
    CONSTRAINT treatment_notes_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'final'::text])))
);

COMMENT ON TABLE public.treatment_notes IS 'Behandlungsdokumentation zu einem Termin. Enthaelt klinischen Freitext. Datenklasse: klinische Patientenakte, 10 Jahre nach Behandlungsabschluss (ADR-008).';

COMMENT ON COLUMN public.treatment_notes.status IS 'Lebenszyklus nach ADR-016 Punkt 2: Entwurf oder finalisiert. Ein finalisierter Eintrag wird ausschliesslich ueber revise_treatment_note geaendert.';

COMMENT ON COLUMN public.treatment_notes.content IS 'Klinischer Freitext. Darf NIEMALS in Betriebslogs oder in den Auditkontext gelangen (ADR-010, ADR-011).';

COMMENT ON COLUMN public.treatment_notes.created_by IS 'auth.users.id der verfassenden Person (PROJECT_PRINCIPLES.md 5). Bewusst ohne FK, damit ein spaeter geloeschter Account die Urheberschaft nicht entfernt.';

COMMENT ON COLUMN public.treatment_notes.updated_by IS 'auth.users.id der zuletzt aendernden Person (PROJECT_PRINCIPLES.md 5).';

COMMENT ON COLUMN public.treatment_notes.finalized_at IS 'Zeitpunkt der Finalisierung (ADR-016 Punkt 4). Ab hier ist der Eintrag Bestandteil der Akte.';

COMMENT ON COLUMN public.treatment_notes.finalized_by IS 'auth.users.id der finalisierenden Person bei manueller Finalisierung. Bewusst ohne FK, damit ein spaeter geloeschter Account die Urheberschaft nicht entfernt. Bei automatischer Finalisierung leer (DOK-004).';

COMMENT ON COLUMN public.treatment_notes.addendum_to_note_id IS 'Gesetzt, wenn dieser Eintrag ein Nachtrag zu einem finalisierten Eintrag ist (ADR-016 Punkt 6). Nachtraege zu Nachtraegen gibt es nicht.';

COMMENT ON COLUMN public.treatment_notes.finalisation_kind IS 'Wie der Eintrag finalisiert wurde: manual durch eine therapeutische Rolle (DOK-002), automatic nach Fristablauf ohne handelnde Person (DOK-004, ADR-016 Punkt 7).';

COMMENT ON COLUMN public.treatment_notes.visit_without_treatment IS 'Pflichtvermerk aus Hausbesuch-Szenario 1 (ADR-018 Fassung 3 Punkt 9): Die Tuer wurde geoeffnet, die Behandlung fand auf Angabe der Patient:in nicht statt. Der Termin gilt trotzdem als durchgefuehrt und wird normal abgerechnet; eine Ausfallgebuehr entsteht NICHT. Gesetzt wird das Merkmal im Abschluss (complete_treatment), nie nachtraeglich von Hand.';

COMMENT ON COLUMN public.treatment_notes.offline_id IS 'OFF-002 (ADR-024 Punkt 7, ANN-362): Kennung, die das Diensttelefon dem ohne Verbindung geschriebenen Entwurf gegeben hat - damit ein zweites Senden nichts doppelt anlegt. Nur fuer created_by eindeutig. Datenklasse wie der Eintrag (klinische Patientenakte).';

COMMENT ON COLUMN public.treatment_notes.reported_written_at IS 'OFF-002 (ADR-024 Punkt 8): letzte Aenderung des Offline-Entwurfs nach der Uhr des Geraets - eine Angabe der Person, keine gepruefte Zeit. created_at ist der Eingang am Server. Datenklasse und Frist wie der Eintrag.';

CREATE TABLE public.treatment_text_snippets (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    staff_member_id uuid,
    title text NOT NULL,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT treatment_text_snippets_body_check CHECK (((length(btrim(body, E' \t\r\n'::text)) >= 1) AND (length(btrim(body, E' \t\r\n'::text)) <= 2000))),
    CONSTRAINT treatment_text_snippets_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 80)))
);

COMMENT ON TABLE public.treatment_text_snippets IS 'Textbausteine fuer die Behandlungsdokumentation (UX-008). Persoenlich (staff_member_id gesetzt) oder praxisweit (null). Datenklasse: Betriebsdaten der Praxis OHNE Patientenbezug - keine Gesundheitsdaten (ANN-020). Frist: bis zur Loeschung durch die Praxis; persoenliche Bausteine enden mit dem Mitarbeiterdatensatz. Freitext, der nie in Logs erscheinen darf (ADR-011).';

COMMENT ON COLUMN public.treatment_text_snippets.staff_member_id IS 'Persoenlicher Baustein dieser Person; null bedeutet praxisweit. KEINE Zugriffsbeschraenkung auf Akten - nur die Sichtbarkeit des Bausteins.';

COMMENT ON COLUMN public.treatment_text_snippets.body IS 'Der einzufuegende Text. Enthaelt bewusst keine Platzhalter und keine Werte aus der Akte (E-9, erste Stufe).';

CREATE TABLE public.waitlist_entries (
    id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    treatment_basis_id uuid,
    preferred_staff_member_id uuid,
    appointment_type text NOT NULL,
    duration_minutes smallint DEFAULT 60 NOT NULL,
    time_windows jsonb DEFAULT '[]'::jsonb NOT NULL,
    earliest_on date,
    needed_by date,
    priority_reason text NOT NULL,
    note text,
    status text DEFAULT 'open'::text NOT NULL,
    placed_appointment_id uuid,
    closed_at timestamp with time zone,
    closed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT waitlist_entries_appointment_type_check CHECK ((appointment_type = ANY (ARRAY['home_visit'::text, 'practice'::text, 'video'::text]))),
    CONSTRAINT waitlist_entries_closed CHECK (((status = 'open'::text) = (closed_at IS NULL))),
    CONSTRAINT waitlist_entries_dates CHECK (((earliest_on IS NULL) OR (needed_by IS NULL) OR (needed_by >= earliest_on))),
    CONSTRAINT waitlist_entries_duration_minutes_check CHECK ((duration_minutes BETWEEN 5 AND 240)),
    CONSTRAINT waitlist_entries_note_check CHECK (((note IS NULL) OR ((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 500)))),
    CONSTRAINT waitlist_entries_placed CHECK (((status = 'placed'::text) OR (placed_appointment_id IS NULL))),
    CONSTRAINT waitlist_entries_priority_reason_check CHECK ((priority_reason = ANY (ARRAY['patient_wish'::text, 'prescription_ending'::text, 'practice_priority'::text]))),
    CONSTRAINT waitlist_entries_status_check CHECK ((status = ANY (ARRAY['open'::text, 'placed'::text, 'withdrawn'::text]))),
    CONSTRAINT waitlist_entries_time_windows_check CHECK (app.waitlist_windows_valid(time_windows))
);

COMMENT ON TABLE public.waitlist_entries IS 'Warteliste mit Wunschfenstern (PRX-001). Kein direkter Zugriff, nur ueber die Funktionen. Datenklasse: offen mit der Akte, geschlossen zwoelf Monate nach dem Schliessen (warteliste, ANN-133).';

COMMENT ON COLUMN public.waitlist_entries.time_windows IS 'Wunschfenster [{weekday 1-7 ISO, from HH:MM, to HH:MM}] in Praxiszeit; leer heisst jederzeit.';

COMMENT ON COLUMN public.waitlist_entries.priority_reason IS 'Organisatorischer Grund der Dringlichkeit (ANN-132): patient_wish, prescription_ending, practice_priority. Nie klinisch (ADR-006 Punkt 4).';

COMMENT ON COLUMN public.waitlist_entries.note IS 'Organisatorische Notiz (Erreichbarkeit, Absprachen). Keine klinischen Angaben - das Feld sagt es in der Oberflaeche.';



































INSERT INTO public.food_sources (id, source, title, publisher, license, license_url, attribution, source_url, version, imported_at, item_count) VALUES ('824041a6-4911-4040-8abd-66f7d60c4b62', 'bls', 'Bundeslebensmittelschlüssel (BLS), Version 4.0', 'Max Rubner-Institut', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/deed.de', 'Max Rubner-Institut (2025): Bundeslebensmittelschlüssel (BLS), Version 4.0 – Deutsche Nährstoffdatenbank. Karlsruhe. DOI: 10.25826/Data20251217-134202-0. Lizenz CC BY 4.0. Geändert: Auswahl der Nährstoffe, Salz aus Natrium berechnet, Namen für die Suche vereinheitlicht, Portionen ergänzt.', 'https://www.blsdb.de', NULL, NULL, 0);
INSERT INTO public.food_sources (id, source, title, publisher, license, license_url, attribution, source_url, version, imported_at, item_count) VALUES ('0d696707-d23b-4e66-a062-b12f37b71d1f', 'off', 'Open Food Facts, Auszug Deutschland', 'Open Food Facts', 'ODbL 1.0', 'https://opendatacommons.org/licenses/odbl/1-0/', 'Enthält Daten von Open Food Facts (openfoodfacts.org), verfügbar unter der Open Database License (ODbL 1.0). Auszug: in Deutschland verkaufte Produkte mit Nährwerten.', 'https://world.openfoodfacts.org', NULL, NULL, 0);




























INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('verordnungsscan', true, 10, 'Foto oder Scan des Verordnungsblatts (VER-004). Klinisch, weil das Blatt die Diagnose zeigt und ein Bild sich nicht projizieren laesst (ANN-011).');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('befund', true, 20, 'Befund einer aerztlichen oder therapeutischen Untersuchung.');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('arztbrief', true, 30, 'Schreiben einer aerztlichen Stelle zur Patientin oder zum Patienten.');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('einwilligung', false, 50, 'Unterschriebene Einwilligung oder Datenschutzinformation. Organisatorisch: office sieht sie.');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('vertrag', false, 60, 'Behandlungsvertrag und vergleichbare Vereinbarungen. Organisatorisch: office sieht sie.');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('dokumentationsfoto', true, 44, 'Foto, das die Praxis von der Person aufnimmt, weil es fuer die Dokumentation der Behandlung erforderlich ist - Ausgangsbefund, Wunde oder Narbe im Verlauf. Teil der Akte (Art. 9 Abs. 2 lit. h DSGVO, zehn Jahre, keine Einwilligung). Entsteht nur im Kameradialog; loeschen nur am Aufnahmetag (ADR-017 Abschnitt H).');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('patientenfoto', true, 45, 'Foto-Arbeitshilfe: Foto, das die Praxis von der Person fuer Uebergabe und Vergleich aufnimmt und das die Dokumentation nicht braucht. Entsteht nur im Kameradialog, braucht die eigene Einwilligung (Zweck patient_photos) und hat eine eigene, kurze Frist (ADR-017 Punkte 35 bis 38 und 43).');
INSERT INTO public.patient_file_document_types (key, is_clinical, sort_order, note) VALUES ('klinisches_bild', true, 40, 'Bildgebung und Aufnahmen aus aerztlicher oder klinischer Hand: Roentgen, MRT, Ultraschall, das Wundfoto im Klinikbericht. Nie ein Foto, das die Praxis selbst von der Person macht - das ist ein Dokumentationsfoto oder eine Arbeitshilfe (ADR-017 Punkte 31 und 43).');





















INSERT INTO public.questionnaire_definitions (id, instrument_id, version, definition, created_at) VALUES ('4d8ff5ff-0ec4-4229-b7d6-1495ebff2078', 'anamnese_v8', '1.0.0', '{"meta": {"id": "anamnese_v8", "aktiv": true, "quelle": {"datei": "Anamnesebogen_Version-8_DIGOTOR_07-2026.pdf", "validierung": "DIGOTOR GbR, Version 8, 07/2026"}, "region": "Allgemein / Erstkontakt", "name_de": "Anamnesebogen Version 8 (DIGOTOR)", "sprache": "de", "version": "1.0.0", "konstrukt": "Anamnese, Schmerzlokalisation, Red Flags, Vorgeschichte", "prioritaet": "a", "lizenzstatus": {"stand": "2026-09-21", "status": "freigegeben", "begruendung": "Erklärung von Jannes vom 2026-09-21: keine Lizenzierung, Integration freigegeben; schriftlicher Beleg offen als B8 (ANN-086)."}, "ausgefuellt_von": "patient"}, "items": [{"id": "beruf", "typ": "freitext", "text": "Beruf:", "gewertet": false}, {"id": "sport_hobby", "typ": "freitext", "text": "Sport/Hobby:", "gewertet": false}, {"id": "beschwerden_ort", "typ": "koerperschema", "text": "Wo haben Sie Ihre Beschwerden (bitte einzeichnen)?", "nummer": 1, "gewertet": false}, {"id": "schmerzen_aktuell", "typ": "einzelauswahl", "text": "Haben Sie aktuell Schmerzen?", "nummer": 2, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "schmerzstaerke", "typ": "skala", "text": "Wie stark sind Ihre Schmerzen? (bitte kennzeichnen)", "anker": {"max": "maximaler Schmerz", "min": "kein Schmerz"}, "skala": {"max": 10, "min": 0}, "nummer": 3, "gewertet": false}, {"id": "schmerzart", "typ": "mehrfachauswahl", "text": "Haben Sie: Ruheschmerzen, Nachtschmerzen, Dauerschmerzen?", "nummer": 4, "gewertet": false, "optionen": [{"id": "ruheschmerzen", "label": "Ruheschmerzen"}, {"id": "nachtschmerzen", "label": "Nachtschmerzen"}, {"id": "dauerschmerzen", "label": "Dauerschmerzen"}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "beweglichkeit_veraendert", "typ": "einzelauswahl", "text": "Ist Ihre Beweglichkeit verändert?", "nummer": 5, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "kraft_vermindert", "typ": "einzelauswahl", "text": "Ist Ihre Kraft vermindert?", "nummer": 6, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "merkmale", "typ": "mehrfachauswahl", "text": "Weisen Ihre Beschwerden eines der folgenden Merkmale auf: Kribbeln, Piksen, Brennen, Juckreiz, Taubheitsgefühl, Gefühl einer schmerzhaften Kälte, elektrische Schläge?", "nummer": 7, "gewertet": false, "optionen": [{"id": "kribbeln", "label": "Kribbeln"}, {"id": "piksen", "label": "Piksen"}, {"id": "brennen", "label": "Brennen"}, {"id": "juckreiz", "label": "Juckreiz"}, {"id": "taubheitsgefuehl", "label": "Taubheitsgefühl"}, {"id": "schmerzhafte_kaelte", "label": "Gefühl einer schmerzhaften Kälte"}, {"id": "elektrische_schlaege", "label": "elektrische Schläge"}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "weitere_beschwerden", "typ": "freitext", "text": "Haben Sie noch weitere Beschwerden?", "nummer": 8, "gewertet": false}, {"id": "beschwerden_seit", "typ": "freitext", "text": "Seit wann haben Sie Ihre Beschwerden?", "nummer": 9, "gewertet": false}, {"id": "beschwerden_zeitlich", "typ": "einzelauswahl", "text": "Haben Sie Ihre Beschwerden: permanent, mit Unterbrechungen?", "nummer": 10, "gewertet": false, "optionen": [{"id": "permanent", "label": "permanent"}, {"id": "mit_unterbrechungen", "label": "mit Unterbrechungen"}]}, {"id": "beschwerden_verlauf", "typ": "einzelauswahl", "text": "Sind Ihre Beschwerden: besser geworden, gleichbleibend, schlechter geworden, wechselnd?", "nummer": 11, "gewertet": false, "optionen": [{"id": "besser_geworden", "label": "besser geworden"}, {"id": "gleichbleibend", "label": "gleichbleibend"}, {"id": "schlechter_geworden", "label": "schlechter geworden"}, {"id": "wechselnd", "label": "wechselnd"}]}, {"id": "verbessert_durch", "typ": "mehrfachauswahl", "text": "a) Was verbessert Ihre Beschwerden:", "nummer": 12, "gewertet": false, "optionen": [{"id": "aktivitaet", "label": "Aktivität"}, {"id": "ruhe", "label": "Ruhe"}, {"id": "liegen", "label": "Liegen"}, {"id": "sitzen", "label": "Sitzen"}, {"id": "aufstehen", "label": "Aufstehen"}, {"id": "buecken", "label": "Bücken"}, {"id": "in_die_hocke_gehen", "label": "in die Hocke gehen"}, {"id": "stehen", "label": "Stehen"}, {"id": "gehen", "label": "Gehen"}, {"id": "laufen", "label": "Laufen"}, {"id": "treppe_hoch_runtergehen", "label": "Treppe hoch-/runtergehen"}, {"id": "an_ausziehen", "label": "An-/Ausziehen"}, {"id": "tragen", "label": "Tragen"}, {"id": "ueberkopfbewegung", "label": "Überkopfbewegung"}, {"id": "greifen", "label": "Greifen"}, {"id": "arbeit", "label": "Arbeit"}, {"id": "hobby", "label": "Hobby"}, {"id": "sport", "label": "Sport"}, {"id": "morgens", "label": "morgens"}, {"id": "abends", "label": "abends"}, {"id": "nachts", "label": "nachts"}, {"id": "sonstiges", "label": "Sonstiges?", "freitext": true}]}, {"id": "verschlechtert_durch", "typ": "mehrfachauswahl", "text": "b) Was verschlechtert Ihre Beschwerden:", "nummer": 12, "gewertet": false, "optionen": [{"id": "aktivitaet", "label": "Aktivität"}, {"id": "ruhe", "label": "Ruhe"}, {"id": "liegen", "label": "Liegen"}, {"id": "sitzen", "label": "Sitzen"}, {"id": "aufstehen", "label": "Aufstehen"}, {"id": "buecken", "label": "Bücken"}, {"id": "in_die_hocke_gehen", "label": "in die Hocke gehen"}, {"id": "stehen", "label": "Stehen"}, {"id": "gehen", "label": "Gehen"}, {"id": "laufen", "label": "Laufen"}, {"id": "treppe_hoch_runtergehen", "label": "Treppe hoch-/runtergehen"}, {"id": "an_ausziehen", "label": "An-/Ausziehen"}, {"id": "tragen", "label": "Tragen"}, {"id": "ueberkopfbewegung", "label": "Überkopfbewegung"}, {"id": "greifen", "label": "Greifen"}, {"id": "arbeit", "label": "Arbeit"}, {"id": "hobby", "label": "Hobby"}, {"id": "sport", "label": "Sport"}, {"id": "morgens", "label": "morgens"}, {"id": "abends", "label": "abends"}, {"id": "nachts", "label": "nachts"}, {"id": "sonstiges", "label": "Sonstiges?", "freitext": true}]}, {"id": "schmerz_durchschnitt", "typ": "skala", "text": "Wie stark waren Ihre Schmerzen im Durchschnitt? (bitte kennzeichnen)", "anker": {"max": "maximaler Schmerz", "min": "kein Schmerz"}, "skala": {"max": 10, "min": 0}, "nummer": 13, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false}, {"id": "unsicher_umgang", "typ": "einzelauswahl", "text": "Sind Sie oft unsicher, wie Sie mit Ihrem Schmerzzustand umgehen sollen?", "nummer": 14, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "stark_gestoert", "typ": "einzelauswahl", "text": "Haben Sie sich in den vergangenen zwei Wochen stark durch Ihre Schmerzen gestört gefühlt?", "nummer": 15, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "kurze_wege", "typ": "einzelauswahl", "text": "Konnten Sie aufgrund Ihrer Schmerzen nur kurze Wege gehen?", "nummer": 16, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "mehrere_koerperteile", "typ": "einzelauswahl", "text": "Hatten Sie störende Gelenk- oder Muskelschmerzen an mehr als einem Körperteil?", "nummer": 17, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "lange_anhalten", "typ": "einzelauswahl", "text": "Denken Sie, dass Ihr Zustand lange anhalten wird?", "nummer": 18, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "andere_gesundheitsprobleme", "typ": "einzelauswahl", "text": "Haben Sie andere bedeutsame Gesundheitsprobleme?", "nummer": 19, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "niedergeschlagen", "typ": "einzelauswahl", "text": "Haben Sie sich aufgrund Ihrer Schmerzen/Beschwerden niedergeschlagen oder depressiv gefühlt?", "nummer": 20, "hinweis": "Zur Beantwortung der Fragen 13-20 denken Sie bitte nur an die vergangenen zwei Wochen:", "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "aktivitaet_schaedlich", "typ": "einzelauswahl", "text": "Denken Sie, dass es für jemanden in Ihrem Zustand schädlich ist, körperlich aktiv zu sein?", "nummer": 21, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "seit_sechs_monaten", "typ": "einzelauswahl", "text": "Haben Sie Ihre derzeitige Schmerzproblematik seit 6 Monaten oder länger?", "nummer": 22, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "symptome_neurologisch", "typ": "mehrfachauswahl", "text": "Hatten Sie in den letzten Wochen: Kopfschmerzen, Gang- oder Gleichgewichtsstörungen, Schwindel, Übelkeit, Ohnmachtsanfällen, Benommenheit, Sprech-/Schluckbeschwerden, Sehprobleme/Doppelbilder?", "nummer": 23, "gewertet": false, "optionen": [{"id": "kopfschmerzen", "label": "Kopfschmerzen"}, {"id": "gang_oder_gleichgewichtsstoerungen", "label": "Gang- oder Gleichgewichtsstörungen"}, {"id": "schwindel", "label": "Schwindel"}, {"id": "uebelkeit", "label": "Übelkeit"}, {"id": "ohnmachtsanfaellen", "label": "Ohnmachtsanfällen"}, {"id": "benommenheit", "label": "Benommenheit"}, {"id": "sprech_schluckbeschwerden", "label": "Sprech-/Schluckbeschwerden"}, {"id": "sehprobleme_doppelbilder", "label": "Sehprobleme/Doppelbilder"}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "symptome_organisch", "typ": "mehrfachauswahl", "text": "Hatten Sie in den letzten Woche: Verdauungsbeschwerden/Sodbrennen, Blasenschwäche, morgendliche Steifheit, Kurzatmigkeit, vermehrte Müdigkeit, Herzrasen, belastungsabhängige Brustschmerzen, Schweißausbrüche?", "nummer": 24, "gewertet": false, "optionen": [{"id": "verdauungsbeschwerden_sodbrennen", "label": "Verdauungsbeschwerden/Sodbrennen"}, {"id": "blasenschwaeche", "label": "Blasenschwäche"}, {"id": "morgendliche_steifheit", "label": "morgendliche Steifheit"}, {"id": "kurzatmigkeit", "label": "Kurzatmigkeit"}, {"id": "vermehrte_muedigkeit", "label": "vermehrte Müdigkeit"}, {"id": "herzrasen", "label": "Herzrasen"}, {"id": "belastungsabhaengige_brustschmerzen", "label": "belastungsabhängige Brustschmerzen"}, {"id": "schweissausbrueche", "label": "Schweißausbrüche"}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "symptome_allgemein", "typ": "mehrfachauswahl", "text": "Hatten Sie in den letzten Wochen: Fieber/Schüttelfrost, Nachtschweiß, Gewichtsverlust, Infektanfälligkeit?", "nummer": 25, "gewertet": false, "optionen": [{"id": "fieber_schuettelfrost", "label": "Fieber/Schüttelfrost"}, {"id": "nachtschweiss", "label": "Nachtschweiß"}, {"id": "gewichtsverlust", "label": "Gewichtsverlust"}, {"id": "infektanfaelligkeit", "label": "Infektanfälligkeit"}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "tumor", "typ": "einzelauswahl", "text": "Hatten Sie jemals einen Tumor oder eine Krebserkrankung?", "nummer": 26, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "tumor_welcher", "typ": "freitext", "text": "Welche/n?", "nummer": 26, "gewertet": false}, {"id": "tumor_wann", "typ": "freitext", "text": "Wann?", "nummer": 26, "gewertet": false}, {"id": "tumor_nachuntersuchung", "typ": "freitext", "text": "Letzte Nachuntersuchung?", "nummer": 26, "gewertet": false}, {"id": "erkrankungen", "typ": "mehrfachauswahl", "text": "Leiden Sie unter: Asthma, Diabetes, Osteoporose, Epilepsie, Depression, Angststörung, andere Erkrankung?", "nummer": 27, "gewertet": false, "optionen": [{"id": "asthma", "label": "Asthma"}, {"id": "diabetes", "label": "Diabetes"}, {"id": "osteoporose", "label": "Osteoporose"}, {"id": "epilepsie", "label": "Epilepsie"}, {"id": "depression", "label": "Depression"}, {"id": "angststoerung", "label": "Angststörung"}, {"id": "andere_erkrankung", "label": "andere Erkrankung?", "freitext": true}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "ereignisse", "typ": "mehrfachauswahl", "text": "Stehen folgende Ereignisse in Zusammenhang mit Ihren aktuellen Problemen: Unfall/Sturz/Verletzung, Operation, anderes Ereignis?", "nummer": 28, "gewertet": false, "optionen": [{"id": "unfall_sturz_verletzung", "label": "Unfall/Sturz/Verletzung"}, {"id": "operation", "label": "Operation"}, {"id": "anderes_ereignis", "label": "anderes Ereignis?", "freitext": true}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "wechseljahre_schwangerschaft", "typ": "mehrfachauswahl", "text": "Befinden Sie sich in den Wechseljahren? Besteht die Wahrscheinlichkeit einer Schwangerschaft?", "nummer": 29, "gewertet": false, "optionen": [{"id": "wechseljahre", "label": "Befinden Sie sich in den Wechseljahren?"}, {"id": "schwangerschaft", "label": "Besteht die Wahrscheinlichkeit einer Schwangerschaft?"}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "medikamente", "typ": "mehrfachauswahl", "text": "Nehmen Sie momentan Medikamente wie: Kortison, Blutverdünner, Schmerzmittel, Hormone, Antidepressiva, andere Medikamente?", "nummer": 30, "gewertet": false, "optionen": [{"id": "kortison", "label": "Kortison"}, {"id": "blutverduenner", "label": "Blutverdünner"}, {"id": "schmerzmittel", "label": "Schmerzmittel"}, {"id": "hormone", "label": "Hormone"}, {"id": "antidepressiva", "label": "Antidepressiva"}, {"id": "andere_medikamente", "label": "andere Medikamente?", "freitext": true}, {"id": "nein", "label": "nein", "exklusiv": true}]}, {"id": "rauchen", "typ": "einzelauswahl", "text": "Rauchen Sie?", "nummer": 31, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "ernaehrung", "typ": "einzelauswahl", "text": "Würden Sie Ihre Ernährung als gut bzw. ausgewogen bezeichnen?", "nummer": 32, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "bewegung", "typ": "einzelauswahl", "text": "Bewegen Sie sich pro Woche 150 Minuten bei niederer Intensität (Herzfrequenz erhöht, Reden ist noch möglich) oder 75 Minuten bei höherer Intensität (Herzfrequenz erhöht, Reden wird unmöglich)?", "nummer": 33, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "krafttraining", "typ": "einzelauswahl", "text": "Machen Sie 2 x pro Woche Krafttraining?", "nummer": 34, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "schlaf", "typ": "einzelauswahl", "text": "Haben Sie Schwierigkeiten einzuschlafen oder durchzuschlafen?", "nummer": 35, "gewertet": false, "optionen": [{"id": "ja", "label": "ja"}, {"id": "nein", "label": "nein"}]}, {"id": "stress_arbeit", "typ": "skala", "text": "Wie gestresst fühlen Sie sich bei Ihrer Arbeit?", "anker": {"max": "maximaler Stress", "min": "kein Stress"}, "skala": {"max": 10, "min": 0}, "nummer": 36, "gewertet": false}, {"id": "stress_alltag", "typ": "skala", "text": "Wie gestresst fühlen Sie sich im Alltag?", "anker": {"max": "maximaler Stress", "min": "kein Stress"}, "skala": {"max": 10, "min": 0}, "nummer": 37, "gewertet": false}, {"id": "bisherige_massnahmen", "typ": "mehrfachauswahl", "text": "W