INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patients', 'patientenakte', 'automatisch', 'Die Akte selbst. Zehn Jahre nach Abschluss der Versorgung, sofern kein Legal Hold besteht.', 80);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('appointments', 'termin_ohne_nachweis', 'automatisch', 'Abgesagte Termine ohne Dokumentation: drei Jahre ab Ende des Kalenderjahres der Absage. Haengt Dokumentation daran, gilt die Frist der Akte.', 90);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('audit_log', 'auditlog', 'automatisch', 'Auditeintraege aelter als die Frist der Klasse. Unveraenderbar ueber den Anwendungspfad; der Loeschlauf ist der einzige Weg (ADR-010 Punkt 4).', 100);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_account_invitations', 'zugangseinladung', 'automatisch', 'Abgeschlossene Einladungen. Offene Einladungen bleiben, bis sie angenommen, zurueckgenommen oder abgelaufen sind.', 110);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('user_profiles', 'accountdaten', 'keine', 'Zuordnung Konto zu Person. Wird ueber die Zugangsverwaltung gesperrt, nicht ueber eine Frist geloescht.', 120);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('user_roles', 'accountdaten', 'ueber_elterndatensatz', 'Rollenzuweisung. Faellt mit dem Konto (FK on delete cascade).', 130);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('persons', 'personenstammdaten', 'ueber_elterndatensatz', 'Faellt, wenn keine Rolle mehr darauf verweist - im Lauf unmittelbar nach der Patientenzeile geprueft.', 140);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_members', 'beschaeftigtendaten', 'keine', 'Mitarbeiterdatensatz. Frist offen (ANN-030).', 150);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_private_details', 'beschaeftigtendaten', 'ueber_elterndatensatz', 'Privatangaben. Fallen mit dem Mitarbeiterdatensatz (FK on delete cascade).', 160);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_working_hour_exceptions', 'beschaeftigtendaten', 'keine', 'Abweichungen vom Wochenplan. Frist offen (ANN-030).', 180);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('prescribers', 'verordnerkartei', 'keine', 'Verordnerkartei. Frist nach dem Ende der letzten Verordnung offen (ANN-013).', 190);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('treatment_text_snippets', 'betriebsdaten', 'keine', 'Textbausteine. Persoenliche Bausteine fallen mit dem Mitarbeiterdatensatz (FK on delete cascade).', 200);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('organizations', 'stammdaten_praxis', 'keine', 'Die Praxis selbst.', 210);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('locations', 'stammdaten_praxis', 'keine', 'Standorte der Praxis.', 220);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('roles', 'konfiguration', 'keine', 'Rollenkatalog ohne Personenbezug.', 230);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('retention_classes', 'konfiguration', 'keine', 'Der Retention Schedule selbst.', 240);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('retention_assignments', 'konfiguration', 'keine', 'Die Zuordnung selbst.', 250);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('legal_holds', 'patientenakte', 'ueber_elterndatensatz', 'Aufgehobene Loeschsperren einer Akte. Fallen mit ihr; eine laufende Sperre verhindert die Loeschung.', 75);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('appointment_notifications', 'patientenakte', 'ueber_elterndatensatz', 'Vermerk, dass ein Termin mitgeteilt wurde. Faellt mit dem Termin (FK on delete cascade); keine eigene Frist.', 45);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_file_document_types', 'konfiguration', 'keine', 'Katalog der Dokumentarten samt Rollenschnitt.', 260);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_file_access_grants', 'patientenakte', 'ueber_elterndatensatz', 'Einmalige Lesefreigabe an einer Datei der Akte (FIX-015, ANN-052): beim ersten Zugriff verbraucht und geloescht, nach 30 Sekunden verfallen und bei der naechsten Ausstellung der Praxis entfernt; faellt spaetestens mit der Datei (FK on delete cascade).', 36);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('treatment_bases', 'patientenakte', 'ueber_elterndatensatz', 'Behandlungsgrundlagen. Fallen mit der Akte; werden im Lauf vor der Patientenzeile geloescht (FK restrict).', 40);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('treatment_base_items', 'patientenakte', 'ueber_elterndatensatz', 'Positionen einer Behandlungsgrundlage. Fallen mit der Grundlage (FK on delete cascade).', 30);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('billable_services', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Erfasste Leistungen. Fallen mit der Patientenakte und werden im Lauf vor dem Termin geloescht (FK restrict).', 15);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('service_catalog_items', 'abrechnungsdaten', 'keine', 'Positionen einer Preisliste. Kein Personenbezug; sie sind der Beleg dafuer, welcher Preis galt, und Leistungen zeigen mit RESTRICT auf sie.', 16);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('service_catalog_versions', 'abrechnungsdaten', 'keine', 'Preislisten. Kein Personenbezug; eine veroeffentlichte Liste ist unveraenderlich und bleibt als Beleg (ADR-009 Punkt 5).', 17);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('practice_billing_profiles', 'abrechnungsdaten', 'keine', 'Praxis-Stammdaten fuer Rechnungen. Kein Personenbezug zu Patientinnen; sie gehoeren zur Praxis und fallen mit ihr.', 18);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('invoice_recipients', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Rechnungsempfaenger einer Patientin. Fallen mit der Akte, nachdem die Rechnungen geloescht sind (FK restrict).', 19);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('invoice_number_series', 'abrechnungsdaten', 'keine', 'Nummernkreis. Kein Personenbezug; er ist der Nachweis, dass keine Nummer zweimal vergeben wurde (ADR-009 Punkt 8).', 22);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('invoices', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Rechnungen. Fallen mit der Patientenakte, aber fruehestens nach Ablauf ihrer eigenen steuerlichen Frist - der Lauf haelt die Akte so lange zurueck (ADR-008 Punkt 2).', 20);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('invoice_items', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Zeilen einer Rechnung. Fallen mit ihrer Rechnung und vor den Leistungen, auf die sie mit RESTRICT zeigen.', 21);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('payments', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Zahlungen und Rueckzahlungen. Fallen mit ihrer Rechnung und vor ihr, weil sie mit RESTRICT auf sie zeigen.', 23);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('invoice_cancellations', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Stornodokumente. Fallen mit ihrer Rechnung und vor ihr, weil sie mit RESTRICT auf sie zeigen.', 24);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('deletion_journal', 'loeschjournal', 'automatisch', 'Eintraege aelter als 60 Tage. Laenger braucht sie das Nachziehen nach einer Wiederherstellung nicht (ADR-012: Backups 30 Tage).', 260);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_working_hours', 'beschaeftigtendaten', 'keine', 'Wochenplan samt frueheren und kuenftigen Fassungen (AZ-001, ANN-589). Frist offen (ANN-030).', 170);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('invoice_payment_reminders', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Zahlungserinnerungen. Fallen mit ihrer Rechnung und vor ihr, weil sie mit RESTRICT auf sie zeigen.', 25);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_relationships', 'trainingsverhaeltnis', 'automatisch', 'Das Verhaeltnis selbst. Eigene Regel im Loeschlauf mit eigenem Anker (LEI-002); die gemeinsame persons-Zeile faellt erst, wenn kein Verhaeltnis und kein Konto mehr auf sie zeigt (ADR-008 Punkt 9).', 55);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_bases', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Planungsklammern des Trainingsverhaeltnisses. Fallen mit dem Verhaeltnis und werden im Lauf vor ihm geloescht (FK restrict, CAL-026).', 56);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('appointments', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Trainingstermine (kind = training). Fallen mit dem Trainingsverhaeltnis und nach eigener Frist - nicht mit der Patientenakte und nicht nach der Frist fuer Termine ohne Nachweis (ADR-022, Konsequenzen). Werden im Lauf vor dem Verhaeltnis geloescht (FK restrict).', 57);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_privacy_records', 'patientenakte', 'ueber_elterndatensatz', 'Vermerke zu Datenschutzinformation, Behandlungsvertrag und Einwilligungen. Fallen mit der Akte (FK on delete cascade); der Nachweis einer Einwilligung wird so lange gebraucht wie die Daten, die auf ihr beruhen.', 46);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_questionnaire_responses', 'patientenakte', 'ueber_elterndatensatz', 'Erhobene Fragebögen (Anamnese, spaeter PROMs) samt Korrekturen. Fallen mit der Akte (FK on delete cascade); ADR-008 fuehrt Anamnese und PROMs ausdruecklich als Teil der Patientenakte.', 47);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_course_events', 'patientenakte', 'ueber_elterndatensatz', 'Ereignisse im Verlauf (Operation, Erkrankung, Urlaub, Medikation). Gesundheitsangaben der Akte; fallen mit ihr (FK on delete cascade).', 48);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('therapy_reports', 'patientenakte', 'ueber_elterndatensatz', 'Therapieberichte an die Verordner:in samt eingefrorenem Snapshot. Klinische Unterlage der Akte; faellt mit ihr (FK on delete cascade).', 49);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_files', 'patientenfoto', 'automatisch', 'Nur Zeilen der Art patientenfoto: eigene Regel im Loeschlauf und beim Widerruf der Einwilligung, mit Eintrag im Loeschjournal. Das Objekt folgt ueber den Loeschauftrag (ADR-017 Punkt 36 und 38).', 36);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('waitlist_entries', 'patientenakte', 'ueber_elterndatensatz', 'Offene Wartelisteneintraege. Fallen mit der Akte (FK on delete cascade).', 48);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('waitlist_entries', 'warteliste', 'automatisch', 'Geschlossene Wartelisteneintraege: eigene Regel im Loeschlauf, zwoelf Monate nach closed_at.', 49);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('territories', 'betriebsdaten', 'keine', 'Gebiete fuer die Terminvergabe. Praxisregel ohne Personenbezug; bleibt, bis die Praxis sie entfernt.', 215);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('territory_postal_codes', 'betriebsdaten', 'ueber_elterndatensatz', 'Postleitzahlen eines Gebiets. Fallen mit dem Gebiet (FK on delete cascade).', 216);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('tasks', 'patientenakte', 'ueber_elterndatensatz', 'Offene Aufgaben mit Personenbezug. Fallen mit der Akte (FK on delete cascade).', 50);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('tasks', 'aufgabe', 'automatisch', 'Erledigte Aufgaben: eigene Regel im Loeschlauf, zwoelf Monate nach done_at.', 51);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('appointment_call_states', 'anrufstand', 'automatisch', 'Eigene Regel im Loeschlauf, vierzehn Tage nach Terminbeginn; faellt ausserdem mit dem Termin (FK on delete cascade).', 52);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('practice_targets', 'stammdaten_praxis', 'keine', 'Zielwerte der Praxisfuehrung ohne Personenbezug. Ein Zielwert wird geloescht, indem er geleert wird; die Zeile faellt mit der Organisation (FK on delete cascade).', 215);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_compensation_models', 'beschaeftigtendaten', 'ueber_elterndatensatz', 'Verguetungsmodell. Faellt mit dem Mitarbeiterdatensatz (FK on delete cascade).', 165);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_contact_details', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Kontaktdaten des Trainingsverhaeltnisses. Fallen mit ihm (FK on delete cascade).', 56);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_protocols', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Trainingsprotokolle. Fallen mit dem Verhaeltnis und im Lauf vor ihrem Termin (FK restrict); in der Teilloeschung nach drei Jahren auch am abgerechneten Termin, denn sie sind kein Beleg (ANN-183).', 56);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_accesses', 'plattformzugang', 'automatisch', 'Zugang je Konto und Verhaeltnis. Faellt das Verhaeltnis, endet er und loest sich von Verhaeltnis und Person; drei Jahre nach dem Ende faellt er im Lauf.', 75);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_access_invitations', 'plattformzugang', 'ueber_elterndatensatz', 'Einladungen eines Zugangs. Fallen mit ihm; die Adresse wird geleert, sobald das Verhaeltnis faellt.', 76);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_account_deletions', 'plattformzugang', 'keine', 'Offene Loeschauftraege fuer Plattformkonten. Ein Auftrag verschwindet mit seiner Bestaetigung; was bleibt, ist der Eintrag im Loeschjournal (ABN-011).', 77);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_mailbox_confirmations', 'plattformzugang', 'ueber_elterndatensatz', 'Bestaetigtes Postfach eines Plattformkontos. Faellt mit dem Konto beim Anmeldedienst (on delete cascade, ABN-012).', 78);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('questionnaire_definitions', 'konfiguration', 'keine', 'Fassungen der Fragebogen-Definitionen (Produktinhalt, ohne Personenbezug). Bleiben, solange eine Erhebung sie nennen kann (ABN-014).', 49);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('treatment_draft_findings', 'patientenakte', 'ueber_elterndatensatz', 'Noch nicht uebernommene Befundangaben je Termin. Fallen beim Festschreiben der Dokumentation weg, sonst mit dem Termin und der Akte (ABN-015).', 46);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_merge_records', 'patientenakte', 'ueber_elterndatensatz', 'Nachweis des Zusammenfuehrens an der bleibenden Akte; faellt mit ihr (ABN-018).', 50);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_protocol_addenda', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Nachtraege zu Trainingsprotokollen; fallen mit dem Protokoll (ABN-022).', 51);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_files', 'patientenakte', 'ueber_elterndatensatz', 'Dateien der Akte einschliesslich Verordnungsscan und Dokumentationsfotos, ausser Foto-Arbeitshilfen (eigene Klasse patientenfoto). Fallen mit der Akte oder mit ihrer Verordnung (FK on delete cascade). Das Objekt folgt ueber einen Loeschauftrag mit Quittung (ADR-017 Punkte 25 und 45).', 35);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('audit_log', 'auditlog_lesen_sicherheit', 'automatisch', 'Lese- und Sicherheitsereignisse; welche Aktion in welche Klasse faellt, sagt app.audit_retention_class.', 101);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('storage_deletion_orders', 'loeschauftrag', 'automatisch', 'Quittierte Auftraege drei Jahre nach der Quittung; offene bleiben (ADR-017 Punkt 25 und 26).', 115);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_file_access_grants', 'loeschauftrag', 'ueber_elterndatensatz', 'Einmalige Loeschfreigabe am Objekt eines Loeschauftrags (FIX-015, ADR-017 Punkt 25): beim ersten Zugriff verbraucht, nach 30 Sekunden verfallen; faellt spaetestens mit dem Auftrag (FK on delete cascade).', 116);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('patient_fee_agreements', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Honorarvereinbarungen einer Patientin (ABR-030). Fallen mit der Akte (on delete cascade), nachdem die festgeschriebenen Honorare mit ihren Terminen geloescht sind (FK restrict).', 19);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('appointment_session_fees', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Terminhonorar je Behandlungstermin (ABR-031). Faellt mit seinem Termin (on delete cascade); den Termin halten bis dahin die Leistungen daran fest (FK restrict).', 15);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_appointment_requests', 'terminwunsch', 'automatisch', 'Beantwortete und zurueckgezogene Wuensche zwoelf Monate nach der Antwort; offene bleiben; mit Akte bzw. Trainingsverhaeltnis fallen sie (cascade).', 76);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('session_activity', 'sitzungsvermerk', 'automatisch', 'Eigene Regel in session_status: jeder Aufruf mit Bedienung entfernt Vermerke, deren letzte Bedienung laenger als einen Tag zurueckliegt; faellt ausserdem mit dem Konto (FK on delete cascade).', 53);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_consent_records', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Einwilligung zu Gesundheitsangaben im Training (POR-017). Faellt mit dem Verhaeltnis (FK on delete cascade); der Nachweis wird so lange gebraucht wie die Angaben, die auf ihr beruhen.', 57);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('aftercare_subscriptions', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Nachsorge-Abos einer Patientin (ANG-001). Fallen mit der Akte (on delete cascade), nachdem die Leistungen daraus geloescht sind (FK restrict); die Akte haelt der Lauf so lange, wie ihre Rechnungen es verlangen.', 19);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_packages', 'abrechnungsdaten', 'ueber_elterndatensatz', 'Trainingspakete einer Kund:in (ANG-006). Fallen mit dem Trainingsverhaeltnis (on delete cascade), nachdem ihre Leistung geloescht ist (FK restrict); das Verhaeltnis haelt der Lauf so lange, wie seine Rechnungen es verlangen (app.training_billing_retention_due_at).', 19);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_offers', 'patientenakte', 'ueber_elterndatensatz', 'Trainingsangebote aus der Akte (KND-002). Enthalten Angaben aus der Behandlung und fallen mit der Akte (on delete cascade); die Kopie im Training lebt mit dem Trainingsverhaeltnis (ADR-021 Punkt 7).', 19);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_profiles', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Voraussetzungsprofil im Training (KND-005). Faellt mit dem Trainingsverhaeltnis (on delete cascade).', 57);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_takeovers', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Aus der Behandlung freigegebene Angaben als Kopie (KND-005, ADR-021 Punkt 7). Ab dem Kopieren Trainingsdaten mit der Frist des Verhaeltnisses; fallen mit ihm (on delete cascade).', 57);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('training_contracts', 'trainingsverhaeltnis', 'ueber_elterndatensatz', 'Nachweis des im eigenen Konto geschlossenen Trainingsvertrags mit Widerrufsbelehrung (KND-003). Faellt mit dem Trainingsverhaeltnis (on delete cascade); das haelt der Lauf, solange seine Rechnungen es verlangen.', 57);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('exercises', 'betriebsdaten', 'keine', 'Uebungsbibliothek (UEB-001). Fachwissen der Praxis ohne Personenbezug; bleibt, bis die Praxis die Uebung loescht (ANN-296). Archivieren nimmt sie aus der Bibliothek, ohne sie zu loeschen.', 205);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('exercise_variants', 'betriebsdaten', 'keine', 'Varianten der Uebungsbibliothek (UEB-001). Wie die Uebung: bleiben, bis die Praxis sie loescht (ANN-296); eine Uebung laesst sich erst ohne Varianten loeschen (FK restrict).', 206);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('exercise_variant_links', 'betriebsdaten', 'keine', 'Verbindungen der Uebungsbibliothek (UEB-002). Ohne Personenbezug; bleiben, bis die Praxis sie loest. Eine verbundene Variante laesst sich erst nach dem Loesen loeschen (FK restrict, ANN-296).', 207);
