INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('session_unlocks', 'sitzungsvermerk', 'automatisch', 'Eigene Regel in unlock_with_pin: Zeilen ohne offenen Fehlversuch und verbrauchte Sitzungen fallen einen Tag nach der letzten Aenderung; mit offenem Fehlversuch bleibt die Zeile, bis die PIN stimmt (sonst begaenne der Zaehler von vorn). Faellt mit dem Konto.', 54);
