INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_message_attachments', 'rueckfrageanhang', 'automatisch', 'Anhaenge an Rueckfragen, 30 Tage ab der Aufnahme; fallen frueher mit dem Vorgang (cascade) und beim Widerruf der Einwilligung. Das Objekt folgt ueber den Loeschauftrag (ADR-017 Punkt 25).', 79);
