INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('notification_deliveries', 'benachrichtigung', 'automatisch', 'Eigener Zeitplan purge_notification_deliveries, taeglich: abgeschlossene Auftraege 30 Tage nach dem Abschluss. Kein Loeschjournal - nach einem Restore faellt ein Auftrag im naechsten Lauf erneut, weil die Frist am Auftrag selbst haengt.', 81);
