INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_thread_states', 'teamchat', 'automatisch', 'Eigener Stand an einem Thread (TEAM-002): fällt mit der Ausgangsnachricht (cascade), beim Verlassen des Gesprächs und mit dem Ausscheiden der Person (ANN-640).', 245);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_message_reactions', 'teamchat', 'automatisch', 'Reaktionen (TEAM-002): fallen mit der Nachricht (cascade) oder ihrem Inhalt (ANN-644).', 246);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_message_pins', 'teamchat', 'automatisch', 'Angeheftetes (TEAM-002): fällt mit der Nachricht (cascade) oder ihrem Inhalt (ANN-645).', 247);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_saved_messages', 'teamchat', 'automatisch', 'Für später (TEAM-002): fällt mit der Nachricht (cascade) oder ihrem Inhalt, beim Verlassen des Gesprächs und mit dem Ausscheiden (ANN-646).', 248);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_channel_settings', 'teamchat', 'automatisch', 'Einstellungen je Gespräch (TEAM-002): fallen mit dem Gespräch (cascade), beim Verlassen und mit dem Ausscheiden (ANN-647).', 249);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_channels', 'teamchat', 'automatisch', 'Gespräche (TEAM-001, TEAM-002): offene Kanäle und das Gespräch der Radflotte bleiben, solange die Praxis sie führt; Direkt- und Gruppennachrichten ohne Nachricht fallen zwölf Monate nach ihrem Beginn; private Kanäle fallen, sobald kein aktives Mitglied mehr dabei ist - jeweils mit Eintrag im Löschjournal (ANN-610, ANN-642).', 242);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_channel_members', 'teamchat', 'automatisch', 'Mitglieder von Direkt- und Gruppennachrichten und privaten Kanälen (TEAM-001, TEAM-002): fallen mit dem Gespräch (cascade) und beim Verlassen oder Herausnehmen (ANN-642).', 243);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_attachment_access_grants', 'teamchat', 'ueber_elterndatensatz', 'Einmalige Lesefreigaben für Anhänge im Teamchat (ANN-052): verbraucht beim ersten Zugriff, abgelaufene täglich gelöscht; fallen mit dem Anhang (cascade).', 262);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('team_message_attachments', 'teamchat', 'automatisch', 'Anhänge im Teamchat, auch Sprachnachrichten (TEAM-003, TEAM-004, ADR-017 Abschnitte M und N): fallen mit der Nachricht (cascade) oder ihrem Inhalt - auf jedem Weg mit Löschauftrag für das Objekt; ungesendete nach 24 Stunden (ANN-652).', 261);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('food_sources', 'betriebsdaten', 'keine', 'Quellen der Lebensmitteldaten mit Lizenz und Stand (ERN-004): Inhalt ohne Personenbezug.', 244);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('food_catalog', 'betriebsdaten', 'keine', 'Lebensmittelkatalog aus BLS 4.0 und Open Food Facts (ERN-004): Bezugsdaten ohne Personenbezug; was eine Quelle nicht mehr führt, wird beim Import zurückgezogen, nicht gelöscht (ANN-659).', 245);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('custom_foods', 'ernaehrungsberatung', 'ueber_elterndatensatz', 'Eigene Lebensmittel der Person (ERN-005, owner_kind person): fallen mit ihrem Ernährungsprofil (ADR-027 Punkt 6).', 246);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('custom_foods', 'betriebsdaten', 'keine', 'Lebensmittel der Praxis (ERN-005, owner_kind practice): Inhalt ohne Personenbezug, abgelegt statt gelöscht.', 247);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('nutrition_diary_entries', 'ernaehrungsberatung', 'ueber_elterndatensatz', 'Einträge des Ernährungstagebuchs (ERN-007): fallen mit ihrem Ernährungsprofil (ADR-027 Punkt 6).', 248);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('nutrition_water_days', 'ernaehrungsberatung', 'ueber_elterndatensatz', 'Wasser je Tag (ERN-007): fällt mit seinem Ernährungsprofil (ADR-027 Punkt 6).', 249);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('nutrition_diary_favorites', 'ernaehrungsberatung', 'ueber_elterndatensatz', 'Favoriten des Ernährungstagebuchs (ERN-008): fallen mit ihrem Ernährungsprofil (ADR-027 Punkt 6) und mit ihrem Lebensmittel.', 250);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_colors', 'beschaeftigtendaten', 'ueber_elterndatensatz', 'Farbe im Teamchat (TEAM-006): fällt mit dem Mitarbeiterdatensatz (cascade).', 185);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('staff_profile_pictures', 'profilbild', 'automatisch', 'Profilbild (TEAM-007): fällt, wenn die Person es entfernt oder ersetzt und wenn ihr Mitarbeiterdatensatz inaktiv wird - sofort, mit Eintrag im Löschjournal; mit dem Mitarbeiterdatensatz (cascade).', 186);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_push_subscriptions', 'plattformzugang', 'ueber_elterndatensatz', 'Push-Registrierung je Geraet: faellt beim Abmelden, bei abgewiesenem Endpunkt, beim Widerruf des Zugangs (Trigger), mit seinem zeitlichen Ende im taeglichen Lauf purge_notification_deliveries (BEF-148, ANN-669) und spaetestens mit dem Zugang (cascade). Eine Sperre laesst sie stehen.', 83);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('platform_notification_settings', 'plattformzugang', 'ueber_elterndatensatz', 'Die Wahl der Person zu Benachrichtigungen (ADR-024 Punkt 15) steht am Zugang: faellt beim Widerruf (Trigger), mit dem Ende der Lesezeit im taeglichen Lauf purge_notification_deliveries (BEF-189, ANN-669) und spaetestens mit dem Zugang (cascade). Eine Sperre laesst sie stehen.', 82);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('nutrition_diary_reminders', 'ernaehrungsberatung', 'ueber_elterndatensatz', 'Erinnerungen an das Ernährungstagebuch (ERN-009): fallen mit dem Ernährungsprofil (ADR-027 Punkt 6), beim Widerruf des Zugangs (Trigger), mit dem Ende seiner Lesezeit im täglichen Lauf (BEF-189, ANN-669) und spätestens mit dem Zugang. Eine Sperre lässt sie stehen.', 251);
INSERT INTO public.retention_assignments (table_name, class_key, deletion_mode, scope_note, sort_order) VALUES ('legal_holds', 'beschaeftigtendaten', 'keine', 'Loeschsperren an Beschaeftigtendaten (BEF-178, ANN-674), laufende und aufgehobene. Bleiben wie der Mitarbeiterdatensatz; Frist offen (ANN-030).', 76);

INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('termin_ohne_nachweis', 'intern', NULL, 'calendar_year_end', '3 years', 'ANN-001', 'Abgesagte Termine und No-shows ohne Rechnung: drei Jahre ab Ende des Kalenderjahres (ADR-008). Greift nur, solange kein Behandlungsnachweis daran haengt - gesetzliche Aufbewahrung hat Vorrang (ADR-008 Punkt 2).', 20, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('zugangseinladung', 'intern', NULL, 'case_closed', '1 year', 'ANN-026', 'Einladung eines Zugangs: zwoelf Monate nach Abschluss des Vorgangs - angenommen, zurueckgenommen oder abgelaufen (STAFF-002b).', 40, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('personenstammdaten', 'abgeleitet', NULL, 'none', NULL, NULL, 'Identifizierende Stammdaten einer natuerlichen Person. Folgen der laengsten Frist der verknuepften Rolle: die Zeile faellt, wenn weder Patient noch Mitarbeiter noch Konto darauf verweisen (ADR-008 Punkt 9, ADR-014).', 50, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('beschaeftigtendaten', 'offen', NULL, 'none', NULL, 'ANN-030', 'Beschaeftigtenstammdaten, Privatangaben und Arbeitszeiten. ADR-008 fuehrt fuer sie keine Frist; bis zur Entscheidung keine automatische Loeschung (ANN-030, PROJECT_PRINCIPLES.md 20).', 60, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('accountdaten', 'gesetzlich_gepraegt', NULL, 'none', NULL, NULL, 'Konto und Rollenzuweisung. Getrennt vom aufbewahrungspflichtigen Fachdatensatz (ADR-008 Punkt 9): der Lebenszyklus laeuft ueber die Zugangsverwaltung (STAFF-003), nicht ueber eine Frist.', 70, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('verordnerkartei', 'offen', NULL, 'none', NULL, 'ANN-013', 'Berufliche Kontaktdaten verordnender Aerzt:innen. Aufbewahrt, solange eine Verordnung darauf verweist; die Frist danach ist offen (ANN-013), deshalb keine automatische Loeschung.', 80, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('betriebsdaten', 'intern', NULL, 'none', NULL, 'ANN-020', 'Betriebsdaten der Praxis ohne Patientenbezug, etwa Textbausteine. Keine Gesundheitsdaten, keine Frist: sie enden, wenn die Praxis sie loescht oder der zugehoerige Mitarbeiterdatensatz faellt (ANN-020).', 90, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('stammdaten_praxis', 'intern', NULL, 'none', NULL, NULL, 'Organisation und Standorte. Bestandsdaten der Praxis ohne Personenbezug und ohne gesetzliche Frist; sie enden mit dem Betrieb.', 100, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('konfiguration', 'abgeleitet', NULL, 'none', NULL, NULL, 'Referenz- und Konfigurationsdaten ohne Personenbezug: Rollenkatalog, Retention Schedule.', 120, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('abrechnungsdaten', 'gesetzlich', 'Par. 147 Abs. 3 AO', 'calendar_year_end', '8 years', NULL, 'Abrechnungsdaten und Buchungsbelege: acht Jahre ab Ende des Kalenderjahres (ADR-008). Sie fallen ueber die Patientenakte, deren zehn Jahre ab Abschluss der Versorgung nie kuerzer sind; der Leistungskatalog faellt gar nicht.', 15, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('trainingsverhaeltnis', 'gesetzlich_gepraegt', 'Par. 195 BGB', 'contract_ended', '3 years', NULL, 'Trainingsverhaeltnis und seine Vertragsdaten: drei Jahre ab Vertragsende (ADR-021 Punkt 4). Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO, nicht die Heilbehandlungs-Ausnahme - die zehn Jahre der Patientenakte gelten hier ausdruecklich nicht. Der Anker ist training_relationships.contract_ended_on; ohne Vertragsende laeuft keine Frist. Screening- und Gesundheitsangaben des Trainings bekommen eine eigene, kuerzere Klasse mit dem Loop, der sie anlegt (Anfrage B2).', 15, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('patientenfoto', 'intern', 'Art. 9 Abs. 2 lit. a DSGVO', 'event_time', '1 year', 'ANN-126', 'Fotos, die die Praxis von der Person aufnimmt: zwoelf Monate nach der Aufnahme, spaetestens drei Monate nach dem festgehaltenen Abschluss der Versorgung, sofort beim Widerruf der Einwilligung. Arbeitshilfe neben der Akte, nicht Teil von ihr - was wesentlich ist, steht im Eintrag (ADR-017 Punkt 35 und 38). Ein Legal Hold haelt die Loeschung an.', 12, 'care_concluded_recorded', '3 mons');
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('warteliste', 'intern', NULL, 'case_closed', '1 year', 'ANN-133', 'Geschlossene Eintraege der Warteliste (eingeplant oder zurueckgezogen): zwoelf Monate nach dem Schliessen, analog zu den Terminanfragen aus ADR-008. Offene Eintraege fallen mit der Akte. Ein Legal Hold an der Akte haelt die Loeschung an.', 45, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('aufgabe', 'intern', NULL, 'case_closed', '1 year', 'ANN-142', 'Erledigte Aufgaben und Wiedervorlagen: zwoelf Monate nach dem Erledigen, wie die Warteliste. Offene bleiben stehen; mit Personenbezug fallen sie mit der Akte. Ein Legal Hold an der Akte haelt die Loeschung an.', 46, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('anrufstand', 'intern', NULL, 'event_time', '14 days', 'ANN-144', 'Stand der Anrufliste (nicht erreicht, Nachricht hinterlassen): vierzehn Tage nach dem Termin. Ein Arbeitsstand, kein Merkmal der Person (PROJECT_PRINCIPLES.md 20).', 47, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('plattformzugang', 'intern', NULL, 'case_closed', '3 years', 'ANN-189', 'Plattformzugang mit Einladungen als Nachweis: drei Jahre nach dem Ende des Zugangs, so lange wie die Auditeintraege, die auf ihn zeigen. Das Konto beim Anmeldedienst faellt 30 Tage nach dem Ende des letzten Zugangs (ADR-023 Punkt 5).', 75, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('auditlog_lesen_sicherheit', 'intern', 'Art. 5 Abs. 2, Art. 32 DSGVO', 'event_time', '1 year', 'ANN-230', 'Lese- und Sicherheitsereignisse im Auditlog (Akte geoeffnet, Lesen ueber eine Vertretung, Abweisungen, Kontosicherheit): zwoelf Monate ab dem Ereignis (ADR-011 Punkt 4). Ein Legal Hold an der Akte haelt die Loeschung an.', 31, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('loeschauftrag', 'intern', NULL, 'case_closed', '3 years', 'ANN-230', 'Quittierte Loeschauftraege der Ablage: drei Jahre ab der Quittung. Offene Auftraege bleiben, bis sie ausgefuehrt sind (ADR-017 Punkt 25).', 111, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('auditlog', 'intern', 'Art. 5 Abs. 2 DSGVO', 'event_time', '3 years', 'ANN-001', 'Uebrige Auditeintraege (Exporte, Herunterladen, Zugaenge, Konten und Rechte, Loeschlauf): drei Jahre ab dem Ereignis. Laeuft nach eigener Frist und nicht mit der Akte (ANN-029); ein Legal Hold an der Akte haelt die Loeschung an.', 30, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('loeschjournal', 'intern', NULL, 'event_time', '60 days', 'ANN-230', 'Nachweis wirksam gewordener Loeschungen fuer das Nachziehen nach einer Wiederherstellung (ADR-008 Punkt 8): 60 Tage ab der Loeschung - Backups leben 30 Tage (ADR-012), dazu 30 Tage Puffer. Den Nachweis je Lauf traegt retention.applied im Auditlog.', 110, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('terminwunsch', 'intern', NULL, 'case_closed', '1 year', 'ANN-246', 'Terminwunsch ueber die Plattform: zwoelf Monate nach der Antwort der Praxis bzw. dem Zurueckziehen, wie Terminanfragen (ANN-001). Offene Wuensche bleiben; mit dem Verhaeltnis fallen sie.', 76, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('sitzungsvermerk', 'intern', NULL, 'event_time', '1 day', 'ANN-256', 'Letzte Bedienung je Sitzung fuer die Sitzungssperre (ADR-025). Nach 60 Minuten ohne neue Anmeldung ist die Sitzung ohnehin gesperrt; ein Tag laesst Spielraum fuer Uhren und Laeufe.', 56, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('patientenkommunikation', 'intern', NULL, 'calendar_year_end', '3 years', 'ANN-001', 'Nachrichten der Behandlung ueber die Plattform, die nicht der Akte zugeordnet sind: drei Jahre ab Ende des Kalenderjahres, in dem der Vorgang erledigt oder zuletzt beantwortet wurde (ADR-008). Offene Vorgaenge bleiben; mit der Akte fallen sie. Zugeordnete Vorgaenge haben die Frist der Akte (KOM-004, ANN-312).', 77, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('rueckfrageanhang', 'intern', 'Art. 9 Abs. 2 lit. a DSGVO', 'event_time', '30 days', 'ANN-332', 'Fotos und Videos, die die Person an ihre Rueckfrage haengt: 30 Tage nach der Aufnahme, frueher mit dem Vorgang, sofort beim Widerruf der Einwilligung. Keine Verlaengerung, kein Weg in die Akte (ADR-017 Punkte 65 und 66). Ein Legal Hold an der Akte haelt.', 78, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('benachrichtigung', 'intern', NULL, 'event_time', '30 days', 'ANN-345', 'Zustellauftraege fuer Benachrichtigungen: 30 Tage nach Versand, Abbruch oder Aufgabe (ADR-024 Punkt 17). Ohne Text und Adresse.', 79, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('patientenakte', 'gesetzlich', 'Par. 630f Abs. 3 BGB', 'care_concluded', '10 years', 'ANN-511', 'Zehn Jahre nach Abschluss der Behandlung. Der Anker ist app.patient_retention_anchor (B1, ADR-008 Fassung 3): das spaeteste Datum aus letzter Behandlung, erfasster Leistung und einem etwaigen ausdruecklichen Abschluss. Rechnungen halten ueber ihre eigene Frist. Ohne jede Behandlung laeuft keine Frist; ein kuenftiger Termin haelt die Akte.', 10, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('radflotte_ereignis', 'intern', 'Par. 195, 199 BGB', 'calendar_year_end', '3 years', 'ANN-551', 'Check-Ups, Pannenmeldungen, Sperren und Stellen am Rad mit ihren Fotos: drei Jahre ab Ende des Kalenderjahres des Ereignisses (bei der Sperre: der Freigabe). Nie, solange eine Stelle oder Sperre offen ist. Nachweis der Pflege des Arbeitsmittels fuer die Verjaehrungsfrist; Kontrollen vor der Fahrt kennen keine gesetzliche Frist (BetrSichV Par. 4 Abs. 5).', 91, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('schluesselverlauf', 'intern', NULL, 'case_closed', '30 days', 'ANN-551', 'Wer den Schluessel eines Rads genommen und zurueckgelegt hat: 30 Tage nach der Rueckgabe; ein offener Vorgang nie. Genug, um bei einem Schaden nach der letzten Fahrt zu fragen; keine Auswertung je Person (PROJECT_PRINCIPLES.md 20).', 92, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('urlaub', 'intern', 'Par. 195, 199 BGB', 'calendar_year_end', '3 years', 'ANN-579', 'Genehmigte und stornierte Urlaubsantraege und Urlaubsansprueche: drei Jahre ab Ende des Kalenderjahres des Urlaubs bzw. Anspruchs - die Verjaehrung von Anspruechen auf Urlaub und Abgeltung. Keine gesetzliche Aufbewahrungspflicht; offene nie.', 93, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('urlaub_kurz', 'intern', NULL, 'case_closed', '1 year', 'ANN-579', 'Abgelehnte und zurueckgezogene Urlaubsantraege: ein Jahr nach ihrem Ende (Entscheidung oder Zurueckziehen). Genug fuer Rueckfragen, ohne Verlauf ueber die Person (PROJECT_PRINCIPLES.md 20).', 94, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('arbeitszeit', 'intern', 'Par. 195, 199 BGB', 'calendar_year_end', '3 years', 'ANN-591', 'Genehmigte Antraege auf Aenderung der Arbeitszeit: drei Jahre ab Ende des Kalenderjahres, in dem die Aenderung wirkt - die Verjaehrung von Anspruechen aus der vereinbarten Arbeitszeit. Keine gesetzliche Aufbewahrungspflicht; offene nie. Der Wochenplan selbst bleibt (ANN-030).', 95, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('arbeitszeit_kurz', 'intern', NULL, 'case_closed', '1 year', 'ANN-591', 'Abgelehnte und zurueckgezogene Antraege auf Aenderung der Arbeitszeit: ein Jahr nach ihrem Ende. Genug fuer Rueckfragen, ohne Verlauf ueber die Person (PROJECT_PRINCIPLES.md 20).', 96, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('zeitkonto', 'intern', 'Par. 195, 199 BGB; Par. 16 Abs. 2 ArbZG', 'calendar_year_end', '3 years', 'ANN-597', 'Gültige Einträge im Zeitkonto: drei Jahre ab Ende des Kalenderjahres ihres Datums - die Verjährung von Ansprüchen auf Ausgleich oder Vergütung; Par. 16 Abs. 2 ArbZG verlangt mindestens zwei Jahre. Ihr Saldo bleibt als Übertrag des Jahres stehen.', 97, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('zeitkonto_kurz', 'intern', NULL, 'case_closed', '1 year', 'ANN-597', 'Zurückgewiesene und zurückgenommene Einträge im Zeitkonto: ein Jahr nach Zurückweisung bzw. Rücknahme. Genug für Rückfragen, ohne Verlauf über die Person (PROJECT_PRINCIPLES.md 20).', 98, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('erstattung', 'gesetzlich', 'Par. 147 Abs. 1 Nr. 4, Abs. 3 AO', 'calendar_year_end', '8 years', 'ANN-602', 'Ausgezahlte Erstattungen mit ihren Belegen: acht Jahre ab Ende des Kalenderjahres der Auszahlung - Buchungsbelege der Praxis. Beantragte und genehmigte, noch nicht ausgezahlte bleiben.', 99, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('erstattung_kurz', 'intern', NULL, 'case_closed', '1 year', 'ANN-602', 'Abgelehnte und zurückgezogene Erstattungen mit ihren Belegen: ein Jahr nach Entscheidung bzw. Zurückziehen. Genug für Rückfragen, ohne Verlauf über die Person (PROJECT_PRINCIPLES.md 20).', 100, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('rueckmeldung', 'intern', NULL, 'event_time', '1 year', 'ANN-607', 'Rückmeldungen von Beschäftigten (§20.2): Barometer und Rückmeldung an die Praxisleitung, mit und ohne Namen. Zwölf Monate ab Ende des Monats der Abgabe, dann endgültig gelöscht - kein Soft-Delete (ADR-008 Fassung 4).', 101, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('rueckmeldung_teilnahme', 'intern', NULL, 'event_time', '1 day', 'ANN-607', 'Teilnahme am Barometer je Person und Monat: nur, damit der Hinweis verschwindet und niemand doppelt abgibt. Fällt einen Tag nach Ende des Monats.', 102, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('teamchat', 'intern', NULL, 'event_time', '1 year', 'ANN-610', 'Interner Teamchat (§10): jede Nachricht zwölf Monate ab ihrem Tag, dann endgültig gelöscht; eine Ausgangsnachricht mit laufenden Antworten bleibt ohne Inhalt als Anker. Dauerhaft Relevantes gehört in den Fachprozess.', 103, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('ernaehrungsberatung', 'intern', NULL, 'counselling_ended', '3 years', 'ANN-619', 'Ernährungsberatung (ADR-027 Punkt 6): Profil, Einwilligung, Gewicht - drei Jahre nach dem Ende des Profils, unabhängig von der Frist des Verhältnisses; fällt das Verhältnis früher, fallen sie mit ihm. Ein Legal Hold an der Akte hält.', 104, NULL, NULL);
INSERT INTO public.retention_classes (key, basis, legal_reference, anchor, retention_interval, assumption_key, note, sort_order, upper_bound_anchor, upper_bound_interval) VALUES ('profilbild', 'intern', NULL, 'none', NULL, 'ANN-667', 'Profilbild einer beschäftigten Person im Teamchat (ADR-017 Abschnitt O): freiwillig, bis die Person es entfernt oder ersetzt, spätestens mit dem Ausscheiden (Mitarbeiterdatensatz inaktiv) - dann sofort, mit Eintrag im Löschjournal. Keine Frist nach Zeit.', 104, NULL, NULL);

INSERT INTO public.roles (key, label, description, sort_order) VALUES ('owner', 'Praxisinhaber', 'Umfassender fachlicher Zugriff (PROJECT_PRINCIPLES.md 4.1). Keine technische Administratorrolle.', 10);
INSERT INTO public.roles (key, label, description, sort_order) VALUES ('therapist', 'Therapeut:in', 'Zugriff auf alle Patientenakten der eigenen Organisation (PROJECT_PRINCIPLES.md 4.2).', 20);
INSERT INTO public.roles (key, label, description, sort_order) VALUES ('team_lead', 'Teamleitung', 'Therapeutenrechte plus organisatorische Zusatzrechte (PROJECT_PRINCIPLES.md 4.5).', 30);
INSERT INTO public.roles (key, label, description, sort_order) VALUES ('office', 'Praxismanagement', 'Organisatorische Daten, kein klinischer Freitext (PROJECT_PRINCIPLES.md 4.3).', 40);
INSERT INTO public.roles (key, label, description, sort_order) VALUES ('patient', 'Patient:in', 'Ausschliesslich eigener Patientenkontext (PROJECT_PRINCIPLES.md 4.6).', 50);
INSERT INTO public.roles (key, label, description, sort_order) VALUES ('trainer', 'Trainingsbetreuung', 'Betreut Trainingsverhaeltnisse (PROJECT_PRINCIPLES.md 4.9). Kein Zugriff auf Patientenakten, Befunde, Behandlungsdokumentation oder Verordnungen.', 45);

































































