CREATE TRIGGER appointments_record_default_services AFTER UPDATE OF status, completed_at, treatment_basis_id ON public.appointments FOR EACH ROW WHEN (((new.kind = 'therapy'::text) AND (new.status = 'documented'::text) AND (new.completed_at IS NOT NULL))) EXECUTE FUNCTION app.appointments_record_default_services();

COMMENT ON TRIGGER appointments_record_default_services ON public.appointments IS 'B7 (ANN-513): Haken und festgeschriebene Doku zusammen - in beliebiger Reihenfolge, auch nach einer spaeteren Zuordnung zur Grundlage - erfassen die Leistungen.';

CREATE TRIGGER appointments_record_nutrition_service AFTER UPDATE OF status, completed_at ON public.appointments FOR EACH ROW WHEN (((new.occasion = 'nutrition_counselling'::text) AND (new.status = 'completed'::text) AND (new.completed_at IS NOT NULL))) EXECUTE FUNCTION app.appointments_record_nutrition_service();

CREATE TRIGGER appointments_staff_active_on_insert BEFORE INSERT ON public.appointments FOR EACH ROW EXECUTE FUNCTION app.assert_appointment_staff_active();

CREATE TRIGGER appointments_staff_active_on_reassign BEFORE UPDATE OF staff_member_id ON public.appointments FOR EACH ROW WHEN ((new.staff_member_id IS DISTINCT FROM old.staff_member_id)) EXECUTE FUNCTION app.assert_appointment_staff_active();

