CREATE POLICY training_bases_select_scoped ON public.training_bases FOR SELECT TO authenticated USING (((organization_id = app.current_organization_id()) AND app.can_read_training_relationships()));

COMMENT ON POLICY training_bases_select_scoped ON public.training_bases IS 'Die Klammer folgt dem Verhaeltnis: wer das Trainingsverhaeltnis lesen darf, liest auch seine Grundlagen (ADR-021 Punkt 6, LEI-003).';

ALTER TABLE public.training_consent_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY training_consent_records_select_scoped ON public.training_consent_records FOR SELECT TO authenticated USING (((organization_id = app.current_organization_id()) AND app.can_read_training_relationships()));

