ALTER TABLE public.treatment_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.treatment_text_snippets ENABLE ROW LEVEL SECURITY;
CREATE POLICY treatment_text_snippets_select_scoped ON public.treatment_text_snippets FOR SELECT TO authenticated USING (((organization_id = app.current_organization_id()) AND app.can_use_text_snippets() AND ((staff_member_id IS NULL) OR (staff_member_id IN ( SELECT sm.id
   FROM public.staff_members sm
  WHERE (sm.person_id = app.current_person_id()))))));

ALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_profiles_select_scoped ON public.user_profiles FOR SELECT TO authenticated USING (((id = auth.uid()) OR ((organization_id = app.current_organization_id()) AND app.has_any_role(VARIADIC ARRAY['owner'::text]))));

ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_roles_select_scoped ON public.user_roles FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR ((organization_id = app.current_organization_id()) AND app.has_any_role(VARIADIC ARRAY['owner'::text]))));

ALTER TABLE public.waitlist_entries ENABLE ROW LEVEL SECURITY;
