-- Policies und Trigger an Storage und Anmeldedienst, Buckets

CREATE TRIGGER auth_users_no_password BEFORE INSERT OR UPDATE OF encrypted_password ON auth.users FOR EACH ROW EXECUTE FUNCTION app.reject_password_via_auth_service();
CREATE TRIGGER platform_mailbox_confirmation_follows_email AFTER UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION app.drop_mailbox_confirmation_on_email_change();
CREATE POLICY fleet_photos_objects_delete ON storage.objects FOR DELETE TO authenticated USING (((bucket_id = app.fleet_photo_bucket()) AND app.may_delete_storage_object(bucket_id, name)));
CREATE POLICY fleet_photos_objects_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket_id = app.fleet_photo_bucket()) AND app.may_upload_fleet_photo_object(name)));
CREATE POLICY fleet_photos_objects_select ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = app.fleet_photo_bucket()) AND app.may_read_fleet_photo_object(name)));
CREATE POLICY fleet_photos_objects_select_for_deletion ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = app.fleet_photo_bucket()) AND app.may_read_storage_object_for_deletion(bucket_id, name)));
