CREATE POLICY patient_files_objects_delete ON storage.objects FOR DELETE TO authenticated USING (((bucket_id = ANY (ARRAY[app.patient_file_bucket(), app.patient_photo_bucket()])) AND app.may_delete_storage_object(bucket_id, name)));
