CREATE POLICY patient_files_objects_select ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = ANY (ARRAY[app.patient_file_bucket(), app.patient_photo_bucket()])) AND app.may_read_patient_file_object(bucket_id, name)));
